--
-- Name: _announce_booking_change(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._announce_booking_change(p_org uuid, p_user uuid, p_kind text, p_title text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO notifications (org_id, user_id, kind, title, link)
  SELECT p_org, p_user, p_kind, p_title, '/app/calendar'
   WHERE p_org IS NOT NULL AND p_user IS NOT NULL
     AND nullif(btrim(coalesce(p_title, '')), '') IS NOT NULL;
$$;


--
-- Name: _booking_form_is_blank(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._booking_form_is_blank(p_answers jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT NOT EXISTS (
    SELECT 1
    FROM jsonb_each(CASE WHEN jsonb_typeof(p_answers) = 'object'
                         THEN p_answers ELSE '{}'::jsonb END) AS e(k, v)
    WHERE CASE jsonb_typeof(e.v)
            WHEN 'null'   THEN false
            WHEN 'string' THEN btrim(e.v #>> '{}') <> ''
            WHEN 'array'  THEN jsonb_array_length(e.v) > 0
            WHEN 'object' THEN e.v <> '{}'::jsonb
            ELSE true
          END
  )
$$;


--
-- Name: _condition_names_value(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._condition_names_value(p_cond jsonb, p_field_key text, p_code text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_sub jsonb;
BEGIN
  IF p_cond IS NULL OR p_code IS NULL THEN RETURN false; END IF;

  IF p_cond ? 'all' THEN
    FOR v_sub IN SELECT * FROM jsonb_array_elements(p_cond -> 'all') LOOP
      IF _condition_names_value(v_sub, p_field_key, p_code) THEN RETURN true; END IF;
    END LOOP;
  END IF;

  IF p_cond ? 'any' THEN
    FOR v_sub IN SELECT * FROM jsonb_array_elements(p_cond -> 'any') LOOP
      IF _condition_names_value(v_sub, p_field_key, p_code) THEN RETURN true; END IF;
    END LOOP;
  END IF;

  -- A leaf only counts when it is about THIS field.
  IF coalesce(p_cond ->> 'field_key', '') <> p_field_key THEN RETURN false; END IF;

  IF p_cond ? 'equals'   AND (p_cond -> 'equals')   ? p_code THEN RETURN true; END IF;
  IF p_cond ? 'contains' AND (p_cond -> 'contains') ? p_code THEN RETURN true; END IF;

  RETURN false;
END;
$$;


--
-- Name: _contact_sort_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._contact_sort_name(p_first text, p_last text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT lower(btrim(coalesce(p_first, '') || ' ' || coalesce(p_last, '')));
$$;


--
-- Name: _contract_document_frozen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._contract_document_frozen(p_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT d.workflow_state = 'executed' OR d.status = 'EXECUTED'
       FROM documents d WHERE d.id = p_document_id), true)
  OR EXISTS (SELECT 1 FROM signatures s
              WHERE s.document_id = p_document_id AND s.deleted_at IS NULL);
$$;


