--

CREATE TABLE public.bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_code text,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    purchase_id uuid,
    contract_id uuid,
    account_user_id uuid,
    account_contact_id uuid,
    offering_id uuid,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    location text,
    status text DEFAULT 'requested'::text NOT NULL,
    hold_expires_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    client_id uuid,
    instructor_user_id uuid,
    credit_id uuid,
    request_id uuid,
    kind text DEFAULT 'purchase'::text NOT NULL,
    horse_id uuid,
    activity_log jsonb,
    is_flexible boolean DEFAULT false NOT NULL,
    series_id uuid,
    travel_before_minutes integer DEFAULT 0 NOT NULL,
    travel_after_minutes integer DEFAULT 0 NOT NULL,
    address text,
    price_amount numeric(10,2),
    location_id uuid,
    created_by uuid,
    all_day boolean DEFAULT false NOT NULL,
    reminder_1h_sent_at timestamp with time zone,
    reminder_2h_sent_at timestamp with time zone,
    current_status text,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT bookings_kind_check CHECK ((kind = ANY (ARRAY['purchase'::text, 'lesson'::text, 'care'::text, 'block'::text]))),
    CONSTRAINT bookings_lesson_requires_client CHECK (((kind <> 'lesson'::text) OR is_flexible OR (status = ANY (ARRAY['draft'::text, 'available'::text, 'unavailable'::text])) OR (client_id IS NOT NULL))),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'available'::text, 'unavailable'::text, 'requested'::text, 'approved'::text, 'pending'::text, 'scheduled'::text, 'moved'::text, 'cancelled'::text, 'confirmed'::text, 'expired'::text, 'completed'::text, 'no_show'::text])))
);


