COMMENT ON CONSTRAINT bookings_lesson_requires_client ON public.bookings IS 'BOOKLINK B1: a committed (non-draft, non-open-slot) lesson must name its client. NOT VALID — 3 pre-existing rows (2 "Maddie", 1 "Audrey 2/4") are unresolved name matches pending an owner ruling; see docs/reports/TASK-BOOKLINK-REPORT.md.';


--
-- Name: _ensure_booking_form(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_booking_form(p_booking public.bookings) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_service text; v_key text;
BEGIN
  SELECT id INTO v_id FROM booking_forms WHERE booking_id = p_booking.id;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  v_service := booking_service_type(p_booking);
  v_key     := booking_form_key(v_service);

  INSERT INTO booking_forms (org_id, booking_id, form_key, form_definition_id, service_type, form_version)
  VALUES (p_booking.org_id, p_booking.id, v_key,
          (SELECT fd.id FROM form_definitions fd WHERE fd.form_key = v_key),
          v_service,
          (SELECT fd.version FROM form_definitions fd WHERE fd.form_key = v_key))
  ON CONFLICT (booking_id) DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: _ensure_client_account(uuid, text, text, text, text[], text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_client_account(p_org uuid, p_email text, p_first_name text, p_last_name text, p_categories text[], p_template_keys text[] DEFAULT NULL::text[], p_marker text DEFAULT 'CLIENT'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_client  uuid;
  v_email   text := lower(trim(p_email));
  v_fn      text := nullif(trim(coalesce(p_first_name, '')), '');
  v_ln      text := nullif(trim(coalesce(p_last_name,  '')), '');
  v_cats    text[];
  v_had_cats boolean;
  v_existing boolean := false;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'org is required'; END IF;
  IF v_email IS NULL OR v_email = '' THEN RAISE EXCEPTION 'email is required'; END IF;
  IF p_marker NOT IN ('CLIENT','CUSTOMER') THEN RAISE EXCEPTION 'marker must be CLIENT or CUSTOMER'; END IF;

  SELECT array_agg(DISTINCT upper(btrim(c))) INTO v_cats
    FROM unnest(coalesce(p_categories, '{}')) c WHERE btrim(c) <> '';
  -- remember whether the CALLER supplied categories, before any defaulting
  v_had_cats := (v_cats IS NOT NULL AND array_length(v_cats, 1) IS NOT NULL);
  IF NOT v_had_cats THEN
    v_cats := ARRAY['GUEST'];  -- GUEST = no service docs pre-assigned (D8)
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_cats) c WHERE c NOT IN ('GUEST','RIDER','HORSE_OWNER')) THEN
    RAISE EXCEPTION 'categories must be a subset of GUEST/RIDER/HORSE_OWNER';
  END IF;

  -- upsert contact by email (skip contacts owned by a DIFFERENT account's profile)
  SELECT c.id INTO v_contact FROM contacts c
    WHERE lower(c.email) = v_email AND c.deleted_at IS NULL
      AND NOT c.is_company  -- the company contact is matched by id only, never email (D7 rule)
      AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id AND lower(coalesce(p.email,'')) <> v_email)
    ORDER BY c.created_at LIMIT 1;
  IF v_contact IS NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, email)
      VALUES (p_org, v_fn, v_ln, v_email) RETURNING id INTO v_contact;
  ELSE
    v_existing := true;
    UPDATE contacts SET
        first_name = CASE WHEN v_fn IS NOT NULL AND (NULLIF(trim(coalesce(first_name,'')),'') IS NULL
                            OR lower(trim(first_name)) = lower(coalesce(email,''))) THEN v_fn ELSE first_name END,
        last_name  = CASE WHEN v_ln IS NOT NULL AND NULLIF(trim(coalesce(last_name,'')),'') IS NULL
                          THEN v_ln ELSE last_name END,
        -- ITEM 3: adopting an existing contact into an account converts a LEAD
        -- into a real CONTACT. Every other type is left exactly as it is.
        contact_type = CASE WHEN contact_type = 'LEAD' THEN 'CONTACT' ELSE contact_type END
      WHERE id = v_contact;
  END IF;

  -- the clients row carries the D8 markers
  SELECT cl.id INTO v_client FROM clients cl WHERE cl.contact_id = v_contact AND cl.deleted_at IS NULL;
  IF v_client IS NULL THEN
    INSERT INTO clients (org_id, contact_id, source, client_since, customer_since)
      VALUES (p_org, v_contact, 'provisioned invitation',
              CASE WHEN p_marker = 'CLIENT'   THEN now() END,
              CASE WHEN p_marker = 'CUSTOMER' THEN now() END)
      RETURNING id INTO v_client;
  ELSE
    UPDATE clients SET
        client_since   = coalesce(client_since,   CASE WHEN p_marker = 'CLIENT'   THEN now() END),
        customer_since = coalesce(customer_since, CASE WHEN p_marker = 'CUSTOMER' THEN now() END)
      WHERE id = v_client;
  END IF;

  -- groups are DERIVED — provisioning writes none; categories drive the
  -- onboarding document set only (GUEST pre-assigns nothing per D8).
  IF p_template_keys IS NOT NULL THEN
    INSERT INTO contact_required_documents (contact_id, template_key, org_id)
    SELECT v_contact, k, p_org FROM unnest(p_template_keys) k WHERE btrim(k) <> ''
    ON CONFLICT DO NOTHING;
  END IF;
  -- ⚠️ OFFERINGDOCS 2026-08-24 — A TAG NO LONGER ASSIGNS PAPERWORK.
  --
  -- A call to apply_category_documents(v_contact, v_cats) stood here, and it is
  -- what made a ticked checkbox a legal obligation: choosing "Rider" on the
  -- provisioning screen wrote Rider's four documents onto the person, whether or
  -- not they had bought, visited, or agreed to anything.
  --
  -- Owner: "the tagging is just for us to know what type of services or
  -- relationship they have with us and it helps inform the onboarding which is a
  -- mistake. the onboarding should be informed by the offerings not a tag."
  --
  -- Paperwork now comes from what they BOUGHT (apply_offering_documents), the
  -- door they CAME IN BY (apply_sign_path_documents), or an explicit list of
  -- TEMPLATES staff chose — p_template_keys above, which is unchanged and is
  -- still honoured exactly as it was. The categories are still recorded; they
  -- just describe.

  RETURN jsonb_build_object('contact_id', v_contact, 'client_id', v_client);
END;
$$;


--
-- Name: _ensure_plan_horizon(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_plan_horizon(p_purchase_item_id uuid, p_through date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pi      purchase_items%ROWTYPE;
  v_pu      purchases%ROWTYPE;
  v_through date := coalesce(p_through, plan_horizon_through());
  v_month   date := date_trunc('month', current_date)::date;
  v_this    date := date_trunc('month', current_date)::date;
  v_last    date;
  v_has_time boolean;
  v_gen     jsonb;
  v_before  uuid[];
  v_months  int := 0;
  v_created int := 0;
  v_pended  int := 0;
  v_minted  int := 0;
BEGIN
  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;

  -- A draft order has not been placed. D23 moved the moment of placing it to the
  -- buyer's own declaration, so this is no longer a staff gate — but a basket is
  -- still a basket.
  IF v_pu.status = 'draft' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'draft');
  END IF;

  v_has_time :=
       nullif(btrim(coalesce(v_pi.config->>'recurring_time', '')), '') IS NOT NULL
    OR (jsonb_typeof(v_pi.config->'recurring_times') = 'object'
        AND (SELECT count(*) FROM jsonb_object_keys(v_pi.config->'recurring_times')) > 0);
  IF NOT v_has_time THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'needs_time');
  END IF;

  v_last := date_trunc('month', v_through)::date;
  WHILE v_month <= v_last LOOP
    EXIT WHEN v_pi.plan_ends_on IS NOT NULL AND v_pi.plan_ends_on < v_month;
    v_minted := v_minted + coalesce(_mint_credits_for_purchase_item(p_purchase_item_id, NULL, v_month), 0);

    -- the fence between "what I am about to make" and "what was already there"
    SELECT coalesce(array_agg(b.id), '{}'::uuid[]) INTO v_before
      FROM bookings b
     WHERE b.purchase_id = v_pu.id
       AND b.starts_at >= v_month
       AND b.starts_at <  (v_month + interval '1 month');
    v_gen := _generate_plan_month(
               p_purchase_item_id,
               NULL,                                                  -- per-day times decide
               coalesce((v_pi.config->>'duration_minutes')::int, 60),
               nullif(btrim(coalesce(v_pi.config->>'horse_id', '')), '')::uuid,
               nullif(btrim(coalesce(v_pi.config->>'location_id', '')), '')::uuid,
               NULL,
               v_month);
    v_created := v_created + coalesce((v_gen->>'created')::int, 0);

    -- ⚠️ THE PENDING MONTH. `_generate_plan_month` inserts every row 'scheduled';
    -- a month beyond the current one is not paid for yet, so what it just made
    -- becomes 'pending' — VISIBLE, not withheld (Trap 6 / D23 / D24: a pending
    -- month never blocks anyone from booking). Scoped to rows this call created,
    -- so a month that already existed is untouched (Trap 8).
    IF v_month > v_this AND coalesce((v_gen->>'created')::int, 0) > 0 THEN
      UPDATE bookings
         SET status = 'pending', updated_at = now()
       WHERE purchase_id = v_pu.id
         AND starts_at >= v_month
         AND starts_at <  (v_month + interval '1 month')
         AND NOT (id = ANY (v_before))
         AND status = 'scheduled';
      GET DIAGNOSTICS v_pended = ROW_COUNT;
    END IF;

    v_months  := v_months + 1;
    v_month   := (v_month + interval '1 month')::date;
  END LOOP;

  -- How far this plan is materialised. `ensure_standing_slots` reads it to skip a
  -- plan that is already out to the horizon, so a calendar load costs one index
  -- lookup per plan rather than a generation pass.
  UPDATE purchase_items
     SET config = coalesce(config, '{}'::jsonb)
                  || jsonb_build_object('horizon_through', to_char(v_through, 'YYYY-MM-DD'))
   WHERE id = p_purchase_item_id;

  RETURN jsonb_build_object('ok', true, 'through', v_through, 'months', v_months,
                            'created', v_created, 'pending', v_pended, 'minted', v_minted);
END;
$$;


--
-- Name: _file_is_on_my_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._file_is_on_my_booking(p_file_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM file_links fl
      JOIN bookings b ON b.id = fl.subject_id
     WHERE fl.file_id = p_file_id
       AND fl.subject_type = 'booking'
       AND fl.deleted_at IS NULL
       AND b.client_id IS NOT NULL
       AND b.client_id = current_client_id())
$$;


--
-- Name: _form_edit_base(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._form_edit_base(p_form_key text, p_from_version integer) RETURNS TABLE(title text, audience text, purpose text, schema jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_from_version is null then
    return query
      select fd.title, fd.audience, fd.purpose, fd.schema
        from form_definitions fd where fd.form_key = p_form_key;
  else
    return query
      select v.title, v.audience, v.purpose, v.schema
        from form_definition_versions v
       where v.form_key = p_form_key and v.version = p_from_version;
  end if;
end;
$$;


--
-- Name: FUNCTION _form_edit_base(p_form_key text, p_from_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._form_edit_base(p_form_key text, p_from_version integer) IS 'TASK-VERSIONSPINE: the content a form edit starts from — the live form, or a named earlier version when the editor opened one.';


--
-- Name: _generate_plan_month(uuid, text, integer, uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._generate_plan_month(p_purchase_item_id uuid, p_start_time text, p_duration_minutes integer DEFAULT 60, p_horse_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_month date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pi      purchase_items%ROWTYPE;
  v_pu      purchases%ROWTYPE;
  v_off     offerings%ROWTYPE;
  v_cl      clients%ROWTYPE;
  v_org     uuid;
  v_days    text[];
  v_acct_c  uuid;
  v_acct_u  uuid;
  v_series  uuid := gen_random_uuid();
  v_month   date := date_trunc('month', coalesce(p_month, current_date))::date;
  v_from    date;
  v_month_end date;
  v_kind    text;
  v_credit  uuid;
  v_time    text;
  d         date;
  v_s       timestamptz;
  v_e       timestamptz;
  v_made    int := 0;
  v_skipped int := 0;
  v_no_ent  int := 0;
  v_no_time int := 0;
BEGIN
  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  SELECT * INTO v_off FROM offerings WHERE id = v_pi.offering_id;
  IF NOT FOUND OR v_off.config_kind <> 'recurring' THEN
    RAISE EXCEPTION 'purchase item % is not a monthly-plan (recurring) offering', p_purchase_item_id;
  END IF;

  -- The org comes from the ORDER, not from current_org(): a horizon roll may run
  -- from a session that is not the buyer's.
  v_org := v_pu.org_id;

  IF p_client_id IS NOT NULL THEN
    SELECT * INTO v_cl FROM clients WHERE id = p_client_id AND deleted_at IS NULL;
  ELSE
    SELECT * INTO v_cl FROM clients
     WHERE contact_id = v_pu.buyer_contact_id AND deleted_at IS NULL
     ORDER BY created_at LIMIT 1;
  END IF;
  IF v_cl.id IS NULL THEN RAISE EXCEPTION 'no client for purchase item %', p_purchase_item_id; END IF;

  -- CAREPLANS: the chosen days, plural. The singular `recurring_day` is kept as a
  -- READ FALLBACK so every plan set up before this task keeps generating exactly
  -- what it generated before.
  SELECT array_agg(x) INTO v_days
    FROM jsonb_array_elements_text(coalesce(v_pi.config->'recurring_days', '[]'::jsonb)) x;
  IF v_days IS NULL OR array_length(v_days, 1) IS NULL THEN
    IF v_pi.config->>'recurring_day' IS NULL THEN
      RAISE EXCEPTION 'choose the days of the week first (set_recurring_days)';
    END IF;
    v_days := ARRAY[v_pi.config->>'recurring_day'];
  END IF;

  v_kind := CASE WHEN v_off.segment = 'horse' THEN 'care' ELSE 'lesson' END;

  -- BUYANDBOOK §4.3 — the month is a PARAMETER now, so a rolling horizon can open
  -- months ahead without a scheduler. Nothing is ever written into the past: the
  -- window starts today even when the named month began earlier.
  v_from      := greatest(current_date, v_month);
  v_month_end := (v_month + interval '1 month - 1 day')::date;

  -- A plan stopped mid-month generates only up to its last day.
  IF v_pi.plan_ends_on IS NOT NULL AND v_pi.plan_ends_on < v_month_end THEN
    v_month_end := v_pi.plan_ends_on;
  END IF;

  v_acct_c := v_cl.contact_id;
  SELECT pr.user_id INTO v_acct_u FROM profiles pr WHERE pr.contact_id = v_acct_c;

  FOR d IN SELECT generate_series(v_from, v_month_end, interval '1 day')::date LOOP
    CONTINUE WHEN NOT (to_char(d, 'Dy') = ANY (v_days));

    -- BUYANDBOOK §4 — A TIME FOR EACH DAY. The owner: "they pick the day or days for
    -- their weekly booking along with the time(s) FOR EACH". `recurring_times` names
    -- a time per weekday; the incumbent scalar covers any day it does not name, so a
    -- plan written before this keeps its single time.
    v_time := coalesce(
      nullif(btrim(coalesce(v_pi.config->'recurring_times'->>to_char(d, 'Dy'), '')), ''),
      nullif(btrim(coalesce(p_start_time, '')), ''),
      nullif(btrim(coalesce(v_pi.config->>'recurring_time', '')), ''));
    IF v_time IS NULL THEN v_no_time := v_no_time + 1; CONTINUE; END IF;

    v_s := d + v_time::time;
    v_e := v_s + make_interval(mins => coalesce(p_duration_minutes,
                                                (v_pi.config->>'duration_minutes')::int, 60));

    -- no carryover, structurally: the generate_series bound is v_month_end —
    -- there is no path in this loop that can ever produce a date past it.

    -- ⚠️ ANY booking for this plan on this date means the date is SETTLED —
    -- cancelled and expired included. Generation used to ignore those, which was
    -- harmless while it ran only when staff pressed a button; now that the horizon
    -- rolls on read, ignoring them would quietly RESURRECT a session the client
    -- cancelled and spend the credit the cancellation gave back. Coming back to a
    -- cancelled slot is a rebooking (the client's act), not something generation
    -- gets to redo behind them.
    IF EXISTS (
      SELECT 1 FROM bookings b WHERE b.client_id = v_cl.id AND b.kind = v_kind
        AND b.purchase_id = v_pu.id AND b.starts_at::date = d
    ) THEN
      v_skipped := v_skipped + 1; CONTINUE;
    END IF;

    IF p_horse_id IS NOT NULL AND horse_time_conflict(v_org, p_horse_id, v_s, v_e, NULL, v_series) THEN
      RAISE EXCEPTION 'that horse is already booked in an overlapping time on %', d;
    END IF;

    -- ── THE ANSWER TO THE DOUBLE-SPEND QUESTION ──
    -- One session generated = one allotment credit spent, taken from THIS plan's
    -- own line so a client with two plans can never have one fund the other. When
    -- the month's allotment is gone, so is the generating: no session is written
    -- that the entitlement does not cover. This is also why the month ends up with
    -- ZERO spendable credits: the bookings ARE the entitlement.
    UPDATE lesson_credits SET credits_remaining = credits_remaining - 1
     WHERE id = (SELECT lc.id FROM lesson_credits lc
                  WHERE lc.client_id = v_cl.id
                    AND lc.purchase_item_id = v_pi.id
                    AND lc.deleted_at IS NULL
                    AND lc.credits_remaining > 0
                    AND (lc.expires_at IS NULL OR lc.expires_at > now())
                    -- the budget for THIS month, not some other month's leftovers
                    AND (lc.period_start IS NULL OR lc.period_start = v_month)
                  ORDER BY lc.expires_at ASC NULLS LAST, lc.period_start
                  LIMIT 1 FOR UPDATE)
     RETURNING id INTO v_credit;
    IF v_credit IS NULL THEN
      v_no_ent := v_no_ent + 1; CONTINUE;
    END IF;

    INSERT INTO bookings (
      org_id, kind, status, starts_at, ends_at, is_flexible,
      client_id, account_contact_id, account_user_id, instructor_user_id,
      horse_id, purchase_id, offering_id, location_id, price_amount,
      series_id, created_by, credit_id
    ) VALUES (
      v_org, v_kind, 'scheduled', v_s, v_e, false,
      v_cl.id, v_acct_c, v_acct_u, auth.uid(),
      coalesce(p_horse_id, nullif(btrim(coalesce(v_pi.config->>'horse_id','')),'')::uuid),
      v_pu.id, v_off.id,
      coalesce(p_location_id, nullif(btrim(coalesce(v_pi.config->>'location_id','')),'')::uuid),
      v_off.price_amount,
      v_series, auth.uid(), v_credit
    );
    v_made := v_made + 1;
    v_credit := NULL;
  END LOOP;

  -- Remember HOW this plan is delivered, so a later month opens the same way without
  -- anyone repeating themselves. Only written when the CALLER named a time — a
  -- horizon roll passes none, and writing NULL over the template would destroy the
  -- very thing the roll reads.
  IF v_made > 0 AND nullif(btrim(coalesce(p_start_time, '')), '') IS NOT NULL THEN
    UPDATE purchase_items
       SET config = coalesce(config, '{}'::jsonb) || jsonb_build_object(
             'recurring_time',   p_start_time,
             'duration_minutes', coalesce(p_duration_minutes, 60),
             'horse_id',         p_horse_id,
             'location_id',      p_location_id)
     WHERE id = p_purchase_item_id;
  END IF;

  RETURN jsonb_build_object('series_id', v_series, 'created', v_made,
    'month', v_month,
    'skipped_existing', v_skipped, 'skipped_no_entitlement', v_no_ent,
    'skipped_no_time', v_no_time,
    'recurring_day', v_days[1], 'recurring_days', to_jsonb(v_days), 'kind', v_kind);
END;
$$;


--
-- Name: _group_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._group_types() RETURNS text[]
    LANGUAGE sql IMMUTABLE
