--
-- Name: _lease_button_options(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lease_button_options(p_field_key text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_field_key
    WHEN 'TXN.PERMITTED_ACTIVITIES' THEN jsonb_build_array(
      jsonb_build_object('value','FLAT','label','Flat / dressage'),
      jsonb_build_object('value','JUMPING','label','Jumping'),
      jsonb_build_object('value','TRAIL','label','Trail riding'),
      jsonb_build_object('value','SHOWING','label','Showing / competition'),
      jsonb_build_object('value','LESSONS','label','Lessons'),
      jsonb_build_object('value','TURNOUT','label','Turnout'),
      jsonb_build_object('value','BREEDING','label','Breeding'))
    WHEN 'TXN.PROHIBITED_ACTIVITIES' THEN jsonb_build_array(
      jsonb_build_object('value','JUMPING','label','Jumping'),
      jsonb_build_object('value','SHOWING','label','Showing / competition'),
      jsonb_build_object('value','BREEDING','label','Breeding'),
      jsonb_build_object('value','TRAIL','label','Trail riding'),
      jsonb_build_object('value','LOANING','label','Loaning to third parties'),
      jsonb_build_object('value','CLINICS','label','Clinics / off-site events'))
    WHEN 'TXN.USE_RESTRICTIONS' THEN jsonb_build_array(
      jsonb_build_object('value','SUPERVISED','label','Supervised use only'),
      jsonb_build_object('value','NO_MINORS','label','No minors without guardian'),
      jsonb_build_object('value','ARENA_ONLY','label','Arena only'),
      jsonb_build_object('value','NO_OFFSITE','label','No off-site use'),
      jsonb_build_object('value','WEATHER','label','Weather restrictions apply'))
    WHEN 'TXN.AUTHORIZED_USERS' THEN jsonb_build_array(
      jsonb_build_object('value','LESSEE_ONLY','label','Lessee only'),
      jsonb_build_object('value','FAMILY','label','Lessee & immediate family'),
      jsonb_build_object('value','TRAINER','label','Lessee & their trainer'),
      jsonb_build_object('value','NAMED','label','Named riders only (list below)'))
    ELSE NULL
  END;
$$;


--
-- Name: _lease_select_options(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lease_select_options(p_field_key text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_field_key
    WHEN 'HORSE.SEX' THEN jsonb_build_array(
      jsonb_build_object('value','MARE','label','Mare'),
      jsonb_build_object('value','GELDING','label','Gelding'),
      jsonb_build_object('value','STALLION','label','Stallion'),
      jsonb_build_object('value','COLT','label','Colt'),
      jsonb_build_object('value','FILLY','label','Filly'))
    WHEN 'HORSE.COLOR' THEN jsonb_build_array(
      jsonb_build_object('value','BAY','label','Bay'),
      jsonb_build_object('value','CHESTNUT','label','Chestnut'),
      jsonb_build_object('value','GRAY','label','Gray'),
      jsonb_build_object('value','BLACK','label','Black'),
      jsonb_build_object('value','BROWN','label','Brown'),
      jsonb_build_object('value','ROAN','label','Roan'),
      jsonb_build_object('value','PALOMINO','label','Palomino'),
      jsonb_build_object('value','PINTO','label','Pinto / Paint'),
      jsonb_build_object('value','BUCKSKIN','label','Buckskin'),
      jsonb_build_object('value','DUN','label','Dun'),
      jsonb_build_object('value','WHITE','label','White / Cremello'))
    WHEN 'HORSE.BREED' THEN jsonb_build_array(
      jsonb_build_object('value','WARMBLOOD','label','Warmblood'),
      jsonb_build_object('value','THOROUGHBRED','label','Thoroughbred'),
      jsonb_build_object('value','QUARTER_HORSE','label','Quarter Horse'),
      jsonb_build_object('value','ARABIAN','label','Arabian'),
      jsonb_build_object('value','PONY','label','Pony'),
      jsonb_build_object('value','DRAFT','label','Draft'),
      jsonb_build_object('value','APPALOOSA','label','Appaloosa'),
      jsonb_build_object('value','MORGAN','label','Morgan'),
      jsonb_build_object('value','FRIESIAN','label','Friesian'),
      jsonb_build_object('value','ANDALUSIAN','label','Andalusian'),
      jsonb_build_object('value','MUSTANG','label','Mustang'),
      jsonb_build_object('value','CROSSBRED','label','Crossbred / Grade'))
    WHEN 'TXN.LEASE_TERM' THEN jsonb_build_array(
      jsonb_build_object('value','3_MONTHS','label','3 months'),
      jsonb_build_object('value','6_MONTHS','label','6 months'),
      jsonb_build_object('value','12_MONTHS','label','12 months'),
      jsonb_build_object('value','MONTH_TO_MONTH','label','Month-to-month'))
    WHEN 'TXN.PAYMENT_SCHEDULE' THEN jsonb_build_array(
      jsonb_build_object('value','MONTHLY','label','Monthly'),
      jsonb_build_object('value','QUARTERLY','label','Quarterly'),
      jsonb_build_object('value','SEMIANNUAL','label','Semi-annually'),
      jsonb_build_object('value','ANNUAL','label','Annually'),
      jsonb_build_object('value','ONE_TIME','label','One-time'))
    ELSE NULL
  END;
$$;


--
-- Name: _lesson_plan_for_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lesson_plan_for_booking(p_booking_id uuid) RETURNS public.lesson_plans
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b    bookings%ROWTYPE;
  v_pin  uuid;
  v_plan lesson_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND OR v_b.client_id IS NULL THEN RETURN NULL; END IF;

  SELECT bf.plan_id INTO v_pin FROM booking_forms bf WHERE bf.booking_id = p_booking_id;

  IF v_pin IS NOT NULL THEN
    SELECT * INTO v_plan FROM lesson_plans WHERE id = v_pin;
    IF FOUND THEN RETURN v_plan; END IF;
  END IF;

  RETURN _current_lesson_plan(v_b.client_id);
END;
$$;


--
-- Name: _lesson_plan_json(public.lesson_plans, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lesson_plan_json(p_plan public.lesson_plans, p_include_private boolean) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_plan.id IS NULL THEN NULL ELSE
    jsonb_build_object(
      'id',           p_plan.id,
      'client_id',    p_plan.client_id,
      'version',      p_plan.version,
      'status',       p_plan.status,
      'focus',        p_plan.focus,
      'objectives',   p_plan.objectives,
      'created_at',   p_plan.created_at,
      'advanced_from_booking_id', p_plan.advanced_from_booking_id,
      -- the private lane, present ONLY when the caller asked for it
      'coach_notes',  CASE WHEN p_include_private THEN to_jsonb(p_plan.coach_notes) ELSE NULL END
    )
  END
$$;


--
-- Name: _lesson_plan_objectives(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lesson_plan_objectives(p_objectives jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_in  jsonb := coalesce(p_objectives, '[]'::jsonb);
  v_out jsonb := '[]'::jsonb;
  v_e   jsonb;
  v_lbl text;
  v_st  text;
BEGIN
  IF jsonb_typeof(v_in) <> 'array' THEN
    RAISE EXCEPTION 'objectives must be an array';
  END IF;

  FOR v_e IN SELECT jsonb_array_elements(v_in) LOOP
    IF jsonb_typeof(v_e) <> 'object' THEN
      RAISE EXCEPTION 'each objective must be an object';
    END IF;
    v_lbl := btrim(coalesce(v_e ->> 'label', ''));
    CONTINUE WHEN v_lbl = '';          -- a blank line Claire left behind is not an objective
    v_st := lower(btrim(coalesce(v_e ->> 'state', 'planned')));
    IF v_st NOT IN ('planned', 'working', 'achieved') THEN
      RAISE EXCEPTION 'unknown objective state: %', v_st;
    END IF;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'id',    coalesce(nullif(btrim(coalesce(v_e ->> 'id', '')), ''), gen_random_uuid()::text),
      'label', v_lbl,
      'state', v_st,
      'note',  nullif(btrim(coalesce(v_e ->> 'note', '')), '')
    ));
  END LOOP;

  RETURN v_out;
END;
$$;


--
-- Name: _lesson_plan_same(text, jsonb, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lesson_plan_same(p_a_focus text, p_a_objectives jsonb, p_a_notes text, p_b_focus text, p_b_objectives jsonb, p_b_notes text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(btrim(coalesce(p_a_focus, '')) = btrim(coalesce(p_b_focus, '')), false)
     AND coalesce(p_a_objectives, '[]'::jsonb) = coalesce(p_b_objectives, '[]'::jsonb)
     AND coalesce(btrim(coalesce(p_a_notes, '')) = btrim(coalesce(p_b_notes, '')), false)
$$;


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    body text,
    link text NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    emailed_at timestamp with time zone,
    category text,
    author_user_id uuid,
    reason text,
    seen_at timestamp with time zone,
    dismissed_at timestamp with time zone
);


--
-- Name: COLUMN notifications.emailed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.emailed_at IS 'When the email nudge digested this notification (api/notifications-nudge). NULL = not yet emailed; stamped only after a successful send.';


--
-- Name: _log_notification_resolution(public.notifications, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._log_notification_resolution(p_n public.notifications, p_outcome text, p_actor uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO notification_log (
    org_id, notification_id, kind, category, title, body, link,
    author_user_id, reason, recipient_user_id, recipient_email,
    raised_at, emailed_at, read_at, locations, outcome, outcome_at, outcome_by)
  VALUES (
    p_n.org_id, p_n.id, p_n.kind,
    coalesce(p_n.category, notification_category(p_n.kind)),
    p_n.title, p_n.body, p_n.link,
    p_n.author_user_id, p_n.reason, p_n.user_id,
    (SELECT pr.email FROM profiles pr WHERE pr.user_id = p_n.user_id),
    p_n.created_at, p_n.emailed_at, p_n.read_at,
    CASE WHEN p_n.emailed_at IS NOT NULL
         THEN ARRAY['in_app','email'] ELSE ARRAY['in_app'] END,
    p_outcome, now(), p_actor)
$$;


--
-- Name: _mint_credits_for_purchase_item(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mint_credits_for_purchase_item(p_item_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_period_start date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_it     purchase_items%ROWTYPE;
  v_pu     purchases%ROWTYPE;
  v_off    offerings%ROWTYPE;
  v_client uuid := p_client_id;
  v_units  integer := 0;
  v_period date;
  v_from   date;
  v_to     date;
  v_made   integer := 0;
  v_days   text[];
BEGIN
  SELECT * INTO v_it FROM purchase_items WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  SELECT * INTO v_pu FROM purchases WHERE id = v_it.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- A DRAFT ORDER IS NOT A PURCHASE. Nothing has been committed to, so nothing is
  -- entitled. BUYANDBOOK §2/§3: the buyer's own payment DECLARATION is now what ends
  -- the draft (`report_my_payment` → `finalize_purchase_payment`), so this gate no
  -- longer waits on staff — it only waits on the order actually being placed.
  IF v_pu.status = 'draft' THEN RETURN 0; END IF;

  SELECT * INTO v_off FROM offerings WHERE id = v_it.offering_id;
  IF NOT FOUND OR v_off.config_kind IS NULL THEN RETURN 0; END IF;

  -- Whose entitlement. The caller may name the client (the provisioning spine knows
  -- it); otherwise resolve it from the buyer, contact first then login.
  IF v_client IS NULL THEN
    SELECT cl.id INTO v_client
      FROM clients cl
     WHERE cl.deleted_at IS NULL
       AND (cl.contact_id = v_pu.buyer_contact_id
            OR cl.contact_id = (SELECT pr.contact_id FROM profiles pr WHERE pr.user_id = v_pu.buyer_user_id))
     ORDER BY (cl.contact_id = v_pu.buyer_contact_id) DESC
     LIMIT 1;
  END IF;
  IF v_client IS NULL THEN RETURN 0; END IF;

  IF v_off.config_kind = 'scheduled' THEN
    -- A session pack mints unit_count × quantity. No period, no expiry. Owner
    -- ruling 2026-08-16 (20260816T2900): single-quantity HORSE services mint one
    -- credit each, TAGGED to the offering — a Full Body Clip credit is a
    -- Full-Body-Clip credit, kept apart from lessons by offering_id, not by a
    -- segment gate. Only unit_count <= 0 (inquire / quote-priced rows) mints nothing.
    IF coalesce(v_off.unit_count, 0) <= 0 THEN RETURN 0; END IF;
    v_units := v_off.unit_count * greatest(coalesce(v_it.quantity, 1), 1);

    INSERT INTO lesson_credits (org_id, client_id, offering_id, purchase_id, purchase_item_id,
                                package_key, credits_total, credits_remaining)
    VALUES (v_pu.org_id, v_client, v_off.id, v_pu.id, v_it.id,
            coalesce(v_it.label, v_off.name), v_units, v_units)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_made = ROW_COUNT;
    RETURN CASE WHEN v_made > 0 THEN v_units ELSE 0 END;

  ELSIF v_off.config_kind = 'recurring' THEN
    -- BOTH SEGMENTS. The owner named lessons and horse care, and all six horse-care
    -- recurring SKUs were equally broken. book_open_slot is already segment-aware, so
    -- a horse-care allotment is consumed by the same path a lesson allotment is.
    v_period := coalesce(p_period_start, date_trunc('month', v_pu.created_at)::date);

    -- ⚠️ BUYANDBOOK §4.1/§4.2 — THE DAYS ARE THE ENTITLEMENT, AND ONLY THE DAYS.
    -- There is no `weekly_frequency` fallback any more. A recurring line whose days
    -- have not been chosen has no standing slot, and a standing slot is the entire
    -- product: minting a count for it would be the "monthly riding punch card" D23
    -- rejects. Nothing is minted until the client (or staff) picks the days.
    SELECT array_agg(x) INTO v_days
      FROM jsonb_array_elements_text(coalesce(v_it.config->'recurring_days', '[]'::jsonb)) x;
    IF v_days IS NULL OR array_length(v_days, 1) IS NULL THEN
      -- the singular stays readable for every plan written before CAREPLANS
      IF nullif(btrim(coalesce(v_it.config->>'recurring_day', '')), '') IS NOT NULL THEN
        v_days := ARRAY[v_it.config->>'recurring_day'];
      ELSE
        RETURN 0;
      END IF;
    END IF;

    -- ⚠️ NEVER RETROACTIVE. `_generate_plan_month` writes from TODAY forward, so a
    -- budget that counted days already past left the difference behind as SPENDABLE
    -- credits — a slot product quietly paying out as a punch card. The two windows
    -- are now the same window.
    v_from   := greatest(v_pu.created_at::date, v_period, current_date);
    v_to     := (v_period + interval '1 month - 1 day')::date;

    -- A plan that has been stopped is not entitled for a month that starts after it ended.
    IF v_it.plan_ends_on IS NOT NULL AND v_it.plan_ends_on < v_from THEN RETURN 0; END IF;
    IF v_it.plan_ends_on IS NOT NULL AND v_it.plan_ends_on < v_to THEN v_to := v_it.plan_ends_on; END IF;

    -- CAREPLANS: the days staff chose ARE the frequency. Their occurrences in this
    -- window, summed, are the month's budget — and `quantity` is deliberately NOT
    -- applied, because set_recurring_days already reconciled the line's quantity
    -- against the SKU's own weekly frequency.
    v_units := _recurring_allotment_days(v_days, v_from, v_to);
    IF v_units <= 0 THEN RETURN 0; END IF;

    INSERT INTO lesson_credits (org_id, client_id, offering_id, purchase_id, purchase_item_id,
                                package_key, credits_total, credits_remaining,
                                period_start, expires_at)
    VALUES (v_pu.org_id, v_client, v_off.id, v_pu.id, v_it.id,
            coalesce(v_it.label, v_off.name), v_units, v_units,
            v_period, (v_period + interval '1 month')::timestamptz)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_made = ROW_COUNT;
    RETURN CASE WHEN v_made > 0 THEN v_units ELSE 0 END;
  END IF;

  -- intake_*, document_transaction and inquire produce fulfillment units, not credits.
  RETURN 0;
END;
$$;


--
-- Name: FUNCTION _mint_credits_for_purchase_item(p_item_id uuid, p_client_id uuid, p_period_start date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._mint_credits_for_purchase_item(p_item_id uuid, p_client_id uuid, p_period_start date) IS 'CREDITALIGN: THE ONE MINT. Every origin — shop checkout, staff provisioning, gift redemption, a booking that creates its own order, the monthly roll — reaches entitlement through this and nothing else. Idempotent via lesson_credits_one_per_item_period. Reads config_kind/segment/unit_count/weekly_frequency/quantity/recurring_day; reads NO display name.';


--
-- Name: _monthly_plan_for_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._monthly_plan_for_client(p_client_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'credit_id',            lc.id,
      'purchase_id',          lc.purchase_id,
      'purchase_item_id',     lc.purchase_item_id,
      'offering_id',          o.id,
      'offering_name',        o.name,
      'segment',              o.segment,
      'weekly_frequency',     o.weekly_frequency,
      'recurring_day',        pi.config->>'recurring_day',
      'recurring_days',       coalesce(pi.config->'recurring_days', '[]'::jsonb),
      'plan_weeks',           (pi.config->>'plan_weeks')::int,
      'indefinite',           pi.plan_ends_on IS NULL,
      'period_start',         lc.period_start,
      'expires_at',           lc.expires_at,
      'plan_ends_on',         pi.plan_ends_on,
      'month_label',          to_char(lc.period_start, 'FMMonth YYYY'),
      'entitled_this_month',  lc.credits_total,
      'used_this_month',      lc.credits_total - lc.credits_remaining,
      'remaining_this_month', lc.credits_remaining)
    ORDER BY o.segment, o.name), '[]'::jsonb)
  FROM lesson_credits lc
  JOIN purchase_items pi ON pi.id = lc.purchase_item_id
  JOIN offerings o       ON o.id = pi.offering_id AND o.config_kind = 'recurring'
  WHERE lc.client_id = p_client_id
    AND lc.deleted_at IS NULL
    AND lc.period_start = date_trunc('month', current_date)::date;
$$;


--
-- Name: FUNCTION _monthly_plan_for_client(p_client_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._monthly_plan_for_client(p_client_id uuid) IS 'CREDITALIGN: a jsonb ARRAY of the client''s current-month recurring allotments, both segments, read straight off lesson_credits. entitled/used/remaining are credits_total, credits_total - credits_remaining and credits_remaining — not a second computation that can disagree with what gets spent.';


--
-- Name: _normalize_recurring_days(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._normalize_recurring_days(p_days text[]) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_in  text;
  v_day text;
  v_out text[] := '{}';
BEGIN
  IF p_days IS NULL OR array_length(p_days, 1) IS NULL THEN
    RAISE EXCEPTION 'choose at least one day of the week';
  END IF;
  FOREACH v_in IN ARRAY p_days LOOP
    v_day := initcap(btrim(coalesce(v_in, '')));
    IF v_day NOT IN ('Mon','Tue','Wed','Thu','Fri','Sat','Sun') THEN
      RAISE EXCEPTION 'day must be one of Mon/Tue/Wed/Thu/Fri/Sat/Sun, got %', v_in;
    END IF;
    IF NOT (v_day = ANY (v_out)) THEN v_out := v_out || v_day; END IF;
  END LOOP;
  IF array_length(v_out, 1) IS NULL THEN
    RAISE EXCEPTION 'choose at least one day of the week';
  END IF;
  -- week order, so a stored set reads Mon..Sun however staff clicked it.
  SELECT array_agg(d ORDER BY array_position(ARRAY['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], d))
    INTO v_out FROM unnest(v_out) d;
  RETURN v_out;
END;
$$;


--
-- Name: _notify_purchase_paid(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_purchase_paid(p_purchase_id uuid, p_announce boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur   purchases%ROWTYPE;
  v_user  uuid;
  v_label text;
  v_paid  text;
BEGIN
  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT string_agg(pi.label, ', ' ORDER BY pi.created_at) INTO v_label
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id;
  v_label := coalesce(nullif(btrim(v_label), ''), 'Your order');
  v_paid  := fmt_money(coalesce(v_pur.amount, 0));

  -- resolve any standing "payment due" / "you said you paid" notices.
  -- ⚠️ THIS RUNS FOR A BACKDATED SETTLEMENT TOO. Suppressing it would leave a
  -- backfilled order flagged as owing money in-app for ever.
  PERFORM resolve_notifications_for_link('/order/' || p_purchase_id::text, NULL, 'purchase_unpaid');
  PERFORM resolve_notifications_for_link('/app/orders', NULL, 'purchase_unpaid');
  PERFORM resolve_notifications_for_link('/app/ops/payments/review', NULL, 'purchase_unpaid');
  PERFORM resolve_notifications_for_link('/app/ops/payments/review', NULL, 'payment_reported');

  -- TASK-BACKDATE: the ANNOUNCEMENT half. A year of backfilled payments must not
  -- ring a client's bell once per historical month.
  IF NOT coalesce(p_announce, true) THEN RETURN; END IF;

  SELECT pr.user_id INTO v_user
    FROM profiles pr WHERE pr.contact_id = v_pur.buyer_contact_id LIMIT 1;
  IF v_user IS NOT NULL THEN
    PERFORM notify_user(v_user, 'payment_received',
      'Payment received — ' || v_label,
      'We received your payment of ' || v_paid || '. Thank you.',
      '/app/orders');
  END IF;

  PERFORM notify_staff(v_pur.org_id, 'payment_received',
    'Payment received — ' || v_label || ' (' || v_paid || ')',
    '/app/ops/payments/review');
END;
$$;


--
-- Name: _options_patch(jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._options_patch(p_options jsonb, p_code text, p_patch jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(
           CASE WHEN o ->> 'value' = p_code THEN o || p_patch ELSE o END
           ORDER BY ord), p_options)
    FROM jsonb_array_elements(coalesce(p_options, '[]'::jsonb)) WITH ORDINALITY t(o, ord);
$$;


--
-- Name: _payment_open(uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._payment_open(p_purchase_id uuid, p_method text, p_reference text, p_actor uuid, p_staff boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur purchases%ROWTYPE;
  v_id  uuid;
  v_old text;
  v_method text := lower(btrim(coalesce(p_method, '')));
BEGIN
  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_method NOT IN ('zelle','cash') THEN RETURN NULL; END IF;

  -- ONE open entry per order at a time. Changing the method amends THIS entry and
  -- is logged as a change — owner, 2026-08-25: "all the changes made if any exist".
  -- A NEW number is minted per INPUT, so a fresh declaration after a decline is a
  -- new record; an edit of an unsettled declaration is the same record changed.
  SELECT id, method INTO v_id, v_old
    FROM payments
   WHERE purchase_id = p_purchase_id AND status = 'pending' AND deleted_at IS NULL
   ORDER BY declared_at DESC LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO payments (org_id, purchase_id, payer_contact_id, method, amount,
                          reference, status, declared_by)
    VALUES (v_pur.org_id, p_purchase_id, v_pur.buyer_contact_id, v_method,
            -- what is still outstanding, not the order total: a second entry
            -- against a part-paid order is for the remainder. This is what makes
            -- a split between cash and Zelle expressible.
            greatest(coalesce(v_pur.amount, 0) - coalesce((
              SELECT sum(amount) FROM payments
               WHERE purchase_id = p_purchase_id AND status = 'paid' AND deleted_at IS NULL), 0), 0.01),
            nullif(btrim(coalesce(p_reference,'')), ''), 'pending', p_actor)
    RETURNING id INTO v_id;

    PERFORM log_status_event('payment', v_id,
      CASE WHEN p_staff THEN 'staff_recorded' ELSE 'declared' END,
      CASE WHEN p_staff THEN 'Recorded by staff as ' ELSE 'Client declared ' END || v_method
        || coalesce(' — ref ' || nullif(btrim(coalesce(p_reference,'')), ''), ''),
      v_pur.org_id);
  ELSE
    UPDATE payments
       SET method    = v_method,
           reference = coalesce(nullif(btrim(coalesce(p_reference,'')), ''), reference)
     WHERE id = v_id;

    IF v_old IS DISTINCT FROM v_method THEN
      PERFORM log_status_event('payment', v_id, 'method_changed',
        'Changed from ' || v_old || ' to ' || v_method, v_pur.org_id);
    END IF;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: _payment_settle(uuid, text, text, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._payment_settle(p_purchase_id uuid, p_method text, p_reference text, p_amount numeric, p_confirmed_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM purchases WHERE id = p_purchase_id;
  -- settle the open entry if there is one; otherwise the money arrived without a
  -- declaration (staff took cash at the barn) and the entry is created settled.
  v_id := _payment_open(p_purchase_id, p_method, p_reference, auth.uid(), true);
  IF v_id IS NULL THEN RETURN NULL; END IF;

  UPDATE payments
     SET status       = 'paid',
         amount       = coalesce(p_amount, amount),
         -- TASK-ORIGIN §4.3: a backfilled historic payment is confirmed AS OF
         -- the date it actually happened, not the day someone typed it in.
         confirmed_at = coalesce(p_confirmed_at, now()),
         confirmed_by = auth.uid()
   WHERE id = v_id;

  PERFORM log_status_event('payment', v_id, 'confirmed',
    'Confirmed received — ' || lower(btrim(coalesce(p_method,'')))
      || coalesce(' — ref ' || nullif(btrim(coalesce(p_reference,'')), ''), ''), v_org);
  RETURN v_id;
END;
$$;


--
-- Name: _provision_purchase_for_offerings(uuid, uuid, uuid, uuid[], boolean, text, text, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._provision_purchase_for_offerings(p_org_id uuid, p_contact_id uuid, p_client_id uuid, p_offering_ids uuid[], p_mark_paid boolean DEFAULT false, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_partial_amount numeric DEFAULT 0, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_purchase uuid;
  v_total    numeric;
  v_paid     numeric;
  v_when     timestamptz;
  v_backdated boolean;
BEGIN
  IF array_length(p_offering_ids, 1) IS NULL THEN
    RETURN NULL;  -- nothing to purchase
  END IF;

  -- TASK-BACKDATE: omitted is now(), which is every existing caller's behaviour.
  v_when := coalesce(p_occurred_at, now());
  v_backdated := (v_when AT TIME ZONE 'America/Los_Angeles')::date
               < (now()  AT TIME ZONE 'America/Los_Angeles')::date;

  SELECT coalesce(sum(o.price_amount), 0) INTO v_total
    FROM offerings o WHERE o.id = ANY(p_offering_ids);

  -- amount_paid: full total when marked paid; else the (clamped) partial amount.
  v_paid := CASE
    WHEN p_mark_paid THEN v_total
    ELSE least(greatest(coalesce(p_partial_amount, 0), 0), v_total)
  END;

  -- payment_status CHECK allows unpaid|pending|paid. A partial payment is
  -- 'pending' (some paid, balance owed) with the exact paid figure in amount_paid.
  INSERT INTO purchases (org_id, buyer_contact_id, status, amount, amount_paid,
                         payment_method, payment_status, payment_reference, paid_at,
                         notes, created_at)
    VALUES (p_org_id, p_contact_id,
            CASE WHEN p_mark_paid THEN 'paid' ELSE 'awaiting_payment' END,
            v_total, v_paid, p_payment_method,
            CASE WHEN p_mark_paid THEN 'paid'
                 WHEN v_paid > 0  THEN 'pending'
                 ELSE 'unpaid' END,
            CASE WHEN p_mark_paid THEN 'Provisioned — paid in full via ' || coalesce(p_payment_method, 'offline payment')
                 WHEN v_paid > 0  THEN 'Provisioned — partial ' || v_paid::text || ' via ' || coalesce(p_payment_method, 'offline payment') END,
            -- TASK-BACKDATE: `revenue_summary` recognises at paid_at, so THIS is
            -- the field that decides which month a backfilled sale lands in.
            CASE WHEN p_mark_paid THEN v_when END,
            coalesce(p_notes, 'Provisioned invitation'),
            v_when)
    RETURNING id INTO v_purchase;

  INSERT INTO purchase_items (org_id, purchase_id, offering_id, label, price_amount, price_unit, quantity, created_at)
  SELECT p_org_id, v_purchase, o.id, o.name, coalesce(o.price_amount, 0), o.price_unit, 1, v_when
    FROM offerings o WHERE o.id = ANY(p_offering_ids);

  -- CREDITALIGN: minting is no longer this function's business. One seam,
  -- `_mint_credits_for_purchase_item`, fired by the purchase_items trigger; this
  -- call only re-runs it with the client this caller already knows.
  PERFORM _mint_credits_for_purchase_item(pi.id, p_client_id)
     FROM purchase_items pi WHERE pi.purchase_id = v_purchase;

  IF p_mark_paid THEN
    -- ZELLECLOSE: same "payment received" trail mark_purchase_paid gives every
    -- other paid purchase — this one was just paid at creation, not by an UPDATE.
    -- TASK-BACKDATE: a historical sale resolves notices but announces nothing.
    PERFORM _notify_purchase_paid(v_purchase, NOT v_backdated);
  ELSE
    -- U3(a): a purchase that owes money raises the standing "payment due" pair
    -- (buyer + staff). No-op when paid (handled above instead). ⚠️ NOT suppressed
    -- when backdated: a backfilled order that was never paid still owes money.
    PERFORM notify_purchase_unpaid(v_purchase);
  END IF;

  RETURN v_purchase;
END;
$$;


--
-- Name: _publish_open_slots_for_org(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._publish_open_slots_for_org(p_org uuid, p_weeks integer, p_slot_minutes integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_day date; v_bh record; v_t timestamptz; v_end timestamptz; v_n integer := 0;
BEGIN
  IF p_slot_minutes NOT BETWEEN 15 AND 240 THEN RAISE EXCEPTION 'slot length out of range'; END IF;
  FOR v_day IN SELECT d::date FROM generate_series(current_date, current_date + (p_weeks * 7 - 1), interval '1 day') d LOOP
    SELECT * INTO v_bh FROM business_hours
     WHERE org_id = p_org AND weekday = extract(dow FROM v_day)::int AND NOT closed;
    CONTINUE WHEN NOT FOUND;
    v_t   := (v_day::text || ' ' || v_bh.open_time::text)::timestamp AT TIME ZONE 'America/Los_Angeles';
    v_end := (v_day::text || ' ' || v_bh.close_time::text)::timestamp AT TIME ZONE 'America/Los_Angeles';
    WHILE v_t + make_interval(mins => p_slot_minutes) <= v_end LOOP
      IF v_t > now() AND NOT EXISTS (
           SELECT 1 FROM bookings b
            WHERE b.org_id = p_org
              AND coalesce(b.status,'') NOT IN ('cancelled','expired')
              AND b.starts_at < v_t + make_interval(mins => p_slot_minutes)
              AND b.ends_at   > v_t)
      THEN
        INSERT INTO bookings (org_id, kind, status, is_flexible, starts_at, ends_at)
        VALUES (p_org, 'lesson', 'available', true, v_t, v_t + make_interval(mins => p_slot_minutes));
        v_n := v_n + 1;
      END IF;
      v_t := v_t + make_interval(mins => p_slot_minutes);
    END LOOP;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: _recompute_purchase_total(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recompute_purchase_total(p_purchase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric;
  v_live  integer;
  v_status text;
BEGIN
  SELECT coalesce(sum(pi.price_amount * pi.quantity), 0), count(*)
    INTO v_total, v_live
    FROM purchase_items pi
   WHERE pi.purchase_id = p_purchase_id AND pi.voided_at IS NULL;

  SELECT status INTO v_status FROM purchases WHERE id = p_purchase_id;

  UPDATE purchases SET amount = v_total, updated_at = now() WHERE id = p_purchase_id;

  IF v_live = 0 AND coalesce(v_status, '') NOT IN ('paid', 'void') THEN
    UPDATE purchases SET status = 'void' WHERE id = p_purchase_id;
    PERFORM log_status_event('order', p_purchase_id, 'void',
      'Every line item was voided', NULL);
  END IF;
END;
$$;


--
-- Name: _recurring_allotment(integer, text, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recurring_allotment(p_weekly_frequency integer, p_anchor_day text, p_from date, p_to date, p_quantity integer DEFAULT 1) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_from > p_to THEN 0 ELSE
    greatest(coalesce(p_weekly_frequency, 1), 1)
    * greatest(coalesce(p_quantity, 1), 1)
    * (SELECT count(*)::int
         FROM generate_series(p_from, p_to, interval '1 day') d
        WHERE to_char(d, 'Dy') = coalesce(nullif(btrim(coalesce(p_anchor_day, '')), ''),
                                          to_char(p_from, 'Dy')))
  END;
$$;


--
-- Name: FUNCTION _recurring_allotment(p_weekly_frequency integer, p_anchor_day text, p_from date, p_to date, p_quantity integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._recurring_allotment(p_weekly_frequency integer, p_anchor_day text, p_from date, p_to date, p_quantity integer) IS 'CREDITALIGN: weekly_frequency × weekday-occurrences-in-window × quantity. The window IS the proration — a mid-month purchase is minted over [purchase date .. month end]. Anchor weekday = the plan''s recurring_day, else the weekday the window opens on.';


--
-- Name: _recurring_allotment_days(text[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recurring_allotment_days(p_days text[], p_from date, p_to date) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_days IS NULL OR array_length(p_days, 1) IS NULL OR p_from > p_to THEN 0
    ELSE (SELECT count(*)::int
            FROM generate_series(p_from, p_to, interval '1 day') d
           WHERE to_char(d, 'Dy') = ANY (p_days))
  END;
$$;


--
-- Name: FUNCTION _recurring_allotment_days(p_days text[], p_from date, p_to date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._recurring_allotment_days(p_days text[], p_from date, p_to date) IS 'CAREPLANS: the month''s entitlement for a plan whose days staff chose. Counts the occurrences of EVERY chosen weekday in the window and adds them up — Sat+Sun in a month with 5 Sundays and 4 Saturdays is 9, not 8. Quantity is NOT a multiplier here: under this model the chosen day count IS the quantity (set_recurring_days writes it onto the line), so multiplying again would double the entitlement.';


--
-- Name: _refund_booking_credit(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._refund_booking_credit(p_booking public.bookings) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src lesson_credits%ROWTYPE;
BEGIN
  IF p_booking.credit_id IS NULL OR p_booking.client_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO v_src FROM lesson_credits WHERE id = p_booking.credit_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_src.deleted_at IS NULL THEN
    -- (a) still live. Only give back what was actually taken.
    IF v_src.credits_remaining < v_src.credits_total THEN
      UPDATE lesson_credits
         SET credits_remaining = credits_remaining + 1
       WHERE id = v_src.id;
      RETURN true;
    END IF;
    -- already whole — nothing was outstanding against it.
    RETURN false;
  END IF;

  -- (b) the source is gone. Compensate, carrying its meaning forward: the same
  -- service, the same order, the same month, the same expiry. purchase_item_id is
  -- deliberately left NULL so this row can never collide with, or masquerade as, the
  -- allotment for that line and period.
  INSERT INTO lesson_credits (org_id, client_id, package_key, credits_total, credits_remaining,
      purchased_at, offering_id, purchase_id, period_start, expires_at)
    VALUES (p_booking.org_id, p_booking.client_id, 'change_credit', 1, 1, now(),
            v_src.offering_id, v_src.purchase_id, v_src.period_start, v_src.expires_at);
  RETURN true;
END;
$$;


--
-- Name: FUNCTION _refund_booking_credit(p_booking public.bookings); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._refund_booking_credit(p_booking public.bookings) IS 'CREDITALIGN: THE one refund seam. Restores the source credit in place when it is still live (capped at its own credits_total, so a double refund cannot mint), else compensates with a row inheriting offering/purchase/period/expiry. A monthly allotment refunded in September stays a September credit.';


--
-- Name: _restore_contract_template_composition(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._restore_contract_template_composition(p_template_key text, p_composition jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_unknown text;
  v_diff    text;
begin
  if p_composition is null then return; end if;

  -- Loud, not silent: if the capture ever grows a column this restore does not
  -- write, say so instead of quietly leaving it behind.
  select string_agg(distinct k, ', ') into v_unknown from (
    select k from (
      select jsonb_object_keys(c) k from jsonb_array_elements(p_composition->'clauses') c
    ) ck where k not in ('template_key','section_key','clause_key','heading','body','clause_type',
                         'sort_order','is_optional','cut_name','conditional_on','guidance',
                         'render_as_subitem','draft_body')
    union all
    select k from (
      select jsonb_object_keys(s) k from jsonb_array_elements(p_composition->'sections') s
    ) sk where k not in ('template_key','section_key','heading','sort_order','is_optional',
                         'cut_name','guidance')
    union all
    select k from (
      select jsonb_object_keys(f) k from jsonb_array_elements(p_composition->'fields') f
    ) fk where k not in ('template_key','field_key','parent_field_key','label','section','owner_role',
                         'input_kind','value_type','options','conditional_on','guidance','required',
                         'is_optional','responsibility','sort_order','format_type','clause_key',
                         'responsibility_kind','closed','default_value')
  ) x;
  if v_unknown is not null then
    raise exception 'this retained version carries composition columns this restore does not write (%). Widen _restore_contract_template_composition before restoring.', v_unknown;
  end if;

  -- Structure must match exactly, in both directions.
  with retained_sections as (select s->>'section_key' k from jsonb_array_elements(p_composition->'sections') s),
       live_sections     as (select section_key k from contract_section_defs where template_key = p_template_key),
       retained_clauses  as (select c->>'clause_key' k from jsonb_array_elements(p_composition->'clauses') c),
       live_clauses      as (select clause_key k from contract_clause_defs where template_key = p_template_key),
       retained_fields   as (select f->>'field_key' k from jsonb_array_elements(p_composition->'fields') f),
       live_fields       as (select field_key k from contract_field_defs where template_key = p_template_key),
       diffs as (
         select 'sections only in the retained version' as lbl, k from (select k from retained_sections except select k from live_sections) a
         union all
         select 'sections only on the live template', k from (select k from live_sections except select k from retained_sections) b
         union all
         select 'clauses only in the retained version', k from (select k from retained_clauses except select k from live_clauses) c
         union all
         select 'clauses only on the live template', k from (select k from live_clauses except select k from retained_clauses) d
         union all
         select 'fields only in the retained version', k from (select k from retained_fields except select k from live_fields) e
         union all
         select 'fields only on the live template', k from (select k from live_fields except select k from retained_fields) f
       )
  select string_agg(lbl || ': ' || ks, '; ')
    into v_diff
    from (select lbl, string_agg(k, ', ' order by k) ks from diffs group by lbl) z;
  if v_diff is not null then
    raise exception 'this version cannot be restored because the template''s structure has changed since — %. Its wording is still retained and readable; restoring structure belongs to the authoring editor.', v_diff;
  end if;

  update contract_section_defs t
     set heading = s.heading, sort_order = s.sort_order, is_optional = s.is_optional,
         cut_name = s.cut_name, guidance = s.guidance
    from jsonb_to_recordset(p_composition->'sections')
      as s(section_key text, heading text, sort_order integer, is_optional boolean,
           cut_name text, guidance text)
   where t.template_key = p_template_key and t.section_key = s.section_key;

  update contract_clause_defs t
     set section_key = c.section_key, heading = c.heading, body = c.body,
         clause_type = c.clause_type, sort_order = c.sort_order, is_optional = c.is_optional,
         cut_name = c.cut_name, conditional_on = c.conditional_on, guidance = c.guidance,
         render_as_subitem = c.render_as_subitem
    from jsonb_to_recordset(p_composition->'clauses')
      as c(clause_key text, section_key text, heading text, body text, clause_type text,
           sort_order integer, is_optional boolean, cut_name text, conditional_on jsonb,
           guidance text, render_as_subitem boolean)
   where t.template_key = p_template_key and t.clause_key = c.clause_key;

  update contract_field_defs t
     set parent_field_key = f.parent_field_key, label = f.label, section = f.section,
         owner_role = f.owner_role, input_kind = f.input_kind, value_type = f.value_type,
         options = f.options, conditional_on = f.conditional_on, guidance = f.guidance,
         required = f.required, is_optional = f.is_optional, responsibility = f.responsibility,
         sort_order = f.sort_order, format_type = f.format_type, clause_key = f.clause_key,
         responsibility_kind = f.responsibility_kind, closed = f.closed,
         default_value = f.default_value
    from jsonb_to_recordset(p_composition->'fields')
      as f(field_key text, parent_field_key text, label text, section text, owner_role text,
           input_kind text, value_type text, options jsonb, conditional_on jsonb, guidance text,
           required boolean, is_optional boolean, responsibility jsonb, sort_order integer,
           format_type text, clause_key text, responsibility_kind text, closed boolean,
           default_value text)
   where t.template_key = p_template_key and t.field_key = f.field_key;
end;
$$;


--
-- Name: _sign_path_allows_minor(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sign_path_allows_minor(p_path text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT lower(btrim(coalesce(p_path, ''))) NOT IN ('horse', 'deal');
$$;


--
-- Name: _sign_path_for_categories(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sign_path_for_categories(p_categories text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_categories @> ARRAY['RIDER'] AND p_categories @> ARRAY['HORSE_OWNER'] THEN 'rider+horse'
    WHEN p_categories @> ARRAY['RIDER']       THEN 'rider'
    WHEN p_categories @> ARRAY['HORSE_OWNER'] THEN 'horse'
    WHEN p_categories @> ARRAY['GUEST']       THEN 'guest'
    ELSE '' END;
$$;


--
-- Name: _skip_required_document(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._skip_required_document(p_contact_id uuid, p_template_key text, p_reason text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row    contact_required_documents%ROWTYPE;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_actor  uuid := coalesce(p_actor, auth.uid());
BEGIN
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to skip a required document';
  END IF;

  SELECT * INTO v_row FROM contact_required_documents
   WHERE contact_id = p_contact_id AND template_key = p_template_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no % requirement on this contact to skip', p_template_key;
  END IF;
  IF v_row.skipped_at IS NOT NULL THEN
    RETURN jsonb_build_object('skipped', true, 'skipped_at', v_row.skipped_at,
                              'already', true);
  END IF;

  -- Standing rule 2026-07-29, and NOSTRIP §1: an EXECUTED document is never
  -- skipped and never removed. A satisfied requirement is evidence that the
  -- obligation existed and was met — there is nothing here to skip, and marking
  -- it skipped would misstate the record.
  IF contact_document_satisfied(p_contact_id, p_template_key) THEN
    RAISE EXCEPTION 'this requirement is satisfied by an executed document and cannot be skipped';
  END IF;

  UPDATE contact_required_documents
     SET skipped_at = now(), skipped_by = v_actor, skip_reason = v_reason
   WHERE contact_id = p_contact_id AND template_key = p_template_key;

  -- Skipping is not signing: the audit shows WHO skipped it and WHEN, and the
  -- requirement row itself carries the mark. No document row is touched.
  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (v_actor, 'UPDATE', 'contact_required_documents', p_contact_id,
          jsonb_build_object('template_key', p_template_key, 'skipped_at', NULL),
          jsonb_build_object('event', 'requirement_skipped',
                             'template_key', p_template_key,
                             'skipped_at', now(),
                             'skipped_by', v_actor,
                             'reason', v_reason));

  RETURN jsonb_build_object('skipped', true, 'skipped_at', now());
END;
$$;


--
-- Name: _unambiguous_purchase_for_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._unambiguous_purchase_for_client(p_client_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ids uuid[];
BEGIN
  IF p_client_id IS NULL THEN RETURN NULL; END IF;
  SELECT array_agg(pu.id) INTO v_ids
    FROM purchases pu
    JOIN clients cl ON cl.contact_id = pu.buyer_contact_id
   WHERE cl.id = p_client_id
     AND cl.deleted_at IS NULL
     AND pu.deleted_at IS NULL
     AND pu.org_id = cl.org_id
     AND EXISTS (
       SELECT 1 FROM fulfillment_units u
        WHERE u.purchase_id = pu.id
          AND u.deleted_at IS NULL
          AND u.current_status = 'open'
          AND u.unit_kind IN ('session','period'));
  IF v_ids IS NULL OR array_length(v_ids, 1) <> 1 THEN RETURN NULL; END IF;
  RETURN v_ids[1];
END;
$$;


--
-- Name: _value_selects_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._value_selects_code(p_value text, p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(p_code = ANY (
    ARRAY(SELECT btrim(x) FROM regexp_split_to_table(coalesce(p_value, ''), ',') x
           WHERE btrim(x) <> '')
  ), false);
$$;


--
-- Name: _value_without_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._value_without_code(p_value text, p_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(array_to_string(ARRAY(
    SELECT btrim(x) FROM regexp_split_to_table(coalesce(p_value, ''), ',') x
     WHERE btrim(x) <> '' AND btrim(x) <> p_code), ', '), '');
$$;


--
-- Name: _waiting_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._waiting_items() RETURNS TABLE(side text, kind text, id text, title text, who text, detail text, link_kind text, link_id text, since timestamp with time zone, rank integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH org AS (SELECT current_org() AS id),
       me  AS (SELECT current_contact_id() AS id, company_contact_id() AS co)

  -- ══ YOUR MOVE ════════════════════════════════════════════════════════════

  -- Money a client says they sent. Confirming it governs whether the lesson
  -- happens (D23) -- the client is already unblocked, so this is purely ours.
  SELECT 'you', 'payment_declared', p.id::text,
         'Confirm ' || to_char(coalesce(p.amount,0), 'FM$999,999') || ' '
           || coalesce(p.client_reported_method, p.payment_method, 'payment'),
         coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
         'They say it is sent. It is not confirmed.',
         'purchase', p.id::text, coalesce(p.client_reported_at, p.created_at), 1
    FROM purchases p LEFT JOIN contacts ct ON ct.id = p.buyer_contact_id CROSS JOIN org
   WHERE p.org_id = org.id AND p.deleted_at IS NULL
     AND p.client_claim_status = 'pending'

  UNION ALL
  -- Money landed and the client was never told.
  SELECT 'you', 'receipt_failed', rs.id::text,
         'Receipt never reached them', rs.recipient_email,
         left(coalesce(rs.error, 'send failed'), 120),
         'purchase', rs.purchase_id::text, rs.attempted_at, 2
    FROM receipt_sends rs, org
   WHERE rs.org_id = org.id AND NOT rs.succeeded
     AND rs.attempted_at > now() - interval '30 days'
     AND NOT EXISTS (SELECT 1 FROM receipt_sends ok
                      WHERE ok.purchase_id = rs.purchase_id AND ok.succeeded
                        AND ok.attempted_at > rs.attempted_at)

  UNION ALL
  -- D29: a proposal is not true yet and needs an explicit disposition.
  SELECT 'you', 'proposal', a.id::text,
         'Accept or reject a proposed change',
         (SELECT d.title FROM documents d WHERE d.id = a.document_id),
         left(coalesce(a.body, ''), 120),
         'document', a.document_id::text, a.created_at, 3
    FROM contract_addenda a, org
   WHERE a.org_id = org.id AND a.status = 'pending'

  UNION ALL
  SELECT 'you', 'change_open', cr.id::text,
         'An open change on a live document',
         (SELECT d.title FROM documents d WHERE d.id = cr.document_id),
         left(coalesce(cr.body, ''), 120),
         'document', cr.document_id::text, coalesce(cr.submitted_at, cr.created_at), 3
    FROM contract_change_requests cr, org
   WHERE cr.org_id = org.id AND cr.resolved_at IS NULL AND cr.submitted_at IS NOT NULL

  UNION ALL
  -- ⚠️ A DOCUMENT NOBODY HAS BEEN SENT IS YOUR MOVE, NOT THEIRS. This is the
  -- row that used to read "Yours to sign" on a document that was never sent.
  SELECT 'you', 'doc_not_sent', d.id::text,
         'Not sent to anyone yet',
         d.title,
         CASE WHEN coalesce(d.workflow_state,'') = 'in_review'
              THEN 'Still in review — finish it and send it'
              ELSE 'Ready to go out' END,
         'document', d.id::text, coalesce(d.generated_at, d.created_at), 4
    FROM documents d, org
   WHERE d.org_id = org.id AND d.deleted_at IS NULL
     AND d.status = 'AWAITING_SIGNATURE' AND d.sent_at IS NULL

  UNION ALL
  -- Genuinely yours to sign: it HAS gone out, and the signature missing is ours.
  SELECT 'you', 'doc_to_sign', d.id::text,
         'Yours to sign', d.title,
         'Everyone else is waiting on your signature',
         'document', d.id::text, coalesce(d.sent_at, d.generated_at, d.created_at), 1
    FROM documents d, org, me
   WHERE d.org_id = org.id AND d.deleted_at IS NULL
     AND d.status = 'AWAITING_SIGNATURE' AND d.sent_at IS NOT NULL
     AND EXISTS (SELECT 1 FROM document_parties dp
                  WHERE dp.document_id = d.id AND dp.is_signer
                    AND (dp.contact_id = me.id OR (me.co IS NOT NULL AND dp.contact_id = me.co))
                    AND NOT EXISTS (SELECT 1 FROM signatures sg
                                     WHERE sg.document_id = d.id AND sg.deleted_at IS NULL
                                       AND sg.signer_contact_id = dp.contact_id))

  UNION ALL
  -- An invitation that failed to send is a person who never heard from us.
  SELECT 'you', 'invite_failed', i.id::text,
         'Invitation never sent',
         coalesce(nullif(btrim(concat_ws(' ', i.first_name, i.last_name)), ''), i.email),
         left(coalesce(i.failure_reason, 'send failed'), 120),
         'contact', i.contact_id::text, i.created_at, 2
    FROM invitations i, org
   WHERE i.org_id = org.id AND i.deleted_at IS NULL
     AND i.failure_reason IS NOT NULL AND i.redeemed_at IS NULL
     AND i.status NOT IN ('superseded', 'revoked')

  UNION ALL
  -- A deal wanting something that is not a signable document (see the B3 rule).
  SELECT 'you', 'deal_open', dl.id::text,
         CASE WHEN deal_governing_document(dl.id) IS NULL
              THEN 'Nothing drafted for this deal yet'
              WHEN (deal_status(dl.id) ->> 'code') = 'complete'
              THEN 'Signed by everyone — ready to close'
              ELSE 'This deal needs a party named' END,
         coalesce(dl.title, dl.deal_type),
         NULL,
         'deal', dl.id::text, dl.created_at, 5
    FROM deals dl, org
   WHERE dl.org_id = org.id AND dl.deleted_at IS NULL AND dl.status <> 'complete'
     AND (
       deal_governing_document(dl.id) IS NULL
       OR (deal_status(dl.id) ->> 'code') = 'complete'
       OR NOT EXISTS (SELECT 1 FROM contract_parties cp
                       WHERE cp.contract_id = dl.contract_id
                         AND cp.party_role = (deal_party_roles(dl.deal_type))[1])
       OR NOT EXISTS (SELECT 1 FROM contract_parties cp
                       WHERE cp.contract_id = dl.contract_id
                         AND cp.party_role = (deal_party_roles(dl.deal_type))[2])
     )

  UNION ALL
  -- Catalog gaps, but ONLY the ones that stop money: a service nobody can buy.
  -- Cover images and staff titles are tidiness, not a next action, and they are
  -- what made the old zone nine rows long.
  SELECT 'you', 'blocks_selling', st.code,
         'Nothing is buyable under ' || st.display_name, NULL,
         'No active offering, so the service cannot be sold',
         'catalog', NULL, now(), 6
    FROM service_types st, org
   WHERE st.active AND st.code NOT IN ('INDEPENDENT_CONTRACTOR', 'ONBOARDING')
     AND NOT EXISTS (SELECT 1 FROM offerings o
                      WHERE o.org_id = org.id AND o.active AND o.service_type = st.code)

  -- ══ THEIR MOVE ═══════════════════════════════════════════════════════════

  UNION ALL
  -- Out for signature, and the signature missing is theirs.
  SELECT 'client', 'awaiting_signature', d.id::text,
         'Waiting on their signature', d.title,
         NULL,
         'document', d.id::text, coalesce(d.sent_at, d.generated_at, d.created_at), 1
    FROM documents d, org, me
   WHERE d.org_id = org.id AND d.deleted_at IS NULL
     AND d.status = 'AWAITING_SIGNATURE' AND d.sent_at IS NOT NULL
     AND EXISTS (SELECT 1 FROM document_parties dp
                  WHERE dp.document_id = d.id AND dp.is_signer
                    AND dp.contact_id IS DISTINCT FROM me.id
                    AND (me.co IS NULL OR dp.contact_id IS DISTINCT FROM me.co)
                    AND NOT EXISTS (SELECT 1 FROM signatures sg
                                     WHERE sg.document_id = d.id AND sg.deleted_at IS NULL
                                       AND sg.signer_contact_id = dp.contact_id))

  UNION ALL
  -- Invited and has not come in yet.
  SELECT 'client', 'invite_open', i.id::text,
         'Invited, has not opened it',
         coalesce(nullif(btrim(concat_ws(' ', i.first_name, i.last_name)), ''), i.email),
         CASE WHEN i.expires_at IS NOT NULL
              THEN 'Link expires ' || to_char(i.expires_at, 'Mon FMDD') END,
         'contact', i.contact_id::text, i.created_at, 2
    FROM invitations i, org
   WHERE i.org_id = org.id AND i.deleted_at IS NULL
     AND i.status = 'sent' AND i.redeemed_at IS NULL

  UNION ALL
  -- D8 §3 PENDING: in, but their paperwork is not done.
  SELECT 'client', 'account_pending', p.user_id::text,
         'Paperwork not finished',
         coalesce(p.display_name, nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.email),
         (SELECT count(*)::text FROM contact_required_documents crd
           WHERE crd.contact_id = p.contact_id AND crd.org_id = org.id
             AND crd.skipped_at IS NULL
             AND NOT contact_document_satisfied(p.contact_id, crd.template_key))
           || ' document(s) still unsigned',
         'contact', p.contact_id::text, p.created_at, 3
    FROM profiles p, org
   WHERE p.org_id = org.id AND coalesce(p.role, 'USER') = 'USER'
     AND p.contact_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM contact_required_documents crd
                  WHERE crd.contact_id = p.contact_id AND crd.org_id = org.id
                    AND crd.skipped_at IS NULL
                    AND NOT contact_document_satisfied(p.contact_id, crd.template_key))

  UNION ALL
  -- Ordered, not paid, and old enough that it is no longer simply new.
  SELECT 'client', 'unpaid_aging', p.id::text,
         'Unpaid ' || to_char(coalesce(p.amount,0), 'FM$999,999'),
         coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
         'Ordered, never paid',
         'purchase', p.id::text, p.created_at, 4
    FROM purchases p LEFT JOIN contacts ct ON ct.id = p.buyer_contact_id CROSS JOIN org
   WHERE p.org_id = org.id AND p.deleted_at IS NULL
     AND p.payment_status <> 'paid' AND p.status <> 'draft'
     AND coalesce(p.client_claim_status, 'none') <> 'pending'
     AND p.created_at < now() - interval '7 days'
$_$;


--
-- Name: _write_lesson_plan_version(uuid, text, jsonb, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._write_lesson_plan_version(p_client_id uuid, p_focus text, p_objectives jsonb, p_coach_notes text, p_reason text, p_detail text DEFAULT NULL::text, p_from_booking uuid DEFAULT NULL::uuid) RETURNS public.lesson_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cur  lesson_plans%ROWTYPE;
  v_new  lesson_plans%ROWTYPE;
  v_org  uuid;
BEGIN
  SELECT c.org_id INTO v_org FROM clients c WHERE c.id = p_client_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'client not found'; END IF;

  v_cur := _current_lesson_plan(p_client_id);

  -- The prior version is RETAINED, marked superseded — never updated in place
  -- and never deleted. Same rule as a superseded document version.
  IF v_cur.id IS NOT NULL THEN
    UPDATE lesson_plans
       SET status = 'superseded', superseded_at = now()
     WHERE id = v_cur.id;
  END IF;

  INSERT INTO lesson_plans (org_id, client_id, version, status, supersedes_id,
                            focus, objectives, coach_notes,
                            advanced_from_booking_id, created_by)
  VALUES (v_org, p_client_id, coalesce(v_cur.version, 0) + 1, 'current', v_cur.id,
          nullif(btrim(coalesce(p_focus, '')), ''),
          _lesson_plan_objectives(p_objectives),
          nullif(btrim(coalesce(p_coach_notes, '')), ''),
          p_from_booking, auth.uid())
  RETURNING * INTO v_new;

  -- THE LOG. status_events, widened by m1 — not a fifth ledger, and it has a
  -- reader (client_lesson_plan's 'log'), which is the part D19 says is missing
  -- everywhere else.
  PERFORM log_status_event('lesson_plan', v_new.id, p_reason,
            coalesce(p_detail, 'Version ' || v_new.version), v_org);

  RETURN v_new;
END;
$$;


--
-- Name: account_state_for_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_state_for_email(p_email text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_email   text := lower(btrim(coalesce(p_email, '')));
  v_user    uuid;
  v_contact uuid;
  v_signin  boolean := false;
BEGIN
  -- ⚠️ SERVICE ROLE ONLY. This function answers "does this address have an
  -- account", which is the exact question the door's anti-enumeration posture
  -- refuses to answer to a browser. It is for the SERVER to decide which email
  -- to send; the response the visitor sees is identical either way.
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF v_email = '' THEN RETURN jsonb_build_object('state', 'new'); END IF;

  SELECT u.id INTO v_user FROM auth.users u
   WHERE lower(u.email) = v_email AND u.deleted_at IS NULL
   ORDER BY u.created_at LIMIT 1;

  -- ⚠️ "CAN SIGN IN" IS AN IDENTITY, NOT A PASSWORD. Measured 2026-09-01: of 18
  -- accounts, 9 carry no `encrypted_password` at all — they are Google identities
  -- and they sign in perfectly well. Testing for a password would have sent every
  -- Google member down the "set up your auth" path they finished months ago.
  IF v_user IS NOT NULL THEN
    SELECT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = v_user)
        OR EXISTS (SELECT 1 FROM auth.users u
                    WHERE u.id = v_user
                      AND coalesce(u.encrypted_password, '') <> '')
      INTO v_signin;
  END IF;

  SELECT c.id INTO v_contact FROM contacts c
   WHERE lower(c.email) = v_email AND c.deleted_at IS NULL AND NOT c.is_company
   ORDER BY c.created_at LIMIT 1;

  RETURN jsonb_build_object(
    -- 'active' — they finished; send them to the login page.
    -- 'known'  — we hold a record (a lead, an order, an invitation) and they have
    --            never set up auth; send the activation email.
    -- 'new'    — nobody; send the activation email.
    'state', CASE WHEN v_user IS NOT NULL AND v_signin THEN 'active'
                  WHEN v_contact IS NOT NULL OR v_user IS NOT NULL THEN 'known'
                  ELSE 'new' END,
    'user_id', v_user,
    'contact_id', v_contact);
END;
$$;


--
-- Name: account_status_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_status_code(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status = 'draft' THEN 'provisioned'
    WHEN p_status IN ('redeemed','accepted') THEN 'redeemed'
    WHEN p_status = 'redeemed_unsuccessful' THEN 'redeemed_unsuccessful'
    WHEN p_status = 'revoked' THEN 'revoked'
    WHEN p_status = 'superseded' THEN 'superseded'
    WHEN p_status = 'expired' THEN 'expired'
    ELSE 'invited' END;
$$;


--
-- Name: acknowledge_content_block(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_content_block(p_slug text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid := current_org();
  v_block content_blocks%ROWTYPE;
BEGIN
  SELECT * INTO v_block FROM content_blocks WHERE org_id = v_org AND slug = p_slug;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'block not found';
  END IF;

  INSERT INTO content_acknowledgments (block_id, version, user_id)
  VALUES (v_block.id, v_block.current_version, auth.uid())
  ON CONFLICT (block_id, version, user_id) DO NOTHING;
END;
$$;


--
-- Name: activity_checklist(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activity_checklist(p_service_type text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(label ORDER BY sort_order, label), '[]'::jsonb)
  FROM activity_checklists
  WHERE org_id = current_org() AND service_type = p_service_type AND active
$$;


--
-- Name: add_booking_note(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_booking_note(p_booking_id uuid, p_phase text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b       bookings%ROWTYPE;
  v_client  uuid := current_client_id();
  v_contact uuid := current_contact_id();
  v_role    text;
  v_name    text;
  v_id      uuid;
  v_body    text := NULLIF(btrim(coalesce(p_body, '')), '');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_body IS NULL THEN RAISE EXCEPTION 'a note cannot be empty'; END IF;
  IF p_phase NOT IN ('pre','post') THEN RAISE EXCEPTION 'phase must be pre or post'; END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;

  IF v_client IS NOT NULL AND v_b.client_id = v_client THEN
    v_role := 'rider';
    SELECT trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')) INTO v_name
      FROM contacts WHERE id = v_contact;
  ELSIF coalesce(has_staff_access() AND v_b.org_id = current_org(), false) THEN
    v_role := 'instructor';
    SELECT coalesce(display_name, trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')))
      INTO v_name FROM profiles WHERE user_id = auth.uid();
  ELSE
    RAISE EXCEPTION 'not authorized to note this booking';
  END IF;

  INSERT INTO booking_notes (org_id, booking_id, author_user_id, author_role, author_name, phase, body)
    VALUES (v_b.org_id, p_booking_id, auth.uid(), v_role, NULLIF(v_name, ''), p_phase, v_body)
    RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'author_role', v_role, 'author_name', NULLIF(v_name,''),
                            'phase', p_phase, 'body', v_body);
END;
$$;


--
-- Name: add_contact_location(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_contact_location(p_contact_id uuid, p_name text, p_address text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_id  uuid;
BEGIN
  IF NOT coalesce(has_staff_access() AND v_org IS NOT NULL, false) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF p_contact_id IS NULL THEN RAISE EXCEPTION 'a contact is required'; END IF;
  p_name := nullif(btrim(p_name), '');
  IF p_name IS NULL THEN RAISE EXCEPTION 'a location name is required'; END IF;

  SELECT id INTO v_id FROM locations
   WHERE org_id = v_org AND owner_contact_id = p_contact_id AND lower(name) = lower(p_name) AND active
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO locations (org_id, name, address, owner_contact_id, is_offsite, is_default, active)
  VALUES (v_org, p_name, nullif(btrim(p_address), ''), p_contact_id, false, false, true)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: add_contract_composition(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_contract_composition(p_document_id uuid, p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT caller_may_propose(p_document_id, 'edit_deal') THEN
    RAISE EXCEPTION 'not authorized to modify this document';
  END IF;
  RETURN apply_contract_composition_spec(p_document_id, p_spec, current_contact_id());
END;
$$;


--
-- Name: add_contract_element(uuid, text, text, text, integer, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_contract_element(p_document_id uuid, p_kind text, p_section text, p_after_section text DEFAULT NULL::text, p_position integer DEFAULT NULL::integer, p_label text DEFAULT NULL::text, p_format_type text DEFAULT 'text'::text, p_options jsonb DEFAULT NULL::jsonb, p_guidance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text;
  v_new_key text;
  v_sort integer;
  v_input_kind text;
  v_after_max integer;
  v_before_min integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'document is not editable'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to modify this document';
  END IF;

  -- resolve input_kind from the format registry (fallback text)
  SELECT input_kind INTO v_input_kind FROM contract_formats WHERE format_type = p_format_type;
  v_input_kind := coalesce(v_input_kind, 'text');
  IF coalesce(p_guidance,'') = '' THEN
    SELECT guidance INTO p_guidance FROM contract_formats WHERE format_type = p_format_type;
  END IF;

  v_new_key := next_custom_field_key(p_document_id, p_label);

  IF p_kind = 'section' THEN
    -- place the new section's first field between p_after_section and the next one
    SELECT max(sort_order) INTO v_after_max FROM contract_fields
      WHERE document_id = p_document_id AND section = p_after_section;
    SELECT min(sort_order) INTO v_before_min FROM contract_fields
      WHERE document_id = p_document_id AND sort_order > coalesce(v_after_max, 0);
    v_sort := coalesce(v_after_max, 0) + CASE
      WHEN v_before_min IS NULL THEN 100
      ELSE greatest(1, (v_before_min - coalesce(v_after_max,0)) / 2) END;
  ELSE
    -- field within p_section at p_position (1-based). Shift everything at/after down.
    IF p_position IS NULL THEN
      SELECT coalesce(max(sort_order),0) + 10 INTO v_sort FROM contract_fields
        WHERE document_id = p_document_id AND section = p_section;
    ELSE
      -- the sort_order of the field currently at that position
      SELECT sort_order INTO v_sort FROM (
        SELECT sort_order, row_number() OVER (ORDER BY sort_order) AS rn
          FROM contract_fields WHERE document_id = p_document_id AND section = p_section
            AND parent_field_key IS NULL
      ) q WHERE q.rn = p_position;
      IF v_sort IS NULL THEN
        SELECT coalesce(max(sort_order),0) + 10 INTO v_sort FROM contract_fields
          WHERE document_id = p_document_id AND section = p_section;
      ELSE
        -- make room: bump this field and everything after it in the doc
        UPDATE contract_fields SET sort_order = sort_order + 10
          WHERE document_id = p_document_id AND sort_order >= v_sort;
      END IF;
    END IF;
  END IF;

  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, owner_role, value, value_type,
    required, sort_order, input_kind, format_type, options, guidance, is_optional, included)
  VALUES (
    v_org, p_document_id, v_new_key, coalesce(p_label, 'New field'), p_section, 'DEAL', NULL,
    CASE WHEN p_format_type IN ('longtext','currency','date','select') THEN p_format_type ELSE 'text' END,
    false, v_sort, v_input_kind, p_format_type, p_options, p_guidance, false, true);

  RETURN jsonb_build_object('field_key', v_new_key, 'sort_order', v_sort, 'section', p_section);
END;
$$;


--
-- Name: add_deal_document(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_deal_document(p_deal_id uuid, p_template_key text, p_has_sale_agreement text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE; v_ctr contracts%ROWTYPE; v_anchor uuid; v_doc uuid;
  v_n int; v_roles text[]; v_horse horses%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to add a document'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;
  IF v_deal.status = 'void' THEN
    RAISE EXCEPTION 'this deal is void — documents cannot be added';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM deal_template_options(v_deal.deal_type) o
                  WHERE o.template_key = p_template_key) THEN
    RAISE EXCEPTION '% is not a document a % deal carries', p_template_key, v_deal.deal_type;
  END IF;

  SELECT * INTO v_ctr FROM contracts WHERE id = v_deal.contract_id;
  v_roles := deal_party_roles(v_deal.deal_type);

  IF NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = v_deal.contract_id AND party_role = v_roles[1])
     OR NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = v_deal.contract_id AND party_role = v_roles[2]) THEN
    RAISE EXCEPTION 'both sides need at least one person before a document can be prepared';
  END IF;

  SELECT contact_id INTO v_anchor FROM contract_parties
   WHERE contract_id = v_deal.contract_id AND party_role = v_roles[2]
   ORDER BY signer_order NULLS LAST, id LIMIT 1;

  SELECT gd.document_id INTO v_doc FROM generate_document(
    v_anchor, p_template_key, v_deal.contract_id, v_ctr.horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,
                                         'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_deal.contract_id),
    NULL::text) gd;

  -- PARTYCTRL: seed default party controls for every role this document
  -- carries, so the admin panel has rows to render from creation onward.
  INSERT INTO document_party_controls (document_id, party_role, can_fill, can_edit_deal, can_suggest, can_add_clause, org_id)
  SELECT DISTINCT v_doc, dp.party_role, true, true, false, false, v_deal.org_id
    FROM document_parties dp
   WHERE dp.document_id = v_doc AND dp.party_role NOT IN ('FHE','COMPANY')
  ON CONFLICT (document_id, party_role) DO NOTHING;

  UPDATE documents SET originator_contact_id = current_contact_id(),
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key, responsibility_kind)
  SELECT v_deal.org_id, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on,
         d.closed, d.guidance, d.required, d.is_optional, d.responsibility, d.sort_order,
         d.parent_field_key, d.responsibility_kind
    FROM contract_field_defs d WHERE d.template_key = p_template_key;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF p_template_key = 'HORSE_BILL_OF_SALE' AND p_has_sale_agreement IN ('YES','NO') THEN
    UPDATE contract_fields SET value = p_has_sale_agreement
     WHERE document_id = v_doc AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';
  END IF;

  IF v_ctr.horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, v_ctr.horse_id);
    SELECT * INTO v_horse FROM horses WHERE id = v_ctr.horse_id;
    UPDATE contract_fields
       SET value = coalesce(horse_field_token_value(v_horse, 'KNOWN_CONDITIONS'), '')
     WHERE document_id = v_doc AND field_key = 'TXN.KNOWN_CONDITIONS'
       AND coalesce(btrim(value), '') = ''
       AND coalesce(horse_field_token_value(v_horse, 'KNOWN_CONDITIONS'), '') <> '';
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'template_key', p_template_key,
                            'fields_seeded', v_n);
END;
$$;


--
-- Name: add_deal_member(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_deal_member(p_deal_id uuid, p_party_role text, p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal  deals%ROWTYPE;
  v_roles text[];
  v_next  int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;
  IF v_deal.status <> 'pending' THEN
    RAISE EXCEPTION 'this deal is % and can no longer be configured', v_deal.status;
  END IF;

  v_roles := deal_party_roles(v_deal.deal_type);
  IF NOT (p_party_role = ANY (v_roles)) THEN
    RAISE EXCEPTION '% is not a party role on a % deal (expected % or %)',
      p_party_role, v_deal.deal_type, v_roles[1], v_roles[2];
  END IF;

  -- L2a: the person must already be in the system
  IF NOT EXISTS (SELECT 1 FROM contacts
                  WHERE id = p_contact_id AND org_id = v_deal.org_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'unknown contact — add the person to the system first';
  END IF;

  SELECT coalesce(max(signer_order), 0) + 1 INTO v_next
    FROM contract_parties WHERE contract_id = v_deal.contract_id;

  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_deal.org_id, v_deal.contract_id, p_contact_id, p_party_role, true, v_next)
    ON CONFLICT (contract_id, contact_id, party_role) DO NOTHING;
END;
$$;


--
-- Name: add_document_party_by_email(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_document_party_by_email(p_document_id uuid, p_party_role text, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org      uuid;
  v_state    text;
  v_contract uuid;
  v_role     text := upper(btrim(coalesce(p_party_role, '')));
  v_email    text := lower(btrim(coalesce(p_email, '')));
  v_contact  uuid;
  v_created  boolean := false;
  v_order    int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state, contract_id INTO v_org, v_state, v_contract
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT coalesce(has_staff_access() AND v_org = current_org(), false) THEN
    RAISE EXCEPTION 'only staff may add a party';
  END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this contract can no longer be edited';
  END IF;
  -- the same four roles reassign_document_party admits; the roster's other roles
  -- (FHE, PARTICIPANT, GUARDIAN ...) are seeded by their own flows.
  IF v_role NOT IN ('LESSEE','LESSOR','BUYER','SELLER') THEN
    RAISE EXCEPTION 'invalid party role: %', p_party_role;
  END IF;
  IF v_email = '' OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RAISE EXCEPTION 'a valid email address is required';
  END IF;

  -- MATCH BEFORE MINT. The email is the match key, so an address already on file
  -- resolves to that contact and their record fills the party immediately.
  SELECT id INTO v_contact FROM contacts
   WHERE org_id = v_org AND lower(email) = v_email AND deleted_at IS NULL
   ORDER BY created_at LIMIT 1;

  IF v_contact IS NULL THEN
    INSERT INTO contacts (org_id, email, name_needs_confirmation)
      VALUES (v_org, v_email, true)
      RETURNING id INTO v_contact;
    v_created := true;
  END IF;

  IF EXISTS (SELECT 1 FROM document_parties
              WHERE document_id = p_document_id AND party_role = v_role) THEN
    PERFORM reassign_document_party(p_document_id, v_role, v_contact);
  ELSE
    SELECT coalesce(max(signer_order), 0) + 1 INTO v_order
      FROM document_parties WHERE document_id = p_document_id;
    INSERT INTO document_parties (org_id, document_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, p_document_id, v_contact, v_role, true, v_order)
      ON CONFLICT (document_id, contact_id, party_role) DO NOTHING;
    IF v_contract IS NOT NULL THEN
      INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
        VALUES (v_org, v_contract, v_contact, v_role, true, v_order)
        ON CONFLICT (contract_id, contact_id, party_role) DO NOTHING;
    END IF;
    PERFORM fill_party_fields_from_contacts(p_document_id);
    PERFORM remerge_contract_from_clauses(p_document_id);
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'contact_id', v_contact, 'contact_created', v_created,
    'email', v_email, 'party_role', v_role);
END;
$_$;


--
-- Name: add_form_field(text, text, text, text, text, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_form_field(p_form_key text, p_section_heading text, p_key text, p_label text, p_type text DEFAULT 'text'::text, p_options text[] DEFAULT NULL::text[], p_from_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_base record; v_new jsonb; v_field jsonb;
  v_key text := nullif(btrim(coalesce(p_key,'')),'');
begin
  if not is_admin() then raise exception 'admin only'; end if;
  if v_key is null or nullif(btrim(coalesce(p_label,'')),'') is null then
    raise exception 'a field needs a key and a label';
  end if;
  select * into v_base from _form_edit_base(p_form_key, p_from_version);
  if v_base.schema is null then
    raise exception 'unknown form % (version %)', p_form_key, p_from_version;
  end if;
  if exists (select 1 from jsonb_array_elements(v_base.schema->'sections') s,
                          jsonb_array_elements(s->'fields') f where f->>'key' = v_key)
  then raise exception 'form % already has a field called %', p_form_key, v_key; end if;
  if not exists (select 1 from jsonb_array_elements(v_base.schema->'sections') s
                  where s->>'heading' = p_section_heading)
  then raise exception 'no section "%" on form %', p_section_heading, p_form_key; end if;

  v_field := jsonb_build_object('key', v_key, 'label', btrim(p_label),
                                'type', coalesce(nullif(btrim(coalesce(p_type,'')),''), 'text'))
    || case when p_options is not null and array_length(p_options,1) is not null
            then jsonb_build_object('options', to_jsonb(p_options)) else '{}'::jsonb end;

  select jsonb_build_object('sections', jsonb_agg(
           case when s->>'heading' = p_section_heading
                then jsonb_set(s, '{fields}', (s->'fields') || v_field)
                else s end order by sec_i)) into v_new
    from jsonb_array_elements(v_base.schema->'sections') with ordinality as q(s, sec_i);

  return save_form_definition_version(
    p_form_key, v_base.title, v_base.audience, v_base.purpose, v_new, p_from_version);
end;
$$;


--
-- Name: add_horse_emergency_contact(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_horse_emergency_contact(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_horse uuid := (p ->> 'horse_id')::uuid; v_owner uuid; v_contact uuid; v_id uuid; v_email text := nullif(btrim(p ->> 'email'),'');
BEGIN
  SELECT org_id, current_owner_contact_id INTO v_org, v_owner FROM horses WHERE id = v_horse AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR v_owner = current_contact_id()) THEN
    RAISE EXCEPTION 'only the horse owner or staff may add an emergency contact to the record';
  END IF;

  IF v_email IS NOT NULL THEN
    SELECT c.id INTO v_contact FROM contacts c JOIN profiles pr ON pr.contact_id = c.id
     WHERE c.org_id = v_org AND c.deleted_at IS NULL AND lower(c.email) = lower(v_email) LIMIT 1;
  END IF;
  IF v_contact IS NULL AND nullif(btrim(p ->> 'name'),'') IS NOT NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, phone)
    VALUES (v_org, split_part(btrim(p ->> 'name'),' ',1),
            nullif(btrim(substr(btrim(p ->> 'name'), length(split_part(btrim(p ->> 'name'),' ',1))+1)),''),
            nullif(btrim(p ->> 'phone'),''))
    RETURNING id INTO v_contact;
  END IF;

  INSERT INTO horse_relationships
    (org_id, horse_id, relationship, party_contact_id, party_name_text, phone, active, created_by_contact_id)
  VALUES (v_org, v_horse, 'EMERGENCY_CONTACT', v_contact, nullif(btrim(p ->> 'name'),''),
          nullif(btrim(p ->> 'phone'),''), true, current_contact_id())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: add_horse_provider(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_horse_provider(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_id uuid; v_horse uuid := (p ->> 'horse_id')::uuid; v_owner uuid;
BEGIN
  SELECT org_id, current_owner_contact_id INTO v_org, v_owner FROM horses WHERE id = v_horse AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR v_owner = current_contact_id()) THEN
    RAISE EXCEPTION 'only the horse owner or staff may add a provider to the record';
  END IF;
  INSERT INTO horse_relationships
    (org_id, horse_id, relationship, provider_role, role_label,
     party_contact_id, party_name_text, business_name, phone, email,
     address_line1, city, state, postal, active, created_by_contact_id)
  VALUES (v_org, v_horse, p ->> 'relationship',
     nullif(p ->> 'provider_role',''), nullif(p ->> 'role_label',''),
     nullif(p ->> 'party_contact_id','')::uuid, nullif(p ->> 'party_name_text',''),
     nullif(p ->> 'business_name',''), nullif(p ->> 'phone',''), nullif(p ->> 'email',''),
     nullif(p ->> 'address_line1',''), nullif(p ->> 'city',''), nullif(p ->> 'state',''), nullif(p ->> 'postal',''),
     true, current_contact_id())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: add_lease_participant(uuid, uuid, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_lease_participant(p_document_id uuid, p_contact_id uuid, p_days text DEFAULT NULL::text, p_hours text DEFAULT NULL::text, p_usage_pct numeric DEFAULT NULL::numeric, p_payment_pct numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_next int;
BEGIN
  v_org := lease_edit_guard(p_document_id);

  -- attach as a PARTICIPANT contract party (signatory) if not already on the doc
  IF NOT EXISTS (SELECT 1 FROM document_parties WHERE document_id = p_document_id AND contact_id = p_contact_id) THEN
    SELECT coalesce(max(signer_order),0) + 1 INTO v_next FROM document_parties WHERE document_id = p_document_id;
    INSERT INTO document_parties (org_id, document_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, p_document_id, p_contact_id, 'PARTICIPANT', true, v_next);
  END IF;

  INSERT INTO lease_participants (org_id, document_id, contact_id, days_used, hours, usage_pct, payment_pct)
    VALUES (v_org, p_document_id, p_contact_id,
            NULLIF(btrim(coalesce(p_days,'')),''), NULLIF(btrim(coalesce(p_hours,'')),''),
            p_usage_pct, p_payment_pct)
  ON CONFLICT (document_id, contact_id) DO UPDATE
    SET days_used = excluded.days_used, hours = excluded.hours,
        usage_pct = excluded.usage_pct, payment_pct = excluded.payment_pct;

  RETURN jsonb_build_object('document_id', p_document_id, 'contact_id', p_contact_id);
END;
$$;


--
-- Name: add_lease_payment_option(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_lease_payment_option(p_document_id uuid, p_amount numeric, p_describe text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_id uuid;
BEGIN
  v_org := lease_edit_guard(p_document_id);
  INSERT INTO lease_payment_options (org_id, document_id, amount, describe)
    VALUES (v_org, p_document_id, p_amount, NULLIF(btrim(coalesce(p_describe,'')),''))
    RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: add_lessee_entry(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_lessee_entry(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_horse uuid := (p ->> 'horse_id')::uuid; v_me uuid := current_contact_id();
  v_src uuid; v_id uuid; v_data jsonb := coalesce(p -> 'data', '{}'::jsonb);
  v_pcontact uuid; v_email text;
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = v_horse AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR caller_is_current_lessee(v_horse)) THEN
    RAISE EXCEPTION 'only the current lessee may add to the lessee layer';
  END IF;

  -- the lease the author is currently under (provenance)
  SELECT id INTO v_src FROM horse_relationships
   WHERE horse_id = v_horse AND relationship = 'LESSEE' AND active
     AND party_contact_id = v_me ORDER BY created_at DESC LIMIT 1;

  -- a provider entry references a contact: match by email or create from name+phone
  IF (p ->> 'kind') = 'provider' THEN
    v_email := nullif(btrim(v_data ->> 'email'), '');
    IF v_email IS NOT NULL THEN
      SELECT c.id INTO v_pcontact FROM contacts c JOIN profiles pr ON pr.contact_id = c.id
       WHERE c.org_id = v_org AND c.deleted_at IS NULL AND lower(c.email) = lower(v_email) LIMIT 1;
    END IF;
    IF v_pcontact IS NULL AND nullif(btrim(v_data ->> 'name'), '') IS NOT NULL THEN
      INSERT INTO contacts (org_id, first_name, last_name, phone)
      VALUES (v_org, split_part(btrim(v_data ->> 'name'),' ',1),
              nullif(btrim(substr(btrim(v_data ->> 'name'), length(split_part(btrim(v_data ->> 'name'),' ',1))+1)),''),
              nullif(btrim(v_data ->> 'phone'),''))
      RETURNING id INTO v_pcontact;
    END IF;
    v_data := v_data || jsonb_build_object('party_contact_id', v_pcontact);
  END IF;

  INSERT INTO horse_lessee_entries (org_id, horse_id, author_contact_id, source_document_id, kind, data)
  VALUES (v_org, v_horse, v_me, (SELECT source_document_id FROM horse_relationships WHERE id = v_src), p ->> 'kind', v_data)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: add_lookup_value(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_lookup_value(p_lookup_key text, p_raw_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key  text := btrim(coalesce(p_lookup_key, ''));
  v_val  text := btrim(coalesce(p_raw_value, ''));
  v_code text;
  v_hit  text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_val = '' THEN RAISE EXCEPTION 'a value is required'; END IF;

  -- Horse intake's vocabularies, plus TASK-ORIGIN's client_origin and
  -- contact_channel (§5 T1) — widened, not opened: an open namespace would
  -- let a public form invent vocabularies (HorseIntakeForm.tsx:222 reaches
  -- this same RPC).
  IF v_key NOT IN ('horse_breeds', 'horse_colors', 'horse_markings',
                   'horse_registration_org', 'horse_passport_country',
                   'client_origin', 'contact_channel') THEN
    RAISE EXCEPTION 'lookup % is not open to additions from a form', v_key;
  END IF;

  -- Already there, however it was capitalised? Use it.
  IF v_key = 'horse_breeds' THEN
    SELECT code INTO v_hit FROM horse_breeds
     WHERE lower(display_name) = lower(v_val) OR lower(code) = lower(v_val) LIMIT 1;
  ELSIF v_key = 'horse_colors' THEN
    SELECT code INTO v_hit FROM horse_colors
     WHERE lower(display_name) = lower(v_val) OR lower(code) = lower(v_val) LIMIT 1;
  ELSE
    SELECT code INTO v_hit FROM lookup_options
     WHERE lookup_key = v_key
       AND (lower(display_name) = lower(v_val) OR lower(code) = lower(v_val)) LIMIT 1;
  END IF;

  IF v_hit IS NOT NULL THEN
    -- A value switched off earlier is switched back on by someone needing it.
    IF v_key = 'horse_breeds' THEN
      UPDATE horse_breeds SET active = true WHERE code = v_hit AND NOT active;
    ELSIF v_key = 'horse_colors' THEN
      UPDATE horse_colors SET active = true WHERE code = v_hit AND NOT active;
    ELSE
      UPDATE lookup_options SET active = true
       WHERE lookup_key = v_key AND code = v_hit AND NOT active;
    END IF;
    RETURN jsonb_build_object('code', v_hit, 'display_name', v_val, 'created', false);
  END IF;

  -- Same code shape promote_lookup_suggestion mints, so the two paths cannot
  -- produce two different codes for one word.
  v_code := upper(regexp_replace(v_val, '[^a-zA-Z0-9]+', '_', 'g'));

  IF v_key = 'horse_breeds' THEN
    INSERT INTO horse_breeds (code, display_name, active, sort_order)
    VALUES (v_code, v_val, true, 900) ON CONFLICT (code) DO UPDATE SET active = true;
  ELSIF v_key = 'horse_colors' THEN
    INSERT INTO horse_colors (code, display_name, active, sort_order)
    VALUES (v_code, v_val, true, 900) ON CONFLICT (code) DO UPDATE SET active = true;
  ELSE
    INSERT INTO lookup_options (lookup_key, code, display_name, active, sort_order)
    VALUES (v_key, v_code, v_val, true, 900)
    ON CONFLICT (lookup_key, code) DO UPDATE SET active = true;
  END IF;

  -- The review queue exists to catch values worth adding. This one has BEEN added,
  -- so it is recorded as settled rather than left for the owner to rule on twice.
  INSERT INTO lookup_suggestions (lookup_key, raw_value, norm_value, status, org_id)
  VALUES (v_key, v_val, lower(v_val), 'promoted', current_org())
  ON CONFLICT (lookup_key, norm_value) DO UPDATE
    SET status = 'promoted', count = lookup_suggestions.count + 1, last_seen = now();

  RETURN jsonb_build_object('code', v_code, 'display_name', v_val, 'created', true);
END;
$$;


--
-- Name: add_my_location(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_my_location(p_name text, p_address text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me  uuid := current_contact_id();
  v_org uuid := current_org();
  v_id  uuid;
BEGIN
  IF v_me IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'sign in first'; END IF;
  p_name := nullif(btrim(p_name), '');
  IF p_name IS NULL THEN RAISE EXCEPTION 'a location name is required'; END IF;

  SELECT id INTO v_id FROM locations
   WHERE org_id = v_org AND owner_contact_id = v_me AND lower(name) = lower(p_name) AND active
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO locations (org_id, name, address, owner_contact_id, is_offsite, is_default, active)
  VALUES (v_org, p_name, nullif(btrim(p_address), ''), v_me, false, false, true)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: add_to_my_purchase(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_to_my_purchase(p_purchase_id uuid, p_items jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_contact uuid := current_contact_id();
  v_org     uuid := current_org();
  v_pu      purchases%ROWTYPE;
  v_off     offerings%ROWTYPE;
  v_item    jsonb;
  v_off_id  uuid;
  v_qty     integer;
  v_added   integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'nothing to add';
  END IF;

  SELECT * INTO v_pu FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'that order does not exist'; END IF;
  IF NOT (v_pu.buyer_user_id = v_uid
          OR (v_contact IS NOT NULL AND v_pu.buyer_contact_id = v_contact)) THEN
    RAISE EXCEPTION 'that order is not yours';
  END IF;
  -- ⚠️ DRAFT ONLY. Once staff open an order it is priced, minted against and
  -- possibly paid; a client adding a line to it would move money silently.
  IF coalesce(v_pu.status, '') <> 'draft' THEN
    RAISE EXCEPTION 'that order can no longer be changed here';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_off_id := nullif(btrim(coalesce(v_item->>'offering_id', '')), '')::uuid;
    IF v_off_id IS NULL THEN RAISE EXCEPTION 'every line must name an offering'; END IF;
    SELECT * INTO v_off FROM offerings
     WHERE id = v_off_id AND org_id = v_pu.org_id AND active;
    IF NOT FOUND THEN RAISE EXCEPTION 'that offering is not available'; END IF;

    v_qty := greatest(coalesce((v_item->>'quantity')::integer, 1), 1);
    INSERT INTO purchase_items (purchase_id, org_id, offering_id, label,
                                price_amount, price_unit, quantity)
    VALUES (p_purchase_id, v_pu.org_id, v_off.id, v_off.name,
            coalesce(v_off.price_amount, 0), v_off.price_unit, v_qty);
    v_added := v_added + 1;
  END LOOP;

  PERFORM _recompute_purchase_total(p_purchase_id);
  RETURN v_added;
END;
$$;


--
-- Name: admin_account_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_account_action(p_contact_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_user uuid;
BEGIN
  IF NOT coalesce(has_staff_access() AND is_admin(), false) THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  IF p_action NOT IN ('remove','unremove','soft') THEN
    RAISE EXCEPTION 'action must be remove, unremove, or soft';
  END IF;

  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id;
  IF v_org IS NULL OR v_org <> current_org() THEN
    RAISE EXCEPTION 'contact not found in this org';
  END IF;
  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_contact_id;

  IF p_action = 'remove' THEN
    UPDATE clients SET status = 'INACTIVE', updated_at = now()
      WHERE contact_id = p_contact_id AND deleted_at IS NULL;
    IF v_user IS NOT NULL THEN
      PERFORM set_config('app.allow_profile_link', '1', true);
      UPDATE profiles SET is_suspended = true WHERE user_id = v_user;
    END IF;
    RETURN jsonb_build_object('ok', true, 'action', 'remove', 'had_login', v_user IS NOT NULL);

  ELSIF p_action = 'unremove' THEN
    UPDATE clients SET status = 'ACTIVE', updated_at = now()
      WHERE contact_id = p_contact_id AND deleted_at IS NULL;
    IF v_user IS NOT NULL THEN
      PERFORM set_config('app.allow_profile_link', '1', true);
      UPDATE profiles SET is_suspended = false WHERE user_id = v_user;
    END IF;
    -- a previously archived contact comes back with the account it belongs to
    IF EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND deleted_at IS NOT NULL) THEN
      PERFORM unarchive_contact(p_contact_id);
    END IF;
    RETURN jsonb_build_object('ok', true, 'action', 'unremove');

  ELSE  -- soft: hide the account, keep every record it is attached to
    UPDATE clients SET deleted_at = now(), deleted_by = auth.uid()
      WHERE contact_id = p_contact_id AND deleted_at IS NULL;
    IF v_user IS NOT NULL THEN
      PERFORM set_config('app.allow_profile_link', '1', true);
      -- suspend the login. contact_id / org_id are NOT touched: the account
      -- must still resolve to the person for their documents to mean anything.
      UPDATE profiles SET is_suspended = true WHERE user_id = v_user;
    END IF;
    PERFORM archive_contact(p_contact_id, 'Soft delete from the account screen');
    RETURN jsonb_build_object('ok', true, 'action', 'soft', 'had_login', v_user IS NOT NULL);
  END IF;
END;
$$;


--
-- Name: FUNCTION admin_account_action(p_contact_id uuid, p_action text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_account_action(p_contact_id uuid, p_action text) IS 'remove/unremove suspend and reinstate the login. soft ARCHIVES the contact through archive_contact (D11/D32) and suspends the login — it no longer severs profiles.contact_id, which used to leave the contact visible AND its account unable to resolve to it. unremove now also unarchives, so the pair is fully reversible.';


--
-- Name: admin_cancel_booking(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_cancel_booking(p_booking_id uuid, p_scope text DEFAULT 'one'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b        bookings%ROWTYPE;
  v_ids      uuid[];
  v_id       uuid;
  v_n        int := 0;
  v_reason   text := nullif(btrim(p_reason), '');
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may cancel a booking';
  END IF;
  IF p_scope NOT IN ('one', 'future', 'all') THEN
    RAISE EXCEPTION 'scope must be one, future or all';
  END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND OR v_b.org_id IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'booking not found';
  END IF;

  -- The set to cancel. 'one' is just this booking; 'future'/'all' reach the
  -- standing series (same client + offering, i.e. the weekly rider's slot), only
  -- ever touching bookings that are still SCHEDULED. 'future' keeps everything
  -- before this booking's start; 'all' keeps only what has already happened.
  IF p_scope = 'one' THEN
    v_ids := ARRAY[p_booking_id];
  ELSE
    SELECT array_agg(b.id) INTO v_ids
      FROM bookings b
     WHERE b.org_id = v_b.org_id
       AND b.status = 'scheduled'
       AND b.account_contact_id IS NOT DISTINCT FROM v_b.account_contact_id
       AND b.offering_id IS NOT DISTINCT FROM v_b.offering_id
       AND (p_scope = 'all' OR b.starts_at >= v_b.starts_at);
  END IF;

  FOREACH v_id IN ARRAY coalesce(v_ids, ARRAY[]::uuid[]) LOOP
    -- Only scheduled bookings can be cancelled; skip anything already
    -- cancelled/completed/no_show so a mixed series does not error out.
    UPDATE bookings SET status = 'cancelled',
           notes = CASE WHEN v_reason IS NULL THEN notes
                        ELSE coalesce(notes || E'\n', '') || 'Cancelled: ' || v_reason END
     WHERE id = v_id AND status = 'scheduled';
    IF FOUND THEN
      v_n := v_n + 1;
      -- Tell the member (when there is a login), per cancelled booking.
      IF v_b.account_user_id IS NOT NULL THEN
        INSERT INTO notifications (org_id, user_id, kind, title, link)
        SELECT b.org_id, b.account_user_id, 'lesson_cancelled',
               'Your ' || coalesce(b.kind, 'booking') || ' on '
                 || to_char(b.starts_at, 'FMMonth FMDD, HH12:MI AM') || ' was cancelled',
               '/app/schedule'
          FROM bookings b WHERE b.id = v_id AND b.account_user_id IS NOT NULL;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('cancelled', v_n, 'scope', p_scope);
END;
$$;


--
-- Name: admin_client_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_accounts() RETURNS TABLE(kind text, user_id uuid, contact_id uuid, client_id uuid, first_name text, last_name text, display_name text, email text, is_suspended boolean, member_status text, created_at timestamp with time zone, tags text[], invite_id uuid, invite_status text, invite_expires_at timestamp with time zone, invite_scheduled_for date, document_count integer, order_count integer, credits jsonb, services jsonb, client_origin text, contact_channel text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    -- arm 1: login-backed accounts (unchanged, + the two new columns)
    SELECT 'account' AS kind, p.user_id, p.contact_id, cl.id AS client_id,
           p.first_name, p.last_name, p.display_name, p.email,
           p.is_suspended, m.status AS member_status, p.created_at,
           c.tags, NULL::uuid AS invite_id, NULL::text AS invite_status,
           NULL::timestamptz AS invite_expires_at, NULL::date AS invite_scheduled_for,
           c.client_origin, c.contact_channel
    FROM profiles p
    JOIN contacts c ON c.id = p.contact_id AND c.org_id = current_org() AND c.deleted_at IS NULL
    LEFT JOIN clients cl ON cl.contact_id = p.contact_id AND cl.deleted_at IS NULL
    LEFT JOIN members m ON m.user_id = p.user_id
    WHERE p.role = 'USER' AND is_admin()

    UNION ALL

    -- arm 2: provisioned clients without a login (unchanged, + the two new columns)
    SELECT 'pending', NULL, c.id, cl.id,
           c.first_name, c.last_name, NULL, c.email,
           false, NULL, cl.created_at,
           c.tags, inv.id, inv.status, inv.expires_at, inv.scheduled_for,
           c.client_origin, c.contact_channel
    FROM clients cl
    JOIN contacts c ON c.id = cl.contact_id AND c.deleted_at IS NULL
    LEFT JOIN LATERAL (
      SELECT i.id, i.status, i.expires_at, i.scheduled_for
      FROM invitations i
      WHERE lower(i.email) = lower(c.email)
      ORDER BY i.created_at DESC LIMIT 1
    ) inv ON true
    WHERE cl.org_id = current_org() AND cl.deleted_at IS NULL AND is_admin()
      AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id)

    UNION ALL

    -- arm 3: bare contacts — no clients row, no USER login (unchanged, + the
    -- two new columns). LEAD / TEAM / DIRECTORY types live on their own pages.
    SELECT 'contact', NULL, c.id, NULL,
           c.first_name, c.last_name, NULL, c.email,
           false, NULL, c.created_at,
           c.tags, inv.id, inv.status, inv.expires_at, inv.scheduled_for,
           c.client_origin, c.contact_channel
    FROM contacts c
    LEFT JOIN LATERAL (
      SELECT i.id, i.status, i.expires_at, i.scheduled_for
      FROM invitations i
      WHERE c.email IS NOT NULL AND lower(i.email) = lower(c.email)
      ORDER BY i.created_at DESC LIMIT 1
    ) inv ON true
    WHERE c.org_id = current_org() AND c.deleted_at IS NULL AND is_admin()
      AND (c.contact_type = 'CONTACT' OR c.contact_type IS NULL)
      AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id AND p.role = 'USER')
      -- not already arm 2 (a client row with a STAFF profile is in neither
      -- earlier arm, so it must land here rather than be excluded)
      AND NOT EXISTS (
        SELECT 1 FROM clients cl
        WHERE cl.contact_id = c.id AND cl.deleted_at IS NULL
          AND NOT EXISTS (SELECT 1 FROM profiles p2 WHERE p2.contact_id = c.id))
  )
  SELECT b.kind, b.user_id, b.contact_id, b.client_id,
         b.first_name, b.last_name, b.display_name, b.email,
         b.is_suspended, b.member_status, b.created_at,
         b.tags, b.invite_id, b.invite_status,
         b.invite_expires_at, b.invite_scheduled_for,
         agg.document_count, agg.order_count, agg.credits, agg.services,
         b.client_origin, b.contact_channel
  FROM base b
  LEFT JOIN LATERAL (
    SELECT
      -- same document grain as staff_contact_directory: own + party
      (SELECT count(DISTINCT d.id)::int FROM documents d
        WHERE d.deleted_at IS NULL
          AND (d.contact_id = b.contact_id
               OR EXISTS (SELECT 1 FROM document_parties dp
                           WHERE dp.document_id = d.id AND dp.contact_id = b.contact_id)))
        AS document_count,
      (SELECT count(*)::int FROM purchases pu
        WHERE pu.deleted_at IS NULL
          AND (pu.buyer_contact_id = b.contact_id
               OR (b.user_id IS NOT NULL AND pu.buyer_user_id = b.user_id)))
        AS order_count,
      -- open credit balances, each with the name it applies to
      (SELECT coalesce(jsonb_agg(jsonb_build_object('label', x.label, 'remaining', x.rem)
                                 ORDER BY x.rem DESC, x.label), '[]'::jsonb)
        FROM (
          SELECT coalesce(o.name, lc.package_key, 'Credits') AS label,
                 sum(lc.credits_remaining)::int AS rem
          FROM lesson_credits lc
          LEFT JOIN offerings o ON o.id = lc.offering_id
          WHERE lc.deleted_at IS NULL
            AND b.client_id IS NOT NULL AND lc.client_id = b.client_id
          GROUP BY 1
          HAVING sum(lc.credits_remaining) > 0
        ) x) AS credits,
      -- consumed service events keyed by service_type code
      (SELECT coalesce(jsonb_object_agg(y.st, y.n), '{}'::jsonb)
        FROM (
          SELECT z.st, sum(z.n)::int AS n FROM (
            SELECT coalesce(o.service_type, o2.service_type,
                            CASE WHEN bk.kind = 'lesson' THEN 'RIDING_LESSON' END) AS st,
                   count(*) AS n
            FROM bookings bk
            LEFT JOIN offerings o ON o.id = bk.offering_id
            LEFT JOIN lesson_credits lc2 ON lc2.id = bk.credit_id
            LEFT JOIN offerings o2 ON o2.id = lc2.offering_id
            WHERE bk.status IN ('scheduled','confirmed','completed','no_show')
              AND ((b.client_id IS NOT NULL AND bk.client_id = b.client_id)
                   OR bk.account_contact_id = b.contact_id
                   OR (b.user_id IS NOT NULL AND bk.account_user_id = b.user_id))
            GROUP BY 1
            UNION ALL
            SELECT o3.service_type, count(*)
            FROM fulfillment_units fu
            JOIN purchases pu2 ON pu2.id = fu.purchase_id AND pu2.deleted_at IS NULL
            JOIN purchase_items pi ON pi.id = fu.purchase_item_id
            JOIN offerings o3 ON o3.id = pi.offering_id
            WHERE fu.deleted_at IS NULL AND fu.unit_kind <> 'session'
              AND fu.consumed_at IS NOT NULL
              AND (pu2.buyer_contact_id = b.contact_id
                   OR (b.user_id IS NOT NULL AND pu2.buyer_user_id = b.user_id))
            GROUP BY 1
          ) z
          WHERE z.st IS NOT NULL
          GROUP BY z.st
        ) y) AS services
  ) agg ON true
$$;


--
-- Name: admin_client_bookings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_bookings(p_user_id uuid) RETURNS TABLE(id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, status text, location text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.id, b.starts_at, b.ends_at, upper(b.status), b.location
  FROM bookings b
  JOIN clients c ON c.id = b.client_id
  JOIN profiles p ON p.contact_id = c.contact_id
  WHERE is_admin() AND b.kind = 'lesson' AND p.user_id = p_user_id
  ORDER BY b.starts_at DESC
$$;


--
-- Name: admin_client_documents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_documents(p_user_id uuid) RETURNS TABLE(id uuid, title text, status text, workflow_state text, created_at timestamp with time zone, wall_gating boolean, contract_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- generated documents (the real instances)
  SELECT d.id, d.title, d.status, d.workflow_state, d.created_at, coalesce(ct.wall_gating, false), d.contract_id
  FROM documents d
  JOIN profiles p ON p.contact_id = d.contact_id
  LEFT JOIN contract_templates ct ON ct.id = d.template_id
  WHERE is_admin() AND p.user_id = p_user_id AND d.deleted_at IS NULL

  UNION ALL

  -- required templates with no document that satisfies them and none in
  -- progress → a pending requirement row:
  --   NOT_STARTED  when the person has no history for the template at all,
  --   ASSIGNED     when prior executed copies exist but are superseded
  --                (staff re-assigned it for signature).
  SELECT
    -- deterministic pseudo-id from the template key (stable list key; not a
    -- real doc).
    ('00000000-0000-0000-0000-' || substr(md5(ct.template_key), 1, 12))::uuid AS id,
    t.title,
    CASE WHEN EXISTS (
      SELECT 1 FROM documents d JOIN contract_templates t2 ON t2.id = d.template_id
      WHERE t2.template_key = ct.template_key
        AND d.contact_id = p.contact_id AND d.deleted_at IS NULL
    ) THEN 'ASSIGNED' ELSE 'NOT_STARTED' END AS status,
    'awaiting_signature'::text AS workflow_state,
    NULL::timestamptz AS created_at,
    coalesce(t.wall_gating, false) AS wall_gating,
    NULL::uuid AS contract_id -- no document exists yet, so no contract to route to
  FROM profiles p
  JOIN required_templates_for_contact(p.contact_id) ct ON true
  JOIN contract_templates t ON t.template_key = ct.template_key AND t.deleted_at IS NULL
  WHERE is_admin() AND p.user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1 FROM documents d
      JOIN contract_templates t2 ON t2.id = d.template_id
      WHERE t2.template_key = ct.template_key
        AND d.contact_id = p.contact_id AND d.deleted_at IS NULL
        AND (d.status <> 'EXECUTED'                      -- in progress (pending signature)
          OR (d.status = 'EXECUTED'
              AND coalesce(d.current_status,'') <> 'superseded'))  -- satisfied
    )

  ORDER BY created_at DESC NULLS LAST
$$;


--
-- Name: admin_client_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_items(p_client_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN NOT is_admin() THEN NULL ELSE jsonb_build_object(
    'documents', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', d.id, 'title', d.title, 'workflow_state', d.workflow_state,
        'status', d.status, 'created_at', d.created_at, 'contract_id', d.contract_id
      ) ORDER BY d.created_at DESC), '[]'::jsonb)
      FROM documents d
      WHERE d.contact_id = (SELECT contact_id FROM clients WHERE id = p_client_id)
        AND d.deleted_at IS NULL
    )
  ) END
$$;


--
-- Name: admin_client_messages(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_messages(p_user_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, sender_id uuid, recipient_id uuid, body text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT dm.id, dm.sender_id, dm.recipient_id, dm.body, dm.created_at
  FROM direct_messages dm
  WHERE is_admin()
    AND (dm.sender_id = p_user_id OR dm.recipient_id = p_user_id)
  ORDER BY dm.created_at DESC
  LIMIT p_limit
$$;


--
-- Name: admin_client_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_overview(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_contact uuid;
  v jsonb;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE user_id = p_user_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'account not found in your organization';
  END IF;
  SELECT contact_id INTO v_contact FROM profiles WHERE user_id = p_user_id;

  SELECT jsonb_build_object(
    'profile', (SELECT jsonb_build_object(
        'user_id', p.user_id, 'email', p.email, 'first_name', p.first_name,
        'last_name', p.last_name, 'display_name', p.display_name,
        'phone', pc.phone, 'mobile', pc.mobile, 'whatsapp', pc.whatsapp,
        'riding_level', p.riding_level, 'bio', p.bio, 'role', p.role,
        'is_suspended', p.is_suspended, 'created_at', p.created_at,
        'contact_id', p.contact_id,
        'client_id', (SELECT c.id FROM clients c WHERE c.contact_id = p.contact_id AND c.deleted_at IS NULL))
      FROM profiles p LEFT JOIN contacts pc ON pc.id = p.contact_id AND pc.deleted_at IS NULL WHERE p.user_id = p_user_id),
    'login', (SELECT jsonb_build_object(
        'providers', coalesce((SELECT jsonb_agg(DISTINCT i.provider)
          FROM auth.identities i WHERE i.user_id = p_user_id), '[]'::jsonb),
        'last_sign_in_at', u.last_sign_in_at,
        'created_at', u.created_at,
        'email_confirmed_at', u.email_confirmed_at)
      FROM auth.users u WHERE u.id = p_user_id),
    'member', (SELECT jsonb_build_object('status', m.status,
        'started_at', m.started_at)
      FROM members m WHERE m.user_id = p_user_id LIMIT 1),
    'counts', jsonb_build_object(
      -- ⚠️ FIX2 §4a: the buyer of a staff-provisioned order is a CONTACT, not a
      -- login. Same predicate as admin_client_accounts().order_count and as
      -- Admin.tsx's buyerFilter(), so the header and the tab cannot disagree.
      'orders',    (SELECT count(*) FROM purchases pu
                     WHERE pu.deleted_at IS NULL
                       AND (pu.buyer_user_id = p_user_id
                            OR (v_contact IS NOT NULL AND pu.buyer_contact_id = v_contact))),
      'posts',     (SELECT count(*) FROM feed_posts WHERE author_id = p_user_id),
      'documents', (SELECT count(*) FROM documents d
                     JOIN profiles p ON p.contact_id = d.contact_id
                     WHERE p.user_id = p_user_id AND d.deleted_at IS NULL),
      'bookings',  (SELECT count(*) FROM bookings b
                     JOIN clients c ON c.id = b.client_id
                     JOIN profiles p ON p.contact_id = c.contact_id
                     WHERE b.kind = 'lesson' AND p.user_id = p_user_id))
  ) INTO v;
  RETURN v;
END;
$$;


--
-- Name: admin_delete_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_invitation(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(has_staff_access() AND is_admin(), false) THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  UPDATE invitations SET deleted_at = now(), expires_at = least(expires_at, now())
   WHERE id = p_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'invitation not found'; END IF;
END;
$$;


--
-- Name: admin_expire_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_expire_invitation(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(has_staff_access() AND is_admin(), false) THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  UPDATE invitations SET expires_at = now()
   WHERE id = p_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'invitation not found'; END IF;
END;
$$;


--
-- Name: admin_form_definitions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_form_definitions() RETURNS TABLE(form_key text, title text, audience text, purpose text, schema jsonb, version integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select fd.form_key, fd.title, fd.audience, fd.purpose, fd.schema, fd.version
  from form_definitions fd
  where fd.active and has_staff_access()
  order by fd.audience, fd.title
$$;


--
-- Name: admin_offering_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_offering_usage() RETURNS TABLE(offering_id uuid, live_lines integer, bookings integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.id,
         (SELECT count(*)::int FROM purchase_items pi
            JOIN purchases pu ON pu.id = pi.purchase_id AND pu.deleted_at IS NULL
           WHERE pi.offering_id = o.id AND pi.voided_at IS NULL),
         (SELECT count(*)::int FROM bookings b
           WHERE b.offering_id = o.id AND b.status NOT IN ('cancelled','expired'))
    FROM offerings o
   WHERE has_staff_access() AND o.org_id = current_org();
$$;


--
-- Name: admin_oversight(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_oversight() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_usage jsonb;
  v_activity jsonb;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'admin access required';
  END IF;

  SELECT jsonb_build_object(
    'members',          (SELECT count(*) FROM profiles WHERE org_id = v_org),
    'open_engagements', (SELECT count(*) FROM contracts
                          WHERE org_id = v_org AND deleted_at IS NULL
                            AND status NOT IN ('executed','void','declined')),
    'open_support',     (SELECT count(*) FROM support_requests WHERE org_id = v_org AND status <> 'resolved'),
    'feed_posts',       (SELECT count(*) FROM feed_posts WHERE org_id = v_org AND pulled_down = false),
    'flagged_posts',    (SELECT count(*) FROM feed_posts WHERE org_id = v_org AND scan_state <> 'clean')
  ) INTO v_usage;

  SELECT COALESCE(jsonb_agg(a ORDER BY a.occurred_at DESC), '[]'::jsonb) INTO v_activity
  FROM (
    SELECT occurred_at, action, table_name, actor_user_id
    FROM audit_logs
    ORDER BY occurred_at DESC
    LIMIT 50
  ) a;

  RETURN jsonb_build_object('usage', v_usage, 'activity', v_activity);
END;
$$;


--
-- Name: admin_purge_contact(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_purge_contact(p_contact_id uuid, p_confirm text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_denied_users constant uuid[] := ARRAY[
    'b45a5503-89bc-489a-b012-c7fbf5c09632',
    'fdbdfe89-76d7-486b-b734-8e23b09e0353',
    '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'
  ]::uuid[];
  c_denied_contacts constant uuid[] := ARRAY[
    '75475f66-8950-4f13-832c-5471070737f8',
    '862b7936-9148-465c-b0db-b83246e236a0',
    '352c3898-65d0-4a90-ad59-29107b7e03fe',
    'c6f7cddc-69da-4948-8e62-4a310f079100'
  ]::uuid[];
  v_org      uuid;
  v_user     uuid;
  v_client   uuid;
  v_email    text;
  r          record;
  v_sql      text;
  v_counts   jsonb := '{}'::jsonb;
  v_n        bigint;
BEGIN
  IF p_confirm IS DISTINCT FROM 'PURGE' THEN
    RAISE EXCEPTION 'admin_purge_contact: confirmation token required';
  END IF;
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'admin_purge_contact: staff access required';
  END IF;

  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'admin_purge_contact: no such contact'; END IF;
  IF v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'admin_purge_contact: contact is not in your organization';
  END IF;

  -- ── PROTECTED-IDENTITY GATE (kept identical to purge_account) ─────────────
  IF p_contact_id = ANY(c_denied_contacts) THEN
    RAISE EXCEPTION 'admin_purge_contact: protected identity — refusing';
  END IF;
  IF EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND is_company) THEN
    RAISE EXCEPTION 'admin_purge_contact: company contact — refusing';
  END IF;

  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_contact_id;
  IF v_user = ANY(c_denied_users) THEN
    RAISE EXCEPTION 'admin_purge_contact: protected account — refusing';
  END IF;
  SELECT id INTO v_client FROM clients WHERE contact_id = p_contact_id;
  IF v_user IS NOT NULL THEN SELECT lower(email) INTO v_email FROM auth.users WHERE id = v_user; END IF;

  -- ── 1. Attribution columns: NULL them (keep the row, drop the pointer) ────
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col, c.confrelid::regclass::text AS ref
      FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
     WHERE c.contype = 'f'
       AND c.confrelid IN ('contacts'::regclass, 'profiles'::regclass, 'clients'::regclass)
       AND c.conrelid <> 'profiles'::regclass
       AND (a.attname IN ('deleted_by','updated_by','created_by','edited_by','administered_by')
            OR a.attname ~ '(actor|author|granted_by|proposed_by|resolved_by|requested_by|entered_by|cancelled_by|archived_by|confirmed_by|created_by|reopened_by|agreed_by|voided_by|claimed_by|originator|provider|signatory|vendor)')
  LOOP
    IF r.ref = 'contacts' AND p_contact_id IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'profiles' AND v_user IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'clients'  AND v_client  IS NULL THEN CONTINUE; END IF;
    v_sql := format('UPDATE %s SET %I = NULL WHERE %I = %L',
                    r.tbl, r.col, r.col,
                    (CASE r.ref WHEN 'contacts' THEN p_contact_id
                                WHEN 'clients'  THEN v_client
                                ELSE v_user END)::text);
    EXECUTE v_sql;
  END LOOP;

  -- ── 2. Ownership rows: delete, children first (mirrors purge_account) ─────
  -- ⚠️ 2026-09-15 additions — the contact's own DOCUMENTS may carry rows that
  -- belong to OTHER parties. Clear those FIRST so the documents delete (below)
  -- does not hit a RESTRICT edge from a counterparty's row.
  DELETE FROM signatures          WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM esign_consents      WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM document_deliveries WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM document_opened     WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM document_party_hidden WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);

  DELETE FROM esign_consents        WHERE contact_id = p_contact_id;
  DELETE FROM signatures            WHERE signer_contact_id = p_contact_id;
  DELETE FROM document_shares       WHERE shared_with_contact_id = p_contact_id;
  DELETE FROM document_deliveries   WHERE recipient_contact_id = p_contact_id;
  -- ⚠️ 2026-09-15 — per-contact document interaction rows (NO ACTION onto contacts).
  DELETE FROM document_opened          WHERE contact_id = p_contact_id;
  DELETE FROM document_party_hidden    WHERE contact_id = p_contact_id;
  DELETE FROM contract_change_request_seen WHERE contact_id = p_contact_id;
  DELETE FROM booking_note_seen        WHERE contact_id = p_contact_id;
  DELETE FROM document_party_archives WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM document_party_controls WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM contract_change_log   WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM contract_change_requests WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM contract_addenda      WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM contract_fields       WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM contract_execution_audit WHERE document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM document_parties      WHERE contact_id = p_contact_id
                                       OR document_id IN (SELECT id FROM documents WHERE contact_id = p_contact_id);
  DELETE FROM documents             WHERE contact_id = p_contact_id;
  DELETE FROM contract_parties      WHERE contact_id = p_contact_id;
  DELETE FROM contact_required_documents WHERE contact_id = p_contact_id;
  DELETE FROM groups                WHERE contact_id = p_contact_id;
  DELETE FROM evaluation_report_shares WHERE shared_with_contact_id = p_contact_id;
  DELETE FROM evaluation_reports    WHERE contact_id = p_contact_id;
  DELETE FROM horse_relationships   WHERE party_contact_id = p_contact_id;
  UPDATE horses SET current_owner_contact_id = NULL WHERE current_owner_contact_id = p_contact_id;
  UPDATE horses SET lessee_contact_id = NULL WHERE lessee_contact_id = p_contact_id;
  DELETE FROM billable_lines        WHERE payer_contact_id = p_contact_id;
  DELETE FROM cost_allocation_rules WHERE payer_contact_id = p_contact_id;
  DELETE FROM board_agreements      WHERE boarder_contact_id = p_contact_id;
  UPDATE contacts SET guardian_contact_id = NULL WHERE guardian_contact_id = p_contact_id;

  -- ⚠️ 2026-09-15 — payments (NO ACTION onto contacts, RESTRICT onto purchases).
  -- Delete by payer AND by the contact's purchases, BEFORE the purchases delete.
  DELETE FROM payments WHERE payer_contact_id = p_contact_id
                          OR purchase_id IN (
                               SELECT id FROM purchases WHERE buyer_contact_id = p_contact_id
                                 OR (v_user IS NOT NULL AND buyer_user_id = v_user));

  -- money + fulfillment spine
  DELETE FROM fulfillment_units WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_contact_id = p_contact_id
      OR (v_user IS NOT NULL AND buyer_user_id = v_user));
  DELETE FROM receipt_sends WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_contact_id = p_contact_id
      OR (v_user IS NOT NULL AND buyer_user_id = v_user));
  DELETE FROM purchase_items WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_contact_id = p_contact_id
      OR (v_user IS NOT NULL AND buyer_user_id = v_user));
  DELETE FROM status_events WHERE entity_type = 'order' AND entity_id IN (
    SELECT id FROM purchases WHERE buyer_contact_id = p_contact_id
      OR (v_user IS NOT NULL AND buyer_user_id = v_user));
  DELETE FROM purchases WHERE buyer_contact_id = p_contact_id
      OR (v_user IS NOT NULL AND buyer_user_id = v_user);

  -- ⚠️ 2026-09-15 — requests (NO ACTION onto contacts) + its RESTRICT child.
  DELETE FROM request_alert_sends WHERE request_id IN (
    SELECT id FROM requests WHERE contact_id = p_contact_id);
  DELETE FROM requests WHERE contact_id = p_contact_id;

  -- bookings + credits
  DELETE FROM bookings WHERE account_contact_id = p_contact_id
                          OR (v_user IS NOT NULL AND account_user_id = v_user)
                          OR (v_client IS NOT NULL AND client_id = v_client);
  IF v_client IS NOT NULL THEN
    DELETE FROM lesson_credits WHERE client_id = v_client;
  END IF;

  -- community (only when there is a login)
  IF v_user IS NOT NULL THEN
    DELETE FROM feed_seen          WHERE user_id = v_user;
    DELETE FROM feed_shares        WHERE from_user_id = v_user OR to_user_id = v_user;
    DELETE FROM feed_account_items WHERE user_id = v_user;
    DELETE FROM feed_view_pref     WHERE user_id = v_user;
    DELETE FROM feed_posts         WHERE author_id = v_user;
    DELETE FROM content_acknowledgments WHERE user_id = v_user;
    DELETE FROM notifications      WHERE user_id = v_user;
    DELETE FROM members            WHERE user_id = v_user;
  END IF;
  DELETE FROM invitations        WHERE contact_id = p_contact_id
                                    OR (v_email IS NOT NULL AND lower(email) = v_email);

  -- anchors last
  IF v_client IS NOT NULL THEN DELETE FROM clients WHERE id = v_client; END IF;
  IF v_user IS NOT NULL THEN
    DELETE FROM profiles WHERE user_id = v_user;
    DELETE FROM auth.users WHERE id = v_user;
  END IF;
  DELETE FROM contacts WHERE id = p_contact_id;

  -- ── 3. Orphan sweep: prove nothing still points at the purged identity ────
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col, c.confrelid::regclass::text AS ref
      FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
     WHERE c.contype = 'f'
       AND c.confrelid IN ('contacts'::regclass, 'profiles'::regclass, 'clients'::regclass)
  LOOP
    IF r.ref = 'contacts' AND p_contact_id IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'profiles' AND v_user IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'clients'  AND v_client  IS NULL THEN CONTINUE; END IF;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I = %L', r.tbl, r.col,
                   (CASE r.ref WHEN 'contacts' THEN p_contact_id
                               WHEN 'clients'  THEN v_client
                               ELSE v_user END)::text) INTO v_n;
    IF v_n > 0 THEN
      v_counts := v_counts || jsonb_build_object(r.tbl || '.' || r.col, v_n);
    END IF;
  END LOOP;

  IF v_counts <> '{}'::jsonb THEN
    RAISE EXCEPTION 'admin_purge_contact: orphaned references remain: %', v_counts::text;
  END IF;

  RETURN jsonb_build_object('purged', true, 'contact_id', p_contact_id,
                            'user_id', v_user, 'had_login', v_user IS NOT NULL);
END;
$$;


--
-- Name: admin_void_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_void_order(p_purchase_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_item uuid;
  v_n int := 0;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may cancel an order';
  END IF;
  SELECT org_id INTO v_org FROM purchases WHERE id = p_purchase_id;
  IF v_org IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'order not found';
  END IF;

  -- Void every live line — void_purchase_item recomputes the total and voids the
  -- ORDER when the last live line goes. No second engine.
  FOR v_item IN
    SELECT id FROM purchase_items WHERE purchase_id = p_purchase_id AND voided_at IS NULL
  LOOP
    PERFORM void_purchase_item(v_item, p_reason);
    v_n := v_n + 1;
  END LOOP;

  RETURN (SELECT jsonb_build_object('purchase_id', p_purchase_id,
            'voided_items', v_n, 'status', p.status)
          FROM purchases p WHERE p.id = p_purchase_id);
END;
$$;


--
-- Name: advance_document_workflow(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_document_workflow(p_document_id uuid, p_to text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org       uuid;
  v_from      text;
  v_recip     boolean;
  v_is_staff  boolean;
  v_is_party  boolean;
  v_blockers  jsonb;
  v_title     text;
  v_horse_confirmed timestamptz;
  v_signed    boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id, workflow_state, recipient_editing,
         coalesce(title, 'A contract'), horse_section_confirmed_at
    INTO v_org, v_from, v_recip, v_title, v_horse_confirmed
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF p_to = 'executed' THEN
    RAISE EXCEPTION 'workflow_state ''executed'' is reached only by signing (record_signature), not manually';
  END IF;
  IF p_to NOT IN ('editable','editing','in_review','locked','void') THEN
    RAISE EXCEPTION 'unknown target workflow_state: %', p_to;
  END IF;

  v_is_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  v_is_party := caller_is_document_party(p_document_id);

  IF NOT (v_is_staff OR v_is_party) THEN
    RAISE EXCEPTION 'not authorized to advance document %', p_document_id;
  END IF;

  IF v_from = p_to THEN
    RETURN v_from;
  END IF;

  IF v_from = 'executed' THEN
    RAISE EXCEPTION 'document is executed and cannot change workflow_state';
  END IF;

  IF p_to = 'void' THEN
    IF NOT v_is_staff THEN
      RAISE EXCEPTION 'only staff may void a document';
    END IF;

  ELSIF p_to = 'editing' THEN
    IF v_from NOT IN ('editable') THEN
      RAISE EXCEPTION 'illegal transition %→editing', v_from;
    END IF;
    -- H1: originator authority collapsed — the company (staff) authors; a
    -- counterparty opens editing only when recipient editing is enabled.
    IF NOT v_is_staff AND NOT v_recip THEN
      RAISE EXCEPTION 'the counterparty may open editing only when recipient editing is enabled';
    END IF;

  ELSIF p_to = 'editable' THEN
    -- LEASEFIX 2026-08-09: a LOCKED document with NO standing signature had no way
    -- back. remove_my_signature is the documented escape from locked (L9), but it
    -- is a no-op when nobody has signed, so a document locked prematurely could
    -- only be VOIDED — losing the draft. The staff "Withdraw / correct" button is
    -- shown in exactly that state and raised 'illegal transition locked→editable'
    -- on every click.
    -- Reopening is staff-only, and is refused the moment a signature stands: with
    -- a signature the escape is withdrawal, which archives the attestation to
    -- audit_logs first. That ordering is the whole point of L9 and is preserved.
    IF v_from = 'locked' THEN
      IF NOT v_is_staff THEN
        RAISE EXCEPTION 'only staff may reopen a locked document';
      END IF;
      IF EXISTS (SELECT 1 FROM signatures
                  WHERE document_id = p_document_id
                    AND signed_at IS NOT NULL AND deleted_at IS NULL) THEN
        RAISE EXCEPTION 'this document is signed — the signer must remove their signature before it can be reopened';
      END IF;
    ELSIF v_from NOT IN ('editing','in_review') THEN
      RAISE EXCEPTION 'illegal transition %→editable', v_from;
    END IF;

  ELSIF p_to = 'in_review' THEN
    IF v_from NOT IN ('editable','editing') THEN
      RAISE EXCEPTION 'illegal transition %→in_review', v_from;
    END IF;

  ELSIF p_to = 'locked' THEN
    IF v_from NOT IN ('in_review','editable','editing') THEN
      RAISE EXCEPTION 'illegal transition %→locked', v_from;
    END IF;
    -- ALL lock preconditions live in contract_lock_blockers (shared with
    -- approve_contract_review) — never re-implement them here.
    v_blockers := contract_lock_blockers(p_document_id);
    IF jsonb_array_length(v_blockers) > 0 THEN
      RAISE EXCEPTION 'cannot lock: %',
        (SELECT string_agg(b->>'message', '; ') FROM jsonb_array_elements(v_blockers) b);
    END IF;
  END IF;

  UPDATE documents SET workflow_state = p_to WHERE id = p_document_id;

  IF p_to = 'locked' THEN
    -- Seed a PENDING signature row for every signer party so the signing surface
    -- has something to render. Idempotent (unique key), leaves sealed rows alone.
    INSERT INTO signatures (org_id, document_id, signer_contact_id, party_role, method)
      SELECT v_org, p_document_id, dp.contact_id, dp.party_role, 'TYPED'
        FROM document_parties dp
       WHERE dp.document_id = p_document_id
         AND dp.is_signer = true
         AND dp.contact_id IS NOT NULL
         AND dp.party_role = ANY (ARRAY['CLIENT','BUYER','SELLER','LESSOR','LESSEE',
              'OWNER','RIDER','PARTICIPANT','PARENT','GUARDIAN','EMERGENCY_CONTACT',
              'CONTRACTOR','FACILITY_CONTACT','COMPANY'])
      ON CONFLICT (document_id, signer_contact_id, party_role) DO NOTHING;

    SELECT EXISTS (SELECT 1 FROM signatures
                   WHERE document_id = p_document_id AND deleted_at IS NULL
                     AND signed_at IS NOT NULL) INTO v_signed;
    IF NOT v_signed THEN
      IF EXISTS (SELECT 1 FROM contract_clause_defs cdf JOIN documents d2 ON true JOIN contract_templates ct2 ON ct2.id=d2.template_id AND ct2.template_key=cdf.template_key WHERE d2.id=p_document_id) THEN
       PERFORM remerge_contract_from_clauses(p_document_id);
     ELSE
       PERFORM remerge_contract_from_fields(p_document_id);
     END IF;
    END IF;
    -- CLOSEOUT §1.5 (B2, owner-ruled 2026-08-18): the lock-time
    -- ensure_horse_documents call is REMOVED. A party reviewing a lease they
    -- might not sign gets nothing else attached; execution
    -- (apply_contract_execution_effects) creates HORSE_EMERGENCY_VET +
    -- RELEASE_HORSE_CARE, because only then is the horse genuinely coming
    -- into care.
  END IF;

  IF p_to IN ('in_review','locked') THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      SELECT DISTINCT v_org, pr.user_id,
        CASE p_to WHEN 'in_review' THEN 'contract_in_review' ELSE 'contract_locked' END,
        v_title || (CASE p_to WHEN 'in_review' THEN ' is ready for your review'
                              ELSE ' is ready to sign' END),
        '/app/contracts/' || p_document_id::text
      FROM document_parties dp
      JOIN contacts pc ON pc.id = dp.contact_id
      JOIN profiles pr ON (pr.contact_id = dp.contact_id
                           OR (pc.email IS NOT NULL AND lower(pr.email) = lower(pc.email)))
      WHERE dp.document_id = p_document_id
        AND pr.user_id IS NOT NULL
        AND pr.user_id <> auth.uid();
  END IF;

  RETURN p_to;
END;
$$;


--
-- Name: FUNCTION advance_document_workflow(p_document_id uuid, p_to text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.advance_document_workflow(p_document_id uuid, p_to text) IS 'The workflow state machine: editable→editing (a party opens editing; counterparty needs recipient_editing), editing/in_review→editable, editable/editing→in_review, in_review/editable/editing→locked (guarded: no open change requests, all required fields filled), any→void (staff only). Rejects illegal transitions and any manual →executed (that is record_signature''s job). Notifies the counterparty on in_review/locked.';


--
-- Name: affiliation_reconciliation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.affiliation_reconciliation() RETURNS TABLE(contact_id uuid, display_code text, name text, has_account boolean, is_deleted boolean, derived_groups text[], current_groups text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.display_code,
         nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')), ''),
         (p.user_id IS NOT NULL),
         (c.deleted_at IS NOT NULL),
         coalesce(derive_affiliations(c.id), ARRAY[]::text[]),
         coalesce((SELECT array_agg(DISTINCT g.group_type ORDER BY g.group_type)
                     FROM groups g WHERE g.contact_id = c.id),
                  ARRAY[]::text[])
    FROM contacts c
    LEFT JOIN profiles p ON p.contact_id = c.id
   WHERE c.deleted_at IS NULL
      OR EXISTS (SELECT 1 FROM groups g WHERE g.contact_id = c.id)
      OR EXISTS (SELECT 1 FROM documents d WHERE d.contact_id = c.id AND d.status = 'EXECUTED' AND d.deleted_at IS NULL)
   ORDER BY nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')), '');
$$;


--
-- Name: agree_change_request(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agree_change_request(p_request_id uuid, p_agreed boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_org uuid; v_parent uuid; v_sub timestamptz; v_cid uuid; v_yes boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_yes := coalesce(p_agreed, true);

  SELECT document_id, org_id, parent_request_id, submitted_at
    INTO v_doc, v_org, v_parent, v_sub
    FROM contract_change_requests WHERE id = p_request_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown change request'; END IF;
  IF v_parent IS NOT NULL THEN RAISE EXCEPTION 'close the thread on its first entry'; END IF;
  IF v_sub IS NULL THEN RAISE EXCEPTION 'this request has not been submitted for review yet'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  v_cid := current_contact_id();

  IF v_yes THEN
    UPDATE contract_change_requests
       SET resolved_at            = now(),
           resolved_by_contact_id = v_cid,
           agreed_at              = now(),
           agreed_by_contact_id   = v_cid,
           updated_at             = now()
     WHERE id = p_request_id;
  ELSE
    -- REOPEN — either party. Back into the open set, so locking blocks again.
    UPDATE contract_change_requests
       SET resolved_at            = NULL,
           resolved_by_contact_id = NULL,
           agreed_at              = NULL,
           agreed_by_contact_id   = NULL,
           reopened_at            = now(),
           reopened_by_contact_id = v_cid,
           updated_at             = now()
     WHERE id = p_request_id;
  END IF;

  RETURN jsonb_build_object('id', p_request_id, 'agreed', v_yes, 'reopened', NOT v_yes);
END;
$$;


--
-- Name: app_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT role FROM profiles WHERE user_id = auth.uid()
$$;


--
-- Name: append_request_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_request_note(p_request_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by  text;
  v_out jsonb;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'not authorized to log request notes';
  END IF;
  IF NULLIF(trim(coalesce(p_note, '')), '') IS NULL THEN
    RAISE EXCEPTION 'note text is required';
  END IF;

  -- by_name: the caller's profile first name (email stands in for a nameless
  -- profile; 'Staff' is the last-resort label — never NULL in the timeline).
  SELECT coalesce(NULLIF(trim(p.first_name), ''), p.email, 'Staff') INTO v_by
    FROM profiles p WHERE p.user_id = auth.uid();
  v_by := coalesce(v_by, 'Staff');

  UPDATE requests
     SET staff_notes = staff_notes || jsonb_build_object(
           'at', now(), 'by_name', v_by, 'note', trim(p_note))
   WHERE id = p_request_id
   RETURNING staff_notes INTO v_out;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown request: %', p_request_id;
  END IF;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION append_request_note(p_request_id uuid, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.append_request_note(p_request_id uuid, p_note text) IS 'Append a staff call note {at, by_name, note} to requests.staff_notes. Staff-gated (has_staff_access()); returns the updated timeline.';


--
-- Name: apply_affiliations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_affiliations(p_contact_id uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_want text[] := coalesce(derive_affiliations(p_contact_id), ARRAY[]::text[]);
BEGIN
  -- add missing group rows
  INSERT INTO groups (contact_id, group_type)
  SELECT p_contact_id, g FROM unnest(v_want) g
  ON CONFLICT (contact_id, group_type) DO NOTHING;

  -- remove group rows no longer derived
  DELETE FROM groups
   WHERE contact_id = p_contact_id
     AND group_type = ANY(_group_types())
     AND group_type <> ALL(v_want);

  RETURN v_want;
END;
$$;


--
-- Name: apply_booking_fee(uuid, text, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_booking_fee(p_booking_id uuid, p_fee_kind text, p_change_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_supersedes uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_b         bookings%ROWTYPE;
  v_contact   uuid;
  v_amount    numeric;
  v_clause    text;
  v_wording   text;
  v_reason    text := nullif(btrim(coalesce(p_reason, '')), '');
  v_purchase  uuid;
  v_charge    uuid;
  v_old       booking_fee_charges%ROWTYPE;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  IF p_fee_kind NOT IN ('computed', 'no_show', 'late_start_before', 'late_start_after', 'custom', 'waived') THEN
    RAISE EXCEPTION 'unknown fee kind: %', p_fee_kind;
  END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;

  IF p_change_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM booking_change_requests WHERE id = p_change_id AND booking_id = p_booking_id) THEN
      RAISE EXCEPTION 'change request does not belong to this booking';
    END IF;
  END IF;

  -- F1: a reason is required for anything other than the computed default.
  IF p_fee_kind <> 'computed' AND v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required for %', p_fee_kind;
  END IF;

  -- resolve amount + the wording the client/staff will see (TRAPS/F1: every
  -- option carries the policy wording so staff know which clause they invoke)
  IF p_fee_kind = 'computed' THEN
    v_amount := reschedule_fee(v_b.org_id, v_b.starts_at);
    v_clause := '§6';
    SELECT f.label INTO v_wording
      FROM booking_change_fees f
     WHERE f.org_id = v_b.org_id AND f.active
       AND v_b.starts_at - now() < make_interval(hours => f.hours_before)
     ORDER BY f.hours_before ASC LIMIT 1;
    v_wording := coalesce(v_wording, CASE WHEN v_amount > 0 THEN 'Rescheduling fee' ELSE 'No rescheduling fee applies' END);
  ELSIF p_fee_kind = 'no_show' THEN
    v_amount  := 75.00;
    v_clause  := '§6';
    v_wording := 'No-call/no-show — client did not attend and did not contact us before the scheduled start time (Company Policies §6)';
  ELSIF p_fee_kind = 'late_start_before' THEN
    v_amount  := 30.00;
    v_clause  := '§7';
    v_wording := 'Late start — contacted us before the start time, no later slot was available (Company Policies §7)';
  ELSIF p_fee_kind = 'late_start_after' THEN
    v_amount  := 40.00;
    v_clause  := '§7';
    v_wording := 'Late start — contacted us after the start time, we could not accommodate (Company Policies §7)';
  ELSIF p_fee_kind = 'custom' THEN
    IF p_amount IS NULL OR p_amount < 0 THEN RAISE EXCEPTION 'a non-negative amount is required for a custom fee'; END IF;
    v_amount  := p_amount;
    v_clause  := NULL;
    v_wording := v_reason;
  ELSE -- waived
    v_amount  := 0;
    v_clause  := NULL;
    v_wording := 'Fee waived — ' || v_reason;
  END IF;

  -- the billable party: contact first (order/receipt ownership convention
  -- throughout this codebase), account login as the notification target.
  SELECT cl.contact_id INTO v_contact FROM clients cl WHERE cl.id = v_b.client_id AND cl.deleted_at IS NULL;
  IF v_contact IS NULL AND v_b.account_user_id IS NULL THEN
    RAISE EXCEPTION 'this booking has no billable party';
  END IF;

  -- one payment spine (D6): an ordinary purchases row, offering_id NULL so no
  -- fulfillment unit / credit / affiliation trigger fires on the line item.
  INSERT INTO purchases (org_id, buyer_contact_id, buyer_user_id, status, amount, payment_status, notes)
  VALUES (v_b.org_id, v_contact, v_b.account_user_id, 'awaiting_payment', v_amount, 'unpaid',
          coalesce('Booking fee — ' || v_wording, 'Booking fee'))
  RETURNING id INTO v_purchase;

  INSERT INTO purchase_items (org_id, purchase_id, offering_id, label, price_amount, quantity)
  VALUES (v_b.org_id, v_purchase, NULL, left(v_wording, 500), v_amount, 1);

  -- a waiver settles at zero through the SAME function every other charge
  -- settles through — never a second write path, not even for $0.
  IF v_amount = 0 THEN
    PERFORM mark_purchase_paid(v_purchase, 0, v_reason, 'waived');
  ELSE
    PERFORM notify_purchase_unpaid(v_purchase);
  END IF;

  INSERT INTO booking_fee_charges (org_id, booking_id, change_request_id, purchase_id,
                                   fee_kind, policy_clause, policy_wording, amount, reason, decided_by)
  VALUES (v_b.org_id, p_booking_id, p_change_id, v_purchase,
          p_fee_kind, v_clause, v_wording, v_amount, v_reason, auth.uid())
  RETURNING id INTO v_charge;

  IF p_supersedes IS NOT NULL THEN
    SELECT * INTO v_old FROM booking_fee_charges WHERE id = p_supersedes AND org_id = v_b.org_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'the charge being corrected was not found'; END IF;
    IF v_old.superseded_by IS NOT NULL THEN RAISE EXCEPTION 'that charge has already been superseded'; END IF;
    -- an unpaid superseded charge is voided so it stops showing as owed
    -- alongside its replacement; a paid one is left exactly as it is (D11 —
    -- nothing settled is mutated or purged).
    UPDATE purchases SET status = 'void'
     WHERE id = v_old.purchase_id AND payment_status <> 'paid';
    UPDATE booking_fee_charges SET superseded_by = v_charge WHERE id = p_supersedes;
  END IF;

  RETURN jsonb_build_object('charge_id', v_charge, 'purchase_id', v_purchase, 'amount', v_amount, 'fee_kind', p_fee_kind);
END;
$_$;


--
-- Name: FUNCTION apply_booking_fee(p_booking_id uuid, p_fee_kind text, p_change_id uuid, p_amount numeric, p_reason text, p_supersedes uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_booking_fee(p_booking_id uuid, p_fee_kind text, p_change_id uuid, p_amount numeric, p_reason text, p_supersedes uuid) IS 'FEECHOICE F1/F3: staff choose the fee on a booking — the computed reschedule amount, a named policy fee (no-show $75, late-start $30/$40), a custom amount, or a waiver — and it settles through mark_purchase_paid, the same spine CASHCONFIRM/ZELLECLOSE use. booking_change_fees is read-only here, never written. p_supersedes corrects a prior charge (D11: never mutate a settled fee) instead of editing it in place.';


--
-- Name: apply_category_documents(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_category_documents(p_contact_id uuid, p_categories text[] DEFAULT NULL::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_n    integer;
  v_cats text[];
BEGIN
  SELECT org_id INTO v_org FROM contacts
   WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'contact % not found', p_contact_id;
  END IF;

  SELECT array_agg(DISTINCT upper(btrim(c))) INTO v_cats
    FROM unnest(coalesce(p_categories, '{}')) c WHERE btrim(c) <> '';
  IF v_cats IS NULL THEN
    SELECT coalesce(array_agg(DISTINCT g.group_type), ARRAY[]::text[]) INTO v_cats
      FROM groups g WHERE g.contact_id = p_contact_id AND g.group_type IN ('RIDER','HORSE_OWNER');
  END IF;

  DROP TABLE IF EXISTS _wanted;
  CREATE TEMP TABLE _wanted ON COMMIT DROP AS
    SELECT DISTINCT cdr.template_key
      FROM category_document_requirements cdr
      JOIN unnest(v_cats) AS s(cat)
        -- 1c: one canonical form on BOTH sides (upper, spaces -> underscores)
        ON upper(replace(btrim(cdr.category), ' ', '_')) = upper(replace(btrim(s.cat), ' ', '_'))
     WHERE cdr.org_id = v_org;

  -- 1a: no wanted rows == no category input. Return the current count and change
  -- NOTHING. A re-invite with empty categories must never strip the requirements
  -- an earlier invite established.
  IF NOT EXISTS (SELECT 1 FROM _wanted) THEN
    SELECT count(*) INTO v_n
      FROM contact_required_documents WHERE contact_id = p_contact_id;
    RETURN v_n;
  END IF;

  -- NOSTRIP: THE DELETE THAT USED TO STAND HERE IS GONE.
  --
  --     DELETE FROM contact_required_documents crd
  --      WHERE crd.contact_id = p_contact_id
  --        AND crd.template_key NOT IN (SELECT template_key FROM _wanted);
  --
  -- It destroyed a person's standing legal requirements with no audit row, no
  -- reason, no actor and no undo, from five call sites — one of which is a
  -- trigger that fires when they buy a lesson. Assigning a category ADDS what
  -- that category requires. Taking requirements away is a separate, deliberate,
  -- reasoned act: narrow_contact_required_documents(), which skips and records.

  INSERT INTO contact_required_documents (contact_id, template_key, org_id)
  SELECT p_contact_id, w.template_key, v_org FROM _wanted w
  ON CONFLICT DO NOTHING;

  SELECT count(*) INTO v_n
    FROM contact_required_documents WHERE contact_id = p_contact_id;

  RETURN v_n;
END;
$$;


--
-- Name: FUNCTION apply_category_documents(p_contact_id uuid, p_categories text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_category_documents(p_contact_id uuid, p_categories text[]) IS 'TASK-NOSTRIP: ADDITIVE ONLY. Assigning categories adds what those categories require and removes nothing, from any of its five callers. Deliberate removal is narrow_contact_required_documents(), which skips rather than deletes.';


--
-- Name: apply_contract_composition_spec(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_contract_composition_spec(p_document_id uuid, p_spec jsonb, p_added_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_tkey text;
  v_section text; v_section_new boolean; v_section_key text;
  v_header_key text; v_header_new text; v_pos int;
  v_prev numeric; v_next numeric; v_ord numeric;
  v_keys jsonb := '{}'::jsonb;          -- local id -> minted CUSTOM key
  v_el jsonb; v_ln jsonb;
  v_key text; v_body text; v_cond jsonb; v_cond_txt text;
  v_line_no int := 0; v_created text[] := '{}';
  v_input text; v_req boolean;
  v_line_pos int; v_existing text[]; v_before int; v_i int;
  r record;
BEGIN
  SELECT d.org_id, d.workflow_state, ct.template_key INTO v_org, v_state, v_tkey
    FROM documents d LEFT JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'document is not editable'; END IF;

  v_section     := btrim(coalesce(p_spec->>'section',''));
  v_section_new := coalesce((p_spec->>'section_new')::boolean, false);
  IF v_section = '' THEN RAISE EXCEPTION 'a section is required'; END IF;

  -- ── the section ──────────────────────────────────────────────────────────
  IF v_section_new THEN
    v_section_key := v_section;
    IF EXISTS (SELECT 1 FROM contract_section_defs WHERE template_key = v_tkey AND section_key = v_section_key)
       OR EXISTS (SELECT 1 FROM contract_fields WHERE document_id = p_document_id
                    AND custom_kind = 'section' AND section = v_section_key) THEN
      RAISE EXCEPTION 'a section named % already exists on this document', v_section_key;
    END IF;
    v_pos := coalesce((p_spec->>'section_position')::int, 2147483647);
    SELECT max(ord) INTO v_prev FROM (
      SELECT ord, row_number() OVER (ORDER BY ord) AS rn FROM (
        SELECT (sort_order::numeric * 1000) AS ord FROM contract_section_defs WHERE template_key = v_tkey
        UNION ALL
        SELECT sort_order::numeric FROM contract_fields
         WHERE document_id = p_document_id AND custom_kind = 'section') s
    ) q WHERE q.rn < v_pos;
    SELECT min(ord) INTO v_next FROM (
      SELECT ord, row_number() OVER (ORDER BY ord) AS rn FROM (
        SELECT (sort_order::numeric * 1000) AS ord FROM contract_section_defs WHERE template_key = v_tkey
        UNION ALL
        SELECT sort_order::numeric FROM contract_fields
         WHERE document_id = p_document_id AND custom_kind = 'section') s
    ) q WHERE q.rn >= v_pos;
    v_ord := CASE
      WHEN v_prev IS NULL AND v_next IS NULL THEN 10000
      WHEN v_prev IS NULL THEN v_next - 500
      WHEN v_next IS NULL THEN v_prev + 1000
      ELSE (v_prev + v_next) / 2 END;
    INSERT INTO contract_fields (org_id, document_id, field_key, label, section,
                                 owner_role, sort_order, custom_kind, included, added_by_contact_id)
    VALUES (v_org, p_document_id, next_custom_field_key(p_document_id, v_section_key),
            v_section_key, v_section_key, 'DEAL', round(v_ord)::int, 'section', true, p_added_by);
    v_created := v_created || v_section_key;
  ELSE
    v_section_key := v_section;
    IF NOT EXISTS (SELECT 1 FROM contract_section_defs WHERE template_key = v_tkey AND section_key = v_section_key)
       AND NOT EXISTS (SELECT 1 FROM contract_fields WHERE document_id = p_document_id
                         AND custom_kind = 'section' AND section = v_section_key) THEN
      RAISE EXCEPTION 'unknown section: %', v_section_key;
    END IF;
  END IF;

  -- ── the header ───────────────────────────────────────────────────────────
  v_header_key := nullif(btrim(coalesce(p_spec#>>'{header,clause_key}','')), '');
  v_header_new := nullif(btrim(coalesce(p_spec#>>'{header,text}','')), '');
  IF v_header_key IS NULL AND v_header_new IS NULL THEN
    RAISE EXCEPTION 'a header is required — pick an existing one or name a new one';
  END IF;
  IF v_header_key IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM contract_clause_defs
                    WHERE template_key = v_tkey AND clause_key = v_header_key AND section_key = v_section_key)
       AND NOT EXISTS (SELECT 1 FROM contract_fields
                    WHERE document_id = p_document_id AND field_key = v_header_key
                      AND custom_kind = 'header' AND section = v_section_key) THEN
      RAISE EXCEPTION 'unknown header % in section %', v_header_key, v_section_key;
    END IF;
  ELSE
    v_pos := (p_spec#>>'{header,position}')::int;
    SELECT max(ord) INTO v_prev FROM (
      SELECT ord, row_number() OVER (ORDER BY ord) AS rn FROM (
        SELECT (sort_order::numeric * 1000) AS ord FROM contract_clause_defs
         WHERE template_key = v_tkey AND section_key = v_section_key
           AND heading IS NOT NULL AND heading <> ''
        UNION ALL
        SELECT sort_order::numeric FROM contract_fields
         WHERE document_id = p_document_id AND custom_kind = 'header' AND section = v_section_key) s
    ) q WHERE v_pos IS NULL OR q.rn < v_pos;
    SELECT min(ord) INTO v_next FROM (
      SELECT ord, row_number() OVER (ORDER BY ord) AS rn FROM (
        SELECT (sort_order::numeric * 1000) AS ord FROM contract_clause_defs
         WHERE template_key = v_tkey AND section_key = v_section_key
           AND heading IS NOT NULL AND heading <> ''
        UNION ALL
        SELECT sort_order::numeric FROM contract_fields
         WHERE document_id = p_document_id AND custom_kind = 'header' AND section = v_section_key) s
    ) q WHERE v_pos IS NOT NULL AND q.rn >= v_pos;
    v_ord := CASE
      WHEN v_prev IS NULL AND v_next IS NULL THEN 10000
      WHEN v_prev IS NULL THEN v_next - 500
      WHEN v_next IS NULL THEN v_prev + 1000
      ELSE (v_prev + v_next) / 2 END;
    v_header_key := next_custom_field_key(p_document_id, v_header_new);
    INSERT INTO contract_fields (org_id, document_id, field_key, label, section,
                                 owner_role, sort_order, custom_kind, included, added_by_contact_id)
    VALUES (v_org, p_document_id, v_header_key, v_header_new, v_section_key,
            'DEAL', round(v_ord)::int, 'header', true, p_added_by);
    v_created := v_created || v_header_key;
  END IF;

  -- ── the inline elements (minted first, so lines can reference their keys) ─
  FOR v_el IN SELECT * FROM jsonb_array_elements(coalesce(p_spec->'elements','[]'::jsonb)) LOOP
    v_input := lower(coalesce(v_el->>'kind','text'));
    IF v_input NOT IN ('select','buttons','text') THEN
      RAISE EXCEPTION 'unsupported element kind: %', v_input;
    END IF;
    v_req := coalesce((v_el->>'required')::boolean, false);
    IF v_req AND v_input <> 'text' THEN v_req := false; END IF;
    v_key := next_custom_field_key(p_document_id, coalesce(v_el->>'label', v_input));
    INSERT INTO contract_fields (
      org_id, document_id, field_key, label, section, clause_key, owner_role,
      value_type, required, sort_order, input_kind, format_type, options,
      guidance, custom_kind, included, added_by_contact_id)
    VALUES (
      v_org, p_document_id, v_key, coalesce(nullif(btrim(v_el->>'label'),''), 'Entry'),
      v_section_key, v_header_key, 'DEAL',
      CASE WHEN v_input = 'select' THEN 'select' ELSE 'text' END,
      v_req, 0, v_input, CASE WHEN v_input = 'text' THEN 'text' ELSE v_input END,
      CASE WHEN v_input = 'text' THEN NULL ELSE coalesce(v_el->'options','[]'::jsonb) END,
      nullif(btrim(coalesce(v_el->>'placeholder','')), ''), 'element', true, p_added_by);
    v_keys := v_keys || jsonb_build_object(coalesce(v_el->>'id', v_key), v_key);
    v_created := v_created || v_key;
  END LOOP;

  v_line_pos := (p_spec#>>'{header,line_position}')::int;
  SELECT coalesce(array_agg(field_key ORDER BY sort_order, field_key), '{}'::text[])
    INTO v_existing
    FROM contract_fields
   WHERE document_id = p_document_id AND custom_kind = 'line' AND clause_key = v_header_key;

  v_before := CASE
    WHEN v_line_pos IS NULL OR v_line_pos > coalesce(array_length(v_existing,1),0)
      THEN coalesce(array_length(v_existing,1),0)
    ELSE greatest(v_line_pos - 1, 0) END;

  FOR v_i IN 1..v_before LOOP
    v_line_no := v_line_no + 10;
    UPDATE contract_fields SET sort_order = v_line_no
     WHERE document_id = p_document_id AND field_key = v_existing[v_i];
  END LOOP;

  FOR v_ln IN SELECT * FROM jsonb_array_elements(coalesce(p_spec->'lines','[]'::jsonb)) LOOP
    v_line_no := v_line_no + 10;
    v_body := coalesce(v_ln->>'body','');
    v_cond := v_ln->'conditional_on';
    IF v_cond = 'null'::jsonb THEN v_cond := NULL; END IF;
    v_cond_txt := v_cond::text;
    FOR r IN SELECT key AS lid, value AS realkey FROM jsonb_each_text(v_keys) LOOP
      v_body := replace(v_body, '{{CUSTOM.@' || r.lid || '}}', '{{' || r.realkey || '}}');
      IF v_cond_txt IS NOT NULL THEN
        v_cond_txt := replace(v_cond_txt, '"@' || r.lid || '"', '"' || r.realkey || '"');
      END IF;
    END LOOP;
    IF v_body ~ '\{\{CUSTOM\.@' THEN
      RAISE EXCEPTION 'line references an element id that was not supplied: %', v_body;
    END IF;
    v_cond := CASE WHEN v_cond_txt IS NULL THEN NULL ELSE v_cond_txt::jsonb END;
    v_key := next_custom_field_key(p_document_id, 'LINE');
    INSERT INTO contract_fields (
      org_id, document_id, field_key, label, section, clause_key, owner_role,
      sort_order, custom_kind, body, conditional_on, guidance, included, added_by_contact_id)
    VALUES (
      v_org, p_document_id, v_key, NULL, v_section_key, v_header_key, 'DEAL',
      v_line_no, 'line', v_body, v_cond,
      nullif(btrim(coalesce(v_ln->>'caption','')), ''), true, p_added_by);
    v_created := v_created || v_key;
  END LOOP;

  FOR v_i IN v_before + 1 .. coalesce(array_length(v_existing,1),0) LOOP
    v_line_no := v_line_no + 10;
    UPDATE contract_fields SET sort_order = v_line_no
     WHERE document_id = p_document_id AND field_key = v_existing[v_i];
  END LOOP;

  PERFORM remerge_contract_from_clauses(p_document_id);
  RETURN jsonb_build_object('section', v_section_key, 'header_key', v_header_key,
                            'element_keys', v_keys, 'created', to_jsonb(v_created));
END;
$$;


--
-- Name: apply_contract_execution_effects(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_contract_execution_effects() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key      text;
  v_kind     text;
  v_fields   jsonb := '{}'::jsonb;
  v_horse    uuid;
  v_chip     text;
  v_lessor   uuid;  -- lease: owner side  | sale: seller
  v_lessee   uuid;  -- lease: lessee      | sale: buyer
  v_start    date;
  v_end      date;
  v_hname    text;
  r          record;
BEGIN
  IF NOT (NEW.workflow_state = 'executed' AND OLD.workflow_state IS DISTINCT FROM 'executed') THEN
    RETURN NEW;
  END IF;

  SELECT template_key, contract_kind INTO v_key, v_kind
    FROM contract_templates WHERE id = NEW.template_id;
  -- coalesce is load-bearing: contract_kind is NULL for every plain template
  -- (releases, policies, medical auth), and NULL IN (...) is NULL.
  IF NOT (is_horse_lease_template(v_key)
          OR v_key = 'HORSE_PURCHASE_SALE'
          OR coalesce(v_kind, '') IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE')) THEN
    RETURN NEW;
  END IF;

  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val
             FROM contract_fields WHERE document_id = NEW.id LOOP
    v_fields := v_fields || jsonb_build_object(r.field_key, r.val);
  END LOOP;

  -- accompanied bill of sale: the sale agreement drives the transfer; this
  -- document records it and has no exec effect of its own
  IF v_kind = 'HORSE_BILL_OF_SALE'
     AND coalesce(v_fields ->> 'TXN.BOS_HAS_SALE_AGREEMENT', '') = 'YES' THEN
    RETURN NEW;
  END IF;

  -- parties from the engagement
  SELECT contact_id INTO v_lessor FROM document_parties
   WHERE document_id = NEW.id AND party_role IN ('LESSOR','SELLER') LIMIT 1;
  SELECT contact_id INTO v_lessee FROM document_parties
   WHERE document_id = NEW.id AND party_role IN ('LESSEE','BUYER') LIMIT 1;

  -- find the record: engagement's horse, else microchip match, else CREATE from
  -- the contract's horse fields (the contract births the record)
  v_horse := NEW.horse_id;
  v_chip := nullif(regexp_replace(coalesce(v_fields ->> 'HORSE.MICROCHIP', ''), '\s', '', 'g'), '');
  IF v_horse IS NULL AND v_chip IS NOT NULL THEN
    SELECT id INTO v_horse FROM horses
     WHERE org_id = NEW.org_id AND deleted_at IS NULL
       AND regexp_replace(coalesce(microchip_id, ''), '\s', '', 'g') = v_chip
     LIMIT 1;
  END IF;
  IF v_horse IS NULL THEN
    -- The horse is required before a sale or lease is locked or sent, so this is
    -- unreachable on a real path; a contract never creates a record.
    RAISE EXCEPTION 'cannot apply execution effects: no horse is attached to document %', NEW.id;
  END IF;

  IF is_horse_lease_template(v_key) THEN
    v_start := nullif(v_fields ->> 'TXN.LEASE_START', '')::date;
    v_end   := nullif(v_fields ->> 'TXN.LEASE_END', '')::date;
    UPDATE horses
       SET lessee_contact_id = v_lessee,
           lease_start = v_start,
           lease_end   = v_end,
           current_owner_contact_id = coalesce(current_owner_contact_id, v_lessor),
           updated_at = now()
     WHERE id = v_horse;
    INSERT INTO horse_relationships (org_id, horse_id, relationship, party_contact_id,
                                     term_start, term_end, source_document_id,
                                     created_by_contact_id)
    VALUES (NEW.org_id, v_horse, 'LESSEE', v_lessee, v_start, v_end, NEW.id, v_lessee);
    -- ownership does not move: the LESSOR is still the owner of record. The
    -- LESSOR's horse documents are generated at SEND as part of the contract role
    -- bundle (disc_51), so execution generates nothing for a lease.
  ELSE  -- sale kinds: ownership transfers seller → buyer
    UPDATE horse_relationships
       SET active = false, ended_at = now()
     WHERE horse_id = v_horse AND relationship = 'OWNER' AND active;
    UPDATE horses
       SET current_owner_contact_id = v_lessee,   -- the buyer
           lessee_contact_id = NULL, lease_start = NULL, lease_end = NULL,
           updated_at = now()
     WHERE id = v_horse;
    INSERT INTO horse_relationships (org_id, horse_id, relationship, party_contact_id,
                                     source_document_id, created_by_contact_id)
    VALUES (NEW.org_id, v_horse, 'OWNER', v_lessee, NEW.id, v_lessee);

    -- DEALAUTO 2026-08-22 (owner): "the seller doesnt retain authority to
    -- release liability or grant vet auth. [the buyer] inherits that upon
    -- signature on the BOS." AFTER the transfer above, so the generator's
    -- own "address it to the owner of record" rule resolves to the buyer.
    -- Isolated: the paperwork that follows a sale may not undo the sale.
    BEGIN
      PERFORM ensure_horse_documents(v_horse, NEW.contract_id, true);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'apply_contract_execution_effects: horse documents not generated for the buyer on horse %: %',
        v_horse, SQLERRM;
    END;

    -- conservative default: home location does NOT follow the transfer
    -- automatically — staff review it
    SELECT coalesce(nickname, registered_name, 'the horse') INTO v_hname
      FROM horses WHERE id = v_horse;
    PERFORM notify_staff(NEW.org_id, 'horse_ownership_transferred',
      'Ownership transferred — review home location for ' || v_hname,
      '/app/ops/horses');
  END IF;



  RETURN NEW;
END;
$$;


--
-- Name: apply_document_supersession(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_document_supersession() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  -- The just-executed document supersedes every prior executed document of
  -- the SAME template family (any version) for the SAME person, scoped to
  -- the SAME horse. A blank-horse prior (no horse_id) is superseded by any
  -- execution of the family; a horse-bound prior is only superseded by a
  -- replacement for that same horse.
  FOR r IN
    SELECT d.id FROM documents d
    JOIN contract_templates ct_old ON ct_old.id = d.template_id
    JOIN contract_templates ct_new ON ct_new.id = NEW.template_id
   WHERE d.contact_id = NEW.contact_id
     AND d.id <> NEW.id
     AND d.deleted_at IS NULL
     AND d.status = 'EXECUTED'
     AND coalesce(d.current_status, '') <> 'superseded'
     AND ct_old.template_key = ct_new.template_key
     AND (d.horse_id IS NULL OR d.horse_id = NEW.horse_id)
  LOOP
    UPDATE documents SET current_status = 'superseded' WHERE id = r.id;
    PERFORM log_status_event('document', r.id, 'superseded',
      'Superseded by document ' || NEW.id::text, NEW.org_id);
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: apply_field_formats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_field_formats(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pairs text[][] := ARRAY[
    ARRAY['TXN.BOARDING_RESPONSIBILITY','TXN.BOARD_COST'],
    ARRAY['TXN.FARRIER_RESPONSIBILITY','TXN.FARRIER_COST'],
    ARRAY['TXN.ROUTINE_VET_RESPONSIBILITY','TXN.ROUTINE_VET_COST'],
    ARRAY['TXN.EMERGENCY_VET_RESPONSIBILITY','TXN.NON_ROUTINE_VET_COST'],
    ARRAY['TXN.SUPPLEMENTS_RESPONSIBILITY','TXN.SUPPLEMENTS_COST']
  ];
  party_fields text[] := ARRAY[
    'TXN.CARE_RESPONSIBILITY','TXN.EXERCISE_RESPONSIBILITY','TXN.CLIPPING_RESPONSIBILITY',
    'TXN.OTHER_CARE_COST','TXN.OTHER_EXPENSES_COST',
    'TXN.MORTALITY_INSURANCE_PARTY','TXN.MAJOR_MEDICAL_INSURANCE_PARTY','TXN.LOSS_OF_USE_INSURANCE_PARTY',
    'TXN.COMPETITION_EXPENSES','TXN.COMPETITION_WINNINGS'
  ];
  button_fields text[] := ARRAY[
    'TXN.PERMITTED_ACTIVITIES','TXN.PROHIBITED_ACTIVITIES','TXN.USE_RESTRICTIONS','TXN.AUTHORIZED_USERS'
  ];
  select_fields text[] := ARRAY[
    'HORSE.SEX','HORSE.COLOR','HORSE.BREED','TXN.LEASE_TERM','TXN.PAYMENT_SCHEDULE'
  ];
  p text[];
  bf text;
  sf text;
BEGIN
  -- correct the mangled labels on this document's fields (idempotent)
  UPDATE contract_fields SET label='Lessons/Day — Advanced'     WHERE document_id=p_document_id AND field_key='TXN.LESSONS_ADVANCED';
  UPDATE contract_fields SET label='Lessons/Day — Beginner'     WHERE document_id=p_document_id AND field_key='TXN.LESSONS_BEGINNER';
  UPDATE contract_fields SET label='Lessons/Day — Intermediate' WHERE document_id=p_document_id AND field_key='TXN.LESSONS_INTERMEDIATE';
  UPDATE contract_fields SET label='Payment Options (one per line: amount — description)' WHERE document_id=p_document_id AND field_key='TXN.PAYMENT_OPTIONS';

  -- base format_type from input_kind/value_type
  UPDATE contract_fields SET format_type = CASE
      WHEN input_kind = 'responsibility' THEN 'party'
      WHEN input_kind = 'contact'        THEN 'person'
      WHEN input_kind IN ('week_grid','select','buttons','currency','date','percent','longtext') THEN input_kind
      ELSE 'text' END
    WHERE document_id = p_document_id AND coalesce(format_type,'') = '';

  -- semantic upgrades so the data is reusable
  UPDATE contract_fields SET format_type='email'       WHERE document_id=p_document_id AND field_key LIKE '%.EMAIL';
  UPDATE contract_fields SET format_type='phone'       WHERE document_id=p_document_id AND (field_key LIKE '%.PHONE' OR field_key LIKE '%\_PHONE');
  UPDATE contract_fields SET format_type='person_name' WHERE document_id=p_document_id AND (field_key LIKE '%.FULL_NAME' OR field_key LIKE '%.PRINTED_NAME' OR field_key LIKE '%.VET_NAME' OR field_key LIKE '%.FARRIER_NAME');
  UPDATE contract_fields SET format_type='address'     WHERE document_id=p_document_id AND (field_key LIKE '%.ADDRESS' OR field_key='HORSE.VET_ADDRESS');
  UPDATE contract_fields SET format_type='currency'    WHERE document_id=p_document_id AND field_key LIKE '%FAIR_MARKET_VALUE';
  UPDATE contract_fields SET format_type='location'    WHERE document_id=p_document_id AND field_key IN ('HORSE.CURRENT_LOCATION','HORSE.HOME_LOCATION');
  UPDATE contract_fields SET format_type='number'      WHERE document_id=p_document_id AND field_key LIKE 'TXN.LESSONS_%' AND field_key <> 'TXN.LESSONS_COST';

  -- standalone responsibility/cost fields → party picker (Lessor/Lessee/Shared %)
  UPDATE contract_fields SET format_type='party', input_kind='responsibility'
   WHERE document_id=p_document_id AND field_key = ANY(party_fields);

  -- multi-select activity/rules fields → buttons with preset options
  FOREACH bf IN ARRAY button_fields LOOP
    UPDATE contract_fields
       SET format_type='buttons', input_kind='buttons', value_type='select',
           options = _lease_button_options(bf)
     WHERE document_id=p_document_id AND field_key=bf;
  END LOOP;

  -- single-choice fields with natural option sets → dropdown (SelectWithOther
  -- gives a free-text escape). Options-first, open text still available.
  FOREACH sf IN ARRAY select_fields LOOP
    UPDATE contract_fields
       SET format_type='select', input_kind='select', value_type='select',
           options = _lease_select_options(sf)
     WHERE document_id=p_document_id AND field_key=sf;
  END LOOP;

  -- Days Used → week-grid day picker
  UPDATE contract_fields SET format_type='week_grid', input_kind='week_grid'
   WHERE document_id=p_document_id AND field_key='TXN.DAYS_USED';

  -- link the manage↔cost pairs
  FOREACH p SLICE 1 IN ARRAY pairs LOOP
    UPDATE contract_fields SET format_type='pair', input_kind='pair', pair_cost_key=p[2]
      WHERE document_id=p_document_id AND field_key=p[1];
    UPDATE contract_fields SET pair_manage_key=p[1]
      WHERE document_id=p_document_id AND field_key=p[2];
  END LOOP;

  -- guidance from the registry where missing
  UPDATE contract_fields cf SET guidance = f.guidance
    FROM contract_formats f
   WHERE cf.document_id=p_document_id AND cf.format_type=f.format_type
     AND coalesce(cf.guidance,'')='' AND coalesce(f.guidance,'')<>'';
END;
$$;


--
-- Name: apply_offering_documents(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_offering_documents(p_contact_id uuid, p_disposition text DEFAULT 'AT_LOGIN'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_n integer;
BEGIN
  IF p_disposition NOT IN ('AT_LOGIN','WITH_CONTRACT','WHEN_READY') THEN
    RAISE EXCEPTION 'unknown disposition %', p_disposition;
  END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact % not found', p_contact_id; END IF;

  INSERT INTO contact_required_documents (contact_id, template_key, org_id, disposition)
  SELECT DISTINCT p_contact_id, r.template_key, v_org, p_disposition
    FROM purchases p
    JOIN purchase_items pi ON pi.purchase_id = p.id AND pi.voided_at IS NULL
    JOIN offerings o       ON o.id = pi.offering_id
    JOIN service_type_document_requirements r
      ON r.org_id = v_org AND r.service_type = o.service_type AND r.active
   WHERE p.buyer_contact_id = p_contact_id
     -- ⚠️ AND NOT 'draft'. A cart is not an order. This is the same correction as
     -- the trigger move: nothing is owed until staff open it.
     AND coalesce(p.status, '') NOT IN ('void', 'draft')
     AND p.deleted_at IS NULL
     AND coalesce(o.config_kind, '') <> 'inquire'
  ON CONFLICT (contact_id, template_key) DO NOTHING;

  SELECT count(*) INTO v_n FROM contact_required_documents WHERE contact_id = p_contact_id;
  RETURN v_n;
END;
$$;


--
-- Name: apply_sign_path_documents(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_sign_path_documents(p_contact_id uuid, p_path text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_n integer;
BEGIN
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact % not found', p_contact_id; END IF;
  INSERT INTO contact_required_documents (contact_id, template_key, org_id)
  SELECT p_contact_id, r.template_key, v_org
    FROM sign_path_document_requirements r
   WHERE r.org_id = v_org AND r.active AND r.path = lower(btrim(p_path))
  ON CONFLICT DO NOTHING;
  SELECT count(*) INTO v_n FROM contact_required_documents WHERE contact_id = p_contact_id;
  RETURN v_n;
END;
$$;


--
-- Name: appointment_notify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appointment_notify(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_b      bookings%ROWTYPE;
  v_client uuid;
  v_user   uuid;
  v_when   text;
  v_title  text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'appointment not found in this org'; END IF;

  v_client := v_b.client_id;

  -- tied only to a horse → resolve the horse's owner, and stamp it on the
  -- booking so the appointment shows on that owner's calendar.
  IF v_client IS NULL AND v_b.horse_id IS NOT NULL THEN
    SELECT c.id INTO v_client
      FROM horses h
      JOIN clients c ON c.contact_id = h.current_owner_contact_id AND c.deleted_at IS NULL
      WHERE h.id = v_b.horse_id AND h.org_id = v_org;
    IF v_client IS NOT NULL THEN
      UPDATE bookings SET client_id = v_client, updated_at = now() WHERE id = p_booking_id;
    END IF;
  END IF;

  IF v_client IS NULL THEN
    RETURN jsonb_build_object('notified', false, 'reason', 'no client linked');
  END IF;

  SELECT p.user_id INTO v_user
    FROM clients c JOIN profiles p ON p.contact_id = c.contact_id
    WHERE c.id = v_client;
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('notified', false, 'reason', 'client has no account', 'client_id', v_client);
  END IF;

  v_title := coalesce(nullif(btrim(v_b.notes), ''), 'An appointment');
  v_when  := to_char(v_b.starts_at, 'FMDay, FMMon FMDD, HH12:MI AM');
  PERFORM notify_user(v_user, 'appointment_scheduled',
    v_title || ' — ' || v_when,
    'This appointment is on your calendar.',
    '/app/calendar');

  RETURN jsonb_build_object('notified', true, 'client_id', v_client);
END;
$$;


--
-- Name: approve_contract_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_contract_review(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me       uuid := current_contact_id();
  v_doc      documents%ROWTYPE;
  v_my_role  text;
  v_my_name  text;
  v_blockers jsonb;
  v_pending  text[];
  v_locked   boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  -- staff/author path is Lock for signing; review approval is the PARTY act.
  IF coalesce(has_staff_access() AND v_doc.org_id = current_org(), false) THEN
    RAISE EXCEPTION 'staff do not approve as reviewers — use Lock for signing';
  END IF;
  IF v_doc.workflow_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'document is % — review approval applies before locking', v_doc.workflow_state;
  END IF;

  SELECT dp.party_role INTO v_my_role
    FROM document_parties dp
   WHERE dp.document_id = p_document_id AND dp.contact_id = v_me AND dp.is_signer
   ORDER BY dp.party_role LIMIT 1;
  IF v_my_role IS NULL THEN
    RAISE EXCEPTION 'only a signing party may approve this document';
  END IF;

  SELECT coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email, 'party')
    INTO v_my_name FROM contacts c WHERE c.id = v_me;

  -- the approval is RECORDED regardless of blockers
  INSERT INTO status_events (org_id, entity_type, entity_id, status, detail, actor_user_id)
  VALUES (v_doc.org_id, 'document', p_document_id, 'review_approved',
          'Reviewed and accepted by ' || initcap(lower(v_my_role)) || ' — ' || v_my_name,
          auth.uid());

  v_blockers := contract_lock_blockers(p_document_id);

  -- multi-party: EVERY non-staff signing party must have approved before locking
  SELECT array_agg(initcap(lower(x.party_role)) ORDER BY x.party_role) INTO v_pending
  FROM (
    SELECT dp.party_role, dp.contact_id
      FROM document_parties dp
      JOIN contacts c ON c.id = dp.contact_id
     WHERE dp.document_id = p_document_id AND dp.is_signer AND dp.contact_id IS NOT NULL
       AND dp.party_role NOT IN ('FHE','COMPANY')
       AND NOT coalesce(c.is_company, false)
       AND NOT EXISTS (SELECT 1 FROM profiles pr
                        WHERE pr.contact_id = dp.contact_id AND pr.is_admin)
  ) x
  WHERE NOT EXISTS (
    SELECT 1 FROM status_events se
      JOIN profiles pr ON pr.user_id = se.actor_user_id
     WHERE se.entity_type = 'document' AND se.entity_id = p_document_id
       AND se.status = 'review_approved' AND pr.contact_id = x.contact_id);
  IF v_pending IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'awaiting_approvals',
      'message', 'Awaiting review approval from: ' || array_to_string(v_pending, ', ')));
  END IF;

  IF jsonb_array_length(v_blockers) = 0 THEN
    PERFORM advance_document_workflow(p_document_id, 'locked');
    v_locked := true;
  END IF;

  RETURN jsonb_build_object('approved', true, 'locked', v_locked, 'blockers', v_blockers);
END;
$$;


--
-- Name: approve_contract_termination(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_contract_termination(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_title text; v_me uuid := current_contact_id(); v_requester uuid; r record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, title, termination_requested_by INTO v_org, v_title, v_requester
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL
      AND termination_requested_at IS NOT NULL AND workflow_state = 'executed';
  IF v_org IS NULL THEN RAISE EXCEPTION 'no pending termination request'; END IF;
  IF NOT caller_is_document_party_or_staff(p_document_id) THEN RAISE EXCEPTION 'not authorized'; END IF;

  UPDATE documents SET workflow_state = 'terminated', terminated_at = now(), terminated_by = v_me,
         updated_at = now()
   WHERE id = p_document_id;

  -- ITEM 5d: the pending request is answered — resolve it rather than leaving
  -- it stacked beside the outcome. Kind-scoped so other contract alerts on the
  -- same link survive.
  PERFORM resolve_notifications_for_link(
    '/app/contracts/' || p_document_id::text, auth.uid(), 'contract_termination_requested');

  FOR r IN
    SELECT DISTINCT pr.user_id FROM document_parties dp
      JOIN profiles pr ON pr.contact_id = dp.contact_id
     WHERE dp.document_id = p_document_id AND pr.user_id IS NOT NULL
  LOOP
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    VALUES (v_org, r.user_id, 'contract_terminated',
            coalesce(v_title,'A contract') || ' was terminated',
            'The contract has been terminated by mutual agreement and is kept on file as a record.',
            '/app/contracts/' || p_document_id::text);
  END LOOP;
  PERFORM notify_staff(v_org, 'contract_terminated',
    coalesce(v_title,'A contract') || ' was terminated', '/app/ops/documents');
END;
$$;


--
-- Name: archive_contact(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_contact(p_contact_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF is_protected_contact(p_contact_id) THEN
    RAISE EXCEPTION 'protected identity — refusing to archive';
  END IF;

  UPDATE contacts
     SET deleted_at     = now(),
         deleted_by     = auth.uid(),
         deleted_reason = nullif(btrim(coalesce(p_reason, '')), '')
   WHERE id = p_contact_id AND org_id = current_org() AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'contact not found in this org, or already archived';
  END IF;
END;
$$;


--
-- Name: FUNCTION archive_contact(p_contact_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.archive_contact(p_contact_id uuid, p_reason text) IS 'D11/D32: stop seeing the account in the main views. Sets deleted_at/deleted_by/deleted_reason on ONE contacts row and nothing else — no document, signature, contract, client, profile or file row is read or written. Reverse it with unarchive_contact. Refuses D1 protected identities.';


--
-- Name: archive_contract(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_contract(p_document_id uuid, p_archive boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_me uuid := current_contact_id();
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN RAISE EXCEPTION 'staff access required'; END IF;
  UPDATE documents
     SET archived_at = CASE WHEN p_archive THEN now() ELSE NULL END,
         archived_by = CASE WHEN p_archive THEN v_me ELSE NULL END,
         updated_at = now()
   WHERE id = p_document_id;
END;
$$;


--
-- Name: archived_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archived_contacts() RETURNS TABLE(contact_id uuid, display_code text, first_name text, last_name text, email text, phone text, contact_type text, is_company boolean, archived_at timestamp with time zone, archived_by uuid, archived_by_name text, reason text, had_login boolean, login_suspended boolean, document_count bigint, executed_document_count bigint, signature_count bigint, party_document_count bigint, order_count bigint, horse_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.display_code, c.first_name, c.last_name,
         c.email, c.phone, c.contact_type, coalesce(c.is_company, false),
         c.deleted_at, c.deleted_by,
         (SELECT nullif(btrim(coalesce(bp.first_name,'') || ' ' || coalesce(bp.last_name,'')), '')
            FROM profiles bp WHERE bp.user_id = c.deleted_by),
         c.deleted_reason,
         EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id),
         coalesce((SELECT bool_or(p.is_suspended) FROM profiles p WHERE p.contact_id = c.id), false),
         -- the footprint. These are counts of what SURVIVED the archive, which
         -- is the whole claim the feature makes; they are deliberately NOT
         -- filtered by contacts.deleted_at anywhere.
         (SELECT count(*) FROM documents d WHERE d.contact_id = c.id AND d.deleted_at IS NULL),
         (SELECT count(*) FROM documents d WHERE d.contact_id = c.id AND d.deleted_at IS NULL
                                             AND d.status = 'EXECUTED'),
         (SELECT count(*) FROM signatures s WHERE s.signer_contact_id = c.id),
         (SELECT count(DISTINCT dp.document_id) FROM document_parties dp WHERE dp.contact_id = c.id),
         (SELECT count(*) FROM purchases pu WHERE pu.buyer_contact_id = c.id AND pu.deleted_at IS NULL),
         (SELECT count(*) FROM horses h WHERE h.deleted_at IS NULL
            AND (h.current_owner_contact_id = c.id OR h.lessee_contact_id = c.id))
    FROM contacts c
   WHERE c.org_id = current_org()
     AND c.deleted_at IS NOT NULL
     AND coalesce(has_staff_access() AND is_admin(), false)
   ORDER BY c.deleted_at DESC
$$;


--
-- Name: FUNCTION archived_contacts(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.archived_contacts() IS 'The deleted-accounts view (D11/D32, owner 2026-08-22). Who was archived, when, by whom and why — plus counts of the documents, signatures, orders and horses that are STILL THERE, because archiving destroys nothing. The only listing in the codebase that returns deleted_at IS NOT NULL rows.';


--
-- Name: assert_horse_care_eligible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_horse_care_eligible(p_contact_id uuid, p_horse_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org        uuid;
  v_release    documents%ROWTYPE;
  v_vet        documents%ROWTYPE;
  v_generated  boolean := false;
  v_parties    jsonb;
  v_missing    text[] := ARRAY[]::text[];
BEGIN
  IF p_horse_id IS NULL THEN
    RAISE EXCEPTION 'a horse is required for a care booking';
  END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown contact'; END IF;
  IF NOT EXISTS (SELECT 1 FROM horses WHERE id = p_horse_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'unknown horse: %', p_horse_id;
  END IF;

  -- Look for THIS horse's care docs owned by THIS contact.
  SELECT d.* INTO v_release FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
   WHERE d.contact_id = p_contact_id AND d.horse_id = p_horse_id
     AND d.deleted_at IS NULL AND t.template_key = 'RELEASE_HORSE_CARE'
   ORDER BY d.created_at DESC LIMIT 1;

  SELECT d.* INTO v_vet FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
   WHERE d.contact_id = p_contact_id AND d.horse_id = p_horse_id
     AND d.deleted_at IS NULL AND t.template_key = 'HORSE_EMERGENCY_VET'
   ORDER BY d.created_at DESC LIMIT 1;

  -- First care booking for this horse: generate whichever of the two is absent.
  -- generate_document reads e->>'role' for document_parties.party_role, which is
  -- constrained; horse-care releases use CLIENT as the signing party.
  v_parties := jsonb_build_array(jsonb_build_object(
    'contact_id', p_contact_id, 'role', 'CLIENT',
    'is_signer', true, 'signer_order', 1));

  IF v_release.id IS NULL THEN
    PERFORM generate_document(p_contact_id, 'RELEASE_HORSE_CARE', NULL::uuid, p_horse_id, v_parties, 'horse');
    v_generated := true;
  END IF;
  IF v_vet.id IS NULL THEN
    PERFORM generate_document(p_contact_id, 'HORSE_EMERGENCY_VET', NULL::uuid, p_horse_id, v_parties, 'horse');
    v_generated := true;
  END IF;

  IF v_generated THEN
    -- re-read after generation
    SELECT d.* INTO v_release FROM documents d JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = p_contact_id AND d.horse_id = p_horse_id AND d.deleted_at IS NULL
       AND t.template_key = 'RELEASE_HORSE_CARE' ORDER BY d.created_at DESC LIMIT 1;
    SELECT d.* INTO v_vet FROM documents d JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = p_contact_id AND d.horse_id = p_horse_id AND d.deleted_at IS NULL
       AND t.template_key = 'HORSE_EMERGENCY_VET' ORDER BY d.created_at DESC LIMIT 1;
  END IF;

  IF coalesce(v_release.status, '') <> 'EXECUTED' THEN v_missing := array_append(v_missing, 'RELEASE_HORSE_CARE'); END IF;
  IF coalesce(v_vet.status, '') <> 'EXECUTED' THEN v_missing := array_append(v_missing, 'HORSE_EMERGENCY_VET'); END IF;

  RETURN jsonb_build_object(
    'eligible', (array_length(v_missing, 1) IS NULL),
    'generated', v_generated,
    'missing', to_jsonb(v_missing),
    'release_document_id', v_release.id,
    'vet_document_id', v_vet.id);
END;
$$;


--
-- Name: assert_not_signature_locked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_not_signature_locked(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_who text;
BEGIN
  SELECT string_agg(coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email, s.party_role), ', ')
    INTO v_who
    FROM signatures s LEFT JOIN contacts c ON c.id = s.signer_contact_id
   WHERE s.document_id = p_document_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL;

  IF v_who IS NOT NULL THEN
    RAISE EXCEPTION 'this document is signed by % and is read-only — ask them to remove their signature before making changes', v_who;
  END IF;
END;
$$;


--
-- Name: assert_template_is_satisfiable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_template_is_satisfiable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM contract_templates ct
                  WHERE ct.template_key = NEW.template_key
                    AND ct.active AND ct.deleted_at IS NULL) THEN
    RAISE EXCEPTION
      'no active template "%" — a requirement pointing at a retired template can '
      'never be signed and never appears on any surface', NEW.template_key;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assign_display_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_display_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.display_code IS NULL THEN
    NEW.display_code := TG_ARGV[0] || lpad(nextval(TG_ARGV[1]::regclass)::text, 6, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assign_display_code_yearly(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_display_code_yearly() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.display_code IS NULL THEN
    NEW.display_code := TG_ARGV[0]
      || to_char(now(), 'YYYY') || '-'
      || lpad(nextval(TG_ARGV[1]::regclass)::text, 6, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assign_horse_section(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_horse_section(p_document_id uuid, p_role text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_n integer;
BEGIN
  SELECT org_id, workflow_state INTO v_org, v_state
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF v_state NOT IN ('editable','editing') THEN
    RAISE EXCEPTION 'document is locked';
  END IF;
  IF EXISTS (SELECT 1 FROM signatures s WHERE s.document_id = p_document_id AND s.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'signatures exist — section ownership is frozen';
  END IF;
  UPDATE contract_fields SET owner_role = upper(p_role)
   WHERE document_id = p_document_id AND field_key LIKE 'HORSE.%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: assign_random_document_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_random_document_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  candidate text;
  tries int := 0;
BEGIN
  IF NEW.display_code IS NOT NULL THEN RETURN NEW; END IF;
  LOOP
    candidate := 'DOC-';
    FOR i IN 1..10 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM documents WHERE display_code = candidate);
    tries := tries + 1;
    IF tries > 5 THEN RAISE EXCEPTION 'could not allocate a unique document code'; END IF;
  END LOOP;
  NEW.display_code := candidate;
  RETURN NEW;
END;
$$;


--
-- Name: atn_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atn_history() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); v_uid uuid := auth.uid(); v_out jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RETURN '[]'::jsonb; END IF;
  SELECT coalesce(jsonb_agg(row_to_json(h) ORDER BY h.at DESC), '[]'::jsonb) INTO v_out
  FROM (
    SELECT 'task' AS kind, t.id, t.title,
           coalesce(t.completed_at, t.cancelled_at, t.deleted_at) AS at,
           t.status AS detail
      FROM tasks t
     WHERE t.org_id = v_org
       AND (t.status IN ('complete','cancelled') OR t.deleted_at IS NOT NULL)
    UNION ALL
    SELECT 'alert', a.id, a.title, a.dismissed_at, a.severity
      FROM alerts a WHERE a.org_id = v_org AND a.user_id = v_uid AND a.dismissed_at IS NOT NULL
    UNION ALL
    SELECT 'notification', n.id, n.title, coalesce(n.dismissed_at, n.seen_at), n.category
      FROM notifications n WHERE n.user_id = v_uid AND (n.dismissed_at IS NOT NULL OR n.seen_at IS NOT NULL)
  ) h;
  RETURN v_out;
END
$$;


--
-- Name: attach_booking_horse(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_booking_horse(p_booking_id uuid, p_horse_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client  uuid := current_client_id();
  v_contact uuid := current_contact_id();
  v_org     uuid := current_org();
  v_b       bookings%ROWTYPE;
  v_mine    boolean;
  v_gate    jsonb;
BEGIN
  IF v_client IS NULL THEN RAISE EXCEPTION 'no member profile'; END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;
  IF v_b.client_id IS DISTINCT FROM v_client THEN RAISE EXCEPTION 'not your booking'; END IF;
  IF v_b.kind NOT IN ('lesson','care') THEN RAISE EXCEPTION 'that booking does not take a horse'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM horses h WHERE h.id = p_horse_id AND h.org_id = v_org AND h.deleted_at IS NULL
      AND caller_may_use_horse(v_contact, h.id)
  ) INTO v_mine;
  IF NOT v_mine THEN RAISE EXCEPTION 'that horse is not yours'; END IF;

  -- care bookings gate on the two per-horse releases (generating them on first).
  IF v_b.kind = 'care' THEN
    v_gate := assert_horse_care_eligible(v_contact, p_horse_id);
    IF NOT coalesce((v_gate->>'eligible')::boolean, false) THEN
      RAISE EXCEPTION 'HORSE_CARE_DOCS_REQUIRED: %', v_gate->>'missing'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  UPDATE bookings SET horse_id = p_horse_id, updated_at = now() WHERE id = p_booking_id;

  PERFORM notify_staff(v_org, 'horse_intake_completed',
    'A client added their horse to their session', '/app/calendar');

  RETURN jsonb_build_object('ok', true, 'horse_id', p_horse_id);
END;
$$;


--
-- Name: attach_first_purchase_policies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_first_purchase_policies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_org     uuid;
BEGIN
  SELECT p.buyer_contact_id, p.org_id INTO v_contact, v_org
    FROM purchases p WHERE p.id = NEW.purchase_id;
  IF v_contact IS NULL OR v_org IS NULL THEN RETURN NEW; END IF;

  -- service line? (config_kind present and not a pure inquiry row)
  IF NOT EXISTS (
    SELECT 1 FROM offerings o
     WHERE o.id = NEW.offering_id
       AND o.config_kind IS NOT NULL
       AND o.config_kind <> 'inquire'
  ) THEN
    RETURN NEW;
  END IF;

  -- already executed (and current)? nothing to attach
  IF EXISTS (
    SELECT 1 FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
     WHERE d.contact_id = v_contact AND d.deleted_at IS NULL
       AND d.status = 'EXECUTED' AND coalesce(d.current_status,'') <> 'superseded'
       AND ct.template_key = 'COMPANY_POLICIES'
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO contact_required_documents (contact_id, template_key, org_id)
  VALUES (v_contact, 'COMPANY_POLICIES', v_org)
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION attach_first_purchase_policies(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.attach_first_purchase_policies() IS 'RETIRED 2026-08-24 (OFFERINGDOCS): fired on purchase_items INSERT and assigned a hardcoded COMPANY_POLICIES to a DRAFT cart, before any staff approval. Superseded by service_type_document_requirements + trg_documents_when_order_opens. Function retained, trigger removed.';


--
-- Name: attach_horse_to_document(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_horse_to_document(p_document_id uuid, p_horse_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me      uuid := current_contact_id();
  v_staff   boolean := has_staff_access();
  v_org     uuid;
  v_state   text;
  v_horse   horses%ROWTYPE;
  r         record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable', 'editing', 'in_review') THEN
    RAISE EXCEPTION 'this contract can no longer be edited';
  END IF;

  IF NOT coalesce(v_staff AND v_org = current_org(), false) THEN
    IF NOT EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = p_document_id AND dp.contact_id = v_me) THEN
      RAISE EXCEPTION 'not authorized for this document';
    END IF;
  END IF;

  SELECT * INTO v_horse FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF v_horse.org_id <> v_org THEN RAISE EXCEPTION 'horse is not in this organization'; END IF;

  IF NOT coalesce(v_staff AND v_org = current_org(), false) THEN
    IF v_horse.current_owner_contact_id IS DISTINCT FROM v_me THEN
      RAISE EXCEPTION 'you can only attach your own horse';
    END IF;
  END IF;

  UPDATE documents SET horse_id = p_horse_id, updated_at = now() WHERE id = p_document_id;

  FOR r IN
    SELECT cf.id,
           upper(split_part(regexp_replace(cf.field_key, '[{}]', '', 'g'), '.', 2)) AS field
    FROM contract_fields cf
    WHERE cf.document_id = p_document_id
      AND regexp_replace(cf.field_key, '[{}]', '', 'g') LIKE 'HORSE.%'
  LOOP
    UPDATE contract_fields
       SET value = horse_field_token_value(v_horse, r.field), updated_at = now()
     WHERE id = r.id;
  END LOOP;

  PERFORM set_document_disclosure_structured(p_document_id, v_horse);

  -- Recompose with the engine the document actually uses: clause-engine
  -- templates (contract_section_defs rows) compose from clauses; flat
  -- templates from the tokenized body. (Previously always from_fields; the
  -- frontend papered over it with a follow-up clauses remerge.)
  IF EXISTS (
    SELECT 1 FROM contract_section_defs s
    JOIN contract_templates ct ON ct.id = (SELECT template_id FROM documents WHERE id = p_document_id)
    WHERE s.template_key = ct.template_key
  ) THEN
    PERFORM remerge_contract_from_clauses(p_document_id);
  ELSE
    PERFORM remerge_contract_from_fields(p_document_id);
  END IF;
END;
$$;


--
-- Name: attach_minor_to_guardian(uuid, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_minor_to_guardian(p_guardian_contact_id uuid, p_first_name text, p_last_name text, p_dob date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_mf    text := nullif(btrim(coalesce(p_first_name, '')), '');
  v_ml    text := nullif(btrim(coalesce(p_last_name,  '')), '');
  v_mname text;
  v_minor uuid;
BEGIN
  -- A minor with no first name is not a minor we can record. The onboarding
  -- caller already guards on this; the door does too. Returning NULL rather
  -- than raising keeps a half-filled optional block from failing a signup.
  IF p_guardian_contact_id IS NULL OR v_mf IS NULL THEN RETURN NULL; END IF;

  SELECT org_id INTO v_org FROM contacts
   WHERE id = p_guardian_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no such guardian contact: %', p_guardian_contact_id;
  END IF;

  v_mname := btrim(coalesce(v_mf, '') || ' ' || coalesce(v_ml, ''));

  -- Find this guardian's minor by name, else create one linked to them. Matching
  -- on name is what makes a repeat submission idempotent: a parent who signs up
  -- twice gets ONE child record, not two.
  SELECT id INTO v_minor FROM contacts
    WHERE guardian_contact_id = p_guardian_contact_id
      AND lower(btrim(coalesce(first_name, '') || ' ' || coalesce(last_name, ''))) = lower(v_mname)
      AND deleted_at IS NULL
    ORDER BY created_at LIMIT 1;

  IF v_minor IS NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, date_of_birth, guardian_contact_id)
      VALUES (v_org, v_mf, v_ml, p_dob, p_guardian_contact_id)
      RETURNING id INTO v_minor;
  ELSE
    -- FILL, never overwrite — the same rule fill_claimant_details applies to
    -- everything a public form supplies.
    UPDATE contacts SET date_of_birth = coalesce(date_of_birth, p_dob)
      WHERE id = v_minor;
  END IF;

  RETURN v_minor;
END;
$$;


--
-- Name: attach_offerings_to_client(uuid, uuid[], boolean, text, text, numeric, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_offerings_to_client(p_contact_id uuid, p_offering_ids uuid[], p_mark_paid boolean DEFAULT false, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_partial_amount numeric DEFAULT 0, p_org_id uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_client   uuid;
  v_purchase uuid;
  v_total    numeric := 0;
  v_labels   text[];
  v_when     timestamptz;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized to attach offerings';
  END IF;
  IF p_contact_id IS NULL THEN RAISE EXCEPTION 'contact is required'; END IF;
  IF array_length(p_offering_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'at least one offering is required';
  END IF;

  -- TASK-BACKDATE: A FUTURE DATE IS NOT A BACKFILL. Refused here, not in the UI —
  -- this function is EXECUTE-able by `authenticated` straight over PostgREST.
  IF p_occurred_at IS NOT NULL
     AND (p_occurred_at AT TIME ZONE 'America/Los_Angeles')::date
       > (now()         AT TIME ZONE 'America/Los_Angeles')::date THEN
    RAISE EXCEPTION 'an order cannot be dated in the future (%)',
      to_char(p_occurred_at AT TIME ZONE 'America/Los_Angeles', 'YYYY-MM-DD');
  END IF;
  v_when := coalesce(p_occurred_at, now());

  -- org: explicit -> the contact's org -> an offering's org -> current_org()
  v_org := p_org_id;
  IF v_org IS NULL THEN
    SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  END IF;
  IF v_org IS NULL THEN
    SELECT o.org_id INTO v_org FROM offerings o WHERE o.id = p_offering_ids[1];
  END IF;
  v_org := coalesce(v_org, current_org());
  IF v_org IS NULL THEN RAISE EXCEPTION 'could not resolve org'; END IF;

  -- client shell (create if the contact isn't a client yet).
  -- TASK-BACKDATE: `client_since` is a D8 marker — a client backfilled from last
  -- March became a client last March, not the day someone typed them in.
  SELECT cl.id INTO v_client FROM clients cl WHERE cl.contact_id = p_contact_id AND cl.deleted_at IS NULL;
  IF v_client IS NULL THEN
    INSERT INTO clients (org_id, contact_id, source, client_since)
      VALUES (v_org, p_contact_id, 'offering attachment', v_when)
      RETURNING id INTO v_client;
  END IF;

  -- the ONE shared purchase/items/credits write
  v_purchase := _provision_purchase_for_offerings(
    v_org, p_contact_id, v_client, p_offering_ids,
    p_mark_paid, p_payment_method, p_notes, p_partial_amount, p_occurred_at);

  SELECT coalesce(sum(o.price_amount), 0), array_agg(o.name)
    INTO v_total, v_labels
    FROM offerings o WHERE o.id = ANY(p_offering_ids);

  RETURN jsonb_build_object(
    'purchase_id', v_purchase, 'contact_id', p_contact_id,
    'amount', coalesce(v_total, 0),
    'occurred_at', v_when,
    'labels', coalesce(v_labels, ARRAY[]::text[]));
END;
$$;


--
-- Name: attach_purchase_horse(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_purchase_horse(p_purchase_id uuid, p_horse_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  UPDATE purchases
     SET horse_id = p_horse_id
   WHERE id = p_purchase_id
     AND deleted_at IS NULL
     AND (buyer_user_id = auth.uid() OR buyer_contact_id = v_contact OR is_admin());
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase not found or not yours';
  END IF;
END;
$$;


--
-- Name: audit_logs_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_logs_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only: % is not permitted', TG_OP;
END;
$$;


--
-- Name: audit_row_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_headers text;
  v_ip      text;
  v_ua      text;
  v_rec     uuid;
BEGIN
  -- best-effort request metadata; absent outside the Supabase runtime
  v_headers := current_setting('request.headers', true);
  IF v_headers IS NOT NULL AND v_headers <> '' THEN
    v_ip := (v_headers::json) ->> 'x-forwarded-for';
    v_ua := (v_headers::json) ->> 'user-agent';
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_rec := OLD.id;
  ELSE
    v_rec := NEW.id;
  END IF;

  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value, ip, user_agent)
  VALUES (
    auth.uid(),
    TG_OP,
    TG_TABLE_NAME,
    v_rec,
    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END,
    v_ip,
    v_ua
  );

  RETURN NULL;  -- AFTER trigger; return value ignored
END;
$$;


--
-- Name: billing_next_due(date, public.billing_cadence, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_next_due(p_start date, p_cadence public.billing_cadence, p_after date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_due date := p_start;
  v_step interval := CASE p_cadence WHEN 'weekly' THEN interval '7 days' ELSE interval '1 month' END;
  v_guard int := 0;
BEGIN
  WHILE v_due < p_after AND v_guard < 600 LOOP
    v_due := (v_due + v_step)::date;
    v_guard := v_guard + 1;
  END LOOP;
  RETURN v_due;
END;
$$;


--
-- Name: block_settled_billable_line_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_settled_billable_line_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'SETTLED' THEN
    RAISE EXCEPTION 'billable_line % is settled and append-only; it cannot be deleted', OLD.id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: block_settled_billable_line_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_settled_billable_line_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'SETTLED' AND (
       NEW.payer_contact_id IS DISTINCT FROM OLD.payer_contact_id
    OR NEW.source_kind      IS DISTINCT FROM OLD.source_kind
    OR NEW.source_id        IS DISTINCT FROM OLD.source_id
    OR NEW.horse_id         IS DISTINCT FROM OLD.horse_id
    OR NEW.qty              IS DISTINCT FROM OLD.qty
    OR NEW.unit_amount      IS DISTINCT FROM OLD.unit_amount
    OR NEW.amount           IS DISTINCT FROM OLD.amount
    OR NEW.status           IS DISTINCT FROM OLD.status
    OR NEW.period           IS DISTINCT FROM OLD.period
    OR NEW.transaction_id   IS DISTINCT FROM OLD.transaction_id
    OR NEW.org_id           IS DISTINCT FROM OLD.org_id
  ) THEN
    RAISE EXCEPTION 'billable_line % is settled and append-only; it cannot be modified', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: block_signed_signature_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_signed_signature_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Guarded identity-merge re-key: ONLY the signer_contact_id may change,
  -- ONLY under the transaction-local flag (set inside
  -- promote_contact_to_account), and every re-key leaves an audit row.
  IF OLD.signed_at IS NOT NULL
     AND current_setting('app.allow_signature_rekey', true) = '1'
     AND NEW.signer_contact_id IS DISTINCT FROM OLD.signer_contact_id
     AND NEW.typed_name  IS NOT DISTINCT FROM OLD.typed_name
     AND NEW.signed_at   IS NOT DISTINCT FROM OLD.signed_at
     AND NEW.ip_address  IS NOT DISTINCT FROM OLD.ip_address
     AND NEW.user_agent  IS NOT DISTINCT FROM OLD.user_agent
     AND NEW.method      IS NOT DISTINCT FROM OLD.method
     AND NEW.party_role  IS NOT DISTINCT FROM OLD.party_role
     AND NEW.document_id IS NOT DISTINCT FROM OLD.document_id THEN
    INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
    VALUES (auth.uid(), 'UPDATE', 'signatures', OLD.id,
            jsonb_build_object('reason', 'identity_merge',
                               'signer_contact_id', OLD.signer_contact_id,
                               'document_id', OLD.document_id),
            jsonb_build_object('reason', 'identity_merge',
                               'signer_contact_id', NEW.signer_contact_id,
                               'document_id', NEW.document_id));
    RETURN NEW;
  END IF;

  IF OLD.signed_at IS NOT NULL AND (
       NEW.typed_name        IS DISTINCT FROM OLD.typed_name
    OR NEW.signed_at         IS DISTINCT FROM OLD.signed_at
    OR NEW.ip_address        IS DISTINCT FROM OLD.ip_address
    OR NEW.user_agent        IS DISTINCT FROM OLD.user_agent
    OR NEW.method            IS DISTINCT FROM OLD.method
    OR NEW.party_role        IS DISTINCT FROM OLD.party_role
    OR NEW.signer_contact_id IS DISTINCT FROM OLD.signer_contact_id
    OR NEW.document_id       IS DISTINCT FROM OLD.document_id
  ) THEN
    RAISE EXCEPTION 'signature % is sealed (signed_at set); use void-and-reissue, not a direct update', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: book_open_slot(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_open_slot(p_booking_id uuid, p_horse_id uuid DEFAULT NULL::uuid, p_credit_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client  uuid := current_client_id();
  v_contact uuid := current_contact_id();
  v_b       bookings%ROWTYPE;
  v_kind    text;
  v_offering uuid;
  v_credit  uuid;
  v_gate    jsonb;
  v_cr_off  uuid;
  v_cr_pur  uuid;
BEGIN
  IF v_client IS NULL THEN RAISE EXCEPTION 'no member profile'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND OR NOT v_b.is_flexible OR v_b.status <> 'available' THEN
    RAISE EXCEPTION 'that time is no longer open';
  END IF;

  SELECT CASE WHEN o.segment = 'horse' THEN 'care' ELSE 'lesson' END, o.id
    INTO v_kind, v_offering
    FROM offerings o WHERE o.id = v_b.offering_id;
  v_kind := coalesce(v_kind, 'lesson');

  IF v_kind = 'care' THEN
    IF p_horse_id IS NULL THEN RAISE EXCEPTION 'a horse is required for a care booking'; END IF;
    v_gate := assert_horse_care_eligible(v_contact, p_horse_id);
    IF NOT (v_gate->>'eligible')::boolean THEN
      RAISE EXCEPTION 'HORSE_CARE_DOCS_REQUIRED: %', v_gate->>'missing'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- lesson branch: an explicit horse must be one the caller may use (owner or
  -- active lease); NULL stays allowed (barn-supplied horse). No care-docs gate
  -- here — that's care-specific.
  IF v_kind = 'lesson' AND p_horse_id IS NOT NULL THEN
    IF NOT caller_may_use_horse(v_contact, p_horse_id) THEN
      RAISE EXCEPTION 'that horse is not yours';
    END IF;
  END IF;

  -- ── ONBOARD §7: the member NAMED which purchased item this is against ──
  -- Their choice is honoured exactly: this credit or nothing. Falling back to
  -- "some other credit" would silently spend the wrong thing, which is worse
  -- than telling them the one they picked is gone.
  -- CREDITALIGN: "gone" now also means "last month's" — an allotment past its
  -- expires_at is not spendable, because the month does not carry over.
  IF p_credit_id IS NOT NULL THEN
    UPDATE lesson_credits SET credits_remaining = credits_remaining - 1
     WHERE id = (SELECT lc.id FROM lesson_credits lc
                  WHERE lc.id = p_credit_id
                    AND lc.client_id = v_client
                    AND lc.deleted_at IS NULL
                    AND lc.credits_remaining > 0
                    AND (lc.expires_at IS NULL OR lc.expires_at > now())
                  FOR UPDATE)
     RETURNING id INTO v_credit;
    IF v_credit IS NULL THEN RAISE EXCEPTION 'NO_CREDITS'; END IF;
  ELSE
  -- credit-gated: both lessons and care debit one service credit, preferring a
  -- credit tagged with this offering, falling back to any untagged balance.
  UPDATE lesson_credits SET credits_remaining = credits_remaining - 1
   WHERE id = (SELECT id FROM lesson_credits
               WHERE client_id = v_client AND org_id = v_b.org_id
                 AND deleted_at IS NULL AND credits_remaining > 0
                 AND (expires_at IS NULL OR expires_at > now())
                 AND (
                   -- offering-tagged slot: that offering's credits, or untagged
                   (v_offering IS NOT NULL AND (offering_id = v_offering OR offering_id IS NULL))
                   -- GENERIC slot (published from business hours, no offering):
                   -- any untagged credit, or any credit whose offering is not a
                   -- horse-care SKU — the slot is generic time; the credit says
                   -- what was bought. Without this, every real purchase (always
                   -- offering-tagged) was rejected by generic open slots.
                   OR (v_offering IS NULL AND (offering_id IS NULL OR EXISTS (
                        SELECT 1 FROM offerings oc WHERE oc.id = offering_id AND oc.segment <> 'horse')))
                 )
               -- CREDITALIGN: spend the thing that expires first. Without this an
               -- expiring monthly allotment sits unused behind a never-expiring pack
               -- and is silently lost at month end.
               ORDER BY (offering_id = v_offering) DESC NULLS LAST,
                        expires_at ASC NULLS LAST,
                        purchased_at, created_at
               LIMIT 1 FOR UPDATE)
   RETURNING id INTO v_credit;
  IF v_credit IS NULL THEN RAISE EXCEPTION 'NO_CREDITS'; END IF;
  END IF;

  -- BOOKWRITE: what the debited credit knows — the service and the order.
  SELECT lc.offering_id, lc.purchase_id INTO v_cr_off, v_cr_pur
    FROM lesson_credits lc WHERE lc.id = v_credit;

  -- REVIEWQ R1: claiming an open slot is a REQUEST, not a confirmation —
  -- status lands 'requested' (was 'scheduled' — FLOWTRACE item 10; then
  -- 'pending' — TASK-LIFECYCLE, because a claim nobody has answered is not
  -- the same state as an order whose payment method has been declared).
  UPDATE bookings SET
    kind = v_kind, status = 'requested', is_flexible = false,
    client_id = v_client,
    account_user_id = auth.uid(),
    account_contact_id = v_contact,
    offering_id = coalesce(offering_id, v_cr_off),
    purchase_id = coalesce(purchase_id, v_cr_pur),
    horse_id = coalesce(p_horse_id, horse_id),
    credit_id = v_credit,
    updated_at = now()
  WHERE id = p_booking_id;

  -- REVIEWQ R2: the companion request row the staff queue (open_change_
  -- requests / decide_booking_change) reads.
  INSERT INTO booking_change_requests (
    org_id, booking_id, requested_by, request_kind,
    proposed_starts_at, proposed_ends_at, status)
  VALUES (v_b.org_id, p_booking_id, auth.uid(), 'new', v_b.starts_at, v_b.ends_at, 'pending');

  PERFORM notify_staff(v_b.org_id, 'booking_time_requested',
    'A client claimed ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM'),
    '/app/calendar');

  RETURN jsonb_build_object('booking_id', p_booking_id, 'status', 'requested', 'kind', v_kind);
END;
$$;


--
-- Name: booking_awaiting_payment(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_awaiting_payment(p_booking public.bookings) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- Skipped exactly where the owner said `approved` is skipped: the session was
  -- bought with a credit, there is no order behind it, the order is paid, or it
  -- owes nothing.
  SELECT p_booking.credit_id IS NULL
     AND p_booking.purchase_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM purchases p
        WHERE p.id = p_booking.purchase_id
          AND p.deleted_at IS NULL
          AND p.status <> 'void'
          AND coalesce(p.payment_status,'') <> 'paid'
          AND greatest(coalesce(p.amount,0) - coalesce(p.amount_paid,0), 0) > 0);
$$;


--
-- Name: booking_change_fee_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_change_fee_schedule() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', f.id, 'hours_before', f.hours_before,
           'fee_amount', f.fee_amount, 'label', f.label, 'active', f.active)
         ORDER BY f.hours_before DESC), '[]'::jsonb)
    FROM booking_change_fees f
   WHERE f.org_id = current_org()
$$;


--
-- Name: booking_form(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_form(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b  bookings%ROWTYPE;
  v_f  booking_forms%ROWTYPE;
  v_service text;
  v_key text;
  v_plan lesson_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;
  IF NOT coalesce(has_staff_access() AND v_b.org_id = current_org(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT * INTO v_f FROM booking_forms WHERE booking_id = p_booking_id;
  v_service := coalesce(v_f.service_type, booking_service_type(v_b));
  v_key     := coalesce(v_f.form_key, booking_form_key(v_service));
  v_plan    := _lesson_plan_for_booking(p_booking_id);

  RETURN jsonb_build_object(
    'booking_id',   v_b.id,
    'kind',         v_b.kind,
    'starts_at',    v_b.starts_at,
    'ends_at',      v_b.ends_at,
    'booking_status', upper(v_b.status),
    'client_id',    v_b.client_id,
    'service_type', v_service,
    'checklist',    activity_checklist(v_service),
    'definition',   (SELECT jsonb_build_object('form_key', fd.form_key, 'title', fd.title,
                              'purpose', fd.purpose, 'version', fd.version, 'schema', fd.schema)
                       FROM form_definitions fd WHERE fd.form_key = v_key),
    'form',         CASE WHEN v_f.id IS NULL THEN NULL ELSE jsonb_build_object(
                      'id', v_f.id, 'status', v_f.status, 'answers', v_f.answers,
                      'blank', _booking_form_is_blank(v_f.answers),
                      'submitted_at', v_f.submitted_at, 'retired_at', v_f.retired_at,
                      'plan_id', v_f.plan_id,
                      'created_at', v_f.created_at, 'updated_at', v_f.updated_at) END,
    'can_mark_no_show', v_b.kind = 'lesson' AND v_b.status = 'scheduled',

    -- LESSONPLAN: the plan this lesson carries. Staff surface, so the private
    -- lane is included and the form labels it as staff-only on screen.
    'plan',         _lesson_plan_json(v_plan, true),
    'plan_next_up', lesson_plan_next_up(v_plan.objectives),
    'plan_pinned',  v_f.plan_id IS NOT NULL
  );
END;
$$;


--
-- Name: booking_form_applies(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_form_applies(p_booking public.bookings) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_booking.kind IN ('lesson', 'care')
     AND p_booking.client_id IS NOT NULL
     AND p_booking.deleted_at IS NULL
     AND p_booking.status IN ('requested', 'approved', 'pending', 'moved',
                              'confirmed', 'scheduled', 'completed', 'no_show')
$$;


--
-- Name: booking_form_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_form_key(p_service_type text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT fd.form_key FROM form_definitions fd
      WHERE fd.active AND p_service_type IS NOT NULL
        AND fd.form_key = 'ACTIVITY_' || p_service_type),
    'ACTIVITY_SESSION')
$$;


--
-- Name: booking_item_options(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_item_options(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b      bookings%ROWTYPE;
  v_client uuid := current_client_id();
  v_staff  boolean := coalesce(has_staff_access(), false);
  v_mine   boolean;
  v_can    boolean := false;
  v_why    text;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;
  v_mine := v_client IS NOT NULL AND v_b.client_id = v_client;
  IF NOT (v_staff OR v_mine) THEN RAISE EXCEPTION 'not authorized to view this booking'; END IF;

  IF v_b.status IN ('completed','cancelled','expired','no_show') THEN
    v_why := 'This booking is ' || v_b.status || ' — there is nothing left to charge.';
  ELSIF v_staff THEN
    v_can := true;
  ELSIF v_b.status IN ('requested','pending') THEN
    v_can := true;
  ELSE
    v_why := 'We have already confirmed this booking — ask us and we will move it for you.';
  END IF;

  RETURN jsonb_build_object(
    'booking_id', p_booking_id,
    'kind', v_b.kind,
    'status', v_b.status,
    'can_swap', v_can,
    'reason', v_why,
    'current', (SELECT jsonb_build_object(
                  'credit_id', lc.id,
                  'label', coalesce(o.name, lc.package_key, 'Lesson credit'),
                  'offering_id', lc.offering_id,
                  'purchase_id', lc.purchase_id,
                  'expires_at', lc.expires_at,
                  'remaining', lc.credits_remaining)
                  FROM lesson_credits lc
                  LEFT JOIN offerings o ON o.id = lc.offering_id
                 WHERE lc.id = v_b.credit_id),
    'options', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                  'credit_id', lc.id,
                  'label', coalesce(o.name, lc.package_key, 'Lesson credit'),
                  'offering_id', lc.offering_id,
                  'purchase_id', lc.purchase_id,
                  'segment', o.segment,
                  'remaining', lc.credits_remaining,
                  'period_start', lc.period_start,
                  'expires_at', lc.expires_at)
                  ORDER BY lc.expires_at ASC NULLS LAST, lc.purchased_at), '[]'::jsonb)
                  FROM lesson_credits lc
                  LEFT JOIN offerings o ON o.id = lc.offering_id
                 WHERE lc.client_id = v_b.client_id
                   AND lc.deleted_at IS NULL
                   AND lc.credits_remaining > 0
                   AND (lc.expires_at IS NULL OR lc.expires_at > now())
                   AND lc.id IS DISTINCT FROM v_b.credit_id
                   -- same segment rule book_open_slot enforces: care is funded by
                   -- horse-segment entitlement, lessons by everything else.
                   AND (v_b.kind <> 'care' OR o.segment = 'horse')
                   AND (v_b.kind <> 'lesson' OR coalesce(o.segment, '') <> 'horse'))
  );
END;
$$;


--
-- Name: booking_notifies_client(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_notifies_client(p_booking public.bookings) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_booking.kind = 'lesson'
      OR (p_booking.kind = 'care' AND (
            p_booking.address IS NOT NULL
            OR EXISTS (SELECT 1 FROM locations l WHERE l.id = p_booking.location_id AND l.is_offsite)));
$$;


--
-- Name: booking_purchase_card(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_purchase_card(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org        uuid := current_org();
  b            record;
  o            record;
  v_kind       text;
  v_total      int;
  v_remaining  int;
  v_used       int;
  v_position   int;
  v_label      text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;

  SELECT bk.id, bk.purchase_id, bk.offering_id, bk.client_id, bk.starts_at, bk.series_id
    INTO b FROM bookings bk WHERE bk.id = p_booking_id AND bk.org_id = v_org;
  IF b.id IS NULL THEN RAISE EXCEPTION 'no such booking'; END IF;
  IF b.purchase_id IS NULL THEN
    RETURN jsonb_build_object('has_purchase', false);
  END IF;

  SELECT id, name, config_kind, unit_count INTO o FROM offerings WHERE id = b.offering_id;

  -- The order's display label.
  SELECT coalesce(p.display_code, o.name, 'Purchase') INTO v_label
    FROM purchases p WHERE p.id = b.purchase_id;

  IF o.config_kind = 'recurring' THEN
    v_kind := 'recurring';
    -- This month's allotment row (the current, non-expired period).
    SELECT lc.credits_total, lc.credits_remaining
      INTO v_total, v_remaining
      FROM lesson_credits lc
     WHERE lc.purchase_id = b.purchase_id AND lc.client_id = b.client_id
       AND lc.offering_id = b.offering_id AND lc.deleted_at IS NULL
       AND (lc.expires_at IS NULL OR lc.expires_at >= now())
     ORDER BY lc.period_start DESC NULLS LAST
     LIMIT 1;
  ELSIF o.config_kind = 'scheduled' AND coalesce(o.unit_count, 1) > 1 THEN
    v_kind := 'punch_card';
    SELECT lc.credits_total, lc.credits_remaining
      INTO v_total, v_remaining
      FROM lesson_credits lc
     WHERE lc.purchase_id = b.purchase_id AND lc.client_id = b.client_id
       AND lc.offering_id = b.offering_id AND lc.deleted_at IS NULL
     ORDER BY lc.created_at ASC
     LIMIT 1;
  ELSE
    v_kind := 'single';
  END IF;

  IF v_kind = 'single' OR v_total IS NULL THEN
    RETURN jsonb_build_object(
      'has_purchase', true, 'label', v_label, 'offering', o.name,
      'kind', v_kind, 'is_series', false);
  END IF;

  v_used := greatest(v_total - v_remaining, 0);
  -- Position of THIS booking among the client's live bookings on the same
  -- purchase, oldest first — "Lesson 5/8".
  SELECT count(*) INTO v_position
    FROM bookings bk
   WHERE bk.purchase_id = b.purchase_id AND bk.client_id = b.client_id
     AND bk.org_id = v_org
     AND bk.status NOT IN ('cancelled','expired')
     AND bk.starts_at <= b.starts_at;

  RETURN jsonb_build_object(
    'has_purchase', true, 'label', v_label, 'offering', o.name,
    'kind', v_kind, 'is_series', true,
    'total', v_total, 'used', v_used, 'remaining', v_remaining,
    'position', v_position);
END;
$$;


--
-- Name: booking_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_report(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b      bookings%ROWTYPE;
  v_client uuid := current_client_id();
  v_staff  boolean;
  v_plan   lesson_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;

  v_staff := coalesce(has_staff_access() AND v_b.org_id = current_org(), false);
  IF NOT (v_staff OR (v_client IS NOT NULL AND v_b.client_id = v_client)) THEN
    RAISE EXCEPTION 'not authorized to view this report';
  END IF;

  v_plan := _lesson_plan_for_booking(p_booking_id);

  RETURN jsonb_build_object(
    'booking_id',   v_b.id,
    'kind',         v_b.kind,
    'starts_at',    v_b.starts_at,
    'ends_at',      v_b.ends_at,
    'status',       upper(v_b.status),
    'location',     v_b.location,
    'horse_id',     v_b.horse_id,
    'service_type', booking_service_type(v_b),
    'checklist',    activity_checklist(booking_service_type(v_b)),
    'activity_log', CASE
                      WHEN v_b.activity_log IS NULL THEN NULL
                      WHEN v_staff THEN v_b.activity_log
                      ELSE jsonb_build_object(
                        'activities', coalesce(v_b.activity_log -> 'activities', '[]'::jsonb),
                        'text', NULL)
                    END,
    'report',       v_b.notes,
    'notes', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'id', n.id, 'author_role', n.author_role, 'author_name', n.author_name,
          'phase', n.phase, 'body', n.body, 'created_at', n.created_at)
        ORDER BY (n.phase = 'pre') DESC, n.created_at)
      FROM booking_notes n WHERE n.booking_id = v_b.id), '[]'::jsonb),
    'form', CASE WHEN NOT v_staff THEN NULL ELSE (
      SELECT jsonb_build_object('id', f.id, 'status', f.status, 'answers', f.answers,
               'blank', _booking_form_is_blank(f.answers), 'submitted_at', f.submitted_at,
               'form_key', f.form_key, 'plan_id', f.plan_id)
        FROM booking_forms f WHERE f.booking_id = v_b.id) END,

    -- LESSONPLAN: what this lesson is for. Private lane included only for staff.
    'plan',         _lesson_plan_json(v_plan, v_staff),
    'plan_next_up', lesson_plan_next_up(v_plan.objectives)
  );
END;
$$;


--
-- Name: booking_service_label(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_service_label(p_kind text, p_offering_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_kind = 'lesson' THEN 'Riding Lesson'
    WHEN p_kind = 'care' THEN coalesce(
      nullif(btrim(regexp_replace(
        (SELECT o.name FROM offerings o WHERE o.id = p_offering_id),
        '^\s*\d+\s*x?\s*(weekly|daily|monthly|per week|/week)?\s*', '', 'i')), ''),
      'horse care')
    ELSE 'appointment'
  END;
$$;


--
-- Name: booking_service_type(public.bookings); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_service_type(p_booking public.bookings) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_booking.offering_id IS NOT NULL
      THEN (SELECT o.service_type FROM offerings o WHERE o.id = p_booking.offering_id)
    WHEN p_booking.kind = 'lesson' THEN 'RIDING_LESSON'
    ELSE NULL
  END
$$;


--
-- Name: booking_status_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_status_code(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status IN ('completed') THEN 'completed'
    WHEN p_status IN ('cancelled','expired') THEN 'cancelled'
    -- asked for · approved and awaiting payment · payment declared · held while
    -- a move is decided. None of these is a session anyone can rely on yet.
    WHEN p_status IN ('requested','approved','pending','moved') THEN 'pending'
    WHEN p_status IN ('scheduled','confirmed') THEN 'scheduled'
    ELSE 'pending' END;
$$;


--
-- Name: bookings_claim_on_account_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_claim_on_account_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.contact_id IS NULL OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE bookings b
     SET account_user_id = NEW.user_id
   WHERE b.account_contact_id = NEW.contact_id
     AND b.account_user_id IS NULL;

  RETURN NEW;
END;
$$;


--
-- Name: bookings_derive_account_contact_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_derive_account_contact_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
BEGIN
  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT contact_id INTO v_contact FROM clients WHERE id = NEW.client_id;

  IF NEW.account_contact_id IS NULL THEN
    NEW.account_contact_id := v_contact;
  ELSIF NEW.account_contact_id IS DISTINCT FROM v_contact THEN
    RAISE EXCEPTION 'bookings: account_contact_id (%) disagrees with client_id''s contact (%)',
      NEW.account_contact_id, v_contact;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: bookings_overlapping(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_overlapping(p_from timestamp with time zone, p_to timestamp with time zone, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); v_out jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RETURN '[]'::jsonb; END IF;
  SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY x.starts_at), '[]'::jsonb) INTO v_out
  FROM (
    SELECT b.id, b.kind, b.status, b.starts_at, b.ends_at, b.client_id, b.horse_id,
           (SELECT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email)
              FROM clients cl JOIN contacts c ON c.id = cl.contact_id WHERE cl.id = b.client_id) AS client_name,
           (SELECT o.name FROM offerings o WHERE o.id = b.offering_id) AS offering_name,
           (SELECT h.nickname FROM horses h WHERE h.id = b.horse_id) AS horse_name
      FROM bookings b
     WHERE b.org_id = v_org AND b.deleted_at IS NULL
       AND b.status NOT IN ('cancelled','expired','draft','available')
       AND (p_exclude_id IS NULL OR b.id <> p_exclude_id)
       AND b.starts_at < p_to
       AND (b.ends_at IS NULL OR b.ends_at > p_from)
  ) x;
  RETURN v_out;
END
$$;


--
-- Name: bos_generate_document(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bos_generate_document(p_contract_id uuid, p_anchor_contact_id uuid, p_horse_id uuid, p_parties jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_doc uuid;
BEGIN
  -- one ACTIVE bill of sale per contract: a superseding one requires voiding
  -- the old first (executed-docs rule: signed documents are never swept)
  IF EXISTS (
    SELECT 1 FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contract_id = p_contract_id AND t.template_key = 'HORSE_BILL_OF_SALE'
       AND d.deleted_at IS NULL AND d.workflow_state <> 'void'
  ) THEN
    RAISE EXCEPTION 'this contract already has a bill of sale — void it before generating another';
  END IF;

  SELECT org_id INTO v_org FROM contacts WHERE id = p_anchor_contact_id;

  SELECT gd.document_id INTO v_doc FROM generate_document(
    p_anchor_contact_id, 'HORSE_BILL_OF_SALE', p_contract_id, p_horse_id, p_parties, NULL::text) gd;

  UPDATE documents SET originator_contact_id = current_contact_id(),
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = 'HORSE_BILL_OF_SALE';

  -- RULE (content file): when the company is a compensated intermediary on this
  -- deal — an executed transaction-representation retainer for any party — the
  -- agent disclosure election must be INCLUDED. Detected via the retainer
  -- document's parties; leave unseeded when no linkage exists.
  IF EXISTS (
    SELECT 1
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id AND t.template_key = 'HORSE_TRANSACTION_REP'
      JOIN document_parties dp ON dp.document_id = d.id
     WHERE d.status = 'EXECUTED' AND d.deleted_at IS NULL
       AND dp.contact_id IN (SELECT contact_id FROM jsonb_to_recordset(p_parties) AS p(contact_id uuid))
  ) THEN
    UPDATE contract_fields SET value = 'INCLUDED'
     WHERE document_id = v_doc AND field_key = 'TXN.AGENT_ELECTION';
  END IF;

  RETURN v_doc;
END;
$$;


--
-- Name: business_hours(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_hours() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'weekday', weekday, 'open', open_time, 'close', close_time, 'closed', closed)
      ORDER BY weekday), '[]'::jsonb)
  FROM business_hours WHERE org_id = current_org()
$$;


--
-- Name: calendar_free_busy(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_free_busy(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_staff  boolean := has_staff_access();
  v_client uuid := current_client_id();
  v_items  jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_to <= p_from OR p_to - p_from > interval '62 days' THEN
    RAISE EXCEPTION 'range must be positive and <= 62 days';
  END IF;

  SELECT coalesce(jsonb_agg(item ORDER BY ((item->>'starts_at')::timestamptz)), '[]'::jsonb) INTO v_items
  FROM (
    SELECT CASE
      -- staff/admin: full detail on every item, now WITH the display names.
      WHEN v_staff THEN jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'status', b.status, 'all_day', b.all_day,
        'starts_at', b.starts_at, 'ends_at', b.ends_at,
        'is_flexible', b.is_flexible, 'is_mine', false, 'mine_role', 'staff',
        'client_id', b.client_id, 'horse_id', b.horse_id, 'purchase_id', b.purchase_id,
        'instructor_user_id', b.instructor_user_id,
        'offering_id', b.offering_id, 'location_id', b.location_id, 'address', b.address,
        'price_amount', b.price_amount, 'notes', b.notes,
        'travel_before_minutes', b.travel_before_minutes,
        'travel_after_minutes', b.travel_after_minutes, 'series_id', b.series_id,
        -- ⚠️ DISPLAY-ONLY (2026-09-12): who the session is with, and what it is.
        'client_name', (SELECT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email)
                          FROM clients cl JOIN contacts c ON c.id = cl.contact_id
                         WHERE cl.id = b.client_id),
        'offering_name', (SELECT o.name FROM offerings o WHERE o.id = b.offering_id))
      WHEN b.client_id = v_client THEN jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'status', b.status, 'all_day', b.all_day,
        'starts_at', b.starts_at, 'ends_at', b.ends_at,
        'is_flexible', b.is_flexible, 'is_mine', true, 'mine_role', 'client',
        'horse_id', b.horse_id, 'offering_id', b.offering_id,
        'location_id', b.location_id, 'address', b.address, 'notes', b.notes,
        'series_id', b.series_id)
      WHEN b.status = 'cancelled' THEN NULL
      WHEN b.is_flexible AND b.status = 'available' THEN jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'status', 'available', 'all_day', b.all_day,
        'starts_at', b.starts_at, 'ends_at', b.ends_at,
        'is_flexible', true, 'is_mine', false, 'offering_id', b.offering_id,
        'location_id', b.location_id)
      ELSE jsonb_build_object(
        'id', b.id,
        'status', CASE WHEN b.status = 'moved' THEN 'pending_reschedule' ELSE 'unavailable' END,
        'is_mine', false,
        'all_day', b.all_day,
        'starts_at', b.starts_at - make_interval(mins => b.travel_before_minutes),
        'ends_at', b.ends_at + make_interval(mins => b.travel_after_minutes))
    END AS item
    FROM bookings b
    WHERE b.org_id = v_org
      AND b.status <> 'expired'
      AND b.starts_at < p_to
      AND (b.ends_at IS NULL OR b.ends_at > p_from)
      AND (v_staff OR b.status <> 'draft')
  ) rows
  WHERE item IS NOT NULL;

  RETURN jsonb_build_object(
    'from', p_from, 'to', p_to,
    'role', CASE WHEN v_staff THEN 'staff' ELSE 'client' END,
    'hours', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'weekday', weekday, 'open', open_time, 'close', close_time, 'closed', closed)
        ORDER BY weekday), '[]'::jsonb)
      FROM business_hours WHERE org_id = v_org),
    'items', v_items
  );
END;
$$;


--
-- Name: calendar_money_items(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_money_items(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT coalesce(jsonb_agg(x ORDER BY x->>'at'), '[]'::jsonb) FROM (
    -- payment due
    SELECT jsonb_build_object(
      'kind','payment','at', p.created_at, 'label',
      'Payment due · $' || round(coalesce(p.amount,0))::text,
      'ref', p.id, 'status', p.payment_status) AS x
      FROM purchases p
     WHERE p.deleted_at IS NULL AND p.payment_status <> 'paid' AND p.status <> 'void'
       AND p.created_at BETWEEN p_from AND p_to
       AND (has_staff_access() OR p.buyer_user_id = auth.uid() OR p.buyer_contact_id = current_contact_id())
    UNION ALL
    -- gift expirations
    SELECT jsonb_build_object(
      'kind','expiration','at', g.expires_at, 'label',
      'Gift expires · ' || coalesce(g.item_label,'gift'), 'ref', g.id, 'status', g.status)
      FROM gifts g
     WHERE g.expires_at BETWEEN p_from AND p_to AND g.status <> 'redeemed'
       AND (has_staff_access() OR g.buyer_user_id = auth.uid()
            OR lower(g.recipient_email) = lower((SELECT email FROM auth.users WHERE id = auth.uid())))
    UNION ALL
    -- confirmations pending: the three real stages before a session is firm,
    -- dated by starts_at (bookings never carry hold_expires_at).
    SELECT jsonb_build_object(
      'kind','confirmation','at', b.starts_at, 'label',
      'Confirm your booking', 'ref', b.id, 'status', b.status)
      FROM bookings b
     WHERE b.starts_at BETWEEN p_from AND p_to
       AND b.status IN ('requested','approved','pending')
       AND (has_staff_access() OR b.account_user_id = auth.uid() OR b.account_contact_id = current_contact_id())
  ) s;
$_$;


--
-- Name: FUNCTION calendar_money_items(p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calendar_money_items(p_from timestamp with time zone, p_to timestamp with time zone) IS 'RETIRED, NOT DROPPED (D32). Built for the calendar''s money row (payments due, gift expirations, pending confirmations) and read by nothing — zero call sites in src/, api/ or test/ as of TASK-FIX2, 2026-08-31. It also carries an unfixed D25 breach (AR1 F12) that has never been seen because nothing renders it. If it is ever wired, fix the naming first.';


--
-- Name: calendar_reminder_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_reminder_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n1 int := 0; b bookings%ROWTYPE; v_title text;
BEGIN
  IF NOT (coalesce(auth.role(),'') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- ⚠️ THE 2-HOUR REMINDER IS RETIRED (owner, 2026-08-26: "we only need the daily
  -- one at the start of the day and then the one that is sent 1 hour prior").
  -- `bookings.reminder_2h_sent_at` is deliberately left in place and left alone —
  -- it records what was already sent, and clearing it would make an old reminder
  -- look like it never happened.

  FOR b IN
    SELECT * FROM bookings
    WHERE status IN ('scheduled','confirmed','requested','approved','pending') AND kind IN ('lesson','care')
      AND reminder_1h_sent_at IS NULL
      AND starts_at BETWEEN now() AND now() + interval '1 hour'
  LOOP
    v_title := 'Starting soon: session at ' || to_char(b.starts_at, 'HH12:MI AM');
    -- THE CLIENT. Their one and only calendar email.
    IF b.account_user_id IS NOT NULL THEN
      INSERT INTO notifications (org_id, user_id, kind, title, link)
        VALUES (b.org_id, b.account_user_id, 'booking_reminder_1h', v_title, '/app/calendar');
    END IF;
    -- ⚠️ NO notify_staff. It fans out to every ADMIN profile, which is how
    -- admin@fhequestrian.com came to be emailed about every session. The shared
    -- inbox is served by the endpoint's single consolidated ops copy instead.
    UPDATE bookings SET reminder_1h_sent_at = now() WHERE id = b.id;
    v_n1 := v_n1 + 1;
  END LOOP;

  RETURN jsonb_build_object('reminders_2h', 0, 'reminders_1h', v_n1);
END;
$$;


--
-- Name: calendar_revenue(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_revenue(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN (
    SELECT jsonb_build_object(
      'total', coalesce(sum(price_amount), 0),
      'count', count(*))
    FROM bookings
    WHERE org_id = v_org
      AND starts_at >= p_from AND starts_at < p_to
      AND price_amount IS NOT NULL
      AND status NOT IN ('cancelled','expired','draft','unavailable','available'));
END;
$$;


--
-- Name: FUNCTION calendar_revenue(p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calendar_revenue(p_from timestamp with time zone, p_to timestamp with time zone) IS 'RETIRED, NOT DROPPED (D32). ⚠️ DO NOT WIRE THIS TO ANY SURFACE. It sums bookings.price_amount over the window''s START TIMES — scheduled value at the moment work is planned — and counts every session of a monthly plan at the plan''s full price. Measured 2026-08-30 it reads $18,320 for August where `revenue_summary` reads $1,880 (9.7x). `revenue_summary` is the single source for money and the calendar ribbon and dashboard tile both already call it (src/lib/ops/api-calendar.ts fetchRevenue). Zero call sites in src/, api/ or test/ as of TASK-FIX2, 2026-08-31.';


--
-- Name: caller_is_current_lessee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_is_current_lessee(h_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM horses h WHERE h.id = h_id AND h.deleted_at IS NULL
      AND h.lessee_contact_id = current_contact_id());
$$;


--
-- Name: caller_is_document_party(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_is_document_party(p_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1
    FROM documents d
    JOIN document_parties dp ON dp.document_id = d.id
    WHERE d.id = p_document_id
      AND d.deleted_at IS NULL
      AND dp.contact_id = current_contact_id()
  );
$$;


--
-- Name: FUNCTION caller_is_document_party(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.caller_is_document_party(p_document_id uuid) IS 'True when the caller''s contact plays ANY party_role on the document''s engagement (broader than caller_owns_document, which matches only the engagement client). Used by contract_fields / change-request / share RLS so a counterparty who is not "our" client can still read their own contract.';


--
-- Name: caller_is_document_party_or_staff(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_is_document_party_or_staff(p_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM documents d WHERE d.id = p_document_id
                  AND coalesce(has_staff_access() AND d.org_id = current_org(), false))
      OR EXISTS (SELECT 1 FROM document_parties dp
                  WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id());
$$;


--
-- Name: caller_may_propose(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_may_propose(p_document_id uuid, p_control text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_ok boolean;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF (has_staff_access() AND v_org = current_org()) OR contract_caller_is_originator(p_document_id) THEN
    RETURN true;
  END IF;
  SELECT bool_or(CASE p_control WHEN 'suggest' THEN coalesce(c.can_suggest, true)
                                WHEN 'add_clause' THEN coalesce(c.can_add_clause, true)
                                WHEN 'edit_deal' THEN coalesce(c.can_edit_deal, true)
                                ELSE false END)
    INTO v_ok
    FROM document_parties dp
    LEFT JOIN document_party_controls c ON c.document_id = dp.document_id AND c.party_role = dp.party_role
    WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id();
  RETURN coalesce(v_ok, false);
END;
$$;


--
-- Name: caller_may_resolve(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_may_resolve(p_document_id uuid, p_proposed_by_contact_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  RETURN (has_staff_access() AND v_org = current_org())
    OR contract_caller_is_originator(p_document_id)
    OR (caller_is_document_party(p_document_id) AND current_contact_id() <> p_proposed_by_contact_id);
END;
$$;


--
-- Name: caller_may_use_horse(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_may_use_horse(p_contact uuid, p_horse uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM horses h
    WHERE h.id = p_horse
      AND (
        h.current_owner_contact_id = p_contact
        OR (h.lessee_contact_id = p_contact AND (h.lease_end IS NULL OR h.lease_end >= current_date))
        OR EXISTS (
          SELECT 1 FROM horse_relationships hr
          WHERE hr.horse_id = h.id AND hr.party_contact_id = p_contact
            AND hr.relationship IN ('OWNER','LESSEE')
            AND hr.active AND (hr.term_end IS NULL OR hr.term_end >= current_date)
        )
      )
  );
$$;


--
-- Name: caller_owns_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_owns_document(doc_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM documents d
    WHERE d.id = doc_id
      AND d.deleted_at IS NULL
      AND d.contact_id = current_contact_id()
  );
$$;


--
-- Name: caller_owns_horse(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_owns_horse(h_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM horses h
    WHERE h.id = h_id
      AND h.deleted_at IS NULL
      AND (h.current_owner_contact_id = current_contact_id()
           OR h.lessee_contact_id = current_contact_id()
           OR EXISTS (SELECT 1 FROM horse_relationships hr
                       WHERE hr.horse_id = h.id
                         AND hr.party_contact_id = current_contact_id()
                         AND hr.active
                         AND hr.relationship IN ('OWNER','LESSEE','LESSOR')
                         AND (hr.term_end IS NULL OR hr.term_end >= current_date)))
  );
$$;


--
-- Name: caller_party_roles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_party_roles(p_document_id uuid) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT dp.party_role
  FROM documents d
  JOIN document_parties dp ON dp.document_id = d.id
  WHERE d.id = p_document_id
    AND d.deleted_at IS NULL
    AND current_contact_id() IS NOT NULL
    AND dp.contact_id = current_contact_id();
$$;


--
-- Name: FUNCTION caller_party_roles(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.caller_party_roles(p_document_id uuid) IS 'Every party_role the caller''s contact holds on the document''s engagement (a set — a contact may hold more than one). The ownership-enforcing RPCs test the owning role against this set.';


--
-- Name: can_cleanup_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_cleanup_document(p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_status text; v_dead boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;

  SELECT org_id, workflow_state, status,
         (voided_at IS NOT NULL OR terminated_at IS NOT NULL)
    INTO v_org, v_state, v_status, v_dead
    FROM documents
   WHERE id = p_document_id AND deleted_at IS NULL;

  -- unknown, already removed, or in a terminal state
  IF v_state IS NULL OR v_dead
     OR v_state IN ('executed', 'void', 'terminated')
     OR upper(coalesce(v_status, '')) IN ('EXECUTED', 'VOID', 'TERMINATED') THEN
    RETURN false;
  END IF;

  -- A document with a signature is never deletable from this UI. Ever.
  IF EXISTS (SELECT 1 FROM signatures s
              WHERE s.document_id = p_document_id
                AND s.deleted_at IS NULL) THEN
    RETURN false;
  END IF;

  -- coalesce is load-bearing: a NULL-org staff caller must be DENIED, not admitted
  -- by a NULL that every `IF NOT …` in the codebase silently skips. See D1a.
  RETURN coalesce(has_staff_access() AND v_org = current_org(), false);
END;
$$;


--
-- Name: can_list_horse(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_list_horse(p_horse_id uuid, p_intent text DEFAULT 'sale'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h horses%ROWTYPE;
  v_me uuid := current_contact_id();
  v_leased boolean;
BEGIN
  SELECT * INTO v_h FROM horses
   WHERE id = p_horse_id AND org_id = current_org() AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;
  IF has_staff_access() THEN RETURN true; END IF;

  v_leased := v_h.lessee_contact_id IS NOT NULL
              AND (v_h.lease_end IS NULL OR v_h.lease_end >= current_date);

  -- the OWNER may always list for sale; may list for lease only when not already leased
  IF v_h.current_owner_contact_id = v_me THEN
    IF p_intent = 'lease' THEN RETURN NOT v_leased; END IF;
    RETURN true;
  END IF;
  -- the LESSEE may list for sublease only when the executed lease permits it
  IF v_h.lessee_contact_id = v_me AND v_leased THEN
    RETURN p_intent = 'lease' AND lease_sublease_allowed(p_horse_id);
  END IF;
  RETURN false;   -- non-owner/non-lessee: never (incl. never for sale)
END;
$$;


--
-- Name: can_void_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_void_document(p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state text; v_org uuid; v_cid uuid; v_dead boolean;
  v_is_party boolean; v_is_staff boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  v_cid := current_contact_id();

  SELECT org_id, workflow_state,
         (voided_at IS NOT NULL OR terminated_at IS NOT NULL)
    INTO v_org, v_state, v_dead
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_state IS NULL OR v_dead OR v_state IN ('executed','void','terminated') THEN
    RETURN false;
  END IF;

  v_is_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  v_is_party := caller_is_document_party(p_document_id);
  IF NOT (v_is_staff OR v_is_party) THEN RETURN false; END IF;

  -- The party rule binds anyone who IS a party — including a staff member who
  -- signs as a party. Once you have signed, you can no longer void.
  IF v_is_party AND v_cid IS NOT NULL AND EXISTS (
    SELECT 1 FROM signatures s
     WHERE s.document_id = p_document_id
       AND s.deleted_at IS NULL AND s.signed_at IS NOT NULL
       AND s.signer_contact_id = v_cid) THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: FUNCTION can_void_document(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_void_document(p_document_id uuid) IS 'True while the caller may void: a party who has not yet signed, OR staff-in-org on a document that is alive and not executed. A staff member who is also a party loses the option once THEY sign, exactly like any other party.';


--
-- Name: cancel_lesson_session(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_lesson_session(p_session_id uuid, p_no_show boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b      bookings%ROWTYPE;
  v_status text := CASE WHEN p_no_show THEN 'no_show' ELSE 'cancelled' END;
  v_user   uuid;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized to cancel lessons';
  END IF;

  SELECT * INTO v_b FROM bookings
    WHERE id = p_session_id AND kind = 'lesson'
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown lesson session: %', p_session_id;
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role' AND v_b.org_id IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'lesson session % is not in your organization', p_session_id;
  END IF;
  IF v_b.status <> 'scheduled' THEN
    RAISE EXCEPTION 'only a SCHEDULED lesson can be cancelled (this one is %)', upper(v_b.status);
  END IF;

  UPDATE bookings SET status = v_status WHERE id = p_session_id;

  -- a cancellation is news the member needs; a no-show is a staff record.
  IF v_status = 'cancelled' AND v_b.account_user_id IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id, 'lesson_cancelled',
              'Your lesson on ' || to_char(v_b.starts_at, 'FMMonth FMDD, HH12:MI AM') || ' was cancelled',
              '/app/schedule');
  END IF;

  RETURN jsonb_build_object('session_id', p_session_id, 'status', upper(v_status));
END;
$$;


--
-- Name: FUNCTION cancel_lesson_session(p_session_id uuid, p_no_show boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_lesson_session(p_session_id uuid, p_no_show boolean) IS 'Flip a SCHEDULED lesson to CANCELLED (default — the member''s app user is notified, lesson_cancelled) or NO_SHOW (p_no_show => true, no notification). Staff-gated.';


--
-- Name: capture_contract_template_composition(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_contract_template_composition(p_template_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'sections', coalesce((
      select jsonb_agg(to_jsonb(s) - 'id' - 'created_at' order by s.sort_order, s.section_key)
        from contract_section_defs s where s.template_key = p_template_key), '[]'::jsonb),
    'clauses', coalesce((
      select jsonb_agg(to_jsonb(c) - 'id' - 'created_at' order by c.section_key, c.sort_order, c.clause_key)
        from contract_clause_defs c where c.template_key = p_template_key), '[]'::jsonb),
    'fields', coalesce((
      select jsonb_agg(to_jsonb(f) - 'id' - 'created_at' order by f.sort_order, f.field_key)
        from contract_field_defs f where f.template_key = p_template_key), '[]'::jsonb)
  )
$$;


--
-- Name: FUNCTION capture_contract_template_composition(p_template_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.capture_contract_template_composition(p_template_key text) IS 'TASK-VERSIONSPINE: the full authored composition of a template — sections, clauses, fields — as one jsonb, for retention in contract_template_versions. Whole-row capture so new columns are retained without a migration.';


--
-- Name: capture_horse_record_info(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_horse_record_info(p_document_id uuid, p_patch jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_horse uuid;
BEGIN
  SELECT org_id, horse_id INTO v_org, v_horse
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_horse IS NULL THEN RAISE EXCEPTION 'no horse on this document'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- Upsert the primary VET provider from the patch (create it if none exists).
  IF p_patch ?| ARRAY['vet_name','vet_phone','vet_business_name','vet_address_line1','vet_city','vet_state','vet_postal'] THEN
    IF EXISTS (SELECT 1 FROM horse_relationships WHERE horse_id = v_horse AND relationship='VET' AND active) THEN
      UPDATE horse_relationships r SET
        party_name_text = CASE WHEN p_patch ? 'vet_name'          THEN nullif(btrim(p_patch->>'vet_name'),'')          ELSE party_name_text END,
        phone           = CASE WHEN p_patch ? 'vet_phone'         THEN nullif(btrim(p_patch->>'vet_phone'),'')         ELSE phone END,
        business_name   = CASE WHEN p_patch ? 'vet_business_name' THEN nullif(btrim(p_patch->>'vet_business_name'),'') ELSE business_name END,
        address_line1   = CASE WHEN p_patch ? 'vet_address_line1' THEN nullif(btrim(p_patch->>'vet_address_line1'),'') ELSE address_line1 END,
        city            = CASE WHEN p_patch ? 'vet_city'          THEN nullif(btrim(p_patch->>'vet_city'),'')          ELSE city END,
        state           = CASE WHEN p_patch ? 'vet_state'         THEN nullif(btrim(p_patch->>'vet_state'),'')         ELSE state END,
        postal          = CASE WHEN p_patch ? 'vet_postal'        THEN nullif(btrim(p_patch->>'vet_postal'),'')        ELSE postal END
      WHERE r.id = (SELECT id FROM horse_relationships WHERE horse_id = v_horse AND relationship='VET' AND active
                    ORDER BY (provider_role='primary') DESC, created_at DESC LIMIT 1);
    ELSE
      INSERT INTO horse_relationships (org_id, horse_id, relationship, provider_role,
        party_name_text, phone, business_name, address_line1, city, state, postal, active, created_by_contact_id)
      VALUES (v_org, v_horse, 'VET', 'primary',
        nullif(btrim(p_patch->>'vet_name'),''), nullif(btrim(p_patch->>'vet_phone'),''),
        nullif(btrim(p_patch->>'vet_business_name'),''), nullif(btrim(p_patch->>'vet_address_line1'),''),
        nullif(btrim(p_patch->>'vet_city'),''), nullif(btrim(p_patch->>'vet_state'),''),
        nullif(btrim(p_patch->>'vet_postal'),''), true, current_contact_id());
    END IF;
  END IF;

  -- Upsert the primary FARRIER provider from the patch.
  IF p_patch ?| ARRAY['farrier_name','farrier_phone'] THEN
    IF EXISTS (SELECT 1 FROM horse_relationships WHERE horse_id = v_horse AND relationship='FARRIER' AND active) THEN
      UPDATE horse_relationships r SET
        party_name_text = CASE WHEN p_patch ? 'farrier_name'  THEN nullif(btrim(p_patch->>'farrier_name'),'')  ELSE party_name_text END,
        phone           = CASE WHEN p_patch ? 'farrier_phone' THEN nullif(btrim(p_patch->>'farrier_phone'),'') ELSE phone END
      WHERE r.id = (SELECT id FROM horse_relationships WHERE horse_id = v_horse AND relationship='FARRIER' AND active
                    ORDER BY (provider_role='primary') DESC, created_at DESC LIMIT 1);
    ELSE
      INSERT INTO horse_relationships (org_id, horse_id, relationship, provider_role,
        party_name_text, phone, active, created_by_contact_id)
      VALUES (v_org, v_horse, 'FARRIER', 'primary',
        nullif(btrim(p_patch->>'farrier_name'),''), nullif(btrim(p_patch->>'farrier_phone'),''),
        true, current_contact_id());
    END IF;
  END IF;

  PERFORM sync_contract_fields_from_defs(p_document_id);

  UPDATE contract_fields cf
     SET value = horse_field_token_value(hz, split_part(regexp_replace(cf.field_key, '[{}]', '', 'g'), 'HORSE.', 2)),
         updated_at = now()
    FROM horses hz
   WHERE hz.id = v_horse
     AND cf.document_id = p_document_id
     AND regexp_replace(cf.field_key, '[{}]', '', 'g') IN
         ('HORSE.FARRIER_NAME','HORSE.FARRIER_PHONE','HORSE.VET_NAME',
          'HORSE.VET_PHONE','HORSE.VET_BUSINESS','HORSE.VET_ADDRESS');

  PERFORM remerge_contract_body(p_document_id);
END;
$$;


--
-- Name: category_document_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.category_document_defaults() RETURNS TABLE(category text, template_key text, title text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT cdr.category, cdr.template_key, t.title
  FROM category_document_requirements cdr
  JOIN contract_templates t ON t.template_key = cdr.template_key
  WHERE cdr.org_id = current_org() AND has_staff_access()
  ORDER BY cdr.category, t.title
$$;


--
-- Name: certify_statement(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.certify_statement(p_field_key text, p_raw text, p_tmpl text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN upper(coalesce(p_raw,'')) = 'YES'
    THEN coalesce((SELECT label FROM contract_field_defs
                    WHERE template_key = p_tmpl AND field_key = p_field_key), '')
    ELSE '' END;
$$;


--
-- Name: change_log_section_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_log_section_key(p_document_id uuid, p_field_key text, OUT section_key text, OUT clause_key text) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_tkey text; v_head text;
BEGIN
  section_key := NULL; clause_key := NULL;
  IF p_field_key IS NULL OR trim(p_field_key) = '' THEN RETURN; END IF;

  -- 1 + 2 — the live field on this document
  SELECT nullif(trim(cf.section),''), nullif(trim(cf.clause_key),'')
    INTO section_key, clause_key
    FROM contract_fields cf
   WHERE cf.document_id = p_document_id AND cf.field_key = p_field_key
   LIMIT 1;
  IF section_key IS NOT NULL OR clause_key IS NOT NULL THEN RETURN; END IF;

  SELECT ct.template_key INTO v_tkey
    FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.id = p_document_id;

  -- 3 — the template definition
  IF v_tkey IS NOT NULL THEN
    SELECT nullif(trim(fd.section),''), nullif(trim(fd.clause_key),'')
      INTO section_key, clause_key
      FROM contract_field_defs fd
     WHERE fd.template_key = v_tkey AND fd.field_key = p_field_key
     LIMIT 1;
    IF section_key IS NOT NULL OR clause_key IS NOT NULL THEN RETURN; END IF;

    -- 4 — the SECTION.FIELD convention, where the key really follows it
    v_head := split_part(p_field_key, '.', 1);
    IF EXISTS (SELECT 1 FROM contract_section_defs sd
                WHERE sd.template_key = v_tkey AND sd.section_key = v_head) THEN
      section_key := v_head;
      RETURN;
    END IF;
  END IF;

  -- 5 — retired keys, attributed from their documented stem
  section_key := retired_field_section(p_field_key);
END;
$$;


--
-- Name: change_request_impact_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_request_impact_rank(p_section text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE upper(coalesce(nullif(trim(p_section), ''), '~'))
    WHEN 'LEASE_FEE'        THEN 100
    WHEN 'PAYMENT_TERMS'    THEN 100
    WHEN 'PAYMENT_METHOD'   THEN 100
    WHEN 'INSURANCE_RISK'   THEN 90
    WHEN 'TERM'             THEN 80
    WHEN 'TERMINATION'      THEN 80
    WHEN 'EVALUATION'       THEN 80
    WHEN 'CARE'             THEN 70
    WHEN 'PERMITTED_USE'    THEN 60
    WHEN 'SCHEDULE'         THEN 60
    WHEN 'HORSE'            THEN 50
    WHEN 'LOCATION'         THEN 50
    WHEN 'PARTIES'          THEN 50
    WHEN 'ASSIGNMENT'       THEN 40
    WHEN 'LESSEE_REPS'      THEN 40
    WHEN 'GOVERNING_LAW'    THEN 30
    WHEN 'ATTORNEYS_FEES'   THEN 30
    WHEN 'NOTICE'           THEN 20
    WHEN 'DEFINITIONS'      THEN 20
    WHEN 'ENTIRE_AGREEMENT' THEN 20
    WHEN 'SEVERABILITY'     THEN 20
    WHEN 'SIGNATURES'       THEN 20
    ELSE 10
  END;
$$;


--
-- Name: FUNCTION change_request_impact_rank(p_section text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.change_request_impact_rank(p_section text) IS 'Money/term/liability weight of a change request by target section. Higher = more impactful. Drives the "five highest-impact requests" listed in the submit-for-review notification and email. Ties break on annotation_number.';


--
-- Name: change_request_is_frozen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_request_is_frozen(p_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM contract_change_request_seen s
      JOIN contract_change_requests cr ON cr.id = s.request_id
     WHERE s.request_id = p_request_id
       AND s.contact_id IS DISTINCT FROM cr.author_contact_id);
$$;


--
-- Name: FUNCTION change_request_is_frozen(p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.change_request_is_frozen(p_request_id uuid) IS 'True once a party OTHER than the author has genuinely viewed this entry. Submission alone does NOT freeze an entry — being seen does.';


--
-- Name: claim_document_origination(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_document_origination(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  UPDATE documents SET originator_contact_id = current_contact_id()
   WHERE id = p_document_id;
END;
$$;


--
-- Name: claim_receipt_send(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_receipt_send(p_purchase_id uuid, p_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM receipt_sends
              WHERE purchase_id = p_purchase_id AND succeeded) THEN
    RETURN false;                                   -- provable and single
  END IF;
  RETURN NOT EXISTS (SELECT 1 FROM receipt_sends WHERE idempotency_key = p_key);
END;
$$;


--
-- Name: claim_request_alert_send(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_request_alert_send(p_request_id uuid, p_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM request_alert_sends
              WHERE request_id = p_request_id AND succeeded) THEN
    RETURN false;                                   -- provable and single
  END IF;
  RETURN NOT EXISTS (SELECT 1 FROM request_alert_sends WHERE idempotency_key = p_key);
END;
$$;


--
-- Name: claim_request_alert_send(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_request_alert_send(p_request_id uuid, p_key text, p_kind text DEFAULT 'staff'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM request_alert_sends
              WHERE request_id = p_request_id
                AND kind = coalesce(p_kind, 'staff')
                AND succeeded) THEN
    RETURN false;                                   -- provable and single, per kind
  END IF;
  RETURN NOT EXISTS (SELECT 1 FROM request_alert_sends WHERE idempotency_key = p_key);
END;
$$;


--
-- Name: claim_signup_help_alert(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_signup_help_alert(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_a       signup_attempts%ROWTYPE;
  v_first   boolean := false;
  v_name    text;
  v_diag    text;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  SELECT * INTO v_a FROM signup_attempts WHERE id = p_attempt_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;

  IF v_a.help_requested_at IS NULL THEN
    UPDATE signup_attempts SET help_requested_at = now() WHERE id = p_attempt_id;
    v_first := true;
  END IF;

  v_name := nullif(btrim(coalesce(v_a.first_name,'') || ' ' || coalesce(v_a.last_name,'')), '');
  v_diag := CASE
    WHEN v_a.rate_limited THEN 'rate limited — no invitation was created for this attempt'
    WHEN v_a.email_ok     THEN 'the transport accepted it' ||
                               coalesce(' (message id ' || v_a.message_id || ')', '')
    ELSE coalesce(v_a.email_error, 'the send failed with no reported reason')
  END;

  -- the in-app dashboard notice, once, with the diagnostic in the body
  IF v_first AND v_a.org_id IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    SELECT v_a.org_id, p.user_id, 'signup_email_help',
           coalesce(v_name, v_a.email) || ' never received their activation email',
           v_a.email || ' · ' || coalesce(v_a.path, 'sign') || ' · ' || v_diag,
           '/app/records?tab=leads'
      FROM profiles p
     WHERE p.org_id = v_a.org_id
       AND coalesce(p.role, 'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN');
  END IF;

  RETURN jsonb_build_object(
    'found', true, 'first', v_first, 'org_id', v_a.org_id,
    'email', v_a.email, 'name', v_name, 'phone', v_a.phone, 'path', v_a.path,
    'invitation_id', v_a.invitation_id, 'email_ok', v_a.email_ok,
    'rate_limited', v_a.rate_limited, 'error', v_a.email_error,
    'message_id', v_a.message_id, 'diagnostic', v_diag,
    'attempted_at', to_char(v_a.created_at, 'YYYY-MM-DD"T"HH24:MI:SSOF'));
END;
$$;


--
-- Name: clause_condition_met(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clause_condition_met(p_cond jsonb, v_fields jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key   text;
  v_raw   text;
  v_have  text[];
  v_v     jsonb;
  v_sub   jsonb;
BEGIN
  IF p_cond IS NULL THEN RETURN true; END IF;

  -- composite AND: every sub-condition must hold
  IF p_cond ? 'all' THEN
    FOR v_sub IN SELECT * FROM jsonb_array_elements(p_cond -> 'all') LOOP
      IF NOT clause_condition_met(v_sub, v_fields) THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  END IF;

  -- composite OR: any sub-condition holding is enough
  IF p_cond ? 'any' THEN
    FOR v_sub IN SELECT * FROM jsonb_array_elements(p_cond -> 'any') LOOP
      IF clause_condition_met(v_sub, v_fields) THEN RETURN true; END IF;
    END LOOP;
    RETURN false;
  END IF;

  v_key := p_cond ->> 'field_key';
  IF v_key IS NULL THEN RETURN true; END IF;
  v_raw := coalesce(v_fields ->> v_key, '');

  IF p_cond ? 'equals' THEN
    IF p_cond -> 'equals' ? v_raw THEN RETURN true; END IF;
  END IF;

  IF p_cond ? 'contains' THEN
    IF jsonb_typeof(to_jsonb(v_raw)) = 'array' THEN
      v_have := ARRAY(SELECT jsonb_array_elements_text(v_raw::jsonb));
    ELSE
      v_have := ARRAY(SELECT btrim(x) FROM regexp_split_to_table(v_raw, ',') x WHERE btrim(x) <> '');
    END IF;
    FOR v_v IN SELECT * FROM jsonb_array_elements(p_cond -> 'contains') LOOP
      IF (v_v #>> '{}') = ANY (v_have) THEN RETURN true; END IF;
    END LOOP;
  END IF;

  -- numeric gate: met when the field's parsed numeric value >= gte.
  -- Unparseable values (empty, "N/A") never meet it.
  IF p_cond ? 'gte' THEN
    BEGIN
      IF nullif(regexp_replace(v_raw, '[^0-9.]', '', 'g'), '')::numeric
         >= (p_cond ->> 'gte')::numeric THEN
        RETURN true;
      END IF;
    EXCEPTION WHEN others THEN
      NULL;
    END;
  END IF;

  RETURN false;
END;
$$;


--
-- Name: clause_cut_kept(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clause_cut_kept(p_cut text, v_fields jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_cut
    WHEN 'EVALUATION_PERIOD' THEN
      coalesce(v_fields->>'TXN.EVALUATION_START','') <> '' OR coalesce(v_fields->>'TXN.EVALUATION_END','') <> ''
    WHEN 'PARTIAL_LEASE' THEN
      lower(coalesce(v_fields->>'TXN.LEASE_TYPE','')) LIKE '%partial%'
    WHEN 'INSURANCE' THEN
      coalesce(v_fields->>'TXN.MORTALITY_INSURANCE_PARTY','') <> ''
      OR coalesce(v_fields->>'TXN.MAJOR_MEDICAL_INSURANCE_PARTY','') <> ''
      OR coalesce(v_fields->>'TXN.LOSS_OF_USE_INSURANCE_PARTY','') <> ''
    WHEN 'COMPETITION' THEN
      coalesce(v_fields->>'TXN.COMPETITION_TERMS','') <> ''
      OR coalesce(v_fields->>'TXN.COMPETITION_EXPENSES','') <> ''
    ELSE true
  END;
$$;


--
-- Name: cleanup_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_document(p_document_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc    documents%ROWTYPE;
  v_horse  text;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
BEGIN
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to remove a document';
  END IF;

  -- The guard is re-checked HERE, not merely consulted by the UI. A caller who
  -- reaches this function directly gets the same refusal the button does.
  -- NOT NULL is NULL, which is not TRUE, which skips the RAISE — so the guard is
  -- read through coalesce and the default is refusal.
  IF NOT coalesce(can_cleanup_document(p_document_id), false) THEN
    RAISE EXCEPTION 'this document cannot be removed: it is signed, executed, void, terminated, already removed, or you are not staff in this organisation';
  END IF;

  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;

  SELECT coalesce(h.nickname, h.registered_name) INTO v_horse
    FROM horses h WHERE h.id = v_doc.horse_id;

  UPDATE documents
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'document was already removed'; END IF;

  -- Every cleanup writes a status_events row naming what was removed and why.
  -- Written with a direct INSERT rather than log_status_event() on purpose: that
  -- helper would issue a second UPDATE on the documents row for any is_true_status
  -- code, which is exactly what aborts on a document with an orphaned contract_id.
  -- The (entity_type, status) foreign key to status_events_vocab still validates the
  -- code, so nothing is lost by not going through the helper.
  INSERT INTO status_events (org_id, entity_type, entity_id, status, detail, actor_user_id)
  VALUES (v_doc.org_id, 'document', p_document_id, 'cleaned_up',
          'Removed from the document integrity panel: '
            || coalesce(v_doc.display_code, p_document_id::text)
            || ' (' || coalesce(v_doc.title, 'untitled')
            || ', horse ' || coalesce(v_horse, 'none') || ')'
            || ' — status ' || coalesce(v_doc.status, '?')
            || ', no signatures. Reason: ' || v_reason,
          auth.uid());

  RETURN jsonb_build_object(
    'id',           p_document_id,
    'display_code', v_doc.display_code,
    'title',        v_doc.title,
    'horse',        v_horse,
    'removed_at',   now()
  );
END;
$$;


--
-- Name: client_can_read_horse(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_can_read_horse(h_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM horses h
    WHERE h.id = h_id
      AND h.deleted_at IS NULL
      AND (
        -- the OWNER always sees the record
        h.current_owner_contact_id = current_contact_id()
        -- everyone else only while the lease is active (term not ended)
        OR (
          (h.lease_end IS NULL OR h.lease_end >= current_date)
          AND (
            h.lessee_contact_id = current_contact_id()
            OR EXISTS (SELECT 1 FROM documents d
                        WHERE d.horse_id = h.id AND d.deleted_at IS NULL
                          AND d.contact_id = current_contact_id())
            OR EXISTS (SELECT 1 FROM contracts c
                        JOIN contract_parties cp ON cp.contract_id = c.id
                        WHERE contract_horse_id(c.id) = h.id AND c.deleted_at IS NULL
                          AND cp.contact_id = current_contact_id())
          )
        )
      )
  );
$$;


--
-- Name: client_lesson_plan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_lesson_plan(p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c    clients%ROWTYPE;
  v_plan lesson_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_c FROM clients WHERE id = p_client_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'client not found'; END IF;
  IF NOT coalesce(has_staff_access() AND v_c.org_id = current_org(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  v_plan := _current_lesson_plan(p_client_id);

  RETURN jsonb_build_object(
    'client_id',   p_client_id,
    'client_name', (SELECT nullif(btrim(coalesce(ct.first_name,'') || ' ' || coalesce(ct.last_name,'')), '')
                      FROM contacts ct WHERE ct.id = v_c.contact_id),
    -- staff surface: the private lane is included, and the screen labels it
    'plan',        _lesson_plan_json(v_plan, true),
    'next_up',     lesson_plan_next_up(v_plan.objectives),

    -- every retained version, newest first. This IS "the prior plan state is
    -- retained" — no separate history table, the superseded rows are the history.
    'versions', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', p.id, 'version', p.version, 'status', p.status,
               'focus', p.focus, 'objectives', p.objectives,
               'coach_notes', p.coach_notes,
               'created_at', p.created_at, 'superseded_at', p.superseded_at,
               'advanced_from_booking_id', p.advanced_from_booking_id,
               'advanced_from_starts_at',
                 (SELECT b.starts_at FROM bookings b WHERE b.id = p.advanced_from_booking_id))
             ORDER BY p.version DESC)
        FROM lesson_plans p WHERE p.client_id = p_client_id), '[]'::jsonb),

    -- the change log, read back to a human (D19)
    'log', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'at', se.created_at, 'code', se.status,
               'label', v.display_name, 'detail', se.detail)
             ORDER BY se.created_at DESC)
        FROM status_events se
        JOIN status_events_vocab v
          ON v.entity_type = se.entity_type AND v.code = se.status
       WHERE se.entity_type = 'lesson_plan'
         AND se.entity_id IN (SELECT p.id FROM lesson_plans p WHERE p.client_id = p_client_id)
      ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: client_monthly_plan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_monthly_plan(p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN _monthly_plan_for_client(p_client_id);
END;
$$;


--
-- Name: client_purchases(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_purchases(p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', pu.id, 'amount', pu.amount,
        'label', coalesce((SELECT pi.label FROM purchase_items pi WHERE pi.purchase_id = pu.id ORDER BY pi.created_at DESC LIMIT 1), 'Purchase'),
        'created_at', pu.created_at) ORDER BY pu.created_at DESC), '[]'::jsonb)
    FROM purchases pu
    JOIN clients cl ON cl.contact_id = pu.buyer_contact_id
    WHERE cl.id = p_client_id AND pu.org_id = current_org() AND pu.deleted_at IS NULL);
END;
$$;


--
-- Name: client_standing_slots(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_standing_slots(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
        'purchase_id',      pu.id,
        'purchase_item_id', pi.id,
        -- ⚠️ FIX2 §2: which ORDER this plan belongs to, and whether it is paid.
        'purchase_code',    pu.display_code,
        'purchase_status',  pu.status,
        'payment_status',   pu.payment_status,
        'purchase_amount',  pu.amount,
        'purchased_at',     pu.created_at,
        'offering_id',      o.id,
        'offering_name',    o.name,
        'segment',          o.segment,
        'weekly_frequency', o.weekly_frequency,
        'recurring_days',   coalesce(pi.config->'recurring_days', '[]'::jsonb),
        'recurring_times',  coalesce(pi.config->'recurring_times', '{}'::jsonb),
        'duration_minutes', coalesce((pi.config->>'duration_minutes')::int, 60),
        'chosen',           coalesce(jsonb_array_length(coalesce(pi.config->'recurring_days','[]'::jsonb)), 0) > 0
                            AND coalesce(pi.config->'recurring_times', '{}'::jsonb) <> '{}'::jsonb,
        'indefinite',       pi.plan_ends_on IS NULL,
        'plan_ends_on',     pi.plan_ends_on,
        'horizon_through',  pi.config->>'horizon_through',
        'booked_ahead',     (SELECT count(*) FROM bookings b
                              WHERE b.purchase_id = pu.id
                                AND b.offering_id = o.id
                                AND b.starts_at >= now()
                                AND b.status NOT IN ('cancelled','expired')))
      ORDER BY pu.created_at DESC, o.name)
      FROM purchase_items pi
      JOIN offerings o  ON o.id  = pi.offering_id AND o.config_kind = 'recurring'
      JOIN purchases pu ON pu.id = pi.purchase_id
     WHERE pu.deleted_at IS NULL
       AND pi.voided_at IS NULL
       AND pu.org_id = current_org()
       AND pu.buyer_contact_id = p_contact_id
       AND (pi.plan_ends_on IS NULL OR pi.plan_ends_on >= current_date)
  ), '[]'::jsonb);
END;
$$;


--
-- Name: clone_contract_template(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_contract_template(p_source_key text, p_new_key text, p_new_title text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_id     uuid;
  v_sections   int;
  v_clauses    int;
  v_fields     int;
BEGIN
  -- Deny by default. A NULL auth.uid() is NOT evidence of a trusted caller: the
  -- anon role has one too. Direct psql/migration access is identified by
  -- session_user (SECURITY DEFINER leaves session_user as the real session role).
  IF NOT coalesce(is_admin() OR session_user IN ('postgres', 'supabase_admin'), false) THEN
    RAISE EXCEPTION 'not authorized to clone a contract template';
  END IF;

  IF p_source_key IS NULL OR p_new_key IS NULL OR p_new_title IS NULL THEN
    RAISE EXCEPTION 'source key, new key and new title are all required';
  END IF;
  IF p_source_key = p_new_key THEN
    RAISE EXCEPTION 'cannot clone % onto itself', p_source_key;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM contract_templates WHERE template_key = p_source_key) THEN
    RAISE EXCEPTION 'source template % does not exist', p_source_key;
  END IF;

  -- Refuse rather than merge. Check the template row AND any stray def rows under
  -- the target key, so a half-cleaned key cannot be silently completed.
  IF EXISTS (SELECT 1 FROM contract_templates    WHERE template_key = p_new_key)
     OR EXISTS (SELECT 1 FROM contract_section_defs WHERE template_key = p_new_key)
     OR EXISTS (SELECT 1 FROM contract_clause_defs  WHERE template_key = p_new_key)
     OR EXISTS (SELECT 1 FROM contract_field_defs   WHERE template_key = p_new_key) THEN
    RAISE EXCEPTION 'template key % already exists; clone refuses to merge or overwrite', p_new_key;
  END IF;

  -- 1. the template row: new id (default), new key, new title, version reset to 1.
  --    Everything else copies verbatim; deleted_at/deleted_by start clean.
  INSERT INTO contract_templates (
    template_key, title, service_type, party_namespaces, body,
    version, active, wall_gating, contract_kind
  )
  SELECT p_new_key, p_new_title, t.service_type, t.party_namespaces, t.body,
         1, t.active, t.wall_gating, t.contract_kind
    FROM contract_templates t
   WHERE t.template_key = p_source_key
  RETURNING id INTO v_new_id;

  -- 2. sections
  INSERT INTO contract_section_defs (
    template_key, section_key, heading, sort_order, is_optional, cut_name, guidance
  )
  SELECT p_new_key, s.section_key, s.heading, s.sort_order, s.is_optional,
         s.cut_name, s.guidance
    FROM contract_section_defs s
   WHERE s.template_key = p_source_key
   ORDER BY s.sort_order, s.section_key;
  GET DIAGNOSTICS v_sections = ROW_COUNT;

  -- 3. clauses  (conditional_on copies by value; keys stay verbatim)
  INSERT INTO contract_clause_defs (
    template_key, section_key, clause_key, heading, body, clause_type, sort_order,
    is_optional, cut_name, conditional_on, guidance, render_as_subitem
  )
  SELECT p_new_key, c.section_key, c.clause_key, c.heading, c.body, c.clause_type,
         c.sort_order, c.is_optional, c.cut_name, c.conditional_on, c.guidance,
         c.render_as_subitem
    FROM contract_clause_defs c
   WHERE c.template_key = p_source_key
   ORDER BY c.section_key, c.sort_order, c.clause_key;
  GET DIAGNOSTICS v_clauses = ROW_COUNT;

  -- 4. fields  (parent_field_key / clause_key are intra-template references and
  --    stay verbatim so they resolve inside the clone)
  INSERT INTO contract_field_defs (
    template_key, field_key, parent_field_key, label, section, owner_role,
    input_kind, value_type, options, conditional_on, guidance, required,
    is_optional, responsibility, sort_order, format_type, clause_key,
    responsibility_kind, closed
  )
  SELECT p_new_key, f.field_key, f.parent_field_key, f.label, f.section, f.owner_role,
         f.input_kind, f.value_type, f.options, f.conditional_on, f.guidance, f.required,
         f.is_optional, f.responsibility, f.sort_order, f.format_type, f.clause_key,
         f.responsibility_kind, f.closed
    FROM contract_field_defs f
   WHERE f.template_key = p_source_key
   ORDER BY f.sort_order, f.field_key;
  GET DIAGNOSTICS v_fields = ROW_COUNT;

  -- 5. v1 of the clone, retained whole, so it does not start with a version
  --    number and no version to read (TASK-VERSIONSPINE).
  INSERT INTO contract_template_versions
    (template_key, version, title, body, composition, parent_version, edited_by)
  SELECT p_new_key, 1, p_new_title, t.body,
         capture_contract_template_composition(p_new_key), NULL, auth.uid()
    FROM contract_templates t WHERE t.template_key = p_new_key;

  RETURN jsonb_build_object(
    'template_id', v_new_id,
    'template_key', p_new_key,
    'source_key',  p_source_key,
    'sections', v_sections,
    'clauses',  v_clauses,
    'fields',   v_fields
  );
END;
$$;


--
-- Name: close_day(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_day(p_date date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); v_id uuid;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  INSERT INTO bookings (org_id, kind, status, all_day, starts_at, ends_at, notes, created_by)
    VALUES (v_org, 'block', 'unavailable', true,
            p_date::timestamptz, (p_date + 1)::timestamptz,
            coalesce(p_reason, 'Closed'), auth.uid())
    RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: comment_author_identity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comment_author_identity(p_document_id uuid) RETURNS TABLE(contact_id uuid, role text, label text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cid uuid; v_role text; v_label text; v_staff boolean; v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  v_cid   := current_contact_id();
  v_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  SELECT r INTO v_role FROM caller_party_roles(p_document_id) r LIMIT 1;
  IF v_role IS NULL AND v_staff THEN v_role := 'STAFF'; END IF;
  SELECT nullif(trim(concat_ws(' ', first_name, last_name)), '')
    INTO v_label FROM contacts WHERE id = v_cid;
  v_label := coalesce(v_label, CASE WHEN v_staff THEN 'Staff' ELSE 'A party' END);
  RETURN QUERY SELECT v_cid, v_role, v_label;
END;
$$;


--
-- Name: company_contact_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.company_contact_id() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid := current_org();
  v_marker   uuid;
  v_id       uuid;
  v_name     text;
BEGIN
  IF v_org IS NULL THEN RETURN NULL; END IF;

  -- (a) explicit marker, when set and the contact is still live
  SELECT o.company_contact_id INTO v_marker
    FROM organizations o
    JOIN contacts c ON c.id = o.company_contact_id AND c.deleted_at IS NULL
   WHERE o.id = v_org;
  IF v_marker IS NOT NULL THEN RETURN v_marker; END IF;

  -- (b) fallback: existing is_company lookup, then self-heal the marker
  SELECT id INTO v_id FROM contacts
   WHERE org_id = v_org AND is_company AND deleted_at IS NULL LIMIT 1;
  IF v_id IS NOT NULL THEN
    UPDATE organizations SET company_contact_id = v_id WHERE id = v_org;
    RETURN v_id;
  END IF;

  -- (c) create-from-BRAND-config, unchanged, then stamp the marker
  SELECT cv.value_text INTO v_name FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'BRAND' AND cv.key = 'NAME';
  IF v_name IS NULL THEN
    SELECT name INTO v_name FROM organizations WHERE id = v_org;
  END IF;
  v_name := coalesce(v_name, 'The Company');

  INSERT INTO contacts (org_id, first_name, last_name, is_company)
  VALUES (v_org, v_name, NULL, true)
  RETURNING id INTO v_id;

  UPDATE organizations SET company_contact_id = v_id WHERE id = v_org;
  RETURN v_id;
END;
$$;


--
-- Name: comped_credit_value(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comped_credit_value(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_from date := coalesce(p_from, date_trunc('month', current_date)::date);
  v_to   date := coalesce(p_to, (date_trunc('month', current_date) + interval '1 month - 1 day')::date);
  v_out  jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  WITH comps AS (
    SELECT pi.id,
           pi.offering_id,
           coalesce(o.name, pi.label)                              AS service,
           pi.quantity                                             AS qty,
           coalesce((pi.config->>'list_price')::numeric, 0)         AS list_price,
           coalesce((pi.config->>'list_price')::numeric, 0) * pi.quantity AS loss,
           coalesce(lc.credits_total, 0)                            AS credits,
           pu.created_at
      FROM purchase_items pi
      JOIN purchases pu ON pu.id = pi.purchase_id
 LEFT JOIN offerings  o  ON o.id = pi.offering_id
 LEFT JOIN lesson_credits lc ON lc.purchase_item_id = pi.id AND lc.deleted_at IS NULL
     WHERE pi.org_id = v_org
       AND pi.config->>'grant_mode' = 'comp'
       -- A reversed comp is not a loss: the credit was taken back.
       AND pi.voided_at IS NULL
       AND pu.deleted_at IS NULL
       AND pu.status <> 'void'
       AND pu.created_at >= v_from::timestamptz
       AND pu.created_at <  (v_to + 1)::timestamptz
  )
  SELECT jsonb_build_object(
    'from',           v_from,
    'to',             v_to,
    'comp_count',     count(*),
    'credits_comped', coalesce(sum(credits), 0)::int,
    'list_value',     coalesce(sum(loss), 0),
    'by_service', coalesce((
      SELECT jsonb_agg(x ORDER BY (x->>'list_value')::numeric DESC)
        FROM (SELECT jsonb_build_object(
                       'service',    service,
                       'comp_count', count(*),
                       'credits',    coalesce(sum(credits), 0)::int,
                       'list_value', coalesce(sum(loss), 0)) AS x
                FROM comps GROUP BY service) s), '[]'::jsonb))
    INTO v_out
    FROM comps;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION comped_credit_value(p_from date, p_to date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.comped_credit_value(p_from date, p_to date) IS 'TASK-CREDITGRANT: the dollar value of credits comped in a period, from the list price captured at comp time. Read by LessonCreditsPage today; dashboard zone B1 is the named follow-up reach point.';


--
-- Name: complete_deal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_deal(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal  deals%ROWTYPE;
  v_state jsonb;
  v_out   text;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF v_deal.status = 'complete' THEN
    RETURN jsonb_build_object('completed', false, 'message', 'this deal is already complete');
  END IF;
  IF v_deal.status <> 'pending' THEN
    RAISE EXCEPTION 'this deal is % and cannot be completed', v_deal.status;
  END IF;

  v_state := deal_completion_state(p_deal_id);
  IF NOT (v_state ->> 'can_complete')::boolean THEN
    SELECT string_agg(value, '; ') INTO v_out
      FROM jsonb_array_elements_text(v_state -> 'outstanding');
    RAISE EXCEPTION 'this deal is not finished — %', coalesce(v_out, 'requirements outstanding');
  END IF;

  UPDATE deals SET status = 'complete', completed_at = now() WHERE id = p_deal_id;
  UPDATE contracts SET status = 'executed' WHERE id = v_deal.contract_id AND status <> 'executed';

  RETURN jsonb_build_object('completed', true, 'completed_at', now());
END;
$$;


--
-- Name: complete_lesson_session(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_lesson_session(p_session_id uuid, p_debit_credit boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b         bookings%ROWTYPE;
  v_credit    uuid;
  v_remaining integer;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized to complete lessons';
  END IF;

  SELECT * INTO v_b FROM bookings
    WHERE id = p_session_id AND kind = 'lesson'
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown lesson session: %', p_session_id;
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role' AND v_b.org_id IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'lesson session % is not in your organization', p_session_id;
  END IF;
  IF v_b.status <> 'scheduled' THEN
    RAISE EXCEPTION 'only a SCHEDULED lesson can be completed (this one is %)', upper(v_b.status);
  END IF;

  UPDATE bookings SET status = 'completed' WHERE id = p_session_id;

  -- CREDITALIGN: a booking that already named its item keeps it. The shipped body
  -- always debited "the oldest row with a balance", which after a swap (or after
  -- book_open_slot honoured an explicit p_credit_id) could take the debit off a
  -- different purchase than the one the booking is charged against.
  IF p_debit_credit AND v_b.credit_id IS NOT NULL THEN
    v_credit := v_b.credit_id;
  ELSIF p_debit_credit THEN
    -- atomically decrement the OLDEST live, UNEXPIRED credit row with balance
    -- (row-locked SELECT ... FOR UPDATE — two concurrent completes can never
    -- double-spend), preferring the one that expires soonest.
    UPDATE lesson_credits lc
       SET credits_remaining = lc.credits_remaining - 1
     WHERE lc.id = (
        SELECT id FROM lesson_credits
        WHERE client_id = v_b.client_id AND org_id = v_b.org_id
          AND deleted_at IS NULL AND credits_remaining > 0
          AND (expires_at IS NULL OR expires_at > now())
        ORDER BY expires_at ASC NULLS LAST, purchased_at, created_at
        LIMIT 1
        FOR UPDATE
      )
     RETURNING lc.id INTO v_credit;

    IF v_credit IS NOT NULL THEN
      UPDATE bookings SET credit_id = v_credit WHERE id = p_session_id;
    END IF;
  END IF;

  IF p_debit_credit THEN
    SELECT coalesce(sum(credits_remaining), 0)::int INTO v_remaining
      FROM lesson_credits
      WHERE client_id = v_b.client_id AND org_id = v_b.org_id AND deleted_at IS NULL
        AND (expires_at IS NULL OR expires_at > now());
  END IF;

  RETURN jsonb_build_object(
    'session_id',        p_session_id,
    'status',            'COMPLETED',
    'debited',           v_credit IS NOT NULL,
    'credit_id',         v_credit,
    'credits_remaining', v_remaining
  );
END;
$$;


--
-- Name: FUNCTION complete_lesson_session(p_session_id uuid, p_debit_credit boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_lesson_session(p_session_id uuid, p_debit_credit boolean) IS 'Mark a SCHEDULED lesson COMPLETED and (by default) debit ONE credit from the client''s oldest lesson_credits row with balance (row-locked — no double-spend). Returns {status, debited, credit_id, credits_remaining}; a client with no credits still completes (debited:false).';


--
-- Name: compose_address(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_address(line1 text, line2 text, city text, state text, postal text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT NULLIF(array_to_string(ARRAY[
    NULLIF(trim(coalesce(line1,'') || ' ' || coalesce(line2,'')), ''),
    NULLIF(city, ''),
    NULLIF(trim(coalesce(state,'') || ' ' || coalesce(postal,'')), '')
  ], ', '), '');
$$;


--
-- Name: compose_contacts_list(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_contacts_list(p jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(string_agg(entry, '; ' ORDER BY ord), '')
    FROM (
      SELECT ord, btrim(concat_ws(', ',
               nullif(btrim(concat_ws(' ', nullif(btrim(r->>'first'),''), nullif(btrim(r->>'last'),''))), ''),
               nullif(btrim(r->>'phone'),''),
               nullif(btrim(r->>'email'),'')
             )) AS entry
        FROM jsonb_array_elements(coalesce(p->'coOwners','[]'::jsonb)) WITH ORDINALITY AS t(r, ord)
    ) q
   WHERE coalesce(nullif(entry,''),'') <> '';
$$;


--
-- Name: compose_field_prose(text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_field_prose(p_format text, p_structured jsonb, p_label text, p_value text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  s jsonb := coalesce(p_structured, '{}'::jsonb);
  v_out text; v_party text; v_prov jsonb; v_manage jsonb; v_split jsonb;
  v_parts text[]; v_e jsonb; v_sel int; v_opt jsonb; v_amt text;
  v_num numeric;
BEGIN
  IF p_structured IS NULL OR p_structured = '{}'::jsonb THEN RETURN coalesce(p_value, ''); END IF;
  CASE p_format
    WHEN 'med_schedule' THEN v_out := compose_med_schedule(s);
    WHEN 'installment_schedule' THEN v_out := compose_installment_schedule(s);
    WHEN 'incident_list' THEN v_out := compose_incident_list(s);
    WHEN 'reveal_text' THEN v_out := compose_reveal_text(s, p_value);
    WHEN 'yesno' THEN
      v_out := CASE upper(coalesce(s->>'value', p_value, '')) WHEN 'YES' THEN 'Yes' WHEN 'NO' THEN 'No' ELSE coalesce(p_value,'') END;
    WHEN 'contact' THEN
      v_parts := ARRAY[]::text[];
      IF coalesce(s->>'name','')    <> '' THEN v_parts := v_parts || (s->>'name'); END IF;
      IF coalesce(s->>'company','') <> '' THEN v_parts := v_parts || (s->>'company'); END IF;
      IF coalesce(s->>'line1','')   <> '' THEN v_parts := v_parts || (s->>'line1'); END IF;
      IF coalesce(s->>'city','') <> '' OR coalesce(s->>'state','') <> '' OR coalesce(s->>'postal','') <> '' THEN
        v_parts := v_parts || btrim(concat_ws(' ', concat_ws(', ', nullif(s->>'city',''), nullif(s->>'state','')), nullif(s->>'postal','')));
      END IF;
      IF coalesce(s->>'phone','')   <> '' THEN v_parts := v_parts || (s->>'phone'); END IF;
      IF coalesce(s->>'email','')   <> '' THEN v_parts := v_parts || (s->>'email'); END IF;
      IF coalesce(s->>'website','') <> '' THEN v_parts := v_parts || (s->>'website'); END IF;
      v_out := array_to_string(v_parts, ', ');
      IF v_out = '' THEN v_out := needs(coalesce(p_label,'contact')); END IF;
    WHEN 'person' THEN
      v_parts := ARRAY[]::text[];
      IF coalesce(s->>'name','')    <> '' THEN v_parts := v_parts || (s->>'name'); END IF;
      IF coalesce(s->>'company','') <> '' THEN v_parts := v_parts || (s->>'company'); END IF;
      IF coalesce(s->>'phone','')   <> '' THEN v_parts := v_parts || (s->>'phone'); END IF;
      IF coalesce(s->>'email','')   <> '' THEN v_parts := v_parts || (s->>'email'); END IF;
      v_out := array_to_string(v_parts, ', ');
      IF v_out = '' THEN v_out := needs(coalesce(p_label,'contact')); END IF;
    WHEN 'address' THEN
      v_out := compose_address(s->>'line1', s->>'line2', s->>'city', s->>'state', s->>'postal');
      IF coalesce(v_out,'') = '' THEN v_out := needs(coalesce(p_label,'address')); END IF;
    WHEN 'location' THEN
      DECLARE v_lname text := btrim(coalesce(s->>'name','')); v_laddr text := btrim(coalesce(compose_address(s->>'line1', s->>'line2', s->>'city', s->>'state', s->>'postal'),'')); BEGIN
        IF v_laddr <> '' AND v_lname <> '' AND lower(v_laddr) LIKE lower(v_lname) || '%' THEN
          v_out := v_laddr;   -- address already contains the name: print it once
        ELSE
          v_out := nullif(btrim(concat_ws(' — ', nullif(v_lname,''), nullif(v_laddr,''))), '');
        END IF;
      END;
      IF coalesce(v_out,'') = '' THEN v_out := needs(coalesce(p_label,'location')); END IF;
    WHEN 'percent_split' THEN
      v_split := s->'parties'; v_parts := ARRAY[]::text[];
      IF v_split IS NOT NULL THEN
        FOR v_e IN SELECT * FROM jsonb_array_elements(v_split) LOOP
          v_parts := v_parts || (party_label(v_e->>'party') || ' ' || coalesce(v_e->>'pct','?') || '%');
        END LOOP;
      END IF;
      v_out := array_to_string(v_parts, ', ');
      IF coalesce(nullif(s->>'note',''),'') <> '' THEN v_out := btrim(v_out || ' (' || (s->>'note') || ')'); END IF;
      IF v_out = '' THEN v_out := needs(coalesce(p_label,'split')); END IF;
    WHEN 'share_amount' THEN
      v_num := nullif(regexp_replace(coalesce(s->>'amount',''), '[^0-9.]', '', 'g'), '')::numeric;
      IF v_num IS NULL THEN
        v_out := needs(coalesce(p_label, 'share'));
      ELSIF upper(coalesce(s->>'unit','PCT')) = 'USD' THEN
        v_out := fmt_money(v_num);
      ELSE
        v_out := rtrim(rtrim(to_char(v_num, 'FM999990.99'), '0'), '.') || '%';
      END IF;
    WHEN 'fee_schedule' THEN
      v_parts := ARRAY[]::text[];
      IF coalesce(nullif(btrim(s->>'initial_due'),''),'') <> '' THEN
        DECLARE v_init text := btrim(s->>'initial_due');
        BEGIN
          v_num := money_numeric(v_init);
          IF v_num IS NOT NULL THEN v_init := fmt_money(v_num); END IF;
          IF coalesce(nullif(btrim(s->>'initial_terms'),''),'') <> '' THEN
            v_parts := v_parts || ('Initial payment due: ' || v_init || ' — ' || btrim(s->>'initial_terms') || '.');
          ELSE
            v_parts := v_parts || ('Initial payment due: ' || v_init || '.');
          END IF;
        END;
      END IF;
      v_sel := nullif(s->>'selected','')::int;
      IF v_sel IS NULL AND s->'options' IS NOT NULL AND jsonb_array_length(s->'options') = 1 THEN v_sel := 0; END IF;
      IF v_sel IS NULL AND s->'options' IS NOT NULL AND jsonb_array_length(s->'options') > 1 THEN
        v_parts := v_parts || needs(coalesce(p_label,'lease fee') || ' — no option chosen');
      END IF;
      IF v_sel IS NOT NULL AND s->'options' IS NOT NULL AND jsonb_array_length(s->'options') > v_sel THEN
        v_opt := (s->'options') -> v_sel; v_amt := btrim(coalesce(v_opt->>'amount',''));
        IF v_amt <> '' THEN
          v_num := money_numeric(v_amt);
          IF v_num IS NOT NULL THEN v_amt := fmt_money(v_num);
          ELSIF left(v_amt,1) <> '$' THEN v_amt := '$' || v_amt; END IF;
          IF coalesce(nullif(btrim(v_opt->>'notes'),''),'') <> '' THEN
            v_out := v_amt || ' ' || btrim(v_opt->>'notes');
            IF right(v_out, 1) <> '.' THEN v_out := v_out || '.'; END IF;
          ELSE
            v_out := v_amt || '.';
          END IF;
          v_parts := v_parts || v_out;
        END IF;
      END IF;
      v_out := array_to_string(v_parts, ' ');
      IF v_out = '' THEN v_out := needs(coalesce(p_label,'lease fee')); END IF;
    WHEN 'party' THEN
      v_party := s->>'party';
      IF coalesce(v_party,'') = '' THEN v_out := needs(coalesce(p_label,'responsible party'));
      ELSIF v_party = 'CARE_PROVIDER' THEN
        v_prov := s->'provider'; v_out := party_label('CARE_PROVIDER');
        IF coalesce(v_prov->>'name','') <> '' THEN v_out := v_out || ' (' || compose_field_prose('person', v_prov, p_label, NULL) || ')';
        ELSE v_out := v_out || ' (' || needs('care provider contact') || ')'; END IF;
      ELSIF v_party = 'OTHER' THEN v_out := coalesce(nullif(s->>'note',''), needs(coalesce(p_label,'arrangement')));
      ELSIF v_party = 'SHARED' THEN v_out := compose_field_prose('percent_split', s, p_label, NULL);
      ELSE v_out := party_label(v_party); END IF;
    WHEN 'pair' THEN
      v_manage := s->'manage'; IF v_manage IS NULL THEN v_manage := s; END IF;
      v_out := compose_field_prose('party', v_manage, p_label, NULL);
    WHEN 'week_grid' THEN v_out := compose_week_grid(s);
    WHEN 'contacts_list' THEN v_out := compose_contacts_list(s);
    WHEN 'certify' THEN
      v_out := CASE WHEN upper(coalesce(s->>'value', p_value, '')) = 'YES'
                    THEN coalesce(p_label, '') ELSE '' END;
    WHEN 'cost_split' THEN
      DECLARE
        v_mode text := upper(coalesce(s->>'mode',''));
        v_bp text := nullif(btrim(coalesce(s#>>'{pct,buyer}','')),'');
        v_sp text := nullif(btrim(coalesce(s#>>'{pct,seller}','')),'');
        v_bu text := nullif(btrim(coalesce(s#>>'{usd,buyer,amount}','')),'');
        v_su text := nullif(btrim(coalesce(s#>>'{usd,seller,amount}','')),'');
        v_br boolean := coalesce((s#>>'{usd,buyer,remaining}')::boolean, false);
        v_sr boolean := coalesce((s#>>'{usd,seller,remaining}')::boolean, false);
        v_bt text; v_st text; v_n numeric;
        fmt_pct text; fmt_usd text;
        v_party text := upper(coalesce(s->>'party','' ));
      BEGIN
        -- the GATE: an explicit Buyer / Seller is a single-party allocation; only
        -- Split (or a legacy value with no party but filled split sets) uses the %/$.
        IF v_party = 'BUYER' THEN v_out := party_label('BUYER');
        ELSIF v_party = 'SELLER' THEN v_out := party_label('SELLER');
        ELSIF v_party <> '' AND v_party <> 'SPLIT' THEN v_out := needs(coalesce(p_label,'allocation'));
        ELSIF v_mode = 'PCT' THEN
          -- normalise: if only one side given, the other is 100 - it
          IF v_bp IS NOT NULL AND v_sp IS NULL THEN v_sp := (100 - v_bp::numeric)::text; END IF;
          IF v_sp IS NOT NULL AND v_bp IS NULL THEN v_bp := (100 - v_sp::numeric)::text; END IF;
          IF v_bp IS NULL AND v_sp IS NULL THEN v_out := needs(coalesce(p_label,'allocation'));
          ELSIF coalesce(v_bp,'0')::numeric = 100 THEN v_out := party_label('BUYER');
          ELSIF coalesce(v_sp,'0')::numeric = 100 THEN v_out := party_label('SELLER');
          ELSIF coalesce(v_bp,'0')::numeric = 0 THEN v_out := party_label('SELLER');
          ELSIF coalesce(v_sp,'0')::numeric = 0 THEN v_out := party_label('BUYER');
          ELSE
            -- format each % without mangling whole numbers: trim_scale drops only the
            -- insignificant decimal zeros (60.0 -> 60, 60.50 -> 60.5, 60 -> 60).
            fmt_pct := trim_scale(v_sp::numeric)::text;
            fmt_usd := trim_scale(v_bp::numeric)::text;
            v_out := party_label('SELLER') || ' as to ' || fmt_pct || '% and '
                  || party_label('BUYER')  || ' as to ' || fmt_usd || '%';
          END IF;
        ELSIF v_mode = 'USD' THEN
          -- compose each side's phrase: a dollar figure, or "the remaining cost"
          IF v_br THEN v_bt := 'the remaining cost';
          ELSIF v_bu IS NOT NULL THEN v_n := money_numeric(v_bu); v_bt := CASE WHEN v_n IS NOT NULL THEN fmt_money(v_n) ELSE '$'||v_bu END; END IF;
          IF v_sr THEN v_st := 'the remaining cost';
          ELSIF v_su IS NOT NULL THEN v_n := money_numeric(v_su); v_st := CASE WHEN v_n IS NOT NULL THEN fmt_money(v_n) ELSE '$'||v_su END; END IF;
          IF v_bt IS NULL AND v_st IS NULL THEN v_out := needs(coalesce(p_label,'allocation'));
          ELSIF v_bt IS NOT NULL AND v_st IS NULL THEN v_out := party_label('BUYER') || ' as to ' || v_bt;
          ELSIF v_st IS NOT NULL AND v_bt IS NULL THEN v_out := party_label('SELLER') || ' as to ' || v_st;
          ELSE v_out := party_label('SELLER') || ' as to ' || v_st || ' and ' || party_label('BUYER') || ' as to ' || v_bt;
          END IF;
        ELSE
          v_out := needs(coalesce(p_label,'allocation'));
        END IF;
      END;
    ELSE
      v_out := coalesce(nullif(s->>'value',''), nullif(s->>'text',''), p_value, '');
  END CASE;
  RETURN coalesce(v_out, '');
END;
$_$;


--
-- Name: compose_incident_list(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_incident_list(p_structured jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE it jsonb; lines text[] := ARRAY[]::text[]; part text; v_when text; v_start text; v_end text;
BEGIN
  IF p_structured IS NULL OR coalesce(jsonb_array_length(p_structured->'incidents'),0) = 0 THEN
    RETURN needs('disclosures');
  END IF;
  FOR it IN SELECT * FROM jsonb_array_elements(p_structured->'incidents') LOOP
    part := btrim(coalesce(it->>'category',''));
    IF part = '' THEN part := 'Disclosure'; END IF;
    v_start := btrim(coalesce(it->>'start',''));
    v_end   := btrim(coalesce(it->>'end',''));
    v_when := '';
    IF v_start <> '' AND v_end <> '' THEN
      v_when := v_start || ' to ' || CASE WHEN lower(v_end) = 'present' THEN 'present' ELSE v_end END;
    ELSIF v_start <> '' THEN
      v_when := v_start;
    END IF;
    IF v_when <> '' THEN part := part || ' (' || v_when || ')'; END IF;
    IF coalesce(nullif(btrim(it->>'detail'),''),'') <> '' THEN
      part := part || ': ' || btrim(it->>'detail');
    END IF;
    IF right(part,1) NOT IN ('.','!','?') THEN part := part || '.'; END IF;
    lines := lines || part;
  END LOOP;
  IF coalesce(array_length(lines,1),0) = 0 THEN RETURN needs('disclosures'); END IF;
  RETURN array_to_string(lines, E'\n');
END;
$$;


--
-- Name: compose_installment_schedule(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_installment_schedule(p_structured jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE it jsonb; lines text[] := ARRAY[]::text[]; part text; v_num numeric; v_amt text;
BEGIN
  IF p_structured IS NULL OR coalesce(jsonb_array_length(p_structured->'rows'),0) = 0 THEN
    RETURN needs('installment schedule');
  END IF;
  FOR it IN SELECT * FROM jsonb_array_elements(p_structured->'rows') LOOP
    v_amt := btrim(coalesce(it->>'amount',''));
    IF v_amt = '' THEN CONTINUE; END IF;
    v_num := money_numeric(v_amt);
    IF v_num IS NOT NULL THEN v_amt := fmt_money(v_num);
    ELSIF left(v_amt,1) <> '$' THEN v_amt := '$' || v_amt; END IF;
    part := v_amt;
    IF coalesce(nullif(btrim(it->>'due'),''),'') <> '' THEN
      part := part || ' due ' || btrim(it->>'due');
    END IF;
    IF coalesce(nullif(btrim(it->>'notes'),''),'') <> '' THEN
      part := part || ' (' || btrim(it->>'notes') || ')';
    END IF;
    lines := lines || part;
  END LOOP;
  IF coalesce(array_length(lines,1),0) = 0 THEN RETURN needs('installment schedule'); END IF;
  RETURN array_to_string(lines, '; ') || '.';
END;
$_$;


--
-- Name: compose_insurance_allocation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_insurance_allocation(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_pref text; v_noun text;
  v_cost_raw text; v_resp text; v_lr text; v_le text;
  v_cost numeric; v_lr_pct numeric; v_le_pct numeric;
  v_lr_amt numeric; v_le_amt numeric;
  v_alloc text; v_split text;
  fn_num CONSTANT text := '[^0-9.]';
BEGIN
  FOREACH v_pref IN ARRAY ARRAY['MORT','MED'] LOOP
    v_noun := CASE v_pref WHEN 'MORT' THEN 'the policy' ELSE 'the medical component' END;

    SELECT coalesce(trim(value),'') INTO v_cost_raw FROM contract_fields
     WHERE document_id = p_document_id AND field_key = 'TXN.'||v_pref||'_POLICY_COST';
    CONTINUE WHEN NOT FOUND;

    SELECT coalesce(trim(value),'') INTO v_resp FROM contract_fields
     WHERE document_id = p_document_id AND field_key = 'TXN.'||v_pref||'_COST_RESP';
    SELECT coalesce(trim(value),'') INTO v_lr FROM contract_fields
     WHERE document_id = p_document_id AND field_key = 'TXN.'||v_pref||'_COST_SPLIT_LESSOR';
    SELECT coalesce(trim(value),'') INTO v_le FROM contract_fields
     WHERE document_id = p_document_id AND field_key = 'TXN.'||v_pref||'_COST_SPLIT_LESSEE';

    v_alloc := ''; v_split := '';
    v_lr_pct := NULL; v_le_pct := NULL; v_lr_amt := NULL; v_le_amt := NULL;
    v_cost := nullif(regexp_replace(v_cost_raw, fn_num, '', 'g'), '')::numeric;

    -- classify each share as a percentage or a money amount
    IF v_lr LIKE '%\%%' THEN
      v_lr_pct := nullif(regexp_replace(v_lr, fn_num, '', 'g'), '')::numeric;
    ELSE
      v_lr_amt := nullif(regexp_replace(v_lr, fn_num, '', 'g'), '')::numeric;
    END IF;
    IF v_le LIKE '%\%%' THEN
      v_le_pct := nullif(regexp_replace(v_le, fn_num, '', 'g'), '')::numeric;
    ELSE
      v_le_amt := nullif(regexp_replace(v_le, fn_num, '', 'g'), '')::numeric;
    END IF;

    -- ── the split SENTENCE. Composed so a one-sided entry still reads as a
    --    complete sentence: the other side is "the remaining balance".
    IF v_resp = 'SPLIT' THEN
      IF (v_lr_pct IS NOT NULL OR v_le_pct IS NOT NULL)
         AND v_lr_amt IS NULL AND v_le_amt IS NULL THEN
        v_lr_pct := coalesce(v_lr_pct, 100 - v_le_pct);
        v_le_pct := coalesce(v_le_pct, 100 - v_lr_pct);
        IF v_lr_pct >= 0 AND v_le_pct >= 0 THEN
          v_split := rtrim(to_char(v_lr_pct,'FM999990.99'),'.')||'% paid by Lessor and '
                   ||rtrim(to_char(v_le_pct,'FM999990.99'),'.')||'% paid by Lessee.';
        END IF;
      ELSIF v_lr_amt IS NOT NULL AND v_le_amt IS NOT NULL THEN
        v_split := '$'||to_char(v_lr_amt,'FM999,999,990.00')||' paid by Lessor and $'
                 ||to_char(v_le_amt,'FM999,999,990.00')||' paid by Lessee.';
      ELSIF v_lr_amt IS NOT NULL THEN
        v_split := '$'||to_char(v_lr_amt,'FM999,999,990.00')
                 ||' paid by Lessor and the remaining balance paid by Lessee.';
      ELSIF v_le_amt IS NOT NULL THEN
        v_split := '$'||to_char(v_le_amt,'FM999,999,990.00')
                 ||' paid by Lessee and the remaining balance paid by Lessor.';
      END IF;
    END IF;

    -- ── the allocation LINE, only once a policy cost is known
    IF v_cost IS NOT NULL AND v_cost > 0 THEN
      IF v_resp = 'LESSOR_FULL' THEN
        v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
                 ||', payable in full by Lessor.';

      ELSIF v_resp = 'LESSEE' THEN
        v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
                 ||', payable in full by Lessee.';

      ELSIF v_resp = 'SPLIT' THEN
        IF v_lr_pct IS NOT NULL AND v_le_pct IS NOT NULL
           AND v_lr_amt IS NULL AND v_le_amt IS NULL
           AND v_lr_pct >= 0 AND v_le_pct >= 0 THEN
          v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
            ||'. Lessor''s share: $'||to_char(round(v_cost*v_lr_pct/100, 2),'FM999,999,990.00')
            ||' ('||rtrim(to_char(v_lr_pct,'FM999990.99'),'.')||'%)'
            ||'. Lessee''s share: $'||to_char(round(v_cost*v_le_pct/100, 2),'FM999,999,990.00')
            ||' ('||rtrim(to_char(v_le_pct,'FM999990.99'),'.')||'%).';

        ELSIF v_lr_amt IS NOT NULL AND v_le_amt IS NOT NULL THEN
          v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
            ||'. Lessor''s share: $'||to_char(v_lr_amt,'FM999,999,990.00')
            ||'. Lessee''s share: $'||to_char(v_le_amt,'FM999,999,990.00')||'.';

        ELSIF v_lr_amt IS NOT NULL AND v_le_amt IS NULL AND v_lr_amt <= v_cost THEN
          v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
            ||'. Lessor''s share: $'||to_char(v_lr_amt,'FM999,999,990.00')
            ||'. Lessee''s share: $'||to_char(v_cost-v_lr_amt,'FM999,999,990.00')
            ||' (the remaining balance).';

        ELSIF v_le_amt IS NOT NULL AND v_lr_amt IS NULL AND v_le_amt <= v_cost THEN
          v_alloc := 'Cost of '||v_noun||': $'||to_char(v_cost,'FM999,999,990.00')
            ||'. Lessee''s share: $'||to_char(v_le_amt,'FM999,999,990.00')
            ||'. Lessor''s share: $'||to_char(v_cost-v_le_amt,'FM999,999,990.00')
            ||' (the remaining balance).';
        END IF;
      END IF;
    END IF;

    UPDATE contract_fields SET value = v_alloc, updated_at = now()
     WHERE document_id = p_document_id
       AND field_key = 'TXN.'||v_pref||'_COST_ALLOCATION'
       AND coalesce(value,'') IS DISTINCT FROM v_alloc;

    UPDATE contract_fields SET value = v_split, updated_at = now()
     WHERE document_id = p_document_id
       AND field_key = 'TXN.'||v_pref||'_COST_SPLIT_TEXT'
       AND coalesce(value,'') IS DISTINCT FROM v_split;
  END LOOP;
END;
$_$;


--
-- Name: compose_med_schedule(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_med_schedule(p_structured jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE it jsonb; lines text[] := ARRAY[]::text[]; part text; roles text[];
BEGIN
  IF p_structured IS NULL OR coalesce(jsonb_array_length(p_structured->'medItems'),0) = 0 THEN
    RETURN needs('medications and supplements');
  END IF;
  FOR it IN SELECT * FROM jsonb_array_elements(p_structured->'medItems') LOOP
    part := btrim(coalesce(it->>'name',''));
    IF coalesce(nullif(btrim(it->>'dose'),''),'') <> '' THEN part := part || ' — ' || btrim(it->>'dose'); END IF;
    IF coalesce(nullif(btrim(it->>'schedule'),''),'') <> '' THEN part := part || ', ' || btrim(it->>'schedule'); END IF;

    roles := ARRAY[]::text[];
    -- administering / ordering / cost, each shown only when set
    IF coalesce(nullif(btrim(it->>'administer_party'),''),'') <> '' THEN
      roles := roles || ('administered by ' || med_party_who(it->>'administer_party', it->>'administer_note'));
    END IF;
    IF coalesce(nullif(btrim(it->>'order_party'),''),'') <> '' THEN
      roles := roles || ('ordered by ' || med_party_who(it->>'order_party', it->>'order_note'));
    END IF;
    IF coalesce(nullif(btrim(it->>'cost_party'),''),'') <> '' THEN
      roles := roles || ('cost paid by ' || med_party_who(it->>'cost_party', it->>'cost_note'));
    END IF;

    IF coalesce(array_length(roles,1),0) > 0 THEN
      part := part || ' (' || array_to_string(roles, '; ') || ')';
    ELSIF coalesce(nullif(btrim(it->>'party'),''),'') <> '' THEN
      -- legacy single-party fallback
      part := part || ' (responsible: ' || med_party_who(it->>'party', it->>'party_note') || ')';
    END IF;

    IF btrim(part) <> '' THEN lines := lines || part; END IF;
  END LOOP;
  RETURN array_to_string(lines, E'\n');
END;
$$;


--
-- Name: compose_pair_cost(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_pair_cost(p_manage_structured jsonb, p_label text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  s jsonb := coalesce(p_manage_structured, '{}'::jsonb);
  v_cost jsonb := s->'cost';
  v_manage jsonb := coalesce(s->'manage', s);
BEGIN
  -- default (or explicit same_as_manage) → the managing party covers the cost
  IF v_cost IS NULL OR coalesce((v_cost->>'same_as_manage')::boolean, true) THEN
    IF coalesce(v_manage->>'party','') = '' THEN RETURN needs('who covers the cost'); END IF;
    RETURN 'borne by ' || party_label(v_manage->>'party');
  END IF;
  -- diverged: a specific party or a shared split
  IF coalesce(v_cost->>'party','') = 'SHARED' THEN
    RETURN 'shared — ' || compose_field_prose('percent_split', v_cost, p_label, NULL);
  ELSIF coalesce(v_cost->>'party','') <> '' THEN
    RETURN 'borne by ' || party_label(v_cost->>'party');
  END IF;
  RETURN needs('who covers the cost');
END;
$$;


--
-- Name: compose_prelease_fee_phrase(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_prelease_fee_phrase(p_timing text, p_eval_type text, p_eval_enabled text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_timing = 'BEFORE_DELIVERY' THEN ''
    WHEN p_timing = 'EVAL_PERIOD' AND p_eval_type = 'FIXED' THEN ', except fees for usage that has already occurred'
    WHEN p_timing = 'EVAL_PERIOD' THEN ''  -- included-at-no-charge period: no fee phrase
    WHEN p_timing = 'DATE' THEN ', except fees for usage that has already occurred'
    ELSE '' END;
$$;


--
-- Name: compose_reveal_text(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_reveal_text(p_structured jsonb, p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN coalesce(nullif(btrim(coalesce(p_structured->>'text', p_value, '')),''),'') = '' THEN ''
    ELSE 'Lessee is prohibited from using these items: ' || btrim(coalesce(p_structured->>'text', p_value)) || '.'
  END;
$$;


--
-- Name: compose_vet_address(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_vet_address(p_line1 text, p_city text, p_state text, p_postal text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(concat_ws(', ',
           nullif(btrim(coalesce(p_line1,'')),''),
           nullif(btrim(coalesce(p_city,'')),''),
           nullif(btrim(concat_ws(' ',
             nullif(btrim(coalesce(p_state,'')),''),
             nullif(btrim(coalesce(p_postal,'')),''))),'')), '');
$$;


--
-- Name: FUNCTION compose_vet_address(p_line1 text, p_city text, p_state text, p_postal text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compose_vet_address(p_line1 text, p_city text, p_state text, p_postal text) IS 'One-line vet address from its parts, skipping empties so a partial address never renders with stray separators. Mirrors compose_address() for contacts.';


--
-- Name: compose_week_grid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compose_week_grid(p jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_party text; v_days jsonb; v_lines text[] := ARRAY[]::text[];
  v_daylist text; w jsonb; v_win text[] := ARRAY[]::text[]; v_out text;
  v_order text[] := ARRAY['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
BEGIN
  IF p IS NULL OR jsonb_typeof(p) <> 'object' THEN RETURN ''; END IF;

  FOR v_party IN SELECT jsonb_array_elements_text(coalesce(p->'parties','[]'::jsonb)) LOOP
    v_days := coalesce(p->'days'->v_party, '[]'::jsonb);
    SELECT string_agg(d, ', ' ORDER BY array_position(v_order, d))
      INTO v_daylist FROM jsonb_array_elements_text(v_days) AS d;
    IF coalesce(nullif(btrim(v_daylist),''),'') <> '' THEN
      v_lines := v_lines || (v_party || ': ' || v_daylist);
    END IF;
  END LOOP;

  IF coalesce(array_length(v_lines,1),0) = 0 THEN RETURN ''; END IF;
  v_out := array_to_string(v_lines, '; ') || '.';

  IF coalesce((p->>'timeframes')::boolean, false)
     AND jsonb_array_length(coalesce(p->'windows','[]'::jsonb)) > 0 THEN
    FOR w IN SELECT * FROM jsonb_array_elements(p->'windows') LOOP
      IF coalesce(w->>'start','') <> '' AND coalesce(w->>'end','') <> '' THEN
        v_win := v_win || (fmt_time12(w->>'start') || ' – ' || fmt_time12(w->>'end'));
      END IF;
    END LOOP;
    IF coalesce(array_length(v_win,1),0) > 0 THEN
      v_out := v_out || ' Time windows: ' || array_to_string(v_win, ', ') || '.';
    END IF;
  END IF;
  RETURN v_out;
END;
$$;


--
-- Name: compute_execution_hash(text, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_execution_hash(p_body text, p_signer uuid, p_typed text, p_signed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN encode(digest(convert_to(
      coalesce(p_body, '') || '|' || p_signer::text || '|'
        || coalesce(p_typed, '') || '|' || p_signed_at::text,
      'UTF8'), 'sha256'), 'hex');
EXCEPTION WHEN undefined_function OR invalid_schema_name THEN
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION compute_execution_hash(p_body text, p_signer uuid, p_typed text, p_signed_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_execution_hash(p_body text, p_signer uuid, p_typed text, p_signed_at timestamp with time zone) IS 'Tamper-evidence hash for an EXECUTED document: hex sha256 of merged_body||''|''||signer_contact_id||''|''||typed_name||''|''||signed_at::text. NULL when pgcrypto''s digest() is unavailable (feature-detected).';


--
-- Name: compute_lease_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_lease_usage(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_primary int; v_total int;
BEGIN
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized'; END IF;
  -- primary lessee's day count (TXN.DAYS_USED)
  SELECT coalesce(array_length(array_remove(
           string_to_array(regexp_replace(coalesce(value,''), '\s','','g'), ','), ''), 1), 0)
    INTO v_primary FROM contract_fields WHERE document_id = p_document_id AND field_key = 'TXN.DAYS_USED';
  v_primary := coalesce(v_primary, 0);

  SELECT v_primary + coalesce(sum(coalesce(array_length(array_remove(
           string_to_array(regexp_replace(coalesce(days_used,''), '\s','','g'), ','), ''), 1), 0)), 0)
    INTO v_total FROM lease_participants WHERE document_id = p_document_id;
  IF coalesce(v_total,0) = 0 THEN RETURN jsonb_build_object('computed', 0); END IF;

  UPDATE lease_participants lp
     SET usage_pct = round(
           coalesce(array_length(array_remove(
             string_to_array(regexp_replace(coalesce(lp.days_used,''), '\s','','g'), ','), ''), 1), 0)::numeric
           / v_total * 100, 2)
   WHERE lp.document_id = p_document_id AND lp.usage_pct IS NULL AND lp.days_used IS NOT NULL;
  RETURN jsonb_build_object('computed', 1);
END;
$$;


--
-- Name: config_required_missing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.config_required_missing(p_org uuid) RETURNS TABLE(namespace text, key text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ck.namespace, ck.key
    FROM config_keys ck
    WHERE ck.required
      AND NOT EXISTS (
        SELECT 1 FROM config_values cv
        WHERE cv.org_id = p_org AND cv.namespace = ck.namespace AND cv.key = ck.key
          AND (cv.value_text IS NOT NULL OR cv.value_num IS NOT NULL OR cv.value_json IS NOT NULL)
      )
      -- typed business_config-backed ORG.* keys count as set when the column is filled
      AND NOT (
        ck.namespace = 'ORG'
        AND EXISTS (
          SELECT 1 FROM business_config bc WHERE bc.org_id = p_org AND (
            (ck.key = 'LEGAL_NAME'      AND bc.legal_entity_name IS NOT NULL) OR
            (ck.key = 'SIGNATORY_NAME'  AND bc.signatory_name    IS NOT NULL) OR
            (ck.key = 'SIGNATORY_TITLE' AND bc.signatory_title   IS NOT NULL) OR
            (ck.key = 'ADDRESS'         AND bc.business_address   IS NOT NULL)
          )
        )
      );
END;
$$;


--
-- Name: config_value(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.config_value(p_ns text, p_key text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_cfg business_config%ROWTYPE;
  v_val text;
BEGIN
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  -- 1) Typed business_config takes precedence for the settled financial/legal
  --    identity fields (single source of truth — do not duplicate into EAV).
  SELECT * INTO v_cfg FROM business_config WHERE org_id = v_org;
  IF FOUND AND p_ns = 'ORG' THEN
    v_val := CASE p_key
      WHEN 'LEGAL_NAME'       THEN v_cfg.legal_entity_name
      WHEN 'SIGNATORY_NAME'   THEN v_cfg.signatory_name
      WHEN 'SIGNATORY_TITLE'  THEN v_cfg.signatory_title
      WHEN 'ENTITY_FORMATION' THEN v_cfg.entity_formation
      WHEN 'REGISTERED_AGENT' THEN v_cfg.registered_agent
      WHEN 'ADDRESS'          THEN v_cfg.business_address
      ELSE NULL END;
    IF v_val IS NOT NULL THEN
      RETURN v_val;
    END IF;
  END IF;

  -- 2) Else the EAV config_values row for this tenant. Coalesce the typed value
  --    columns in text/num/json order.
  SELECT COALESCE(
           cv.value_text,
           CASE WHEN cv.value_num IS NOT NULL THEN cv.value_num::text END,
           CASE WHEN cv.value_json IS NOT NULL THEN cv.value_json #>> '{}' END
         )
    INTO v_val
    FROM config_values cv
    WHERE cv.org_id = v_org AND cv.namespace = p_ns AND cv.key = p_key;

  RETURN v_val;  -- NULL when unset (the go-live check flags required-but-unset)
END;
$$;


--
-- Name: confirm_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_booking(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_b bookings%ROWTYPE; v_owes boolean;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found in this org'; END IF;
  IF v_b.status NOT IN ('requested','approved','pending') THEN
    RAISE EXCEPTION 'only a requested, approved or pending booking can be confirmed'; END IF;

  v_owes := booking_awaiting_payment(v_b);

  UPDATE bookings
     SET status = CASE WHEN v_owes THEN 'approved'
                       WHEN kind = 'lesson' THEN 'scheduled' ELSE 'confirmed' END,
         updated_at = now()
   WHERE id = p_booking_id;

  UPDATE booking_change_requests SET status='approved', decided_by=auth.uid(), decided_at=now()
   WHERE booking_id = p_booking_id AND status='pending';

  IF v_owes THEN
    -- the ask for the money raises the buyer's "payment due" notice and the
    -- staff copy through notify_purchase_unpaid, so this branch does not also
    -- send a "confirmed" notice for a session that is not confirmed yet.
    PERFORM request_purchase_payment(v_b.purchase_id, NULL);
    RETURN jsonb_build_object('status', 'approved', 'payment_requested', true);
  END IF;

  IF v_b.account_user_id IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id, 'booking_confirmed',
              'Your session on ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM') || ' is confirmed',
              '/app/calendar');
  END IF;
  RETURN jsonb_build_object('status', 'confirmed', 'payment_requested', false);
END;
$$;


--
-- Name: confirm_booking_for_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_booking_for_purchase(p_purchase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- the calendar owns scheduling now; on payment we just confirm any booking
  -- already linked to this purchase.
  UPDATE bookings
     SET status = CASE WHEN kind = 'lesson' THEN 'scheduled' ELSE 'confirmed' END,
         updated_at = now()
   WHERE purchase_id = p_purchase_id
     AND status IN ('requested','approved','pending');
END;
$$;


--
-- Name: confirm_horse_section(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_horse_section(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc documents%ROWTYPE;
  v_is_staff boolean;
  v_is_lessor boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;
  IF v_doc.workflow_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'document is % — the horse section can only be confirmed before locking', v_doc.workflow_state;
  END IF;

  v_is_staff  := coalesce(has_staff_access() AND v_doc.org_id = current_org(), false);
  v_is_lessor := EXISTS (SELECT 1 FROM caller_party_roles(p_document_id) r WHERE r = 'LESSOR');
  IF NOT (v_is_staff OR v_is_lessor) THEN
    RAISE EXCEPTION 'only the Lessor (or staff) may confirm the horse information';
  END IF;

  UPDATE documents
     SET horse_section_confirmed_at = now(),
         horse_section_confirmed_by = current_contact_id()
   WHERE id = p_document_id;

  RETURN jsonb_build_object(
    'document_id', p_document_id,
    'horse_section_confirmed_at', now(),
    'horse_section_confirmed_by', current_contact_id());
END;
$$;


--
-- Name: confirm_my_legal_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_my_legal_name(p_first text, p_last text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_first text := nullif(trim(coalesce(p_first,'')),'');
  v_last  text := nullif(trim(coalesce(p_last,'')),'');
BEGIN
  IF v_contact IS NULL THEN RAISE EXCEPTION 'no contact record for this account'; END IF;
  IF v_first IS NULL OR v_last IS NULL THEN
    RAISE EXCEPTION 'both a first and a last name are required';
  END IF;

  UPDATE contacts
     SET first_name = v_first,
         last_name  = v_last,
         name_needs_confirmation = false,
         updated_at = now()
   WHERE id = v_contact;
END
$$;


--
-- Name: FUNCTION confirm_my_legal_name(p_first text, p_last text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_my_legal_name(p_first text, p_last text) IS 'The member states their own legal name, clearing the confirmation gate. This is the ONLY way the flag is cleared — staff cannot confirm on someone''s behalf, because the whole point is that we could not safely assert it.';


--
-- Name: confirm_payment_claim(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_payment_claim(p_purchase_id uuid, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur    purchases%ROWTYPE;
  v_method text;
  v_result text;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown purchase: %', p_purchase_id; END IF;
  IF v_pur.client_claim_status <> 'pending' THEN
    RAISE EXCEPTION 'no pending claim on this order (claim status: %)', v_pur.client_claim_status;
  END IF;

  v_method := coalesce(v_pur.client_reported_method, v_pur.payment_method, 'zelle');

  -- D6: one payment spine — the SAME function a matched Zelle payment settles
  -- through. Writes payment_status/status/paid_at/amount_paid/payment_method,
  -- fires the existing status_events trigger, and notifies the buyer + staff.
  -- TASK-BACKDATE: `p_paid_at` rides through it; the future-date refusal and the
  -- silence live there, so there is one rule, not two.
  v_result := mark_purchase_paid(
    p_purchase_id, v_pur.amount, v_pur.client_reported_reference, v_method, p_paid_at);

  UPDATE purchases
     SET client_claim_status      = 'confirmed',
         client_claim_resolved_by = auth.uid(),
         client_claim_resolved_at = now()
   WHERE id = p_purchase_id;

  PERFORM log_status_event('order', p_purchase_id, 'claim_confirmed',
    'Confirmed by staff — settled as ' || v_method, v_pur.org_id);

  RETURN jsonb_build_object('confirmed', true, 'settlement', v_result, 'method', v_method);
END;
$$;


--
-- Name: consume_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_notification(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n notifications%ROWTYPE;
BEGIN
  SELECT * INTO v_n FROM notifications WHERE id = p_id AND user_id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;

  -- CLOSEOUT §1.8: the log is the source of truth, written before the delete
  -- in the same transaction — a failed delete rolls the log entry back with it.
  PERFORM _log_notification_resolution(v_n, 'dismissed_by_recipient', auth.uid());

  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (auth.uid(), 'DELETE', 'notifications', v_n.id,
    to_jsonb(v_n), jsonb_build_object('event', 'notification_consumed', 'by', 'recipient'));

  DELETE FROM notifications WHERE id = v_n.id;
  RETURN true;
END;
$$;


--
-- Name: consume_unit_for_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_unit_for_booking(p_booking_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b bookings%ROWTYPE;
  v_u uuid;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND OR v_b.purchase_id IS NULL THEN RETURN NULL; END IF;

  SELECT u.id INTO v_u
    FROM fulfillment_units u
    JOIN purchase_items pi ON pi.id = u.purchase_item_id
   WHERE u.purchase_id = v_b.purchase_id AND u.deleted_at IS NULL
     AND u.current_status = 'open' AND u.unit_kind IN ('session','period')
   ORDER BY (v_b.offering_id IS NOT NULL AND pi.offering_id = v_b.offering_id) DESC,
            u.seq
   LIMIT 1;
  IF v_u IS NULL THEN RETURN NULL; END IF;

  UPDATE fulfillment_units SET booking_id = p_booking_id WHERE id = v_u;
  PERFORM set_unit_status(v_u, 'scheduled', 'Booking ' || p_booking_id::text);
  RETURN v_u;
END;
$$;


--
-- Name: contact_activity_stream(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_activity_stream(p_contact_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org  uuid := current_org();
  v_user uuid;
  v_out  jsonb;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'contact not found in this organisation';
  END IF;

  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = p_contact_id;

  WITH ev AS (
    -- ── DOCUMENT: sent ──────────────────────────────────────────────────────
    SELECT d.sent_at AS occurred_at, 'document_sent' AS kind,
           coalesce(d.title, d.display_code, 'Document') AS title,
           'Sent for signature' AS detail, 'document' AS source_type, d.id AS source_id
      FROM documents d
     WHERE d.deleted_at IS NULL AND d.sent_at IS NOT NULL
       AND (d.contact_id = p_contact_id
         OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = d.id AND dp.contact_id = p_contact_id))

    -- ── DOCUMENT: viewed ────────────────────────────────────────────────────
    UNION ALL
    SELECT o.opened_at, 'document_viewed',
           coalesce(d.title, d.display_code, 'Document'),
           'Opened' || coalesce(' as ' || nullif(o.opened_label, ''), ''),
           'document', d.id
      FROM document_opened o
      JOIN documents d ON d.id = o.document_id AND d.deleted_at IS NULL
     WHERE o.contact_id = p_contact_id

    -- ── DOCUMENT: signed ────────────────────────────────────────────────────
    UNION ALL
    SELECT s.signed_at, 'document_signed',
           coalesce(d.title, d.display_code, 'Document'),
           'Signed' || coalesce(' as ' || nullif(s.party_role, ''), ''),
           'document', d.id
      FROM signatures s
      JOIN documents d ON d.id = s.document_id AND d.deleted_at IS NULL
     WHERE s.signer_contact_id = p_contact_id AND s.deleted_at IS NULL AND s.signed_at IS NOT NULL

    -- ── DOCUMENT: executed ──────────────────────────────────────────────────
    UNION ALL
    SELECT (d.effective_date::timestamptz), 'document_executed',
           coalesce(d.title, d.display_code, 'Document'),
           'Executed — in force', 'document', d.id
      FROM documents d
     WHERE d.deleted_at IS NULL AND d.status = 'EXECUTED' AND d.effective_date IS NOT NULL
       AND (d.contact_id = p_contact_id
         OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = d.id AND dp.contact_id = p_contact_id))

    -- ── DOCUMENT: delivered ─────────────────────────────────────────────────
    UNION ALL
    SELECT dd.delivered_at, 'document_delivered',
           coalesce(d.title, d.display_code, 'Document'),
           'Delivered' || coalesce(' via ' || nullif(dd.channel, ''), ''),
           'document', d.id
      FROM document_deliveries dd
      JOIN documents d ON d.id = dd.document_id AND d.deleted_at IS NULL
     WHERE dd.recipient_contact_id = p_contact_id AND dd.deleted_at IS NULL AND dd.delivered_at IS NOT NULL

    -- ── INVITATION: sent ────────────────────────────────────────────────────
    UNION ALL
    SELECT i.created_at, 'invitation_sent', 'Invitation',
           'Invitation sent', 'invitation', i.id
      FROM invitations i
     WHERE i.contact_id = p_contact_id

    -- ── INVITATION: redeemed (account claimed) ──────────────────────────────
    UNION ALL
    SELECT i.redeemed_at, 'invitation_redeemed', 'Invitation',
           'Redeemed — account created', 'invitation', i.id
      FROM invitations i
     WHERE i.contact_id = p_contact_id AND i.redeemed_at IS NOT NULL

    -- ── BOOKINGS ────────────────────────────────────────────────────────────
    UNION ALL
    SELECT b.created_at, 'booking', coalesce(o.name, 'Session'),
           'Booked for ' || to_char(b.starts_at, 'Mon DD, YYYY'), 'booking', b.id
      FROM bookings b
      LEFT JOIN offerings o ON o.id = b.offering_id
     WHERE b.account_contact_id = p_contact_id

    -- ── ORDERS ──────────────────────────────────────────────────────────────
    UNION ALL
    SELECT pu.created_at, 'order',
           coalesce(pu.display_code, 'Order'),
           'Order placed — $' || to_char(coalesce(pu.amount, 0), 'FM999990.00'),
           'order', pu.id
      FROM purchases pu
     WHERE pu.buyer_contact_id = p_contact_id

    -- ── PAYMENTS ────────────────────────────────────────────────────────────
    UNION ALL
    SELECT pu.paid_at, 'payment',
           coalesce(pu.display_code, 'Order'),
           'Payment received — $' || to_char(coalesce(pu.amount, 0), 'FM999990.00')
             || coalesce(' (' || nullif(pu.payment_method, '') || ')', ''),
           'order', pu.id
      FROM purchases pu
     WHERE pu.buyer_contact_id = p_contact_id AND pu.paid_at IS NOT NULL

    -- ── POSTS (account only) ────────────────────────────────────────────────
    UNION ALL
    SELECT f.created_at, 'post',
           coalesce(nullif(left(f.body, 80), ''), '(' || f.post_type || ')'),
           CASE WHEN f.pulled_down THEN 'Post (pulled down)'
                WHEN f.published THEN 'Post published' ELSE 'Post drafted' END,
           'post', f.id
      FROM feed_posts f
     WHERE v_user IS NOT NULL AND f.author_id = v_user

    -- ── EVALUATION RECORDS, where they exist ────────────────────────────────
    UNION ALL
    SELECT coalesce(e.delivered_at, e.created_at), 'evaluation',
           coalesce(e.title, 'Evaluation'),
           CASE WHEN e.delivered_at IS NOT NULL THEN 'Evaluation delivered' ELSE 'Evaluation created' END
             || coalesce(' — ' || nullif(e.horse_label, ''), ''),
           'evaluation', e.id
      FROM evaluation_reports e
     WHERE e.contact_id = p_contact_id AND e.deleted_at IS NULL
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'occurred_at', occurred_at, 'kind', kind, 'title', title,
           'detail', detail, 'source_type', source_type, 'source_id', source_id)
           ORDER BY occurred_at DESC), '[]'::jsonb)
    INTO v_out
    FROM (SELECT * FROM ev WHERE occurred_at IS NOT NULL
           ORDER BY occurred_at DESC LIMIT p_limit) s;

  RETURN v_out;
END
$_$;


--
-- Name: contact_audit_trail(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_audit_trail(p_contact_id uuid, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_user uuid; v_out jsonb;
BEGIN
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_contact_id LIMIT 1;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', a.id, 'action', a.action, 'table_name', a.table_name,
           'record_id', a.record_id, 'occurred_at', a.occurred_at,
           'actor_user_id', a.actor_user_id,
           'old_value', a.old_value, 'new_value', a.new_value,
           'by_them', (a.actor_user_id = v_user))
           ORDER BY a.occurred_at DESC), '[]'::jsonb)
    INTO v_out
    FROM (
      SELECT * FROM audit_logs al
       WHERE (v_user IS NOT NULL AND al.actor_user_id = v_user)
          OR al.record_id = p_contact_id
          OR (v_user IS NOT NULL AND al.record_id = v_user)
       ORDER BY al.occurred_at DESC
       LIMIT p_limit
    ) a;
  RETURN v_out;
END
$$;


--
-- Name: contact_checklist(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_checklist(p_contact_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(row ORDER BY done, created_at), '[]'::jsonb)
  FROM (
    SELECT jsonb_build_object(
        'kind', 'document',
        'id', d.id,
        'title', coalesce(d.title, 'Contract'),
        'action', CASE
          WHEN EXISTS (SELECT 1 FROM signatures sg
                        WHERE sg.document_id = d.id AND sg.signer_contact_id = p_contact_id
                          AND sg.deleted_at IS NULL) THEN 'Signed'
          WHEN coalesce(c.can_fill, true) AND EXISTS (
                 SELECT 1 FROM contract_fields f
                  WHERE f.document_id = d.id AND f.owner_role = dp.party_role
                    AND coalesce(f.value, '') = '') THEN 'Add your information and sign'
          WHEN coalesce(c.can_edit_deal, false) THEN 'Review, edit the terms, and sign'
          WHEN coalesce(c.can_suggest, false) THEN 'Review, suggest changes if needed, and sign'
          ELSE 'Review and sign'
        END,
        'link', '/app/contracts/' || d.id,
        'done', EXISTS (SELECT 1 FROM signatures sg
                         WHERE sg.document_id = d.id AND sg.signer_contact_id = p_contact_id
                           AND sg.deleted_at IS NULL)
      ) AS row,
      EXISTS (SELECT 1 FROM signatures sg
               WHERE sg.document_id = d.id AND sg.signer_contact_id = p_contact_id
                 AND sg.deleted_at IS NULL) AS done,
      d.created_at
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    LEFT JOIN document_party_controls c
      ON c.document_id = d.id AND c.party_role = dp.party_role
    WHERE dp.contact_id = p_contact_id
      AND dp.party_role <> 'PARTICIPANT'

    UNION ALL

    SELECT jsonb_build_object(
        'kind', 'required_doc',
        'id', ct.template_key,
        'title', t.title,
        'action', 'Review and sign at first login',
        'link', '/app/onboarding',
        'done', false
      ),
      false,
      now()
    FROM required_templates_for_contact(p_contact_id) ct
    JOIN contract_templates t ON t.template_key = ct.template_key
    WHERE NOT EXISTS (
      SELECT 1 FROM documents d
      JOIN contract_templates t2 ON t2.id = d.template_id
      WHERE t2.template_key = ct.template_key
        AND d.contact_id = p_contact_id AND d.deleted_at IS NULL
    )
  ) items
$$;


--
-- Name: contact_designations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_designations(p_contact uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(array_agg(designation ORDER BY designation), '{}')
  FROM staff_designations
  WHERE org_id = current_org() AND contact_id = p_contact AND has_staff_access();
$$;


--
-- Name: contact_document_satisfied(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_document_satisfied(p_contact_id uuid, p_template_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Version-BLIND by design. A valid executed signature is not invalidated by a
  -- later edit to the template body; only an explicit, deliberate staff decision
  -- may demand a re-signature (see the resign-floor migration).
  SELECT p_contact_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM documents d
      JOIN contract_templates ct ON ct.id = d.template_id
     WHERE d.contact_id = p_contact_id
       AND d.deleted_at IS NULL
       AND d.status = 'EXECUTED'
       AND coalesce(d.current_status, '') <> 'superseded'
       AND ct.template_key = p_template_key);
$$;


--
-- Name: FUNCTION contact_document_satisfied(p_contact_id uuid, p_template_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contact_document_satisfied(p_contact_id uuid, p_template_key text) IS 'THE satisfaction rule for an assigned document. Called by contact_document_wall_state(), my_onboarding_state() and generate_my_onboarding_documents() so the signing wall and the onboarding page cannot disagree and deadlock a member. Version-blind: see 20260807T1500.';


--
-- Name: contact_document_wall_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_document_wall_state(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pending int; v_gating int; v_titles text[];
  v_waiting int; v_waiting_titles text[];
BEGIN
  IF p_contact_id IS NULL THEN
    RETURN jsonb_build_object('pending', 0, 'gating', 0, 'titles', '[]'::jsonb,
                              'waiting', 0, 'waiting_titles', '[]'::jsonb);
  END IF;

  SELECT count(*),
         -- ⚠️ WAS `ct.wall_gating` — a property of the TEMPLATE. It is the
         -- ASSIGNMENT's disposition now, so staff can require one person to sign
         -- at login and merely ask another for the same document.
         count(*) FILTER (WHERE crd.disposition = 'AT_LOGIN'),
         array_agg(coalesce(ct.title, ct.template_key)
                   ORDER BY coalesce(ct.title, ct.template_key))
           FILTER (WHERE crd.disposition = 'AT_LOGIN'),
         -- §12: asked for, not demanded. Surfaced every login until signed.
         count(*) FILTER (WHERE crd.disposition = 'WHEN_READY'),
         array_agg(coalesce(ct.title, ct.template_key)
                   ORDER BY coalesce(ct.title, ct.template_key))
           FILTER (WHERE crd.disposition = 'WHEN_READY')
    INTO v_pending, v_gating, v_titles, v_waiting, v_waiting_titles
    FROM contact_required_documents crd
    JOIN contract_templates ct ON ct.template_key = crd.template_key
     AND ct.active AND ct.deleted_at IS NULL
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key
                          AND x.active AND x.deleted_at IS NULL)
   WHERE crd.contact_id = p_contact_id
     AND crd.skipped_at IS NULL
     -- WITH_CONTRACT is not owed yet: it arrives with the deal, on execution.
     AND crd.disposition <> 'WITH_CONTRACT'
     AND NOT contact_document_satisfied(p_contact_id, crd.template_key);

  RETURN jsonb_build_object(
    'pending', coalesce(v_pending, 0),
    'gating',  coalesce(v_gating, 0),
    'titles',  to_jsonb(coalesce(v_titles, ARRAY[]::text[])),
    'waiting', coalesce(v_waiting, 0),
    'waiting_titles', to_jsonb(coalesce(v_waiting_titles, ARRAY[]::text[])));
END;
$$;


--
-- Name: FUNCTION contact_document_wall_state(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contact_document_wall_state(p_contact_id uuid) IS 'THE shared onboarding-document predicate: how many assigned documents a contact has not yet satisfied at the current active template version, and how many of those are wall_gating. The signing wall (my_wall_state), the contract lock preconditions (contract_lock_blockers) and the signature guard (record_signature) all read this one function so they can never disagree.';


--
-- Name: contact_dossier(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_dossier(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_user uuid;
  v_out  jsonb;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM contacts
                  WHERE id = p_contact_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'contact not found in this organisation';
  END IF;

  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = p_contact_id;

  SELECT jsonb_build_object(
    'contact', (SELECT to_jsonb(c) FROM contacts c WHERE c.id = p_contact_id),

    'account', CASE WHEN v_user IS NULL THEN NULL ELSE (
      SELECT jsonb_build_object(
        'user_id', p.user_id, 'role', p.role, 'is_suspended', p.is_suspended,
        'display_name', p.display_name, 'bio', p.bio, 'riding_level', p.riding_level,
        'avatar_url', p.avatar_url, 'created_at', p.created_at,
        'member_status', (SELECT m.status FROM members m WHERE m.user_id = p.user_id LIMIT 1),
        'login', (SELECT jsonb_build_object(
            'providers', coalesce((SELECT jsonb_agg(DISTINCT i.provider)
                                     FROM auth.identities i WHERE i.user_id = p.user_id), '[]'::jsonb),
            'last_sign_in_at', u.last_sign_in_at,
            'email_confirmed_at', u.email_confirmed_at)
          FROM auth.users u WHERE u.id = p.user_id))
      FROM profiles p WHERE p.user_id = v_user) END,

    'standing', jsonb_build_object(
      'contact_type', (SELECT c.contact_type FROM contacts c WHERE c.id = p_contact_id),
      'is_client', EXISTS (SELECT 1 FROM clients cl
                            WHERE cl.contact_id = p_contact_id AND cl.deleted_at IS NULL),
      'groups', coalesce((SELECT jsonb_agg(g.group_type ORDER BY g.group_type)
                            FROM groups g WHERE g.contact_id = p_contact_id), '[]'::jsonb),
      'party_roles', coalesce((SELECT jsonb_agg(DISTINCT dp.party_role)
                                 FROM document_parties dp WHERE dp.contact_id = p_contact_id), '[]'::jsonb)),

    'contract_roles', coalesce((SELECT jsonb_agg(jsonb_build_object(
                 'document_id', d.id, 'document_code', d.display_code,
                 'document_title', d.title, 'party_role', dp.party_role,
                 'status', d.status, 'current_status', d.current_status,
                 'effective_date', d.effective_date) ORDER BY d.generated_at DESC)
                 FROM document_parties dp
                 JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
                WHERE dp.contact_id = p_contact_id), '[]'::jsonb),

    'family', jsonb_build_object(
      'guardian', (SELECT jsonb_build_object(
                     'contact_id', g.id,
                     'name', coalesce(nullif(trim(concat_ws(' ', g.first_name, g.last_name)), ''), g.email),
                     'email', g.email)
                     FROM contacts g
                     JOIN contacts c ON c.guardian_contact_id = g.id
                    WHERE c.id = p_contact_id AND g.deleted_at IS NULL),
      'dependants', coalesce((SELECT jsonb_agg(jsonb_build_object(
                     'contact_id', d.id,
                     'name', coalesce(nullif(trim(concat_ws(' ', d.first_name, d.last_name)), ''), d.email),
                     'date_of_birth', d.date_of_birth) ORDER BY d.date_of_birth)
                     FROM contacts d
                    WHERE d.guardian_contact_id = p_contact_id AND d.deleted_at IS NULL), '[]'::jsonb)),

    'horses', coalesce((SELECT jsonb_agg(jsonb_build_object(
                 'horse_id', h.id,
                 'name', coalesce(h.nickname, h.registered_name),
                 'relation', CASE WHEN h.current_owner_contact_id = p_contact_id THEN 'owner'
                                  ELSE 'lessee' END) ORDER BY h.registered_name)
                 FROM horses h
                WHERE h.deleted_at IS NULL
                  AND (h.current_owner_contact_id = p_contact_id
                    OR h.lessee_contact_id = p_contact_id)), '[]'::jsonb),

    'documents', coalesce((SELECT jsonb_agg(jsonb_build_object(
                 'document_id', d.id, 'code', d.display_code, 'title', d.title,
                 'status', d.status, 'current_status', d.current_status,
                 'generated_at', d.generated_at,
                 'effective_date', d.effective_date) ORDER BY d.generated_at DESC)
                 FROM documents d
                WHERE d.deleted_at IS NULL
                  AND (d.contact_id = p_contact_id
                    OR EXISTS (SELECT 1 FROM document_parties dp
                                WHERE dp.document_id = d.id AND dp.contact_id = p_contact_id))), '[]'::jsonb),

    'orders', coalesce((SELECT jsonb_agg(jsonb_build_object(
                 'purchase_id', pu.id, 'code', pu.display_code, 'status', pu.status,
                 'amount', pu.amount, 'amount_paid', pu.amount_paid,
                 'payment_status', pu.payment_status, 'payment_method', pu.payment_method,
                 'paid_at', pu.paid_at, 'current_status', pu.current_status,
                 'client_claim_status', pu.client_claim_status,
                 'client_reported_method', pu.client_reported_method,
                 'items', coalesce((SELECT jsonb_agg(jsonb_build_object(
                              'item_id', pi.id, 'offering_id', pi.offering_id,
                              'label', coalesce(o.name, pi.label),
                              'quantity', pi.quantity,
                              'price_amount', pi.price_amount, 'price_unit', pi.price_unit,
                              'config_kind', o.config_kind, 'service_type', o.service_type,
                              'voided_at', pi.voided_at, 'void_reason', pi.void_reason)
                              ORDER BY pi.created_at)
                            FROM purchase_items pi
                            LEFT JOIN offerings o ON o.id = pi.offering_id
                           WHERE pi.purchase_id = pu.id), '[]'::jsonb),
                 'created_at', pu.created_at) ORDER BY pu.created_at DESC)
                 FROM purchases pu WHERE pu.buyer_contact_id = p_contact_id), '[]'::jsonb),

    'notifications', coalesce((SELECT jsonb_agg(jsonb_build_object(
                 'id', n.id, 'kind', n.kind, 'title', n.title,
                 'created_at', n.created_at) ORDER BY n.created_at DESC)
                 FROM notifications n WHERE v_user IS NOT NULL AND n.user_id = v_user
                 LIMIT 25), '[]'::jsonb)
  ) INTO v_out;

  RETURN v_out;
END
$$;


--
-- Name: FUNCTION contact_dossier(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contact_dossier(p_contact_id uuid) IS 'Everything known about one person, keyed on CONTACT so it works for the 13 of 19 contacts with no account — counterparties, kiosk signers, leads and minors. The account block, posts and activity come back NULL (not empty) when there is no login, so the UI can distinguish "nothing yet" from "does not apply". Includes the guardian/dependant links, which existed in the schema and were populated but had no surface anywhere in the app.';


--
-- Name: contact_locations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_locations(p_contact_id uuid) RETURNS TABLE(id uuid, name text, address text, is_offsite boolean, is_default boolean, is_mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT l.id, l.name, l.address, l.is_offsite, l.is_default,
         (l.owner_contact_id = p_contact_id) AS is_mine
  FROM locations l
  WHERE l.org_id = current_org()
    AND l.active
    AND has_staff_access()
    AND (l.owner_contact_id IS NULL OR l.owner_contact_id = p_contact_id)
  ORDER BY l.is_default DESC, (l.owner_contact_id IS NOT NULL), l.sort_order, l.name
$$;


--
-- Name: contact_profile_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_profile_complete(p_contact_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT c.phone IS NOT NULL
        AND c.date_of_birth IS NOT NULL
        AND c.emergency_contact_1_name IS NOT NULL
        AND c.emergency_contact_1_phone IS NOT NULL
       FROM contacts c WHERE c.id = p_contact_id),
    false)
$$;


--
-- Name: FUNCTION contact_profile_complete(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contact_profile_complete(p_contact_id uuid) IS 'ONBOARD §5: the ONE definition of "this person''s profile is filled in" — phone, date of birth, and a first emergency contact with a number. Read by my_onboarding_state and by my_profile_completion so the onboarding wizard and the dashboard notice can never disagree.';


--
-- Name: contact_required_documents_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_required_documents_state(p_contact_id uuid) RETURNS TABLE(template_key text, skipped_at timestamp with time zone, skipped_by_name text, skip_reason text, satisfied boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT crd.template_key, crd.skipped_at,
         (SELECT nullif(trim(concat_ws(' ', pr.first_name, pr.last_name)), '')
            FROM profiles pr WHERE pr.user_id = crd.skipped_by),
         crd.skip_reason,
         contact_document_satisfied(p_contact_id, crd.template_key)
    FROM contact_required_documents crd
   WHERE crd.contact_id = p_contact_id
     AND has_staff_access()
   ORDER BY crd.template_key
$$;


--
-- Name: contacts_a_seed_community_channels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_a_seed_community_channels() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.phone IS NOT NULL AND btrim(NEW.phone) <> '' THEN
    NEW.mobile_call   := coalesce(NEW.mobile_call,   NEW.phone);
    NEW.mobile_text   := coalesce(NEW.mobile_text,   NEW.phone);
    NEW.whatsapp_call := coalesce(NEW.whatsapp_call, NEW.phone);
    NEW.whatsapp_text := coalesce(NEW.whatsapp_text, NEW.phone);
  END IF;
  IF NEW.email IS NOT NULL AND btrim(NEW.email) <> '' THEN
    NEW.community_email := coalesce(NEW.community_email, NEW.email);
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: contacts_convert_lead_on_client(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_convert_lead_on_client() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE contacts
     SET contact_type = 'CONTACT', updated_at = now()
   WHERE id = NEW.contact_id
     AND contact_type = 'LEAD';
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION contacts_convert_lead_on_client(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contacts_convert_lead_on_client() IS 'A LEAD who becomes a client moves to CONTACT automatically — the campaign list must never keep advertising someone who already bought. Only LEAD rows are converted, so a TEAM or DIRECTORY row given a client record is left alone.';


--
-- Name: contacts_file_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_file_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- The caller was explicit (e.g. the inbound trigger says LEAD, or staff picked
  -- a page). Never second-guess that.
  IF NEW.contact_type IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- is_company is the TENANT'S OWN company record (one per org, enforced by the
  -- one_company_contact_per_org partial unique index) — not a generic vendor
  -- organisation. It belongs to TEAM.
  IF coalesce(NEW.is_company, false) THEN
    NEW.contact_type := 'TEAM';
  ELSE
    NEW.contact_type := 'CONTACT';
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: FUNCTION contacts_file_on_insert(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contacts_file_on_insert() IS 'Files a new contact onto a person-page when the creating path did not say. An is_company row becomes TEAM — that flag marks the TENANT''S OWN company record (one per org, per the one_company_contact_per_org index), not a vendor. Everyone else becomes CONTACT, because every path reaching here is engaging a person already — provisioning a client, signing a release, promoting an account. LEAD is set only by the inbound-capture trigger, where someone has merely enquired: defaulting here to LEAD would pad the campaign list with existing customers. An explicit contact_type from the caller always wins.';


--
-- Name: contacts_file_team_on_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_file_team_on_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.contact_id IS NULL OR NEW.role IS NULL OR NEW.role = 'USER' THEN
    RETURN NEW;
  END IF;
  -- Only promote a contact that is not already deliberately filed elsewhere.
  UPDATE contacts
     SET contact_type = 'TEAM', updated_at = now()
   WHERE id = NEW.contact_id
     AND coalesce(contact_type, 'CONTACT') = 'CONTACT';
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION contacts_file_team_on_link(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contacts_file_team_on_link() IS 'Moves a contact to TEAM when its account is given a staff role. Runs on the profile because the role does not exist at contact-insert time. Never overrides a deliberate filing — only a contact still sitting at the CONTACT default is promoted.';


--
-- Name: contacts_minor_no_email_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_minor_no_email_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.date_of_birth IS NOT NULL
     AND NEW.date_of_birth + interval '18 years' > current_date
     AND (NEW.email IS NOT NULL OR NEW.correspondence_email IS NOT NULL)
  THEN
    RAISE EXCEPTION 'a minor contact carries no direct email; put the address on the guardian record';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: contacts_normalise_phone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contacts_normalise_phone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.phone  := format_phone(NEW.phone);
  NEW.mobile := format_phone(NEW.mobile);
  NEW.phone_ext  := nullif(regexp_replace(coalesce(NEW.phone_ext, ''),  '\D', '', 'g'), '');
  NEW.mobile_ext := nullif(regexp_replace(coalesce(NEW.mobile_ext, ''), '\D', '', 'g'), '');
  NEW.mobile_call   := format_phone(NEW.mobile_call);
  NEW.mobile_text   := format_phone(NEW.mobile_text);
  NEW.whatsapp_call := format_phone(NEW.whatsapp_call);
  NEW.whatsapp_text := format_phone(NEW.whatsapp_text);
  RETURN NEW;
END
$$;


--
-- Name: content_block_version_at(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_block_version_at(p_slug text, p_version integer) RETURNS TABLE(version integer, parent_version integer, title text, body text, kind text, is_current boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, b.title, v.body, b.kind,
         v.version = b.current_version as is_current, v.created_at
    from content_block_versions v
    join content_blocks b on b.id = v.block_id
   where b.org_id = current_org() and b.slug = p_slug and v.version = p_version
$$;


--
-- Name: content_block_version_list(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_block_version_list(p_slug text) RETURNS TABLE(version integer, parent_version integer, is_current boolean, edited_by uuid, edited_by_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.version = b.current_version as is_current,
         v.edited_by,
         coalesce(nullif(btrim(coalesce(p.display_name, '')), ''),
                  nullif(btrim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''),
                  p.email) as edited_by_name,
         v.created_at
    from content_block_versions v
    join content_blocks b on b.id = v.block_id
    left join profiles p on p.user_id = v.edited_by
   where b.org_id = current_org() and b.slug = p_slug
   order by v.version desc
$$;


--
-- Name: contract_caller_is_originator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_caller_is_originator(p_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT current_contact_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM documents d
    WHERE d.id = p_document_id AND d.deleted_at IS NULL
      AND d.originator_contact_id = current_contact_id()
  );
$$;


--
-- Name: contract_change_log_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_change_log_list(p_document_id uuid, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_tree jsonb; v_num jsonb := '{}'::jsonb; v_ttl jsonb := '{}'::jsonb;
  s jsonb; sub jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to read document %', p_document_id;
  END IF;

  -- numbering straight from the composer-agreeing tree
  v_tree := contract_section_tree(p_document_id);
  FOR s IN SELECT jsonb_array_elements(v_tree) LOOP
    v_num := v_num || jsonb_build_object(s->>'section_key', s->>'number');
    v_ttl := v_ttl || jsonb_build_object(s->>'section_key', s->>'title');
    FOR sub IN SELECT jsonb_array_elements(s->'subsections') LOOP
      v_num := v_num || jsonb_build_object(sub->>'clause_key', sub->>'number');
      v_ttl := v_ttl || jsonb_build_object(sub->>'clause_key', sub->>'title');
    END LOOP;
  END LOOP;

  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC)
    FROM (
      SELECT cl.id, cl.change_kind, cl.field_key, cl.field_label, cl.owner_role,
             cl.old_value, cl.new_value, cl.detail, cl.actor_label, cl.actor_roles,
             cl.actor_is_staff, cl.created_at,
             r.section_key, r.clause_key,
             -- the SECTION number/title this row bundles under
             (v_num ->> r.section_key)  AS section_number,
             (v_ttl ->> r.section_key)  AS section_title,
             -- the finer subsection number, when the row resolves that far
             (v_num ->> r.clause_key)   AS clause_number,
             (v_ttl ->> r.clause_key)   AS clause_title
        FROM contract_change_log cl
        CROSS JOIN LATERAL change_log_section_key(cl.document_id, cl.field_key) r
       WHERE cl.document_id = p_document_id
       ORDER BY cl.created_at DESC
       LIMIT greatest(1, least(p_limit, 1000))
    ) t
  ), '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION contract_change_log_list(p_document_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_change_log_list(p_document_id uuid, p_limit integer) IS 'Change log with SERVER-SIDE section attribution. Each row carries its resolved section_key/clause_key plus the live number+title from contract_section_tree, so the log''s numbering always matches the composed document. Attribution ladder: contract_fields → contract_field_defs → SECTION.FIELD key convention → retired_field_section.';


--
-- Name: contract_change_requests_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_change_requests_list(p_document_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.created_at), '[]'::jsonb)
  FROM (
    SELECT cr.id, cr.parent_request_id, cr.anchor_kind, cr.anchor_ref,
           cr.target_section, cr.annotation_number, cr.impact_rank,
           cr.quote, cr.quote_prefix, cr.is_stale, cr.needs_review, cr.body,
           cr.author_label, cr.author_role, cr.author_contact_id,
           cr.submitted_at, cr.agreed_at, cr.resolved_at, cr.edited_at, cr.created_at,
           cr.reopened_at, cr.reopened_by_contact_id,
           coalesce(sd.heading, 'The whole document') AS section_heading,
           -- SEEN stamps: everyone other than the author who has viewed this entry
           coalesce((
             SELECT jsonb_agg(jsonb_build_object(
                      'contact_id', s.contact_id, 'seen_at', s.seen_at,
                      'role', s.seen_role, 'label', s.seen_label)
                    ORDER BY s.seen_at)
               FROM contract_change_request_seen s
              WHERE s.request_id = cr.id
                AND s.contact_id IS DISTINCT FROM cr.author_contact_id), '[]'::jsonb) AS seen_by,
           -- frozen = somebody other than the author has seen it
           EXISTS (SELECT 1 FROM contract_change_request_seen s2
                    WHERE s2.request_id = cr.id
                      AND s2.contact_id IS DISTINCT FROM cr.author_contact_id) AS is_frozen,
           -- can the CALLER still edit this entry? (author + not yet seen)
           (cr.author_contact_id = current_contact_id()
            AND NOT EXISTS (SELECT 1 FROM contract_change_request_seen s3
                             WHERE s3.request_id = cr.id
                               AND s3.contact_id IS DISTINCT FROM cr.author_contact_id)) AS can_edit
      FROM contract_change_requests cr
      LEFT JOIN documents d ON d.id = cr.document_id
      LEFT JOIN contract_templates ct ON ct.id = d.template_id
      LEFT JOIN contract_section_defs sd
             ON sd.template_key = ct.template_key AND sd.section_key = cr.target_section
     WHERE cr.document_id = p_document_id
       AND ((cr.org_id = current_org() AND has_staff_access())
            OR caller_is_document_party(p_document_id))
  ) t;
$$;


--
-- Name: contract_comments_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_comments_list(p_document_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT contract_change_requests_list(p_document_id); $$;


--
-- Name: contract_deal_type(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_deal_type(p_contract_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_terms jsonb;
  v_v     text;
BEGIN
  SELECT terms INTO v_terms FROM contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- 1. the deal kind create_deal stamps on the contract it opens
  v_v := upper(coalesce(v_terms ->> 'deal_kind', ''));
  IF v_v IN ('SALE', 'LEASE') THEN RETURN v_v; END IF;

  -- 2. the deal side the three start_* functions stamp
  v_v := upper(coalesce(v_terms ->> 'deal_side', ''));
  IF v_v = 'SALE' THEN RETURN 'SALE'; END IF;
  IF v_v IN ('LEASE_IN', 'LEASE_OUT', 'LEASE') THEN RETURN 'LEASE'; END IF;

  -- 3. the governing document already on the contract
  SELECT CASE
           WHEN is_horse_lease_template(t.template_key) THEN 'LEASE'
           WHEN t.template_key = 'HORSE_PURCHASE_SALE' THEN 'SALE'
           WHEN coalesce(t.contract_kind, '') IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE') THEN 'SALE'
         END
    INTO v_v
    FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
   WHERE d.contract_id = p_contract_id AND d.deleted_at IS NULL
     AND coalesce(d.workflow_state, '') <> 'void'
     AND (is_horse_lease_template(t.template_key)
          OR t.template_key = 'HORSE_PURCHASE_SALE'
          OR coalesce(t.contract_kind, '') IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE'))
   ORDER BY d.created_at
   LIMIT 1;
  IF v_v IS NOT NULL THEN RETURN v_v; END IF;

  -- 4. who is standing on each side
  SELECT CASE
           WHEN bool_or(cp.party_role IN ('LESSOR','LESSEE')) THEN 'LEASE'
           WHEN bool_or(cp.party_role IN ('BUYER','SELLER'))  THEN 'SALE'
         END
    INTO v_v
    FROM contract_parties cp WHERE cp.contract_id = p_contract_id;

  RETURN v_v;
END;
$$;


--
-- Name: contract_document_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_document_detail(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me    uuid := current_contact_id();
  v_org   uuid; v_recip boolean; v_state text; v_orig uuid;
  v_staff boolean; v_roles text[]; v_can_fill boolean; v_can_deal boolean;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, recipient_editing, workflow_state, originator_contact_id
    INTO v_org, v_recip, v_state, v_orig
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  v_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  IF NOT (v_staff OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to read document %', p_document_id;
  END IF;

  SELECT array_agg(r) INTO v_roles FROM caller_party_roles(p_document_id) r;
  v_roles := coalesce(v_roles, ARRAY[]::text[]);

  SELECT bool_or(coalesce(c.can_fill, true)), bool_or(coalesce(c.can_edit_deal, true))
    INTO v_can_fill, v_can_deal
  FROM unnest(v_roles) r
  LEFT JOIN document_party_controls c
    ON c.document_id = p_document_id AND c.party_role = r;
  v_can_fill := coalesce(v_can_fill, true);
  v_can_deal := coalesce(v_can_deal, false);

  SELECT jsonb_build_object(
    'document', (SELECT jsonb_build_object(
        'document_id', d.id, 'title', d.title, 'status', d.status,
        'template_key', (SELECT ct.template_key FROM contract_templates ct WHERE ct.id = d.template_id),
        'workflow_state', d.workflow_state, 'recipient_editing', d.recipient_editing,
        'execution_hash', d.execution_hash, 'merged_body', d.merged_body,
        'is_originator', (d.originator_contact_id = v_me),
        'horse_section_confirmed_at', d.horse_section_confirmed_at,
        'sent_at', d.sent_at, 'archived_at', d.archived_at,
        'voided_at', d.voided_at, 'void_reason', d.void_reason,
        'voided_by_me', (d.voided_by IS NOT NULL AND d.voided_by = v_me),
        'my_hidden_at', (SELECT dph.hidden_at FROM document_party_hidden dph
                          WHERE dph.document_id = d.id AND dph.contact_id = v_me),
        'can_void', can_void_document(d.id),
        'horse_id', d.horse_id,
        'horse_section_confirmed_by', d.horse_section_confirmed_by,
        'terminated_at', d.terminated_at,
        'termination_requested_at', d.termination_requested_at,
        'termination_requested_by', d.termination_requested_by,
        'termination_request_reason', d.termination_request_reason,
        'effective_date', d.effective_date,
        -- TASK-SURFACEEDITOR: THE TELL. An executed document renders the version
        -- it was signed against, forever, and it must SAY SO — otherwise the
        -- first person to edit a lease template assumes signed copies changed
        -- too (D33 is precisely that they do not). Both numbers, because the
        -- fact only reads as a fact when the two can be compared.
        'signed_template_version', d.signed_template_version,
        'template_version_now', (SELECT ct.version FROM contract_templates ct WHERE ct.id = d.template_id),
        'executed_email_sent_at', d.executed_email_sent_at)
      FROM documents d WHERE d.id = p_document_id),
    'my_roles', to_jsonb(v_roles),
    -- TASK COSIGN: roles a staff caller may sign because the role's signer
    -- contact is the org's own company contact — mirrors record_signature's
    -- company branch exactly.
    'company_signable_roles', coalesce((
      SELECT jsonb_agg(DISTINCT dp.party_role)
      FROM document_parties dp
      JOIN contacts cc ON cc.id = dp.contact_id
      WHERE dp.document_id = p_document_id AND dp.is_signer AND cc.is_company
        AND cc.org_id = v_org AND cc.deleted_at IS NULL), '[]'::jsonb),
    'company_contact_name', (
      SELECT cc.first_name FROM document_parties dp
      JOIN contacts cc ON cc.id = dp.contact_id
      WHERE dp.document_id = p_document_id AND cc.is_company
        AND cc.org_id = v_org AND cc.deleted_at IS NULL LIMIT 1),
    'party_controls', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'party_role', c.party_role, 'can_fill', c.can_fill,
          'can_edit_deal', c.can_edit_deal, 'can_suggest', c.can_suggest,
          'can_add_clause', coalesce(c.can_add_clause, true)))
      FROM document_party_controls c WHERE c.document_id = p_document_id), '[]'::jsonb),
    'fields', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'field_key', cf.field_key, 'label', cf.label, 'section', cf.section,
          'clause_key', cf.clause_key, 'responsibility_kind', cf.responsibility_kind,
          'custom_kind', cf.custom_kind, 'body', cf.body,
          'added_by_contact_id', cf.added_by_contact_id,
          'added_by_me', cf.added_by_contact_id IS NOT NULL AND cf.added_by_contact_id = current_contact_id(),
          'added_by_contact_id', cf.added_by_contact_id,
          'owner_role', cf.owner_role, 'value', cf.value, 'value_type', cf.value_type,
          'required', cf.required, 'sort_order', cf.sort_order,
          'parent_field_key', cf.parent_field_key, 'input_kind', cf.input_kind,
          'options', cf.options, 'conditional_on', cf.conditional_on, 'guidance', cf.guidance,
          'closed', coalesce(cf.closed, false),
          'is_optional', cf.is_optional, 'included', cf.included, 'is_na', cf.is_na,
          'control_override', cf.control_override, 'responsibility', cf.responsibility,
          'format_type', cf.format_type, 'structured', cf.structured,
          'pair_cost_key', cf.pair_cost_key, 'pair_manage_key', cf.pair_manage_key,
          'can_edit', (
            CASE
              -- F1 / D4: the six insurance responsibility elections are
              -- PARTY-EXCLUSIVE. Staff status does NOT substitute for owning the
              -- role here, mirroring set_contract_field's carve-out exactly so the
              -- UI never offers an edit the server will reject. FHE is itself the
              -- Lessor on these contracts, so without this the app would render
              -- the LESSEE's box as checkable to FHE staff.
              WHEN cf.field_key IN (
                     'TXN.GL_LESSEE_RESPONSIBLE','TXN.MORT_LESSEE_RESPONSIBLE','TXN.MED_LESSEE_RESPONSIBLE',
                     'TXN.GL_NOT_REQUIRED','TXN.MORT_NOT_REQUIRED','TXN.MED_NOT_REQUIRED')
                THEN cf.owner_role = ANY(v_roles) AND v_can_fill
              -- Disclosure CONTENT is imported from the horse record; never edited here.
              WHEN cf.field_key IN (
                     'HORSE.KNOWN_CONDITIONS','HORSE.MEDICAL_HISTORY','HORSE.BEHAVIORAL_HISTORY',
                     'HORSE.INJURIES_TO_HUMANS','HORSE.INJURIES_TO_HORSE','HORSE.MEDICATIONS','HORSE.SUPPLEMENTS')
                THEN false
              -- A disclosure GATE locks to its record-derived value when the record
              -- section has entries; it is author-answerable only when the record is empty.
              WHEN cf.field_key LIKE 'HORSE.%\_GATE' AND disclosure_gate_locked(p_document_id, cf.field_key)
                THEN false
              ELSE
                   v_staff
                OR (cf.owner_role = 'DEAL' AND v_can_deal)
                OR (cf.owner_role <> 'DEAL' AND cf.owner_role = ANY(v_roles) AND v_can_fill)
            END
          ) AND v_state IN ('editable','editing','in_review'))
        ORDER BY cf.sort_order, cf.field_key)
      FROM contract_fields cf WHERE cf.document_id = p_document_id), '[]'::jsonb),
    -- OPEN change requests now come from the surviving table: a ROOT row that has
    -- been SUBMITTED and not yet resolved. Shape preserved for the caller.
    'open_change_requests', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'id', cr.id, 'annotation_number', cr.annotation_number,
          'target_field_key', cr.anchor_ref, 'target_section', cr.target_section,
          'current_value', NULL::text, 'requested_change', cr.body,
          'status', 'open')
        ORDER BY cr.annotation_number)
      FROM contract_change_requests cr
      WHERE cr.document_id = p_document_id
        AND cr.parent_request_id IS NULL
        AND cr.submitted_at IS NOT NULL AND cr.resolved_at IS NULL), '[]'::jsonb),
    'shares', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'shared_with_contact_id', s.shared_with_contact_id,
          'recipient_editing', s.recipient_editing, 'notified_at', s.notified_at))
      FROM document_shares s WHERE s.document_id = p_document_id), '[]'::jsonb),
    'signatures', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'party_role', sg.party_role, 'typed_name', sg.typed_name,
          'signed_at', sg.signed_at)
        ORDER BY sg.party_role)
      FROM signatures sg WHERE sg.document_id = p_document_id AND sg.deleted_at IS NULL), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION contract_document_detail(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_document_detail(p_document_id uuid) IS 'Full read model for one contract the caller is a party to (or staff): the document (status, workflow_state, recipient_editing, execution_hash, merged_body), the caller''s roles, every field with a can_edit flag mirroring set_contract_field''s ownership rule, open change requests, shares, and signature status. jsonb — the detail read model a UI binds to.';


--
-- Name: contract_event_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_event_log(p_document_id uuid) RETURNS TABLE(occurred_at timestamp with time zone, kind text, actor text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;

  RETURN QUERY
  WITH status AS (
    SELECT
      se.created_at AS occurred_at,
      'STATUS'::text AS kind,
      coalesce(nullif(btrim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''), p.display_name, 'Unknown') AS actor,
      initcap(replace(se.status, '_', ' ')) AS detail
    FROM status_events se
    LEFT JOIN profiles p ON p.user_id = se.actor_user_id
    WHERE se.entity_type = 'document' AND se.entity_id = p_document_id
  ),
  sent AS (
    SELECT
      dd.delivered_at AS occurred_at,
      'SENT'::text AS kind,
      coalesce(nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''), 'Unknown') AS actor,
      (coalesce(nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''), 'Unknown')
        || ' via ' || dd.channel
        || CASE WHEN dd.is_mirror THEN ' (mirror copy)' ELSE '' END) AS detail
    FROM document_deliveries dd
    LEFT JOIN contacts c ON c.id = dd.recipient_contact_id
    WHERE dd.document_id = p_document_id AND dd.deleted_at IS NULL
  ),
  signed AS (
    SELECT
      s.signed_at AS occurred_at,
      'SIGNED'::text AS kind,
      coalesce(nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''), 'Unknown') AS actor,
      initcap(replace(s.party_role, '_', ' ')) AS detail
    FROM signatures s
    LEFT JOIN contacts c ON c.id = s.signer_contact_id
    WHERE s.document_id = p_document_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL
  ),
  opened AS (
    SELECT
      do_.opened_at AS occurred_at,
      'OPENED'::text AS kind,
      coalesce(do_.opened_label, 'Unknown') AS actor,
      coalesce(initcap(replace(do_.opened_role, '_', ' ')), 'Viewed') AS detail
    FROM document_opened do_
    WHERE do_.document_id = p_document_id
  ),
  edits AS (
    SELECT
      max(ccl.created_at) AS occurred_at,
      'EDITS'::text AS kind,
      coalesce(nullif(btrim(ccl.actor_label), ''), 'Unknown') AS actor,
      (count(*)::text || ' field edit' || CASE WHEN count(*) = 1 THEN '' ELSE 's' END) AS detail
    FROM contract_change_log ccl
    WHERE ccl.document_id = p_document_id
    GROUP BY ccl.actor_label, (ccl.created_at AT TIME ZONE 'America/Los_Angeles')::date
  )
  SELECT * FROM status
  UNION ALL SELECT * FROM sent
  UNION ALL SELECT * FROM signed
  UNION ALL SELECT * FROM opened
  UNION ALL SELECT * FROM edits
  ORDER BY occurred_at DESC;
END;
$$;


--
-- Name: contract_execution_audit_get(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_execution_audit_get(p_document_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT to_jsonb(a) FROM contract_execution_audit a
   WHERE a.document_id = p_document_id
     AND ((a.org_id = current_org() AND has_staff_access())
          OR caller_is_document_party(p_document_id));
$$;


--
-- Name: contract_horse_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_horse_id(p_contract_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- The contract's horse IS its document's horse. Where a contract carries more
  -- than one document (a lease and an addendum), the earliest one that names a
  -- horse is the contract's — an addendum does not re-subject the agreement.
  SELECT d.horse_id
    FROM documents d
   WHERE d.contract_id = p_contract_id
     AND d.deleted_at IS NULL
     AND d.horse_id IS NOT NULL
   ORDER BY d.created_at
   LIMIT 1;
$$;


--
-- Name: contract_intake_requirements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_intake_requirements(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc     documents%ROWTYPE;
  v_tkey    text;
  v_staff   boolean;
  v_roles   text[];
  v_me      uuid := current_contact_id();
  v_c       contacts%ROWTYPE;
  v_horse   horses%ROWTYPE;
  v_tokens  text[] := '{}';
  v_can_fill boolean;
  v_mine    text[] := '{}';          -- the roles the CALLER's own contact holds
  v_cmiss   jsonb := '[]'::jsonb;
  v_hmiss   jsonb := '[]'::jsonb;
  v_horse_mine boolean := false;
  r         record;
  v_has     boolean;
  v_blocking int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  v_staff := coalesce(has_staff_access() AND v_doc.org_id = current_org(), false);
  IF NOT (v_staff OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to read document %', p_document_id;
  END IF;

  SELECT template_key INTO v_tkey FROM contract_templates WHERE id = v_doc.template_id;
  SELECT array_agg(x.r) INTO v_roles FROM caller_party_roles(p_document_id) AS x(r);
  v_roles := coalesce(v_roles, ARRAY[]::text[]);

  SELECT bool_or(coalesce(c.can_fill, true)) INTO v_can_fill
    FROM unnest(v_roles) rr
    LEFT JOIN document_party_controls c
      ON c.document_id = p_document_id AND c.party_role = rr;
  v_can_fill := coalesce(v_can_fill, true);

  -- The roles whose party row is the CALLER'S OWN CONTACT. A staff member reading
  -- someone else's contract has no personal information to give it, and must never
  -- be prompted to enter theirs into the counterparty's seat.
  SELECT coalesce(array_agg(DISTINCT dp.party_role), ARRAY[]::text[]) INTO v_mine
    FROM document_parties dp
   WHERE dp.document_id = p_document_id AND dp.contact_id = v_me;

  -- ── every token this document can print ──────────────────────────────────
  SELECT coalesce(array_agg(DISTINCT t), '{}') INTO v_tokens FROM (
    SELECT (regexp_matches(cd.body, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1] AS t
      FROM contract_clause_defs cd WHERE cd.template_key = v_tkey
    UNION ALL
    SELECT (regexp_matches(ct.body, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1]
      FROM contract_templates ct WHERE ct.id = v_doc.template_id AND ct.body IS NOT NULL
    UNION ALL
    SELECT (regexp_matches(cf.body, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1]
      FROM contract_fields cf
     WHERE cf.document_id = p_document_id AND cf.body IS NOT NULL
  ) q;

  -- ── the person ───────────────────────────────────────────────────────────
  IF v_me IS NOT NULL AND array_length(v_mine, 1) > 0 THEN
    SELECT * INTO v_c FROM contacts WHERE id = v_me;
    FOR r IN
      SELECT * FROM (VALUES
        ('name',    'FULL_NAME',
         nullif(btrim(coalesce(v_c.first_name,'') || ' ' || coalesce(v_c.last_name,'')), '')),
        ('email',   'EMAIL',   nullif(btrim(coalesce(v_c.email, '')), '')),
        ('phone',   'PHONE',   nullif(btrim(coalesce(v_c.phone, '')), '')),
        ('address', 'ADDRESS', nullif(btrim(coalesce(
            nullif(btrim(coalesce(v_c.address_composed, '')), ''),
            compose_address(v_c.address_line1, v_c.address_line2,
                            v_c.city, v_c.state, v_c.postal_code),
            '')), ''))
      ) AS t(key, suffix, val)
    LOOP
      CONTINUE WHEN r.val IS NOT NULL;                 -- already on file
      SELECT EXISTS (
        SELECT 1 FROM unnest(v_mine) AS m(party_role)
         WHERE (m.party_role || '.' || r.suffix) = ANY(v_tokens)
            OR (r.suffix = 'FULL_NAME' AND (m.party_role || '.PRINTED_NAME') = ANY(v_tokens))
      ) INTO v_has;
      CONTINUE WHEN NOT v_has;                         -- this contract never prints it
      v_cmiss := v_cmiss || jsonb_build_object(
        'key', r.key,
        'optional', false,
        'label', CASE r.key WHEN 'name' THEN 'Your full legal name'
                            WHEN 'email' THEN 'Email address'
                            WHEN 'phone' THEN 'Phone number'
                            ELSE 'Mailing address' END);
    END LOOP;
  END IF;

  -- ── the horse record ─────────────────────────────────────────────────────
  v_horse_mine := EXISTS (
    SELECT 1 FROM contract_fields cf
     WHERE cf.document_id = p_document_id
       AND upper(coalesce(cf.section, '')) = 'HORSE'
       AND cf.owner_role = ANY(v_roles)
  ) AND v_can_fill;

  IF v_doc.horse_id IS NOT NULL AND v_horse_mine THEN
    SELECT * INTO v_horse FROM horses WHERE id = v_doc.horse_id AND deleted_at IS NULL;
    IF FOUND THEN
      FOR r IN
        -- ⚠️ THE LAST COLUMN IS `optional`. A mobile veterinarian who travels to
        -- the horse has no address to give, and the contract must still complete.
        SELECT * FROM (VALUES
          ('farrier_name',  'FARRIER_NAME',  'Farrier — name',    'text',    false),
          ('farrier_phone', 'FARRIER_PHONE', 'Farrier — phone',   'text',    false),
          ('vet_name',      'VET_NAME',      'Veterinarian — name',     'text', false),
          ('vet_phone',     'VET_PHONE',     'Veterinarian — phone',    'text', false),
          ('vet_business_name', 'VET_BUSINESS', 'Veterinary practice',  'text', false),
          ('vet_address',   'VET_ADDRESS',   'Veterinarian — address',  'address', true)
        ) AS t(key, token, label, kind, optional)
      LOOP
        CONTINUE WHEN NOT (('HORSE.' || r.token) = ANY(v_tokens));
        CONTINUE WHEN nullif(btrim(coalesce(horse_field_token_value(v_horse, r.token), '')), '') IS NOT NULL;
        v_hmiss := v_hmiss || jsonb_build_object(
          'key', r.key, 'label', r.label, 'kind', r.kind, 'optional', r.optional);
      END LOOP;
    END IF;
  END IF;

  -- ⚠️ `complete` COUNTS ONLY WHAT BLOCKS. An optional entry is still returned so
  -- the page can offer it, but it can never hold a contract open.
  SELECT count(*) INTO v_blocking
    FROM (SELECT e FROM jsonb_array_elements(v_cmiss) e
          UNION ALL
          SELECT e FROM jsonb_array_elements(v_hmiss) e) q
   WHERE coalesce((q.e ->> 'optional')::boolean, false) = false;

  RETURN jsonb_build_object(
    'document_id', v_doc.id,
    'title', v_doc.title,
    'workflow_state', v_doc.workflow_state,
    'my_roles', to_jsonb(v_roles),
    'contact', jsonb_build_object('contact_id', v_me, 'missing', v_cmiss),
    'horse', jsonb_build_object(
       'horse_id', v_doc.horse_id,
       'mine', v_horse_mine,
       'needs_horse', (v_doc.horse_id IS NULL AND v_horse_mine),
       'missing', v_hmiss),
    'complete', (v_blocking = 0));
END;
$$;


--
-- Name: contract_lock_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_lock_blockers(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_blockers jsonb := '[]'::jsonb;
  v_open int;
  v_vals jsonb := '{}'::jsonb;
  r record;
  v_missing text[];
  v_horse_confirmed timestamptz;
  v_needs_horse boolean;
  v_unnamed text[];
BEGIN
  SELECT horse_section_confirmed_at INTO v_horse_confirmed
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  SELECT count(*) INTO v_open FROM contract_change_requests
   WHERE document_id = p_document_id
     AND parent_request_id IS NULL AND submitted_at IS NOT NULL AND resolved_at IS NULL;
  IF v_open > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'open_change_requests',
      'message', v_open || ' open change request(s) must be resolved'));
  END IF;

  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val
             FROM contract_fields WHERE document_id = p_document_id LOOP
    v_vals := v_vals || jsonb_build_object(r.field_key, r.val);
  END LOOP;
  SELECT array_agg(coalesce(cf.label, cf.field_key) ORDER BY cf.sort_order, cf.field_key)
    INTO v_missing
    FROM contract_fields cf
    LEFT JOIN contract_clause_defs cd
      ON cd.template_key = (SELECT ct.template_key FROM documents d
                             JOIN contract_templates ct ON ct.id = d.template_id
                            WHERE d.id = p_document_id)
     AND cd.clause_key = cf.clause_key
   WHERE cf.document_id = p_document_id AND cf.required
     AND coalesce(cf.included, true) AND NOT coalesce(cf.is_na, false)
     AND (nullif(trim(coalesce(cf.value, '')), '') IS NULL OR (cf.format_type = 'certify' AND upper(coalesce(cf.value, '')) <> 'YES'))
     -- a clause gated on THIS field (a self-gating driver) counts as visible
     -- for the required check — an unanswered gate must block, never hide
     AND (clause_condition_met(cd.conditional_on, v_vals)
          OR (cd.conditional_on IS NOT NULL
              AND cd.conditional_on::text LIKE '%"' || cf.field_key || '"%'))
     AND clause_condition_met(cf.conditional_on, v_vals);
  IF v_missing IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'required_fields',
      'message', 'Required field(s) still empty: ' || array_to_string(v_missing, ', ')));
  END IF;

  -- ── PARTYEMAIL PHASE 3: a signer must have a full name ─────────────────────
  SELECT array_agg(DISTINCT nm ORDER BY nm) INTO v_unnamed
    FROM (
      SELECT coalesce(nullif(btrim(coalesce(c.email,'')), ''), 'A party') AS nm
        FROM (
          SELECT dp.contact_id, dp.party_role,
                 CASE WHEN dp.party_role = 'BUYER'
                       AND row_number() OVER (PARTITION BY dp.party_role
                                              ORDER BY dp.signer_order NULLS LAST, dp.id) > 1
                      THEN 'COBUYER' ELSE dp.party_role END AS ns
            FROM document_parties dp
           WHERE dp.document_id = p_document_id AND dp.is_signer
        ) p
        JOIN contacts c ON c.id = p.contact_id
       WHERE NOT coalesce(c.is_company, false)
         AND p.party_role NOT IN ('FHE','COMPANY')
         AND (
           nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), '') IS NULL
           OR EXISTS (
                SELECT 1 FROM contract_fields cf
                 WHERE cf.document_id = p_document_id
                   AND cf.field_key IN (p.ns || '.FULL_NAME', p.ns || '.PRINTED_NAME')
                   AND nullif(btrim(coalesce(cf.value,'')), '') IS NULL)
         )
    ) x;
  IF v_unnamed IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'party_name_required',
      'message', 'A full name is required before signing for: '
                 || array_to_string(v_unnamed, ', ')));
  END IF;

  IF EXISTS (
    SELECT 1 FROM contract_fields cf
      JOIN documents d2 ON d2.id = cf.document_id
      JOIN contract_parties cp2 ON cp2.contract_id = d2.contract_id AND cp2.party_role = 'LESSEE'
      JOIN contacts c2 ON c2.id = cp2.contact_id
     WHERE cf.document_id = p_document_id AND cf.field_key = 'LESSEE.PARTY_TYPE'
       AND ((cf.value = 'INDIVIDUAL' AND coalesce(c2.is_company,false))
         OR (cf.value = 'ENTITY' AND NOT coalesce(c2.is_company,false)))
  ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'party_type_mismatch',
      'message', 'LESSEE.PARTY_TYPE contradicts the Lessee party record (person vs company) — correct the field or the contact record'));
  END IF;

  -- ── horse_unconfirmed: REMOVED 2026-08-25 (owner ruling) ──────────────────
  -- "as the author (admin) its weird that the box for 'I have reviewed the horse
  -- information and it is accurate' is shown ... i have no way to know if its
  -- accurate, the data comes from the horse record and the horse record is either
  -- mine and i created it so i think its accurate or its not mine and i dont know
  -- if its accurate ... remove that entirely from the system it serves no purpose."
  --
  -- ⚠️ IT WAS A LIVE BLOCKER NOBODY HAD EVER SATISFIED. Zero of 68 documents had
  -- horse_section_confirmed_at set, so EVERY contract carrying LESSOR-owned HORSE.*
  -- fields was refused a lock. Removing it is the unblock, not just a tidy-up.
  -- The columns and the confirm/reopen functions stay (D32); nothing calls them.

  -- ── document-before-contract: REMOVED 2026-08-22 (owner ruling) ────────────
  -- The `onboarding_documents` blocker lived here. It read
  -- contact_document_wall_state(signer)->>'gating' > 0 for every non-company
  -- signer and refused the signature with "Onboarding documents must be
  -- completed first by: <names>". The onboarding wall is still computed, still
  -- presented at /app/onboarding, and still read by everything else that reads
  -- it — it simply no longer decides whether a contract may be signed. The
  -- wall's subject is arrival on the property; a signature is a different
  -- event, and the lease and bill of sale carry their own release and
  -- indemnification language. Asked and confirmed explicitly: off entirely, not
  -- narrowed to the client side.
  --
  -- D3 REMOVED 2026-08-10 (owner ruling): the four LESSEE acceptance checkboxes
  -- it read are deleted; a blocker keyed on fields that no longer exist could
  -- never be satisfied. The generic required-fields rule above is untouched.

  -- A sale or lease must have its horse attached before it can be locked or sent.
  IF EXISTS (
    SELECT 1 FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
    WHERE d.id = p_document_id AND d.horse_id IS NULL
      AND (is_horse_lease_template(t.template_key)
           OR coalesce(t.contract_kind, '') IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE')
           OR t.template_key = 'HORSE_PURCHASE_SALE')
  ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'horse_missing',
      'message', 'Attach the horse to this contract before locking or sending it.'));
  END IF;

    -- initials acknowledgment: a filled initials field must match the owning
  -- party's name on the document (first letter of each name token, letters only).
  -- Name source depends on the party type: an ENTITY uses its signing individual's
  -- name (<ROLE>.ENTITY_SIGNER_NAME, a contract field); an individual uses the
  -- contact name from document_parties -> contacts (the party-name blocker's source).
  DECLARE
    r record; v_expect text; v_got text; v_pname text; v_ptype text; v_bad text[];
  BEGIN
    FOR r IN
      SELECT cf.field_key, cf.value, cf.owner_role,
             coalesce(cf.label, cf.field_key) AS label
        FROM contract_fields cf
       WHERE cf.document_id = p_document_id AND cf.format_type = 'initials'
         AND nullif(btrim(coalesce(cf.value,'')), '') IS NOT NULL
    LOOP
      SELECT upper(btrim(coalesce(cf2.value,''))) INTO v_ptype FROM contract_fields cf2
        WHERE cf2.document_id = p_document_id AND cf2.field_key = r.owner_role || '.PARTY_TYPE';
      IF v_ptype = 'ENTITY' THEN
        SELECT btrim(coalesce(cf3.value,'')) INTO v_pname FROM contract_fields cf3
          WHERE cf3.document_id = p_document_id AND cf3.field_key = r.owner_role || '.ENTITY_SIGNER_NAME';
      ELSE
        SELECT btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')) INTO v_pname
          FROM document_parties dp JOIN contacts c ON c.id = dp.contact_id
         WHERE dp.document_id = p_document_id AND dp.party_role = r.owner_role
         ORDER BY dp.signer_order NULLS LAST, dp.id
         LIMIT 1;
      END IF;
      v_expect := upper(regexp_replace(
        array_to_string(ARRAY(SELECT left(w,1) FROM regexp_split_to_table(btrim(coalesce(v_pname,'')), '\s+') w WHERE w <> ''), ''),
        '[^A-Za-z]', '', 'g'));
      v_got := upper(regexp_replace(coalesce(r.value,''), '[^A-Za-z]', '', 'g'));
      IF v_expect <> '' AND v_got <> v_expect THEN
        v_bad := coalesce(v_bad, ARRAY[]::text[]) || (r.label || ' (expected ' || v_expect || ')');
      END IF;
    END LOOP;
    IF v_bad IS NOT NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'initials_mismatch',
        'message', 'Initials do not match the party''s name for: ' || array_to_string(v_bad, ', ')));
    END IF;
  END;

    -- R3 task 2: BOS pre-purchase examination value must stay within the set
  -- the source allows, so a sync cannot reopen a locked state.
  DECLARE v_src2 text; v_val2 text; v_has text;
  BEGIN
    SELECT upper(btrim(coalesce(value,''))) INTO v_has FROM contract_fields
      WHERE document_id = p_document_id AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';
    SELECT btrim(coalesce(value,'')) INTO v_val2 FROM contract_fields
      WHERE document_id = p_document_id AND field_key = 'TXN.BOS_PPE';
    SELECT btrim(coalesce(value,'')) INTO v_src2 FROM contract_fields
      WHERE document_id = p_document_id AND field_key = 'TXN.BOS_PPE_SOURCE';
    IF v_has = 'YES' AND v_val2 <> '' THEN
      IF v_src2 = 'AUTHOR' AND v_val2 NOT IN ('REQUESTED_COMPLETED','REQUESTED_NOT_COMPLETED') THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'code','bos_ppe_state',
          'message','The pre-purchase examination status must be one the accompanying sale allows (completed or not completed).'));
      ELSIF v_src2 = 'DERIVED' AND v_val2 NOT IN ('SELLER_DECLINED','WAIVED') THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'code','bos_ppe_state',
          'message','The pre-purchase examination status is derived from the sale and cannot be changed here.'));
      END IF;
    END IF;
  END;
  RETURN v_blockers;
END;
$$;


--
-- Name: FUNCTION contract_lock_blockers(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_lock_blockers(p_document_id uuid) IS 'THE single source of contract lock preconditions (shared by advance_document_workflow and approve_contract_review). Returns a jsonb ARRAY of {code,message}. Includes the document-before-contract rule: a signing party with unsatisfied wall-gating onboarding documents blocks the contract (code onboarding_documents). Onboarding documents themselves are exempt.';


--
-- Name: contract_menu_add_value(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_menu_add_value(p_template_key text, p_field_key text, p_code text, p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_entry jsonb; v_touched int := 0; v_version int; v_have jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin access required'; END IF;
  IF coalesce(btrim(p_code), '') = '' OR coalesce(btrim(p_label), '') = '' THEN
    RAISE EXCEPTION 'a value needs both a code and a label';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM contract_field_defs
                  WHERE template_key = p_template_key AND field_key = p_field_key) THEN
    RAISE EXCEPTION 'no field %.%', p_template_key, p_field_key;
  END IF;

  SELECT o INTO v_have
    FROM contract_field_defs f, LATERAL jsonb_array_elements(f.options) o
   WHERE f.template_key = p_template_key AND f.field_key = p_field_key
     AND o ->> 'value' = btrim(p_code) LIMIT 1;
  IF v_have IS NOT NULL THEN
    -- ⚠️ INCLUDING A RETIRED ONE. Re-adding a code that already exists would
    -- give one code two meanings, which is the thing rule 1 protects against.
    RAISE EXCEPTION 'the code % already exists on %.% (%). %',
      btrim(p_code), p_template_key, p_field_key,
      CASE WHEN coalesce((v_have ->> 'active')::boolean, true)
           THEN 'active' ELSE 'retired' END,
      CASE WHEN coalesce((v_have ->> 'active')::boolean, true)
           THEN 'Relabel it instead.'
           ELSE 'Reactivate it instead — it kept its code, which is why undo is possible.' END;
  END IF;

  v_entry := jsonb_build_object('label', btrim(p_label), 'value', btrim(p_code), 'active', true);

  UPDATE contract_field_defs
     SET options = coalesce(options, '[]'::jsonb) || jsonb_build_array(v_entry)
   WHERE template_key = p_template_key AND field_key = p_field_key;

  -- ⚠️ THE BELL BOOTS LESSON (2026-08-26): updating only the template adds the
  -- option to FUTURE documents and leaves the live one without it.
  WITH upd AS (
    UPDATE contract_fields cf
       SET options = coalesce(cf.options, '[]'::jsonb) || jsonb_build_array(v_entry)
      FROM documents d, contract_templates ct
     WHERE cf.document_id = d.id AND d.deleted_at IS NULL AND ct.id = d.template_id
       AND ct.template_key = p_template_key AND cf.field_key = p_field_key
       AND NOT _contract_document_frozen(cf.document_id)
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(cf.options,'[]'::jsonb)) x
                        WHERE x ->> 'value' = btrim(p_code))
     RETURNING 1)
  SELECT count(*) INTO v_touched FROM upd;

  v_version := save_contract_template_version(p_template_key);

  RETURN jsonb_build_object('ok', true, 'action', 'added',
    'template_key', p_template_key, 'field_key', p_field_key,
    'code', btrim(p_code), 'label', btrim(p_label),
    'template_version', v_version, 'documents_updated', v_touched);
END;
$$;


--
-- Name: contract_menu_dependents(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_menu_dependents(p_template_key text, p_field_key text, p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opt       jsonb;
  v_clauses   jsonb;
  v_fields    jsonb;
  v_options   jsonb;
  v_documents jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  -- the option itself, so the caller can show its label and current state
  SELECT o INTO v_opt
    FROM contract_field_defs f, LATERAL jsonb_array_elements(f.options) o
   WHERE f.template_key = p_template_key AND f.field_key = p_field_key
     AND o ->> 'value' = p_code
   LIMIT 1;

  -- 1 ── clause-level conditions (the largest set)
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'clause_key', cd.clause_key, 'section_key', cd.section_key,
           'heading', cd.heading) ORDER BY cd.sort_order), '[]'::jsonb)
    INTO v_clauses
    FROM contract_clause_defs cd
   WHERE cd.template_key = p_template_key
     AND _condition_names_value(cd.conditional_on, p_field_key, p_code);

  -- 2 ── field-level conditions
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'field_key', fd.field_key, 'label', fd.label,
           'section', fd.section) ORDER BY fd.sort_order), '[]'::jsonb)
    INTO v_fields
    FROM contract_field_defs fd
   WHERE fd.template_key = p_template_key
     AND _condition_names_value(fd.conditional_on, p_field_key, p_code);

  -- 3 ── ⚠️ per-option `when` gates in OTHER option lists
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'field_key', fd.field_key, 'label', fd.label,
           'option_value', o ->> 'value', 'option_label', o ->> 'label')), '[]'::jsonb)
    INTO v_options
    FROM contract_field_defs fd, LATERAL jsonb_array_elements(fd.options) o
   WHERE fd.template_key = p_template_key
     AND o ? 'when'
     AND _condition_names_value(o -> 'when', p_field_key, p_code);

  -- 4 ── documents that have it SELECTED, split by whether they can still change
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'document_id', d.id, 'title', d.title,
           'workflow_state', d.workflow_state, 'status', d.status,
           'frozen', (coalesce(d.workflow_state, '') = 'executed'),
           'value', cf.value) ORDER BY d.created_at DESC), '[]'::jsonb)
    INTO v_documents
    FROM contract_fields cf
    JOIN documents d ON d.id = cf.document_id AND d.deleted_at IS NULL
    JOIN contract_templates ct ON ct.id = d.template_id
   WHERE ct.template_key = p_template_key
     AND cf.field_key = p_field_key
     AND _value_selects_code(cf.value, p_code);

  RETURN jsonb_build_object(
    'template_key', p_template_key,
    'field_key',    p_field_key,
    'code',         p_code,
    'label',        v_opt ->> 'label',
    'exists',       (v_opt IS NOT NULL),
    -- absent `active` reads as active: 212 live lists predate the flag.
    'active',       coalesce((v_opt ->> 'active')::boolean, true),
    'clauses',      v_clauses,
    'fields',       v_fields,
    'options',      v_options,
    'documents',    v_documents,
    'totals', jsonb_build_object(
      'conditions', jsonb_array_length(v_clauses) + jsonb_array_length(v_fields)
                    + jsonb_array_length(v_options),
      'clauses',    jsonb_array_length(v_clauses),
      'fields',     jsonb_array_length(v_fields),
      'options',    jsonb_array_length(v_options),
      'documents_open',   (SELECT count(*) FROM jsonb_array_elements(v_documents) x
                            WHERE NOT (x ->> 'frozen')::boolean),
      'documents_frozen', (SELECT count(*) FROM jsonb_array_elements(v_documents) x
                            WHERE (x ->> 'frozen')::boolean)));
END;
$$;


--
-- Name: contract_menu_recode(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_menu_recode(p_template_key text, p_field_key text, p_code text, p_new_code text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_dep jsonb; v_t jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin access required'; END IF;
  v_dep := contract_menu_dependents(p_template_key, p_field_key, p_code);
  v_t   := v_dep -> 'totals';

  RAISE EXCEPTION USING
    ERRCODE = 'raise_exception',
    MESSAGE = format(
      'a value''s code can never change. %s names "%s": %s clause condition(s), %s field condition(s), %s option gate(s), and %s document(s) have it selected (%s of them frozen). Retire it and add a new one instead — the old code must keep resolving for every one of those.',
      p_template_key, p_code,
      v_t ->> 'clauses', v_t ->> 'fields', v_t ->> 'options',
      (v_t ->> 'documents_open')::int + (v_t ->> 'documents_frozen')::int,
      v_t ->> 'documents_frozen'),
    HINT = 'contract_menu_set_active(..., false) then contract_menu_add_value(...)';
END;
$$;


--
-- Name: contract_menu_relabel(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_menu_relabel(p_template_key text, p_field_key text, p_code text, p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_touched int := 0; v_version int; v_exists boolean;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin access required'; END IF;
  IF coalesce(btrim(p_label), '') = '' THEN
    RAISE EXCEPTION 'a label cannot be blank';
  END IF;

  SELECT EXISTS (SELECT 1 FROM contract_field_defs f, LATERAL jsonb_array_elements(f.options) o
                  WHERE f.template_key = p_template_key AND f.field_key = p_field_key
                    AND o ->> 'value' = p_code) INTO v_exists;
  IF NOT v_exists THEN
    RAISE EXCEPTION 'no option % on %.%', p_code, p_template_key, p_field_key;
  END IF;

  UPDATE contract_field_defs
     SET options = _options_patch(options, p_code, jsonb_build_object('label', btrim(p_label)))
   WHERE template_key = p_template_key AND field_key = p_field_key;

  -- Both stores, non-frozen only. A relabel changes no answer, so nothing is
  -- cleared and nothing re-opens -- it is the safe half of rule 1.
  WITH upd AS (
    UPDATE contract_fields cf
       SET options = _options_patch(cf.options, p_code, jsonb_build_object('label', btrim(p_label)))
      FROM documents d, contract_templates ct
     WHERE cf.document_id = d.id AND d.deleted_at IS NULL AND ct.id = d.template_id
       AND ct.template_key = p_template_key AND cf.field_key = p_field_key
       AND NOT _contract_document_frozen(cf.document_id)
     RETURNING 1)
  SELECT count(*) INTO v_touched FROM upd;

  v_version := save_contract_template_version(p_template_key);

  RETURN jsonb_build_object('ok', true, 'action', 'relabelled',
    'template_key', p_template_key, 'field_key', p_field_key, 'code', p_code,
    'label', btrim(p_label), 'template_version', v_version,
    'documents_updated', v_touched);
END;
$$;


--
-- Name: contract_menu_set_active(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_menu_set_active(p_template_key text, p_field_key text, p_code text, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opt      jsonb;
  v_before   jsonb;
  r          record;
  v_new      text;
  v_blk_before int;
  v_blk_after  int;
  v_cleared  jsonb := '[]'::jsonb;
  v_reopened jsonb := '[]'::jsonb;
  v_touched  int := 0;
  v_version  int;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin access required'; END IF;

  SELECT o INTO v_opt
    FROM contract_field_defs f, LATERAL jsonb_array_elements(f.options) o
   WHERE f.template_key = p_template_key AND f.field_key = p_field_key
     AND o ->> 'value' = p_code
   LIMIT 1;
  IF v_opt IS NULL THEN
    RAISE EXCEPTION 'no option % on %.%', p_code, p_template_key, p_field_key;
  END IF;

  -- What the caller is about to affect, captured BEFORE the write so the return
  -- value describes the decision they made rather than the world after it.
  v_before := contract_menu_dependents(p_template_key, p_field_key, p_code);

  -- 1 ── the template
  UPDATE contract_field_defs
     SET options = _options_patch(options, p_code, jsonb_build_object('active', p_active))
   WHERE template_key = p_template_key AND field_key = p_field_key;

  -- 2 ── every document that is still allowed to change
  FOR r IN
    SELECT cf.id, cf.document_id, cf.value, cf.label, cf.owner_role, cf.required, d.title
      FROM contract_fields cf
      JOIN documents d ON d.id = cf.document_id AND d.deleted_at IS NULL
      JOIN contract_templates ct ON ct.id = d.template_id
     WHERE ct.template_key = p_template_key
       AND cf.field_key = p_field_key
       AND NOT _contract_document_frozen(cf.document_id)
  LOOP
    UPDATE contract_fields
       SET options = _options_patch(options, p_code, jsonb_build_object('active', p_active))
     WHERE id = r.id;
    v_touched := v_touched + 1;

    -- ⚠️ A DRAFT TAKES THE NEW OPTIONS, SO A SELECTED OLD OPTION IS CLEARED
    -- (owner, 2026-08-26). Only on the way OUT -- reactivating never rewrites
    -- an answer, because nothing about it became untrue.
    CONTINUE WHEN p_active OR NOT _value_selects_code(r.value, p_code);

    SELECT jsonb_array_length(coalesce(contract_lock_blockers(r.document_id), '[]'::jsonb))
      INTO v_blk_before;

    v_new := _value_without_code(r.value, p_code);
    UPDATE contract_fields SET value = v_new WHERE id = r.id;

    -- ⚠️ LOGGED, ALWAYS. "A value vanishing with no trace is indistinguishable
    -- from a bug, and the author will swear they answered it."
    PERFORM log_contract_change(
      r.document_id, 'option_retired', p_field_key, r.label, r.owner_role,
      r.value, v_new,
      jsonb_build_object('code', p_code, 'label', v_opt ->> 'label',
                         'reason', 'the option was retired on the template'));

    SELECT jsonb_array_length(coalesce(contract_lock_blockers(r.document_id), '[]'::jsonb))
      INTO v_blk_after;

    v_cleared := v_cleared || jsonb_build_object(
      'document_id', r.document_id, 'title', r.title,
      'was', r.value, 'now', v_new, 'required', coalesce(r.required, false));

    -- ⚠️ RETIRING AN OPTION CAN UN-READY A CONTRACT THAT WAS READY TO SIGN.
    -- Correct, and the person who did it has to be told which ones.
    IF v_blk_after > v_blk_before THEN
      v_reopened := v_reopened || jsonb_build_object(
        'document_id', r.document_id, 'title', r.title,
        'blockers_before', v_blk_before, 'blockers_after', v_blk_after);
    END IF;
  END LOOP;

  -- 3 ── the template's new version (D33: the live template must not drift
  -- ahead of its own retained version)
  v_version := save_contract_template_version(p_template_key);

  RETURN jsonb_build_object(
    'ok', true, 'action', CASE WHEN p_active THEN 'reactivated' ELSE 'deactivated' END,
    'template_key', p_template_key, 'field_key', p_field_key, 'code', p_code,
    'label', v_opt ->> 'label',
    'template_version', v_version,
    'documents_updated', v_touched,
    'dependents', v_before,
    'cleared',  v_cleared,
    'reopened', v_reopened);
END;
$$;


--
-- Name: contract_notes_for_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_notes_for_document(p_document_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(t ORDER BY t.created_at), '[]'::jsonb)
    FROM (
      SELECT n.id, n.title, n.created_at,
             (n.created_by_contact_id = current_contact_id()) AS mine,
             coalesce((
               SELECT jsonb_agg(jsonb_build_object(
                        'id', m.id, 'body', m.body, 'created_at', m.created_at,
                        'author', coalesce(m.author_label, 'Someone'),
                        'mine', m.author_contact_id = current_contact_id())
                      ORDER BY m.created_at)
                 FROM contract_note_messages m
                WHERE m.note_id = n.id AND m.deleted_at IS NULL), '[]'::jsonb) AS messages
        FROM contract_notes n
       WHERE n.document_id = p_document_id AND n.deleted_at IS NULL
    ) t
$$;


--
-- Name: contract_notification_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_notification_log(p_document_id uuid) RETURNS TABLE(kind text, category text, title text, author text, reason text, recipient text, raised_at timestamp with time zone, emailed_at timestamp with time zone, locations text[], outcome text, outcome_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT nl.kind, nl.category, nl.title,
         coalesce((SELECT nullif(trim(concat_ws(' ', pr.first_name, pr.last_name)), '')
                     FROM profiles pr WHERE pr.user_id = nl.author_user_id), 'system'),
         nl.reason,
         coalesce((SELECT nullif(trim(concat_ws(' ', pr.first_name, pr.last_name)), '')
                     FROM profiles pr WHERE pr.user_id = nl.recipient_user_id),
                  nl.recipient_email),
         nl.raised_at, nl.emailed_at, nl.locations, nl.outcome, nl.outcome_at
    FROM notification_log nl
   WHERE has_staff_access()
     AND nl.org_id = current_org()
     AND position(p_document_id::text in coalesce(nl.link, '')) > 0
   ORDER BY nl.raised_at
$$;


--
-- Name: contract_notify(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_notify(p_document_id uuid, p_to_contact uuid, p_kind text, p_title text, p_body text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_user uuid;
BEGIN
  IF p_to_contact IS NULL THEN RETURN; END IF;
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id;
  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_to_contact;
  IF v_user IS NOT NULL AND v_org IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
      VALUES (v_org, v_user, p_kind, p_title, p_body,
              '/app/contracts/' || p_document_id::text);
  END IF;
END;
$$;


--
-- Name: FUNCTION contract_notify(p_document_id uuid, p_to_contact uuid, p_kind text, p_title text, p_body text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_notify(p_document_id uuid, p_to_contact uuid, p_kind text, p_title text, p_body text) IS 'Internal contract-engine notification producer: inserts a notifications row (org stamped from the document) for the target contact''s app user, no-op when unaccounted. Used instead of notify_user because a non-staff party drives share/change/review notifications and notify_user''s fence would reject them — mirrors record_signature''s own direct-insert producer.';


--
-- Name: contract_party_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_party_options() RETURNS TABLE(id uuid, name text, email text, is_company boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id,
         CASE WHEN c.is_company
              THEN coalesce(nullif(trim(c.first_name), ''), 'French Heritage Equestrian')
              ELSE trim(concat_ws(' ', c.first_name, c.last_name)) END,
         c.email,
         c.is_company
  FROM contacts c
  WHERE c.org_id = current_org()
    AND c.deleted_at IS NULL
    AND has_staff_access()
    AND (
      c.is_company
      OR (
        NOT EXISTS (
          SELECT 1 FROM profiles p
          WHERE p.contact_id = c.id
            AND (p.role IN ('ADMIN','MANAGER','EMPLOYEE','SUPER_ADMIN') OR p.is_admin)
        )
        AND (
          nullif(trim(concat_ws(' ', c.first_name, c.last_name)), '') IS NOT NULL
          AND trim(concat_ws(' ', c.first_name, c.last_name)) <> 'Unnamed Contact'
        )
      )
    )
  ORDER BY c.is_company DESC, c.last_name NULLS LAST, c.first_name
$$;


--
-- Name: contract_redline_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_redline_state(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT ((has_staff_access() AND v_org = current_org()) OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized for this document';
  END IF;

  RETURN jsonb_build_object(
    'field_proposals', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
          'field_key', cf.field_key, 'label', cf.label,
          'current_value', cf.value, 'proposed_value', cf.proposed_value,
          'proposed_by', nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'mine', cf.proposed_by_contact_id = current_contact_id(),
          'proposed_at', cf.proposed_at) ORDER BY cf.sort_order), '[]'::jsonb)
      FROM contract_fields cf
      LEFT JOIN contacts c ON c.id = cf.proposed_by_contact_id
      WHERE cf.document_id = p_document_id AND cf.proposed_by_contact_id IS NOT NULL
    ),
    'addenda', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
          'id', a.id, 'item_number', a.item_number, 'body', a.body, 'status', a.status,
          'proposed_by_role', a.proposed_by_role,
          'proposed_by', nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'mine', a.proposed_by_contact_id = current_contact_id(),
          'created_at', a.created_at) ORDER BY a.item_number), '[]'::jsonb)
      FROM contract_addenda a
      LEFT JOIN contacts c ON c.id = a.proposed_by_contact_id
      WHERE a.document_id = p_document_id AND a.status IN ('open','accepted')
    ),
    'pending_compositions', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
          'id', pc.id, 'spec', pc.spec, 'status', pc.status,
          'proposed_by_role', pc.proposed_by_role,
          'proposed_by', nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'mine', pc.proposed_by_contact_id = current_contact_id(),
          'created_at', pc.created_at) ORDER BY pc.created_at), '[]'::jsonb)
      FROM contract_pending_compositions pc
      LEFT JOIN contacts c ON c.id = pc.proposed_by_contact_id
      WHERE pc.document_id = p_document_id AND pc.status IN ('open','rejected')
    ),
    'can_suggest', caller_may_propose(p_document_id, 'suggest'),
    'can_add_clause', caller_may_propose(p_document_id, 'add_clause'),
    'can_edit_deal', caller_may_propose(p_document_id, 'edit_deal')
  );
END;
$$;


--
-- Name: contract_reminder_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_reminder_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n integer := 0;
  r record;
  admin_user uuid;
BEGIN
  -- locked but unsigned for 3+ days → nudge org admins to follow up
  FOR r IN
    SELECT d.id, d.org_id, d.title
    FROM documents d
    WHERE d.workflow_state = 'locked' AND d.status <> 'EXECUTED'
      AND d.deleted_at IS NULL
      AND d.updated_at < now() - interval '3 days'
  LOOP
    FOR admin_user IN
      SELECT pr.user_id FROM profiles pr WHERE pr.org_id = r.org_id AND pr.role = 'ADMIN'
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.user_id = admin_user AND n.kind = 'contract_followup'
          AND n.link = '/app/contracts/' || r.id
          AND n.created_at > now() - interval '3 days'
      ) THEN
        PERFORM notify_user(admin_user, 'contract_followup',
          'Unsigned contract needs a follow-up',
          coalesce(r.title, 'A contract') || ' has been locked for 3+ days without all signatures.',
          '/app/contracts/' || r.id);
        v_n := v_n + 1;
      END IF;
    END LOOP;
  END LOOP;
  -- lease start/expiry moved to lease_reminder_sweep() (Slice 7).
  RETURN jsonb_build_object('notifications_created', v_n);
END;
$$;


--
-- Name: contract_review_payload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_review_payload(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me       uuid := current_contact_id();
  v_org      uuid;
  v_title    text;
  v_editor   text;
  v_note     text;
  v_recips   jsonb := '[]'::jsonb;
  r          record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, coalesce(title, 'A document') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;

  SELECT coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''), email, 'The other party')
    INTO v_editor FROM contacts WHERE id = v_me;

  -- The most recent review note the editor left, if any — the message that must
  -- travel in the email so they can read it WITHOUT opening the contract.
  SELECT l.detail ->> 'message' INTO v_note
    FROM contract_change_log l
   WHERE l.document_id = p_document_id
     AND l.change_kind IN ('review_requested','signature_removed')
     AND l.detail ->> 'message' IS NOT NULL
   ORDER BY l.created_at DESC
   LIMIT 1;

  -- Every OTHER party (not the editor). Each gets the changes computed for THEM
  -- (their signature came off, so the diff anchors on their withdrawal).
  FOR r IN
    SELECT DISTINCT dp.contact_id,
           coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email, 'there') AS name,
           c.email AS email,
           dp.party_role
      FROM document_parties dp
      JOIN contacts c ON c.id = dp.contact_id
     WHERE dp.document_id = p_document_id
       AND dp.contact_id IS DISTINCT FROM v_me
       AND NOT coalesce(c.is_company, false)
       AND c.email IS NOT NULL
  LOOP
    v_recips := v_recips || jsonb_build_array(jsonb_build_object(
      'contact_id', r.contact_id,
      'name', r.name,
      'email', r.email,
      'party_role', r.party_role,
      'changes', document_changes_since_signature(p_document_id, r.contact_id)));
  END LOOP;

  RETURN jsonb_build_object(
    'org_id', v_org,
    'document_id', p_document_id,
    'title', v_title,
    'editor', v_editor,
    'note', v_note,
    'link', '/app/contracts/' || p_document_id::text,
    'recipients', v_recips);
END;
$$;


--
-- Name: contract_role_document_requirements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_role_document_requirements(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_contract uuid;
  v_key      text;
  v_rows     jsonb;
BEGIN
  SELECT d.org_id, d.contract_id, ct.template_key
    INTO v_org, v_contract, v_key
    FROM documents d
    LEFT JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  -- Readable by staff, and by anyone who is themselves a party to this contract:
  -- a lessee is entitled to see what their own role owes.
  IF NOT coalesce(has_staff_access(), false) THEN
    -- non-staff caller: must be a party to this contract to read its requirements
    IF NOT EXISTS (SELECT 1 FROM document_parties dp
                    WHERE dp.document_id = p_document_id
                      AND dp.contact_id = current_contact_id()) THEN
      RAISE EXCEPTION 'not a party to this contract';
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY x->>'party_role', x->>'template_key'), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'contact_id',   dp.contact_id,
             'party_role',   dp.party_role,
             'party_name',   nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
             'party_email',  c.email,
             'template_key', crd.template_key,
             'title',        coalesce(t.title, crd.template_key),
             -- SATISFIED = an executed document of this template already on file
             -- for this party. Deliberately NOT contract-scoped: signing the
             -- Company Policies twice is not an obligation, it is a nuisance.
             'satisfied',    sat.document_id IS NOT NULL,
             'satisfied_document_id', sat.document_id,
             -- Anything of this template already sitting on THIS contract,
             -- whoever it is addressed to — the disagreement described above is
             -- visible rather than assumed away.
             'on_this_contract_document_id', onc.document_id,
             'on_this_contract_addressed_to', onc.contact_id,
             -- Who creates it, when it does not exist yet. DEALAUTO 2026-08-22:
             -- keyed on the TEMPLATE, not on lease-vs-sale. ensure_horse_documents
             -- owns these two on both kinds — on a lease it addresses them to the
             -- lessor, who stays the owner; on a sale to the buyer, who has just
             -- become one. Gated on `v_is_lease` it read 'unassigned' for a sale,
             -- and the role-bundle generator would have made a second copy.
             'owned_by',     CASE
               WHEN crd.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
                    AND NOT is_horse_lease_template(v_key)
                 THEN 'ensure_horse_documents@execution'
               ELSE 'unassigned' END
           ) AS x
      FROM document_parties dp
      JOIN contacts c ON c.id = dp.contact_id
      JOIN contract_role_documents crd
        ON crd.org_id = v_org AND crd.doc_role = dp.party_role AND crd.active
      LEFT JOIN contract_templates t ON t.template_key = crd.template_key
      LEFT JOIN LATERAL (
        SELECT d2.id AS document_id FROM documents d2
         JOIN contract_templates t2 ON t2.id = d2.template_id
        WHERE d2.contact_id = dp.contact_id AND t2.template_key = crd.template_key
          AND d2.status = 'EXECUTED' AND d2.deleted_at IS NULL
        ORDER BY d2.generated_at DESC NULLS LAST LIMIT 1) sat ON true
      LEFT JOIN LATERAL (
        SELECT d3.id AS document_id, d3.contact_id FROM documents d3
         JOIN contract_templates t3 ON t3.id = d3.template_id
        WHERE t3.template_key = crd.template_key AND d3.deleted_at IS NULL
          AND (d3.contract_id IS NOT DISTINCT FROM v_contract AND v_contract IS NOT NULL)
        ORDER BY d3.generated_at DESC NULLS LAST LIMIT 1) onc ON true
     WHERE dp.document_id = p_document_id
       AND dp.party_role IN ('BUYER','LESSEE','LESSOR','SELLER')
       -- ⚠️ NEVER THE COMPANY. Wired literally, the seed table asks the LESSOR to
       -- sign Company Policies and a visitor liability release — and on every
       -- lease FHE writes, the LESSOR *is* French Heritage Equestrian.
       AND NOT coalesce(c.is_company, false)
  ) s;

  RETURN jsonb_build_object(
    'document_id', p_document_id,
    'contract_id', v_contract,
    'template_key', v_key,
    'requirements', v_rows);
END;
$$;


--
-- Name: contract_section_tree(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_section_tree(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_tkey text; v_fields jsonb := '{}'::jsonb;
  v_sec record; v_cl record; r record;
  v_sec_no int := 0; v_cl_no int;
  v_subs jsonb; v_out jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT d.org_id, ct.template_key INTO v_org, v_tkey
    FROM documents d
    LEFT JOIN contract_templates ct ON ct.id = d.template_id
   WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to read document %', p_document_id;
  END IF;

  IF v_tkey IS NULL
     OR NOT EXISTS (SELECT 1 FROM contract_clause_defs WHERE template_key = v_tkey) THEN
    RETURN '[]'::jsonb;   -- not a clause-model document
  END IF;

  -- the document's own field values decide every cut/conditional gate
  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val
             FROM contract_fields WHERE document_id = p_document_id LOOP
    v_fields := v_fields || jsonb_build_object(r.field_key, r.val);
  END LOOP;

  FOR v_sec IN
    SELECT * FROM contract_section_defs WHERE template_key = v_tkey ORDER BY sort_order
  LOOP
    IF v_sec.cut_name IS NOT NULL AND NOT clause_cut_kept(v_sec.cut_name, v_fields) THEN
      CONTINUE;                                  -- cut: consumes no number
    END IF;

    -- buffer the clauses first: the section only earns a number once it has
    -- content, and the subsection numbers embed that section number.
    v_cl_no  := 0;
    v_subs   := '[]'::jsonb;

    FOR v_cl IN
      SELECT * FROM contract_clause_defs
       WHERE template_key = v_tkey AND section_key = v_sec.section_key
       ORDER BY sort_order
    LOOP
      IF v_cl.cut_name IS NOT NULL AND NOT clause_cut_kept(v_cl.cut_name, v_fields) THEN
        CONTINUE;
      END IF;
      IF NOT clause_condition_met(v_cl.conditional_on, v_fields) THEN
        CONTINUE;
      END IF;
      -- remerge folds an unheaded subitem into the previous line — no number
      IF coalesce(v_cl.render_as_subitem, false)
         AND (v_cl.heading IS NULL OR v_cl.heading = '') THEN
        CONTINUE;
      END IF;

      v_cl_no := v_cl_no + 1;
      v_subs := v_subs || jsonb_build_array(jsonb_build_object(
        'clause_key', v_cl.clause_key,
        'sub_index',  v_cl_no,
        'title',      coalesce(nullif(trim(v_cl.heading), ''), v_sec.heading),
        'guidance',   v_cl.guidance));
    END LOOP;

    -- an empty section is not composed and consumes no number
    IF v_cl_no = 0 THEN CONTINUE; END IF;

    v_sec_no := v_sec_no + 1;

    -- stamp the now-known section number onto each subsection
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'clause_key', x->>'clause_key',
             'number',     v_sec_no || '.' || (x->>'sub_index'),
             'title',      x->>'title',
             'guidance',   x->>'guidance') ORDER BY ord), '[]'::jsonb)
      INTO v_subs
      FROM jsonb_array_elements(v_subs) WITH ORDINALITY q(x, ord);

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'section_key', v_sec.section_key,
      'number',      v_sec_no::text,
      'title',       v_sec.heading,
      'guidance',    v_sec.guidance,
      'subsections', v_subs));
  END LOOP;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION contract_section_tree(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contract_section_tree(p_document_id uuid) IS 'Live section/subsection tree for a clause-model document, numbered exactly as remerge_contract_from_clauses composes merged_body (cut/conditional gating applied, unheaded render_as_subitem clauses folded away). The change-request and change-history menus derive their numbers from this — never hardcoded.';


--
-- Name: contract_send_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_send_state(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_out jsonb;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT coalesce(has_staff_access() AND v_org = current_org(), false) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY x.party_role), '[]'::jsonb) INTO v_out
  FROM (
    SELECT
      dp.party_role,
      dp.contact_id,
      coalesce(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), c.email, 'A party') AS party_name,
      c.email AS party_email,
      EXISTS (SELECT 1 FROM invitations i
               WHERE i.contact_id = dp.contact_id AND i.deleted_at IS NULL) AS has_invitation,
      pr.user_id IS NOT NULL AS has_auth,
      (u.last_sign_in_at IS NOT NULL) AS has_session,
      -- their assigned, unsatisfied, non-WITH_CONTRACT documents (to sequence against)
      coalesce((
        SELECT jsonb_agg(jsonb_build_object('template_key', crd.template_key,
                 'title', coalesce(ct.title, crd.template_key)) ORDER BY crd.template_key)
          FROM contact_required_documents crd
          JOIN contract_templates ct ON ct.template_key = crd.template_key
           AND ct.active AND ct.deleted_at IS NULL
         WHERE crd.contact_id = dp.contact_id
           AND crd.skipped_at IS NULL
           AND crd.disposition <> 'WITH_CONTRACT'
           AND NOT contact_document_satisfied(dp.contact_id, crd.template_key)
      ), '[]'::jsonb) AS unsigned_docs
    FROM document_parties dp
    LEFT JOIN contacts c ON c.id = dp.contact_id
    LEFT JOIN profiles pr ON pr.contact_id = dp.contact_id
    LEFT JOIN auth.users u ON u.id = pr.user_id
    WHERE dp.document_id = p_document_id
      AND dp.is_signer
      AND dp.party_role NOT IN ('FHE','COMPANY')
  ) x;
  RETURN v_out;
END
$$;


--
-- Name: contract_signing_set(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_signing_set(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ctr   uuid;
  v_org   uuid;
  v_may   boolean;
  v_me    uuid;
  v_staff boolean;
BEGIN
  SELECT contract_id, org_id INTO v_ctr, v_org
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_ctr IS NULL THEN RETURN '[]'::jsonb; END IF;

  v_may := (coalesce(has_staff_access() AND v_org = current_org(), false))
    OR caller_is_document_party(p_document_id)
    OR EXISTS (SELECT 1 FROM documents d
                WHERE d.id = p_document_id AND d.horse_id IS NOT NULL
                  AND client_can_read_horse(d.horse_id));
  IF NOT v_may THEN RAISE EXCEPTION 'not authorized for this document set'; END IF;

  v_me    := current_contact_id();
  v_staff := coalesce(has_staff_access() AND v_org = current_org(), false);

  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'document_id', d.id,
        'title', d.title,
        'template_key', t.template_key,
        'short_label', coalesce(t.short_label, t.title),
        'sign_sequence', d.sign_sequence,
        'status', d.status,
        'executed', d.status = 'EXECUTED',
        'i_sign',   seat.mine > 0,
        'i_signed', seat.mine > 0 AND seat.unsigned = 0
      ) ORDER BY d.sign_sequence NULLS LAST, d.created_at), '[]'::jsonb)
    FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
    LEFT JOIN LATERAL (
      SELECT count(*) AS mine,
             count(*) FILTER (WHERE NOT EXISTS (
               SELECT 1 FROM signatures s
                WHERE s.document_id = dp.document_id
                  AND s.signer_contact_id = dp.contact_id
                  AND s.party_role = dp.party_role
                  AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL)) AS unsigned
        FROM document_parties dp
        JOIN contacts c ON c.id = dp.contact_id
       WHERE dp.document_id = d.id AND dp.is_signer
         AND (dp.contact_id = v_me
              -- record_signature's company branch: staff complete the org's
              -- own company seat, which has no login of its own
              OR (v_staff AND coalesce(c.is_company, false)
                  AND c.org_id = v_org AND c.deleted_at IS NULL))
    ) seat ON true
    WHERE d.contract_id = v_ctr AND d.deleted_at IS NULL AND d.sign_sequence IS NOT NULL
  );
END;
$$;


--
-- Name: contract_signing_set_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_signing_set_complete(p_contract_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT delivery_set_complete(p_contract_id);
$$;


--
-- Name: contract_split_deductible_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_split_deductible_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_base text;
  v_counterpart text;
  v_mode text;
  v_anchor_key text;
  v_anchor text;
  v_n numeric;
  v_d numeric;
  v_fmv numeric;
  v_self text;
  v_other text;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  -- coverage toggles: clear the block's dependent fields when switched off
  IF NEW.field_key = 'TXN.MORT_ELECTED' AND coalesce(NEW.value,'') <> 'YES'
     AND NEW.value IS DISTINCT FROM OLD.value THEN
    UPDATE contract_fields SET value=''
     WHERE document_id=NEW.document_id AND field_key LIKE 'TXN.MORT\_%'
       AND field_key <> 'TXN.MORT_ELECTED' AND coalesce(value,'') <> '';
    RETURN NEW;
  END IF;
  IF NEW.field_key = 'TXN.MED_COVERAGE' AND coalesce(NEW.value,'') <> 'COVERED'
     AND NEW.value IS DISTINCT FROM OLD.value THEN
    UPDATE contract_fields SET value=''
     WHERE document_id=NEW.document_id AND field_key LIKE 'TXN.MED\_%'
       AND field_key <> 'TXN.MED_COVERAGE' AND coalesce(value,'') <> '';
    RETURN NEW;
  END IF;

  -- mortality limit: must be >= the horse's fair market value
  IF NEW.field_key = 'TXN.MORT_LIMIT' AND coalesce(NEW.value,'') <> '' THEN
    BEGIN
      v_n := nullif(regexp_replace(NEW.value, '[^0-9.]', '', 'g'), '')::numeric;
      SELECT nullif(regexp_replace(coalesce(value,''), '[^0-9.]', '', 'g'), '')::numeric
        INTO v_fmv FROM contract_fields
       WHERE document_id=NEW.document_id AND field_key='HORSE.FAIR_MARKET_VALUE';
    EXCEPTION WHEN others THEN
      v_n := NULL; v_fmv := NULL;
    END;
    IF v_n IS NOT NULL AND v_fmv IS NOT NULL AND v_n < v_fmv THEN
      RAISE EXCEPTION 'Mortality policy limit (%) must be at least the Horse''s fair market value (%)',
        NEW.value, to_char(v_fmv, 'FM$999,999,990.00');
    END IF;
    RETURN NEW;
  END IF;

  -- stated deductible changed: recompute an active $-split against the new amount
  IF NEW.field_key IN ('TXN.MORT_DEDUCTIBLE','TXN.MED_DEDUCTIBLE')
     AND NEW.value IS DISTINCT FROM OLD.value THEN
    v_base := replace(NEW.field_key, '_DEDUCTIBLE', '') || '_DED_RESP';
    SELECT value INTO v_mode FROM contract_fields
     WHERE document_id=NEW.document_id AND field_key = v_base || '_MODE';
    IF v_mode = 'DOLLAR' THEN
      UPDATE contract_fields SET value=''
       WHERE document_id=NEW.document_id
         AND field_key IN (v_base || '_SPLIT_LESSOR', v_base || '_SPLIT_LESSEE')
         AND coalesce(value,'') <> '';
    END IF;
    RETURN NEW;
  END IF;

  -- responsibility selection changed: clear children that no longer apply
  IF NEW.field_key ~ '_RESP$' THEN
    IF NEW.value IS DISTINCT FROM OLD.value THEN
      IF coalesce(NEW.value,'') <> 'SPLIT' THEN
        UPDATE contract_fields SET value=''
         WHERE document_id=NEW.document_id
           AND field_key IN (NEW.field_key || '_MODE', NEW.field_key || '_SPLIT_LESSOR', NEW.field_key || '_SPLIT_LESSEE')
           AND coalesce(value,'') <> '';
      END IF;
      IF coalesce(NEW.value,'') <> 'OTHER' THEN
        UPDATE contract_fields SET value=''
         WHERE document_id=NEW.document_id
           AND field_key = NEW.field_key || '_OTHER' AND coalesce(value,'') <> '';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- mode change: clear both shares for fresh entry
  IF NEW.field_key ~ '_RESP_MODE$' THEN
    IF NEW.value IS DISTINCT FROM OLD.value THEN
      v_base := regexp_replace(NEW.field_key, '_MODE$', '');
      UPDATE contract_fields SET value=''
       WHERE document_id=NEW.document_id
         AND field_key IN (v_base || '_SPLIT_LESSOR', v_base || '_SPLIT_LESSEE')
         AND coalesce(value,'') <> '';
    END IF;
    RETURN NEW;
  END IF;

  -- share entry: normalize + auto-fill counterpart. $-anchored groups
  -- (mortality/medical deductible) resolve mode from _RESP_MODE; all other
  -- groups are %-only.
  IF NEW.field_key !~ '_RESP_SPLIT_(LESSOR|LESSEE)$' THEN RETURN NEW; END IF;
  IF coalesce(NEW.value,'') = '' OR NEW.value IS NOT DISTINCT FROM OLD.value THEN
    RETURN NEW;
  END IF;
  v_base := regexp_replace(NEW.field_key, '_SPLIT_(LESSOR|LESSEE)$', '');
  v_counterpart := CASE WHEN NEW.field_key LIKE '%_LESSOR'
                        THEN v_base || '_SPLIT_LESSEE' ELSE v_base || '_SPLIT_LESSOR' END;

  v_anchor_key := CASE v_base
                    WHEN 'TXN.MORT_DED_RESP' THEN 'TXN.MORT_DEDUCTIBLE'
                    WHEN 'TXN.MED_DED_RESP'  THEN 'TXN.MED_DEDUCTIBLE'
                    ELSE NULL END;
  IF v_anchor_key IS NOT NULL THEN
    SELECT value INTO v_mode FROM contract_fields
     WHERE document_id=NEW.document_id AND field_key = v_base || '_MODE';
  ELSE
    v_mode := 'PERCENT';
  END IF;

  BEGIN
    v_n := nullif(regexp_replace(NEW.value, '[^0-9.]', '', 'g'), '')::numeric;
  EXCEPTION WHEN others THEN
    v_n := NULL;
  END;
  IF v_n IS NULL THEN RETURN NEW; END IF;

  IF v_mode = 'PERCENT' THEN
    IF v_n < 0 OR v_n > 100 THEN
      RAISE EXCEPTION 'A percentage share must be between 0 and 100 (got %)', NEW.value;
    END IF;
    v_self  := to_char(v_n, 'FM990.##') || '%';
    v_other := to_char(100 - v_n, 'FM990.##') || '%';
  ELSIF v_mode = 'DOLLAR' THEN
    SELECT value INTO v_anchor FROM contract_fields
     WHERE document_id=NEW.document_id AND field_key = v_anchor_key;
    BEGIN
      v_d := nullif(regexp_replace(coalesce(v_anchor,''), '[^0-9.]', '', 'g'), '')::numeric;
    EXCEPTION WHEN others THEN
      v_d := NULL;
    END;
    IF v_d IS NULL THEN RETURN NEW; END IF;
    IF v_n > v_d THEN
      RAISE EXCEPTION 'A $ share (%) cannot exceed the stated deductible (%)',
        NEW.value, to_char(v_d, 'FM$999,999,990.00');
    END IF;
    v_self  := to_char(v_n, 'FM$999,999,990.00');
    v_other := to_char(v_d - v_n, 'FM$999,999,990.00');
  ELSE
    RETURN NEW; -- no mode chosen yet
  END IF;

  IF v_self IS DISTINCT FROM NEW.value THEN
    UPDATE contract_fields SET value = v_self
     WHERE document_id=NEW.document_id AND field_key = NEW.field_key;
  END IF;
  UPDATE contract_fields SET value = v_other
   WHERE document_id=NEW.document_id AND field_key = v_counterpart
     AND value IS DISTINCT FROM v_other;
  RETURN NEW;
END;
$_$;


--
-- Name: contract_template_structure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_template_structure(p_template_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'template_key', p_template_key,
    -- TASK-ONEAUTHOR: which surfaces this document type can actually have.
    -- Absent template row -> the permissive default, identical to pre-config
    -- behaviour, so an unknown key never silently loses a drawer.
    'config', coalesce((
      SELECT jsonb_build_object(
        'title',                  t.title,
        'short_label',            coalesce(t.short_label, t.title),
        'contract_kind',          t.contract_kind,
        'show_comments',          t.show_comments,
        'show_change_requests',   t.show_change_requests,
        'show_history',           t.show_history,
        'show_party_controls',    t.show_party_controls,
        'allows_co_buyer',        t.allows_co_buyer,
        'companion_template_key', t.companion_template_key,
        'companion_label', (
          SELECT coalesce(c.short_label, c.title)
            FROM contract_templates c
           WHERE c.template_key = t.companion_template_key
             AND c.active AND c.deleted_at IS NULL)
      )
      FROM contract_templates t
      WHERE t.template_key = p_template_key
    ), jsonb_build_object(
        'title',                  NULL,
        'short_label',            NULL,
        'contract_kind',          NULL,
        'show_comments',          true,
        'show_change_requests',   true,
        'show_history',           true,
        'show_party_controls',    true,
        'allows_co_buyer',        false,
        'companion_template_key', NULL,
        'companion_label',        NULL
    )),
    'sections', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'section_key', s.section_key,
        'heading', s.heading,
        'sort_order', s.sort_order,
        'is_optional', s.is_optional,
        'guidance', s.guidance,
        'clauses', coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'clause_key', c.clause_key,
            'heading', c.heading,
            'body', c.body,
            'clause_type', c.clause_type,
            'sort_order', c.sort_order,
            'is_optional', c.is_optional,
            'conditional_on', c.conditional_on,
            'guidance', c.guidance
          ) ORDER BY c.sort_order)
          FROM contract_clause_defs c
          WHERE c.template_key = p_template_key AND c.section_key = s.section_key
        ), '[]'::jsonb)
      ) ORDER BY s.sort_order)
      FROM contract_section_defs s WHERE s.template_key = p_template_key
    ), '[]'::jsonb)
  );
$$;


--
-- Name: contract_template_version_at(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_template_version_at(p_template_key text, p_version integer) RETURNS TABLE(version integer, parent_version integer, title text, body text, composition jsonb, is_current boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.title, v.body, v.composition,
         v.version = ct.version as is_current, v.created_at
    from contract_template_versions v
    join contract_templates ct on ct.template_key = v.template_key
   where v.template_key = p_template_key and v.version = p_version
     and has_staff_access()
$$;


--
-- Name: contract_template_version_list(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_template_version_list(p_template_key text) RETURNS TABLE(version integer, parent_version integer, is_current boolean, title text, clause_count integer, edited_by uuid, edited_by_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.version = ct.version as is_current, v.title,
         coalesce(jsonb_array_length(v.composition->'clauses'), 0)::integer as clause_count,
         v.edited_by,
         coalesce(nullif(btrim(coalesce(p.display_name, '')), ''),
                  nullif(btrim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''),
                  p.email) as edited_by_name,
         v.created_at
    from contract_template_versions v
    join contract_templates ct on ct.template_key = v.template_key
    left join profiles p on p.user_id = v.edited_by
   where v.template_key = p_template_key
     and has_staff_access()
   order by v.version desc
$$;


--
-- Name: contract_view_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_view_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc        documents%ROWTYPE;
  v_gov_status text;
  v_parties    jsonb;
  v_disclosure jsonb;
BEGIN
  -- Resolve the token -> its document. Only a live CONTRACT_VIEW token reads;
  -- a token of any other kind returns nothing, so an activation/claim token
  -- cannot be bent into a reader.
  SELECT d.* INTO v_doc
    FROM invitations i
    JOIN documents d ON d.id = i.document_id AND d.deleted_at IS NULL
   WHERE i.token = p_token
     AND coalesce(i.kind, '') = 'CONTRACT_VIEW'
     AND i.deleted_at IS NULL
   ORDER BY i.created_at DESC
   LIMIT 1;

  IF v_doc.id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  -- The GOVERNING document decides the dead-switch (report item 3). On a contract
  -- it is the sign_sequence = 1 document; a standalone document is its own.
  IF v_doc.contract_id IS NOT NULL THEN
    SELECT d2.status INTO v_gov_status
      FROM documents d2
     WHERE d2.contract_id = v_doc.contract_id AND d2.deleted_at IS NULL
       AND d2.sign_sequence = 1
     LIMIT 1;
  END IF;
  v_gov_status := coalesce(v_gov_status, v_doc.status);

  -- Valid until signed: once the governing document executes the link goes dead
  -- for every token-holder at once.
  IF v_gov_status = 'EXECUTED' THEN
    RETURN jsonb_build_object('found', true, 'executed', true);
  END IF;

  -- Parties' display names — the names the instrument prints, nothing more. Taken
  -- from the merged party-name fields, not the contact record, so no off-instrument
  -- PII is reachable through this function.
  SELECT coalesce(jsonb_agg(jsonb_build_object('role', role, 'name', nm)
                            ORDER BY role), '[]'::jsonb)
    INTO v_parties
    FROM (
      SELECT split_part(cf.field_key, '.', 1) AS role, cf.value AS nm
        FROM contract_fields cf
       WHERE cf.document_id = v_doc.id
         AND cf.field_key LIKE '%.FULL_NAME'
         AND coalesce(btrim(cf.value), '') <> ''
    ) p;

  -- The HORSE.<SECTION> disclosure structured values the boxed component renders.
  -- Only the disclosure sections — never the full editable field graph.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
                    'field_key', cf.field_key, 'structured', cf.structured)), '[]'::jsonb)
    INTO v_disclosure
    FROM contract_fields cf
   WHERE cf.document_id = v_doc.id
     AND cf.field_key LIKE 'HORSE.%'
     AND cf.structured IS NOT NULL;

  RETURN jsonb_build_object(
    'found', true,
    'executed', false,
    'document_id', v_doc.id,
    'title', v_doc.title,
    'body', v_doc.merged_body,
    'parties', v_parties,
    'disclosure_fields', v_disclosure);
END;
$$;


--
-- Name: contracts_ensure_deal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contracts_ensure_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    PERFORM ensure_deal_for_contract(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'contracts_ensure_deal: no deal opened for contract %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;


--
-- Name: correct_claimant_name_from_signup(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_claimant_name_from_signup(p_contact_id uuid, p_first_name text, p_last_name text, p_requester_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c     contacts%ROWTYPE;
  v_first text := nullif(btrim(coalesce(p_first_name, '')), '');
  v_last  text := nullif(btrim(coalesce(p_last_name,  '')), '');
BEGIN
  -- Same authorization gate fill_claimant_details uses. The door holds the
  -- service-role key; nothing anonymous reaches this.
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF p_contact_id IS NULL OR v_first IS NULL THEN RETURN false; END IF;
  IF nullif(btrim(coalesce(p_requester_hash, '')), '') IS NULL THEN RETURN false; END IF;

  SELECT * INTO v_c FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  -- 4. it must actually differ
  IF btrim(coalesce(v_c.first_name, '')) = v_first
     AND btrim(coalesce(v_c.last_name, '')) IS NOT DISTINCT FROM v_last THEN
    RETURN false;
  END IF;

  -- 1. same requester, on an earlier attempt for this same address
  IF v_c.email IS NULL OR NOT EXISTS (
       SELECT 1 FROM signup_attempts sa
        WHERE lower(sa.email) = lower(v_c.email)
          AND sa.requester_hash = p_requester_hash) THEN
    RETURN false;
  END IF;

  -- 2. nothing signed
  IF EXISTS (SELECT 1 FROM signatures s
              WHERE s.signer_contact_id = p_contact_id
                AND s.deleted_at IS NULL AND s.signed_at IS NOT NULL) THEN
    RETURN false;
  END IF;

  -- 3. no human has deliberately set this name in-app
  IF EXISTS (
       SELECT 1 FROM audit_logs a
        WHERE a.table_name = 'contacts' AND a.action = 'UPDATE'
          AND a.record_id = p_contact_id
          AND a.actor_user_id IS NOT NULL
          AND (a.old_value->>'first_name' IS DISTINCT FROM a.new_value->>'first_name'
            OR a.old_value->>'last_name'  IS DISTINCT FROM a.new_value->>'last_name')) THEN
    RETURN false;
  END IF;

  -- family_sort_key is maintained by contacts_family_sort_key_trg and the name
  -- reaches profiles through sync_profile_name_from_contact_trg. Neither is
  -- written by hand here — that is what made the incident traceable at all.
  UPDATE contacts
     SET first_name = v_first,
         last_name  = v_last,
         name_needs_confirmation = false,
         updated_at = now()
   WHERE id = p_contact_id;

  RETURN true;
END;
$$;


--
-- Name: create_contract_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_contract_note(p_document_id uuid, p_title text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_id uuid; v_n int; v_title text;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (has_staff_access() OR EXISTS (
            SELECT 1 FROM document_parties dp
             WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id())) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  -- N counts every comment ever created on this document, deleted ones included,
  -- so a default title is never reused after a deletion.
  SELECT count(*) + 1 INTO v_n FROM contract_notes WHERE document_id = p_document_id;
  v_title := coalesce(nullif(trim(coalesce(p_title, '')), ''), 'Comment ' || v_n);

  INSERT INTO contract_notes (org_id, document_id, title, created_by_contact_id)
  VALUES (v_org, p_document_id, v_title, current_contact_id())
  RETURNING id INTO v_id;
  RETURN v_id;
END
$$;


--
-- Name: create_deal(text, uuid[], uuid[], text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_deal(p_deal_type text, p_party_a_contact_ids uuid[] DEFAULT '{}'::uuid[], p_party_b_contact_ids uuid[] DEFAULT '{}'::uuid[], p_notes text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_horse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_roles text[]; v_contract uuid; v_deal uuid; v_id uuid; v_n int := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to create a deal'; END IF;

  v_roles := deal_party_roles(p_deal_type);
  IF v_roles IS NULL THEN
    RAISE EXCEPTION 'unknown deal type: % (expected SALE or LEASE)', p_deal_type;
  END IF;

  v_org := current_org();

  INSERT INTO contracts (org_id, segment, status, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', current_contact_id(),
            jsonb_build_object('deal_kind', p_deal_type))
    RETURNING id INTO v_contract;

  v_deal := ensure_deal_for_contract(v_contract, p_deal_type, p_title, p_notes);
  IF v_deal IS NULL THEN
    RAISE EXCEPTION 'could not open a deal for contract %', v_contract;
  END IF;

  FOREACH v_id IN ARRAY coalesce(p_party_a_contact_ids, '{}') LOOP
    PERFORM add_deal_member(v_deal, v_roles[1], v_id); v_n := v_n + 1;
  END LOOP;
  FOREACH v_id IN ARRAY coalesce(p_party_b_contact_ids, '{}') LOOP
    PERFORM add_deal_member(v_deal, v_roles[2], v_id); v_n := v_n + 1;
  END LOOP;

  RETURN jsonb_build_object('deal_id', v_deal, 'contract_id', v_contract,
                            'deal_type', p_deal_type, 'roles', v_roles,
                            'members_added', v_n);
END;
$$;


--
-- Name: create_evaluation_report(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_evaluation_report(p_contact_id uuid, p_purchase_item_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_id  uuid;
  v_label text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF p_contact_id IS NULL THEN RAISE EXCEPTION 'contact is required'; END IF;

  -- reuse an existing draft for this purchase line if one exists
  IF p_purchase_item_id IS NOT NULL THEN
    SELECT id INTO v_id FROM evaluation_reports
     WHERE purchase_item_id = p_purchase_item_id AND status = 'draft' AND deleted_at IS NULL
     LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'reused', true); END IF;
  END IF;

  -- horse label from the submitted intake, if any
  SELECT coalesce(pi.config->>'horse_name', pi.config->>'horse_location')
    INTO v_label FROM purchase_items pi WHERE pi.id = p_purchase_item_id;

  INSERT INTO evaluation_reports (org_id, contact_id, purchase_item_id, horse_id, horse_label, title, created_by)
    VALUES (v_org, p_contact_id, p_purchase_item_id, p_horse_id, v_label,
            coalesce(p_title, 'Horse Evaluation Report'), auth.uid())
    RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'reused', false);
END;
$$;


--
-- Name: create_gift(uuid, text, text, text, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_gift(p_offering_id uuid, p_buyer_name text, p_buyer_email text, p_recipient_name text, p_recipient_email text DEFAULT NULL::text, p_gift_message text DEFAULT NULL::text, p_mark_paid boolean DEFAULT false, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_off        offerings%ROWTYPE;
  v_code       text;
  v_gift       uuid;
  v_buyer_acct jsonb;
  v_buyer_user uuid;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized to create gifts';
  END IF;

  SELECT * INTO v_off FROM offerings WHERE id = p_offering_id AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'offering not found or inactive'; END IF;
  IF v_off.price_amount IS NULL THEN
    RAISE EXCEPTION 'this offering has no price and cannot be gifted';
  END IF;

  IF nullif(btrim(coalesce(p_buyer_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'buyer name is required';
  END IF;
  IF nullif(btrim(coalesce(p_buyer_email,'')),'') IS NULL THEN
    RAISE EXCEPTION 'buyer email is required';
  END IF;
  IF nullif(btrim(coalesce(p_recipient_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'recipient name is required';
  END IF;

  -- short, unique, URL-safe claim code (the credential itself — task constraint:
  -- open_gift/redeem_gift stay unguarded/self-guarding, this is what they check)
  LOOP
    v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM gifts WHERE code = v_code);
  END LOOP;

  SELECT u.id INTO v_buyer_user FROM auth.users u
   WHERE lower(u.email) = lower(btrim(p_buyer_email)) LIMIT 1;

  INSERT INTO gifts (org_id, code, item_type, item_label, amount, offering_id,
                     buyer_name, buyer_email, buyer_user_id,
                     recipient_name, recipient_email, gift_message, status)
    VALUES (v_off.org_id, v_code, coalesce(v_off.service_type, v_off.segment),
            v_off.name, v_off.price_amount, v_off.id,
            btrim(p_buyer_name), lower(btrim(p_buyer_email)), v_buyer_user,
            btrim(p_recipient_name),
            nullif(lower(btrim(coalesce(p_recipient_email,''))), ''),
            nullif(btrim(coalesce(p_gift_message,'')),''),
            CASE WHEN p_mark_paid THEN 'paid' ELSE 'created' END)
    RETURNING id INTO v_gift;

  -- D8/4b: revives the buyer-account call site written in Stage 4 for exactly
  -- this moment — dead until now because nothing created a gift. Soft-fails:
  -- a buyer-account hiccup must not block the gift itself from existing, but
  -- (matching the D3 lesson) it must not be a silent NULL either.
  BEGIN
    v_buyer_acct := ensure_gift_buyer_account(v_gift);
  EXCEPTION WHEN others THEN
    PERFORM notify_staff(v_off.org_id, 'gift_buyer_account_failed',
      'Gift ' || v_code || ' created, but buyer account setup failed for '
        || p_buyer_email || ' — ' || SQLERRM,
      '/app/ops/intake');
  END;

  IF p_request_id IS NOT NULL THEN
    UPDATE requests SET status = 'converted' WHERE id = p_request_id;
  END IF;

  RETURN jsonb_build_object(
    'gift_id', v_gift, 'code', v_code,
    'claim_link', '/redeem?code=' || v_code,
    'buyer_contact_id', v_buyer_acct->>'contact_id');
END;
$$;


--
-- Name: FUNCTION create_gift(p_offering_id uuid, p_buyer_name text, p_buyer_email text, p_recipient_name text, p_recipient_email text, p_gift_message text, p_mark_paid boolean, p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_gift(p_offering_id uuid, p_buyer_name text, p_buyer_email text, p_recipient_name text, p_recipient_email text, p_gift_message text, p_mark_paid boolean, p_request_id uuid) IS 'The one gift-creation path (D4, owner decision 2026-08-11: staff converts an inquiry). item_type/item_label/amount captured from the linked offering so redemption can provision a real purchase against it (D1).';


--
-- Name: create_horse_record(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_horse_record(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_me    uuid := current_contact_id();
  v_org   uuid := current_org();
  v_chip  text := nullif(regexp_replace(coalesce(p ->> 'microchip_id', ''), '\s', '', 'g'), '');
  v_match horses%ROWTYPE;
  v_id    uuid;
  v_leased boolean := lower(coalesce(p ->> 'is_leased', 'no')) IN ('yes','true','1');
  v_owner_text  text := nullif(trim(concat_ws(' ', p ->> 'owner_name_text',
                          CASE WHEN nullif(p ->> 'owner_email','') IS NOT NULL
                               THEN '(' || (p ->> 'owner_email') || ')' END)), '');
  v_lessee_text text := nullif(trim(concat_ws(' ', p ->> 'lessee_name_text',
                          CASE WHEN nullif(p ->> 'lessee_email','') IS NOT NULL
                               THEN '(' || (p ->> 'lessee_email') || ')' END)), '');
BEGIN
  IF auth.uid() IS NULL OR v_me IS NULL THEN
    RAISE EXCEPTION 'an authenticated member account is required to create a horse record';
  END IF;
  IF has_staff_access() AND nullif(p ->> 'owner_contact_id','') IS NOT NULL THEN
    v_me := (p ->> 'owner_contact_id')::uuid;
  END IF;

  IF v_org IS NULL THEN RAISE EXCEPTION 'no org context'; END IF;
  IF coalesce(nullif(trim(p ->> 'nickname'), ''), nullif(trim(p ->> 'registered_name'), '')) IS NULL THEN
    RAISE EXCEPTION 'a horse name is required';
  END IF;

  IF v_chip IS NOT NULL THEN
    SELECT * INTO v_match FROM horses
     WHERE org_id = v_org AND deleted_at IS NULL
       AND regexp_replace(coalesce(microchip_id, ''), '\s', '', 'g') = v_chip
     LIMIT 1;
    IF FOUND THEN
      IF has_staff_access() OR client_can_read_horse(v_match.id) THEN
        RETURN jsonb_build_object('outcome', 'match_found', 'horse_id', v_match.id);
      ELSE
        INSERT INTO horse_reconciliation
          (org_id, existing_horse_id, claimed_by_contact_id, claim_type, claim_note, match_method)
        VALUES (v_org, v_match.id, v_me, 'OWNER', nullif(p ->> 'claim_note', ''), 'MICROCHIP');
        RETURN jsonb_build_object('outcome', 'match_pending_review');
      END IF;
    END IF;
  END IF;

  INSERT INTO horses (
    org_id, registered_name, nickname, breed, color, markings, sex,
    date_of_birth, height, sire, dam, registration_number, registration_org,
    microchip_id, passport_number, passport_country, current_location,
    fair_market_value, euthanasia_authorization,
    pending_fields,
    medical_history_list, behavioral_history_list, known_conditions_list,
    training_history_list, competition_history_list, injuries_to_humans, injuries_to_horse,
    created_by_contact_id, current_owner_contact_id, owner_name_text,
    lessee_contact_id, lessee_name_text, lease_start, lease_end)
  VALUES (
    v_org,
    nullif(trim(p ->> 'registered_name'), ''),
    nullif(trim(p ->> 'nickname'), ''),
    nullif(p ->> 'breed', ''), nullif(p ->> 'color', ''), nullif(p ->> 'markings', ''),
    nullif(p ->> 'sex', ''),
    (nullif(p ->> 'date_of_birth', ''))::date,
    nullif(p ->> 'height', ''),
    nullif(btrim(p ->> 'sire'), ''), nullif(btrim(p ->> 'dam'), ''),
    nullif(p ->> 'registration_number', ''), nullif(p ->> 'registration_org', ''),
    v_chip, nullif(p ->> 'passport_number', ''), nullif(p ->> 'passport_country', ''),
    nullif(p ->> 'current_location', ''),
    nullif(nullif(replace(replace(coalesce(p ->> 'fair_market_value', ''), '$', ''), ',', ''), '')::numeric, 0),
    nullif(p ->> 'euthanasia_authorization',''),
    coalesce(p -> 'pending_fields', '[]'::jsonb),
    coalesce(p -> 'medical_history_list', '[]'::jsonb),
    coalesce(p -> 'behavioral_history_list', '[]'::jsonb),
    coalesce(p -> 'known_conditions_list', '[]'::jsonb),
    coalesce(p -> 'training_history_list', '[]'::jsonb),
    coalesce(p -> 'competition_history_list', '[]'::jsonb),
    nullif(btrim(coalesce(p ->> 'injuries_to_humans','')),''),
    coalesce(p -> 'injuries_to_horse', '[]'::jsonb),
    v_me, v_me, v_owner_text,
    NULL, v_lessee_text,
    CASE WHEN v_leased THEN (nullif(p ->> 'lease_start', ''))::date END,
    CASE WHEN v_leased THEN (nullif(p ->> 'lease_end', ''))::date END)
  RETURNING id INTO v_id;

  INSERT INTO horse_relationships
    (org_id, horse_id, relationship, party_contact_id, created_by_contact_id)
  VALUES (v_org, v_id, 'OWNER', v_me, v_me);
  IF v_leased AND v_lessee_text IS NOT NULL THEN
    INSERT INTO horse_relationships
      (org_id, horse_id, relationship, party_name_text, created_by_contact_id, term_start, term_end)
    VALUES (v_org, v_id, 'LESSEE', v_lessee_text, v_me,
            (nullif(p ->> 'lease_start',''))::date, (nullif(p ->> 'lease_end',''))::date);
  END IF;

  IF v_chip IS NULL THEN
    INSERT INTO horse_reconciliation
      (org_id, existing_horse_id, claimed_by_contact_id, claim_type, claim_note, match_method)
    SELECT v_org, h.id, v_me, 'OTHER',
           'possible duplicate of new record ' || v_id::text, 'FUZZY'
    FROM horses h
    WHERE h.org_id = v_org AND h.deleted_at IS NULL AND h.id <> v_id
      AND lower(coalesce(h.registered_name, '')) = lower(coalesce(p ->> 'registered_name', ''))
      AND h.date_of_birth IS NOT DISTINCT FROM (nullif(p ->> 'date_of_birth',''))::date
      AND coalesce(h.color, '') = coalesce(p ->> 'color', '')
      AND nullif(p ->> 'registered_name','') IS NOT NULL
    LIMIT 3;
  END IF;

  RETURN jsonb_build_object('outcome', 'created', 'horse_id', v_id);
END;
$_$;


--
-- Name: create_my_purchase(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_purchase(p_items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_contact  uuid := current_contact_id();
  v_org      uuid := current_org();
  v_purchase uuid;
  v_off      offerings%ROWTYPE;
  v_item     jsonb;
  v_off_id   uuid;
  v_slug     text;
  v_qty      integer;
  v_config   jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no organization for this account'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'an order needs at least one item';
  END IF;

  -- Purchase unification (Phase 2/3): stamp BOTH buyer keys — the contact is the
  -- durable identity, the login is who is holding the phone.
  INSERT INTO purchases (org_id, buyer_user_id, buyer_contact_id,
                         status, amount, amount_paid, payment_status)
  VALUES (v_org, v_uid, v_contact, 'draft', 0, 0, 'unpaid')
  RETURNING id INTO v_purchase;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_off_id := nullif(btrim(coalesce(v_item->>'offering_id', '')), '')::uuid;
    v_slug   := nullif(btrim(coalesce(v_item->>'offering_slug', '')), '');

    -- The catalog is the price list. A line that does not resolve to a live
    -- offering in the caller's own org has no price we are willing to honour.
    IF v_off_id IS NOT NULL THEN
      SELECT * INTO v_off FROM offerings
       WHERE id = v_off_id AND org_id = v_org AND active;
    ELSIF v_slug IS NOT NULL THEN
      SELECT * INTO v_off FROM offerings
       WHERE slug = v_slug AND org_id = v_org AND active;
    ELSE
      RAISE EXCEPTION 'every line must name an offering';
    END IF;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'that offering is not available: %', coalesce(v_off_id::text, v_slug);
    END IF;

    v_qty := greatest(coalesce((v_item->>'quantity')::integer, 1), 1);
    -- `config` is the buyer's own words (a service address, a note). It carries no
    -- price and no entitlement, so it is passed through as given.
    v_config := CASE WHEN jsonb_typeof(v_item->'config') = 'object'
                     THEN v_item->'config' ELSE '{}'::jsonb END;

    INSERT INTO purchase_items (purchase_id, org_id, offering_id, label,
                                price_amount, price_unit, quantity, config)
    VALUES (v_purchase, v_org, v_off.id, v_off.name,
            coalesce(v_off.price_amount, 0), v_off.price_unit, v_qty, v_config);
  END LOOP;

  -- One totaller, the incumbent one — the same function every other line-item
  -- change in this codebase calls.
  PERFORM _recompute_purchase_total(v_purchase);

  RETURN v_purchase;
END;
$$;


--
-- Name: credit_ledger(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_ledger(p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  RETURN coalesce((
    SELECT jsonb_agg(row ORDER BY (row->>'purchased_at') DESC)
      FROM (
        SELECT jsonb_build_object(
          'id',                lc.id,
          'client_id',         lc.client_id,
          'client_name',       nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'package_key',       lc.package_key,
          'offering_id',       lc.offering_id,
          'offering_name',     o.name,
          'credits_total',     lc.credits_total,
          'credits_remaining', lc.credits_remaining,
          'purchased_at',      lc.purchased_at,
          'expires_at',        lc.expires_at,
          'period_start',      lc.period_start,
          -- WHERE IT CAME FROM. Four real shapes exist on this table, and the page
          -- must not present them as one:
          --   the three staff modes (config->>'grant_mode');
          --   'change'   — _refund_booking_credit's compensating row, minted when a
          --                standing slot was cancelled or rescheduled (package_key
          --                'change_credit'), which was never bought and never comped;
          --   'unknown'  — a credit with no line AND no order behind it. One such row
          --                exists on prod (2026-08-18, no package, no offering, fully
          --                spent) — TASK-AUTHORITY's orphan shape. Calling it
          --                "Purchased" would be the ledger lying, so it says so.
          'origin',            CASE
             WHEN pi.config ? 'grant_mode'      THEN pi.config->>'grant_mode'
             WHEN lc.package_key = 'change_credit' THEN 'change'
             WHEN pi.id IS NULL AND pu.id IS NULL  THEN 'unknown'
             ELSE 'purchase' END,
          'reason',            pi.config->>'grant_reason',
          'granted_by',        (SELECT nullif(btrim(coalesce(gp.first_name,'') || ' ' || coalesce(gp.last_name,'')), '')
                                  FROM profiles gp WHERE gp.user_id = (pi.config->>'granted_by')::uuid),
          'quantity',          coalesce(pi.quantity, 1),
          -- per UNIT, as captured at grant time…
          'list_price',        coalesce((pi.config->>'list_price')::numeric, pi.price_amount),
          -- …and what the whole LINE was worth, which is the figure a ledger row shows.
          'list_value',        coalesce((pi.config->>'list_price')::numeric, pi.price_amount, 0)
                                 * coalesce(pi.quantity, 1),
          'line_amount',       coalesce(pi.price_amount * pi.quantity, 0),
          'purchase_id',       pu.id,
          'display_code',      pu.display_code,
          'order_status',      pu.status,
          'payment_status',    pu.payment_status,
          'amount',            pu.amount,
          'amount_due',        greatest(coalesce(pu.amount,0) - coalesce(pu.amount_paid,0), 0),
          -- coalesce, not a bare `?`: a credit with no line at all (a returned or
          -- orphan row) makes the test NULL, and a nullable can_undo is a contract
          -- every reader has to remember to defend against.
          'can_undo',          coalesce(pi.config ? 'grant_mode', false)
                                 AND coalesce(pu.status,'') <> 'void'
                                 AND lc.credits_remaining >= lc.credits_total
                                 AND coalesce(pu.client_claim_status,'none') <> 'confirmed'
                                 AND NOT EXISTS (SELECT 1 FROM receipt_sends rs
                                                  WHERE rs.purchase_id = pu.id AND rs.succeeded),
          'undo_blocked',      CASE
             WHEN NOT coalesce(pi.config ? 'grant_mode', false) THEN 'This credit did not come from a staff grant.'
             WHEN coalesce(pu.status,'') = 'void' THEN 'Already undone.'
             WHEN lc.credits_remaining < lc.credits_total THEN
               (lc.credits_total - lc.credits_remaining) || ' of these credits have been used.'
             WHEN coalesce(pu.client_claim_status,'none') = 'confirmed'
               OR EXISTS (SELECT 1 FROM receipt_sends rs WHERE rs.purchase_id = pu.id AND rs.succeeded)
               THEN 'A payment on this order has settled — refund it instead.'
             END
        ) AS row
        FROM lesson_credits lc
        JOIN clients cl ON cl.id = lc.client_id
        LEFT JOIN contacts c  ON c.id = cl.contact_id
        LEFT JOIN offerings o ON o.id = lc.offering_id
        LEFT JOIN purchase_items pi ON pi.id = lc.purchase_item_id
        LEFT JOIN purchases pu ON pu.id = lc.purchase_id
       WHERE lc.org_id = v_org
         AND lc.deleted_at IS NULL
         AND (p_client_id IS NULL OR lc.client_id = p_client_id)
      ) s), '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION credit_ledger(p_client_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.credit_ledger(p_client_id uuid) IS 'TASK-CREDITGRANT: the one named query behind LessonCreditsPage. Says where each credit came from (purchase / handwrite / comp / bill), what it was for, why, and whether the grant can still be undone.';


--
-- Name: credits_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credits_roster() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'client_id', cl.id,
        'name', trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')),
        'credits_remaining', r.rem) ORDER BY r.rem DESC), '[]'::jsonb)
    FROM (
      SELECT client_id, sum(credits_remaining)::int AS rem
      FROM lesson_credits
      WHERE org_id = v_org AND deleted_at IS NULL
        AND (expires_at IS NULL OR expires_at > now())
      GROUP BY client_id
      HAVING sum(credits_remaining) > 0
    ) r
    JOIN clients cl ON cl.id = r.client_id
    JOIN contacts c ON c.id = cl.contact_id AND c.deleted_at IS NULL);
END;
$$;


