$$;


--
-- Name: dash_activity_readback(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_activity_readback(p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_lim   integer := least(greatest(coalesce(p_limit, 40), 1), 200);
  v_share integer := greatest(v_lim / 5, 2);
  v_rows  jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  -- A FAIR SHARE PER LEDGER, then ordered by time. Straight "most recent 40"
  -- looked right and was useless: `audit_logs` writes ~3,200 rows a month where
  -- `receipt_sends` writes 2, so the read-back rendered forty identical
  -- "UPDATE documents" lines and the four ledgers a person actually wants to see
  -- never appeared. Each ledger contributes at most a fifth of the window.
  SELECT coalesce(jsonb_agg(to_jsonb(t) - 'at' || jsonb_build_object('at', t.at)
                            ORDER BY t.at DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    (SELECT 'status'::text AS ledger, se.created_at AS at, se.entity_type AS subject,
            se.entity_id AS subject_id, se.status AS what, se.detail AS detail
       FROM status_events se
      WHERE se.org_id = v_org AND se.created_at > now() - interval '14 days'
      ORDER BY se.created_at DESC LIMIT v_share)

    UNION ALL
    (SELECT 'notification', n.created_at, coalesce(n.category, n.kind),
            n.user_id, n.title, left(coalesce(n.body, ''), 160)
       FROM notifications n
      WHERE n.org_id = v_org AND n.created_at > now() - interval '14 days'
      ORDER BY n.created_at DESC LIMIT v_share)

    UNION ALL
    (SELECT 'delivery', dd.created_at, 'document',
            dd.document_id, coalesce(dd.channel, 'delivered'),
            CASE WHEN dd.is_mirror THEN 'copy to the barn' ELSE 'to the recipient' END
       FROM document_deliveries dd
      WHERE dd.deleted_at IS NULL AND dd.created_at > now() - interval '14 days'
        AND EXISTS (SELECT 1 FROM documents d WHERE d.id = dd.document_id AND d.org_id = v_org)
      ORDER BY dd.created_at DESC LIMIT v_share)

    UNION ALL
    (SELECT 'receipt', rs.attempted_at, 'purchase',
            rs.purchase_id, CASE WHEN rs.succeeded THEN 'receipt sent' ELSE 'receipt FAILED' END,
            coalesce(rs.recipient_email, '')
       FROM receipt_sends rs
      WHERE rs.org_id = v_org AND rs.attempted_at > now() - interval '14 days'
      ORDER BY rs.attempted_at DESC LIMIT v_share)

    UNION ALL
    (SELECT 'audit', al.occurred_at, coalesce(al.table_name, 'record'),
            al.record_id, al.action,
            (SELECT coalesce(pr.display_name,
                    nullif(btrim(concat_ws(' ', pr.first_name, pr.last_name)), ''))
               FROM profiles pr WHERE pr.user_id = al.actor_user_id)
       FROM audit_logs al
      WHERE al.occurred_at > now() - interval '14 days'
        AND EXISTS (SELECT 1 FROM profiles pr
                     WHERE pr.user_id = al.actor_user_id AND pr.org_id = v_org)
      ORDER BY al.occurred_at DESC LIMIT v_share)
  ) t;

  -- `count` is what this surface is showing, not the size of fourteen days of
  -- ledger. A read-back stream is never "empty because there is nothing to do" —
  -- it renders when there is history, which there always is.
  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_business_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_business_kpis() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid := current_org();
  v_mo_from  timestamptz := date_trunc('month', now());
  v_new      integer;
  v_leads    integer;
  v_conv     integer;
  v_pipeline numeric;
  v_declared numeric;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT count(*) INTO v_new
    FROM clients cl
   WHERE cl.org_id = v_org AND cl.deleted_at IS NULL
     AND coalesce(cl.client_since, cl.customer_since, cl.created_at) >= v_mo_from;

  -- Lead → client, over 90 days: inquiries received, and how many of those
  -- people now hold a client record. Two numbers, so the ratio can be shown
  -- with its denominator instead of as a bare percentage nobody can check.
  SELECT count(*),
         count(*) FILTER (WHERE EXISTS (
           SELECT 1 FROM clients cl
            WHERE cl.contact_id = r.contact_id AND cl.deleted_at IS NULL
              AND cl.client_since IS NOT NULL))
    INTO v_leads, v_conv
    FROM requests r
   WHERE r.org_id = v_org AND r.created_at > now() - interval '90 days';

  SELECT coalesce(sum(coalesce(p.amount, 0)), 0) INTO v_pipeline
    FROM purchases p
   WHERE p.org_id = v_org AND p.deleted_at IS NULL
     AND p.payment_status <> 'paid' AND p.status <> 'draft';

  SELECT coalesce(sum(coalesce(p.amount, 0)), 0) INTO v_declared
    FROM purchases p
   WHERE p.org_id = v_org AND p.deleted_at IS NULL
     AND p.client_claim_status = 'pending';

  RETURN jsonb_build_object(
    'new_clients_month', v_new,
    'leads_90d',     v_leads,
    'converted_90d', v_conv,
    'open_pipeline', v_pipeline,
    'declared_unconfirmed', v_declared);
END;
$$;


--
-- Name: dash_catalog_hygiene(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_catalog_hygiene() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'rank')::int, x->>'label'), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'kind',  'tile_no_skus',
             'id',    st.code, 'label', st.display_name,
             'detail','Nothing is buyable under this service',
             'rank',  1) AS x
      FROM service_types st
     WHERE st.active
       AND st.code NOT IN ('INDEPENDENT_CONTRACTOR', 'ONBOARDING')
       AND NOT EXISTS (SELECT 1 FROM offerings o
                        WHERE o.org_id = v_org AND o.active AND o.service_type = st.code)

    UNION ALL
    SELECT jsonb_build_object(
             'kind',  'tile_no_image',
             'id',    st.code, 'label', st.display_name,
             'detail','No cover image — the card renders bare',
             'rank',  2)
      FROM service_types st
     WHERE st.active AND st.cover_image_url IS NULL
       AND EXISTS (SELECT 1 FROM offerings o
                    WHERE o.org_id = v_org AND o.active AND o.service_type = st.code)

    UNION ALL
    SELECT jsonb_build_object(
             'kind',  'offering_no_config',
             'id',    o.id::text, 'label', o.name,
             'detail','No booking configuration — it cannot be scheduled',
             'rank',  1)
      FROM offerings o
     WHERE o.org_id = v_org AND o.active AND o.config_kind IS NULL

    UNION ALL
    SELECT jsonb_build_object(
             'kind',  'offering_no_price',
             'id',    o.id::text, 'label', o.name,
             'detail','No price and no price model',
             'rank',  1)
      FROM offerings o
     WHERE o.org_id = v_org AND o.active
       AND o.price_amount IS NULL
       AND coalesce(o.price_model, '{}'::jsonb) = '{}'::jsonb

    UNION ALL
    SELECT jsonb_build_object(
             'kind',  'staff_no_title',
             'id',    p.user_id::text,
             'label', coalesce(p.display_name, nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.email),
             'detail','No title on the team roster',
             'rank',  3)
      FROM profiles p
     WHERE p.org_id = v_org AND p.role IN ('ADMIN', 'MANAGER', 'EMPLOYEE')
       AND coalesce(btrim(p.title), '') = ''
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_claires_plate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_claires_plate() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_money   jsonb;
  v_people  jsonb;
  v_notes   jsonb;
  v_rows    jsonb := '[]'::jsonb;
  v_overdue integer;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  v_money  := dash_money_waiting();
  v_people := dash_people_waiting();
  v_notes  := dash_notes_loop();

  -- MONEY MIRRORS, always.
  IF (v_money->>'count')::int > 0 THEN
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'kind',   'money',
      'label',  'orders awaiting payment or confirmation',
      'count',  (v_money->>'count')::int,
      'oldest_days', coalesce((SELECT max((i->>'age_days')::int)
                                 FROM jsonb_array_elements(v_money->'items') i), 0),
      'amount', coalesce((SELECT sum((i->>'amount')::numeric)
                            FROM jsonb_array_elements(v_money->'items') i), 0),
      'breach', false));
  END IF;

  -- A PERSON WAITING MIRRORS, and past 24 hours it is an SLA breach rather than
  -- a queue length. The barn answers people the same day or it does not.
  IF (v_people->>'count')::int > 0 THEN
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'kind',   'people',
      'label',  'people waiting on a reply',
      'count',  (v_people->>'count')::int,
      'oldest_hours', coalesce((SELECT max((i->>'age_hours')::int)
                                  FROM jsonb_array_elements(v_people->'items') i), 0),
      'breach', coalesce((SELECT max((i->>'age_hours')::int)
                            FROM jsonb_array_elements(v_people->'items') i), 0) > 24));
  END IF;

  -- ROUTINE EXECUTION DOES NOT MIRROR — UNLESS OVERDUE. A lesson written up
  -- three days late is the barn's problem; one written up this afternoon is
  -- Claire's own workflow and is none of this dashboard's business.
  SELECT count(*) INTO v_overdue
    FROM jsonb_array_elements(v_notes->'items') i
   WHERE i->>'kind' = 'write_up' AND (i->>'age_days')::int >= 3;

  IF v_overdue > 0 THEN
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'kind',   'notes_overdue',
      'label',  'sessions written up more than three days late',
      'count',  v_overdue,
      'breach', true));
  END IF;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_community_pulse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_community_pulse() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'since')::timestamptz DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'kind',   CASE WHEN fp.pulled_down THEN 'pulled_down'
                            WHEN fp.reported_reason IS NOT NULL THEN 'reported'
                            ELSE 'scan_pending' END,
             'id',     fp.id,
             'body',   left(coalesce(fp.body, ''), 160),
             'reason', fp.reported_reason,
             'since',  fp.created_at,
             'author_id', fp.author_id) AS x
      FROM feed_posts fp
     WHERE fp.org_id = v_org
       AND (fp.pulled_down OR fp.reported_reason IS NOT NULL
            OR fp.scan_state::text NOT IN ('clean', 'skipped'))

    UNION ALL
    SELECT jsonb_build_object(
             'kind',   'event_upcoming',
             'id',     e.id,
             'title',  e.title,
             'since',  e.starts_at,
             'starts_at', e.starts_at,
             'rsvps',  (SELECT count(*) FROM event_rsvps rs
                         WHERE rs.event_id = e.id AND rs.status = 'going'),
             'capacity', e.capacity)
      FROM events e
     WHERE e.org_id = v_org AND e.published
       AND e.starts_at BETWEEN now() AND now() + interval '30 days'
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_deals_contracts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_deals_contracts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_me   uuid := current_contact_id();
  v_co   uuid := company_contact_id();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'rank')::int, (x->>'since')::timestamptz), '[]'::jsonb)
    INTO v_rows
  FROM (
    -- D29: a PROPOSAL is not true yet and needs an explicit disposition.
    SELECT jsonb_build_object(
             'kind',        'proposal',
             'id',          a.id,
             'document_id', a.document_id,
             'title',       (SELECT d.title FROM documents d WHERE d.id = a.document_id),
             'detail',      left(coalesce(a.body, ''), 160),
             'who',         a.proposed_by_role,
             'since',       a.created_at,
             'rank',        1) AS x
      FROM contract_addenda a
     WHERE a.org_id = v_org AND a.status = 'pending'

    UNION ALL
    -- D29: a CHANGE is already true and is approved by being seen — but an
    -- unresolved one is still an open thread on a live instrument.
    SELECT jsonb_build_object(
             'kind',        'change_request',
             'id',          cr.id,
             'document_id', cr.document_id,
             'title',       (SELECT d.title FROM documents d WHERE d.id = cr.document_id),
             'detail',      left(coalesce(cr.body, ''), 160),
             'who',         cr.author_label,
             'since',       coalesce(cr.submitted_at, cr.created_at),
             'rank',        2)
      FROM contract_change_requests cr
     WHERE cr.org_id = v_org AND cr.resolved_at IS NULL
       AND cr.submitted_at IS NOT NULL

    UNION ALL
    SELECT jsonb_build_object(
             'kind',         'awaiting_signature',
             'id',           d.id,
             'document_id',  d.id,
             'title',        d.title,
             'display_code', d.display_code,
             'since',        coalesce(d.sent_at, d.generated_at, d.created_at),
             'age_days',     floor(extract(epoch FROM now() - coalesce(d.sent_at, d.generated_at, d.created_at)) / 86400)::int,
             'mine_to_sign', EXISTS (
                 SELECT 1 FROM document_parties dp
                  WHERE dp.document_id = d.id AND dp.is_signer
                    AND (dp.contact_id = v_me OR (v_co IS NOT NULL AND dp.contact_id = v_co))
                    AND NOT EXISTS (SELECT 1 FROM signatures sg
                                     WHERE sg.document_id = d.id
                                       AND sg.deleted_at IS NULL
                                       AND sg.signer_contact_id = dp.contact_id)),
             'rank',         3)
      FROM documents d
     WHERE d.org_id = v_org AND d.deleted_at IS NULL
       AND d.status = 'AWAITING_SIGNATURE'

    UNION ALL
    -- ⚠️ ONLY THE DEALS THAT WANT SOMETHING THIS ZONE IS NOT ALREADY SAYING.
    SELECT jsonb_build_object(
             'kind',         'deal_open',
             'id',           q.id,
             'deal_id',      q.id,
             'title',        q.title,
             'display_code', q.display_code,
             'deal_type',    q.deal_type,
             'status',       q.status,
             'detail',       array_to_string(q.reasons, ' · '),
             'since',        q.created_at,
             'age_days',     floor(extract(epoch FROM now() - q.created_at) / 86400)::int,
             'rank',         4)
      FROM (
        SELECT dl.id, coalesce(dl.title, dl.deal_type) AS title, dl.display_code,
               dl.deal_type, dl.status, dl.created_at,
               array_remove(ARRAY[
                 CASE WHEN NOT EXISTS (
                        SELECT 1 FROM contract_parties cp
                         WHERE cp.contract_id = dl.contract_id
                           AND cp.party_role = (deal_party_roles(dl.deal_type))[1])
                      THEN 'No ' || lower(initcap((deal_party_roles(dl.deal_type))[1])) || ' named' END,
                 CASE WHEN NOT EXISTS (
                        SELECT 1 FROM contract_parties cp
                         WHERE cp.contract_id = dl.contract_id
                           AND cp.party_role = (deal_party_roles(dl.deal_type))[2])
                      THEN 'No ' || lower(initcap((deal_party_roles(dl.deal_type))[2])) || ' named' END,
                 CASE
                   -- nothing opened yet
                   WHEN deal_governing_document(dl.id) IS NULL
                     THEN CASE dl.deal_type WHEN 'SALE' THEN 'No bill of sale started'
                                            ELSE 'No lease agreement started' END
                   -- everyone signed and it is still sitting open: closing it is
                   -- a real act, and not one any document row performs.
                   WHEN (deal_status(dl.id) ->> 'code') = 'complete'
                     THEN 'Signed by everyone — ready to close'
                   -- ⚠️ THE DOCUMENT IS ALREADY A ROW IN THIS ZONE. Say nothing.
                   WHEN EXISTS (SELECT 1 FROM documents d
                                 WHERE d.id = deal_governing_document(dl.id)
                                   AND d.status = 'AWAITING_SIGNATURE')
                     OR EXISTS (SELECT 1 FROM contract_addenda a
                                 WHERE a.document_id = deal_governing_document(dl.id)
                                   AND a.status = 'pending')
                     OR EXISTS (SELECT 1 FROM contract_change_requests cr
                                 WHERE cr.document_id = deal_governing_document(dl.id)
                                   AND cr.resolved_at IS NULL AND cr.submitted_at IS NOT NULL)
                     THEN NULL
                   ELSE 'Not sent for signature yet'
                 END
               ], NULL) AS reasons
          FROM deals dl
         WHERE dl.org_id = v_org AND dl.deleted_at IS NULL
           AND dl.status <> 'complete'
      ) q
     WHERE coalesce(array_length(q.reasons, 1), 0) > 0
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_documents_onboarding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_documents_onboarding() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'rank')::int, x->>'who'), '[]'::jsonb)
    INTO v_rows
  FROM (
    -- D8 §3: an account with assigned-but-unsigned documents is PENDING.
    SELECT jsonb_build_object(
             'kind',      'unsigned',
             'id',        ct.id,
             'contact_id',ct.id,
             'who',       coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
             'templates', u.keys,
             'blocks_at', u.next_service,
             'rank',      CASE WHEN u.next_service IS NOT NULL THEN 1 ELSE 3 END) AS x
      FROM contacts ct
      CROSS JOIN LATERAL (
        SELECT array_agg(crd.template_key ORDER BY crd.template_key) AS keys,
               (SELECT min(b.starts_at)
                  FROM bookings b
                  JOIN clients cl ON cl.id = b.client_id
                 WHERE cl.contact_id = ct.id AND b.org_id = v_org
                   AND b.deleted_at IS NULL AND b.status = 'scheduled'
                   AND b.starts_at >= now()) AS next_service
          FROM contact_required_documents crd
         WHERE crd.contact_id = ct.id AND crd.org_id = v_org
           AND crd.skipped_at IS NULL
           AND NOT contact_document_satisfied(ct.id, crd.template_key)
      ) u
     WHERE ct.org_id = v_org AND u.keys IS NOT NULL

    UNION ALL
    -- An invitation that is about to stop working.
    SELECT jsonb_build_object(
             'kind',      'invitation_expiring',
             'id',        i.id,
             'who',       coalesce(nullif(btrim(concat_ws(' ', i.first_name, i.last_name)), ''), i.email),
             'expires_at',i.expires_at,
             'contact_id',i.contact_id,
             'rank',      2)
      FROM invitations i
     WHERE i.org_id = v_org AND i.deleted_at IS NULL
       AND i.status = 'sent' AND i.redeemed_at IS NULL
       AND i.expires_at IS NOT NULL
       AND i.expires_at <= now() + interval '3 days'
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_evaluations_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_evaluations_due() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'since')::timestamptz DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'kind',       'rider',
             'id',         cl.id,
             'contact_id', cl.contact_id,
             'who',        coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
             'since',      coalesce(cl.client_since, cl.created_at)) AS x
      FROM clients cl
      JOIN contacts ct ON ct.id = cl.contact_id
     WHERE cl.org_id = v_org AND cl.deleted_at IS NULL
       AND cl.client_since IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM evaluation_reports er
                        WHERE er.contact_id = cl.contact_id
                          AND er.deleted_at IS NULL AND er.horse_id IS NULL)

    UNION ALL
    SELECT jsonb_build_object(
             'kind',     'horse',
             'id',       h.id,
             'horse_id', h.id,
             'who',      coalesce(h.nickname, h.registered_name, 'Unnamed horse'),
             'since',    h.created_at)
      FROM horses h
     WHERE h.org_id = v_org AND h.deleted_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM evaluation_reports er
                        WHERE er.horse_id = h.id AND er.deleted_at IS NULL)
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_gifts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_gifts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'gift_id',    g.id,
           'code',       g.code,
           'item_label', g.item_label,
           'amount',     g.amount,
           'buyer',      g.buyer_name,
           'recipient',  g.recipient_name,
           'deliver_on', g.deliver_on,
           'opened_at',  g.opened_at,
           'status',     g.status,
           'since',      g.created_at) ORDER BY g.created_at DESC), '[]'::jsonb)
    INTO v_rows
    FROM gifts g
   WHERE g.org_id = v_org
     AND g.redeemed_at IS NULL
     AND coalesce(g.status, '') <> 'cancelled';

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_money_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_money_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'rank')::int, (x->>'since')::timestamptz), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'kind',         'declared',
             'id',           p.id,
             'purchase_id',  p.id,
             'display_code', p.display_code,
             'amount',       coalesce(p.amount, 0),
             'who',          coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
             'method',       coalesce(p.client_reported_method, p.payment_method),
             'since',        coalesce(p.client_reported_at, p.created_at),
             'age_days',     floor(extract(epoch FROM now() - coalesce(p.client_reported_at, p.created_at)) / 86400)::int,
             'rank',         1) AS x
      FROM purchases p
      LEFT JOIN contacts ct ON ct.id = p.buyer_contact_id
     WHERE p.org_id = v_org AND p.deleted_at IS NULL
       AND p.client_claim_status = 'pending'

    UNION ALL
    -- Unpaid and ageing: a week is the line, because below it the order is
    -- simply new and there is nothing to chase.
    SELECT jsonb_build_object(
             'kind',         'unpaid_aging',
             'id',           p.id,
             'purchase_id',  p.id,
             'display_code', p.display_code,
             'amount',       coalesce(p.amount, 0),
             'who',          coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
             'since',        p.created_at,
             'age_days',     floor(extract(epoch FROM now() - p.created_at) / 86400)::int,
             'rank',         2)
      FROM purchases p
      LEFT JOIN contacts ct ON ct.id = p.buyer_contact_id
     WHERE p.org_id = v_org AND p.deleted_at IS NULL
       AND p.payment_status <> 'paid' AND p.status <> 'draft'
       AND coalesce(p.client_claim_status, 'none') <> 'pending'
       AND p.created_at < now() - interval '7 days'

    UNION ALL
    -- A receipt is provable and single (`receipt_sends`, one row per attempt).
    -- A failed one is money that landed and a client who was never told.
    SELECT jsonb_build_object(
             'kind',        'receipt_failed',
             'id',          rs.id,
             'purchase_id', rs.purchase_id,
             'who',         rs.recipient_email,
             'detail',      left(coalesce(rs.error, 'send failed'), 160),
             'since',       rs.attempted_at,
             'age_days',    floor(extract(epoch FROM now() - rs.attempted_at) / 86400)::int,
             'rank',        3)
      FROM receipt_sends rs
     WHERE rs.org_id = v_org AND NOT rs.succeeded
       AND rs.attempted_at > now() - interval '30 days'
       AND NOT EXISTS (SELECT 1 FROM receipt_sends ok
                        WHERE ok.purchase_id = rs.purchase_id AND ok.succeeded
                          AND ok.attempted_at > rs.attempted_at)
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_money_waiting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_money_waiting() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'sort_at')::timestamptz), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'kind',        CASE WHEN p.client_claim_status = 'pending' THEN 'claim' ELSE 'order' END,
      'purchase_id', p.id,
      'display_code',p.display_code,
      'amount',      coalesce(p.amount, 0),
      'buyer_name',  coalesce(nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), ''), ct.email),
      'buyer_contact_id', p.buyer_contact_id,
      'method',      coalesce(p.client_reported_method, p.payment_method),
      'reference',   p.client_reported_reference,
      'declared_at', p.client_reported_at,
      'created_at',  p.created_at,
      'sort_at',     coalesce(p.client_reported_at, p.created_at),
      'age_days',    floor(extract(epoch FROM now() - coalesce(p.client_reported_at, p.created_at)) / 86400)::int,
      'items',       (SELECT coalesce(jsonb_agg(pi.label ORDER BY pi.created_at), '[]'::jsonb)
                        FROM purchase_items pi
                       WHERE pi.purchase_id = p.id AND pi.voided_at IS NULL)
    ) AS x
      FROM purchases p
      LEFT JOIN contacts ct ON ct.id = p.buyer_contact_id
     WHERE p.org_id = v_org
       AND p.deleted_at IS NULL
       AND p.payment_status <> 'paid'
       AND p.status <> 'draft'
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_notes_loop(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_notes_loop() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_me   uuid := current_contact_id();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'since')::timestamptz DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'kind',        'write_up',
             'id',          b.id,
             'booking_id',  b.id,
             'starts_at',   b.starts_at,
             'since',       b.starts_at,
             'age_days',    floor(extract(epoch FROM now() - b.starts_at) / 86400)::int,
             'client_id',   b.client_id,
             'client_name', (SELECT nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), '')
                               FROM clients cl JOIN contacts ct ON ct.id = cl.contact_id
                              WHERE cl.id = b.client_id),
             'service_type', booking_service_type(b)) AS x
      FROM bookings b
     WHERE b.org_id = v_org AND b.deleted_at IS NULL
       AND b.status = 'scheduled'
       AND b.starts_at < now()
       AND b.starts_at > now() - interval '30 days'
       AND booking_form_applies(b)
       AND NOT EXISTS (SELECT 1 FROM booking_notes bn
                        WHERE bn.booking_id = b.id
                          AND bn.author_role <> 'client'
                          AND bn.phase = 'after')

    UNION ALL

    SELECT jsonb_build_object(
             'kind',        'unread_note',
             'id',          bn.id,
             'note_id',     bn.id,
             'booking_id',  bn.booking_id,
             'since',       bn.created_at,
             'age_days',    floor(extract(epoch FROM now() - bn.created_at) / 86400)::int,
             'author_name', bn.author_name,
             'phase',       bn.phase,
             'body',        left(bn.body, 200),
             'starts_at',   (SELECT b2.starts_at FROM bookings b2 WHERE b2.id = bn.booking_id))
      FROM booking_notes bn
     WHERE bn.org_id = v_org
       AND bn.author_role = 'client'
       AND v_me IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM booking_note_seen s
                        WHERE s.note_id = bn.id AND s.contact_id = v_me)
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_notifications() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH live AS (
    SELECT n.*
      FROM notifications n
     WHERE n.user_id = auth.uid()
       AND n.read_at IS NULL
       AND (
         n.link IS NULL
         OR n.link !~ '^/app/contracts/[0-9a-fA-F-]{36}$'
         OR EXISTS (
           SELECT 1 FROM documents d
            WHERE d.id = regexp_replace(n.link, '^/app/contracts/', '')::uuid
              AND d.deleted_at IS NULL
         )
       )
       AND n.kind <> 'contract_cancelled'
       AND n.title NOT ILIKE '%awaiting archive%'
  )
  SELECT jsonb_build_object(
    'count', (SELECT count(*) FROM live),
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id',         l.id,
               'kind',       l.kind,
               'category',   l.category,
               'title',      l.title,
               'body',       left(coalesce(l.body, ''), 200),
               'link',       l.link,
               'created_at', l.created_at)
             ORDER BY l.created_at DESC, l.id DESC)
        FROM live l), '[]'::jsonb));
$_$;


--
-- Name: dash_onboarding_pipeline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_onboarding_pipeline() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'rank')::int, (x->>'since')::timestamptz), '[]'::jsonb)
    INTO v_rows
  FROM (
    -- An invitation that failed to send is a person who never heard from us.
    SELECT jsonb_build_object(
             'kind',   'invite_failed',
             'id',     i.id,
             'who',    coalesce(nullif(btrim(concat_ws(' ', i.first_name, i.last_name)), ''), i.email),
             'detail', left(coalesce(i.failure_reason, 'send failed'), 160),
             'since',  i.created_at,
             'rank',   1) AS x
      FROM invitations i
     WHERE i.org_id = v_org AND i.deleted_at IS NULL
       AND i.failure_reason IS NOT NULL
       AND i.redeemed_at IS NULL
       AND i.status NOT IN ('superseded', 'revoked')

    UNION ALL
    -- Sent, still open, and getting old.
    SELECT jsonb_build_object(
             'kind',   'invite_open',
             'id',     i.id,
             'who',    coalesce(nullif(btrim(concat_ws(' ', i.first_name, i.last_name)), ''), i.email),
             'expires_at', i.expires_at,
             'since',  i.created_at,
             'age_days', floor(extract(epoch FROM now() - i.created_at) / 86400)::int,
             'rank',   2)
      FROM invitations i
     WHERE i.org_id = v_org AND i.deleted_at IS NULL
       AND i.status = 'sent' AND i.redeemed_at IS NULL

    UNION ALL
    -- D8 §3 PENDING: the account exists, the documents were assigned, nothing is
    -- signed, and service features stay locked until they are.
    SELECT jsonb_build_object(
             'kind',   'account_pending',
             'id',     p.user_id,
             'contact_id', p.contact_id,
             'who',    coalesce(p.display_name,
                                nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.email),
             'unsigned', (SELECT count(*) FROM contact_required_documents crd
                           WHERE crd.contact_id = p.contact_id AND crd.org_id = v_org
                             AND crd.skipped_at IS NULL
                             AND NOT contact_document_satisfied(p.contact_id, crd.template_key)),
             'since',  p.created_at,
             'age_days', floor(extract(epoch FROM now() - p.created_at) / 86400)::int,
             'rank',   3)
      FROM profiles p
     WHERE p.org_id = v_org AND coalesce(p.role, 'USER') = 'USER'
       AND p.contact_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM contact_required_documents crd
                    WHERE crd.contact_id = p.contact_id AND crd.org_id = v_org
                      AND crd.skipped_at IS NULL
                      AND NOT contact_document_satisfied(p.contact_id, crd.template_key))
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_people_waiting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_people_waiting() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_me   uuid := auth.uid();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'since')::timestamptz), '[]'::jsonb)
    INTO v_rows
  FROM (
    -- An inquiry nobody has answered yet -- and who has not already converted.
    SELECT jsonb_build_object(
             'kind',    'inquiry',
             'id',      r.id,
             'who',     coalesce(nullif(btrim(concat_ws(' ', r.contact_first_name, r.contact_last_name)), ''),
                                 r.contact_name, r.contact_email),
             'subject', coalesce(r.subject, r.category, 'New inquiry'),
             'detail',  left(coalesce(r.notes, ''), 160),
             'since',   r.created_at,
             'age_hours', floor(extract(epoch FROM now() - r.created_at) / 3600)::int,
             'status',  r.status,
             'contact_id', r.contact_id) AS x
      FROM requests r
      JOIN inbound_queue iq ON iq.id = r.id
     WHERE r.org_id = v_org AND r.status = 'new'
       AND NOT coalesce(iq.already_converted, false)

    UNION ALL
    -- Someone asked to move or cancel a session and is waiting on the answer.
    SELECT jsonb_build_object(
             'kind',    'reschedule',
             'id',      cr.id,
             'who',     (SELECT nullif(btrim(concat_ws(' ', pr.first_name, pr.last_name)), '')
                           FROM profiles pr WHERE pr.user_id = cr.requested_by),
             'subject', CASE cr.request_kind WHEN 'cancel' THEN 'Cancellation request'
                                             ELSE 'Reschedule request' END,
             'detail',  coalesce(cr.note, ''),
             'since',   cr.created_at,
             'age_hours', floor(extract(epoch FROM now() - cr.created_at) / 3600)::int,
             'status',  cr.status,
             'booking_id', cr.booking_id)
      FROM booking_change_requests cr
     WHERE cr.org_id = v_org AND cr.status = 'pending'

    UNION ALL
    -- A direct message to me that I have not opened.
    SELECT jsonb_build_object(
             'kind',    'message',
             'id',      dm.id,
             'who',     (SELECT coalesce(pr.display_name,
                                 nullif(btrim(concat_ws(' ', pr.first_name, pr.last_name)), ''))
                           FROM profiles pr WHERE pr.user_id = dm.sender_id),
             'subject', 'Direct message',
             'detail',  left(dm.body, 160),
             'since',   dm.created_at,
             'age_hours', floor(extract(epoch FROM now() - dm.created_at) / 3600)::int,
             'sender_id', dm.sender_id)
      FROM direct_messages dm
     WHERE dm.org_id = v_org AND dm.deleted_at IS NULL
       AND dm.read_at IS NULL AND dm.recipient_id = v_me

    UNION ALL
    -- A comment on a contract that the barn has not replied under.
    SELECT jsonb_build_object(
             'kind',    'contract_note',
             'id',      m.id,
             'who',     m.author_label,
             'subject', 'Contract comment',
             'detail',  left(m.body, 160),
             'since',   m.created_at,
             'age_hours', floor(extract(epoch FROM now() - m.created_at) / 3600)::int,
             'note_id', m.note_id,
             'document_id', (SELECT n.document_id FROM contract_notes n WHERE n.id = m.note_id))
      FROM contract_note_messages m
     WHERE m.org_id = v_org AND m.deleted_at IS NULL
       AND m.author_contact_id IS DISTINCT FROM current_contact_id()
       AND NOT EXISTS (SELECT 1 FROM contract_note_messages later
                        WHERE later.note_id = m.note_id
                          AND later.deleted_at IS NULL
                          AND later.created_at > m.created_at
                          AND later.author_contact_id = current_contact_id())
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_stable_board(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_stable_board() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'urgency')::int, x->>'name'), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'horse_id', h.id,
             'name',     coalesce(h.nickname, h.registered_name, 'Unnamed horse'),
             'reasons',  r.reasons,
             'urgency',  r.urgency,
             'rides_this_week', (SELECT count(*) FROM bookings b
                                  WHERE b.org_id = v_org AND b.deleted_at IS NULL
                                    AND b.horse_id = h.id AND b.status = 'scheduled'
                                    AND b.starts_at >= date_trunc('week', now())
                                    AND b.starts_at <  date_trunc('week', now()) + interval '7 days')
           ) AS x
      FROM horses h
      CROSS JOIN LATERAL (
        SELECT jsonb_agg(z.reason ORDER BY z.rank) AS reasons, min(z.rank) AS urgency
          FROM (
            SELECT 1 AS rank,
                   jsonb_build_object('kind','health_overdue','label', he.event_type,
                                      'due', he.next_due, 'event_id', he.id) AS reason
              FROM horse_health_events he
             WHERE he.horse_id = h.id AND he.deleted_at IS NULL AND he.org_id = v_org
               AND he.next_due IS NOT NULL AND he.next_due < current_date
            UNION ALL
            SELECT 2,
                   jsonb_build_object('kind','health_due','label', he.event_type,
                                      'due', he.next_due, 'event_id', he.id)
              FROM horse_health_events he
             WHERE he.horse_id = h.id AND he.deleted_at IS NULL AND he.org_id = v_org
               AND he.next_due BETWEEN current_date AND current_date + 14
            UNION ALL
            SELECT 3,
                   jsonb_build_object('kind','lease_ending','label','Lease ends',
                                      'due', h.lease_end)
             WHERE h.lease_end IS NOT NULL
               AND h.lease_end BETWEEN current_date AND current_date + 30
            UNION ALL
            SELECT 4,
                   jsonb_build_object('kind','medication','label', hm.name,
                                      'detail', hm.instructions, 'med_id', hm.id)
              FROM horse_medications hm
             WHERE hm.horse_id = h.id AND hm.deleted_at IS NULL AND hm.org_id = v_org
          ) z
      ) r
     WHERE h.org_id = v_org AND h.deleted_at IS NULL
       AND r.reasons IS NOT NULL
  ) s;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_today_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_today_plan() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'booking_id',    d.booking_id,
           'starts_at',     d.starts_at,
           'ends_at',       d.ends_at,
           'client_id',     d.client_id,
           'client_name',   d.client_name,
           'service_type',  d.service_type,
           'status',        d.booking_status,
           'plan_id',       d.plan_id,
           'plan_version',  d.plan_version,
           'focus',         d.focus,
           'next_up',       d.next_up,
           'has_plan',      d.plan_id IS NOT NULL,
           'progress_recorded', d.progress_recorded,
           'client_note',   EXISTS (SELECT 1 FROM booking_forms bf
                                     WHERE bf.booking_id = d.booking_id
                                       AND bf.retired_at IS NULL
                                       AND bf.submitted_at IS NOT NULL
                                       AND coalesce(bf.answers, '{}'::jsonb) <> '{}'::jsonb),
           'horse_name',    (SELECT coalesce(h.nickname, h.registered_name)
                               FROM bookings b JOIN horses h ON h.id = b.horse_id
                              WHERE b.id = d.booking_id)
         ) ORDER BY d.starts_at), '[]'::jsonb)
    INTO v_rows
    FROM lesson_plans_for_day(current_date) d;

  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


--
-- Name: dash_today_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_today_tasks() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_items jsonb; v_count int;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY x_sort), '[]'::jsonb), count(*)
    INTO v_items, v_count
  FROM (
    SELECT jsonb_build_object(
             'task_id', t.id,
             'title', t.title,
             'category', t.category,
             'status', t.status,
             'scheduled_at', t.scheduled_at,
             'due_at', t.due_at,
             'blocks_availability', t.blocks_availability,
             'horse_id', (SELECT tl.target_id FROM task_links tl WHERE tl.task_id = t.id AND tl.link_type = 'horse' LIMIT 1),
             'horse_name', (SELECT h.registered_name FROM horses h
                              JOIN task_links tl ON tl.target_id = h.id
                             WHERE tl.task_id = t.id AND tl.link_type = 'horse' LIMIT 1),
             'client_id', (SELECT tl.target_id FROM task_links tl WHERE tl.task_id = t.id AND tl.link_type = 'client' LIMIT 1)
           ) AS x,
           coalesce(t.scheduled_at, t.due_at) AS x_sort
      FROM tasks t
     WHERE t.org_id = current_org()
       AND t.deleted_at IS NULL
       AND t.status IN ('new','in_progress')
       AND (
         (t.scheduled_at >= date_trunc('day', now()) AND t.scheduled_at < date_trunc('day', now()) + interval '1 day')
         OR (t.due_at   >= date_trunc('day', now()) AND t.due_at   < date_trunc('day', now()) + interval '1 day')
       )
  ) s;

  RETURN jsonb_build_object('count', v_count, 'items', v_items);
END;
$$;


--
-- Name: dash_trainer_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_trainer_kpis() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid := current_org();
  v_today    integer;
  v_booked   integer;
  v_open     integer;
  v_money    numeric;
  v_people   jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT (dash_today_plan()->>'count')::int INTO v_today;

  SELECT count(*) FILTER (WHERE b.status = 'scheduled'),
         count(*) FILTER (WHERE b.status = 'available' AND b.kind = 'lesson')
    INTO v_booked, v_open
    FROM bookings b
   WHERE b.org_id = v_org AND b.deleted_at IS NULL
     AND b.starts_at >= current_date::timestamptz
     AND b.starts_at <  (current_date + 7)::timestamptz;

  -- Money DECLARED and awaiting confirmation. Not revenue (see revenue_summary):
  -- it is the number that says how much of the week is sitting on a human.
  SELECT coalesce(sum(coalesce(p.amount, 0)), 0) INTO v_money
    FROM purchases p
   WHERE p.org_id = v_org AND p.deleted_at IS NULL
     AND p.client_claim_status = 'pending';

  SELECT jsonb_build_object(
           'count', (w->>'count')::int,
           'oldest_hours', coalesce((SELECT max((i->>'age_hours')::int)
                                       FROM jsonb_array_elements(w->'items') i), 0))
    INTO v_people
    FROM (SELECT dash_people_waiting() AS w) q;

  RETURN jsonb_build_object(
    'today_lessons',  v_today,
    'week_booked',    v_booked,
    'week_capacity',  v_booked + v_open,
    'awaiting_confirmation', v_money,
    'people_waiting', v_people->'count',
    'people_oldest_hours', v_people->'oldest_hours');
END;
$$;


--
-- Name: dash_waiting_on_clients(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_waiting_on_clients() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(w) - 'side' ORDER BY w.rank, w.since), '[]'::jsonb)
    INTO v_rows FROM _waiting_items() w WHERE w.side = 'client';
  RETURN jsonb_build_object('count', jsonb_array_length(v_rows), 'items', v_rows);
END;
$$;


