--
-- Name: dash_week_strip(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dash_week_strip() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_days jsonb;
  v_book integer;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY (x->>'day')::date), '[]'::jsonb), coalesce(sum(booked), 0)
    INTO v_days, v_book
  FROM (
    SELECT jsonb_build_object(
             'day',       g.day,
             'is_today',  g.day = current_date,
             'booked',    b.booked,
             'open',      b.open_slots,
             'items',     coalesce(b.items, '[]'::jsonb),
             'care_due',  (SELECT count(*) FROM horse_health_events he
                             JOIN horses h ON h.id = he.horse_id
                            WHERE he.org_id = v_org AND he.deleted_at IS NULL
                              AND h.deleted_at IS NULL AND he.next_due = g.day),
             'lease_ends',(SELECT count(*) FROM horses h
                            WHERE h.org_id = v_org AND h.deleted_at IS NULL
                              AND h.lease_end = g.day)
           ) AS x,
           b.booked
      FROM (SELECT (current_date + i)::date AS day FROM generate_series(0, 6) AS i) g
      CROSS JOIN LATERAL (
        SELECT
          count(*) FILTER (WHERE bk.status = 'scheduled')                      AS booked,
          count(*) FILTER (WHERE bk.status = 'available' AND bk.kind='lesson') AS open_slots,
          jsonb_agg(jsonb_build_object(
              'booking_id',   bk.id,
              'starts_at',    bk.starts_at,
              'service_type', booking_service_type(bk),
              'client_name',  (SELECT nullif(btrim(concat_ws(' ', ct.first_name, ct.last_name)), '')
                                 FROM clients cl JOIN contacts ct ON ct.id = cl.contact_id
                                WHERE cl.id = bk.client_id))
            ORDER BY bk.starts_at) FILTER (WHERE bk.status = 'scheduled')      AS items
        FROM bookings bk
       WHERE bk.org_id = v_org AND bk.deleted_at IS NULL
         AND bk.starts_at >= g.day::timestamptz
         AND bk.starts_at <  (g.day + 1)::timestamptz
      ) b
  ) s;

  -- The strip is about the week, so it stays visible whenever the week holds
  -- anything at all; `count` is the week's committed work.
  RETURN jsonb_build_object('count', v_book, 'items', v_days);
END;
$$;


--
-- Name: dashboard_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_alerts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_uid uuid; v_rows jsonb;
BEGIN
  v_org := current_org(); v_uid := auth.uid();
  IF NOT coalesce(has_staff_access() AND v_org IS NOT NULL, false) THEN RETURN '[]'::jsonb; END IF;

  WITH computed AS (
    -- unpaid orders
    SELECT 'unpaid_order' AS source, p.id AS entity_id,
           'Order awaiting payment' AS title,
           coalesce(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')),'A buyer')
             || ' — ' || coalesce(p.display_code, left(p.id::text,8)) AS body,
           '/app/ops/orders' AS link, 'standard' AS severity,
           p.created_at AS created_at, true AS has_task
      FROM purchases p LEFT JOIN contacts c ON c.id = p.buyer_contact_id
     WHERE p.org_id = v_org AND p.deleted_at IS NULL
       AND p.status <> 'void' AND p.payment_status <> 'paid'
    UNION ALL
    -- uncontacted new leads (last 30 days)
    SELECT 'new_lead', ct.id,
           'New lead', coalesce(btrim(coalesce(ct.first_name,'')||' '||coalesce(ct.last_name,'')), ct.email, 'A lead'),
           '/app/records/leads', 'standard', ct.created_at, true
      FROM contacts ct
     WHERE ct.org_id = v_org AND ct.deleted_at IS NULL
       AND ct.contact_type = 'LEAD'
       AND ct.created_at > now() - interval '30 days'
    UNION ALL
    -- onboarding incomplete: a contact with unsatisfied AT_LOGIN docs
    SELECT 'onboarding_incomplete', ct.id,
           'Onboarding documents unsigned',
           coalesce(btrim(coalesce(ct.first_name,'')||' '||coalesce(ct.last_name,'')), ct.email, 'Someone'),
           '/app/records/documents', 'standard', ct.created_at, true
      FROM contacts ct
     WHERE ct.org_id = v_org AND ct.deleted_at IS NULL
       AND (contact_document_wall_state(ct.id)->>'gating')::int > 0
  ),
  computed_visible AS (
    SELECT cm.* FROM computed cm
     WHERE NOT EXISTS (
       SELECT 1 FROM alert_suppressions s
        WHERE s.org_id = v_org AND s.user_id = v_uid
          AND s.source = cm.source AND s.entity_id = cm.entity_id
          AND (s.suppressed_until IS NULL OR s.suppressed_until > now()))
  ),
  stored AS (
    SELECT a.source, a.task_id AS entity_id, a.title, a.body, a.link,
           a.severity, a.created_at, (a.task_id IS NOT NULL) AS has_task
      FROM alerts a
     WHERE a.org_id = v_org AND a.user_id = v_uid
       AND a.dismissed_at IS NULL
       AND (a.snoozed_until IS NULL OR a.snoozed_until <= now())
  ),
  merged AS (
    SELECT source, entity_id, title, body, link, severity, created_at, has_task FROM computed_visible
    UNION ALL
    SELECT source, entity_id, title, body, link, severity, created_at, has_task FROM stored
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source', source, 'entity_id', entity_id, 'title', title, 'body', body,
           'link', link, 'severity', severity, 'created_at', created_at, 'has_task', has_task)
           ORDER BY created_at DESC), '[]'::jsonb)     -- NEWEST FIRST (owner)
    INTO v_rows FROM merged;
  RETURN v_rows;
END
$$;


--
-- Name: dashboard_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_notifications() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid; v_org uuid; v_rows jsonb;
BEGIN
  v_uid := auth.uid(); v_org := current_org();
  IF NOT coalesce(has_staff_access(), false) THEN RETURN '[]'::jsonb; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', n.id, 'title', n.title, 'body', n.body, 'link', n.link,
           'category', n.category, 'created_at', n.created_at)
           ORDER BY n.created_at DESC), '[]'::jsonb)
    INTO v_rows
    FROM notifications n
   WHERE n.user_id = v_uid
     AND n.dismissed_at IS NULL
     AND n.seen_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM notification_mutes m
                      WHERE m.user_id = v_uid AND m.category = n.category);
  RETURN v_rows;
END
$$;


--
-- Name: deal_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_activity(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF NOT (coalesce(has_staff_access() AND v_deal.org_id = current_org(), false))
     AND NOT EXISTS (SELECT 1 FROM contract_parties cp
                      WHERE cp.contract_id = v_deal.contract_id
                        AND cp.contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not authorized for this deal';
  END IF;

  RETURN coalesce((
    SELECT jsonb_agg(x ORDER BY (x ->> 'at') DESC)
    FROM (
      -- the deal itself
      SELECT jsonb_build_object(
        'at', v_deal.created_at, 'who', coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), 'Staff'),
        'what', 'Deal created', 'detail', v_deal.title, 'document_id', NULL) AS x
        FROM contacts c WHERE c.id = v_deal.created_by_contact_id
      UNION ALL
      -- a document was added
      SELECT jsonb_build_object(
        'at', d.created_at, 'who', coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), 'Staff'),
        'what', 'Document added', 'detail', coalesce(d.title, t.template_key), 'document_id', d.id)
        FROM documents d
        JOIN contract_templates t ON t.id = d.template_id
        LEFT JOIN contacts c ON c.id = d.originator_contact_id
       WHERE d.contract_id = v_deal.contract_id AND d.deleted_at IS NULL
      UNION ALL
      -- signatures given
      SELECT jsonb_build_object(
        'at', s.signed_at, 'who', s.typed_name,
        'what', 'Signed', 'detail', coalesce(d.title, t.template_key), 'document_id', d.id)
        FROM signatures s
        JOIN documents d ON d.id = s.document_id
        JOIN contract_templates t ON t.id = d.template_id
       WHERE d.contract_id = v_deal.contract_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL
      UNION ALL
      -- everything the change log already records (signature removals,
      -- permission requests, review requests, field edits)
      SELECT jsonb_build_object(
        'at', l.created_at, 'who', coalesce(l.actor_label, 'Someone'),
        'what', CASE l.change_kind
                  WHEN 'signature_removed'          THEN 'Signature removed'
                  WHEN 'edit_permission_requested'  THEN 'Asked to edit'
                  WHEN 'review_requested'           THEN 'Asked for review'
                  WHEN 'field_value'                THEN 'Changed ' || coalesce(l.field_label, l.field_key)
                  ELSE initcap(replace(l.change_kind, '_', ' ')) END,
        'detail', coalesce(d.title, t.template_key), 'document_id', d.id)
        FROM contract_change_log l
        JOIN documents d ON d.id = l.document_id
        JOIN contract_templates t ON t.id = d.template_id
       WHERE d.contract_id = v_deal.contract_id
         AND l.change_kind <> 'field_value'   -- field noise stays in the document's own history
    ) t), '[]'::jsonb);
END;
$$;


--
-- Name: deal_autocomplete_on_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_autocomplete_on_execution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE;
  v_key  text;
  v_kind text;
  v_gov  boolean;
BEGIN
  IF NOT coalesce(NEW.workflow_state = 'executed' AND OLD.workflow_state IS DISTINCT FROM 'executed', false) THEN
    RETURN NEW;
  END IF;
  IF NEW.contract_id IS NULL THEN RETURN NEW; END IF;

  SELECT template_key, contract_kind INTO v_key, v_kind
    FROM contract_templates WHERE id = NEW.template_id;
  v_gov := is_horse_lease_template(v_key)
        OR v_key = 'HORSE_PURCHASE_SALE'
        OR coalesce(v_kind, '') IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE');
  IF v_gov THEN
    UPDATE contracts
       SET status = 'executed', signed_at = coalesce(signed_at, now())
     WHERE id = NEW.contract_id AND status <> 'executed';
  END IF;

  BEGIN
    PERFORM ensure_deal_for_contract(NEW.contract_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'deal_autocomplete_on_execution: ensure_deal_for_contract failed for contract %: %',
      NEW.contract_id, SQLERRM;
  END;

  -- ⚠️ FIX ROUND 5b — the role bundle is NO LONGER generated at execution. It is
  -- generated at SEND (send_contract_to_party), so by the time the governing
  -- document executes the bundle already exists and is sequenced behind it.
  -- Generating here raced the delivery evaluation on the same transition and was
  -- the likely source of duplicate drafts.

  SELECT * INTO v_deal FROM deals
   WHERE contract_id = NEW.contract_id AND deleted_at IS NULL AND status = 'pending';
  IF NOT FOUND THEN RETURN NEW; END IF;

  IF (deal_completion_state(v_deal.id) ->> 'can_complete')::boolean THEN
    UPDATE deals SET status = 'complete', completed_at = now() WHERE id = v_deal.id;
    UPDATE contracts SET status = 'executed' WHERE id = v_deal.contract_id AND status <> 'executed';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: deal_completion_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_completion_state(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE; v_roles text[]; v_missing text[] := '{}'; v_badge jsonb;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  v_roles := deal_party_roles(v_deal.deal_type);
  v_badge := deal_status(p_deal_id);

  IF NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = v_deal.contract_id AND party_role = v_roles[1]) THEN
    v_missing := v_missing || ('No ' || lower(initcap(v_roles[1])) || ' named');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = v_deal.contract_id AND party_role = v_roles[2]) THEN
    v_missing := v_missing || ('No ' || lower(initcap(v_roles[2])) || ' named');
  END IF;

  -- ONLY the governing document gates completion. An optional agreement or
  -- affidavit the parties chose not to sign is their business (owner ruling).
  IF (v_badge ->> 'code') <> 'complete' THEN
    v_missing := v_missing || (CASE v_deal.deal_type
      WHEN 'SALE'  THEN 'The bill of sale is not signed by all parties'
      WHEN 'LEASE' THEN 'The lease agreement is not signed by all parties'
      ELSE 'The governing document is not signed' END);
  END IF;

  RETURN jsonb_build_object(
    'deal_id', p_deal_id, 'status', v_deal.status, 'completed_at', v_deal.completed_at,
    'can_complete', (v_deal.status = 'pending' AND coalesce(array_length(v_missing,1),0) = 0),
    'outstanding', to_jsonb(v_missing));
END;
$$;


--
-- Name: deal_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_detail(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE; v_roles text[]; v_gov uuid;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF NOT (has_staff_access() AND v_deal.org_id = current_org())
     AND NOT EXISTS (SELECT 1 FROM contract_parties cp
                      WHERE cp.contract_id = v_deal.contract_id
                        AND cp.contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not authorized for this deal';
  END IF;

  v_roles := deal_party_roles(v_deal.deal_type);
  v_gov   := deal_governing_document(p_deal_id);

  RETURN jsonb_build_object(
    'id', v_deal.id,
    'display_code', v_deal.display_code,
    'title', v_deal.title,
    'deal_type', v_deal.deal_type,
    'status', v_deal.status,
    'badge', deal_status(v_deal.id),
    'completed_at', v_deal.completed_at,
    'notes', v_deal.notes,
    'contract_id', v_deal.contract_id,
    'created_at', v_deal.created_at,
    'roles', to_jsonb(v_roles),
    'horse', (SELECT jsonb_build_object('id', h.id,
                'name', coalesce(nullif(h.registered_name,''), h.nickname))
                FROM horses h JOIN contracts ct ON contract_horse_id(ct.id) = h.id
               WHERE ct.id = v_deal.contract_id),
    'parties', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'party_role', cp.party_role, 'contact_id', cp.contact_id,
               'name', nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''),
               'email', c.email, 'display_code', c.display_code)
             ORDER BY array_position(v_roles, cp.party_role), cp.signer_order, cp.id)
        FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
       WHERE cp.contract_id = v_deal.contract_id), '[]'::jsonb),
    'documents', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'document_id', d.id, 'title', d.title, 'display_code', d.display_code,
               'template_key', t.template_key, 'status', d.status,
               'workflow_state', d.workflow_state, 'created_at', d.created_at,
               'governing', (d.id = v_gov),
               'signed', (SELECT count(*) FROM signatures s
                           WHERE s.document_id = d.id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL),
               'signers', (SELECT count(*) FROM document_parties dp
                            WHERE dp.document_id = d.id AND dp.is_signer))
             ORDER BY (d.id = v_gov) DESC, d.created_at)
        FROM documents d JOIN contract_templates t ON t.id = d.template_id
       WHERE d.contract_id = v_deal.contract_id AND d.deleted_at IS NULL), '[]'::jsonb)
  );
END;
$$;


--
-- Name: deal_document_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_document_status(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'template_key', o.template_key,
             'title', o.title,
             'required', o.required,
             'present', EXISTS (
               SELECT 1 FROM documents d
                 JOIN contract_templates t ON t.id = d.template_id
                WHERE d.contract_id = v_deal.contract_id
                  AND d.deleted_at IS NULL AND d.workflow_state <> 'void'
                  AND t.template_key = o.template_key),
             'executed', EXISTS (
               SELECT 1 FROM documents d
                 JOIN contract_templates t ON t.id = d.template_id
                WHERE d.contract_id = v_deal.contract_id
                  AND d.deleted_at IS NULL AND d.status = 'EXECUTED'
                  AND t.template_key = o.template_key))
           ORDER BY o.sort_order)
      FROM deal_template_options(v_deal.deal_type) o), '[]'::jsonb);
END;
$$;


--
-- Name: deal_governing_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_governing_document(p_deal_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.id
    FROM deals dl
    JOIN documents d ON d.contract_id = dl.contract_id
    JOIN contract_templates t ON t.id = d.template_id
   WHERE dl.id = p_deal_id AND dl.deleted_at IS NULL
     AND d.deleted_at IS NULL AND coalesce(d.workflow_state, '') <> 'void'
     AND is_deal_governing_template(dl.deal_type, t.template_key)
   ORDER BY (t.template_key = deal_governing_template(dl.deal_type)) DESC,
            d.created_at DESC
   LIMIT 1;
$$;


--
-- Name: deal_governing_template(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_governing_template(p_deal_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_deal_type
           WHEN 'SALE'  THEN 'HORSE_BILL_OF_SALE'
           WHEN 'LEASE' THEN 'HORSE_LEASE_V2'
         END;
$$;


--
-- Name: deal_party_roles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_party_roles(p_deal_type text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  -- [party A (the giving/owning side), party B (the receiving side)]
  SELECT CASE p_deal_type
           WHEN 'SALE'  THEN ARRAY['SELLER','BUYER']
           WHEN 'LEASE' THEN ARRAY['LESSOR','LESSEE']
         END;
$$;


--
-- Name: FUNCTION deal_party_roles(p_deal_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.deal_party_roles(p_deal_type text) IS 'The party designations a deal type uses. The type is chosen FIRST precisely so the two sides can be labelled before members are added (deal plan L2).';


--
-- Name: deal_record_export(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_record_export(p_deal_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE; v_roles text[]; v_out text[] := '{}';
  v_role text; r record; v_any boolean;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF NOT (coalesce(has_staff_access() AND v_deal.org_id = current_org(), false))
     AND NOT EXISTS (SELECT 1 FROM contract_parties cp
                      WHERE cp.contract_id = v_deal.contract_id
                        AND cp.contact_id = current_contact_id()) THEN
    RAISE EXCEPTION 'not authorized for this deal';
  END IF;

  v_roles := deal_party_roles(v_deal.deal_type);

  v_out := v_out || (coalesce(v_deal.title, initcap(lower(v_deal.deal_type)) || ' deal'))::text;
  v_out := v_out || ('Reference: ' || coalesce(v_deal.display_code, v_deal.id::text))::text;
  v_out := v_out || ('Type: ' || initcap(lower(v_deal.deal_type)))::text;
  v_out := v_out || ('Opened: ' || to_char(v_deal.created_at, 'FMMonth FMDD, YYYY'))::text;
  v_out := v_out || ('Status: ' || (deal_status(p_deal_id) ->> 'label'))::text;
  IF v_deal.completed_at IS NOT NULL THEN
    v_out := v_out || ('Completed: ' || to_char(v_deal.completed_at, 'FMMonth FMDD, YYYY'))::text;
  END IF;

  SELECT coalesce(nullif(h.registered_name,''), h.nickname) INTO r
    FROM horses h JOIN contracts ct ON contract_horse_id(ct.id) = h.id WHERE ct.id = v_deal.contract_id;
  IF FOUND THEN
    v_out := v_out || ''::text;
    v_out := v_out || 'HORSE'::text;
    v_out := v_out || ('  ' || (SELECT coalesce(nullif(h.registered_name,''), h.nickname)
                                  FROM horses h JOIN contracts ct ON contract_horse_id(ct.id) = h.id
                                 WHERE ct.id = v_deal.contract_id))::text;
  END IF;

  FOREACH v_role IN ARRAY v_roles LOOP
    v_out := v_out || ''::text;
    v_out := v_out || upper(initcap(lower(v_role)))::text;
    v_any := false;
    FOR r IN
      SELECT nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), '') AS nm,
             c.email, c.phone_display AS phone, c.address_composed AS addr
        FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
       WHERE cp.contract_id = v_deal.contract_id AND cp.party_role = v_role
       ORDER BY cp.signer_order NULLS LAST, cp.id
    LOOP
      v_any := true;
      v_out := v_out || ('  ' || coalesce(r.nm, r.email, 'Unnamed')
                         || coalesce(' · ' || r.email, '') || coalesce(' · ' || r.phone, ''))::text;
      IF nullif(btrim(coalesce(r.addr,'')),'') IS NOT NULL THEN
        v_out := v_out || ('    ' || r.addr)::text;
      END IF;
    END LOOP;
    IF NOT v_any THEN v_out := v_out || '  (nobody named yet)'::text; END IF;
  END LOOP;

  v_out := v_out || ''::text;
  v_out := v_out || 'DOCUMENTS'::text;
  v_any := false;
  FOR r IN
    SELECT coalesce(d.title, t.template_key) AS title, d.display_code, d.status,
           d.effective_date,
           (SELECT count(*) FROM signatures s WHERE s.document_id = d.id
              AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL) AS signed,
           (SELECT count(*) FROM document_parties dp WHERE dp.document_id = d.id AND dp.is_signer) AS signers
      FROM documents d JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contract_id = v_deal.contract_id AND d.deleted_at IS NULL
       AND coalesce(d.workflow_state,'') <> 'void'
     ORDER BY d.created_at
  LOOP
    v_any := true;
    v_out := v_out || ('  ' || r.title || coalesce(' (' || r.display_code || ')', '')
                       || ' — ' || CASE WHEN r.status = 'EXECUTED' THEN 'complete'
                                        ELSE r.signed || '/' || r.signers || ' signatures' END
                       || coalesce(', effective ' || to_char(r.effective_date, 'FMMonth FMDD, YYYY'), ''))::text;
  END LOOP;
  IF NOT v_any THEN v_out := v_out || '  (none yet)'::text; END IF;

  IF nullif(btrim(coalesce(v_deal.notes,'')),'') IS NOT NULL THEN
    v_out := v_out || ''::text;
    v_out := v_out || 'NOTES'::text;
    v_out := v_out || ('  ' || v_deal.notes)::text;
  END IF;

  RETURN array_to_string(v_out, E'\n');
END;
$$;


--
-- Name: deal_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_status(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal   deals%ROWTYPE;
  v_doc    record;
  v_need   int;
  v_have   int;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  IF v_deal.status = 'void' THEN
    RETURN jsonb_build_object('code', 'void', 'label', 'Void');
  END IF;

  SELECT d.id, d.workflow_state, d.status INTO v_doc
    FROM documents d WHERE d.id = deal_governing_document(p_deal_id);

  -- no governing document yet: the deal exists, nothing has been opened
  IF NOT FOUND THEN
    RETURN jsonb_build_object('code', 'created', 'label', 'Created');
  END IF;

  SELECT count(*) FILTER (WHERE dp.is_signer) INTO v_need
    FROM document_parties dp WHERE dp.document_id = v_doc.id;
  SELECT count(*) INTO v_have
    FROM signatures s
   WHERE s.document_id = v_doc.id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL;

  IF v_doc.workflow_state = 'executed' OR (v_need > 0 AND v_have >= v_need) THEN
    RETURN jsonb_build_object('code', 'complete', 'label', 'Complete',
                              'signed', v_have, 'required', v_need);
  END IF;

  IF v_have > 0 THEN
    RETURN jsonb_build_object('code', 'signed',
                              'label', 'Signed ' || v_have || '/' || greatest(v_need, v_have),
                              'signed', v_have, 'required', greatest(v_need, v_have));
  END IF;

  RETURN jsonb_build_object('code', 'editable', 'label', 'Editable');
END;
$$;


--
-- Name: deal_template_options(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_template_options(p_deal_type text) RETURNS TABLE(template_key text, title text, required boolean, sort_order integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT t.template_key, t.title, t.required, t.sort_order
    FROM (VALUES
      ('SALE',  'HORSE_BILL_OF_SALE', 'Bill of Sale',          true,  10),
      ('SALE',  'HORSE_SALE_V3',      'Horse Sale Agreement',  false, 20),
      ('LEASE', 'HORSE_LEASE_V3',     'Horse Lease Agreement', true,  10)
    ) AS t(deal_type, template_key, title, required, sort_order)
   WHERE t.deal_type = p_deal_type;
$$;


--
-- Name: decide_booking_change(uuid, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_booking_change(p_change_id uuid, p_approve boolean, p_waive_fee boolean DEFAULT false, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cr     booking_change_requests%ROWTYPE;
  v_b      bookings%ROWTYPE;
  v_client uuid := current_client_id();
  v_when   text;
  v_delta  interval;
  v_scope  text;
  v_ids    uuid[];
  v_n      int;
  rid      uuid;
  r        bookings%ROWTYPE;
  v_freed  int := 0;
  v_refunded boolean := false;
  v_label  text;
  v_needs_payment boolean := false;
BEGIN
  SELECT * INTO v_cr FROM booking_change_requests WHERE id = p_change_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'change request not found'; END IF;
  IF v_cr.status <> 'pending' THEN RAISE EXCEPTION 'already decided'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = v_cr.booking_id;

  -- D25 — what this person's session is CALLED. Resolved once, used in every title.
  v_label := booking_service_label(v_b.kind, v_b.offering_id);

  -- REVIEWQ R2: direction-aware — the default (awaiting_client = false) is
  -- the incumbent shape, staff decides a client's ask; awaiting_client = true
  -- is a staff-proposed counter-time, and only the booking's own client may
  -- decide it.
  IF NOT (
    (v_cr.awaiting_client AND v_client IS NOT NULL AND v_b.client_id = v_client)
    OR (NOT v_cr.awaiting_client AND has_staff_access())
  ) THEN
    RAISE EXCEPTION 'not authorized to decide this request';
  END IF;

  v_scope := coalesce(v_cr.scope, 'one');

  IF NOT p_approve THEN
    -- Three distinct reject shapes:
    IF v_cr.request_kind = 'new' AND v_cr.awaiting_client THEN
      -- (1) the client turned down a staff-proposed counter-time. The
      -- booking was never confirmed by anyone, so it stays 'pending' — this
      -- row withdraws and a fresh 'new' row (proposed time reset to the
      -- booking's own current time) reopens the queue for staff, same
      -- invariant book_open_slot/request_open_time established: every
      -- pending booking has exactly one open companion row.
      UPDATE booking_change_requests SET status='withdrawn', decided_by=auth.uid(), decided_at=now()
        WHERE id=p_change_id;
      INSERT INTO booking_change_requests (org_id, booking_id, requested_by, request_kind,
          proposed_starts_at, proposed_ends_at, status)
        VALUES (v_b.org_id, v_b.id, v_cr.requested_by, 'new', v_b.starts_at, v_b.ends_at, 'pending');
      PERFORM notify_staff(v_b.org_id, 'booking_time_declined',
        'Client declined the proposed time for ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM'),
        '/app/calendar');
      RETURN jsonb_build_object('status','withdrawn', 'kind','new', 'booking_status','requested');

    ELSIF v_cr.request_kind = 'new' THEN
      -- (2) a genuine company decline of a fresh request nobody countered:
      -- terminal, credit refunded if one was debited, reason recorded.
      IF v_b.status <> 'cancelled' AND v_b.credit_id IS NOT NULL THEN
        v_refunded := _refund_booking_credit(v_b);
      END IF;
      UPDATE bookings SET status = 'cancelled', updated_at = now() WHERE id = v_cr.booking_id;
      UPDATE booking_change_requests SET status='rejected', staff_note = coalesce(p_reason, staff_note),
        decided_by=auth.uid(), decided_at=now() WHERE id=p_change_id;
      IF v_b.account_user_id IS NOT NULL AND booking_notifies_client(v_b) THEN
        INSERT INTO notifications (org_id, user_id, kind, title, link)
          VALUES (v_b.org_id, v_b.account_user_id, 'booking_declined',
                  'We could not hold ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM')
                    || ' for your ' || v_label
                    || CASE WHEN p_reason IS NOT NULL THEN ' — ' || p_reason ELSE '' END,
                  '/app/calendar');
      END IF;
      RETURN jsonb_build_object('status','rejected', 'kind','new', 'credit_refunded', v_refunded);

    ELSE
      -- (3) the incumbent shape, unchanged: a reschedule/cancel/defer ask
      -- against an already-live booking is refused, and the booking reverts
      -- to its prior live status.
      UPDATE booking_change_requests SET status='rejected', decided_by=auth.uid(), decided_at=now() WHERE id=p_change_id;
      UPDATE bookings SET status = CASE WHEN kind='lesson' THEN 'scheduled' ELSE 'confirmed' END, updated_at=now()
        WHERE id = v_cr.booking_id AND status IN ('pending','moved');
      IF v_b.account_user_id IS NOT NULL AND booking_notifies_client(v_b) THEN
        INSERT INTO notifications (org_id, user_id, kind, title, link)
          VALUES (v_b.org_id, v_b.account_user_id, 'booking_change_rejected',
                  initcap(v_cr.request_kind) || ' declined for your ' || v_label
                    || ' — please reach out', '/app/calendar');
      END IF;
      RETURN jsonb_build_object('status','rejected');
    END IF;
  END IF;

  -- ⚠️ LIFECYCLE — `approved` IS A REAL STATE AND IT MEANS "WE SAID YES, THE
  -- MONEY HAS NOT ARRIVED". Staff approving a fresh request on an order that
  -- is not paid for lands the booking on `approved` and asks for the money
  -- through the ONE function that already does that (`request_purchase_payment`
  -- → `/api/order-request-payment`). Skipped exactly where the owner said:
  -- already paid, or the session was bought with a credit, or it is a
  -- reschedule of something already settled.
  -- Staff-only, because `request_purchase_payment` is staff-only: when the
  -- CLIENT accepts a staff counter-time this behaves exactly as it did before.
  IF p_approve AND v_cr.request_kind = 'new' AND has_staff_access() THEN
    v_needs_payment := booking_awaiting_payment(v_b);
  END IF;

  -- resolve the affected occurrences by scope
  IF v_b.series_id IS NULL OR v_scope = 'one' THEN
    v_ids := ARRAY[v_b.id];
  ELSIF v_scope = 'all' THEN
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_b.series_id;
  ELSIF v_scope = 'future' THEN
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_b.series_id AND starts_at >= v_b.starts_at;
  ELSIF v_scope LIKE 'weeks:%' THEN
    v_n := nullif(split_part(v_scope, ':', 2), '')::int;
    SELECT array_agg(id) INTO v_ids FROM (
      SELECT id FROM bookings WHERE series_id = v_b.series_id AND starts_at >= v_b.starts_at
      ORDER BY starts_at LIMIT coalesce(v_n, 1)) x;
  ELSE
    v_ids := ARRAY[v_b.id];
  END IF;

  -- REVIEWQ: 'new' rides the same apply-delta-then-schedule branch as
  -- 'reschedule' — a fresh request's proposed_* is set to its own original
  -- time at creation (delta 0, confirm-in-place); a staff counter-offer sets
  -- proposed_* to the new time (delta shifts it), and approving here is the
  -- client's acceptance.
  IF v_cr.request_kind IN ('reschedule','new') THEN
    v_delta := coalesce(v_cr.proposed_starts_at, v_b.starts_at) - v_b.starts_at;
    FOREACH rid IN ARRAY v_ids LOOP
      SELECT * INTO r FROM bookings WHERE id = rid;
      UPDATE bookings SET starts_at = r.starts_at + v_delta, ends_at = r.ends_at + v_delta,
        status = CASE WHEN v_needs_payment THEN 'approved'
                      WHEN kind='lesson' THEN 'scheduled' ELSE 'confirmed' END,
        reminder_1h_sent_at = NULL, reminder_2h_sent_at = NULL, updated_at=now()
      WHERE id = rid;
    END LOOP;
    v_when := to_char(coalesce(v_cr.proposed_starts_at, v_b.starts_at), 'FMMon FMDD, HH12:MI AM');
  ELSE
    FOREACH rid IN ARRAY v_ids LOOP
      SELECT * INTO r FROM bookings WHERE id = rid;
      UPDATE bookings SET status='cancelled', updated_at=now() WHERE id = rid;
      -- CAREPLANS m4 — a cancellation returns THE CREDIT IT SPENT, through the one
      -- refund seam, capped at what the month was minted with and carrying that
      -- month's expiry. The shipped body inserted a fresh, untagged, NEVER-EXPIRING
      -- `change_credit` instead: it survived into the next month (the owner's
      -- ruling is that a cancelled lesson does not), it was spendable on any other
      -- service because it named none, and it was minted even when the booking had
      -- never debited anything — entitlement from nothing. `_refund_booking_credit`
      -- is the seam `delete_calendar_item`, `swap_booking_item` and
      -- `withdraw_my_pending_booking` already use; this arm was the one that did not.
      IF r.status <> 'cancelled' AND r.credit_id IS NOT NULL AND r.client_id IS NOT NULL THEN
        IF _refund_booking_credit(r) THEN
          v_freed := v_freed + 1;
        END IF;
      END IF;
    END LOOP;
    v_when := to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM');
  END IF;

  UPDATE booking_change_requests
    SET status='approved', fee_waived = p_waive_fee, decided_by=auth.uid(), decided_at=now()
    WHERE id=p_change_id;

  -- ⚠️ THE ASK FOR THE MONEY. `request_purchase_payment` raises the buyer's
  -- "payment due" notice and the staff copy through `notify_purchase_unpaid`,
  -- and writes the `payment_requested` line on the order's own timeline — so
  -- this branch deliberately does NOT also send the booking notification
  -- below. One approval, one notice, and it is the one about the money.
  IF v_needs_payment THEN
    PERFORM request_purchase_payment(v_b.purchase_id, NULL);
  END IF;

  IF v_b.account_user_id IS NOT NULL AND booking_notifies_client(v_b)
     AND NOT v_needs_payment THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id,
              CASE WHEN v_cr.request_kind = 'new' THEN 'booking_confirmed' ELSE 'booking_' || v_cr.request_kind || '_approved' END,
              CASE v_cr.request_kind
                WHEN 'reschedule' THEN 'Your ' || v_label || ' has moved to ' || v_when
                WHEN 'new' THEN 'Your ' || v_label || ' on ' || v_when || ' is confirmed'
                WHEN 'defer' THEN 'Your ' || v_label || ' is deferred — that session is back on your account'
                ELSE 'Your ' || v_label || ' on ' || v_when || ' is cancelled'
                     || CASE WHEN v_freed > 0
                             THEN ' — that session is back on your account, so pick a new time whenever you like'
                             ELSE '' END END,
              '/app/calendar');
  END IF;

  RETURN jsonb_build_object('status', CASE WHEN v_needs_payment THEN 'approved_payment_due' ELSE 'approved' END,
                            'kind', v_cr.request_kind,
                            'payment_requested', v_needs_payment,
                            'affected', coalesce(array_length(v_ids,1),1));
END;
$$;


--
-- Name: decline_contract_termination(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_contract_termination(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_title text; v_requester uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, title, termination_requested_by INTO v_org, v_title, v_requester
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL
      AND termination_requested_at IS NOT NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no pending termination request'; END IF;
  IF NOT caller_is_document_party_or_staff(p_document_id) THEN RAISE EXCEPTION 'not authorized'; END IF;

  UPDATE documents SET termination_requested_at = NULL, termination_requested_by = NULL,
         termination_request_reason = NULL, updated_at = now()
   WHERE id = p_document_id;

  -- ITEM 5d: same as approve — the request is answered, so it resolves.
  PERFORM resolve_notifications_for_link(
    '/app/contracts/' || p_document_id::text, auth.uid(), 'contract_termination_requested');

  -- tell the requester it was declined
  IF v_requester IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    SELECT v_org, pr.user_id, 'contract_termination_declined',
           coalesce(v_title,'A contract') || ' — termination declined',
           'The other party declined the request to terminate. The contract remains in force.',
           '/app/contracts/' || p_document_id::text
      FROM profiles pr WHERE pr.contact_id = v_requester AND pr.user_id IS NOT NULL;
  END IF;
END;
$$;


--
-- Name: decline_payment_claim(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_payment_claim(p_purchase_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur    purchases%ROWTYPE;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to decline a payment claim';
  END IF;

  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown purchase: %', p_purchase_id; END IF;
  IF v_pur.client_claim_status <> 'pending' THEN
    RAISE EXCEPTION 'no pending claim on this order (claim status: %)', v_pur.client_claim_status;
  END IF;

  UPDATE purchases
     SET client_claim_status         = 'declined',
         client_claim_resolved_by    = auth.uid(),
         client_claim_resolved_at    = now(),
         client_claim_decline_reason = v_reason
   WHERE id = p_purchase_id;

  -- ⚠️ THE ENTRY IS CLOSED, NOT DELETED. "if there were any issues" is the
  -- owner's own line: a declined declaration is exactly the issue the ledger is
  -- for, and the next declaration mints a NEW number rather than reopening this.
  UPDATE payments
     SET status = 'declined', decline_reason = v_reason,
         confirmed_by = auth.uid(), confirmed_at = now()
   WHERE purchase_id = p_purchase_id AND status = 'pending' AND deleted_at IS NULL;

  PERFORM log_status_event('order', p_purchase_id, 'claim_declined', v_reason, v_pur.org_id);
  PERFORM log_status_event('payment', pid, 'declined', v_reason, v_pur.org_id)
     FROM (SELECT id AS pid FROM payments
            WHERE purchase_id = p_purchase_id AND status = 'declined'
              AND confirmed_at >= now() - interval '1 minute') q;

  RETURN jsonb_build_object('declined', true, 'reason', v_reason);
END;
$$;


--
-- Name: FUNCTION decline_payment_claim(p_purchase_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.decline_payment_claim(p_purchase_id uuid, p_reason text) IS 'CASHCONFIRM C2: staff declines a pending client-reported claim that never arrived. payment_status is untouched (a claim never set it) and the claim row is retained, never deleted (D11) — only its resolution (who/when/reason) is recorded. report_my_payment reopens the claim (client_claim_status=pending) if the client reports again.';


--
-- Name: delete_calendar_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_calendar_item(p_id uuid, p_scope text DEFAULT 'one'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_row    bookings%ROWTYPE;
  v_ids    uuid[];
  v_id     uuid;
  v_target bookings%ROWTYPE;
  v_has_history boolean;
  v_n      integer := 0;
  -- SLOTREACH §5
  v_refunded boolean;
  v_label  text;
  v_to     uuid;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_row FROM bookings WHERE id = p_id AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'item not found in this org'; END IF;

  IF p_scope = 'one' OR v_row.series_id IS NULL THEN
    v_ids := ARRAY[p_id];
  ELSIF p_scope = 'future' THEN
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_row.series_id AND starts_at >= v_row.starts_at;
  ELSE
    SELECT array_agg(id) INTO v_ids FROM bookings WHERE series_id = v_row.series_id;
  END IF;

  FOREACH v_id IN ARRAY coalesce(v_ids, ARRAY[]::uuid[]) LOOP
    SELECT * INTO v_target FROM bookings WHERE id = v_id;
    v_has_history := v_target.client_id IS NOT NULL OR v_target.purchase_id IS NOT NULL
      OR v_target.credit_id IS NOT NULL
      OR EXISTS (SELECT 1 FROM booking_change_requests WHERE booking_id = v_target.id);
    v_refunded := false;

    IF v_has_history THEN
      IF v_target.status <> 'cancelled' AND v_target.credit_id IS NOT NULL THEN
        v_refunded := coalesce(_refund_booking_credit(v_target), false);
      END IF;
      UPDATE bookings SET deleted_at = now(), deleted_by = auth.uid(),
          status = 'cancelled', updated_at = now()
        WHERE id = v_id;
      UPDATE booking_change_requests SET status='withdrawn', decided_by=auth.uid(), decided_at=now()
        WHERE booking_id = v_id AND status='pending';
    ELSE
      DELETE FROM bookings WHERE id = v_id;
    END IF;

    -- SLOTREACH §5 — WALK2 G-3, the other half. A session vanishing from someone's
    -- calendar with no record anywhere that it happened is the defect; this is the
    -- record. Only a session that was actually LIVE is announced — re-deleting an
    -- already-cancelled row is housekeeping, not news.
    v_to := v_target.account_user_id;
    IF v_target.status NOT IN ('cancelled','expired')
       AND coalesce(booking_notifies_client(v_target), false)
       AND v_to IS NOT NULL
       AND v_to <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid) THEN
      v_label := booking_service_label(v_target.kind, v_target.offering_id);
      PERFORM _announce_booking_change(v_org, v_to, 'booking_cancelled',
        'Your ' || v_label || ' on '
          || to_char(v_target.starts_at, 'FMDay FMMon FMDD') || ' at '
          || to_char(v_target.starts_at, 'FMHH12:MI AM') || ' is cancelled'
          || CASE WHEN v_refunded
                  THEN ' — that session is back on your account, so pick a new time whenever you like.'
                  ELSE '.' END);
    END IF;

    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


--
-- Name: delete_contract_comment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_contract_comment(p_comment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_author uuid; v_me uuid; v_sub timestamptz; v_parent uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT document_id, author_contact_id, submitted_at, parent_request_id
    INTO v_doc, v_author, v_sub, v_parent
    FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;
  SELECT contact_id INTO v_me FROM comment_author_identity(v_doc);
  IF v_me IS NULL OR v_me <> v_author THEN RAISE EXCEPTION 'only the author may delete this comment'; END IF;
  IF v_parent IS NULL AND v_sub IS NOT NULL THEN
    RAISE EXCEPTION 'this request was submitted for review and can no longer be withdrawn';
  END IF;
  DELETE FROM contract_change_requests WHERE id = p_comment_id OR parent_request_id = p_comment_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: delete_contract_composition_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_contract_composition_item(p_document_id uuid, p_field_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_kind text; v_section text; v_n int;
BEGIN
  SELECT custom_kind, section INTO v_kind, v_section FROM contract_fields
   WHERE document_id = p_document_id AND field_key = p_field_key;
  IF v_kind IS NULL THEN RAISE EXCEPTION 'not an author-added item: %', p_field_key; END IF;

  IF v_kind = 'section' THEN
    DELETE FROM contract_fields WHERE document_id = p_document_id
      AND (section = v_section AND custom_kind IS NOT NULL);
  ELSIF v_kind = 'header' THEN
    DELETE FROM contract_fields WHERE document_id = p_document_id
      AND (field_key = p_field_key OR clause_key = p_field_key)
      AND custom_kind IS NOT NULL;
  ELSE
    DELETE FROM contract_fields WHERE document_id = p_document_id AND field_key = p_field_key;
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: delete_lessee_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lessee_entry(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horse_lessee_entries SET deleted_at = now(), updated_at = now()
   WHERE id = p_id AND org_id = current_org()
     AND (has_staff_access() OR (author_contact_id = current_contact_id() AND caller_is_current_lessee(horse_id)));
  IF NOT FOUND THEN RAISE EXCEPTION 'not your entry to remove, or the lease has ended'; END IF;
END;
$$;


--
-- Name: deliver_evaluation_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_evaluation_report(p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_org     uuid;
  v_user    uuid;
  v_consistent boolean;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT contact_id, org_id INTO v_contact, v_org FROM evaluation_reports
   WHERE id = p_report_id AND org_id = current_org();
  IF v_contact IS NULL THEN RAISE EXCEPTION 'report not found'; END IF;

  SELECT EXISTS (SELECT 1 FROM groups g
                  WHERE g.contact_id = v_contact AND g.group_type IN ('RIDER','HORSE_OWNER'))
    INTO v_consistent;

  UPDATE evaluation_reports
     SET status = 'delivered', delivered_at = now(),
         available_until = CASE WHEN v_consistent THEN NULL ELSE now() + interval '90 days' END
   WHERE id = p_report_id;

  -- ALERT the client (their account), not just staff. notifications.user_id is
  -- the account; resolve it from the report's contact.
  SELECT user_id INTO v_user FROM profiles WHERE contact_id = v_contact LIMIT 1;
  IF v_user IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    VALUES (v_org, v_user, 'evaluation_report_ready',
            'Your horse evaluation report is ready',
            'Your evaluation report is available to review, download, or share.',
            '/app/evaluations');
  END IF;
  -- TASK-FIX3: was '/app/ops/oversight', which no longer resolves.
  PERFORM notify_staff(v_org, 'evaluation_report_delivered',
    'An evaluation report was delivered', '/app/ops/evaluations');

  RETURN jsonb_build_object('ok', true, 'consistent_client', v_consistent);
END;
$$;


--
-- Name: deliver_executed_document_set(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_executed_document_set(p_contact_id uuid, p_include uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ids  uuid[];
  v_org  uuid;
  v_base text;
  v_req  bigint;
BEGIN
  -- Callers: the execution trigger, the sweep (service_role), staff, and a person
  -- flushing THEIR OWN set to themselves (SIGNBOOK). Unchanged authorization.
  IF NOT (pg_trigger_depth() > 0
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(has_staff_access(), false)
          OR (p_contact_id IS NOT NULL AND p_contact_id = current_contact_id())
          OR auth.uid() IS NULL AND auth.role() IS NULL) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF p_contact_id IS NULL THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'no contact');
  END IF;

  WITH deliverable AS (
    SELECT d.id, d.delivery_set_id, d.contact_id, d.generated_at, d.created_at
      FROM documents d
     WHERE d.deleted_at IS NULL
       AND d.status = 'EXECUTED'
       AND d.executed_email_sent_at IS NULL
       AND (d.delivery_held_at IS NOT NULL OR d.id = p_include)
       AND NOT EXISTS (
         SELECT 1 FROM signatures s
          WHERE s.document_id = d.id AND s.deleted_at IS NULL AND s.signed_at IS NULL)
  ), anchored AS (
    SELECT * FROM deliverable WHERE contact_id = p_contact_id
  )
  SELECT array_agg(x.id ORDER BY x.generated_at, x.created_at)
    INTO v_ids
    FROM (
      SELECT * FROM anchored
      UNION
      -- the rest of the SAME delivery SET's undelivered documents (contract set
      -- or non-contract onboarding set — one marker, one rule)
      SELECT dl.* FROM deliverable dl
       WHERE dl.delivery_set_id IS NOT NULL
         AND dl.delivery_set_id IN (SELECT a.delivery_set_id FROM anchored a WHERE a.delivery_set_id IS NOT NULL)
    ) x;

  IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'nothing to deliver');
  END IF;

  SELECT d.org_id INTO v_org FROM documents d WHERE d.id = v_ids[1];

  SELECT value_text INTO v_base FROM config_values
   WHERE org_id = v_org AND namespace = 'SYSTEM' AND key = 'APP_BASE_URL';
  IF coalesce(btrim(v_base), '') = '' THEN
    UPDATE documents SET executed_email_error = 'APP_BASE_URL not configured'
     WHERE id = ANY(v_ids);
    RETURN jsonb_build_object('sent', false, 'reason', 'no base url',
                              'documents', array_length(v_ids, 1));
  END IF;

  SELECT net.http_post(
           url     := v_base || '/api/deliver-documents',
           body    := jsonb_build_object(
                        'documentIds',
                        (SELECT jsonb_agg(x::text) FROM unnest(v_ids) x))
                      || CASE WHEN p_context IS NULL THEN '{}'::jsonb
                              ELSE jsonb_build_object('context', p_context) END,
           headers := '{"Content-Type": "application/json"}'::jsonb,
           timeout_milliseconds := 15000
         ) INTO v_req;

  UPDATE documents
     SET executed_email_sent_at = now(),
         executed_email_error   = NULL,
         delivery_held_at       = NULL
   WHERE id = ANY(v_ids);

  RETURN jsonb_build_object(
    'sent', true, 'request_id', v_req, 'documents', array_length(v_ids, 1));
END;
$$;


--
-- Name: delivery_set_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_set_complete(p_set_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_set_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM documents d
     WHERE d.delivery_set_id = p_set_id
       AND d.deleted_at IS NULL
       AND d.status NOT IN ('EXECUTED', 'VOID')
       AND coalesce(d.workflow_state, '') <> 'void');
$$;


--
-- Name: derive_affiliations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_affiliations(p_contact_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ex AS (
    SELECT bool_or(t.template_key = 'RELEASE_PARTICIPANT') AS sig_rider,
           bool_or(t.template_key = 'RELEASE_HORSE_CARE')  AS sig_care,
           bool_or(t.template_key = 'HORSE_EMERGENCY_VET') AS sig_vet,
           bool_or(t.template_key = 'RELEASE_GENERAL')     AS sig_guest
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = p_contact_id AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
  ),
  -- THE PURCHASE. segment rider -> RIDER, segment horse -> HORSE_OWNER;
  -- inquire-only lines and voided purchases are not a purchase.
  --
  -- CAREPATH §C1d.2: `own_horse` is the third fact this CTE now carries — a
  -- lesson the client rides THEIR OWN horse in. Same predicate as
  -- my_onboarding_state's horse_needed, so the documents and the horse intake
  -- step are triggered by exactly the same orders.
  pur AS (
    SELECT DISTINCT lower(coalesce(o.segment, '')) AS seg,
           (lower(coalesce(o.segment, '')) = 'rider' AND o.horse_included = false) AS own_horse
      FROM purchases p
      JOIN purchase_items pi ON pi.purchase_id = p.id
      JOIN offerings o       ON o.id = pi.offering_id
     WHERE p.buyer_contact_id = p_contact_id
       AND coalesce(p.status, '') <> 'void'
       AND p.deleted_at IS NULL
       AND coalesce(o.config_kind, '') <> 'inquire'
  )
  SELECT (
    SELECT array_agg(g ORDER BY g) FROM (
      -- GUEST: the visitor release is the affiliation (2026-08-04). Without
      -- this, signing the general release granted NO affiliation at all, so a
      -- visitor had documents on file and no category to hang them on. It is
      -- additive: a guest who later signs a participant release simply gains
      -- RIDER alongside it.
      SELECT 'GUEST'::text AS g
       WHERE (SELECT sig_guest FROM ex)
      UNION
      SELECT 'RIDER'::text AS g
       WHERE (SELECT sig_rider FROM ex)
          OR EXISTS (SELECT 1 FROM pur WHERE seg = 'rider')
      UNION
      SELECT 'HORSE_OWNER'
       WHERE (SELECT (sig_care AND sig_vet) FROM ex)
          OR EXISTS (SELECT 1 FROM horses h
                      WHERE h.current_owner_contact_id = p_contact_id AND h.deleted_at IS NULL)
          OR EXISTS (SELECT 1 FROM pur WHERE seg = 'horse')
          -- §C1d.2 — a lesson on their own horse is a horse-related purchase.
          OR EXISTS (SELECT 1 FROM pur WHERE own_horse)
      UNION
      -- DEAL_PARTY: they are named on a contract. A description, not an
      -- obligation — it says "this person has a deal with us" and assigns
      -- nothing. The company itself is never tagged: on every lease FHE writes,
      -- one of the parties IS French Heritage Equestrian.
      SELECT 'DEAL_PARTY' WHERE EXISTS (
        SELECT 1 FROM document_parties dp
          JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
          JOIN contacts c2 ON c2.id = dp.contact_id
         WHERE dp.contact_id = p_contact_id
           AND dp.party_role IN ('BUYER','SELLER','LESSEE','LESSOR')
           AND NOT coalesce(c2.is_company, false))
      UNION
      SELECT 'PARENT_GUARDIAN' WHERE EXISTS (
        SELECT 1 FROM document_parties dp
         WHERE dp.contact_id = p_contact_id AND dp.party_role = 'GUARDIAN')
    ) s
  );
$$;


--
-- Name: derive_request_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_request_status(p_request_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_active int; v_total int;
BEGIN
  SELECT count(*) FILTER (WHERE state NOT IN ('declined','not_a_booking','withdrawn','expired','confirmed')),
         count(*)
    INTO v_active, v_total
    FROM request_selections WHERE request_id = p_request_id;
  IF v_total = 0 THEN RETURN 'new'; END IF;
  IF v_active > 0 THEN RETURN 'open'; END IF;
  RETURN 'closed';
END;
$$;


--
-- Name: discard_booking_form(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.discard_booking_form(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b     bookings%ROWTYPE;
  v_f     booking_forms%ROWTYPE;
  v_blank boolean;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found in this org'; END IF;

  SELECT * INTO v_f FROM booking_forms WHERE booking_id = p_booking_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('booking_id', p_booking_id, 'outcome', 'none');
  END IF;

  v_blank := _booking_form_is_blank(v_f.answers);

  IF v_blank THEN
    DELETE FROM booking_forms WHERE id = v_f.id;
    RETURN jsonb_build_object('booking_id', p_booking_id, 'outcome', 'deleted');
  END IF;

  UPDATE booking_forms
     SET status = 'retired', retired_at = now(), retired_by = auth.uid(), updated_at = now()
   WHERE id = v_f.id;
  RETURN jsonb_build_object('booking_id', p_booking_id, 'outcome', 'retired');
END;
$$;


--
-- Name: disclosure_entry_fields(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disclosure_entry_fields(p_section text, p_entry jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'label', s.label,
    'value', CASE
      WHEN s.kind = 'occurrence' THEN
        CASE WHEN coalesce((p_entry->>'current')::boolean, false) THEN 'Current'
             ELSE coalesce(nullif(btrim(p_entry->>s.k),''), '') END
      ELSE coalesce(nullif(btrim(p_entry->>s.k),''), '') END
  ) ORDER BY s.ord), '[]'::jsonb)
  FROM disclosure_section_spec(p_section) WITH ORDINALITY AS s(k, label, kind, ord);
$$;


--
-- Name: disclosure_gate_locked(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disclosure_gate_locked(p_document_id uuid, p_gate_field text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- p_gate_field like 'HORSE.KNOWN_CONDITIONS_GATE' -> the section's HAS-ENTRIES token
  -- is the same key ('KNOWN_CONDITIONS_GATE'); the resolver returns 'YES' when the
  -- record section is non-empty. Locked exactly when that is 'YES'.
  SELECT CASE WHEN p_gate_field LIKE 'HORSE.%\_GATE' THEN
    coalesce((SELECT horse_field_token_value(h, split_part(p_gate_field,'.',2))='YES'
                FROM documents d JOIN horses h ON h.id = d.horse_id
               WHERE d.id = p_document_id), false)
  ELSE false END;
$$;


--
-- Name: disclosure_section_spec(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disclosure_section_spec(p_section text) RETURNS TABLE(k text, label text, kind text)
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT s.k, s.label, s.kind FROM (VALUES
    ('KNOWN_CONDITIONS', 1, 'description', 'Description', 'text'),
    ('KNOWN_CONDITIONS', 2, 'trigger', 'Trigger', 'text'),
    ('KNOWN_CONDITIONS', 3, 'last_occurrence', 'Current or Date of last occurrence', 'occurrence'),
    ('KNOWN_CONDITIONS', 4, 'accommodations', 'Accommodations', 'text'),
    ('MEDICAL_HISTORY', 1, 'description', 'Description', 'text'),
    ('MEDICAL_HISTORY', 2, 'date', 'Date', 'text'),
    ('MEDICAL_HISTORY', 3, 'type', 'Type', 'text'),
    ('MEDICAL_HISTORY', 4, 'status', 'Status', 'text'),
    ('BEHAVIORAL_HISTORY', 1, 'description', 'Description', 'text'),
    ('BEHAVIORAL_HISTORY', 2, 'trigger', 'Trigger', 'text'),
    ('BEHAVIORAL_HISTORY', 3, 'last_occurrence', 'Current or Date of last occurrence', 'occurrence'),
    ('INJURIES_TO_HORSE', 1, 'description', 'Description', 'text'),
    ('INJURIES_TO_HORSE', 2, 'date', 'Date or date range', 'text'),
    ('INJURIES_TO_HORSE', 3, 'outcome', 'Outcome', 'text'),
    ('INJURIES_TO_HORSE', 4, 'status', 'Status', 'text'),
    -- Medications and supplements: the labels horse_section_entries used to hold as
    -- literals, now here in the same shape. k = the horse_medications column.
    ('MEDICATIONS', 1, 'name', 'Name', 'text'),
    ('MEDICATIONS', 2, 'purpose', 'Purpose', 'text'),
    ('MEDICATIONS', 3, 'dosage', 'Dose', 'text'),
    ('MEDICATIONS', 4, 'frequency', 'Frequency', 'text'),
    ('MEDICATIONS', 5, 'cost_per_dose', 'Cost per dose', 'text'),
    ('MEDICATIONS', 6, 'rx_required', 'Rx required', 'bool'),
    ('SUPPLEMENTS', 1, 'name', 'Name', 'text'),
    ('SUPPLEMENTS', 2, 'purpose', 'Purpose', 'text'),
    ('SUPPLEMENTS', 3, 'dosage', 'Dose', 'text'),
    ('SUPPLEMENTS', 4, 'frequency', 'Frequency', 'text'),
    ('SUPPLEMENTS', 5, 'cost_per_dose', 'Cost per dose', 'text'),
    ('SUPPLEMENTS', 6, 'rx_required', 'Rx required', 'bool')
  ) AS s(section, ord, k, label, kind)
  WHERE s.section = p_section
  ORDER BY s.ord;
$$;


--
-- Name: dismiss_alert(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_alert(p_alert_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF p_alert_id IS NOT NULL THEN
    UPDATE alerts SET dismissed_at = now()
     WHERE id = p_alert_id AND org_id = v_org AND user_id = auth.uid();
  ELSIF p_source IS NOT NULL THEN
    INSERT INTO alert_suppressions (org_id, user_id, source, entity_id, suppressed_until)
    VALUES (v_org, auth.uid(), p_source, p_entity_id, NULL)
    ON CONFLICT (org_id, user_id, source, entity_id)
    DO UPDATE SET suppressed_until = NULL, created_at = now();
  END IF;
END
$$;


--
-- Name: dm_delete_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_delete_message(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE direct_messages
     SET deleted_at = now(), body = ''
   WHERE id = p_message_id AND sender_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'not your message'; END IF;
END;
$$;


--
-- Name: dm_edit_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_edit_message(p_message_id uuid, p_body text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF btrim(coalesce(p_body,'')) = '' THEN RAISE EXCEPTION 'empty message'; END IF;
  UPDATE direct_messages
     SET body = p_body, edited_at = now()
   WHERE id = p_message_id AND sender_id = auth.uid() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'not your message'; END IF;
END;
$$;


--
-- Name: dm_hide_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_hide_conversation(p_other_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO dm_hidden_conversations (user_id, other_id, hidden_before)
  VALUES (auth.uid(), p_other_id, now())
  ON CONFLICT (user_id, other_id) DO UPDATE SET hidden_before = now();
END;
$$;


--
-- Name: dm_list_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_list_conversations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_out jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  WITH pairs AS (
    SELECT dm.*,
           CASE WHEN dm.sender_id = v_uid THEN dm.recipient_id ELSE dm.sender_id END AS other_id
      FROM direct_messages dm
     WHERE (dm.sender_id = v_uid OR dm.recipient_id = v_uid)
  ),
  visible AS (
    SELECT p.*
      FROM pairs p
      LEFT JOIN dm_hidden_conversations h
        ON h.user_id = v_uid AND h.other_id = p.other_id
     WHERE h.hidden_before IS NULL OR p.created_at > h.hidden_before
  ),
  latest AS (
    SELECT DISTINCT ON (other_id) other_id, id, body, deleted_at, created_at, sender_id
      FROM visible
     ORDER BY other_id, created_at DESC
  ),
  unread AS (
    SELECT other_id, count(*) AS n
      FROM visible
     WHERE recipient_id = v_uid AND read_at IS NULL AND deleted_at IS NULL
     GROUP BY other_id
  )
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.last_at DESC), '[]'::jsonb) INTO v_out
    FROM (
      SELECT l.other_id                                   AS user_id,
             pr.display_name, pr.first_name, pr.avatar_url,
             CASE WHEN l.deleted_at IS NOT NULL THEN NULL ELSE l.body END AS last_body,
             (l.sender_id = v_uid)                        AS last_mine,
             l.created_at                                 AS last_at,
             coalesce(u.n, 0)                             AS unread
        FROM latest l
        LEFT JOIN profiles pr ON pr.user_id = l.other_id
        LEFT JOIN unread u ON u.other_id = l.other_id
    ) t;

  RETURN v_out;
END;
$$;


--
-- Name: dm_mark_conversation_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_mark_conversation_read(p_other_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE direct_messages
     SET read_at = now()
   WHERE recipient_id = auth.uid() AND sender_id = p_other_id AND read_at IS NULL;
END;
$$;


--
-- Name: dm_unread_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_unread_total() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(count(*), 0)::int
    FROM direct_messages dm
    LEFT JOIN dm_hidden_conversations h
      ON h.user_id = auth.uid() AND h.other_id = dm.sender_id
   WHERE dm.recipient_id = auth.uid()
     AND dm.read_at IS NULL
     AND dm.deleted_at IS NULL
     AND (h.hidden_before IS NULL OR dm.created_at > h.hidden_before);
$$;


--
-- Name: doc_status_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.doc_status_code(p_status text, p_workflow text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status = 'EXECUTED' THEN 'signed'
    WHEN p_status = 'VOID'     THEN 'void'
    WHEN p_workflow = 'in_review' THEN 'sent_for_review'
    WHEN p_workflow = 'locked'    THEN 'ready_to_sign'
    WHEN p_workflow IN ('editing') THEN 'in_progress'
    WHEN p_status = 'AWAITING_SIGNATURE' THEN 'ready_to_sign'
    ELSE 'assigned' END;
$$;


--
-- Name: document_changes_frozen(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_changes_frozen(p_document_id uuid, p_author_contact_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Nothing freezes a document that nobody has signed. The old rule froze on a
  -- counterparty OPENING it, which made a normal joint review lock the author
  -- out of their own draft.
  SELECT EXISTS (
    SELECT 1 FROM documents d
     WHERE d.id = p_document_id
       AND d.status = 'EXECUTED');
$$;


--
-- Name: FUNCTION document_changes_frozen(p_document_id uuid, p_author_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_changes_frozen(p_document_id uuid, p_author_contact_id uuid) IS 'TRUE only once the document is fully EXECUTED. Reading a document never freezes it — the previous rule locked the author out as soon as any counterparty opened the draft. A partial signature does not freeze either; it is VOIDED by the edit instead (see void_signatures_on_edit), because a signature attests to a specific text.';


--
-- Name: document_changes_since_signature(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_changes_since_signature(p_document_id uuid, p_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target uuid := coalesce(p_contact_id, current_contact_id());
  v_since  timestamptz;
BEGIN
  -- when this party's signature last came off (the withdrawal event), else when
  -- they last signed. Nothing before that is "new" to them.
  SELECT max(l.created_at) INTO v_since
    FROM contract_change_log l
   WHERE l.document_id = p_document_id
     AND l.change_kind = 'signature_removed'
     AND coalesce((l.detail ->> 'for_contact_id')::uuid,
                  (l.detail ->> 'by_contact_id')::uuid) = v_target;

  IF v_since IS NULL THEN
    SELECT max(signed_at) INTO v_since
      FROM signatures
     WHERE document_id = p_document_id AND signer_contact_id = v_target;
  END IF;
  IF v_since IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', l.id,
             'change_kind', l.change_kind,
             'field_key', l.field_key,
             'field_label', l.field_label,
             'old_value', l.old_value,
             'new_value', l.new_value,
             'actor', l.actor_label,
             'at', l.created_at)
           ORDER BY l.created_at)
      FROM contract_change_log l
     WHERE l.document_id = p_document_id
       AND l.created_at > v_since
       AND l.change_kind = 'field_value'), '[]'::jsonb);
END;
$$;


--
-- Name: document_delivery_is_held(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_delivery_is_held(p_document_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- A document belongs to a delivery set iff delivery_set_id is set. It is held
  -- while any sibling in that set is unexecuted. A document with NO set
  -- (delivery_set_id NULL) is never held — it delivers as a single document.
  SELECT EXISTS (
    SELECT 1 FROM documents d
     WHERE d.id = p_document_id
       AND d.delivery_set_id IS NOT NULL
       AND NOT delivery_set_complete(d.delivery_set_id));
$$;


--
-- Name: document_horse_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_horse_ids(p_document_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT array_agg(dh.horse_id ORDER BY dh.position, dh.created_at)
       FROM document_horses dh WHERE dh.document_id = p_document_id),
    (SELECT CASE WHEN d.horse_id IS NULL THEN NULL ELSE ARRAY[d.horse_id] END
       FROM documents d WHERE d.id = p_document_id));
$$;


--
-- Name: FUNCTION document_horse_ids(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.document_horse_ids(p_document_id uuid) IS 'Ordered horses a document names (join table, else the legacy horse_id column).';


--
-- Name: document_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_integrity() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_limit  int  := 50;   -- items listed per check; `count` is always the true total
  v_checks jsonb;
  v_known  jsonb;
BEGIN
  IF v_org IS NULL OR NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  WITH live AS (
    SELECT d.*, coalesce(h.nickname, h.registered_name) AS horse_name
      FROM documents d
      LEFT JOIN horses h ON h.id = d.horse_id
     WHERE d.org_id = v_org AND d.deleted_at IS NULL
  ),
  findings AS (
    -- 1. contract link points at a contract row that does not exist
    SELECT 'orphan_contract'::text AS check_key, l.id, l.display_code, l.title,
           l.horse_name, l.status, l.current_status,
           'contract ' || l.contract_id::text || ' does not exist' AS detail
      FROM live l
     WHERE l.contract_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM contracts c WHERE c.id = l.contract_id)

    UNION ALL
    -- 2. horse link points at a horse that is missing or removed
    SELECT 'orphan_horse', l.id, l.display_code, l.title, l.horse_name, l.status,
           l.current_status, 'horse ' || l.horse_id::text || ' is missing or removed'
      FROM live l
     WHERE l.horse_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM horses h
                        WHERE h.id = l.horse_id AND h.deleted_at IS NULL)

    UNION ALL
    -- 4. ready to sign, but nobody is a party to it
    SELECT 'ready_no_parties', l.id, l.display_code, l.title, l.horse_name, l.status,
           l.current_status, 'ready to sign with no parties on the document'
      FROM live l
     WHERE l.current_status = 'ready_to_sign'
       AND NOT EXISTS (SELECT 1 FROM document_parties p WHERE p.document_id = l.id)

    UNION ALL
    -- 5. missing fields its template defines — BY KEY. Reports both numbers.
    SELECT 'missing_fields', l.id, l.display_code, l.title, l.horse_name, l.status,
           l.current_status,
           k.absent::text || ' of ' || k.defined::text || ' defined fields absent'
             || CASE WHEN s.stale > 0
                     THEN '; ' || s.stale::text || ' stale fields held'
                     ELSE '' END
             || ' (' || t.template_key || ')'
      FROM live l
      JOIN contract_templates t ON t.id = l.template_id
      CROSS JOIN LATERAL (
        SELECT count(*) AS defined,
               count(*) FILTER (
                 WHERE NOT EXISTS (SELECT 1 FROM contract_fields f
                                    WHERE f.document_id = l.id
                                      AND f.field_key = fd.field_key)) AS absent
          FROM contract_field_defs fd
         WHERE fd.template_key = t.template_key) k
      CROSS JOIN LATERAL (
        SELECT count(*) AS stale
          FROM contract_fields f
         WHERE f.document_id = l.id
           AND NOT EXISTS (SELECT 1 FROM contract_field_defs fd
                            WHERE fd.template_key = t.template_key
                              AND fd.field_key = f.field_key)) s
     WHERE k.defined > 0 AND k.absent > 0
  ),
  spec (check_key, label, why, sort_order) AS (
    VALUES
      ('orphan_contract',  'Contract link points at a contract that no longer exists',
       'The document cannot be signed — the foreign-key re-check aborts the signing transaction.', 1),
      ('orphan_horse',     'Horse link points at a horse that is missing or removed',
       'The document names a horse the system can no longer resolve.', 2),
      ('ready_no_parties', 'Ready to sign, but nobody is a party to it',
       'Nobody can sign it and nobody is notified about it.', 3),
      ('missing_fields',   'Missing fields its template defines',
       'It renders as an incomplete contract, quietly. Compared by field key, so a template edit does not move the result.', 4)
  ),
  listed AS (
    SELECT f.check_key,
           jsonb_agg(jsonb_build_object(
             'id',             f.id,
             'display_code',   f.display_code,
             'title',          f.title,
             'horse',          f.horse_name,
             'status',         f.status,
             'current_status', f.current_status,
             'detail',         f.detail,
             'can_cleanup',    can_cleanup_document(f.id)
           ) ORDER BY f.display_code) FILTER (WHERE f.rn <= v_limit) AS items,
           count(*) AS total
      FROM (SELECT f.*, row_number() OVER (PARTITION BY f.check_key
                                               ORDER BY f.display_code) AS rn
              FROM findings f) f
     GROUP BY f.check_key
  )
  SELECT jsonb_agg(jsonb_build_object(
           'key',   s.check_key,
           'label', s.label,
           'why',   s.why,
           'count', coalesce(l.total, 0),
           'items', coalesce(l.items, '[]'::jsonb)
         ) ORDER BY s.sort_order)
    INTO v_checks
    FROM spec s LEFT JOIN listed l ON l.check_key = s.check_key;

  -- 3. contact-orphans — reported, never actionable.
  SELECT jsonb_build_object(
           'key',   'orphan_contact',
           'label', 'Contact link points at a contact that is missing or removed',
           'note',  'Known and expected. These are the stranded executed documents on '
                    || 'the owner''s test identities. They are evidence and they leave '
                    || 'with the owner-run post-Stage-5 purge, via the 5g routine — '
                    || 'never from this panel.',
           'count', count(*),
           'items', coalesce(jsonb_agg(jsonb_build_object(
                      'id',             x.id,
                      'display_code',   x.display_code,
                      'title',          x.title,
                      'horse',          x.horse_name,
                      'status',         x.status,
                      'current_status', x.current_status,
                      'signatures',     x.sigs
                    ) ORDER BY x.status, x.display_code), '[]'::jsonb)
         )
    INTO v_known
    FROM (
      SELECT d.id, d.display_code, d.title, d.status, d.current_status,
             coalesce(h.nickname, h.registered_name) AS horse_name,
             (SELECT count(*) FROM signatures s
               WHERE s.document_id = d.id AND s.deleted_at IS NULL) AS sigs
        FROM documents d
        LEFT JOIN horses h ON h.id = d.horse_id
       WHERE d.org_id = v_org AND d.deleted_at IS NULL AND d.contact_id IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM contacts c
                          WHERE c.id = d.contact_id AND c.deleted_at IS NULL)
    ) x;

  RETURN jsonb_build_object(
    'checked_at',  now(),
    'item_limit',  v_limit,
    'checks',      coalesce(v_checks, '[]'::jsonb),
    'known',       v_known
  );
END;
$$;


--
-- Name: document_parties_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_parties_summary(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_horse uuid;
BEGIN
  SELECT org_id, horse_id INTO v_org, v_horse FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  RETURN jsonb_build_object(
    'parties', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'party_role', dp.party_role,
          'contact_id', dp.contact_id,
          'name',  nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
          'email', nullif(btrim(coalesce(c.email,'')), ''),
          'phone', nullif(btrim(coalesce(c.phone,'')), ''),
          'address', nullif(btrim(coalesce(
                       nullif(btrim(coalesce(c.address_composed,'')),''),
                       compose_address(c.address_line1, c.address_line2, c.city, c.state, c.postal_code)
                     ,'')), ''),
          -- component fields so the modal can edit the address in parts
          'address_line1', c.address_line1, 'address_line2', c.address_line2,
          'city', c.city, 'state', c.state, 'postal_code', c.postal_code,
          'first_name', c.first_name, 'last_name', c.last_name,
          -- PARTYEMAIL P1: this party is an email address and nothing else yet.
          -- The card says so rather than printing an em dash where a name goes.
          'awaiting_details', coalesce(c.name_needs_confirmation, false),
          -- required-field completeness (name+address+email+phone)
          'missing', (
            SELECT coalesce(jsonb_agg(m), '[]'::jsonb) FROM (
              SELECT 'name'    AS m WHERE nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')),'') IS NULL
              UNION ALL SELECT 'email'   WHERE nullif(btrim(coalesce(c.email,'')),'') IS NULL
              UNION ALL SELECT 'phone'   WHERE nullif(btrim(coalesce(c.phone,'')),'') IS NULL
              UNION ALL SELECT 'address' WHERE nullif(btrim(coalesce(
                         nullif(btrim(coalesce(c.address_composed,'')),''),
                         compose_address(c.address_line1,c.address_line2,c.city,c.state,c.postal_code)
                       ,'')),'') IS NULL
            ) q
          ))
        ORDER BY dp.party_role, dp.signer_order NULLS LAST, dp.id)
      FROM document_parties dp
      LEFT JOIN contacts c ON c.id = dp.contact_id
      WHERE dp.document_id = p_document_id
        AND dp.party_role IN ('LESSEE','LESSOR','BUYER','SELLER')), '[]'::jsonb),
    'horse_id', v_horse,
    'horse_name', (SELECT coalesce(nullif(registered_name,''), nickname) FROM horses WHERE id = v_horse),
    'horse_missing', CASE WHEN v_horse IS NULL THEN jsonb_build_array('horse')
      ELSE coalesce((SELECT jsonb_agg(m) FROM (
        SELECT 'identity' AS m FROM horses h WHERE h.id = v_horse
         AND nullif(btrim(coalesce(h.registered_name,'')),'') IS NULL
         AND nullif(btrim(coalesce(h.nickname,'')),'') IS NULL
      ) q), '[]'::jsonb) END
  );
END;
$$;


--
-- Name: document_signature_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_signature_state(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_me uuid := current_contact_id();
BEGIN
  RETURN jsonb_build_object(
    'signed_count', (SELECT count(*) FROM signatures
                      WHERE document_id = p_document_id AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'locked_by_signature', EXISTS (SELECT 1 FROM signatures
                      WHERE document_id = p_document_id AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'i_have_signed', EXISTS (SELECT 1 FROM signatures
                      WHERE document_id = p_document_id AND signer_contact_id = v_me
                        AND signed_at IS NOT NULL AND deleted_at IS NULL),
    'signers', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'contact_id', s.signer_contact_id,
               'party_role', s.party_role,
               'name', coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email),
               'signed_at', s.signed_at)
             ORDER BY s.signed_at)
        FROM signatures s LEFT JOIN contacts c ON c.id = s.signer_contact_id
       WHERE s.document_id = p_document_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL), '[]'::jsonb));
END;
$$;


--
-- Name: documents_send_executed_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_send_executed_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_anchor uuid;
BEGIN
  IF NEW.status = 'EXECUTED' AND OLD.status IS DISTINCT FROM 'EXECUTED'
     AND NEW.executed_email_sent_at IS NULL THEN
    BEGIN
      IF NEW.delivery_set_id IS NOT NULL THEN
        IF delivery_set_complete(NEW.delivery_set_id) THEN
          -- The set is finished. One delivery call ships the whole set as one
          -- email per signer, reaching across the set for siblings held under
          -- other anchors. Anchor on this doc's contact, else any set member that
          -- still has a contact and is undelivered.
          v_anchor := coalesce(NEW.contact_id, (
            SELECT d2.contact_id FROM documents d2
             WHERE d2.delivery_set_id = NEW.delivery_set_id AND d2.deleted_at IS NULL
               AND d2.contact_id IS NOT NULL AND d2.status = 'EXECUTED'
               AND d2.executed_email_sent_at IS NULL
             ORDER BY d2.generated_at, d2.created_at LIMIT 1));
          IF v_anchor IS NOT NULL THEN
            PERFORM deliver_executed_document_set(v_anchor, NEW.id);
          ELSE
            -- a set with no contact anchor anywhere: single-document path
            PERFORM send_executed_document_email(NEW.id);
          END IF;
        ELSE
          -- Set incomplete: hold. The last execution in the set flushes it.
          UPDATE documents SET delivery_held_at = coalesce(delivery_held_at, now())
           WHERE id = NEW.id;
        END IF;
      ELSIF NEW.contact_id IS NULL THEN
        -- No set and no contact (a lone multi-party instrument): single-document path.
        PERFORM send_executed_document_email(NEW.id);
      ELSE
        -- No set, a contact anchor: single-document delivery (unchanged).
        PERFORM deliver_executed_document_set(NEW.contact_id, NEW.id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE documents SET executed_email_error = SQLERRM WHERE id = NEW.id;
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: documents_sync_workflow_on_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_sync_workflow_on_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'EXECUTED' THEN
    NEW.workflow_state := 'executed';
  ELSIF NEW.status = 'VOID' AND NEW.workflow_state NOT IN ('void','executed') THEN
    NEW.workflow_state := 'void';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: edit_change_request_entry(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_change_request_entry(p_request_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_org uuid; v_author uuid; v_state text; v_cid uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'a body is required'; END IF;

  SELECT document_id, org_id, author_contact_id
    INTO v_doc, v_org, v_author
    FROM contract_change_requests WHERE id = p_request_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown change request'; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  v_cid := current_contact_id();
  IF v_author IS DISTINCT FROM v_cid THEN
    RAISE EXCEPTION 'only the author may edit this entry';
  END IF;

  SELECT workflow_state INTO v_state FROM documents WHERE id = v_doc AND deleted_at IS NULL;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  IF change_request_is_frozen(p_request_id) THEN
    RAISE EXCEPTION 'the other party has already seen this entry — it can no longer be edited';
  END IF;

  UPDATE contract_change_requests
     SET body = trim(p_body), edited_at = now(), updated_at = now()
   WHERE id = p_request_id;

  RETURN jsonb_build_object('id', p_request_id, 'edited', true);
END;
$$;


--
-- Name: edit_contract_comment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_contract_comment(p_comment_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_author uuid; v_me uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'comment body required'; END IF;

  SELECT document_id, author_contact_id INTO v_doc, v_author
    FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;

  v_me := current_contact_id();
  IF v_me IS NULL OR v_me <> v_author THEN
    RAISE EXCEPTION 'only the author may edit this comment';
  END IF;

  -- THE ONE EDITABILITY RULE. Being NOTIFIED does not freeze an entry; being
  -- SEEN by the other party does. Same predicate as upsert_change_request and
  -- edit_change_request_entry, and the same promise the Notify modal makes.
  IF change_request_is_frozen(p_comment_id) THEN
    RAISE EXCEPTION 'the other party has already seen this entry — it can no longer be edited';
  END IF;

  UPDATE contract_change_requests
     SET body = trim(p_body), edited_at = now(), updated_at = now()
   WHERE id = p_comment_id;

  RETURN jsonb_build_object('id', p_comment_id, 'edited', true);
END;
$$;


--
-- Name: edit_form_field(text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_form_field(p_form_key text, p_field_key text, p_label text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_new_key text DEFAULT NULL::text, p_from_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_base record; v_new jsonb;
  v_key text := nullif(btrim(coalesce(p_new_key,'')),'');
begin
  if not is_admin() then raise exception 'admin only'; end if;
  select * into v_base from _form_edit_base(p_form_key, p_from_version);
  if v_base.schema is null then
    raise exception 'unknown form % (version %)', p_form_key, p_from_version;
  end if;
  if not exists (
    select 1 from jsonb_array_elements(v_base.schema->'sections') s,
                  jsonb_array_elements(s->'fields') f where f->>'key' = p_field_key
  ) then raise exception 'no field % on form %', p_field_key, p_form_key; end if;
  if v_key is not null and v_key <> p_field_key and exists (
    select 1 from jsonb_array_elements(v_base.schema->'sections') s,
                  jsonb_array_elements(s->'fields') f where f->>'key' = v_key
  ) then raise exception 'form % already has a field called %', p_form_key, v_key; end if;

  select jsonb_build_object('sections', jsonb_agg(sec order by sec_i)) into v_new
    from (
      select sec_i, jsonb_set(s, '{fields}', (
               select jsonb_agg(
                        case when f->>'key' <> p_field_key then f
                        else f
                             || case when nullif(btrim(coalesce(p_label,'')),'') is not null
                                     then jsonb_build_object('label', btrim(p_label)) else '{}'::jsonb end
                             || case when nullif(btrim(coalesce(p_type,'')),'') is not null
                                     then jsonb_build_object('type', btrim(p_type)) else '{}'::jsonb end
                             || case when v_key is not null
                                     then jsonb_build_object('key', v_key) else '{}'::jsonb end
                        end order by f_i)
                 from jsonb_array_elements(s->'fields') with ordinality as t(f, f_i))) as sec
        from jsonb_array_elements(v_base.schema->'sections') with ordinality as q(s, sec_i)
    ) x;

  return save_form_definition_version(
    p_form_key, v_base.title, v_base.audience, v_base.purpose, v_new, p_from_version);
end;
$$;


--
-- Name: email_template_discard_draft(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_discard_draft(p_email_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  IF NOT coalesce(is_admin(), false) THEN
    RAISE EXCEPTION 'Email template editing is admin-only';
  END IF;
  UPDATE email_templates SET draft_subject = NULL, draft_body = NULL
   WHERE email_key = p_email_key AND deleted_at IS NULL
     AND (draft_subject IS NOT NULL OR draft_body IS NOT NULL);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('discarded', v_n > 0);
END;
$$;


--
-- Name: email_template_get(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_get(p_email_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT coalesce(is_admin(), false) THEN
    RAISE EXCEPTION 'Email template editing is admin-only';
  END IF;
  SELECT to_jsonb(x) INTO v FROM (
    SELECT e.email_key, e.title, e.description, e.category,
           e.subject, e.body, e.draft_subject, e.draft_body,
           e.version, e.active, e.transactional, e.recipient_note,
           e.from_address_rule, e.reply_to_rule, e.updated_at
      FROM email_templates e
     WHERE e.email_key = p_email_key AND e.deleted_at IS NULL
  ) x;
  IF v IS NULL THEN RAISE EXCEPTION 'Email template % not found', p_email_key; END IF;
  RETURN v;
END;
$$;


--
-- Name: email_template_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_list() RETURNS TABLE(email_key text, title text, description text, category text, subject text, version integer, active boolean, transactional boolean, recipient_note text, from_address_rule text, reply_to_rule text, has_unpublished boolean, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.email_key, e.title, e.description, e.category,
         e.subject, e.version, e.active,
         e.transactional, e.recipient_note,
         e.from_address_rule, e.reply_to_rule,
         (e.draft_body IS NOT NULL OR e.draft_subject IS NOT NULL) AS has_unpublished,
         e.updated_at
    FROM email_templates e
   WHERE e.deleted_at IS NULL
     AND coalesce(is_admin(), false)
   ORDER BY e.category, e.title;
$$;


--
-- Name: email_template_publish(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_publish(p_email_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row     email_templates%rowtype;
  v_version integer;
begin
  if not coalesce(is_admin(), false) then
    raise exception 'Email template editing is admin-only';
  end if;

  select * into v_row from email_templates
   where email_key = p_email_key and deleted_at is null;
  if not found then raise exception 'Email template % not found', p_email_key; end if;

  if v_row.draft_subject is null and v_row.draft_body is null then
    raise exception 'Nothing to publish for % — no draft changes exist.', p_email_key;
  end if;

  v_version := save_email_template_version(
    p_email_key,
    null,
    coalesce(v_row.draft_subject, v_row.subject),
    coalesce(v_row.draft_body,    v_row.body),
    null);

  update email_templates
     set draft_subject = null, draft_body = null
   where id = v_row.id;

  return jsonb_build_object('email_key', p_email_key, 'new_version', v_version);
end;
$$;


--
-- Name: email_template_save_draft(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_save_draft(p_email_key text, p_subject text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_subject text;
  v_body    text;
  v_ds      text;
  v_db      text;
BEGIN
  IF NOT coalesce(is_admin(), false) THEN
    RAISE EXCEPTION 'Email template editing is admin-only';
  END IF;

  SELECT e.subject, e.body INTO v_subject, v_body
    FROM email_templates e WHERE e.email_key = p_email_key AND e.deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Email template % not found', p_email_key; END IF;

  v_ds := CASE WHEN p_subject IS NULL OR p_subject = v_subject THEN NULL ELSE p_subject END;
  v_db := CASE WHEN p_body    IS NULL OR p_body    = v_body    THEN NULL ELSE p_body    END;

  UPDATE email_templates
     SET draft_subject = v_ds, draft_body = v_db
   WHERE email_key = p_email_key AND deleted_at IS NULL;

  RETURN jsonb_build_object(
    'email_key', p_email_key,
    'has_unpublished', (v_ds IS NOT NULL OR v_db IS NOT NULL));
END;
$$;


--
-- Name: email_template_set_active(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_set_active(p_email_key text, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(is_admin(), false) THEN
    RAISE EXCEPTION 'Email template editing is admin-only';
  END IF;
  UPDATE email_templates SET active = p_active
   WHERE email_key = p_email_key AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Email template % not found', p_email_key; END IF;
  RETURN jsonb_build_object('email_key', p_email_key, 'active', p_active);
END;
$$;


--
-- Name: email_template_version_at(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_version_at(p_email_key text, p_version integer) RETURNS TABLE(version integer, parent_version integer, is_current boolean, title text, subject text, body text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.version = e.version as is_current,
         v.title, v.subject, v.body, v.created_at
    from email_template_versions v
    join email_templates e on e.id = v.template_id
   where e.email_key = p_email_key and v.version = p_version and is_admin()
$$;


--
-- Name: email_template_version_list(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_template_version_list(p_email_key text) RETURNS TABLE(version integer, parent_version integer, is_current boolean, subject text, edited_by uuid, edited_by_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.version = e.version as is_current,
         v.subject, v.edited_by,
         coalesce(nullif(btrim(coalesce(p.display_name, '')), ''),
                  nullif(btrim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''),
                  p.email) as edited_by_name,
         v.created_at
    from email_template_versions v
    join email_templates e on e.id = v.template_id
    left join profiles p on p.user_id = v.edited_by
   where e.email_key = p_email_key and is_admin()
   order by v.version desc
$$;


--
-- Name: end_horse_lease(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_horse_lease(p_horse uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = p_horse AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff only'; END IF;
  UPDATE horse_relationships SET active = false, ended_at = now(), term_end = coalesce(term_end, current_date)
   WHERE horse_id = p_horse AND relationship = 'LESSEE' AND active;
  UPDATE horses SET lessee_contact_id = NULL, lessee_name_text = NULL,
         lease_start = NULL, lease_end = NULL, updated_at = now()
   WHERE id = p_horse;
END;
$$;


--
-- Name: end_horse_provider(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_horse_provider(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff only'; END IF;
  UPDATE horse_relationships SET active = false, ended_at = now(), term_end = coalesce(term_end, current_date)
   WHERE id = p_id AND org_id = current_org();
END;
$$;


--
-- Name: ensure_contact_for_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_contact_for_profile(p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_denied_users constant uuid[] := ARRAY[
    'b45a5503-89bc-489a-b012-c7fbf5c09632',  -- admin@fhequestrian.com
    'fdbdfe89-76d7-486b-b734-8e23b09e0353',  -- hello@fhequestrian.com
    '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'   -- admin@cactai.io (platform)
  ]::uuid[];
  v_profile    profiles%ROWTYPE;
  v_contact_id uuid;
  v_first text;
  v_last  text;
  v_org   uuid;
BEGIN
  SELECT * INTO v_profile FROM profiles WHERE user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_profile.contact_id IS NOT NULL THEN
    RETURN v_profile.contact_id;
  END IF;

  -- D1: protected identities never regrow a tenant bridge through this path.
  IF p_user_id = ANY(c_denied_users) THEN
    RETURN NULL;
  END IF;

  v_org := coalesce(v_profile.org_id, current_org());
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  v_first := NULLIF(trim(coalesce(v_profile.first_name, '')), '');
  v_last  := NULLIF(trim(coalesce(v_profile.last_name,  '')), '');
  IF v_first IS NULL AND v_last IS NULL THEN
    v_first := coalesce(v_profile.email, 'Unnamed Contact');
  END IF;

  IF v_profile.email IS NOT NULL THEN
    SELECT c.id INTO v_contact_id
    FROM contacts c
    WHERE lower(c.email) = lower(v_profile.email)
      AND c.org_id = v_org
      AND c.deleted_at IS NULL
      AND NOT c.is_company
      AND NOT EXISTS (SELECT 1 FROM profiles p2 WHERE p2.contact_id = c.id AND p2.user_id <> p_user_id)
    ORDER BY c.created_at
    LIMIT 1;
  END IF;

  IF v_contact_id IS NULL THEN
    -- profiles has no address columns — a contact seeded from a bare
    -- profile starts with name/email/phone only. Address, if any, lives on
    -- contacts already and is untouched by this path.
    INSERT INTO contacts (org_id, first_name, last_name, email)
    VALUES (v_org, v_first, v_last, v_profile.email)
    RETURNING id INTO v_contact_id;
  END IF;

  PERFORM promote_contact_to_account(p_user_id, v_contact_id);
  RETURN v_contact_id;
END;
$$;


--
-- Name: ensure_contract_role_documents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_contract_role_documents(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_req      jsonb;
  v_contract uuid;
  v_org      uuid;
  v_seq      int;
  v_out      jsonb := '[]'::jsonb;
  v_doc      uuid;
  v_minor    uuid;
  v_fields   int;
  r          jsonb;
  v_contact  uuid;
  v_key      text;
BEGIN
  SELECT d.contract_id, d.org_id INTO v_contract, v_org
    FROM documents d WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_contract IS NULL THEN
    RETURN jsonb_build_object('generated', v_out, 'reason', 'no contract');
  END IF;

  UPDATE documents SET sign_sequence = 1
   WHERE id = p_document_id AND sign_sequence IS NULL;
  -- cf STEP 6: the governing document joins the contract's delivery set.
  UPDATE documents SET delivery_set_id = v_contract
   WHERE id = p_document_id AND delivery_set_id IS NULL;

  v_req := coalesce(contract_role_document_requirements(p_document_id) -> 'requirements', '[]'::jsonb);

  SELECT coalesce(max(d.sign_sequence), 0) INTO v_seq
    FROM documents d WHERE d.contract_id = v_contract AND d.deleted_at IS NULL;

  FOR r IN SELECT e.value FROM jsonb_array_elements(v_req) e LOOP
    v_contact := nullif(r ->> 'contact_id', '')::uuid;
    v_key     := r ->> 'template_key';
    CONTINUE WHEN v_contact IS NULL OR v_key IS NULL;
    CONTINUE WHEN coalesce((r ->> 'satisfied')::boolean, false);
    CONTINUE WHEN coalesce(r ->> 'owned_by', 'unassigned') <> 'unassigned';

    -- ⚠️ FIX ROUND 5b — idempotency, per PERSON, orphan-proof. A live (non-void)
    -- copy of THIS template for THIS person on THIS contract is detected whether
    -- the copy is tied to the person by documents.contact_id OR by a CLIENT
    -- document_parties row. The old guard matched contact_id only, so a draft
    -- whose contact_id did not line up was invisible and got duplicated.
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM documents d2 JOIN contract_templates t2 ON t2.id = d2.template_id
       WHERE d2.contract_id = v_contract
         AND t2.template_key = v_key AND d2.deleted_at IS NULL
         AND coalesce(d2.workflow_state, '') <> 'void'
         AND (d2.contact_id = v_contact
           OR EXISTS (SELECT 1 FROM document_parties dp
                       WHERE dp.document_id = d2.id AND dp.contact_id = v_contact
                         AND dp.party_role = 'CLIENT')));

    SELECT id INTO v_minor FROM contacts
     WHERE guardian_contact_id = v_contact AND deleted_at IS NULL
     ORDER BY created_at LIMIT 1;

    SELECT gd.document_id INTO v_doc FROM generate_document(
      v_contact, v_key, v_contract, NULL::uuid,
      jsonb_build_array(
        jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT',
                           'is_signer', true, 'signer_order', 1),
        jsonb_build_object('contact_id', coalesce(v_minor, v_contact),
                           'role', 'PARTICIPANT', 'is_signer', false)),
      NULL::text) gd;
    CONTINUE WHEN v_doc IS NULL;

    v_seq := v_seq + 1;
    SELECT count(*) INTO v_fields FROM contract_fields WHERE document_id = v_doc;

    UPDATE documents
       SET status         = 'AWAITING_SIGNATURE',
           sign_sequence  = v_seq,
           delivery_set_id = v_contract,
           workflow_state = CASE WHEN v_fields = 0 THEN 'locked' ELSE workflow_state END
     WHERE id = v_doc;

    v_out := v_out || jsonb_build_object(
      'document_id', v_doc, 'template_key', v_key,
      'contact_id', v_contact, 'party_role', r ->> 'party_role',
      'sign_sequence', v_seq);
    v_doc := NULL; v_minor := NULL;
  END LOOP;

  RETURN jsonb_build_object('contract_id', v_contract, 'generated', v_out);
END;
$$;


--
-- Name: ensure_deal_for_contract(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_deal_for_contract(p_contract_id uuid, p_deal_type text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal uuid;
  v_type text;
  v_org  uuid;
BEGIN
  IF p_contract_id IS NULL THEN RETURN NULL; END IF;

  SELECT id INTO v_deal FROM deals WHERE contract_id = p_contract_id;
  IF FOUND THEN
    -- a name or a note handed in later still lands on the existing container
    IF nullif(btrim(coalesce(p_title, '')), '') IS NOT NULL THEN
      UPDATE deals SET title = btrim(p_title) WHERE id = v_deal;
    END IF;
    IF nullif(btrim(coalesce(p_notes, '')), '') IS NOT NULL THEN
      UPDATE deals SET notes = btrim(p_notes) WHERE id = v_deal;
    END IF;
    RETURN v_deal;
  END IF;

  SELECT org_id INTO v_org FROM contracts WHERE id = p_contract_id;
  IF v_org IS NULL THEN RETURN NULL; END IF;

  v_type := coalesce(nullif(btrim(coalesce(p_deal_type, '')), ''),
                     contract_deal_type(p_contract_id));
  -- unclassifiable, or a type the deal layer does not know: no deal, no guess
  IF v_type IS NULL OR deal_party_roles(v_type) IS NULL THEN RETURN NULL; END IF;

  INSERT INTO deals (org_id, contract_id, deal_type, title, notes, created_by_contact_id)
    VALUES (v_org, p_contract_id, v_type,
            nullif(btrim(coalesce(p_title, '')), ''),
            nullif(btrim(coalesce(p_notes, '')), ''),
            current_contact_id())
    ON CONFLICT (contract_id) DO NOTHING
    RETURNING id INTO v_deal;

  IF v_deal IS NULL THEN
    SELECT id INTO v_deal FROM deals WHERE contract_id = p_contract_id;
  END IF;
  RETURN v_deal;
END;
$$;


--
-- Name: ensure_gift_buyer_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_gift_buyer_account(p_gift_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_g      gifts%ROWTYPE;
  v_res    jsonb;
  v_fn     text;
  v_ln     text;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF v_g.org_id IS NULL OR nullif(btrim(coalesce(v_g.buyer_email,'')),'') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing org or buyer email');
  END IF;

  v_fn := nullif(split_part(coalesce(v_g.buyer_name,''), ' ', 1), '');
  v_ln := nullif(btrim(substr(coalesce(v_g.buyer_name,''),
            coalesce(nullif(position(' ' in coalesce(v_g.buyer_name,'')), 0),
                     length(coalesce(v_g.buyer_name,''))+1))), '');

  -- THE SPINE, with the commercial marker. Categories empty → no service docs.
  v_res := _ensure_client_account(v_g.org_id, lower(btrim(v_g.buyer_email)),
                                  v_fn, v_ln, ARRAY[]::text[], ARRAY[]::text[], 'CUSTOMER');
  RETURN jsonb_build_object('ok', true, 'contact_id', v_res->>'contact_id');
END;
$$;


--
-- Name: ensure_horse_documents(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_horse_documents(p_horse_id uuid, p_contract_id uuid DEFAULT NULL::uuid, p_include_care boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org       uuid := current_org();
  v_horse     horses%ROWTYPE;
  v_owner     uuid;
  v_contact   uuid := current_contact_id();
  v_templates text[] := ARRAY['HORSE_EMERGENCY_VET'];
  v_tpl       text;
  v_doc       uuid;
  v_voided    int := 0;
  v_rc        int := 0;
  v_gen       jsonb := '[]'::jsonb;
  v_may       boolean;
  v_seq       int;
  v_fields    int;
BEGIN
  -- DEALAUTO: in trigger context the org comes from the horse, not from the
  -- signer's session — a buyer signing a bill of sale may have no org of their
  -- own resolved at that instant, and the horse's org is the fact.
  SELECT * INTO v_horse FROM horses
   WHERE id = p_horse_id AND deleted_at IS NULL
     AND (org_id = v_org OR pg_trigger_depth() > 0);
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org'; END IF;
  v_org := v_horse.org_id;

  v_may := pg_trigger_depth() > 0
    OR has_staff_access()
    OR v_horse.current_owner_contact_id = v_contact
    OR v_horse.lessee_contact_id = v_contact
    OR EXISTS (SELECT 1 FROM horse_relationships hr WHERE hr.horse_id = p_horse_id AND hr.party_contact_id = v_contact AND hr.active);
  IF NOT v_may THEN RAISE EXCEPTION 'not authorized for this horse'; END IF;

  v_owner := coalesce(v_horse.current_owner_contact_id, v_contact);
  IF v_owner IS NULL THEN RAISE EXCEPTION 'horse has no owner on record to authorize'; END IF;

  IF p_include_care IS TRUE
     OR (p_include_care IS NULL AND owner_has_executed_template(v_owner, 'RELEASE_HORSE_CARE')) THEN
    v_templates := array_append(v_templates, 'RELEASE_HORSE_CARE');
  END IF;

  FOREACH v_tpl IN ARRAY v_templates LOOP
    -- HORSEDOCS: a signed document is evidence and is NEVER swept. EXECUTED is
    -- protected, and so is a still-pending document that already carries a live
    -- signature.
    WITH tmpl AS (SELECT id FROM contract_templates WHERE template_key = v_tpl)
    UPDATE documents d
       SET deleted_at = now(), deleted_by = auth.uid()
     WHERE d.contact_id = v_owner
       AND d.template_id = (SELECT id FROM tmpl)
       AND d.deleted_at IS NULL
       AND d.status <> 'EXECUTED'
       AND NOT EXISTS (SELECT 1 FROM signatures s
                        WHERE s.document_id = d.id AND s.deleted_at IS NULL)
       AND (d.horse_id IS NULL
            OR (d.horse_id = p_horse_id AND d.merged_body LIKE '%{{HORSE.REGISTERED_NAME}}%'));
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    v_voided := v_voided + v_rc;

    IF EXISTS (
      SELECT 1 FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
      WHERE d.contact_id = v_owner AND t.template_key = v_tpl
        AND d.horse_id = p_horse_id AND d.deleted_at IS NULL
        AND d.merged_body NOT LIKE '%{{HORSE.REGISTERED_NAME}}%'
    ) THEN
      CONTINUE;
    END IF;

    -- OWNER is the sole party/signer; coverage of FHE + any active-term lessee is
    -- a standing clause in the body, not a named party.
    SELECT gd.document_id INTO v_doc FROM generate_document(
      v_owner, v_tpl, p_contract_id, p_horse_id,
      jsonb_build_array(jsonb_build_object(
        'contact_id', v_owner, 'role', 'CLIENT', 'is_signer', true, 'signer_order', 1)),
      'horse'::text) gd;

    v_seq := CASE WHEN p_contract_id IS NULL THEN NULL
                  WHEN v_tpl = 'HORSE_EMERGENCY_VET' THEN 2
                  WHEN v_tpl = 'RELEASE_HORSE_CARE'  THEN 3 END;
    SELECT count(*) INTO v_fields FROM contract_fields WHERE document_id = v_doc;
    -- DEALAUTO §2: a document with nothing to author is ready to sign. Left
    -- 'editable' it appears in the signing set and offers no way to sign it.
    UPDATE documents
       SET status = 'AWAITING_SIGNATURE', sign_sequence = v_seq,
           workflow_state = CASE WHEN v_fields = 0 THEN 'locked' ELSE workflow_state END
      WHERE id = v_doc AND status = 'DRAFT';
    v_gen := v_gen || jsonb_build_object('template_key', v_tpl, 'document_id', v_doc);
  END LOOP;

  IF p_contract_id IS NOT NULL THEN
    UPDATE documents d SET sign_sequence = 1
      FROM contract_templates t
     WHERE d.template_id = t.id AND is_horse_lease_template(t.template_key)
       AND d.contract_id = p_contract_id AND d.deleted_at IS NULL
       AND d.sign_sequence IS DISTINCT FROM 1;
  END IF;

  RETURN jsonb_build_object('owner_contact_id', v_owner, 'generated', v_gen, 'voided', v_voided);
END;
$$;


--
-- Name: ensure_my_member_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_member_access() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_status  text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;

  SELECT status INTO v_status FROM members WHERE user_id = auth.uid();
  IF v_status = 'active' THEN RETURN true; END IF;

  -- D8: any org-attached account holds community access. Resolve the org from
  -- the profile first, falling back to the contact's client record.
  SELECT p.org_id INTO v_org FROM profiles p WHERE p.user_id = auth.uid();
  IF v_org IS NULL THEN
    SELECT cl.org_id INTO v_org FROM clients cl
     WHERE cl.contact_id = current_contact_id() AND cl.deleted_at IS NULL
     ORDER BY cl.created_at DESC LIMIT 1;
  END IF;
  IF v_org IS NULL THEN RETURN false; END IF;

  IF v_status IS NULL THEN
    INSERT INTO members (user_id, status, org_id)
      VALUES (auth.uid(), 'active', v_org)
      ON CONFLICT (user_id) DO UPDATE SET status = 'active';
    RETURN true;
  ELSIF v_status = 'paused' THEN
    UPDATE members SET status = 'active' WHERE user_id = auth.uid();
    RETURN true;
  END IF;
  RETURN false;
END;
$$;


--
-- Name: ensure_my_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_membership() RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT public.ensure_my_member_access(); $$;


--
-- Name: FUNCTION ensure_my_membership(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_my_membership() IS 'Self-heal for provisioned clients whose invitation token was lost/consumed: grants (or reactivates a paused) community membership when the caller''s contact has a live client row. Cancelled/suspended memberships are never overridden.';


--
-- Name: ensure_staff_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_staff_profile(p_user_id uuid, p_title text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile profiles%ROWTYPE;
BEGIN
  SELECT * INTO v_profile FROM profiles WHERE user_id = p_user_id;
  IF NOT FOUND OR v_profile.org_id IS NULL THEN RETURN; END IF;
  IF NOT (v_profile.role IN ('ADMIN','MANAGER','EMPLOYEE','SUPER_ADMIN') OR v_profile.is_admin) THEN RETURN; END IF;
  PERFORM set_config('app.allow_profile_link', '1', true);
  UPDATE profiles
     SET title = coalesce(p_title, title),
         staff_active = true
   WHERE user_id = p_user_id;
END;
$$;


--
-- Name: ensure_standing_slots(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_standing_slots(p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff  boolean := has_staff_access();
  v_client uuid    := p_client_id;
  v_org    uuid    := current_org();
  v_target date    := plan_horizon_through();
  v_res    jsonb;
  v_plans  int := 0;
  v_created int := 0;
  r        record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_client IS NULL AND NOT v_staff THEN
    v_client := current_client_id();
    IF v_client IS NULL THEN RETURN jsonb_build_object('plans', 0, 'created', 0); END IF;
  END IF;
  IF v_client IS NOT NULL AND NOT v_staff AND v_client <> coalesce(current_client_id(), '00000000-0000-0000-0000-000000000000'::uuid) THEN
    RAISE EXCEPTION 'not your plans';
  END IF;

  FOR r IN
    SELECT pi.id
      FROM purchase_items pi
      JOIN offerings  o  ON o.id  = pi.offering_id AND o.config_kind = 'recurring'
      JOIN purchases  pu ON pu.id = pi.purchase_id
      JOIN clients    cl ON cl.contact_id = pu.buyer_contact_id AND cl.deleted_at IS NULL
     WHERE pu.deleted_at IS NULL
       AND pi.voided_at IS NULL
       AND pu.status <> 'draft'
       AND pu.org_id = v_org
       AND (v_client IS NULL OR cl.id = v_client)
       AND (pi.plan_ends_on IS NULL OR pi.plan_ends_on >= current_date)
       -- already materialised out to the horizon: nothing to do
       AND coalesce(nullif(pi.config->>'horizon_through', '')::date, DATE '0001-01-01') < v_target
  LOOP
    v_res := _ensure_plan_horizon(r.id, v_target);
    IF coalesce((v_res->>'ok')::boolean, false) THEN
      v_plans   := v_plans + 1;
      v_created := v_created + coalesce((v_res->>'created')::int, 0);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('plans', v_plans, 'created', v_created, 'through', v_target);
END;
$$;


--
-- Name: entity_status_log(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_status_log(p_entity_type text, p_entity_id uuid) RETURNS TABLE(status text, display_name text, is_true_status boolean, is_terminal boolean, detail text, actor_user_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.status, v.display_name, v.is_true_status, v.is_terminal, e.detail, e.actor_user_id, e.created_at
    FROM status_events e
    JOIN status_events_vocab v ON v.entity_type = e.entity_type AND v.code = e.status
   WHERE e.entity_type = p_entity_type AND e.entity_id = p_entity_id
     AND coalesce(has_staff_access() AND e.org_id = current_org(), false)
   ORDER BY e.created_at DESC;
$$;


--
-- Name: expand_horse_blocks(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expand_horse_blocks(p_body text, p_horse_ids uuid[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lines   text[];
  v_out     text[] := '{}';
  v_run     text[] := '{}';
  v_line    text;
  v_i       integer;
  v_n       integer := coalesce(array_length(p_horse_ids, 1), 0);
  v_h       integer;
  v_horse   horses%ROWTYPE;
  v_copy    text;
  v_runline text;
  v_tok     text;
  v_toks    text[];
BEGIN
  IF p_body IS NULL THEN RETURN NULL; END IF;

  -- No horses bound: hand the body back untouched. generate_document's existing
  -- token loop then blanks the HORSE.* tokens exactly as it does today, so the
  -- "no horse named" document is unchanged.
  IF v_n = 0 THEN RETURN p_body; END IF;

  v_lines := string_to_array(p_body, E'\n');

  -- Local helper as an inline block: flush the accumulated run into v_out.
  -- (Written out longhand because plpgsql has no nested functions.)
  FOR v_i IN 1 .. coalesce(array_length(v_lines, 1), 0) LOOP
    v_line := v_lines[v_i];

    IF v_line ~ '\{\{HORSE\.[A-Z0-9_]+\}\}' THEN
      v_run := v_run || v_line;
      CONTINUE;
    END IF;

    -- non-horse line: flush any pending run first
    IF coalesce(array_length(v_run, 1), 0) > 0 THEN
      FOR v_h IN 1 .. v_n LOOP
        SELECT * INTO v_horse FROM horses WHERE id = p_horse_ids[v_h];
        -- caption + blank-line separator ONLY when there is more than one horse,
        -- so the single-horse body is byte-identical to the pre-change output.
        IF v_n > 1 THEN
          -- ''::text, not '': bare '' concatenated to a text[] is read as an
          -- array literal and raises "malformed array literal".
          IF v_h > 1 THEN v_out := v_out || ''::text; END IF;
          v_out := v_out || horse_block_caption(v_horse, v_h);
        END IF;
        FOREACH v_runline IN ARRAY v_run LOOP
          v_copy := v_runline;
          v_toks := ARRAY(SELECT (regexp_matches(v_copy, '\{\{(HORSE\.[A-Z0-9_]+)\}\}', 'g'))[1]);
          FOREACH v_tok IN ARRAY v_toks LOOP
            v_copy := replace(v_copy, '{{' || v_tok || '}}',
              coalesce(horse_field_token_value(v_horse, split_part(v_tok, '.', 2)), ''));
          END LOOP;
          v_out := v_out || v_copy;
        END LOOP;
      END LOOP;
      v_run := '{}';
    END IF;

    v_out := v_out || v_line;
  END LOOP;

  -- trailing run (a body ending on horse lines)
  IF coalesce(array_length(v_run, 1), 0) > 0 THEN
    FOR v_h IN 1 .. v_n LOOP
      SELECT * INTO v_horse FROM horses WHERE id = p_horse_ids[v_h];
      IF v_n > 1 THEN
        IF v_h > 1 THEN v_out := v_out || ''::text; END IF;
        v_out := v_out || horse_block_caption(v_horse, v_h);
      END IF;
      FOREACH v_runline IN ARRAY v_run LOOP
        v_copy := v_runline;
        v_toks := ARRAY(SELECT (regexp_matches(v_copy, '\{\{(HORSE\.[A-Z0-9_]+)\}\}', 'g'))[1]);
        FOREACH v_tok IN ARRAY v_toks LOOP
          v_copy := replace(v_copy, '{{' || v_tok || '}}',
            coalesce(horse_field_token_value(v_horse, split_part(v_tok, '.', 2)), ''));
        END LOOP;
        v_out := v_out || v_copy;
      END LOOP;
    END LOOP;
  END IF;

  RETURN array_to_string(v_out, E'\n');
END;
$$;


--
-- Name: FUNCTION expand_horse_blocks(p_body text, p_horse_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.expand_horse_blocks(p_body text, p_horse_ids uuid[]) IS 'Expand each contiguous run of HORSE.*-token lines into one filled copy per bound horse. One horse in = byte-identical to single-horse substitution.';


--
-- Name: feed_get(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_get(p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := current_org();
  v_shape text;
  v_posts jsonb;
  v_items jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT shape::text INTO v_shape FROM feed_view_pref WHERE user_id = v_uid;
  v_shape := coalesce(v_shape, 'blended');

  SELECT coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_posts FROM (
    SELECT p.id, p.post_type, p.media_url, p.media_kind, p.body, p.source_link,
           p.subject_horse_id, p.visibility, p.publish_at, p.as_company,
           p.author_id,
           ap.author_name,
           ap.author_avatar,
           coalesce(ap.author_is_company, false) AS author_is_company,
           (s.user_id IS NOT NULL) AS seen,
           sh.from_name AS shared_by
      FROM feed_posts p
      LEFT JOIN feed_seen s ON s.post_id = p.id AND s.user_id = v_uid
      LEFT JOIN LATERAL (
        SELECT
          CASE WHEN p.as_company
            THEN coalesce(
                   nullif(btrim((SELECT value_text FROM config_values
                                  WHERE org_id = p.org_id AND namespace = 'BRAND' AND key = 'NAME')), ''),
                   'French Heritage Equestrian')
            ELSE coalesce(nullif(btrim(pr.display_name), ''),
                          nullif(btrim(coalesce(pr.first_name,'') || ' ' || coalesce(pr.last_name,'')), ''),
                          'Member')
          END AS author_name,
          -- a company post shows the brand mark; a personal post keeps the avatar
          CASE WHEN p.as_company THEN NULL ELSE pr.avatar_url END AS author_avatar,
          p.as_company AS author_is_company
          FROM profiles pr
         WHERE pr.user_id = p.author_id
        LIMIT 1
      ) ap ON true
      LEFT JOIN LATERAL (
        SELECT trim(coalesce(pr.first_name,'') || ' ' || coalesce(pr.last_name,'')) AS from_name
          FROM feed_shares fsh
          JOIN contacts pr ON pr.id = (SELECT contact_id FROM profiles WHERE user_id = fsh.from_user_id)
         WHERE fsh.post_id = p.id AND fsh.to_user_id = v_uid
         ORDER BY fsh.created_at DESC LIMIT 1
      ) sh ON true
     WHERE p.org_id = v_org
       AND p.published AND p.publish_at <= now() AND NOT p.pulled_down AND p.scan_state = 'clean'
       AND (p_before IS NULL OR p.publish_at < p_before)
       AND (
         p.visibility IN ('members','both')  -- authed member sees member+both
         OR EXISTS (SELECT 1 FROM feed_shares fsh WHERE fsh.post_id = p.id AND fsh.to_user_id = v_uid)
       )
     ORDER BY p.publish_at DESC
     LIMIT p_limit
  ) t;

  SELECT coalesce(jsonb_agg(row_to_json(a)), '[]'::jsonb) INTO v_items FROM (
    SELECT id, kind, title, body, payload, resolved, publish_at
      FROM feed_account_items
     WHERE user_id = v_uid AND publish_at <= now() AND NOT resolved
     ORDER BY publish_at DESC
  ) a;

  RETURN jsonb_build_object('shape', v_shape, 'posts', v_posts, 'account_items', v_items);
END;
$$;


--
-- Name: feed_mark_seen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_mark_seen(p_post_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO feed_seen (user_id, post_id) VALUES (auth.uid(), p_post_id)
  ON CONFLICT (user_id, post_id) DO NOTHING;
$$;


--
-- Name: feed_moderate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_moderate(p_post_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_action = 'approve' THEN
    UPDATE feed_posts SET scan_state='clean', published=true, pulled_down=false, updated_at=now() WHERE id=p_post_id;
  ELSIF p_action = 'affirm' THEN
    UPDATE feed_posts SET scan_state='blocked', published=false, updated_at=now() WHERE id=p_post_id;
  ELSIF p_action = 'pull_down' THEN
    UPDATE feed_posts SET pulled_down=true, updated_at=now() WHERE id=p_post_id;
  ELSE RAISE EXCEPTION 'unknown moderation action: %', p_action;
  END IF;
END;
$$;


--
-- Name: feed_my_posts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_my_posts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  FROM (
    SELECT p.id, p.post_type, p.media_url, p.media_kind, p.body, p.source_link,
           p.visibility, p.as_company, p.published, p.publish_at, p.pulled_down,
           p.created_at, p.updated_at
      FROM feed_posts p
     WHERE p.author_id = auth.uid()
  ) t;
$$;


--
-- Name: feed_post_create(public.feed_post_type, text, public.feed_media_kind, text, text, uuid, boolean, public.feed_visibility, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_create(p_type public.feed_post_type, p_media_url text, p_media_kind public.feed_media_kind, p_body text DEFAULT NULL::text, p_source_link text DEFAULT NULL::text, p_subject_horse_id uuid DEFAULT NULL::uuid, p_as_company boolean DEFAULT false, p_visibility public.feed_visibility DEFAULT 'members'::public.feed_visibility, p_publish_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_org uuid := current_org(); v_scan feed_scan_state;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  -- only operators may post as the company
  IF p_as_company AND NOT is_admin() THEN RAISE EXCEPTION 'only operators may post as the company'; END IF;
  -- H.9 LISTING ELIGIBILITY: a horse-record-backed post may only be created by
  -- someone entitled to list that horse (owner; lessee only with sublease rights;
  -- staff unrestricted). Enforced server-side, not just in the picker.
  -- Listing integrity: a horse/gear LISTING must be backed by a horse the poster
  -- may list. Without this, a NULL subject skips the eligibility check entirely.
  IF p_type IN ('horse','gear') AND p_subject_horse_id IS NULL THEN
    RAISE EXCEPTION 'a horse or gear listing must reference a horse you are entitled to list';
  END IF;
  IF p_subject_horse_id IS NOT NULL
     AND NOT (can_list_horse(p_subject_horse_id, 'sale')
              OR can_list_horse(p_subject_horse_id, 'lease')) THEN
    RAISE EXCEPTION 'you are not authorized to list this horse';
  END IF;
  -- MODERATION SEAM: run the scan (returns clean at launch; NudeNet/vision later).
  v_scan := feed_scan_media(p_media_url, p_media_kind);
  INSERT INTO feed_posts (org_id, author_id, as_company, post_type, media_url, media_kind,
                          body, source_link, subject_horse_id, visibility, scan_state,
                          published, publish_at)
    VALUES (v_org, auth.uid(), p_as_company, p_type, p_media_url, p_media_kind,
            p_body, p_source_link, p_subject_horse_id, p_visibility, v_scan,
            v_scan = 'clean',                       -- clean posts go live; blocked stay unpublished
            coalesce(p_publish_at, now()))
    RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: feed_post_delete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_delete(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_author uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT author_id INTO v_author FROM feed_posts WHERE id = p_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF NOT coalesce(v_author = auth.uid() OR is_admin(), false) THEN
    RAISE EXCEPTION 'not your post';
  END IF;

  DELETE FROM feed_posts WHERE id = p_id;
  RETURN true;
END;
$$;


--
-- Name: feed_post_update(uuid, text, text, public.feed_visibility); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_post_update(p_id uuid, p_body text DEFAULT NULL::text, p_source_link text DEFAULT NULL::text, p_visibility public.feed_visibility DEFAULT NULL::public.feed_visibility) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_author uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT author_id INTO v_author FROM feed_posts WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'post not found'; END IF;
  IF NOT coalesce(v_author = auth.uid() OR is_admin(), false) THEN
    RAISE EXCEPTION 'not your post';
  END IF;

  UPDATE feed_posts SET
    body        = nullif(btrim(coalesce(p_body, body)), ''),
    source_link = nullif(btrim(coalesce(p_source_link, source_link)), ''),
    visibility  = coalesce(p_visibility, visibility),
    updated_at  = now()
   WHERE id = p_id;
  RETURN true;
END;
$$;


--
-- Name: feed_report_post(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_report_post(p_post_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE feed_posts SET scan_state = 'disputed', reported_reason = p_reason, updated_at = now()
   WHERE id = p_post_id AND author_id = auth.uid() AND scan_state = 'blocked';
END;
$$;


--
-- Name: feed_scan_media(text, public.feed_media_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_scan_media(p_media_url text, p_media_kind public.feed_media_kind) RETURNS public.feed_scan_state
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT 'clean'::feed_scan_state $$;


--
-- Name: feed_seed_welcome(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feed_seed_welcome() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := current_org();
  v_pu  purchases%ROWTYPE;
  v_has boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;

  SELECT EXISTS (SELECT 1 FROM feed_account_items WHERE user_id = v_uid AND kind = 'welcome') INTO v_has;
  IF v_has THEN RETURN; END IF;

  INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
    VALUES (v_org, v_uid, 'welcome', 'Welcome to your feed',
      'This is your home — new horses, gear, and moments from the barn land here. Choose how you''d like to see it; you can change it anytime.',
      jsonb_build_object('chooser', true));

  INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
    VALUES (v_org, v_uid, 'orientation', 'Getting around',
      'Tap the horse to Ask about it, Share a post with another rider, or start a service. Your library, schedule, and account live in the menu under your avatar.',
      '{}'::jsonb);

  -- tailored purchase card from the caller's latest spine purchase
  SELECT pu.* INTO v_pu
    FROM purchases pu
    JOIN profiles p ON p.contact_id = pu.buyer_contact_id
   WHERE p.user_id = v_uid AND pu.deleted_at IS NULL
   ORDER BY pu.created_at DESC LIMIT 1;
  IF FOUND THEN
    INSERT INTO feed_account_items (org_id, user_id, kind, title, body, payload)
      VALUES (v_org, v_uid, 'purchase_card',
        coalesce((SELECT pi.label FROM purchase_items pi WHERE pi.purchase_id = v_pu.id ORDER BY pi.created_at DESC LIMIT 1), 'Your booking'),
        CASE WHEN v_pu.payment_status = 'paid' THEN 'You''re all set. Here''s what to know before your first session.'
             ELSE 'Almost there — complete payment to confirm. Here''s what to know before your first session.' END,
        jsonb_build_object('purchase_id', v_pu.id, 'paid', v_pu.payment_status = 'paid'));
  END IF;
END;
$$;


