--
-- Name: fill_claimant_details(uuid, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_claimant_details(p_contact_id uuid, p_first_name text, p_last_name text, p_phone text, p_address_line1 text DEFAULT NULL::text, p_address_line2 text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  UPDATE contacts
     SET first_name = CASE WHEN nullif(btrim(coalesce(first_name,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_first_name,'')),'') ELSE first_name END,
         last_name  = CASE WHEN nullif(btrim(coalesce(last_name,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_last_name,'')),'') ELSE last_name END,
         phone      = CASE WHEN nullif(btrim(coalesce(phone,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_phone,'')),'') ELSE phone END,
         address_line1 = CASE WHEN nullif(btrim(coalesce(address_line1,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_address_line1,'')),'') ELSE address_line1 END,
         address_line2 = CASE WHEN nullif(btrim(coalesce(address_line2,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_address_line2,'')),'') ELSE address_line2 END,
         city          = CASE WHEN nullif(btrim(coalesce(city,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_city,'')),'') ELSE city END,
         state         = CASE WHEN nullif(btrim(coalesce(state,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_state,'')),'') ELSE state END,
         postal_code   = CASE WHEN nullif(btrim(coalesce(postal_code,'')),'') IS NULL
                           THEN nullif(btrim(coalesce(p_postal_code,'')),'') ELSE postal_code END,
         -- the person told us their own name: it no longer needs confirming, and
         -- the stub an email-only party was created as stops being a stub.
         name_needs_confirmation = CASE
           WHEN nullif(btrim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), '') IS NOT NULL
             OR nullif(btrim(coalesce(p_first_name,'') || ' ' || coalesce(p_last_name,'')), '') IS NOT NULL
           THEN false ELSE name_needs_confirmation END
   WHERE id = p_contact_id;
END;
$$;


--
-- Name: fill_party_fields_from_contacts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_party_fields_from_contacts(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_contract uuid;
  v_doc_template_id uuid;
  r    RECORD;
  v_name text;
  v_addr text;
  v_pair record;
  v_frozen boolean;
  v_prev   text;
BEGIN
  IF NOT coalesce(caller_is_document_party_or_staff(p_document_id), false) THEN
    RAISE EXCEPTION 'not authorized to write party fields on document %', p_document_id;
  END IF;
  SELECT contract_id, org_id, template_id INTO v_contract, v_org, v_doc_template_id
    FROM documents WHERE id = p_document_id;
  IF v_contract IS NULL THEN RETURN; END IF;

  -- Is the name settled? Once anything on this document has been signed, the two
  -- name tokens are the signature's and stop tracking the record.
  SELECT (coalesce(d.workflow_state, '') = 'executed')
      OR EXISTS (SELECT 1 FROM signatures s
                  WHERE s.document_id = p_document_id
                    AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL)
    INTO v_frozen
    FROM documents d WHERE d.id = p_document_id;

  FOR r IN
    SELECT t.*,
           CASE WHEN t.party_role = 'BUYER' AND t.rn > 1 THEN 'COBUYER' ELSE t.party_role END AS ns
      FROM (
        SELECT cp.party_role,
               row_number() OVER (PARTITION BY cp.party_role
                                  ORDER BY cp.signer_order NULLS LAST, cp.id) AS rn,
               c.first_name, c.last_name, c.email, c.phone_display AS phone,
               c.address_composed, c.address_line1, c.address_line2,
               c.city, c.state, c.postal_code, c.is_company
          FROM contract_parties cp
          JOIN contacts c ON c.id = cp.contact_id
         WHERE cp.contract_id = v_contract
      ) t
  LOOP
    v_name := nullif(btrim(coalesce(r.first_name,'') || ' ' || coalesce(r.last_name,'')), '');
    -- prefer a precomposed address; otherwise assemble from parts
    v_addr := coalesce(
      nullif(btrim(coalesce(r.address_composed,'')), ''),
      compose_address(r.address_line1, r.address_line2, r.city, r.state, r.postal_code)
    );

    -- `owned` = the contact record is the source of truth for this token and
    -- overwrites whatever the document holds. FALSE keeps the original blank-only
    -- behaviour, which is what a frozen name and PARTY_TYPE get.
    FOR v_pair IN
      SELECT * FROM (VALUES
        (r.ns || '.FULL_NAME',    v_name,   NOT v_frozen),
        (r.ns || '.PRINTED_NAME', v_name,   NOT v_frozen),
        (r.ns || '.EMAIL',        r.email,  true),
        (r.ns || '.PHONE',        r.phone,  true),
        (r.ns || '.ADDRESS',      v_addr,   true),
         (r.ns || '.PARTY_TYPE',
          CASE WHEN r.ns IN ('LESSEE','LESSOR','SELLER','BUYER','COBUYER')
               THEN CASE WHEN coalesce(r.is_company,false) THEN 'ENTITY' ELSE 'INDIVIDUAL' END END,
          false)
      ) AS t(field_key, val, owned)
      WHERE coalesce(btrim(t.val), '') <> ''
    LOOP
      SELECT nullif(btrim(coalesce(cf.value, '')), '') INTO v_prev
        FROM contract_fields cf
       WHERE cf.document_id = p_document_id AND cf.field_key = v_pair.field_key;

      IF v_pair.owned THEN
        INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                     value_type, is_optional, included, sort_order)
        VALUES (v_org, p_document_id, v_pair.field_key, 'SYSTEM', v_pair.val,
                'text', false, true, 0)
        ON CONFLICT (document_id, field_key) DO UPDATE
          SET value = EXCLUDED.value, updated_at = now()
          WHERE contract_fields.value IS DISTINCT FROM EXCLUDED.value;

        -- D14: an overwrite is an edit and is surfaced like one. A first fill is
        -- not an edit, so v_prev IS NULL is silent.
        IF v_prev IS NOT NULL AND v_prev IS DISTINCT FROM v_pair.val THEN
          PERFORM log_contract_change(
            p_document_id, 'field_value', v_pair.field_key, v_pair.field_key,
            'SYSTEM', v_prev, v_pair.val,
            jsonb_build_object('propagated', true, 'source', 'contact_record'));
        END IF;
      ELSE
        -- Blank-only: a value already on the document is never overwritten. This
        -- is what a signed name keeps, and what PARTY_TYPE has always had.
        INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                     value_type, is_optional, included, sort_order)
        VALUES (v_org, p_document_id, v_pair.field_key, 'SYSTEM', v_pair.val,
                'text', false, true, 0)
        ON CONFLICT (document_id, field_key) DO UPDATE
          SET value = EXCLUDED.value, updated_at = now()
          WHERE coalesce(btrim(contract_fields.value), '') = '';
      END IF;
    END LOOP;
  END LOOP;

  /* ⚠️ NEVER `remerge_contract_from_fields` FROM HERE. It composes from
     `contract_templates.body`, and every clause-composed template stores the
     literal string '(composed from clauses)' there — 23 characters. This
     function's last act was therefore to REPLACE A LEASE'S ENTIRE TEXT with that
     placeholder, and the only reason no contract was ever lost is that all nine
     database callers happen to recompose from the clauses immediately afterwards,
     inside the same transaction. That is a property of nine call sites, not a
     property of this function, and it is not one a tenth caller would know to
     preserve.

     A clause-composed document is now left ALONE here: its `contract_fields` rows
     have been updated, and the caller recomposes. Stale is a recoverable failure
     mode; destroyed is not. Flat templates are unchanged — for them
     `remerge_contract_from_fields` IS the right composer, and it is still called.

     Verified 2026-08-25 — the nine callers, all of which recompose after:
       add_deal_document · add_document_party_by_email · reassign_document_party ·
       regenerate_contract_document · set_document_co_buyer · start_bill_of_sale ·
       start_bill_of_sale_standalone · start_lease_contract_v2 · start_sale_contract
     (`sync_contract_fields_from_defs` only NAMES it, in a comment.) */
  IF NOT EXISTS (
    SELECT 1 FROM contract_clause_defs cd
     WHERE cd.template_key = (SELECT ct.template_key FROM contract_templates ct
                               WHERE ct.id = v_doc_template_id)
  ) THEN
    PERFORM remerge_contract_from_fields(p_document_id);
  END IF;
END;
$$;


--
-- Name: finalize_purchase_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_purchase_payment(p_purchase_id uuid, p_method text) RETURNS TABLE(unique_amount numeric, payment_reference text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur     purchases%ROWTYPE;
  v_total   numeric;
  v_balance numeric;
  v_ref     text;
  v_prefix  text;
  v_contact uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  v_contact := current_contact_id();

  -- The buyer is whichever key the creating path populated: self-serve orders
  -- carry buyer_user_id, provisioned orders carry buyer_contact_id.
  SELECT * INTO v_pur FROM purchases
   WHERE id = p_purchase_id
     AND deleted_at IS NULL
     AND (buyer_user_id = auth.uid() OR buyer_contact_id = v_contact);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase not found';
  END IF;

  SELECT COALESCE(SUM(pi.price_amount * COALESCE(pi.quantity, 1)), 0) INTO v_total
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id;
  IF v_total = 0 THEN v_total := COALESCE(v_pur.amount, 0); END IF;

  -- Balance owed after any partial already paid at provisioning time.
  v_balance := greatest(v_total - COALESCE(v_pur.amount_paid, 0), 0);

  IF v_pur.payment_reference IS NULL THEN
    SELECT cv.value_text INTO v_prefix
      FROM config_values cv
     WHERE cv.org_id = v_pur.org_id AND cv.namespace = 'BRAND' AND cv.key = 'SHORT_NAME';
    v_prefix := COALESCE(NULLIF(regexp_replace(upper(v_prefix), '[^A-Z0-9]', '', 'g'), ''), 'PUR');
    v_ref := v_prefix || '-' || upper(substr(md5(p_purchase_id::text || v_prefix), 1, 6));
  ELSE
    v_ref := v_pur.payment_reference;
  END IF;

  UPDATE purchases p
     SET amount            = v_total,       -- the full order total
         -- the amount the invitee pays now (= the balance); the memo reference
         -- is the true match key, this is the exact expected Zelle amount.
         unique_amount     = v_balance,
         payment_reference = v_ref,
         payment_method    = p_method,
         status            = 'awaiting_payment',
         payment_status    = 'pending',
         -- backfill only: the caller matched as this purchase's buyer contact.
         buyer_user_id     = COALESCE(p.buyer_user_id,
                                      CASE WHEN v_contact IS NOT NULL
                                            AND p.buyer_contact_id = v_contact
                                           THEN auth.uid() END)
         -- amount_paid intentionally preserved
   WHERE p.id = p_purchase_id;

  RETURN QUERY SELECT v_balance, v_ref;
END;
$$;


--
-- Name: FUNCTION finalize_purchase_payment(p_purchase_id uuid, p_method text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_purchase_payment(p_purchase_id uuid, p_method text) IS 'Assigns the Zelle matching keys (unique_amount = balance owed, brand-prefixed payment_reference) and moves the purchase to awaiting_payment. PAYLOCK 2026-08-13: recognises the buyer by buyer_user_id OR buyer_contact_id, so a staff-provisioned buyer (contact key only) can pay.';


--
-- Name: find_claimable_contract(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_claimable_contract(p_email text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_row   record;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF v_email = '' THEN RETURN jsonb_build_object('found', false); END IF;

  SELECT d.id AS document_id, d.org_id, d.title, c.id AS contact_id
    INTO v_row
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    JOIN contacts  c ON c.id = dp.contact_id  AND c.deleted_at IS NULL
   WHERE lower(c.email) = v_email
     -- "and they dont have an account yet" — the whole premise of the flow
     AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id)
     -- a contract that is over is not claimable
     AND d.status NOT IN ('VOID', 'EXECUTED')
     AND d.voided_at IS NULL AND d.terminated_at IS NULL AND d.archived_at IS NULL
     -- SENDGUARD, again: somebody who already signed has nothing to claim
     AND NOT EXISTS (
       SELECT 1 FROM signatures s
        WHERE s.document_id = d.id AND s.signer_contact_id = c.id AND s.deleted_at IS NULL)
   ORDER BY d.created_at DESC
   LIMIT 1;

  IF v_row.document_id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;

  RETURN jsonb_build_object(
    'found', true, 'document_id', v_row.document_id, 'org_id', v_row.org_id,
    'title', v_row.title, 'contact_id', v_row.contact_id);
END;
$$;


--
-- Name: FUNCTION find_claimable_contract(p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.find_claimable_contract(p_email text) IS 'ONBOARD §1b: the one contract a /sign "deal" visitor may claim — a document party whose contact email matches, who has NO account yet, on a contract that is still live, who has not already signed. Returns found=false for every other case with no reason attached, because the caller is answering an unauthenticated stranger.';


--
-- Name: fire_due_task_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fire_due_task_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_due timestamptz; v_fired int := 0; v_interval interval;
BEGIN
  FOR r IN
    SELECT tr.*, t.title, t.due_at, t.org_id AS task_org, t.status
      FROM task_reminders tr
      JOIN tasks t ON t.id = tr.task_id
     WHERE t.deleted_at IS NULL
       AND t.status IN ('new','in_progress')
       AND (tr.via_dashboard OR tr.via_modal OR tr.via_email)
  LOOP
    v_interval := (r.value || ' ' || r.unit)::interval;
    -- when this reminder is due
    IF r.offset_kind = 'before_due' THEN
      IF r.due_at IS NULL THEN CONTINUE; END IF;
      v_due := r.due_at - v_interval;
    ELSE   -- after_create: base is the last fire, else the reminder's creation
      v_due := coalesce(r.fired_at, r.created_at) + v_interval;
    END IF;

    -- one-time already fired → skip
    IF NOT r.recurring AND r.fired_at IS NOT NULL THEN CONTINUE; END IF;
    IF v_due > now() THEN CONTINUE; END IF;

    -- fire the configured surfaces to the recipient
    IF r.user_id IS NOT NULL AND (r.via_dashboard OR r.via_modal) THEN
      INSERT INTO alerts (org_id, user_id, title, body, link, severity, source, task_id, category)
      VALUES (r.task_org, r.user_id, 'Reminder: ' || r.title, NULL, NULL,
              CASE WHEN r.via_modal THEN 'priority' ELSE 'standard' END,
              'task', r.task_id, 'reminder');
    END IF;
    IF r.via_email AND r.user_id IS NOT NULL THEN
      INSERT INTO notifications (org_id, user_id, kind, title, body, category)
      VALUES (r.task_org, r.user_id, 'task_reminder', 'Reminder: ' || r.title, NULL, 'reminder');
    END IF;

    UPDATE task_reminders SET fired_at = now() WHERE id = r.id;
    v_fired := v_fired + 1;
  END LOOP;
  RETURN v_fired;
END
$$;


--
-- Name: flush_held_executed_document_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flush_held_executed_document_emails(p_hold_minutes integer DEFAULT 30) RETURNS TABLE(contact_id uuid, documents integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r     RECORD;
  v_out jsonb;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- A held document whose SET IS COMPLETE but which never mailed (a failed POST).
  -- NOTHING partial is ever flushed: a doc whose set is still open stays held until
  -- its last sibling executes. p_hold_minutes only debounces the retry of a
  -- complete-but-unsent set, it never releases a partial one.
  FOR r IN
    SELECT DISTINCT d.contact_id AS cid
      FROM documents d
     WHERE d.delivery_held_at IS NOT NULL
       AND d.executed_email_sent_at IS NULL
       AND d.deleted_at IS NULL
       AND d.status = 'EXECUTED'
       AND d.contact_id IS NOT NULL
       AND d.delivery_set_id IS NOT NULL
       AND delivery_set_complete(d.delivery_set_id)
       AND d.delivery_held_at < now() - make_interval(mins => greatest(p_hold_minutes, 1))
  LOOP
    v_out := deliver_executed_document_set(r.cid, NULL);
    IF coalesce((v_out->>'sent')::boolean, false) THEN
      contact_id := r.cid;
      documents  := coalesce((v_out->>'documents')::int, 0);
      RETURN NEXT;
    END IF;
  END LOOP;

  -- A held anchor-less document (no contact AND no set, or a complete set with no
  -- contact) still needs a home. Sent on its own, since there is no set to batch.
  FOR r IN
    SELECT d.id AS did
      FROM documents d
     WHERE d.delivery_held_at IS NOT NULL
       AND d.executed_email_sent_at IS NULL
       AND d.deleted_at IS NULL
       AND d.status = 'EXECUTED'
       AND d.contact_id IS NULL
       AND (d.delivery_set_id IS NULL OR delivery_set_complete(d.delivery_set_id))
       AND d.delivery_held_at < now() - make_interval(mins => greatest(p_hold_minutes, 1))
  LOOP
    v_out := send_executed_document_email(r.did);
    IF coalesce((v_out->>'sent')::boolean, false) THEN
      UPDATE documents SET delivery_held_at = NULL WHERE id = r.did;
      contact_id := NULL;
      documents  := 1;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION flush_held_executed_document_emails(p_hold_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.flush_held_executed_document_emails(p_hold_minutes integer) IS 'ONBOARD §4 backstop: deliver document sets that were held for a signature that never came. Abandoning a signing run must not cost someone the copies of what they DID sign.';


--
-- Name: fmt_money(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fmt_money(v numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE WHEN v IS NULL THEN '' ELSE '$' || to_char(v, 'FM999,999,990.00') END
$_$;


--
-- Name: fmt_time12(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fmt_time12(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE WHEN t ~ '^\d{1,2}:\d{2}$'
    THEN to_char(to_timestamp(t, 'HH24:MI'), 'FMHH12:MI AM') ELSE coalesce(t,'') END;
$_$;


--
-- Name: form_version_at(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.form_version_at(p_form_key text, p_version integer) RETURNS TABLE(version integer, parent_version integer, title text, audience text, purpose text, schema jsonb, is_current boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version, v.parent_version, v.title, v.audience, v.purpose, v.schema,
         v.version = fd.version as is_current, v.created_at
    from form_definition_versions v
    join form_definitions fd on fd.form_key = v.form_key
   where v.form_key = p_form_key and v.version = p_version
     and has_staff_access()
$$;


--
-- Name: FUNCTION form_version_at(p_form_key text, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.form_version_at(p_form_key text, p_version integer) IS 'TASK-VERSIONSPINE: one retained form version, in full, for opening it in the editor.';


--
-- Name: form_version_list(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.form_version_list(p_form_key text) RETURNS TABLE(version integer, parent_version integer, is_current boolean, edited_by uuid, edited_by_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.version,
         v.parent_version,
         v.version = fd.version as is_current,
         v.edited_by,
         coalesce(nullif(btrim(coalesce(p.display_name, '')), ''),
                  nullif(btrim(coalesce(p.first_name,'') || ' ' || coalesce(p.last_name,'')), ''),
                  p.email) as edited_by_name,
         v.created_at
    from form_definition_versions v
    join form_definitions fd on fd.form_key = v.form_key
    left join profiles p on p.user_id = v.edited_by
   where v.form_key = p_form_key
     and has_staff_access()
   order by v.version desc
$$;


--
-- Name: FUNCTION form_version_list(p_form_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.form_version_list(p_form_key text) IS 'TASK-VERSIONSPINE: a form''s version list — v8 · from v4 · who · when. Named _list rather than form_definition_versions() so the function is never confused with the table it reads.';


--
-- Name: format_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.format_phone(p_raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_digits text;
BEGIN
  IF p_raw IS NULL OR trim(p_raw) = '' THEN RETURN NULL; END IF;
  v_digits := regexp_replace(p_raw, '\D', '', 'g');

  -- 11 digits starting with the US country code: drop the 1.
  IF length(v_digits) = 11 AND left(v_digits, 1) = '1' THEN
    v_digits := substr(v_digits, 2);
  END IF;

  IF length(v_digits) = 10 THEN
    RETURN '(' || substr(v_digits, 1, 3) || ') '
                || substr(v_digits, 4, 3) || '-'
                || substr(v_digits, 7, 4);
  END IF;

  RETURN trim(p_raw);   -- not a NANP number — leave it as the person wrote it
END
$$;


--
-- Name: FUNCTION format_phone(p_raw text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.format_phone(p_raw text) IS 'Normalises a NANP number to (XXX) XXX-XXXX, tolerating any input shape and stripping a leading US country code. Anything it does not recognise as a 10-digit number is returned trimmed and otherwise UNCHANGED — an international or partial number must not be mangled into a plausible-looking wrong one.';


--
-- Name: freeze_signed_template_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_signed_template_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'EXECUTED' AND coalesce(OLD.status,'') <> 'EXECUTED'
     AND NEW.signed_template_version IS NULL THEN
    SELECT ct.version INTO NEW.signed_template_version
      FROM contract_templates ct WHERE ct.id = NEW.template_id;
  END IF;
  RETURN NEW;
END
$$;


