--
-- Name: generate_document(uuid, text, uuid, uuid, jsonb, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_document(p_contact_id uuid, p_template_key text, p_contract_id uuid, p_horse_id uuid, p_parties jsonb, p_service_type text, p_horse_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(document_id uuid, merged_body text)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
  v_tmpl    contract_templates%ROWTYPE;
  v_org_id  uuid;
  v_ctr     contracts%ROWTYPE;
  v_has_ctr boolean := false;
  v_horse   horses%ROWTYPE;
  v_horse_ids uuid[];        -- the ordered multi-horse set (Stage: multi-horse)
  v_cfg     business_config%ROWTYPE;
  v_breed   text := '';
  v_color   text := '';
  v_home_loc text := '';
  v_curr_loc text := '';
  v_doc_id  uuid;
  v_doc_code text;
  v_body    text;
  v_val     text;
  v_org     text;
  v_rate    numeric;
  v_dir     jsonb := '{}'::jsonb;
  r         record;
  m         record;
  v_fn text; v_ph text; v_em text; v_ad text; v_ti text; v_re text; v_db text;
  v_ec1n text; v_ec1r text; v_ec1p text; v_ec2n text; v_ec2r text; v_ec2p text;
  v_ry text; v_jx text; v_rb text; v_jl text;
  v_c_phone text; v_c_email text; v_c_url text;
  v_has_minor boolean := false;
  v_is_jumper boolean := false;
  v_svc text;
BEGIN
  SELECT * INTO v_tmpl FROM contract_templates
    WHERE template_key = p_template_key AND active AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown or inactive contract template: %', p_template_key;
  END IF;
  IF v_tmpl.body IS NULL THEN
    RAISE EXCEPTION 'template % has no body loaded (no source document yet)', p_template_key;
  END IF;

  -- org from the CONTACT (was: the engagement). Explicit, not RLS-accidental.
  SELECT org_id INTO v_org_id FROM contacts WHERE id = p_contact_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'unknown contact: %', p_contact_id;
  END IF;

  IF p_contract_id IS NOT NULL THEN
    SELECT * INTO v_ctr FROM contracts WHERE id = p_contract_id AND deleted_at IS NULL;
    v_has_ctr := FOUND;
  END IF;

  v_svc := coalesce(p_service_type, v_ctr.segment);

  IF p_horse_id IS NOT NULL THEN
    SELECT * INTO v_horse FROM horses WHERE id = p_horse_id;
    SELECT display_name INTO v_breed FROM horse_breeds WHERE code = v_horse.breed;
    SELECT display_name INTO v_color FROM horse_colors WHERE code = v_horse.color;
    v_home_loc := coalesce(horse_current_location_label(v_horse.id), '');
    v_curr_loc := coalesce(horse_current_location_label(v_horse.id), '');
  END IF;

  SELECT * INTO v_cfg FROM business_config WHERE org_id = v_org_id;
  SELECT value_text INTO v_c_phone FROM config_values WHERE org_id = v_org_id AND namespace = 'CONTACT' AND key = 'PHONE';
  SELECT value_text INTO v_c_email FROM config_values WHERE org_id = v_org_id AND namespace = 'CONTACT' AND key = 'EMAIL';
  SELECT value_text INTO v_c_url   FROM config_values WHERE org_id = v_org_id AND namespace = 'CONTACT' AND key = 'URL';

  -- DIRECTIONAL TERMINOLOGY ÃÂ¢ÃÂÃÂ from the contract now (deal_side/retained_by in
  -- contract.terms), was engagement_stages. No contract ÃÂ¢ÃÂÃÂ no overrides.
  IF v_has_ctr THEN
    SELECT COALESCE(tv.token_overrides, '{}'::jsonb) INTO v_dir
      FROM template_variants tv
      WHERE tv.template_key = p_template_key
        AND tv.retained_by  = (v_ctr.terms ->> 'retained_by')
        AND tv.deal_side    = (v_ctr.terms ->> 'deal_side')
        AND tv.active
      LIMIT 1;
  END IF;
  v_dir := COALESCE(v_dir, '{}'::jsonb);

  INSERT INTO documents (org_id, contact_id, contract_id, horse_id, template_id, title, status)
    VALUES (v_org_id, p_contact_id, p_contract_id, p_horse_id, v_tmpl.id, v_tmpl.title, 'DRAFT')
    RETURNING id, display_code INTO v_doc_id, v_doc_code;

  -- MULTI-HORSE: bind the full ordered set NOW, before the body is composed,
  -- so the expander below sees every horse on this one pass. One id (or
  -- none) changes nothing — the single-horse path is untouched.
  IF coalesce(array_length(p_horse_ids, 1), 0) > 1 THEN
    DELETE FROM document_horses WHERE document_id = v_doc_id;
    INSERT INTO document_horses (org_id, document_id, horse_id, position)
      SELECT v_org_id, v_doc_id, p_horse_ids[i], i
        FROM generate_subscripts(p_horse_ids, 1) AS i
      ON CONFLICT (document_id, horse_id) DO UPDATE SET position = EXCLUDED.position;
  END IF;

  -- seed the document's parties (was engagement_parties). Person + SIG tokens and
  -- signing authz all resolve from document_parties keyed by this document.
  IF p_parties IS NOT NULL THEN
    INSERT INTO document_parties (document_id, contact_id, party_role, relationship, title, is_signer, signer_order, org_id)
    SELECT v_doc_id,
           (e ->> 'contact_id')::uuid,
           e ->> 'role',
           e ->> 'relationship',
           e ->> 'title',
           COALESCE((e ->> 'is_signer')::boolean, false),
           (e ->> 'signer_order')::int,
           v_org_id
      FROM jsonb_array_elements(p_parties) e
    ON CONFLICT (document_id, contact_id, party_role) DO NOTHING;
  END IF;

  v_body := v_tmpl.body;

  -- MULTI-HORSE: when this document names more than one horse, expand every
  -- contiguous run of HORSE.*-token lines into one filled copy per horse
  -- BEFORE the token loop. One horse (or none) skips this entirely, so the
  -- single-horse body is byte-for-byte what it has always been.
  v_horse_ids := document_horse_ids(v_doc_id);
  IF coalesce(array_length(v_horse_ids, 1), 0) > 1 THEN
    v_body := expand_horse_blocks(v_body, v_horse_ids);
  END IF;

  -- MINORBLOCK 2026-08-24 — A PARTICIPANT WHO IS THE CLIENT IS NOT A MINOR.
  -- Both generators add PARTICIPANT as coalesce(minor, the person themselves) so
  -- the template renders the same on either path; testing only for the ROLE
  -- therefore matched every adult, and the "MINOR PARTICIPANT" block printed on
  -- their release with their own name and date of birth.
  v_has_minor := EXISTS (
    SELECT 1 FROM document_parties dp
     WHERE dp.document_id = v_doc_id
       AND dp.party_role = 'PARTICIPANT'
       AND dp.contact_id IS DISTINCT FROM (
         SELECT d2.contact_id FROM documents d2 WHERE d2.id = v_doc_id));
  v_is_jumper := v_svc = 'JUMPER_TRAINING';
  FOR m IN
    SELECT DISTINCT (regexp_matches(v_body, '<!-- CUT-START: ([A-Z_]+)', 'g'))[1] AS name
  LOOP
    IF m.name IN ('EVALUATION_PERIOD','PARTIAL_LEASE','INSURANCE',
                  'MORTALITY_INSURANCE','MAJOR_MEDICAL_INSURANCE',
                  'LOSS_OF_USE_INSURANCE','COMPETITION') THEN
      CONTINUE;
    END IF;
    IF (m.name LIKE 'MINOR%' AND v_has_minor)
       OR (m.name LIKE 'JUMPER%' AND v_is_jumper) THEN
      v_body := regexp_replace(
        v_body, '[ \t]*<!-- CUT-(START|END): ' || m.name || '[^>]*-->\n?', '', 'g');
    ELSE
      v_body := regexp_replace(
        v_body,
        '\n?[ \t]*<!-- CUT-START: ' || m.name || '[^>]*-->.*<!-- CUT-END: ' || m.name || ' -->\n?',
        E'\n', 'g');
    END IF;
  END LOOP;

  FOR r IN
    SELECT namespace, field, token FROM template_tokens
    WHERE template_id = v_tmpl.id AND kind <> 'signature'
  LOOP
    v_val := '';

    IF r.namespace = 'HORSE' THEN
      v_val := CASE r.field
        WHEN 'REGISTERED_NAME'     THEN v_horse.registered_name
        WHEN 'BARN_NAME'           THEN v_horse.nickname
        WHEN 'BREED'               THEN v_breed
        WHEN 'COLOR'               THEN v_color
        WHEN 'SEX'                 THEN v_horse.sex
        WHEN 'AGE_DOB'             THEN to_char(v_horse.date_of_birth, 'FMMonth FMDD, YYYY')
        WHEN 'HEIGHT'              THEN v_horse.height
        WHEN 'REGISTRATION_NUMBER' THEN v_horse.registration_number
        WHEN 'MICROCHIP'           THEN v_horse.microchip_id
        WHEN 'CURRENT_LOCATION'    THEN coalesce(nullif(v_curr_loc,''), v_horse.current_location)
        WHEN 'HOME_LOCATION'       THEN v_home_loc
        WHEN 'VET_NAME'            THEN horse_provider_value(v_horse.id, 'VET', 'NAME')
        WHEN 'VET_PHONE'           THEN horse_provider_value(v_horse.id, 'VET', 'PHONE')
        WHEN 'FARRIER_NAME'        THEN horse_provider_value(v_horse.id, 'FARRIER', 'NAME')
        WHEN 'FARRIER_PHONE'       THEN horse_provider_value(v_horse.id, 'FARRIER', 'PHONE')
        WHEN 'FAIR_MARKET_VALUE'   THEN fmt_money(v_horse.fair_market_value)
        WHEN 'MARKINGS'            THEN v_horse.markings
        WHEN 'PASSPORT_NUMBER'     THEN v_horse.passport_number
        WHEN 'VET_BUSINESS'        THEN horse_provider_value(v_horse.id, 'VET', 'BUSINESS')
        WHEN 'VET_ADDRESS'         THEN horse_provider_value(v_horse.id, 'VET', 'ADDRESS')
        WHEN 'MEDICATION_NAME'         THEN horse_medications_prose(v_horse.id, 'MEDICATION')
        WHEN 'MEDICATION_DOSAGE'       THEN horse_medication_component(v_horse.id, 'DOSAGE')
        WHEN 'MEDICATION_INSTRUCTIONS' THEN horse_medication_component(v_horse.id, 'INSTRUCTIONS')
        WHEN 'MEDICATION_ADDITIONAL'   THEN horse_medication_component(v_horse.id, 'ADDITIONAL')
        WHEN 'KNOWN_CONDITIONS'        THEN horse_list_prose(v_horse.known_conditions_list, 'condition')
        WHEN 'EUTHANASIA_A' THEN CASE WHEN v_horse.euthanasia_authorization = 'A' THEN 'X' ELSE ' ' END
        WHEN 'EUTHANASIA_B' THEN CASE WHEN v_horse.euthanasia_authorization = 'B' THEN 'X' ELSE ' ' END
        ELSE '' END;

    ELSIF r.namespace = 'ENG' THEN
      -- ENG.ID/SERVICE_TYPE/START_DATE are used by ZERO live templates; map what
      -- exists onto the contract, blank otherwise.
      v_val := CASE r.field
        WHEN 'ID'           THEN v_ctr.display_code
        WHEN 'SERVICE_TYPE' THEN v_svc
        WHEN 'START_DATE'   THEN to_char(v_ctr.effective_date, 'FMMonth FMDD, YYYY')
        ELSE '' END;

    ELSIF r.namespace = 'DOC' THEN
      v_val := CASE r.field
        WHEN 'UUID'           THEN v_doc_id::text
        WHEN 'ID'             THEN v_doc_code
        WHEN 'GENERATED_DATE' THEN to_char(now(), 'FMMonth FMDD, YYYY')
        WHEN 'EFFECTIVE_DATE' THEN to_char(coalesce(
                                 (SELECT d2.effective_date FROM documents d2 WHERE d2.id = v_doc_id),
                                 (SELECT d2.created_at::date FROM documents d2 WHERE d2.id = v_doc_id),
                                 now()::date), 'FMMonth FMDD, YYYY')
        ELSE '' END;

    ELSIF r.namespace = 'ORD' THEN
      IF r.field = 'SERVICE_SELECTION' THEN
        SELECT pi.label INTO v_val FROM purchase_items pi
          JOIN purchases pu ON pu.id = pi.purchase_id
          WHERE pu.contract_id = p_contract_id
          ORDER BY pi.created_at DESC LIMIT 1;
      ELSE
        v_val := CASE r.field
          WHEN 'UUID' THEN v_doc_id::text
          WHEN 'ID'   THEN v_doc_code
          ELSE '' END;
      END IF;

    ELSIF r.namespace = 'REQ' THEN
      v_val := '';

    ELSIF r.namespace = 'DIR' THEN
      v_val := v_dir ->> r.field;

    ELSIF r.namespace IN ('ORG', 'FHE') THEN
      v_org := CASE r.field
        WHEN 'LEGAL_NAME'       THEN v_cfg.legal_entity_name
        WHEN 'SIGNATORY_NAME'   THEN v_cfg.signatory_name
        WHEN 'SIGNATORY_TITLE'  THEN v_cfg.signatory_title
        WHEN 'ADDRESS'          THEN v_cfg.business_address
        WHEN 'BRAND_NAME'       THEN v_cfg.legal_entity_name
        WHEN 'ENTITY_FORMATION' THEN v_cfg.entity_formation
        WHEN 'REGISTERED_AGENT' THEN v_cfg.registered_agent
        WHEN 'CANCELLATION_FEE' THEN fmt_money(v_cfg.cancellation_fee)
        WHEN 'LATE_FEE'         THEN fmt_money(v_cfg.late_fee)
        WHEN 'NO_SHOW_FEE'      THEN fmt_money(v_cfg.no_show_fee)
        WHEN 'PHONE'            THEN v_c_phone
        WHEN 'EMAIL'            THEN v_c_email
        WHEN 'URL'              THEN v_c_url
        ELSE NULL END;
      IF v_org IS NULL THEN
        SELECT coalesce(cv.value_text, cv.value_num::text, cv.value_json #>> '{}')
          INTO v_org FROM config_values cv
          WHERE cv.org_id = v_org_id AND cv.namespace = 'ORG' AND cv.key = r.field;
      END IF;
      v_val := v_org;

    ELSIF r.namespace = 'TXN' THEN
      -- commission from config; deal money is filled by remerge from contract_fields.
      IF r.field = 'COMMISSION_RATE' THEN
        v_rate := CASE
          WHEN v_svc ILIKE '%SALE%'  THEN v_cfg.commission_sale_rate
          WHEN v_svc ILIKE '%LEASE%' THEN v_cfg.commission_lease_rate
          ELSE v_cfg.commission_purchase_rate END;
        v_val := CASE WHEN v_rate IS NULL THEN ''
                      ELSE rtrim(rtrim(to_char(v_rate, 'FM999990.00'), '0'), '.') || '%' END;
      ELSIF r.field = 'COMMISSION_MIN' THEN
        v_val := fmt_money(v_cfg.commission_min);
      ELSE
        v_val := '';
      END IF;

    ELSE
      v_fn := NULL; v_ph := NULL; v_em := NULL; v_ad := NULL; v_ti := NULL; v_re := NULL; v_db := NULL;
      v_ec1n := NULL; v_ec1r := NULL; v_ec1p := NULL; v_ec2n := NULL; v_ec2r := NULL; v_ec2p := NULL;
      v_ry := NULL; v_jx := NULL; v_rb := NULL; v_jl := NULL;
      SELECT NULLIF(trim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')), ''),
             c.phone, c.email, c.address_composed, dp.title, dp.relationship,
             CASE WHEN c.date_of_birth IS NULL THEN NULL
                  ELSE to_char(c.date_of_birth, 'FMMonth FMDD, YYYY') END,
             c.emergency_contact_1_name, c.emergency_contact_1_relationship, c.emergency_contact_1_phone,
             c.emergency_contact_2_name, c.emergency_contact_2_relationship, c.emergency_contact_2_phone,
             c.riding_experience_years, c.jump_experience, c.riding_background, c.jump_limitations
        INTO v_fn, v_ph, v_em, v_ad, v_ti, v_re, v_db,
             v_ec1n, v_ec1r, v_ec1p, v_ec2n, v_ec2r, v_ec2p,
             v_ry, v_jx, v_rb, v_jl
        FROM document_parties dp
        JOIN contacts c ON c.id = dp.contact_id
        WHERE dp.document_id = v_doc_id AND dp.party_role = r.namespace
        ORDER BY dp.signer_order NULLS LAST
        LIMIT 1;
      v_val := CASE r.field
        WHEN 'FULL_NAME'    THEN v_fn
        WHEN 'PRINTED_NAME' THEN v_fn
        WHEN 'PHONE'        THEN v_ph
        WHEN 'EMAIL'        THEN v_em
        WHEN 'ADDRESS'      THEN v_ad
        WHEN 'TITLE'        THEN v_ti
        WHEN 'RELATIONSHIP' THEN v_re
        WHEN 'DOB'          THEN v_db
        WHEN 'EMERGENCY_CONTACT_1_NAME'         THEN v_ec1n
        WHEN 'EMERGENCY_CONTACT_1_RELATIONSHIP' THEN v_ec1r
        WHEN 'EMERGENCY_CONTACT_1_PHONE'        THEN v_ec1p
        WHEN 'EMERGENCY_CONTACT_2_NAME'         THEN v_ec2n
        WHEN 'EMERGENCY_CONTACT_2_RELATIONSHIP' THEN v_ec2r
        WHEN 'EMERGENCY_CONTACT_2_PHONE'        THEN v_ec2p
        WHEN 'RIDING_EXPERIENCE_YEARS'          THEN v_ry
        WHEN 'JUMP_EXPERIENCE'                  THEN v_jx
        WHEN 'RIDING_BACKGROUND'                THEN v_rb
        WHEN 'JUMP_LIMITATIONS'                 THEN v_jl
        WHEN 'HORSE_CAPACITY' THEN CASE
          WHEN v_horse.current_owner_contact_id IS NULL THEN 'owns, leases, manages, or otherwise has authority over'
          WHEN (SELECT dp2.contact_id FROM document_parties dp2 WHERE dp2.document_id = v_doc_id AND dp2.party_role = r.namespace ORDER BY dp2.signer_order NULLS LAST LIMIT 1) = v_horse.current_owner_contact_id THEN 'owns'
          WHEN (SELECT dp2.contact_id FROM document_parties dp2 WHERE dp2.document_id = v_doc_id AND dp2.party_role = r.namespace ORDER BY dp2.signer_order NULLS LAST LIMIT 1) = v_horse.lessee_contact_id THEN 'leases'
          ELSE 'is an authorized agent of' END
        ELSE '' END;
    END IF;

    v_body := replace(v_body, r.token, COALESCE(v_val, ''));
  END LOOP;

  UPDATE documents SET merged_body = v_body WHERE id = v_doc_id;

  document_id := v_doc_id;
  merged_body := v_body;
  RETURN NEXT;
END;
$$;


--
-- Name: generate_fulfillment_units(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_fulfillment_units(p_purchase_item_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_it   purchase_items%ROWTYPE;
  v_o    offerings%ROWTYPE;
  v_org  uuid;
  v_kind text;
  v_n    int := 0;
  i      int;
  v_qty  int;
  v_ms   date;
BEGIN
  SELECT * INTO v_it FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RETURN 0; END IF;
  SELECT * INTO v_o FROM offerings WHERE id = v_it.offering_id;
  IF NOT FOUND OR v_o.config_kind IS NULL THEN RETURN 0; END IF;
  SELECT org_id INTO v_org FROM purchases WHERE id = v_it.purchase_id;
  v_qty := greatest(coalesce(v_it.quantity, 1), 1);

  IF v_o.config_kind = 'inquire' THEN
    RETURN 0;                                   -- inquire → no units, by design
  ELSIF v_o.config_kind = 'scheduled' THEN
    v_kind := 'session';
    FOR i IN 1 .. (coalesce(v_o.unit_count, 1) * v_qty) LOOP
      INSERT INTO fulfillment_units (org_id, purchase_id, purchase_item_id, unit_kind, seq, label)
      VALUES (v_org, v_it.purchase_id, v_it.id, v_kind, i,
              coalesce(v_it.label, v_o.name) || ' · session ' || i)
      ON CONFLICT DO NOTHING;
      v_n := v_n + 1;
    END LOOP;
  ELSIF v_o.config_kind = 'recurring' THEN
    -- period units: seed the first period; later periods roll as they are billed.
    -- CREDITALIGN: the period is the CALENDAR MONTH, so this window and the
    -- lesson_credits allotment that funds bookings inside it end on the same day.
    v_kind := 'period';
    v_ms := date_trunc('month', current_date)::date;
    INSERT INTO fulfillment_units (org_id, purchase_id, purchase_item_id, unit_kind, seq, label,
                                   period_start, period_end)
    VALUES (v_org, v_it.purchase_id, v_it.id, v_kind, 1,
            coalesce(v_it.label, v_o.name) || ' · period 1',
            v_ms, (v_ms + interval '1 month - 1 day')::date)
    ON CONFLICT DO NOTHING;
    v_n := 1;
  ELSIF v_o.config_kind IN ('intake_finder','intake_evaluation') THEN
    v_kind := 'milestone';
    FOR i IN 1 .. v_qty LOOP
      INSERT INTO fulfillment_units (org_id, purchase_id, purchase_item_id, unit_kind, seq, label)
      VALUES (v_org, v_it.purchase_id, v_it.id, v_kind, i, coalesce(v_it.label, v_o.name))
      ON CONFLICT DO NOTHING;
      v_n := v_n + 1;
    END LOOP;
  ELSIF v_o.config_kind = 'document_transaction' THEN
    v_kind := 'execution';
    INSERT INTO fulfillment_units (org_id, purchase_id, purchase_item_id, unit_kind, seq, label)
    VALUES (v_org, v_it.purchase_id, v_it.id, v_kind, 1, coalesce(v_it.label, v_o.name))
    ON CONFLICT DO NOTHING;
    v_n := 1;
  END IF;

  RETURN v_n;
END;
$$;


--
-- Name: generate_lease_availability(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_lease_availability(p_horse_id uuid, p_weeks integer DEFAULT 4) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_h horses%ROWTYPE; v_doc uuid; v_contract uuid;
  v_used text[]; v_unav text[];
  d date; v_dow text; v_open time; v_close time; v_closed boolean;
  v_made int := 0; v_start timestamptz; v_end timestamptz;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_h FROM horses WHERE id = p_horse_id AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org'; END IF;

  -- D10: the live lease family. 'HORSE_LEASE' is the archived original and never
  -- backs a document, so filtering on it made this function unreachable.
  SELECT dc.id, dc.contract_id INTO v_doc, v_contract
    FROM documents dc
    JOIN contract_templates t ON t.id = dc.template_id
    WHERE dc.horse_id = p_horse_id
      AND t.template_key IN ('HORSE_LEASE_V3')
      AND dc.status = 'EXECUTED' AND dc.deleted_at IS NULL
    ORDER BY dc.effective_date DESC NULLS LAST, dc.created_at DESC LIMIT 1;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'no executed lease contract for this horse'; END IF;

  -- union: the primary lessee's days + every participant's days
  SELECT array_agg(DISTINCT day) INTO v_used FROM (
    SELECT unnest(string_to_array(regexp_replace(coalesce(
             (SELECT value FROM contract_fields WHERE document_id=v_doc AND field_key='TXN.DAYS_USED'),''), '\s','','g'), ',')) AS day
    UNION
    SELECT unnest(string_to_array(regexp_replace(coalesce(days_used,''), '\s','','g'), ',')) AS day
      FROM lease_participants WHERE document_id = v_doc
  ) x WHERE day <> '';
  SELECT string_to_array(regexp_replace(coalesce(value,''), '\s','','g'), ',')
    INTO v_unav FROM contract_fields WHERE document_id = v_doc AND field_key = 'TXN.DAYS_UNAVAILABLE';
  v_used := coalesce(v_used,'{}'); v_unav := coalesce(v_unav,'{}');
  IF array_length(array_remove(v_used,''),1) IS NULL THEN
    RAISE EXCEPTION 'the lease has no "days used" set (primary or participants) — fill it first';
  END IF;

  -- compute any blank participant usage % from the day shares
  PERFORM compute_lease_usage(v_doc);

  FOR d IN SELECT generate_series(current_date, current_date + (p_weeks*7), '1 day')::date LOOP
    CONTINUE WHEN v_h.lease_start IS NOT NULL AND d < v_h.lease_start;
    CONTINUE WHEN v_h.lease_end   IS NOT NULL AND d > v_h.lease_end;
    v_dow := to_char(d, 'Dy');
    CONTINUE WHEN NOT (v_dow = ANY (v_used));
    CONTINUE WHEN v_dow = ANY (v_unav);
    SELECT open_time, close_time, closed INTO v_open, v_close, v_closed
      FROM business_hours WHERE org_id = v_org AND weekday = extract(dow FROM d)::int;
    CONTINUE WHEN coalesce(v_closed, false);
    v_open := coalesce(v_open, '10:00'); v_close := coalesce(v_close, '18:00');
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM bookings b WHERE b.horse_id = p_horse_id AND b.kind='block'
        AND b.is_flexible AND b.starts_at::date = d);
    v_start := d + v_open; v_end := d + v_close;
    INSERT INTO bookings (org_id, kind, status, is_flexible, horse_id, contract_id,
                          starts_at, ends_at, notes, created_by)
      VALUES (v_org, 'block', 'available', true, p_horse_id, v_contract,
              v_start, v_end, 'Leased-horse availability', auth.uid());
    v_made := v_made + 1;
  END LOOP;
  RETURN jsonb_build_object('created', v_made, 'contract_id', v_contract);
END;
$$;


--
-- Name: generate_monthly_lessons(uuid, uuid, text, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_monthly_lessons(p_client_id uuid, p_purchase_item_id uuid, p_start_time text, p_duration_minutes integer DEFAULT 60, p_horse_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_pi  purchase_items%ROWTYPE;
  v_pu  purchases%ROWTYPE;
  v_cl  clients%ROWTYPE;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;

  SELECT * INTO v_cl FROM clients WHERE id = p_client_id AND deleted_at IS NULL AND org_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'client not found in this org'; END IF;

  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL AND buyer_contact_id = v_cl.contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item % does not belong to this client', p_purchase_item_id; END IF;

  RETURN _generate_plan_month(p_purchase_item_id, p_start_time, p_duration_minutes,
                              p_horse_id, p_location_id, p_client_id);
END;
$$;


--
-- Name: generate_my_onboarding_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_my_onboarding_documents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_out     jsonb := '[]'::jsonb;
  v_horse   uuid;
  v_cnt     integer;
  v_hid     text;
  v_minor   uuid;
  v_parties jsonb;
  req       record;
  v_doc     uuid;
  v_status  text;
  v_title   text;
  v_keep_horses uuid[];   -- the member's bound horse set for this template
  v_set     uuid := gen_random_uuid();  -- cf STEP 6: one delivery set per run
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_contact := coalesce(current_contact_id(), ensure_contact_for_profile(auth.uid()));
  IF v_contact IS NULL THEN RAISE EXCEPTION 'no contact record for this account'; END IF;
  IF NOT EXISTS (SELECT 1 FROM required_templates_for_contact(v_contact)) THEN
    RETURN v_out;
  END IF;

  -- The horse this paperwork is about — NEVER guessed:
  --   1) the horse attached to the latest purchase (the member chose it, or the
  --      horse-intake step attached it),
  --   2) else the contact's SOLE owned/leased horse (unambiguous),
  --   3) else NULL: documents generate without a horse identity rather than
  --      silently binding to an arbitrary record. All documents in this batch
  --      share the one v_horse, so the horse releases can never split.
  SELECT pu.horse_id INTO v_horse
    FROM purchases pu
    WHERE pu.buyer_contact_id = v_contact AND pu.deleted_at IS NULL
    ORDER BY pu.created_at DESC LIMIT 1;
  IF v_horse IS NULL THEN
    SELECT count(*), max(h.id::text) INTO v_cnt, v_hid
      FROM horses h
      WHERE h.deleted_at IS NULL
        AND (h.current_owner_contact_id = v_contact OR h.lessee_contact_id = v_contact);
    IF v_cnt = 1 THEN v_horse := v_hid::uuid; END IF;
  END IF;

  -- PARTICIPANT = a guardian-linked minor, else the client themselves
  SELECT id INTO v_minor FROM contacts
   WHERE guardian_contact_id = v_contact AND deleted_at IS NULL
   ORDER BY created_at LIMIT 1;

  v_parties := jsonb_build_array(
    jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT', 'is_signer', true),
    jsonb_build_object('contact_id', coalesce(v_minor, v_contact), 'role', 'PARTICIPANT', 'is_signer', false));

  FOR req IN
    SELECT ct.template_key FROM required_templates_for_contact(v_contact) ct
    ORDER BY coalesce((SELECT max(x.onboarding_order) FROM contract_templates x
                       WHERE x.template_key = ct.template_key), 99), ct.template_key
  LOOP
    -- Shared predicate: whatever the wall and the onboarding page consider
    -- unsatisfied, this MUST be willing to generate — otherwise the page lists a
    -- document that can never be produced, which is the deadlock in another form.
    v_doc := NULL; v_status := NULL; v_title := NULL;
    IF contact_document_satisfied(v_contact, req.template_key) THEN
      SELECT d.id, d.status, d.title INTO v_doc, v_status, v_title
        FROM documents d
        JOIN contract_templates t ON t.id = d.template_id
        WHERE (d.contact_id = v_contact OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = d.id AND dp.contact_id = v_contact AND dp.party_role = 'CLIENT')) AND t.template_key = req.template_key
          AND d.deleted_at IS NULL
          AND d.status = 'EXECUTED'
          AND coalesce(d.current_status, '') <> 'superseded'
        ORDER BY d.created_at DESC
        LIMIT 1;
    END IF;

    -- SENDGUARD §3: a pending document carrying a LIVE SIGNATURE is never
    -- swept and never duplicated — it is the document for this template.
    IF v_doc IS NULL THEN
      SELECT d.id, d.status, d.title INTO v_doc, v_status, v_title
        FROM documents d
        JOIN contract_templates t ON t.id = d.template_id
        WHERE (d.contact_id = v_contact OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = d.id AND dp.contact_id = v_contact AND dp.party_role = 'CLIENT')) AND t.template_key = req.template_key
          AND d.deleted_at IS NULL AND d.status <> 'EXECUTED'
          AND EXISTS (SELECT 1 FROM signatures s
                       WHERE s.document_id = d.id AND s.deleted_at IS NULL)
        ORDER BY d.created_at DESC
        LIMIT 1;
    END IF;

    IF v_doc IS NULL THEN
      -- carry the member's multi-horse choice across regeneration
      SELECT dh.horses INTO v_keep_horses FROM (
        SELECT array_agg(x.horse_id ORDER BY x.position) AS horses
          FROM documents d2
          JOIN contract_templates t2 ON t2.id = d2.template_id
          JOIN document_horses x ON x.document_id = d2.id
         WHERE (d2.contact_id = v_contact OR EXISTS (SELECT 1 FROM document_parties dp2 WHERE dp2.document_id = d2.id AND dp2.contact_id = v_contact AND dp2.party_role = 'CLIENT')) AND t2.template_key = req.template_key
           AND d2.deleted_at IS NULL AND d2.status <> 'EXECUTED'
      ) dh;

      UPDATE documents d SET deleted_at = now()
        FROM contract_templates t
        WHERE d.template_id = t.id AND (d.contact_id = v_contact OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = d.id AND dp.contact_id = v_contact AND dp.party_role = 'CLIENT'))
          AND t.template_key = req.template_key
          AND d.status <> 'EXECUTED' AND d.deleted_at IS NULL
          AND NOT EXISTS (SELECT 1 FROM signatures s
                           WHERE s.document_id = d.id AND s.deleted_at IS NULL);
      SELECT g.document_id INTO v_doc
        FROM generate_document(v_contact, req.template_key, NULL::uuid,
             coalesce(v_keep_horses[1], v_horse), v_parties, NULL::text,
             v_keep_horses) g;
      SELECT d.status, d.title INTO v_status, v_title FROM documents d WHERE d.id = v_doc;
    END IF;

    -- cf STEP 6: every document this run touches joins the one onboarding set
    IF v_doc IS NOT NULL THEN
      UPDATE documents SET delivery_set_id = v_set
       WHERE id = v_doc AND status <> 'EXECUTED' AND delivery_set_id IS NULL;
    END IF;
    v_out := v_out || jsonb_build_object(
      'document_id', v_doc, 'template_key', req.template_key,
      'title', v_title, 'status', v_status);
    v_doc := NULL; v_status := NULL; v_title := NULL; v_keep_horses := NULL;
  END LOOP;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION generate_my_onboarding_documents(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_my_onboarding_documents() IS 'Regenerate the signed-in member''s unsigned onboarding documents with fresh profile data. v3: scoped to the single most recent AWAITING_SIGNATURE engagement.';


--
-- Name: get_content_block(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_content_block(p_slug text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid := current_org();
  v_block content_blocks%ROWTYPE;
  v_body  text;
  v_key   text;
  v_val   text;
BEGIN
  SELECT * INTO v_block FROM content_blocks WHERE org_id = v_org AND slug = p_slug;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT body INTO v_body FROM content_block_versions
   WHERE block_id = v_block.id AND version = v_block.current_version;

  FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(p_context) LOOP
    v_body := replace(v_body, '{{' || v_key || '}}', COALESCE(v_val, ''));
  END LOOP;

  RETURN jsonb_build_object(
    'slug', v_block.slug,
    'kind', v_block.kind,
    'title', v_block.title,
    'version', v_block.current_version,
    'body', v_body
  );
END;
$$;


--
-- Name: gift_claim_link(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_claim_link(p_gift_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_g gifts%ROWTYPE;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_g.buyer_user_id = auth.uid(), false) THEN
    RAISE EXCEPTION 'not your gift';
  END IF;
  RETURN '/redeem?code=' || v_g.code;
END;
$$;


--
-- Name: gift_mark_sent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_mark_sent(p_gift_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_g gifts%ROWTYPE;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_g.buyer_user_id = auth.uid(), false) THEN
    RAISE EXCEPTION 'not your gift';
  END IF;
  UPDATE gifts SET last_sent_at = now(), send_count = send_count + 1 WHERE id = p_gift_id;
END;
$$;


--
-- Name: gift_reschedule(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_reschedule(p_gift_id uuid, p_deliver_on date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_g gifts%ROWTYPE;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_g.buyer_user_id = auth.uid(), false) THEN
    RAISE EXCEPTION 'not your gift';
  END IF;
  IF v_g.status = 'redeemed' THEN RAISE EXCEPTION 'this gift has already been used'; END IF;
  UPDATE gifts SET deliver_on = p_deliver_on WHERE id = p_gift_id;
END;
$$;


--
-- Name: gift_transfer(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_transfer(p_gift_id uuid, p_recipient_name text, p_recipient_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_g gifts%ROWTYPE;
BEGIN
  SELECT * INTO v_g FROM gifts WHERE id = p_gift_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_g.buyer_user_id = auth.uid(), false) THEN
    RAISE EXCEPTION 'not your gift';
  END IF;
  IF v_g.status = 'redeemed' THEN RAISE EXCEPTION 'this gift has already been used'; END IF;
  IF nullif(btrim(coalesce(p_recipient_name,'')),'') IS NULL THEN
    RAISE EXCEPTION 'a recipient name is required';
  END IF;
  UPDATE gifts SET
      transferred_from_email = recipient_email,
      recipient_name  = btrim(p_recipient_name),
      recipient_email = nullif(lower(btrim(coalesce(p_recipient_email,''))), ''),
      -- live status vocabulary: created/paid/delivered/opened/redeemed/
      -- expired/cancelled. A transferred gift that had been opened returns to
      -- 'delivered' so the new recipient opens it fresh.
      status = CASE WHEN status = 'opened' THEN 'delivered' ELSE status END,
      opened_at = NULL
    WHERE id = p_gift_id;
END;
$$;


--
-- Name: grant_lesson_credit(uuid, uuid, integer, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_lesson_credit(p_client_id uuid, p_offering_id uuid, p_quantity integer DEFAULT 1, p_mode text DEFAULT 'handwrite'::text, p_reason text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid := current_org();
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_mode     text := lower(btrim(coalesce(p_mode, '')));
  v_qty      integer := coalesce(p_quantity, 1);
  v_cl       clients%ROWTYPE;
  v_off      offerings%ROWTYPE;
  v_list     numeric;
  v_line     numeric;
  v_total    numeric;
  v_purchase uuid;
  v_item     uuid;
  v_credit   lesson_credits%ROWTYPE;
  v_user     uuid;
  v_code     text;
  v_detail   text;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may grant a credit';
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no organization in scope';
  END IF;
  IF v_mode NOT IN ('handwrite', 'comp', 'bill') THEN
    RAISE EXCEPTION 'mode must be handwrite, comp or bill (got %)', p_mode;
  END IF;
  -- D19(2). Not optional, not defaulted, not a placeholder.
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to grant a credit';
  END IF;
  IF v_qty < 1 THEN
    RAISE EXCEPTION 'quantity must be at least 1';
  END IF;

  SELECT * INTO v_cl FROM clients
   WHERE id = p_client_id AND deleted_at IS NULL AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'client not found in this organization';
  END IF;

  SELECT * INTO v_off FROM offerings WHERE id = p_offering_id AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'service not found in this organization';
  END IF;
  IF coalesce(v_off.config_kind, '') <> 'scheduled' THEN
    RAISE EXCEPTION '% is a % service — only a scheduled service mints a spendable credit. A weekly plan is a standing slot, not a credit balance.',
      v_off.name, coalesce(v_off.config_kind, 'quote-priced');
  END IF;
  IF coalesce(v_off.unit_count, 0) <= 0 THEN
    RAISE EXCEPTION '% carries no credit units, so granting it would mint nothing', v_off.name;
  END IF;

  -- THE LIST PRICE AT GRANT TIME. Read now, stored on the line, never re-derived:
  -- the offering's price is editable and a recorded loss must not move with it.
  v_list  := coalesce(v_off.price_amount, 0);
  v_line  := CASE WHEN v_mode = 'comp' THEN 0 ELSE v_list END;
  v_total := v_line * v_qty;

  INSERT INTO purchases (org_id, buyer_contact_id, status, amount, amount_paid,
                         payment_method, payment_status, paid_at, notes)
  VALUES (
    v_org, v_cl.contact_id,
    CASE WHEN v_mode = 'bill' THEN 'awaiting_payment' ELSE 'paid' END,
    v_total,
    CASE WHEN v_mode = 'bill' THEN 0 ELSE v_total END,
    CASE WHEN v_mode = 'comp' THEN 'comp'
         WHEN v_mode = 'handwrite' THEN coalesce(nullif(btrim(coalesce(p_payment_method, '')), ''), 'offline')
         END,
    CASE WHEN v_mode = 'bill' THEN 'unpaid' ELSE 'paid' END,
    -- TASK-ORIGIN §4.3: "a backfilled purchase entered today with today's
    -- timestamp is worse than no record." A bill is unpaid regardless — no
    -- paid_at to backdate until it is settled (mark_purchase_paid, above).
    CASE WHEN v_mode = 'bill' THEN NULL ELSE coalesce(p_paid_at, now()) END,
    CASE v_mode
      WHEN 'comp'      THEN 'Comped by staff — ' || v_reason
      WHEN 'bill'      THEN 'Billed by staff — ' || v_reason
      ELSE                  'Hand-written by staff — ' || v_reason
    END)
  RETURNING id, display_code INTO v_purchase, v_code;

  -- The line. `config` is the per-line intent this table already carries; the grant's
  -- own facts live there rather than in new columns nothing else would read.
  INSERT INTO purchase_items (org_id, purchase_id, offering_id, label, price_amount,
                              price_unit, quantity, config)
  VALUES (v_org, v_purchase, v_off.id, v_off.name, v_line, v_off.price_unit, v_qty,
          jsonb_build_object(
            'grant_mode',  v_mode,
            'grant_reason', v_reason,
            'list_price',  v_list,
            'granted_by',  auth.uid(),
            'granted_at',  now()))
  RETURNING id INTO v_item;

  -- The INSERT trigger has already minted through the engine. This re-run only names
  -- the client explicitly (the trigger resolves it from the buyer contact); the
  -- one-per-item unique index makes it a no-op when the trigger already succeeded.
  PERFORM _mint_credits_for_purchase_item(v_item, p_client_id);

  SELECT * INTO v_credit FROM lesson_credits
   WHERE purchase_item_id = v_item AND deleted_at IS NULL
   ORDER BY created_at LIMIT 1;
  -- D17: never report a grant that granted nothing. If the engine minted no row, the
  -- whole act rolls back rather than leaving an order that looks like an entitlement.
  IF NOT FOUND THEN
    RAISE EXCEPTION 'the credit engine minted nothing for % — no credit was granted', v_off.name;
  END IF;

  v_detail :=
    CASE v_mode
      WHEN 'comp' THEN 'Comped ' || v_credit.credits_total || ' x ' || v_off.name
                       || ' (list ' || fmt_money(v_list * v_qty) || ' written off)'
      WHEN 'bill' THEN 'Billed ' || v_credit.credits_total || ' x ' || v_off.name
                       || ' — ' || fmt_money(v_total) || ' owed'
      ELSE             'Hand-wrote ' || v_credit.credits_total || ' x ' || v_off.name
                       || ' (' || fmt_money(v_total) || ' recorded as received)'
    END || ' — ' || v_reason;
  PERFORM log_status_event('order', v_purchase, 'staff_grant', v_detail, v_org);

  -- The client is told what they now hold. A BILL raises no "payment due" notice here:
  -- asking for the money is a separate, deliberate staff act (request_purchase_payment).
  SELECT pr.user_id INTO v_user FROM profiles pr WHERE pr.contact_id = v_cl.contact_id LIMIT 1;
  IF v_user IS NOT NULL THEN
    PERFORM notify_user(v_user, 'credit_granted',
      v_credit.credits_total || ' x ' || v_off.name || ' added to your account',
      CASE v_mode
        WHEN 'comp' THEN 'With our compliments. ' || v_reason
        WHEN 'bill' THEN 'Added now — ' || fmt_money(v_total) || ' is owed on order ' || coalesce(v_code, '') || '.'
        ELSE             'Recorded against ' || fmt_money(v_total) || ' already received.'
      END,
      '/order/' || v_purchase::text);
  END IF;

  IF v_mode = 'handwrite' THEN
    -- Same "payment received" trail every other paid order gets. A comp is not a
    -- payment and does not get one.
    PERFORM _notify_purchase_paid(v_purchase);
  END IF;

  RETURN jsonb_build_object(
    'purchase_id',   v_purchase,
    'display_code',  v_code,
    'item_id',       v_item,
    'credit_id',     v_credit.id,
    'credits',       v_credit.credits_total,
    'mode',          v_mode,
    'reason',        v_reason,
    'list_price',    v_list,
    'amount',        v_total,
    'comp_value',    CASE WHEN v_mode = 'comp' THEN v_list * v_qty ELSE 0 END,
    'offering_name', v_off.name,
    'client_id',     p_client_id);
END;
$$;


--
-- Name: grantable_offerings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grantable_offerings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', o.id, 'name', o.name, 'segment', o.segment,
             'unit_count', o.unit_count, 'price_amount', coalesce(o.price_amount, 0),
             'active', o.active)
           ORDER BY o.active DESC, o.segment, o.name)
      FROM offerings o
     WHERE o.org_id = v_org
       AND o.config_kind = 'scheduled'
       AND coalesce(o.unit_count, 0) > 0), '[]'::jsonb);
END;
$$;


--
-- Name: hard_delete_booking_drafts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_booking_drafts(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); v_n int;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  -- Only ever deletes rows that are genuinely drafts in the caller's org — a
  -- committed booking id passed here is ignored, never destroyed.
  WITH del AS (
    DELETE FROM bookings
     WHERE id = ANY(p_ids) AND org_id = v_org AND status = 'draft'
     RETURNING 1)
  SELECT count(*) INTO v_n FROM del;
  RETURN v_n;
END
$$;


--
-- Name: hard_delete_contract(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_contract(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_contract uuid;
BEGIN
  SELECT org_id, workflow_state, contract_id INTO v_org, v_state, v_contract
    FROM documents WHERE id = p_document_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF v_state = 'executed' THEN RAISE EXCEPTION 'an executed document cannot be deleted'; END IF;

  DELETE FROM notifications WHERE link = '/app/contracts/' || p_document_id::text;

  DELETE FROM signatures          WHERE document_id = p_document_id;
  DELETE FROM esign_consents      WHERE document_id = p_document_id;
  DELETE FROM document_deliveries WHERE document_id = p_document_id;
  DELETE FROM invitations         WHERE document_id = p_document_id;
  UPDATE horse_relationships SET source_document_id = NULL WHERE source_document_id = p_document_id;
  UPDATE horse_reconciliation SET evidence_document_id = NULL WHERE evidence_document_id = p_document_id;

  DELETE FROM contract_fields   WHERE document_id = p_document_id;
  DELETE FROM document_parties  WHERE document_id = p_document_id;
  DELETE FROM contract_change_requests WHERE document_id = p_document_id;
  DELETE FROM contract_addenda  WHERE document_id = p_document_id;

  DELETE FROM documents WHERE id = p_document_id;

  IF v_contract IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM documents WHERE contract_id = v_contract) THEN
    DELETE FROM contract_parties WHERE contract_id = v_contract;
    DELETE FROM contracts WHERE id = v_contract;
  END IF;
END;
$$;


--
-- Name: has_module(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM org_modules
    WHERE org_id = current_org()
      AND module_key = p_key
      AND enabled
      AND (expires_at IS NULL OR expires_at > now())
  )
$$;


--
-- Name: has_staff_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_staff_access() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(app_role() IN ('SUPER_ADMIN','ADMIN','MANAGER','EMPLOYEE'), false)
$$;


--
-- Name: FUNCTION has_staff_access(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_staff_access() IS 'True only for a SUPER_ADMIN/ADMIN/MANAGER/EMPLOYEE profile. Fails closed: NULL app_role() (no profiles row, e.g. anon) returns false so that `IF NOT has_staff_access()` actually fires (NULLUID).';


--
-- Name: hold_purchase_for_horse(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_purchase_for_horse(p_purchase_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v purchases%ROWTYPE;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may hold an order';
  END IF;
  SELECT * INTO v FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF v.id IS NULL OR v.org_id IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'order not found';
  END IF;
  IF v.status = 'paid' THEN
    RAISE EXCEPTION 'that order is already paid — it cannot be put on hold';
  END IF;

  -- §C5b vocabulary only: `draft` plus a status event. No new status value.
  UPDATE purchases SET status = 'draft', payment_status = 'unpaid', updated_at = now()
   WHERE id = p_purchase_id;
  PERFORM log_status_event('order', p_purchase_id, 'awaiting_horse',
    coalesce(nullif(btrim(p_reason), ''),
             'Held until the horse these services are for exists'), v.org_id);

  RETURN jsonb_build_object('purchase_id', p_purchase_id, 'status', 'draft',
                            'current_status', 'awaiting_horse');
END;
$$;


--
-- Name: horse_active_lease_doc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_active_lease_doc(p_horse_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object('document_id', dc.id, 'display_code', dc.display_code,
                            'effective_date', dc.effective_date)
  FROM documents dc
  JOIN contract_templates t ON t.id = dc.template_id
  WHERE dc.horse_id = p_horse_id AND t.template_key = 'HORSE_LEASE'
    AND dc.status = 'EXECUTED' AND dc.deleted_at IS NULL
    AND dc.org_id = current_org()
  ORDER BY dc.effective_date DESC NULLS LAST, dc.created_at DESC
  LIMIT 1
$$;


--
-- Name: horse_behavior_prose(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_behavior_prose(p_list jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(nullif(btrim(concat_ws(' ',
    nullif(btrim(e->>'description'),''),
    CASE WHEN nullif(btrim(e->>'trigger'),'') IS NOT NULL THEN '| trigger: ' || btrim(e->>'trigger') END,
    CASE WHEN nullif(btrim(e->>'date_since'),'') IS NOT NULL THEN '(since ' || btrim(e->>'date_since') || ')' END
  )),''), E'\n'), '')
  FROM jsonb_array_elements(coalesce(p_list,'[]'::jsonb)) e;
$$;


--
-- Name: horses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.horses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_code text,
    registered_name text,
    nickname text,
    breed text,
    color text,
    sex text,
    date_of_birth date,
    height text,
    registration_number text,
    microchip_id text,
    current_location text,
    current_owner_contact_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    fair_market_value numeric,
    markings text,
    registration_org text,
    passport_number text,
    passport_country text,
    created_by_contact_id uuid,
    owner_name_text text,
    lessee_contact_id uuid,
    lessee_name_text text,
    lease_start date,
    lease_end date,
    euthanasia_authorization text,
    sublease_allowed boolean DEFAULT false NOT NULL,
    rider_level_min text,
    rider_level_max text,
    vaccinations jsonb DEFAULT '[]'::jsonb NOT NULL,
    pending_fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    medical_history_list jsonb DEFAULT '[]'::jsonb NOT NULL,
    behavioral_history_list jsonb DEFAULT '[]'::jsonb NOT NULL,
    known_conditions_list jsonb DEFAULT '[]'::jsonb NOT NULL,
    training_history_list jsonb DEFAULT '[]'::jsonb NOT NULL,
    competition_history_list jsonb DEFAULT '[]'::jsonb NOT NULL,
    injuries_to_humans text NOT NULL,
    injuries_to_horse jsonb DEFAULT '[]'::jsonb NOT NULL,
    sire text,
    dam text,
    CONSTRAINT horses_euthanasia_authorization_check CHECK (((euthanasia_authorization IS NULL) OR (euthanasia_authorization = ANY (ARRAY['A'::text, 'B'::text])))),
    CONSTRAINT horses_named CHECK (((registered_name IS NOT NULL) OR (nickname IS NOT NULL))),
    CONSTRAINT horses_sex_check CHECK ((sex = ANY (ARRAY['MARE'::text, 'GELDING'::text, 'STALLION'::text, 'FILLY'::text, 'COLT'::text])))
);


--
-- Name: COLUMN horses.rider_level_min; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.horses.rider_level_min IS 'Lowest rider level this horse suits (matching, not yet enforced).';


--
-- Name: COLUMN horses.rider_level_max; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.horses.rider_level_max IS 'Highest rider level this horse suits (matching, not yet enforced).';


--
-- Name: horse_block_caption(public.horses, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_block_caption(v_horse public.horses, p_index integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 'Horse ' || p_index || ' — '
      || coalesce(nullif(btrim(coalesce(v_horse.registered_name, '')), ''),
                  nullif(btrim(coalesce(v_horse.nickname, '')), ''),
                  'Unnamed');
$$;


--
-- Name: horse_conditions_prose(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_conditions_prose(p_list jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(nullif(btrim(concat_ws(' ',
    nullif(btrim(e->>'description'),''),
    CASE WHEN nullif(btrim(e->>'date_first_noticed'),'') IS NOT NULL THEN '(first noticed ' || btrim(e->>'date_first_noticed') || ')' END,
    CASE WHEN nullif(btrim(e->>'status'),'') IS NOT NULL THEN '— ' || btrim(e->>'status') END,
    CASE WHEN nullif(btrim(e->>'triggers'),'') IS NOT NULL THEN '| triggers: ' || btrim(e->>'triggers') END,
    CASE WHEN nullif(btrim(e->>'accommodations'),'') IS NOT NULL THEN '| accommodations: ' || btrim(e->>'accommodations') END
  )),''), E'\n'), '')
  FROM jsonb_array_elements(coalesce(p_list,'[]'::jsonb)) e;
$$;


--
-- Name: horse_current_location_label(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_current_location_label(p_horse uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT nullif(btrim(concat_ws(', ', hl.name, hl.address_line1, hl.city,
            nullif(btrim(concat_ws(' ', hl.state, hl.postal)),''))), '')
  FROM horse_locations hl
  WHERE hl.horse_id = p_horse AND hl.end_on IS NULL
  ORDER BY hl.created_at DESC
  LIMIT 1;
$$;


--
-- Name: horse_deals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_deals(p_horse_id uuid) RETURNS TABLE(id uuid, display_code text, title text, deal_type text, status text, badge jsonb, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT d.id, d.display_code, d.title, d.deal_type, d.status,
         deal_status(d.id), d.created_at
  FROM deals d
  JOIN contracts ct ON ct.id = d.contract_id
  WHERE d.deleted_at IS NULL AND contract_horse_id(ct.id) = p_horse_id
    AND ((coalesce(has_staff_access() AND d.org_id = current_org(), false))
      OR EXISTS (SELECT 1 FROM contract_parties cp
                  WHERE cp.contract_id = d.contract_id AND cp.contact_id = current_contact_id()))
  ORDER BY d.created_at DESC;
$$;


--
-- Name: horse_field_token_value(public.horses, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_field_token_value(v_horse public.horses, p_field text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_breed  text;
  v_color  text;
  v_reg_org  text;
  v_passport_country text;
  v_pending text[] := ARRAY(SELECT jsonb_array_elements_text(coalesce(v_horse.pending_fields, '[]'::jsonb)));
  -- record field name → the HORSE token it feeds
  v_pending_token boolean := CASE p_field
    WHEN 'REGISTERED_NAME'     THEN 'registered_name'     = ANY(v_pending)
    WHEN 'REGISTRATION_NUMBER' THEN 'registration_number' = ANY(v_pending)
    WHEN 'MICROCHIP'           THEN 'microchip_id'        = ANY(v_pending)
    WHEN 'FAIR_MARKET_VALUE'   THEN 'fair_market_value'   = ANY(v_pending)
    WHEN 'PASSPORT_NUMBER'     THEN 'passport_number'     = ANY(v_pending)
    WHEN 'AGE_DOB'             THEN 'date_of_birth'       = ANY(v_pending)
    WHEN 'HEIGHT'              THEN 'height'              = ANY(v_pending)
    WHEN 'MARKINGS'            THEN 'markings'            = ANY(v_pending)
    ELSE false END;
  v_raw text;
BEGIN
  v_breed := coalesce((SELECT display_name FROM horse_breeds WHERE code = v_horse.breed), v_horse.breed);
  v_color := coalesce((SELECT display_name FROM horse_colors WHERE code = v_horse.color), v_horse.color);
  v_reg_org := coalesce((SELECT display_name FROM lookup_options WHERE lookup_key='horse_registration_org' AND code = v_horse.registration_org), v_horse.registration_org);
  v_passport_country := coalesce((SELECT display_name FROM lookup_options WHERE lookup_key='horse_passport_country' AND code = v_horse.passport_country), v_horse.passport_country);

  v_raw := CASE p_field
    WHEN 'REGISTERED_NAME'     THEN v_horse.registered_name
    WHEN 'BARN_NAME'           THEN v_horse.nickname
    WHEN 'BREED'               THEN v_breed
    WHEN 'COLOR'               THEN v_color
    WHEN 'SEX'                 THEN CASE upper(coalesce(v_horse.sex, ''))
                                   WHEN 'MARE' THEN 'Mare' WHEN 'GELDING' THEN 'Gelding'
                                   WHEN 'STALLION' THEN 'Stallion' WHEN 'COLT' THEN 'Colt'
                                   WHEN 'FILLY' THEN 'Filly' WHEN '' THEN v_horse.sex
                                   ELSE initcap(v_horse.sex) END
    WHEN 'AGE_DOB'             THEN to_char(v_horse.date_of_birth, 'FMMonth FMDD, YYYY')
    WHEN 'HEIGHT'              THEN v_horse.height
    WHEN 'REGISTRATION_NUMBER' THEN v_horse.registration_number
    WHEN 'MICROCHIP'           THEN v_horse.microchip_id
    WHEN 'MARKINGS'            THEN v_horse.markings
    WHEN 'REGISTRATION_ORG'    THEN v_reg_org
    WHEN 'PASSPORT_NUMBER'     THEN v_horse.passport_number
    WHEN 'PASSPORT_COUNTRY'    THEN v_passport_country
    WHEN 'CURRENT_LOCATION'    THEN coalesce(horse_current_location_label(v_horse.id), v_horse.current_location)
    WHEN 'HOME_LOCATION'       THEN horse_current_location_label(v_horse.id)
    WHEN 'VET_NAME'            THEN horse_provider_value(v_horse.id, 'VET', 'NAME')
    WHEN 'VET_PHONE'           THEN horse_provider_value(v_horse.id, 'VET', 'PHONE')
    WHEN 'VET_BUSINESS'        THEN horse_provider_value(v_horse.id, 'VET', 'BUSINESS')
    WHEN 'VET_ADDRESS'         THEN horse_provider_value(v_horse.id, 'VET', 'ADDRESS')
    WHEN 'FARRIER_NAME'        THEN horse_provider_value(v_horse.id, 'FARRIER', 'NAME')
    WHEN 'FARRIER_PHONE'       THEN horse_provider_value(v_horse.id, 'FARRIER', 'PHONE')
    WHEN 'FAIR_MARKET_VALUE'   THEN fmt_money(v_horse.fair_market_value)
    -- Disclosure sections (record -> contract). Prose from the structured lists.
    WHEN 'KNOWN_CONDITIONS'        THEN horse_section_text_block(v_horse, 'KNOWN_CONDITIONS')
    WHEN 'MEDICAL_HISTORY'         THEN horse_section_text_block(v_horse, 'MEDICAL_HISTORY')
    WHEN 'BEHAVIORAL_HISTORY'      THEN horse_section_text_block(v_horse, 'BEHAVIORAL_HISTORY')
    WHEN 'INJURIES_TO_HUMANS'      THEN upper(coalesce(nullif(btrim(v_horse.injuries_to_humans),''),''))
    WHEN 'INJURIES_TO_HORSE'       THEN horse_section_text_block(v_horse, 'INJURIES_TO_HORSE')
    WHEN 'MEDICATIONS'             THEN horse_section_text_block(v_horse, 'MEDICATIONS')
    WHEN 'SUPPLEMENTS'             THEN horse_section_text_block(v_horse, 'SUPPLEMENTS')
    WHEN 'TRAINING_HISTORY'        THEN horse_list_prose(v_horse.training_history_list, 'entry')
    WHEN 'COMPETITION_HISTORY'     THEN horse_list_prose(v_horse.competition_history_list, 'entry')
    WHEN 'MEDICATION_NAME'         THEN horse_meds_prose_v2(v_horse.id, 'MEDICATION')
    WHEN 'MEDICATION_HISTORY'      THEN horse_meds_prose_v2(v_horse.id, 'MEDICATION')
    WHEN 'MEDICATION_DOSAGE'       THEN ''
    WHEN 'MEDICATION_INSTRUCTIONS' THEN ''
    WHEN 'MEDICATION_ADDITIONAL'   THEN ''
    -- Per-section HAS-ENTRIES gate: 'YES' when the record section holds entries.
    WHEN 'KNOWN_CONDITIONS_GATE'   THEN CASE WHEN jsonb_array_length(coalesce(v_horse.known_conditions_list,'[]'::jsonb))>0 THEN 'YES' ELSE 'NO' END
    WHEN 'MEDICAL_HISTORY_GATE'    THEN CASE WHEN jsonb_array_length(coalesce(v_horse.medical_history_list,'[]'::jsonb))>0 THEN 'YES' ELSE 'NO' END
    WHEN 'BEHAVIORAL_HISTORY_GATE' THEN CASE WHEN jsonb_array_length(coalesce(v_horse.behavioral_history_list,'[]'::jsonb))>0 THEN 'YES' ELSE 'NO' END
    WHEN 'INJURIES_TO_HUMANS_GATE' THEN upper(coalesce(nullif(btrim(v_horse.injuries_to_humans),''),''))
    WHEN 'INJURIES_TO_HORSE_GATE'  THEN CASE WHEN jsonb_array_length(coalesce(v_horse.injuries_to_horse,'[]'::jsonb))>0 THEN 'YES' ELSE 'NO' END
    WHEN 'MEDICATIONS_GATE'        THEN CASE WHEN EXISTS(SELECT 1 FROM horse_medications m WHERE m.horse_id=v_horse.id AND m.kind='MEDICATION' AND m.deleted_at IS NULL) THEN 'YES' ELSE 'NO' END
    WHEN 'SUPPLEMENTS_GATE'        THEN CASE WHEN EXISTS(SELECT 1 FROM horse_medications m WHERE m.horse_id=v_horse.id AND m.kind='SUPPLEMENT' AND m.deleted_at IS NULL) THEN 'YES' ELSE 'NO' END
    WHEN 'EUTHANASIA_A' THEN CASE WHEN v_horse.euthanasia_authorization = 'A' THEN 'X' ELSE ' ' END
    WHEN 'EUTHANASIA_B' THEN CASE WHEN v_horse.euthanasia_authorization = 'B' THEN 'X' ELSE ' ' END
    ELSE '' END;

  -- A pending field with nothing entered prints "To be provided" so its line shows
  -- the gap rather than vanishing; a filled pending field prints its value.
  IF v_pending_token AND nullif(btrim(coalesce(v_raw, '')), '') IS NULL THEN
    RETURN 'To be provided';
  END IF;
  RETURN v_raw;
END;
$$;


--
-- Name: horse_hidden_lessee_entries(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_hidden_lessee_entries(p_horse uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'kind', e.kind, 'data', e.data, 'created_at', e.created_at,
      'author', coalesce(nullif(btrim(c.first_name||' '||c.last_name),''), c.email, 'Lessee'),
      'author_contact_id', e.author_contact_id) ORDER BY e.created_at DESC), '[]'::jsonb)
  FROM horse_lessee_entries e
  JOIN contacts c ON c.id = e.author_contact_id
  WHERE e.horse_id = p_horse AND e.deleted_at IS NULL AND e.hidden_by_owner
    AND e.org_id = current_org()
    AND (has_staff_access() OR EXISTS (
      SELECT 1 FROM horses h WHERE h.id = p_horse AND h.current_owner_contact_id = current_contact_id()));
$$;


--
-- Name: horse_injuries_change_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_injuries_change_log(p_horse uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'at', a.occurred_at,
      'by', coalesce(nullif(btrim(c.first_name||' '||c.last_name),''), c.email, p.display_name, 'Someone'),
      'action', a.action,
      'before', a.old_value -> 'injuries_to_humans',
      'after', a.new_value -> 'injuries_to_humans') ORDER BY a.occurred_at DESC), '[]'::jsonb)
  FROM audit_logs a
  LEFT JOIN profiles p ON p.user_id = a.actor_user_id
  LEFT JOIN contacts c ON c.id = p.contact_id
  WHERE a.table_name = 'horses' AND a.record_id = p_horse
    AND (a.old_value -> 'injuries_to_humans') IS DISTINCT FROM (a.new_value -> 'injuries_to_humans')
    AND has_staff_access()  -- the disclosure log is a staff/record-keeping view
    AND current_org() = (SELECT org_id FROM horses WHERE id = p_horse);
$$;


--
-- Name: horse_injuries_horse_prose(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_injuries_horse_prose(p_list jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(nullif(btrim(concat_ws(' ',
    CASE WHEN nullif(btrim(e->>'date'),'') IS NOT NULL THEN btrim(e->>'date') || ':' END,
    nullif(btrim(e->>'description'),''),
    CASE WHEN (e->>'rider_involved') = 'true' THEN '| a rider was involved' END,
    CASE WHEN (e->>'human_hurt') = 'true' THEN '| a person was hurt'
          || CASE WHEN (e->>'human_was_riding') = 'true' THEN ' (riding)'
                  WHEN (e->>'human_was_riding') = 'false' THEN ' (not riding)' ELSE '' END END,
    CASE WHEN nullif(btrim(e->>'outcome'),'') IS NOT NULL THEN '— ' || btrim(e->>'outcome') END,
    CASE WHEN nullif(btrim(e->>'status'),'') IS NOT NULL THEN '(' || btrim(e->>'status') || ')' END
  )),''), E'\n'), '')
  FROM jsonb_array_elements(coalesce(p_list,'[]'::jsonb)) e;
$$;


--
-- Name: horse_injuries_prose(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_injuries_prose(p_list jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(
    nullif(btrim(concat_ws(' ',
      nullif(btrim(e ->> 'date'), ''),
      CASE WHEN nullif(btrim(e ->> 'person_type'), '') IS NOT NULL
           THEN '(' || btrim(e ->> 'person_type') || ')' END,
      nullif(btrim(e ->> 'description'), ''),
      CASE WHEN nullif(btrim(e ->> 'outcome'), '') IS NOT NULL
           THEN '— ' || btrim(e ->> 'outcome') END)), ''),
    '; '), '')
  FROM jsonb_array_elements(coalesce(p_list, '[]'::jsonb)) e;
$$;


--
-- Name: horse_list_prose(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_list_prose(p_list jsonb, p_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(nullif(btrim(e ->> p_key), ''), '; '), '')
  FROM jsonb_array_elements(coalesce(p_list, '[]'::jsonb)) e;
$$;


--
-- Name: horse_medical_prose(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_medical_prose(p_list jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT nullif(string_agg(nullif(btrim(concat_ws(' ',
    CASE WHEN nullif(btrim(e->>'date'),'') IS NOT NULL THEN btrim(e->>'date') || ':' END,
    CASE WHEN nullif(btrim(e->>'type'),'') IS NOT NULL THEN btrim(e->>'type') || ' —' END,
    nullif(btrim(e->>'description'),''),
    CASE WHEN nullif(btrim(e->>'status'),'') IS NOT NULL THEN '(' || btrim(e->>'status') || ')' END
  )),''), E'\n'), '')
  FROM jsonb_array_elements(coalesce(p_list,'[]'::jsonb)) e;
$$;


--
-- Name: horse_medication_component(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_medication_component(p_horse_id uuid, p_component text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT string_agg(part, '; ' ORDER BY sort_order)
  FROM (
    SELECT m.sort_order,
           btrim(CASE upper(p_component)
             WHEN 'DOSAGE'       THEN coalesce(nullif(btrim(m.dosage), ''), '')
             WHEN 'INSTRUCTIONS' THEN coalesce(nullif(btrim(m.instructions), ''), '')
             WHEN 'ADDITIONAL'   THEN
               -- everything that is neither name, dosage nor instructions:
               -- supply/cost/prescription detail, in the prose function's order
               coalesce(nullif(btrim(concat_ws(', ',
                 nullif(btrim(concat_ws(' ', nullif(m.order_units, ''),
                   CASE WHEN m.days_supply IS NOT NULL
                        THEN '(' || m.days_supply || ' day supply)' END)), ''),
                 CASE WHEN m.cost IS NOT NULL
                      THEN '$' || trim(to_char(m.cost, 'FM999999990.00')) || '/order' END,
                 nullif(btrim(m.rx_info), '')
               )), ''), '')
             ELSE '' END) AS part
      FROM horse_medications m
     WHERE m.horse_id = p_horse_id AND m.deleted_at IS NULL AND m.kind = 'MEDICATION'
  ) parts
  WHERE part <> ''
$_$;


--
-- Name: FUNCTION horse_medication_component(p_horse_id uuid, p_component text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.horse_medication_component(p_horse_id uuid, p_component text) IS 'U2.3: single medication component (DOSAGE | INSTRUCTIONS | ADDITIONAL) across a horse''s medications. horse_medications_prose renders the whole line; this renders one part of it.';


--
-- Name: horse_medications_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_medications_list(p_horse_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', id, 'kind', kind, 'name', name, 'dosage', dosage, 'instructions', instructions,
    'cost', cost, 'supplier_website', supplier_website, 'supplier_phone', supplier_phone,
    'rx_info', rx_info, 'order_units', order_units, 'days_supply', days_supply,
    'purpose', purpose, 'frequency', frequency, 'cost_per_dose', cost_per_dose, 'rx_required', rx_required)
    ORDER BY kind, sort_order), '[]'::jsonb)
  FROM horse_medications
  WHERE horse_id = p_horse_id AND deleted_at IS NULL
    AND (has_staff_access() OR caller_owns_horse(horse_id));
$$;


--
-- Name: horse_medications_prose(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_medications_prose(p_horse_id uuid, p_kind text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT string_agg(
    btrim(concat_ws(' — ',
      m.name,
      nullif(btrim(concat_ws(', ', nullif(m.dosage,''), nullif(m.instructions,''))),''),
      nullif(btrim(concat_ws(', ',
        CASE WHEN m.order_units IS NOT NULL OR m.days_supply IS NOT NULL
             THEN nullif(btrim(concat_ws(' ', nullif(m.order_units,''),
                    CASE WHEN m.days_supply IS NOT NULL THEN '(' || m.days_supply || ' day supply)' END)),'') END,
        CASE WHEN m.cost IS NOT NULL THEN '$' || trim(to_char(m.cost, 'FM999999990.00')) || '/order' END)),'')
    )), '; ' ORDER BY m.sort_order)
  FROM horse_medications m
  WHERE m.horse_id = p_horse_id AND m.deleted_at IS NULL AND m.kind = upper(p_kind);
$_$;


--
-- Name: horse_meds_prose_v2(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_meds_prose_v2(p_horse uuid, p_kind text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT nullif(string_agg(nullif(btrim(concat_ws(' ',
    nullif(btrim(m.name),''),
    CASE WHEN nullif(btrim(m.dosage),'') IS NOT NULL THEN '— ' || btrim(m.dosage) END,
    CASE WHEN nullif(btrim(m.instructions),'') IS NOT NULL THEN '(' || btrim(m.instructions) || ')' END
  )),''), E'\n' ORDER BY m.sort_order, m.name), '')
  FROM horse_medications m
  WHERE m.horse_id = p_horse AND m.kind = p_kind AND m.deleted_at IS NULL;
$$;


--
-- Name: horse_page_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_page_detail(p_horse_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_h horses%ROWTYPE; v_out jsonb; v_lease jsonb; v_curr jsonb;
BEGIN
  SELECT * INTO v_h FROM horses WHERE id = p_horse_id AND org_id = current_org() AND deleted_at IS NULL;
  IF v_h.id IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR caller_owns_horse(p_horse_id)) THEN
    RAISE EXCEPTION 'not authorized for this horse';
  END IF;

  IF v_h.lease_start IS NOT NULL AND v_h.lease_start <= current_date
     AND (v_h.lease_end IS NULL OR v_h.lease_end >= current_date) THEN
    SELECT jsonb_build_object(
        'lessee_name', coalesce((SELECT nullif(btrim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')),'') FROM contacts WHERE id = v_h.lessee_contact_id), v_h.lessee_name_text),
        'lease_start', v_h.lease_start, 'lease_end', v_h.lease_end,
        'lease_type', nullif(cf.lease_type, ''), 'days_used', nullif(cf.days_used, ''),
        'schedule_terms', nullif(cf.schedule_terms, ''), 'source_document_id', d.id
      ) INTO v_lease
      FROM documents d
      JOIN contract_templates ct ON ct.id = d.template_id
      CROSS JOIN LATERAL (
        SELECT max(value) FILTER (WHERE field_key = 'TXN.LEASE_TYPE') AS lease_type,
               max(value) FILTER (WHERE field_key = 'TXN.DAYS_USED') AS days_used,
               max(value) FILTER (WHERE field_key = 'TXN.SCHEDULE_TERMS') AS schedule_terms
          FROM contract_fields WHERE document_id = d.id
      ) cf
      WHERE d.horse_id = p_horse_id AND d.deleted_at IS NULL
        AND d.workflow_state = 'executed' AND is_horse_lease_template(ct.template_key)
      ORDER BY d.effective_date DESC NULLS LAST, d.created_at DESC
      LIMIT 1;
  END IF;

  -- The current (open) location row.
  SELECT jsonb_build_object('name', hl.name, 'address_line1', hl.address_line1,
      'city', hl.city, 'state', hl.state, 'postal', hl.postal,
      'keeping_spots', hl.keeping_spots, 'notes', hl.notes, 'sub_location', hl.sub_location, 'start_on', hl.start_on)
    INTO v_curr
    FROM horse_locations hl WHERE hl.horse_id = p_horse_id AND hl.end_on IS NULL
    ORDER BY hl.created_at DESC LIMIT 1;

  v_out := jsonb_build_object(
    'record', jsonb_build_object(
      'id', v_h.id, 'registered_name', v_h.registered_name, 'nickname', v_h.nickname,
      'breed', coalesce((SELECT display_name FROM horse_breeds WHERE code = v_h.breed), v_h.breed),
      'color', coalesce((SELECT display_name FROM horse_colors WHERE code = v_h.color), v_h.color),
      'markings', v_h.markings, 'sex', v_h.sex, 'date_of_birth', v_h.date_of_birth,
      'height', v_h.height, 'registration_number', v_h.registration_number,
      'registration_org', v_h.registration_org, 'microchip_id', v_h.microchip_id,
      'passport_number', v_h.passport_number, 'passport_country', v_h.passport_country,
      'fair_market_value', v_h.fair_market_value,
      'current_location', v_curr,
      'medical_history_list', v_h.medical_history_list,
      'behavioral_history_list', v_h.behavioral_history_list,
      'known_conditions_list', v_h.known_conditions_list,
      'training_history_list', v_h.training_history_list,
      'competition_history_list', v_h.competition_history_list,
      'injuries_to_humans', v_h.injuries_to_humans,
      'pending_fields', v_h.pending_fields,
      'euthanasia_authorization', v_h.euthanasia_authorization,
      'owner_name', coalesce((SELECT nullif(btrim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')),'') FROM contacts WHERE id = v_h.current_owner_contact_id), v_h.owner_name_text),
      'owner_email', (SELECT email FROM contacts WHERE id = v_h.current_owner_contact_id),
      'owner_phone', (SELECT phone FROM contacts WHERE id = v_h.current_owner_contact_id),
      'lessee_name', coalesce((SELECT nullif(btrim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')),'') FROM contacts WHERE id = v_h.lessee_contact_id), v_h.lessee_name_text),
      'lease_start', v_h.lease_start, 'lease_end', v_h.lease_end
    ),
    'viewer_is_lessee', (v_h.lessee_contact_id IS NOT NULL AND v_h.lessee_contact_id = current_contact_id()),
    'lease', v_lease,
    -- current active care providers
    'providers', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'type', r.relationship, 'role', r.provider_role, 'role_label', r.role_label,
        'name', coalesce(nullif(btrim(r.party_name_text),''),
                 (SELECT nullif(btrim(c.first_name||' '||c.last_name),'') FROM contacts c WHERE c.id = r.party_contact_id)),
        'business_name', r.business_name, 'phone', r.phone, 'email', r.email,
        'address_line1', r.address_line1, 'city', r.city, 'state', r.state, 'postal', r.postal,
        'linked', (r.party_contact_id IS NOT NULL))
        ORDER BY r.relationship, (r.provider_role='primary') DESC, r.created_at)
      FROM horse_relationships r
      WHERE r.horse_id = p_horse_id AND r.active
        AND r.relationship IN ('VET','FARRIER','TRAINER','GROOM','CARE_GIVER','EMERGENCY_CONTACT','OTHER')), '[]'::jsonb),
    -- provider history: ended providers, newest end first
    'provider_history', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'type', r.relationship, 'role', r.provider_role, 'role_label', r.role_label,
        'name', coalesce(nullif(btrim(r.party_name_text),''),
                 (SELECT nullif(btrim(c.first_name||' '||c.last_name),'') FROM contacts c WHERE c.id = r.party_contact_id)),
        'business_name', r.business_name, 'phone', r.phone,
        'created_at', r.created_at, 'ended_at', r.ended_at)
        ORDER BY r.ended_at DESC NULLS LAST)
      FROM horse_relationships r
      WHERE r.horse_id = p_horse_id AND NOT r.active
        AND r.relationship IN ('VET','FARRIER','TRAINER','GROOM','CARE_GIVER','EMERGENCY_CONTACT','OTHER')), '[]'::jsonb),
    -- location history: ended location rows, newest end first
    'location_history', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', hl.id, 'name', hl.name, 'address_line1', hl.address_line1, 'city', hl.city,
        'state', hl.state, 'postal', hl.postal, 'start_on', hl.start_on, 'end_on', hl.end_on)
        ORDER BY hl.end_on DESC NULLS LAST)
      FROM horse_locations hl WHERE hl.horse_id = p_horse_id AND hl.end_on IS NOT NULL), '[]'::jsonb),
    'medications', horse_medications_list(p_horse_id),
    'documents', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', d.id, 'title', d.title, 'display_code', d.display_code, 'status', d.status,
        'workflow_state', d.workflow_state, 'effective_date', d.effective_date, 'created_at', d.created_at)
        ORDER BY d.created_at DESC)
      FROM documents d WHERE d.horse_id = p_horse_id AND d.deleted_at IS NULL), '[]'::jsonb),
    'schedule', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'starts_at', b.starts_at, 'ends_at', b.ends_at,
        'status', b.status, 'location', coalesce(b.location, (SELECT name FROM locations WHERE id = b.location_id)),
        'notes', b.notes) ORDER BY b.starts_at DESC)
      FROM bookings b WHERE b.horse_id = p_horse_id), '[]'::jsonb),
    'sessions', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', b.id, 'kind', b.kind, 'offering', (SELECT name FROM offerings WHERE id = b.offering_id),
        'starts_at', b.starts_at, 'status', b.status,
        'location', coalesce(b.location, (SELECT name FROM locations WHERE id = b.location_id)),
        'activities', b.activity_log -> 'activities', 'report', coalesce(b.activity_log ->> 'text', b.notes))
        ORDER BY b.starts_at DESC)
      FROM bookings b WHERE b.horse_id = p_horse_id
        AND (b.activity_log IS NOT NULL OR coalesce(btrim(b.notes),'') <> '')), '[]'::jsonb),
    'purchases', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', pu.id, 'display_code', pu.display_code, 'amount', pu.amount,
        'status', pu.status, 'payment_status', pu.payment_status,
        'notes', pu.notes, 'paid_at', pu.paid_at, 'created_at', pu.created_at)
        ORDER BY pu.created_at DESC)
      FROM purchases pu WHERE pu.horse_id = p_horse_id AND pu.deleted_at IS NULL), '[]'::jsonb),
    -- the lessee layer: entries a (current or former) lessee created, attributed to
    -- them, each marked with the author's name. Hidden-by-owner entries are omitted
    -- from this (owner/staff) view. The owner's own lists above are untouched.
    'lessee_entries', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'kind', e.kind, 'data', e.data, 'created_at', e.created_at,
        'hidden', e.hidden_by_owner,
        'author', coalesce(nullif(btrim(c.first_name||' '||c.last_name),''), c.email, 'Lessee'),
        'author_contact_id', e.author_contact_id)
        ORDER BY e.created_at DESC)
      FROM horse_lessee_entries e
      JOIN contacts c ON c.id = e.author_contact_id
      WHERE e.horse_id = p_horse_id AND e.deleted_at IS NULL
        AND NOT e.hidden_by_owner), '[]'::jsonb),
    'lessee_hidden_count', (SELECT count(*) FROM horse_lessee_entries e
       WHERE e.horse_id = p_horse_id AND e.deleted_at IS NULL AND e.hidden_by_owner)
  );
  RETURN v_out;
END;
$$;


--
-- Name: horse_provider_value(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_provider_value(p_horse uuid, p_type text, p_part text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_part
    WHEN 'NAME'     THEN coalesce(nullif(btrim(r.party_name_text), ''),
                                  (SELECT nullif(btrim(c.first_name||' '||c.last_name),'') FROM contacts c WHERE c.id = r.party_contact_id))
    WHEN 'PHONE'    THEN r.phone
    WHEN 'BUSINESS' THEN r.business_name
    WHEN 'ADDRESS'  THEN nullif(btrim(concat_ws(', ', r.address_line1, r.city,
                            nullif(btrim(concat_ws(' ', r.state, r.postal)),''))), '')
    ELSE NULL END
  FROM horse_relationships r
  WHERE r.horse_id = p_horse AND r.relationship = p_type AND r.active
  ORDER BY (r.provider_role = 'primary') DESC, r.created_at DESC
  LIMIT 1;
$$;


--
-- Name: horse_section_entries(public.horses, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_section_entries(v_horse public.horses, p_section text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v_list jsonb; e jsonb; out jsonb := '[]'::jsonb; m record; fields jsonb;
BEGIN
  IF p_section IN ('MEDICATIONS','SUPPLEMENTS') THEN
    FOR m IN
      SELECT name, purpose, dosage, frequency, cost_per_dose, rx_required
        FROM horse_medications
       WHERE horse_id = v_horse.id AND deleted_at IS NULL
         AND kind = CASE WHEN p_section='SUPPLEMENTS' THEN 'SUPPLEMENT' ELSE 'MEDICATION' END
       ORDER BY sort_order, name
    LOOP
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'label', s.label,
        'value', CASE
          WHEN s.kind = 'bool' THEN
            CASE WHEN (to_jsonb(m)->>s.k)::boolean IS TRUE THEN 'Yes'
                 WHEN (to_jsonb(m)->>s.k)::boolean IS FALSE THEN 'No'
                 ELSE '' END
          ELSE coalesce(nullif(btrim(to_jsonb(m)->>s.k), ''), '') END
      ) ORDER BY s.ord), '[]'::jsonb)
        INTO fields
        FROM disclosure_section_spec(p_section) WITH ORDINALITY AS s(k, label, kind, ord);
      out := out || jsonb_build_array(fields);
    END LOOP;
    RETURN out;
  END IF;

  v_list := CASE p_section
    WHEN 'KNOWN_CONDITIONS'   THEN v_horse.known_conditions_list
    WHEN 'MEDICAL_HISTORY'    THEN v_horse.medical_history_list
    WHEN 'BEHAVIORAL_HISTORY' THEN v_horse.behavioral_history_list
    WHEN 'INJURIES_TO_HORSE'  THEN v_horse.injuries_to_horse
    ELSE '[]'::jsonb END;

  FOR e IN SELECT * FROM jsonb_array_elements(coalesce(v_list,'[]'::jsonb)) LOOP
    out := out || jsonb_build_array(disclosure_entry_fields(p_section, e));
  END LOOP;
  RETURN out;
END $$;


--
-- Name: horse_section_text_block(public.horses, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_section_text_block(v_horse public.horses, p_section text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE entries jsonb; e jsonb; f jsonb; lines text[] := ARRAY[]::text[]; n int := 0;
BEGIN
  entries := horse_section_entries(v_horse, p_section);
  FOR e IN SELECT * FROM jsonb_array_elements(entries) LOOP
    n := n + 1;
    lines := lines || ('Entry ' || n || ':');
    FOR f IN SELECT * FROM jsonb_array_elements(e) LOOP
      lines := lines || ('  ' || (f->>'label') || ': ' || (f->>'value'));
    END LOOP;
  END LOOP;
  IF n = 0 THEN RETURN ''; END IF;  -- gate yes with no entries: no block, reads clean
  RETURN '[[DISCLOSURE:' || p_section || ']]' || E'\n'
       || array_to_string(lines, E'\n') || E'\n'
       || '[[/DISCLOSURE]]';
END $$;


--
-- Name: horse_time_conflict(uuid, uuid, timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.horse_time_conflict(p_org uuid, p_horse uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_exclude_id uuid, p_exclude_series uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.org_id = p_org
      AND b.horse_id = p_horse
      AND b.status NOT IN ('cancelled','expired','draft')
      AND b.starts_at < p_end AND b.ends_at > p_start
      AND (p_exclude_id IS NULL OR b.id <> p_exclude_id)
      AND (p_exclude_series IS NULL OR b.series_id IS DISTINCT FROM p_exclude_series)
  )
$$;


--
-- Name: http_request_attribution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.http_request_attribution(OUT ip text, OUT user_agent text) RETURNS record
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_hdrs json;
BEGIN
  BEGIN
    v_hdrs := nullif(current_setting('request.headers', true), '')::json;
  EXCEPTION WHEN others THEN
    v_hdrs := NULL;
  END;
  ip         := nullif(trim(split_part(coalesce(v_hdrs ->> 'x-forwarded-for', ''), ',', 1)), '');
  user_agent := nullif(trim(coalesce(v_hdrs ->> 'user-agent', '')), '');
END;
$$;


--
-- Name: FUNCTION http_request_attribution(OUT ip text, OUT user_agent text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.http_request_attribution(OUT ip text, OUT user_agent text) IS 'Session attribution from PostgREST''s request.headers GUC: (ip = first x-forwarded-for hop, user_agent). NULLs when the GUC is absent/malformed (guarded current_setting).';


--
-- Name: inbound_open_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inbound_open_count() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  RETURN
    (SELECT count(*) FROM inbound_queue q
      WHERE q.org_id = current_org()
        AND q.status NOT IN ('converted', 'expired')
        AND NOT coalesce(q.already_converted, false))
    +
    (SELECT count(*) FROM support_requests
      WHERE org_id = current_org() AND status <> 'resolved');
END;
$$;


--
-- Name: FUNCTION inbound_open_count(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inbound_open_count() IS 'Open inbound work for the Dashboard nav badge: requests that are neither in a terminal status nor already converted (inbound_queue.already_converted is the single definition — do not restate it here or in the client), plus support requests not yet resolved. Deliberately the same predicate the dashboard lead band lists, so the badge and the list can never disagree.';


--
-- Name: inquiry_email_payload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inquiry_email_payload(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'request_id', r.id,
    'org_id', r.org_id,
    'contact_name', r.contact_name,
    'contact_email', r.contact_email,
    'contact_phone', r.contact_phone,
    'contact_method', r.contact_method,
    'category', r.category,
    'created_at', r.created_at,
    -- The SELECTIONS the staff email never carried (§C6) and the buyer's copy
    -- is mostly made of. Price comes from the CATALOG, not from the cart, so a
    -- stale browser cannot put a number in an email; a NULL price stays NULL
    -- and both emails render "Price on inquiry" from it.
    'selections', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'label', coalesce(rs.label, o.name),
               'price_amount', o.price_amount,
               'price_unit', o.price_unit)
             ORDER BY coalesce(rs.label, o.name))
        FROM request_selections rs
        LEFT JOIN offerings o ON o.id = rs.offering_id
       WHERE rs.request_id = r.id), '[]'::jsonb),
    'order', (
      SELECT jsonb_build_object('display_code', p.display_code, 'amount', p.amount,
                                'status', p.status, 'current_status', p.current_status)
        FROM purchases p
       WHERE p.request_id = r.id AND p.deleted_at IS NULL
       ORDER BY p.created_at LIMIT 1)
  )
  FROM requests r WHERE r.id = p_request_id;
$$;


--
-- Name: instructor_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instructor_options() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'user_id', x.user_id,
        'name',    x.name,
        'title',   x.title) ORDER BY x.name), '[]'::jsonb)
      FROM (
        SELECT p.user_id,
               coalesce(
                 nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
                 nullif(btrim(coalesce(p.display_name,'')), ''),
                 c.email, 'Staff') AS name,
               p.title
          FROM profiles p
          LEFT JOIN contacts c ON c.id = p.contact_id
         WHERE p.org_id = v_org
           AND coalesce(p.staff_active, false)
           AND p.role IN ('ADMIN','MANAGER','EMPLOYEE')
           AND (c.id IS NULL OR c.deleted_at IS NULL)
      ) x);
END;
$$;


--
-- Name: insurance_resolution_sync(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_resolution_sync(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vals        jsonb := '{}'::jsonb;
  r             record;
  v_sec         text;
  v_unresolved  boolean;
  v_any_unres   boolean := false;
  v_link        text;
  v_kind        text := 'insurance_unresolved';
  v_title       text := 'Insurance responsibility unresolved';
  v_body        text;
  u             uuid;
  v_created     int := 0;
  v_status      text;
BEGIN
  -- The tooltip / notification body, verbatim from spec F2.
  v_body := 'Neither party currently has this coverage. The contract cannot be '
         || 'signed until one party accepts financial responsibility for it. '
         || 'Only the accepting party can check their box: the Lessor checks '
         || 'the first, the Lessee checks the second. Checking a box is that '
         || 'party''s election and appears in the contract.';

  SELECT status INTO v_status FROM documents
   WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('skipped','unknown document'); END IF;

  -- Executed instruments are never re-notified or re-evaluated.
  IF v_status = 'EXECUTED' THEN
    RETURN jsonb_build_object('skipped','executed');
  END IF;

  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val
             FROM contract_fields WHERE document_id = p_document_id LOOP
    v_vals := v_vals || jsonb_build_object(r.field_key, r.val);
  END LOOP;

  FOREACH v_sec IN ARRAY ARRAY['GL','MORT','MED'] LOOP
    v_unresolved :=
         (v_vals ? ('TXN.' || v_sec || '_LESSOR_STATUS'))
     AND (v_vals ? ('TXN.' || v_sec || '_LESSEE_STATUS'))
     AND coalesce(v_vals ->> ('TXN.' || v_sec || '_LESSOR_STATUS'), '') = 'NONE'
     AND coalesce(v_vals ->> ('TXN.' || v_sec || '_LESSEE_STATUS'), '') = 'NONE'
     AND coalesce(v_vals ->> ('TXN.' || v_sec || '_NOT_REQUIRED'), '') <> 'YES'
     AND coalesce(v_vals ->> ('TXN.' || v_sec || '_LESSEE_RESPONSIBLE'), '') <> 'YES';
    IF v_unresolved THEN v_any_unres := true; END IF;
  END LOOP;

  v_link := '/app/contracts/' || p_document_id;

  IF v_any_unres THEN
    -- Producer: one notification per party. Dedupe on (user, kind, link) so a
    -- field edit that leaves the state unresolved does not restack alerts —
    -- this is the "transition INTO the unresolved state" the spec asks for.
    FOR u IN
      SELECT pr.user_id
        FROM document_parties dp
        JOIN profiles pr ON pr.contact_id = dp.contact_id
       WHERE dp.document_id = p_document_id AND pr.user_id IS NOT NULL
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM notifications n
         WHERE n.user_id = u AND n.kind = v_kind AND n.link = v_link
           AND n.read_at IS NULL
      ) THEN
        -- Inserted directly rather than via notify_user(). notify_user carries a
        -- staff/service_role fence, and SECURITY DEFINER preserves auth.uid(), so
        -- routing through it would make a PARTY's own legitimate election fail
        -- with 'not authorized to send notifications' — the producer must never
        -- be able to reject the edit that triggered it. This function is itself
        -- SECURITY DEFINER and stamps the TARGET user's org, exactly as
        -- notify_user does.
        INSERT INTO notifications (org_id, user_id, kind, title, body, link)
        SELECT coalesce(pr.org_id, current_org()), u, v_kind, v_title, v_body, v_link
          FROM profiles pr WHERE pr.user_id = u;
        v_created := v_created + 1;
      END IF;
    END LOOP;
  ELSE
    -- Resolver: every section resolved -> clear this contract's alerts via the
    -- existing resolve-by-link mechanism (3-arg signature, kind-scoped so
    -- unrelated notifications on the same link are untouched).
    PERFORM resolve_notifications_for_link(v_link, NULL, v_kind);
  END IF;

  RETURN jsonb_build_object(
    'document_id', p_document_id,
    'unresolved', v_any_unres,
    'notifications_created', v_created);

EXCEPTION WHEN others THEN
  -- A notification is bookkeeping ABOUT an edit; it must never be able to
  -- reject the edit itself. Any failure here is surfaced in the return value
  -- and logged, never raised into the caller's transaction.
  RAISE WARNING 'insurance_resolution_sync failed for %: %', p_document_id, SQLERRM;
  RETURN jsonb_build_object(
    'document_id', p_document_id,
    'unresolved', v_any_unres,
    'error', SQLERRM);
END;
$$;


--
-- Name: intake_requirements(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intake_requirements(p_channel text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_object_agg(field_key, required), '{}'::jsonb)
  FROM intake_requirements
  WHERE channel = p_channel
    AND org_id = coalesce(current_org(), current_addressed_org(), sole_org())
$$;


--
-- Name: invitation_expiry_days(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invitation_expiry_days(p_org uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT nullif(btrim(value_text), '')::int
       FROM config_values
      WHERE org_id = p_org AND namespace = 'INVITATIONS' AND key = 'EXPIRY_DAYS'),
    7);
$$;


--
-- Name: invitation_replacement_notice(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invitation_replacement_notice(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old     invitations%ROWTYPE;
  v_new     invitations%ROWTYPE;
  v_local   text;
  v_domain  text;
  v_masked  text;
BEGIN
  IF p_token IS NULL OR btrim(p_token) = '' THEN RETURN NULL; END IF;

  SELECT * INTO v_old FROM invitations WHERE token = p_token;
  IF NOT FOUND THEN RETURN NULL; END IF;
  -- still usable: the caller should be activating, not reading this page
  IF v_old.status = 'sent' AND v_old.expires_at > now() AND v_old.deleted_at IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_new FROM invitations i
   WHERE i.org_id = v_old.org_id
     AND lower(i.email) = lower(v_old.email)
     AND i.status = 'sent'
     AND i.expires_at > now()
     AND i.deleted_at IS NULL
   ORDER BY i.created_at DESC
   LIMIT 1;
  IF NOT FOUND THEN
    -- CLOSEOUT §1.3: no newer invitation to point at. If THIS link was already
    -- redeemed and the account exists, the right message is "sign in", not
    -- "check your inbox for a newer one".
    IF v_old.status = 'redeemed' AND EXISTS (
         SELECT 1 FROM profiles p WHERE lower(p.email) = lower(v_old.email)) THEN
      RETURN jsonb_build_object('already_activated', true);
    END IF;
    RETURN NULL;
  END IF;

  v_local  := split_part(v_new.email, '@', 1);
  v_domain := split_part(v_new.email, '@', 2);
  -- keep the first character and the last, mask the middle: enough for a person
  -- to recognise their own address, not enough to learn someone else's.
  v_masked := CASE
    WHEN length(v_local) <= 2 THEN left(v_local, 1) || '•••'
    ELSE left(v_local, 1) || repeat('•', greatest(length(v_local) - 2, 3)) || right(v_local, 1)
  END || '@' || v_domain;

  RETURN jsonb_build_object(
    'masked_email', v_masked,
    'sent_at',      v_new.created_at,
    'expires_at',   v_new.expires_at);
END;
$$;


--
-- Name: invitation_request_resend(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invitation_request_resend(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old   invitations%ROWTYPE;
  v_new   invitations%ROWTYPE;
  v_count int;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF p_token IS NULL OR btrim(p_token) = '' THEN
    RETURN jsonb_build_object('allowed', false);
  END IF;

  SELECT * INTO v_old FROM invitations WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false); END IF;

  SELECT * INTO v_new FROM invitations i
   WHERE i.org_id = v_old.org_id
     AND lower(i.email) = lower(v_old.email)
     AND i.status = 'sent'
     AND i.expires_at > now()
     AND i.deleted_at IS NULL
   ORDER BY i.created_at DESC
   LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false); END IF;

  SELECT count(*) INTO v_count
    FROM status_events e
   WHERE e.entity_type = 'account' AND e.entity_id = v_new.id
     AND e.status = 'resent' AND e.detail = 'self-service'
     AND e.created_at > now() - interval '1 hour';
  IF v_count >= 3 THEN
    RETURN jsonb_build_object('allowed', false, 'rate_limited', true);
  END IF;

  RETURN jsonb_build_object(
    'allowed',       true,
    'invitation_id', v_new.id,
    'email',         v_new.email,
    'token',         v_new.token,
    'expires_at',    v_new.expires_at);
END;
$$;


--
-- Name: invite_contract_counterparty(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_contract_counterparty(p_document_id uuid, p_contact_id uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_doc   documents%ROWTYPE;
  v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_id    uuid;
  v_role  text;
BEGIN
  -- staff of the document's org, or a service-role caller. The service-role arm is
  -- what lets the public /sign deal path reuse this instead of minting a second
  -- claim mechanism; the endpoint that calls it does its own matching and rate
  -- limiting, and can only ever reach a party who has no account yet.
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;
  IF NOT (coalesce(auth.role(), '') = 'service_role'
          OR coalesce(has_staff_access() AND v_doc.org_id = current_org(), false)) THEN
    RAISE EXCEPTION 'not authorized to invite a counterparty on document %', p_document_id;
  END IF;
  IF p_email IS NULL OR p_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RAISE EXCEPTION 'a valid email is required';
  END IF;
  -- the contact must be a party on the document (spine roster)
  IF NOT EXISTS (
    SELECT 1 FROM document_parties
    WHERE document_id = p_document_id AND contact_id = p_contact_id
  ) THEN
    RAISE EXCEPTION 'contact % is not a party on this contract', p_contact_id;
  END IF;

  -- SENDGUARD: never mint a signing invitation for someone who already signed.
  SELECT s.party_role INTO v_role
    FROM signatures s
   WHERE s.document_id = p_document_id
     AND s.signer_contact_id = p_contact_id
     AND s.deleted_at IS NULL
   ORDER BY s.signed_at NULLS LAST, s.created_at
   LIMIT 1;
  IF v_role IS NOT NULL THEN
    RAISE EXCEPTION 'this party has already signed this document as % — a new signing invitation cannot be sent', v_role
      USING ERRCODE = 'P0001',
            HINT = 'Their signature is on file. Open the document to see it.';
  END IF;

  INSERT INTO invitations (org_id, email, token, expires_at, status, kind, document_id, contact_id)
  VALUES (v_doc.org_id, lower(trim(p_email)), v_token, now() + interval '14 days',
          'sent', 'CONTRACT', p_document_id, p_contact_id)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'invitation_id', v_id, 'token', v_token,
    'document_id', p_document_id, 'expires_at', now() + interval '14 days');
END;
$_$;


--
-- Name: invite_contract_party_account(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_contract_party_account(p_document_id uuid, p_contact_id uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_doc   documents%ROWTYPE;
  v_email text := lower(btrim(p_email));
  v_inv   invitations%ROWTYPE;
  v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_days  integer;
  v_role  text;
  v_c     contacts%ROWTYPE;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  -- Same authorization arms as invite_contract_counterparty: staff of the
  -- document's org, or a service-role caller (the /api endpoint).
  IF NOT (coalesce(auth.role(), '') = 'service_role'
          OR coalesce(has_staff_access() AND v_doc.org_id = current_org(), false)) THEN
    RAISE EXCEPTION 'not authorized to invite a counterparty on document %', p_document_id;
  END IF;

  IF v_email IS NULL OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RAISE EXCEPTION 'a valid email is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM document_parties
     WHERE document_id = p_document_id AND contact_id = p_contact_id
  ) THEN
    RAISE EXCEPTION 'contact % is not a party on this contract', p_contact_id;
  END IF;

  -- SENDGUARD: never mint a signing invitation for someone who already signed.
  SELECT s.party_role INTO v_role
    FROM signatures s
   WHERE s.document_id = p_document_id
     AND s.signer_contact_id = p_contact_id
     AND s.deleted_at IS NULL
   ORDER BY s.signed_at NULLS LAST, s.created_at
   LIMIT 1;
  IF v_role IS NOT NULL THEN
    RAISE EXCEPTION 'this party has already signed this document as % — a new signing invitation cannot be sent', v_role
      USING ERRCODE = 'P0001',
            HINT = 'Their signature is on file. Open the document to see it.';
  END IF;

  -- C10: a minor cannot hold an account. The CONTRACT path never had to care —
  -- it only ever reached people who already had one. This one creates accounts,
  -- so it inherits the account rule.
  IF coalesce(is_minor_contact(p_contact_id), false) THEN
    RAISE EXCEPTION 'minors cannot be invited to hold accounts; invite the guardian';
  END IF;

  v_days := coalesce(nullif(invitation_expiry_days(v_doc.org_id), 0), 7);

  -- REUSE, in preference to issuing a second one.
  SELECT * INTO v_inv
    FROM invitations
   WHERE org_id = v_doc.org_id
     AND lower(email) = v_email
     AND coalesce(kind, 'COMMUNITY') = 'COMMUNITY'
     AND status IN ('sent', 'draft')
     AND deleted_at IS NULL
   ORDER BY created_at DESC
   LIMIT 1;

  IF FOUND THEN
    UPDATE invitations
       SET document_id = p_document_id,
           contact_id  = coalesce(contact_id, p_contact_id),
           status      = 'sent',
           -- never shorten a live window; a stale one is refreshed so the person
           -- being asked to sign has the configured time to do it
           expires_at  = greatest(expires_at, now() + make_interval(days => v_days))
     WHERE id = v_inv.id
     RETURNING * INTO v_inv;

    RETURN jsonb_build_object(
      'invitation_id', v_inv.id, 'token', v_inv.token,
      'expires_at', v_inv.expires_at, 'document_id', p_document_id, 'reused', true);
  END IF;

  SELECT * INTO v_c FROM contacts WHERE id = p_contact_id;

  INSERT INTO invitations (org_id, email, token, expires_at, status, kind,
                           document_id, contact_id, invited_role, first_name, last_name)
  VALUES (v_doc.org_id, v_email, v_token, now() + make_interval(days => v_days),
          'sent', 'COMMUNITY', p_document_id, p_contact_id, 'USER',
          nullif(btrim(coalesce(v_c.first_name, '')), ''),
          nullif(btrim(coalesce(v_c.last_name, '')), ''))
  RETURNING * INTO v_inv;

  RETURN jsonb_build_object(
    'invitation_id', v_inv.id, 'token', v_inv.token,
    'expires_at', v_inv.expires_at, 'document_id', p_document_id, 'reused', false);
END;
$_$;


--
-- Name: invited_account_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invited_account_state(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email       text;
  v_document_id uuid;
  v_user        record;
BEGIN
  -- Resolve the invitation by token (any kind, live or spent — a spent link still
  -- needs to route an existing account-holder correctly).
  SELECT lower(email), document_id INTO v_email, v_document_id
    FROM invitations WHERE token = p_token
   ORDER BY created_at DESC LIMIT 1;
  IF v_email IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT u.id, u.last_sign_in_at INTO v_user
    FROM auth.users u WHERE lower(u.email) = v_email LIMIT 1;

  RETURN jsonb_build_object(
    'found', true,
    'email', v_email,
    'document_id', v_document_id,
    -- an account exists for the invited email
    'has_account', v_user.id IS NOT NULL,
    -- it has had at least one session (established account → send to login)
    'has_session', coalesce(v_user.last_sign_in_at IS NOT NULL, false)
  );
END;
$$;


--
-- Name: is_active_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_member() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN auth.uid() IS NULL THEN false
    WHEN COALESCE((SELECT p.is_suspended FROM profiles p WHERE p.user_id = auth.uid()), false) THEN false
    WHEN is_admin() THEN true
    ELSE EXISTS (SELECT 1 FROM members m WHERE m.user_id = auth.uid() AND m.status = 'active')
  END;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(app_role() IN ('ADMIN','SUPER_ADMIN'), false)
$$;


--
-- Name: is_deal_governing_template(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_deal_governing_template(p_deal_type text, p_template_key text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE p_deal_type
    WHEN 'LEASE' THEN coalesce(is_horse_lease_template(p_template_key), false)
    WHEN 'SALE'  THEN p_template_key = 'HORSE_PURCHASE_SALE'
                   OR coalesce((SELECT ct.contract_kind FROM contract_templates ct
                                 WHERE ct.template_key = p_template_key
                                 ORDER BY ct.version DESC LIMIT 1), '')
                      IN ('HORSE_SALE', 'HORSE_BILL_OF_SALE')
    ELSE false
  END;
$$;


--
-- Name: is_horse_lease_template(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_horse_lease_template(p_template_key text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(
    (SELECT contract_kind = 'HORSE_LEASE' FROM contract_templates
      WHERE template_key = p_template_key
      ORDER BY version DESC LIMIT 1),
    p_template_key LIKE 'HORSE_LEASE%'  -- fallback if the template row is gone
  );
$$;


--
-- Name: FUNCTION is_horse_lease_template(p_template_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_horse_lease_template(p_template_key text) IS 'The one place "is this template a horse lease" gets decided. Every function below was patched to call this instead of comparing against the literal string ''HORSE_LEASE'' — add a new lease template key and it is automatically covered as long as contract_kind is set correctly.';


--
-- Name: is_minor_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_minor_contact(p_contact_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT date_of_birth IS NOT NULL AND date_of_birth + interval '18 years' > current_date
     FROM contacts WHERE id = p_contact_id),
    false
  );
$$;


--
-- Name: is_org_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_org_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(app_role() = 'ADMIN', false)
$$;


--
-- Name: FUNCTION is_org_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_org_admin() IS 'True only for an ADMIN profile. Fails closed on a NULL app_role() (NULLUID).';


--
-- Name: is_platform_profile(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_platform_profile(p_role text, p_org uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
