--
-- Name: is_protected_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_protected_contact(p_contact_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_contact_id = ANY (ARRAY[
           '75475f66-8950-4f13-832c-5471070737f8',
           '862b7936-9148-465c-b0db-b83246e236a0',
           '352c3898-65d0-4a90-ad59-29107b7e03fe',
           'c6f7cddc-69da-4948-8e62-4a310f079100'
         ]::uuid[])
      OR EXISTS (SELECT 1 FROM contacts c
                  WHERE c.id = p_contact_id AND c.is_company)
      OR EXISTS (SELECT 1 FROM profiles p
                  WHERE p.contact_id = p_contact_id
                    AND p.user_id = ANY (ARRAY[
                          'b45a5503-89bc-489a-b012-c7fbf5c09632',  -- admin@fhequestrian.com
                          'fdbdfe89-76d7-486b-b734-8e23b09e0353',  -- hello@fhequestrian.com
                          '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'   -- admin@cactai.io (platform)
                        ]::uuid[]));
$$;


--
-- Name: FUNCTION is_protected_contact(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_protected_contact(p_contact_id uuid) IS 'D1/D1a: the platform owner, the two production FHE staff identities and the tenant company contact are never archivable. Shared by archive_contact; purge_account keeps its own inlined copy on purpose.';


