-- Name: lease_expiry_nudge(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_expiry_nudge(p_days_ahead integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN lease_reminder_sweep();
END;
$$;


--
-- Name: lease_fee_payable(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_fee_payable(s jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    coalesce(money_numeric(coalesce(s->>'initial_due','')), 0) > 0
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(s->'options','[]'::jsonb)) o
       WHERE coalesce(money_numeric(coalesce(o->>'amount','')), 0) > 0),
    false);
$$;


--
-- Name: lease_participants_for_doc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_participants_for_doc(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'contact_id', lp.contact_id,
        'name', trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')),
        'days_used', lp.days_used, 'hours', lp.hours,
        'usage_pct', lp.usage_pct, 'payment_pct', lp.payment_pct) ORDER BY lp.created_at), '[]'::jsonb)
    FROM lease_participants lp JOIN contacts c ON c.id = lp.contact_id
    WHERE lp.document_id = p_document_id);
END;
$$;


--
-- Name: lease_payment_options_for_doc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_payment_options_for_doc(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (has_staff_access() OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'amount', amount, 'describe', describe) ORDER BY created_at), '[]'::jsonb)
    FROM lease_payment_options WHERE document_id = p_document_id);
END;
$$;


--
-- Name: lease_reminder_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_reminder_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d record;
  u uuid;
  v_kind text; v_title text; v_body text; v_link text; v_window interval;
  v_n int := 0;
BEGIN
  -- every executed lease with a start (â¤7d) or expiry (â¤30d) coming up
  FOR d IN
    SELECT dc.id AS doc_id, dc.org_id,
           coalesce(h.nickname, h.registered_name, 'the horse') AS hname,
           h.lease_start, h.lease_end
    FROM documents dc
    JOIN contract_templates t ON t.id = dc.template_id
    JOIN horses h ON h.id = dc.horse_id
    WHERE is_horse_lease_template(t.template_key) AND dc.status = 'EXECUTED'
      AND dc.deleted_at IS NULL AND h.deleted_at IS NULL
      AND (
        (h.lease_start IS NOT NULL AND h.lease_start BETWEEN current_date AND current_date + 7)
        OR (h.lease_end IS NOT NULL AND h.lease_end BETWEEN current_date AND current_date + 30)
      )
  LOOP
    IF d.lease_start IS NOT NULL AND d.lease_start BETWEEN current_date AND current_date + 7 THEN
      v_kind := 'lease_start'; v_window := interval '3 days';
      v_title := 'Lease start approaching';
      v_body := d.hname || ' â lease starts ' || to_char(d.lease_start, 'FMMonth FMDD') || '.';
    ELSE
      v_kind := 'lease_expiry'; v_window := interval '7 days';
      v_title := 'Lease expiring soon';
      v_body := d.hname || ' â lease ends ' || to_char(d.lease_end, 'FMMonth FMDD, YYYY') || '.';
    END IF;
    v_link := '/app/contracts/' || d.doc_id;

    -- recipients: every party of the lease + all staff/admin in the org
    FOR u IN
      SELECT pr.user_id
        FROM document_parties dp JOIN profiles pr ON pr.contact_id = dp.contact_id
       WHERE dp.document_id = d.doc_id AND pr.user_id IS NOT NULL
      UNION
      SELECT pr2.user_id FROM profiles pr2
       WHERE pr2.org_id = d.org_id
         AND coalesce(pr2.role,'USER') IN ('SUPER_ADMIN','ADMIN','MANAGER','EMPLOYEE')
         AND pr2.user_id IS NOT NULL
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.user_id = u AND n.kind = v_kind AND n.link = v_link
          AND n.created_at > now() - v_window
      ) THEN
        PERFORM notify_user(u, v_kind, v_title, v_body, v_link);
        v_n := v_n + 1;
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('notifications_created', v_n);
END;
$$;


--
-- Name: lease_sublease_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_sublease_allowed(p_horse_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    coalesce((SELECT sublease_allowed FROM horses WHERE id = p_horse_id), false)
    OR coalesce((
      SELECT lower(btrim(cf.value)) IN ('true','yes','1','checked','on')
      FROM documents dc
      JOIN contract_templates t ON t.id = dc.template_id
      JOIN contract_fields cf ON cf.document_id = dc.id AND cf.field_key = 'TXN.SUBLEASE_ALLOWED'
      WHERE dc.horse_id = p_horse_id AND is_horse_lease_template(t.template_key)
        AND dc.status = 'EXECUTED' AND dc.deleted_at IS NULL
      ORDER BY dc.effective_date DESC NULLS LAST, dc.created_at DESC
      LIMIT 1
    ), false)
$$;


--
-- Name: lesson_activity(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_activity(p_client_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(booking_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, client_id uuid, client_name text, horse_id uuid, horse_name text, service_type text, booking_status text, activities jsonb, report text, log_text text, plan_version integer, plan_focus text, media_count integer, form_status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH scope AS (
    SELECT coalesce(has_staff_access() AND current_org() IS NOT NULL, false) AS is_staff,
           current_client_id() AS me
  )
  SELECT b.id, b.starts_at, b.ends_at, b.client_id,
         nullif(btrim(coalesce(ct.first_name, '') || ' ' || coalesce(ct.last_name, '')), ''),
         b.horse_id,
         (SELECT coalesce(h.nickname, h.registered_name, h.display_code)
            FROM horses h WHERE h.id = b.horse_id),
         coalesce(bf.service_type, booking_service_type(b)),
         upper(b.status),
         coalesce(b.activity_log -> 'activities', '[]'::jsonb),
         b.notes,
         -- THE STAFF LANE. NULL for a rider reading their own log, by
         -- construction rather than by a caller remembering to drop it.
         CASE WHEN s.is_staff THEN b.activity_log ->> 'text' END,
         pl.version, pl.focus,
         (SELECT count(*)::int FROM file_links fl
           WHERE fl.subject_type = 'booking' AND fl.subject_id = b.id
             AND fl.deleted_at IS NULL),
         bf.status
    FROM scope s
    CROSS JOIN bookings b
    LEFT JOIN booking_forms bf ON bf.booking_id = b.id
    LEFT JOIN clients cl       ON cl.id = b.client_id
    LEFT JOIN contacts ct      ON ct.id = cl.contact_id
    LEFT JOIN lesson_plans pl  ON pl.id = bf.plan_id
   WHERE b.deleted_at IS NULL
     AND b.kind IN ('lesson', 'care')
     AND (
       (s.is_staff AND b.org_id = current_org())
       OR (s.me IS NOT NULL AND b.client_id = s.me)
     )
     AND (p_client_id IS NULL OR b.client_id = p_client_id)
     AND (p_horse_id  IS NULL OR b.horse_id  = p_horse_id)
     -- "has something on it": a write-up, a checked activity, a photo, or a
     -- finished form. An empty future lesson is on the schedule, not in the log.
     AND (
       nullif(btrim(coalesce(b.notes, '')), '') IS NOT NULL
       OR jsonb_array_length(coalesce(b.activity_log -> 'activities', '[]'::jsonb)) > 0
       OR nullif(btrim(coalesce(b.activity_log ->> 'text', '')), '') IS NOT NULL
       OR bf.status = 'submitted'
       OR EXISTS (SELECT 1 FROM file_links fl
                   WHERE fl.subject_type = 'booking' AND fl.subject_id = b.id
                     AND fl.deleted_at IS NULL)
     )
   ORDER BY b.starts_at DESC
   LIMIT greatest(1, least(coalesce(p_limit, 100), 500))
$$;


--
-- Name: lesson_forms(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_forms(p_scope text DEFAULT 'todo'::text) RETURNS TABLE(form_id uuid, booking_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, client_id uuid, client_name text, service_type text, booking_kind text, booking_status text, form_status text, has_answers boolean, submitted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT f.id, b.id, b.starts_at, b.ends_at, b.client_id,
         nullif(btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')), ''),
         f.service_type, b.kind, upper(b.status), f.status,
         NOT _booking_form_is_blank(f.answers), f.submitted_at
    FROM booking_forms f
    JOIN bookings b  ON b.id = f.booking_id
    LEFT JOIN clients cl ON cl.id = b.client_id
    LEFT JOIN contacts c ON c.id = cl.contact_id
   WHERE coalesce(has_staff_access() AND f.org_id = current_org(), false)
     AND CASE coalesce(p_scope, 'todo')
           -- the working list: a lesson that has already happened and whose form
           -- nobody has finished. Retired and submitted forms are out of it.
           WHEN 'todo'     THEN f.status = 'open' AND b.starts_at <= now()
           WHEN 'past'     THEN f.status <> 'retired' AND b.starts_at <= now()
           WHEN 'upcoming' THEN f.status <> 'retired' AND b.starts_at > now()
           WHEN 'retired'  THEN f.status = 'retired'
           ELSE true  -- 'all'
         END
   ORDER BY CASE WHEN coalesce(p_scope, 'todo') = 'upcoming' THEN b.starts_at END ASC,
            b.starts_at DESC
$$;


--
-- Name: lesson_media(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_media(p_booking_id uuid) RETURNS TABLE(file_id uuid, bucket_id text, storage_path text, filename text, mime_type text, title text, byte_size bigint, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT f.id, f.bucket_id, f.storage_path, f.filename, f.mime_type, f.title,
         f.byte_size, fl.created_at
    FROM file_links fl
    JOIN files f    ON f.id = fl.file_id AND f.deleted_at IS NULL
    JOIN bookings b ON b.id = fl.subject_id
   WHERE fl.subject_type = 'booking'
     AND fl.subject_id = p_booking_id
     AND fl.deleted_at IS NULL
     AND (coalesce(has_staff_access() AND b.org_id = current_org(), false)
          OR (b.client_id IS NOT NULL AND b.client_id = current_client_id()))
   ORDER BY fl.created_at
$$;


--
-- Name: lesson_plan_for_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_plan_for_booking(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b    bookings%ROWTYPE;
  v_plan lesson_plans%ROWTYPE;
  v_pin  uuid;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'lesson not found'; END IF;
  IF NOT coalesce(has_staff_access() AND v_b.org_id = current_org(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  v_plan := _lesson_plan_for_booking(p_booking_id);
  SELECT bf.plan_id INTO v_pin FROM booking_forms bf WHERE bf.booking_id = p_booking_id;

  RETURN jsonb_build_object(
    'booking_id', p_booking_id,
    'client_id',  v_b.client_id,
    'starts_at',  v_b.starts_at,
    'plan',       _lesson_plan_json(v_plan, true),
    'next_up',    lesson_plan_next_up(v_plan.objectives),
    -- true once this lesson has been written up: the plan shown is the one it
    -- was taught against and no longer moves when the client's plan advances.
    'pinned',     v_pin IS NOT NULL
  );
END;
$$;


--
-- Name: lesson_plan_next_up(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_plan_next_up(p_objectives jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT e.v
    FROM jsonb_array_elements(
           CASE WHEN jsonb_typeof(coalesce(p_objectives, '[]'::jsonb)) = 'array'
                THEN p_objectives ELSE '[]'::jsonb END)
         WITH ORDINALITY AS e(v, n)
   WHERE coalesce(e.v ->> 'state', 'planned') <> 'achieved'
   ORDER BY e.n
   LIMIT 1
$$;


--
-- Name: lesson_plan_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_plan_roster() RETURNS TABLE(client_id uuid, client_name text, plan_id uuid, plan_version integer, focus text, next_up text, objective_count integer, achieved_count integer, plan_updated_at timestamp with time zone, last_lesson_at timestamp with time zone, next_lesson_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT cl.id,
         nullif(btrim(coalesce(ct.first_name, '') || ' ' || coalesce(ct.last_name, '')), ''),
         pl.id, pl.version, pl.focus,
         lesson_plan_next_up(pl.objectives) ->> 'label',
         coalesce(jsonb_array_length(pl.objectives), 0),
         coalesce((SELECT count(*)::int FROM jsonb_array_elements(coalesce(pl.objectives, '[]'::jsonb)) e
                    WHERE e ->> 'state' = 'achieved'), 0),
         pl.created_at,
         (SELECT max(b.starts_at) FROM bookings b
           WHERE b.client_id = cl.id AND b.kind = 'lesson' AND b.deleted_at IS NULL
             AND b.starts_at <= now()),
         (SELECT min(b.starts_at) FROM bookings b
           WHERE b.client_id = cl.id AND b.kind = 'lesson' AND b.deleted_at IS NULL
             AND b.starts_at > now() AND b.status NOT IN ('cancelled', 'expired'))
    FROM clients cl
    LEFT JOIN contacts ct ON ct.id = cl.contact_id
    LEFT JOIN lesson_plans pl ON pl.client_id = cl.id AND pl.status = 'current'
   WHERE coalesce(has_staff_access() AND cl.org_id = current_org(), false)
     AND cl.deleted_at IS NULL
     AND (ct.id IS NULL OR ct.deleted_at IS NULL)
     AND (pl.id IS NOT NULL
          OR EXISTS (SELECT 1 FROM bookings b
                      WHERE b.client_id = cl.id AND b.kind = 'lesson'
                        AND b.deleted_at IS NULL))
   ORDER BY (SELECT min(b.starts_at) FROM bookings b
              WHERE b.client_id = cl.id AND b.kind = 'lesson' AND b.deleted_at IS NULL
                AND b.starts_at > now() AND b.status NOT IN ('cancelled', 'expired'))
            ASC NULLS LAST,
            cl.created_at DESC
$$;


--
-- Name: lesson_plans_for_day(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_plans_for_day(p_day date DEFAULT NULL::date) RETURNS TABLE(booking_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, client_id uuid, client_name text, booking_status text, service_type text, plan_id uuid, plan_version integer, focus text, next_up text, objectives jsonb, progress_recorded boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.id, b.starts_at, b.ends_at, b.client_id,
         nullif(btrim(coalesce(ct.first_name, '') || ' ' || coalesce(ct.last_name, '')), ''),
         upper(b.status),
         coalesce(bf.service_type, booking_service_type(b)),
         pl.id, pl.version, pl.focus,
         lesson_plan_next_up(pl.objectives) ->> 'label',
         coalesce(pl.objectives, '[]'::jsonb),
         bf.plan_id IS NOT NULL
    FROM bookings b
    LEFT JOIN booking_forms bf ON bf.booking_id = b.id
    LEFT JOIN clients cl       ON cl.id = b.client_id
    LEFT JOIN contacts ct      ON ct.id = cl.contact_id
    LEFT JOIN LATERAL (SELECT * FROM _lesson_plan_for_booking(b.id)) pl ON true
   WHERE coalesce(has_staff_access() AND b.org_id = current_org(), false)
     AND b.kind = 'lesson'
     -- booking_form_applies() already encodes "a serviced booking in a state
     -- that has something to record" (assigned, not deleted, not cancelled).
     -- Reusing it means the day view and the form backlog can never disagree
     -- about which lessons are real.
     AND booking_form_applies(b)
     AND b.starts_at::date = coalesce(p_day, current_date)
   ORDER BY b.starts_at
$$;


--
-- Name: line_item_hold_expired(public.line_item_state, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.line_item_hold_expired(p_state public.line_item_state, p_hold_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_state = 'approved_awaiting_claim'
     AND p_hold_expires_at IS NOT NULL
     AND p_hold_expires_at < now();
$$;


--
-- Name: link_contract_to_purchase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_contract_to_purchase(p_contract_id uuid, p_purchase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_buyer uuid;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM contracts WHERE id = p_contract_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'contract not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM purchases WHERE id = p_purchase_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'purchase not found';
  END IF;
  SELECT buyer_contact_id INTO v_buyer FROM purchases WHERE id = p_purchase_id;
  UPDATE contracts
     SET purchase_id = p_purchase_id,
         originator_contact_id = coalesce(originator_contact_id, current_contact_id())
   WHERE id = p_contract_id;
END;
$$;


--
-- Name: link_horse_provider(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_horse_provider(p_id uuid, p_contact uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff only'; END IF;
  UPDATE horse_relationships SET party_contact_id = p_contact
   WHERE id = p_id AND org_id = current_org();
END;
$$;


--
-- Name: list_booking_drafts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_booking_drafts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); v_out jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RETURN '[]'::jsonb; END IF;
  SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY x.updated_at DESC), '[]'::jsonb) INTO v_out
  FROM (
    SELECT b.id, b.kind, b.starts_at, b.ends_at, b.all_day, b.notes,
           b.client_id, b.horse_id, b.offering_id, b.location_id,
           b.created_at, b.updated_at,
           (SELECT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email)
              FROM clients cl JOIN contacts c ON c.id = cl.contact_id WHERE cl.id = b.client_id) AS client_name,
           (SELECT o.name FROM offerings o WHERE o.id = b.offering_id) AS offering_name,
           (SELECT h.nickname FROM horses h WHERE h.id = b.horse_id) AS horse_name
      FROM bookings b
     WHERE b.org_id = v_org AND b.deleted_at IS NULL AND b.status = 'draft'
  ) x;
  RETURN v_out;
END
$$;


--
-- Name: list_deals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_deals() RETURNS TABLE(id uuid, display_code text, title text, deal_type text, status text, badge jsonb, created_at timestamp with time zone, completed_at timestamp with time zone, party_summary text, horse_summary text, document_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.id, d.display_code, d.title, d.deal_type, d.status,
    deal_status(d.id), d.created_at, d.completed_at,
    (SELECT string_agg(DISTINCT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email), ', ')
       FROM contract_parties cp JOIN contacts c ON c.id = cp.contact_id
      WHERE cp.contract_id = d.contract_id),
    (SELECT coalesce(nullif(h.registered_name,''), h.nickname)
       FROM horses h JOIN contracts ct ON contract_horse_id(ct.id) = h.id WHERE ct.id = d.contract_id),
    (SELECT count(*) FROM documents doc
      WHERE doc.contract_id = d.contract_id AND doc.deleted_at IS NULL)
  FROM deals d
  WHERE d.deleted_at IS NULL
    AND ((coalesce(has_staff_access() AND d.org_id = current_org(), false))
      OR EXISTS (SELECT 1 FROM contract_parties cp
                  WHERE cp.contract_id = d.contract_id AND cp.contact_id = current_contact_id()))
  ORDER BY d.created_at DESC;
$$;


--
-- Name: list_service_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_service_types() RETURNS TABLE(code text, display_name text, description text, segment text, requires_horse boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT st.code, st.display_name, st.description, st.segment, st.requires_horse
  FROM service_types st
  WHERE st.active AND st.code <> 'ONBOARDING' AND has_staff_access()
  ORDER BY st.sort_order, st.display_name
$$;


--
-- Name: location_full_label(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_full_label(p_location_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    nullif(btrim(CASE
      -- structured address present: always "name — street, city, ST postal"
      WHEN nullif(compose_address(l.address_line1, NULL, l.city, l.state, l.postal), '') IS NOT NULL
        THEN concat_ws(' — ', nullif(btrim(l.name), ''),
                       compose_address(l.address_line1, NULL, l.city, l.state, l.postal))
      -- freeform address that already leads with the name: use it as-is
      WHEN nullif(btrim(l.address), '') IS NOT NULL
       AND lower(btrim(l.address)) LIKE lower(btrim(l.name)) || '%'
        THEN btrim(l.address)
      -- freeform address that does not name the facility: compose both
      WHEN nullif(btrim(l.address), '') IS NOT NULL
        THEN concat_ws(' — ', nullif(btrim(l.name), ''), btrim(l.address))
      ELSE btrim(coalesce(l.name, ''))
    END), ''),
    ''
  )
  FROM locations l WHERE l.id = p_location_id
$$;


--
-- Name: FUNCTION location_full_label(p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.location_full_label(p_location_id uuid) IS 'U2.5: a facility name plus its address. "FHE Main Barn Stall 12" is not an address on a legal instrument.';


--
-- Name: locations_match(jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.locations_match(p_a_struct jsonb, p_a_text text, p_b_struct jsonb, p_b_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH norm AS (
    SELECT
      lower(btrim(coalesce(p_a_struct->>'name',''))) AS a_name,
      lower(btrim(coalesce(p_b_struct->>'name',''))) AS b_name,
      -- strip punctuation/space so "Carmel Creek Ranch — …" and "Carmel Creek
      -- Ranch, …" compare equal on the leading identity
      lower(regexp_replace(coalesce(p_a_text,''), '[^a-z0-9]+', '', 'gi')) AS a_full,
      lower(regexp_replace(coalesce(p_b_text,''), '[^a-z0-9]+', '', 'gi')) AS b_full
  )
  SELECT CASE
    WHEN (a_full = '' OR b_full = '') THEN NULL          -- unknown: don't force a decision
    WHEN a_name <> '' AND b_name <> '' THEN a_name = b_name
    -- one side has no structured name (e.g. the horse's text-only current location):
    -- fall back to a prefix test so "<name>…" on each side still matches on identity
    WHEN a_name <> '' THEN b_full LIKE lower(regexp_replace(a_name,'[^a-z0-9]+','','gi')) || '%'
    WHEN b_name <> '' THEN a_full LIKE lower(regexp_replace(b_name,'[^a-z0-9]+','','gi')) || '%'
    ELSE a_full = b_full
  END
  FROM norm
$$;


--
-- Name: lock_and_sign_contract(uuid, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_and_sign_contract(p_document_id uuid, p_party_role text, p_typed_name text, p_esign_consent boolean DEFAULT false, p_signer_title text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state text; v_blockers jsonb; v_msgs text; v_signed boolean;
  v_org uuid; v_is_entity boolean; v_title text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT workflow_state, org_id INTO v_state, v_org
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF v_state NOT IN ('locked','editable') THEN
    IF v_state = 'executed' THEN
      RAISE EXCEPTION 'document is already executed; changing it requires signatures to be removed first';
    END IF;
    RAISE EXCEPTION 'document is not ready to sign (workflow_state=%); lock it first', v_state;
  END IF;

  -- ── CAPACITY, WRITTEN BY THE SIGNATURE ──────────────────────────────────
  -- Only for a party this contract treats as an ENTITY: an individual signs in
  -- their own name and has no capacity to declare. The typed signature name IS
  -- the signing individual's name — they are the same fact, typed once.
  SELECT coalesce(upper(btrim(cf.value)), '') = 'ENTITY' INTO v_is_entity
    FROM contract_fields cf
   WHERE cf.document_id = p_document_id
     AND cf.field_key = p_party_role || '.PARTY_TYPE';

  IF coalesce(v_is_entity, false) THEN
    v_title := nullif(btrim(coalesce(p_signer_title, '')), '');
    IF v_title IS NULL THEN
      RAISE EXCEPTION 'signing for % requires the title you sign in', p_party_role;
    END IF;

    INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                 value_type, is_optional, included, sort_order)
    VALUES
      (v_org, p_document_id, p_party_role || '.ENTITY_SIGNER_NAME',  'SYSTEM',
       btrim(p_typed_name), 'text', false, true, 0),
      (v_org, p_document_id, p_party_role || '.ENTITY_SIGNER_TITLE', 'SYSTEM',
       v_title, 'text', false, true, 0)
    ON CONFLICT (document_id, field_key) DO UPDATE
      SET value = EXCLUDED.value, updated_at = now()
      WHERE contract_fields.value IS DISTINCT FROM EXCLUDED.value;
  END IF;

  -- ONE function decides completeness. contract_lock_blockers carries the
  -- condition-aware required-field check, the open-change-request check, the
  -- LESSEE.PARTY_TYPE check, the horse-confirmation check and the
  -- document-before-contract wall — and it runs on every call, so a locked
  -- document altered after locking is caught here instead of signing anyway.
  -- It runs AFTER the capacity write above, which is the point: the signature
  -- supplies the last two fields rather than being blocked by them.
  v_blockers := contract_lock_blockers(p_document_id);
  IF jsonb_array_length(v_blockers) > 0 THEN
    SELECT string_agg(b->>'message', '; ') INTO v_msgs
      FROM jsonb_array_elements(v_blockers) b;
    RAISE EXCEPTION 'cannot sign: %', v_msgs;
  END IF;

  IF v_state = 'editable' THEN
    SELECT EXISTS (SELECT 1 FROM signatures
                   WHERE document_id = p_document_id AND deleted_at IS NULL
                     AND signed_at IS NOT NULL) INTO v_signed;
    IF NOT v_signed THEN
      -- ⚠️ THE DISPATCHER, NEVER `remerge_contract_from_fields` DIRECTLY: the flat
      -- composer reads a 23-character placeholder for every clause-composed
      -- template, and nothing here recomposes afterwards (20260826T0900).
      PERFORM remerge_contract_body(p_document_id);
    END IF;
  END IF;

  RETURN record_signature(p_document_id, p_party_role, p_typed_name, NULL, NULL,
                          coalesce(p_esign_consent, false));
END;
$$;


--
-- Name: log_contract_change(uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_contract_change(p_document_id uuid, p_change_kind text, p_field_key text DEFAULT NULL::text, p_field_label text DEFAULT NULL::text, p_owner_role text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid;
  v_label  text;
  v_roles  text[];
  v_staff  boolean;
  v_cid    uuid;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RETURN; END IF;   -- unknown/deleted doc: skip silently

  v_cid   := current_contact_id();
  v_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  BEGIN
    v_roles := ARRAY(SELECT r FROM caller_party_roles(p_document_id) r);
  EXCEPTION WHEN OTHERS THEN v_roles := '{}';
  END;
  SELECT nullif(trim(concat_ws(' ', first_name, last_name)), '')
    INTO v_label FROM contacts WHERE id = v_cid;

  INSERT INTO contract_change_log (
    org_id, document_id, change_kind, field_key, field_label, owner_role,
    old_value, new_value, detail, actor_contact_id, actor_label, actor_roles, actor_is_staff)
  VALUES (
    v_org, p_document_id, p_change_kind, p_field_key, p_field_label, p_owner_role,
    p_old_value, p_new_value, coalesce(p_detail,'{}'::jsonb),
    v_cid, coalesce(v_label, CASE WHEN v_staff THEN 'Staff' ELSE 'A party' END),
    coalesce(v_roles,'{}'), coalesce(v_staff,false));
EXCEPTION WHEN OTHERS THEN
  -- logging must never break a contract edit
  NULL;
END;
$$;


