--
-- Name: mark_purchase_paid(uuid, numeric, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_purchase_paid(p_purchase_id uuid, p_amount numeric, p_reference text DEFAULT NULL::text, p_method text DEFAULT 'zelle'::text, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_disposition text DEFAULT 'paid'::text, p_write_down_reason text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_pur       purchases%ROWTYPE;
  v_this      numeric;
  v_settled   numeric;
  v_covers    boolean;
  v_disp      text := lower(btrim(coalesce(p_disposition, 'paid')));
  v_reason    text := nullif(btrim(coalesce(p_write_down_reason, '')), '');
  v_down      numeric;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  -- TASK-BACKDATE: A FUTURE DATE IS NOT A BACKFILL. Refused here, because this
  -- function is reachable by `authenticated` directly over PostgREST.
  IF p_paid_at IS NOT NULL
     AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
       > (now()     AT TIME ZONE 'America/Los_Angeles')::date THEN
    RAISE EXCEPTION 'a payment cannot be dated in the future (%)',
      to_char(p_paid_at AT TIME ZONE 'America/Los_Angeles', 'YYYY-MM-DD');
  END IF;

  IF v_disp NOT IN ('paid', 'discounted', 'comped') THEN
    RAISE EXCEPTION 'unknown disposition: % (paid, discounted or comped)', p_disposition;
  END IF;
  -- D19: no reason, no give-away.
  IF v_disp <> 'paid' AND v_reason IS NULL THEN
    RAISE EXCEPTION 'a % order needs a reason — what was this given for?', v_disp;
  END IF;

  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown purchase: %', p_purchase_id; END IF;
  IF v_pur.payment_status = 'paid' THEN RETURN 'already_paid'; END IF;

  -- What was already settled BEFORE this act, from the payment records.
  SELECT coalesce(sum(amount), 0) INTO v_settled
    FROM payments
   WHERE purchase_id = p_purchase_id AND status = 'paid' AND deleted_at IS NULL;

  -- ── COMPED: the full price is written down; no money moves, so no payment
  --    record is written (payments.amount is CHECKed > 0 — there is nothing to
  --    record). The order keeps its full price; the customer owes $0.
  IF v_disp = 'comped' THEN
    IF coalesce(p_amount, 0) <> 0 THEN
      RAISE EXCEPTION 'a comp collects nothing — money collected is a discounted settlement';
    END IF;
    IF v_settled > 0 THEN
      RAISE EXCEPTION 'money was already collected on this order (%). Settle the remainder as discounted, not comped',
        to_char(v_settled, 'FM999999990.00');
    END IF;
    v_down := coalesce(v_pur.amount, 0);
    IF v_down <= 0 THEN
      RAISE EXCEPTION 'this order has no price to write down';
    END IF;

    UPDATE purchases p
       SET amount_paid         = 0,
           payment_method      = 'comp',
           payment_status      = 'paid',
           status              = 'paid',
           paid_at             = coalesce(p_paid_at, now()),
           payment_disposition = 'comped',
           write_down_amount   = v_down,
           write_down_reason   = v_reason
     WHERE p.id = p_purchase_id;

    PERFORM log_status_event('order', p_purchase_id, 'write_down',
      'Comped — ' || to_char(v_down, 'FM999999990.00')
        || ' written down; the full price stays on the order — ' || v_reason, v_pur.org_id);
    -- TASK-BACKDATE: a settlement dated before today RESOLVES the standing
    -- "payment due" notices (or a backfilled order owes money for ever) but
    -- ANNOUNCES nothing. The receipt email is suppressed one layer up, in
    -- api/orders-mark-paid.ts, which is the only thing that sends one.
    PERFORM _notify_purchase_paid(p_purchase_id,
      NOT (p_paid_at IS NOT NULL
           AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
             < (now()     AT TIME ZONE 'America/Los_Angeles')::date));
    IF p_paid_at IS NOT NULL
       AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
         < (now()     AT TIME ZONE 'America/Los_Angeles')::date THEN
      PERFORM log_status_event('order', p_purchase_id, 'paid',
        'Backdated settlement — recorded as of '
          || to_char(p_paid_at AT TIME ZONE 'America/Los_Angeles', 'FMMonth FMDD, YYYY')
          || '. No receipt or notice was sent.', v_pur.org_id);
    END IF;
    RETURN 'paid';
  END IF;

  -- ── DISCOUNTED: what arrives is recorded as an ordinary payment; the order
  --    then CLOSES with the shortfall stored as the write-down. This is what
  --    distinguishes a discount from a part payment: a part payment leaves the
  --    order open with a balance owed; a discount says the books are closed.
  IF v_disp = 'discounted' THEN
    v_this := coalesce(p_amount, 0);
    IF v_this <= 0 THEN
      RAISE EXCEPTION 'a discount that collects nothing is a comp — use the comped disposition';
    END IF;
    IF v_settled + v_this >= coalesce(v_pur.amount, 0) - 0.005 THEN
      RAISE EXCEPTION 'that collects the full % — nothing is being written down; mark it paid',
        to_char(coalesce(v_pur.amount, 0), 'FM999999990.00');
    END IF;

    PERFORM _payment_settle(p_purchase_id, coalesce(p_method, 'zelle'), p_reference, v_this, p_paid_at);
    v_down := coalesce(v_pur.amount, 0) - (v_settled + v_this);

    UPDATE purchases p
       SET amount_paid         = v_settled + v_this,
           payment_method      = lower(btrim(coalesce(p_method, 'zelle'))),
           payment_reference   = COALESCE(p.payment_reference, p_reference),
           payment_status      = 'paid',
           status              = 'paid',
           paid_at             = coalesce(p_paid_at, now()),
           payment_disposition = 'discounted',
           write_down_amount   = v_down,
           write_down_reason   = v_reason
     WHERE p.id = p_purchase_id;

    PERFORM log_status_event('order', p_purchase_id, 'write_down',
      'Discounted — collected ' || to_char(v_settled + v_this, 'FM999999990.00')
        || ' of ' || to_char(coalesce(v_pur.amount, 0), 'FM999999990.00')
        || '; ' || to_char(v_down, 'FM999999990.00') || ' written down — ' || v_reason, v_pur.org_id);
    -- TASK-BACKDATE: a settlement dated before today RESOLVES the standing
    -- "payment due" notices (or a backfilled order owes money for ever) but
    -- ANNOUNCES nothing. The receipt email is suppressed one layer up, in
    -- api/orders-mark-paid.ts, which is the only thing that sends one.
    PERFORM _notify_purchase_paid(p_purchase_id,
      NOT (p_paid_at IS NOT NULL
           AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
             < (now()     AT TIME ZONE 'America/Los_Angeles')::date));
    IF p_paid_at IS NOT NULL
       AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
         < (now()     AT TIME ZONE 'America/Los_Angeles')::date THEN
      PERFORM log_status_event('order', p_purchase_id, 'paid',
        'Backdated settlement — recorded as of '
          || to_char(p_paid_at AT TIME ZONE 'America/Los_Angeles', 'FMMonth FMDD, YYYY')
          || '. No receipt or notice was sent.', v_pur.org_id);
    END IF;
    RETURN 'paid';
  END IF;

  -- ── PAID: the pre-existing behaviour, unchanged — except that a ZERO-TOTAL
  --    order (a waived booking fee) now settles instead of raising: there is no
  --    money to record and nothing written down. apply_booking_fee has called
  --    this with (id, 0, reason, 'waived') since ZELLECLOSE; the >0 guard below
  --    made that call raise ever since the payments ledger arrived.
  v_this := coalesce(p_amount, greatest(coalesce(v_pur.amount, 0) - v_settled, 0));
  IF v_this <= 0 AND coalesce(v_pur.amount, 0) - v_settled <= 0 THEN
    UPDATE purchases p
       SET amount_paid       = v_settled,
           payment_method    = lower(btrim(coalesce(p_method, 'zelle'))),
           payment_reference = COALESCE(p.payment_reference, p_reference),
           payment_status    = 'paid',
           status            = 'paid',
           paid_at           = coalesce(p_paid_at, now())
     WHERE p.id = p_purchase_id;
    -- TASK-BACKDATE: a settlement dated before today RESOLVES the standing
    -- "payment due" notices (or a backfilled order owes money for ever) but
    -- ANNOUNCES nothing. The receipt email is suppressed one layer up, in
    -- api/orders-mark-paid.ts, which is the only thing that sends one.
    PERFORM _notify_purchase_paid(p_purchase_id,
      NOT (p_paid_at IS NOT NULL
           AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
             < (now()     AT TIME ZONE 'America/Los_Angeles')::date));
    IF p_paid_at IS NOT NULL
       AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
         < (now()     AT TIME ZONE 'America/Los_Angeles')::date THEN
      PERFORM log_status_event('order', p_purchase_id, 'paid',
        'Backdated settlement — recorded as of '
          || to_char(p_paid_at AT TIME ZONE 'America/Los_Angeles', 'FMMonth FMDD, YYYY')
          || '. No receipt or notice was sent.', v_pur.org_id);
    END IF;
    RETURN 'paid';
  END IF;
  IF v_this <= 0 THEN RAISE EXCEPTION 'a payment amount must be greater than zero'; END IF;
  IF v_settled + v_this > coalesce(v_pur.amount, 0) + 0.005 THEN
    RAISE EXCEPTION 'that would settle %, more than the order total of %',
      v_settled + v_this, v_pur.amount;
  END IF;

  -- the entry that says WHEN this money was marked paid, by WHOM, and HOW
  PERFORM _payment_settle(p_purchase_id, coalesce(p_method,'zelle'), p_reference, v_this, p_paid_at);

  v_covers := (v_settled + v_this) >= coalesce(v_pur.amount, 0) - 0.005;

  UPDATE purchases p
     SET amount_paid       = v_settled + v_this,
         payment_method    = lower(btrim(coalesce(p_method, 'zelle'))),
         payment_reference = COALESCE(p.payment_reference, p_reference),
         -- ⚠️ ONLY when the money is all in. A part-paid order is still open, and
         -- its entitlements are still gated on payment exactly as before.
         -- TASK-ORIGIN §4.3: the date a monthly report reads (revenue_summary
         -- filters on paid_at) — a backfilled sale states when it really
         -- happened, or this stays today's default exactly as before.
         payment_status    = CASE WHEN v_covers THEN 'paid' ELSE p.payment_status END,
         status            = CASE WHEN v_covers THEN 'paid' ELSE p.status END,
         paid_at           = CASE WHEN v_covers THEN coalesce(p_paid_at, now()) ELSE p.paid_at END
   WHERE p.id = p_purchase_id;

  IF NOT v_covers THEN
    PERFORM log_status_event('order', p_purchase_id, 'partial_payment',
      'Part payment of ' || to_char(v_this, 'FM999999990.00')
        || ' by ' || lower(btrim(coalesce(p_method,'zelle')))
        || ' — ' || to_char(coalesce(v_pur.amount,0) - (v_settled + v_this), 'FM999999990.00')
        || ' still outstanding', v_pur.org_id);
    RETURN 'part_paid';
  END IF;

  -- TASK-BACKDATE: a settlement dated before today RESOLVES the standing
    -- "payment due" notices (or a backfilled order owes money for ever) but
    -- ANNOUNCES nothing. The receipt email is suppressed one layer up, in
    -- api/orders-mark-paid.ts, which is the only thing that sends one.
    PERFORM _notify_purchase_paid(p_purchase_id,
      NOT (p_paid_at IS NOT NULL
           AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
             < (now()     AT TIME ZONE 'America/Los_Angeles')::date));
    IF p_paid_at IS NOT NULL
       AND (p_paid_at AT TIME ZONE 'America/Los_Angeles')::date
         < (now()     AT TIME ZONE 'America/Los_Angeles')::date THEN
      PERFORM log_status_event('order', p_purchase_id, 'paid',
        'Backdated settlement — recorded as of '
          || to_char(p_paid_at AT TIME ZONE 'America/Los_Angeles', 'FMMonth FMDD, YYYY')
          || '. No receipt or notice was sent.', v_pur.org_id);
    END IF;
  RETURN 'paid';
END;
$_$;


--
-- Name: mark_tour_seen(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_tour_seen(p_form_factor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  -- app.allow_profile_link lets this pass the role guard: the member is
  -- writing their own presentational marker, not an identity/employment field.
  PERFORM set_config('app.allow_profile_link', '1', true);
  IF p_form_factor = 'mobile' THEN
    UPDATE profiles
       SET tour_seen_mobile_at = coalesce(tour_seen_mobile_at, now()),
           tour_seen_at        = coalesce(tour_seen_at, now())
     WHERE user_id = auth.uid();
  ELSE
    UPDATE profiles
       SET tour_seen_desktop_at = coalesce(tour_seen_desktop_at, now()),
           tour_seen_at         = coalesce(tour_seen_at, now())
     WHERE user_id = auth.uid();
  END IF;
END;
$$;


--
-- Name: match_account_by_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_account_by_email(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count int; v_name text; v_org uuid := current_org();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  DELETE FROM email_lookup_attempts WHERE attempted_at < now() - interval '10 minutes';
  SELECT count(*) INTO v_count FROM email_lookup_attempts WHERE user_id = auth.uid();
  IF v_count >= 10 THEN RETURN jsonb_build_object('rate_limited', true); END IF;
  INSERT INTO email_lookup_attempts (user_id) VALUES (auth.uid());

  SELECT nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')),'')
    INTO v_name
    FROM contacts c JOIN profiles pr ON pr.contact_id = c.id
   WHERE c.org_id = v_org AND c.deleted_at IS NULL
     AND lower(c.email) = lower(btrim(p_email))
   LIMIT 1;
  IF v_name IS NULL THEN RETURN jsonb_build_object('matched', false); END IF;
  RETURN jsonb_build_object('matched', true, 'display_name', v_name);
END;
$$;


--
-- Name: med_party_who(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.med_party_who(p_party text, p_note text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN upper(coalesce(p_party,'')) = 'OTHER'
              THEN coalesce(nullif(btrim(p_note),''), 'Other')
              ELSE party_label(p_party) END;
$$;


--
-- Name: member_directory_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_directory_list(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, display_name text, first_name text, avatar_url text, bio text, riding_level text, community_email text, mobile_call text, mobile_text text, whatsapp_call text, whatsapp_text text, social_tiktok text, social_instagram text, social_facebook text, social_linkedin text, is_horse_owner boolean, preferred_contact text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Gate 1 — no anonymous reads.
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;

  -- Gate 2 — a suspended caller reads nothing.
  IF COALESCE((SELECT p2.is_suspended FROM profiles p2 WHERE p2.user_id = auth.uid()), false) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    p.user_id,
    p.display_name,
    COALESCE(p.first_name, c.first_name)                                        AS first_name,
    p.avatar_url,
    p.bio,
    p.riding_level,
    CASE WHEN c.hide_community_email THEN NULL ELSE c.community_email END       AS community_email,
    CASE WHEN c.hide_mobile_call     THEN NULL ELSE c.mobile_call     END       AS mobile_call,
    CASE WHEN c.hide_mobile_text     THEN NULL ELSE c.mobile_text     END       AS mobile_text,
    CASE WHEN c.hide_whatsapp_call   THEN NULL ELSE c.whatsapp_call   END       AS whatsapp_call,
    CASE WHEN c.hide_whatsapp_text   THEN NULL ELSE c.whatsapp_text   END       AS whatsapp_text,
    c.social_tiktok,
    c.social_instagram,
    c.social_facebook,
    c.social_linkedin,
    EXISTS (
      SELECT 1 FROM horses h
      WHERE h.current_owner_contact_id = p.contact_id AND h.deleted_at IS NULL
    )                                                                           AS is_horse_owner,
    CASE
      WHEN c.preferred_contact = 'email'     AND (c.hide_community_email OR c.community_email IS NULL) THEN 'none'
      WHEN c.preferred_contact = 'sms'       AND (c.hide_mobile_text     OR c.mobile_text     IS NULL) THEN 'none'
      WHEN c.preferred_contact = 'call'      AND (c.hide_mobile_call     OR c.mobile_call     IS NULL) THEN 'none'
      WHEN c.preferred_contact = 'whatsapp'  AND (c.hide_whatsapp_text   OR c.whatsapp_text   IS NULL) THEN 'none'
      WHEN c.preferred_contact = 'instagram' AND c.social_instagram IS NULL THEN 'none'
      WHEN c.preferred_contact = 'facebook'  AND c.social_facebook  IS NULL THEN 'none'
      WHEN c.preferred_contact = 'linkedin'  AND c.social_linkedin  IS NULL THEN 'none'
      WHEN c.preferred_contact = 'tiktok'    AND c.social_tiktok    IS NULL THEN 'none'
      ELSE c.preferred_contact
    END                                                                         AS preferred_contact
  FROM profiles p
  JOIN members  m ON m.user_id = p.user_id AND m.status = 'active'
  JOIN contacts c ON c.id = p.contact_id AND c.deleted_at IS NULL
  WHERE NOT p.is_suspended
    AND p.role IS DISTINCT FROM 'SUPER_ADMIN'
    AND (p_user_id IS NULL OR p.user_id = p_user_id)
  ORDER BY p.display_name NULLS LAST, p.user_id;
END;
$$;


--
-- Name: FUNCTION member_directory_list(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.member_directory_list(p_user_id uuid) IS 'SECFIX2 G2. Community member directory. SECURITY DEFINER because the directory is a cross-row read that RLS cannot express (profiles_select_own / contacts_select restrict a non-admin to their own row). Gates itself: no anonymous caller, no suspended caller. Enforces the contacts.hide_* flags. Does NOT return the legacy email/mobile/whatsapp columns. Replaces the member_directory view, whose security_invoker was off.';


--
-- Name: member_display_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_display_name(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    nullif(btrim(coalesce(first_name,'')), ''),
    nullif(btrim(coalesce(display_name,'')), ''),
    'A member'
  ) FROM profiles WHERE user_id = p_user_id;
$$;


--
-- Name: member_horses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_horses(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'name', coalesce(nullif(btrim(h.nickname),''), h.registered_name),
      'home_location', horse_current_location_label(h.id))
      ORDER BY h.created_at), '[]'::jsonb)
  FROM horses h
  JOIN profiles p ON p.contact_id = h.current_owner_contact_id
  WHERE p.user_id = p_user_id AND h.deleted_at IS NULL;
$$;


--
-- Name: members_post_join_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.members_post_join_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN RETURN NEW; END IF;

  v_org := coalesce(NEW.org_id, (SELECT org_id FROM profiles WHERE user_id = NEW.user_id));
  IF v_org IS NULL THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM feed_posts
    WHERE author_id = NEW.user_id AND post_type = 'member_joined'
  ) THEN
    INSERT INTO feed_posts (org_id, author_id, post_type, body, visibility, published)
    VALUES (v_org, NEW.user_id, 'member_joined',
            member_display_name(NEW.user_id) || ' just joined the community.',
            'members', true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: menu_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_inventory() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(m ORDER BY m->>'label'), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
             'source', 'vocabulary', 'menu_key', k.key, 'label', k.label,
             'used_by', k.used_by,
             'total', k.total, 'active', k.active) AS m
      FROM (
        SELECT 'horse_breeds' AS key, 'Horse breed' AS label,
               'Horse records · horse intake · contracts' AS used_by,
               count(*) AS total, count(*) FILTER (WHERE active) AS active
          FROM horse_breeds
        UNION ALL
        SELECT 'horse_colors', 'Horse color', 'Horse records · horse intake · contracts',
               count(*), count(*) FILTER (WHERE active) FROM horse_colors
        UNION ALL
        SELECT lo.lookup_key,
               initcap(replace(replace(lo.lookup_key, 'horse_', 'Horse '), '_', ' ')),
               -- TASK-ORIGIN §5 T3: every lookup_options key used to be labelled
               -- 'Horse intake · contracts' regardless of what it actually feeds.
               -- Minimal CASE, not a restructure (§8 explicitly rules that out).
               CASE lo.lookup_key
                 WHEN 'client_origin'   THEN 'Contact & client record'
                 WHEN 'contact_channel' THEN 'Contact & client record'
                 ELSE 'Horse intake · contracts'
               END,
               count(*), count(*) FILTER (WHERE lo.active)
          FROM lookup_options lo GROUP BY lo.lookup_key
      ) k
    UNION ALL
    SELECT jsonb_build_object(
             'source', 'form', 'menu_key', fd.form_key || '::' || (f->>'key'),
             'label', (f->>'label'), 'form_key', fd.form_key, 'field_key', (f->>'key'),
             'used_by', fd.title,
             'total', jsonb_array_length(f->'options'),
             'active', jsonb_array_length(f->'options'))
      FROM form_definitions fd,
           LATERAL jsonb_array_elements(fd.schema->'sections') s,
           LATERAL jsonb_array_elements(s->'fields') f
     WHERE fd.active AND f ? 'options'
  ) all_menus;
$$;


--
-- Name: menu_vocabulary_values(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_vocabulary_values(p_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_key = 'horse_breeds' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('code', code, 'display_name', display_name,
             'active', active) ORDER BY display_name), '[]'::jsonb) INTO v FROM horse_breeds;
  ELSIF p_key = 'horse_colors' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('code', code, 'display_name', display_name,
             'active', active) ORDER BY display_name), '[]'::jsonb) INTO v FROM horse_colors;
  ELSE
    SELECT coalesce(jsonb_agg(jsonb_build_object('code', code, 'display_name', display_name,
             'active', active) ORDER BY display_name), '[]'::jsonb) INTO v
      FROM lookup_options WHERE lookup_key = p_key;
  END IF;
  RETURN v;
END;
$$;


--
-- Name: mint_recurring_allotments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mint_recurring_allotments() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month date := date_trunc('month', current_date)::date;
  v_target date := plan_horizon_through();
  v_considered int := 0;
  v_credits    int := 0;
  v_booked     int := 0;
  v_plans_gen  int := 0;
  v_res        jsonb;
  r            record;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  FOR r IN
    SELECT pi.id
      FROM purchase_items pi
      JOIN offerings o  ON o.id = pi.offering_id AND o.config_kind = 'recurring'
      JOIN purchases pu ON pu.id = pi.purchase_id
     WHERE pu.deleted_at IS NULL
       AND pi.voided_at IS NULL
       AND pu.status <> 'draft'
       -- a staff caller rolls their own tenant only; a service_role caller rolls all.
       AND (coalesce(auth.role(), '') = 'service_role' OR pu.org_id = current_org())
       -- a FIXED-WEEK plan stops when its weeks are up; an INDEFINITE one
       -- (plan_ends_on IS NULL) keeps rolling until someone stops it.
       AND (pi.plan_ends_on IS NULL OR pi.plan_ends_on >= v_month)
  LOOP
    v_considered := v_considered + 1;
    v_res := _ensure_plan_horizon(r.id, v_target);
    IF coalesce((v_res->>'ok')::boolean, false) THEN
      v_credits   := v_credits + coalesce((v_res->>'minted')::int, 0);
      v_booked    := v_booked  + coalesce((v_res->>'created')::int, 0);
      v_plans_gen := v_plans_gen + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('month', v_month, 'through', v_target,
                            'plans_considered', v_considered,
                            'credits_minted', v_credits,
                            'plans_generated', v_plans_gen,
                            'sessions_booked', v_booked);
END;
$$;


--
-- Name: FUNCTION mint_recurring_allotments(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mint_recurring_allotments() IS 'CREDITALIGN: the month roll. Mints the current month''s allotment for every paid, unstopped recurring plan line that has not got one yet. Idempotent (the unique index on (purchase_item_id, period_start) is the real guard). Run daily from /api/mint-monthly-allotments; also safe for staff to invoke.';


--
-- Name: mirror_admin_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_admin_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- only mirror org/client events, and only when the recipient is themselves an
  -- admin/owner (so client-facing alerts to clients are never copied to staff).
  IF notification_is_personal(NEW.kind) THEN RETURN NEW; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = NEW.user_id AND p.org_id = NEW.org_id
       AND coalesce(p.role,'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN')
  ) THEN RETURN NEW; END IF;

  -- fan out to every OTHER admin/owner in the org, skipping any who already have
  -- this exact alert (keeps it idempotent and prevents trigger recursion loops).
  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
  SELECT NEW.org_id, p.user_id, NEW.kind, NEW.title, NEW.body, NEW.link
    FROM profiles p
   WHERE p.org_id = NEW.org_id
     AND p.user_id <> NEW.user_id
     AND coalesce(p.role,'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN')
     AND NOT EXISTS (
       SELECT 1 FROM notifications n2
        WHERE n2.user_id = p.user_id AND n2.org_id = NEW.org_id
          AND n2.kind = NEW.kind
          AND coalesce(n2.link,'') = coalesce(NEW.link,'')
          AND n2.created_at > now() - interval '1 minute'
     );
  RETURN NEW;
END $$;


--
-- Name: money_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.money_numeric(p_raw text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_raw IS NULL THEN NULL
    WHEN btrim(regexp_replace(p_raw, '[^0-9.\-]', '', 'g')) IN ('', '-', '.', '-.') THEN NULL
    ELSE btrim(regexp_replace(p_raw, '[^0-9.\-]', '', 'g'))::numeric
  END
$$;


--
-- Name: FUNCTION money_numeric(p_raw text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.money_numeric(p_raw text) IS 'Extracts the numeric value from any money-shaped string. NULL when no number is present. Paired with fmt_money for render.';


--
-- Name: money_shape_violation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.money_shape_violation(p_format text, p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE v jsonb;
BEGIN
  IF p_value IS NULL OR btrim(p_value) = '' THEN RETURN NULL; END IF;  -- unset is always legal

  IF p_format = 'currency' THEN
    -- canonical: a bare numeric. '$45,000.00' and '1,200' are rejected so the
    -- symbol and separators can only ever come from fmt_money at render.
    IF btrim(p_value) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN RETURN NULL; END IF;
    RETURN format('currency fields store a bare number (e.g. 45000), not %L — the $ and separators are applied at render', p_value);

  ELSIF p_format = 'fee_schedule' THEN
    -- canonical: the {initial_due, initial_terms?, options[], selected} object.
    BEGIN
      v := p_value::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RETURN format('fee_schedule fields store a JSON object, not %L — a bare amount or rendered prose is not a valid value', p_value);
    END;
    IF jsonb_typeof(v) <> 'object' THEN
      RETURN format('fee_schedule fields store a JSON object, not a %s', jsonb_typeof(v));
    END IF;
    -- a rendered-prose round-trip is the specific defect this guard exists for
    IF p_value ~ 'Initial payment due:' THEN
      RETURN 'that is rendered output, not a stored value — save the fee schedule, not its rendering';
    END IF;
    RETURN NULL;
  END IF;

  RETURN NULL;
END;
$_$;


--
-- Name: FUNCTION money_shape_violation(p_format text, p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.money_shape_violation(p_format text, p_value text) IS 'U2.1c door guard: NULL when a money value is canonical for its format_type, else the rejection reason.';


--
-- Name: mute_notification_category(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mute_notification_category(p_category text, p_muted boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_muted THEN
    INSERT INTO notification_mutes (user_id, category) VALUES (auth.uid(), p_category)
    ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM notification_mutes WHERE user_id = auth.uid() AND category = p_category;
  END IF;
END
$$;


--
-- Name: my_acquisition_intake_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_acquisition_intake_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_pending jsonb;
BEGIN
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('pending', '[]'::jsonb, 'needs_intake', false);
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'purchase_item_id', pi.id,
           'offering_id', pi.offering_id,
           'label', pi.label,
           'config_kind', o.config_kind
         ) ORDER BY pu.created_at), '[]'::jsonb)
    INTO v_pending
    FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
   WHERE (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid())
     AND coalesce(pu.status, '') <> 'void'
     AND pu.deleted_at IS NULL
     AND o.config_kind IN ('intake_finder', 'intake_evaluation')
     -- "not yet filled": no meaningful keys captured on the line config
     AND (pi.config IS NULL OR pi.config = '{}'::jsonb OR NOT (pi.config ? 'submitted_at'));

  RETURN jsonb_build_object(
    'pending', v_pending,
    'needs_intake', jsonb_array_length(v_pending) > 0);
END;
$$;


--
-- Name: my_contract_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_contract_documents() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me    uuid := current_contact_id();
  v_staff boolean := has_staff_access();
  v_org   uuid := current_org();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  IF v_staff AND v_org IS NOT NULL THEN
    RETURN coalesce((
      SELECT jsonb_agg(row_to_json(t) ORDER BY t.generated_at DESC)
      FROM (
        SELECT DISTINCT
          d.id AS document_id, d.title, d.status, d.workflow_state,
          d.recipient_editing, d.execution_hash, d.generated_at, d.sent_at,
          d.archived_at, d.voided_at, d.void_reason,
          (SELECT dpa.archived_at FROM document_party_archives dpa
            WHERE dpa.document_id = d.id AND dpa.contact_id = v_me) AS my_archived_at,
          (SELECT dph.hidden_at FROM document_party_hidden dph
            WHERE dph.document_id = d.id AND dph.contact_id = v_me) AS my_hidden_at,
          (d.originator_contact_id = v_me) AS is_originator,
          (SELECT string_agg(dp.party_role, ',' ORDER BY dp.party_role)
             FROM document_parties dp
            WHERE dp.document_id = d.id AND dp.contact_id = v_me) AS my_roles,
          (SELECT count(*) FROM contract_change_requests cr
            WHERE cr.document_id = d.id AND cr.parent_request_id IS NULL
              AND cr.submitted_at IS NOT NULL AND cr.resolved_at IS NULL) AS open_change_requests
        FROM documents d
        WHERE d.deleted_at IS NULL
          AND d.org_id = v_org
          AND EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
      ) t
    ), '[]'::jsonb);
  END IF;

  IF v_me IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(t) ORDER BY t.generated_at DESC)
    FROM (
      SELECT DISTINCT
        d.id AS document_id, d.title, d.status, d.workflow_state,
        d.recipient_editing, d.execution_hash, d.generated_at, d.sent_at,
        d.archived_at, d.voided_at, d.void_reason,
        (SELECT dpa.archived_at FROM document_party_archives dpa
          WHERE dpa.document_id = d.id AND dpa.contact_id = v_me) AS my_archived_at,
        NULL::timestamptz AS my_hidden_at,
        (d.originator_contact_id = v_me) AS is_originator,
        (SELECT string_agg(dp.party_role, ',' ORDER BY dp.party_role)
           FROM document_parties dp
          WHERE dp.document_id = d.id AND dp.contact_id = v_me) AS my_roles,
        (SELECT count(*) FROM contract_change_requests cr
          WHERE cr.document_id = d.id AND cr.parent_request_id IS NULL
            AND cr.submitted_at IS NOT NULL AND cr.resolved_at IS NULL) AS open_change_requests
      FROM documents d
      JOIN document_parties dp2 ON dp2.document_id = d.id
      WHERE d.deleted_at IS NULL
        AND dp2.contact_id = v_me
        AND EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
        AND NOT EXISTS (SELECT 1 FROM document_party_hidden dph
                         WHERE dph.document_id = d.id AND dph.contact_id = v_me)
    ) t
  ), '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION my_contract_documents(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_contract_documents() IS 'The caller''s contract documents (those carrying structured contract_fields where they are a party): document_id, title, status, workflow_state, recipient_editing, execution_hash, is_originator, my_roles (csv), open_change_requests. jsonb array, newest first. The list read model a UI binds to.';


--
-- Name: my_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_documents() RETURNS TABLE(document_id uuid, template_key text, title text, kind text, signed_at timestamp with time zone, current_status text, superseded boolean, created_at timestamp with time zone, executed_email_sent_at timestamp with time zone, is_contract boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- pending (generated but unsigned)
  SELECT d.id, ct.template_key, ct.title, 'pending'::text,
         NULL::timestamptz, d.current_status, false, d.created_at, NULL::timestamptz,
         EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
    FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
   WHERE (d.contact_id = current_contact_id() OR caller_is_document_party(d.id))
     AND d.deleted_at IS NULL
     AND d.status <> 'EXECUTED' AND coalesce(d.current_status,'') <> 'void'
  UNION ALL
  -- assigned but not yet generated (a placeholder: there is no document yet, so
  -- it is not a contract)
  SELECT NULL::uuid, crd.template_key, ct.title, 'assigned'::text,
         NULL::timestamptz, 'assigned', false, now(), NULL::timestamptz,
         false
    FROM contact_required_documents crd
    JOIN contract_templates ct ON ct.template_key = crd.template_key AND ct.active AND ct.deleted_at IS NULL
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key AND x.active AND x.deleted_at IS NULL)
   WHERE crd.contact_id = current_contact_id()
     AND NOT EXISTS (SELECT 1 FROM documents d JOIN contract_templates ct2 ON ct2.id = d.template_id
                      WHERE d.contact_id = crd.contact_id AND d.deleted_at IS NULL
                        AND ct2.template_key = crd.template_key
                        AND (d.status <> 'EXECUTED' OR (d.status = 'EXECUTED' AND coalesce(d.current_status,'') <> 'superseded')))
  UNION ALL
  -- executed, signing order (newest last → FE may reverse per page convention)
  SELECT d.id, ct.template_key, ct.title, 'executed'::text,
         (SELECT max(s.signed_at) FROM signatures s WHERE s.document_id = d.id AND s.deleted_at IS NULL),
         d.current_status, (d.current_status = 'superseded'), d.created_at, d.executed_email_sent_at,
         EXISTS (SELECT 1 FROM contract_fields cf WHERE cf.document_id = d.id)
    FROM documents d JOIN contract_templates ct ON ct.id = d.template_id
   WHERE (d.contact_id = current_contact_id() OR caller_is_document_party(d.id))
     AND d.deleted_at IS NULL
     AND d.status = 'EXECUTED'
   ORDER BY 4 DESC, 8;
$$;


--
-- Name: my_evaluation_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_evaluation_reports() RETURNS TABLE(id uuid, title text, horse_label text, body text, delivered_at timestamp with time zone, available_until timestamp with time zone, is_shared boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.title, r.horse_label, r.body, r.delivered_at, r.available_until,
         (r.contact_id <> current_contact_id()) AS is_shared
    FROM evaluation_reports r
   WHERE r.deleted_at IS NULL
   ORDER BY r.delivered_at DESC NULLS LAST;
$$;


--
-- Name: my_executed_delivery_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_executed_delivery_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_total   int;
  v_done    int;
  v_held    int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_contact := current_contact_id();
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('total', 0, 'delivered', 0, 'held', 0);
  END IF;

  SELECT count(*) INTO v_total
    FROM documents d
   WHERE d.contact_id = v_contact AND d.deleted_at IS NULL AND d.status = 'EXECUTED';

  SELECT count(*) INTO v_done
    FROM documents d
   WHERE d.contact_id = v_contact AND d.deleted_at IS NULL AND d.status = 'EXECUTED'
     AND EXISTS (
       SELECT 1 FROM document_deliveries dd
        WHERE dd.document_id = d.id
          AND dd.recipient_contact_id = v_contact
          AND dd.channel = 'EMAIL'
          AND dd.deleted_at IS NULL);

  SELECT count(*) INTO v_held
    FROM documents d
   WHERE d.contact_id = v_contact AND d.deleted_at IS NULL AND d.status = 'EXECUTED'
     AND d.delivery_held_at IS NOT NULL AND d.executed_email_sent_at IS NULL;

  RETURN jsonb_build_object('total', v_total, 'delivered', v_done, 'held', v_held);
END;
$$;


--
-- Name: my_first_lesson_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_first_lesson_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'has_lesson_purchase', EXISTS (
      SELECT 1
        FROM purchases pu
        JOIN purchase_items pi ON pi.purchase_id = pu.id AND pi.voided_at IS NULL
        JOIN offerings o       ON o.id = pi.offering_id
       WHERE pu.buyer_contact_id = current_contact_id()
         AND pu.deleted_at IS NULL
         -- A DRAFT counts. They picked it and are mid-checkout; nagging somebody
         -- who is already holding the thing is how a prompt loses its authority.
         AND coalesce(pu.status, '') <> 'void'
         AND o.service_type = 'RIDING_LESSON'),
    -- Only prompt people for whom a lesson is the point. A boarder or a pure
    -- contract party is not failing to do something by never buying one.
    'is_rider', EXISTS (
      SELECT 1 FROM groups g
       WHERE g.contact_id = current_contact_id() AND g.group_type = 'RIDER')
      OR EXISTS (
      SELECT 1 FROM contact_required_documents crd
       WHERE crd.contact_id = current_contact_id()
         AND crd.template_key = 'RELEASE_PARTICIPANT'));
$$;


--
-- Name: my_fulfillment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_fulfillment() RETURNS TABLE(purchase_id uuid, label text, unit_kind text, total integer, open integer, consumed integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u.purchase_id,
         coalesce(min(u.label), 'Purchase'),
         u.unit_kind,
         count(*)::int,
         count(*) FILTER (WHERE u.current_status IN ('open','scheduled'))::int,
         count(*) FILTER (WHERE u.current_status IN ('consumed','delivered'))::int
    FROM fulfillment_units u
    JOIN purchases p ON p.id = u.purchase_id
   WHERE u.deleted_at IS NULL
     AND (p.buyer_user_id = auth.uid() OR p.buyer_contact_id = current_contact_id())
   GROUP BY u.purchase_id, u.unit_kind;
$$;


--
-- Name: my_gifts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_gifts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(g ORDER BY g.created_at DESC), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'id', gf.id, 'code', gf.code, 'item_type', gf.item_type, 'item_label', gf.item_label,
      'amount', gf.amount, 'status', gf.status, 'gift_message', gf.gift_message,
      'buyer_name', gf.buyer_name, 'recipient_name', gf.recipient_name,
      'unlocked', gf.unlocked, 'opened_at', gf.opened_at, 'redeemed_at', gf.redeemed_at,
      'expires_at', gf.expires_at, 'created_at', gf.created_at,
      'direction', CASE WHEN gf.buyer_user_id = auth.uid() THEN 'given' ELSE 'received' END
    ) AS g, gf.created_at
    FROM gifts gf
    WHERE gf.buyer_user_id = auth.uid()
       OR gf.redeemed_user_id = auth.uid()
       OR lower(gf.recipient_email) = lower((SELECT email FROM auth.users WHERE id = auth.uid()))
  ) g;
$$;


--
-- Name: my_hidden_pages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_hidden_pages() RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT page_key
    FROM org_page_visibility
   WHERE org_id = current_org()
   ORDER BY page_key
$$;


--
-- Name: FUNCTION my_hidden_pages(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_hidden_pages() IS 'TASK-PAGEVIS: the page_keys the CALLER''S OWN tenant has hidden from its navigation. current_org()-scoped; never crosses tenants; returns nothing for a caller with no org (D1a: correct for the platform owner). A display preference — it gates no data.';


--
-- Name: my_horse_onboarding_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_horse_onboarding_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_pending jsonb;
  v_care_unsigned boolean;
  v_care_purchase boolean;
  v_needs_horse boolean;
BEGIN
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('pending_horse_docs','[]'::jsonb,'needs_horse',false,'service_blocked',false);
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'document_id', d.id, 'template_key', t.template_key,
           'title', d.title, 'link', '/app/contracts/' || d.id) ORDER BY d.created_at), '[]'::jsonb)
    INTO v_pending
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = v_contact
      AND t.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
      AND d.status <> 'EXECUTED'
      AND NOT EXISTS (SELECT 1 FROM signatures sg
                       WHERE sg.document_id = d.id AND sg.signer_contact_id = v_contact
                         AND sg.deleted_at IS NULL);

  SELECT EXISTS (
    SELECT 1 FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = v_contact AND t.template_key = 'RELEASE_HORSE_CARE'
      AND d.status <> 'EXECUTED'
  ) INTO v_care_unsigned;

  -- a non-cancelled horse (care) purchase by this buyer — contact OR user grain.
  SELECT EXISTS (
    SELECT 1 FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
    WHERE (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid())
      AND o.segment = 'horse'
      AND coalesce(pu.status, '') <> 'cancelled'
  ) INTO v_care_purchase;

  -- has a paid care service but no booking yet carrying a horse (booking grain).
  SELECT v_care_purchase AND NOT EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.client_id = current_client_id()
      AND b.kind = 'care' AND b.horse_id IS NOT NULL
      AND b.status NOT IN ('cancelled','available')
  ) INTO v_needs_horse;

  RETURN jsonb_build_object(
    'pending_horse_docs', v_pending,
    'needs_horse', v_needs_horse,
    'service_blocked', v_care_purchase AND v_care_unsigned
  );
END;
$$;


--
-- Name: my_inquiry_answers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_inquiry_answers() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_details jsonb;
  v_out jsonb := jsonb_build_object();
  k text;
  v text;
  v_subject text;
  v_question text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_contact IS NULL THEN RETURN v_out; END IF;

  -- The client's most recent inquiry that actually carries answers. Their file
  -- is drafted from what they last told us, not from an older submission.
  SELECT r.details INTO v_details
    FROM requests r
   WHERE r.contact_id = v_contact
     AND r.details IS NOT NULL AND r.details <> '{}'::jsonb
   ORDER BY r.created_at DESC
   LIMIT 1;
  IF v_details IS NULL THEN RETURN v_out; END IF;

  -- `buildSubmission` writes "{subject label} — {question}" keys. Split on that
  -- separator and regroup, so the caller asks for a SUBJECT and can never be
  -- handed another animal's answers by accident.
  FOR k, v IN SELECT key, value FROM jsonb_each_text(v_details)
  LOOP
    IF position(' — ' IN k) = 0 THEN
      CONTINUE;   -- the two ⚑ flag rows carry no subject; they are staff prose
    END IF;
    -- The separator is THREE CHARACTERS (space, em dash, space). `substring`
    -- and `position` count characters, not bytes — the em dash's 3-byte UTF-8
    -- encoding is irrelevant here, and treating it as bytes ate the first two
    -- letters of every question.
    v_question := btrim(substring(k FROM position(' — ' IN k) + 3));
    v_subject := CASE btrim(substring(k FROM 1 FOR position(' — ' IN k) - 1))
      WHEN 'About you'                       THEN 'person'
      WHEN 'Your horse'                      THEN 'client_horse'
      WHEN 'Horse being evaluated'           THEN 'evaluated_horse'
      WHEN 'Horse you are looking for'       THEN 'sought_horse'
      -- ⚠️ A horse they do not have yet is NOT their horse.
      WHEN 'Horse we are being asked to find' THEN 'sought_horse'
      ELSE NULL END;
    IF v_subject IS NULL THEN CONTINUE; END IF;
    v_out := jsonb_set(
      v_out, ARRAY[v_subject],
      coalesce(v_out->v_subject, '{}'::jsonb) || jsonb_build_object(v_question, v),
      true);
  END LOOP;

  RETURN v_out;
END;
$$;


--
-- Name: my_leased_horse_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_leased_horse_entries() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(h ORDER BY h->>'name'), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'horse_id', hz.id,
      'name', coalesce(hz.nickname, hz.registered_name, 'Horse'),
      'is_current_lessee', (hz.lessee_contact_id = current_contact_id()),
      'entries', (SELECT coalesce(jsonb_agg(jsonb_build_object(
          'id', e.id, 'kind', e.kind, 'data', e.data, 'created_at', e.created_at) ORDER BY e.created_at DESC), '[]'::jsonb)
        FROM horse_lessee_entries e
        WHERE e.horse_id = hz.id AND e.author_contact_id = current_contact_id() AND e.deleted_at IS NULL)
    ) AS h
    FROM horses hz
    WHERE hz.org_id = current_org() AND hz.deleted_at IS NULL
      AND EXISTS (SELECT 1 FROM horse_lessee_entries e
                   WHERE e.horse_id = hz.id AND e.author_contact_id = current_contact_id() AND e.deleted_at IS NULL)
  ) q;
$$;


--
-- Name: my_lesson_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_plan() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client uuid := current_client_id();
  v_plan   lesson_plans%ROWTYPE;
BEGIN
  IF v_client IS NULL THEN RETURN NULL; END IF;
  v_plan := _current_lesson_plan(v_client);
  IF v_plan.id IS NULL THEN RETURN NULL; END IF;

  -- p_include_private => FALSE. coach_notes never reaches this payload.
  RETURN _lesson_plan_json(v_plan, false)
         || jsonb_build_object('next_up', lesson_plan_next_up(v_plan.objectives));
END;
$$;


--
-- Name: my_lesson_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_progress() RETURNS TABLE(session_id uuid, starts_at timestamp with time zone, status text, location text, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.id, b.starts_at, upper(b.status), b.location, b.notes
  FROM bookings b
  WHERE b.kind = 'lesson'
    AND b.client_id = current_client_id()
    AND b.notes IS NOT NULL
    AND btrim(b.notes) <> ''
  ORDER BY b.starts_at DESC
$$;


--
-- Name: my_lesson_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_reports() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(r ORDER BY r.starts_at DESC), '[]'::jsonb)
  FROM (
    SELECT
      b.starts_at,
      jsonb_build_object(
        'booking_id',   b.id,
        'starts_at',    b.starts_at,
        'ends_at',      b.ends_at,
        'status',       upper(b.status),
        'location',     b.location,
        'activity_log', b.activity_log,
        'report',       b.notes,
        'notes', coalesce((
          SELECT jsonb_agg(jsonb_build_object(
              'author_role', n.author_role, 'author_name', n.author_name,
              'phase', n.phase, 'body', n.body, 'created_at', n.created_at)
            ORDER BY (n.phase = 'pre') DESC, n.created_at)
          FROM booking_notes n WHERE n.booking_id = b.id), '[]'::jsonb)
      ) AS r
    FROM bookings b
    WHERE b.kind = 'lesson'
      AND b.client_id = current_client_id()
      AND (
        (b.notes IS NOT NULL AND btrim(b.notes) <> '')
        OR b.activity_log IS NOT NULL
        OR EXISTS (SELECT 1 FROM booking_notes n WHERE n.booking_id = b.id)
      )
    ORDER BY b.starts_at DESC
    LIMIT 50
  ) r
$$;


--
-- Name: my_lesson_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_lesson_sessions() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id, 'starts_at', s.starts_at, 'ends_at', s.ends_at,
      -- ⚠️ DELIBERATELY still 'PENDING' for all four pre-firm states.
      -- `MyLessonsContent.tsx:147` filters the member's upcoming list to
      -- SCHEDULED|PENDING; emitting 'REQUESTED' here would delete the client's
      -- own session from their own page. The member surface already renders
      -- PENDING with the word "REQUESTED" (:193).
      'status', CASE
        WHEN s.status IN ('requested','approved','pending','moved') THEN 'PENDING'
        WHEN s.status IN ('scheduled','confirmed') THEN 'SCHEDULED'
        WHEN s.status IN ('cancelled','expired') THEN 'CANCELLED'
        WHEN s.status = 'completed' THEN 'COMPLETED'
        WHEN s.status = 'no_show' THEN 'NO_SHOW'
        ELSE upper(s.status) END,
      'location', s.location, 'notes', s.notes)
      ORDER BY s.ord), '[]'::jsonb)
  FROM (
    SELECT b.*, row_number() OVER (
        ORDER BY (b.starts_at >= now()) DESC,
                 CASE WHEN b.starts_at >= now() THEN b.starts_at END ASC,
                 CASE WHEN b.starts_at <  now() THEN b.starts_at END DESC
      ) AS ord
    FROM bookings b
    WHERE b.kind = 'lesson'
      AND b.client_id = current_client_id()
      AND has_module('mod.lessons')
    ORDER BY (b.starts_at >= now()) DESC,
             CASE WHEN b.starts_at >= now() THEN b.starts_at END ASC,
             CASE WHEN b.starts_at <  now() THEN b.starts_at END DESC
    LIMIT 50
  ) s
$$;


--
-- Name: FUNCTION my_lesson_sessions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_lesson_sessions() IS 'The signed-in member''s own lesson sessions (jsonb array): upcoming soonest-first, then recent past, limit 50. Empty array for non-clients or a mod.lessons-OFF tenant.';


--
-- Name: my_listable_horses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_listable_horses(p_intent text DEFAULT 'sale'::text) RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, color text, sex text, height text, date_of_birth date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.color, h.sex,
         h.height, h.date_of_birth
  FROM horses h
  WHERE h.org_id = current_org() AND h.deleted_at IS NULL
    AND (
      has_staff_access()
      OR h.current_owner_contact_id = current_contact_id()
      OR h.lessee_contact_id = current_contact_id()
    )
    AND can_list_horse(h.id, p_intent)
  ORDER BY coalesce(h.nickname, h.registered_name)
$$;


--
-- Name: my_locations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_locations() RETURNS TABLE(id uuid, name text, address text, is_offsite boolean, is_default boolean, is_mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT l.id, l.name, l.address, l.is_offsite, l.is_default,
         (l.owner_contact_id IS NOT NULL) AS is_mine
  FROM locations l
  WHERE l.org_id = current_org()
    AND l.active
    AND (l.owner_contact_id IS NULL OR l.owner_contact_id = current_contact_id())
  ORDER BY l.is_default DESC, (l.owner_contact_id IS NOT NULL), l.sort_order, l.name
$$;


--
-- Name: my_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_modules() RETURNS TABLE(module_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT om.module_key
    FROM org_modules om
    JOIN modules m ON m.module_key = om.module_key
    WHERE om.org_id = current_org()
      AND om.enabled
      AND (om.expires_at IS NULL OR om.expires_at > now())
      AND COALESCE(m.active, true)
    ORDER BY om.module_key
$$;


--
-- Name: FUNCTION my_modules(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_modules() IS 'U15 Layer-C UI-gating seam: the CURRENT caller''s own tenant''s enabled+unexpired module keys, read past org_modules RLS so a plain USER member can resolve nav gating. current_org()-scoped; never crosses tenants.';


