    'needs_confirmation', coalesce(v_needs, false),
    'first_name', v_first,
    'last_name', v_last);
END
$$;


--
-- Name: my_nav_presence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_nav_presence() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payments boolean;
  v_orders boolean;
  v_documents boolean;
  v_stable boolean;
  v_posts boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'orders', false, 'documents', false, 'stable', false, 'payments', false,
      'posts', false, 'saved', false);
  END IF;

  v_orders := EXISTS (
    SELECT 1 FROM purchases p
    WHERE (p.buyer_user_id = auth.uid() OR p.buyer_contact_id = current_contact_id())
      AND p.org_id = current_org()
  );

  v_documents := EXISTS (SELECT 1 FROM public.my_documents() LIMIT 1);

  v_stable := EXISTS (SELECT 1 FROM public.my_stable_horses() LIMIT 1);

  v_posts := EXISTS (
    SELECT 1 FROM feed_posts fp WHERE fp.author_id = auth.uid()
  );

  -- CR-76b: My Payments appears once there is a payment entry to read. An order
  -- with no method chosen is AWAITING PAYMENT — the absence of an entry — so a
  -- client who has never engaged the payment screen gets no row, which is the
  -- same presence rule every other link here uses.
  v_payments := EXISTS (
    SELECT 1 FROM payments pay
     WHERE pay.deleted_at IS NULL
       AND pay.payer_contact_id = current_contact_id()
  );

  RETURN jsonb_build_object(
    'orders', v_orders,
    'documents', v_documents,
    'stable', v_stable,
    'posts', v_posts,
    'saved', false,
    'payments', v_payments
  );
END;
$$;


--
-- Name: my_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_notifications(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', n.id, 'kind', n.kind, 'title', n.title, 'body', n.body,
      'link', n.link, 'read_at', n.read_at, 'created_at', n.created_at)
      ORDER BY n.created_at DESC, n.id DESC), '[]'::jsonb)
  FROM (
    SELECT * FROM notifications
    WHERE user_id = auth.uid()
      -- a contract-linked notification is only valid while its document exists and
      -- is not soft-deleted; non-contract notifications are unaffected.
      AND (
        link IS NULL
        OR link !~ '^/app/contracts/[0-9a-fA-F-]{36}$'
        OR EXISTS (
          SELECT 1 FROM documents d
          WHERE d.id = regexp_replace(link, '^/app/contracts/', '')::uuid
            AND d.deleted_at IS NULL
        )
      )
      -- RETIRED: the cancel path no longer exists. Its historical notifications
      -- stay in the table as evidence but are never surfaced as live to-dos.
      AND kind <> 'contract_cancelled'
      AND title NOT ILIKE '%awaiting archive%'
    ORDER BY created_at DESC, id DESC
    LIMIT greatest(coalesce(p_limit, 20), 1)
  ) n
$_$;


--
-- Name: FUNCTION my_notifications(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_notifications(p_limit integer) IS 'The signed-in user''s notifications, newest first (jsonb array; empty array when none).';


--
-- Name: my_onboarding_checklist(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_onboarding_checklist() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN has_staff_access() THEN '[]'::jsonb
