--
-- Name: my_purchase_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_purchase_categories() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(array_agg(DISTINCT cat ORDER BY cat), ARRAY[]::text[])
  FROM (
    SELECT CASE o.segment
             WHEN 'rider'   THEN 'riding'
             WHEN 'support' THEN 'deal'
             WHEN 'horse'   THEN 'care'
             ELSE o.segment
           END AS cat
    FROM purchases pu
    JOIN purchase_items pi ON pi.purchase_id = pu.id
    JOIN offerings o ON o.id = pi.offering_id
    WHERE pu.buyer_contact_id = current_contact_id()
      AND pu.deleted_at IS NULL
      AND o.segment IS NOT NULL

    UNION

    SELECT CASE lower(t)
             WHEN 'rider'       THEN 'riding'
             WHEN 'horse owner' THEN 'care'
             WHEN 'owner'       THEN 'care'
             WHEN 'buyer'       THEN 'deal'
             WHEN 'seller'      THEN 'deal'
             WHEN 'lessee'      THEN 'deal'
             WHEN 'lessor'      THEN 'deal'
             ELSE NULL
           END AS cat
    FROM contacts c
    CROSS JOIN LATERAL unnest(coalesce(c.tags, ARRAY[]::text[])) AS t
    WHERE c.id = current_contact_id()

    UNION

    -- THE DERIVED AFFILIATION — apply_affiliations is the sole writer of these,
    -- computed from executed documents, purchases and horse ownership. Every
    -- other surface already trusts them; this one did not, which is why a rider
    -- with all four releases signed had no community feed.
    SELECT CASE g.group_type
             WHEN 'RIDER'       THEN 'riding'
             WHEN 'HORSE_OWNER' THEN 'care'
             ELSE NULL
           END AS cat
    FROM groups g
    WHERE g.contact_id = current_contact_id()
  ) s
  WHERE cat IS NOT NULL
$$;


--
-- Name: my_stable_delete_horse(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_delete_horse(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horses
     SET deleted_at = now()
   WHERE id = p_id
     AND org_id = current_org()
     AND deleted_at IS NULL
     AND (
       current_owner_contact_id = current_contact_id()
       OR (has_staff_access() AND current_owner_contact_id = company_contact_id())
     );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'horse not found or not yours to remove';
  END IF;
END;
$$;


--
-- Name: my_stable_horses(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_horses(p_as_company boolean DEFAULT NULL::boolean) RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, sex text, height text, date_of_birth date, color text, current_location text, is_owner boolean, created_at timestamp with time zone, lease_start date, lease_end date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope uuid;
  v_as_company boolean := coalesce(p_as_company, has_staff_access());
BEGIN
  IF v_as_company AND NOT has_staff_access() THEN
    RAISE EXCEPTION 'only staff may view the company''s stable';
  END IF;
  v_scope := CASE WHEN v_as_company THEN company_contact_id()
                  ELSE current_contact_id() END;
  RETURN QUERY
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.sex, h.height,
         h.date_of_birth, h.color, h.current_location,
         (h.current_owner_contact_id = v_scope) AS is_owner,
         h.created_at, h.lease_start, h.lease_end
  FROM horses h
  WHERE h.deleted_at IS NULL
    AND h.org_id = current_org()
    AND (
      h.current_owner_contact_id = v_scope
      OR h.lessee_contact_id     = v_scope
      OR EXISTS (
        SELECT 1 FROM horse_relationships hr
        WHERE hr.horse_id = h.id AND hr.active
          AND hr.party_contact_id = v_scope
          AND (hr.term_end IS NULL OR hr.term_end >= current_date)
      )
    )
  ORDER BY lower(coalesce(nullif(btrim(h.nickname),''), h.registered_name, '')), h.created_at;
END;
$$;


--
-- Name: my_stable_update_horse(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_stable_update_horse(p_id uuid, p_barn_name text DEFAULT NULL::text, p_breed text DEFAULT NULL::text, p_sex text DEFAULT NULL::text, p_height text DEFAULT NULL::text, p_color text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horses
     SET nickname        = COALESCE(p_barn_name, nickname),
         breed            = COALESCE(p_breed, breed),
         sex              = COALESCE(p_sex, sex),
         height           = COALESCE(p_height, height),
         color            = COALESCE(p_color, color),
         current_location = COALESCE(p_location, current_location),
         updated_at       = now()
   WHERE id = p_id
     AND org_id = current_org()
     AND deleted_at IS NULL
     AND (
       current_owner_contact_id = current_contact_id()
       OR (has_staff_access() AND current_owner_contact_id = company_contact_id())
     );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'horse not found or not yours to edit';
  END IF;
END;
$$;


--
-- Name: my_standing_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_standing_categories() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_groups  text[];
BEGIN
  IF auth.uid() IS NULL OR v_contact IS NULL THEN RETURN ARRAY[]::text[]; END IF;
  SELECT coalesce(array_agg(DISTINCT g.group_type ORDER BY g.group_type), ARRAY[]::text[])
    INTO v_groups
    FROM groups g
   WHERE g.contact_id = v_contact AND g.group_type IN ('GUEST','RIDER','HORSE_OWNER');
  RETURN v_groups;
END;
$$;


--
-- Name: my_standing_slots(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_standing_slots(p_purchase_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_client  uuid := current_client_id();
BEGIN
  IF auth.uid() IS NULL THEN RETURN '[]'::jsonb; END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
        'purchase_id',      pu.id,
        'purchase_item_id', pi.id,
        'offering_id',      o.id,
        'offering_name',    o.name,
        'segment',          o.segment,
        'weekly_frequency', o.weekly_frequency,
        'recurring_days',   coalesce(pi.config->'recurring_days', '[]'::jsonb),
        'recurring_times',  coalesce(pi.config->'recurring_times', '{}'::jsonb),
        'duration_minutes', coalesce((pi.config->>'duration_minutes')::int, 60),
        'chosen',           coalesce(jsonb_array_length(coalesce(pi.config->'recurring_days','[]'::jsonb)), 0) > 0
                            AND coalesce(pi.config->'recurring_times', '{}'::jsonb) <> '{}'::jsonb,
        'indefinite',       pi.plan_ends_on IS NULL,
        'plan_ends_on',     pi.plan_ends_on,
        'horizon_through',  pi.config->>'horizon_through',
        'booked_ahead',     (SELECT count(*) FROM bookings b
                              WHERE b.purchase_id = pu.id
                                AND b.offering_id = o.id
                                AND b.starts_at >= now()
                                AND b.status NOT IN ('cancelled','expired')))
      ORDER BY pu.created_at DESC, o.name)
      FROM purchase_items pi
      JOIN offerings o  ON o.id  = pi.offering_id AND o.config_kind = 'recurring'
      JOIN purchases pu ON pu.id = pi.purchase_id
     WHERE pu.deleted_at IS NULL
       AND pi.voided_at IS NULL
       AND (p_purchase_id IS NULL OR pu.id = p_purchase_id)
       AND (pu.buyer_user_id = auth.uid()
            OR (v_contact IS NOT NULL AND pu.buyer_contact_id = v_contact))
       AND (pi.plan_ends_on IS NULL OR pi.plan_ends_on >= current_date)
  ), '[]'::jsonb);
END;
$$;


