--
-- Name: my_view_surfaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_view_surfaces() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cats     text[] := my_purchase_categories();
  v_operator boolean := has_staff_access();
  -- D8: an account is the qualification for the community. Nothing else.
  v_surfaces text[] := ARRAY['dashboard', 'feed', 'community']::text[];
BEGIN
  IF v_operator THEN
    v_cats := (SELECT ARRAY(SELECT DISTINCT unnest(v_cats || ARRAY['operator'])));
    v_surfaces := v_surfaces || ARRAY['company'];
  END IF;

  -- The LIBRARY is still a rider surface — it is instructional material for
  -- people taking lessons, not a community space.
  IF 'riding' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['library'];
  END IF;

  IF 'deal' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['deal_dashboard'];
  END IF;
  IF 'care' = ANY(v_cats) THEN
    v_surfaces := v_surfaces || ARRAY['care_dashboard'];
  END IF;

  v_surfaces := v_surfaces || ARRAY['account', 'documents', 'orders'];
  v_surfaces := (SELECT ARRAY(SELECT DISTINCT unnest(v_surfaces) ORDER BY 1));

  RETURN jsonb_build_object(
    'categories', to_jsonb(v_cats),
    'surfaces',   to_jsonb(v_surfaces),
    'has_feed',   ('feed' = ANY(v_surfaces)),
    'has_community', ('community' = ANY(v_surfaces)),
    'is_operator', v_operator
  );
END;
$$;


--
-- Name: my_wall_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_wall_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_state jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_contact IS NULL THEN
    RETURN jsonb_build_object('pending', 0, 'wall', false, 'staff', false,
                              'waiting', 0, 'waiting_titles', '[]'::jsonb);
  END IF;

  v_state := contact_document_wall_state(v_contact);

  RETURN jsonb_build_object(
    'pending', (v_state->>'pending')::int,
    'wall', ((v_state->>'gating')::int > 0 AND NOT has_staff_access()),
    'staff_banner', ((v_state->>'gating')::int > 0 AND has_staff_access()),
    'staff', has_staff_access(),
    -- §12: documents ASKED for. Never walls — surfaced at every login until
    -- signed, and dismissable for the session. Staff see their own too; being
    -- staff exempts you from the wall, not from being asked.
    'waiting', (v_state->>'waiting')::int,
    'waiting_titles', coalesce(v_state->'waiting_titles', '[]'::jsonb));
END;
$$;


--
-- Name: narrow_contact_required_documents(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.narrow_contact_required_documents(p_contact_id uuid, p_keep_template_keys text[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_keep     text[] := coalesce(p_keep_template_keys, '{}');
  v_drop     text[];
  v_evidence text[];
  k          text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'contact not found in this org';
  END IF;

  -- §2 / test 6: a narrowing with no reason is REFUSED. Checked before the work
  -- so the refusal is about the act, not about whichever template sorts first.
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to remove required paperwork from someone''s record';
  END IF;

  -- What this narrowing would take away: standing (not already skipped)
  -- requirements outside the keep set.
  SELECT coalesce(array_agg(crd.template_key ORDER BY crd.template_key), '{}')
    INTO v_drop
    FROM contact_required_documents crd
   WHERE crd.contact_id = p_contact_id
     AND crd.skipped_at IS NULL
     AND crd.template_key <> ALL (v_keep);

  IF array_length(v_drop, 1) IS NULL THEN
    RETURN jsonb_build_object('skipped', '[]'::jsonb, 'kept_executed', '[]'::jsonb);
  END IF;

  -- §1 — EXECUTED PAPERWORK IS EVIDENCE AND IS NEVER REMOVED BY ANY PATH.
  SELECT coalesce(array_agg(d ORDER BY d), '{}') INTO v_evidence
    FROM unnest(v_drop) d WHERE contact_document_satisfied(p_contact_id, d);
  IF array_length(v_evidence, 1) IS NOT NULL THEN
    RAISE EXCEPTION
      'cannot remove %: satisfied by an executed document. Executed paperwork is the '
      'evidence that the obligation existed and was met, and is never removed — '
      'uncheck the rest, or leave this one on the record.',
      array_to_string(v_evidence, ', ');
  END IF;

  FOREACH k IN ARRAY v_drop LOOP
    PERFORM _skip_required_document(p_contact_id, k, v_reason, auth.uid());
  END LOOP;

  -- §3 — RECORD IT. `lesson_credits` and `bookings` are already absent from
  -- audit_logs (W10); this does not become a third silent table. One row for the
  -- narrowing ACT, naming the contact, the templates, the actor and the reason —
  -- beside the per-template rows _skip_required_document writes.
  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (auth.uid(), 'UPDATE', 'contact_required_documents', p_contact_id,
          jsonb_build_object('event', 'requirements_before_narrowing',
                             'standing_templates', to_jsonb(v_drop || v_keep)),
          jsonb_build_object('event', 'requirements_narrowed',
                             'contact_id', p_contact_id,
                             'kept_templates', to_jsonb(v_keep),
                             'skipped_templates', to_jsonb(v_drop),
                             'skipped_by', auth.uid(),
                             'reason', v_reason,
                             'destroyed', false));

  RETURN jsonb_build_object('skipped', to_jsonb(v_drop), 'kept_executed', '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION narrow_contact_required_documents(p_contact_id uuid, p_keep_template_keys text[], p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.narrow_contact_required_documents(p_contact_id uuid, p_keep_template_keys text[], p_reason text) IS 'TASK-NOSTRIP: the ONLY door that removes a set of required documents from a person. It skips (retains + marks with who/when/why), never deletes; refuses without a reason; refuses outright when an executed document satisfies one of them; writes an audit_logs row. Undo is unskip_required_document.';


--
-- Name: needs(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.needs(p_label text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT '⟦NEEDS:' || p_label || '⟧_____⟧';
$$;


--
-- Name: next_custom_field_key(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_custom_field_key(p_document_id uuid, p_label text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_seq int; v_base text; v_key text;
BEGIN
  v_base := btrim(upper(regexp_replace(coalesce(nullif(btrim(p_label),''),'FIELD'),
                                       '[^a-zA-Z0-9]+', '_', 'g')), '_');
  IF v_base = '' THEN v_base := 'FIELD'; END IF;
  SELECT count(*) INTO v_seq FROM contract_fields
   WHERE document_id = p_document_id AND field_key LIKE 'CUSTOM.%';
  LOOP
    v_seq := v_seq + 1;
    v_key := 'CUSTOM.' || v_base || '_' || v_seq;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM contract_fields
                           WHERE document_id = p_document_id AND field_key = v_key);
  END LOOP;
  RETURN v_key;
END;
$$;


--
-- Name: normalise_phone_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalise_phone_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_col text;
  v_val text;
BEGIN
  FOREACH v_col IN ARRAY TG_ARGV LOOP
    EXECUTE format('SELECT ($1).%I::text', v_col) INTO v_val USING NEW;
    IF v_val IS NOT NULL AND btrim(v_val) <> '' THEN
      NEW := jsonb_populate_record(NEW, to_jsonb(NEW) || jsonb_build_object(v_col, format_phone(v_val)));
    END IF;
  END LOOP;
  RETURN NEW;
END
$_$;


--
-- Name: normalize_person_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_person_name(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_value IS NULL THEN NULL
    WHEN btrim(p_value) = '' THEN btrim(p_value)
    ELSE (
      SELECT string_agg(
        CASE
          -- already has a capital somewhere — hands off
          WHEN w ~ '[[:upper:]]' THEN w
          -- starts with a lowercase letter — capitalise that one letter only
          WHEN w ~ '^[[:lower:]]' THEN upper(left(w, 1)) || substr(w, 2)
          ELSE w
        END, ' ' ORDER BY ord)
      FROM regexp_split_to_table(
             regexp_replace(btrim(p_value), '\s+', ' ', 'g'), ' '
           ) WITH ORDINALITY AS t(w, ord)
    )
  END;
$$;


--
-- Name: FUNCTION normalize_person_name(p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_person_name(p_value text) IS 'TASK-FIX4/CR-83: capitalise each word that carries no capital of its own. ONE-TIME backfill helper. NEVER attach this to a trigger — re-normalising on every write overwrites a person''s deliberate correction (CR-83).';


--
-- Name: notification_category(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_category(p_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_kind LIKE 'contract%' OR p_kind IN
      ('document_executed','party_signed','insurance_unresolved') THEN 'contract'
    WHEN p_kind LIKE 'purchase%' OR p_kind LIKE 'payment%' OR p_kind LIKE 'receipt%' THEN 'payment'
    WHEN p_kind LIKE 'lesson%' OR p_kind LIKE 'booking%' OR p_kind LIKE 'session%' THEN 'lesson'
    WHEN p_kind LIKE 'request%' OR p_kind LIKE 'lead%' OR p_kind LIKE 'signup%' THEN 'lead'
    WHEN p_kind IN ('member_hi','redemption_conflict') THEN 'account'
    WHEN p_kind LIKE 'horse%' THEN 'horse'
    ELSE 'general'
  END
$$;


--
-- Name: notification_is_personal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_is_personal(p_kind text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_kind IN ('member_hi','member_hi_back')
      OR p_kind LIKE '%_reminder'
      OR p_kind = 'document_executed_self';  -- reserved: a signer's own confirmation
$$;


--
-- Name: notifications_capture_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_capture_provenance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.category       := coalesce(NEW.category, notification_category(NEW.kind));
  -- the acting session raised it; NULL (cron, service role) reads as "system"
  NEW.author_user_id := coalesce(NEW.author_user_id, auth.uid());
  RETURN NEW;
END;
$$;


--
-- Name: notify_minor_delivery_skipped(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_minor_delivery_skipped(p_org uuid, p_link text, p_names text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_names IS NULL OR array_length(p_names, 1) IS NULL THEN RETURN; END IF;
  PERFORM notify_staff(
    p_org, 'minor_no_guardian',
    'Not sent — no guardian email on file: ' || array_to_string(p_names, ', '),
    p_link);
END;
$$;


--
-- Name: notify_purchase_unpaid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_purchase_unpaid(p_purchase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur   purchases%ROWTYPE;
  v_user  uuid;
  v_label text;
  v_due   text;
BEGIN
  SELECT * INTO v_pur FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN; END IF;

  -- only for a purchase that actually owes money
  IF coalesce(v_pur.payment_status, '') NOT IN ('unpaid', 'pending') THEN RETURN; END IF;

  SELECT string_agg(pi.label, ', ' ORDER BY pi.created_at) INTO v_label
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id;
  v_label := coalesce(nullif(btrim(v_label), ''), 'Your order');
  v_due   := fmt_money(greatest(coalesce(v_pur.amount, 0) - coalesce(v_pur.amount_paid, 0), 0));

  -- the buyer, when they have an account
  SELECT pr.user_id INTO v_user
    FROM profiles pr WHERE pr.contact_id = v_pur.buyer_contact_id LIMIT 1;
  IF v_user IS NOT NULL THEN
    PERFORM notify_user(v_user, 'purchase_unpaid',
      v_label || ' — payment due',
      'Your order is confirmed and awaiting payment of ' || v_due || '.',
      '/order/' || p_purchase_id::text);
  END IF;

  -- staff, at the review queue
  PERFORM notify_staff(v_pur.org_id, 'purchase_unpaid',
    v_label || ' — awaiting payment (' || v_due || ')',
    '/app/ops/payments/review');
END;
$$;


--
-- Name: FUNCTION notify_purchase_unpaid(p_purchase_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.notify_purchase_unpaid(p_purchase_id uuid) IS 'U3(a): standing "payment due" alerts to buyer and staff. Resolved by mark_purchase_paid when payment lands.';


--
-- Name: notify_review_changes(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_review_changes(p_document_id uuid, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_title text; v_me uuid := current_contact_id(); v_n int := 0; r record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, coalesce(title, 'A document') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;

  FOR r IN
    SELECT DISTINCT pr.user_id FROM document_parties dp
      JOIN profiles pr ON pr.contact_id = dp.contact_id
     WHERE dp.document_id = p_document_id AND dp.contact_id IS DISTINCT FROM v_me
       AND pr.user_id IS NOT NULL
  LOOP
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_org, r.user_id, 'review_changes',
              v_title || ' has changes to review', '/app/contracts/' || p_document_id::text);
    v_n := v_n + 1;
  END LOOP;

  PERFORM log_contract_change(p_document_id, 'review_requested', NULL,
                              'Review of changes requested', NULL, NULL, NULL,
                              jsonb_build_object('message', p_message, 'notified', v_n));

  RETURN jsonb_build_object('notified', v_n);
END;
$$;


--
-- Name: notify_staff(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff(p_org uuid, p_kind text, p_title text, p_link text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO notifications (org_id, user_id, kind, title, link)
  SELECT p_org, p.user_id, p_kind, p_title, p_link
  FROM profiles p
  WHERE p.org_id = p_org AND coalesce(p.role,'USER') IN ('ADMIN','MANAGER','EMPLOYEE','OWNER','SUPERADMIN');
$$;


--
-- Name: notify_user(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_user(p_user_id uuid, p_kind text, p_title text, p_body text DEFAULT NULL::text, p_link text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_id  uuid;
BEGIN
  -- same fence as provision_lesson_invitation
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized to send notifications';
  END IF;

  -- stamp the TARGET user's org (their profile), not the caller's; fall back
  -- to current_org() for profiles not yet org-joined.
  SELECT org_id INTO v_org FROM profiles WHERE user_id = p_user_id;
  v_org := coalesce(v_org, current_org());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'cannot resolve an organization for user %', p_user_id;
  END IF;

  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    VALUES (v_org, p_user_id, p_kind, p_title, p_body, p_link)
    RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION notify_user(p_user_id uuid, p_kind text, p_title text, p_body text, p_link text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.notify_user(p_user_id uuid, p_kind text, p_title text, p_body text, p_link text) IS 'Create a notification for a user (staff/service_role only — same fence as provision_lesson_invitation). Org stamped from the target user''s profile, current_org() fallback.';


--
-- Name: onboarding_template_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_template_options() RETURNS TABLE(template_key text, title text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ct.template_key, ct.title
    FROM contract_templates ct
   WHERE has_staff_access()
     AND ct.active AND ct.deleted_at IS NULL
     AND coalesce(ct.wall_gating, false)
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key
                          AND x.active AND x.deleted_at IS NULL)
   ORDER BY ct.title
$$;


--
-- Name: open_change_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_change_requests() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', cr.id, 'booking_id', cr.booking_id, 'kind', cr.request_kind,
        'proposed_starts_at', cr.proposed_starts_at, 'proposed_ends_at', cr.proposed_ends_at,
        'fee_amount', cr.fee_amount, 'fee_paid', cr.fee_paid, 'phone_required', cr.phone_required,
        'note', cr.note, 'staff_note', cr.staff_note, 'awaiting_client', cr.awaiting_client,
        'created_at', cr.created_at,
        'client_name', trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')),
        'starts_at', b.starts_at) ORDER BY cr.created_at DESC), '[]'::jsonb)
    FROM booking_change_requests cr
    JOIN bookings b ON b.id = cr.booking_id
    LEFT JOIN clients cl ON cl.id = b.client_id
    LEFT JOIN contacts c ON c.id = cl.contact_id
    WHERE cr.org_id = current_org() AND cr.status = 'pending');
END;
$$;


--
-- Name: open_gift(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_gift(p_code text) RETURNS TABLE(item_type text, item_label text, recipient_name text, gift_message text, buyer_name text, status text, unlock_gate text, unlocked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Mark opened the first time a valid, paid/delivered gift is viewed.
  UPDATE gifts g SET status = 'opened', opened_at = now()
  WHERE g.code = p_code AND g.status IN ('paid','delivered');

  RETURN QUERY
    SELECT g.item_type, g.item_label, g.recipient_name, g.gift_message,
           g.buyer_name, g.status, g.unlock_gate, g.unlocked
    FROM gifts g
    WHERE g.code = p_code
      AND g.status IN ('paid','delivered','opened','redeemed')
      AND (g.expires_at IS NULL OR g.expires_at > now());
END;
$$;


--
-- Name: ops_day_sheet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_day_sheet(p_org uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_day date;
BEGIN
  IF NOT (coalesce(auth.role(),'') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  v_org := coalesce(p_org, current_org());
  -- "Today" is the BARN's today, not the server's (D: America/Los_Angeles).
  v_day := (now() AT TIME ZONE 'America/Los_Angeles')::date;

  RETURN jsonb_build_object(
    'day', v_day,
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'at',    to_char(b.starts_at AT TIME ZONE 'America/Los_Angeles', 'HH12:MI AM'),
               'what',  coalesce(nullif(btrim(o.name), ''), initcap(b.kind)),
               'who',   coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''), '—'),
               'horse', coalesce(nullif(btrim(h.nickname), ''), h.registered_name),
               'status', b.status)
             ORDER BY b.starts_at)
        FROM bookings b
        LEFT JOIN contacts c ON c.id = b.account_contact_id
        LEFT JOIN offerings o ON o.id = b.offering_id
        LEFT JOIN horses   h ON h.id = b.horse_id
       WHERE b.org_id = v_org
         AND b.deleted_at IS NULL
         AND b.kind IN ('lesson','care')
         -- ⚠️ 'available' is EXCLUDED: 494 of the calendar's rows are published
         -- open slots, not sessions. A day sheet listing them would be unreadable.
         AND b.status IN ('scheduled','confirmed','requested','approved','pending')
         AND (b.starts_at AT TIME ZONE 'America/Los_Angeles')::date = v_day
    ), '[]'::jsonb));
END;
$$;


--
-- Name: order_status_code(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_status_code(p_status text, p_payment text, p_claim_status text DEFAULT NULL::text, p_claim_method text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_status = 'void' THEN 'void'
    WHEN p_status = 'paid' OR p_payment = 'paid' THEN 'paid'
    -- D23 — the client has SAID how they are paying. That is a state of the order,
    -- not a footnote on it, and it names the method because the method is what staff
    -- have to go and check.
    WHEN coalesce(p_claim_status, '') = 'pending'
     AND lower(coalesce(p_claim_method, '')) = 'zelle' THEN 'payment_pending_zelle'
    WHEN coalesce(p_claim_status, '') = 'pending'
     AND lower(coalesce(p_claim_method, '')) = 'cash'  THEN 'payment_pending_cash'
    WHEN p_status = 'awaiting_payment' THEN 'submitted'
    WHEN p_status = 'sent' THEN 'submitted'
    ELSE 'pending' END;
$$;


--
-- Name: org_public_config(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_public_config(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org     uuid;
  v_brand   jsonb;
  v_contact jsonb;
  v_modules jsonb := '[]'::jsonb;
  v_pricing jsonb := '[]'::jsonb;
BEGIN
  SELECT id INTO v_org FROM organizations
    WHERE slug = p_slug AND status = 'ACTIVE' AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RETURN NULL;  -- unknown / inactive tenant
  END IF;

  -- Brand: the config_values ns 'BRAND' rows for this tenant, as a flat object.
  SELECT COALESCE(
           jsonb_object_agg(cv.key, COALESCE(
             cv.value_text,
             CASE WHEN cv.value_num IS NOT NULL THEN cv.value_num::text END,
             CASE WHEN cv.value_json IS NOT NULL THEN cv.value_json #>> '{}' END)),
           '{}'::jsonb)
    INTO v_brand
    FROM config_values cv
    WHERE cv.org_id = v_org AND cv.namespace = 'BRAND';

  -- Contact (public-safe: phone/email/url only), keyed CONTACT_<KEY>.
  SELECT COALESCE(
           jsonb_object_agg('CONTACT_' || cv.key, cv.value_text),
           '{}'::jsonb)
    INTO v_contact
    FROM config_values cv
    WHERE cv.org_id = v_org AND cv.namespace = 'CONTACT'
      AND cv.key IN ('PHONE','EMAIL','URL');

  v_brand := v_brand || v_contact;

  -- Active PUBLIC module list — only when the entitlement substrate exists (U2).
  -- Guarded so U3 applies and tests green whether or not U2 has shipped yet.
  IF to_regclass('public.org_modules') IS NOT NULL
     AND to_regclass('public.modules') IS NOT NULL THEN
    EXECUTE $q$
      SELECT COALESCE(jsonb_agg(om.module_key ORDER BY om.module_key), '[]'::jsonb)
        FROM org_modules om
        JOIN modules m ON m.module_key = om.module_key
        WHERE om.org_id = $1
          AND om.enabled
          AND (om.expires_at IS NULL OR om.expires_at > now())
          AND COALESCE(m.active, true)
    $q$ INTO v_modules USING v_org;
  END IF;

  -- Public pricing — only when the per-org products/product_prices exist (U5).
  -- Guarded so U3 applies and tests green whether or not U5 has shipped yet. Only
  -- active products at the current effective price; NO commission/retention/e-sign.
  IF to_regclass('public.products') IS NOT NULL
     AND to_regclass('public.product_prices') IS NOT NULL THEN
    EXECUTE $q$
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'product_key', p.product_key,
               'name', p.name,
               'amount', pp.amount) ORDER BY p.product_key), '[]'::jsonb)
        FROM products p
        JOIN LATERAL (
          SELECT amount FROM product_prices
            WHERE product_id = p.id
              AND effective_from <= now()
              AND (effective_to IS NULL OR effective_to > now())
            ORDER BY effective_from DESC LIMIT 1
        ) pp ON true
        WHERE p.org_id = $1 AND p.active
    $q$ INTO v_pricing USING v_org;
  END IF;

  RETURN jsonb_build_object(
    'org_id',   v_org,
    'slug',     p_slug,
    'brand',    v_brand,
    'modules',  v_modules,
    'pricing',  v_pricing
  );
END;
$_$;


--
-- Name: org_staff_user_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_staff_user_ids(p_org_id uuid) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.user_id FROM profiles p
   WHERE p.org_id = p_org_id
     AND p.role IN ('ADMIN','SUPER_ADMIN')
     AND coalesce(p.staff_active, true);
$$;


--
-- Name: owner_has_executed_template(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_has_executed_template(p_owner uuid, p_template_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM documents d
    JOIN contract_templates t ON t.id = d.template_id
    WHERE d.contact_id = p_owner AND t.template_key = p_template_key
      AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
      AND d.horse_id IS NOT NULL
      AND d.merged_body NOT LIKE '%{{HORSE.%'
  )
$$;


--
-- Name: owns_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owns_order(p_order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM orders o
    WHERE o.id = p_order_id AND (o.user_id = auth.uid() OR is_admin())
  );
$$;


--
-- Name: party_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_label(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE upper(coalesce(p,''))
    WHEN 'OWNER'  THEN 'the Owner'   WHEN 'LESSOR' THEN 'the Lessor'
    WHEN 'LESSEE' THEN 'the Lessee'  WHEN 'BUYER'  THEN 'the Buyer'
    WHEN 'SELLER' THEN 'the Seller'  WHEN 'CLIENT' THEN 'the Client'
    WHEN 'FHE'    THEN 'French Heritage Equestrian'
    WHEN 'TRAINER' THEN 'the Trainer/Instructor'
    WHEN 'BOARDING' THEN 'the Boarding Staff'
    WHEN 'VETERINARIAN' THEN 'the Veterinarian'
    WHEN 'CARE_PROVIDER' THEN 'the Care Provider'
    WHEN 'SHARED' THEN 'the parties jointly'
    ELSE '' END;
$$;


--
-- Name: party_user_ids(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_user_ids(p_document_id uuid, p_party_role text) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT p.user_id
    FROM document_parties dp
    JOIN contacts c ON c.id = dp.contact_id
    JOIN profiles p ON (p.contact_id = dp.contact_id
                        OR (c.email IS NOT NULL AND lower(p.email) = lower(c.email)))
   WHERE dp.document_id = p_document_id
     AND dp.party_role = p_party_role
     AND p.user_id IS NOT NULL;
$$;


--
-- Name: payer_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payer_candidates() RETURNS TABLE(contact_id uuid, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.contact_id,
         coalesce(nullif(btrim(p.display_name), ''),
                  nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                  'Member')
    FROM profiles p
    JOIN members m ON m.user_id = p.user_id AND m.status = 'active'
   WHERE p.contact_id IS NOT NULL
     AND p.org_id = current_org()
     AND NOT is_platform_profile(p.role, p.org_id)
     AND auth.uid() IS NOT NULL
   ORDER BY 2;
$$;


--
-- Name: pending_fee_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_fee_candidates() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (coalesce(auth.role(),'') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', cr.id,
        'fee_amount', cr.fee_amount,
        'name', nullif(trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
        'email', coalesce(c.email, p.email),
        'phone', coalesce(c.phone, c.mobile))), '[]'::jsonb)
    FROM booking_change_requests cr
    JOIN bookings b ON b.id = cr.booking_id
    LEFT JOIN clients cl ON cl.id = b.client_id
    LEFT JOIN contacts c ON c.id = cl.contact_id
    LEFT JOIN profiles p ON p.user_id = b.account_user_id
    WHERE cr.status = 'pending' AND cr.fee_paid = false AND cr.fee_amount IS NOT NULL);
END;
$$;


--
-- Name: pending_notify_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_notify_summary(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_cid uuid; v_last timestamptz;
  v_changes int := 0; v_requests int := 0;
  v_other_role text; v_other_name text;
  v_changes_frozen boolean; v_requests_frozen boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to read document %', p_document_id;
  END IF;

  SELECT contact_id INTO v_cid FROM comment_author_identity(p_document_id);
  v_cid := coalesce(v_cid, current_contact_id());

  -- THE COUNTERPARTY, by ROLE name, derived from the document's own parties.
  -- Never hardcoded: whoever is not the caller is the other side.
  SELECT dp.party_role,
         initcap(lower(replace(dp.party_role, '_', ' ')))
    INTO v_other_role, v_other_name
    FROM document_parties dp
   WHERE dp.document_id = p_document_id
     AND dp.contact_id IS DISTINCT FROM v_cid
   ORDER BY dp.party_role
   LIMIT 1;
  v_other_name := coalesce(v_other_name, 'the other party');

  -- last notify by this caller on this document
  SELECT max(cr.submitted_at) INTO v_last
    FROM contract_change_requests cr
   WHERE cr.document_id = p_document_id AND cr.author_contact_id = v_cid;

  -- CHANGES pending = this caller's document edits not yet notified about
  SELECT count(*) INTO v_changes
    FROM contract_change_log cl
   WHERE cl.document_id = p_document_id
     AND cl.actor_contact_id = v_cid
     AND cl.change_kind IN ('field_value','field_structured')
     AND (v_last IS NULL OR cl.created_at > v_last);

  -- REQUESTS pending = this caller's un-notified (draft) requests
  SELECT count(*) INTO v_requests
    FROM contract_change_requests cr
   WHERE cr.document_id = p_document_id
     AND cr.parent_request_id IS NULL
     AND cr.author_contact_id = v_cid
     AND cr.submitted_at IS NULL;

  v_changes_frozen  := document_changes_frozen(p_document_id, v_cid);
  -- requests freeze individually; this reports whether ANY pending one is frozen
  v_requests_frozen := EXISTS (
    SELECT 1 FROM contract_change_requests cr
     WHERE cr.document_id = p_document_id
       AND cr.parent_request_id IS NULL
       AND cr.author_contact_id = v_cid
       AND change_request_is_frozen(cr.id));

  RETURN jsonb_build_object(
    'document_id',      p_document_id,
    'other_party_role', v_other_role,
    'other_party_name', v_other_name,
    'changes',          v_changes,
    'requests',         v_requests,
    'has_changes',      v_changes  > 0,
    'has_requests',     v_requests > 0,
    'anything',         (v_changes + v_requests) > 0,
    -- the SAME booleans the enforcement paths test
    'changes_frozen',   v_changes_frozen,
    'requests_frozen',  v_requests_frozen);
END;
$$;


--
-- Name: FUNCTION pending_notify_summary(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pending_notify_summary(p_document_id uuid) IS 'THE single source of truth behind the Notify confirmation modal. Returns the counterparty ROLE name and the pending change/request counts the copy renders, alongside changes_frozen (document_changes_frozen) and requests_frozen (change_request_is_frozen) — the very predicates the enforcement paths test, so the modal copy and the rule cannot drift apart.';


--
-- Name: pending_version_decisions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_version_decisions() RETURNS TABLE(id uuid, template_key text, title text, from_version integer, to_version integer, occurred_at timestamp with time zone, past_signers bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id, e.template_key, coalesce(ct.title, e.template_key),
         e.from_version, e.to_version, e.occurred_at,
         (SELECT count(DISTINCT d.contact_id)
            FROM documents d JOIN contract_templates ct2 ON ct2.id = d.template_id
           WHERE ct2.template_key = e.template_key
             AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
             AND coalesce(d.signed_template_version, ct2.version) < e.to_version)
    FROM template_version_events e
    LEFT JOIN contract_templates ct ON ct.template_key = e.template_key
                                   AND ct.active AND ct.deleted_at IS NULL
   WHERE e.resolved_at IS NULL AND has_staff_access()
   ORDER BY e.occurred_at DESC
$$;


--
-- Name: FUNCTION pending_version_decisions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pending_version_decisions() IS 'Version bumps still awaiting a re-sign decision, with how many past signers are behind. Drives the prompt staff answer with ALL / SELECTED / NONE.';


--
-- Name: people_with_designation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_with_designation(p_designation text) RETURNS TABLE(contact_id uuid, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, nullif(btrim(coalesce(c.first_name,'')||' '||coalesce(c.last_name,'')), '')
  FROM staff_designations d
  JOIN contacts c ON c.id = d.contact_id
  WHERE d.org_id = current_org() AND d.designation = p_designation
    AND c.deleted_at IS NULL AND has_staff_access()
  ORDER BY c.last_name NULLS LAST, c.first_name;
$$;


--
-- Name: plan_horizon_through(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_horizon_through() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- the current month, materialised as it always was, PLUS one month generated
  -- pending. The last day of next month is where generation stops.
  SELECT (date_trunc('month', current_date) + interval '2 months' - interval '1 day')::date;
$$;


--
-- Name: platform_set_tenant_module(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_tenant_module(p_org_id uuid, p_module_key text, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(app_role(), '') <> 'SUPER_ADMIN' THEN
    RAISE EXCEPTION 'platform operator only';
  END IF;
  INSERT INTO org_modules (org_id, module_key, enabled, source)
  VALUES (p_org_id, p_module_key, p_enabled, 'GRANT')
  ON CONFLICT (org_id, module_key) DO UPDATE
    SET enabled = p_enabled, updated_at = now();
END;
$$;


--
-- Name: platform_set_tenant_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_tenant_status(p_org_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF coalesce(app_role(), '') <> 'SUPER_ADMIN' THEN
    RAISE EXCEPTION 'platform operator only';
  END IF;
  IF p_status NOT IN ('ACTIVE','SUSPENDED','ARCHIVED') THEN
    RAISE EXCEPTION 'status must be ACTIVE, SUSPENDED, or ARCHIVED';
  END IF;
  UPDATE organizations SET status = p_status, updated_at = now()
   WHERE id = p_org_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown organization';
  END IF;
END;
$$;


--
-- Name: platform_tenant_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_detail(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF coalesce(app_role(), '') <> 'SUPER_ADMIN' THEN
    RAISE EXCEPTION 'platform operator only';
  END IF;

  SELECT jsonb_build_object(
    'org', (SELECT jsonb_build_object(
        'id', o.id, 'name', o.name, 'slug', o.slug, 'status', o.status,
        'display_code', o.display_code, 'created_at', o.created_at)
      FROM organizations o WHERE o.id = p_org_id),
    'modules', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'module_key', m.module_key, 'name', m.name, 'description', m.description,
        'is_core', m.is_core,
        'enabled', coalesce(om.enabled, m.is_core),
        'source', om.source) ORDER BY m.is_core DESC, m.module_key), '[]'::jsonb)
      FROM modules m
      LEFT JOIN org_modules om ON om.module_key = m.module_key AND om.org_id = p_org_id
      WHERE m.active),
    'admins', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'user_id', p.user_id, 'email', p.email,
        'name', trim(concat_ws(' ', p.first_name, p.last_name)),
        'role', p.role) ORDER BY p.role, p.email), '[]'::jsonb)
      FROM profiles p
      WHERE p.org_id = p_org_id AND p.role IN ('ADMIN','MANAGER','EMPLOYEE')),
    'usage', jsonb_build_object(
      'members',     (SELECT count(*) FROM profiles WHERE org_id = p_org_id),
      'contacts',    (SELECT count(*) FROM contacts WHERE org_id = p_org_id),
      'engagements', (SELECT count(*) FROM contracts WHERE org_id = p_org_id AND deleted_at IS NULL),
      'horses',      (SELECT count(*) FROM horses WHERE org_id = p_org_id AND deleted_at IS NULL),
      'documents',   (SELECT count(*) FROM documents WHERE org_id = p_org_id AND deleted_at IS NULL))
  ) INTO v;
  RETURN v;
END;
$$;


--
-- Name: post_contract_comment(uuid, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_contract_comment(p_document_id uuid, p_body text, p_anchor_kind text DEFAULT 'document'::text, p_anchor_ref text DEFAULT NULL::text, p_quote text DEFAULT NULL::text, p_quote_prefix text DEFAULT NULL::text, p_parent_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_id uuid; v_cid uuid; v_role text; v_label text;
  v_parent_doc uuid; v_parent_resolved timestamptz; v_section text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'comment body required'; END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  IF p_parent_id IS NOT NULL THEN
    SELECT document_id, resolved_at INTO v_parent_doc, v_parent_resolved
      FROM contract_change_requests WHERE id = p_parent_id;
    IF v_parent_doc IS NULL OR v_parent_doc <> p_document_id THEN
      RAISE EXCEPTION 'reply target not on this document';
    END IF;
    IF v_parent_resolved IS NOT NULL THEN
      RAISE EXCEPTION 'this thread is resolved and closed to replies';
    END IF;
  END IF;

  SELECT contact_id, role, label INTO v_cid, v_role, v_label
    FROM comment_author_identity(p_document_id);

  v_section := CASE WHEN p_parent_id IS NULL THEN nullif(trim(p_anchor_ref),'') END;

  INSERT INTO contract_change_requests (
    org_id, document_id, parent_request_id, anchor_kind, anchor_ref, quote, quote_prefix,
    target_section, body, author_contact_id, author_role, author_label,
    submitted_at, impact_rank)
  VALUES (
    v_org, p_document_id, p_parent_id,
    CASE WHEN p_parent_id IS NOT NULL THEN 'document' ELSE coalesce(p_anchor_kind,'document') END,
    p_anchor_ref, p_quote, p_quote_prefix,
    v_section, trim(p_body), v_cid, v_role, v_label,
    now(), change_request_impact_rank(v_section))
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: post_contract_note_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_contract_note_message(p_note_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_doc uuid; v_id uuid; v_body text := nullif(trim(coalesce(p_body,'')),'');
  v_label text;
BEGIN
  IF v_body IS NULL THEN RAISE EXCEPTION 'an empty message cannot be posted'; END IF;
  SELECT org_id, document_id INTO v_org, v_doc FROM contract_notes
   WHERE id = p_note_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown note'; END IF;
  IF NOT (has_staff_access() OR EXISTS (
            SELECT 1 FROM document_parties dp
             WHERE dp.document_id = v_doc AND dp.contact_id = current_contact_id())) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  SELECT coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), c.email)
    INTO v_label FROM contacts c WHERE c.id = current_contact_id();

  INSERT INTO contract_note_messages (org_id, note_id, author_contact_id, author_label, body)
  VALUES (v_org, p_note_id, current_contact_id(), v_label, v_body)
  RETURNING id INTO v_id;

  UPDATE contract_notes SET updated_at = now() WHERE id = p_note_id;
  RETURN v_id;
END
$$;


--
-- Name: profiles_link_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_link_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM ensure_contact_for_profile(NEW.user_id);
  RETURN NEW;
END;
$$;


--
-- Name: profiles_role_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_role_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  -- controlled privileged paths (contract-invite redemption) set this flag
  -- transaction-locally inside a SECURITY DEFINER function.
  IF current_setting('app.allow_profile_link', true) = '1' THEN
    RETURN NEW;
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role
     OR NEW.is_admin IS DISTINCT FROM OLD.is_admin
     OR NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    IF NOT is_admin() THEN
      RAISE EXCEPTION 'only an admin may change role, admin flag, or org';
    END IF;
    IF (NEW.role = 'SUPER_ADMIN' OR OLD.role = 'SUPER_ADMIN')
       AND app_role() <> 'SUPER_ADMIN' THEN
      RAISE EXCEPTION 'only a super admin may grant or revoke super admin';
    END IF;
  END IF;

  -- Stage 1j: employment fields carry the old staff table's admin-only write.
  IF NEW.title IS DISTINCT FROM OLD.title
     OR NEW.pay_type IS DISTINCT FROM OLD.pay_type
     OR NEW.staff_active IS DISTINCT FROM OLD.staff_active THEN
    IF NOT is_admin() THEN
      RAISE EXCEPTION 'only an admin may change employment fields';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: profiles_sync_staff_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_sync_staff_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN   IF (NEW.role IN ('ADMIN','MANAGER','EMPLOYEE','SUPER_ADMIN') OR NEW.is_admin) THEN     PERFORM ensure_staff_profile(NEW.user_id);   END IF;   RETURN NEW; END; $$;


--
-- Name: promote_buyer_from_offering(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_buyer_from_offering() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_org     uuid;
  v_kind    text;
BEGIN
  SELECT p.buyer_contact_id, p.org_id INTO v_contact, v_org
    FROM purchases p WHERE p.id = NEW.purchase_id;
  IF v_contact IS NULL OR v_org IS NULL THEN RETURN NEW; END IF;

  SELECT o.config_kind INTO v_kind FROM offerings o WHERE o.id = NEW.offering_id;
  IF v_kind IS NULL OR v_kind = 'inquire' THEN RETURN NEW; END IF;

  -- Tags stay here: they describe the relationship and require nothing.
  PERFORM apply_affiliations(v_contact);

  -- ⚠️ THE DOCUMENTS MOVED to trg_documents_when_order_opens. Assigning them from
  -- here meant a line in a DRAFT cart created the obligation — before staff had
  -- approved anything, and before the client had committed to anything.
  RETURN NEW;
END;
$$;


--
-- Name: promote_contact_to_account(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_contact_to_account(p_user_id uuid, p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_denied_users constant uuid[] := ARRAY[
    'b45a5503-89bc-489a-b012-c7fbf5c09632',
    'fdbdfe89-76d7-486b-b734-8e23b09e0353',
    '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'
  ]::uuid[];
  c_denied_contacts constant uuid[] := ARRAY[
    '75475f66-8950-4f13-832c-5471070737f8',
    '862b7936-9148-465c-b0db-b83246e236a0',
    '352c3898-65d0-4a90-ad59-29107b7e03fe',
    'c6f7cddc-69da-4948-8e62-4a310f079100'
  ]::uuid[];
  v_profile   profiles%ROWTYPE;
  v_email     text;
  v_survivor  uuid;
  v_dissolved uuid;
  v_trail_cur int;
  v_trail_new int;
  v_refs      text;
  v_groups    text[];
BEGIN
  IF p_user_id IS NULL OR p_contact_id IS NULL THEN
    RAISE EXCEPTION 'promote_contact_to_account: user and contact are required';
  END IF;
  IF p_user_id = ANY(c_denied_users) OR p_contact_id = ANY(c_denied_contacts) THEN
    RAISE EXCEPTION 'promote_contact_to_account: identity is protected (D1) — refusing';
  END IF;
  IF EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND is_company) THEN
    RAISE EXCEPTION 'promote_contact_to_account: a company contact is never promoted or dissolved';
  END IF;

  SELECT * INTO v_profile FROM profiles WHERE user_id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'promote_contact_to_account: no profile for user %', p_user_id;
  END IF;
  SELECT lower(email) INTO v_email FROM auth.users WHERE id = p_user_id;

  PERFORM set_config('app.allow_profile_link', '1', true);

  IF v_profile.contact_id IS NULL OR v_profile.contact_id = p_contact_id THEN
    v_survivor  := p_contact_id;
    v_dissolved := NULL;
    UPDATE profiles SET contact_id = p_contact_id,
                        org_id = coalesce(org_id, (SELECT org_id FROM contacts WHERE id = p_contact_id))
     WHERE user_id = p_user_id AND contact_id IS DISTINCT FROM p_contact_id;
  ELSE
    IF v_profile.contact_id = ANY(c_denied_contacts) THEN
      RAISE EXCEPTION 'promote_contact_to_account: account is anchored to a protected contact — refusing';
    END IF;

    -- Evidence-based survivor: the contact carrying the document trail wins;
    -- tie → the contact whose email matches the account; last resort → the
    -- account's current link.
    SELECT (SELECT count(*) FROM documents        WHERE contact_id        = v_profile.contact_id AND deleted_at IS NULL)
         + (SELECT count(*) FROM document_parties WHERE contact_id        = v_profile.contact_id)
         + (SELECT count(*) FROM signatures       WHERE signer_contact_id = v_profile.contact_id AND deleted_at IS NULL)
      INTO v_trail_cur;
    SELECT (SELECT count(*) FROM documents        WHERE contact_id        = p_contact_id AND deleted_at IS NULL)
         + (SELECT count(*) FROM document_parties WHERE contact_id        = p_contact_id)
         + (SELECT count(*) FROM signatures       WHERE signer_contact_id = p_contact_id AND deleted_at IS NULL)
      INTO v_trail_new;

    IF v_trail_new > 0 AND v_trail_cur = 0 THEN
      v_survivor := p_contact_id;
    ELSIF v_trail_cur > 0 AND v_trail_new = 0 THEN
      v_survivor := v_profile.contact_id;
    ELSIF (SELECT lower(email) FROM contacts WHERE id = p_contact_id) = v_email
      AND (SELECT lower(coalesce(email,'')) FROM contacts WHERE id = v_profile.contact_id) IS DISTINCT FROM v_email THEN
      v_survivor := p_contact_id;
    ELSE
      v_survivor := v_profile.contact_id;
    END IF;
    v_dissolved := CASE WHEN v_survivor = p_contact_id THEN v_profile.contact_id ELSE p_contact_id END;

    -- ITEM 4: FAIL FAST. This scan used to run after the merge UPDATEs below,
    -- so a collision left the data half-moved and the account half-linked.
    -- Now it runs before any mutation: the function either merges completely
    -- or changes nothing at all.
    --
    -- Running it FIRST changes what it must exclude. Previously the migrated
    -- rows were already re-pointed by the time it ran, so they self-excluded.
    -- Now they are still present, so the scan must skip exactly the
    -- (table, column) pairs the merge block below handles — COLUMN-level, not
    -- table-level: documents.archived_by / voided_by / originator_contact_id
    -- and document_shares.granted_by_contact_id are NOT migrated and must
    -- still block a merge, even though sibling columns on those tables are.
    SELECT string_agg(t, ', ') INTO v_refs FROM (
      SELECT format('%s.%s', c.conrelid::regclass, a.attname) AS t
        FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
       WHERE c.contype = 'f' AND c.confrelid = 'contacts'::regclass
         AND c.conrelid NOT IN ('clients'::regclass, 'profiles'::regclass)
         AND a.attname <> 'deleted_by'
         AND (c.conrelid::regclass::text || '.' || a.attname) NOT IN (
               'documents.contact_id',
               'document_parties.contact_id',
               'signatures.signer_contact_id',
               'contract_parties.contact_id',
               'document_shares.shared_with_contact_id',
               'contact_required_documents.contact_id',
               'invitations.contact_id',
               'groups.contact_id')
         AND EXISTS (SELECT 1 FROM query_to_xml(
               format('SELECT 1 FROM %s WHERE %I = %L LIMIT 1', c.conrelid::regclass, a.attname, v_dissolved),
               false, true, '') x WHERE x IS DOCUMENT)
    ) refs;
    IF v_refs IS NOT NULL THEN
      RAISE EXCEPTION 'promote_contact_to_account: contact % still referenced by % — merge those first', v_dissolved, v_refs;
    END IF;

    UPDATE documents         SET contact_id        = v_survivor WHERE contact_id        = v_dissolved;
    UPDATE document_parties  SET contact_id        = v_survivor WHERE contact_id        = v_dissolved;
    PERFORM set_config('app.allow_signature_rekey', '1', true);
    UPDATE signatures        SET signer_contact_id = v_survivor WHERE signer_contact_id = v_dissolved;
    PERFORM set_config('app.allow_signature_rekey', '0', true);
    UPDATE contract_parties  SET contact_id        = v_survivor WHERE contact_id        = v_dissolved;
    UPDATE document_shares   SET shared_with_contact_id = v_survivor WHERE shared_with_contact_id = v_dissolved;
    UPDATE contact_required_documents SET contact_id = v_survivor WHERE contact_id = v_dissolved
      AND NOT EXISTS (SELECT 1 FROM contact_required_documents x
                       WHERE x.contact_id = v_survivor AND x.template_key = contact_required_documents.template_key);
    DELETE FROM contact_required_documents WHERE contact_id = v_dissolved;
    UPDATE invitations SET contact_id = v_survivor WHERE contact_id = v_dissolved;

    INSERT INTO clients (org_id, contact_id, source, client_since, customer_since)
    SELECT d.org_id, v_survivor, d.source, d.client_since, d.customer_since
      FROM clients d WHERE d.contact_id = v_dissolved AND d.deleted_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM clients s WHERE s.contact_id = v_survivor AND s.deleted_at IS NULL)
    LIMIT 1;
    UPDATE clients s SET
        client_since   = least(coalesce(s.client_since,  d.client_since),  coalesce(d.client_since,  s.client_since)),
        customer_since = least(coalesce(s.customer_since,d.customer_since),coalesce(d.customer_since,s.customer_since))
      FROM clients d
     WHERE s.contact_id = v_survivor AND s.deleted_at IS NULL
       AND d.contact_id = v_dissolved AND d.deleted_at IS NULL;
    UPDATE clients SET deleted_at = now() WHERE contact_id = v_dissolved AND deleted_at IS NULL;
    DELETE FROM groups WHERE contact_id = v_dissolved;

    UPDATE profiles SET contact_id = v_survivor WHERE user_id = p_user_id;
    UPDATE contacts SET deleted_at = now(), deleted_by = p_user_id WHERE id = v_dissolved;
  END IF;

  UPDATE signatures SET signer_user_id = p_user_id
   WHERE signer_contact_id = v_survivor AND signer_user_id IS NULL;

  INSERT INTO members (user_id, status, org_id)
  VALUES (p_user_id, 'active', (SELECT org_id FROM contacts WHERE id = v_survivor))
  ON CONFLICT (user_id) DO UPDATE SET status = 'active';

  v_groups := apply_affiliations(v_survivor);

  RETURN jsonb_build_object(
    'contact_id', v_survivor,
    'dissolved_contact_id', v_dissolved,
    'groups', to_jsonb(coalesce(v_groups, ARRAY[]::text[])));
END;
$$;


--
-- Name: promote_lookup_suggestion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_lookup_suggestion(p_id uuid, p_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_s lookup_suggestions%ROWTYPE; v_code text;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_s FROM lookup_suggestions WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown suggestion'; END IF;
  v_code := coalesce(nullif(p_code,''), upper(regexp_replace(v_s.raw_value, '[^a-zA-Z0-9]+', '_', 'g')));

  IF v_s.lookup_key = 'horse_breeds' THEN
    INSERT INTO horse_breeds (code, display_name, active, sort_order)
      VALUES (v_code, v_s.raw_value, true, 900) ON CONFLICT (code) DO UPDATE SET active=true;
  ELSIF v_s.lookup_key = 'horse_colors' THEN
    INSERT INTO horse_colors (code, display_name, active, sort_order)
      VALUES (v_code, v_s.raw_value, true, 900) ON CONFLICT (code) DO UPDATE SET active=true;
  ELSE
    INSERT INTO lookup_options (lookup_key, code, display_name, active, sort_order)
      VALUES (v_s.lookup_key, v_code, v_s.raw_value, true, 900)
      ON CONFLICT (lookup_key, code) DO UPDATE SET active=true;
  END IF;

  UPDATE lookup_suggestions SET status='promoted' WHERE id = p_id;
END;
$$;


--
-- Name: propose_booking_time(uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_booking_time(p_booking_id uuid, p_new_start timestamp with time zone, p_new_end timestamp with time zone, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b  bookings%ROWTYPE;
  v_cr booking_change_requests%ROWTYPE;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF p_new_start IS NULL OR p_new_end IS NULL OR p_new_end <= p_new_start THEN
    RAISE EXCEPTION 'pick a start and a later end';
  END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found in this org'; END IF;
  IF v_b.status NOT IN ('requested','pending') THEN
    RAISE EXCEPTION 'only a requested or pending booking can be countered'; END IF;

  SELECT * INTO v_cr FROM booking_change_requests
    WHERE booking_id = p_booking_id AND status = 'pending'
    ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'no open request on this booking to counter'; END IF;

  UPDATE booking_change_requests SET
    proposed_starts_at = p_new_start, proposed_ends_at = p_new_end,
    awaiting_client = true, staff_note = coalesce(p_note, staff_note)
  WHERE id = v_cr.id;

  IF v_b.account_user_id IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id, 'booking_time_proposed',
              'We proposed a different time — ' || to_char(p_new_start, 'FMMon FMDD, HH12:MI AM'),
              '/app/calendar');
  END IF;

  RETURN jsonb_build_object('change_id', v_cr.id, 'status', 'pending', 'awaiting_client', true);
END;
$$;


--
-- Name: propose_clause(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_clause(p_document_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_me uuid := current_contact_id(); v_num int; v_role text; v_id uuid; v_direct boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NULLIF(btrim(coalesce(p_body,'')),'') IS NULL THEN RAISE EXCEPTION 'the clause text is empty'; END IF;
  IF NOT caller_may_propose(p_document_id, 'add_clause') THEN RAISE EXCEPTION 'not permitted to add a clause'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'the document is not open for changes'; END IF;

  SELECT coalesce(max(item_number),0)+1 INTO v_num FROM contract_addenda WHERE document_id = p_document_id;
  SELECT party_role INTO v_role FROM document_parties WHERE document_id = p_document_id AND contact_id = v_me LIMIT 1;
  v_direct := caller_may_propose(p_document_id, 'edit_deal');

  INSERT INTO contract_addenda (org_id, document_id, item_number, body, proposed_by_contact_id, proposed_by_role,
                                status, resolved_by_contact_id, resolved_at)
    VALUES (v_org, p_document_id, v_num, btrim(p_body), v_me, v_role,
            CASE WHEN v_direct THEN 'accepted' ELSE 'open' END,
            CASE WHEN v_direct THEN v_me ELSE NULL END,
            CASE WHEN v_direct THEN now() ELSE NULL END)
    RETURNING id INTO v_id;

  IF v_direct THEN
    PERFORM rebuild_additional_terms(p_document_id);
  ELSE
    PERFORM redline_notify(p_document_id, 'contract_clause_proposed', 'A new clause was proposed on ');
  END IF;
  RETURN jsonb_build_object('addendum_id', v_id, 'item_number', v_num, 'applied', v_direct);
END;
$$;


--
-- Name: propose_community_event(text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_community_event(p_title text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location text DEFAULT NULL::text, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid := current_org();
  v_id    uuid;
  v_cats  text[] := my_purchase_categories();
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no org context';
  END IF;
  IF NOT coalesce('riding' = ANY(v_cats), false) AND NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'community events are for riders';
  END IF;
  IF p_title IS NULL OR btrim(p_title) = '' THEN
    RAISE EXCEPTION 'title required';
  END IF;
  IF p_starts_at IS NULL THEN
    RAISE EXCEPTION 'start time required';
  END IF;

  INSERT INTO events (title, description, starts_at, ends_at, location, published, org_id)
  VALUES (btrim(p_title), p_description, p_starts_at, p_ends_at, p_location, false, v_org)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: propose_contract_composition(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_contract_composition(p_document_id uuid, p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_me uuid := current_contact_id(); v_role text; v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT caller_may_propose(p_document_id, 'suggest') THEN
    RAISE EXCEPTION 'not permitted to suggest an item';
  END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'the document is not open for changes'; END IF;

  IF coalesce((p_spec->>'section_new')::boolean, false)
     OR nullif(btrim(coalesce(p_spec#>>'{header,clause_key}','')), '') IS NULL
     OR jsonb_array_length(coalesce(p_spec->'elements','[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'a suggested item must go into an existing section and item, with no new questions — create new sections/items directly if you have edit access';
  END IF;

  SELECT party_role INTO v_role FROM document_parties WHERE document_id = p_document_id AND contact_id = v_me LIMIT 1;

  INSERT INTO contract_pending_compositions (org_id, document_id, spec, proposed_by_contact_id, proposed_by_role, status)
    VALUES (v_org, p_document_id, p_spec, v_me, v_role, 'open')
    RETURNING id INTO v_id;

  PERFORM redline_notify(p_document_id, 'contract_item_proposed', 'A new item was suggested on ');
  RETURN jsonb_build_object('pending_id', v_id);
END;
$$;


--
-- Name: propose_field_edit(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_field_edit(p_document_id uuid, p_field_key text, p_proposed_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_state text; v_me uuid := current_contact_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT caller_may_propose(p_document_id, 'suggest') THEN RAISE EXCEPTION 'not permitted to propose changes'; END IF;
  SELECT workflow_state INTO v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_state NOT IN ('editable','editing') THEN RAISE EXCEPTION 'the document is not open for changes'; END IF;

  UPDATE contract_fields
     SET proposed_value = p_proposed_value, proposed_by_contact_id = v_me, proposed_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'no field % on this document', p_field_key; END IF;

  PERFORM redline_notify(p_document_id, 'contract_change_proposed', 'A change was proposed on ');
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: provision_client_invitation(text, text, text, text[], uuid[], text[], boolean, text, text, uuid, uuid, numeric, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_client_invitation(p_email text, p_first_name text, p_last_name text, p_categories text[], p_offering_ids uuid[] DEFAULT '{}'::uuid[], p_template_keys text[] DEFAULT NULL::text[], p_mark_paid boolean DEFAULT false, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid, p_partial_amount numeric DEFAULT 0, p_phone text DEFAULT NULL::text, p_agreed_lesson jsonb DEFAULT NULL::jsonb, p_send boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_contact  uuid;
  v_client   uuid;
  v_acct     jsonb;
  v_purchase uuid;
  v_inv_id   uuid;
  v_token    text;
  v_total    numeric := 0;
  v_labels   text[];
  v_has_off  boolean := (array_length(p_offering_ids, 1) IS NOT NULL);
  v_dup_purchase uuid;
  v_cats     text[];
  -- STABILIZE ITEM 2: the caller deliberately named no category (see below).
  v_no_cats  boolean := false;
  v_email    text := lower(trim(p_email));
  v_fn       text := nullif(trim(coalesce(p_first_name, '')), '');
  v_ln       text := nullif(trim(coalesce(p_last_name,  '')), '');
  v_ph       text := nullif(trim(coalesce(p_phone,      '')), '');
  v_linked   uuid;
  v_confirmed uuid[] := '{}';
  v_ord RECORD;   -- NOT `r`: `requests r` is aliased r throughout this body
  -- LESSONREQUEST §L3
  v_start    timestamptz;
  v_end      timestamptz;
  v_off      uuid;
  v_session  jsonb;
  v_agreed   jsonb := NULL;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'not authorized to provision invitations';
  END IF;
  IF v_email IS NULL OR v_email = '' THEN RAISE EXCEPTION 'email is required'; END IF;

  SELECT array_agg(DISTINCT upper(btrim(c))) INTO v_cats
    FROM unnest(coalesce(p_categories, '{}')) c WHERE btrim(c) <> '';
  -- ⚠️ CATEGORISE §2 — the "at least one category is required" guard USED TO BE
  -- HERE. It moved below the org resolution, unchanged, because the cart-derived
  -- default needs the org and nothing between here and there reads v_cats.

  v_org := p_org_id;
  IF v_org IS NULL AND v_has_off THEN
    SELECT o.org_id INTO v_org FROM offerings o WHERE o.id = p_offering_ids[1];
  END IF;
  IF v_org IS NULL AND p_request_id IS NOT NULL THEN
    SELECT r.org_id INTO v_org FROM requests r WHERE r.id = p_request_id;
  END IF;
  v_org := coalesce(v_org, current_org());
  IF v_org IS NULL THEN RAISE EXCEPTION 'could not resolve org for this invitation'; END IF;

  -- ── CATEGORISE §2 — WHEN NO CATEGORY WAS CHOSEN, THE CART DECIDES ────────
  --
  -- Until now the only categories this function ever saw were the ones a staff
  -- member ticked, and the screen's suggestion came from the FUNNEL the visitor
  -- happened to be standing in — so a cart holding a riding lesson and a horse
  -- clipping was filed under one of them and the person signed one of the two
  -- document sets. The cart is the fact; the funnel is an accident of navigation.
  --
  -- ⚠️ THE DERIVATION IS A DEFAULT, NOT A CAGE (§2). It runs ONLY when the caller
  -- named no category at all. A staff member who ticks boxes still gets exactly
  -- what they ticked, including a deliberate narrowing — a phone call can reveal
  -- what a cart cannot, in both directions.
  --
  -- `request_onboarding_categories` returns DISPLAY categories and already
  -- unions in whatever the contact holds, so this can only ever ADD. The token
  -- translation is `segment_categories`, not a second copy of the browser's
  -- CATEGORY_TOKEN map: 'Deal client' resolves to GUEST, which is the one label
  -- whose token is not simply its own name, and getting it wrong here would
  -- assign an acquisition client NOTHING (apply_category_documents rule 1a
  -- returns early on an unmatched category rather than raising).
  IF (v_cats IS NULL OR array_length(v_cats, 1) IS NULL) AND p_request_id IS NOT NULL THEN
    SELECT array_agg(DISTINCT x.tok) INTO v_cats
      FROM unnest(request_onboarding_categories(p_request_id)) c
      CROSS JOIN LATERAL (
        SELECT coalesce(
                 (SELECT sc.onboarding_token FROM segment_categories sc
                   WHERE sc.org_id = v_org AND sc.onboarding_category = c LIMIT 1),
                 upper(replace(btrim(c), ' ', '_'))) AS tok) x
     WHERE btrim(c) <> '';
  END IF;

  -- ── STABILIZE ITEM 2 — NO CATEGORY IS A CHOICE, NOT AN ERROR ─────────────
  --
  -- Owner, 2026-08-22: "an account gets tags that ENABLE an action, never
  -- OBLIGATE one on their own... For a party who signs nothing but the
  -- contract: select ZERO categories, not a new one."
  --
  -- This guard is what made that impossible. `RAISE EXCEPTION 'at least one
  -- category is required'` refused the very shape the owner needs — a person
  -- whose only relationship to the business is a contract, who never visits,
  -- never rides and never boards a horse, and therefore owes none of the
  -- category paperwork. It is replaced by a FLAG, not deleted: everything
  -- downstream that would otherwise DEFAULT an empty category set to GUEST
  -- reads it and assigns nothing instead.
  --
  -- ⚠️ NO NEW TOKEN AND NO SCHEMA CHANGE (owner ruling, same message).
  -- 'Deal client' keeps its PARTYROLE meaning exactly — a client who comes to
  -- the property and signs what any guest signs. Nothing about it moves here.
  v_no_cats := (v_cats IS NULL OR array_length(v_cats, 1) IS NULL);

  -- ITEM 2: when a request is named, its FK link is the truth. The email match
  -- inside _ensure_client_account remains the fallback for the null-link case.
  IF p_request_id IS NOT NULL THEN
    SELECT r.contact_id INTO v_linked
      FROM requests r WHERE r.id = p_request_id;
    IF v_linked IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM contacts c WHERE c.id = v_linked AND c.deleted_at IS NOT NULL) THEN
      v_contact := v_linked;
      -- ITEM 3: a linked LEAD becomes a real CONTACT at conversion.
      UPDATE contacts
         SET contact_type = CASE WHEN contact_type = 'LEAD' THEN 'CONTACT' ELSE contact_type END,
             first_name = CASE WHEN v_fn IS NOT NULL AND NULLIF(trim(coalesce(first_name,'')),'') IS NULL
                               THEN v_fn ELSE first_name END,
             last_name  = CASE WHEN v_ln IS NOT NULL AND NULLIF(trim(coalesce(last_name,'')),'') IS NULL
                               THEN v_ln ELSE last_name END
       WHERE id = v_contact;
      SELECT cl.id INTO v_client FROM clients cl
       WHERE cl.contact_id = v_contact AND cl.deleted_at IS NULL;
      IF v_client IS NULL THEN
        INSERT INTO clients (org_id, contact_id, source, client_since)
          VALUES (v_org, v_contact, 'provisioned invitation', now())
          RETURNING id INTO v_client;
      END IF;
      IF p_template_keys IS NOT NULL THEN
        INSERT INTO contact_required_documents (contact_id, template_key, org_id)
        SELECT v_contact, k, v_org FROM unnest(p_template_keys) k WHERE btrim(k) <> ''
        ON CONFLICT DO NOTHING;
      ELSIF NOT v_no_cats THEN
        PERFORM apply_category_documents(v_contact, v_cats);
      END IF;
      -- v_no_cats + no template_keys: assign nothing. Passing an empty array to
      -- apply_category_documents would NOT be a no-op here — with no categories
      -- it falls back to reading this contact's existing RIDER/HORSE_OWNER
      -- groups, which is the opposite of what "no category" was just asked for.
    END IF;
  END IF;

  -- single-sourced account creation (unchanged path when there is no link)
  IF v_contact IS NULL THEN
    -- ⚠️ `_ensure_client_account` DEFAULTS an empty p_categories to ARRAY['GUEST']
    -- and then, for a contact it just created, calls apply_category_documents
    -- with it — so passing NULL template keys alongside no categories would
    -- silently assign Company Policies, Facility Rules and the General Release
    -- to the one person who owes none of them. An EXPLICIT empty array takes the
    -- documented '{}' branch instead: nothing inserted, nothing deleted. Same
    -- call redeem_contract_invitation makes, for the same reason.
    v_acct    := _ensure_client_account(v_org, v_email, v_fn, v_ln, v_cats,
                   CASE WHEN v_no_cats THEN coalesce(p_template_keys, ARRAY[]::text[])
                        ELSE p_template_keys END);
    v_contact := (v_acct->>'contact_id')::uuid;
    v_client  := (v_acct->>'client_id')::uuid;
  END IF;

  -- ONBOARD §2: the phone the person just typed. Same conservative rule the
  -- names above follow — fill a blank, never overwrite what is already on file.
  IF v_ph IS NOT NULL AND v_contact IS NOT NULL THEN
    UPDATE contacts SET phone = v_ph
     WHERE id = v_contact AND nullif(btrim(coalesce(phone, '')), '') IS NULL;
  END IF;

  -- ── §C5b rule 5 / §C8 — CONFIRM THE INQUIRY'S OWN ORDER, IN THIS ACT ─────
  -- Adopted by request_id, which survives a §C5c split; the old exact-offering-
  -- set match did not, and would have minted a duplicate order for a split
  -- inquiry. draft -> awaiting_payment IS the moment anything becomes owed.
  --
  -- ⚠️ A HELD ORDER IS NOT CONFIRMED HERE. Order B stays `draft` while the horse
  -- is missing (§C5c): nothing is owed for work that cannot begin. It moves to
  -- awaiting_payment only when a horse appears (the horses trigger).
  IF p_request_id IS NOT NULL THEN
    FOR v_ord IN
      SELECT p.id FROM purchases p
       WHERE p.request_id = p_request_id
         AND p.deleted_at IS NULL
         AND p.status = 'draft'
         AND coalesce(p.current_status, '') <> 'awaiting_horse'
       ORDER BY p.created_at
    LOOP
      UPDATE purchases
         SET status = 'awaiting_payment',
             buyer_contact_id = coalesce(buyer_contact_id, v_contact),
             updated_at = now()
       WHERE id = v_ord.id;
      PERFORM log_status_event('order', v_ord.id, 'submitted',
        'Confirmed with the client — the invitation to activate was sent in the same act',
        v_org);
      v_confirmed := v_confirmed || v_ord.id;
      IF v_purchase IS NULL THEN v_purchase := v_ord.id; END IF;
    END LOOP;
  END IF;

  -- The offering-id path stays for staff-provisioned orders that had no inquiry
  -- behind them (the "client bought offline" case this function was built for).
  -- It is SKIPPED when the inquiry's own order was just confirmed, so one
  -- inquiry can never produce two orders.
  IF v_has_off AND array_length(v_confirmed, 1) IS NULL THEN
    SELECT p.id INTO v_dup_purchase
      FROM purchases p
     WHERE p.buyer_contact_id = v_contact AND coalesce(p.status,'') <> 'void' AND p.deleted_at IS NULL
       AND (SELECT array_agg(DISTINCT pi.offering_id ORDER BY pi.offering_id)
              FROM purchase_items pi WHERE pi.purchase_id = p.id)
           = (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(p_offering_ids) x)
     ORDER BY p.created_at DESC LIMIT 1;
    IF v_dup_purchase IS NOT NULL THEN
      v_purchase := v_dup_purchase;
    ELSE
      v_purchase := _provision_purchase_for_offerings(
        v_org, v_contact, v_client, p_offering_ids,
        p_mark_paid, p_payment_method, p_notes, p_partial_amount);
    END IF;
  END IF;

  -- ── LESSONREQUEST §L3 — THE AGREED TIME, IN THIS SAME ACT ────────────────
  --
  -- Runs AFTER the order is confirmed, because that transition is what mints
  -- the credit this booking draws down, and BEFORE the request is flipped to
  -- `invited` below — `schedule_lesson_session` sets it to `converted`, and
  -- `invited` is the truer word here: they have been invited, and conversion is
  -- what happens when they activate.
  --
  -- The visitor's `proposed_times` are NOT read, NOT copied and NOT overwritten.
  -- Staff choose the slot from the phone call; the ranges are shown beside the
  -- picker in the UI so an out-of-range choice is visible, never silent.
  IF p_agreed_lesson IS NOT NULL THEN
    v_start := nullif(btrim(coalesce(p_agreed_lesson->>'starts_at', '')), '')::timestamptz;
    v_end   := nullif(btrim(coalesce(p_agreed_lesson->>'ends_at',   '')), '')::timestamptz;
  END IF;

  IF v_start IS NOT NULL AND v_end IS NOT NULL THEN
    IF v_client IS NULL THEN
      RAISE EXCEPTION 'cannot book the agreed lesson: no client record was resolved for %', v_email;
    END IF;

    -- Which service the lesson is against: what staff named, else the first
    -- rider-segment line ON THE ORDER THEY JUST CONFIRMED. Read from the order
    -- rather than guessed, so the booking draws down the thing they bought.
    v_off := nullif(btrim(coalesce(p_agreed_lesson->>'offering_id', '')), '')::uuid;
    IF v_off IS NULL AND v_purchase IS NOT NULL THEN
      SELECT pi.offering_id INTO v_off
        FROM purchase_items pi
        JOIN offerings o ON o.id = pi.offering_id
       WHERE pi.purchase_id = v_purchase AND pi.voided_at IS NULL AND o.segment = 'rider'
       ORDER BY pi.created_at
       LIMIT 1;
    END IF;

    -- THE INCUMBENT WRITER. Not an INSERT here; not a second one anywhere.
    SELECT schedule_lesson_session(
             v_client, v_start, v_end,
             NULL,                                                            -- p_engagement_id
             p_request_id,
             nullif(btrim(coalesce(p_agreed_lesson->>'location', '')), ''),
             nullif(btrim(coalesce(p_agreed_lesson->>'notes',    '')), ''),
             nullif(btrim(coalesce(p_agreed_lesson->>'horse_id', '')), '')::uuid,
             v_off,
             nullif(btrim(coalesce(p_agreed_lesson->>'instructor_user_id', '')), '')::uuid,
             v_purchase)
      INTO v_session;

    v_agreed := jsonb_build_object(
      'booking_id', v_session->>'session_id',
      'starts_at',  v_start,
      'ends_at',    v_end,
      'offering_id', v_off,
      'credit_id',  v_session->>'credit_id');

    -- The agreement goes on the order's own timeline, so it is visible wherever
    -- staff open the order — not only on the lead drawer that produced it.
    --
    -- ⚠️ THE SLOT IS DELIBERATELY NOT SPELLED OUT IN THIS SENTENCE. There is no
    -- tenant timezone anywhere in this database (checked: no `timezone`-shaped
    -- column exists on any table), so a server-side `to_char` renders UTC — the
    -- first draft of this line printed a 4pm lesson as "11:00 PM". The booking
    -- row already holds the instant, and every surface that shows it renders it
    -- in the reader's own zone. One fact, one home, no invented configuration.
    -- The wider defect this exposed is reported, not silently worked around.
    IF v_purchase IS NOT NULL THEN
      PERFORM log_status_event('order', v_purchase, 'time_agreed',
        'The first lesson was booked in the same act — see the calendar entry for the slot',
        v_org);
    END IF;
  END IF;

  IF v_has_off THEN
    SELECT coalesce(sum(o.price_amount), 0), array_agg(o.name) INTO v_total, v_labels
      FROM offerings o WHERE o.id = ANY(p_offering_ids);
  ELSIF v_purchase IS NOT NULL THEN
    -- The labels the invitation email names come from the confirmed order.
    SELECT coalesce(sum(pi.price_amount), 0), array_agg(pi.label)
      INTO v_total, v_labels
      FROM purchase_items pi WHERE pi.purchase_id = v_purchase AND pi.voided_at IS NULL;
  END IF;

  -- ── PAMELA §A — SAVE AND SEND ARE TWO ACTS ON ONE ROW ───────────────────
  --
  -- A DRAFT is an account that exists and whose claim link has never been
  -- delivered. Re-saving updates that same draft rather than minting a second
  -- token, so the invitation history stays a record of what was actually issued
  -- instead of filling with one row per keystroke of staff second-guessing.
  -- Sending promotes the draft in place: the owner sends the link he saved.
  SELECT i.id, i.token INTO v_inv_id, v_token
    FROM invitations i
   WHERE i.org_id = v_org AND lower(i.email) = v_email
     AND i.status = 'draft' AND i.deleted_at IS NULL
   ORDER BY i.created_at DESC
   LIMIT 1;

  IF v_inv_id IS NOT NULL THEN
    UPDATE invitations
       SET status        = CASE WHEN p_send THEN 'sent' ELSE 'draft' END,
           request_id    = coalesce(p_request_id, request_id),
           expires_at    = now() + (invitation_expiry_days(v_org) || ' days')::interval,
           first_name    = coalesce(v_fn, first_name),
           last_name     = coalesce(v_ln, last_name),
           contact_id    = coalesce(v_contact, contact_id),
           categories    = v_cats,
           offering_ids  = nullif(p_offering_ids, '{}'),
           template_keys = p_template_keys
     WHERE id = v_inv_id;
  ELSE
    v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
    INSERT INTO invitations (org_id, request_id, email, token, expires_at, status,
                             first_name, last_name, contact_id, categories, offering_ids, template_keys)
      VALUES (v_org, p_request_id, v_email, v_token,
              now() + (invitation_expiry_days(v_org) || ' days')::interval,
              CASE WHEN p_send THEN 'sent' ELSE 'draft' END,
              v_fn, v_ln, v_contact, v_cats, nullif(p_offering_ids, '{}'), p_template_keys)
      RETURNING id INTO v_inv_id;
  END IF;

  -- INVITEWORKS: the new link is live, so any older live link for this person is
  -- not. Same call the plain path makes, so a resend behaves identically however
  -- the invitation was created: one live token, the prior one kept as trail.
  IF p_send THEN PERFORM supersede_invitations(v_org, v_email, v_inv_id); END IF;

  -- ⚠️ THE DOOR ASSIGNS ITS OWN PAPERWORK, whatever version of the client called.
  -- `p_categories` is how the self-service endpoint names the path it came from
  -- (PATH_CATEGORIES: rider -> RIDER, horse -> HORSE_OWNER, guest -> GUEST). The
  -- newer endpoint calls apply_sign_path_documents itself; this makes the spine
  -- work without it, so a migration can never again land ahead of its code and
  -- leave real people with an account and no paperwork.
  -- Skipped entirely when the caller named documents explicitly — an explicit
  -- list is an instruction, including an empty one (PARTYROLE 2026-08-17).
  IF p_template_keys IS NULL AND NOT v_no_cats AND v_contact IS NOT NULL THEN
    PERFORM apply_sign_path_documents(v_contact, _sign_path_for_categories(v_cats));
  END IF;

  -- The invitation now EXISTS, so it is evidence. Recompute through the sole
  -- writer: the contact record shows the chosen category immediately, and it is
  -- the same computation activation will run, so the two cannot disagree.
  PERFORM apply_affiliations(v_contact);

  -- ORCH4: sending is what invites somebody. A save has issued nothing,
  -- so the request stays where it was and its alert stays open.
  IF p_request_id IS NOT NULL AND p_send THEN
    UPDATE requests SET status = 'invited' WHERE id = p_request_id;
    -- ITEM 5b: the request has been acted on; its inbound alert is done.
    PERFORM resolve_notifications_for_link(
      '/app/ops/intake?request=' || p_request_id::text, auth.uid(), 'request_new');
  END IF;

  RETURN jsonb_build_object(
    'invitation_id', v_inv_id, 'token', v_token, 'contact_id', v_contact,
    'purchase_id', v_purchase, 'categories', v_cats, 'amount', coalesce(v_total, 0),
    'labels', coalesce(v_labels, ARRAY[]::text[]), 'request_id', p_request_id,
    'confirmed_orders', to_jsonb(v_confirmed),
    'client_id', v_client,
    'agreed_lesson', v_agreed);
END;
$$;


--
-- Name: provision_tenant(text, text, text, text, uuid, jsonb, jsonb, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_tenant(p_name text, p_slug text, p_tier_key text, p_admin_email text, p_admin_user_id uuid DEFAULT NULL::uuid, p_brand jsonb DEFAULT '{}'::jsonb, p_legal jsonb DEFAULT '{}'::jsonb, p_rates jsonb DEFAULT '{}'::jsonb, p_modules text[] DEFAULT NULL::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org       uuid;
  v_template  uuid;   -- the operator/template org (tenant #1) whose catalog we clone
  v_barn_payer uuid;
  r           record;
BEGIN
  -- SUPER_ADMIN only — platform provisioning is a platform-owner path (§9).
  -- `IS NOT TRUE` (not `NOT …`) so anon/outsider (is_super_admin() → NULL) is denied,
  -- not silently admitted by NULL propagation.
  IF is_super_admin() IS NOT TRUE THEN
    RAISE EXCEPTION 'provision_tenant is restricted to SUPER_ADMIN'
      USING errcode = 'insufficient_privilege';
  END IF;

  IF p_slug IS NULL OR btrim(p_slug) = '' THEN
    RAISE EXCEPTION 'provision_tenant requires a non-empty slug';
  END IF;
  IF p_tier_key IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM tiers WHERE tier_key = p_tier_key) THEN
    RAISE EXCEPTION 'unknown tier: %', p_tier_key;
  END IF;

  -- ------------------------------------------------------------
  -- 1. Create org. slug is UNIQUE (mig 24); a duplicate raises here and the WHOLE
  --    function rolls back — atomic, no partial tenant. The ORG- display code is set
  --    by the existing organizations_set_code trigger.
  -- ------------------------------------------------------------
  INSERT INTO organizations (name, slug, status)
    VALUES (p_name, p_slug, 'ACTIVE')
    RETURNING id INTO v_org;

  -- Resolve to the new tenant BEFORE any user exists: every DEFAULT current_org() and
  -- boundary check below now stamps v_org (auth.uid() IS NULL in this DEFINER context
  -- for the seed/service caller → current_org() reads the app.current_org GUC).
  PERFORM set_config('app.current_org', v_org::text, true);  -- SET LOCAL (txn-scoped)

  -- The template org whose default catalog we clone (the operator's own, tenant #1).
  SELECT id INTO v_template FROM organizations
    WHERE id <> v_org ORDER BY created_at LIMIT 1;

  -- ------------------------------------------------------------
  -- 2. Seed the value registry.
  --    business_config typed row (legal + rates); config_values BRAND/CONTACT + knobs.
  --    Every value nullable/overridable, so an unfinished tenant still boots.
  -- ------------------------------------------------------------
  INSERT INTO business_config (
    org_id,
    legal_entity_name, entity_formation, registered_agent,
    signatory_name, signatory_title, business_address,
    commission_purchase_rate, commission_sale_rate, commission_lease_rate, commission_min,
    cancellation_fee, late_fee, no_show_fee,
    protection_period, sales_tax_rate, document_retention, esignature_provider
  ) VALUES (
    v_org,
    NULLIF(p_legal->>'LEGAL_NAME',''),
    NULLIF(p_legal->>'ENTITY_FORMATION',''),
    NULLIF(p_legal->>'REGISTERED_AGENT',''),
    NULLIF(p_legal->>'SIGNATORY_NAME',''),
    NULLIF(p_legal->>'SIGNATORY_TITLE',''),
    NULLIF(p_legal->>'ADDRESS',''),
    (p_rates->>'COMMISSION_PURCHASE_RATE')::numeric,
    (p_rates->>'COMMISSION_SALE_RATE')::numeric,
    (p_rates->>'COMMISSION_LEASE_RATE')::numeric,
    (p_rates->>'COMMISSION_MIN')::numeric,
    (p_rates->>'CANCELLATION_FEE')::numeric,
    (p_rates->>'LATE_FEE')::numeric,
    (p_rates->>'NO_SHOW_FEE')::numeric,
    NULLIF(p_legal->>'PROTECTION_PERIOD',''),
    (p_rates->>'SALES_TAX_RATE')::numeric,
    NULLIF(p_legal->>'DOCUMENT_RETENTION',''),
    NULLIF(p_legal->>'ESIGN_PROVIDER','')
  );

  -- Brand + contact + module knobs from p_brand. Keys prefixed BRAND./CONTACT./
  -- MODULE.<mod>. route to the matching namespace; a bare key defaults to BRAND.
  FOR r IN SELECT key, value FROM jsonb_each_text(COALESCE(p_brand, '{}'::jsonb)) LOOP
    INSERT INTO config_values (org_id, namespace, key, value_text, category)
    VALUES (
      v_org,
      CASE
        WHEN r.key LIKE 'CONTACT.%' THEN 'CONTACT'
        WHEN r.key LIKE 'BRAND.%'   THEN 'BRAND'
        WHEN r.key LIKE 'MODULE.%'  THEN split_part(r.key, '.', 2)
        ELSE 'BRAND'
      END,
      CASE
        WHEN r.key LIKE 'CONTACT.%' THEN substr(r.key, length('CONTACT.') + 1)
        WHEN r.key LIKE 'BRAND.%'   THEN substr(r.key, length('BRAND.') + 1)
        WHEN r.key LIKE 'MODULE.%'  THEN substr(r.key, length('MODULE.') + length(split_part(r.key,'.',2)) + 2)
        ELSE r.key
      END,
      r.value,
      CASE
        WHEN r.key LIKE 'CONTACT.%' THEN 'contact'
        WHEN r.key LIKE 'MODULE.%'  THEN 'module_config'
        ELSE 'branding'
      END
    )
    ON CONFLICT (org_id, namespace, key) DO UPDATE SET value_text = EXCLUDED.value_text;
  END LOOP;

  -- ------------------------------------------------------------
  -- 3. Seed entitlements: expand the tier (via tier_modules) + explicit add-ons into
  --    org_modules so has_module() lights up exactly the paid surfaces.
  -- ------------------------------------------------------------
  IF p_tier_key IS NOT NULL THEN
    INSERT INTO org_modules (org_id, module_key, enabled, source)
    SELECT v_org, tm.module_key, true, 'TIER'
      FROM tier_modules tm
      WHERE tm.tier_key = p_tier_key
    ON CONFLICT (org_id, module_key) DO NOTHING;
  END IF;

  IF p_modules IS NOT NULL THEN
    INSERT INTO org_modules (org_id, module_key, enabled, source)
    SELECT v_org, m.module_key, true, 'ADDON'
      FROM unnest(p_modules) AS m(module_key)
      WHERE EXISTS (SELECT 1 FROM modules mm WHERE mm.module_key = m.module_key)
    ON CONFLICT (org_id, module_key) DO NOTHING;
  END IF;

  -- ------------------------------------------------------------
  -- 4. Clone the tier's default catalog: copy the template org's active products
  --    (+ their current price rows) whose module_key is core (NULL) or in the new
  --    tenant's granted module set, into v_org. A no-op when the template has no
  --    seeded catalog; wires the real path so a seeded default catalog flows through.
  -- ------------------------------------------------------------
  IF v_template IS NOT NULL THEN
    FOR r IN
      SELECT p.id, p.product_key, p.name, p.service_type, p.module_key, p.price_value_key, p.active
        FROM products p
        WHERE p.org_id = v_template
          AND p.deleted_at IS NULL
          AND (
            p.module_key IS NULL
            OR EXISTS (SELECT 1 FROM org_modules om
                        WHERE om.org_id = v_org AND om.module_key = p.module_key AND om.enabled)
          )
    LOOP
      WITH new_prod AS (
        INSERT INTO products (org_id, product_key, name, service_type, module_key, price_value_key, active)
        VALUES (v_org, r.product_key, r.name, r.service_type, r.module_key, r.price_value_key, r.active)
        ON CONFLICT (org_id, product_key) DO NOTHING
        RETURNING id
      )
      INSERT INTO product_prices (org_id, product_id, amount, effective_from, effective_to)
      SELECT v_org, np.id, pp.amount, now(), NULL
        FROM new_prod np
        JOIN LATERAL (
          SELECT amount FROM product_prices
            WHERE product_id = r.id AND deleted_at IS NULL
              AND effective_from <= now()
              AND (effective_to IS NULL OR effective_to > now())
            ORDER BY effective_from DESC LIMIT 1
        ) pp ON true;
    END LOOP;
  END IF;

  -- ------------------------------------------------------------
  -- 5. First ADMIN. The /api layer find-or-creates the auth user (idempotent by
  --    email); here we bind the tenant ADMIN profile. The profiles->contact trigger
  --    binds identity. Skipped when no auth user id is supplied (assisted onboarding
  --    can attach the admin later); the tenant still boots. Done BEFORE the barnops
  --    starter so the admin's contact can serve as the barn/default payer.
  -- ------------------------------------------------------------
  IF p_admin_user_id IS NOT NULL THEN
    INSERT INTO profiles (user_id, email, role, org_id)
    VALUES (p_admin_user_id, p_admin_email, 'ADMIN', v_org)
    ON CONFLICT (user_id) DO UPDATE SET role = 'ADMIN', org_id = v_org;
    -- the profiles->contact trigger bound a contact; resolve it as the barn payer.
    SELECT contact_id INTO v_barn_payer FROM profiles WHERE user_id = p_admin_user_id;
  END IF;

  -- Barn-ops starter: a SINGLE default/barn-scoped cost_allocation_rules fallback (NOT
  -- a per-horse "100% owner" override — the split derives from horse_relationships, §7.7).
  -- Deferred/conditional: only when the mod.barnops table already exists (U11 shipped)
  -- AND the tenant has barnops AND a barn payer contact is resolvable (the column is
  -- NOT NULL). This lets U6 apply and green BEFORE U11 exists, and skips cleanly when
  -- no admin contact anchors the barn payer (the resolver still routes uncovered
  -- remainder to an explicit default line at billing time — §7.7).
  IF v_barn_payer IS NOT NULL
     AND to_regclass('public.cost_allocation_rules') IS NOT NULL
     AND EXISTS (SELECT 1 FROM org_modules om
                  WHERE om.org_id = v_org AND om.module_key = 'mod.barnops' AND om.enabled) THEN
    EXECUTE
      'INSERT INTO cost_allocation_rules (org_id, scope, scope_id, payer_contact_id, share_pct, effective_from) '
      'VALUES ($1, ''default'', NULL, $2, 100, now())'
      USING v_org, v_barn_payer;
  END IF;

  -- ------------------------------------------------------------
  -- 6. Audit PROVISION_TENANT + return. The organizations INSERT already emits an
  --    audit row (action INSERT, table organizations); this explicit marker records
  --    the provisioning action itself (SECURITY DEFINER writes past audit_logs RLS).
  --    action stays within the mig-6 CHECK (INSERT); table_name carries the semantic.
  -- ------------------------------------------------------------
  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, new_value)
  VALUES (
    auth.uid(), 'INSERT', 'provision_tenant', v_org,
    jsonb_build_object('event', 'PROVISION_TENANT', 'org_id', v_org,
                       'slug', p_slug, 'tier_key', p_tier_key,
                       'modules', COALESCE(p_modules, ARRAY[]::text[]))
  );

  RETURN v_org;
END;
$_$;


--
-- Name: FUNCTION provision_tenant(p_name text, p_slug text, p_tier_key text, p_admin_email text, p_admin_user_id uuid, p_brand jsonb, p_legal jsonb, p_rates jsonb, p_modules text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.provision_tenant(p_name text, p_slug text, p_tier_key text, p_admin_email text, p_admin_user_id uuid, p_brand jsonb, p_legal jsonb, p_rates jsonb, p_modules text[]) IS 'U6: the single blessed SUPER_ADMIN-only push-button tenant provisioning path (org + registry + entitlements + cloned catalog + first ADMIN), one atomic transaction. §9.';


--
-- Name: public_offerings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_offerings(p_slug text DEFAULT NULL::text) RETURNS TABLE(id uuid, segment text, name text, tagline text, description text, slug text, service_type text, price_amount numeric, price_unit text, price_min numeric, purchase_type text, horse_included boolean, is_popular boolean, note text, sort_order integer, price_model jsonb, config_kind text, unit_count integer, weekly_frequency integer, badge_label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.id, o.segment, o.name, o.tagline, o.description, o.slug,
         o.service_type, o.price_amount, o.price_unit, o.price_min,
         o.purchase_type::text, o.horse_included, o.is_popular,
         o.note, o.sort_order, o.price_model,
         o.config_kind, o.unit_count, o.weekly_frequency, o.badge_label
  FROM offerings o
  JOIN organizations org ON org.id = o.org_id
  WHERE o.active
    AND org.id = COALESCE((SELECT id FROM organizations WHERE slug = p_slug),
      'e656f20b-ef43-4725-9029-19e7f0190d9c'::uuid)
  ORDER BY o.segment, o.sort_order, o.name
$$;


--
-- Name: publish_open_slots(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_open_slots(p_weeks integer DEFAULT 4, p_slot_minutes integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org(); v_n integer;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no organization in session'; END IF;
  v_n := _publish_open_slots_for_org(v_org, p_weeks, p_slot_minutes);
  RETURN jsonb_build_object('published', v_n, 'weeks', p_weeks, 'slot_minutes', p_slot_minutes);
END;
$$;


--
-- Name: publish_open_slots_all(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_open_slots_all(p_weeks integer DEFAULT 4, p_slot_minutes integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_total integer := 0; v_orgs integer := 0;
BEGIN
  FOR r IN SELECT DISTINCT org_id FROM business_hours WHERE NOT closed LOOP
    v_total := v_total + _publish_open_slots_for_org(r.org_id, p_weeks, p_slot_minutes);
    v_orgs := v_orgs + 1;
  END LOOP;
  RETURN jsonb_build_object('published', v_total, 'orgs', v_orgs, 'weeks', p_weeks);
END;
$$;


--
-- Name: purge_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_account(p_user_id uuid, p_confirm text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- the ONLY identities this routine may ever touch
  c_allowed_emails constant text[] := ARRAY[
    'cjzigs@icloud.com',
    'charlesjzigmund@gmail.com'
  ]::text[];
  -- The routine must be PROVABLE before it is trusted with the real test
  -- identities. A synthetic proof account is admitted ONLY inside an explicit
  -- transaction-local flag that a caller must set deliberately; it can never
  -- widen the allowlist for a real identity (the denylist checks below still
  -- run, and the address is a reserved non-routable test domain).
  c_proof_domain constant text := '@purge-proof.invalid';
  -- belt-and-braces: never these, whatever their email says
  c_denied_users constant uuid[] := ARRAY[
    'b45a5503-89bc-489a-b012-c7fbf5c09632',  -- admin@fhequestrian.com
    'fdbdfe89-76d7-486b-b734-8e23b09e0353',  -- hello@fhequestrian.com
    '3c5d6af1-ce10-45c0-afbb-1ddbdfc77bd5'   -- admin@cactai.io (platform)
  ]::uuid[];
  c_denied_contacts constant uuid[] := ARRAY[
    '75475f66-8950-4f13-832c-5471070737f8',
    '862b7936-9148-465c-b0db-b83246e236a0',
    '352c3898-65d0-4a90-ad59-29107b7e03fe',
    'c6f7cddc-69da-4948-8e62-4a310f079100'
  ]::uuid[];
  v_email    text;
  v_contact  uuid;
  v_client   uuid;
  r          record;
  v_sql      text;
  v_counts   jsonb := '{}'::jsonb;
  v_n        bigint;
BEGIN
  IF p_confirm IS DISTINCT FROM 'PURGE' THEN
    RAISE EXCEPTION 'purge_account: confirmation token required';
  END IF;

  SELECT lower(email) INTO v_email FROM auth.users WHERE id = p_user_id;
  IF v_email IS NULL THEN RAISE EXCEPTION 'purge_account: no such account'; END IF;

  -- ── THE STRUCTURAL GATE ───────────────────────────────────────────────────
  IF NOT coalesce(
       v_email = ANY(c_allowed_emails)
       OR (v_email LIKE '%' || c_proof_domain
           AND current_setting('app.purge_proof', true) = '1')
     , false) THEN
    RAISE EXCEPTION 'purge_account: % is not on the allowlist — refusing', v_email;
  END IF;
  IF p_user_id = ANY(c_denied_users) THEN
    RAISE EXCEPTION 'purge_account: protected identity — refusing';
  END IF;

  SELECT contact_id INTO v_contact FROM profiles WHERE user_id = p_user_id;
  IF v_contact = ANY(c_denied_contacts) THEN
    RAISE EXCEPTION 'purge_account: account is anchored to a protected contact — refusing';
  END IF;
  IF v_contact IS NOT NULL AND EXISTS (SELECT 1 FROM contacts WHERE id = v_contact AND is_company) THEN
    RAISE EXCEPTION 'purge_account: company contact — refusing';
  END IF;
  SELECT id INTO v_client FROM clients WHERE contact_id = v_contact;

  -- ── 1. Attribution columns: NULL them (keep the row, drop the pointer) ────
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col, c.confrelid::regclass::text AS ref
      FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
     WHERE c.contype = 'f'
       AND c.confrelid IN ('contacts'::regclass, 'profiles'::regclass, 'clients'::regclass)
       AND c.conrelid <> 'profiles'::regclass
       AND (a.attname IN ('deleted_by','updated_by','created_by','edited_by','administered_by')
            OR a.attname ~ '(actor|author|granted_by|proposed_by|resolved_by|requested_by|entered_by|cancelled_by|archived_by|confirmed_by|created_by)')
  LOOP
    IF r.ref = 'contacts' AND v_contact IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'clients'  AND v_client  IS NULL THEN CONTINUE; END IF;
    v_sql := format('UPDATE %s SET %I = NULL WHERE %I = %L',
                    r.tbl, r.col, r.col,
                    (CASE r.ref WHEN 'contacts' THEN v_contact
                                WHEN 'clients'  THEN v_client
                                ELSE p_user_id END)::text);
    EXECUTE v_sql;
  END LOOP;

  -- ── 2. Ownership rows: delete, children first ────────────────────────────
  -- documents carry the deepest chains; clear them before the anchors.
  IF v_contact IS NOT NULL THEN
    DELETE FROM esign_consents        WHERE contact_id = v_contact;
    DELETE FROM signatures            WHERE signer_contact_id = v_contact;
    DELETE FROM document_shares       WHERE shared_with_contact_id = v_contact;
    DELETE FROM document_deliveries   WHERE recipient_contact_id = v_contact;
    DELETE FROM document_party_archives WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM document_party_controls WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM contract_change_log   WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM contract_change_requests WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM contract_addenda      WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM contract_fields       WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM contract_execution_audit WHERE document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM document_parties      WHERE contact_id = v_contact
                                         OR document_id IN (SELECT id FROM documents WHERE contact_id = v_contact);
    DELETE FROM documents             WHERE contact_id = v_contact;
    DELETE FROM contract_parties      WHERE contact_id = v_contact;
    DELETE FROM contact_required_documents WHERE contact_id = v_contact;
    DELETE FROM groups                WHERE contact_id = v_contact;
    DELETE FROM evaluation_report_shares WHERE shared_with_contact_id = v_contact;
    DELETE FROM evaluation_reports    WHERE contact_id = v_contact;
    DELETE FROM horse_relationships   WHERE party_contact_id = v_contact;
    UPDATE horses SET current_owner_contact_id = NULL WHERE current_owner_contact_id = v_contact;
    UPDATE horses SET lessee_contact_id = NULL WHERE lessee_contact_id = v_contact;
    DELETE FROM billable_lines        WHERE payer_contact_id = v_contact;
    DELETE FROM cost_allocation_rules WHERE payer_contact_id = v_contact;
    DELETE FROM board_agreements      WHERE boarder_contact_id = v_contact;
    UPDATE contacts SET guardian_contact_id = NULL WHERE guardian_contact_id = v_contact;
  END IF;

  -- money + fulfillment spine
  DELETE FROM fulfillment_units WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_user_id = p_user_id OR buyer_contact_id = v_contact);
  DELETE FROM receipt_sends WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_user_id = p_user_id OR buyer_contact_id = v_contact);
  DELETE FROM purchase_items WHERE purchase_id IN (
    SELECT id FROM purchases WHERE buyer_user_id = p_user_id OR buyer_contact_id = v_contact);
  DELETE FROM status_events WHERE entity_type = 'order' AND entity_id IN (
    SELECT id FROM purchases WHERE buyer_user_id = p_user_id OR buyer_contact_id = v_contact);
  DELETE FROM purchases WHERE buyer_user_id = p_user_id OR buyer_contact_id = v_contact;

  -- bookings + credits
  DELETE FROM bookings WHERE account_user_id = p_user_id OR account_contact_id = v_contact
                          OR (v_client IS NOT NULL AND client_id = v_client);
  IF v_client IS NOT NULL THEN
    DELETE FROM lesson_credits WHERE client_id = v_client;
  END IF;

  -- community
  DELETE FROM feed_seen          WHERE user_id = p_user_id;
  DELETE FROM feed_shares        WHERE from_user_id = p_user_id OR to_user_id = p_user_id;
  DELETE FROM feed_account_items WHERE user_id = p_user_id;
  DELETE FROM feed_view_pref     WHERE user_id = p_user_id;
  DELETE FROM feed_posts         WHERE author_id = p_user_id;
  DELETE FROM content_acknowledgments WHERE user_id = p_user_id;
  DELETE FROM notifications      WHERE user_id = p_user_id;
  DELETE FROM members            WHERE user_id = p_user_id;
  DELETE FROM invitations        WHERE contact_id = v_contact
                                    OR lower(email) = v_email;

  -- anchors last
  IF v_client IS NOT NULL THEN DELETE FROM clients WHERE id = v_client; END IF;
  DELETE FROM profiles WHERE user_id = p_user_id;
  IF v_contact IS NOT NULL THEN DELETE FROM contacts WHERE id = v_contact; END IF;
  DELETE FROM auth.users WHERE id = p_user_id;

  -- ── 3. Orphan sweep: prove nothing still points at the purged identity ────
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col, c.confrelid::regclass::text AS ref
      FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
     WHERE c.contype = 'f'
       AND c.confrelid IN ('contacts'::regclass, 'profiles'::regclass, 'clients'::regclass)
  LOOP
    IF r.ref = 'contacts' AND v_contact IS NULL THEN CONTINUE; END IF;
    IF r.ref = 'clients'  AND v_client  IS NULL THEN CONTINUE; END IF;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I = %L', r.tbl, r.col,
                   (CASE r.ref WHEN 'contacts' THEN v_contact
                               WHEN 'clients'  THEN v_client
                               ELSE p_user_id END)::text) INTO v_n;
    IF v_n > 0 THEN
      v_counts := v_counts || jsonb_build_object(r.tbl || '.' || r.col, v_n);
    END IF;
  END LOOP;

  IF v_counts <> '{}'::jsonb THEN
    RAISE EXCEPTION 'purge_account: orphaned references remain: %', v_counts::text;
  END IF;

  RETURN jsonb_build_object('purged', true, 'email', v_email,
                            'user_id', p_user_id, 'contact_id', v_contact);
END;
$$;


--
-- Name: reap_expired_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reap_expired_holds() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer := 0;
BEGIN
  -- lapse line items past their 48h hold (approval preserved; re-offer resets)
  UPDATE request_selections SET state = 'lapsed'
   WHERE state = 'approved_awaiting_claim'
     AND hold_expires_at IS NOT NULL
     AND hold_expires_at < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN v_count;
END;
$$;


--
-- Name: reassign_document_party(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_document_party(p_document_id uuid, p_party_role text, p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_contract uuid; v_role text := upper(p_party_role);
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state, contract_id INTO v_org, v_state, v_contract
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'only staff may reassign a party';
  END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this contract can no longer be edited';
  END IF;
  IF v_role NOT IN ('LESSEE','LESSOR','BUYER','SELLER') THEN
    RAISE EXCEPTION 'invalid party role: %', p_party_role;
  END IF;
  -- the contact must be in the same org
  IF NOT EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND org_id = v_org AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'unknown contact';
  END IF;

  UPDATE document_parties SET contact_id = p_contact_id
   WHERE document_id = p_document_id AND party_role = v_role;
  IF v_contract IS NOT NULL THEN
    UPDATE contract_parties SET contact_id = p_contact_id
     WHERE contract_id = v_contract AND party_role = v_role;
  END IF;

  -- clear the stale party auto-fill values so fill_party_fields repopulates them
  UPDATE contract_fields SET value = '', structured = NULL
   WHERE document_id = p_document_id
     AND field_key IN (v_role||'.FULL_NAME', v_role||'.PRINTED_NAME', v_role||'.ADDRESS',
                       v_role||'.EMAIL', v_role||'.PHONE');
  PERFORM fill_party_fields_from_contacts(p_document_id);
  PERFORM remerge_contract_from_clauses(p_document_id);
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: rebuild_additional_terms(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_additional_terms(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_terms text := ''; r record;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  FOR r IN SELECT body, row_number() OVER (ORDER BY item_number) AS n
             FROM contract_addenda WHERE document_id = p_document_id AND status = 'accepted' ORDER BY item_number LOOP
    v_terms := v_terms || 'A-' || r.n || '. ' || r.body || E'\n\n';
  END LOOP;
  IF v_terms <> '' THEN
    v_terms := E'28. ADDITIONAL TERMS\n\nThe following additional terms have been agreed by the parties:\n\n' || btrim(v_terms);
  END IF;
  INSERT INTO contract_fields (org_id, document_id, field_key, label, section, owner_role, value, value_type, sort_order)
    VALUES (v_org, p_document_id, 'TXN.ADDITIONAL_TERMS', 'Additional Terms', 'Additional Terms', 'DEAL',
            nullif(v_terms,''), 'longtext', 900)
  ON CONFLICT (document_id, field_key) DO UPDATE SET value = excluded.value, updated_at = now();
END;
$$;


--
-- Name: recompose_document_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompose_document_fields(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE r RECORD; v_manage jsonb;
BEGIN
  -- 1. every field that has structure → compose its own value
  FOR r IN SELECT field_key, format_type, structured, value, label, pair_manage_key
             FROM contract_fields WHERE document_id = p_document_id LOOP
    IF r.pair_manage_key IS NOT NULL THEN
      CONTINUE;  -- cost children handled in pass 2 (need the manage field's structure)
    END IF;
    IF r.structured IS NOT NULL AND r.structured <> '{}'::jsonb THEN
      UPDATE contract_fields
         SET value = compose_field_prose(r.format_type, r.structured, r.label, r.value),
             updated_at = now()
       WHERE document_id = p_document_id AND field_key = r.field_key;
    END IF;
  END LOOP;

  /* ⚠️ THE FEE-PAYABLE FLAG. A clause cannot ask "is any money changing hands?"
     of a prose string, and clause_condition_met only does equals/contains — so the
     question is answered ONCE, here, and written as an ordinary field the ordinary
     condition mechanism can read. It lands in v_fields because
     remerge_contract_from_clauses calls this function immediately before building
     v_fields from contract_fields.

     Owner, 2026-08-26: "that text should be conditional against is payment in
     either intial payment field or any added payment field options, >$0? if yes,
     dont show the text, if no, show the text." */
  FOR r IN SELECT field_key, structured, org_id
             FROM contract_fields
            WHERE document_id = p_document_id AND format_type = 'fee_schedule' LOOP
    INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                 value_type, is_optional, included, sort_order)
    VALUES (r.org_id, p_document_id, 'TXN.LEASE_FEE_PAYABLE', 'SYSTEM',
            CASE WHEN lease_fee_payable(r.structured) THEN 'YES' ELSE 'NO' END,
            'text', true, false, 0)
    ON CONFLICT (document_id, field_key) DO UPDATE
      SET value = EXCLUDED.value, updated_at = now()
      WHERE contract_fields.value IS DISTINCT FROM EXCLUDED.value;
  END LOOP;

  -- 2. pair cost children → compose from the manage field's structure
  FOR r IN SELECT c.field_key, c.label, m.structured AS manage_structured
             FROM contract_fields c
             JOIN contract_fields m ON m.document_id = c.document_id AND m.field_key = c.pair_manage_key
            WHERE c.document_id = p_document_id AND c.pair_manage_key IS NOT NULL LOOP
    IF r.manage_structured IS NOT NULL AND r.manage_structured <> '{}'::jsonb THEN
      UPDATE contract_fields
         SET value = compose_pair_cost(r.manage_structured, r.label), updated_at = now()
       WHERE document_id = p_document_id AND field_key = r.field_key;
    END IF;
  END LOOP;

  -- CR-126 #7: transport applies when the delivery location differs from the
  -- handoff origin — the trial location if a trial is elected, else the horse's
  -- current location. Compared over structured + text so a manually-typed address
  -- is recognised, not only a picked one. Written as an ordinary field the gate
  -- can read (delivery gate is TXN.TRANSPORT_APPLIES = YES).
  IF EXISTS (SELECT 1 FROM contract_fields
              WHERE document_id = p_document_id AND field_key = 'TXN.DELIVERY_LOCATION') THEN
    DECLARE
      v_del   RECORD; v_origin RECORD; v_trial_on boolean; v_match boolean; v_org2 uuid;
    BEGIN
      SELECT org_id INTO v_org2 FROM documents WHERE id = p_document_id;
      SELECT structured, value INTO v_del FROM contract_fields
        WHERE document_id = p_document_id AND field_key = 'TXN.DELIVERY_LOCATION';
      v_trial_on := upper(coalesce((SELECT value FROM contract_fields
        WHERE document_id = p_document_id AND field_key = 'TXN.TRIAL_ENABLED'), '')) = 'YES';
      IF v_trial_on THEN
        SELECT structured, value INTO v_origin FROM contract_fields
          WHERE document_id = p_document_id AND field_key = 'TXN.TRIAL_LOCATION';
      ELSE
        SELECT structured, value INTO v_origin FROM contract_fields
          WHERE document_id = p_document_id AND field_key = 'HORSE.CURRENT_LOCATION';
      END IF;
      v_match := locations_match(v_del.structured, v_del.value, v_origin.structured, v_origin.value);
      INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                   value_type, is_optional, included, sort_order)
      VALUES (v_org2, p_document_id, 'TXN.TRANSPORT_APPLIES', 'SYSTEM',
              -- transport applies when the two are KNOWN to differ (match = false).
              -- Unknown (NULL) or same (true) => no transport sentence.
              CASE WHEN v_match IS FALSE THEN 'YES' ELSE 'NO' END,
              'text', true, false, 0)
      ON CONFLICT (document_id, field_key) DO UPDATE
        SET value = EXCLUDED.value, updated_at = now()
        WHERE contract_fields.value IS DISTINCT FROM EXCLUDED.value;
    END;
  END IF;

  -- CR-126: TXN.TRIAL_AT_CURRENT — YES when the trial location equals the horse's
  -- current location. Drives the "Current Location" trial-intro variant.
  IF EXISTS (SELECT 1 FROM contract_fields
              WHERE document_id = p_document_id AND field_key = 'TXN.TRIAL_LOCATION') THEN
    DECLARE v_tl RECORD; v_cl RECORD; v_m boolean; v_org3 uuid;
    BEGIN
      SELECT org_id INTO v_org3 FROM documents WHERE id = p_document_id;
      SELECT structured, value INTO v_tl FROM contract_fields
        WHERE document_id = p_document_id AND field_key = 'TXN.TRIAL_LOCATION';
      SELECT structured, value INTO v_cl FROM contract_fields
        WHERE document_id = p_document_id AND field_key = 'HORSE.CURRENT_LOCATION';
      v_m := locations_match(v_tl.structured, v_tl.value, v_cl.structured, v_cl.value);
      INSERT INTO contract_fields (org_id, document_id, field_key, owner_role, value,
                                   value_type, is_optional, included, sort_order)
      VALUES (v_org3, p_document_id, 'TXN.TRIAL_AT_CURRENT', 'SYSTEM',
              CASE WHEN v_m IS TRUE THEN 'YES' ELSE 'NO' END,
              'text', true, false, 0)
      ON CONFLICT (document_id, field_key) DO UPDATE
        SET value = EXCLUDED.value, updated_at = now()
        WHERE contract_fields.value IS DISTINCT FROM EXCLUDED.value;
    END;
  END IF;

  -- 3. LEASEFIX 2026-08-09: derived insurance cost allocation. No-ops on every
  --    template that has no TXN.*_POLICY_COST field, i.e. everything but the lease.
  -- pre-lease fee phrases (SYSTEM): from the timing + evaluation-period fields.
  DECLARE v_vt text; v_tt text; v_et text; v_ee text; v_org uuid;
  BEGIN
    SELECT org_id INTO v_org FROM documents WHERE id = p_document_id;
    SELECT value INTO v_vt FROM contract_fields WHERE document_id=p_document_id AND field_key='TXN.VET_TIMING';
    SELECT value INTO v_tt FROM contract_fields WHERE document_id=p_document_id AND field_key='TXN.TRAINER_TIMING';
    SELECT value INTO v_et FROM contract_fields WHERE document_id=p_document_id AND field_key='TXN.EVAL_PERIOD_TYPE';
    SELECT value INTO v_ee FROM contract_fields WHERE document_id=p_document_id AND field_key='TXN.EVALUATION_ENABLED';
    IF v_org IS NOT NULL THEN
      UPDATE contract_fields SET value = compose_prelease_fee_phrase(coalesce(v_vt,''), coalesce(v_et,''), coalesce(v_ee,''))
        WHERE document_id=p_document_id AND field_key='TXN.VET_FEE_PHRASE';
      UPDATE contract_fields SET value = compose_prelease_fee_phrase(coalesce(v_tt,''), coalesce(v_et,''), coalesce(v_ee,''))
        WHERE document_id=p_document_id AND field_key='TXN.TRAINER_FEE_PHRASE';
    END IF;
  END;

  PERFORM compose_insurance_allocation(p_document_id);
END;
$_$;


--
-- Name: record_invitation_delivery(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invitation_delivery(p_invitation_id uuid, p_ok boolean, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_code text;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'not authorized to record invitation delivery';
  END IF;

  SELECT org_id INTO v_org FROM invitations WHERE id = p_invitation_id;
  IF v_org IS NULL THEN RETURN false; END IF;   -- unknown invitation: nothing to record against

  v_code := CASE WHEN p_ok THEN 'email_sent' ELSE 'email_failed' END;

  INSERT INTO status_events (org_id, entity_type, entity_id, status, detail, actor_user_id)
  VALUES (v_org, 'account', p_invitation_id, v_code,
          CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'no reason reported'), 500) END,
          auth.uid());

  -- A person who was told "we've emailed you" and was not emailed is an ops
  -- problem, not a log line. Surface it where staff already look.
  IF NOT p_ok THEN
    PERFORM notify_staff(v_org, 'invitation_email_failed',
      'An invitation was created but the email did not send', '/app/admin');
  END IF;

  RETURN true;
END;
$$;


--
-- Name: record_invitation_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invitation_failure(p_token text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_any    invitations%ROWTYPE;
  v_email  text;
  v_reason text;
BEGIN
  SELECT * INTO v_any FROM invitations WHERE token = p_token ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN 'token_not_found'; END IF;  -- nothing to record against

  IF auth.uid() IS NOT NULL THEN
    SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();
  END IF;

  v_reason := CASE
    WHEN v_any.status = 'sent' AND v_any.expires_at <= now() THEN 'token_expired'
    WHEN v_any.status = 'sent' AND v_email IS NOT NULL AND lower(v_any.email) IS DISTINCT FROM v_email
      THEN 'email_address_mismatch'
    WHEN v_any.status <> 'sent' THEN 'already_' || v_any.status
    ELSE 'invalid' END;

  -- only the live/expired states convert to a failure record; don't clobber a
  -- successful redemption that raced.
  UPDATE invitations
     SET status = 'redeemed_unsuccessful', failure_reason = v_reason
   WHERE id = v_any.id AND status IN ('sent','expired');

  IF FOUND THEN
    PERFORM notify_staff(v_any.org_id, 'invitation_redeem_failed',
      'An invitation could not be redeemed (' || v_reason || ')', '/app/admin');
  END IF;
  RETURN v_reason;
END;
$$;


--
-- Name: record_invitation_resend(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invitation_resend(p_invitation_id uuid, p_self_service boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'not authorized to record an invitation resend';
  END IF;

  SELECT org_id INTO v_org FROM invitations WHERE id = p_invitation_id;
  IF v_org IS NULL THEN RETURN false; END IF;

  INSERT INTO status_events (org_id, entity_type, entity_id, status, detail, actor_user_id)
  VALUES (v_org, 'account', p_invitation_id, 'resent',
          CASE WHEN p_self_service THEN 'self-service' ELSE 'staff' END,
          auth.uid());
  RETURN true;
END;
$$;


--
-- Name: record_lesson_progress(uuid, jsonb, jsonb, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_lesson_progress(p_booking_id uuid, p_answers jsonb DEFAULT '{}'::jsonb, p_outcomes jsonb DEFAULT '[]'::jsonb, p_next_focus text DEFAULT NULL::text, p_coach_notes text DEFAULT NULL::text, p_submit boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b        bookings%ROWTYPE;
  v_taught   lesson_plans%ROWTYPE;
  v_base     lesson_plans%ROWTYPE;
  v_next     lesson_plans%ROWTYPE;
  v_objs     jsonb := '[]'::jsonb;
  v_o        jsonb;
  v_hit      jsonb;
  v_outcomes jsonb := coalesce(p_outcomes, '[]'::jsonb);
  v_focus    text;
  v_notes    text;
  v_advanced boolean := false;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF jsonb_typeof(v_outcomes) <> 'array' THEN
    RAISE EXCEPTION 'outcomes must be an array';
  END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'lesson not found in this org'; END IF;
  IF v_b.client_id IS NULL THEN
    RAISE EXCEPTION 'this session has no client, so there is no plan to record progress against';
  END IF;

  -- ── 1. the record of what happened, through the ONE form writer ───────────
  -- The outcomes ride in the form's answers under their own key, so the write-up
  -- and the per-objective result are one saved thing and cannot half-land.
  PERFORM save_booking_form(
    p_booking_id,
    coalesce(p_answers, '{}'::jsonb) || jsonb_build_object('plan_progress', v_outcomes),
    p_submit);

  -- ── 2. two plans, and they are only the same thing the FIRST time ────────
  -- v_taught  what this lesson carried. It is what gets PINNED, and what the
  --           write-up is true about afterwards.
  -- v_base    where the plan is RIGHT NOW. It is what an advance moves on from.
  --
  -- On a first recording these are the same row. On a SECOND recording of the
  -- same lesson they are not, because the first one already advanced the plan —
  -- and advancing from v_taught again would re-derive a version the plan has
  -- already moved past, writing an identical version every time Claire re-saves
  -- and discarding any hand edit made in between. Objective ids are stable
  -- across versions, so the outcomes still land on the right objectives when
  -- applied to the current plan.
  v_taught := _lesson_plan_for_booking(p_booking_id);
  v_base   := _current_lesson_plan(v_b.client_id);
  IF v_base.id IS NULL THEN v_base := v_taught; END IF;

  IF v_taught.id IS NULL THEN
    -- No plan yet. Outcomes cannot mean anything (they name objectives that do
    -- not exist), so say so rather than inventing a plan out of them. A bare
    -- "next focus" is allowed and starts the plan — that is Claire finishing a
    -- first lesson and writing down where this rider is going.
    IF jsonb_array_length(v_outcomes) > 0 THEN
      RAISE EXCEPTION 'this client has no lesson plan yet — start one before recording progress against it';
    END IF;
    IF nullif(btrim(coalesce(p_next_focus, '')), '') IS NOT NULL
       OR nullif(btrim(coalesce(p_coach_notes, '')), '') IS NOT NULL THEN
      v_next := _write_lesson_plan_version(v_b.client_id, p_next_focus, '[]'::jsonb,
                  p_coach_notes, 'created', 'Started while recording this lesson', p_booking_id);
      v_advanced := true;
    END IF;
  ELSE
    -- ── 3. apply the outcomes, in order, to the plan's objectives ──────────
    FOR v_o IN SELECT jsonb_array_elements(coalesce(v_base.objectives, '[]'::jsonb)) LOOP
      SELECT x INTO v_hit
        FROM jsonb_array_elements(v_outcomes) AS x
       WHERE x ->> 'id' IS NOT NULL AND x ->> 'id' = v_o ->> 'id'
       LIMIT 1;
      IF v_hit IS NOT NULL THEN
        v_o := v_o
             || CASE WHEN nullif(btrim(coalesce(v_hit ->> 'state', '')), '') IS NOT NULL
                     THEN jsonb_build_object('state', lower(btrim(v_hit ->> 'state')))
                     ELSE '{}'::jsonb END
             || CASE WHEN v_hit ? 'note'
                     THEN jsonb_build_object('note', nullif(btrim(coalesce(v_hit ->> 'note', '')), ''))
                     ELSE '{}'::jsonb END;
        v_hit := NULL;
      END IF;
      v_objs := v_objs || jsonb_build_array(v_o);
    END LOOP;

    -- outcomes that name no existing objective but carry a label are NEW work
    FOR v_hit IN SELECT jsonb_array_elements(v_outcomes) LOOP
      IF nullif(btrim(coalesce(v_hit ->> 'label', '')), '') IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM jsonb_array_elements(coalesce(v_base.objectives, '[]'::jsonb)) AS y
            WHERE y ->> 'id' = v_hit ->> 'id') THEN
        v_objs := v_objs || jsonb_build_array(jsonb_build_object(
          'label', btrim(v_hit ->> 'label'),
          'state', coalesce(nullif(btrim(coalesce(v_hit ->> 'state', '')), ''), 'planned'),
          'note',  nullif(btrim(coalesce(v_hit ->> 'note', '')), '')));
      END IF;
    END LOOP;

    v_objs  := _lesson_plan_objectives(v_objs);
    v_focus := coalesce(nullif(btrim(coalesce(p_next_focus, '')), ''), v_base.focus);
    v_notes := CASE WHEN p_coach_notes IS NULL THEN v_base.coach_notes ELSE p_coach_notes END;

    -- ── 4. advance, unless the plan ALREADY SAYS THIS ──────────────────────
    -- Compared against where the plan is now, not against what this lesson
    -- carried: re-saving a lesson that has already been recorded must be a
    -- no-op, not a fresh identical version.
    IF NOT _lesson_plan_same(v_base.focus, v_base.objectives, v_base.coach_notes,
                             v_focus, v_objs, v_notes) THEN
      v_next := _write_lesson_plan_version(v_b.client_id, v_focus, v_objs, v_notes,
                  'advanced', 'Advanced after the Riding Lesson on '
                              || to_char(v_b.starts_at, 'FMDD Mon YYYY'),
                  p_booking_id);
      v_advanced := true;
    END IF;
  END IF;

  -- ── 5. pin the version this lesson was taught against ────────────────────
  -- After the form save, because save_booking_form is what guarantees the row
  -- exists (it ensures the instance). Pinning is what freezes this lesson's copy
  -- so a later advance does not rewrite its history.
  IF v_taught.id IS NOT NULL THEN
    UPDATE booking_forms
       SET plan_id = v_taught.id, updated_at = now()
     WHERE booking_id = p_booking_id;
  END IF;

  -- ── 6. the lesson's own trail ────────────────────────────────────────────
  PERFORM log_status_event('offering', p_booking_id, 'progress_recorded',
            CASE WHEN v_advanced THEN 'Progress recorded; the plan advanced to version '
                                      || v_next.version
                 ELSE 'Progress recorded' END,
            v_b.org_id);

  RETURN jsonb_build_object(
    'booking_id',    p_booking_id,
    'plan_advanced', v_advanced,
    'taught_against', _lesson_plan_json(v_taught, true),
    'plan',          _lesson_plan_json(
                       CASE WHEN v_next.id IS NOT NULL THEN v_next
                            ELSE _current_lesson_plan(v_b.client_id) END, true),
    'form',          booking_form(p_booking_id));
END;
$$;


--
-- Name: record_lookup_suggestion(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_lookup_suggestion(p_lookup_key text, p_raw_value text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_norm text; v_exists boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  v_norm := lower(btrim(coalesce(p_raw_value,'')));
  IF v_norm = '' THEN RETURN; END IF;

  -- if the value already matches an official option in a known table, don't queue it
  IF p_lookup_key = 'horse_breeds' THEN
    SELECT EXISTS(SELECT 1 FROM horse_breeds WHERE active AND lower(display_name)=v_norm) INTO v_exists;
  ELSIF p_lookup_key = 'horse_colors' THEN
    SELECT EXISTS(SELECT 1 FROM horse_colors WHERE active AND lower(display_name)=v_norm) INTO v_exists;
  ELSE
    SELECT EXISTS(SELECT 1 FROM lookup_options WHERE lookup_key=p_lookup_key AND active AND lower(display_name)=v_norm) INTO v_exists;
  END IF;
  IF v_exists THEN RETURN; END IF;

  INSERT INTO lookup_suggestions (lookup_key, raw_value, norm_value, org_id)
  VALUES (p_lookup_key, btrim(p_raw_value), v_norm, current_org())
  ON CONFLICT (lookup_key, norm_value)
  DO UPDATE SET count = lookup_suggestions.count + 1, last_seen = now(),
                raw_value = EXCLUDED.raw_value;
END;
$$;


--
-- Name: record_signature(uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_signature(p_document_id uuid, p_party_role text, p_typed_name text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_esign_consent boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc_org uuid; v_signer uuid; v_need int; v_have int; v_status text;
  v_body text; v_hash text; v_sig record; v_user uuid; v_title text;
  v_ip text; v_ua text; r record;
  v_ns text;
  v_is_company_signer boolean := false;
  v_expected text;   -- FIX1 §C: the name on the signer's own contact record
BEGIN
  SELECT org_id INTO v_doc_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_doc_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;

  v_signer := current_contact_id();
  IF v_signer IS NULL THEN RAISE EXCEPTION 'no contact for the signing account'; END IF;

  IF NOT EXISTS (SELECT 1 FROM document_parties
                  WHERE document_id = p_document_id AND contact_id = v_signer
                    AND party_role = p_party_role AND is_signer) THEN
    -- COMPANY-SIDE SIGNING (2026-08-03): the org's company contact is a
    -- faceless entity with no linked account (the identity consolidation
    -- moved every staff profile onto a personal TEAM contact), so when the
    -- signing party IS the company contact, a staff member signs on the
    -- company's behalf: the signature is recorded against the company
    -- contact, the acting human is captured in signer_user_id + typed_name.
    -- Mirrors remove_my_signature's existing staff-on-behalf allowance.
    IF has_staff_access() AND EXISTS (
         SELECT 1 FROM document_parties dp
           JOIN contacts cc ON cc.id = dp.contact_id
          WHERE dp.document_id = p_document_id AND dp.party_role = p_party_role
            AND dp.is_signer AND cc.is_company AND cc.org_id = v_doc_org
            AND cc.deleted_at IS NULL) THEN
      SELECT dp.contact_id INTO v_signer
        FROM document_parties dp JOIN contacts cc ON cc.id = dp.contact_id
       WHERE dp.document_id = p_document_id AND dp.party_role = p_party_role
         AND dp.is_signer AND cc.is_company LIMIT 1;
      v_is_company_signer := true;
    ELSE
      RAISE EXCEPTION 'not a signer on this document in role %', p_party_role;
    END IF;
  END IF;

  IF nullif(btrim(coalesce(p_typed_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'a typed name is required to sign';
  END IF;

  -- ── FIX1 §C — THE NAME RULE, SERVER-SIDE (AR7 F3/F4, R4) ─────────────────
  -- Four of the six signing surfaces enforced NOTHING, and three code comments
  -- told every reader for two months that a server check had their back.
  -- sign_release has had the real comparison since the kiosk shipped; this is
  -- that same rule, moved into the function every other surface reaches.
  --
  -- CASE-INSENSITIVE, deliberately, not laxly: four already-executed production
  -- signatures — "Brian olenik" and three "Elisheva fiszer" — are real people
  -- signing their own names with a lowercase letter. A case-sensitive rule
  -- would refuse 4 of 71. Whitespace is collapsed for the same reason: a double
  -- space between forename and surname is a typing artefact, not another
  -- person. NOTHING else is folded — no accent stripping, no punctuation
  -- stripping, no nicknames, no initials. Each of those would let a DIFFERENT
  -- person's name pass, which is the failure this rule exists to prevent.
  --
  -- EXEMPT — the company signer. The branch above reassigned v_signer to the
  -- faceless company contact, and the human deliberately types THEIR OWN name
  -- on the company's behalf. Comparing here would refuse every company
  -- signature this system has ever taken.
  --
  -- EXEMPT — a signer whose contact record holds no name at all. An email-only
  -- contract party derives nothing until their record is populated (D22 §1), so
  -- there is no expected string to compare and refusing would strand them with
  -- no route out. The non-empty check above still applies to them.
  --
  -- ⚠️ This would NOT have caught the 2026-08-28 incident: that record genuinely
  -- said "Aubrey" at signing time, so this check would have PASSED. It is
  -- defence in depth. The fix for that incident is §A and §B, at the front door.
  IF NOT v_is_company_signer THEN
    SELECT nullif(btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')), '')
      INTO v_expected
      FROM contacts c WHERE c.id = v_signer;
    IF v_expected IS NOT NULL
       AND lower(regexp_replace(btrim(p_typed_name), '\s+', ' ', 'g'))
        <> lower(regexp_replace(v_expected,          '\s+', ' ', 'g')) THEN
      -- The expected string is named so the surface can show it. It is the
      -- caller's own contact record; nothing is disclosed that is not theirs.
      RAISE EXCEPTION 'typed signature must match the name on your record exactly: %', v_expected;
    END IF;
  END IF;

  -- ── FIX1 §C — ATTRIBUTION IS CAPTURED, NOT MERELY ACCEPTED (AR7 F4, R5) ──
  -- This function has always TAKEN p_ip/p_user_agent and every caller has
  -- always passed NULL, so 21 of 71 production signatures carry neither, and
  -- the 2026-08-28 incident had to be reconstructed out of audit_logs. The old
  -- line here coalesced p_ip onto v_ip — itself still NULL — a no-op shaped
  -- exactly like a fallback. This is the real one, and it is the same line
  -- sign_release line 106 already runs. An explicitly passed value still wins.
  SELECT a.ip, a.user_agent INTO v_ip, v_ua FROM http_request_attribution() a;
  v_ip := coalesce(nullif(trim(coalesce(p_ip, '')), ''), v_ip);
  v_ua := coalesce(nullif(trim(coalesce(p_user_agent, '')), ''), v_ua);

  INSERT INTO signatures (org_id, document_id, signer_contact_id, signer_user_id, party_role, typed_name, signed_at, ip_address, user_agent, method)
    VALUES (v_doc_org, p_document_id, v_signer, coalesce((SELECT pr.user_id FROM profiles pr WHERE pr.contact_id = v_signer LIMIT 1), auth.uid()), p_party_role, p_typed_name, now(), v_ip, v_ua, 'TYPED')
    ON CONFLICT (document_id, signer_contact_id, party_role) DO UPDATE
      SET typed_name = EXCLUDED.typed_name,
          -- the rows pre-seeded at lock time carry NULL signer_user_id; the
          -- sealing update must stamp the signing account or no executed
          -- document ever records WHO signed (found in the 2026-08-03 e2e)
          signer_user_id = EXCLUDED.signer_user_id,
          signed_at  = EXCLUDED.signed_at,
          ip_address = EXCLUDED.ip_address,
          user_agent = EXCLUDED.user_agent,
          method     = EXCLUDED.method
      WHERE signatures.signed_at IS NULL;  -- never overwrite an already-sealed signature  -- but a WITHDRAWN one may be given again

  IF coalesce(p_esign_consent, false) THEN
    INSERT INTO esign_consents (org_id, contact_id, document_id, ip_address, user_agent)
      VALUES (v_doc_org, v_signer, p_document_id, v_ip, v_ua);
  END IF;

  -- the signer's TOKEN namespace: a second (or later) same-role BUYER contact is
  -- the co-buyer and substitutes SIG.COBUYER.* (the block its clause renders)
  v_ns := p_party_role;
  IF p_party_role = 'BUYER' THEN
    SELECT CASE WHEN t.rn > 1 THEN 'COBUYER' ELSE 'BUYER' END INTO v_ns
      FROM (SELECT dp.contact_id,
                   row_number() OVER (ORDER BY dp.signer_order NULLS LAST, dp.id) AS rn
              FROM document_parties dp
             WHERE dp.document_id = p_document_id AND dp.party_role = 'BUYER') t
     WHERE t.contact_id = v_signer;
    v_ns := coalesce(v_ns, p_party_role);
  END IF;

  UPDATE documents SET merged_body =
      replace(replace(merged_body,
        '{{SIG.' || v_ns || '.NAME}}', p_typed_name),
        '{{SIG.' || v_ns || '.DATE}}', to_char(now(), 'FMMonth FMDD, YYYY'))
    WHERE id = p_document_id AND merged_body IS NOT NULL;

  SELECT count(*) FILTER (WHERE is_signer) INTO v_need
    FROM document_parties WHERE document_id = p_document_id;
  SELECT count(*) INTO v_have
    FROM signatures WHERE document_id = p_document_id AND signed_at IS NOT NULL AND deleted_at IS NULL;

  IF v_need > 0 AND v_have >= v_need THEN
    SELECT merged_body INTO v_body FROM documents WHERE id = p_document_id;
    SELECT signer_contact_id, typed_name, signed_at INTO v_sig
      FROM signatures
      WHERE document_id = p_document_id AND signer_contact_id = v_signer
        AND party_role = p_party_role AND deleted_at IS NULL;
    IF FOUND THEN
      v_hash := compute_execution_hash(v_body, v_sig.signer_contact_id, v_sig.typed_name, v_sig.signed_at);
    END IF;

    UPDATE documents SET status = 'EXECUTED', effective_date = now()::date,
                         execution_hash = v_hash, workflow_state = 'executed'
      WHERE id = p_document_id AND status <> 'EXECUTED';

    IF FOUND THEN
      -- the contract is signed: its per-party "ready to sign / in review" alerts
      -- (link /app/contracts/<id>) are no longer valid for anyone — clear all.
      PERFORM resolve_notifications_for_link('/app/contracts/' || p_document_id::text, auth.uid());

      SELECT coalesce(d.title, 'Your document') INTO v_title
        FROM documents d WHERE d.id = p_document_id;

      -- ITEM 5c: notify the OTHER parties, never the signer whose own action
      -- completed execution. Telling someone their own click succeeded is
      -- residue, and it arrived in the same breath as the resolve above.
      FOR r IN
        SELECT DISTINCT pr.user_id
          FROM document_parties dp
          JOIN profiles pr ON pr.contact_id = dp.contact_id
         WHERE dp.document_id = p_document_id
           AND dp.contact_id <> v_signer
           AND pr.user_id IS NOT NULL
      LOOP
        INSERT INTO notifications (org_id, user_id, kind, title, link)
          VALUES (v_doc_org, r.user_id, 'document_executed', v_title || ' is signed', '/app/documents');
      END LOOP;

      -- TASK A16: the old staff-only broadcast here is folded into the
      -- unified party_signed notification below (same event, one row).
    END IF;
  END IF;

  -- TASK A16: admin notified when a (non-company) party signs, every
  -- signature event. Best-effort — isolated the same way
  -- documents_send_executed_email isolates its mail send, so a notification
  -- failure can never block or roll back a signature that already sealed.
  IF NOT v_is_company_signer THEN
    BEGIN
      SELECT coalesce(d.title, 'A document') INTO v_title FROM documents d WHERE d.id = p_document_id;
      IF v_need > 0 AND v_have >= v_need THEN
        PERFORM notify_staff(v_doc_org, 'party_signed',
          v_title || ' — fully executed; signed by ' || p_typed_name || ' (' || p_party_role || ')',
          '/app/ops/documents/' || p_document_id::text);
      ELSE
        PERFORM notify_staff(v_doc_org, 'party_signed',
          v_title || ' — signed by ' || p_typed_name || ' (' || p_party_role || ')',
          '/app/ops/documents/' || p_document_id::text);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'record_signature: party_signed notify_staff failed for document %: %', p_document_id, SQLERRM;
    END;
  END IF;

  SELECT status INTO v_status FROM documents WHERE id = p_document_id;
  RETURN v_status;
END;
$$;


--
-- Name: FUNCTION record_signature(p_document_id uuid, p_party_role text, p_typed_name text, p_ip text, p_user_agent text, p_esign_consent boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_signature(p_document_id uuid, p_party_role text, p_typed_name text, p_ip text, p_user_agent text, p_esign_consent boolean) IS 'Seal a party''s typed signature (TASK A16 = v6 + party_signed staff notification on every signature, non-company signer, best-effort/non-blocking; folds the prior staff-only document_executed broadcast into one row on the completing signature). Everything else preserved verbatim — attribution capture, esign_consents log, execution_hash, SIG-token substitution, the co-signer document_executed notification. Caller must be tenant staff or the party''s own contact; flips EXECUTED once every signer party has signed.';


--
-- Name: record_signup_alert_send(uuid, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_signup_alert_send(p_attempt_id uuid, p_key text, p_recipient text, p_ok boolean, p_error text, p_message_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  SELECT org_id INTO v_org FROM signup_attempts WHERE id = p_attempt_id;
  IF v_org IS NULL THEN RETURN; END IF;
  INSERT INTO signup_alert_sends (org_id, attempt_id, idempotency_key, recipient_email,
                                  succeeded, error, message_id)
    VALUES (v_org, p_attempt_id, p_key, p_recipient, coalesce(p_ok, false), p_error, p_message_id)
    ON CONFLICT (idempotency_key) DO NOTHING;
END;
$$;


--
-- Name: record_signup_attempt(uuid, text, text, text, text, text, text[], uuid, boolean, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_signup_attempt(p_org uuid, p_email text, p_first_name text, p_last_name text, p_phone text, p_path text, p_categories text[], p_invitation_id uuid, p_email_ok boolean, p_email_error text, p_message_id text, p_rate_limited boolean, p_requester_hash text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  INSERT INTO signup_attempts (org_id, email, first_name, last_name, phone, path,
                               categories, invitation_id, email_ok, email_error,
                               message_id, rate_limited, requester_hash)
    VALUES (p_org, lower(btrim(p_email)), nullif(btrim(coalesce(p_first_name,'')),''),
            nullif(btrim(coalesce(p_last_name,'')),''), nullif(btrim(coalesce(p_phone,'')),''),
            p_path, p_categories, p_invitation_id, coalesce(p_email_ok, false),
            p_email_error, p_message_id, coalesce(p_rate_limited, false), p_requester_hash)
    RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: record_template_version_bump(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_template_version_bump() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.version IS DISTINCT FROM OLD.version AND NEW.version > coalesce(OLD.version, 0) THEN
    INSERT INTO template_version_events (template_key, from_version, to_version)
    VALUES (NEW.template_key, OLD.version, NEW.version);
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: redeem_contract_invitation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_contract_invitation(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv     invitations%ROWTYPE;
  v_email   text;
  v_profile profiles%ROWTYPE;
  v_inv_is_company boolean;
  v_signed  boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'sign in before redeeming an invitation'; END IF;
  SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();

  -- SENDGUARD: resolve the token WITHOUT the liveness filter first, so an
  -- already-signed party who clicks a spent/superseded/expired link can still be
  -- routed to their own signed document. The liveness rules are re-applied below
  -- for anyone who has NOT signed — unchanged.
  SELECT * INTO v_inv FROM invitations
   WHERE token = p_token AND kind = 'CONTRACT'
   ORDER BY created_at DESC
   LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'invitation is not valid or has expired'; END IF;
  IF lower(v_inv.email) IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'this invitation was issued to a different email address';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM signatures s
     WHERE s.document_id = v_inv.document_id
       AND s.deleted_at IS NULL
       AND (s.signer_contact_id = v_inv.contact_id
            OR s.signer_user_id = auth.uid()
            OR s.signer_contact_id = (SELECT p.contact_id FROM profiles p WHERE p.user_id = auth.uid()))
  ) INTO v_signed;

  -- A caller who already has an account that is a PARTY on this document opens it
  -- directly — whether or not they have signed yet. A party with an account has read
  -- access by RLS and needs no live token; the one-time link should never dead-end
  -- them. This also makes the link effectively reusable for an account-holder.
  IF v_signed OR EXISTS (
       SELECT 1 FROM document_parties dp
        WHERE dp.document_id = v_inv.document_id
          AND dp.contact_id = (SELECT p.contact_id FROM profiles p WHERE p.user_id = auth.uid())
     ) THEN
    -- Nothing to provision: they are already a party on the document. Retire a
    -- still-live token so it cannot be walked twice, and leave a spent one as-is.
    UPDATE invitations
       SET status = 'redeemed', redeemed_at = coalesce(redeemed_at, now())
     WHERE id = v_inv.id AND status = 'sent';
    RETURN jsonb_build_object('document_id', v_inv.document_id, 'already_signed', v_signed);
  END IF;

  -- ORIGINAL liveness rules for a party who has not signed.
  IF NOT (v_inv.status = 'sent' AND v_inv.expires_at > now()) THEN
    RAISE EXCEPTION 'invitation is not valid or has expired';
  END IF;

  PERFORM set_config('app.allow_profile_link', '1', true);

  -- ── STABILIZE ITEM 1 — SEED THE PROFILE RATHER THAN REFUSING ─────────────
  --
  -- A brand-new counterparty reaches this line 300ms after their account was
  -- created and has no profile row yet, because nothing creates one for them.
  -- The old `IF NOT FOUND THEN RAISE` turned the ordinary case into the error
  -- case. The insert below is `redeem_invitation`'s, verbatim in shape: the
  -- invitation's org_id (so contacts.org_id's NOT NULL is satisfiable through
  -- the link trigger), the invitation's names, the account's own email.
  SELECT * INTO v_profile FROM profiles WHERE user_id = auth.uid();
  IF NOT FOUND THEN
    INSERT INTO profiles (user_id, org_id, first_name, last_name, email)
    VALUES (auth.uid(), v_inv.org_id,
            nullif(btrim(coalesce(v_inv.first_name, '')), ''),
            nullif(btrim(coalesce(v_inv.last_name,  '')), ''),
            v_email)
    ON CONFLICT (user_id) DO NOTHING;
    SELECT * INTO v_profile FROM profiles WHERE user_id = auth.uid();
    IF NOT FOUND THEN
      -- Genuinely impossible short of the row being deleted underneath us.
      RAISE EXCEPTION 'no profile for the signed-in user';
    END IF;
  END IF;

  SELECT coalesce(is_company, false) INTO v_inv_is_company FROM contacts WHERE id = v_inv.contact_id;

  IF v_profile.contact_id IS NULL THEN
    IF NOT v_inv_is_company THEN
      PERFORM promote_contact_to_account(auth.uid(), v_inv.contact_id);
    ELSE
      UPDATE profiles SET org_id = coalesce(org_id, v_inv.org_id) WHERE user_id = auth.uid();
    END IF;
  ELSIF v_profile.contact_id <> v_inv.contact_id AND NOT v_inv_is_company THEN
    -- THE SPINE merges the duplicate counterparty contact into the account's
    -- contact (documents/parties/signatures/shares re-anchor, duplicate
    -- dissolves) — replacing the hand-rolled partial re-point.
    PERFORM promote_contact_to_account(auth.uid(), v_inv.contact_id);
    UPDATE documents SET originator_contact_id = v_profile.contact_id
     WHERE originator_contact_id = v_inv.contact_id AND deleted_at IS NULL;
  END IF;

  -- FOLD-IN: ensure the counterparty has a real account + clients row (individuals
  -- only — a company party is represented by the company contact, not the person).
  --
  -- PARTYROLE 2026-08-17: `p_template_keys` is an EXPLICIT EMPTY ARRAY, not NULL.
  -- NULL meant "fall through to the category defaults", and the category is
  -- GUEST, so redeeming a contract invitation assigned the general release,
  -- company policies and facility rules to a counterparty who owes none of them —
  -- and, because `apply_category_documents` deletes every requirement outside the
  -- wanted set, STRIPPED the horse-owner requirements off a boarder who was
  -- invited as Lessor. '{}' takes the explicit branch: nothing is inserted, and
  -- nothing is deleted. A Party's document set is decided by staff, never here.
  --
  -- ⚠️ STABILIZE ITEM 4 — THIS IS THE ONLY THING THAT GIVES A COUNTERPARTY A
  -- `clients` ROW, AND UNTIL ITEM 1 ABOVE IT WAS UNREACHABLE. The swallow stays
  -- (a contract redemption must never fail on provisioning), but it is no longer
  -- swallowing the whole function's failure to get here.
  IF NOT v_inv_is_company AND v_email IS NOT NULL THEN
    BEGIN
      PERFORM _ensure_client_account(v_inv.org_id, v_email,
        nullif(v_inv.first_name,''), nullif(v_inv.last_name,''),
        ARRAY['GUEST'], ARRAY[]::text[]);
    EXCEPTION WHEN others THEN NULL;  -- never block a contract redemption on provisioning
    END;
  END IF;

  -- PARTYEMAIL PHASE 4b — THE MOMENT THE RECORD BECOMES READABLE (D22 §7).
  -- Until now this document held only the address the party was matched on;
  -- name, phone and address were never read from the contact record because the
  -- person had not claimed the contract. They just did. Push the record into the
  -- party tokens and recompose, so the document they are about to be shown carries
  -- their own details rather than blanks. Wrapped, like the fold-in above:
  -- provisioning must never block a redemption.
  BEGIN
    PERFORM regenerate_contract_document(v_inv.document_id);
  EXCEPTION WHEN others THEN NULL;
  END;

  UPDATE invitations SET status = 'redeemed', redeemed_at = now() WHERE id = v_inv.id;
  RETURN jsonb_build_object('document_id', v_inv.document_id, 'already_signed', false);
END;
$$;


--
-- Name: FUNCTION redeem_contract_invitation(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.redeem_contract_invitation(p_token text) IS 'Contract-invite redemption: validates the token/email like redeem_invitation, then links the signed-in profile to the engagement party contact (fresh account adopts the contact; an existing account keeps its contact and the party rows repoint to it). Marks the invite accepted. Grants NO community membership. Returns {document_id} — the app routes there.';


--
-- Name: redeem_gift(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_gift(p_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gift     gifts%ROWTYPE;
  v_off      offerings%ROWTYPE;
  v_email    text;
  v_fn       text;
  v_ln       text;
  v_marker   text;
  v_res      jsonb;
  v_contact  uuid;
  v_client   uuid;
  v_purchase uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN 'not_authenticated'; END IF;

  SELECT * INTO v_gift FROM gifts WHERE code = p_code FOR UPDATE;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;
  IF v_gift.status = 'redeemed' THEN RETURN 'already_redeemed'; END IF;
  IF v_gift.expires_at IS NOT NULL AND v_gift.expires_at < now() THEN RETURN 'expired'; END IF;
  IF v_gift.unlock_gate = 'intro_call' AND NOT v_gift.unlocked THEN RETURN 'awaiting_intro_call'; END IF;

  SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();
  v_email := coalesce(v_email, lower(nullif(trim(v_gift.recipient_email), '')));
  IF v_email IS NULL OR v_gift.org_id IS NULL THEN
    -- D3: nothing to provision against. Record it and say so — not a silent
    -- 'redeemed' with no account behind it.
    PERFORM notify_staff(v_gift.org_id, 'gift_redemption_failed',
      'Gift ' || v_gift.code || ' redemption could not resolve an email for user '
        || auth.uid()::text, '/app/ops/intake');
    RETURN 'redemption_failed';
  END IF;

  IF v_gift.offering_id IS NOT NULL THEN
    SELECT * INTO v_off FROM offerings WHERE id = v_gift.offering_id;
  END IF;

  -- D2 (owner ruling 2026-08-11): the taxonomy splits on what the person
  -- HOLDS, not who paid. A real service (config_kind present, not a pure
  -- inquiry line — the same test attach_first_purchase_policies and
  -- promote_buyer_from_offering already use) makes the redeemer a CLIENT.
  -- Anything else — no linked offering, or a non-service line — CUSTOMER:
  -- they hold something but received no experience.
  v_marker := CASE
    WHEN v_off.config_kind IS NOT NULL AND v_off.config_kind <> 'inquire' THEN 'CLIENT'
    ELSE 'CUSTOMER'
  END;

  v_fn := nullif(split_part(coalesce(v_gift.recipient_name, ''), ' ', 1), '');
  v_ln := nullif(btrim(substr(coalesce(v_gift.recipient_name, ''),
            coalesce(nullif(position(' ' in coalesce(v_gift.recipient_name,'')), 0),
                     length(coalesce(v_gift.recipient_name,''))+1))), '');

  -- D3: provisioning happens BEFORE the gift is marked consumed, in one
  -- exception block. Failure here means the UPDATE below never runs, so the
  -- gift stays in its pre-redemption status — genuinely redeemable again —
  -- with no compensating write required.
  BEGIN
    -- Discovered in dry-run, not in the task doc: promote_contact_to_account
    -- RAISEs if auth.uid() has no `profiles` row yet — true for a brand-new
    -- gift recipient created via /api/register-gift, which (like every other
    -- account-creation path here) only creates the auth.users row, never the
    -- profile. redeem_invitation already carries this exact step for its own
    -- new-signup path; mirrored verbatim (same ON CONFLICT DO NOTHING, same
    -- app.allow_profile_link flag) rather than inventing a second shape.
    PERFORM set_config('app.allow_profile_link', '1', true);
    INSERT INTO profiles (user_id, org_id, first_name, last_name, email)
    VALUES (auth.uid(), v_gift.org_id, v_fn, v_ln, v_email)
    ON CONFLICT (user_id) DO NOTHING;

    -- BUG FIX: NULL/NULL, not ARRAY[]::text[]/ARRAY[]::text[]. An empty (but
    -- non-NULL) template_keys array took _ensure_client_account's "insert
    -- these specific docs" branch and unnested to zero rows — permanently
    -- skipping its "derive from category" fallback. NULL lets that fallback
    -- run (category defaults to GUEST for a brand-new contact); the real
    -- RIDER/HORSE_OWNER category — and the documents it requires — gets
    -- derived a moment later from the purchase itself, same as every other
    -- purchase path (see below).
    v_res := _ensure_client_account(v_gift.org_id, v_email, v_fn, v_ln, NULL, NULL, v_marker);
    v_contact := (v_res->>'contact_id')::uuid;
    v_client  := (v_res->>'client_id')::uuid;

    -- D1: on the standard spine — indistinguishable downstream from any other
    -- purchase. The purchase_items insert this makes fires BOTH
    -- promote_buyer_from_offering (derives RIDER/HORSE_OWNER from the
    -- offering's segment, assigns that category's documents — the
    -- authoritative deriver, fixed 2026-08-10) and
    -- purchase_items_generate_units (fulfillment_units by config_kind).
    -- Punch-card / single-session offerings also grant lesson_credits, same
    -- as every staff-provisioned purchase — that is what the schedule reads.
    -- Marked paid: a gift was already paid for; the recipient owes nothing.
    IF v_gift.offering_id IS NOT NULL THEN
      v_purchase := _provision_purchase_for_offerings(
        v_gift.org_id, v_contact, v_client, ARRAY[v_gift.offering_id],
        true, NULL, 'Gift redemption — code ' || v_gift.code, 0);
    END IF;

    PERFORM promote_contact_to_account(auth.uid(), v_contact);
  EXCEPTION WHEN others THEN
    -- D3: recorded, not NULL — staff can see exactly what failed and for whom.
    PERFORM notify_staff(v_gift.org_id, 'gift_redemption_failed',
      'Gift ' || v_gift.code || ' redemption failed for ' || v_email || ' — ' || SQLERRM,
      '/app/ops/intake');
    RETURN 'redemption_failed';
  END;

  UPDATE gifts SET status = 'redeemed', redeemed_at = now(), redeemed_user_id = auth.uid()
  WHERE id = v_gift.id;

  RETURN 'redeemed';
END;
$$;


--
-- Name: FUNCTION redeem_gift(p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.redeem_gift(p_code text) IS 'D1/D2/D3 (2026-08-11): provisions a real purchase on the standard spine (config_kind-driven fulfillment_units + lesson_credits), marks the redeemer CLIENT/CUSTOMER by whether the linked offering is a real service, and only marks the gift consumed after provisioning succeeds. Failure -> ''redemption_failed'', gift stays redeemable, notify_staff records it. open_gift/redeem_gift keep their existing auth shape by design — the gift code is the credential; do not add an identity gate to either.';


--
-- Name: redeem_invitation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_invitation(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv     invitations%ROWTYPE;
  v_email   text;
  v_fn      text;
  v_ln      text;
  v_title   text;
  v_contact uuid;
  v_err     text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'sign in before redeeming an invitation';
  END IF;
  SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();

  SELECT * INTO v_inv FROM invitations
   WHERE token = p_token AND status = 'sent' AND expires_at > now();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invitation is not valid or has expired';
  END IF;
  IF lower(v_inv.email) IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'this invitation was issued to a different email address';
  END IF;

  v_fn    := nullif(btrim(coalesce(v_inv.first_name, '')), '');
  v_ln    := nullif(btrim(coalesce(v_inv.last_name,  '')), '');
  v_title := nullif(btrim(coalesce(v_inv.title,      '')), '');

  PERFORM set_config('app.allow_profile_link', '1', true);

  INSERT INTO profiles (user_id, org_id, first_name, last_name, email)
  VALUES (auth.uid(), v_inv.org_id, v_fn, v_ln, v_email)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE profiles
     SET role       = CASE WHEN v_inv.invited_role <> 'USER' THEN v_inv.invited_role ELSE role END,
         is_admin   = CASE WHEN v_inv.invited_role = 'ADMIN' THEN true ELSE is_admin END,
         org_id     = coalesce(org_id, v_inv.org_id),
         first_name = coalesce(nullif(btrim(coalesce(first_name, '')), ''), v_fn),
         last_name  = coalesce(nullif(btrim(coalesce(last_name,  '')), ''), v_ln)
   WHERE user_id = auth.uid();

  -- Resolve the person contact this invitation belongs to: the invitation's
  -- own contact, else the same by-email resolution the provisioning spine
  -- uses (never a company contact, never email-matching the shared pair —
  -- is_company is excluded structurally).
  v_contact := v_inv.contact_id;
  IF v_contact IS NULL THEN
    SELECT c.id INTO v_contact FROM contacts c
     WHERE lower(c.email) = v_email AND c.deleted_at IS NULL AND NOT c.is_company
       AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.contact_id = c.id AND p.user_id <> auth.uid())
     ORDER BY c.created_at LIMIT 1;
  END IF;

  IF v_contact IS NOT NULL THEN
    -- ITEM 3: redemption converts a LEAD into a real CONTACT.
    UPDATE contacts SET contact_type = 'CONTACT'
     WHERE id = v_contact AND contact_type = 'LEAD';

    -- THE SPINE: link/merge, signature account-stamp, members, derive groups.
    -- ITEM 4: a merge collision must not dead-end the invitation. The scan in
    -- promote_contact_to_account now runs before any mutation, so catching
    -- here leaves the database untouched; we surface the conflict to staff and
    -- re-raise so the transaction rolls back with the invitation still 'sent'.
    BEGIN
      PERFORM promote_contact_to_account(auth.uid(), v_contact);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      -- staff-visible record of the collision, outside the doomed transaction
      PERFORM pg_notify('redemption_conflict',
        json_build_object('contact_id', v_contact, 'user_id', auth.uid(),
                          'invitation_id', v_inv.id, 'error', v_err)::text);
      INSERT INTO notifications (org_id, user_id, kind, title, body, link)
      SELECT v_inv.org_id, pr.user_id, 'redemption_conflict',
             'Account linking hit a data conflict',
             'A member could not be linked to their contact record during redemption: '
               || v_err || ' Their invitation remains valid until this is resolved.',
             '/app/ops/contacts/' || v_contact::text
        FROM profiles pr
       WHERE pr.org_id = v_inv.org_id AND coalesce(pr.staff_active, false) = true;
      RAISE EXCEPTION 'account linking hit a data conflict — staff have been notified; your invitation remains valid, try again after it is resolved';
    END;
  ELSE
    -- No person contact exists yet (bare account) — community still follows
    -- the account (D8).
    INSERT INTO members (user_id, status, org_id)
    VALUES (auth.uid(), 'active', v_inv.org_id)
    ON CONFLICT (user_id) DO UPDATE SET status = 'active';
  END IF;

  -- ── STABILIZE ITEM 4 — THE `clients` ROW, UNCONDITIONALLY ────────────────
  --
  -- Staff accounts are excluded: an operator is not someone we serve, and a
  -- clients row would put them in the booking form's CLIENT dropdown. Everyone
  -- else who finishes a redemption is a person this business serves, whatever
  -- door they came through, and the standing-slot machinery, the manual-booking
  -- dropdown and `current_client_id()` all key on exactly this row.
  --
  -- Swallowed for the same reason the contract redemption swallows it: an
  -- account that is otherwise fully activated must not be rolled back because
  -- a provisioning nicety failed. Idempotent — it no-ops when the row exists.
  IF v_inv.invited_role = 'USER' AND v_email IS NOT NULL THEN
    BEGIN
      PERFORM _ensure_client_account(v_inv.org_id, v_email, v_fn, v_ln,
        ARRAY['GUEST'], ARRAY[]::text[]);
    EXCEPTION WHEN others THEN NULL;
    END;
  END IF;

  IF v_inv.invited_role IN ('MANAGER','ADMIN','EMPLOYEE') AND v_title IS NOT NULL THEN
    UPDATE profiles SET title = v_title, staff_active = true WHERE user_id = auth.uid();
  END IF;

  -- Success: 'redeemed' is the new terminal success marker (accepted stays as
  -- the legacy value on historical rows).
  UPDATE invitations SET status = 'redeemed', redeemed_at = now() WHERE id = v_inv.id;

  -- close the inbound lifecycle: the request that produced this invitation is
  -- CONVERTED once the person actually creates their account. Guarded so a
  -- re-redemption or a manually-advanced request is never walked backwards.
  IF v_inv.request_id IS NOT NULL THEN
    UPDATE requests SET status = 'converted'
     WHERE id = v_inv.request_id AND status IS DISTINCT FROM 'converted';
  END IF;

  -- ── P1 ITEM 1 — THE INVITATION MAY ALSO CARRY A CONTRACT ─────────────────
  --
  -- One invitation, one email, two meanings: `document_id` is set by
  -- invite_contract_party_account when staff send a contract to a counterparty
  -- who has no account. The ROUTING is the caller's (validate_invitation returns
  -- the same document_id); what belongs HERE is the half redeem_contract_invitation
  -- does at the same moment — PARTYEMAIL Phase 4b, D22 §7: the record has just
  -- become readable, so push it into the party tokens and recompose, or the
  -- document she is about to be shown still carries the blanks it was drafted with.
  --
  -- Swallowed, exactly as the contract path swallows it: a propagation that
  -- cannot run must never cost someone their account.
  IF v_inv.document_id IS NOT NULL THEN
    BEGIN
      PERFORM regenerate_contract_document(v_inv.document_id);
    EXCEPTION WHEN others THEN NULL;
    END;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: redeem_my_pending_invitation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_my_pending_invitation() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE   v_email text;   v_token text; BEGIN   IF auth.uid() IS NULL THEN     RETURN false;   END IF;    SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();   IF v_email IS NULL THEN     RETURN false;   END IF;    SELECT token INTO v_token     FROM invitations    WHERE lower(email) = v_email      AND status = 'sent'      AND expires_at > now()    ORDER BY created_at DESC    LIMIT 1;    IF v_token IS NULL THEN     RETURN false;   END IF;    PERFORM public.redeem_invitation(v_token);    RETURN EXISTS (     SELECT 1 FROM members WHERE user_id = auth.uid() AND status = 'active'   ) OR EXISTS (     SELECT 1 FROM profiles WHERE user_id = auth.uid()       AND (role IN ('ADMIN','MANAGER','EMPLOYEE','SUPER_ADMIN') OR is_admin)   ); END; $$;


--
-- Name: redline_notify(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redline_notify(p_document_id uuid, p_kind text, p_prefix text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO notifications (org_id, user_id, kind, title, link)
  SELECT d.org_id, pr.user_id, p_kind,
         p_prefix || coalesce(d.title, 'a contract'),
         '/app/contracts/' || d.id::text
  FROM documents d
  JOIN document_parties dp ON dp.document_id = d.id
  JOIN profiles pr ON pr.contact_id = dp.contact_id
  WHERE d.id = p_document_id AND pr.user_id IS NOT NULL AND pr.user_id <> auth.uid();
$$;


--
-- Name: regenerate_contract_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_contract_document(p_document_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc     documents%ROWTYPE;
  v_horse   horses%ROWTYPE;
  v_body    text;
  v_new     text;
  v_tver    integer;
  v_drifted boolean := false;
  r         record;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  IF NOT coalesce(caller_is_document_party_or_staff(p_document_id), false) THEN
    RAISE EXCEPTION 'not authorized to regenerate document %', p_document_id;
  END IF;

  -- Only a contract-engine document has party tokens to refresh; a release or a
  -- policy is generated once and never recomposed.
  IF v_doc.contract_id IS NULL THEN RETURN v_doc.merged_body; END IF;
  -- A voided or terminated document is a record of something that ended. Nothing
  -- is pushed into it.
  IF v_doc.status = 'VOID' OR v_doc.voided_at IS NOT NULL OR v_doc.terminated_at IS NOT NULL THEN
    RETURN v_doc.merged_body;
  END IF;

  -- ── the horse record -> HORSE.* tokens (D22 §7's symmetric half) ───────────
  -- Only a value the record actually holds is pushed: horse_field_token_value
  -- returns '' for the tokens the horses table has no column for (HORSE.LABEL,
  -- the medication detail lines), and those keep whatever was typed.
  IF v_doc.horse_id IS NOT NULL THEN
    SELECT * INTO v_horse FROM horses WHERE id = v_doc.horse_id AND deleted_at IS NULL;
    IF FOUND THEN
      FOR r IN
        SELECT cf.id, cf.value,
               upper(split_part(regexp_replace(cf.field_key, '[{}]', '', 'g'), '.', 2)) AS field
          FROM contract_fields cf
         WHERE cf.document_id = p_document_id
           AND regexp_replace(cf.field_key, '[{}]', '', 'g') LIKE 'HORSE.%'
      LOOP
        v_new := horse_field_token_value(v_horse, r.field);
        IF nullif(btrim(coalesce(v_new, '')), '') IS NOT NULL
           AND r.value IS DISTINCT FROM v_new THEN
          UPDATE contract_fields SET value = v_new, updated_at = now() WHERE id = r.id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── the contact records -> the party tokens ────────────────────────────────
  PERFORM fill_party_fields_from_contacts(p_document_id);

  v_body := remerge_contract_from_clauses(p_document_id);
  -- NULL = a flat (non-clause) template: nothing recomposes from clauses, and the
  -- fill above has already re-merged it from its fields.
  IF v_body IS NULL THEN
    RETURN (SELECT merged_body FROM documents WHERE id = p_document_id);
  END IF;

  -- ── replay the signatures ──────────────────────────────────────────────────
  FOR r IN
    SELECT CASE WHEN s.party_role = 'BUYER' AND t.rn > 1 THEN 'COBUYER' ELSE s.party_role END AS ns,
           s.typed_name, s.signed_at
      FROM signatures s
      LEFT JOIN (
        SELECT dp.contact_id,
               row_number() OVER (ORDER BY dp.signer_order NULLS LAST, dp.id) AS rn
          FROM document_parties dp
         WHERE dp.document_id = p_document_id AND dp.party_role = 'BUYER'
      ) t ON t.contact_id = s.signer_contact_id
     WHERE s.document_id = p_document_id
       AND s.deleted_at IS NULL AND s.signed_at IS NOT NULL
  LOOP
    v_body := replace(v_body, '{{SIG.' || r.ns || '.NAME}}', coalesce(r.typed_name, ''));
    v_body := replace(v_body, '{{SIG.' || r.ns || '.DATE}}',
                      to_char(r.signed_at, 'FMMonth FMDD, YYYY'));
  END LOOP;

  -- ── template drift guard (see the header) ──────────────────────────────────
  IF coalesce(v_doc.workflow_state, '') = 'executed' THEN
    SELECT ct.version INTO v_tver FROM contract_templates ct WHERE ct.id = v_doc.template_id;
    v_drifted := (v_doc.signed_template_version IS DISTINCT FROM v_tver);
  END IF;
  IF v_drifted THEN
    RETURN (SELECT merged_body FROM documents WHERE id = p_document_id);
  END IF;

  UPDATE documents SET merged_body = v_body WHERE id = p_document_id;
  RETURN v_body;
END;
$$;


--
-- Name: regroup_contract_subjects(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regroup_contract_subjects(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- BOARDING subject
  UPDATE contract_fields SET section='Boarding', sort_order=CASE field_key
      WHEN 'TXN.BOARDING_RESPONSIBILITY' THEN 1000 WHEN 'TXN.BOARD_COST' THEN 1001 ELSE sort_order END
    WHERE document_id=p_document_id AND field_key IN ('TXN.BOARDING_RESPONSIBILITY','TXN.BOARD_COST');

  -- FARRIER subject
  UPDATE contract_fields SET section='Farrier', sort_order=CASE field_key
      WHEN 'TXN.FARRIER_RESPONSIBILITY' THEN 1100 WHEN 'TXN.FARRIER_COST' THEN 1101 ELSE sort_order END
    WHERE document_id=p_document_id AND field_key IN ('TXN.FARRIER_RESPONSIBILITY','TXN.FARRIER_COST');

  -- VETERINARY subject (routine + emergency + non-routine + auth contact)
  UPDATE contract_fields SET section='Veterinary Care', sort_order=CASE field_key
      WHEN 'TXN.ROUTINE_VET_RESPONSIBILITY' THEN 1200 WHEN 'TXN.ROUTINE_VET_COST' THEN 1201
      WHEN 'TXN.EMERGENCY_VET_RESPONSIBILITY' THEN 1202 WHEN 'TXN.NON_ROUTINE_VET_COST' THEN 1203
      WHEN 'TXN.VET_AUTH_CONTACT' THEN 1204 ELSE sort_order END
    WHERE document_id=p_document_id AND field_key IN
      ('TXN.ROUTINE_VET_RESPONSIBILITY','TXN.ROUTINE_VET_COST','TXN.EMERGENCY_VET_RESPONSIBILITY',
       'TXN.NON_ROUTINE_VET_COST','TXN.VET_AUTH_CONTACT');

  -- SUPPLEMENTS subject
  UPDATE contract_fields SET section='Supplements & Medications', sort_order=CASE field_key
      WHEN 'TXN.SUPPLEMENTS' THEN 1300 WHEN 'TXN.SUPPLEMENTS_RESPONSIBILITY' THEN 1301
      WHEN 'TXN.SUPPLEMENTS_COST' THEN 1302 ELSE sort_order END
    WHERE document_id=p_document_id AND field_key IN
      ('TXN.SUPPLEMENTS','TXN.SUPPLEMENTS_RESPONSIBILITY','TXN.SUPPLEMENTS_COST');

  -- EXERCISE & HANDLING subject
  UPDATE contract_fields SET section='Exercise & Handling', sort_order=CASE field_key
      WHEN 'TXN.CARE_RESPONSIBILITY' THEN 1400 WHEN 'TXN.EXERCISE_RESPONSIBILITY' THEN 1401
      WHEN 'TXN.CLIPPING_RESPONSIBILITY' THEN 1402 ELSE sort_order END
    WHERE document_id=p_document_id AND field_key IN
      ('TXN.CARE_RESPONSIBILITY','TXN.EXERCISE_RESPONSIBILITY','TXN.CLIPPING_RESPONSIBILITY');

  -- TRAINING & LESSONS: fold their costs into the existing Training & Lessons section
  UPDATE contract_fields SET section='Training & Lessons'
    WHERE document_id=p_document_id AND field_key IN ('TXN.TRAINING_COST','TXN.LESSONS_COST');

  -- OTHER care/expenses → their own subject
  UPDATE contract_fields SET section='Other Care & Expenses'
    WHERE document_id=p_document_id AND field_key IN ('TXN.OTHER_CARE_COST','TXN.OTHER_EXPENSES_COST');
END;
$$;


--
-- Name: release_preview(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_preview(p_template_key text, p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(title text, body text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid;
  v_tmpl   record;
  v_cfg    business_config%ROWTYPE;
  v_body   text;
  v_ident  text;
  v_phone  text;
  v_email  text;
  v_url    text;
  v_princ  text;
  v_marker text;
  v_cut    integer;
BEGIN
  -- The kiosk's readable surface: the four releases + the rules-gate document.
  IF p_template_key NOT IN ('RELEASE_GENERAL','RELEASE_PARTICIPANT',
                            'RELEASE_HORSE_EXERCISE','RELEASE_HORSE_CARE',
                            'FACILITY_RULES','COMPANY_POLICIES',
                            'HUMAN_EMERGENCY_MEDICAL') THEN
    RAISE EXCEPTION 'unknown release template: %', p_template_key;
  END IF;

  v_org := coalesce(p_org, current_org(), current_addressed_org(), sole_org());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no organization resolvable for release preview';
  END IF;

  SELECT t.title, t.body INTO v_tmpl
    FROM contract_templates t
   WHERE t.template_key = p_template_key AND t.active AND t.body IS NOT NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'release template unavailable: %', p_template_key;
  END IF;

  SELECT * INTO v_cfg FROM business_config bc WHERE bc.org_id = v_org;
  SELECT cv.value_text INTO v_ident FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'ORG' AND cv.key = 'LEGAL_IDENTITY';
  SELECT cv.value_text INTO v_phone FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'CONTACT' AND cv.key = 'PHONE';
  SELECT cv.value_text INTO v_email FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'CONTACT' AND cv.key = 'EMAIL';
  SELECT cv.value_text INTO v_url FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'CONTACT' AND cv.key = 'URL';
  SELECT cv.value_text INTO v_princ FROM config_values cv
   WHERE cv.org_id = v_org AND cv.namespace = 'ORG' AND cv.key = 'PRINCIPALS';

  v_body := v_tmpl.body;
  -- Truncate BEFORE merging: nothing signature-ish reaches a preview. Owner
  -- revision 2026-07-03: every kiosk document (all four releases AND
  -- FACILITY_RULES) ends with the SAME single CLIENT signer block, and the
  -- minor CUT section sits below it — one marker truncates them all.
  v_marker := E'CLIENT\n\nDate: {{SIG.CLIENT.DATE}}';
  v_cut := position(v_marker IN v_body);
  IF v_cut > 0 THEN
    v_body := rtrim(left(v_body, v_cut - 1));
  END IF;
  -- Belt-and-braces: no CUT-marker comment may survive into a rendered preview
  -- (today they all live below the truncation point).
  v_body := regexp_replace(v_body, '[ \t]*<!-- CUT-(START|END): [A-Z_]+[^>]*-->\n?', '', 'g');

  -- Releases identify the business by trade name only (owner 2026-07-02); the
  -- LEGAL_IDENTITY arm stays for non-release documents.
  v_body := replace(v_body, '{{ORG.LEGAL_IDENTITY}}',  coalesce(v_ident, v_cfg.legal_entity_name, ''));
  v_body := replace(v_body, '{{ORG.LEGAL_NAME}}',      coalesce(v_cfg.legal_entity_name, ''));
  v_body := replace(v_body, '{{ORG.SIGNATORY_NAME}}',  coalesce(v_cfg.signatory_name, ''));
  v_body := replace(v_body, '{{ORG.SIGNATORY_TITLE}}', coalesce(v_cfg.signatory_title, ''));
  v_body := replace(v_body, '{{ORG.ADDRESS}}',         coalesce(v_cfg.business_address, ''));
  v_body := replace(v_body, '{{ORG.PHONE}}',           coalesce(v_phone, ''));
  v_body := replace(v_body, '{{ORG.EMAIL}}',           coalesce(v_email, ''));
  v_body := replace(v_body, '{{ORG.URL}}',             coalesce(v_url, ''));
  -- Named principals in the Released Parties definitions (2026-08-02 bodies).
  v_body := replace(v_body, '{{ORG.PRINCIPALS}}',      coalesce(v_princ, ''));
  v_body := replace(v_body, '{{DOC.EFFECTIVE_DATE}}',  to_char(current_date, 'FMMonth DD, YYYY'));
  v_body := replace(v_body, '{{DOC.GENERATED_DATE}}',  to_char(current_date, 'FMMonth DD, YYYY'));
  -- Any remaining token (HORSE.*, person tokens above the cut, …) becomes a
  -- fill-in line: the signer's details land on the SIGNED document only.
  v_body := regexp_replace(v_body, '\{\{[A-Z0-9_.]+\}\}', '__________', 'g');

  RETURN QUERY SELECT v_tmpl.title, v_body;
END;
$$;


--
-- Name: FUNCTION release_preview(p_template_key text, p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.release_preview(p_template_key text, p_org uuid) IS 'Public kiosk preview: merges org identity + dates for one of the four RELEASE_* templates (or FACILITY_RULES for the rules gate) and truncates the body before the CLIENT signer block (owner 2026-07-03 single-signer canon). Org: p_org -> current_org() -> addressed org -> sole_org().';


--
-- Name: remerge_contract_body(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remerge_contract_body(p_document_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_body text;
BEGIN
  v_body := remerge_contract_from_clauses(p_document_id);   -- NULL if no clause defs
  IF v_body IS NOT NULL THEN
    RETURN v_body;
  END IF;
  RETURN remerge_contract_from_fields(p_document_id);
END;
$$;


--
-- Name: remerge_contract_from_clauses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remerge_contract_from_clauses(p_document_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_doc documents%ROWTYPE; v_tkey text;
  v_fields jsonb := '{}'::jsonb; v_labels jsonb := '{}'::jsonb;
  v_out text[] := '{}'; v_sec_buf text[]; v_cl_buf text[];
  v_sec record; v_cl record; v_sec_no int := 0; v_cl_no int; v_sub_no int := 0;
  v_body text; v_lines text[]; v_line text; v_stripped text;
  v_toks text[]; v_tok text; v_any_token boolean; v_all_empty boolean; v_has_sig boolean;
  v_is_label_line boolean;
  v_na boolean;
  r record; v_cf record; v_val text;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  SELECT template_key INTO v_tkey FROM contract_templates WHERE id = v_doc.template_id;
  IF NOT EXISTS (SELECT 1 FROM contract_clause_defs WHERE template_key = v_tkey) THEN RETURN NULL; END IF;

  /* B4: once the document has left the editable phase its content is the
     instrument, so an author-added entry nobody filled must SAY it is empty
     rather than vanish. Blank CUSTOM tokens compose as 'N/A' from that point. */
  v_na := coalesce(v_doc.workflow_state, '') NOT IN ('editable','editing');

  PERFORM recompose_document_fields(p_document_id);
  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val FROM contract_fields WHERE document_id = p_document_id LOOP
    v_fields := v_fields || jsonb_build_object(r.field_key, r.val);
  END LOOP;
  SELECT coalesce(jsonb_object_agg(field_key, vmap), '{}'::jsonb) INTO v_labels
  FROM (SELECT field_key, jsonb_object_agg(opt->>'value', opt->>'label') AS vmap
          FROM contract_field_defs fd CROSS JOIN LATERAL jsonb_array_elements(fd.options) AS opt
         WHERE fd.template_key = v_tkey AND fd.options IS NOT NULL GROUP BY field_key) m;
  -- author-added elements carry their option labels on the DOCUMENT, not the
  -- template, so their values resolve to words too.
  SELECT v_labels || coalesce(jsonb_object_agg(field_key, vmap), '{}'::jsonb) INTO v_labels
  FROM (SELECT field_key, jsonb_object_agg(opt->>'value', opt->>'label') AS vmap
          FROM contract_fields cfo CROSS JOIN LATERAL jsonb_array_elements(cfo.options) AS opt
         WHERE cfo.document_id = p_document_id AND cfo.custom_kind = 'element'
           AND cfo.options IS NOT NULL GROUP BY field_key) m2;

  FOR v_sec IN
    SELECT section_key, heading, cut_name, ord FROM (
      SELECT sd.section_key, sd.heading, sd.cut_name, (sd.sort_order::numeric * 1000) AS ord
        FROM contract_section_defs sd WHERE sd.template_key = v_tkey
      UNION ALL
      SELECT cs.section, coalesce(nullif(btrim(cs.label),''), cs.section), NULL::text, cs.sort_order::numeric
        FROM contract_fields cs
       WHERE cs.document_id = p_document_id AND cs.custom_kind = 'section'
    ) s ORDER BY ord
  LOOP
    IF v_sec.cut_name IS NOT NULL AND NOT clause_cut_kept(v_sec.cut_name, v_fields) THEN CONTINUE; END IF;
    v_sec_buf := '{}'; v_cl_no := 0; v_sub_no := 0;

    FOR v_cl IN
      SELECT clause_key, heading, body, clause_type, is_optional, cut_name,
             conditional_on, render_as_subitem, ord1, ord2 FROM (
        SELECT cd.clause_key, cd.heading, cd.body, cd.clause_type, cd.is_optional,
               cd.cut_name, cd.conditional_on, cd.render_as_subitem,
               (cd.sort_order::numeric * 1000) AS ord1, 0::numeric AS ord2
          FROM contract_clause_defs cd
         WHERE cd.template_key = v_tkey AND cd.section_key = v_sec.section_key
        UNION ALL
        -- author-added HEADER: a clause with a heading and no body of its own
        SELECT ch.field_key, coalesce(nullif(btrim(ch.label),''), 'Item'), NULL::text,
               'prose', false, NULL::text, NULL::jsonb, false,
               ch.sort_order::numeric, 0::numeric
          FROM contract_fields ch
         WHERE ch.document_id = p_document_id AND ch.custom_kind = 'header'
           AND ch.section = v_sec.section_key
        UNION ALL
        -- author-added LINE: headingless continuation, sorted under its header
        SELECT cl.field_key, NULL::text, cl.body, 'prose', false, NULL::text,
               cl.conditional_on, false,
               coalesce(cdh.sort_order::numeric * 1000, cfh.sort_order::numeric, 2147483647::numeric),
               cl.sort_order::numeric
          FROM contract_fields cl
          LEFT JOIN contract_clause_defs cdh
            ON cdh.template_key = v_tkey AND cdh.clause_key = cl.clause_key
           AND cdh.section_key = v_sec.section_key
          LEFT JOIN contract_fields cfh
            ON cfh.document_id = p_document_id AND cfh.field_key = cl.clause_key
           AND cfh.custom_kind = 'header'
         WHERE cl.document_id = p_document_id AND cl.custom_kind = 'line'
           AND cl.section = v_sec.section_key
      ) c ORDER BY ord1, ord2
    LOOP
      IF v_cl.cut_name IS NOT NULL AND NOT clause_cut_kept(v_cl.cut_name, v_fields) THEN CONTINUE; END IF;
      IF NOT clause_condition_met(v_cl.conditional_on, v_fields) THEN CONTINUE; END IF;
      v_body := coalesce(v_cl.body, '');

      IF v_cl.clause_type = 'input' AND v_cl.is_optional THEN
        v_toks := ARRAY(SELECT (regexp_matches(v_body, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1]);
        v_all_empty := true;
        FOREACH v_tok IN ARRAY coalesce(v_toks, ARRAY[]::text[]) LOOP
          IF v_tok NOT LIKE 'SIG.%' AND coalesce(v_fields ->> v_tok,'') <> '' THEN v_all_empty := false; END IF;
        END LOOP;
        IF coalesce(array_length(v_toks,1),0) > 0 AND v_all_empty THEN CONTINUE; END IF;
      END IF;

      v_cl_buf := '{}';
      IF v_body <> '' THEN
        v_lines := string_to_array(v_body, E'\n');
        FOREACH v_line IN ARRAY v_lines LOOP
          v_toks := ARRAY(SELECT (regexp_matches(v_line, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1]);
          v_any_token := coalesce(array_length(v_toks,1),0) > 0;
          /* A LABEL:VALUE MATRIX LINE ("Barn Name: {{HORSE.BARN_NAME}}", a party
             "Name: {{...}}") is not a sentence and takes no terminal period. Detect
             it from the ORIGINAL line, before substitution: the text with tokens
             removed is only a short "Label:" lead-in (optionally after a list
             marker), nothing following the token. Sentences ("...as follows:
             {{TOKEN}}") do not match, so they still get their period. */
          v_is_label_line := v_any_token
            AND regexp_replace(regexp_replace(v_line, '\{\{[A-Z0-9_.]+\}\}', '', 'g'),
                               '[[:space:]]+$', '')
                ~ '^[[:space:]]*(?:[-*][[:space:]]*)?[[:alpha:]][[:alpha:][:digit:] ''()/-]{0,60}:[[:space:]]*$';
          IF NOT v_any_token THEN
            /* R11: an AUTHORED line is never typed with a closing period —
               the composer supplies terminal punctuation here, exactly as R5
               does for a token-bearing line. Template prose is left verbatim:
               its punctuation is part of the drafted instrument. */
            IF v_cl.clause_key LIKE 'CUSTOM.%' AND btrim(v_line) <> ''
               AND btrim(v_line) !~ '[.!?:;)"'']$' THEN
              v_line := v_line || '.';
            END IF;
            v_cl_buf := array_append(v_cl_buf, v_line); CONTINUE;
          END IF;
          -- line-level field gating: if any token on this line is a field with an
          -- unmet conditional_on, drop the whole line.
          IF EXISTS (
            SELECT 1 FROM unnest(v_toks) t
             JOIN contract_field_defs fdg
               ON fdg.template_key = v_tkey AND fdg.field_key = t
            WHERE fdg.conditional_on IS NOT NULL
              AND NOT clause_condition_met(fdg.conditional_on, v_fields)
          ) THEN CONTINUE; END IF;
          v_all_empty := true; v_has_sig := false;
          FOREACH v_tok IN ARRAY v_toks LOOP
            IF v_tok LIKE 'SIG.%' THEN v_has_sig := true; v_all_empty := false;
            ELSIF v_tok = 'DOC.EFFECTIVE_DATE' THEN v_all_empty := false;
            ELSIF v_tok LIKE 'CUSTOM.%' AND v_na THEN v_all_empty := false;   -- B4: prints N/A
            ELSIF coalesce(v_fields ->> v_tok,'') <> '' THEN v_all_empty := false; END IF;
          END LOOP;
          IF v_all_empty AND NOT v_has_sig THEN
            v_stripped := regexp_replace(v_line, '\{\{[A-Z0-9_.]+\}\}', '', 'g');
            -- drop a leading "Label:" (up to ~5 words) so a labeled line with only
            -- blank tokens is treated as empty and omitted, not printed as "Label:".
            v_stripped := regexp_replace(v_stripped, '^\s*[[:alpha:]][[:alpha:] ''()/-]{0,60}:\s*', '');
            v_stripped := btrim(regexp_replace(v_stripped, '[[:punct:][:space:]]', '', 'g'));
            IF v_stripped = '' THEN CONTINUE; END IF;
          END IF;
          FOREACH v_tok IN ARRAY v_toks LOOP
            IF v_tok LIKE 'SIG.%' THEN CONTINUE;
            ELSIF v_tok = 'DOC.EFFECTIVE_DATE' THEN
              v_line := replace(v_line, '{{'||v_tok||'}}', to_char(coalesce(v_doc.effective_date, v_doc.created_at::date), 'FMMonth FMDD, YYYY'));
            ELSIF v_tok LIKE 'CUSTOM.%' AND v_na AND coalesce(v_fields ->> v_tok,'') = '' THEN
              v_line := replace(v_line, '{{'||v_tok||'}}', 'N/A');
            ELSIF EXISTS (SELECT 1 FROM contract_field_defs fdc
                          WHERE fdc.template_key = v_tkey AND fdc.field_key = v_tok
                            AND fdc.format_type = 'certify') THEN
              v_line := replace(v_line, '{{'||v_tok||'}}', certify_statement(v_tok, v_fields ->> v_tok, v_tkey));
            ELSIF (v_fields ->> v_tok) ~ '^\d+(\.\d+)?$'
              AND EXISTS (SELECT 1 FROM contract_field_defs fdpct
                          WHERE fdpct.template_key = v_tkey AND fdpct.field_key = v_tok
                            AND fdpct.format_type = 'percent') THEN
              v_line := replace(v_line, '{{'||v_tok||'}}', (v_fields ->> v_tok) || '%');
            ELSIF (v_fields ->> v_tok) ~ '^\d+(\.\d+)?$'
              AND EXISTS (SELECT 1 FROM contract_field_defs fdcur
                          WHERE fdcur.template_key = v_tkey AND fdcur.field_key = v_tok
                            AND fdcur.format_type = 'currency') THEN
              v_line := replace(v_line, '{{'||v_tok||'}}', fmt_money((v_fields ->> v_tok)::numeric));
            ELSE v_line := replace(v_line, '{{'||v_tok||'}}', token_display_value(v_tok, v_fields ->> v_tok, v_labels)); END IF;
          END LOOP;
          /* R5 (2026-08-04): sentence-terminal punctuation is appended HERE,
             not authored into the body. The clause bodies used to end
             "…: {{TOKEN}}." which produced an orphan "." under a full-width
             input in the editor and a doubled ".." whenever the signer typed
             their own period. Now: if the composed line ends with a filled
             token and lacks terminal punctuation, add one. A line whose token
             resolved to empty gets nothing, so no orphan period survives. */
          /* Only punctuate a line that actually SAYS something: a line whose
             token resolved to empty ends in its lead-in colon ("are: ") and
             must stay bare rather than becoming "are: ." — the unanswered
             field is already flagged by the required marker. */
          /* CR-101·A1 (owner, 2026-09-02): "we dont need a (.) at the end of a
             line that has a signature in it." A signature-block line keeps its
             SIG.* token here (skipped above) and resolves it at signing time
             (record_signature) or display time (documentBody.ts), where this
             guard cannot see the result — so the "." it would add became
             "Signature: ." unsigned and "Name." signed. v_has_sig, computed
             above for this very line, is the flag: the whole block (NAME and
             DATE lines) is exempt. Every other token line keeps its period. */
          IF NOT v_has_sig AND NOT v_is_label_line AND btrim(v_line) <> '' AND btrim(v_line) !~ '[.!?:;)"'']$'
             AND btrim(v_line) !~ '^\[\[/?DISCLOSURE' THEN
            v_line := v_line || '.';
          END IF;
          v_line := regexp_replace(v_line, ':\s*\.\s*$', ':');
          v_line := regexp_replace(v_line, '\s+([.,;])', '\1', 'g');
          v_cl_buf := array_append(v_cl_buf, v_line);
        END LOOP;
      END IF;

      IF (v_cl.heading IS NULL OR v_cl.heading = '') AND NOT EXISTS (SELECT 1 FROM unnest(coalesce(v_cl_buf, ARRAY[]::text[])) x WHERE btrim(x) <> '') THEN CONTINUE; END IF;

      IF coalesce(v_cl.render_as_subitem,false) AND (v_cl.heading IS NULL OR v_cl.heading = '') AND coalesce(array_length(v_cl_buf,1),0) > 0 THEN
        v_sub_no := coalesce(array_upper(v_sec_buf,1),0);
          WHILE v_sub_no >= 1 AND v_sec_buf[v_sub_no] = '' LOOP v_sub_no := v_sub_no - 1; END LOOP;
          IF v_sub_no >= 1 THEN
            v_sec_buf[v_sub_no] := v_sec_buf[v_sub_no] || ' ' || array_to_string(v_cl_buf, ' ');
        ELSE
          v_sec_buf := v_sec_buf || v_cl_buf;
        END IF;
      ELSE
      v_sub_no := 0;
      /* R11: the NUMBER belongs to the HEADING. Only a headed clause consumes
         one; a headingless clause is continuation text under the item above
         (or section preamble when no header precedes it) and is emitted bare. */
      IF v_cl.heading IS NOT NULL AND v_cl.heading <> '' THEN
        v_cl_no := v_cl_no + 1;
        v_sec_buf := array_append(v_sec_buf, ('§CLAUSENUM§.' || v_cl_no || ' ' || v_cl.heading)::text);
        IF coalesce(array_length(v_cl_buf,1),0) > 0 THEN v_sec_buf := v_sec_buf || v_cl_buf; END IF;
      ELSE
        IF coalesce(array_length(v_cl_buf,1),0) > 0 THEN
          v_sec_buf := v_sec_buf || v_cl_buf;
        END IF;
      END IF;
      END IF;
      v_sec_buf := array_append(v_sec_buf, ''::text);
    END LOOP;

    -- LEGACY custom fields (pre-R11 add surface): still "Label: value" at the
    -- end of the section they were added to.
    FOR v_cf IN SELECT field_key, label, value FROM contract_fields
                 WHERE document_id = p_document_id AND field_key LIKE 'CUSTOM.%'
                   AND custom_kind IS NULL
                   AND section = v_sec.section_key ORDER BY sort_order LOOP
      v_val := btrim(coalesce(v_cf.value, ''));
      IF v_val = '' THEN
        IF NOT v_na THEN CONTINUE; END IF;                          -- omit while editable
        v_val := 'N/A';                                             -- B4 at execution
      END IF;
      v_cl_no := v_cl_no + 1;
      v_sec_buf := array_append(v_sec_buf,
        ('§CLAUSENUM§.' || v_cl_no || ' ' || coalesce(v_cf.label,'Item') || ': ' || v_val)::text);
      v_sec_buf := array_append(v_sec_buf, ''::text);
    END LOOP;

    IF coalesce(array_length(v_sec_buf,1),0) > 0 THEN
      v_sec_no := v_sec_no + 1;
      v_out := array_append(v_out, (v_sec_no || '. ' || upper(v_sec.heading))::text);
      v_out := v_out || ARRAY(SELECT replace(x, '§CLAUSENUM§', v_sec_no::text) FROM unnest(v_sec_buf) x);
    END IF;
  END LOOP;

  -- LEGACY custom SECTIONS (a pre-R11 CUSTOM.* field whose `section` matches no
  -- section_def and has no author-added section row): emitted after everything.
  FOR v_sec IN
    SELECT DISTINCT section FROM contract_fields
     WHERE document_id = p_document_id AND field_key LIKE 'CUSTOM.%'
       AND custom_kind IS NULL
       AND section NOT IN (SELECT section_key FROM contract_section_defs WHERE template_key = v_tkey)
       AND section NOT IN (SELECT cs.section FROM contract_fields cs
                            WHERE cs.document_id = p_document_id AND cs.custom_kind = 'section')
     ORDER BY section
  LOOP
    v_sec_buf := '{}'; v_cl_no := 0; v_sub_no := 0;
    FOR v_cf IN SELECT field_key, label, value FROM contract_fields
                 WHERE document_id = p_document_id AND field_key LIKE 'CUSTOM.%'
                   AND custom_kind IS NULL
                   AND section = v_sec.section ORDER BY sort_order LOOP
      v_val := btrim(coalesce(v_cf.value, ''));
      IF v_val = '' THEN
        IF NOT v_na THEN CONTINUE; END IF;
        v_val := 'N/A';
      END IF;
      v_cl_no := v_cl_no + 1;
      v_sec_buf := array_append(v_sec_buf,
        ('§CLAUSENUM§.' || v_cl_no || ' ' || coalesce(v_cf.label,'Item') || ': ' || v_val)::text);
      v_sec_buf := array_append(v_sec_buf, ''::text);
    END LOOP;
    IF coalesce(array_length(v_sec_buf,1),0) > 0 THEN
      v_sec_no := v_sec_no + 1;
      v_out := array_append(v_out, (v_sec_no || '. ' || upper(v_sec.section))::text);
      v_out := v_out || ARRAY(SELECT replace(x, '§CLAUSENUM§', v_sec_no::text) FROM unnest(v_sec_buf) x);
    END IF;
  END LOOP;

  v_body := array_to_string(v_out, E'\n');
  /* A numbered SECTION heading ("3. THE HORSE") and a numbered SUBITEM heading
     ("3.1 Horse") each open with a blank line before them, so sections and
     subsections are visually separated in the composed body and the party view.
     Applied to the whole body so the rule holds however a heading was emitted,
     then runs of blank lines collapse to a single one. */
  v_body := regexp_replace(v_body, E'([^\n])\n(\d+\.(?:\d+)?[ \t])', E'\1\n\n\2', 'g');
  v_body := regexp_replace(v_body, E'\n{3,}', E'\n\n', 'g');
  v_body := regexp_replace(v_body, E'^\n+', '', 'g');
  UPDATE documents SET merged_body = v_body WHERE id = p_document_id AND workflow_state <> 'executed';
  RETURN v_body;
END;
$_$;


--
-- Name: remerge_contract_from_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remerge_contract_from_fields(p_document_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc      documents%ROWTYPE;
  v_body     text;
  v_fields   jsonb := '{}'::jsonb;     -- field_key â value (trimmed; '' when empty)
  v_keep     boolean;
  v_name     text;
  v_lines    text[];
  v_out      text[] := '{}';
  v_line     text;
  v_toks     text[];
  v_tok      text;
  v_all_empty boolean;
  v_has_sig   boolean;
  v_has_printed boolean;
  v_any_token boolean;
  r          record;
BEGIN
  IF auth.uid() IS NULL AND current_setting('request.jwt.claims', true) IS NULL THEN
    NULL; -- service/definer chains allowed
  END IF;

  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  -- staff of the org, the originator, or any document party may re-derive
  IF NOT (
       (coalesce(has_staff_access() AND v_doc.org_id = current_org(), false))
    OR caller_is_document_party(p_document_id)
  ) THEN
    RAISE EXCEPTION 'not authorized to re-merge document %', p_document_id;
  END IF;

  -- 1. the ORIGINAL tokenized template body
  SELECT body INTO v_body FROM contract_templates WHERE id = v_doc.template_id;
  IF v_body IS NULL THEN
    RAISE EXCEPTION 'document % has no template body', p_document_id;
  END IF;

  -- 0. compose structured fields into their  first, so token substitution
  --    below picks up prose derived from the structured source of truth.
  PERFORM recompose_document_fields(p_document_id);

  -- 2. field map
  FOR r IN SELECT field_key, coalesce(trim(value), '') AS val
             FROM contract_fields WHERE document_id = p_document_id LOOP
    v_fields := v_fields || jsonb_build_object(r.field_key, r.val);
  END LOOP;

  -- helper predicate inline: a field is "present" when non-empty after trim
  -- 3. CUT evaluation â INSURANCE wrapper FIRST, then children, then the rest.
  FOREACH v_name IN ARRAY ARRAY[
    'INSURANCE',
    'MORTALITY_INSURANCE','MAJOR_MEDICAL_INSURANCE','LOSS_OF_USE_INSURANCE',
    'EVALUATION_PERIOD','PARTIAL_LEASE','COMPETITION'
  ] LOOP
    -- skip sections not present in this template's body
    CONTINUE WHEN position('<!-- CUT-START: ' || v_name in v_body) = 0;

    v_keep := CASE v_name
      WHEN 'EVALUATION_PERIOD' THEN
        coalesce(v_fields ->> 'TXN.EVALUATION_START', '') <> ''
        OR coalesce(v_fields ->> 'TXN.EVALUATION_END', '') <> ''
      WHEN 'PARTIAL_LEASE' THEN
        lower(coalesce(v_fields ->> 'TXN.LEASE_TYPE', '')) LIKE '%partial%'
      WHEN 'INSURANCE' THEN
        coalesce(v_fields ->> 'TXN.MORTALITY_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.MORTALITY_INSURANCE_PARTY', '') <> ''
        OR coalesce(v_fields ->> 'TXN.MAJOR_MEDICAL_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.MAJOR_MEDICAL_INSURANCE_PARTY', '') <> ''
        OR coalesce(v_fields ->> 'TXN.LOSS_OF_USE_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.LOSS_OF_USE_INSURANCE_PARTY', '') <> ''
      WHEN 'MORTALITY_INSURANCE' THEN
        coalesce(v_fields ->> 'TXN.MORTALITY_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.MORTALITY_INSURANCE_PARTY', '') <> ''
      WHEN 'MAJOR_MEDICAL_INSURANCE' THEN
        coalesce(v_fields ->> 'TXN.MAJOR_MEDICAL_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.MAJOR_MEDICAL_INSURANCE_PARTY', '') <> ''
      WHEN 'LOSS_OF_USE_INSURANCE' THEN
        coalesce(v_fields ->> 'TXN.LOSS_OF_USE_INSURANCE_COST', '') <> ''
        OR coalesce(v_fields ->> 'TXN.LOSS_OF_USE_INSURANCE_PARTY', '') <> ''
      WHEN 'COMPETITION' THEN
        coalesce(v_fields ->> 'TXN.COMPETITION_TERMS', '') <> ''
        OR coalesce(v_fields ->> 'TXN.COMPETITION_EXPENSES', '') <> ''
        OR coalesce(v_fields ->> 'TXN.COMPETITION_WINNINGS', '') <> ''
      ELSE true  -- unknown/other sections: keep content (conservative)
    END;

    IF v_keep THEN
      v_body := regexp_replace(
        v_body, '[ \t]*<!-- CUT-(START|END): ' || v_name || '[^>]*-->\n?', '', 'g');
    ELSE
      v_body := regexp_replace(
        v_body,
        '\n?[ \t]*<!-- CUT-START: ' || v_name || '[^>]*-->.*<!-- CUT-END: ' || v_name || ' -->\n?',
        E'\n', 'g');
    END IF;
  END LOOP;

  -- any other CUT sections this template carries (e.g. future additions): keep
  FOR r IN SELECT DISTINCT (regexp_matches(v_body, '<!-- CUT-START: ([A-Z_]+)', 'g'))[1] AS name LOOP
    v_body := regexp_replace(
      v_body, '[ \t]*<!-- CUT-(START|END): ' || r.name || '[^>]*-->\n?', '', 'g');
  END LOOP;

  -- 4+5. token fill + strip-unfilled, line by line
  v_lines := string_to_array(v_body, E'\n');
  FOREACH v_line IN ARRAY v_lines LOOP
    v_toks := ARRAY(SELECT (regexp_matches(v_line, '\{\{([A-Z0-9_.]+)\}\}', 'g'))[1]);
    v_any_token := coalesce(array_length(v_toks, 1), 0) > 0;

    IF NOT v_any_token THEN
      v_out := v_out || v_line;
      CONTINUE;
    END IF;

    v_all_empty := true;
    v_has_sig := false;
    v_has_printed := false;
    FOREACH v_tok IN ARRAY v_toks LOOP
      IF v_tok LIKE 'SIG.%' THEN
        v_has_sig := true; v_all_empty := false;
      ELSIF v_tok = 'DOC.EFFECTIVE_DATE' THEN
        v_all_empty := false;
      ELSIF v_tok LIKE '%.PRINTED_NAME' THEN
        v_has_printed := true;
      ELSIF coalesce(v_fields ->> v_tok, '') <> '' THEN
        v_all_empty := false;
      END IF;
    END LOOP;

    -- drop a line whose fillable tokens all resolved empty (decision 6) â unless
    -- it carries a SIG token or a PRINTED_NAME (signature-ceremony lines stay)
    IF v_all_empty AND NOT v_has_sig AND NOT v_has_printed THEN
      CONTINUE;
    END IF;

    -- fill: contract_fields values; DOC.EFFECTIVE_DATE from the document; SIG left
    FOREACH v_tok IN ARRAY v_toks LOOP
      IF v_tok LIKE 'SIG.%' THEN
        CONTINUE;
      ELSIF v_tok = 'DOC.EFFECTIVE_DATE' THEN
        v_line := replace(v_line, '{{' || v_tok || '}}',
          to_char(coalesce(v_doc.effective_date, v_doc.created_at::date), 'FMMonth FMDD, YYYY'));
      ELSE
        v_line := replace(v_line, '{{' || v_tok || '}}', coalesce(v_fields ->> v_tok, ''));
      END IF;
    END LOOP;

    v_out := v_out || v_line;
  END LOOP;

  v_body := array_to_string(v_out, E'\n');
  -- 6. collapse the gaps stripped sections/lines leave behind
  v_body := regexp_replace(v_body, E'\n{3,}', E'\n\n', 'g');

  -- 7. never rewrite an executed body
  UPDATE documents SET merged_body = v_body
   WHERE id = p_document_id AND workflow_state <> 'executed';

  RETURN v_body;
END;
$$;


--
-- Name: FUNCTION remerge_contract_from_fields(p_document_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.remerge_contract_from_fields(p_document_id uuid) IS 'Lock-time authority for negotiated contracts: rebuilds merged_body from the ORIGINAL template + current contract_fields (idempotent), evaluates the lease''s optional-section CUT conditions from field values (INSURANCE wrapper before its children), fills every non-SIG token (DOC.EFFECTIVE_DATE from the document row), drops lines whose fillable tokens all ended empty (strip-unfilled; SIG/PRINTED_NAME lines exempt), collapses blank runs. Never rewrites an executed body. Wired into the locked transition and lock_and_sign_contract.';


--
-- Name: remove_contract_composition(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_contract_composition(p_document_id uuid, p_field_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_author uuid; v_n int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'document is not editable'; END IF;

  SELECT added_by_contact_id INTO v_author FROM contract_fields
   WHERE document_id = p_document_id AND field_key = p_field_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'not an author-added item: %', p_field_key; END IF;
  IF NOT ((has_staff_access() AND v_org = current_org())
          OR (v_author IS NOT NULL AND v_author = current_contact_id())) THEN
    RAISE EXCEPTION 'only the item''s author or staff may remove it';
  END IF;

  v_n := delete_contract_composition_item(p_document_id, p_field_key);
  PERFORM remerge_contract_from_clauses(p_document_id);
  RETURN v_n;
END;
$$;


--
-- Name: remove_deal_member(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_deal_member(p_deal_id uuid, p_party_role text, p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;
  IF v_deal.status <> 'pending' THEN
    RAISE EXCEPTION 'this deal is % and can no longer be configured', v_deal.status;
  END IF;

  -- a party already on a generated document is not removable from the deal
  IF EXISTS (
    SELECT 1 FROM document_parties dp
      JOIN documents d ON d.id = dp.document_id AND d.deleted_at IS NULL
     WHERE d.contract_id = v_deal.contract_id
       AND dp.contact_id = p_contact_id AND dp.party_role = p_party_role
  ) THEN
    RAISE EXCEPTION 'this person is a party on a document in this deal — remove them there first';
  END IF;

  DELETE FROM contract_parties
   WHERE contract_id = v_deal.contract_id
     AND contact_id = p_contact_id AND party_role = p_party_role;
END;
$$;


--
-- Name: remove_document_co_buyer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_document_co_buyer(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc documents%ROWTYPE;
  r record;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN; END IF;

  FOR r IN
    SELECT contact_id FROM (
      SELECT dp.contact_id,
             row_number() OVER (ORDER BY dp.signer_order NULLS LAST, dp.id) AS rn
        FROM document_parties dp
       WHERE dp.document_id = p_document_id AND dp.party_role = 'BUYER'
    ) t WHERE t.rn > 1
  LOOP
    DELETE FROM document_parties
     WHERE document_id = p_document_id AND contact_id = r.contact_id AND party_role = 'BUYER';
    -- drop the contract-grain row only when no other document under this
    -- contract still names this contact as a BUYER party
    IF NOT EXISTS (
      SELECT 1 FROM document_parties dp
        JOIN documents d ON d.id = dp.document_id
       WHERE d.contract_id = v_doc.contract_id AND d.deleted_at IS NULL
         AND dp.contact_id = r.contact_id AND dp.party_role = 'BUYER'
    ) THEN
      DELETE FROM contract_parties
       WHERE contract_id = v_doc.contract_id AND contact_id = r.contact_id AND party_role = 'BUYER';
    END IF;
  END LOOP;

  -- clear the co-buyer's namespace values (defs stay; values go)
  UPDATE contract_fields SET value = NULL, updated_at = now()
   WHERE document_id = p_document_id AND field_key LIKE 'COBUYER.%'
     AND coalesce(btrim(value), '') <> '';

  PERFORM assert_not_signature_locked(p_document_id);
  PERFORM remerge_contract_from_clauses(p_document_id);
END;
$$;


--
-- Name: remove_form_field(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_form_field(p_form_key text, p_field_key text, p_from_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_base record; v_new jsonb;
begin
  if not is_admin() then raise exception 'admin only'; end if;
  select * into v_base from _form_edit_base(p_form_key, p_from_version);
  if v_base.schema is null then
    raise exception 'unknown form % (version %)', p_form_key, p_from_version;
  end if;
  if not exists (select 1 from jsonb_array_elements(v_base.schema->'sections') s,
                              jsonb_array_elements(s->'fields') f where f->>'key' = p_field_key)
  then raise exception 'no field % on form %', p_field_key, p_form_key; end if;

  select jsonb_build_object('sections', jsonb_agg(sec order by sec_i)) into v_new
    from (
      select sec_i, jsonb_set(s, '{fields}',
               coalesce((select jsonb_agg(f order by f_i)
                           from jsonb_array_elements(s->'fields') with ordinality as t(f, f_i)
                          where f->>'key' <> p_field_key), '[]'::jsonb)) as sec
        from jsonb_array_elements(v_base.schema->'sections') with ordinality as q(s, sec_i)
    ) x;

  return save_form_definition_version(
    p_form_key, v_base.title, v_base.audience, v_base.purpose, v_new, p_from_version);
end;
$$;


--
-- Name: remove_from_my_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_from_my_purchase(p_item_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_contact uuid := current_contact_id();
  v_pu      purchases%ROWTYPE;
  v_live    integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT p.* INTO v_pu FROM purchase_items pi
    JOIN purchases p ON p.id = pi.purchase_id AND p.deleted_at IS NULL
   WHERE pi.id = p_item_id AND pi.voided_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'that item is not on an order you can change'; END IF;
  IF NOT (v_pu.buyer_user_id = v_uid
          OR (v_contact IS NOT NULL AND v_pu.buyer_contact_id = v_contact)) THEN
    RAISE EXCEPTION 'that order is not yours';
  END IF;
  IF coalesce(v_pu.status, '') <> 'draft' THEN
    RAISE EXCEPTION 'that order can no longer be changed here';
  END IF;

  SELECT count(*) INTO v_live FROM purchase_items
   WHERE purchase_id = v_pu.id AND voided_at IS NULL;
  -- ⚠️ NOT THE LAST ONE. `_recompute_purchase_total` VOIDS the order when its last
  -- live line goes, and an order that voids itself underneath somebody who is
  -- mid-flow is a dead end, not an edit. Adding first, then removing, works.
  IF v_live <= 1 THEN
    RAISE EXCEPTION 'an order needs at least one item — add what you want first, then remove this';
  END IF;

  UPDATE purchase_items
     SET voided_at = now(), voided_by = v_uid, void_reason = 'removed by the client during onboarding'
   WHERE id = p_item_id AND voided_at IS NULL;

  PERFORM _recompute_purchase_total(v_pu.id);
  RETURN v_live - 1;
END;
$$;


--
-- Name: remove_lease_participant(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_lease_participant(p_document_id uuid, p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM lease_edit_guard(p_document_id);
  DELETE FROM lease_participants WHERE document_id = p_document_id AND contact_id = p_contact_id;
  DELETE FROM document_parties WHERE document_id = p_document_id AND contact_id = p_contact_id AND party_role = 'PARTICIPANT';
END;
$$;


--
-- Name: remove_lease_payment_option(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_lease_payment_option(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid;
BEGIN
  SELECT document_id INTO v_doc FROM lease_payment_options WHERE id = p_id;
  IF v_doc IS NULL THEN RETURN; END IF;
  PERFORM lease_edit_guard(v_doc);
  DELETE FROM lease_payment_options WHERE id = p_id;
END;
$$;


--
-- Name: remove_my_signature(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_my_signature(p_document_id uuid, p_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me     uuid := current_contact_id();
  v_target uuid;
  v_org    uuid;
  v_title  text;
  v_roles  text[];
  v_n      int := 0;
  s        record;
  r        record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, coalesce(title, 'A document') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;

  -- staff may remove on a party's behalf (they sign from the barn office);
  -- everyone else may only remove their own.
  v_target := coalesce(p_contact_id, v_me);
  IF v_target IS DISTINCT FROM v_me AND NOT has_staff_access() THEN
    RAISE EXCEPTION 'you can only remove your own signature';
  END IF;

  v_roles := ARRAY[]::text[];

  FOR s IN
    SELECT * FROM signatures
     WHERE document_id = p_document_id AND signer_contact_id = v_target
       AND signed_at IS NOT NULL AND deleted_at IS NULL
  LOOP
    -- 1. ARCHIVE the attested state. This is the evidence, and it is permanent.
    INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value, ip, user_agent)
    VALUES (auth.uid(), 'DELETE', 'signatures', s.id,
            jsonb_build_object(
              'reason', 'signature_withdrawn_by_party',
              'document_id', s.document_id,
              'signer_contact_id', s.signer_contact_id,
              'party_role', s.party_role,
              'typed_name', s.typed_name,
              'signed_at', s.signed_at,
              'method', s.method),
            jsonb_build_object('withdrawn_at', now(), 'withdrawn_by_contact_id', v_me),
            s.ip_address, s.user_agent);

    -- 2. FREE the slot. The unique key spans soft-deleted rows, so the row must
    --    go for the party to be able to sign again. Its content now lives in
    --    audit_logs, and the withdrawal is logged on the document below.
    DELETE FROM signatures WHERE id = s.id;

    v_roles := v_roles || s.party_role;
    v_n := v_n + 1;
  END LOOP;

  IF v_n = 0 THEN
    RETURN jsonb_build_object('removed', 0, 'message', 'no standing signature to remove');
  END IF;

  -- 3. REISSUE a pending row per role, so the signing surface has something to
  --    render and the party can sign again once they have reviewed the changes.
  INSERT INTO signatures (org_id, document_id, signer_contact_id, party_role, method)
  SELECT v_org, p_document_id, v_target, role_key, 'TYPED'
    FROM unnest(v_roles) AS role_key
  ON CONFLICT (document_id, signer_contact_id, party_role) DO NOTHING;

  UPDATE documents
     SET signatures_voided_at = now(),
         signatures_voided_roles = coalesce(signatures_voided_roles, '{}') || v_roles,
         -- A withdrawn signature REGRESSES the instrument: an EXECUTED document
         -- with a missing signature is a false state (2026-08-03 e2e finding —
         -- the old CASE kept EXECUTED as-is, so a fully-executed lease still
         -- read as executed after a party withdrew).
         status = 'AWAITING_SIGNATURE',
         -- locked or executed, the document returns to editable — withdrawing
         -- in order to edit is the entire point of L9's withdraw path
         workflow_state = CASE WHEN workflow_state IN ('locked','executed') THEN 'editable' ELSE workflow_state END
   WHERE id = p_document_id;

  PERFORM log_contract_change(p_document_id, 'signature_removed', NULL,
                              'Signature removed', NULL, NULL, NULL,
                              jsonb_build_object('roles', to_jsonb(v_roles),
                                                 'by_contact_id', v_me,
                                                 -- the WITHDRAWN party — the anchor
                                                 -- document_changes_since_signature needs
                                                 -- when staff withdraw on a party's behalf
                                                 'for_contact_id', v_target));

  FOR r IN
    SELECT DISTINCT pr.user_id FROM document_parties dp
      JOIN profiles pr ON pr.contact_id = dp.contact_id
     WHERE dp.document_id = p_document_id AND dp.contact_id <> v_target
       AND pr.user_id IS NOT NULL
  LOOP
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_org, r.user_id, 'signature_removed',
              v_title || ' — a signature was removed, so it can be edited again',
              '/app/contracts/' || p_document_id::text);
  END LOOP;
  -- The company party has no linked account by design — its withdrawal
  -- notice goes to the staff inbox instead (2026-08-03 e2e finding: a
  -- lessee's withdrawal on a company-side lease notified no one).
  IF EXISTS (SELECT 1 FROM document_parties dp JOIN contacts cc ON cc.id = dp.contact_id
              WHERE dp.document_id = p_document_id AND dp.contact_id <> v_target AND cc.is_company)
  THEN
    PERFORM notify_staff(v_org, 'signature_removed',
              v_title || ' — a signature was removed, so it can be edited again',
              '/app/ops/documents/' || p_document_id::text);
  END IF;

  RETURN jsonb_build_object('removed', v_n, 'roles', to_jsonb(v_roles));
END;
$$;


--
-- Name: rename_contract_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_contract_note(p_note_id uuid, p_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_title text := nullif(trim(coalesce(p_title,'')),'');
BEGIN
  IF v_title IS NULL THEN RAISE EXCEPTION 'a note needs a title'; END IF;
  UPDATE contract_notes SET title = v_title, updated_at = now()
   WHERE id = p_note_id AND deleted_at IS NULL
     AND (has_staff_access() OR created_by_contact_id = current_contact_id());
  IF NOT FOUND THEN RAISE EXCEPTION 'note not found, or not yours to rename'; END IF;
END
$$;


--
-- Name: reopen_change_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_change_request(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT agree_change_request(p_request_id, false); $$;


--
-- Name: FUNCTION reopen_change_request(p_request_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reopen_change_request(p_request_id uuid) IS 'Either party reopens a resolved request. Records who + when, clears the close, and returns the request to the open set — which contract_lock_blockers counts, so locking is blocked again.';


--
-- Name: reopen_deal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_deal(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to reopen a deal'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;
  IF v_deal.status <> 'complete' THEN
    RETURN jsonb_build_object('reopened', false, 'message', 'this deal is not complete');
  END IF;

  UPDATE deals SET status = 'pending', completed_at = NULL WHERE id = p_deal_id;
  UPDATE contracts SET status = 'draft' WHERE id = v_deal.contract_id;

  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (auth.uid(), 'UPDATE', 'deals', p_deal_id,
          jsonb_build_object('status', 'complete', 'completed_at', v_deal.completed_at),
          jsonb_build_object('status', 'pending', 'reason', 'reopened_by_staff'));

  -- completion is DERIVED: if every document is still signed, this deal already
  -- satisfies its requirements again and the next execution event will settle
  -- it. Say so, rather than implying it will stay open.
  RETURN jsonb_build_object(
    'reopened', true,
    'still_satisfied', (deal_completion_state(p_deal_id) ->> 'can_complete')::boolean,
    'message', CASE WHEN (deal_completion_state(p_deal_id) ->> 'can_complete')::boolean
      THEN 'Reopened, but every requirement is still met — void or reopen a document to keep this deal open.'
      ELSE 'Reopened.' END);
END;
$$;


--
-- Name: reopen_horse_section(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_horse_section(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc documents%ROWTYPE;
  v_is_staff boolean;
  v_is_lessor boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;
  IF v_doc.workflow_state NOT IN ('editable','editing') THEN
    RAISE EXCEPTION 'document is % — the horse section cannot be reopened', v_doc.workflow_state;
  END IF;

  v_is_staff  := coalesce(has_staff_access() AND v_doc.org_id = current_org(), false);
  v_is_lessor := EXISTS (SELECT 1 FROM caller_party_roles(p_document_id) r WHERE r = 'LESSOR');
  IF NOT (v_is_staff OR v_is_lessor) THEN
    RAISE EXCEPTION 'only the Lessor (or staff) may reopen the horse section';
  END IF;

  UPDATE documents
     SET horse_section_confirmed_at = NULL,
         horse_section_confirmed_by = NULL
   WHERE id = p_document_id;
END;
$$;


--
-- Name: reply_to_change_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reply_to_change_request(p_request_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc uuid; v_org uuid; v_sub timestamptz; v_parent uuid;
  v_state text; v_cid uuid; v_role text; v_label text; v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'a reply body is required'; END IF;

  SELECT document_id, org_id, submitted_at, parent_request_id
    INTO v_doc, v_org, v_sub, v_parent
    FROM contract_change_requests WHERE id = p_request_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown change request'; END IF;
  IF v_parent IS NOT NULL THEN RAISE EXCEPTION 'reply on the thread''s first entry'; END IF;
  IF v_sub IS NULL THEN RAISE EXCEPTION 'this request has not been submitted for review yet'; END IF;

  SELECT workflow_state INTO v_state FROM documents WHERE id = v_doc AND deleted_at IS NULL;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  SELECT contact_id, role, label INTO v_cid, v_role, v_label FROM comment_author_identity(v_doc);

  INSERT INTO contract_change_requests (
    org_id, document_id, parent_request_id, anchor_kind, body,
    author_contact_id, author_role, author_label, submitted_at)
  VALUES (v_org, v_doc, p_request_id, 'document', trim(p_body),
          v_cid, v_role, v_label, now())
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id);
END;
$$;


--
-- Name: report_my_payment(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_my_payment(p_purchase_id uuid, p_method text, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur     purchases%ROWTYPE;
  v_contact uuid := current_contact_id();
  v_method  text := lower(btrim(coalesce(p_method, '')));
  v_ref     text := nullif(btrim(coalesce(p_reference, '')), '');
  v_label   text;
  v_who     text;
  v_opened  boolean := false;
  v_pay     uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF v_method NOT IN ('zelle', 'cash') THEN
    RAISE EXCEPTION 'a payment report is zelle or cash';
  END IF;

  SELECT * INTO v_pur FROM purchases
   WHERE id = p_purchase_id AND deleted_at IS NULL
     AND (buyer_user_id = auth.uid() OR (v_contact IS NOT NULL AND buyer_contact_id = v_contact));
  IF NOT FOUND THEN RAISE EXCEPTION 'order not found'; END IF;

  IF coalesce(v_pur.payment_status, '') = 'paid' THEN
    RETURN jsonb_build_object('recorded', false, 'reason', 'already paid');
  END IF;

  UPDATE purchases
     SET client_reported_method       = v_method,
         client_reported_reference    = coalesce(v_ref, client_reported_reference),
         client_reported_at           = now(),
         payment_method                = v_method,
         client_claim_status           = 'pending',
         client_claim_resolved_by      = NULL,
         client_claim_resolved_at      = NULL,
         client_claim_decline_reason   = NULL
   WHERE id = p_purchase_id;

  -- ⚠️ LIFECYCLE — `pending` IS ENTERED BY THE CLIENT, NOT BY STAFF.
  -- Owner: the booking is `pending` once *"the client declares a payment
  -- method on an unpaid order"*. This is that declaration. It moves the
  -- sessions this order pays for out of `requested`/`approved` and into
  -- `pending` — where they stay VISIBLE and BOOKABLE (D23/D24: a pending
  -- month never blocks anyone) until staff confirm the money arrived.
  UPDATE bookings SET status = 'pending', updated_at = now()
   WHERE purchase_id = p_purchase_id AND status IN ('requested','approved');

  -- CR-76b: the declaration IS the payment entry. Its number is what the client
  -- sees on My Payments, and it is minted here — at the input, not at settlement.
  v_pay := _payment_open(p_purchase_id, v_method, v_ref, auth.uid(), false);

  IF coalesce(v_pur.status, '') = 'draft' THEN
    PERFORM finalize_purchase_payment(p_purchase_id, v_method);
    v_opened := true;
  END IF;

  SELECT string_agg(pi.label, ', ' ORDER BY pi.created_at) INTO v_label
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id;
  v_label := coalesce(nullif(btrim(v_label), ''), 'Order');

  SELECT nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), '')
    INTO v_who FROM contacts c WHERE c.id = v_pur.buyer_contact_id;
  v_who := coalesce(v_who, 'The buyer');

  PERFORM log_status_event(
    'order', p_purchase_id, 'payment_reported',
    CASE WHEN v_method = 'cash'
         THEN 'Client says they are paying cash'
         ELSE 'Client says they sent the Zelle payment'
              || coalesce(' — confirmation ' || v_ref, ' — no confirmation number given')
    END,
    v_pur.org_id);

  PERFORM notify_staff(v_pur.org_id, 'payment_reported',
    v_who || ' says they paid ' || v_label
      || CASE WHEN v_method = 'cash' THEN ' in cash' ELSE ' by Zelle' END
      || coalesce(' (ref ' || v_ref || ')', '')
      || ' — not yet confirmed',
    '/app/ops/payments/review');

  RETURN jsonb_build_object('recorded', true, 'method', v_method, 'reference', v_ref,
                            'payment_id', v_pay,
                            'order_opened', v_opened);
END;
$$;


--
-- Name: FUNCTION report_my_payment(p_purchase_id uuid, p_method text, p_reference text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_my_payment(p_purchase_id uuid, p_method text, p_reference text) IS 'ONBOARD §6 + CASHCONFIRM: the buyer''s own statement that they have paid (Zelle, optional confirmation number) or will pay cash. Records a claim on the status trail, opens client_claim_status=pending for the staff queue, and alerts staff. NEVER sets payment_status — only staff confirmation (via mark_purchase_paid) does.';


--
-- Name: report_order_incorrect(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_order_incorrect(p_purchase_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v purchases%ROWTYPE;
  v_me   uuid := current_contact_id();
  v_who  text;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_sent integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT * INTO v FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF v.id IS NULL THEN RAISE EXCEPTION 'order not found'; END IF;
  -- Their OWN order only. A client may flag what they were shown, nothing else.
  IF NOT (v.buyer_user_id = auth.uid() OR (v_me IS NOT NULL AND v.buyer_contact_id = v_me)) THEN
    RAISE EXCEPTION 'that is not your order';
  END IF;

  SELECT coalesce(nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''), c.email)
    INTO v_who FROM contacts c WHERE c.id = coalesce(v.buyer_contact_id, v_me);

  -- The durable record, on the order's own timeline: staff see it wherever they
  -- open the order, not only in a notification that can be dismissed.
  PERFORM log_status_event('order', p_purchase_id, 'client_flagged',
    coalesce(v_who, 'The client') || ' says this order is not correct'
      || coalesce(' — ' || v_note, ''), v.org_id);

  PERFORM notify_staff(v.org_id, 'order_flagged',
    coalesce(v_who, 'A client') || ' says order '
      || coalesce(v.display_code, '') || ' is not correct',
    '/app/ops/intake');

  -- How many humans this actually reached. `notify_staff` writes one row per
  -- staff recipient; counting them is the difference between "we told someone"
  -- and "we called a function".
  SELECT count(*) INTO v_sent
    FROM notifications n
   WHERE n.org_id = v.org_id
     AND n.created_at > now() - interval '10 seconds'
     AND n.link = '/app/ops/intake';

  RETURN jsonb_build_object('recipients', coalesce(v_sent, 0), 'logged', true);
END;
$$;


--
-- Name: request_booking_change(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_booking_change(p_booking_id uuid, p_kind text, p_new_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_new_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scope text DEFAULT 'one'::text, p_note text DEFAULT NULL::text, p_fee_method text DEFAULT NULL::text, p_fee_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client uuid := current_client_id();
  v_b      bookings%ROWTYPE;
  v_fee    numeric;
  v_phone  boolean;
  v_id     uuid;
  v_recurring boolean;
  v_method text := nullif(lower(btrim(coalesce(p_fee_method, ''))), '');
  v_ref    text := nullif(btrim(coalesce(p_fee_reference, '')), '');
BEGIN
  IF p_kind NOT IN ('reschedule','cancel','defer') THEN RAISE EXCEPTION 'bad change kind'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;
  IF NOT coalesce(has_staff_access() OR (v_client IS NOT NULL AND v_b.client_id = v_client), false) THEN
    RAISE EXCEPTION 'not your booking';
  END IF;
  IF p_kind = 'reschedule' AND (p_new_start IS NULL OR p_new_end IS NULL) THEN
    RAISE EXCEPTION 'a reschedule needs a new time';
  END IF;

  -- BOOKLINK B4: monthly lessons don't carry over — a reschedule request
  -- that would push the lesson into a different calendar month is refused.
  IF p_kind = 'reschedule' AND v_b.purchase_id IS NOT NULL THEN
    SELECT true INTO v_recurring
      FROM purchase_items pi JOIN offerings o ON o.id = pi.offering_id
     WHERE pi.purchase_id = v_b.purchase_id AND o.config_kind = 'recurring' LIMIT 1;
    IF coalesce(v_recurring, false)
       AND date_trunc('month', p_new_start) <> date_trunc('month', v_b.starts_at) THEN
      RAISE EXCEPTION 'monthly lessons must be used within the same month — no carryover to next month';
    END IF;
  END IF;

  v_fee   := CASE WHEN p_kind = 'reschedule' THEN reschedule_fee(v_b.org_id, v_b.starts_at) ELSE 0 END;
  v_phone := v_b.starts_at - now() < interval '24 hours';

  -- ONBOARD §7 — the fee gate. A chargeable change is not accepted until the
  -- client has said how they are settling it. Staff are exempt: they are acting
  -- on the client's behalf and can waive at decision time.
  IF coalesce(v_fee, 0) > 0 AND NOT has_staff_access() THEN
    IF v_method IS NULL OR v_method NOT IN ('zelle','cash') THEN
      RAISE EXCEPTION 'FEE_CONFIRMATION_REQUIRED: a % fee applies to this change', v_fee
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  INSERT INTO booking_change_requests (
    org_id, booking_id, requested_by, request_kind,
    proposed_starts_at, proposed_ends_at, scope, status,
    fee_amount, phone_required, note,
    fee_reported_method, fee_reported_reference, fee_reported_at)
  VALUES (
    v_b.org_id, p_booking_id, auth.uid(), p_kind,
    p_new_start, p_new_end, p_scope, 'pending',
    NULLIF(v_fee,0), v_phone, p_note,
    CASE WHEN coalesce(v_fee,0) > 0 THEN v_method END,
    CASE WHEN coalesce(v_fee,0) > 0 THEN v_ref END,
    CASE WHEN coalesce(v_fee,0) > 0 AND v_method IS NOT NULL THEN now() END)
  RETURNING id INTO v_id;

  -- ⚠️ LIFECYCLE: A RESCHEDULE ENTERS `moved`, AND THAT IS THE HOLD.
  -- Owner: *"a held slot isnt empty and available until the new booking is
  -- approved then the hold is released."* The row stays at its OLD time in
  -- `moved`; `decide_booking_change` applies the delta to this same row on
  -- approval, which releases the old slot by construction. No second row, no
  -- hold table. A cancel/defer ask holds the slot as `pending`, as before.
  UPDATE bookings
     SET status = CASE WHEN p_kind = 'reschedule' THEN 'moved' ELSE 'pending' END,
         updated_at = now()
   WHERE id = p_booking_id AND status IN ('scheduled','confirmed');

  -- staff get an in-app heads-up (email rides the sweep)
  PERFORM notify_staff(v_b.org_id, 'booking_change_requested',
    initcap(p_kind) || ' requested — ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM')
      || CASE WHEN coalesce(v_fee,0) > 0
              THEN ' · ' || fmt_money(v_fee) || ' fee — client says '
                   || CASE WHEN v_method = 'cash' THEN 'they will pay cash'
                           ELSE 'they sent it by Zelle' || coalesce(' (ref ' || v_ref || ')', '') END
                   || ', not yet confirmed'
              ELSE '' END,
    '/app/calendar');

  RETURN jsonb_build_object(
    'change_id', v_id, 'fee_amount', NULLIF(v_fee,0), 'phone_required', v_phone,
    'kind', p_kind, 'fee_method', CASE WHEN coalesce(v_fee,0) > 0 THEN v_method END);
END;
$$;


--
-- Name: request_category_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_category_label(p_category text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_category
    WHEN 'general'     THEN 'General question'
    WHEN 'lessons'     THEN 'Riding lessons'
    WHEN 'horse_care'  THEN 'Horse care'
    WHEN 'acquisition' THEN 'Leasing & purchasing'
    WHEN 'media'       THEN 'Media / press'
    WHEN 'partnership' THEN 'Partnership / sponsorship'
    WHEN 'gift'        THEN 'Gift enquiry'
    WHEN 'visit'       THEN 'Visit the ranch'
    ELSE coalesce(p_category, 'Uncategorised')
  END;
$$;


--
-- Name: request_contract_termination(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_contract_termination(p_document_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_title text; v_state text; v_me uuid := current_contact_id();
  v_staff boolean := has_staff_access(); r record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, title, workflow_state INTO v_org, v_title, v_state
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT ((coalesce(v_staff AND v_org = current_org(), false))
          OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = p_document_id AND dp.contact_id = v_me)) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF v_state <> 'executed' THEN RAISE EXCEPTION 'only an executed contract can be terminated'; END IF;
  IF EXISTS (SELECT 1 FROM documents WHERE id = p_document_id AND termination_requested_at IS NOT NULL) THEN
    RAISE EXCEPTION 'a termination request is already pending';
  END IF;

  UPDATE documents SET termination_requested_at = now(), termination_requested_by = v_me,
         termination_request_reason = nullif(btrim(coalesce(p_reason,'')),''), updated_at = now()
   WHERE id = p_document_id;

  -- notify the party/parties whose agreement is needed. When a party requests,
  -- that's the other party; when staff requests (no party role of their own),
  -- every party is asked to agree.
  FOR r IN
    SELECT DISTINCT pr.user_id FROM document_parties dp
      JOIN profiles pr ON pr.contact_id = dp.contact_id
     WHERE dp.document_id = p_document_id
       AND pr.user_id IS NOT NULL
       AND (v_staff OR dp.contact_id IS DISTINCT FROM v_me)
  LOOP
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
    VALUES (v_org, r.user_id, 'contract_termination_requested',
            coalesce(v_title,'A contract') || ' — termination requested',
            CASE WHEN v_staff THEN 'The barn has requested to terminate this contract. Please review and agree or decline.'
                 ELSE 'The other party has requested to terminate this contract. Please review and approve or decline.' END,
            '/app/contracts/' || p_document_id::text);
  END LOOP;
  PERFORM notify_staff(v_org, 'contract_termination_requested',
    coalesce(v_title,'A contract') || ' — termination requested', '/app/ops/documents');
END;
$$;


--
-- Name: request_document_change(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_document_change(p_document_id uuid, p_field_key text, p_target_section text, p_requested_change text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_title text; v_orig uuid;
  v_cid uuid; v_role text; v_label text; v_next int; v_id uuid; v_section text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF coalesce(trim(p_requested_change), '') = '' THEN
    RAISE EXCEPTION 'a requested change is required';
  END IF;

  SELECT org_id, workflow_state, coalesce(title,'A contract'), originator_contact_id
    INTO v_org, v_state, v_title, v_orig
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not authorized to request changes on document %', p_document_id;
  END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  v_section := coalesce(nullif(trim(p_target_section),''), nullif(trim(p_field_key),''));
  SELECT contact_id, role, label INTO v_cid, v_role, v_label
    FROM comment_author_identity(p_document_id);
  SELECT coalesce(max(annotation_number),0) + 1 INTO v_next
    FROM contract_change_requests WHERE document_id = p_document_id;

  INSERT INTO contract_change_requests (
    org_id, document_id, parent_request_id, anchor_kind, anchor_ref, target_section,
    annotation_number, submitted_at, body, author_contact_id, author_role, author_label,
    impact_rank)
  VALUES (
    v_org, p_document_id, NULL,
    CASE WHEN nullif(trim(p_field_key),'') IS NOT NULL THEN 'field' ELSE 'document' END,
    nullif(trim(p_field_key),''), v_section,
    v_next, now(), trim(p_requested_change), v_cid, v_role, v_label,
    change_request_impact_rank(v_section))
  RETURNING id INTO v_id;

  PERFORM contract_notify(p_document_id, v_orig, 'contract_change_requested',
    'Change requested on ' || v_title,
    'Change #' || v_next || ': ' || trim(p_requested_change));

  RETURN jsonb_build_object(
    'id', v_id, 'document_id', p_document_id, 'annotation_number', v_next,
    'target_field_key', nullif(trim(p_field_key),''), 'target_section', v_section,
    'requested_change', trim(p_requested_change), 'status', 'open');
END;
$$;


--
-- Name: FUNCTION request_document_change(p_document_id uuid, p_field_key text, p_target_section text, p_requested_change text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_document_change(p_document_id uuid, p_field_key text, p_target_section text, p_requested_change text) IS 'A party (or staff) logs a change request against a field or a free section; auto-assigns the next per-document annotation_number and snapshots the current field value; notifies the originator (kind ''contract_change_requested''). Returns the request as jsonb.';


--
-- Name: request_documents_from_contact(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_documents_from_contact(p_contact_id uuid, p_template_keys text[], p_disposition text DEFAULT 'WHEN_READY'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_user uuid; v_email text; v_first text;
  v_titles text[]; v_n int; v_unknown text[]; v_note uuid;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF p_disposition NOT IN ('AT_LOGIN','WITH_CONTRACT','WHEN_READY') THEN
    RAISE EXCEPTION 'unknown disposition %', p_disposition;
  END IF;

  SELECT c.org_id, c.email, nullif(btrim(coalesce(c.first_name,'')),'')
    INTO v_org, v_email, v_first
    FROM contacts c WHERE c.id = p_contact_id AND c.deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact % not found', p_contact_id; END IF;

  -- An obligation nobody can satisfy is worse than no obligation.
  SELECT array_agg(k) INTO v_unknown
    FROM unnest(coalesce(p_template_keys, ARRAY[]::text[])) k
   WHERE btrim(k) <> ''
     AND NOT EXISTS (SELECT 1 FROM contract_templates ct
                      WHERE ct.template_key = k AND ct.active AND ct.deleted_at IS NULL);
  IF v_unknown IS NOT NULL THEN
    RAISE EXCEPTION 'no active template for %  — nothing was asked for',
      array_to_string(v_unknown, ', ');
  END IF;

  INSERT INTO contact_required_documents (contact_id, template_key, org_id, disposition)
  SELECT p_contact_id, k, v_org, p_disposition
    FROM unnest(coalesce(p_template_keys, ARRAY[]::text[])) k
   WHERE btrim(k) <> ''
  ON CONFLICT (contact_id, template_key) DO UPDATE
    SET disposition = EXCLUDED.disposition, skipped_at = NULL, skipped_by = NULL;

  SELECT array_agg(DISTINCT coalesce(ct.title, k)), count(DISTINCT k)
    INTO v_titles, v_n
    FROM unnest(coalesce(p_template_keys, ARRAY[]::text[])) k
    LEFT JOIN contract_templates ct ON ct.template_key = k AND ct.active AND ct.deleted_at IS NULL
   WHERE btrim(k) <> '';

  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = p_contact_id;
  IF v_user IS NOT NULL AND coalesce(v_n, 0) > 0 THEN
    v_note := notify_user(v_user, 'documents_requested',
      CASE WHEN v_n = 1 THEN 'A document needs your signature'
           ELSE v_n || ' documents need your signature' END,
      array_to_string(v_titles, ', '), '/app/onboarding');
  END IF;

  RETURN jsonb_build_object(
    'count', coalesce(v_n, 0),
    'titles', to_jsonb(coalesce(v_titles, ARRAY[]::text[])),
    'email', v_email, 'first_name', v_first, 'org_id', v_org,
    -- The endpoint stamps this once the email is away, so the daily digest can
    -- never send a second copy of something already delivered.
    'notification_id', v_note,
    'has_account', v_user IS NOT NULL, 'disposition', p_disposition);
END;
$$;


--
-- Name: request_horse_intake(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_horse_intake(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b    bookings%ROWTYPE;
  v_when text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found in this org'; END IF;
  IF v_b.kind NOT IN ('lesson','care') THEN RAISE EXCEPTION 'only a lesson or care booking takes a horse'; END IF;
  IF v_b.account_user_id IS NULL THEN RAISE EXCEPTION 'this booking has no client account to notify'; END IF;

  v_when := to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM');
  PERFORM notify_user(
    v_b.account_user_id,
    'horse_intake_request',
    'Tell us about your horse',
    'For your session on ' || coalesce(v_when, 'the calendar')
      || ', add your horse''s details so we''re ready for you. It only takes a minute.',
    '/app/horse-intake?booking=' || p_booking_id::text
  );
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: request_onboarding_categories(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_onboarding_categories(p_request_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_include_held boolean DEFAULT true) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_contact uuid;
  v_cats    text[];
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role'
          OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'not authorized to read request categories';
  END IF;

  SELECT r.org_id, coalesce(p_contact_id, r.contact_id)
    INTO v_org, v_contact
    FROM requests r WHERE r.id = p_request_id;
  IF v_org IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  SELECT coalesce(array_agg(DISTINCT c ORDER BY c), ARRAY[]::text[]) INTO v_cats
  FROM (
    -- the cart
    SELECT sc.onboarding_category AS c
      FROM request_selections rs
      JOIN offerings o
        ON o.org_id = v_org
       AND (o.id = rs.offering_id
            OR (rs.offering_id IS NULL
                AND (o.slug = rs.offering_slug OR o.id::text = rs.offering_slug)))
      JOIN segment_categories sc ON sc.org_id = v_org AND sc.segment = o.segment
     WHERE rs.request_id = p_request_id
       AND rs.state NOT IN ('declined','withdrawn','not_a_booking')

    UNION

    -- what this person already holds: every requirement of the category is on
    -- file. Never narrows; only ever keeps what apply_category_documents would
    -- otherwise delete.
    SELECT cdr.category
      FROM (SELECT DISTINCT category FROM category_document_requirements
             WHERE org_id = v_org) cdr
     WHERE p_include_held AND v_contact IS NOT NULL
       AND EXISTS (SELECT 1 FROM category_document_requirements x
                    WHERE x.org_id = v_org AND x.category = cdr.category)
       AND NOT EXISTS (
             SELECT 1 FROM category_document_requirements x
              WHERE x.org_id = v_org AND x.category = cdr.category
                AND NOT EXISTS (
                      SELECT 1 FROM contact_required_documents crd
                       WHERE crd.contact_id = v_contact
                         AND crd.template_key = x.template_key))

    UNION

    -- and what their standing affiliation says, once documents are executed
    SELECT CASE g.group_type WHEN 'RIDER' THEN 'Rider'
                             WHEN 'HORSE_OWNER' THEN 'Horse owner' END
      FROM groups g
     WHERE p_include_held AND v_contact IS NOT NULL
       AND g.contact_id = v_contact AND g.group_type IN ('RIDER','HORSE_OWNER')
  ) s
  WHERE c IS NOT NULL;

  RETURN v_cats;
END;
$$;


--
-- Name: FUNCTION request_onboarding_categories(p_request_id uuid, p_contact_id uuid, p_include_held boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_onboarding_categories(p_request_id uuid, p_contact_id uuid, p_include_held boolean) IS 'TASK-CATEGORISE §2: the onboarding categories an inquiry implies — the cart''s categories UNION the ones the contact already holds, so a derived default can only ever ADD documents. Staff override it; it never overrides staff.';


--
-- Name: request_open_time(timestamp with time zone, timestamp with time zone, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_open_time(p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_offering_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client uuid := current_client_id();
  v_org    uuid := current_org();
  v_contact uuid := current_contact_id();
  v_kind   text := 'lesson';
  v_id     uuid;
BEGIN
  IF v_client IS NULL THEN RAISE EXCEPTION 'no member profile'; END IF;
  IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'pick a start and a later end';
  END IF;
  IF p_starts_at < now() THEN RAISE EXCEPTION 'pick a future time'; END IF;

  IF p_offering_id IS NOT NULL THEN
    SELECT CASE WHEN o.segment = 'horse' THEN 'care' ELSE 'lesson' END INTO v_kind
      FROM offerings o WHERE o.id = p_offering_id;
    v_kind := coalesce(v_kind, 'lesson');
  END IF;

  -- a horse can't be double-booked
  IF p_horse_id IS NOT NULL AND horse_time_conflict(v_org, p_horse_id, p_starts_at, p_ends_at, NULL, NULL) THEN
    RAISE EXCEPTION 'that horse is already booked in an overlapping time';
  END IF;

  INSERT INTO bookings (org_id, kind, status, client_id, account_user_id, account_contact_id,
      offering_id, horse_id, starts_at, ends_at, notes)
    VALUES (v_org, v_kind, 'requested', v_client, auth.uid(), v_contact,
            p_offering_id, p_horse_id, p_starts_at, p_ends_at,
            NULLIF(btrim(coalesce(p_note,'')),''))
    RETURNING id INTO v_id;

  -- ⚠️ LIFECYCLE: a credit-holder picking a time IS the owner's `requested`
  -- state — his first of six. It was 'pending', which is the state AFTER a
  -- payment method has been declared, and which is why nobody could tell an
  -- unanswered ask from an unpaid one.
  -- REVIEWQ R2: the companion request row the staff queue reads (see
  -- book_open_slot above — same shape, same reasoning).
  INSERT INTO booking_change_requests (
    org_id, booking_id, requested_by, request_kind,
    proposed_starts_at, proposed_ends_at, note, status)
  VALUES (v_org, v_id, auth.uid(), 'new', p_starts_at, p_ends_at,
          NULLIF(btrim(coalesce(p_note,'')),''), 'pending');

  PERFORM notify_staff(v_org, 'booking_time_requested',
    'A client requested ' || to_char(p_starts_at, 'FMMon FMDD, HH12:MI AM'),
    '/app/calendar');

  RETURN jsonb_build_object('booking_id', v_id, 'status', 'requested');
END;
$$;


--
-- Name: request_orders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_orders(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_out jsonb;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may read an inquiry''s orders';
  END IF;
  SELECT r.org_id INTO v_org FROM requests r WHERE r.id = p_request_id;
  IF v_org IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT coalesce(jsonb_agg(o ORDER BY o->>'created_at'), '[]'::jsonb) INTO v_out
  FROM (
    SELECT jsonb_build_object(
      'id', p.id,
      'display_code', p.display_code,
      'status', p.status,
      'current_status', p.current_status,
      'current_status_label', (SELECT v.display_name FROM status_events_vocab v
                                WHERE v.entity_type = 'order' AND v.code = p.current_status),
      'amount', p.amount,
      'payment_status', p.payment_status,
      'created_at', p.created_at,
      'notes', p.notes,
      'items', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'id', pi.id, 'label', pi.label,
                 'price_amount', pi.price_amount, 'price_unit', pi.price_unit,
                 'quantity', pi.quantity,
                 'offering_id', pi.offering_id,
                 -- §C7: the quantity staff schedule against comes from the
                 -- CATALOG, never from parsing the offering name. Names changed
                 -- on 2026-08-15 and name-parsing broke credit minting three
                 -- separate times; CREDITALIGN settled minting on unit_count.
                 'config_kind', o.config_kind,
                 'weekly_frequency', o.weekly_frequency,
                 'unit_count', o.unit_count,
                 'voided_at', pi.voided_at,
                 'void_reason', pi.void_reason)
               ORDER BY pi.created_at)
          FROM purchase_items pi
          LEFT JOIN offerings o ON o.id = pi.offering_id
         WHERE pi.purchase_id = p.id), '[]'::jsonb)
    ) AS o
    FROM purchases p
    WHERE p.request_id = p_request_id AND p.deleted_at IS NULL
  ) s;

  RETURN v_out;
END;
$$;


--
-- Name: request_permission_to_edit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_permission_to_edit(p_document_id uuid, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_title text; v_me uuid := current_contact_id();
  v_asker text; v_n int := 0; r record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, coalesce(title, 'A document') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'document not found'; END IF;

  SELECT coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''), email, 'Someone')
    INTO v_asker FROM contacts WHERE id = v_me;

  FOR r IN
    SELECT DISTINCT s.signer_contact_id, pr.user_id
      FROM signatures s
      JOIN profiles pr ON pr.contact_id = s.signer_contact_id
     WHERE s.document_id = p_document_id AND s.signed_at IS NOT NULL AND s.deleted_at IS NULL
       AND s.signer_contact_id IS DISTINCT FROM v_me AND pr.user_id IS NOT NULL
  LOOP
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_org, r.user_id, 'edit_permission_requested',
              v_asker || ' asks to edit ' || v_title || ' — remove your signature to allow changes',
              '/app/contracts/' || p_document_id::text);
    v_n := v_n + 1;
  END LOOP;

  PERFORM log_contract_change(p_document_id, 'edit_permission_requested', NULL,
                              'Permission to edit requested', NULL, NULL, NULL,
                              jsonb_build_object('message', p_message, 'notified', v_n));

  RETURN jsonb_build_object('notified', v_n);
END;
$$;


--
-- Name: request_purchase_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_purchase_payment(p_purchase_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid := current_org();
  v_pu    purchases%ROWTYPE;
  v_note  text := nullif(btrim(coalesce(p_note, '')), '');
  v_due   numeric;
  v_label text;
  v_user  uuid;
  v_email text;
  v_key   text;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may request payment';
  END IF;

  SELECT * INTO v_pu FROM purchases
   WHERE id = p_purchase_id AND deleted_at IS NULL AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found in this organization';
  END IF;

  v_due := greatest(coalesce(v_pu.amount, 0) - coalesce(v_pu.amount_paid, 0), 0);
  IF v_pu.status = 'void' THEN
    RAISE EXCEPTION 'that order is void — there is nothing to collect';
  END IF;
  IF coalesce(v_pu.payment_status, '') = 'paid' OR v_due <= 0 THEN
    RAISE EXCEPTION 'that order owes nothing';
  END IF;

  SELECT string_agg(pi.label, ', ' ORDER BY pi.created_at) INTO v_label
    FROM purchase_items pi WHERE pi.purchase_id = p_purchase_id AND pi.voided_at IS NULL;
  v_label := coalesce(nullif(btrim(v_label), ''), 'Your order');

  SELECT pr.user_id, pr.email INTO v_user, v_email
    FROM profiles pr WHERE pr.contact_id = v_pu.buyer_contact_id LIMIT 1;
  IF v_email IS NULL THEN
    SELECT c.email INTO v_email FROM contacts c WHERE c.id = v_pu.buyer_contact_id;
  END IF;

  -- The existing spine raises the buyer + staff "payment due" pair. One notice, not two.
  PERFORM notify_purchase_unpaid(p_purchase_id);

  -- A note from staff rides as its own line so the client sees WHY they are being asked.
  IF v_note IS NOT NULL AND v_user IS NOT NULL THEN
    PERFORM notify_user(v_user, 'purchase_unpaid',
      v_label || ' — a note from us', v_note, '/order/' || p_purchase_id::text);
  END IF;

  PERFORM log_status_event('order', p_purchase_id, 'payment_requested',
    'Payment of ' || fmt_money(v_due) || ' requested'
      || coalesce(' — ' || v_note, ''), v_org);

  -- The key the email half logs its attempt under. Unique per request, because staff
  -- may legitimately ask twice a fortnight apart — this is not a "single and provable"
  -- receipt, it is a repeatable deliberate act.
  v_key := 'payreq:' || p_purchase_id::text || ':' || to_char(now(), 'YYYYMMDD"T"HH24MISSMS');

  RETURN jsonb_build_object(
    'purchase_id',  p_purchase_id,
    'display_code', v_pu.display_code,
    'amount_due',   v_due,
    'label',        v_label,
    'recipient',    v_email,
    'note',         v_note,
    'send_key',     v_key);
END;
$$;


--
-- Name: FUNCTION request_purchase_payment(p_purchase_id uuid, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_purchase_payment(p_purchase_id uuid, p_note text) IS 'TASK-CREDITGRANT: one deliberate staff request for an owed balance. Reuses notify_purchase_unpaid, writes the order timeline, and returns the send key the email half logs under. Not dunning: nothing schedules this.';


--
-- Name: requests_capture_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requests_capture_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_email   text := lower(nullif(trim(coalesce(NEW.contact_email, '')), ''));
BEGIN
  -- No email means nothing to dedupe on and no way to reach them; the request
  -- still stands on its own in the queue.
  IF v_email IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_contact
    FROM contacts
   WHERE lower(email) = v_email AND org_id = NEW.org_id AND deleted_at IS NULL
   ORDER BY created_at
   LIMIT 1;

  IF v_contact IS NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, email, phone, contact_type, notes, contact_channel)
    VALUES (NEW.org_id,
            nullif(trim(coalesce(NEW.contact_first_name, '')), ''),
            nullif(trim(coalesce(NEW.contact_last_name, '')), ''),
            v_email,
            nullif(trim(coalesce(NEW.contact_phone, '')), ''),
            'LEAD',
            'Captured from ' || coalesce(NEW.channel, 'inbound')
              || coalesce(' (' || NEW.category || ')', ''),
            'WEBSITE_FORM')
    RETURNING id INTO v_contact;
  END IF;

  -- ITEM 2, repaired: this trigger is AFTER INSERT, so `NEW.contact_id := ...`
  -- is discarded once the row is already written. Persist explicitly. The
  -- WHERE guard keeps this idempotent and never clobbers an existing link.
  UPDATE requests SET contact_id = v_contact
   WHERE id = NEW.id AND contact_id IS NULL;

  RETURN NEW;
END
$$;


--
-- Name: FUNCTION requests_capture_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.requests_capture_contact() IS 'Every inbound submission becomes a person immediately, flagged LEAD, so there is one record from first touch and the Leads page is a real campaign list. Matches an existing contact on email before creating one, so a returning visitor does not spawn a duplicate. An existing contact is never reclassified — a client who books again stays a client.';


--
-- Name: require_module(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_module(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_module(p_key) THEN
    RAISE EXCEPTION 'module % is not enabled for this organization', p_key
      USING errcode = 'insufficient_privilege';
  END IF;
END;
$$;


--
-- Name: require_resign_from(text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_resign_from(p_template_key text, p_contact_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_n int := 0;
  r   record;
  dr  record;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM contract_templates
                  WHERE template_key = p_template_key AND active AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'no active template with key %', p_template_key;
  END IF;

  -- Only contacts in this org, and only the ones actually named.
  FOR r IN
    SELECT c.id FROM contacts c
     WHERE c.id = ANY(coalesce(p_contact_ids, '{}'::uuid[]))
       AND c.org_id = v_org AND c.deleted_at IS NULL
  LOOP
    -- 1. The obligation must exist.
    INSERT INTO contact_required_documents (contact_id, template_key, org_id)
    VALUES (r.id, p_template_key, v_org)
    ON CONFLICT DO NOTHING;

    -- 2. Supersede the executed copies that would otherwise satisfy it. This is
    --    what actually creates the demand — same mechanism as
    --    staff_assign_documents(). Evidence is retained, not deleted, and
    --    signed_template_version is left exactly as signed.
    --    Only EXECUTED documents are touched: anything mid-negotiation
    --    (AWAITING_SIGNATURE, DRAFT, …) is never written by this path.
    FOR dr IN
      SELECT d.id FROM documents d
      JOIN contract_templates ct ON ct.id = d.template_id
      WHERE d.contact_id = r.id AND d.deleted_at IS NULL
        AND d.status = 'EXECUTED'
        AND coalesce(d.current_status, '') <> 'superseded'
        AND ct.template_key = p_template_key
    LOOP
      UPDATE documents SET current_status = 'superseded' WHERE id = dr.id;
      -- FIX1 §E — THE REASON IS A PARAMETER NOW. It was a single hardcoded
      -- string, "a template version change", which is one reason among several
      -- and was simply untrue for the 2026-08-28 re-issue: that was an
      -- application defect at the front door, not a template edit and emphatically
      -- not a signer error. A superseded legal document that misstates why it was
      -- superseded is worse than one with no note at all. The old string remains
      -- the default, so every existing caller is unchanged.
      PERFORM log_status_event('document', dr.id, 'superseded',
        coalesce(nullif(btrim(coalesce(p_reason, '')), ''),
                 'Re-signature required by staff decision on a template version change'),
        v_org);
    END LOOP;

    -- Count people who genuinely owe the document now, so people_required on the
    -- resolved event is the truth rather than a count of fresh INSERTs.
    IF NOT contact_document_satisfied(r.id, p_template_key) THEN
      v_n := v_n + 1;
    END IF;
  END LOOP;

  RETURN v_n;
END
$$;


--
-- Name: required_documents_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.required_documents_for(p_service_type text) RETURNS SETOF text
    LANGUAGE sql STABLE
    AS $$
  SELECT template_key FROM contract_requirements
  WHERE service_type = p_service_type
  ORDER BY template_key;
$$;


--
-- Name: FUNCTION required_documents_for(p_service_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.required_documents_for(p_service_type text) IS 'Template_keys a purchase of the service requires signed (contract_requirements matrix; SECURITY INVOKER — org-scoped by RLS).';


--
-- Name: required_templates_for_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.required_templates_for_contact(p_contact_id uuid) RETURNS TABLE(template_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT crd.template_key FROM contact_required_documents crd
  WHERE crd.contact_id = p_contact_id
    AND crd.skipped_at IS NULL
    AND crd.disposition <> 'WITH_CONTRACT'
$$;


--
-- Name: reschedule_fee(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_fee(p_org uuid, p_start timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    -- the tightest band that still applies (smallest hours_before that the
    -- remaining time is inside) — i.e. the latest change costs the most
    (SELECT f.fee_amount
       FROM booking_change_fees f
      WHERE f.org_id = p_org AND f.active
        AND p_start - now() < make_interval(hours => f.hours_before)
      ORDER BY f.hours_before ASC
      LIMIT 1),
    -- no schedule entered yet: exactly the behaviour that shipped before
    CASE WHEN p_start - now() < interval '48 hours'
         THEN coalesce((SELECT cs.reschedule_fee FROM calendar_settings cs WHERE cs.org_id = p_org), 0)
         ELSE 0 END)
$$;


--
-- Name: resend_executed_document_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resend_executed_document_email(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT coalesce(has_staff_access() OR EXISTS (
        SELECT 1 FROM document_parties dp
         WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id()), false)
  THEN RAISE EXCEPTION 'not authorized for this document'; END IF;

  UPDATE documents SET executed_email_sent_at = NULL WHERE id = p_document_id;
  RETURN send_executed_document_email(p_document_id);
END;
$$;


--
-- Name: resolve_change_request(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_change_request(p_change_id uuid, p_accept boolean, p_new_value text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc uuid; v_org uuid; v_state text; v_owner text; v_field text;
  v_ann int; v_author uuid; v_res timestamptz; v_parent uuid;
  v_by uuid := current_contact_id(); v_title text; v_status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT document_id, org_id, anchor_ref, annotation_number,
         author_contact_id, resolved_at, parent_request_id
    INTO v_doc, v_org, v_field, v_ann, v_author, v_res, v_parent
    FROM contract_change_requests WHERE id = p_change_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown change request: %', p_change_id; END IF;
  IF v_parent IS NOT NULL THEN RAISE EXCEPTION 'resolve the thread on its first entry'; END IF;
  IF v_res IS NOT NULL THEN RAISE EXCEPTION 'change request % is already resolved', p_change_id; END IF;

  SELECT workflow_state, coalesce(title,'A contract') INTO v_state, v_title
    FROM documents WHERE id = v_doc AND deleted_at IS NULL;

  -- unchanged authority: only staff of the org resolve change requests
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'not authorized to resolve changes on document %', v_doc;
  END IF;

  IF coalesce(p_accept, false) THEN
    IF nullif(p_new_value,'') IS NOT NULL AND nullif(v_field,'') IS NOT NULL THEN
      IF v_state NOT IN ('editable','editing') THEN
        RAISE EXCEPTION 'document is locked (workflow_state=%): cannot apply the change', v_state;
      END IF;
      SELECT owner_role INTO v_owner FROM contract_fields
        WHERE document_id = v_doc AND field_key = v_field;
      IF v_owner IS NULL THEN
        RAISE EXCEPTION 'targeted field % no longer exists', v_field;
      END IF;
      IF v_owner = 'DEAL' OR (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
        UPDATE contract_fields
           SET value = p_new_value, entered_by_contact_id = v_by, entered_at = now()
         WHERE document_id = v_doc AND field_key = v_field;
      ELSE
        RAISE EXCEPTION 'cannot apply a value to a % field via a change request (owner must edit it)', v_owner;
      END IF;
    END IF;
    v_status := 'accepted';
  ELSE
    v_status := 'rejected';
  END IF;

  -- both outcomes CLOSE the thread (it stops blocking the lock)
  UPDATE contract_change_requests
     SET resolved_at = now(), resolved_by_contact_id = v_by,
         agreed_at = CASE WHEN v_status = 'accepted' THEN now() ELSE NULL END,
         agreed_by_contact_id = CASE WHEN v_status = 'accepted' THEN v_by ELSE NULL END,
         updated_at = now()
   WHERE id = p_change_id;

  PERFORM contract_notify(v_doc, v_author, 'contract_change_resolved',
    'Change #' || coalesce(v_ann::text,'?') || ' on ' || v_title || ' was ' || v_status);

  RETURN jsonb_build_object(
    'id', p_change_id, 'document_id', v_doc, 'annotation_number', v_ann,
    'status', v_status, 'resolved_by_contact_id', v_by, 'resolved_at', now());
END;
$$;


--
-- Name: FUNCTION resolve_change_request(p_change_id uuid, p_accept boolean, p_new_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_change_request(p_change_id uuid, p_accept boolean, p_new_value text) IS 'Originator/staff accepts (optionally applying p_new_value to the targeted field — DEAL fields via the originator, personal/horse fields only via staff) or rejects a change request; stamps status/resolved_*; notifies the requester. Returns the resolved request as jsonb.';


--
-- Name: resolve_change_request_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_change_request_thread(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT agree_change_request(p_request_id, true); $$;


--
-- Name: resolve_clause(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_clause(p_addendum_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_proposer uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT document_id, proposed_by_contact_id INTO v_doc, v_proposer FROM contract_addenda WHERE id = p_addendum_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown addendum'; END IF;
  IF NOT caller_may_resolve(v_doc, v_proposer) THEN
    RAISE EXCEPTION 'not authorized to resolve this clause';
  END IF;

  UPDATE contract_addenda
     SET status = CASE WHEN p_accept THEN 'accepted' ELSE 'rejected' END,
         resolved_by_contact_id = current_contact_id(), resolved_at = now()
   WHERE id = p_addendum_id AND status = 'open';
  IF NOT FOUND THEN RAISE EXCEPTION 'that clause is already resolved'; END IF;

  PERFORM rebuild_additional_terms(v_doc);
  RETURN jsonb_build_object('accepted', p_accept);
END;
$$;


--
-- Name: resolve_consumption_billing(tstzrange); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_consumption_billing(p_period tstzrange) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org          uuid := current_org();
  v_default_payer uuid;
  v_ev            record;
  v_alloc         record;
  v_unit_cost     numeric;
  v_amount        numeric;
  v_covered       numeric;
  v_remainder     numeric;
  v_lines         integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  -- Layer B (§4.3): raise cleanly if the caller's tenant lacks the module.
  PERFORM require_module('mod.barnops');

  -- The default/barn payer: the active 'default'-scoped cost_allocation_rules row for
  -- this tenant (seeded by provision_tenant, §9 step 4). Any uncovered event or
  -- share-shortfall routes here so nothing is silently dropped.
  SELECT payer_contact_id INTO v_default_payer
  FROM cost_allocation_rules
  WHERE org_id = v_org
    AND scope = 'default'
    AND deleted_at IS NULL
    AND (effective_from IS NULL OR effective_from <= now()::date)
    AND (effective_to   IS NULL OR effective_to   >= now()::date)
  ORDER BY effective_from DESC NULLS LAST
  LIMIT 1;

  -- Idempotency: clear our own prior UNSETTLED consumption lines for this period so a
  -- re-run re-emits identically. SETTLED lines are sealed (U5 trigger) and preserved.
  DELETE FROM billable_lines
  WHERE org_id = v_org
    AND source_kind = 'consumption'
    AND status = 'OPEN'
    AND period = p_period;

  -- Walk every consumption event in the period, for THIS tenant only.
  FOR v_ev IN
    SELECT ce.id, ce.resource_id, ce.resource_lot_id, ce.horse_id, ce.qty, ce.occurred_at
    FROM consumption_events ce
    WHERE ce.org_id = v_org
      AND ce.deleted_at IS NULL
      AND ce.occurred_at <@ p_period
    ORDER BY ce.occurred_at, ce.id
  LOOP
    -- money is computed HERE (the resolver), never in the dumb event.
    SELECT COALESCE(rl.unit_cost, 0) INTO v_unit_cost
    FROM resource_lots rl
    WHERE rl.id = v_ev.resource_lot_id AND rl.org_id = v_org;
    v_unit_cost := COALESCE(v_unit_cost, 0);
    v_amount    := ROUND(v_ev.qty * v_unit_cost, 2);

    v_covered := 0;

    -- Precedence 1: explicit override on the horse's scope.
    IF v_ev.horse_id IS NOT NULL THEN
      FOR v_alloc IN
        SELECT car.payer_contact_id, car.share_pct
        FROM cost_allocation_rules car
        WHERE car.org_id = v_org
          AND car.scope = 'horse'
          AND car.scope_id = v_ev.horse_id
          AND car.deleted_at IS NULL
          AND (car.effective_from IS NULL OR car.effective_from <= v_ev.occurred_at::date)
          AND (car.effective_to   IS NULL OR car.effective_to   >= v_ev.occurred_at::date)
      LOOP
        INSERT INTO billable_lines
          (org_id, payer_contact_id, source_kind, source_id, horse_id, qty, unit_amount, amount, status, period)
        VALUES
          (v_org, v_alloc.payer_contact_id, 'consumption', v_ev.id, v_ev.horse_id,
           v_ev.qty, v_unit_cost, ROUND(v_amount * v_alloc.share_pct / 100, 2), 'OPEN', p_period);
        v_covered := v_covered + v_alloc.share_pct;
        v_lines := v_lines + 1;
      END LOOP;
    END IF;

    -- Precedence 2: derived from horse_relationships (the single source of truth), only if
    -- no explicit override covered the horse.
    IF v_covered = 0 AND v_ev.horse_id IS NOT NULL THEN
      FOR v_alloc IN
        SELECT hr.party_contact_id AS payer_contact_id, hr.share_pct
        FROM horse_relationships hr
        WHERE hr.org_id = v_org
          AND hr.horse_id = v_ev.horse_id
          AND hr.active
          AND hr.share_pct IS NOT NULL
          AND hr.share_pct > 0
          AND (hr.term_start IS NULL OR hr.term_start <= v_ev.occurred_at::date)
          AND (hr.term_end   IS NULL OR hr.term_end   >= v_ev.occurred_at::date)
      LOOP
        INSERT INTO billable_lines
          (org_id, payer_contact_id, source_kind, source_id, horse_id, qty, unit_amount, amount, status, period)
        VALUES
          (v_org, v_alloc.payer_contact_id, 'consumption', v_ev.id, v_ev.horse_id,
           v_ev.qty, v_unit_cost, ROUND(v_amount * v_alloc.share_pct / 100, 2), 'OPEN', p_period);
        v_covered := v_covered + v_alloc.share_pct;
        v_lines := v_lines + 1;
      END LOOP;
    END IF;

    -- Precedence 3: uncovered / remainder → the default/barn payer, NEVER dropped.
    -- Applies when nothing covered the event (no horse, no override, no share) OR the
    -- effective split fell short of 100.
    v_remainder := 100 - v_covered;
    IF v_remainder > 0.0005 THEN
      IF v_default_payer IS NULL THEN
        RAISE EXCEPTION
          'consumption event % has an uncovered % share but no default/barn payer is configured (seed a default-scoped cost_allocation_rule)',
          v_ev.id, v_remainder
          USING errcode = 'insufficient_privilege';
      END IF;
      INSERT INTO billable_lines
        (org_id, payer_contact_id, source_kind, source_id, horse_id, qty, unit_amount, amount, status, period)
      VALUES
        (v_org, v_default_payer, 'consumption', v_ev.id, v_ev.horse_id,
         v_ev.qty, v_unit_cost, ROUND(v_amount * v_remainder / 100, 2), 'OPEN', p_period);
      v_lines := v_lines + 1;
    END IF;
  END LOOP;

  RETURN v_lines;
END;
$$;


--
-- Name: resolve_contract_comment(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_contract_comment(p_comment_id uuid, p_resolved boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_org uuid; v_parent uuid; v_cid uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT document_id, org_id, parent_request_id INTO v_doc, v_org, v_parent
    FROM contract_change_requests WHERE id = p_comment_id;
  IF v_doc IS NULL THEN RAISE EXCEPTION 'unknown comment'; END IF;
  IF v_parent IS NOT NULL THEN RAISE EXCEPTION 'resolve the thread on its first comment'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false)) OR caller_is_document_party(v_doc)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;
  v_cid := current_contact_id();
  UPDATE contract_change_requests
     SET resolved_at = CASE WHEN p_resolved THEN now() ELSE NULL END,
         resolved_by_contact_id = CASE WHEN p_resolved THEN v_cid ELSE NULL END,
         agreed_at = CASE WHEN p_resolved THEN now() ELSE NULL END,
         agreed_by_contact_id = CASE WHEN p_resolved THEN v_cid ELSE NULL END,
         updated_at = now()
   WHERE id = p_comment_id;
END;
$$;


--
-- Name: resolve_field_edit(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_field_edit(p_document_id uuid, p_field_key text, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pv text; v_pby uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT proposed_value, proposed_by_contact_id INTO v_pv, v_pby
    FROM contract_fields WHERE document_id = p_document_id AND field_key = p_field_key;
  IF v_pby IS NULL THEN RAISE EXCEPTION 'no pending proposal on that field'; END IF;
  IF NOT caller_may_resolve(p_document_id, v_pby) THEN
    RAISE EXCEPTION 'not authorized to resolve this proposal';
  END IF;

  IF p_accept THEN
    UPDATE contract_fields
       SET value = v_pv, entered_by_contact_id = v_pby, entered_at = now(),
           proposed_value = NULL, proposed_by_contact_id = NULL, proposed_at = NULL, updated_at = now()
     WHERE document_id = p_document_id AND field_key = p_field_key;
  ELSE
    UPDATE contract_fields
       SET proposed_value = NULL, proposed_by_contact_id = NULL, proposed_at = NULL
     WHERE document_id = p_document_id AND field_key = p_field_key;
  END IF;
  RETURN jsonb_build_object('accepted', p_accept);
END;
$$;


--
-- Name: resolve_notifications_for_link(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_notifications_for_link(p_link text, p_actor uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ct integer := 0; v_n notifications%ROWTYPE;
BEGIN
  IF p_link IS NULL OR btrim(p_link) = '' THEN RETURN 0; END IF;
  FOR v_n IN SELECT * FROM notifications
              WHERE link = p_link
                AND (p_kind IS NULL OR kind = p_kind) LOOP
    -- CLOSEOUT §1.8: log first, delete second, one transaction.
    PERFORM _log_notification_resolution(v_n, 'target_resolved', coalesce(p_actor, auth.uid()));
    INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
    VALUES (coalesce(p_actor, auth.uid()), 'DELETE', 'notifications', v_n.id,
      to_jsonb(v_n), jsonb_build_object('event', 'notification_resolved', 'by', 'target_resolved'));
    v_ct := v_ct + 1;
  END LOOP;
  DELETE FROM notifications WHERE link = p_link AND (p_kind IS NULL OR kind = p_kind);
  RETURN v_ct;
END;
$$;


--
-- Name: resolve_pending_composition(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_pending_composition(p_pending_id uuid, p_decision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_doc uuid; v_spec jsonb; v_proposer uuid; v_applied jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_decision NOT IN ('include','reject') THEN RAISE EXCEPTION 'unknown decision: %', p_decision; END IF;

  SELECT document_id, spec, proposed_by_contact_id INTO v_doc, v_spec, v_proposer
    FROM contract_pending_compositions WHERE id = p_pending_id AND status = 'open';
  IF v_doc IS NULL THEN RAISE EXCEPTION 'that item is already resolved'; END IF;
  IF NOT caller_may_resolve(v_doc, v_proposer) THEN
    RAISE EXCEPTION 'not authorized to resolve this item';
  END IF;

  IF p_decision = 'include' THEN
    v_applied := apply_contract_composition_spec(v_doc, v_spec, v_proposer);
    UPDATE contract_pending_compositions
       SET status = 'accepted', resolved_by_contact_id = current_contact_id(), resolved_at = now()
     WHERE id = p_pending_id;
  ELSE
    UPDATE contract_pending_compositions
       SET status = 'rejected', resolved_by_contact_id = current_contact_id(), resolved_at = now()
     WHERE id = p_pending_id;
  END IF;

  PERFORM redline_notify(p_document_id := v_doc, p_kind := 'contract_item_resolved',
    p_prefix := CASE WHEN p_decision = 'include' THEN 'A suggested item was included on '
                      ELSE 'A suggested item was rejected on ' END);
  RETURN jsonb_build_object('decision', p_decision, 'applied', v_applied);
END;
$$;


--
-- Name: resolve_property_term(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_property_term(p_org uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key text;
  v_row property_terms%ROWTYPE;
BEGIN
  SELECT cv.value_text INTO v_key
    FROM config_values cv
    WHERE cv.org_id = p_org AND cv.namespace = 'PROPERTY' AND cv.key = 'TERM_KEY';

  SELECT * INTO v_row FROM property_terms WHERE key = COALESCE(v_key, 'FACILITY') AND active;
  IF NOT FOUND THEN
    SELECT * INTO v_row FROM property_terms WHERE key = 'FACILITY';
  END IF;

  RETURN jsonb_build_object(
    'key',         v_row.key,
    'term',        v_row.term,
    'article',     v_row.article,
    'plural',      v_row.plural,
    'preposition', v_row.preposition
  );
END;
$$;


--
-- Name: resolve_version_decision(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_version_decision(p_event_id uuid, p_resolution text, p_contact_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key text;
  v_n int := 0;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF p_resolution NOT IN ('ALL','SELECTED','NONE') THEN
    RAISE EXCEPTION 'resolution must be ALL, SELECTED or NONE (got %)', p_resolution;
  END IF;

  SELECT template_key INTO v_key FROM template_version_events
   WHERE id = p_event_id AND resolved_at IS NULL;
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'no unresolved version event with id %', p_event_id;
  END IF;

  IF p_resolution = 'ALL' THEN
    SELECT require_resign_from(v_key, array_agg(s.contact_id))
      INTO v_n FROM template_past_signers(v_key) s;
  ELSIF p_resolution = 'SELECTED' THEN
    IF p_contact_ids IS NULL OR array_length(p_contact_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'SELECTED requires at least one contact';
    END IF;
    v_n := require_resign_from(v_key, p_contact_ids);
  END IF;
  -- NONE: recorded deliberately. The decision that nobody re-signs is still a
  -- decision, and leaving the event unresolved would keep nagging for it.

  UPDATE template_version_events
     SET resolved_at = now(), resolution = p_resolution,
         resolved_by = auth.uid(), people_required = coalesce(v_n, 0)
   WHERE id = p_event_id;

  RETURN coalesce(v_n, 0);
END
$$;


--
-- Name: FUNCTION resolve_version_decision(p_event_id uuid, p_resolution text, p_contact_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_version_decision(p_event_id uuid, p_resolution text, p_contact_ids uuid[]) IS 'Answer a version-bump prompt: ALL (every past signer re-signs), SELECTED (the named subset) or NONE. NONE is recorded rather than dismissed — choosing that nobody re-signs is a real decision and should be auditable, and an unresolved event would otherwise keep prompting.';


--
-- Name: restore_content_block_version(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_content_block_version(p_slug text, p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_body text; v_title text; v_kind text;
begin
  if not is_admin() then raise exception 'admin access required'; end if;
  select v.body, b.title, b.kind into v_body, v_title, v_kind
    from content_block_versions v
    join content_blocks b on b.id = v.block_id
   where b.org_id = current_org() and b.slug = p_slug and v.version = p_version;
  if not found then raise exception 'content block % has no version %', p_slug, p_version; end if;

  return save_content_block_version(p_slug, v_title, v_body, v_kind, p_version);
end;
$$;


--
-- Name: FUNCTION restore_content_block_version(p_slug text, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_content_block_version(p_slug text, p_version integer) IS 'TASK-VERSIONSPINE: mints a NEW version carrying an old version''s body, stamped "from v<n>". Never moves the pointer backwards.';


--
-- Name: restore_contract_template_version(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_contract_template_version(p_template_key text, p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row contract_template_versions%rowtype;
begin
  if not is_admin() then raise exception 'admin access required'; end if;
  if p_template_key = 'HORSE_LEASE_STANDARD' then
    raise exception 'HORSE_LEASE_STANDARD is archived (D10) and no longer receives content updates.';
  end if;
  select * into v_row from contract_template_versions
   where template_key = p_template_key and version = p_version;
  if not found then raise exception 'template % has no version %', p_template_key, p_version; end if;

  perform _restore_contract_template_composition(p_template_key, v_row.composition);
  return save_contract_template_version(p_template_key, v_row.title, v_row.body, p_version);
end;
$$;


--
-- Name: FUNCTION restore_contract_template_version(p_template_key text, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_contract_template_version(p_template_key text, p_version integer) IS 'TASK-VERSIONSPINE: mints a NEW version carrying an old version''s wording, stamped "from v<n>". Never moves the pointer backwards. Refuses when the template''s structure has changed since that version.';


--
-- Name: restore_email_template_version(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_email_template_version(p_email_key text, p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_title text; v_subject text; v_body text;
begin
  if not coalesce(is_admin(), false) then
    raise exception 'Email template editing is admin-only';
  end if;
  select v.title, v.subject, v.body into v_title, v_subject, v_body
    from email_template_versions v
    join email_templates e on e.id = v.template_id
   where e.email_key = p_email_key and v.version = p_version;
  if not found then raise exception 'Email template % has no version %', p_email_key, p_version; end if;

  return save_email_template_version(p_email_key, v_title, v_subject, v_body, p_version);
end;
$$;


--
-- Name: FUNCTION restore_email_template_version(p_email_key text, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_email_template_version(p_email_key text, p_version integer) IS 'TASK-SURFACEEDITOR: mints a NEW version carrying an old version''s wording, stamped "from v<n>". Never moves the pointer backwards.';


--
-- Name: restore_form_definition_version(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_form_definition_version(p_form_key text, p_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row form_definition_versions%rowtype;
begin
  if not is_admin() then raise exception 'admin only'; end if;
  select * into v_row from form_definition_versions
   where form_key = p_form_key and version = p_version;
  if not found then raise exception 'form % has no version %', p_form_key, p_version; end if;

  return save_form_definition_version(
    p_form_key, v_row.title, v_row.audience, v_row.purpose, v_row.schema, p_version);
end;
$$;


--
-- Name: FUNCTION restore_form_definition_version(p_form_key text, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_form_definition_version(p_form_key text, p_version integer) IS 'TASK-VERSIONSPINE: mints a NEW version carrying an old version''s content, stamped "from v<n>". Never moves the pointer backwards, never removes a row.';


--
-- Name: restore_lesson_plan_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_lesson_plan_version(p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old lesson_plans%ROWTYPE;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;

  SELECT * INTO v_old FROM lesson_plans WHERE id = p_plan_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'plan version not found in this org'; END IF;
  IF v_old.status = 'current' THEN
    RAISE EXCEPTION 'that version is already the current plan';
  END IF;

  PERFORM _write_lesson_plan_version(v_old.client_id, v_old.focus, v_old.objectives,
            v_old.coach_notes, 'revised',
            'Restored the plan as it stood at version ' || v_old.version);

  RETURN client_lesson_plan(v_old.client_id);
END;
$$;


--
-- Name: retired_field_section(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retired_field_section(p_field_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    -- removed by 20260729021000_lease_insurance_rebuild
    WHEN p_field_key IN ('TXN.GL_POSTURE','TXN.MED_COVERAGE','TXN.MORT_ELECTED',
                         'TXN.MORT_PREM_RESP','TXN.MORT_EFFECTIVE_DATE')
      THEN 'INSURANCE_RISK'
    -- removed by 20260729020000_lease_eval_lessons_restrictions_others
    WHEN p_field_key IN ('TXN.EVALUATION_FEE_MODE','TXN.EVALUATION_FEE_AMOUNT',
                         'TXN.EVALUATION_LENGTH','TXN.EVALUATION_UNIT')
      THEN 'EVALUATION'
    ELSE NULL
  END;
$$;


--
-- Name: FUNCTION retired_field_section(p_field_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.retired_field_section(p_field_key text) IS 'Owning section for change-log field keys whose field has since been removed from the template (insurance rebuild / evaluation rework). The change log is evidence, so a retired field''s history must still be attributable.';


--
-- Name: revenue_period_lines(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_period_lines(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(purchase_id uuid, display_code text, paid_at timestamp with time zone, client text, full_price numeric, collected numeric, write_down numeric, disposition text, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Refuse rather than return an empty set that looks like a quiet month.
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  RETURN QUERY
  SELECT p.id,
         p.display_code,
         p.paid_at,
         coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)), ''),
                  pr.email, c.email, '—'),
         coalesce(p.amount, 0),
         -- R5: an explicit zero on a paid order is ZERO collected (a comp).
         -- Only NULL falls back to `amount` — rows written before amount_paid
         -- existed keep exactly the meaning they had.
         coalesce(p.amount_paid, p.amount, 0),
         coalesce(p.write_down_amount, 0),
         p.payment_disposition,
         p.write_down_reason
    FROM purchases p
    LEFT JOIN contacts  c  ON c.id = p.buyer_contact_id
    LEFT JOIN profiles  pr ON pr.user_id = p.buyer_user_id
   WHERE p.org_id = current_org()
     AND p.deleted_at IS NULL
     AND p.payment_status = 'paid'
     AND p.paid_at IS NOT NULL
     AND p.paid_at >= p_from AND p.paid_at < p_to
   ORDER BY p.paid_at;
END;
$$;


--
-- Name: revenue_summary(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_summary(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_span    interval;
  v_total   numeric;
  v_count   integer;
  v_down    numeric;
  v_dcount  integer;
  v_prior   numeric;
  v_pcount  integer;
  v_pdown   numeric;
  v_pdcount integer;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  v_span := p_to - p_from;

  -- The window itself.
  SELECT coalesce(sum(l.collected), 0), count(*),
         coalesce(sum(l.write_down), 0), count(*) FILTER (WHERE l.disposition <> 'paid')
    INTO v_total, v_count, v_down, v_dcount
    FROM revenue_period_lines(p_from, p_to) l;

  -- The window of the same length immediately before it, so a figure can be
  -- read as up or down without a second call and a second definition.
  SELECT coalesce(sum(l.collected), 0), count(*),
         coalesce(sum(l.write_down), 0), count(*) FILTER (WHERE l.disposition <> 'paid')
    INTO v_prior, v_pcount, v_pdown, v_pdcount
    FROM revenue_period_lines(p_from - v_span, p_from) l;

  RETURN jsonb_build_object(
    'total',                  v_total,
    'count',                  v_count,
    'prior_total',            v_prior,
    'prior_count',            v_pcount,
    'delta',                  v_total - v_prior,
    'delta_pct',              CASE WHEN v_prior > 0 THEN round(((v_total - v_prior) / v_prior) * 100, 1) ELSE NULL END,
    'write_down_total',       v_down,
    'write_down_count',       v_dcount,
    'prior_write_down_total', v_pdown,
    'prior_write_down_count', v_pdcount,
    'from',                   p_from,
    'to',                     p_to);
END;
$$;


--
-- Name: FUNCTION revenue_summary(p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revenue_summary(p_from timestamp with time zone, p_to timestamp with time zone) IS 'DASHBOARDBUILD §5 / D18. THE revenue computation: paid purchases recognized at payment date (purchases.paid_at), with the prior equal-length window for deltas. The dashboard KPI and the calendar money strip both call this. Do not add a second one.';


--
-- Name: revert_purchase_writedown(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_purchase_writedown(p_purchase_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pur     purchases%ROWTYPE;
  v_settled numeric;
  v_covers  boolean;
  v_prior   text;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  SELECT * INTO v_pur FROM purchases
   WHERE id = p_purchase_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown purchase: %', p_purchase_id; END IF;
  IF v_pur.payment_disposition = 'paid' THEN
    RAISE EXCEPTION 'nothing to revert — this order carries no write-down';
  END IF;

  -- The value the write-down granted may already be consumed. An undo would then
  -- bill for something already delivered under the comp — refuse it.
  IF EXISTS (SELECT 1 FROM lesson_credits lc
              WHERE lc.purchase_id = p_purchase_id
                AND lc.deleted_at IS NULL
                AND lc.credits_remaining < lc.credits_total) THEN
    RAISE EXCEPTION 'credits from this order have already been used — the write-down cannot be undone';
  END IF;

  SELECT coalesce(sum(amount), 0) INTO v_settled
    FROM payments
   WHERE purchase_id = p_purchase_id AND status = 'paid' AND deleted_at IS NULL;
  v_covers := v_settled >= coalesce(v_pur.amount, 0) - 0.005;

  v_prior := v_pur.payment_disposition;

  -- Money that actually arrived stays recorded (payments rows untouched). Only
  -- the disposition and the closed state come off: the order reopens owing the
  -- difference, exactly as a declared-but-unconfirmed order does (D23).
  UPDATE purchases p
     SET payment_disposition = 'paid',
         write_down_amount   = 0,
         write_down_reason   = NULL,
         amount_paid         = v_settled,
         payment_method      = CASE WHEN p.payment_method = 'comp' THEN NULL ELSE p.payment_method END,
         payment_status      = CASE WHEN v_covers THEN 'paid'
                                    WHEN v_settled > 0 THEN 'pending'
                                    ELSE 'unpaid' END,
         status              = CASE WHEN v_covers THEN 'paid' ELSE 'awaiting_payment' END,
         paid_at             = CASE WHEN v_covers THEN p.paid_at ELSE NULL END
   WHERE p.id = p_purchase_id;

  PERFORM log_status_event('order', p_purchase_id, 'write_down_reverted',
    'Write-down of ' || to_char(v_pur.write_down_amount, 'FM999999990.00')
      || ' (' || v_prior || ') undone — the order reopens owing '
      || to_char(greatest(coalesce(v_pur.amount, 0) - v_settled, 0), 'FM999999990.00')
      || coalesce(' — ' || nullif(btrim(coalesce(p_reason, '')), ''), ''), v_pur.org_id);

  RETURN jsonb_build_object(
    'reverted',        true,
    'was',             v_prior,
    'write_down_was',  v_pur.write_down_amount,
    'now_owing',       greatest(coalesce(v_pur.amount, 0) - v_settled, 0),
    'payment_status',  CASE WHEN v_covers THEN 'paid' WHEN v_settled > 0 THEN 'pending' ELSE 'unpaid' END);
END;
$$;


--
-- Name: revoke_lesson_credit_grant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_lesson_credit_grant(p_purchase_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid := current_org();
  v_reason  text := nullif(btrim(coalesce(p_reason, '')), '');
  v_pu      purchases%ROWTYPE;
  v_mode    text;
  v_used    integer;
  v_revoked integer := 0;
  v_voided  integer := 0;
  v_it      record;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may undo a credit grant';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to undo a credit grant';
  END IF;

  SELECT * INTO v_pu FROM purchases
   WHERE id = p_purchase_id AND deleted_at IS NULL AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found in this organization';
  END IF;

  -- Scoped deliberately: this is the undo for a STAFF GRANT, not a general order
  -- voider. A real client checkout is retired by the order tools, not from here.
  SELECT pi.config->>'grant_mode' INTO v_mode
    FROM purchase_items pi
   WHERE pi.purchase_id = p_purchase_id AND pi.config ? 'grant_mode'
   ORDER BY pi.created_at LIMIT 1;
  IF v_mode IS NULL THEN
    RAISE EXCEPTION 'order % is not a staff credit grant', coalesce(v_pu.display_code, p_purchase_id::text);
  END IF;

  IF v_pu.status = 'void' THEN
    RAISE EXCEPTION 'that grant has already been undone';
  END IF;

  -- Already spent? The lesson happened; this is not undoable.
  SELECT coalesce(sum(lc.credits_total - lc.credits_remaining), 0)::int INTO v_used
    FROM lesson_credits lc
    JOIN purchase_items pi ON pi.id = lc.purchase_item_id
   WHERE pi.purchase_id = p_purchase_id AND lc.deleted_at IS NULL;
  IF v_used > 0 THEN
    RAISE EXCEPTION '% of these credits have already been used — this grant cannot be undone', v_used;
  END IF;
  IF EXISTS (
    SELECT 1 FROM bookings b
      JOIN lesson_credits lc ON lc.id = b.credit_id
      JOIN purchase_items pi ON pi.id = lc.purchase_item_id
     WHERE pi.purchase_id = p_purchase_id
       AND b.status NOT IN ('cancelled', 'expired', 'no_show')
  ) THEN
    RAISE EXCEPTION 'a session is booked against these credits — cancel it first';
  END IF;

  -- Money that actually settled is a refund, not an undo.
  IF coalesce(v_pu.client_claim_status, 'none') = 'confirmed'
     OR EXISTS (SELECT 1 FROM receipt_sends rs WHERE rs.purchase_id = p_purchase_id AND rs.succeeded)
  THEN
    RAISE EXCEPTION 'a payment on this order has already been settled and receipted — refund it rather than undoing the grant';
  END IF;

  -- 1. The entitlement goes first, so no window exists where the order is void and
  --    the credit is still spendable.
  UPDATE lesson_credits lc
     SET deleted_at = now(), deleted_by = auth.uid()
    FROM purchase_items pi
   WHERE pi.id = lc.purchase_item_id
     AND pi.purchase_id = p_purchase_id
     AND lc.deleted_at IS NULL;
  GET DIAGNOSTICS v_revoked = ROW_COUNT;

  -- 2. Void the ORDER before its lines, so _recompute_purchase_total (which skips a
  --    paid or void order) does not log a second, duplicate void event — and so a
  --    hand-written "paid" order does not survive as paid with nothing on it.
  UPDATE purchases
     SET status = 'void', payment_status = 'unpaid', amount_paid = 0, paid_at = NULL
   WHERE id = p_purchase_id;

  -- 3. Void the lines through the existing path (retained as evidence, D11/D16).
  FOR v_it IN SELECT id FROM purchase_items
               WHERE purchase_id = p_purchase_id AND voided_at IS NULL LOOP
    PERFORM void_purchase_item(v_it.id, v_reason);
    v_voided := v_voided + 1;
  END LOOP;

  -- 4. Clear any standing "payment due" notice this order raised.
  PERFORM resolve_notifications_for_link('/order/' || p_purchase_id::text, NULL, 'purchase_unpaid');

  PERFORM log_status_event('order', p_purchase_id, 'grant_reversed',
    'Staff grant undone (' || v_mode || ') — ' || v_revoked || ' credit row(s) withdrawn'
      || CASE WHEN v_mode = 'handwrite' THEN ', recorded payment reversed' ELSE '' END
      || ' — ' || v_reason, v_org);

  RETURN jsonb_build_object(
    'purchase_id',     p_purchase_id,
    'display_code',    v_pu.display_code,
    'mode',            v_mode,
    'credits_revoked', v_revoked,
    'items_voided',    v_voided,
    'reason',          v_reason);
END;
$$;


--
-- Name: FUNCTION revoke_lesson_credit_grant(p_purchase_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revoke_lesson_credit_grant(p_purchase_id uuid, p_reason text) IS 'TASK-CREDITGRANT: the undo for grant_lesson_credit. Soft-deletes the minted credits, voids the order and its lines through void_purchase_item, and refuses when the credits were spent or a real payment settled.';


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: roster_service_slots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roster_service_slots() RETURNS TABLE(code text, display_name text, segment text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT st.code, st.display_name, st.segment
  FROM service_types st
  WHERE st.active AND st.segment <> 'internal'
    AND EXISTS (SELECT 1 FROM offerings o
                 WHERE o.service_type = st.code AND o.active
                   AND o.org_id = current_org())
  ORDER BY CASE st.segment WHEN 'rider' THEN 1 WHEN 'horse' THEN 2 ELSE 3 END,
           st.sort_order, st.code
$$;


--
-- Name: save_booking_form(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_booking_form(p_booking_id uuid, p_answers jsonb, p_submit boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b        bookings%ROWTYPE;
  v_f        booking_forms%ROWTYPE;
  v_id       uuid;
  v_merged   jsonb;
  v_no_show  boolean;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF jsonb_typeof(coalesce(p_answers, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'answers must be an object';
  END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found in this org'; END IF;

  -- The retired check comes BEFORE the ensure, deliberately. A retired form sits
  -- on a booking a form no longer "applies" to (it was cancelled), so ensuring
  -- first would return NULL and report "this booking has no activity form" —
  -- true of the booking, and wrong about the form, which is right there being
  -- kept as a record. Caught by the test of the same name.
  SELECT * INTO v_f FROM booking_forms WHERE booking_id = p_booking_id;
  IF FOUND AND v_f.status = 'retired' THEN
    RAISE EXCEPTION 'this form was retired with its cancelled booking and is kept as a record';
  END IF;

  v_id := _ensure_booking_form(v_b);
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'this booking has no activity form (a form applies to an assigned lesson or care session)';
  END IF;

  SELECT * INTO v_f FROM booking_forms WHERE id = v_id;

  -- shallow merge: a partial save never wipes a field it did not mention, and
  -- clearing a field is sending it as '' (which _booking_form_is_blank still
  -- reads as untouched — a cleared textarea is not a record).
  v_merged := coalesce(v_f.answers, '{}'::jsonb) || coalesce(p_answers, '{}'::jsonb);

  UPDATE booking_forms
     SET answers      = v_merged,
         status       = CASE WHEN p_submit THEN 'submitted' ELSE status END,
         submitted_at = CASE WHEN p_submit THEN now() ELSE submitted_at END,
         submitted_by = CASE WHEN p_submit THEN auth.uid() ELSE submitted_by END,
         updated_at   = now()
   WHERE id = v_id;

  -- ── the projections the rider-facing surfaces already read ────────────────
  -- One-way, written here and nowhere else. Same pattern as current_status on
  -- documents/purchases/bookings: the record is the instance, the column is a
  -- denormalized read.
  UPDATE bookings
     SET activity_log = jsonb_build_object(
           'activities', coalesce(v_merged -> 'activities', '[]'::jsonb),
           'text',       nullif(btrim(coalesce(v_merged ->> 'log_text', '')), '')),
         notes = nullif(btrim(coalesce(v_merged ->> 'report', '')), '')
   WHERE id = p_booking_id;

  -- ── attendance ────────────────────────────────────────────────────────────
  v_no_show := coalesce(v_merged ->> 'attendance', '') = 'no_show';
  IF v_no_show AND v_b.status = 'scheduled' THEN
    IF v_b.kind <> 'lesson' THEN
      -- cancel_lesson_session is lesson-only. A care no-show is a real gap and is
      -- named in the report rather than written around here with a second writer.
      RAISE EXCEPTION 'no-show can only be recorded on a lesson booking today';
    END IF;
    PERFORM cancel_lesson_session(p_booking_id, true);
  ELSIF v_no_show AND v_b.status <> 'no_show' THEN
    RAISE EXCEPTION 'only a SCHEDULED lesson can be marked a no-show (this one is %)', upper(v_b.status);
  END IF;

  RETURN booking_form(p_booking_id);
END;
$$;


--
-- Name: save_calendar_item(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_calendar_item(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid := current_org();
  v_id      uuid := nullif(p->>'id','')::uuid;
  v_kind    text := coalesce(p->>'kind','block');
  v_status  text := coalesce(p->>'status','draft');
  v_start   timestamptz := (p->>'starts_at')::timestamptz;
  v_end     timestamptz := (p->>'ends_at')::timestamptz;
  v_horse   uuid := nullif(p->>'horse_id','')::uuid;
  v_offer   uuid := nullif(p->>'offering_id','')::uuid;
  v_price   numeric := nullif(p->>'price_amount','')::numeric;
  v_weeks   int := coalesce(nullif(p->>'recurrence_weeks','')::int, 1);
  v_scope   text := coalesce(p->>'scope','one');
  v_client  uuid := nullif(p->>'client_id','')::uuid;
  v_pur     uuid := nullif(p->>'purchase_id','')::uuid;
  -- ⚠️ FIX2 §1: the EXPLICITLY NAMED instructor and nothing else.
  v_instr   uuid := nullif(p->>'instructor_user_id','')::uuid;
  -- ⚠️ FIX2 §1: the fallback, applied only where the field is blank.
  v_fallback uuid;
  -- ⚠️ FIX2 §1: NULL means the payload said nothing about all_day, which on an
  -- edit means UNCHANGED. Only CREATE falls back to false.
  v_all_day boolean := (p->>'all_day')::boolean;
  v_flex    boolean := coalesce((p->>'is_flexible')::boolean, false);
  v_pay_method text := nullif(btrim(coalesce(p->>'payment_method','')), '');
  v_mark_paid  boolean := (p->>'payment_state') = 'paid';
  v_credit  uuid;
  v_acct_c  uuid;
  v_acct_u  uuid;
  v_series  uuid;
  v_row     bookings%ROWTYPE;
  v_delta   interval;
  v_dur     interval;
  i         int;
  v_s       timestamptz;
  v_e       timestamptz;
  v_new_id  uuid;
  -- SLOTREACH §5
  v_tell    boolean := false;
  v_label   text;
  v_to      uuid;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF v_start IS NULL OR v_end IS NULL OR v_end <= v_start THEN
    RAISE EXCEPTION 'a calendar item needs a start and a later end';
  END IF;
  IF v_price IS NULL AND v_offer IS NOT NULL THEN
    SELECT price_amount INTO v_price FROM offerings WHERE id = v_offer;
  END IF;

  -- BOOKWRITE: everything the item already knows, resolved once.
  IF v_client IS NOT NULL THEN
    SELECT cl.contact_id INTO v_acct_c FROM clients cl
     WHERE cl.id = v_client AND cl.deleted_at IS NULL;
    IF v_acct_c IS NOT NULL THEN
      SELECT pr.user_id INTO v_acct_u FROM profiles pr WHERE pr.contact_id = v_acct_c;
    END IF;
    -- BOOKLINK B2: the paying item, only on a real (non-draft) commit where
    -- nothing was already resolved for it.
    IF v_pur IS NULL AND NOT v_flex AND v_kind IN ('lesson','care') AND v_status <> 'draft' THEN
      IF v_offer IS NOT NULL THEN
        SELECT d.purchase_id, d.credit_id INTO v_pur, v_credit
          FROM _debit_or_create_for_booking(v_client, v_offer, NULL, v_pay_method, v_mark_paid) d;
      ELSE
        v_pur := _unambiguous_purchase_for_client(v_client);
      END IF;
    END IF;
    -- ⚠️ FIX2 §1: who delivers it, WHEN NOBODY IS RECORDED YET. Same rule this
    -- function has always had, and the same guard (a client-bound lesson or care
    -- item); what changed is that it can no longer reach a row that already
    -- names someone. See the UPDATE and the INSERT below.
    IF v_kind IN ('lesson','care') THEN
      v_fallback := auth.uid();
    END IF;
  END IF;

  -- SLOTREACH §5 — does a change to this item reach the client at all? Same rule
  -- `booking_notifies_client` has always applied (rider always; horse care only when
  -- it happens somewhere they need to be), evaluated against the item AS SAVED rather
  -- than as it was, because that is what they will find on their calendar.
  v_tell := v_status <> 'draft' AND (
       v_kind = 'lesson'
    OR (v_kind = 'care' AND (
          nullif(btrim(coalesce(p->>'address','')), '') IS NOT NULL
       OR EXISTS (SELECT 1 FROM locations l
                   WHERE l.id = nullif(p->>'location_id','')::uuid AND l.is_offsite))));
  v_label := booking_service_label(v_kind, v_offer);

  -- ── EDIT ──────────────────────────────────────────────────────────────────
  IF v_id IS NOT NULL THEN
    SELECT * INTO v_row FROM bookings WHERE id = v_id AND org_id = v_org;
    IF NOT FOUND THEN RAISE EXCEPTION 'item not found in this org'; END IF;

    v_delta := v_start - v_row.starts_at;
    v_dur   := v_end - v_start;

    -- which rows the edit touches (series scope)
    FOR v_row IN
      SELECT * FROM bookings
      WHERE org_id = v_org
        AND (CASE
          WHEN v_scope = 'one' OR v_row.series_id IS NULL THEN id = v_id
          WHEN v_scope = 'future' THEN series_id = v_row.series_id AND starts_at >= v_row.starts_at
          ELSE series_id = v_row.series_id  -- 'all'
        END)
    LOOP
      v_s := v_row.starts_at + v_delta;
      v_e := v_s + v_dur;
      IF v_horse IS NOT NULL AND horse_time_conflict(v_org, v_horse, v_s, v_e, v_row.id, v_row.series_id) THEN
        RAISE EXCEPTION 'that horse is already booked in an overlapping time';
      END IF;
      UPDATE bookings SET
        kind = v_kind, status = v_status, starts_at = v_s, ends_at = v_e,
        is_flexible = coalesce((p->>'is_flexible')::boolean, is_flexible),
        client_id = v_client,
        account_contact_id = v_acct_c,
        account_user_id = v_acct_u,
        -- ⚠️ FIX2 §1 — THE FIX, IN ONE LINE. `instructor_user_id` sits SECOND:
        -- a stamp that exists is never moved by an edit that does not name a
        -- replacement, which is the defect. A blank one is still filled by the
        -- person doing the work, which is how a published open slot becomes a
        -- real lesson with someone's name on it.
        instructor_user_id = coalesce(v_instr, instructor_user_id, v_fallback),
        horse_id = v_horse,
        purchase_id = v_pur,
        credit_id = coalesce(v_credit, credit_id),
        offering_id = v_offer,
        location_id = nullif(p->>'location_id','')::uuid,
        address = nullif(p->>'address',''),
        travel_before_minutes = coalesce((p->>'travel_before_minutes')::int, 0),
        travel_after_minutes = coalesce((p->>'travel_after_minutes')::int, 0),
        price_amount = v_price,
        -- ⚠️ FIX2 §1: same rule. `close_day` is the only writer of `all_day = true`
        -- and the panel never sends the key; an edit must not silently un-close a day.
        all_day = coalesce(v_all_day, all_day),
        notes = nullif(p->>'notes',''),
        updated_at = now()
      WHERE id = v_row.id;

      -- SLOTREACH §5 — WALK2 G-3. This is the branch that moved a client's lesson
      -- and told nobody. The account the item now belongs to is the one told; a
      -- staff member acting on their own calendar entry is not notified about
      -- themselves.
      v_to := coalesce(v_acct_u, v_row.account_user_id);
      IF v_tell AND v_to IS NOT NULL AND v_to <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid) THEN
        IF v_status = 'cancelled' AND v_row.status <> 'cancelled' THEN
          PERFORM _announce_booking_change(v_org, v_to, 'booking_cancelled',
            'Your ' || v_label || ' on '
              || to_char(v_row.starts_at, 'FMDay FMMon FMDD') || ' at '
              || to_char(v_row.starts_at, 'FMHH12:MI AM') || ' is cancelled');
        ELSIF v_s <> v_row.starts_at THEN
          PERFORM _announce_booking_change(v_org, v_to, 'booking_rescheduled',
            'Your ' || v_label || ' has moved to '
              || to_char(v_s, 'FMDay FMMon FMDD') || ' at '
              || to_char(v_s, 'FMHH12:MI AM')
              || ' (was ' || to_char(v_row.starts_at, 'FMMon FMDD') || ')');
        END IF;
      END IF;
    END LOOP;
    RETURN jsonb_build_object('id', v_id, 'series_id', v_row.series_id);
  END IF;

  -- ── CREATE (single or recurring) ────────────────────────────────────────────
  v_dur := v_end - v_start;
  IF v_weeks > 1 THEN v_series := gen_random_uuid(); END IF;

  FOR i IN 0 .. (greatest(v_weeks,1) - 1) LOOP
    v_s := v_start + make_interval(weeks => i);
    v_e := v_s + v_dur;
    IF v_horse IS NOT NULL AND horse_time_conflict(v_org, v_horse, v_s, v_e, NULL, v_series) THEN
      RAISE EXCEPTION 'that horse is already booked in an overlapping time (week %)', i + 1;
    END IF;
    INSERT INTO bookings (
      org_id, kind, status, starts_at, ends_at, all_day, is_flexible,
      client_id, account_contact_id, account_user_id, instructor_user_id,
      horse_id, purchase_id, credit_id, offering_id, location_id, address,
      travel_before_minutes, travel_after_minutes, price_amount, notes,
      series_id, created_by
    ) VALUES (
      v_org, v_kind, v_status, v_s, v_e,
      coalesce(v_all_day, false),
      v_flex,
      v_client, v_acct_c, v_acct_u, coalesce(v_instr, v_fallback),
      v_horse, v_pur, v_credit, v_offer,
      nullif(p->>'location_id','')::uuid, nullif(p->>'address',''),
      coalesce((p->>'travel_before_minutes')::int, 0),
      coalesce((p->>'travel_after_minutes')::int, 0),
      v_price, nullif(p->>'notes',''), v_series, auth.uid()
    ) RETURNING id INTO v_new_id;
  END LOOP;

  RETURN jsonb_build_object('id', v_new_id, 'series_id', v_series);
END;
$$;


--
-- Name: save_content_block_version(text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_content_block_version(p_slug text, p_title text, p_body text, p_kind text DEFAULT 'content'::text, p_parent_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org    uuid := current_org();
  v_block  content_blocks%rowtype;
  v_next   integer;
  v_parent integer := p_parent_version;
begin
  if not is_admin() then raise exception 'admin access required'; end if;
  if p_kind not in ('content', 'policy') then
    raise exception 'kind must be content or policy';
  end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null then
    raise exception 'a content block needs a title';
  end if;

  select * into v_block from content_blocks
   where org_id = v_org and slug = p_slug for update;

  if not found then
    if v_parent is not null then
      raise exception 'content block % does not exist, so it has no version % to come from', p_slug, v_parent;
    end if;
    insert into content_blocks (org_id, slug, kind, title, current_version)
    values (v_org, p_slug, p_kind, p_title, 1)
    returning * into v_block;
    v_next := 1;
  else
    select greatest(v_block.current_version, coalesce(max(cbv.version), 0)) + 1
      into v_next
      from content_block_versions cbv where cbv.block_id = v_block.id;

    if v_parent is not null then
      if v_parent = v_next - 1 then
        v_parent := null;                     -- the ordinary case says itself
      elsif v_parent >= v_next then
        raise exception 'a version cannot come from version % — that is not earlier than %', v_parent, v_next;
      elsif not exists (select 1 from content_block_versions cbv
                         where cbv.block_id = v_block.id and cbv.version = v_parent) then
        raise exception 'content block % has no version % to edit from', p_slug, v_parent;
      end if;
    end if;

    update content_blocks
       set current_version = v_next, title = p_title, kind = p_kind, updated_at = now()
     where id = v_block.id;
  end if;

  insert into content_block_versions (block_id, version, body, parent_version, edited_by)
  values (v_block.id, v_next, p_body, v_parent, auth.uid());

  return v_next;
end;
$$;


--
-- Name: FUNCTION save_content_block_version(p_slug text, p_title text, p_body text, p_kind text, p_parent_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_content_block_version(p_slug text, p_title text, p_body text, p_kind text, p_parent_version integer) IS 'TASK-VERSIONSPINE: the ONLY way a content block version is written. Mints v(max+1) and stamps p_parent_version when an older version was the one being edited.';


--
-- Name: save_contract_template_version(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_contract_template_version(p_template_key text, p_title text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_parent_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ct     contract_templates%rowtype;
  v_next   integer;
  v_parent integer := p_parent_version;
  v_title  text;
  v_body   text;
begin
  if not is_admin() then raise exception 'admin access required'; end if;

  select * into v_ct from contract_templates
   where template_key = p_template_key for update;
  if not found then raise exception 'unknown template: %', p_template_key; end if;

  v_title := coalesce(nullif(btrim(coalesce(p_title,'')),''), v_ct.title);
  v_body  := coalesce(p_body, v_ct.body);

  -- The outgoing live state must be IN the list before we add to it. The
  -- 20260826T1910 backfill covers every template that existed then; this covers
  -- one created since.
  insert into contract_template_versions
    (template_key, version, title, body, composition, parent_version, edited_by, created_at)
  values (v_ct.template_key, v_ct.version, v_ct.title, v_ct.body,
          capture_contract_template_composition(v_ct.template_key), null, null, v_ct.updated_at)
  on conflict (template_key, version) do nothing;

  select greatest(v_ct.version, coalesce(max(ctv.version), 0)) + 1
    into v_next
    from contract_template_versions ctv where ctv.template_key = p_template_key;

  if v_parent is not null then
    if v_parent = v_next - 1 then
      v_parent := null;                       -- the ordinary case says itself
    elsif v_parent >= v_next then
      raise exception 'a version cannot come from version % — that is not earlier than %', v_parent, v_next;
    elsif not exists (select 1 from contract_template_versions ctv
                       where ctv.template_key = p_template_key and ctv.version = v_parent) then
      raise exception 'template % has no version % to edit from', p_template_key, v_parent;
    end if;
  end if;

  update contract_templates
     set title = v_title, body = v_body, version = v_next, updated_at = now()
   where template_key = p_template_key;

  -- Captured AFTER the caller has written its content changes, which is why the
  -- publish path calls this last.
  insert into contract_template_versions
    (template_key, version, title, body, composition, parent_version, edited_by)
  values (p_template_key, v_next, v_title, v_body,
          capture_contract_template_composition(p_template_key), v_parent, auth.uid());

  return v_next;
end;
$$;


--
-- Name: FUNCTION save_contract_template_version(p_template_key text, p_title text, p_body text, p_parent_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_contract_template_version(p_template_key text, p_title text, p_body text, p_parent_version integer) IS 'TASK-VERSIONSPINE: the ONLY way a contract template version is written. Mints v(max+1) and retains body AND composition (sections/clauses/fields) in full.';


--
-- Name: save_email_template_version(text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_email_template_version(p_email_key text, p_title text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_parent_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row    email_templates%rowtype;
  v_next   integer;
  v_parent integer := p_parent_version;
begin
  if not coalesce(is_admin(), false) then
    raise exception 'Email template editing is admin-only';
  end if;

  select * into v_row from email_templates
   where email_key = p_email_key and deleted_at is null
   for update;
  if not found then raise exception 'Email template % not found', p_email_key; end if;

  -- greatest(live, max(history)) + 1 under the row lock: two concurrent saves
  -- cannot claim the same number and no path can produce one already used.
  select greatest(v_row.version, coalesce(max(v.version), 0)) + 1
    into v_next
    from email_template_versions v where v.template_id = v_row.id;

  if v_parent is not null then
    if v_parent = v_next - 1 then
      v_parent := null;                       -- the ordinary case says itself
    elsif v_parent >= v_next then
      raise exception 'a version cannot come from version % — that is not earlier than %', v_parent, v_next;
    elsif not exists (select 1 from email_template_versions v
                       where v.template_id = v_row.id and v.version = v_parent) then
      raise exception 'Email template % has no version % to edit from', p_email_key, v_parent;
    end if;
  end if;

  update email_templates
     set title   = coalesce(p_title,   title),
         subject = coalesce(p_subject, subject),
         body    = coalesce(p_body,    body),
         version = v_next,
         updated_at = now()
   where id = v_row.id
  returning * into v_row;

  insert into email_template_versions
    (template_id, email_key, version, parent_version, title, subject, body, edited_by)
  values
    (v_row.id, v_row.email_key, v_next, v_parent, v_row.title, v_row.subject, v_row.body, auth.uid());

  return v_next;
end;
$$;


--
-- Name: FUNCTION save_email_template_version(p_email_key text, p_title text, p_subject text, p_body text, p_parent_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_email_template_version(p_email_key text, p_title text, p_subject text, p_body text, p_parent_version integer) IS 'TASK-SURFACEEDITOR: the ONLY way an email template version is written. Mints v(max+1) and stamps p_parent_version when an older version was the one being edited.';


--
-- Name: save_evaluation_report(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_evaluation_report(p_report_id uuid, p_body text, p_title text DEFAULT NULL::text, p_horse_label text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  UPDATE evaluation_reports
     SET body = p_body,
         title = coalesce(p_title, title),
         horse_label = coalesce(p_horse_label, horse_label)
   WHERE id = p_report_id AND org_id = current_org() AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'report not found or not a draft'; END IF;
END;
$$;


--
-- Name: save_form_definition_version(text, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_form_definition_version(p_form_key text, p_title text, p_audience text, p_purpose text, p_schema jsonb, p_parent_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_fd     form_definitions%rowtype;
  v_next   integer;
  v_parent integer := p_parent_version;
begin
  if not is_admin() then raise exception 'admin only'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null then
    raise exception 'a form version needs a title';
  end if;
  if p_schema is null or jsonb_typeof(p_schema->'sections') <> 'array' then
    raise exception 'a form version needs a schema with a sections array';
  end if;

  -- FOR UPDATE serialises minting per form: two saves cannot claim the same number.
  select * into v_fd from form_definitions where form_key = p_form_key for update;
  if not found then raise exception 'unknown form: %', p_form_key; end if;

  -- The outgoing live state must be IN the list before we add to it. Legacy rows
  -- predate this spine, so this is a no-op once a form has been saved through it.
  -- edited_by stays NULL: nobody recorded who authored the state we inherited.
  insert into form_definition_versions (form_key, version, title, audience, purpose, schema, edited_by)
  values (v_fd.form_key, v_fd.version, v_fd.title, v_fd.audience, v_fd.purpose, v_fd.schema, null)
  on conflict (form_key, version) do nothing;

  -- greatest(): the number only ever goes up, even if the live pointer and the
  -- history ever disagreed. Nothing here can produce a number already used.
  select greatest(v_fd.version, coalesce(max(fdv.version), 0)) + 1
    into v_next
    from form_definition_versions fdv where fdv.form_key = p_form_key;

  if v_parent is not null then
    if v_parent = v_next - 1 then
      v_parent := null;                       -- the ordinary case says itself
    elsif v_parent >= v_next then
      raise exception 'a version cannot come from version % — that is not earlier than %', v_parent, v_next;
    elsif not exists (select 1 from form_definition_versions fdv
                       where fdv.form_key = p_form_key and fdv.version = v_parent) then
      raise exception 'form % has no version % to edit from', p_form_key, v_parent;
    end if;
  end if;

  insert into form_definition_versions
    (form_key, version, title, audience, purpose, schema, parent_version, edited_by)
  values (p_form_key, v_next, p_title, p_audience, p_purpose, p_schema, v_parent, auth.uid());

  update form_definitions
     set title = p_title, audience = p_audience, purpose = p_purpose,
         schema = p_schema, version = v_next, updated_at = now()
   where form_key = p_form_key;

  return v_next;
end;
$$;


--
-- Name: FUNCTION save_form_definition_version(p_form_key text, p_title text, p_audience text, p_purpose text, p_schema jsonb, p_parent_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_form_definition_version(p_form_key text, p_title text, p_audience text, p_purpose text, p_schema jsonb, p_parent_version integer) IS 'TASK-VERSIONSPINE: the ONLY way a form version is written. Mints v(max+1), retains it in full, and points the live form at it. p_parent_version records which version was edited when it was not the latest.';


--
-- Name: save_lesson_plan(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_lesson_plan(p_client_id uuid, p_focus text, p_objectives jsonb DEFAULT '[]'::jsonb, p_coach_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_c    clients%ROWTYPE;
  v_cur  lesson_plans%ROWTYPE;
  v_objs jsonb;
  v_notes text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;

  SELECT * INTO v_c FROM clients WHERE id = p_client_id AND org_id = current_org();
  IF NOT FOUND THEN RAISE EXCEPTION 'client not found in this org'; END IF;

  v_objs := _lesson_plan_objectives(p_objectives);
  v_cur  := _current_lesson_plan(p_client_id);
  v_notes := CASE WHEN p_coach_notes IS NULL THEN v_cur.coach_notes ELSE p_coach_notes END;

  IF v_cur.id IS NULL THEN
    PERFORM _write_lesson_plan_version(p_client_id, p_focus, v_objs, v_notes,
              'created', 'Plan started');
  ELSIF _lesson_plan_same(v_cur.focus, v_cur.objectives, v_cur.coach_notes,
                          p_focus, v_objs, v_notes) THEN
    -- nothing changed: no version, no log entry, no noise in the history
    NULL;
  ELSE
    PERFORM _write_lesson_plan_version(p_client_id, p_focus, v_objs, v_notes,
              'revised', 'Edited by staff');
  END IF;

  RETURN client_lesson_plan(p_client_id);
END;
$$;


--
-- Name: say_hi(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.say_hi(p_to_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_from uuid := auth.uid();
BEGIN
  IF v_from IS NULL THEN RAISE EXCEPTION 'sign in first'; END IF;
  IF v_from = p_to_user THEN RETURN false; END IF;
  v_org := (SELECT org_id FROM profiles WHERE user_id = v_from);
  IF v_org IS NULL OR v_org IS DISTINCT FROM (SELECT org_id FROM profiles WHERE user_id = p_to_user) THEN
    RAISE EXCEPTION 'members must be in the same community';
  END IF;
  INSERT INTO member_greetings (org_id, from_user, to_user, kind)
  VALUES (v_org, v_from, p_to_user, 'hi') ON CONFLICT (from_user, to_user, kind) DO NOTHING;
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
  VALUES (v_org, p_to_user, 'member_hi',
          'A welcome from ' || member_display_name(v_from),
          'Hi ' || member_display_name(p_to_user) || ', welcome to the community! - ' || member_display_name(v_from),
          '/app?filter=members&hi_back=' || v_from::text);
  RETURN true;
END;
$$;


--
-- Name: say_hi_back(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.say_hi_back(p_to_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_from uuid := auth.uid();
BEGIN
  IF v_from IS NULL THEN RAISE EXCEPTION 'sign in first'; END IF;
  IF v_from = p_to_user THEN RETURN false; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM member_greetings
    WHERE from_user = p_to_user AND to_user = v_from AND kind = 'hi'
  ) THEN
    RAISE EXCEPTION 'no welcome to reply to';
  END IF;

  v_org := (SELECT org_id FROM profiles WHERE user_id = v_from);

  INSERT INTO member_greetings (org_id, from_user, to_user, kind)
  VALUES (v_org, v_from, p_to_user, 'hi_back')
  ON CONFLICT (from_user, to_user, kind) DO NOTHING;
  IF NOT FOUND THEN RETURN false; END IF;

  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
  VALUES (v_org, p_to_user, 'member_hi_back',
          'A note from ' || member_display_name(v_from),
          'Hi ' || member_display_name(p_to_user) || ', thanks for welcoming me to the community. – ' || member_display_name(v_from),
          '/app?filter=members');
  RETURN true;
END;
$$;


--
-- Name: schedule_lesson_session(uuid, timestamp with time zone, timestamp with time zone, uuid, uuid, text, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lesson_session(p_client_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_engagement_id uuid DEFAULT NULL::uuid, p_request_id uuid DEFAULT NULL::uuid, p_location text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_horse_id uuid DEFAULT NULL::uuid, p_offering_id uuid DEFAULT NULL::uuid, p_instructor_user_id uuid DEFAULT NULL::uuid, p_purchase_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_contact uuid;
  v_id      uuid;
  v_user    uuid;
  v_instr   uuid;
  v_pur     uuid;
  v_credit  uuid;   -- LESSONREQUEST §L3: what this booking actually drew down
BEGIN
  -- coalesce(): D1a — a caller for whom has_staff_access() is undefined must be
  -- DENIED, not admitted by a NULL falling through the IF.
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'not authorized to schedule lessons';
  END IF;
  IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'a lesson needs a start and an end, and the end must be after the start';
  END IF;

  SELECT cl.org_id, cl.contact_id INTO v_org, v_contact
    FROM clients cl WHERE cl.id = p_client_id AND cl.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown client: %', p_client_id;
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role' AND v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'client % is not in your organization', p_client_id;
  END IF;

  -- a supplied horse must belong to the same tenant
  IF p_horse_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM horses h WHERE h.id = p_horse_id AND h.org_id = v_org AND h.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'horse % is not in your organization', p_horse_id;
  END IF;

  -- BOOKWRITE: a supplied offering must be this tenant's
  IF p_offering_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM offerings o WHERE o.id = p_offering_id AND o.org_id = v_org
  ) THEN
    RAISE EXCEPTION 'offering % is not in your organization', p_offering_id;
  END IF;

  -- BOOKWRITE: a supplied purchase must belong to this client
  IF p_purchase_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM purchases pu
     WHERE pu.id = p_purchase_id AND pu.deleted_at IS NULL
       AND pu.org_id = v_org AND pu.buyer_contact_id = v_contact
  ) THEN
    RAISE EXCEPTION 'purchase % does not belong to this client', p_purchase_id;
  END IF;

  IF EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.kind = 'lesson' AND b.client_id = p_client_id AND b.org_id = v_org
      AND b.status = 'scheduled'
      AND b.starts_at < p_ends_at AND b.ends_at > p_starts_at
  ) THEN
    RAISE EXCEPTION 'this client already has a lesson scheduled that overlaps % – %',
      to_char(p_starts_at, 'FMMonth FMDD, HH12:MI AM'), to_char(p_ends_at, 'HH12:MI AM');
  END IF;

  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = v_contact;

  -- who is delivering it: named, else the acting staff member
  v_instr := coalesce(p_instructor_user_id, auth.uid());

  -- ── LESSONREQUEST §L3 — what paid for it, through BOOKLINK's writer ──────
  -- Debits an open credit for this service (preferring the named purchase),
  -- respects a purchase staff named outright, and only creates an order when
  -- there is a service named and nothing anywhere to draw it from. With no
  -- service named it is a no-op that hands the purchase straight back, and the
  -- coalesce below preserves this function's original behaviour exactly.
  SELECT d.purchase_id, d.credit_id INTO v_pur, v_credit
    FROM _debit_or_create_for_booking(p_client_id, p_offering_id, p_purchase_id, NULL, false) d;
  v_pur := coalesce(v_pur, p_purchase_id, _unambiguous_purchase_for_client(p_client_id));

  INSERT INTO bookings
      (org_id, kind, client_id, account_contact_id, account_user_id, request_id, horse_id,
       offering_id, instructor_user_id, purchase_id, credit_id,
       starts_at, ends_at, location, notes, status)
    VALUES
      (v_org, 'lesson', p_client_id, v_contact, v_user, p_request_id, p_horse_id,
       p_offering_id, v_instr, v_pur, v_credit,
       p_starts_at, p_ends_at,
       NULLIF(trim(coalesce(p_location, '')), ''), NULLIF(trim(coalesce(p_notes, '')), ''),
       'scheduled')
    RETURNING id INTO v_id;

  IF p_request_id IS NOT NULL THEN
    UPDATE requests SET status = 'converted' WHERE id = p_request_id;
  END IF;

  IF v_user IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_org, v_user, 'lesson_scheduled',
              'Your lesson is booked — ' || to_char(p_starts_at, 'FMMonth FMDD, HH12:MI AM'),
              '/app/schedule');
  END IF;

  RETURN jsonb_build_object(
    'session_id',    v_id,
    'client_id',     p_client_id,
    'starts_at',     p_starts_at,
    'ends_at',       p_ends_at,
    'status',        'SCHEDULED',
    'location',      NULLIF(trim(coalesce(p_location, '')), ''),
    'horse_id',      p_horse_id,
    'offering_id',   p_offering_id,
    'instructor_user_id', v_instr,
    'purchase_id',   v_pur,
    'credit_id',     v_credit,
    'engagement_id', p_engagement_id,
    'request_id',    p_request_id
  );
END;
$$;


--
-- Name: scrub_lesson_content(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrub_lesson_content(p_kind text, p_subject uuid, p_reason text, p_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_f      files%ROWTYPE;
  v_b      bookings%ROWTYPE;
  v_plan   lesson_plans%ROWTYPE;
  v_count  integer := 0;
  v_path   text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a scrub needs a reason — it is the only thing left once the content is gone';
  END IF;

  -- ── a photo or video on a lesson ─────────────────────────────────────────
  IF p_kind = 'media' THEN
    SELECT * INTO v_f FROM files WHERE id = p_subject AND org_id = current_org();
    IF NOT FOUND THEN RAISE EXCEPTION 'file not found in this org'; END IF;
    IF EXISTS (SELECT 1 FROM content_resources cr WHERE cr.file_id = v_f.id) THEN
      RAISE EXCEPTION 'this file is published in the content catalogue — unpublish it there first';
    END IF;
    -- the link this scrub is being requested from, for the log
    SELECT b.* INTO v_b FROM file_links fl JOIN bookings b ON b.id = fl.subject_id
      WHERE fl.file_id = v_f.id AND fl.subject_type = 'booking' LIMIT 1;

    v_path := v_f.storage_path;
    DELETE FROM file_links WHERE file_id = v_f.id;
    DELETE FROM files WHERE id = v_f.id;
    v_count := 1;

    IF v_b.id IS NOT NULL THEN
      PERFORM log_status_event('offering', v_b.id, 'progress_recorded',
                'Media scrubbed for liability: ' || v_reason, v_b.org_id);
    END IF;

    RETURN jsonb_build_object('kind', 'media', 'scrubbed', v_count,
                              'storage_path', v_path, 'bucket_id', v_f.bucket_id);
  END IF;

  -- ── one text answer on a lesson's form ───────────────────────────────────
  IF p_kind = 'answer' THEN
    IF p_key IS NULL OR btrim(p_key) = '' THEN
      RAISE EXCEPTION 'name the field to scrub';
    END IF;
    SELECT * INTO v_b FROM bookings WHERE id = p_subject AND org_id = current_org();
    IF NOT FOUND THEN RAISE EXCEPTION 'lesson not found in this org'; END IF;

    -- The answers row AND its projection on bookings, together — leaving the
    -- projection behind is leaving the content in the system, which is the whole
    -- thing this call exists to prevent.
    UPDATE booking_forms
       SET answers = answers - btrim(p_key), updated_at = now()
     WHERE booking_id = p_subject;
    GET DIAGNOSTICS v_count = ROW_COUNT;

    IF btrim(p_key) = 'report' THEN
      UPDATE bookings SET notes = NULL WHERE id = p_subject;
    ELSIF btrim(p_key) = 'log_text' THEN
      UPDATE bookings SET activity_log = coalesce(activity_log, '{}'::jsonb)
                            || jsonb_build_object('text', NULL)
       WHERE id = p_subject;
    END IF;

    PERFORM log_status_event('offering', p_subject, 'progress_recorded',
              'Field "' || btrim(p_key) || '" scrubbed for liability: ' || v_reason,
              v_b.org_id);
    RETURN jsonb_build_object('kind', 'answer', 'scrubbed', v_count, 'key', btrim(p_key));
  END IF;

  -- ── one objective's note, across EVERY retained version of the plan ──────
  -- Scrubbing only the current version would leave the text sitting in the
  -- history the rest of this task works hard to retain. The objective itself
  -- stays; only the note is destroyed.
  IF p_kind = 'objective_note' THEN
    IF p_key IS NULL OR btrim(p_key) = '' THEN
      RAISE EXCEPTION 'name the objective to scrub';
    END IF;
    SELECT * INTO v_plan FROM lesson_plans WHERE id = p_subject AND org_id = current_org();
    IF NOT FOUND THEN RAISE EXCEPTION 'plan version not found in this org'; END IF;

    UPDATE lesson_plans p
       SET objectives = (
         SELECT coalesce(jsonb_agg(
                  CASE WHEN e.v ->> 'id' = btrim(p_key)
                       THEN e.v || jsonb_build_object('note', NULL) ELSE e.v END
                  ORDER BY e.n), '[]'::jsonb)
           FROM jsonb_array_elements(p.objectives) WITH ORDINALITY AS e(v, n))
     WHERE p.client_id = v_plan.client_id
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(p.objectives) AS y
                    WHERE y ->> 'id' = btrim(p_key) AND y ->> 'note' IS NOT NULL);
    GET DIAGNOSTICS v_count = ROW_COUNT;

    PERFORM log_status_event('lesson_plan', v_plan.id, 'scrubbed',
              'An objective note was scrubbed for liability across ' || v_count
              || ' version(s): ' || v_reason, v_plan.org_id);
    RETURN jsonb_build_object('kind', 'objective_note', 'scrubbed', v_count);
  END IF;

  RAISE EXCEPTION 'unknown scrub kind: % (media | answer | objective_note)', p_kind;
END;
$$;


--
-- Name: seed_cascade_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_cascade_fields(p_document_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_tmpl text; v_n int := 0;
BEGIN
  SELECT d.org_id, t.template_key INTO v_org, v_tmpl
    FROM documents d JOIN contract_templates t ON t.id = d.template_id
   WHERE d.id = p_document_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;

  INSERT INTO contract_fields
    (org_id, document_id, field_key, label, section, owner_role, value, value_type,
     required, sort_order, parent_field_key, input_kind, options, conditional_on, closed,
     guidance, is_optional, included)
  SELECT v_org, p_document_id, cd.field_key, cd.label, cd.section, cd.owner_role, NULL,
         cd.value_type, cd.required, cd.sort_order, cd.parent_field_key, cd.input_kind,
         cd.options, cd.conditional_on, cd.guidance, cd.is_optional,
         NOT cd.is_optional   -- optional fields start un-included
  FROM contract_field_defs cd
  WHERE cd.template_key = v_tmpl
    AND NOT EXISTS (SELECT 1 FROM contract_fields cf
                    WHERE cf.document_id = p_document_id AND cf.field_key = cd.field_key);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: seed_contract_fields(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_contract_fields(p_document_id uuid, p_fields jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_state text;
  v_f     jsonb;
  v_n     integer := 0;
  v_by    uuid := current_contact_id();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id, workflow_state INTO v_org, v_state
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF NOT (
       (coalesce(has_staff_access() AND v_org = current_org(), false))
  ) THEN
    RAISE EXCEPTION 'not authorized to seed fields on document %', p_document_id;
  END IF;

  IF jsonb_typeof(p_fields) <> 'array' THEN
    RAISE EXCEPTION 'p_fields must be a jsonb array of field definitions';
  END IF;

  FOR v_f IN SELECT * FROM jsonb_array_elements(p_fields) LOOP
    IF coalesce(v_f ->> 'field_key', '') = '' THEN
      RAISE EXCEPTION 'each field needs a field_key';
    END IF;
    IF coalesce(v_f ->> 'owner_role', '') = '' THEN
      RAISE EXCEPTION 'field % needs an owner_role', v_f ->> 'field_key';
    END IF;

    INSERT INTO contract_fields (
      org_id, document_id, field_key, label, section, owner_role,
      value, value_type, input_kind, is_optional, included, required, sort_order,
      entered_by_contact_id, entered_at)
    VALUES (
      v_org, p_document_id,
      v_f ->> 'field_key',
      v_f ->> 'label',
      v_f ->> 'section',
      v_f ->> 'owner_role',
      v_f ->> 'value',
      coalesce(nullif(v_f ->> 'value_type', ''), 'text'),
      CASE
        WHEN coalesce(v_f ->> 'input_kind','') <> '' THEN v_f ->> 'input_kind'
        WHEN (v_f ->> 'value_type') = 'longtext' THEN 'longtext'
        WHEN (v_f ->> 'value_type') = 'currency' THEN 'currency'
        WHEN (v_f ->> 'value_type') = 'date' THEN 'date'
        WHEN (v_f ->> 'value_type') = 'select' THEN 'select'
        WHEN (v_f ->> 'value_type') = 'checkbox' THEN 'buttons'
        WHEN (v_f ->> 'field_key') IN ('TXN.DAYS_USED','TXN.RESERVED_DAYS','TXN.DAYS_UNAVAILABLE') THEN 'week_grid'
        WHEN (v_f ->> 'field_key') LIKE '%_COST' THEN 'responsibility'
        WHEN (v_f ->> 'field_key') LIKE '%_RESPONSIBILITY' THEN 'responsibility'
        ELSE 'text' END,
      -- optional (includable) sections collapse until included
      coalesce((v_f ->> 'is_optional')::boolean,
        (v_f ->> 'section') IN ('Training & Lessons','Competition','Evaluation Period','Partial Lease','Equipment & Tack','Insurance','Permissions')),
      NOT coalesce((v_f ->> 'is_optional')::boolean,
        (v_f ->> 'section') IN ('Training & Lessons','Competition','Evaluation Period','Partial Lease','Equipment & Tack','Insurance','Permissions')),
      coalesce((v_f ->> 'required')::boolean, false),
      coalesce((v_f ->> 'sort_order')::int, 0),
      CASE WHEN nullif(v_f ->> 'value', '') IS NOT NULL THEN v_by END,
      CASE WHEN nullif(v_f ->> 'value', '') IS NOT NULL THEN now() END)
    ON CONFLICT (document_id, field_key) DO UPDATE SET
      label      = excluded.label,
      section    = excluded.section,
      owner_role = excluded.owner_role,
      value_type = excluded.value_type, input_kind = excluded.input_kind,
      required   = excluded.required,
      sort_order = excluded.sort_order,
      -- keep an already-entered value unless the seed provides a new one
      value                 = coalesce(nullif(excluded.value, ''), contract_fields.value),
      entered_by_contact_id = CASE WHEN nullif(excluded.value, '') IS NOT NULL
                                   THEN v_by ELSE contract_fields.entered_by_contact_id END,
      entered_at            = CASE WHEN nullif(excluded.value, '') IS NOT NULL
                                   THEN now() ELSE contract_fields.entered_at END;
    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


--
-- Name: FUNCTION seed_contract_fields(p_document_id uuid, p_fields jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.seed_contract_fields(p_document_id uuid, p_fields jsonb) IS 'Staff/originator: bulk-insert a generated document''s structured, party-owned field DEFINITIONS from a jsonb array (field_key, label, section, owner_role, value_type, required, sort_order, value). Idempotent per (document_id, field_key). Returns the number of fields processed.';


--
-- Name: seed_contract_note(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_contract_note() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.contract_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM contract_notes WHERE document_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  INSERT INTO contract_notes (org_id, document_id, title, created_by_contact_id)
  VALUES (NEW.org_id, NEW.id, 'Comment 1', NULL);
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION seed_contract_note(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.seed_contract_note() IS 'Creates the single starter note on a new CONTRACT document (contract_id not null). Server-side and guarded, so it happens exactly once however many parties open the document simultaneously — the client-side version it replaces could double-seed under exactly that race.';


--
-- Name: send_contract_to_party(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_contract_to_party(p_document_id uuid, p_party_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_title text; v_target uuid; v_me uuid := current_contact_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state, title INTO v_org, v_state, v_title FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))) THEN
    RAISE EXCEPTION 'not authorized to send this document';
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(contract_lock_blockers(p_document_id)) b
              WHERE b->>'code' = 'horse_missing') THEN
    RAISE EXCEPTION 'Attach the horse to this contract before sending it.';
  END IF;

  SELECT contact_id INTO v_target FROM document_parties
   WHERE document_id = p_document_id AND party_role = p_party_role AND contact_id IS NOT NULL LIMIT 1;
  IF v_target IS NULL THEN RAISE EXCEPTION 'that party has no contact to send to'; END IF;

  UPDATE documents SET sent_at = coalesce(sent_at, now()), updated_at = now() WHERE id = p_document_id;

  -- ⚠️ FIX ROUND 5b — the role bundle each party owes is generated HERE, at send,
  -- sequenced behind this contract. ensure_contract_role_documents is idempotent,
  -- so a second send, a resend, or execution never creates another copy. Hold and
  -- delivery are unchanged: nothing delivers until every sequenced document on the
  -- contract executes.
  BEGIN
    PERFORM ensure_contract_role_documents(p_document_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'send_contract_to_party: role bundle not generated for document %: %',
      p_document_id, SQLERRM;
  END;

  INSERT INTO notifications (org_id, user_id, kind, title, body, link)
  SELECT v_org, p.user_id, 'contract_sent',
         coalesce(v_title, 'A document') || ' is ready for you',
         'You have a document to review'
           || CASE WHEN v_state IN ('locked') THEN ' and sign.' ELSE ' and complete.' END,
         '/app/contracts/' || p_document_id::text
    FROM profiles p
   WHERE p.user_id IN (SELECT user_id FROM party_user_ids(p_document_id, p_party_role));
END;
$$;


--
-- Name: send_executed_document_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_executed_document_email(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc     documents%ROWTYPE;
  v_unsigned int;
  v_base    text;
  v_req     bigint;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;

  -- every signer must have signed: any NULL signature means do not send
  SELECT count(*) INTO v_unsigned
    FROM signatures s
   WHERE s.document_id = p_document_id AND s.deleted_at IS NULL AND s.signed_at IS NULL;
  IF v_doc.status <> 'EXECUTED' OR v_unsigned > 0 THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'not fully signed');
  END IF;

  IF v_doc.executed_email_sent_at IS NOT NULL THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'already sent',
                              'sent_at', v_doc.executed_email_sent_at);
  END IF;

  SELECT value_text INTO v_base FROM config_values
   WHERE org_id = v_doc.org_id AND namespace='SYSTEM' AND key='APP_BASE_URL';
  IF coalesce(btrim(v_base),'') = '' THEN
    UPDATE documents SET executed_email_error = 'APP_BASE_URL not configured'
     WHERE id = p_document_id;
    RETURN jsonb_build_object('sent', false, 'reason', 'no base url');
  END IF;

  -- fire-and-forget POST; the endpoint renders the PDFs, unions the parties,
  -- brands per tenant and writes document_deliveries rows idempotently.
  -- A15: 15000ms timeout — the endpoint legitimately takes 6-8s (PDF + SMTP);
  -- pg_net's 5000ms default was recording false timeouts on real successes.
  SELECT net.http_post(
           url     := v_base || '/api/deliver-documents',
           body    := jsonb_build_object('documentIds', jsonb_build_array(p_document_id::text)),
           headers := '{"Content-Type": "application/json"}'::jsonb,
           timeout_milliseconds := 15000
         ) INTO v_req;

  UPDATE documents
     SET executed_email_sent_at = now(), executed_email_error = NULL
   WHERE id = p_document_id;

  RETURN jsonb_build_object('sent', true, 'request_id', v_req);
END;
$$;


--
-- Name: set_booking_change_fee_schedule(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_booking_change_fee_schedule(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
  v_n   integer := 0;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'no organization in scope'; END IF;

  DELETE FROM booking_change_fees WHERE org_id = v_org;

  INSERT INTO booking_change_fees (org_id, hours_before, fee_amount, label, active)
  SELECT v_org,
         (r->>'hours_before')::int,
         (r->>'fee_amount')::numeric,
         nullif(btrim(coalesce(r->>'label', '')), ''),
         coalesce((r->>'active')::boolean, true)
    FROM jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
   WHERE coalesce(nullif(r->>'hours_before',''), '') <> ''
     AND coalesce(nullif(r->>'fee_amount',''), '') <> '';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: set_booking_horse(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_booking_horse(p_booking_id uuid, p_horse_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;

  IF p_horse_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM horses h WHERE h.id = p_horse_id AND h.org_id = v_org AND h.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'horse % is not in your organization', p_horse_id;
  END IF;

  UPDATE bookings
     SET horse_id = p_horse_id
   WHERE id = p_booking_id
     AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking not found in this org';
  END IF;

  RETURN jsonb_build_object('booking_id', p_booking_id, 'horse_id', p_horse_id);
END;
$$;


--
-- Name: set_booking_log(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_booking_log(p_booking_id uuid, p_activities jsonb, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- LESSONFORM: was a direct UPDATE of bookings.activity_log. Now it writes the
  -- form instance, which writes that column as its projection. Same signature,
  -- same visible effect, one writer.
  PERFORM save_booking_form(p_booking_id, jsonb_build_object(
    'activities', coalesce(p_activities, '[]'::jsonb),
    'log_text',   coalesce(nullif(btrim(coalesce(p_text, '')), ''), '')));
END;
$$;


--
-- Name: set_business_hours(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_hours(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org(); e jsonb;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  FOR e IN SELECT * FROM jsonb_array_elements(p) LOOP
    INSERT INTO business_hours (org_id, weekday, open_time, close_time, closed)
      VALUES (v_org, (e->>'weekday')::smallint,
              coalesce((e->>'open')::time, '10:00'),
              coalesce((e->>'close')::time, '18:00'),
              coalesce((e->>'closed')::boolean, false))
    ON CONFLICT (org_id, weekday) DO UPDATE
      SET open_time = excluded.open_time, close_time = excluded.close_time, closed = excluded.closed;
  END LOOP;
END;
$$;


--
-- Name: set_calendar_settings(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_calendar_settings(p_reschedule_fee numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  INSERT INTO calendar_settings (org_id, reschedule_fee, updated_at)
    VALUES (current_org(), coalesce(p_reschedule_fee,0), now())
  ON CONFLICT (org_id) DO UPDATE SET reschedule_fee = excluded.reschedule_fee, updated_at = now();
END;
$$;


--
-- Name: set_contact_designation(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_designation(p_contact uuid, p_designation text, p_on boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff only'; END IF;
  IF p_on THEN
    INSERT INTO staff_designations (org_id, contact_id, designation)
    VALUES (v_org, p_contact, p_designation)
    ON CONFLICT (org_id, contact_id, designation) DO NOTHING;
  ELSE
    DELETE FROM staff_designations WHERE org_id = v_org AND contact_id = p_contact AND designation = p_designation;
  END IF;
END;
$$;


--
-- Name: set_contact_required_documents(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_required_documents(p_contact_id uuid, p_template_keys text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_n        integer;
  v_keep     text[] := coalesce(p_template_keys, '{}');
  v_removed  text[];
  v_evidence text[];
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'contact not found in this org';
  END IF;

  SELECT coalesce(array_agg(crd.template_key ORDER BY crd.template_key), '{}')
    INTO v_removed
    FROM contact_required_documents crd
   WHERE crd.contact_id = p_contact_id
     AND crd.template_key <> ALL (v_keep);

  -- §1 — an EXECUTED requirement is never removed by ANY path. Refuse, and say
  -- which one: it is the evidence that the obligation existed and was met.
  IF array_length(v_removed, 1) IS NOT NULL THEN
    SELECT coalesce(array_agg(d ORDER BY d), '{}') INTO v_evidence
      FROM unnest(v_removed) d WHERE contact_document_satisfied(p_contact_id, d);
    IF array_length(v_evidence, 1) IS NOT NULL THEN
      RAISE EXCEPTION
        'cannot remove %: satisfied by an executed document. Executed paperwork is '
        'the evidence that the obligation existed and was met, and is never removed.',
        array_to_string(v_evidence, ', ');
    END IF;
  END IF;

  -- CLOSEOUT §1.6: delete only what left the set and insert only what joined it.
  -- The old delete-all-reinsert wiped skip marks on every editor save.
  DELETE FROM contact_required_documents
   WHERE contact_id = p_contact_id
     AND template_key <> ALL (v_keep);
  INSERT INTO contact_required_documents (contact_id, template_key, org_id)
  SELECT p_contact_id, k, v_org FROM unnest(v_keep) k
  ON CONFLICT DO NOTHING;

  -- §3 — record it. This path carries no reason (it is a checkbox, not a
  -- narrowing), so it records the actor and the names and says so.
  IF array_length(v_removed, 1) IS NOT NULL THEN
    INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
    VALUES (auth.uid(), 'UPDATE', 'contact_required_documents', p_contact_id,
            jsonb_build_object('event', 'requirements_before_editor_save',
                               'removed_templates', to_jsonb(v_removed)),
            jsonb_build_object('event', 'requirements_removed_in_editor',
                               'contact_id', p_contact_id,
                               'removed_templates', to_jsonb(v_removed),
                               'kept_templates', to_jsonb(v_keep),
                               'removed_by', auth.uid(),
                               'reason', NULL));
  END IF;

  SELECT count(*) INTO v_n
    FROM contact_required_documents WHERE contact_id = p_contact_id;
  RETURN v_n;
END;
$$;


--
-- Name: set_contact_type(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_type(p_contact_id uuid, p_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF p_type IS NOT NULL AND p_type NOT IN ('LEAD','CONTACT','TEAM','DIRECTORY','VENDOR','PARTNER') THEN
    RAISE EXCEPTION 'contact_type must be LEAD, CONTACT, TEAM, DIRECTORY, VENDOR or PARTNER (got %)', p_type;
  END IF;

  UPDATE contacts
     SET contact_type = p_type, updated_at = now()
   WHERE id = p_contact_id
     AND org_id = current_org()
     AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'contact not found in this organisation: %', p_contact_id;
  END IF;
END
$$;


--
-- Name: FUNCTION set_contact_type(p_contact_id uuid, p_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_contact_type(p_contact_id uuid, p_type text) IS 'Move a contact between the person-pages. Staff only; validates against the same four values the column CHECK enforces, so a typo cannot invent a bucket.';


--
-- Name: set_contract_field(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contract_field(p_document_id uuid, p_field_key text, p_value text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org        uuid;
  v_state      text;
  v_recip_edit boolean;
  v_owner_role text;
  v_is_staff   boolean;
  v_is_orig    boolean;
  v_owns_role  boolean;
  v_can_fill   boolean;
  v_can_deal   boolean;
  v_row        contract_fields%ROWTYPE;
  v_confirmed  timestamptz;
  v_old_value  text;
  v_label      text;
  v_changed    boolean;
  v_format     text;
  v_violation  text;
  v_sec        text;
  v_counterpart text;
  v_is_elect   boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  -- disclosure content is imported from the horse record; refuse contract-side edits.
  IF p_field_key IN ('HORSE.KNOWN_CONDITIONS','HORSE.MEDICAL_HISTORY','HORSE.BEHAVIORAL_HISTORY','HORSE.INJURIES_TO_HUMANS','HORSE.INJURIES_TO_HORSE','HORSE.MEDICATIONS','HORSE.SUPPLEMENTS') THEN
    RAISE EXCEPTION 'this disclosure is imported from the horse record; edit it on the record';
  END IF;
  IF p_field_key LIKE 'HORSE.%\_GATE' AND disclosure_gate_locked(p_document_id, p_field_key) THEN
    RAISE EXCEPTION 'this disclosure gate is set from the horse record and cannot be changed here';
  END IF;

  SELECT org_id, workflow_state, recipient_editing, horse_section_confirmed_at
    INTO v_org, v_state, v_recip_edit, v_confirmed
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  SELECT owner_role, value, label INTO v_owner_role, v_old_value, v_label
    FROM contract_fields WHERE document_id = p_document_id AND field_key = p_field_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no field % on document %', p_field_key, p_document_id;
  END IF;

  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'document is locked (workflow_state=%): fields are read-only', v_state;
  END IF;

  -- THE CHANGES FREEZE (Notify model): an author may keep editing the document
  -- until a COUNTERPARTY has actually OPENED it. Requests freeze separately, per
  -- request, on being SEEN. Same predicate the Notify modal copy is built from.
  IF document_changes_frozen(p_document_id, NULL) THEN
    RAISE EXCEPTION 'this contract is fully executed — it can no longer be edited';
  END IF;

  -- U2.1c: money values must be canonical for their declared format BEFORE
  -- anything is written. A bare amount where the fee-schedule object belongs,
  -- a '$'-formatted string where a numeric belongs, or rendered prose saved
  -- back as a value are all rejected here rather than discovered later in a
  -- document that renders wrong.
  SELECT format_type INTO v_format
    FROM contract_field_defs fd
    JOIN documents d ON d.id = p_document_id
   WHERE fd.field_key = p_field_key
     AND fd.template_key = coalesce(
           (SELECT t.template_key FROM contract_templates t WHERE t.id = d.template_id),
           fd.template_key)
   LIMIT 1;
  IF v_format IS NOT NULL THEN
    v_violation := money_shape_violation(v_format, p_value);
    IF v_violation IS NOT NULL THEN
      RAISE EXCEPTION '%', v_violation;
    END IF;
  END IF;

  -- Decided before the write, while v_old_value still holds the prior value.
  v_changed := coalesce(v_old_value,'') IS DISTINCT FROM coalesce(p_value,'');

  v_is_staff := coalesce(has_staff_access() AND v_org = current_org(), false);
  v_is_orig  := false;  -- H1: originator no longer grants edit rights
  v_owns_role := EXISTS (SELECT 1 FROM caller_party_roles(p_document_id) r WHERE r = v_owner_role);

  SELECT bool_or(coalesce(c.can_fill, true)), bool_or(coalesce(c.can_edit_deal, true))
    INTO v_can_fill, v_can_deal
  FROM caller_party_roles(p_document_id) r
  LEFT JOIN document_party_controls c
    ON c.document_id = p_document_id AND c.party_role = r;
  v_can_fill := coalesce(v_can_fill, true);
  v_can_deal := coalesce(v_can_deal, false);

  -- D4(a): the two insurance responsibility elections are PARTY-EXCLUSIVE.
  -- An election is a party's own act; staff status does not stand in for it.
  -- FHE is itself the Lessor on these contracts, so without this carve-out
  -- FHE staff could make the Lessee's election for them.
  v_sec := CASE
             WHEN p_field_key IN ('TXN.GL_LESSEE_RESPONSIBLE','TXN.GL_NOT_REQUIRED') THEN 'GL'
             WHEN p_field_key IN ('TXN.MORT_LESSEE_RESPONSIBLE','TXN.MORT_NOT_REQUIRED') THEN 'MORT'
             WHEN p_field_key IN ('TXN.MED_LESSEE_RESPONSIBLE','TXN.MED_NOT_REQUIRED') THEN 'MED'
             ELSE NULL
           END;
  v_is_elect := v_sec IS NOT NULL;

  IF v_is_elect THEN
    -- Only the owning party may elect. No staff substitution.
    IF NOT (v_owns_role AND v_can_fill) THEN
      RAISE EXCEPTION
        'only the % may make this election (field %) — it is that party''s own act and cannot be made on their behalf',
        v_owner_role, p_field_key;
    END IF;
  ELSIF NOT (
       v_is_staff
    OR (v_owner_role = 'DEAL' AND v_can_deal)
    OR (v_owner_role <> 'DEAL' AND v_owns_role AND v_can_fill)
  ) THEN
    RAISE EXCEPTION 'not authorized to edit this field (owner_role=%)', v_owner_role;
  END IF;

  -- D4(b): mutual exclusivity. While one election is YES, the other cannot be
  -- set to YES. Unchecking your own re-opens the choice (spec).
  IF v_is_elect AND upper(coalesce(p_value,'')) = 'YES' THEN
    v_counterpart := CASE
      WHEN p_field_key LIKE '%_LESSEE_RESPONSIBLE' THEN 'TXN.' || v_sec || '_NOT_REQUIRED'
      ELSE 'TXN.' || v_sec || '_LESSEE_RESPONSIBLE'
    END;
    IF EXISTS (
      SELECT 1 FROM contract_fields
       WHERE document_id = p_document_id
         AND field_key = v_counterpart
         AND upper(coalesce(value,'')) = 'YES'
    ) THEN
      RAISE EXCEPTION
        'conflicting election: % is already accepted on this contract — the other party must uncheck it first',
        v_counterpart;
    END IF;
  END IF;

  -- An edit changes the text a signature attested to, so any standing
  -- signature is voided. A save that writes back the identical value is not
  -- an edit and must leave signatures intact. The signer is told at the next SEND.
  IF v_changed THEN
    PERFORM assert_not_signature_locked(p_document_id);
  END IF;

  UPDATE contract_fields
     SET value = p_value,
         entered_by_contact_id = current_contact_id(),
         entered_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key
   RETURNING * INTO v_row;

  IF p_field_key LIKE 'HORSE.%' AND v_confirmed IS NOT NULL THEN
    UPDATE documents
       SET horse_section_confirmed_at = NULL,
           horse_section_confirmed_by = NULL
     WHERE id = p_document_id;
  END IF;

  -- (horse writeback removed 2026-08-03: record values are edited at their
  -- source, never written back from a document. Deal plan L10.)

  -- audit: only log an actual change
  IF v_changed THEN
    PERFORM log_contract_change(p_document_id, 'field_value', p_field_key, v_label,
                                v_owner_role, v_old_value, p_value, '{}'::jsonb);
  END IF;

  -- co-buyer teardown: flipping the enable to NO removes the co-buyer signer
  -- and party rows (signatures were already voided by the change above).
  IF v_changed AND p_field_key = 'TXN.CO_BUYER_ENABLED'
     AND upper(coalesce(p_value,'')) = 'NO' THEN
    PERFORM remove_document_co_buyer(p_document_id);
  END IF;

  -- D5: the elections drive the unresolved-state notifications. Called after
  -- the write so it observes the new state. Never modifies status values.
  IF v_is_elect OR p_field_key LIKE 'TXN.%_LESSOR_STATUS' OR p_field_key LIKE 'TXN.%_LESSEE_STATUS' THEN
    PERFORM insurance_resolution_sync(p_document_id);
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id, 'document_id', v_row.document_id, 'field_key', v_row.field_key,
    'owner_role', v_row.owner_role, 'value', v_row.value, 'value_type', v_row.value_type,
    'entered_by_contact_id', v_row.entered_by_contact_id, 'entered_at', v_row.entered_at);
END;
$_$;


--
-- Name: FUNCTION set_contract_field(p_document_id uuid, p_field_key text, p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_contract_field(p_document_id uuid, p_field_key text, p_value text) IS 'THE ownership-enforcing field write. Allowed only when the document is editable/editing AND the caller is (a) staff, or (b) for a personal/horse field, the party whose party_role = the field''s owner_role, or (c) for a DEAL field, the originator always / the counterparty only when documents.recipient_editing. Nobody edits another party''s personal fields. Stamps entered_by/entered_at; returns the updated field as jsonb.';


--
-- Name: set_dashboard_focus(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_dashboard_focus(p_user_id uuid, p_focus text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_target uuid;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  IF p_focus IS NOT NULL AND p_focus NOT IN ('trainer', 'business') THEN
    RAISE EXCEPTION 'unknown dashboard view: %', p_focus;
  END IF;

  -- Self, or anyone on my own org's roster if I am an admin. The org test is
  -- not decoration: it is what keeps the platform owner (org_id NULL, D1a) from
  -- reaching a tenant's rows, and `coalesce(..., false)` is what stops a NULL
  -- comparison being read as permission (the D1a repair pattern).
  SELECT p.user_id INTO v_target
    FROM profiles p
   WHERE p.user_id = p_user_id
     AND coalesce(p.org_id = v_org, false)
     AND (p.user_id = auth.uid() OR coalesce(is_admin(), false));

  IF v_target IS NULL THEN
    RAISE EXCEPTION 'not permitted to change that account''s default view';
  END IF;

  UPDATE profiles SET dashboard_focus = p_focus, updated_at = now()
   WHERE user_id = v_target;

  RETURN coalesce(p_focus, 'default');
END;
$$;


--
-- Name: FUNCTION set_dashboard_focus(p_user_id uuid, p_focus text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_dashboard_focus(p_user_id uuid, p_focus text) IS 'DASHBOARDBUILD §2.2 — the owner-editable default dashboard view (D13). Reached from Team -> the member panel -> "Default dashboard". The on-dashboard toggle does NOT call this: a session switch must not silently move where you land.';


--
-- Name: set_document_co_buyer(uuid, uuid, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_document_co_buyer(p_document_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address_line1 text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc      documents%ROWTYPE;
  v_contact  uuid := p_contact_id;
  v_email    text := lower(nullif(btrim(coalesce(p_email, '')), ''));
  v_next     int;
  v_primary  uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to set a co-buyer'; END IF;

  SELECT * INTO v_doc FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  IF v_doc.workflow_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this contract can no longer be edited';
  END IF;

  SELECT contact_id INTO v_primary FROM document_parties
   WHERE document_id = p_document_id AND party_role = 'BUYER'
   ORDER BY signer_order NULLS LAST, id LIMIT 1;
  IF v_primary IS NULL THEN RAISE EXCEPTION 'the document has no primary buyer party'; END IF;

  -- hand-entry fallback: create a contact record from the entry (deduped on
  -- email, the same way inbound capture creates contacts elsewhere)
  IF v_contact IS NULL THEN
    IF v_email IS NOT NULL THEN
      SELECT id INTO v_contact FROM contacts
       WHERE lower(email) = v_email AND org_id = v_doc.org_id AND deleted_at IS NULL
       ORDER BY created_at LIMIT 1;
    END IF;
    IF v_contact IS NULL THEN
      IF coalesce(btrim(coalesce(p_first_name,'') || coalesce(p_last_name,'')), '') = '' THEN
        RAISE EXCEPTION 'a contact or a name is required for the co-buyer';
      END IF;
      INSERT INTO contacts (org_id, first_name, last_name, email, phone,
                            address_line1, city, state, postal_code, contact_type, notes)
      VALUES (v_doc.org_id,
              nullif(btrim(coalesce(p_first_name,'')), ''),
              nullif(btrim(coalesce(p_last_name,'')), ''),
              v_email,
              nullif(btrim(coalesce(p_phone,'')), ''),
              nullif(btrim(coalesce(p_address_line1,'')), ''),
              nullif(btrim(coalesce(p_city,'')), ''),
              nullif(btrim(coalesce(p_state,'')), ''),
              nullif(btrim(coalesce(p_postal_code,'')), ''),
              'CONTACT',
              'Created as co-buyer on contract document ' || p_document_id::text)
      RETURNING id INTO v_contact;
    END IF;
  END IF;

  IF v_contact = v_primary THEN
    RAISE EXCEPTION 'the co-buyer must be a different person than the buyer';
  END IF;

  -- a second BUYER party row with the next signer_order (unique on doc+contact+role)
  SELECT coalesce(max(signer_order), 0) + 1 INTO v_next
    FROM document_parties WHERE document_id = p_document_id;

  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_doc.org_id, v_doc.contract_id, v_contact, 'BUYER', true, v_next)
    ON CONFLICT (contract_id, contact_id, party_role) DO NOTHING;
  INSERT INTO document_parties (org_id, document_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_doc.org_id, p_document_id, v_contact, 'BUYER', true, v_next)
    ON CONFLICT (document_id, contact_id, party_role) DO NOTHING;

  -- adding a signer changes what the signatures attest to
  PERFORM assert_not_signature_locked(p_document_id);

  UPDATE contract_fields SET value = 'YES', updated_at = now()
   WHERE document_id = p_document_id AND field_key = 'TXN.CO_BUYER_ENABLED'
     AND coalesce(btrim(value), '') <> 'YES';

  PERFORM fill_party_fields_from_contacts(p_document_id);
  PERFORM remerge_contract_from_clauses(p_document_id);

  RETURN jsonb_build_object('contact_id', v_contact, 'signer_order', v_next);
END;
$$;


--
-- Name: set_document_disclosure_structured(uuid, public.horses); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_document_disclosure_structured(p_document_id uuid, v_horse public.horses) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE sec text;
BEGIN
  FOREACH sec IN ARRAY ARRAY['KNOWN_CONDITIONS','MEDICAL_HISTORY','BEHAVIORAL_HISTORY','INJURIES_TO_HORSE','MEDICATIONS','SUPPLEMENTS'] LOOP
    UPDATE contract_fields
       SET structured = horse_section_entries(v_horse, sec), updated_at = now()
     WHERE document_id = p_document_id AND field_key = 'HORSE.' || sec;
  END LOOP;
END $$;


--
-- Name: set_document_effective_date(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_document_effective_date(p_document_id uuid, p_effective_date date, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org    uuid := current_org();
  v_old    date;
  v_status text;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to correct the effective date';
  END IF;
  IF p_effective_date IS NULL THEN
    RAISE EXCEPTION 'an effective date is required';
  END IF;

  SELECT effective_date, status INTO v_old, v_status
    FROM documents
   WHERE id = p_document_id AND org_id = v_org AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'document not found in this organisation';
  END IF;

  UPDATE documents SET effective_date = p_effective_date, updated_at = now()
   WHERE id = p_document_id;

  -- D19: the reason, the old and new value, the actor and the time, kept. The
  -- audit_logs.action CHECK allows only INSERT/UPDATE/DELETE, so the correction is
  -- an UPDATE whose new_value carries the reason and the field changed, which is
  -- what makes it answerable later (the generic trigger row has no reason).
  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (auth.uid(), 'UPDATE', 'documents', p_document_id,
          jsonb_build_object('effective_date', v_old),
          jsonb_build_object('effective_date', p_effective_date, 'reason', v_reason,
                             'change', 'effective_date_corrected'));

  RETURN jsonb_build_object('document_id', p_document_id,
                            'effective_date', p_effective_date,
                            'previous', v_old);
END
$$;


--
-- Name: set_document_party_archived(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_document_party_archived(p_document_id uuid, p_archive boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_me uuid := current_contact_id();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT caller_is_document_party_or_staff(p_document_id) THEN RAISE EXCEPTION 'not authorized'; END IF;

  IF p_archive THEN
    INSERT INTO document_party_archives (document_id, contact_id, org_id)
    VALUES (p_document_id, v_me, v_org)
    ON CONFLICT (document_id, contact_id) DO UPDATE SET archived_at = now();
  ELSE
    DELETE FROM document_party_archives WHERE document_id = p_document_id AND contact_id = v_me;
  END IF;
END;
$$;


--
-- Name: set_document_party_hidden(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_document_party_hidden(p_document_id uuid, p_hidden boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_cid uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_cid := current_contact_id();
  IF v_cid IS NULL THEN RAISE EXCEPTION 'no contact identity for the caller'; END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  IF coalesce(p_hidden, true) THEN
    INSERT INTO document_party_hidden (document_id, contact_id, org_id)
    VALUES (p_document_id, v_cid, v_org)
    ON CONFLICT (document_id, contact_id) DO NOTHING;
  ELSE
    DELETE FROM document_party_hidden
     WHERE document_id = p_document_id AND contact_id = v_cid;
  END IF;

  -- the document itself is untouched — prove it to the caller
  RETURN jsonb_build_object(
    'hidden', coalesce(p_hidden, true),
    'document_still_exists', EXISTS (SELECT 1 FROM documents WHERE id = p_document_id));
END;
$$;


--
-- Name: set_field_control_override(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_field_control_override(p_document_id uuid, p_field_key text, p_override jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing') THEN RAISE EXCEPTION 'document is not editable'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))) THEN
    RAISE EXCEPTION 'not authorized to set field controls';
  END IF;
  UPDATE contract_fields
     SET control_override = CASE WHEN p_override = '{}'::jsonb OR p_override IS NULL THEN NULL ELSE p_override END,
         updated_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key;
END;
$$;


--
-- Name: set_field_included(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_field_included(p_document_id uuid, p_field_key text, p_included boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text;
BEGIN
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'document is not editable'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id())) THEN
    RAISE EXCEPTION 'not authorized for this document';
