END;
$$;


--
-- Name: set_field_na(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_field_na(p_document_id uuid, p_field_key text, p_is_na boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text;
BEGIN
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing') THEN RAISE EXCEPTION 'document is not editable'; END IF;
  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id())) THEN
    RAISE EXCEPTION 'not authorized for this document';
  END IF;
  UPDATE contract_fields
     SET is_na = p_is_na, value = CASE WHEN p_is_na THEN 'N/A' ELSE value END, updated_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key;
END;
$$;


--
-- Name: set_field_responsibility(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_field_responsibility(p_document_id uuid, p_field_key text, p_responsibility jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing') THEN RAISE EXCEPTION 'document is not editable'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    IF NOT EXISTS (SELECT 1 FROM document_parties dp WHERE dp.document_id = p_document_id AND dp.contact_id = current_contact_id()) THEN
      RAISE EXCEPTION 'not authorized for this document';
    END IF;
  END IF;
  UPDATE contract_fields
     SET responsibility = p_responsibility,
         value = trim(coalesce(p_responsibility ->> 'party','')
                 || CASE WHEN p_responsibility -> 'split' IS NOT NULL
                    THEN ' (Owner ' || coalesce(p_responsibility #>> '{split,owner}','') || '% / Lessee '
                         || coalesce(p_responsibility #>> '{split,lessee}','') || '%)'
                    WHEN nullif(p_responsibility ->> 'detail','') IS NOT NULL
                    THEN ': ' || (p_responsibility ->> 'detail') ELSE '' END),
         is_na = false,
         entered_by_contact_id = current_contact_id(), entered_at = now(), updated_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key;
END;
$$;


--
-- Name: set_field_structured(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_field_structured(p_document_id uuid, p_field_key text, p_structured jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org        uuid;
  v_state      text;
  v_recip_edit boolean;
  v_confirmed  timestamptz;
  v_owner_role text;
  v_is_staff   boolean;
  v_is_orig    boolean;
  v_owns_role  boolean;
  v_can_fill   boolean;
  v_can_deal   boolean;
  v_label      text;
  v_old_prose  text;
  v_new_prose  text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id, workflow_state, recipient_editing, horse_section_confirmed_at
    INTO v_org, v_state, v_recip_edit, v_confirmed
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  SELECT owner_role, label, value INTO v_owner_role, v_label, v_old_prose
    FROM contract_fields WHERE document_id = p_document_id AND field_key = p_field_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no field % on document %', p_field_key, p_document_id;
  END IF;

  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'document is locked (workflow_state=%): fields are read-only', v_state;
  END IF;

  -- THE CHANGES FREEZE (Notify model): an author may keep editing the document
  -- until a COUNTERPARTY has actually OPENED it. Requests freeze separately, per
  -- request, on being SEEN. Same predicate the Notify modal copy is built from.
  IF document_changes_frozen(p_document_id, NULL) THEN
    RAISE EXCEPTION 'this contract is fully executed — it can no longer be edited';
  END IF;

  v_is_staff  := coalesce(has_staff_access() AND v_org = current_org(), false);
  v_is_orig   := false;  -- H1: originator no longer grants edit rights
  v_owns_role := EXISTS (SELECT 1 FROM caller_party_roles(p_document_id) r WHERE r = v_owner_role);

  SELECT bool_or(coalesce(c.can_fill, true)), bool_or(coalesce(c.can_edit_deal, true))
    INTO v_can_fill, v_can_deal
  FROM caller_party_roles(p_document_id) r
  LEFT JOIN document_party_controls c
    ON c.document_id = p_document_id AND c.party_role = r;
  v_can_fill := coalesce(v_can_fill, true);
  v_can_deal := coalesce(v_can_deal, false);

  IF NOT (
       v_is_staff
    OR (v_owner_role = 'DEAL' AND v_can_deal)
    OR (v_owner_role <> 'DEAL' AND v_owns_role AND v_can_fill)
  ) THEN
    RAISE EXCEPTION 'not authorized to edit this field (owner_role=%)', v_owner_role;
  END IF;

  UPDATE contract_fields
     SET structured = CASE WHEN p_structured = '{}'::jsonb THEN NULL ELSE p_structured END,
         updated_at = now()
   WHERE document_id = p_document_id AND field_key = p_field_key;

  IF p_field_key LIKE 'HORSE.%' AND v_confirmed IS NOT NULL THEN
    UPDATE documents
       SET horse_section_confirmed_at = NULL,
           horse_section_confirmed_by = NULL
     WHERE id = p_document_id;
  END IF;

  PERFORM recompose_document_fields(p_document_id);
  PERFORM remerge_contract_body(p_document_id);

  -- audit: capture the recomposed prose after the write; only log a real change
  SELECT value INTO v_new_prose FROM contract_fields
    WHERE document_id = p_document_id AND field_key = p_field_key;
  IF coalesce(v_old_prose,'') IS DISTINCT FROM coalesce(v_new_prose,'') THEN
    -- An edit changes the text a signature attested to, so any standing
    -- signature is voided. Restructuring that recomposes to identical prose
    -- is not an edit and leaves signatures intact.
    PERFORM assert_not_signature_locked(p_document_id);
    PERFORM log_contract_change(p_document_id, 'field_structured', p_field_key, v_label,
                                v_owner_role, v_old_prose, v_new_prose,
                                jsonb_build_object('structured', p_structured));
  END IF;
END;
$$;


--
-- Name: set_form_field_options(text, text, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_form_field_options(p_form_key text, p_field_key text, p_options text[], p_from_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_base record; v_new jsonb;
begin
  if not is_admin() then raise exception 'admin only'; end if;
  if p_options is null or array_length(p_options, 1) is null then
    raise exception 'a menu needs at least one option';
  end if;
  select * into v_base from _form_edit_base(p_form_key, p_from_version);
  if v_base.schema is null then
    raise exception 'unknown form % (version %)', p_form_key, p_from_version;
  end if;

  select jsonb_build_object('sections', jsonb_agg(sec order by sec_i)) into v_new
    from (
      select sec_i, jsonb_set(s, '{fields}', (
               select jsonb_agg(
                        case when f->>'key' = p_field_key and f ? 'options'
                             then jsonb_set(f, '{options}', to_jsonb(p_options))
                             else f end order by f_i)
                 from jsonb_array_elements(s->'fields') with ordinality as t(f, f_i))) as sec
        from jsonb_array_elements(v_base.schema->'sections') with ordinality as q(s, sec_i)
    ) x;

  return save_form_definition_version(
    p_form_key, v_base.title, v_base.audience, v_base.purpose, v_new, p_from_version);
end;
$$;


--
-- Name: set_form_required(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_form_required(p_form_key text, p_required jsonb, p_from_version integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_base record; v_out jsonb := '{"sections": []}'::jsonb;
  sec jsonb; fld jsonb; new_fields jsonb; v_n integer := 0;
begin
  if not is_admin() then raise exception 'admin access required'; end if;
  select * into v_base from _form_edit_base(p_form_key, p_from_version);
  if v_base.schema is null then
    raise exception 'unknown form: % (version %)', p_form_key, p_from_version;
  end if;

  for sec in select * from jsonb_array_elements(v_base.schema -> 'sections') loop
    new_fields := '[]'::jsonb;
    for fld in select * from jsonb_array_elements(sec -> 'fields') loop
      if p_required ? (fld ->> 'key') then
        fld := jsonb_set(fld, '{required}', p_required -> (fld ->> 'key'));
        v_n := v_n + 1;
      end if;
      new_fields := new_fields || fld;
    end loop;
    v_out := jsonb_set(v_out, '{sections}',
      (v_out -> 'sections') || jsonb_set(sec, '{fields}', new_fields));
  end loop;

  perform save_form_definition_version(
    p_form_key, v_base.title, v_base.audience, v_base.purpose, v_out, p_from_version);
  return v_n;
end;
$$;


--
-- Name: set_horse_current_location(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_horse_current_location(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_horse uuid := (p ->> 'horse_id')::uuid; v_id uuid;
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = v_horse AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR caller_owns_horse(v_horse)) THEN RAISE EXCEPTION 'not authorized'; END IF;

  UPDATE horse_locations SET end_on = coalesce((nullif(p ->> 'start_on',''))::date, current_date)
   WHERE horse_id = v_horse AND end_on IS NULL;

  INSERT INTO horse_locations
    (org_id, horse_id, name, address_line1, city, state, postal, keeping_spots, notes, start_on, end_on)
  VALUES (v_org, v_horse, nullif(p ->> 'name',''), nullif(p ->> 'address_line1',''),
          nullif(p ->> 'city',''), nullif(p ->> 'state',''), nullif(p ->> 'postal',''),
          coalesce(p -> 'keeping_spots', '[]'::jsonb), nullif(p ->> 'notes',''),
          (nullif(p ->> 'start_on',''))::date, NULL)
  RETURNING id INTO v_id;

  IF coalesce((p ->> 'update_known')::boolean, false) AND nullif(p ->> 'name','') IS NOT NULL THEN
    UPDATE locations SET address_line1 = nullif(p ->> 'address_line1',''),
           city = nullif(p ->> 'city',''), state = nullif(p ->> 'state',''), postal = nullif(p ->> 'postal','')
     WHERE org_id = v_org AND lower(name) = lower(p ->> 'name');
  END IF;
  RETURN v_id;
END;
$$;


--
-- Name: set_horse_locations(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_horse_locations(p_horse_id uuid, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_me uuid := current_contact_id(); v_staff boolean := has_staff_access();
  v_curr jsonb := coalesce(p_payload -> 'current', p_payload -> 'home');
  v_vacc jsonb := p_payload -> 'vaccinations';
  v_name text := nullif(btrim(v_curr ->> 'name'), '');
  v_update_known boolean := coalesce((p_payload ->> 'update_known')::boolean, false);
  v_open horse_locations%ROWTYPE;
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT coalesce(v_staff AND v_org = current_org(), false) THEN
    IF v_me IS NULL OR v_me NOT IN (
      (SELECT current_owner_contact_id FROM horses WHERE id = p_horse_id),
      (SELECT lessee_contact_id FROM horses WHERE id = p_horse_id)
    ) THEN RAISE EXCEPTION 'not authorized for this horse'; END IF;
  END IF;

  IF v_name IS NOT NULL THEN
    SELECT * INTO v_open FROM horse_locations
     WHERE horse_id = p_horse_id AND end_on IS NULL ORDER BY created_at DESC LIMIT 1;
    IF v_open.id IS NOT NULL THEN
      UPDATE horse_locations SET
        name = v_name,
        address_line1 = nullif(btrim(v_curr ->> 'address_line1'),''),
        city = nullif(btrim(v_curr ->> 'city'),''),
        state = nullif(btrim(v_curr ->> 'state'),''),
        postal = nullif(btrim(v_curr ->> 'postal'),''),
        sub_location = nullif(btrim(v_curr ->> 'sub_location'),''),
        keeping_spots = coalesce(v_curr -> 'keeping_spots', '[]'::jsonb),
        notes = nullif(btrim(v_curr ->> 'notes'),'')
      WHERE id = v_open.id;
    ELSE
      INSERT INTO horse_locations
        (org_id, horse_id, name, address_line1, city, state, postal, sub_location, keeping_spots, notes, start_on, end_on)
      VALUES (v_org, p_horse_id, v_name, nullif(btrim(v_curr ->> 'address_line1'),''),
              nullif(btrim(v_curr ->> 'city'),''), nullif(btrim(v_curr ->> 'state'),''),
              nullif(btrim(v_curr ->> 'postal'),''), nullif(btrim(v_curr ->> 'sub_location'),''),
              coalesce(v_curr -> 'keeping_spots','[]'::jsonb),
              nullif(btrim(v_curr ->> 'notes'),''), NULL, NULL);
    END IF;

    IF v_update_known THEN
      UPDATE locations SET
          address_line1 = nullif(btrim(v_curr ->> 'address_line1'),''),
          city  = nullif(btrim(v_curr ->> 'city'),''),
          state = nullif(btrim(v_curr ->> 'state'),''),
          postal= nullif(btrim(v_curr ->> 'postal'),'')
       WHERE org_id = v_org AND lower(name) = lower(v_name);
    END IF;
  END IF;

  UPDATE horses SET
      vaccinations = CASE WHEN v_vacc IS NOT NULL THEN v_vacc ELSE vaccinations END,
      updated_at = now()
   WHERE id = p_horse_id;
END;
$$;


--
-- Name: set_horse_medications(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_horse_medications(p_horse_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org uuid; v_me uuid := current_contact_id(); v_staff boolean := has_staff_access();
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT coalesce(v_staff AND v_org = current_org(), false) THEN
    IF v_me IS NULL OR v_me NOT IN (
      (SELECT current_owner_contact_id FROM horses WHERE id = p_horse_id),
      (SELECT lessee_contact_id FROM horses WHERE id = p_horse_id)
    ) THEN RAISE EXCEPTION 'not authorized for this horse'; END IF;
  END IF;

  -- replace-all: soft-delete the current set, then insert the incoming rows in
  -- ONE statement. A per-row loop fired the statement-level doc-sync trigger once
  -- per row; this fires it once.
  UPDATE horse_medications SET deleted_at = now() WHERE horse_id = p_horse_id AND deleted_at IS NULL;

  IF jsonb_typeof(p_items) = 'array' THEN
    INSERT INTO horse_medications (
      org_id, horse_id, kind, sort_order, name, dosage, instructions, cost,
      supplier_website, supplier_phone, rx_info, order_units, days_supply,
      purpose, frequency, cost_per_dose, rx_required)
    SELECT
      v_org, p_horse_id,
      CASE WHEN upper(coalesce(e.item ->> 'kind','MEDICATION')) = 'SUPPLEMENT' THEN 'SUPPLEMENT' ELSE 'MEDICATION' END,
      (e.ord - 1)::int,
      nullif(btrim(e.item ->> 'name'),''), nullif(btrim(e.item ->> 'dosage'),''), nullif(btrim(e.item ->> 'instructions'),''),
      nullif(regexp_replace(coalesce(e.item ->> 'cost',''), '[$,\s]', '', 'g'), '')::numeric,
      nullif(btrim(e.item ->> 'supplier_website'),''), nullif(btrim(e.item ->> 'supplier_phone'),''),
      -- rx_info is meaningful only for medications
      CASE WHEN upper(coalesce(e.item ->> 'kind','MEDICATION')) = 'SUPPLEMENT' THEN NULL ELSE nullif(btrim(e.item ->> 'rx_info'),'') END,
      nullif(btrim(e.item ->> 'order_units'),''), nullif(btrim(e.item ->> 'days_supply'),''),
      nullif(btrim(e.item ->> 'purpose'),''), nullif(btrim(e.item ->> 'frequency'),''),
      nullif(btrim(e.item ->> 'cost_per_dose'),''),
      CASE WHEN e.item ? 'rx_required' THEN (e.item ->> 'rx_required')::boolean ELSE NULL END
    FROM jsonb_array_elements(p_items) WITH ORDINALITY AS e(item, ord)
    WHERE coalesce(nullif(btrim(e.item ->> 'name'),''),'') <> '';
  END IF;
END;
$_$;


--
-- Name: set_intake_requirement(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_intake_requirement(p_channel text, p_field_key text, p_required boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'operator access required';
  END IF;
  INSERT INTO intake_requirements (org_id, channel, field_key, required, updated_at)
    VALUES (v_org, p_channel, p_field_key, p_required, now())
  ON CONFLICT (org_id, channel, field_key)
    DO UPDATE SET required = excluded.required, updated_at = now();
END;
$$;


--
-- Name: set_lessee_entry_hidden(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lessee_entry_hidden(p_id uuid, p_hidden boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horse_lessee_entries e SET hidden_by_owner = p_hidden, updated_at = now()
   WHERE e.id = p_id AND e.org_id = current_org()
     AND (has_staff_access() OR EXISTS (
       SELECT 1 FROM horses h WHERE h.id = e.horse_id AND h.current_owner_contact_id = current_contact_id()));
  IF NOT FOUND THEN RAISE EXCEPTION 'only the horse owner or staff may hide a lessee entry'; END IF;
END;
$$;


--
-- Name: set_lesson_progress_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lesson_progress_note(p_session_id uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- LESSONFORM: as above, for the rider-visible report (bookings.notes).
  PERFORM save_booking_form(p_session_id,
    jsonb_build_object('report', coalesce(nullif(btrim(coalesce(p_note, '')), ''), '')));
END;
$$;


--
-- Name: set_menu_value(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_menu_value(p_key text, p_code text, p_display_name text DEFAULT NULL::text, p_active boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_name text := nullif(btrim(coalesce(p_display_name, '')), '');
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_display_name IS NOT NULL AND v_name IS NULL THEN
    RAISE EXCEPTION 'a menu value needs a name';
  END IF;

  IF p_key = 'horse_breeds' THEN
    UPDATE horse_breeds SET display_name = coalesce(v_name, display_name),
                            active = coalesce(p_active, active) WHERE code = p_code;
  ELSIF p_key = 'horse_colors' THEN
    UPDATE horse_colors SET display_name = coalesce(v_name, display_name),
                            active = coalesce(p_active, active) WHERE code = p_code;
  ELSE
    UPDATE lookup_options SET display_name = coalesce(v_name, display_name),
                              active = coalesce(p_active, active)
     WHERE lookup_key = p_key AND code = p_code;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'no value % in menu %', p_code, p_key; END IF;
END;
$$;


--
-- Name: set_my_onboarding_horses(uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid;
  v_user    uuid := auth.uid();
  v_org     uuid;
  v_doc     record;
  v_i       integer;
  v_hid     uuid;
  v_bound   integer := 0;
  v_docs    integer := 0;
  v_notes   integer := 0;
  v_name    text;
  v_purch   uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_contact := current_contact_id();
  IF v_contact IS NULL THEN RAISE EXCEPTION 'no contact record for this account'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = v_contact;

  -- Ownership fence: every id must be a horse this contact owns or leases.
  IF p_horse_ids IS NOT NULL THEN
    FOR v_i IN 1 .. coalesce(array_length(p_horse_ids, 1), 0) LOOP
      IF NOT EXISTS (
        SELECT 1 FROM horses h
         WHERE h.id = p_horse_ids[v_i] AND h.deleted_at IS NULL
           AND (h.current_owner_contact_id = v_contact OR h.lessee_contact_id = v_contact)
      ) THEN
        RAISE EXCEPTION 'you can only attach your own horse';
      END IF;
    END LOOP;
  END IF;

  -- Bind to every OPEN horse document this member holds. Executed documents are
  -- never touched — a signed release is evidence and its horse set is frozen.
  --
  -- Binding replaces the whole set (the member's choice on this pass is the
  -- truth) and then REGENERATES the document, because the body was composed for
  -- whatever horse it previously named. Regeneration goes through
  -- generate_my_onboarding_documents' own path: we soft-delete the stale copy
  -- and let generate_document recompose with the full set, which is the single
  -- composition path everything else uses.
  FOR v_doc IN
    SELECT d.id, t.template_key
      FROM documents d
      JOIN contract_templates t ON t.id = d.template_id
     WHERE d.contact_id = v_contact
       AND d.deleted_at IS NULL
       AND t.template_key IN ('HORSE_EMERGENCY_VET','RELEASE_HORSE_CARE')
       AND d.status <> 'EXECUTED'
       AND d.workflow_state IN ('editable','editing','in_review')
  LOOP
    v_docs := v_docs + 1;
    DELETE FROM document_horses WHERE document_id = v_doc.id;
    FOR v_i IN 1 .. coalesce(array_length(p_horse_ids, 1), 0) LOOP
      INSERT INTO document_horses (org_id, document_id, horse_id, position)
        VALUES (v_org, v_doc.id, p_horse_ids[v_i], v_i)
        ON CONFLICT (document_id, horse_id) DO UPDATE SET position = EXCLUDED.position;
      v_bound := v_bound + 1;
    END LOOP;
  END LOOP;

  -- Recompose: soft-delete the now-stale bodies and regenerate them bound to the
  -- full set. generate_my_onboarding_documents captures the set we just wrote
  -- (per template key) and replays it into generate_document.
  IF v_docs > 0 AND coalesce(array_length(p_horse_ids, 1), 0) > 0 THEN
    PERFORM generate_my_onboarding_documents();
  END IF;

  -- the purchase keeps carrying the PRIMARY horse (unchanged behaviour)
  IF coalesce(array_length(p_horse_ids, 1), 0) > 0 THEN
    SELECT pu.id INTO v_purch FROM purchases pu
      WHERE pu.buyer_contact_id = v_contact AND pu.deleted_at IS NULL
      ORDER BY pu.created_at DESC LIMIT 1;
    IF v_purch IS NOT NULL THEN
      UPDATE purchases SET horse_id = p_horse_ids[1] WHERE id = v_purch;
    END IF;
  END IF;

  -- THE SOFT DEFERRED REMINDER — one per deferred horse, never duplicated while
  -- an undismissed one is already sitting there.
  FOR v_i IN 1 .. coalesce(array_length(p_deferred_horse_ids, 1), 0) LOOP
    v_hid := p_deferred_horse_ids[v_i];
    CONTINUE WHEN NOT EXISTS (
      SELECT 1 FROM horses h WHERE h.id = v_hid AND h.deleted_at IS NULL
        AND (h.current_owner_contact_id = v_contact OR h.lessee_contact_id = v_contact));
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM notifications n
       WHERE n.user_id = v_user AND n.kind = 'horse_record_task'
         AND n.read_at IS NULL
         AND n.link = '/app/horse-intake?horse=' || v_hid::text);
    SELECT coalesce(nullif(btrim(h.nickname), ''), h.registered_name, 'your horse')
      INTO v_name FROM horses h WHERE h.id = v_hid;
    INSERT INTO notifications (org_id, user_id, kind, title, body, link)
      VALUES (v_org, v_user, 'horse_record_task',
        'Finish ' || v_name || '''s record',
        'You set ' || v_name || ' aside for later. Their record still needs a few '
        || 'details before the horse paperwork can cover them. Pick up where you '
        || 'left off whenever you are ready — nothing else is waiting on it.',
        '/app/horse-intake?horse=' || v_hid::text);
    v_notes := v_notes + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'documents', v_docs, 'bindings', v_bound, 'deferred_reminders', v_notes);
END;
$$;


--
-- Name: FUNCTION set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_my_onboarding_horses(p_horse_ids uuid[], p_deferred_horse_ids uuid[]) IS 'Member path: bind an ordered horse set to BOTH open horse documents (combined signing), attach the primary to the purchase, and raise the soft dashboard reminder for horses the member deferred. Own horses only.';


--
-- Name: set_my_standing_schedule(uuid, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_standing_schedule(p_purchase_item_id uuid, p_slots jsonb, p_duration_minutes integer DEFAULT 60, p_horse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_pi     purchase_items%ROWTYPE;
  v_pu     purchases%ROWTYPE;
  v_off    offerings%ROWTYPE;
  v_client uuid;
  v_freq   int;
  v_slot   jsonb;
  v_day    text;
  v_time   text;
  v_days   text[] := '{}';
  v_times  jsonb  := '{}'::jsonb;
  v_res    jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  SELECT * INTO v_off FROM offerings WHERE id = v_pi.offering_id;
  IF NOT FOUND OR v_off.config_kind <> 'recurring' THEN
    RAISE EXCEPTION 'that purchase is not a weekly plan';
  END IF;

  SELECT id INTO v_client FROM clients WHERE contact_id = v_pu.buyer_contact_id AND deleted_at IS NULL;
  IF NOT (has_staff_access() OR (v_client IS NOT NULL AND v_client = current_client_id())) THEN
    RAISE EXCEPTION 'not your plan';
  END IF;

  IF p_slots IS NULL OR jsonb_typeof(p_slots) <> 'array' THEN
    RAISE EXCEPTION 'pick a day and a time for each weekly session';
  END IF;

  v_freq := greatest(coalesce(v_off.weekly_frequency, 1), 1);
  IF jsonb_array_length(p_slots) <> v_freq THEN
    RAISE EXCEPTION 'this plan is % session(s) a week — pick a day and time for each',
      v_freq;
  END IF;

  FOR v_slot IN SELECT * FROM jsonb_array_elements(p_slots) LOOP
    v_day  := initcap(btrim(coalesce(v_slot->>'day', '')));
    v_time := btrim(coalesce(v_slot->>'time', ''));
    IF v_day NOT IN ('Mon','Tue','Wed','Thu','Fri','Sat','Sun') THEN
      RAISE EXCEPTION 'day must be one of Mon/Tue/Wed/Thu/Fri/Sat/Sun, got %', v_slot->>'day';
    END IF;
    IF v_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RAISE EXCEPTION 'a time looks like 16:00, got %', v_slot->>'time';
    END IF;
    IF v_day = ANY (v_days) THEN
      RAISE EXCEPTION 'pick a different day for each weekly session — % is already taken', v_day;
    END IF;
    v_days  := v_days || v_day;
    v_times := v_times || jsonb_build_object(v_day, v_time);
  END LOOP;

  -- the incumbent day writer (it also re-prices the line and re-trues this month)
  PERFORM set_recurring_days(p_purchase_item_id, v_days, NULL, true);

  UPDATE purchase_items
     SET config = coalesce(config, '{}'::jsonb) || jsonb_build_object(
           'recurring_times',  v_times,
           -- the incumbent scalar keeps pointing at the first day's time, so every
           -- reader written before per-day times still resolves to something true
           'recurring_time',   v_times->>v_days[1],
           'duration_minutes', greatest(coalesce(p_duration_minutes, 60), 15),
           'horse_id',         p_horse_id)
   WHERE id = p_purchase_item_id;

  -- and materialise it, out to the rolling horizon
  v_res := _ensure_plan_horizon(p_purchase_item_id);

  RETURN jsonb_build_object(
    'purchase_item_id', p_purchase_item_id,
    'offering_name',    v_off.name,
    'weekly_frequency', v_freq,
    'slots',            p_slots,
    'horizon',          v_res);
END;
$_$;


--
-- Name: set_org_module(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_org_module(p_org uuid, p_key text, p_enabled boolean DEFAULT true, p_source text DEFAULT 'ADDON'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Deny by default. A NULL auth.uid() is NOT evidence of a trusted caller: the anon
  -- role has one too. Name the trusted callers positively instead.
  IF NOT (
       coalesce(is_super_admin(), false)
    OR coalesce(auth.role(), '') = 'service_role'
    OR (session_user IN ('postgres', 'supabase_admin') AND coalesce(auth.role(), '') = '')
  ) THEN
    RAISE EXCEPTION 'set_org_module is restricted to SUPER_ADMIN / the billing service'
      USING errcode = 'insufficient_privilege';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM organizations WHERE id = p_org) THEN
    RAISE EXCEPTION 'unknown organization: %', p_org;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM modules WHERE module_key = p_key) THEN
    RAISE EXCEPTION 'unknown module: %', p_key;
  END IF;
  IF p_source NOT IN ('TIER','ADDON','GRANT','SUBSCRIPTION') THEN
    RAISE EXCEPTION 'invalid source: %', p_source;
  END IF;

  INSERT INTO org_modules (org_id, module_key, enabled, source)
  VALUES (p_org, p_key, p_enabled, p_source)
  ON CONFLICT (org_id, module_key)
    DO UPDATE SET enabled = EXCLUDED.enabled, source = EXCLUDED.source, updated_at = now();
END;
$$;


--
-- Name: FUNCTION set_org_module(p_org uuid, p_key text, p_enabled boolean, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_org_module(p_org uuid, p_key text, p_enabled boolean, p_source text) IS 'U6: SUPER_ADMIN / billing-service upsert of a single org_modules entitlement (add-on / subscription seam). §4.1. Deny-by-default: SUPER_ADMIN, service_role, or a direct postgres/supabase_admin session. A NULL auth.uid() is not trust (NULLUID).';


--
-- Name: set_page_hidden(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_page_hidden(p_page_key text, p_hidden boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  /* THE ONE PAGE THAT CANNOT BE HIDDEN. Guarded here rather than in the UI: a
     UI-only guard is bypassed by one supabase.rpc() call from the console, and
     a tenant that hides its own way back needs a developer to get it — exactly
     what D13 forbids. Every OTHER page, Branding/Products/Forms included, is
     hideable, because this page brings all of them back. */
  c_protected constant text[] := ARRAY['settings.page_visibility'];
  v_org uuid := current_org();
BEGIN
  IF NOT coalesce(is_admin(), false) OR v_org IS NULL THEN
    RAISE EXCEPTION 'set_page_hidden: restricted to a tenant administrator'
      USING ERRCODE = '42501';
  END IF;

  IF p_page_key IS NULL OR p_page_key !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' THEN
    RAISE EXCEPTION 'set_page_hidden: % is not a page key', coalesce(p_page_key, '(null)')
      USING ERRCODE = '22023';
  END IF;

  IF coalesce(p_hidden, false) AND p_page_key = ANY (c_protected) THEN
    RAISE EXCEPTION 'set_page_hidden: % is the page that unhides everything else and cannot be hidden', p_page_key
      USING ERRCODE = '22023';
  END IF;

  IF coalesce(p_hidden, false) THEN
    INSERT INTO org_page_visibility (org_id, page_key)
    VALUES (v_org, p_page_key)
    ON CONFLICT (org_id, page_key) DO NOTHING;
    RETURN true;
  END IF;

  DELETE FROM org_page_visibility
   WHERE org_id = v_org AND page_key = p_page_key;
  RETURN false;
END;
$_$;


--
-- Name: FUNCTION set_page_hidden(p_page_key text, p_hidden boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_page_hidden(p_page_key text, p_hidden boolean) IS 'TASK-PAGEVIS: the tenant admin puts a page away (true) or brings it back (false). Returns the resulting hidden state. Writes ONLY org_page_visibility — never org_modules.enabled, which is an entitlement and not a display preference. Refuses to hide settings.page_visibility so the way back always exists.';


--
-- Name: set_party_controls(uuid, text, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_role text := upper(p_role);
  v_others int;
BEGIN
  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF NOT (coalesce(has_staff_access() AND v_org = current_org(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  -- Dropping this party below full access is refused when no OTHER signing party
  -- would still be able to edit. A party with no controls row is editable by
  -- default, so it counts as an editor here.
  IF NOT p_can_edit_deal THEN
    SELECT count(*) INTO v_others
      FROM document_parties dp
      LEFT JOIN document_party_controls c
        ON c.document_id = dp.document_id AND c.party_role = dp.party_role
     WHERE dp.document_id = p_document_id
       AND dp.party_role <> v_role
       AND dp.is_signer
       AND dp.party_role NOT IN ('FHE', 'COMPANY')
       AND coalesce(c.can_edit_deal, true);

    IF v_others = 0 THEN
      RAISE EXCEPTION 'at least one party must be able to edit deal terms — '
        'otherwise no party can change a term and every edit has to go through staff';
    END IF;
  END IF;

  INSERT INTO document_party_controls (document_id, party_role, can_fill, can_edit_deal, can_suggest, can_add_clause, org_id)
  VALUES (p_document_id, v_role, p_can_fill, p_can_edit_deal, p_can_suggest, p_can_add_clause, v_org)
  ON CONFLICT (document_id, party_role)
  DO UPDATE SET can_fill = excluded.can_fill,
                can_edit_deal = excluded.can_edit_deal,
                can_suggest = excluded.can_suggest,
                can_add_clause = excluded.can_add_clause;
END;
$$;


--
-- Name: FUNCTION set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_party_controls(p_document_id uuid, p_role text, p_can_fill boolean, p_can_edit_deal boolean, p_can_suggest boolean, p_can_add_clause boolean) IS 'Sets one party''s document controls. REFUSES a change that would leave no signing party able to edit deal terms: in that state the parties can at most suggest, and every actual edit has to be made by staff on their behalf. Turning one party off while another holds the permission is unaffected.';


--
-- Name: set_recipient_editing(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_recipient_editing(p_document_id uuid, p_on boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id INTO v_org FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF NOT (
       (coalesce(has_staff_access() AND v_org = current_org(), false))
  ) THEN
    RAISE EXCEPTION 'not authorized to change editing permission on document %', p_document_id;
  END IF;

  UPDATE documents SET recipient_editing = coalesce(p_on, false) WHERE id = p_document_id;
  -- keep the active share row in step, if one exists
  UPDATE document_shares SET recipient_editing = coalesce(p_on, false)
    WHERE document_id = p_document_id;
  RETURN coalesce(p_on, false);
END;
$$;


--
-- Name: FUNCTION set_recipient_editing(p_document_id uuid, p_on boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_recipient_editing(p_document_id uuid, p_on boolean) IS 'Originator/staff toggles documents.recipient_editing (whether the counterparty may edit DEAL fields/body). Keeps the active document_shares row in step.';


--
-- Name: set_recurring_day(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_recurring_day(p_purchase_item_id uuid, p_day text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pi   purchase_items%ROWTYPE;
  v_pu   purchases%ROWTYPE;
  v_off  offerings%ROWTYPE;
  v_day  text := initcap(btrim(coalesce(p_day, '')));
  v_client uuid;
  v_lc   lesson_credits%ROWTYPE;
  v_from date;
  v_to   date;
  v_new  int;
  v_used int;
BEGIN
  IF v_day NOT IN ('Mon','Tue','Wed','Thu','Fri','Sat','Sun') THEN
    RAISE EXCEPTION 'day must be one of Mon/Tue/Wed/Thu/Fri/Sat/Sun, got %', p_day;
  END IF;

  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  SELECT * INTO v_off FROM offerings WHERE id = v_pi.offering_id;
  IF NOT FOUND OR v_off.config_kind <> 'recurring' THEN
    RAISE EXCEPTION 'purchase item % is not a monthly-plan (recurring) offering', p_purchase_item_id;
  END IF;

  SELECT id INTO v_client FROM clients WHERE contact_id = v_pu.buyer_contact_id AND deleted_at IS NULL;
  IF NOT (has_staff_access() OR (v_client IS NOT NULL AND v_client = current_client_id())) THEN
    RAISE EXCEPTION 'not authorized to set this plan''s day';
  END IF;

  UPDATE purchase_items SET config = coalesce(config, '{}'::jsonb) || jsonb_build_object('recurring_day', v_day)
   WHERE id = p_purchase_item_id;

  -- CREDITALIGN: re-true the CURRENT month's allotment against the day just chosen.
  SELECT * INTO v_lc FROM lesson_credits
   WHERE purchase_item_id = p_purchase_item_id
     AND period_start = date_trunc('month', current_date)::date
     AND deleted_at IS NULL
   FOR UPDATE;
  IF FOUND THEN
    v_from := greatest(v_pu.created_at::date, v_lc.period_start);
    v_to   := (v_lc.period_start + interval '1 month - 1 day')::date;
    IF v_pi.plan_ends_on IS NOT NULL AND v_pi.plan_ends_on < v_to THEN v_to := v_pi.plan_ends_on; END IF;
    v_new  := _recurring_allotment(v_off.weekly_frequency, v_day, v_from, v_to, v_pi.quantity);
    v_used := v_lc.credits_total - v_lc.credits_remaining;
    UPDATE lesson_credits
       SET credits_total = v_new,
           credits_remaining = greatest(v_new - v_used, 0)
     WHERE id = v_lc.id;
  END IF;

  RETURN jsonb_build_object('purchase_item_id', p_purchase_item_id, 'recurring_day', v_day,
                            'entitled_this_month', v_new);
END;
$$;


--
-- Name: set_recurring_days(uuid, text[], integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_recurring_days(p_purchase_item_id uuid, p_days text[], p_weeks integer DEFAULT NULL::integer, p_indefinite boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pi     purchase_items%ROWTYPE;
  v_pu     purchases%ROWTYPE;
  v_off    offerings%ROWTYPE;
  v_days   text[];
  v_client uuid;
  v_lc     lesson_credits%ROWTYPE;
  v_from   date;
  v_to     date;
  v_start  date;
  v_ends   date;
  v_new    int;
  v_used   int;
  v_qty    int;
  v_freq   int;
  v_qty_locked boolean := false;
BEGIN
  v_days := _normalize_recurring_days(p_days);

  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_pu FROM purchases WHERE id = v_pi.purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  SELECT * INTO v_off FROM offerings WHERE id = v_pi.offering_id;
  IF NOT FOUND OR v_off.config_kind <> 'recurring' THEN
    RAISE EXCEPTION 'purchase item % is not a monthly-plan (recurring) offering', p_purchase_item_id;
  END IF;

  SELECT id INTO v_client FROM clients WHERE contact_id = v_pu.buyer_contact_id AND deleted_at IS NULL;
  IF NOT (has_staff_access() OR (v_client IS NOT NULL AND v_client = current_client_id())) THEN
    RAISE EXCEPTION 'not authorized to set this plan''s days';
  END IF;

  -- ── how long: N weeks, or indefinitely until cancelled ──
  -- "Indefinite" is plan_ends_on IS NULL — the same column, the same meaning, and
  -- the same stop button (set_recurring_plan_end). No second lifecycle store.
  v_start := greatest(v_pu.created_at::date, current_date);
  IF coalesce(p_indefinite, false) THEN
    v_ends := NULL;
  ELSIF p_weeks IS NOT NULL THEN
    IF p_weeks < 1 THEN RAISE EXCEPTION 'a plan runs for at least one week'; END IF;
    v_ends := v_start + (p_weeks * 7 - 1);
  ELSE
    v_ends := v_pi.plan_ends_on;   -- unchanged when the caller says nothing
  END IF;

  -- ── the quantity FOLLOWS the days ABOVE THE SKU'S OWN FREQUENCY (owner, 2026-08-16
  -- as corrected by BUYANDBOOK §4) ── Two chosen days on a 1x weekly SKU is quantity 2,
  -- because there is no volume discount in this business. Two chosen days on the 2x
  -- SKU is quantity 1, because that SKU already sells two. A PAID order is not
  -- re-priced by a scheduling action — that would change what someone already paid;
  -- it is reported back instead.
  v_freq := greatest(coalesce(v_off.weekly_frequency, 1), 1);
  v_qty  := greatest(ceil(array_length(v_days, 1)::numeric / v_freq)::int, 1);
  IF coalesce(v_pu.payment_status, '') = 'paid' AND coalesce(v_pi.quantity, 1) <> v_qty THEN
    v_qty_locked := true;
    v_qty := v_pi.quantity;
  END IF;

  UPDATE purchase_items
     SET config = coalesce(config, '{}'::jsonb)
                  || jsonb_build_object(
                       'recurring_days', to_jsonb(v_days),
                       -- the singular stays in sync as the first day so every reader
                       -- written before this task still resolves to something true.
                       'recurring_day',  v_days[1],
                       'plan_weeks',     CASE WHEN coalesce(p_indefinite, false) THEN NULL
                                              ELSE p_weeks END,
                       'plan_starts_on', v_start),
         quantity = v_qty,
         plan_ends_on = v_ends
   WHERE id = p_purchase_item_id;

  PERFORM _recompute_purchase_total(v_pu.id);

  -- ── re-true THIS month's allotment against the days just chosen ──
  -- Same shape as set_recurring_day's re-true: a new total, reduced by whatever the
  -- client has already used, floored at zero. Sessions already taken are never
  -- clawed back. BUYANDBOOK §4.2: the window starts TODAY, never at the purchase
  -- date — days already gone are not entitlement, they are leftovers.
  SELECT * INTO v_lc FROM lesson_credits
   WHERE purchase_item_id = p_purchase_item_id
     AND period_start = date_trunc('month', current_date)::date
     AND deleted_at IS NULL
   FOR UPDATE;
  IF FOUND THEN
    v_from := greatest(v_pu.created_at::date, v_lc.period_start, current_date);
    v_to   := (v_lc.period_start + interval '1 month - 1 day')::date;
    IF v_ends IS NOT NULL AND v_ends < v_to THEN v_to := v_ends; END IF;
    v_new  := _recurring_allotment_days(v_days, v_from, v_to);
    v_used := v_lc.credits_total - v_lc.credits_remaining;
    UPDATE lesson_credits
       SET credits_total = v_new,
           credits_remaining = greatest(v_new - v_used, 0)
     WHERE id = v_lc.id;
  END IF;

  RETURN jsonb_build_object(
    'purchase_item_id',    p_purchase_item_id,
    'recurring_days',      to_jsonb(v_days),
    'plan_ends_on',        v_ends,
    'plan_weeks',          CASE WHEN coalesce(p_indefinite, false) THEN NULL ELSE p_weeks END,
    'indefinite',          v_ends IS NULL,
    'quantity',            v_qty,
    'quantity_locked',     v_qty_locked,
    'catalog_default',     v_off.weekly_frequency,
    -- Surfaced, never corrected quietly (owner, 2026-08-17): staff may deliberately
    -- give a 2x SKU three days. The UI shows the difference; nothing blocks it.
    'differs_from_catalog', v_freq <> array_length(v_days, 1),
    'entitled_this_month', v_new);
END;
$$;


--
-- Name: FUNCTION set_recurring_days(p_purchase_item_id uuid, p_days text[], p_weeks integer, p_indefinite boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_recurring_days(p_purchase_item_id uuid, p_days text[], p_weeks integer, p_indefinite boolean) IS 'CAREPLANS §P3: staff choose the days of the week and how long the plan runs; the quantity follows from the days. The days are an ENTITLEMENT BASIS, not a schedule — they decide HOW MANY sessions the month holds, and the client may then book them on any dates they like.';


--
-- Name: set_recurring_plan_end(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_recurring_plan_end(p_purchase_item_id uuid, p_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pi  purchase_items%ROWTYPE;
  v_off offerings%ROWTYPE;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'operator access required'; END IF;
  SELECT * INTO v_pi FROM purchase_items WHERE id = p_purchase_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase item not found'; END IF;
  SELECT * INTO v_off FROM offerings WHERE id = v_pi.offering_id;
  IF NOT FOUND OR v_off.config_kind <> 'recurring' THEN
    RAISE EXCEPTION 'purchase item % is not a monthly-plan (recurring) offering', p_purchase_item_id;
  END IF;

  UPDATE purchase_items SET plan_ends_on = p_date WHERE id = p_purchase_item_id;

  -- Ending a plan does NOT claw back the month already paid for — the allotment it
  -- bought stands and expires on its own boundary. It only stops the roll.
  RETURN jsonb_build_object('purchase_item_id', p_purchase_item_id, 'plan_ends_on', p_date);
END;
$$;


--
-- Name: set_request_checklist(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_request_checklist(p_request_id uuid, p_checklist jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_out jsonb;
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'not authorized to update the request checklist';
  END IF;
  IF p_checklist IS NULL OR jsonb_typeof(p_checklist) <> 'object' THEN
    RAISE EXCEPTION 'checklist must be a JSON object of item key -> boolean';
  END IF;

  UPDATE requests SET checklist = p_checklist WHERE id = p_request_id
    RETURNING checklist INTO v_out;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown request: %', p_request_id;
  END IF;

  RETURN v_out;
END;
$$;


--
-- Name: FUNCTION set_request_checklist(p_request_id uuid, p_checklist jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_request_checklist(p_request_id uuid, p_checklist jsonb) IS 'Store the lesson-fit checklist state (flat object of item key -> boolean) on a request. Staff-gated (has_staff_access()).';


--
-- Name: set_support_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_support_status(p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'admin access required';
  END IF;
  IF p_status NOT IN ('open', 'in_progress', 'resolved') THEN
    RAISE EXCEPTION 'invalid status';
  END IF;

  UPDATE support_requests
     SET status = p_status,
         resolved_at = CASE WHEN p_status = 'resolved' THEN now() ELSE NULL END,
         resolved_by = CASE WHEN p_status = 'resolved' THEN auth.uid() ELSE NULL END
   WHERE id = p_id
     AND org_id = current_org();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'request not found in this org';
  END IF;
END;
$$;


--
-- Name: set_unit_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_unit_status(p_unit_id uuid, p_status text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_u fulfillment_units%ROWTYPE;
BEGIN
  SELECT * INTO v_u FROM fulfillment_units WHERE id = p_unit_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unit not found'; END IF;
  UPDATE fulfillment_units
     SET current_status = p_status,
         consumed_at = CASE WHEN p_status IN ('consumed','delivered') THEN now() ELSE consumed_at END
   WHERE id = p_unit_id;
  PERFORM log_status_event('fulfillment', p_unit_id, p_status, p_detail, v_u.org_id);
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: share_document(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org     uuid;
  v_title   text;
  v_by      uuid := current_contact_id();
  v_share   document_shares%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT org_id, coalesce(title, 'A contract') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document: %', p_document_id;
  END IF;

  IF NOT (
       (coalesce(has_staff_access() AND v_org = current_org(), false))
  ) THEN
    RAISE EXCEPTION 'not authorized to share document %', p_document_id;
  END IF;

  PERFORM 1 FROM contacts WHERE id = p_with_contact_id AND org_id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown contact % in this organization', p_with_contact_id;
  END IF;

  INSERT INTO document_shares (org_id, document_id, shared_with_contact_id,
                              granted_by_contact_id, recipient_editing, notified_at)
    VALUES (v_org, p_document_id, p_with_contact_id, v_by,
            coalesce(p_recipient_editing, false), now())
  ON CONFLICT (document_id, shared_with_contact_id) DO UPDATE SET
    recipient_editing = excluded.recipient_editing,
    granted_by_contact_id = excluded.granted_by_contact_id,
    notified_at = now()
  RETURNING * INTO v_share;

  -- mirror recipient_editing onto the document for the active share
  UPDATE documents SET recipient_editing = coalesce(p_recipient_editing, false)
    WHERE id = p_document_id;

  -- notify the recipient's app user (skip silently when they have no account)
  PERFORM contract_notify(p_document_id, p_with_contact_id, 'contract_shared',
    v_title || ' was shared with you',
    'You have been granted access to review this contract.');

  RETURN jsonb_build_object(
    'id', v_share.id, 'document_id', v_share.document_id,
    'shared_with_contact_id', v_share.shared_with_contact_id,
    'recipient_editing', v_share.recipient_editing, 'notified_at', v_share.notified_at);
END;
$$;


--
-- Name: FUNCTION share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.share_document(p_document_id uuid, p_with_contact_id uuid, p_recipient_editing boolean) IS 'Originator/staff: create/update a document_shares grant, mirror recipient_editing onto the document, and notify the recipient (kind ''contract_shared''). Returns the share as jsonb.';


--
-- Name: share_evaluation_report(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_evaluation_report(p_report_id uuid, p_email text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_allowed boolean;
BEGIN
  SELECT org_id, (has_staff_access() OR contact_id = current_contact_id())
    INTO v_org, v_allowed
    FROM evaluation_reports WHERE id = p_report_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'report not found'; END IF;
  IF NOT coalesce(v_allowed, false) THEN RAISE EXCEPTION 'not allowed to share this report'; END IF;

  INSERT INTO evaluation_report_shares (org_id, report_id, shared_with_contact_id, shared_with_email, shared_by)
    VALUES (v_org, p_report_id, p_contact_id, lower(nullif(trim(p_email), '')), auth.uid());
  INSERT INTO evaluation_report_access (org_id, report_id, actor_user_id, action, detail)
    VALUES (v_org, p_report_id, auth.uid(), 'shared', coalesce(p_email, p_contact_id::text));
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: sign_general_release(text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid DEFAULT NULL::uuid, p_esign_consent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Owner directive 2026-07-03: kiosk signatures must carry an email for
  -- attribution. Fail before any row is written.
  IF NULLIF(trim(coalesce(p_email, '')), '') IS NULL THEN
    RAISE EXCEPTION 'email is required';
  END IF;
  RETURN sign_release(
    'RELEASE_GENERAL',
    NULLIF(split_part(trim(coalesce(p_full_name, '')), ' ', 1), ''),
    CASE WHEN position(' ' IN trim(coalesce(p_full_name, ''))) > 0
         THEN NULLIF(trim(substring(trim(p_full_name) FROM position(' ' IN trim(p_full_name)) + 1)), '')
         ELSE NULL END,
    p_email, p_phone, p_typed_name,
    false, NULL, NULL, NULL, NULL, true, p_org,
    coalesce(p_esign_consent, false));
END;
$$;


--
-- Name: FUNCTION sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid, p_esign_consent boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_general_release(p_full_name text, p_email text, p_phone text, p_typed_name text, p_org uuid, p_esign_consent boolean) IS 'Kiosk wrapper over sign_release(RELEASE_GENERAL, …, adult path). v4: forwards its own trailing p_esign_consent (DEFAULT false — sign_release rejects without it; consent always comes from the user). v3: p_email REQUIRED. Splits its single full-name argument on the first space into first/last. Unilateral: EXECUTES on the visitor signature (signer = CLIENT party).';


--
-- Name: sign_path_for_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_path_for_contact(p_contact_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cats text[];
  v_doc  uuid;
BEGIN
  IF p_contact_id IS NULL THEN RETURN ''; END IF;
  -- The NEWEST invitation, because a re-invited person's current door is the one
  -- that just brought them here, not the one from a year ago.
  SELECT i.categories, i.document_id INTO v_cats, v_doc
    FROM invitations i
   WHERE i.contact_id = p_contact_id AND i.deleted_at IS NULL
   ORDER BY i.created_at DESC
   LIMIT 1;
  IF NOT FOUND THEN RETURN ''; END IF;
  -- A contract invitation IS the `deal` door: `invite_contract_counterparty` is
  -- the only writer of invitations.document_id, and /api/sign-start's deal branch
  -- is the only self-service caller of it. `kind` cannot be used for this — every
  -- invitation row on production carries kind='COMMUNITY' (22 of 22, checked).
  IF v_doc IS NOT NULL THEN RETURN 'deal'; END IF;
  RETURN coalesce(_sign_path_for_categories(coalesce(v_cats, ARRAY[]::text[])), '');
END;
$$;


--
-- Name: sign_release(text, text, text, text, text, text, boolean, text, text, date, text, boolean, uuid, boolean, date, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean DEFAULT false, p_minor_first_name text DEFAULT NULL::text, p_minor_last_name text DEFAULT NULL::text, p_minor_dob date DEFAULT NULL::date, p_guardian_relationship text DEFAULT NULL::text, p_rules_acknowledged boolean DEFAULT false, p_org uuid DEFAULT NULL::uuid, p_esign_consent boolean DEFAULT false, p_dob date DEFAULT NULL::date, p_address_line1 text DEFAULT NULL::text, p_address_line2 text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_postal_code text DEFAULT NULL::text, p_ec1_name text DEFAULT NULL::text, p_ec1_relationship text DEFAULT NULL::text, p_ec1_phone text DEFAULT NULL::text, p_ec2_name text DEFAULT NULL::text, p_ec2_relationship text DEFAULT NULL::text, p_ec2_phone text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_first     text := trim(coalesce(p_first_name, ''));
  v_last      text := trim(coalesce(p_last_name, ''));
  v_name      text;
  v_typed     text := trim(coalesce(p_typed_name, ''));
  v_email     text := lower(trim(coalesce(p_email, '')));
  v_phone     text := trim(coalesce(p_phone, ''));
  v_minor_first text := trim(coalesce(p_minor_first_name, ''));
  v_minor_last  text := trim(coalesce(p_minor_last_name, ''));
  v_minor     text;
  v_rel       text := trim(coalesce(p_guardian_relationship, ''));
  v_org       uuid;
  v_contact   uuid;
  v_minor_c   uuid;
  v_client    uuid;
  v_parties   jsonb;
  v_doc       uuid;
  v_doc_code  text;
  v_body      text;
  v_today     text := to_char(current_date, 'FMMonth FMDD, YYYY');
  v_need      integer;
  v_have      integer;
  v_status    text;
  v_ip        text;
  v_ua        text;
  v_signed_at timestamptz;
  v_hash      text;
  v_is_release boolean;
BEGIN
  v_name  := trim(v_first || ' ' || v_last);
  v_minor := trim(v_minor_first || ' ' || v_minor_last);

  IF p_template_key NOT IN ('RELEASE_GENERAL','RELEASE_PARTICIPANT',
                            'RELEASE_HORSE_EXERCISE','RELEASE_HORSE_CARE',
                            'FACILITY_RULES','COMPANY_POLICIES',
                            'HUMAN_EMERGENCY_MEDICAL') THEN
    RAISE EXCEPTION 'unknown release template: %', p_template_key;
  END IF;

  v_is_release := (p_template_key LIKE 'RELEASE\_%');

  IF v_is_release AND NOT coalesce(p_rules_acknowledged, false) THEN
    RAISE EXCEPTION 'the facility rules must be acknowledged before signing';
  END IF;
  IF NOT coalesce(p_esign_consent, false) THEN
    RAISE EXCEPTION 'electronic signing consent is required';
  END IF;
  IF v_first = '' THEN
    RAISE EXCEPTION 'a first name is required';
  END IF;
  IF length(v_name) < 2 OR length(v_name) > 200 THEN
    RAISE EXCEPTION 'a name is required (2-200 characters)';
  END IF;
  IF v_typed = '' OR lower(v_typed) <> lower(v_name) THEN
    RAISE EXCEPTION 'typed signature must match the full name exactly';
  END IF;
  IF v_email = '' THEN v_email := NULL; END IF;
  IF v_phone = '' THEN v_phone := NULL; END IF;
  IF v_email IS NULL AND v_phone IS NULL THEN
    RAISE EXCEPTION 'an email address or phone number is required';
  END IF;
  IF v_email IS NOT NULL AND (
       length(v_email) > 320
       OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ) THEN
    RAISE EXCEPTION 'invalid email address';
  END IF;
  IF v_phone IS NOT NULL AND v_phone !~ '^[0-9+().\- ]{7,25}$' THEN
    RAISE EXCEPTION 'invalid phone number';
  END IF;
  IF coalesce(p_is_minor, false) THEN
    IF v_minor_first = '' THEN
      RAISE EXCEPTION 'the minor''s first name is required';
    END IF;
    IF length(v_minor) < 2 OR length(v_minor) > 200 THEN
      RAISE EXCEPTION 'the minor''s name is required (2-200 characters)';
    END IF;
    IF p_minor_dob IS NULL OR p_minor_dob >= current_date THEN
      RAISE EXCEPTION 'a valid date of birth for the minor is required';
    END IF;
    IF p_minor_dob + interval '18 years' <= current_date THEN
      RAISE EXCEPTION 'the named person is not a minor (18 or older); sign the adult release';
    END IF;
    IF length(v_rel) < 2 OR length(v_rel) > 100 THEN
      RAISE EXCEPTION 'the guardian''s relationship to the minor is required (2-100 characters)';
    END IF;
  END IF;

  -- ---- org resolution + transaction-local tenant pin (see 20260702020000) ----
  v_org := coalesce(p_org, current_org(), current_addressed_org(), sole_org());
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no organization addressed (multi-tenant deployments must address a tenant)';
  END IF;
  PERFORM 1 FROM organizations WHERE id = v_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown organization: %', v_org;
  END IF;
  PERFORM set_config('app.current_org', v_org::text, true);

  SELECT a.ip, a.user_agent INTO v_ip, v_ua FROM http_request_attribution() a;

  -- ---- find-or-create the SIGNER's contact (per-org email match) ----
  IF v_email IS NOT NULL THEN
    SELECT id INTO v_contact FROM contacts
      WHERE org_id = v_org AND lower(email) = v_email AND deleted_at IS NULL
      ORDER BY created_at LIMIT 1;
  END IF;
  IF v_contact IS NULL THEN
    INSERT INTO contacts (org_id, first_name, last_name, email, phone,
                          date_of_birth, address_line1, address_line2, city, state, postal_code,
                          emergency_contact_1_name, emergency_contact_1_relationship, emergency_contact_1_phone,
                          emergency_contact_2_name, emergency_contact_2_relationship, emergency_contact_2_phone)
      VALUES (v_org, v_first, NULLIF(v_last, ''), v_email, v_phone,
              p_dob, NULLIF(trim(coalesce(p_address_line1,'')),''), NULLIF(trim(coalesce(p_address_line2,'')),''),
              NULLIF(trim(coalesce(p_city,'')),''), NULLIF(trim(coalesce(p_state,'')),''), NULLIF(trim(coalesce(p_postal_code,'')),''),
              NULLIF(trim(coalesce(p_ec1_name,'')),''), NULLIF(trim(coalesce(p_ec1_relationship,'')),''), NULLIF(trim(coalesce(p_ec1_phone,'')),''),
              NULLIF(trim(coalesce(p_ec2_name,'')),''), NULLIF(trim(coalesce(p_ec2_relationship,'')),''), NULLIF(trim(coalesce(p_ec2_phone,'')),''))
      RETURNING id INTO v_contact;
  ELSE
    UPDATE contacts
       SET first_name = v_first,
           last_name  = NULLIF(v_last, ''),
           phone      = coalesce(nullif(phone, ''), v_phone)
     WHERE id = v_contact
       AND (
         NULLIF(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), '') IS NULL
         OR lower(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, ''))) = lower(coalesce(email, ''))
       );
    UPDATE contacts SET
        date_of_birth = coalesce(date_of_birth, p_dob),
        address_line1 = coalesce(nullif(address_line1,''), NULLIF(trim(coalesce(p_address_line1,'')),'')),
        address_line2 = coalesce(nullif(address_line2,''), NULLIF(trim(coalesce(p_address_line2,'')),'')),
        city          = coalesce(nullif(city,''), NULLIF(trim(coalesce(p_city,'')),'')),
        state         = coalesce(nullif(state,''), NULLIF(trim(coalesce(p_state,'')),'')),
        postal_code   = coalesce(nullif(postal_code,''), NULLIF(trim(coalesce(p_postal_code,'')),'')),
        emergency_contact_1_name         = coalesce(nullif(emergency_contact_1_name,''), NULLIF(trim(coalesce(p_ec1_name,'')),'')),
        emergency_contact_1_relationship = coalesce(nullif(emergency_contact_1_relationship,''), NULLIF(trim(coalesce(p_ec1_relationship,'')),'')),
        emergency_contact_1_phone        = coalesce(nullif(emergency_contact_1_phone,''), NULLIF(trim(coalesce(p_ec1_phone,'')),'')),
        emergency_contact_2_name         = coalesce(nullif(emergency_contact_2_name,''), NULLIF(trim(coalesce(p_ec2_name,'')),'')),
        emergency_contact_2_relationship = coalesce(nullif(emergency_contact_2_relationship,''), NULLIF(trim(coalesce(p_ec2_relationship,'')),'')),
        emergency_contact_2_phone        = coalesce(nullif(emergency_contact_2_phone,''), NULLIF(trim(coalesce(p_ec2_phone,'')),''))
      WHERE id = v_contact;
  END IF;

  

  -- ---- client shell (CRM: a visitor who signs a release becomes a client) ----
  SELECT id INTO v_client FROM clients
    WHERE contact_id = v_contact AND deleted_at IS NULL;
  IF v_client IS NULL THEN
    INSERT INTO clients (org_id, contact_id, source, client_since)
      VALUES (v_org, v_contact, 'VISITOR_RELEASE', now())
      RETURNING id INTO v_client;
  END IF;

  -- ---- build the spine document_parties roster (NO engagement) ----
  IF coalesce(p_is_minor, false) THEN
    -- Minor path: the minor is the PARTICIPANT party (NOT a signer) — its
    -- presence makes generate_document KEEP the MINOR_* CUT sections and resolve
    -- {{PARTICIPANT.*}} tokens. The parent/guardian signs as CLIENT.
    SELECT id INTO v_minor_c FROM contacts
      WHERE org_id = v_org
        AND lower(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, ''))) = lower(v_minor)
        AND deleted_at IS NULL
      ORDER BY created_at LIMIT 1;
    IF v_minor_c IS NULL THEN
      INSERT INTO contacts (org_id, first_name, last_name, date_of_birth, guardian_contact_id)
        VALUES (v_org, v_minor_first, NULLIF(v_minor_last, ''), p_minor_dob, v_contact)
        RETURNING id INTO v_minor_c;
    ELSE
      UPDATE contacts SET date_of_birth = coalesce(date_of_birth, p_minor_dob),
                          guardian_contact_id = coalesce(guardian_contact_id, v_contact)
        WHERE id = v_minor_c;
    END IF;
    

    v_parties := jsonb_build_array(
      jsonb_build_object('contact_id', v_minor_c, 'role', 'PARTICIPANT', 'is_signer', false),
      jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT', 'is_signer', true,
                         'signer_order', 1, 'relationship', v_rel));
  ELSE
    -- Adult path: the CLIENT signs for themself; no PARTICIPANT party, so
    -- generate_document strips the MINOR_* CUT sections whole.
    v_parties := jsonb_build_array(
      jsonb_build_object('contact_id', v_contact, 'role', 'CLIENT', 'is_signer', true, 'signer_order', 1));
  END IF;

  -- NO COMPANY party: releases are unilateral (owner decision 2026-07-02).

  -- ---- generate through the ONE spine generator (v11): contact-owned, no
  --      engagement, no contract, no horse; document_parties seeded from v_parties ----
  SELECT gd.document_id, gd.merged_body INTO v_doc, v_body
    FROM generate_document(v_contact, p_template_key, NULL::uuid, NULL::uuid, v_parties, NULL::text) gd;
  UPDATE documents SET org_id = v_org, status = 'AWAITING_SIGNATURE' WHERE id = v_doc;

  IF position('{{SIG.CLIENT.NAME}}' IN v_body) = 0 THEN
    RAISE EXCEPTION 'template % is missing its CLIENT signature block', p_template_key;
  END IF;
  v_body := replace(v_body, '{{SIG.CLIENT.NAME}}', v_typed);
  v_body := replace(v_body, '{{SIG.CLIENT.DATE}}', v_today);

  IF v_is_release THEN
    v_body := rtrim(v_body)
      || E'\n\nFACILITY RULES ACKNOWLEDGMENT\n\nSigner acknowledged the Facility Rules and Safety Acknowledgment on '
      || v_today || E'.\n';
  END IF;

  INSERT INTO signatures (org_id, document_id, signer_contact_id, signer_user_id, party_role, typed_name, signed_at, ip_address, user_agent, method)
    VALUES (v_org, v_doc, v_contact, (SELECT pr.user_id FROM profiles pr WHERE pr.contact_id = v_contact LIMIT 1), 'CLIENT', v_typed, now(), v_ip, v_ua, 'KIOSK_TYPED')
    RETURNING signed_at INTO v_signed_at;

  INSERT INTO esign_consents (org_id, contact_id, document_id, ip_address, user_agent)
    VALUES (v_org, v_contact, v_doc, v_ip, v_ua);

  -- executed once EVERY signer party has signed (single signer here) — counted
  -- off document_parties (the spine roster) instead of engagement_parties.
  SELECT count(*) FILTER (WHERE is_signer) INTO v_need
    FROM document_parties WHERE document_id = v_doc;
  SELECT count(*) INTO v_have
    FROM signatures WHERE document_id = v_doc AND signed_at IS NOT NULL AND deleted_at IS NULL;
  -- PARTYEMAIL PHASE 0 / flow-map X4 (1 of 2): the SIGNED body is persisted
  -- BEFORE the execution UPDATE. snapshot_execution_audit archives NEW.merged_body,
  -- and until now the body was written AFTERWARDS -- so even once the trigger fires,
  -- archiving it here is what makes the snapshot the document that was signed
  -- (typed signature substituted, rules acknowledgment appended) rather than the
  -- pre-signature merge. record_signature has always ordered it this way.
  UPDATE documents SET merged_body = v_body WHERE id = v_doc;

  IF v_need > 0 AND v_have >= v_need THEN
    v_hash := compute_execution_hash(v_body, v_contact, v_typed, v_signed_at);
    -- PARTYEMAIL PHASE 0 / flow-map X4 (2 of 2): workflow_state is NAMED in the
    -- target list. The three execution triggers are AFTER UPDATE OF workflow_state,
    -- and Postgres decides that from the columns the STATEMENT names -- not from
    -- the value documents_sync_workflow_on_status assigns in its BEFORE trigger.
    -- Naming only status therefore fired NONE of them, so a kiosk execution wrote
    -- no contract_execution_audit row and the live row was its only evidence.
    -- The stored VALUE is unchanged: 'executed' either way.
    UPDATE documents SET status = 'EXECUTED', effective_date = now()::date,
                         execution_hash = v_hash, workflow_state = 'executed'
      WHERE id = v_doc;
  END IF;

  SELECT status, display_code INTO v_status, v_doc_code FROM documents WHERE id = v_doc;

  RETURN jsonb_build_object(
    'document_id',   v_doc,
    'document_code', v_doc_code,
    'contact_id',    v_contact,
    'status',        v_status,
    'merged_body',   v_body
  );
END;
$_$;


--
-- Name: FUNCTION sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean, p_minor_first_name text, p_minor_last_name text, p_minor_dob date, p_guardian_relationship text, p_rules_acknowledged boolean, p_org uuid, p_esign_consent boolean, p_dob date, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_ec1_name text, p_ec1_relationship text, p_ec1_phone text, p_ec2_name text, p_ec2_relationship text, p_ec2_phone text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_release(p_template_key text, p_first_name text, p_last_name text, p_email text, p_phone text, p_typed_name text, p_is_minor boolean, p_minor_first_name text, p_minor_last_name text, p_minor_dob date, p_guardian_relationship text, p_rules_acknowledged boolean, p_org uuid, p_esign_consent boolean, p_dob date, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_ec1_name text, p_ec1_relationship text, p_ec1_phone text, p_ec2_name text, p_ec2_relationship text, p_ec2_phone text) IS 'Public release kiosk (2026-07-07 medical-auth extension): adds HUMAN_EMERGENCY_MEDICAL to the allow-list and twelve optional trailing params (DOB, address parts, two emergency contacts) written fill-blank onto the signer contact so the medical-auth document merges them. All prior behavior preserved from 20260703140000.';


--
-- Name: sign_start_register_attempt(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_start_register_attempt(p_hash text, p_org uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.sign_start_attempts%ROWTYPE;
  v_should_notify boolean := false;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR has_staff_access()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF p_hash IS NULL OR btrim(p_hash) = '' THEN
    RAISE EXCEPTION 'requester hash is required';
  END IF;

  SELECT * INTO v_row FROM public.sign_start_attempts
   WHERE requester_hash = p_hash AND window_start > now() - interval '1 hour'
   ORDER BY window_start DESC LIMIT 1
   FOR UPDATE;

  IF v_row.id IS NULL THEN
    INSERT INTO public.sign_start_attempts (requester_hash, window_start, count)
    VALUES (p_hash, now(), 1)
    RETURNING * INTO v_row;
  ELSE
    UPDATE public.sign_start_attempts SET count = count + 1
     WHERE id = v_row.id
     RETURNING * INTO v_row;
  END IF;

  IF v_row.count = 10 AND v_row.notified_at IS NULL THEN
    v_should_notify := true;
    UPDATE public.sign_start_attempts SET notified_at = now() WHERE id = v_row.id;
  END IF;

  IF v_should_notify AND p_org IS NOT NULL THEN
    PERFORM notify_staff(p_org, 'sign_start_lockout',
      'The /sign self-onboarding form hit its rate limit (10 submissions/hour) for one visitor',
      '/app/ops/intake');
  END IF;

  RETURN jsonb_build_object('allowed', v_row.count <= 10, 'count', v_row.count);
END;
$$;


--
-- Name: skip_required_document(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.skip_required_document(p_contact_id uuid, p_template_key text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'contact not found in this org';
  END IF;

  RETURN _skip_required_document(p_contact_id, p_template_key, p_reason, auth.uid());
END;
$$;


--
-- Name: snapshot_execution_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_execution_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_log jsonb; v_cmt jsonb; v_nlog int; v_ncmt int;
BEGIN
  IF NOT (NEW.workflow_state = 'executed' AND OLD.workflow_state IS DISTINCT FROM 'executed') THEN
    RETURN NEW;
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(cl) ORDER BY cl.created_at), '[]'::jsonb), count(*)
    INTO v_log, v_nlog
    FROM contract_change_log cl WHERE cl.document_id = NEW.id;

  SELECT coalesce(jsonb_agg(to_jsonb(cc) ORDER BY cc.created_at), '[]'::jsonb), count(*)
    INTO v_cmt, v_ncmt
    FROM contract_change_requests cc WHERE cc.document_id = NEW.id;

  INSERT INTO contract_execution_audit (
    org_id, document_id, executed_at, execution_hash, merged_body,
    change_log, comments, change_count, comment_count)
  VALUES (
    NEW.org_id, NEW.id, now(), NEW.execution_hash, NEW.merged_body,
    coalesce(v_log,'[]'::jsonb), coalesce(v_cmt,'[]'::jsonb),
    coalesce(v_nlog,0), coalesce(v_ncmt,0))
  ON CONFLICT (document_id) DO NOTHING;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


--
-- Name: snooze_alert(timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snooze_alert(p_until timestamp with time zone, p_alert_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := current_org();
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF p_alert_id IS NOT NULL THEN
    UPDATE alerts SET snoozed_until = p_until
     WHERE id = p_alert_id AND org_id = v_org AND user_id = auth.uid();
  ELSIF p_source IS NOT NULL THEN
    INSERT INTO alert_suppressions (org_id, user_id, source, entity_id, suppressed_until)
    VALUES (v_org, auth.uid(), p_source, p_entity_id, p_until)
    ON CONFLICT (org_id, user_id, source, entity_id)
    DO UPDATE SET suppressed_until = p_until, created_at = now();
  END IF;
END
$$;


--
-- Name: sole_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sole_org() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN (SELECT count(*) FROM organizations) = 1
              THEN (SELECT id FROM organizations LIMIT 1) END
$$;


--
-- Name: FUNCTION sole_org(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sole_org() IS 'The lone organization when exactly one exists (single-tenant launch fallback for public intake); NULL once a second tenant is provisioned — unaddressed anon writes then fail loudly.';


--
-- Name: split_purchase(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_purchase(p_purchase_id uuid, p_item_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src purchases%ROWTYPE;
  v_new uuid;
  v_moved integer;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may split an order';
  END IF;
  SELECT * INTO v_src FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF v_src.id IS NULL THEN RAISE EXCEPTION 'order not found'; END IF;
  IF v_src.org_id IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'order not found';
  END IF;
  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'choose at least one item to move';
  END IF;
  -- Moving EVERY live line would leave an empty husk and a clone, not a split.
  IF NOT EXISTS (
    SELECT 1 FROM purchase_items pi
     WHERE pi.purchase_id = p_purchase_id AND pi.voided_at IS NULL
       AND NOT (pi.id = ANY(p_item_ids))
  ) THEN
    RAISE EXCEPTION 'that would move every item — there would be nothing left in this order';
  END IF;

  -- Order B: same buyer, same tenant, SAME INQUIRY. It starts as a draft and
  -- owes nothing; whether it is held or confirmed is a separate staff decision.
  INSERT INTO purchases (org_id, request_id, buyer_contact_id, buyer_user_id,
                         status, amount, payment_status, horse_id, notes)
  VALUES (v_src.org_id, v_src.request_id, v_src.buyer_contact_id, v_src.buyer_user_id,
          'draft', 0, 'unpaid', v_src.horse_id, p_reason)
  RETURNING id INTO v_new;

  UPDATE purchase_items
     SET purchase_id = v_new
   WHERE id = ANY(p_item_ids) AND purchase_id = p_purchase_id AND voided_at IS NULL;
  GET DIAGNOSTICS v_moved = ROW_COUNT;
  IF v_moved = 0 THEN
    RAISE EXCEPTION 'none of those items belong to this order';
  END IF;

  PERFORM _recompute_purchase_total(p_purchase_id);
  PERFORM _recompute_purchase_total(v_new);

  PERFORM log_status_event('order', p_purchase_id, 'items_moved',
    v_moved || ' item(s) moved to a separate order'
      || coalesce(' — ' || nullif(btrim(p_reason), ''), ''), v_src.org_id);
  PERFORM log_status_event('order', v_new, 'split',
    'Split from order ' || coalesce(v_src.display_code, p_purchase_id::text)
      || coalesce(' — ' || nullif(btrim(p_reason), ''), ''), v_src.org_id);

  RETURN jsonb_build_object('purchase_id', v_new, 'moved', v_moved,
                            'request_id', v_src.request_id);
END;
$$;


--
-- Name: staff_archive_horse(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_archive_horse(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  UPDATE horses SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_id AND org_id = current_org() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org, or already archived'; END IF;
END;
$$;


--
-- Name: staff_assign_documents(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assign_documents(p_contact_id uuid, p_template_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_assigned text[] := '{}';
  v_resign   text[] := '{}';
  k          text;
  r          record;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;

  FOREACH k IN ARRAY coalesce(p_template_keys, '{}') LOOP
    IF NOT EXISTS (SELECT 1 FROM staff_assignable_templates(p_contact_id) t WHERE t.template_key = k) THEN
      RAISE EXCEPTION 'template % is not assignable (inactive, clause-engine, or not the current version)', k;
    END IF;

    -- CLOSEOUT §1.6: assigning a template that was skipped is the explicit way
    -- of saying you want it back — the skip mark is cleared.
    INSERT INTO contact_required_documents (contact_id, template_key, org_id)
    VALUES (p_contact_id, k, v_org)
    ON CONFLICT (contact_id, template_key) DO UPDATE
      SET skipped_at = NULL, skipped_by = NULL, skip_reason = NULL
      WHERE contact_required_documents.skipped_at IS NOT NULL;
    v_assigned := v_assigned || k;

    -- Re-sign: every executed, non-superseded copy that would still satisfy the
    -- requirement is superseded (retained as evidence), so the assignment
    -- ALWAYS produces a pending requirement.
    FOR r IN
      SELECT d.id FROM documents d
      JOIN contract_templates ct ON ct.id = d.template_id
      WHERE d.contact_id = p_contact_id AND d.deleted_at IS NULL
        AND d.status = 'EXECUTED'
        AND coalesce(d.current_status, '') <> 'superseded'
        AND ct.template_key = k
    LOOP
      UPDATE documents SET current_status = 'superseded' WHERE id = r.id;
      PERFORM log_status_event('document', r.id, 'superseded',
        'Re-assigned for signature by staff', v_org);
      IF NOT (k = ANY (v_resign)) THEN v_resign := v_resign || k; END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'assigned', to_jsonb(v_assigned),
    'resign',   to_jsonb(v_resign));
END;
$$;


--
-- Name: staff_assign_horse_party(uuid, text, uuid, date, date, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assign_horse_party(p_horse_id uuid, p_role text, p_contact_id uuid, p_term_start date DEFAULT NULL::date, p_term_end date DEFAULT NULL::date, p_sublease_allowed boolean DEFAULT false, p_share_pct numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid := current_org();
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  IF p_role NOT IN ('OWNER','LESSEE','TRAINER','CARETAKER','BOARDER') THEN
    RAISE EXCEPTION 'role must be OWNER, LESSEE, TRAINER, CARETAKER, or BOARDER';
  END IF;

  -- OWNER/LESSEE keep their exclusive semantics + horses-column side effects
  -- (live behavior, unchanged). The ledger roles are plain additive rows.
  IF p_role = 'OWNER' THEN
    UPDATE horse_relationships SET active = false, ended_at = now()
     WHERE horse_id = p_horse_id AND relationship = 'OWNER' AND active
       AND (p_contact_id IS NULL OR party_contact_id IS DISTINCT FROM p_contact_id);
    UPDATE horses SET current_owner_contact_id = p_contact_id, updated_at = now()
     WHERE id = p_horse_id AND org_id = v_org;
  ELSIF p_role = 'LESSEE' THEN
    UPDATE horse_relationships SET active = false, ended_at = now()
     WHERE horse_id = p_horse_id AND relationship = 'LESSEE' AND active
       AND (p_contact_id IS NULL OR party_contact_id IS DISTINCT FROM p_contact_id);
    UPDATE horses
       SET lessee_contact_id = p_contact_id,
           lease_start = CASE WHEN p_contact_id IS NULL THEN NULL ELSE coalesce(p_term_start, lease_start) END,
           lease_end   = CASE WHEN p_contact_id IS NULL THEN NULL ELSE coalesce(p_term_end, lease_end) END,
           sublease_allowed = CASE WHEN p_contact_id IS NULL THEN false ELSE p_sublease_allowed END,
           updated_at = now()
     WHERE id = p_horse_id AND org_id = v_org;
  END IF;

  IF p_contact_id IS NOT NULL THEN
    INSERT INTO horse_relationships
      (org_id, horse_id, relationship, party_contact_id, term_start, term_end,
       share_pct, notes, created_by_contact_id)
    VALUES (v_org, p_horse_id, p_role, p_contact_id, p_term_start, p_term_end,
            p_share_pct, p_notes, current_contact_id());
  END IF;
END;
$$;


--
-- Name: staff_assignable_templates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assignable_templates(p_contact_id uuid) RETURNS TABLE(template_key text, title text, version integer, wall_gating boolean, on_file_status text, on_file_date date, on_file_version integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ct.template_key, ct.title, ct.version, ct.wall_gating,
         CASE WHEN d.id IS NULL THEN 'none'
              WHEN d.current_status = 'superseded' THEN 'superseded'
              ELSE 'executed' END,
         d.exec_date, d.version
    FROM contract_templates ct
    LEFT JOIN LATERAL (
      SELECT dd.id, dd.current_status, dd.created_at::date AS exec_date, ct2.version
        FROM documents dd JOIN contract_templates ct2 ON ct2.id = dd.template_id
       WHERE dd.contact_id = p_contact_id AND dd.deleted_at IS NULL
         AND dd.status = 'EXECUTED' AND ct2.template_key = ct.template_key
       ORDER BY (dd.current_status IS DISTINCT FROM 'superseded') DESC, dd.created_at DESC
       LIMIT 1
    ) d ON true
   WHERE has_staff_access()
     AND ct.active AND ct.deleted_at IS NULL
     AND ct.body IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM contract_section_defs s WHERE s.template_key = ct.template_key)
     AND ct.version = (SELECT max(x.version) FROM contract_templates x
                        WHERE x.template_key = ct.template_key AND x.active AND x.deleted_at IS NULL)
   ORDER BY ct.wall_gating DESC, ct.title;
$$;


--
-- Name: staff_contact_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_contact_directory() RETURNS TABLE(id uuid, display_code text, first_name text, last_name text, email text, phone text, tags text[], notes text, created_at timestamp with time zone, linked_user_id uuid, linked_role text, is_client boolean, party_roles text[], horses_owned bigint, horses_leased bigint, engagement_count bigint, document_count bigint, contact_type text, is_company boolean, client_origin text, contact_channel text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.display_code, c.first_name, c.last_name,
         c.email, c.phone, c.tags, c.notes, c.created_at,
         p.user_id, p.role,
         EXISTS (SELECT 1 FROM clients cl
                  WHERE cl.contact_id = c.id AND cl.deleted_at IS NULL),
         (SELECT coalesce(array_agg(DISTINCT dp.party_role), '{}')
            FROM document_parties dp WHERE dp.contact_id = c.id),
         (SELECT count(*) FROM horses h
           WHERE h.current_owner_contact_id = c.id AND h.deleted_at IS NULL),
         (SELECT count(*) FROM horses h
           WHERE h.lessee_contact_id = c.id AND h.deleted_at IS NULL),
         0::bigint,
         (SELECT count(DISTINCT d.id)
            FROM documents d
           WHERE d.deleted_at IS NULL
             AND (d.contact_id = c.id
                  OR EXISTS (SELECT 1 FROM document_parties dp
                              WHERE dp.document_id = d.id AND dp.contact_id = c.id))),
         c.contact_type,
         coalesce(c.is_company, false),
         c.client_origin, c.contact_channel
  FROM contacts c
  LEFT JOIN profiles p ON p.contact_id = c.id
  WHERE c.org_id = current_org()
    AND c.deleted_at IS NULL
    AND has_staff_access()
  ORDER BY c.last_name NULLS LAST, c.first_name
$$;


--
-- Name: staff_contact_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_contact_options() RETURNS TABLE(id uuid, name text, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, trim(concat_ws(' ', c.first_name, c.last_name)), c.email
  FROM contacts c
  WHERE c.org_id = current_org() AND c.deleted_at IS NULL AND has_staff_access()
  ORDER BY c.last_name NULLS LAST, c.first_name
$$;


--
-- Name: staff_end_horse_relationship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_end_horse_relationship(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  UPDATE horse_relationships SET active = false, ended_at = now()
   WHERE id = p_id AND org_id = current_org() AND active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'relationship not found or already ended';
  END IF;
END;
$$;


--
-- Name: staff_evaluation_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_evaluation_reports() RETURNS TABLE(id uuid, contact_id uuid, title text, horse_label text, status text, delivered_at timestamp with time zone, available_until timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.contact_id, r.title, r.horse_label, r.status,
         r.delivered_at, r.available_until, r.created_at
    FROM evaluation_reports r
   WHERE r.deleted_at IS NULL AND r.org_id = current_org()
     AND has_staff_access()
   ORDER BY r.created_at DESC;
$$;


--
-- Name: staff_horse_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_horse_records() RETURNS TABLE(id uuid, registered_name text, nickname text, breed text, color text, markings text, sex text, date_of_birth date, height text, registration_number text, registration_org text, microchip_id text, current_location text, fair_market_value numeric, vet_name text, vet_phone text, farrier_name text, farrier_phone text, owner_contact_id uuid, owner_name text, owner_name_text text, lessee_contact_id uuid, lessee_name text, lessee_name_text text, lease_start date, lease_end date, document_count bigint, active_lease_doc jsonb, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT h.id, h.registered_name, h.nickname, h.breed, h.color,
         h.markings, h.sex, h.date_of_birth, h.height,
         h.registration_number, h.registration_org, h.microchip_id,
         coalesce(horse_current_location_label(h.id), h.current_location),
         h.fair_market_value,
         horse_provider_value(h.id,'VET','NAME'), horse_provider_value(h.id,'VET','PHONE'),
         horse_provider_value(h.id,'FARRIER','NAME'), horse_provider_value(h.id,'FARRIER','PHONE'),
         h.current_owner_contact_id,
         (SELECT trim(concat_ws(' ', c.first_name, c.last_name)) FROM contacts c WHERE c.id = h.current_owner_contact_id),
         h.owner_name_text,
         h.lessee_contact_id,
         (SELECT trim(concat_ws(' ', c.first_name, c.last_name)) FROM contacts c WHERE c.id = h.lessee_contact_id),
         h.lessee_name_text,
         h.lease_start, h.lease_end,
         (SELECT count(*) FROM documents d
           WHERE d.horse_id = h.id AND d.deleted_at IS NULL AND d.org_id = h.org_id),
         horse_active_lease_doc(h.id) AS active_lease_doc,
         h.created_at
  FROM horses h
  WHERE h.org_id = current_org() AND h.deleted_at IS NULL AND has_staff_access()
  ORDER BY coalesce(h.nickname, h.registered_name)
$$;


--
-- Name: staff_orders_board(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_orders_board() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_out jsonb;
BEGIN
  v_org := current_org();
  IF NOT (coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY x.created_at DESC), '[]'::jsonb)
    INTO v_out
  FROM (
    SELECT
      p.id,
      p.display_code,
      p.amount,
      p.amount_paid,
      p.status,
      p.current_status,
      p.payment_status,
      p.created_at,
      p.paid_at,
      btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')) AS buyer_name,
      coalesce((SELECT string_agg(pi.label, ', ') FROM purchase_items pi WHERE pi.purchase_id = p.id), 'Order') AS items,
      -- booking rollup for this order
      (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
         AND b.status <> 'available') AS booking_count,
      (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
         AND coalesce(b.current_status, b.status) = 'completed') AS completed_count,
      (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
         AND coalesce(b.current_status, b.status) NOT IN ('cancelled','available')
         AND b.ends_at < now()
         AND coalesce(b.current_status, b.status) <> 'completed') AS overdue_count,
      -- the bucket
      CASE
        WHEN p.status = 'void' OR p.current_status = 'void' THEN 'cancelled'
        WHEN p.payment_status <> 'paid' THEN
          CASE WHEN p.status IN ('draft') AND p.current_status IS DISTINCT FROM 'payment_pending_zelle'
                    AND p.current_status IS DISTINCT FROM 'payment_pending_cash'
               THEN 'new' ELSE 'unpaid' END
        -- paid from here
        WHEN (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
                AND coalesce(b.current_status, b.status) NOT IN ('cancelled','available')
                AND b.ends_at < now()
                AND coalesce(b.current_status, b.status) <> 'completed') > 0 THEN 'issue'
        WHEN (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
                AND coalesce(b.current_status, b.status) = 'completed') > 0
             AND (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
                    AND coalesce(b.current_status, b.status) NOT IN ('cancelled','available','completed')) = 0
          THEN 'complete'
        WHEN (SELECT count(*) FROM bookings b WHERE b.purchase_id = p.id AND b.deleted_at IS NULL
                AND coalesce(b.current_status, b.status) IN ('scheduled','pending')
                AND b.starts_at >= now()) > 0 THEN 'booked'
        ELSE 'paid'
      END AS bucket
    FROM purchases p
    LEFT JOIN contacts c ON c.id = p.buyer_contact_id
    WHERE p.deleted_at IS NULL
      AND (v_org IS NULL OR p.org_id = v_org)
  ) x;
  RETURN v_out;
END
$$;


--
-- Name: staff_payments_board(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_payments_board() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_out jsonb;
BEGIN
  v_org := current_org();
  IF NOT (coalesce(has_staff_access(), false)) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  SELECT coalesce(jsonb_agg(row_to_json(x) ORDER BY x.created_at DESC), '[]'::jsonb)
    INTO v_out
  FROM (
    SELECT
      p.id,
      p.display_code,
      p.amount,
      p.amount_paid,
      p.payment_status,
      p.payment_method,
      p.client_reported_method,
      p.client_reported_at,
      p.paid_at,
      p.created_at,
      btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')) AS buyer_name,
      CASE
        WHEN p.payment_status = 'paid' THEN 'paid'
        WHEN p.payment_status = 'pending' OR p.client_reported_at IS NOT NULL THEN 'payment_sent'
        WHEN p.created_at < now() - interval '24 hours' THEN 'overdue'
        ELSE 'awaiting_payment'
      END AS pay_state
    FROM purchases p
    LEFT JOIN contacts c ON c.id = p.buyer_contact_id
    WHERE p.deleted_at IS NULL
      AND p.status <> 'void'
      AND (v_org IS NULL OR p.org_id = v_org)
  ) x;
  RETURN v_out;
END
$$;


--
-- Name: staff_request_horse_record_completion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_request_horse_record_completion(p_horse_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_horse horses%ROWTYPE;
  v_user  uuid;
  v_name  text;
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT * INTO v_horse FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown horse'; END IF;
  SELECT p.user_id INTO v_user FROM profiles p WHERE p.contact_id = v_horse.current_owner_contact_id;
  IF v_user IS NULL THEN RAISE EXCEPTION 'the horse''s owner has no account to notify'; END IF;
  v_name := coalesce(nullif(btrim(v_horse.nickname), ''), v_horse.registered_name, 'your horse');
  RETURN notify_user(
    v_user,
    'horse_record_task',
    'Complete ' || v_name || '''s record',
    'A few details are still needed on ' || v_name || '''s record so their care paperwork can be completed. It only takes a couple of minutes.',
    '/app/horse-intake?horse=' || p_horse_id::text);
END;
$$;


--
-- Name: staff_restore_horse_relationship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_restore_horse_relationship(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_staff_access() THEN
    RAISE EXCEPTION 'staff access required';
  END IF;
  UPDATE horse_relationships SET active = true, ended_at = NULL
   WHERE id = p_id AND org_id = current_org() AND NOT active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'relationship not found or already active';
  END IF;
END;
$$;


--
-- Name: staff_update_horse(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_update_horse(p_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  UPDATE horses SET
    registered_name   = coalesce(nullif(p ->> 'registered_name', ''), registered_name),
    nickname          = CASE WHEN p ? 'nickname' THEN nullif(p ->> 'nickname', '') ELSE nickname END,
    breed             = CASE WHEN p ? 'breed' THEN nullif(p ->> 'breed', '') ELSE breed END,
    color             = CASE WHEN p ? 'color' THEN nullif(p ->> 'color', '') ELSE color END,
    markings          = CASE WHEN p ? 'markings' THEN nullif(p ->> 'markings', '') ELSE markings END,
    sex               = CASE WHEN p ? 'sex' THEN nullif(p ->> 'sex', '') ELSE sex END,
    height            = CASE WHEN p ? 'height' THEN nullif(p ->> 'height', '') ELSE height END,
    current_location  = CASE WHEN p ? 'current_location' THEN nullif(p ->> 'current_location', '') ELSE current_location END,
    fair_market_value = CASE WHEN p ? 'fair_market_value'
                             THEN nullif(replace(replace(p ->> 'fair_market_value', '$', ''), ',', ''), '')::numeric
                             ELSE fair_market_value END,
    updated_at = now()
  WHERE id = p_id AND org_id = current_org() AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse not found in this org'; END IF;
END;
$_$;


--
-- Name: start_bill_of_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_bill_of_sale(p_sale_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale     documents%ROWTYPE;
  v_tkey     text;
  v_doc      uuid;
  v_anchor   uuid;
  v_installments text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to generate a bill of sale'; END IF;

  SELECT * INTO v_sale FROM documents WHERE id = p_sale_document_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown document: %', p_sale_document_id; END IF;
  SELECT template_key INTO v_tkey FROM contract_templates WHERE id = v_sale.template_id;
  IF v_tkey <> 'HORSE_SALE_V3' THEN
    RAISE EXCEPTION 'a bill of sale is generated from a HORSE_SALE_V3 document (got %)', v_tkey;
  END IF;

  SELECT contact_id INTO v_anchor FROM document_parties
   WHERE document_id = p_sale_document_id AND party_role = 'BUYER'
   ORDER BY signer_order NULLS LAST, id LIMIT 1;
  IF v_anchor IS NULL THEN v_anchor := v_sale.contact_id; END IF;

  -- parties mirror the SALE DOCUMENT's parties (co-buyer + signer_order carried)
  v_doc := bos_generate_document(
    v_sale.contract_id, v_anchor, v_sale.horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',dp.contact_id,'role',dp.party_role,'is_signer',dp.is_signer,'signer_order',dp.signer_order))
       FROM document_parties dp WHERE dp.document_id = p_sale_document_id));

  -- prefill every shared field from the sale document's values (parties, horse,
  -- price, co-buyer set) — same field_keys by design; still editable before signing
  UPDATE contract_fields b
     SET value = s.value, updated_at = now()
    FROM contract_fields s
   WHERE b.document_id = v_doc
     AND s.document_id = p_sale_document_id
     AND s.field_key = b.field_key
     AND coalesce(btrim(s.value), '') <> ''
     AND coalesce(btrim(b.value), '') = '';

  UPDATE contract_fields SET value = 'YES'
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';

  -- payment status derives from the sale's installment election (still editable)
  SELECT coalesce(btrim(value), '') INTO v_installments
    FROM contract_fields
   WHERE document_id = p_sale_document_id AND field_key = 'TXN.INSTALLMENTS_ENABLED';
  UPDATE contract_fields
     SET value = CASE v_installments WHEN 'YES' THEN 'INSTALLMENTS'
                                     WHEN 'NO'  THEN 'PAID_IN_FULL'
                                     ELSE '' END
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_PAYMENT_STATUS';

  IF v_sale.horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, v_sale.horse_id);
  END IF;
  -- BOS PPE from the sale's pre-purchase-examination election (owner, corrections
  -- round 2, task 2). Seller-declined and Buyer-waived derive to a locked statement;
  -- Buyer-requested is NOT inferred — the author states Performed or Buyer-Declined,
  -- blocked by a pending until answered. No outcome is ever guessed.
  -- BOS PPE from the sale's pre-purchase-examination election (four-state model,
  -- corrections round 3). Seller-declined and Buyer-waived derive to a locked
  -- statement; Buyer-requested is editable, limited to the two REQUESTED outcomes,
  -- and blank until the author states which occurred (a pending blocks signing).
  DECLARE v_ppe_choice text;
  BEGIN
    SELECT coalesce(btrim(value),'') INTO v_ppe_choice FROM contract_fields
      WHERE document_id = p_sale_document_id AND field_key = 'TXN.PPE_CHOICE';
    IF v_ppe_choice = 'SELLER_DECLINES' THEN
      UPDATE contract_fields SET value='SELLER_DECLINED' WHERE document_id=v_doc AND field_key='TXN.BOS_PPE';
      UPDATE contract_fields SET value='DERIVED'         WHERE document_id=v_doc AND field_key='TXN.BOS_PPE_SOURCE';
    ELSIF v_ppe_choice = 'BUYER_WAIVED' THEN
      UPDATE contract_fields SET value='WAIVED'  WHERE document_id=v_doc AND field_key='TXN.BOS_PPE';
      UPDATE contract_fields SET value='DERIVED' WHERE document_id=v_doc AND field_key='TXN.BOS_PPE_SOURCE';
    ELSIF v_ppe_choice = 'BUYER_REQUESTED' THEN
      UPDATE contract_fields SET value=''       WHERE document_id=v_doc AND field_key='TXN.BOS_PPE';
      UPDATE contract_fields SET value='AUTHOR' WHERE document_id=v_doc AND field_key='TXN.BOS_PPE_SOURCE';
      UPDATE contract_fields
         SET options='[{"label": "Buyer requested one and it was completed before this Bill of Sale", "value": "REQUESTED_COMPLETED"}, {"label": "Buyer requested one and it was not completed before this Bill of Sale", "value": "REQUESTED_NOT_COMPLETED"}]'::jsonb
       WHERE document_id=v_doc AND field_key='TXN.BOS_PPE';
    END IF;
  END;

  PERFORM fill_party_fields_from_contacts(v_doc);
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_sale.contract_id);
END;
$$;


--
-- Name: start_bill_of_sale_standalone(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_bill_of_sale_standalone(p_buyer_contact_id uuid, p_seller_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org      uuid;
  v_contract uuid;
  v_doc      uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a bill of sale'; END IF;
  IF p_buyer_contact_id IS NULL THEN RAISE EXCEPTION 'a buyer contact is required'; END IF;

  SELECT org_id INTO v_org FROM contacts WHERE id = p_buyer_contact_id;

  INSERT INTO contracts (org_id, segment, status, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', current_contact_id(), jsonb_build_object('deal_side','SALE'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_buyer_contact_id, 'BUYER', true, 1);
  IF p_seller_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_seller_contact_id, 'SELLER', true, 2);
  END IF;

  v_doc := bos_generate_document(
    v_contract, p_buyer_contact_id, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract));

  UPDATE contract_fields SET value = 'NO'
   WHERE document_id = v_doc AND field_key = 'TXN.BOS_HAS_SALE_AGREEMENT';

  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract);
END;
$$;


--
-- Name: start_lease_contract_v2(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_lease_contract_v2(p_lessee_contact_id uuid, p_lessor_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_responsible_role text DEFAULT 'LESSEE'::text, p_template_key text DEFAULT 'HORSE_LEASE_V3'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract   uuid;
  v_org        uuid;
  v_doc        uuid;
  v_tmpl       uuid;
  v_originator uuid;
  v_n          int;
  v_key        text;
  v_active     boolean;
  v_deleted    timestamptz;
  v_kind       text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a lease contract'; END IF;
  IF p_lessee_contact_id IS NULL THEN RAISE EXCEPTION 'a lessee contact is required'; END IF;

  -- LEASEFORK: which lease version to author. NULL == not specified == the default.
  v_key := coalesce(p_template_key, 'HORSE_LEASE_V2');

  v_originator := current_contact_id();  -- H1: the company (staff caller) is always the author

  SELECT org_id INTO v_org FROM contacts WHERE id = p_lessee_contact_id;

  -- LEASEFORK: validate the selected template. No silent fallback — a bad key
  -- raises rather than quietly authoring a different contract than was chosen.
  SELECT id, active, deleted_at, contract_kind
    INTO v_tmpl, v_active, v_deleted, v_kind
    FROM contract_templates WHERE template_key = v_key;
  IF v_tmpl IS NULL THEN
    RAISE EXCEPTION 'unknown contract template: %', v_key;
  END IF;
  IF v_kind IS DISTINCT FROM 'HORSE_LEASE' THEN
    RAISE EXCEPTION 'template % is not a lease template (contract_kind = %)',
      v_key, coalesce(v_kind, 'NULL');
  END IF;
  IF NOT v_active OR v_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'template % is not active', v_key;
  END IF;

  -- contract + parties (spine model)
  INSERT INTO contracts (org_id, segment, status, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', v_originator, jsonb_build_object('deal_side','LEASE_IN'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_lessee_contact_id, 'LESSEE', true, 1);
  IF p_lessor_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_lessor_contact_id, 'LESSOR', true, 2);
  END IF;

  -- document shell (same generator the engine uses; body recomposed below)
  SELECT gd.document_id INTO v_doc FROM generate_document(
    p_lessee_contact_id, v_key, v_contract, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract),
    NULL::text) gd;

  -- PARTYCTRL: seed default party controls for every role this document
  -- carries, so the admin panel has rows to render from creation onward.
  INSERT INTO document_party_controls (document_id, party_role, can_fill, can_edit_deal, can_suggest, can_add_clause, org_id)
  SELECT DISTINCT v_doc, dp.party_role, true, true, false, false, v_org
    FROM document_parties dp
   WHERE dp.document_id = v_doc AND dp.party_role NOT IN ('FHE','COMPANY')
  ON CONFLICT (document_id, party_role) DO NOTHING;

  UPDATE documents SET originator_contact_id = v_originator,
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  -- seed fields straight from the clause-model defs (clause_key + responsibility_kind carried)
  -- LEASEFIX 2026-08-09: `value` seeds from d.default_value. NULL for every def that
  -- does not set one, which is the prior behaviour exactly.
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind, value)
  SELECT v_org, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind, d.default_value
    FROM contract_field_defs d
   WHERE d.template_key = v_key;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- fill horse + party identity fields from records (reuse verified paths)
  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);

  -- compose the numbered clause body
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract,
                            'fields_seeded', v_n, 'template_key', v_key);
END;
$$;


--
-- Name: start_sale_contract(uuid, uuid, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_sale_contract(p_buyer_contact_id uuid, p_seller_contact_id uuid DEFAULT NULL::uuid, p_horse_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT NULL::numeric, p_deposit numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contract   uuid;
  v_org        uuid;
  v_doc        uuid;
  v_tmpl       uuid;
  v_originator uuid;
  v_n          int;
  v_horse      horses%ROWTYPE;
  v_lessee_nm  text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized to start a sale contract'; END IF;
  IF p_buyer_contact_id IS NULL THEN RAISE EXCEPTION 'a buyer contact is required'; END IF;

  v_originator := current_contact_id();  -- H1: the company (staff caller) is always the author

  SELECT org_id INTO v_org FROM contacts WHERE id = p_buyer_contact_id;
  SELECT id INTO v_tmpl FROM contract_templates WHERE template_key = 'HORSE_SALE_V3';
  IF v_tmpl IS NULL THEN RAISE EXCEPTION 'HORSE_SALE_V3 template missing'; END IF;

  -- contract + parties (spine model)
  INSERT INTO contracts (org_id, segment, status, originator_contact_id, terms)
    VALUES (v_org, 'acquisition', 'draft', v_originator, jsonb_build_object('deal_side','SALE'))
    RETURNING id INTO v_contract;
  INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
    VALUES (v_org, v_contract, p_buyer_contact_id, 'BUYER', true, 1);
  IF p_seller_contact_id IS NOT NULL THEN
    INSERT INTO contract_parties (org_id, contract_id, contact_id, party_role, is_signer, signer_order)
      VALUES (v_org, v_contract, p_seller_contact_id, 'SELLER', true, 2);
  END IF;

  -- document shell (same generator the engine uses; body recomposed below)
  SELECT gd.document_id INTO v_doc FROM generate_document(
    p_buyer_contact_id, 'HORSE_SALE_V3', v_contract, p_horse_id,
    (SELECT jsonb_agg(jsonb_build_object('contact_id',cp.contact_id,'role',cp.party_role,'is_signer',cp.is_signer,'signer_order',cp.signer_order))
       FROM contract_parties cp WHERE cp.contract_id = v_contract),
    NULL::text) gd;

  -- PARTYCTRL: seed default party controls for every role this document
  -- carries, so the admin panel has rows to render from creation onward.
  INSERT INTO document_party_controls (document_id, party_role, can_fill, can_edit_deal, can_suggest, can_add_clause, org_id)
  SELECT DISTINCT v_doc, dp.party_role, true, true, false, false, v_org
    FROM document_parties dp
   WHERE dp.document_id = v_doc AND dp.party_role NOT IN ('FHE','COMPANY')
  ON CONFLICT (document_id, party_role) DO NOTHING;

  UPDATE documents SET originator_contact_id = v_originator,
                       workflow_state = 'editable', status = 'AWAITING_SIGNATURE'
   WHERE id = v_doc;

  -- seed fields straight from the clause-model defs (clause_key + responsibility_kind carried)
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, v_doc, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = 'HORSE_SALE_V3';
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- deal terms handed in at start
  IF p_amount IS NOT NULL THEN
    UPDATE contract_fields SET value = p_amount::text
     WHERE document_id = v_doc AND field_key = 'TXN.PURCHASE_PRICE';
  END IF;
  IF p_deposit IS NOT NULL THEN
    UPDATE contract_fields SET value = p_deposit::text
     WHERE document_id = v_doc AND field_key = 'TXN.DEPOSIT_AMOUNT';
    UPDATE contract_fields SET value = 'YES'
     WHERE document_id = v_doc AND field_key = 'TXN.DEPOSIT_ENABLED';
  END IF;

  -- fill horse + party identity fields from records (reuse verified paths)
  IF p_horse_id IS NOT NULL THEN
    PERFORM attach_horse_to_document(v_doc, p_horse_id);
    SELECT * INTO v_horse FROM horses WHERE id = p_horse_id;

    -- owner ruling: an actively-leased horse is sellable; prefill the
    -- encumbrances election toward YES identifying the lease (still editable).
    IF v_horse.lessee_contact_id IS NOT NULL
       AND (v_horse.lease_end IS NULL OR v_horse.lease_end >= current_date) THEN
      SELECT nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), '')
        INTO v_lessee_nm FROM contacts c WHERE c.id = v_horse.lessee_contact_id;
      UPDATE contract_fields SET value = 'YES'
       WHERE document_id = v_doc AND field_key = 'TXN.HAS_ENCUMBRANCES'
         AND coalesce(btrim(value), '') = '';
      UPDATE contract_fields
         SET value = 'The Horse is currently under an active lease to '
                     || coalesce(v_lessee_nm, 'the lessee of record')
                     || coalesce(' through ' || to_char(v_horse.lease_end, 'FMMonth FMDD, YYYY'), '')
                     || '.'
       WHERE document_id = v_doc AND field_key = 'TXN.DISCLOSED_ENCUMBRANCES'
         AND coalesce(btrim(value), '') = '';
    END IF;
  END IF;
  PERFORM fill_party_fields_from_contacts(v_doc);

  -- compose the numbered clause body
  PERFORM remerge_contract_from_clauses(v_doc);

  RETURN jsonb_build_object('document_id', v_doc, 'contract_id', v_contract, 'fields_seeded', v_n);
END;
$$;


--
-- Name: status_feed(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.status_feed(p_entity_type text DEFAULT NULL::text, p_true_only boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS TABLE(entity_type text, entity_id uuid, status text, display_name text, is_true_status boolean, detail text, actor_user_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.entity_type, e.entity_id, e.status, v.display_name, v.is_true_status,
         e.detail, e.actor_user_id, e.created_at
    FROM status_events e
    JOIN status_events_vocab v ON v.entity_type = e.entity_type AND v.code = e.status
   WHERE coalesce(has_staff_access() AND e.org_id = current_org(), false)
     AND (p_entity_type IS NULL OR e.entity_type = p_entity_type)
     AND (NOT p_true_only OR v.is_true_status)
   ORDER BY e.created_at DESC
   LIMIT greatest(1, least(coalesce(p_limit, 100), 500));
$$;


--
-- Name: submit_acquisition_intake(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_acquisition_intake(p_purchase_item_id uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact uuid := current_contact_id();
  v_org     uuid;
  v_owns    boolean;
BEGIN
  IF v_contact IS NULL THEN RAISE EXCEPTION 'sign in to submit intake'; END IF;

  -- the line must belong to a purchase this member owns (contact or user grain)
  SELECT pu.org_id, true INTO v_org, v_owns
    FROM purchase_items pi
    JOIN purchases pu ON pu.id = pi.purchase_id
   WHERE pi.id = p_purchase_item_id
     AND (pu.buyer_contact_id = v_contact OR pu.buyer_user_id = auth.uid());
  IF NOT coalesce(v_owns, false) THEN RAISE EXCEPTION 'that purchase is not yours'; END IF;

  UPDATE purchase_items
     SET config = coalesce(config, '{}'::jsonb)
                  || coalesce(p_data, '{}'::jsonb)
                  || jsonb_build_object('submitted_at', now())
   WHERE id = p_purchase_item_id;

  -- let staff know the brief/intake is in
  -- TASK-FIX3: was '/app/ops/oversight', which no longer resolves.
  PERFORM notify_staff(v_org, 'acquisition_intake_submitted',
    'A client submitted their acquisition intake', '/app/records/deals');

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: submit_change_requests(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_change_requests(p_document_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_title text; v_cid uuid;
  v_next int; v_n int := 0; r record;
  v_top jsonb; v_body text; v_ids uuid[] := '{}';
  v_party record; v_me_label text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, workflow_state, coalesce(title,'A contract')
    INTO v_org, v_state, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  SELECT contact_id, label INTO v_cid, v_me_label FROM comment_author_identity(p_document_id);

  SELECT coalesce(max(annotation_number), 0) INTO v_next
    FROM contract_change_requests WHERE document_id = p_document_id;

  -- lock every unsubmitted draft this caller authored
  FOR r IN
    SELECT id FROM contract_change_requests
     WHERE document_id = p_document_id AND parent_request_id IS NULL
       AND author_contact_id = v_cid AND submitted_at IS NULL
     ORDER BY created_at
  LOOP
    v_next := v_next + 1; v_n := v_n + 1;
    UPDATE contract_change_requests
       SET submitted_at = now(), annotation_number = v_next, updated_at = now()
     WHERE id = r.id;
    v_ids := v_ids || r.id;
  END LOOP;

  IF v_n = 0 THEN
    RETURN jsonb_build_object('submitted', 0, 'notified', 0);
  END IF;

  -- the FIVE highest-impact requests just submitted (impact desc, then earliest)
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'annotation_number', t.annotation_number,
           'target_section', t.target_section,
           'heading', t.heading,
           'impact_rank', t.impact_rank,
           'body', t.body) ORDER BY t.impact_rank DESC, t.annotation_number), '[]'::jsonb)
    INTO v_top
    FROM (
      SELECT cr.annotation_number, cr.target_section, cr.impact_rank, cr.body,
             coalesce(sd.heading, 'The whole document') AS heading
        FROM contract_change_requests cr
        LEFT JOIN documents d ON d.id = cr.document_id
        LEFT JOIN contract_templates ct ON ct.id = d.template_id
        LEFT JOIN contract_section_defs sd
               ON sd.template_key = ct.template_key AND sd.section_key = cr.target_section
       WHERE cr.id = ANY(v_ids)
       ORDER BY cr.impact_rank DESC, cr.annotation_number
       LIMIT 5
    ) t;

  SELECT string_agg('#' || (e->>'annotation_number') || ' ' || (e->>'heading') || ' — ' ||
                    left(e->>'body', 160), E'\n' ORDER BY ord)
    INTO v_body
    FROM jsonb_array_elements(v_top) WITH ORDINALITY AS x(e, ord);

  -- notify every OTHER party (dashboard notification via contract_notify, which
  -- resolves the contact's app user and links back to this document).
  FOR v_party IN
    SELECT DISTINCT dp.contact_id
      FROM document_parties dp
     WHERE dp.document_id = p_document_id
       AND dp.contact_id IS DISTINCT FROM v_cid
  LOOP
    PERFORM contract_notify(p_document_id, v_party.contact_id,
      'contract_change_requested',
      coalesce(v_me_label,'A party') || ' submitted ' || v_n || ' change request'
        || CASE WHEN v_n = 1 THEN '' ELSE 's' END || ' on ' || v_title,
      v_body);
  END LOOP;

  RETURN jsonb_build_object(
    'submitted', v_n,
    'top', v_top,
    'notify_parties', coalesce((
      SELECT jsonb_agg(DISTINCT dp.contact_id)
        FROM document_parties dp
       WHERE dp.document_id = p_document_id
         AND dp.contact_id IS DISTINCT FROM v_cid), '[]'::jsonb));
END;
$$;


--
-- Name: submit_my_booking_request(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_booking_request(p_purchase_id uuid, p_slots jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid      uuid := auth.uid();
  v_contact  uuid := current_contact_id();
  v_org      uuid := current_org();
  v_pu       purchases%ROWTYPE;
  v_slot     jsonb;
  v_item     purchase_items%ROWTYPE;
  v_start    timestamptz;
  v_end      timestamptz;
  v_booking  uuid;
  v_bookings uuid[] := '{}';
  v_first    timestamptz;
  v_request  uuid;
  v_name     text;
  v_email    text;
  v_times    jsonb := '[]'::jsonb;
  v_result   jsonb;
  v_offering uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_slots IS NULL OR jsonb_typeof(p_slots) <> 'array' OR jsonb_array_length(p_slots) = 0 THEN
    RAISE EXCEPTION 'pick a day and time for what you are booking';
  END IF;

  SELECT * INTO v_pu FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'that order does not exist'; END IF;
  IF NOT (v_pu.buyer_user_id = v_uid
          OR (v_contact IS NOT NULL AND v_pu.buyer_contact_id = v_contact)) THEN
    RAISE EXCEPTION 'that order is not yours';
  END IF;
  IF coalesce(v_pu.status, '') <> 'draft' THEN
    RAISE EXCEPTION 'that order has already been submitted';
  END IF;
  IF EXISTS (SELECT 1 FROM bookings b
              WHERE b.purchase_id = p_purchase_id AND b.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'a time has already been requested for that order';
  END IF;

  FOR v_slot IN SELECT * FROM jsonb_array_elements(p_slots) LOOP
    SELECT * INTO v_item FROM purchase_items
     WHERE id = (v_slot->>'item_id')::uuid
       AND purchase_id = p_purchase_id AND voided_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'that item is not on this order'; END IF;

    v_start := (v_slot->>'starts_at')::timestamptz;
    v_end   := (v_slot->>'ends_at')::timestamptz;

    -- ⚠️ THE BOOKING WRITER IS `request_open_time` AND IT IS NOT COPIED HERE
    -- (D18/D35 — it is TASK-LIFECYCLE's function). It validates the times,
    -- refuses a past one, opens the staff decision row and raises the in-app
    -- staff notification. This adds the order link it has no argument for.
    v_result  := request_open_time(v_start, v_end, v_item.offering_id, NULL, p_note);
    v_booking := (v_result->>'booking_id')::uuid;
    v_bookings := v_bookings || v_booking;
    IF v_first IS NULL OR v_start < v_first THEN v_first := v_start; END IF;
    IF v_offering IS NULL THEN v_offering := v_item.offering_id; END IF;

    UPDATE bookings SET purchase_id = p_purchase_id WHERE id = v_booking;

    v_times := v_times || jsonb_build_array(jsonb_build_object(
      'label', coalesce(v_item.label, 'A session') || ' — '
               || to_char(v_start, 'FMDay, FMMon FMDD YYYY') || ' at '
               || to_char(v_start, 'FMHH12:MI AM')));
  END LOOP;

  -- The inbound-alert row: one per SUBMISSION, carrying every requested time.
  SELECT nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''),
         c.email INTO v_name, v_email
    FROM contacts c WHERE c.id = v_contact;

  IF v_email IS NOT NULL AND v_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    INSERT INTO requests (
      org_id, contact_id, contact_name, contact_first_name, contact_last_name,
      contact_email, contact_phone, channel, category, entry_location,
      subject, notes, proposed_times, status)
    SELECT v_org, v_contact, coalesce(v_name, v_email), c.first_name, c.last_name, v_email,
           CASE WHEN c.phone ~ '^[-+().0-9[:space:]]{7,32}$' THEN c.phone END,
           'booking',
           CASE WHEN o.segment = 'horse' THEN 'horse_care' ELSE 'lessons' END,
           'onboarding',
           'Booking request — ' || coalesce(v_pu.display_code, 'a new order'),
           nullif(btrim(coalesce(p_note, '')), ''),
           v_times, 'new'
      FROM contacts c
      LEFT JOIN offerings o ON o.id = v_offering
     WHERE c.id = v_contact
    RETURNING id INTO v_request;
  END IF;

  IF v_request IS NOT NULL THEN
    UPDATE bookings SET request_id = v_request WHERE id = ANY(v_bookings);
    UPDATE purchases SET request_id = v_request WHERE id = p_purchase_id;
    INSERT INTO request_selections (request_id, org_id, offering_id, label, origin)
    SELECT v_request, v_org, pi.offering_id, pi.label, 'onboarding'
      FROM purchase_items pi
     WHERE pi.purchase_id = p_purchase_id AND pi.voided_at IS NULL;
  END IF;

  -- CR-98 step 8: release the run held since the sign step and send the ONE
  -- email — documents attached, order and requested times in the body.
  BEGIN
    PERFORM deliver_executed_document_set(
      v_contact, NULL,
      jsonb_build_object('purchaseId', p_purchase_id, 'bookingId', v_bookings[1]));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'signed-document set not delivered for %: %', v_contact, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'booking_ids', to_jsonb(v_bookings),
    'request_id', v_request,
    'purchase_id', p_purchase_id,
    'first_starts_at', v_first,
    'status', v_result->>'status');
END;
$_$;


--
-- Name: submit_public_request(text, text, text, text, text, text, jsonb, text, text, text, text, jsonb, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_public_request(p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text, p_contact_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_proposed_times jsonb DEFAULT '[]'::jsonb, p_category text DEFAULT NULL::text, p_channel text DEFAULT 'contact'::text, p_entry_location text DEFAULT NULL::text, p_intent text DEFAULT NULL::text, p_selections jsonb DEFAULT '[]'::jsonb, p_details jsonb DEFAULT '{}'::jsonb, p_interests text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org   uuid := coalesce(current_org(), current_addressed_org(), sole_org());
  v_first text := NULLIF(btrim(coalesce(p_first_name, '')), '');
  v_last  text := NULLIF(btrim(coalesce(p_last_name, '')), '');
  v_email text := lower(NULLIF(btrim(coalesce(p_email, '')), ''));
  v_phone text := NULLIF(btrim(coalesce(p_phone, '')), '');
  v_notes text := NULLIF(btrim(coalesce(p_notes, '')), '');
  v_details jsonb := CASE WHEN jsonb_typeof(p_details) = 'object' THEN p_details ELSE '{}'::jsonb END;
  v_id    uuid;
  v_sel   jsonb;
  v_contact  uuid;
  v_purchase uuid;
  v_lines    integer := 0;
  v_has_lesson boolean := false;   -- LESSONREQUEST §L1
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'could not resolve an organization for this request';
  END IF;
  IF v_first IS NULL THEN RAISE EXCEPTION 'first name is required'; END IF;
  IF v_last  IS NULL THEN RAISE EXCEPTION 'last name is required'; END IF;
  IF v_email IS NULL THEN RAISE EXCEPTION 'email is required'; END IF;
  IF v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'that email address does not look valid';
  END IF;
  IF v_phone IS NOT NULL AND v_phone !~ '^[-+().0-9[:space:]]{7,32}$' THEN
    RAISE EXCEPTION 'that phone number does not look valid';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 4000 THEN
    RAISE EXCEPTION 'your message is too long (max 4000 characters)';
  END IF;
  IF p_contact_method IS NOT NULL AND p_contact_method NOT IN ('text','call','email') THEN
    RAISE EXCEPTION 'invalid contact method';
  END IF;

  -- ── LESSONREQUEST §L1 — STEP 2 IS NOT OPTIONAL ON THE LESSON PATH ────────
  -- Checked BEFORE anything is written: a rejected inquiry must leave no row,
  -- no lead and no order behind. The selections have not been resolved yet, so
  -- the lesson test runs against the payload the caller sent, matching an
  -- offering by id OR slug exactly as the resolution loop below does.
  SELECT EXISTS (
    SELECT 1
      FROM jsonb_array_elements(coalesce(p_selections, '[]'::jsonb)) s
      JOIN offerings o
        ON o.org_id = v_org
       AND (o.id = nullif(s->>'offering_id', '')::uuid
            OR o.slug = nullif(s->>'offering_slug', ''))
     WHERE o.segment = 'rider'
  ) INTO v_has_lesson;

  IF v_has_lesson
     AND coalesce(p_channel, 'contact') = 'booking'
     AND EXISTS (SELECT 1 FROM intake_requirements ir
                  WHERE ir.org_id = v_org AND ir.channel = 'booking'
                    AND ir.field_key = 'availability' AND ir.required)
     AND jsonb_array_length(coalesce(p_proposed_times, '[]'::jsonb)) = 0
  THEN
    RAISE EXCEPTION 'please tell us when you are available before sending a lesson inquiry';
  END IF;

  -- ── CLOSEOUT §3.4 (LESSONREQUEST G2) — experience, same gate shape ────────
  -- Client-side-only enforcement is a request, not a rule. The same
  -- intake_requirements row the form reads decides here too, so switching the
  -- requirement off in config releases both ends together.
  IF v_has_lesson
     AND coalesce(p_channel, 'contact') = 'booking'
     AND EXISTS (SELECT 1 FROM intake_requirements ir
                  WHERE ir.org_id = v_org AND ir.channel = 'booking'
                    AND ir.field_key = 'experience' AND ir.required)
     AND nullif(btrim(coalesce(v_details->>'Riding experience (years)', '')), '') IS NULL
  THEN
    RAISE EXCEPTION 'please tell us the rider''s experience before sending a lesson inquiry';
  END IF;

  INSERT INTO requests (
    org_id, status, contact_name, contact_first_name, contact_last_name,
    contact_email, contact_phone, contact_method, proposed_times, notes,
    category, channel, entry_location, intent, details, interests
  ) VALUES (
    v_org, 'new', v_first || ' ' || v_last, v_first, v_last,
    v_email, v_phone, p_contact_method, coalesce(p_proposed_times, '[]'::jsonb), v_notes,
    p_category, coalesce(p_channel, 'contact'), p_entry_location, p_intent, v_details,
    -- the checkboxes, de-duplicated and blank-stripped; NULL when none were ticked
    (SELECT array_agg(DISTINCT x) FROM unnest(coalesce(p_interests, '{}')) x WHERE btrim(x) <> '')
  )
  RETURNING id INTO v_id;

  -- cart selections (Checkout) — resolve each offering to its row in-tenant.
  --
  -- ⚠️ ASKRIGHT F3, FIXED HERE. This loop matched on `o.slug` alone while the
  -- checkout sent the offering UUID in the slug key, so it never matched, fell
  -- into the IF NOT FOUND branch, and wrote a row with a UUID in the slug
  -- column and a NULL offering_id — every one of the 7 production selections
  -- looks like that. An inquiry's offerings were linked to the catalog by label
  -- TEXT only. §C5's order needs the real id, so both keys are now accepted and
  -- offering_id is the truth.
  FOR v_sel IN SELECT * FROM jsonb_array_elements(coalesce(p_selections, '[]'::jsonb))
  LOOP
    INSERT INTO request_selections (request_id, org_id, offering_id, offering_slug, label)
    SELECT v_id, v_org, o.id, o.slug, (v_sel->>'label')
      FROM offerings o
      WHERE o.org_id = v_org
        AND (o.id = nullif(v_sel->>'offering_id', '')::uuid
             OR o.slug = nullif(v_sel->>'offering_slug', ''))
      LIMIT 1;
    IF NOT FOUND THEN
      INSERT INTO request_selections (request_id, org_id, offering_slug, label)
        VALUES (v_id, v_org, (v_sel->>'offering_slug'), (v_sel->>'label'));
    END IF;
  END LOOP;

  -- The `requests_capture_contact` AFTER INSERT trigger has already run by now:
  -- it deduped or created the LEAD contact and stamped requests.contact_id.
  -- THAT contact is the lead (owner taxonomy: identity + intent, no account),
  -- and it is who the order belongs to.
  SELECT r.contact_id INTO v_contact FROM requests r WHERE r.id = v_id;

  -- ── §C5b — THE ORDER ─────────────────────────────────────────────────────
  -- Opened only when at least one selection resolved to a real catalog row. A
  -- /contact-form message carries no selections and must not manufacture an
  -- empty order; "everything is an order" is about what people BUY.
  SELECT count(*) INTO v_lines
    FROM request_selections rs WHERE rs.request_id = v_id AND rs.offering_id IS NOT NULL;

  IF v_lines > 0 THEN
    -- draft + unpaid. NOTHING IS OWED (rule 4): no payment surface, receipt,
    -- reminder or balance may treat this as payable until the one act in §C8
    -- confirms it. `buyer_user_id` stays NULL — there is no account yet, which
    -- is precisely what "lead" means.
    INSERT INTO purchases (org_id, request_id, buyer_contact_id, status, amount, payment_status)
    SELECT v_org, v_id, v_contact, 'draft',
           coalesce(sum(o.price_amount), 0), 'unpaid'
      FROM request_selections rs
      JOIN offerings o ON o.id = rs.offering_id
     WHERE rs.request_id = v_id
    RETURNING id INTO v_purchase;

    INSERT INTO purchase_items (purchase_id, org_id, offering_id, label, price_amount, price_unit)
    SELECT v_purchase, v_org, o.id, coalesce(rs.label, o.name), coalesce(o.price_amount, 0),
           -- 'lesson' is a UI-only unit; the check constraint knows 'session'.
           CASE WHEN o.price_unit = 'lesson' THEN 'session' ELSE o.price_unit END
      FROM request_selections rs
      JOIN offerings o ON o.id = rs.offering_id
     WHERE rs.request_id = v_id;

    -- The ops-board distinction, without a new purchases.status value: this
    -- order came from a visitor and is waiting on a call, and a staff-made
    -- draft (current_status NULL) is a different thing.
    PERFORM log_status_event('order', v_purchase, 'enquiry',
      'Opened by a website inquiry — nothing is owed until it is confirmed', v_org);
  END IF;

  -- alert the barn: in-app to every staff/owner (mirrored to co-admins by the
  -- notifications trigger). Email is sent separately by the /api/request-received
  -- and /api/inquiry-confirmation endpoints the public form calls after this returns.
  -- ⚠️ THE BELL HAS TO SAY WHAT IT IS. Owner, 2026-09-01: *"if they are
  -- communicating something like wanting to visit us, wouldnt we need to see that
  -- in a place we can take action on it as quickly as possible?"* A visit is a
  -- person planning to stand on the property, and it is time-bound in a way an
  -- ordinary enquiry is not — so it is named in the title rather than left for
  -- somebody to find by opening the row. The interests ride along for the same
  -- reason: they are the whole point of having asked.
  PERFORM notify_staff(
    v_org,
    CASE WHEN p_category = 'visit' OR 'visit' = ANY(coalesce(p_interests, '{}'))
         THEN 'request_visit' ELSE 'request_new' END,
    CASE WHEN p_category = 'visit' THEN 'VISIT REQUEST from '
         WHEN 'visit' = ANY(coalesce(p_interests, '{}')) THEN 'Wants to visit — '
         ELSE 'New inquiry from ' END
    || coalesce(nullif(btrim(v_first || ' ' || v_last), ''), v_email)
    || CASE
         WHEN p_category = 'visit' AND coalesce(array_length(p_interests, 1), 0) > 0
           THEN ' — interested in ' || array_to_string(
                  ARRAY(SELECT request_category_label(x) FROM unnest(p_interests) x
                         WHERE x <> 'visit'), ', ')
         ELSE ''
       END,
    '/app/ops/intake');

  RETURN jsonb_build_object(
    'request_id', v_id, 'status', 'new',
    'purchase_id', v_purchase, 'contact_id', v_contact);
END;
$_$;


--
-- Name: submit_support_request(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_support_request(p_subject text, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid := current_org();
  v_id   uuid;
  v_base text;
  v_req  bigint;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'no org context';
  END IF;
  IF p_subject IS NULL OR btrim(p_subject) = '' OR p_body IS NULL OR btrim(p_body) = '' THEN
    RAISE EXCEPTION 'subject and message are required';
  END IF;

  INSERT INTO support_requests (org_id, user_id, subject, body)
  VALUES (v_org, auth.uid(), btrim(p_subject), btrim(p_body))
  RETURNING id INTO v_id;

  -- alert the barn: in-app to every staff/owner, mirroring how
  -- submit_public_request notifies on a new inquiry.
  PERFORM notify_staff(
    v_org, 'support_new',
    'New support request: ' || btrim(p_subject),
    '/app/ops/support');

  -- email the ops inbox (best-effort; never blocks the member's submission).
  BEGIN
    SELECT value_text INTO v_base FROM config_values
     WHERE org_id = v_org AND namespace = 'SYSTEM' AND key = 'APP_BASE_URL';
    IF coalesce(btrim(v_base), '') <> '' THEN
      SELECT net.http_post(
               url     := v_base || '/api/support-received',
               body    := jsonb_build_object('requestId', v_id::text),
               headers := '{"Content-Type": "application/json"}'::jsonb
             ) INTO v_req;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- never let a mail-dispatch failure roll back the support request itself
    NULL;
  END;

  RETURN v_id;
END;
$$;


--
-- Name: suggested_category_for_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggested_category_for_contact(p_contact_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH signed AS (
    SELECT DISTINCT t.template_key
    FROM document_parties dp
    JOIN documents d ON d.id = dp.document_id AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
    JOIN contract_templates t ON t.id = d.template_id
    WHERE dp.contact_id = p_contact_id
  )
  SELECT jsonb_build_object(
    'suggested', CASE
      WHEN EXISTS (SELECT 1 FROM signed WHERE template_key IN ('RELEASE_HORSE_CARE','HORSE_EMERGENCY_VET'))
        THEN 'HORSE_OWNER'
      WHEN EXISTS (SELECT 1 FROM signed WHERE template_key IN ('RELEASE_PARTICIPANT','RIDER_LESSON','RIDER_LESSON_JUMPER','MINOR_RIDER'))
        THEN 'RIDER'
      ELSE 'GUEST'
    END,
    'executed_templates', coalesce((SELECT array_agg(template_key ORDER BY template_key) FROM signed), ARRAY[]::text[])
  );
$$;


--
-- Name: supersede_invitations(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supersede_invitations(p_org uuid, p_email text, p_new_invitation_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  WITH superseded AS (
    UPDATE invitations
       SET status = 'superseded', superseded_by = p_new_invitation_id
     WHERE org_id = p_org
       AND lower(email) = lower(p_email)
       AND id <> p_new_invitation_id
       AND status = 'sent'
       AND deleted_at IS NULL
    RETURNING 1)
  SELECT count(*) INTO v_count FROM superseded;

  UPDATE invitations SET resend_of = (
    SELECT id FROM invitations
     WHERE org_id = p_org AND lower(email) = lower(p_email)
       AND id <> p_new_invitation_id AND status = 'superseded'
     ORDER BY created_at DESC LIMIT 1)
   WHERE id = p_new_invitation_id AND resend_of IS NULL;

  RETURN v_count;
END;
$$;


--
-- Name: swap_booking_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.swap_booking_item(p_booking_id uuid, p_credit_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_b        bookings%ROWTYPE;
  v_client   uuid := current_client_id();
  v_staff    boolean := coalesce(has_staff_access(), false);
  v_mine     boolean;
  v_role     text;
  v_to       lesson_credits%ROWTYPE;
  v_to_seg   text;
  v_to_label text;
  v_from     lesson_credits%ROWTYPE;
  v_from_lbl text;
  v_debited  uuid;
  v_refunded boolean := false;
BEGIN
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking not found'; END IF;

  v_mine := v_client IS NOT NULL AND v_b.client_id = v_client;
  IF v_staff THEN
    v_role := 'staff';
    IF v_b.org_id IS DISTINCT FROM current_org() THEN
      RAISE EXCEPTION 'that booking is not in your organization';
    END IF;
  ELSIF v_mine THEN
    v_role := 'client';
    -- ONBOARD §7's boundary, reused: a request is still yours; a confirmation is ours.
    IF v_b.status NOT IN ('requested','pending') THEN
      RAISE EXCEPTION 'NOT_PENDING: we have already confirmed this booking — ask us and we will move it for you';
    END IF;
  ELSE
    RAISE EXCEPTION 'not authorized to change this booking';
  END IF;

  IF v_b.status IN ('completed','cancelled','expired','no_show') THEN
    RAISE EXCEPTION 'BOOKING_CLOSED: this booking is % — there is nothing left to charge', v_b.status;
  END IF;
  IF v_b.client_id IS NULL THEN
    RAISE EXCEPTION 'BOOKING_UNASSIGNED: this booking has no client to charge';
  END IF;

  -- ── the target has to be real, theirs, live, unexpired, and have something left ──
  SELECT * INTO v_to FROM lesson_credits
   WHERE id = p_credit_id AND client_id = v_b.client_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NO_SUCH_ITEM: that purchased item does not belong to this client';
  END IF;
  IF v_to.id = v_b.credit_id THEN
    RAISE EXCEPTION 'ALREADY_ON_THAT_ITEM: this booking is already charged against that item';
  END IF;
  IF v_to.expires_at IS NOT NULL AND v_to.expires_at <= now() THEN
    RAISE EXCEPTION 'ITEM_EXPIRED: that allotment ran out on % and does not carry over',
      to_char(v_to.expires_at - interval '1 day', 'FMMon FMDD, YYYY');
  END IF;

  SELECT o.segment, coalesce(o.name, v_to.package_key, 'Lesson credit')
    INTO v_to_seg, v_to_label
    FROM offerings o WHERE o.id = v_to.offering_id;
  v_to_label := coalesce(v_to_label, v_to.package_key, 'Lesson credit');

  -- same segment rule book_open_slot enforces at booking time.
  IF v_b.kind = 'care' AND coalesce(v_to_seg, '') <> 'horse' THEN
    RAISE EXCEPTION 'WRONG_SERVICE: "%" is not a horse-care item, so it cannot pay for a care booking', v_to_label;
  END IF;
  IF v_b.kind = 'lesson' AND coalesce(v_to_seg, '') = 'horse' THEN
    RAISE EXCEPTION 'WRONG_SERVICE: "%" is a horse-care item, so it cannot pay for a lesson', v_to_label;
  END IF;

  -- ── DEBIT FIRST. If there is nothing to take, the booking is untouched. ──
  UPDATE lesson_credits SET credits_remaining = credits_remaining - 1
   WHERE id = v_to.id AND credits_remaining > 0
   RETURNING id INTO v_debited;
  IF v_debited IS NULL THEN
    RAISE EXCEPTION 'NO_ENTITLEMENT: "%" has nothing left to book with', v_to_label;
  END IF;

  -- ── THEN REFUND, through the one seam. Same transaction, so the pair is atomic. ──
  IF v_b.credit_id IS NOT NULL THEN
    SELECT * INTO v_from FROM lesson_credits WHERE id = v_b.credit_id;
    SELECT coalesce(o.name, v_from.package_key, 'Lesson credit') INTO v_from_lbl
      FROM offerings o WHERE o.id = v_from.offering_id;
    v_from_lbl := coalesce(v_from_lbl, v_from.package_key, 'Lesson credit');
    v_refunded := _refund_booking_credit(v_b);
  END IF;

  UPDATE bookings SET
    credit_id   = v_to.id,
    offering_id = coalesce(v_to.offering_id, offering_id),
    purchase_id = coalesce(v_to.purchase_id, purchase_id),
    updated_at  = now()
  WHERE id = p_booking_id;

  INSERT INTO booking_item_swaps (
    org_id, booking_id, swapped_by, swapped_by_role, booking_status_at,
    from_credit_id, from_offering_id, from_purchase_id, from_label,
    to_credit_id, to_offering_id, to_purchase_id, to_label)
  VALUES (v_b.org_id, p_booking_id, auth.uid(), v_role, v_b.status,
          v_b.credit_id, v_from.offering_id, v_from.purchase_id, v_from_lbl,
          v_to.id, v_to.offering_id, v_to.purchase_id, v_to_label);

  -- The company confirms bookings, so it needs to know when the thing it confirmed
  -- gets re-charged to something else.
  IF v_role = 'client' THEN
    PERFORM notify_staff(v_b.org_id, 'booking_item_swapped',
      'A client re-assigned ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM')
        || ' to ' || v_to_label, '/app/calendar');
  ELSIF v_b.account_user_id IS NOT NULL THEN
    INSERT INTO notifications (org_id, user_id, kind, title, link)
      VALUES (v_b.org_id, v_b.account_user_id, 'booking_item_swapped',
              'Your ' || to_char(v_b.starts_at, 'FMMon FMDD') || ' booking is now against ' || v_to_label,
              '/app/calendar');
  END IF;

  RETURN jsonb_build_object(
    'booking_id', p_booking_id,
    'from_credit_id', v_b.credit_id, 'from_label', v_from_lbl,
    'to_credit_id', v_to.id, 'to_label', v_to_label,
    'refunded', v_refunded,
    'by', v_role);
END;
$$;


--
-- Name: FUNCTION swap_booking_item(p_booking_id uuid, p_credit_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.swap_booking_item(p_booking_id uuid, p_credit_id uuid) IS 'CREDITALIGN A2: re-charge a booking from one purchased item to another. Debit first, then refund through _refund_booking_credit (the one refund seam) — one function, one transaction. Client while pending, staff any time. Refuses with a readable reason when the target is expired, empty, the wrong segment or not theirs; never mints.';


--
-- Name: sweep_undelivered_executed_documents(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_undelivered_executed_documents(p_limit integer DEFAULT 500) RETURNS TABLE(document_id uuid, org_id uuid, missing_count bigint, notified boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_doc documents%ROWTYPE;
  v_names text;
  v_link text;
BEGIN
  FOR r IN
    SELECT u.document_id, u.missing_recipients
    FROM undelivered_executed_documents(p_limit, 0) u
  LOOP
    SELECT * INTO v_doc FROM documents WHERE id = r.document_id AND deleted_at IS NULL;
    IF NOT FOUND THEN CONTINUE; END IF;

    -- only genuinely-stamped-but-undelivered docs alert (stamp NULL = email
    -- was never queued at all — a different, already-known condition).
    IF v_doc.executed_email_sent_at IS NULL THEN CONTINUE; END IF;
    IF v_doc.executed_email_sent_at >= now() - interval '10 minutes' THEN CONTINUE; END IF;
    -- already alerted once for this document — never repeat.
    IF v_doc.executed_email_error IS NOT NULL THEN CONTINUE; END IF;

    -- recompute the missing-recipient names with the identical join predicate
    -- the finder used for its count, for a title that names who is missing.
    SELECT string_agg(
             coalesce(nullif(btrim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''), c.email)
               || ' (' || dp.party_role || ')',
             ', ' ORDER BY c.first_name)
      INTO v_names
      FROM document_parties dp
      JOIN contacts c ON c.id = dp.contact_id AND coalesce(btrim(c.email), '') <> ''
      LEFT JOIN document_deliveries dd
             ON dd.document_id = dp.document_id
            AND dd.recipient_contact_id = dp.contact_id
            AND dd.channel = 'EMAIL'
            AND dd.deleted_at IS NULL
     WHERE dp.document_id = v_doc.id
       AND dd.id IS NULL;

    IF coalesce(btrim(v_names), '') = '' THEN CONTINUE; END IF; -- recompute found nothing (race) — skip, don't alert on stale data

    v_link := '/app/ops/documents/' || v_doc.id;
    PERFORM notify_staff(
      v_doc.org_id, 'delivery_failure',
      coalesce(v_doc.title, 'Document') ||
        coalesce(' (' || v_doc.display_code || ')', '') ||
        ' — delivery failed for: ' || v_names,
      v_link);

    UPDATE documents
       SET executed_email_error = 'ALERT RAISED ' || now()::text || ': no delivery for ' || v_names
     WHERE id = v_doc.id;

    document_id := v_doc.id;
    org_id := v_doc.org_id;
    missing_count := r.missing_recipients;
    notified := true;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: sync_contract_fields_from_defs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_contract_fields_from_defs(p_document_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org  uuid;
  v_tkey text;
BEGIN
  SELECT d.org_id, t.template_key INTO v_org, v_tkey
    FROM documents d JOIN contract_templates t ON t.id = d.template_id
   WHERE d.id = p_document_id AND d.deleted_at IS NULL;
  IF v_tkey IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM contract_clause_defs WHERE template_key = v_tkey) THEN
    RETURN;  -- flat templates manage their own fields
  END IF;

  -- new defs → new blank rows
  INSERT INTO contract_fields (
    org_id, document_id, field_key, label, section, clause_key, owner_role,
    value_type, input_kind, format_type, options, conditional_on, closed, guidance,
    required, is_optional, responsibility, sort_order, parent_field_key,
    responsibility_kind)
  SELECT v_org, p_document_id, d.field_key, d.label, d.section, d.clause_key, d.owner_role,
         d.value_type, nullif(d.input_kind,''), d.format_type, d.options, d.conditional_on, d.closed, d.guidance,
         d.required, d.is_optional, d.responsibility, d.sort_order, d.parent_field_key,
         d.responsibility_kind
    FROM contract_field_defs d
   WHERE d.template_key = v_tkey
     AND NOT EXISTS (
       SELECT 1 FROM contract_fields cf
        WHERE cf.document_id = p_document_id AND cf.field_key = d.field_key);

  -- existing rows → refresh def-owned columns (value is preserved)
  UPDATE contract_fields cf SET
      label = d.label, section = d.section, clause_key = d.clause_key,
      owner_role = d.owner_role, value_type = d.value_type,
      input_kind = nullif(d.input_kind,''), format_type = d.format_type,
      options = d.options, conditional_on = d.conditional_on, guidance = d.guidance,
      required = d.required, is_optional = d.is_optional, sort_order = d.sort_order,
      parent_field_key = d.parent_field_key, responsibility_kind = d.responsibility_kind,
      updated_at = now()
    FROM contract_field_defs d
   WHERE d.template_key = v_tkey
     AND cf.document_id = p_document_id AND cf.field_key = d.field_key;

  -- selected option no longer offered → reset the field. Only for single-select
  -- controls (select / buttons / yesno) with a non-empty value that is NOT present
  -- in the (now-refreshed) options list. Multi-select values (which are stored as
  -- CSV and may legitimately combine several codes) and free-text are left alone.
  --
  -- HORSE.% is EXCLUDED (2026-08-09). Those values are imported from the horse
  -- record by horse_field_token_value(), which returns the display LABEL ('Bay')
  -- while the options carry CODES ('BAY') — so they never matched and every sync
  -- silently erased the horse's colour and breed. For an imported field the record
  -- is the source of truth, not the picker; a value the picker cannot render means
  -- the option list needs fixing, not that the horse's data should be destroyed.
  UPDATE contract_fields cf SET value = '', updated_at = now()
   WHERE cf.document_id = p_document_id
     AND cf.owner_role <> 'SYSTEM'
     AND cf.field_key NOT LIKE 'HORSE.%'
     AND coalesce(cf.value,'') <> ''
     AND cf.input_kind IN ('select','buttons','yesno')
     AND cf.value NOT LIKE '%,%'                       -- skip multi-select CSVs
     AND jsonb_typeof(cf.options) = 'array'
     AND jsonb_array_length(cf.options) > 0
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(cf.options) o
        WHERE o->>'value' = cf.value);

  -- rows whose def is gone → remove (but never remove SYSTEM party auto-fill rows,
  -- which are inserted by fill_party_fields_from_contacts and have no def)
  DELETE FROM contract_fields cf
   WHERE cf.document_id = p_document_id
     AND cf.owner_role <> 'SYSTEM'
     AND NOT EXISTS (
       SELECT 1 FROM contract_field_defs d
        WHERE d.template_key = v_tkey AND d.field_key = cf.field_key);
END;
$$;


--
-- Name: sync_document_primary_horse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_document_primary_horse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc     uuid := coalesce(NEW.document_id, OLD.document_id);
  v_primary uuid;
BEGIN
  SELECT dh.horse_id INTO v_primary
    FROM document_horses dh
    WHERE dh.document_id = v_doc
    ORDER BY dh.position, dh.created_at
    LIMIT 1;
  -- No join rows left → the document is horse-less again (NULL), which is the
  -- pre-existing "no horse named" state, not an error.
  UPDATE documents SET horse_id = v_primary, updated_at = now()
    WHERE id = v_doc AND horse_id IS DISTINCT FROM v_primary;
  RETURN NULL;
END;
$$;


--
-- Name: sync_documents_on_medication_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_documents_on_medication_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h record; v_horse horses%ROWTYPE;
BEGIN
  FOR h IN SELECT horse_id FROM old_rows WHERE horse_id IS NOT NULL GROUP BY horse_id LOOP
    SELECT * INTO v_horse FROM horses WHERE id = h.horse_id;
    IF FOUND THEN PERFORM sync_horse_documents(v_horse, v_horse, true); END IF;
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: sync_documents_on_medication_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_documents_on_medication_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h record; v_horse horses%ROWTYPE;
BEGIN
  FOR h IN SELECT horse_id FROM new_rows WHERE horse_id IS NOT NULL GROUP BY horse_id LOOP
    SELECT * INTO v_horse FROM horses WHERE id = h.horse_id;
    IF FOUND THEN PERFORM sync_horse_documents(v_horse, v_horse, true); END IF;
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: sync_documents_on_medication_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_documents_on_medication_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h record; v_horse horses%ROWTYPE;
BEGIN
  FOR h IN
    SELECT horse_id FROM (SELECT horse_id FROM new_rows UNION SELECT horse_id FROM old_rows) s
     WHERE horse_id IS NOT NULL GROUP BY horse_id
  LOOP
    SELECT * INTO v_horse FROM horses WHERE id = h.horse_id;
    IF FOUND THEN PERFORM sync_horse_documents(v_horse, v_horse, true); END IF;
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: sync_horse_documents(public.horses, public.horses, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_horse_documents(p_old public.horses, p_new public.horses, p_force boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d record; f record; v_new text; v_old text; v_changed boolean;
BEGIN
  FOR d IN
    SELECT doc.id, ct.template_key FROM documents doc
    JOIN contract_templates ct ON ct.id = doc.template_id
    WHERE doc.horse_id = p_new.id
      AND doc.deleted_at IS NULL
      AND doc.workflow_state IN ('editable', 'editing', 'in_review')
  LOOP
    BEGIN
      v_changed := p_force;
      FOR f IN
        SELECT cf.id, cf.value,
               upper(split_part(regexp_replace(cf.field_key, '[{}]', '', 'g'), '.', 2)) AS field
        FROM contract_fields cf
        WHERE cf.document_id = d.id
          AND regexp_replace(cf.field_key, '[{}]', '', 'g') LIKE 'HORSE.%'
      LOOP
        v_new := horse_field_token_value(p_new, f.field);
        v_old := horse_field_token_value(p_old, f.field);
        -- Disclosure CONTENT tokens are pure read-only imports (no author path
        -- since ADD was removed) → always refresh to the record value.
        -- Disclosure GATES refresh to the record value ONLY when the record has
        -- entries (derived YES/UNKNOWN non-empty = locked); when the record is
        -- empty the gate is the AUTHOR's own selection and must be preserved.
        -- Both bypass the typed-field divergence-preservation that guards the
        -- other HORSE.* fields (microchip, vet, farrier…). This also makes the
        -- medications path (p_old = p_new) refresh the gate correctly.
        IF f.field IN ('KNOWN_CONDITIONS','MEDICAL_HISTORY','BEHAVIORAL_HISTORY',
                       'INJURIES_TO_HORSE','INJURIES_TO_HUMANS','MEDICATIONS','SUPPLEMENTS') THEN
          IF f.value IS DISTINCT FROM v_new THEN
            UPDATE contract_fields SET value = v_new, updated_at = now() WHERE id = f.id;
            v_changed := true;
          END IF;
        ELSIF f.field IN ('KNOWN_CONDITIONS_GATE','MEDICAL_HISTORY_GATE','BEHAVIORAL_HISTORY_GATE',
                          'INJURIES_TO_HORSE_GATE','MEDICATIONS_GATE','SUPPLEMENTS_GATE') THEN
          -- list-section gate: record-derived is YES iff the list has entries. Lock
          -- to YES when it does; when empty (derived NO) leave the author's answer.
          IF v_new = 'YES' AND f.value IS DISTINCT FROM 'YES' THEN
            UPDATE contract_fields SET value = 'YES', updated_at = now() WHERE id = f.id;
            v_changed := true;
          END IF;
        ELSIF f.field = 'INJURIES_TO_HUMANS_GATE' THEN
          -- injuries-to-humans is answered on the RECORD (Yes/No/Unknown), never on
          -- the contract — so the contract gate always mirrors the record scalar.
          IF f.value IS DISTINCT FROM v_new THEN
            UPDATE contract_fields SET value = v_new, updated_at = now() WHERE id = f.id;
            v_changed := true;
          END IF;
        ELSIF (f.value IS NULL OR btrim(f.value) = '' OR f.value = v_old)
           AND f.value IS DISTINCT FROM v_new THEN
          UPDATE contract_fields SET value = v_new, updated_at = now() WHERE id = f.id;
          v_changed := true;
        END IF;
      END LOOP;
      PERFORM set_document_disclosure_structured(d.id, p_new);
      IF v_changed THEN
        IF EXISTS (SELECT 1 FROM contract_section_defs s WHERE s.template_key = d.template_key) THEN
          PERFORM remerge_contract_from_clauses(d.id);
        ELSE
          PERFORM remerge_contract_from_fields(d.id);
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- one document's failure never blocks the save
    END;
  END LOOP;
END $$;


--
-- Name: sync_horse_fields_to_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_horse_fields_to_documents() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM sync_horse_documents(OLD, NEW, false);
  RETURN NEW;
END $$;


--
-- Name: sync_horse_id_to_document_horses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_horse_id_to_document_horses() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.horse_id IS NULL THEN RETURN NULL; END IF;

  -- already bound (in any position) → nothing to do
  IF EXISTS (SELECT 1 FROM document_horses dh
              WHERE dh.document_id = NEW.id AND dh.horse_id = NEW.horse_id) THEN
    RETURN NULL;
  END IF;

  -- Make room at position 1 FIRST (no-op when the document has no rows yet),
  -- then insert the new primary there. Done in this order there is no window
  -- where two rows share position 1.
  UPDATE document_horses dh
     SET position = dh.position + 1
   WHERE dh.document_id = NEW.id;

  INSERT INTO document_horses (org_id, document_id, horse_id, position)
    VALUES (NEW.org_id, NEW.id, NEW.horse_id, 1)
    ON CONFLICT (document_id, horse_id) DO NOTHING;

  RETURN NULL;
END;
$$;


--
-- Name: sync_profile_name_from_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_name_from_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.first_name IS DISTINCT FROM OLD.first_name
     OR NEW.last_name IS DISTINCT FROM OLD.last_name THEN
    UPDATE profiles
       SET first_name = NEW.first_name,
           last_name  = NEW.last_name,
           updated_at = now()
     WHERE contact_id = NEW.id;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION sync_profile_name_from_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_profile_name_from_contact() IS 'contacts is authoritative for the legal name; profiles mirrors it so the two can never diverge again (they had, for 2 of 6 linked pairs). The community PERSONA — display_name, avatar_url, bio — is separate and deliberately not touched: a member may show "CJ" while their contracts read "Charles Zigmund".';


--
-- Name: template_editor_clauses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_clauses(p_template_key text) RETURNS TABLE(clause_id uuid, section_key text, section_heading text, section_sort integer, clause_key text, heading text, body text, draft_body text, clause_type text, is_optional boolean, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.id, c.section_key, s.heading, s.sort_order,
    c.clause_key, c.heading, c.body, c.draft_body,
    c.clause_type, c.is_optional, c.sort_order
  FROM contract_clause_defs c
  LEFT JOIN contract_section_defs s
    ON s.template_key = c.template_key AND s.section_key = c.section_key
  WHERE c.template_key = p_template_key
    AND is_admin()
  ORDER BY s.sort_order NULLS LAST, c.sort_order;
$$;


--
-- Name: template_editor_discard_drafts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_discard_drafts(p_template_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_keys     text[];
  v_clauses  integer;
  v_flats    integer;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Template editing is admin-only';
  END IF;

  v_keys := template_editor_lockstep_keys(p_template_key);

  UPDATE contract_clause_defs SET draft_body = NULL
   WHERE template_key = ANY (v_keys) AND draft_body IS NOT NULL;
  GET DIAGNOSTICS v_clauses = ROW_COUNT;

  UPDATE contract_templates SET draft_body = NULL
   WHERE template_key = ANY (v_keys) AND draft_body IS NOT NULL;
  GET DIAGNOSTICS v_flats = ROW_COUNT;

  RETURN jsonb_build_object('keys', to_jsonb(v_keys),
                            'clause_drafts_discarded', v_clauses,
                            'flat_drafts_discarded', v_flats);
END;
$$;


--
-- Name: template_editor_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_list() RETURNS TABLE(template_key text, title text, short_label text, version integer, active boolean, is_composed boolean, clause_count bigint, draft_clause_count bigint, has_flat_draft boolean, body_empty boolean, has_unpublished boolean, lockstep_keys text[], locked_reason text, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    t.template_key,
    t.title,
    t.short_label,
    t.version,
    t.active,
    EXISTS (SELECT 1 FROM contract_clause_defs c WHERE c.template_key = t.template_key) AS is_composed,
    (SELECT count(*) FROM contract_clause_defs c WHERE c.template_key = t.template_key) AS clause_count,
    (SELECT count(*) FROM contract_clause_defs c WHERE c.template_key = t.template_key AND c.draft_body IS NOT NULL) AS draft_clause_count,
    (t.draft_body IS NOT NULL) AS has_flat_draft,
    (coalesce(t.body,'') = '') AS body_empty,
    (t.draft_body IS NOT NULL
      OR EXISTS (SELECT 1 FROM contract_clause_defs c
                 WHERE c.template_key = t.template_key AND c.draft_body IS NOT NULL)) AS has_unpublished,
    template_editor_lockstep_keys(t.template_key) AS lockstep_keys,
    CASE WHEN t.template_key = 'HORSE_LEASE_STANDARD'
         THEN 'Archived (D10) — edit the Standard lease (HORSE_LEASE_V2) instead'
         END AS locked_reason,
    t.updated_at
  FROM contract_templates t
  WHERE t.deleted_at IS NULL
    AND is_admin()
  ORDER BY EXISTS (SELECT 1 FROM contract_clause_defs c WHERE c.template_key = t.template_key) DESC,
           t.title;
$$;


--
-- Name: template_editor_lockstep_keys(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_lockstep_keys(p_key text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_key IN ('HORSE_LEASE_V2','HORSE_LEASE_SIMPLE','HORSE_LEASE_FULL')
      THEN ARRAY['HORSE_LEASE_V2','HORSE_LEASE_SIMPLE','HORSE_LEASE_FULL']
    ELSE ARRAY[p_key]
  END
$$;


--
-- Name: template_editor_publish(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_publish(p_template_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_keys      text[];
  v_conflicts text;
  v_clauses   integer := 0;
  v_flat      integer := 0;
  v_versions  jsonb := '{}'::jsonb;
  v_key       text;
  v_new       integer;
begin
  if not is_admin() then
    raise exception 'Template editing is admin-only';
  end if;
  if p_template_key = 'HORSE_LEASE_STANDARD' then
    raise exception 'HORSE_LEASE_STANDARD is archived (D10) and no longer receives content updates.';
  end if;

  v_keys := template_editor_lockstep_keys(p_template_key);

  select string_agg(clause_key, ', ') into v_conflicts
  from (
    select clause_key from contract_clause_defs
    where template_key = any (v_keys) and draft_body is not null
    group by clause_key having count(distinct draft_body) > 1
  ) conflicting;
  if v_conflicts is not null then
    raise exception 'Conflicting drafts across the lease set for clause(s): %. Resolve before publishing.', v_conflicts;
  end if;

  -- Clause wording: apply each drafted clause_key to every key in the set.
  update contract_clause_defs c
     set body = d.draft, draft_body = null
    from (
      select clause_key, min(draft_body) as draft
      from contract_clause_defs
      where template_key = any (v_keys) and draft_body is not null
      group by clause_key
    ) d
   where c.template_key = any (v_keys) and c.clause_key = d.clause_key;
  get diagnostics v_clauses = row_count;

  -- Flat body.
  update contract_templates
     set body = draft_body, draft_body = null
   where template_key = any (v_keys) and draft_body is not null and deleted_at is null;
  get diagnostics v_flat = row_count;

  if v_clauses = 0 and v_flat = 0 then
    raise exception 'Nothing to publish for % — no draft changes exist.', p_template_key;
  end if;

  -- Version +1 on every key published, THROUGH THE SAVE PATH, so the published
  -- state is retained instead of only counted. The AFTER UPDATE OF version
  -- trigger still records the template_version_events row; documents are never
  -- touched.
  foreach v_key in array v_keys loop
    if exists (select 1 from contract_templates
                where template_key = v_key and deleted_at is null) then
      v_new := save_contract_template_version(v_key, null, null, null);
      v_versions := v_versions || jsonb_build_object(v_key, v_new);
    end if;
  end loop;

  return jsonb_build_object('published_keys', to_jsonb(v_keys),
                            'clause_rows_published', v_clauses,
                            'flat_bodies_published', v_flat,
                            'new_versions', v_versions);
end;
$$;


--
-- Name: template_editor_save_clause_draft(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_save_clause_draft(p_clause_id uuid, p_draft text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key    text;
  v_clause text;
  v_body   text;
  v_keys   text[];
  v_n      integer;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Template editing is admin-only';
  END IF;

  SELECT template_key, clause_key, body INTO v_key, v_clause, v_body
  FROM contract_clause_defs WHERE id = p_clause_id;
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'Clause % not found', p_clause_id;
  END IF;
  IF v_key = 'HORSE_LEASE_STANDARD' THEN
    RAISE EXCEPTION 'HORSE_LEASE_STANDARD is archived (D10) and no longer receives content updates. Edit the Standard lease (HORSE_LEASE_V2) instead.';
  END IF;

  v_keys := template_editor_lockstep_keys(v_key);

  IF p_draft IS NULL OR p_draft = v_body THEN
    -- Back to the live wording: that is not a pending change, clear the draft.
    UPDATE contract_clause_defs
       SET draft_body = NULL
     WHERE template_key = ANY (v_keys) AND clause_key = v_clause;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN jsonb_build_object('cleared', true, 'updated_keys', to_jsonb(v_keys), 'rows', v_n);
  END IF;

  UPDATE contract_clause_defs
     SET draft_body = p_draft
   WHERE template_key = ANY (v_keys) AND clause_key = v_clause;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  RETURN jsonb_build_object('cleared', false, 'updated_keys', to_jsonb(v_keys), 'rows', v_n);
END;
$$;


--
-- Name: template_editor_save_flat_draft(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_save_flat_draft(p_template_key text, p_draft text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_body text;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Template editing is admin-only';
  END IF;
  IF EXISTS (SELECT 1 FROM contract_clause_defs c WHERE c.template_key = p_template_key) THEN
    RAISE EXCEPTION '% is clause-composed — edit its clauses, not a flat body', p_template_key;
  END IF;

  SELECT body INTO v_body
  FROM contract_templates
  WHERE template_key = p_template_key AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template % not found', p_template_key;
  END IF;

  IF p_draft IS NULL OR p_draft = coalesce(v_body, '') THEN
    UPDATE contract_templates SET draft_body = NULL
     WHERE template_key = p_template_key AND deleted_at IS NULL;
    RETURN jsonb_build_object('cleared', true);
  END IF;

  UPDATE contract_templates SET draft_body = p_draft
   WHERE template_key = p_template_key AND deleted_at IS NULL;
  RETURN jsonb_build_object('cleared', false);
END;
$$;


--
-- Name: template_editor_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_editor_tokens() RETURNS TABLE(id uuid, template_id uuid, template_key text, namespace text, field text, token text, kind text, source_table text, source_column text, computed boolean, required boolean, party_scoped boolean, notes text, source_live boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    tt.id, tt.template_id, ct.template_key,
    tt.namespace, tt.field, tt.token, tt.kind,
    tt.source_table, tt.source_column,
    tt.computed, tt.required, tt.party_scoped, tt.notes,
    (tt.source_table IS NOT NULL AND EXISTS (
       SELECT 1 FROM information_schema.tables t
       WHERE t.table_schema = 'public' AND t.table_name = tt.source_table
     )) AS source_live
  FROM template_tokens tt
  LEFT JOIN contract_templates ct ON ct.id = tt.template_id
  WHERE is_admin()
  ORDER BY tt.namespace, tt.field;
$$;


--
-- Name: template_past_signers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_past_signers(p_template_key text) RETURNS TABLE(contact_id uuid, name text, email text, signed_version integer, signed_at timestamp with time zone, already_required boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id,
         coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
                  c.email, 'Unnamed'),
         c.email,
         max(coalesce(d.signed_template_version, ct.version))::int,
         max(d.generated_at),
         NOT contact_document_satisfied(c.id, p_template_key)
    FROM documents d
    JOIN contract_templates ct ON ct.id = d.template_id
    JOIN contacts c ON c.id = d.contact_id AND c.deleted_at IS NULL
   WHERE ct.template_key = p_template_key
     AND d.status = 'EXECUTED' AND d.deleted_at IS NULL
     AND c.org_id = current_org()
     AND has_staff_access()
   GROUP BY c.id, c.first_name, c.last_name, c.email
  HAVING max(coalesce(d.signed_template_version, ct.version))
         < (SELECT max(version) FROM contract_templates
             WHERE template_key = p_template_key AND active AND deleted_at IS NULL)
   ORDER BY max(d.generated_at) DESC
$$;


--
-- Name: FUNCTION template_past_signers(p_template_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.template_past_signers(p_template_key text) IS 'Everyone who signed an OLDER version of this template — the pick list for a targeted re-sign request. already_required shows who is on the hook already, so staff can see at a glance what a second run would change.';


--
-- Name: token_display_value(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.token_display_value(p_token text, p_raw text, p_labels jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN coalesce(p_raw,'') = '' THEN ''
    -- pure include-toggles (checkbox controls) emit no document text; they only
    -- gate their target clause. Convention: token key ends in _INCLUDE.
    WHEN p_token LIKE '%\_INCLUDE' THEN ''
    -- ISO date values render in written-out style, matching DOC.EFFECTIVE_DATE
    WHEN p_raw ~ '^\d{4}-\d{2}-\d{2}$'
      THEN to_char(to_date(p_raw, 'YYYY-MM-DD'), 'FMMonth FMDD, YYYY')
    WHEN p_raw LIKE '%,%' AND p_labels ? p_token THEN (
      SELECT string_agg(
               coalesce(p_labels #>> ARRAY[p_token, btrim(v)], btrim(v)),
               ', ' ORDER BY ord)
        FROM unnest(string_to_array(p_raw, ',')) WITH ORDINALITY AS t(v, ord)
        WHERE btrim(v) <> ''
    )
    WHEN p_labels #>> ARRAY[p_token, p_raw] IS NOT NULL
      THEN p_labels #>> ARRAY[p_token, p_raw]
    WHEN upper(p_raw) = 'YES' THEN 'Yes'
    WHEN upper(p_raw) = 'NO'  THEN 'No'
    ELSE p_raw
  END;
$_$;


--
-- Name: transfer_payment_responsibility(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_payment_responsibility(p_purchase_id uuid, p_new_payer_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p    purchases%ROWTYPE;
  v_user uuid;
BEGIN
  SELECT * INTO v_p FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_p.buyer_user_id = auth.uid()
          OR v_p.buyer_contact_id = current_contact_id(), false) THEN
    RAISE EXCEPTION 'not your purchase';
  END IF;
  IF v_p.payment_status = 'paid' THEN
    RAISE EXCEPTION 'this purchase is already paid';
  END IF;

  SELECT user_id INTO v_user FROM profiles WHERE contact_id = p_new_payer_contact_id;
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'the new payer must have an account';
  END IF;

  UPDATE purchases
     SET buyer_contact_id = p_new_payer_contact_id,
         buyer_user_id    = v_user,
         updated_at       = now()
   WHERE id = p_purchase_id;

  PERFORM log_status_event('order', p_purchase_id, coalesce(v_p.current_status, 'pending'),
    'Payment responsibility transferred to contact ' || p_new_payer_contact_id::text, v_p.org_id);
END;
$$;


--
-- Name: trg_apply_affiliations_on_doc(); Type: FUNCTION; Schema: public; Owner: -
