END;
$$;


--
-- Name: trg_booking_form_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_booking_form_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now boolean := booking_form_applies(NEW);
  v_was boolean := CASE WHEN TG_OP = 'UPDATE' THEN booking_form_applies(OLD) ELSE false END;
BEGIN
  -- ── became live: assignment, or a replacement, or a revival ──────────────
  IF v_now AND NOT v_was THEN
    PERFORM _ensure_booking_form(NEW);
    RETURN NULL;
  END IF;

  -- ── stopped being live: cancelled, expired, soft-deleted, unassigned ─────
  IF v_was AND NOT v_now THEN
    -- untouched blank: it records nothing, so it goes
    DELETE FROM booking_forms bf
     WHERE bf.booking_id = NEW.id
       AND bf.status = 'open'
       AND _booking_form_is_blank(bf.answers);
    -- written in: it is evidence (D11) — kept, and out of the working views
    UPDATE booking_forms bf
       SET status = 'retired', retired_at = now(), retired_by = auth.uid(), updated_at = now()
     WHERE bf.booking_id = NEW.id
       AND bf.status <> 'retired';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: trg_booking_unit_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_booking_unit_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_units uuid[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.purchase_id IS NOT NULL AND NEW.status NOT IN ('cancelled','expired') THEN
      PERFORM consume_unit_for_booking(NEW.id);
    END IF;
    RETURN NEW;
  END IF;

  -- the purchase behind this booking changed (including NULL → a purchase)
  IF NEW.purchase_id IS DISTINCT FROM OLD.purchase_id THEN
    SELECT array_agg(id) INTO v_units FROM fulfillment_units WHERE booking_id = NEW.id;
    IF v_units IS NOT NULL THEN
      UPDATE fulfillment_units SET booking_id = NULL WHERE id = ANY(v_units);
      PERFORM set_unit_status(f.id, 'open', 'Booking relinked — unit returned')
        FROM fulfillment_units f
       WHERE f.id = ANY(v_units) AND f.current_status = 'scheduled';
    END IF;
    IF NEW.purchase_id IS NOT NULL AND NEW.status NOT IN ('cancelled','expired') THEN
      PERFORM consume_unit_for_booking(NEW.id);
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'completed' THEN
      PERFORM set_unit_status(u.id, 'consumed', 'Booking completed')
        FROM fulfillment_units u
       WHERE u.booking_id = NEW.id AND u.current_status <> 'consumed';
    ELSIF NEW.status IN ('cancelled','expired') THEN
      SELECT array_agg(id) INTO v_units FROM fulfillment_units WHERE booking_id = NEW.id;
      IF v_units IS NOT NULL THEN
        UPDATE fulfillment_units SET booking_id = NULL WHERE id = ANY(v_units);
        PERFORM set_unit_status(f.id, 'open', 'Booking cancelled — unit returned')
          FROM fulfillment_units f
         WHERE f.id = ANY(v_units) AND f.current_status <> 'open';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


