      UPDATE fulfillment_units SET report_id = NEW.id WHERE id = v_u;
      PERFORM set_unit_status(v_u, 'delivered', 'Evaluation report delivered');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


