--
-- Name: unarchive_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unarchive_contact(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'staff access required';
  END IF;

  UPDATE contacts
     SET deleted_at = NULL, deleted_by = NULL, deleted_reason = NULL
   WHERE id = p_contact_id AND org_id = current_org() AND deleted_at IS NOT NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'contact not found in this org, or not archived';
  END IF;
END;
$$;


--
-- Name: FUNCTION unarchive_contact(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.unarchive_contact(p_contact_id uuid) IS 'Reverses archive_contact completely: the contact returns to every listing it left. Archiving is reversible by design (D19) precisely because nothing was destroyed to begin with.';


--
-- Name: undelivered_executed_documents(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undelivered_executed_documents(p_limit integer DEFAULT 10, p_grace_minutes integer DEFAULT 5) RETURNS TABLE(document_id uuid, title text, executed_at timestamp with time zone, missing_recipients bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.id,
         coalesce(d.title, 'Document'),
         d.updated_at,
         count(*) FILTER (WHERE dd.id IS NULL) AS missing_recipients
    FROM documents d
    JOIN document_parties dp ON dp.document_id = d.id
    JOIN contacts c ON c.id = dp.contact_id
                   AND coalesce(btrim(c.email), '') <> ''
    LEFT JOIN document_deliveries dd
           ON dd.document_id = d.id
          AND dd.recipient_contact_id = dp.contact_id
          AND dd.channel = 'EMAIL'
          AND dd.deleted_at IS NULL
   WHERE d.status = 'EXECUTED'
     AND d.deleted_at IS NULL
     -- grace: let the browser path deliver first in the common case
     AND d.updated_at < now() - make_interval(mins => greatest(p_grace_minutes, 0))
   GROUP BY d.id, d.title, d.updated_at
  HAVING count(*) FILTER (WHERE dd.id IS NULL) > 0
   ORDER BY d.updated_at
   LIMIT greatest(p_limit, 1);
$$;


--
-- Name: unskip_required_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unskip_required_document(p_contact_id uuid, p_template_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_row contact_required_documents%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'staff access required'; END IF;
  SELECT org_id INTO v_org FROM contacts WHERE id = p_contact_id AND deleted_at IS NULL;
  IF v_org IS NULL OR v_org <> current_org() THEN
    RAISE EXCEPTION 'contact not found in this org';
  END IF;

  SELECT * INTO v_row FROM contact_required_documents
   WHERE contact_id = p_contact_id AND template_key = p_template_key;
  IF NOT FOUND OR v_row.skipped_at IS NULL THEN
    RETURN jsonb_build_object('restored', false);
  END IF;

  UPDATE contact_required_documents
     SET skipped_at = NULL, skipped_by = NULL, skip_reason = NULL
   WHERE contact_id = p_contact_id AND template_key = p_template_key;

  INSERT INTO audit_logs (actor_user_id, action, table_name, record_id, old_value, new_value)
  VALUES (auth.uid(), 'UPDATE', 'contact_required_documents', p_contact_id,
          jsonb_build_object('template_key', p_template_key,
                             'skipped_at', v_row.skipped_at,
                             'skipped_by', v_row.skipped_by,
                             'reason', v_row.skip_reason),
          jsonb_build_object('event', 'requirement_skip_restored',
                             'template_key', p_template_key));

  RETURN jsonb_build_object('restored', true);
END;
$$;


--
-- Name: update_contact_record(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contact_record(p_contact_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_allowed text[] := ARRAY[
    'first_name','last_name','email','phone','phone_ext','mobile','mobile_ext','whatsapp','text_only_phone',
    'address_line1','address_line2','city','state','postal_code','country',
    'date_of_birth','notes','tags','contact_type','guardian_contact_id',
    'emergency_contact_1_name','emergency_contact_1_relationship','emergency_contact_1_phone',
    'emergency_contact_2_name','emergency_contact_2_relationship','emergency_contact_2_phone',
    'riding_experience_years','jump_experience','riding_background','jump_limitations',
    'preferred_contact','hide_mobile','hide_whatsapp','hide_email',
    'social_tiktok','social_instagram','social_facebook','social_linkedin',
    -- TASK-ORIGIN §5 T2 — "editable afterwards, on the record, forever" (§4.2).
    'client_origin','contact_channel'];
  k text;
  v_sets text[] := '{}';
  v_sql text;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN RAISE EXCEPTION 'staff access required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM contacts
                  WHERE id = p_contact_id AND org_id = current_org() AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'contact not found in this organisation';
  END IF;

  FOR k IN SELECT jsonb_object_keys(p_patch) LOOP
    IF NOT coalesce(k = ANY(v_allowed), false) THEN
      RAISE EXCEPTION 'field % is not editable here', k;
    END IF;
    v_sets := v_sets || format('%I = ($1->>%L)::text', k, k);
  END LOOP;

  IF array_length(v_sets, 1) IS NULL THEN
    RETURN contact_dossier(p_contact_id);
  END IF;

  -- tags is text[], the booleans are boolean, dates are date — cast per column
  -- rather than forcing everything through text.
  v_sql := 'UPDATE contacts SET ' || array_to_string(
    ARRAY(SELECT CASE
      WHEN key = 'tags' THEN
        format('tags = CASE WHEN $1->%L = ''null''::jsonb THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text($1->%L)) END', key, key)
      WHEN key IN ('hide_mobile','hide_whatsapp','hide_email') THEN
        format('%I = ($1->>%L)::boolean', key, key)
      WHEN key = 'date_of_birth' THEN
        format('date_of_birth = nullif($1->>%L, '''')::date', key)
      WHEN key = 'guardian_contact_id' THEN
        format('guardian_contact_id = nullif($1->>%L, '''')::uuid', key)
      ELSE format('%I = nullif($1->>%L, '''')', key, key)
    END FROM jsonb_object_keys(p_patch) AS key), ', ')
    || ', updated_at = now() WHERE id = $2';

  EXECUTE v_sql USING p_patch, p_contact_id;
  RETURN contact_dossier(p_contact_id);
END
$_$;


--
-- Name: FUNCTION update_contact_record(p_contact_id uuid, p_patch jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_contact_record(p_contact_id uuid, p_patch jsonb) IS 'Staff edit of one contact record. The patch is checked against an explicit allowlist and an unknown key RAISES rather than being skipped — a mistyped field name must not look like a successful save. Returns the fresh dossier so the caller never has to guess what landed.';


--
-- Name: update_contract_composition(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contract_composition(p_document_id uuid, p_field_key text, p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_state text; v_author uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT org_id, workflow_state INTO v_org, v_state FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document'; END IF;
  IF v_state NOT IN ('editable','editing','in_review') THEN RAISE EXCEPTION 'document is not editable'; END IF;

  SELECT added_by_contact_id INTO v_author FROM contract_fields
   WHERE document_id = p_document_id AND field_key = p_field_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'not an author-added item: %', p_field_key; END IF;
  IF NOT ((has_staff_access() AND v_org = current_org())
          OR (v_author IS NOT NULL AND v_author = current_contact_id())) THEN
    RAISE EXCEPTION 'only the item''s author or staff may edit it';
  END IF;

  PERFORM delete_contract_composition_item(p_document_id, p_field_key);
  -- next_custom_field_key mints a fresh key for the replacement content, so
  -- the edited item's field_key changes — an accepted tradeoff of reapplying
  -- through the same apply path rather than a bespoke in-place patch.
  RETURN apply_contract_composition_spec(p_document_id, p_spec, coalesce(v_author, current_contact_id()));
END;
$$;


--
-- Name: update_deal(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_deal(p_deal_id uuid, p_deal_type text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_title text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown deal: %', p_deal_id; END IF;

  -- the title is the user's own name for the deal: always editable, including
  -- on a finished deal (renaming changes nothing about what happened)
  IF p_title IS NOT NULL THEN
    UPDATE deals SET title = nullif(btrim(p_title),'') WHERE id = p_deal_id;
  END IF;

  IF v_deal.status <> 'pending' THEN
    IF p_deal_type IS NOT NULL OR p_notes IS NOT NULL THEN
      RAISE EXCEPTION 'this deal is % and can no longer be edited', v_deal.status;
    END IF;
    RETURN;
  END IF;

  IF p_deal_type IS NOT NULL AND p_deal_type IS DISTINCT FROM v_deal.deal_type THEN
    IF EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = v_deal.contract_id)
       OR EXISTS (SELECT 1 FROM documents WHERE contract_id = v_deal.contract_id AND deleted_at IS NULL) THEN
      RAISE EXCEPTION 'the deal type cannot change once parties or documents exist — void this deal and start another';
    END IF;
    IF deal_party_roles(p_deal_type) IS NULL THEN
      RAISE EXCEPTION 'unknown deal type: %', p_deal_type;
    END IF;
    UPDATE deals SET deal_type = p_deal_type WHERE id = p_deal_id;
    UPDATE contracts SET terms = terms || jsonb_build_object('deal_kind', p_deal_type)
     WHERE id = v_deal.contract_id;
  END IF;

  IF p_notes IS NOT NULL THEN
    UPDATE deals SET notes = nullif(btrim(p_notes),'') WHERE id = p_deal_id;
  END IF;
END;
$$;


--
-- Name: update_horse_care_team(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_horse_care_team(p_horse_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_owner uuid;
BEGIN
  SELECT org_id, current_owner_contact_id INTO v_org, v_owner
    FROM horses WHERE id = p_horse_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR v_owner = current_contact_id()) THEN
    RAISE EXCEPTION 'only the horse owner or staff may edit the care team';
  END IF;

  IF p ?| ARRAY['vet_name','vet_phone'] THEN
    IF EXISTS (SELECT 1 FROM horse_relationships WHERE horse_id = p_horse_id AND relationship='VET' AND active) THEN
      UPDATE horse_relationships r SET
        party_name_text = CASE WHEN p ? 'vet_name'  THEN nullif(btrim(p->>'vet_name'),'')  ELSE party_name_text END,
        phone           = CASE WHEN p ? 'vet_phone' THEN nullif(btrim(p->>'vet_phone'),'') ELSE phone END
      WHERE r.id = (SELECT id FROM horse_relationships WHERE horse_id = p_horse_id AND relationship='VET' AND active
                    ORDER BY (provider_role='primary') DESC, created_at DESC LIMIT 1);
    ELSE
      INSERT INTO horse_relationships (org_id, horse_id, relationship, provider_role,
        party_name_text, phone, active, created_by_contact_id)
      VALUES (v_org, p_horse_id, 'VET', 'primary',
        nullif(btrim(p->>'vet_name'),''), nullif(btrim(p->>'vet_phone'),''), true, current_contact_id());
    END IF;
  END IF;

  IF p ?| ARRAY['farrier_name','farrier_phone'] THEN
    IF EXISTS (SELECT 1 FROM horse_relationships WHERE horse_id = p_horse_id AND relationship='FARRIER' AND active) THEN
      UPDATE horse_relationships r SET
        party_name_text = CASE WHEN p ? 'farrier_name'  THEN nullif(btrim(p->>'farrier_name'),'')  ELSE party_name_text END,
        phone           = CASE WHEN p ? 'farrier_phone' THEN nullif(btrim(p->>'farrier_phone'),'') ELSE phone END
      WHERE r.id = (SELECT id FROM horse_relationships WHERE horse_id = p_horse_id AND relationship='FARRIER' AND active
                    ORDER BY (provider_role='primary') DESC, created_at DESC LIMIT 1);
    ELSE
      INSERT INTO horse_relationships (org_id, horse_id, relationship, provider_role,
        party_name_text, phone, active, created_by_contact_id)
      VALUES (v_org, p_horse_id, 'FARRIER', 'primary',
        nullif(btrim(p->>'farrier_name'),''), nullif(btrim(p->>'farrier_phone'),''), true, current_contact_id());
    END IF;
  END IF;
END;
$$;


--
-- Name: update_horse_record(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_horse_record(p_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM horses WHERE id = p_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown horse'; END IF;
  IF NOT (has_staff_access() OR caller_owns_horse(p_id)) THEN
    RAISE EXCEPTION 'not authorized for this horse';
  END IF;

  UPDATE horses SET
    registered_name     = CASE WHEN p ? 'registered_name'     THEN nullif(btrim(p ->> 'registered_name'),'')     ELSE registered_name END,
    nickname            = CASE WHEN p ? 'nickname'            THEN nullif(btrim(p ->> 'nickname'),'')            ELSE nickname END,
    breed               = CASE WHEN p ? 'breed'               THEN nullif(btrim(p ->> 'breed'),'')               ELSE breed END,
    color               = CASE WHEN p ? 'color'               THEN nullif(btrim(p ->> 'color'),'')               ELSE color END,
    markings            = CASE WHEN p ? 'markings'            THEN nullif(btrim(p ->> 'markings'),'')            ELSE markings END,
    sex                 = CASE WHEN p ? 'sex'                 THEN nullif(btrim(p ->> 'sex'),'')                 ELSE sex END,
    date_of_birth       = CASE WHEN p ? 'date_of_birth'       THEN nullif(p ->> 'date_of_birth','')::date        ELSE date_of_birth END,
    height              = CASE WHEN p ? 'height'              THEN nullif(btrim(p ->> 'height'),'')              ELSE height END,
    sire                = CASE WHEN p ? 'sire'                THEN nullif(btrim(p ->> 'sire'),'')                ELSE sire END,
    dam                 = CASE WHEN p ? 'dam'                 THEN nullif(btrim(p ->> 'dam'),'')                 ELSE dam END,
    registration_number = CASE WHEN p ? 'registration_number' THEN nullif(btrim(p ->> 'registration_number'),'') ELSE registration_number END,
    registration_org    = CASE WHEN p ? 'registration_org'    THEN nullif(btrim(p ->> 'registration_org'),'')    ELSE registration_org END,
    microchip_id        = CASE WHEN p ? 'microchip_id'        THEN nullif(btrim(p ->> 'microchip_id'),'')        ELSE microchip_id END,
    passport_number     = CASE WHEN p ? 'passport_number'     THEN nullif(btrim(p ->> 'passport_number'),'')     ELSE passport_number END,
    passport_country    = CASE WHEN p ? 'passport_country'    THEN nullif(btrim(p ->> 'passport_country'),'')    ELSE passport_country END,
    fair_market_value   = CASE WHEN p ? 'fair_market_value'   THEN nullif(nullif(regexp_replace(coalesce(p ->> 'fair_market_value',''),'[$,\s]','','g'),'')::numeric, 0) ELSE fair_market_value END,
    euthanasia_authorization = CASE WHEN p ? 'euthanasia_authorization' THEN nullif(btrim(p ->> 'euthanasia_authorization'),'') ELSE euthanasia_authorization END,
    pending_fields           = CASE WHEN p ? 'pending_fields'           THEN coalesce(p -> 'pending_fields', '[]'::jsonb)           ELSE pending_fields END,
    medical_history_list     = CASE WHEN p ? 'medical_history_list'     THEN coalesce(p -> 'medical_history_list', '[]'::jsonb)     ELSE medical_history_list END,
    behavioral_history_list  = CASE WHEN p ? 'behavioral_history_list'  THEN coalesce(p -> 'behavioral_history_list', '[]'::jsonb)  ELSE behavioral_history_list END,
    known_conditions_list    = CASE WHEN p ? 'known_conditions_list'    THEN coalesce(p -> 'known_conditions_list', '[]'::jsonb)    ELSE known_conditions_list END,
    training_history_list    = CASE WHEN p ? 'training_history_list'    THEN coalesce(p -> 'training_history_list', '[]'::jsonb)    ELSE training_history_list END,
    competition_history_list = CASE WHEN p ? 'competition_history_list' THEN coalesce(p -> 'competition_history_list', '[]'::jsonb) ELSE competition_history_list END,
    injuries_to_humans       = CASE WHEN p ? 'injuries_to_humans'       THEN nullif(btrim(coalesce(p ->> 'injuries_to_humans','')),'') ELSE injuries_to_humans END,
    injuries_to_horse        = CASE WHEN p ? 'injuries_to_horse'        THEN coalesce(p -> 'injuries_to_horse', '[]'::jsonb)        ELSE injuries_to_horse END,
    updated_at = now()
  WHERE id = p_id;
END;
$_$;


--
-- Name: update_lessee_entry(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_lessee_entry(p_id uuid, p_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE horse_lessee_entries SET data = p_data, updated_at = now()
   WHERE id = p_id AND org_id = current_org()
     AND (has_staff_access() OR (author_contact_id = current_contact_id() AND caller_is_current_lessee(horse_id)));
  IF NOT FOUND THEN RAISE EXCEPTION 'not your entry to edit, or the lease has ended'; END IF;
END;
$$;


--
-- Name: update_my_onboarding_profile(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_onboarding_profile(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact   uuid;
  v_org       uuid;
  v_has_minor boolean;
  v_mf        text;
  v_ml        text;
  v_mdob      date;
  v_mname     text;
  v_minor_c   uuid;
  v_fn        text := NULLIF(trim(coalesce(p->>'first_name', '')), '');
  v_ln        text := NULLIF(trim(coalesce(p->>'last_name',  '')), '');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  v_contact := coalesce(current_contact_id(), ensure_contact_for_profile(auth.uid()));
  IF v_contact IS NULL THEN RAISE EXCEPTION 'no contact record for this account'; END IF;

  UPDATE contacts SET
    -- Name: fill only when currently blank or a placeholder (= the email).
    first_name = CASE WHEN v_fn IS NOT NULL AND (NULLIF(trim(coalesce(first_name,'')),'') IS NULL
                        OR lower(trim(first_name)) = lower(coalesce(email,'')))
                      THEN v_fn ELSE first_name END,
    last_name  = CASE WHEN v_ln IS NOT NULL AND NULLIF(trim(coalesce(last_name,'')),'') IS NULL
                      THEN v_ln ELSE last_name END,
    phone         = coalesce(NULLIF(trim(p->>'phone'), ''), phone),
    -- INTAKE 2026-08-24. `phone` IS the mobile number (relabelled, not rewired);
    -- this is the alternate the person only wants TEXTS on.
    text_only_phone   = coalesce(NULLIF(trim(p->>'text_only_phone'), ''), text_only_phone),
    preferred_contact = coalesce(NULLIF(trim(p->>'preferred_contact'), ''), preferred_contact),
    date_of_birth = coalesce(NULLIF(trim(p->>'date_of_birth'), '')::date, date_of_birth),
    address_line1 = coalesce(NULLIF(trim(p->>'address_street'), ''), address_line1),
    city          = coalesce(NULLIF(trim(p->>'address_city'), ''), city),
    state         = coalesce(NULLIF(trim(p->>'address_state'), ''), state),
    postal_code   = coalesce(NULLIF(trim(p->>'address_zip'), ''), postal_code),
    emergency_contact_1_name         = coalesce(NULLIF(trim(p->>'emergency_contact_1_name'), ''), emergency_contact_1_name),
    emergency_contact_1_relationship = coalesce(NULLIF(trim(p->>'emergency_contact_1_relationship'), ''), emergency_contact_1_relationship),
    emergency_contact_1_phone        = coalesce(NULLIF(trim(p->>'emergency_contact_1_phone'), ''), emergency_contact_1_phone),
    emergency_contact_2_name         = coalesce(NULLIF(trim(p->>'emergency_contact_2_name'), ''), emergency_contact_2_name),
    emergency_contact_2_relationship = coalesce(NULLIF(trim(p->>'emergency_contact_2_relationship'), ''), emergency_contact_2_relationship),
    emergency_contact_2_phone        = coalesce(NULLIF(trim(p->>'emergency_contact_2_phone'), ''), emergency_contact_2_phone),
    riding_experience_years          = coalesce(NULLIF(trim(p->>'riding_experience_years'), ''), riding_experience_years),
    jump_experience                  = coalesce(NULLIF(trim(p->>'jump_experience'), ''), jump_experience),
    riding_background                = coalesce(NULLIF(trim(p->>'riding_background'), ''), riding_background),
    jump_limitations                 = coalesce(NULLIF(trim(p->>'jump_limitations'), ''), jump_limitations),
    updated_at    = now()
  WHERE id = v_contact;

  -- Mirror the name onto the profile (same fill-when-blank rule) so account
  -- surfaces show it too.
  UPDATE profiles SET
    first_name = CASE WHEN v_fn IS NOT NULL AND NULLIF(trim(coalesce(first_name,'')),'') IS NULL THEN v_fn ELSE first_name END,
    last_name  = CASE WHEN v_ln IS NOT NULL AND NULLIF(trim(coalesce(last_name,'')),'')  IS NULL THEN v_ln ELSE last_name END,
    -- ⚠️ THE DISPLAY NAME IS SEEDED FROM THE NAME THEY JUST GAVE US. Owner,
    -- 2026-09-01: *"the display name should be populated from the name they give
    -- us when they fill in the account information. that field exists so they can
    -- change it if they want to from the profile page."*
    -- Nothing has ever written this column — 14 of 16 live accounts carry no
    -- value — which is why the dossier said "(no display name)" for a person whose
    -- name was on the record twice.
    -- ⚠️ SEEDED, NOT OWNED. `NULLIF(trim(…)) IS NULL` means it fills a BLANK and
    -- never overwrites a value: the moment a member types their own handle, this
    -- stops touching it. That is the difference between a default and a rule.
    display_name = CASE
      WHEN NULLIF(trim(coalesce(display_name, '')), '') IS NULL
      THEN NULLIF(btrim(concat_ws(' ',
             coalesce(v_fn, first_name), coalesce(v_ln, last_name))), '')
      ELSE display_name END
  WHERE user_id = auth.uid();

  -- Minor rider handling — VERBATIM from the prior prod body (unchanged).
  IF p ? 'has_minor' THEN
    v_has_minor := coalesce((p->>'has_minor')::boolean, false);
    v_mf    := NULLIF(trim(coalesce(p->>'minor_first_name', '')), '');
    v_ml    := NULLIF(trim(coalesce(p->>'minor_last_name', '')), '');
    v_mdob  := NULLIF(trim(coalesce(p->>'minor_dob', '')), '')::date;
    v_mname := trim(coalesce(v_mf, '') || ' ' || coalesce(v_ml, ''));

    -- ⚠️ SIGNDOOR — THE PATH RULE IS RE-DECIDED HERE, exactly as the door
    -- re-decides it from MINOR_PATHS. The browser is not the authority on which
    -- doors may carry a child: a horse owner and a contract counterparty must be
    -- 18+ (owner ruling 2026-08-31), and an unknown path FAILS OPEN to asking,
    -- because not asking is the AR7 incident and asking is merely a question.
    -- A guardian who ALREADY has a minor attached is always allowed through —
    -- otherwise an edit to an existing child would be dropped in silence, which
    -- is the "reports success while doing nothing" failure this repo has most of.
    IF v_has_minor AND v_mf IS NOT NULL
       AND (_sign_path_allows_minor(sign_path_for_contact(v_contact))
            OR EXISTS (SELECT 1 FROM contacts m
                        WHERE m.guardian_contact_id = v_contact AND m.deleted_at IS NULL)) THEN
      -- FIX1 §A — ONE ENGINE. This block used to hold the find-or-create inline,
      -- and /api/sign-start now needs exactly the same act at the front door,
      -- before there is an account to run this function under. Rather than write
      -- a second minor concept at the door (D18: never leave a second write path
      -- beside a correct engine), the block moved to attach_minor_to_guardian()
      -- and both callers reach it. The behaviour here is byte-for-byte what it
      -- was: find this guardian's minor by name, else create it linked to them,
      -- and only ever FILL a missing date of birth.
      v_minor_c := attach_minor_to_guardian(v_contact, v_mf, v_ml, v_mdob);

    ELSIF NOT v_has_minor THEN
      -- toggled off: unlink this guardian's minors, but never disturb one whose
      -- participant doc has already executed (preservation rule).
      UPDATE contacts m SET guardian_contact_id = NULL
        WHERE m.guardian_contact_id = v_contact
          AND NOT EXISTS (
            SELECT 1 FROM document_parties dp
            JOIN documents d ON d.id = dp.document_id
            WHERE dp.contact_id = m.id AND dp.party_role = 'PARTICIPANT'
              AND d.status = 'EXECUTED' AND d.deleted_at IS NULL);
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION update_my_onboarding_profile(p jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_my_onboarding_profile(p jsonb) IS 'Save the authenticated client''s onboarding profile (contacts is the canonical store). v2: optional has_minor/minor_first_name/minor_last_name/minor_dob keys manage the non-signing PARTICIPANT party on the caller''s AWAITING_SIGNATURE service engagements — present+true upserts the minor contact + party (DOB healed when null), present+false removes the party where no document has EXECUTED, absent leaves minor state untouched.';


--
-- Name: update_my_pending_booking(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_pending_booking(p_booking_id uuid, p_new_start timestamp with time zone, p_new_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client uuid := current_client_id();
  v_b      bookings%ROWTYPE;
BEGIN
  IF v_client IS NULL THEN RAISE EXCEPTION 'no member profile'; END IF;
  IF p_new_start IS NULL OR p_new_end IS NULL THEN RAISE EXCEPTION 'a new time is required'; END IF;
  IF p_new_end <= p_new_start THEN RAISE EXCEPTION 'the end must be after the start'; END IF;

  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND OR v_b.client_id IS DISTINCT FROM v_client THEN
    RAISE EXCEPTION 'not your booking';
  END IF;
  IF v_b.status NOT IN ('requested','pending') THEN
    RAISE EXCEPTION 'NOT_PENDING: this booking is confirmed — use a change request';
  END IF;

  UPDATE bookings
     SET starts_at = p_new_start, ends_at = p_new_end,
         reminder_1h_sent_at = NULL, reminder_2h_sent_at = NULL,
         updated_at = now()
   WHERE id = p_booking_id;

  -- the companion open row follows it, so the staff queue shows the time the
  -- client actually wants rather than the one they first picked
  UPDATE booking_change_requests
     SET proposed_starts_at = p_new_start, proposed_ends_at = p_new_end
   WHERE booking_id = p_booking_id AND status = 'pending' AND NOT coalesce(awaiting_client, false);

  PERFORM notify_staff(v_b.org_id, 'booking_time_requested',
    'A client changed their requested time to ' || to_char(p_new_start, 'FMMon FMDD, HH12:MI AM'),
    '/app/calendar');

  RETURN jsonb_build_object('booking_id', p_booking_id, 'status', 'pending',
                            'starts_at', p_new_start, 'ends_at', p_new_end);
END;
$$;


--
-- Name: update_purchase_payment_method(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_purchase_payment_method(p_purchase_id uuid, p_method text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_p purchases%ROWTYPE; v_method text := lower(btrim(coalesce(p_method,'')));
BEGIN
  SELECT * INTO v_p FROM purchases WHERE id = p_purchase_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'purchase not found'; END IF;
  IF NOT coalesce(has_staff_access() OR v_p.buyer_user_id = auth.uid()
          OR v_p.buyer_contact_id = current_contact_id(), false) THEN
    RAISE EXCEPTION 'not your purchase';
  END IF;
  IF v_method NOT IN ('zelle','cash') THEN
    RAISE EXCEPTION 'a payment method is zelle or cash';
  END IF;
  -- A PAID payment is evidence and is never re-methoded (CR-76: pending is
  -- client-editable, paid is not).
  IF coalesce(v_p.payment_status,'') = 'paid' THEN
    RAISE EXCEPTION 'this order is already paid; its method cannot be changed';
  END IF;

  UPDATE purchases SET payment_method = v_method, updated_at = now()
   WHERE id = p_purchase_id;

  PERFORM _payment_open(p_purchase_id, v_method, NULL, auth.uid(), has_staff_access());
END;
$$;


--
-- Name: upsert_change_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_change_request(p_document_id uuid, p_target_section text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_state text; v_cid uuid; v_role text; v_label text;
  v_id uuid; v_sub timestamptz; v_body text := coalesce(trim(p_body), '');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;

  SELECT org_id, workflow_state INTO v_org, v_state
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'unknown document: %', p_document_id; END IF;

  IF NOT ((coalesce(has_staff_access() AND v_org = current_org(), false))
          OR caller_is_document_party(p_document_id)) THEN
    RAISE EXCEPTION 'not a party to this document';
  END IF;

  IF v_state NOT IN ('editable','editing','in_review') THEN
    RAISE EXCEPTION 'this document is % — it is no longer open to change requests', v_state;
  END IF;

  SELECT contact_id, role, label INTO v_cid, v_role, v_label
    FROM comment_author_identity(p_document_id);
  IF v_cid IS NULL THEN RAISE EXCEPTION 'no contact identity for the caller'; END IF;

  SELECT id, submitted_at INTO v_id, v_sub
    FROM contract_change_requests
   WHERE document_id = p_document_id
     AND parent_request_id IS NULL
     AND author_contact_id = v_cid
     AND coalesce(target_section,'') = coalesce(nullif(trim(p_target_section),''), '')
   LIMIT 1;

  -- THE REVERSAL: submission no longer refuses the edit. Only a recorded view by
  -- the other party does.
  IF v_id IS NOT NULL AND change_request_is_frozen(v_id) THEN
    RAISE EXCEPTION 'the other party has already seen this request — it can no longer be edited';
  END IF;

  -- empty body → remove. Only allowed while it is still a private draft: once it
  -- has been submitted the other party has been told it exists, so it is
  -- withdrawn by resolving it, not by vanishing.
  IF v_body = '' THEN
    IF v_id IS NOT NULL AND v_sub IS NULL THEN
      DELETE FROM contract_change_requests WHERE id = v_id;
      RETURN jsonb_build_object('id', NULL, 'removed', true);
    END IF;
    IF v_id IS NULL THEN
      RETURN jsonb_build_object('id', NULL, 'removed', true);
    END IF;
    RAISE EXCEPTION 'this request has been submitted — resolve it rather than emptying it';
  END IF;

  IF v_id IS NULL THEN
    INSERT INTO contract_change_requests (
      org_id, document_id, parent_request_id, anchor_kind, anchor_ref,
      target_section, body, author_contact_id, author_role, author_label, impact_rank)
    VALUES (
      v_org, p_document_id, NULL,
      CASE WHEN nullif(trim(p_target_section),'') IS NULL THEN 'document' ELSE 'field' END,
      nullif(trim(p_target_section), ''),
      nullif(trim(p_target_section), ''),
      v_body, v_cid, v_role, v_label,
      change_request_impact_rank(p_target_section))
    RETURNING id INTO v_id;
  ELSE
    UPDATE contract_change_requests
       SET body = v_body, edited_at = now(), updated_at = now()
     WHERE id = v_id;
  END IF;

  RETURN jsonb_build_object('id', v_id, 'removed', false);
END;
$$;


--
-- Name: upsert_content_block(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
