--

CREATE FUNCTION public.validate_invitation(p_token text) RETURNS TABLE(id uuid, email text, status text, expires_at timestamp with time zone, request_id uuid, kind text, document_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT i.id, i.email, i.status, i.expires_at, i.request_id, i.kind, i.document_id
  FROM invitations i
  WHERE i.token = p_token
    AND i.status = 'sent'
    AND i.expires_at > now();
$$;


--
-- Name: version_rows_are_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.version_rows_are_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception
    'Version history is append-only: % on % is refused. A version is superseded by minting a new one, never by changing or removing a row.',
    tg_op, tg_table_name
    using errcode = 'restrict_violation';
  return null;
end;
$$;


--
-- Name: FUNCTION version_rows_are_append_only(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.version_rows_are_append_only() IS 'TASK-VERSIONSPINE: refuses UPDATE and DELETE on any version-history table. The list only ever grows.';


--
-- Name: void_deal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_deal(p_deal_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deal deals%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT has_staff_access() THEN RAISE EXCEPTION 'not authorized'; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN; END IF;

  -- executed documents are never swept; void the deal around them
  UPDATE deals SET status = 'void', deleted_at = now(), deleted_by = current_contact_id()
   WHERE id = p_deal_id;
  UPDATE contracts SET status = 'void' WHERE id = v_deal.contract_id;
END;
$$;


--
-- Name: void_document(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_document(p_document_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_title text; v_cid uuid; v_label text; v_note text;
  v_party record; v_n int := 0; v_is_party boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT can_void_document(p_document_id) THEN
    RAISE EXCEPTION 'you can no longer void this document';
  END IF;

  SELECT org_id, coalesce(title,'A contract') INTO v_org, v_title
    FROM documents WHERE id = p_document_id AND deleted_at IS NULL;

  v_is_party := caller_is_document_party(p_document_id);

  -- comment_author_identity resolves a PARTY label; a non-party staff voider gets
  -- their own contact + a staff label so the counterparty sees who acted.
  SELECT contact_id, label INTO v_cid, v_label FROM comment_author_identity(p_document_id);
  IF v_cid IS NULL THEN
    v_cid := current_contact_id();
    SELECT coalesce(nullif(trim(c.full_name), ''), 'The barn') INTO v_label
      FROM contacts c WHERE c.id = v_cid;
    v_label := coalesce(v_label, 'The barn');
  END IF;

  v_note := nullif(trim(coalesce(p_note,'')), '');

  UPDATE documents
     SET workflow_state = 'void',
         voided_at      = now(),
         voided_by      = v_cid,
         void_reason    = v_note,
         status         = 'VOID'
   WHERE id = p_document_id;

  PERFORM log_contract_change(p_document_id, 'document_voided', NULL, 'Document',
                              NULL, NULL, 'void',
                              jsonb_build_object('note', coalesce(v_note,''),
                                                 'by_staff', NOT v_is_party));

  -- notify every OTHER party, note included — identical for a staff void
  FOR v_party IN
    SELECT DISTINCT dp.contact_id FROM document_parties dp
     WHERE dp.document_id = p_document_id
       AND dp.contact_id IS DISTINCT FROM v_cid
  LOOP
    v_n := v_n + 1;
    PERFORM contract_notify(p_document_id, v_party.contact_id, 'contract_voided',
      coalesce(v_label,'The other party') || ' voided ' || v_title,
      coalesce(v_note, 'No reason was given.')
        || E'\n\nYou can keep a copy on your documents page or remove it from your view.');
  END LOOP;

  RETURN jsonb_build_object(
    'voided', true,
    'notified', v_n,
    'note', v_note,
    'by_staff', NOT v_is_party,
    -- page 2 (keep/remove) is only meaningful for a voider who is a PARTY: the
    -- hide flag governs a party's documents page, and staff read through the ops
    -- branch that deliberately ignores it.
    'offer_keep_remove', v_is_party);
END;
$$;


--
-- Name: void_purchase_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_purchase_item(p_item_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_purchase uuid;
  v_org      uuid;
  v_label    text;
BEGIN
  IF NOT coalesce(has_staff_access(), false) THEN
    RAISE EXCEPTION 'only staff may cancel a line item';
  END IF;
  SELECT pi.purchase_id, pi.org_id, pi.label INTO v_purchase, v_org, v_label
    FROM purchase_items pi WHERE pi.id = p_item_id;
  IF v_purchase IS NULL OR v_org IS DISTINCT FROM current_org() THEN
    RAISE EXCEPTION 'line item not found';
  END IF;

  -- Voided, NEVER deleted: what was asked for is evidence.
  UPDATE purchase_items
     SET voided_at = now(), voided_by = auth.uid(), void_reason = nullif(btrim(p_reason), '')
   WHERE id = p_item_id AND voided_at IS NULL;

  PERFORM log_status_event('order', v_purchase, 'item_voided',
    coalesce(v_label, 'A line item') || ' cancelled'
      || coalesce(' — ' || nullif(btrim(p_reason), ''), ''), v_org);
  -- Recomputes the total, and voids the ORDER if that was the last live line.
  PERFORM _recompute_purchase_total(v_purchase);

  RETURN (SELECT jsonb_build_object(
            'purchase_id', v_purchase, 'amount', p.amount, 'status', p.status)
          FROM purchases p WHERE p.id = v_purchase);
END;
$$;


--
-- Name: wall_onboarding_invariant_violations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wall_onboarding_invariant_violations() RETURNS TABLE(contact_id uuid, person text, wall_gating integer, onboarding_actionable integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT v.id, v.person, v.gating, v.actionable
    FROM (
      SELECT c.id,
             coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
                      c.email, c.id::text) AS person,
             (contact_document_wall_state(c.id)->>'gating')::int AS gating,
             (SELECT count(*)::int FROM contact_required_documents crd
               WHERE crd.contact_id = c.id
                 AND crd.skipped_at IS NULL   -- CLOSEOUT §1.6
                 AND NOT contact_document_satisfied(c.id, crd.template_key)) AS actionable
        FROM contacts c
       WHERE c.deleted_at IS NULL) v
   WHERE v.gating > 0 AND v.actionable = 0;
$$;


--
-- Name: FUNCTION wall_onboarding_invariant_violations(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.wall_onboarding_invariant_violations() IS 'Must always return zero rows. A row means a contact is walled with nothing to sign — the WALLSYNC deadlock. Checked by the migration that introduced the shared predicate.';


--
-- Name: weekly_digest(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_digest(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_alerts jsonb; v_tasks jsonb; v_alert_task_ids uuid[];
BEGIN
  -- stored alerts still live for this user
  SELECT coalesce(jsonb_agg(a.title ORDER BY a.created_at DESC), '[]'::jsonb),
         coalesce(array_agg(a.task_id) FILTER (WHERE a.task_id IS NOT NULL), ARRAY[]::uuid[])
    INTO v_alerts, v_alert_task_ids
    FROM alerts a
   WHERE a.user_id = p_user_id AND a.dismissed_at IS NULL
     AND (a.snoozed_until IS NULL OR a.snoozed_until <= now());

  -- active tasks the user is assigned to, minus any already surfaced as an alert
  SELECT coalesce(jsonb_agg(t.title ORDER BY t.due_at NULLS LAST, t.created_at DESC), '[]'::jsonb)
    INTO v_tasks
    FROM tasks t
    JOIN task_assignees ta ON ta.task_id = t.id AND ta.user_id = p_user_id
   WHERE t.deleted_at IS NULL AND t.status IN ('new','in_progress')
     AND NOT (t.id = ANY(v_alert_task_ids));

  RETURN jsonb_build_object('alerts', v_alerts, 'tasks', v_tasks);
END
$$;


--
-- Name: withdraw_clause(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_clause(p_addendum_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE contract_addenda SET status = 'withdrawn', resolved_at = now()
   WHERE id = p_addendum_id AND status = 'open' AND proposed_by_contact_id = current_contact_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'no open clause of yours to withdraw'; END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: withdraw_field_edit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_field_edit(p_document_id uuid, p_field_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE contract_fields
     SET proposed_value = NULL, proposed_by_contact_id = NULL, proposed_at = NULL
   WHERE document_id = p_document_id AND field_key = p_field_key
     AND proposed_by_contact_id = current_contact_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'no proposal of yours on that field'; END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: withdraw_my_pending_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_my_pending_booking(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client uuid := current_client_id();
  v_b      bookings%ROWTYPE;
  v_refund boolean := false;
BEGIN
  IF v_client IS NULL THEN RAISE EXCEPTION 'no member profile'; END IF;
  SELECT * INTO v_b FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND OR v_b.client_id IS DISTINCT FROM v_client THEN
    RAISE EXCEPTION 'not your booking';
  END IF;
  IF v_b.status NOT IN ('requested','pending') THEN
    RAISE EXCEPTION 'NOT_PENDING: this booking is confirmed — use a change request';
  END IF;

  IF v_b.credit_id IS NOT NULL THEN v_refund := _refund_booking_credit(v_b); END IF;
  UPDATE bookings SET status = 'cancelled', updated_at = now() WHERE id = p_booking_id;
  UPDATE booking_change_requests
     SET status = 'withdrawn', decided_by = auth.uid(), decided_at = now()
   WHERE booking_id = p_booking_id AND status = 'pending';

  PERFORM notify_staff(v_b.org_id, 'booking_withdrawn',
    'A client withdrew their request for ' || to_char(v_b.starts_at, 'FMMon FMDD, HH12:MI AM'),
    '/app/calendar');

  RETURN jsonb_build_object('booking_id', p_booking_id, 'status', 'cancelled',
                            'credit_refunded', v_refund);
END;
$$;


--
-- Name: withdraw_pending_composition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_pending_composition(p_pending_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  UPDATE contract_pending_compositions SET status = 'withdrawn', resolved_at = now()
   WHERE id = p_pending_id AND status = 'open' AND proposed_by_contact_id = current_contact_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'no open item of yours to withdraw'; END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


