);


--
-- Name: TABLE booking_note_seen; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.booking_note_seen IS 'DASHBOARDBUILD C6. One row = this person has read that lesson note. Same shape as contract_change_request_seen, deliberately — see that table before changing this one.';


--
-- Name: booking_notes; Type: TABLE; Schema: public; Owner: -
