    deleted_by uuid,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    customer_since timestamp with time zone,
    client_since timestamp with time zone,
    CONSTRAINT clients_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text, 'ARCHIVED'::text])))
);


--
-- Name: contacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_code text,
    first_name text,
    last_name text,
    email text,
    phone text,
    address_line1 text,
    address_line2 text,
    city text,
    state text,
    postal_code text,
    country text DEFAULT 'USA'::text,
    address_composed text GENERATED ALWAYS AS (public.compose_address(address_line1, address_line2, city, state, postal_code)) STORED,
    date_of_birth date,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    emergency_contact_1_name text,
    emergency_contact_1_relationship text,
    emergency_contact_1_phone text,
    emergency_contact_2_name text,
    emergency_contact_2_relationship text,
    emergency_contact_2_phone text,
    riding_experience_years text,
    jump_experience text,
    riding_background text,
    jump_limitations text,
    is_company boolean DEFAULT false NOT NULL,
    guardian_contact_id uuid,
    contact_type text DEFAULT 'CONTACT'::text NOT NULL,
    mobile text,
    whatsapp text,
    preferred_contact text,
    hide_email boolean DEFAULT false NOT NULL,
    hide_mobile boolean DEFAULT false NOT NULL,
    hide_whatsapp boolean DEFAULT false NOT NULL,
    social_tiktok text,
    social_instagram text,
    social_facebook text,
    social_linkedin text,
    name_needs_confirmation boolean DEFAULT false NOT NULL,
    phone_ext text,
    mobile_ext text,
    phone_display text GENERATED ALWAYS AS (
CASE
    WHEN ((phone IS NULL) OR (TRIM(BOTH FROM phone) = ''::text)) THEN NULL::text
    ELSE (public.format_phone(phone) ||
    CASE
        WHEN ((phone_ext IS NULL) OR (TRIM(BOTH FROM phone_ext) = ''::text)) THEN ''::text
        ELSE (' ext. '::text || TRIM(BOTH FROM phone_ext))
    END)
END) STORED,
    mobile_display text GENERATED ALWAYS AS (
CASE
    WHEN ((mobile IS NULL) OR (TRIM(BOTH FROM mobile) = ''::text)) THEN NULL::text
    ELSE (public.format_phone(mobile) ||
    CASE
        WHEN ((mobile_ext IS NULL) OR (TRIM(BOTH FROM mobile_ext) = ''::text)) THEN ''::text
        ELSE (' ext. '::text || TRIM(BOTH FROM mobile_ext))
    END)
END) STORED,
    mobile_call text,
    mobile_text text,
    whatsapp_call text,
    whatsapp_text text,
    community_email text,
    hide_mobile_call boolean DEFAULT false NOT NULL,
    hide_mobile_text boolean DEFAULT false NOT NULL,
    hide_whatsapp_call boolean DEFAULT false NOT NULL,
    hide_whatsapp_text boolean DEFAULT false NOT NULL,
    hide_community_email boolean DEFAULT false NOT NULL,
    rider_skill_level text,
    mobile_number text,
    texts_phone text,
    correspondence_email text,
    zelle_phone text,
    zelle_email text,
    staff_preferred_contact text DEFAULT 'none'::text NOT NULL,
    deleted_reason text,
    text_only_phone text,
    family_sort_key text,
    client_origin text,
    contact_channel text,
    CONSTRAINT contacts_contact_type_check CHECK (((contact_type IS NULL) OR (contact_type = ANY (ARRAY['LEAD'::text, 'CONTACT'::text, 'TEAM'::text, 'DIRECTORY'::text, 'VENDOR'::text, 'PARTNER'::text])))),
    CONSTRAINT contacts_staff_preferred_contact_check CHECK ((staff_preferred_contact = ANY (ARRAY['none'::text, 'phone_call'::text, 'text'::text, 'email'::text])))
);


--
-- Name: TABLE contacts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contacts IS 'THE person record — the single home for everything we know about a human or organisation, whether or not they have a login. `profiles` is the ACCOUNT (auth bridge, role, community persona, tour markers) and holds nothing about the person. Onboarding, the website form, the app profile page and every staff surface all read and write HERE.';


--
-- Name: COLUMN contacts.contact_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.contact_type IS 'The person-page discriminator — one row appears on exactly ONE page. LEAD: a potential future client we may reach out to or include in a campaign. CONTACT: an internal person the business serves (client, member, horse owner, counterparty) who is not part of the company. TEAM: the company itself — staff, internal accounts, and the tenant org record. DIRECTORY: external people and businesses that PROVIDE something — farriers, vets, suppliers, service providers, event organizers. Explicit and settable. NULL means unclassified and is surfaced for a human decision, never silently bucketed — the old "Lead" was assigned whenever nothing else matched, which is why it never formed a usable campaign list.';


--
-- Name: COLUMN contacts.name_needs_confirmation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.name_needs_confirmation IS 'TRUE when we cannot safely assert this person''s legal name and they must supply it before filling a form or signing anything. Set when two sources disagreed irreconcilably (not a mere abbreviation) — the alternative was to guess, and a guessed surname on an executed contract is not recoverable. Cleared the moment they confirm.';


--
-- Name: COLUMN contacts.phone_ext; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.phone_ext IS 'Extension for `phone`, stored separately so the number itself stays clean and dialable. Composed into the display form as "(858) 439-3614 ext. 412".';


--
-- Name: COLUMN contacts.phone_display; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.phone_display IS 'THE reading form of the phone number, generated from phone + phone_ext. Every surface that SHOWS a number should read this; `phone` is the storage form. Generated, so it cannot fall out of step with its parts.';


--
-- Name: COLUMN contacts.mobile_call; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.mobile_call IS 'Community-facing number for phone calls. Independent of contacts.phone (the company-on-file number): seeded from it once, then fully the member''s to change. Hidden from the community when hide_mobile_call.';


--
-- Name: COLUMN contacts.community_email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.community_email IS 'Community-facing email, may differ from the account/login email. Seeded from the contact email once, then independent.';


--
-- Name: COLUMN contacts.rider_skill_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.rider_skill_level IS 'Internal staff assessment of the rider''s level; pairs with horses.rider_level_min/max for horse-rider matching.';


--
-- Name: COLUMN contacts.deleted_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.deleted_reason IS 'Why this contact was archived, captured by archive_contact (D19). Cleared by unarchive_contact; the audit_contacts trigger keeps the prior value in audit_logs either way.';


--
-- Name: COLUMN contacts.text_only_phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.text_only_phone IS 'An alternate number the person wants TEXTS ONLY on. `phone` is their mobile and the number we call. Added 2026-08-24 (TASK-INTAKE).';


--
-- Name: clients_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.clients_overview WITH (security_invoker='true') AS
 SELECT cl.id,
    cl.status,
    cl.source,
    cl.created_at,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    c.display_code
   FROM (public.clients cl
     JOIN public.contacts c ON ((c.id = cl.contact_id)))
  WHERE (cl.deleted_at IS NULL);


