    guidance text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    render_as_subitem boolean DEFAULT false NOT NULL,
    draft_body text,
    CONSTRAINT contract_clause_defs_clause_type_check CHECK ((clause_type = ANY (ARRAY['input'::text, 'prose'::text, 'choice'::text])))
);


--
-- Name: COLUMN contract_clause_defs.draft_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_clause_defs.draft_body IS 'Unpublished wording edit from the template editor. NULL = no pending edit. Publish copies this into body and clears it; nothing else may read it — remerge_contract_from_clauses reads body only.';


