--

COMMENT ON COLUMN public.contract_field_defs.default_value IS 'Seeded into contract_fields.value when a document is created. NULL = seed blank. Never applied to an existing document - sync_contract_fields_from_defs deliberately leaves values alone, so a default cannot retro-answer a question a party already saw.';


--
-- Name: contract_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contract_fields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    document_id uuid NOT NULL,
    field_key text NOT NULL,
    label text,
    section text,
    owner_role text NOT NULL,
    value text,
    value_type text DEFAULT 'text'::text,
    entered_by_contact_id uuid,
    entered_at timestamp with time zone,
    required boolean DEFAULT false,
    sort_order integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    proposed_value text,
    proposed_by_contact_id uuid,
    proposed_at timestamp with time zone,
    parent_field_key text,
    input_kind text,
    options jsonb,
    conditional_on jsonb,
    guidance text,
    is_optional boolean DEFAULT false NOT NULL,
    included boolean DEFAULT true NOT NULL,
    is_na boolean DEFAULT false NOT NULL,
    control_override jsonb,
    responsibility jsonb,
    format_type text,
    structured jsonb,
    pair_cost_key text,
    pair_manage_key text,
    clause_key text,
    responsibility_kind text,
    closed boolean DEFAULT false NOT NULL,
    custom_kind text,
    body text,
    added_by_contact_id uuid,
    CONSTRAINT contract_fields_custom_kind_chk CHECK (((custom_kind IS NULL) OR (custom_kind = ANY (ARRAY['section'::text, 'header'::text, 'line'::text, 'element'::text])))),
    CONSTRAINT contract_fields_value_type_check CHECK ((value_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'currency'::text, 'checkbox'::text, 'select'::text, 'longtext'::text])))
);

ALTER TABLE ONLY public.contract_fields REPLICA IDENTITY FULL;


--
-- Name: TABLE contract_fields; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contract_fields IS 'Structured, party-owned field store for a contract document. owner_role names the party_role that owns/must-fill the field (personal/horse fields → that party; DEAL fields → the originator, and the counterparty only when documents.recipient_editing). All writes go through set_contract_field()/seed_contract_fields() (SECURITY DEFINER) — no direct authenticated DML — so ownership enforcement is centralized.';


--
-- Name: COLUMN contract_fields.custom_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_fields.custom_kind IS 'Author-added row kind: section | header | line | element. NULL = a template field, or a legacy custom field from the pre-R11 add surface (still rendered as "Label: value").';


--
-- Name: COLUMN contract_fields.body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_fields.body IS 'Prose of a custom_kind=''line'' row, with {{CUSTOM.*}} tokens where inline elements sit — the same convention contract_clause_defs.body uses.';


