    CONSTRAINT contract_role_documents_doc_role_check CHECK ((doc_role = ANY (ARRAY['BUYER'::text, 'LESSEE'::text, 'LESSOR'::text, 'SELLER'::text])))
);


--
-- Name: contract_section_defs; Type: TABLE; Schema: public; Owner: -
--

