    is_signer boolean DEFAULT false NOT NULL,
    signer_order integer,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT document_parties_party_role_check CHECK ((party_role = ANY (ARRAY['CLIENT'::text, 'BUYER'::text, 'SELLER'::text, 'LESSOR'::text, 'LESSEE'::text, 'OWNER'::text, 'RIDER'::text, 'PARTICIPANT'::text, 'PARENT'::text, 'GUARDIAN'::text, 'EMERGENCY_CONTACT'::text, 'CONTRACTOR'::text, 'FACILITY_CONTACT'::text, 'FHE'::text])))
);


