);


--
-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_code text,
    template_id uuid,
    title text,
    merged_body text,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    effective_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    execution_hash text,
    workflow_state text DEFAULT 'editable'::text NOT NULL,
    recipient_editing boolean DEFAULT false NOT NULL,
    originator_contact_id uuid,
    horse_section_confirmed_at timestamp with time zone,
    horse_section_confirmed_by uuid,
    contact_id uuid,
    horse_id uuid,
    contract_id uuid,
    sign_sequence integer,
    sent_at timestamp with time zone,
    archived_at timestamp with time zone,
    archived_by uuid,
    terminated_at timestamp with time zone,
    terminated_by uuid,
    termination_requested_at timestamp with time zone,
    termination_requested_by uuid,
    termination_request_reason text,
    current_status text,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    signed_template_version integer,
    signatures_voided_at timestamp with time zone,
    signatures_voided_roles text[],
    executed_email_sent_at timestamp with time zone,
    executed_email_error text,
    delivery_held_at timestamp with time zone,
    delivery_set_id uuid,
    CONSTRAINT documents_workflow_state_check CHECK ((workflow_state = ANY (ARRAY['editable'::text, 'editing'::text, 'in_review'::text, 'locked'::text, 'executed'::text, 'void'::text, 'terminated'::text])))
);

ALTER TABLE ONLY public.documents REPLICA IDENTITY FULL;


--
-- Name: COLUMN documents.execution_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.execution_hash IS 'SHA-256 over the final merged_body + sealing signature fields (signer contact id, typed_name, signed_at), hex. Stamped once at the EXECUTED flip; NULL for drafts and for documents executed before 20260703110000.';


--
-- Name: COLUMN documents.workflow_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.workflow_state IS 'Finer multi-party workflow layer beside status (DRAFT..EXECUTED). editable→editing→in_review→locked→executed, plus void. Executed is reached ONLY through record_signature (v6 sets it at the EXECUTED flip); advance_document_workflow rejects a manual →executed.';


--
-- Name: COLUMN documents.recipient_editing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.recipient_editing IS 'Whether the NON-originating party may edit DEAL fields / body (vs only their own personal fields). Mirrored from the active document_shares row; toggled by set_recipient_editing / share_document.';


--
-- Name: COLUMN documents.originator_contact_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.originator_contact_id IS 'The party who started this contract (always "us"/the initiating client — e.g. the LESSEE on a LEASE_IN). The originator always owns DEAL fields; the counterparty may touch them only when recipient_editing is true.';


--
-- Name: COLUMN documents.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.void_reason IS 'The voiding party''s note to the other party ("why I am no longer interested"). Shown to the counterparty in their notification and on the voided document.';


--
-- Name: COLUMN documents.signed_template_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.signed_template_version IS 'The contract_templates.version in force WHEN THIS DOCUMENT WAS SIGNED, frozen at signature time. Templates are edited in place (one row per key, version bumped), so template_id alone cannot tell you what the signer actually read — an old signature would inherit the new number. This column is the evidence.';


--
-- Name: COLUMN documents.signatures_voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.signatures_voided_at IS 'When an edit last invalidated one or more signatures on this document. Cleared when the document is next sent for review, which is when the affected parties are told — an author edits in bursts and may revert, so alerting on each field change would make the alert meaningless.';


--
-- Name: COLUMN documents.executed_email_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.executed_email_sent_at IS 'When the executed-copy email was dispatched. NULL = not sent (UI offers SEND); set = sent (UI offers RESEND).';


--
-- Name: COLUMN documents.executed_email_error; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.executed_email_error IS 'Last dispatch failure, surfaced to staff so a silent non-delivery is impossible.';


--
-- Name: COLUMN documents.delivery_held_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documents.delivery_held_at IS 'ONBOARD §4: set when an executed document is deliberately NOT emailed yet because its signer is mid-signing-run. Cleared when the set goes out as one email. NULL on every pre-existing row, which is what keeps the flush away from history.';


--
-- Name: email_lookup_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.email_lookup_attempts (
    user_id uuid NOT NULL,
    attempted_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: email_template_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.email_template_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_id uuid NOT NULL,
    email_key text NOT NULL,
    version integer NOT NULL,
    parent_version integer,
    title text NOT NULL,
    subject text NOT NULL,
    body text NOT NULL,
    edited_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT email_template_versions_parent_is_earlier CHECK (((parent_version IS NULL) OR ((parent_version >= 1) AND (parent_version < version))))
);


--
-- Name: TABLE email_template_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.email_template_versions IS 'TASK-SURFACEEDITOR: the retained history of every email template. Append-only; the history holds EVERY version including the live one (TASK-VERSIONSPINE §5.1''s settled storage rule).';


--
-- Name: COLUMN email_template_versions.parent_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_template_versions.parent_version IS 'The version this one was edited FROM. NULL = the immediately preceding version (the ordinary case). Never points forward.';


