    CONSTRAINT requests_channel_check CHECK (((channel IS NULL) OR (channel = ANY (ARRAY['contact'::text, 'inquiry'::text, 'booking'::text, 'kiosk'::text, 'gift'::text])))),
    CONSTRAINT requests_contact_method_check CHECK ((contact_method = ANY (ARRAY['text'::text, 'call'::text, 'email'::text]))),
