COMMENT ON COLUMN public.requests.interests IS 'The CHECKBOXES revealed by the menu selection (requests.category), owner ruling 2026-09-01. When category = ''visit'' these are the offering categories they said they are interested in; when category is an offering category, this carries ''visit'' if they ticked the come-and-visit box. NEVER the menu answer itself.';


--
-- Name: inbound_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.inbound_queue WITH (security_invoker='true') AS
 SELECT r.id,
    r.org_id,
    r.status,
    r.channel,
    r.category,
    r.created_at,
    r.contact_first_name,
    r.contact_last_name,
    r.contact_email,
    r.contact_phone,
    r.subject,
    r.notes,
    r.staff_notes,
    r.proposed_times,
    r.booking_eligible,
    ((now())::date - (r.created_at)::date) AS days_open,
    c.id AS contact_id,
    c.contact_type,
    (c.contact_type = 'CONTACT'::text) AS already_converted,
    ((r.status = 'new'::text) AND (COALESCE(c.contact_type, ''::text) <> 'CONTACT'::text) AND (((now())::date - (r.created_at)::date) >= 2)) AS overdue,
        CASE
            WHEN (a.succeeded_at IS NOT NULL) THEN 'sent'::text
            WHEN (r.created_at < '2026-08-12 14:36:00-07'::timestamp with time zone) THEN 'unknown'::text
            WHEN (a.attempts = 0) THEN 'not_attempted'::text
            ELSE 'failed'::text
        END AS alert_state,
    COALESCE(a.succeeded_at, a.last_attempt_at) AS alert_attempted_at,
    a.last_recipient AS alert_recipient,
        CASE
            WHEN (a.succeeded_at IS NULL) THEN a.last_error
            ELSE NULL::text
        END AS alert_error
   FROM ((public.requests r
     LEFT JOIN LATERAL ( SELECT c2.id,
            c2.contact_type
           FROM public.contacts c2
          WHERE ((c2.deleted_at IS NULL) AND (c2.org_id = r.org_id) AND (((r.contact_id IS NOT NULL) AND (c2.id = r.contact_id)) OR ((r.contact_id IS NULL) AND (lower(c2.email) = lower(r.contact_email)))))
          ORDER BY c2.created_at
         LIMIT 1) c ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS attempts,
            max(s.attempted_at) FILTER (WHERE s.succeeded) AS succeeded_at,
            max(s.attempted_at) AS last_attempt_at,
            (array_agg(s.recipient_email ORDER BY s.attempted_at DESC))[1] AS last_recipient,
            (array_agg(s.error ORDER BY s.attempted_at DESC))[1] AS last_error
           FROM public.request_alert_sends s
          WHERE (s.request_id = r.id)) a ON (true));


--
-- Name: VIEW inbound_queue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.inbound_queue IS 'The inbound lead queue: the request, how long it has waited, whether its person was ever captured (already_converted), and — INBOUNDALERT — whether the ops inbox was actually told about it (alert_state/alert_error). Rows created before 2026-08-12 21:36Z report alert_state ''unknown'': no attempt record existed then, so silence is not evidence either way.';


