--

COMMENT ON COLUMN public.purchase_items.voided_at IS 'CAREPATH C5b: a cancelled line is voided, never deleted — the record of what was asked for is evidence. A voided line is excluded from the order total.';


--
-- Name: purchases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    display_code text,
    org_id uuid DEFAULT public.current_org() NOT NULL,
    contract_id uuid,
    buyer_contact_id uuid,
    buyer_user_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    amount numeric DEFAULT 0 NOT NULL,
    payment_method text,
    payment_status text DEFAULT 'unpaid'::text NOT NULL,
    payment_reference text,
    unique_amount numeric,
    paid_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    horse_id uuid,
    amount_paid numeric DEFAULT 0 NOT NULL,
    current_status text,
    client_reported_method text,
    client_reported_reference text,
    client_reported_at timestamp with time zone,
    client_claim_status text DEFAULT 'none'::text NOT NULL,
    client_claim_resolved_by uuid,
    client_claim_resolved_at timestamp with time zone,
    client_claim_decline_reason text,
    request_id uuid,
    payment_disposition text DEFAULT 'paid'::text NOT NULL,
    write_down_amount numeric DEFAULT 0 NOT NULL,
    write_down_reason text,
    CONSTRAINT purchases_client_claim_status_check CHECK ((client_claim_status = ANY (ARRAY['none'::text, 'pending'::text, 'confirmed'::text, 'declined'::text]))),
    CONSTRAINT purchases_payment_disposition_check CHECK ((payment_disposition = ANY (ARRAY['paid'::text, 'discounted'::text, 'comped'::text]))),
    CONSTRAINT purchases_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'pending'::text, 'paid'::text]))),
    CONSTRAINT purchases_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'awaiting_payment'::text, 'paid'::text, 'void'::text]))),
    CONSTRAINT purchases_write_down_shape_check CHECK ((((payment_disposition = 'paid'::text) AND (write_down_amount = (0)::numeric)) OR ((payment_disposition <> 'paid'::text) AND (write_down_amount > (0)::numeric) AND (write_down_reason IS NOT NULL))))
);


--
-- Name: COLUMN purchases.client_reported_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.purchases.client_reported_method IS 'ONBOARD §6: what the BUYER says they did — ''zelle'' or ''cash''. A claim, never a confirmation. payment_status is still only ever written by staff reconciliation.';


--
-- Name: COLUMN purchases.client_reported_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.purchases.client_reported_reference IS 'ONBOARD §6: the confirmation number the buyer typed, if they typed one. Optional by owner instruction ("if they leave it blank thats ok"). NOT payment_reference — that is the memo code WE generate for matching, and it is never overwritten by this.';


--
-- Name: COLUMN purchases.client_claim_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.purchases.client_claim_status IS 'CASHCONFIRM: staff handling of the current client-reported claim — ''none'' (no claim), ''pending'' (claimed, awaiting staff), ''confirmed'', ''declined''. Distinct from client_reported_* (the claim itself, never overwritten here) and from payment_status (never set by a claim — only mark_purchase_paid sets that).';


--
-- Name: COLUMN purchases.request_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.purchases.request_id IS 'CAREPATH C5: the inquiry this order came from. Both halves of a split order carry the same value, so staff never lose why order B exists.';


