-- Name: segment_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.segment_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    segment text NOT NULL,
    request_category text NOT NULL,
    onboarding_category text NOT NULL,
    onboarding_token text NOT NULL,
    CONSTRAINT segment_categories_onboarding_category_check CHECK ((onboarding_category = ANY (ARRAY['Guest'::text, 'Rider'::text, 'Horse owner'::text, 'Deal client'::text]))),
    CONSTRAINT segment_categories_onboarding_token_check CHECK ((onboarding_token = ANY (ARRAY['GUEST'::text, 'RIDER'::text, 'HORSE_OWNER'::text]))),
    CONSTRAINT segment_categories_request_category_check CHECK ((request_category = ANY (ARRAY['general'::text, 'lessons'::text, 'horse_care'::text, 'acquisition'::text, 'media'::text, 'partnership'::text, 'gift'::text]))),
    CONSTRAINT segment_categories_segment_check CHECK ((segment = ANY (ARRAY['rider'::text, 'horse'::text, 'acquisition'::text])))
);


--
-- Name: TABLE segment_categories; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.segment_categories IS 'TASK-CATEGORISE: what an offering''s segment means in the two category vocabularies. Read by the request_categories view (staff filtering) and by request_onboarding_categories() (the provisioning default). One row per segment per tenant.';


--
-- Name: request_categories; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.request_categories WITH (security_invoker='true') AS
 SELECT request_id,
    org_id,
    category,
    bool_or(from_cart) AS from_cart,
    bool_or(from_funnel) AS from_funnel
   FROM ( SELECT r.id AS request_id,
            r.org_id,
            sc.request_category AS category,
            true AS from_cart,
            false AS from_funnel
           FROM (((public.requests r
             JOIN public.request_selections rs ON ((rs.request_id = r.id)))
             JOIN public.offerings o ON (((o.org_id = r.org_id) AND ((o.id = rs.offering_id) OR ((rs.offering_id IS NULL) AND ((o.slug = rs.offering_slug) OR ((o.id)::text = rs.offering_slug)))))))
             JOIN public.segment_categories sc ON (((sc.org_id = r.org_id) AND (sc.segment = o.segment))))
        UNION ALL
         SELECT r.id,
            r.org_id,
            r.category,
            false,
            true
           FROM public.requests r
          WHERE (r.category IS NOT NULL)) s
  GROUP BY request_id, org_id, category;


--
-- Name: VIEW request_categories; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.request_categories IS 'TASK-CATEGORISE: the PLURAL category membership of an inquiry — every category its cart touches, plus the single value the funnel stored. Beside requests.category, never instead of it. Staff category filters read this.';


