INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6641ed33-9d0d-4544-a108-a46a83a4852c', 'HORSE_SALE_V2', 'PPE', 'PPE.CONTINGENCY_NODEP', 'Sale Contingent on Examination', 'This sale is contingent on a pre-purchase examination whose results are satisfactory to Buyer in Buyer''s reasonable discretion. If the Buyer gives Seller written notice that the examination results are not satisfactory, this Agreement terminates, and neither party has further obligation to the other except obligations that expressly survive.', 'input', 20, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["YES"], "field_key": "TXN.PPE_CONTINGENT"}, {"equals": ["NO"], "field_key": "TXN.DEPOSIT_ENABLED"}]}', NULL, '2026-09-28 12:02:59.530037-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9df99f00-6108-40b1-b148-6dc568996b57', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.TRAINER_EVAL', 'Pre-Lease Trainer Evaluation', 'Pre-lease trainer evaluation of the Horse: {{TXN.TRAINER_EVAL_CHOICE}}', 'input', 55, false, NULL, NULL, NULL, '2026-07-27 13:12:30.672304-07', false, NULL);
