', 'input', 5, false, NULL, NULL, NULL, '2026-07-21 05:19:05.018123-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f5711e45-d829-43ff-a719-71f3d53921c2', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PROHIBITED.OTHERS_OTHER', NULL, 'Other persons allowed to ride or handle the Horse:
{{TXN.OTHERS_ALLOWED_OTHER}}', 'input', 490, false, NULL, '{"contains": ["OTHER"], "field_key": "TXN.OTHERS_ALLOWED"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('34e59eef-f689-4065-96ac-0e9162ef9e26', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.SAFETY_ATTIRE', 'Required Protective Attire', 'Lessee shall wear, and shall ensure that any other person riding the Horse under Lessee''s authorization wears, an appropriately fitted and securely fastened ASTM/SEI-certified equestrian helmet at all times while mounted on the Horse, together with heeled boots and long pants; gloves and long sleeves are highly recommended. Riders shall provide their own helmet, boots, and pants meeting these requirements unless otherwise agreed in writing. Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, assumes all increased risk of injury or death resulting from any failure to wear the required attire. Any refusal or failure to wear an approved helmet or the other required attire immediately revokes permission to ride or handle the Horse and constitutes a material breach of this Agreement.', 'prose', 1100, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('520477e2-0c97-402a-bff8-07c1259e18e9', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PROHIBITED.OTHERS_OTHER', NULL, 'Other persons allowed to ride or handle the Horse:
{{TXN.OTHERS_ALLOWED_OTHER}}', 'input', 490, false, NULL, '{"contains": ["OTHER"], "field_key": "TXN.OTHERS_ALLOWED"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
