{{TXN.PROTECTIVE_EQUIPMENT_OTHER}}', 'input', 63, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.PROTECTIVE_REQUIRED"}, {"contains": ["OTHER"], "field_key": "TXN.PROTECTIVE_EQUIPMENT"}]}', NULL, '2026-08-09 10:44:37.989495-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b56b50e6-97b6-43bf-84c8-28b1af2e7d2b', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.RETURN_NODEP', NULL, 'If Buyer returns the Horse with approved notice on or before that date, this Agreement terminates.', 'prose', 12, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"equals": ["NO"], "field_key": "TXN.DEPOSIT_ENABLED"}]}', NULL, '2026-09-28 12:02:59.839659-07', true, NULL);
