INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('478c444b-f9cd-4754-b247-73dfa4ae2712', 'HORSE_LEASE_V2', 'EVALUATION', 'EVALUATION.WAIVED', NULL, 'No evaluation period applies to this Agreement. The Lessee has waived any evaluation period, and the Lease begins on the Effective Date without one.', 'input', 41, false, NULL, '{"any": [{"equals": ["WAIVED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-07-31 13:30:42.09657-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e0ec5d84-9fc8-46b5-b185-87a7bec65b8c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RISK_OF_LOSS', 'Risk of Loss of or Injury to the Horse', 'Lessor assumes all risk of loss of or injury to the Horse during the term of this Agreement, except to the extent caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct.', 'input', 500, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('86340cdc-5509-426c-8646-a1f0309e7b98', 'HORSE_LEASE_V2', 'PAYMENT_TERMS', 'PAYMENT_TERMS.LATE', 'Late Payments', 'All payments are due on their due date or within 5 business days of notification of the amount owed. Payments will be deemed late if they remain unpaid on the 6th business day. Late payments are considered a breach of the contract terms and may be grounds for termination of the Agreement unless the party from whom the payment is owed has communicated in writing the date by which payment will be made. Payments exceeding 1 calendar month in past-due status constitute grounds for termination for cause under the Termination for Cause provisions of this Agreement unless prior written acceptance of the delay is provided by the party to whom the payment is owed.', 'input', 40, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('20614d1f-d53c-454a-aad6-832e1427d6b7', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORTALITY', 'Mortality Insurance', '', 'input', 200, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
