INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0433aa3f-42c5-435b-a090-44c3542504d0', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.INSURANCE', 'Insurance Requirements', 'The parties agree to the insurance elections set forth below. Each policy elected or required below shall be maintained in effect for the duration of this Agreement.', 'prose', 100, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3066d984-936d-4c13-8543-617937e8d5a4', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.NOT_RETURNED', NULL, 'If the Horse is not returned and no such notice is given by that date, Buyer is deemed to have accepted the Horse and Closing proceeds under this Agreement.', 'prose', 13, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-09-28 12:02:59.839659-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7b0df54b-5942-4f84-b87b-556f2437798f', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE', 'Release of Liability', 'In consideration for being permitted to handle or ride the Horse, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, completely releases, forever discharges, and agrees to hold harmless the Lessor Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessee''s use, handling, or riding of the Horse, whether caused by the ordinary negligence of any Lessor Party or otherwise. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 960, false, NULL, NULL, NULL, '2026-07-20 19:48:55.640351-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b99ed9ba-80eb-40e7-851a-6ff48f2678cf', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement.', 'prose', 1300, false, NULL, NULL, NULL, '2026-07-20 14:49:33.78281-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('87ce748d-c496-4aa0-8d27-717074492b21', 'HORSE_LEASE_V2', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 14:51:03.659545-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3297bc65-483e-4f03-afd6-303b936c1c0d', 'HORSE_LEASE_V2', 'CARE', 'CARE.PROTECTIVE_EQUIP', NULL, 'Lessor will provide the following equipment for the Horse: {{TXN.PROTECTIVE_EQUIPMENT}}
Lessee must ensure equipment is used and properly secured to the Horse prior to all activities.', 'input', 62, true, NULL, '{"equals": ["YES"], "field_key": "TXN.PROTECTIVE_REQUIRED"}', NULL, '2026-07-21 12:52:35.787525-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6df79ded-6550-4e96-a0a7-e0a2c305b478', 'HORSE_LEASE_V2', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_ENTITY', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is duly organized and in good standing, and has full authority to enter into this Agreement, and that the individual signing this Agreement does so as Lessee''s authorized representative; that each person who rides or handles the Horse under Lessee''s authorization will, before doing so, have executed the releases required under this Agreement and possess the knowledge and experience to handle and ride the Horse safely; and that Lessee will use reasonable care and follow Lessor''s instructions in all handling of the Horse. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-07-27 17:36:43.221618-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('52cf43dd-21c4-40b7-be1e-cae4f5f13d43', 'HORSE_LEASE_FULL', 'CARE', 'CARE.RIDER_AIDS_LIST', NULL, 'Lessor prohibits the use of the following rider aids: {{TXN.RIDER_AIDS}}', 'input', 92, false, NULL, '{"equals": ["YES"], "field_key": "TXN.RIDER_AIDS_PROHIBITED"}', NULL, '2026-08-09 10:44:37.989495-07', false, NULL);
