INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('18db9f1b-0c0e-4109-84ee-d639485487e8', 'HORSE_LEASE_V2', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

