INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1d9d19ff-0f8c-4b7d-8722-3b53558cf9a2', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.INTRO', NULL, 'This Horse Sale and Purchase Agreement (the "Agreement") is made effective as of {{DOC.EFFECTIVE_DATE}} by and between {{SELLER.FULL_NAME}} of {{SELLER.ADDRESS}} ("Seller") and {{BUYER.FULL_NAME}} of {{BUYER.ADDRESS}} ("Buyer").', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:12.539765-07', false, NULL);
