INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c18b8272-df3f-4f74-8484-35c713d928b7', 'HORSE_LEASE_V2', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment or Transfer', 'Lessee shall not assign, sublease, or otherwise transfer this Agreement or any of Lessee''s rights or obligations under it without Lessor''s prior written consent, unless permitted in the sections above.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 14:51:03.659545-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dd302a61-c66d-413f-8eab-58d9b727b8ed', 'HORSE_SALE_V2', 'HORSE', 'HORSE.BREEDING', 'Breeding Warranty', 'Seller expressly warrants that, to Seller''s knowledge, the Horse is capable of breeding and free of any reproductive condition that would prevent it, as supported by the reproductive examination or records described here: {{TXN.BREEDING_BASIS}}. If a licensed veterinarian determines within {{TXN.BREEDING_CLAIM_WINDOW}} days after Closing that the Horse was incapable of breeding as of Closing due to a condition existing at Closing, Buyer''s exclusive remedy is, at Buyer''s election, return of the Horse in substantially the condition delivered for a refund of the Purchase Price, or a reduction of the Purchase Price agreed by the parties. This is the sole warranty regarding breeding and does not otherwise limit the Disclaimer of Warranties.', 'input', 90, false, NULL, '{"all": [{"any": [{"equals": ["Mare"], "field_key": "HORSE.SEX"}, {"equals": ["Stallion"], "field_key": "HORSE.SEX"}, {"equals": ["Colt"], "field_key": "HORSE.SEX"}, {"equals": ["Filly"], "field_key": "HORSE.SEX"}]}, {"equals": ["INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}]}', NULL, '2026-08-02 07:03:13.506345-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1265c8ff-3bb4-4d63-9c3a-bc471eaa7ea4', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE_LESSOR', 'Release of Liability by Lessor', 'In consideration of the mutual promises in this Agreement, Lessor, on behalf of Lessor and anyone claiming by, through, or under Lessor, completely releases, forever discharges, and agrees to hold harmless the Lessee Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessor''s riding or handling of the Horse or Lessor''s presence at any facility where the Horse is kept during the term of this Agreement, whether caused by the ordinary negligence of any Lessee Party or otherwise. Lessor expressly and voluntarily assumes all inherent risks of equine activities in connection with such riding, handling, or presence. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 961, false, NULL, NULL, NULL, '2026-08-02 04:16:19.009752-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('14346b45-54f7-4c4b-8b23-fd70145fee86', 'HORSE_LEASE_STANDARD', 'CARE', 'CARE.RIDER_AIDS_OTHER', NULL, 'Other prohibited rider aid:
