INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('30ca5326-b4eb-43db-bb15-4c7f59368985', 'HORSE_LEASE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Rider and Other Serious Injuries', 'Lessor discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Lessee acknowledges this disclosure and proceeds with knowledge of it.', 'input', 45, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 04:16:19.009752-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7186adae-35c0-4112-b0ca-d9f5cb04ccba', 'HORSE_LEASE_V2', 'PURPOSE', 'PURPOSE.RECREATION', 'Purpose of Agreement', 'For {{TXN.LEASE_PURPOSE}} purposes, Lessee wishes to ride and/or handle Lessor''s horse, and Lessor agrees to allow Lessee to ride and/or handle Lessor''s horse in exchange for the consideration described herein.', 'prose', 10, false, NULL, '{"equals": ["RECREATIONAL", "INSTRUCTIONAL", "COMPETITION", "COMMERCIAL"], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-07-20 14:43:51.525808-07', false, NULL);
