INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e4b81e32-f91f-49ee-bf31-0607c2cadd0d', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_REQ', NULL, 'Lessor requires Lessee to maintain care, custody and control insurance for the duration of this Agreement. Care, custody and control insurance applies only where injury to, or death of the Horse is caused by Lessee''s negligence. It shall not be claimed against merely because other coverage is unavailable, is not in force, or has denied a claim. Where a loss is caused by Lessee''s negligence, care, custody and control insurance is the policy to be claimed against for that loss.', 'input', 173, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["YES"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3e9fa9e8-b1ac-44df-9536-c7e3b5535e9a', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_REQ', NULL, 'Lessor requires Lessee to maintain care, custody and control insurance for the duration of this Agreement. Care, custody and control insurance applies only where injury to, or death of the Horse is caused by Lessee''s negligence. It shall not be claimed against merely because other coverage is unavailable, is not in force, or has denied a claim. Where a loss is caused by Lessee''s negligence, care, custody and control insurance is the policy to be claimed against for that loss.', 'input', 173, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["YES"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('96e1416b-089e-49de-99d6-acc503f344ff', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_REQ', NULL, 'Lessor requires Lessee to maintain care, custody and control insurance for the duration of this Agreement. Care, custody and control insurance applies only where injury to, or death of the Horse is caused by Lessee''s negligence. It shall not be claimed against merely because other coverage is unavailable, is not in force, or has denied a claim. Where a loss is caused by Lessee''s negligence, care, custody and control insurance is the policy to be claimed against for that loss.', 'input', 173, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["YES"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9445b24b-dda7-4a99-b69e-c30cab92b061', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_STATUS', NULL, 'Lessee {{TXN.CCC_LESSEE_STATUS}} care, custody and control insurance covering the Horse while in Lessee''s care, custody, or control.', 'input', 174, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cd7758b6-3d70-41c2-a54d-dfbbf628e56b', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.TRANSPORT', NULL, 'Transport is arranged by {{TXN.TRANSPORT_RESPONSIBLE}} and paid for by {{TXN.TRANSPORT_COST_RESPONSIBLE}}.', 'prose', 11, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRANSPORT_APPLIES"}', NULL, '2026-10-12 10:19:30.914119-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ab230df9-e6be-4acc-8e62-1a7df0684b70', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.DELAYS', NULL, 'If Buyer fails to take delivery within 7 days of the agreed date other than due to Seller''s delay, Buyer shall pay board and care for the Horse at {{TXN.BOARD_RATE_AFTER}} per day until delivery occurs. If Seller delays delivery by more than 7 days, Seller shall pay {{TXN.SELLER_DELAY_PENALTY}} penalty to Buyer per day until delivery occurs.', 'prose', 12, false, NULL, NULL, NULL, '2026-10-12 10:20:08.423063-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('24200eb7-288f-42a2-b099-5a0d55dda3e4', 'HORSE_LEASE_SIMPLE', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions and understandings. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0726a0ad-f271-4f9c-b3f9-3c78fd29603f', 'HORSE_LEASE_V2', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions and understandings. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-07-20 14:51:03.659545-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('21d6488a-495d-453c-a3a1-b30dc83a8d1a', 'HORSE_SALE_V3', 'PRICE', 'PRICE.FINANCING_PENDING', NULL, '[Pending — select the financing arrangement. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 69, false, NULL, '{"equals": [""], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f577c709-4c39-43a0-a7a6-474cb8b81d59', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.OWNERSHIP_LIMITS_GATE', NULL, '', 'input', 112, false, NULL, NULL, NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('94eade0c-c0bc-413e-b550-54c4e8147f7a', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.OWNERSHIP_LIMITS_PENDING', NULL, '[Pending — select whether any ownership related leasing restrictions apply. This placeholder is replaced by the applicable statement and blocks signing.]', 'input', 113, false, NULL, '{"equals": [""], "field_key": "TXN.HAS_OWNERSHIP_LIMITS"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7b0eef0b-aab6-4e72-9db8-932e62b8e9b6', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.MEDICAL_HISTORY_DISCLOSED_ACK', NULL, 'Lessee acknowledges the medical history disclosed above and proceeds with knowledge of it. Initialed: {{ACK.MEDICAL_HISTORY}}', 'input', 163, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.MEDICAL_HISTORY_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('05c02d26-d5b2-4631-a4f0-f7119d8bd09d', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.CO_BUYER', 'Co-Buyer', '{{COBUYER.FULL_NAME}} of {{COBUYER.ADDRESS}} ("Co-Buyer") purchases the Horse jointly with Buyer. Co-Buyer is a Buyer for all purposes of this Agreement, every reference to Buyer includes Co-Buyer, and the representations, covenants, releases, waivers, and payment obligations of Buyer under this Agreement are made by Buyer and Co-Buyer jointly and severally. Buyer and Co-Buyer shall hold title to the Horse as follows: {{TXN.CO_BUYER_TITLE_FORM}}. This Agreement is effective as to Co-Buyer upon Co-Buyer''s execution of it.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 07:03:12.586921-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4cc81896-a4f5-4d91-91c2-4bc17010eb37', 'HORSE_SALE_V2', 'PARTIES', 'PARTIES.CO_BUYER_TITLE_DETAIL', NULL, 'Title detail: {{TXN.CO_BUYER_TITLE_DETAIL}}', 'input', 40, false, NULL, '{"any": [{"equals": ["TIC_STATED"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}, {"equals": ["OTHER"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}]}', NULL, '2026-08-02 07:03:12.678354-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cc37eeab-3cef-4722-91a3-85e11f13cdd2', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_IND', NULL, '"Seller Parties" means Seller; Seller''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Seller''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.721499-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1560a3f4-19df-467b-b0e4-d5c833783f62', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_ENT', NULL, '"Seller Parties" means Seller; Seller''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Seller and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.764683-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('082ae613-2002-48b4-aab2-c144d583ca92', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.SELLER_PENDING', NULL, '[Pending — select whether Seller is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.807885-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('55bb470e-6bf3-4aa0-9be8-f62922f78d65', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_IND', NULL, '"Buyer Parties" means Buyer; Buyer''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Buyer''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 40, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.851524-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0ff17db3-71f5-4378-87cc-6707ff9253a5', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_ENT', NULL, '"Buyer Parties" means Buyer; Buyer''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Buyer and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 50, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.894434-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b4c57e57-66b7-4bf6-83e4-871d2aa51697', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BUYER_PENDING', NULL, '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 60, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:12.948312-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2a295f87-9643-4bea-ad97-d1494ec37cd1', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.CLOSING', NULL, '"Closing" means the moment at which both of the following have occurred: Seller''s receipt of the Purchase Price in full (or, where installment payment applies, receipt of all amounts due at transfer under the installment terms), and delivery of the Horse to Buyer as provided in this Agreement.', 'prose', 70, false, NULL, NULL, NULL, '2026-08-02 07:03:12.996257-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('959be128-1c8b-4759-94ee-4446331af514', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release approved by the other party to ride, handle, or care for the Horse prior to Closing, and each party shall indemnify, defend, and hold harmless the other party''s Seller Parties or Buyer Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'prose', 80, false, NULL, NULL, NULL, '2026-08-02 07:03:13.039483-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f544f15d-ee4c-4f82-a9cf-4cb4e41a0ea5', 'HORSE_SALE_V2', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Seller Party and each Buyer Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'prose', 90, false, NULL, NULL, NULL, '2026-08-02 07:03:13.086982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6ac27fb6-305f-4cfc-b5aa-1cbc8bc17a54', 'HORSE_SALE_V2', 'HORSE', 'HORSE.IDENTITY', 'Horse', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn Name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Height: {{HORSE.HEIGHT}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}
Current Location: {{HORSE.CURRENT_LOCATION}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:13.143093-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c10179d9-d2ee-451e-866e-aeb4f4cb9213', 'HORSE_SALE_V2', 'HORSE', 'HORSE.OWNERSHIP', 'Title and Ownership', 'Seller warrants that Seller lawfully owns the Horse, holds good and marketable title to the Horse, free and clear of all liens, security interests, leases, breeding contracts, co-ownership interests, and encumbrances except as expressly disclosed in this Agreement, and has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and sell the Horse.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 07:03:13.190637-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('df08d130-53f4-4872-be7d-1c99d4366ce7', 'HORSE_SALE_V2', 'HORSE', 'HORSE.ENCUMBRANCES', 'Disclosed Encumbrances and Interests', 'Seller discloses the following liens, leases, co-ownership interests, or other encumbrances affecting the Horse, each of which will be released or satisfied at or before Closing unless expressly stated otherwise: {{TXN.DISCLOSED_ENCUMBRANCES}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_ENCUMBRANCES"}', NULL, '2026-08-02 07:03:13.238079-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a68e8828-56d2-4f4d-b37b-77d696771bec', 'HORSE_SALE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_NONE', 'No Serious Injury History', 'Seller represents that, to Seller''s knowledge, no person has suffered serious injury proximately caused by the direct actions of the Horse, including biting, kicking, striking, bucking, rearing, bolting, crushing, or throwing a rider. This representation does not extend to any incident caused primarily by a third party or an external stimulus — such as another horse or rider being at fault, a loose dog, wildlife, a vehicle, or a similar external provocation — where the Horse''s reaction was within the range of normal equine behavior.', 'input', 60, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 07:03:13.372006-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6fb44add-768b-4071-9a6f-57eaebaa4b23', 'HORSE_SALE_V2', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Serious Injury History Disclosed', 'Seller discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}.', 'input', 70, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-02 07:03:13.415595-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('212eb8a8-a80f-4941-8c62-5f55aef54eaf', 'HORSE_SALE_V2', 'HORSE', 'HORSE.BREEDING_DECLINED', 'Breeding Warranty Not Elected', 'No warranty of breeding soundness, fertility, or reproductive capacity is given or implied. The parties considered including a breeding warranty and both elected not to include one.', 'prose', 100, false, NULL, '{"all": [{"any": [{"equals": ["Mare"], "field_key": "HORSE.SEX"}, {"equals": ["Stallion"], "field_key": "HORSE.SEX"}, {"equals": ["Colt"], "field_key": "HORSE.SEX"}, {"equals": ["Filly"], "field_key": "HORSE.SEX"}]}, {"equals": ["NOT_INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}]}', NULL, '2026-08-02 07:03:13.549137-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2926d83f-95a7-4334-aa68-10436db3363c', 'HORSE_SALE_V2', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations and warranties expressly stated in this Agreement, the Horse is sold AS IS, and SELLER MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE, and no warranty is made regarding the Horse''s future soundness, health, temperament, performance, suitability for any discipline or rider, or value. This disclaimer does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 110, false, NULL, NULL, NULL, '2026-08-02 07:03:13.592762-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('be00874e-a67a-4174-917a-eb0d23d84fd0', 'HORSE_SALE_V2', 'PURPOSE_SALE', 'PURPOSE_SALE.MAIN', 'Purpose of Agreement', 'Seller owns the horse described in this Agreement and desires to sell it, and Buyer desires to purchase it, on the terms and conditions of this Agreement.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:13.635517-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2de69002-b0c6-455b-9a5a-8c22c92d6a25', 'HORSE_SALE_V2', 'PURPOSE_SALE', 'PURPOSE_SALE.SALE', 'Agreement to Sell and Purchase', 'Subject to the terms and conditions of this Agreement, Seller agrees to sell, transfer, and convey the Horse to Buyer, and Buyer agrees to purchase the Horse from Seller, for the Purchase Price and on the terms stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 07:03:13.683212-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b77f51c4-5982-4648-a6f7-4fdee522f848', 'HORSE_SALE_V2', 'PRICE', 'PRICE.AMOUNT', 'Purchase Price', 'The purchase price for the Horse is {{TXN.PURCHASE_PRICE}} (the "Purchase Price").', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:13.726309-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('180e2806-976e-4483-975b-12bc14904253', 'HORSE_SALE_V2', 'PRICE', 'PRICE.DEPOSIT', 'Deposit', 'Buyer shall pay a deposit of {{TXN.DEPOSIT_AMOUNT}} (the "Deposit") upon execution of this Agreement. The Deposit is applied against the Purchase Price at Closing. If this Agreement terminates because a condition precedent stated in this Agreement fails (including an unsatisfactory pre-purchase examination where the sale is contingent on one, a financing contingency that fails where one is included, or a trial period return in accordance with this Agreement), the Deposit is refunded to Buyer in full within 5 business days. If Buyer fails to complete the purchase for any other reason, the parties agree that Seller''s actual damages would be impracticable or extremely difficult to determine, that the Deposit is a reasonable estimate of those damages, and that Seller may retain the Deposit as liquidated damages as Seller''s sole monetary remedy for that failure.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.DEPOSIT_ENABLED"}', NULL, '2026-08-02 07:03:13.773992-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d997336a-caf2-41eb-a8fd-e82e73a65a49', 'HORSE_SALE_V2', 'PRICE', 'PRICE.PAYMENT_METHOD', 'Payment Method', 'The Purchase Price shall be paid by the following method(s): {{TXN.PAYMENT_METHODS}}. Payment is not received until funds are actually and irrevocably credited to Seller.', 'input', 30, false, NULL, NULL, NULL, '2026-08-02 07:03:13.821356-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('88f313d7-724e-4636-896f-f97b3ccf7b7d', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FULL_PAYMENT', 'Payment in Full at Transfer', 'The Purchase Price, less any Deposit already paid, is due in full at or before delivery of the Horse. Seller is not obligated to deliver the Horse or any registration or transfer documents until the Purchase Price is received in full.', 'prose', 40, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 07:03:13.865698-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f7e32bcc-5259-4855-969d-c2fb418d7649', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_IND', 'Buyer''s Representations', 'Buyer represents and warrants that Buyer is at least 18 years of age and has full authority to enter into this Agreement; that Buyer has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of Buyer''s choosing, and to ask questions about the Horse; and that Buyer has the knowledge and experience to evaluate the Horse''s suitability for Buyer''s intended use. By signing this Agreement, Buyer acknowledges that Buyer has read this Agreement, fully understands its terms, and understands that Buyer is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 20, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:15.630369-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4025972f-0cf2-4c5f-b8ad-f86774959ae0', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_BEHAVIORAL_HISTORY_DISCLOSED_ACK', NULL, 'Buyer acknowledges the behavior disclosed above and proceeds with knowledge of it. Initialed: {{ACK.BEHAVIORAL_HISTORY}}', 'input', 133, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e78a7e1c-40b8-4e60-8eb6-a0413ed8510a', 'HORSE_SALE_V2', 'HORSE', 'HORSE.DISCLOSURES', 'Health and Condition Disclosures', 'Seller has disclosed to Buyer all known material information regarding the Horse''s medical conditions, injuries, lameness history, surgeries, allergies, current and past medications, behavioral issues, vices, and prior veterinary concerns, as follows: {{TXN.KNOWN_CONDITIONS}}. Seller warrants that these disclosures are true and complete to Seller''s knowledge as of the Effective Date, and shall promptly disclose any material change arising before Closing.', 'input', 50, false, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_DISCLOSURES"}', NULL, '2026-08-02 07:03:13.32491-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('48f1fabf-4daa-4fab-ac16-07aebb0d33e0', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_BEHAVIORAL_HISTORY_DISCLOSED_ACK_CB', NULL, 'Co-Buyer acknowledges the behavior disclosed above and proceeds with knowledge of it. Initialed: {{ACK.BEHAVIORAL_HISTORY_COBUYER}}', 'input', 134, false, NULL, '{"all": [{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}]}, {"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2700671c-ef8c-474c-814a-648a9dc4aee6', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FINANCING_DECLINED', 'Financing Contingency Not Elected', 'This sale is not contingent on Buyer obtaining financing. The parties considered including a financing contingency and both elected not to include one.', 'prose', 80, false, NULL, '{"equals": ["__RETIRED__"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-08-02 07:03:14.051477-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('650cb2ad-de25-4be4-9060-673c398c9fe0', 'HORSE_SALE_V2', 'PPE', 'PPE.CONDUCTED', 'Pre-Purchase Examination', 'Buyer may, at Buyer''s sole cost, have the Horse examined by a licensed veterinarian of Buyer''s choosing{{TXN.PPE_TIMING}} {{TXN.PPE_DEADLINE}}. Seller shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request.', 'input', 10, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["DATE"], "field_key": "TXN.PPE_TIMING"}]}', NULL, '2026-08-02 07:03:14.161612-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('13d65c8c-88d6-482e-adac-809a01905876', 'HORSE_SALE_V2', 'PRICE', 'PRICE.FINANCING', 'Financing Contingency', 'This sale is contingent on Buyer obtaining financing for not less than {{TXN.FINANCING_AMOUNT}} on terms reasonably acceptable to Buyer on or before {{TXN.FINANCING_DEADLINE}}. Buyer shall pursue financing diligently and in good faith. If Buyer gives Seller written notice on or before that date that financing could not be obtained, this Agreement terminates, the Deposit (if any) is refunded in full, and neither party has further obligation to the other except obligations that expressly survive. If no such notice is given by that date, this contingency is deemed waived.', 'input', 70, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-08-02 07:03:14.003916-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9f697a70-5ae0-40b5-949c-ece6f5ca744e', 'HORSE_SALE_V2', 'PRICE', 'PRICE.TAXES', 'Taxes', 'Any sales, use, or similar transfer tax arising from this sale is the responsibility of {{TXN.SALES_TAX_RESPONSIBLE}}. Each party is otherwise responsible for its own tax obligations arising from this transaction.', 'input', 90, false, NULL, NULL, NULL, '2026-08-02 07:03:14.105734-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('578afa96-4d58-4166-a76c-f6037bdda7c3', 'HORSE_SALE_V2', 'PPE', 'PPE.DRUG_TESTING', 'Drug and Substance Testing', 'At the pre-purchase examination or at delivery, whichever Buyer elects, Buyer may, at Buyer''s cost, have a licensed veterinarian draw blood or other samples from the Horse. Samples shall be split, sealed, and identified in the presence of both parties or their representatives, with one set retained by the veterinarian or a certified testing laboratory. If a certified laboratory confirms the presence of a prohibited, masking, or performance- or behavior-altering substance not disclosed in this Agreement and not administered under a disclosed current veterinary prescription, Buyer may rescind this Agreement by written notice within 5 business days of receiving the confirmed result, return the Horse in substantially the condition delivered, and receive a refund of all amounts paid including the Deposit, and Seller shall reimburse Buyer''s reasonable testing and return transport costs.', 'input', 50, false, NULL, '{"equals": ["__RETIRED__"], "field_key": "TXN.DRUG_TEST_ELECTION"}', NULL, '2026-08-02 07:03:14.357064-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('eabac1d8-f5b7-424c-8815-75faf25dcccf', 'HORSE_SALE_V2', 'PPE', 'PPE.WAIVED', 'Examination Waived', 'Buyer has been advised to obtain an independent pre-purchase veterinary examination of the Horse and knowingly and voluntarily waives it. Buyer accepts the Horse without such examination and assumes all risk associated with conditions an examination might have revealed. This waiver does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 30, false, NULL, '{"equals": ["BUYER_WAIVED"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-08-02 07:03:14.265609-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fa7c776a-42e7-45cd-a8f2-a66809008179', 'HORSE_BILL_OF_SALE', 'BOS_RELEASE', 'BOS_RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Each party understands that horseback riding and handling horses are inherently dangerous activities, and that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. In connection with any examination, handling, riding, transport, or delivery of the Horse under this Bill of Sale, each party, on behalf of itself and anyone claiming by, through, or under it — including its family and household members, and its owners, principals, employees, agents, and contractors — expressly and voluntarily assumes all inherent risks of equine activities, and acknowledges that the other party, together with that party''s family, household members, owners, principals, employees, agents, and contractors, owes no duty to protect it from those inherent risks.', 'prose', 5, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-10-20 04:30:32.506834-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7001c7e2-4d3c-4974-b960-629a4627e258', 'HORSE_SALE_V2', 'PPE', 'PPE.CONTINGENCY', 'Sale Contingent on Examination', 'This sale is contingent on a pre-purchase examination whose results are satisfactory to Buyer in Buyer''s reasonable discretion. If the Buyer gives Seller written notice that the examination results are not satisfactory, this Agreement terminates, the Deposit is refunded in full, and neither party has further obligation to the other except obligations that expressly survive.', 'input', 20, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["YES"], "field_key": "TXN.PPE_CONTINGENT"}, {"equals": ["YES"], "field_key": "TXN.DEPOSIT_ENABLED"}]}', NULL, '2026-08-02 07:03:14.222098-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5407c0ad-df08-4d17-a741-d081e87764b2', 'HORSE_BILL_OF_SALE', 'BOS_RELEASE', 'BOS_RELEASE.SELLER', 'Release by Seller', 'Seller, on behalf of Seller and anyone claiming by, through, or under Seller, completely releases, forever discharges, and agrees to hold harmless Buyer, together with Buyer''s family and household members and Buyer''s owners, principals, employees, agents, and contractors, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Seller''s riding or handling of the Horse or Seller''s presence at any facility where the Horse is kept in connection with this Bill of Sale, whether caused by the ordinary negligence of any of them or otherwise. This release does not apply to gross negligence, reckless conduct, intentional misconduct, or fraud.', 'prose', 25, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["INCLUDED"], "field_key": "TXN.BOS_RELEASE_ELECTION"}]}', NULL, '2026-10-20 04:30:32.506834-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('55fb041d-b93a-4c0a-9ec1-afd128cd0f15', 'HORSE_SALE_V2', 'PPE', 'PPE.DRUG_TESTING_DECLINED', 'Drug and Substance Testing Not Elected', 'Buyer was offered the opportunity to have samples drawn from the Horse and tested for prohibited, masking, or performance- or behavior-altering substances, and the parties elected not to include drug testing. Buyer assumes the risk that the Horse''s condition or behavior at examination, trial, or delivery may have been affected by a substance present at that time.', 'prose', 60, false, NULL, '{"equals": ["__RETIRED__"], "field_key": "TXN.DRUG_TEST_ELECTION"}', NULL, '2026-08-02 07:03:14.404111-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3ec1fa0d-3836-490b-9769-842e281d9993', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_DISCLOSURES.ENCUMBRANCES_NONE', NULL, 'Seller represents that the Horse is free of any liens, leases, co-ownership interests, or other encumbrances.', 'input', 65, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["NO"], "field_key": "TXN.HAS_ENCUMBRANCES"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('73309130-0026-4ab9-93f9-8475f050f4c9', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.TERMS', 'Delivery', 'The Horse shall be delivered to Buyer at {{TXN.DELIVERY_LOCATION}} on or about {{TXN.DELIVERY_DATE}}.', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:14.582067-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8a3f1535-e61c-4e0d-8b7a-7c14fc2343c0', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.NONE', NULL, 'No trial period applies to this sale.', 'prose', 20, false, NULL, '{"equals": ["NO"], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-08-02 07:03:14.495695-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2d304187-9ccc-4128-9c60-003f90c8ec95', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.PAPERS', 'Registration and Transfer Documents', 'At Closing (or, where installment payment applies, upon payment in full), Seller shall deliver to Buyer the Horse''s registration papers, passport, and any transfer forms required to record the change of ownership, executed by Seller where signature is required. Each party shall cooperate to complete breed registry, microchip registry, and passport transfers promptly, with recording fees paid by {{TXN.TRANSFER_FEES_RESPONSIBLE}}.', 'input', 30, false, NULL, NULL, NULL, '2026-08-02 07:03:14.677869-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ce40cb54-8f79-4f5a-825b-3c57a4aa6f35', 'HORSE_SALE_V2', 'RISK', 'RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Each party understands that horseback riding and handling horses are inherently dangerous activities, and that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. In connection with any examination, trial, handling, riding, transport, or delivery of the Horse under this Agreement, each party, on behalf of itself and anyone claiming by, through, or under it, expressly and voluntarily assumes all inherent risks of equine activities, and acknowledges that the other party''s Seller Parties or Buyer Parties, as applicable, owe no duty to protect it from those inherent risks.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:14.772214-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('87c89925-3cc8-43f1-a306-e1f20839f883', 'HORSE_SALE_V2', 'RISK', 'RISK.RELEASE_BUYER', 'Release by Buyer', 'Buyer, on behalf of Buyer and anyone claiming by, through, or under Buyer, completely releases, forever discharges, and agrees to hold harmless the Seller Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Buyer''s examination, trial, handling, riding, or transport of the Horse before Closing, whether caused by the ordinary negligence of any Seller Party or otherwise, and from any and all claims arising after Closing relating to the Horse''s condition, soundness, behavior, suitability, or value. This release does not apply to gross negligence, reckless conduct, intentional misconduct, fraud, or breach of the express representations and warranties stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 07:03:14.81968-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a13a8998-f99f-4e79-8254-df9955c5ea12', 'HORSE_SALE_V2', 'RISK', 'RISK.RELEASE_SELLER', 'Release by Seller', 'Seller, on behalf of Seller and anyone claiming by, through, or under Seller, completely releases, forever discharges, and agrees to hold harmless the Buyer Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Seller''s riding or handling of the Horse or Seller''s presence at any facility where the Horse is kept in connection with this Agreement, whether caused by the ordinary negligence of any Buyer Party or otherwise. This release does not apply to gross negligence, reckless conduct, intentional misconduct, or fraud.', 'prose', 30, false, NULL, NULL, NULL, '2026-08-02 07:03:14.862907-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1afd1604-549c-4ab3-8d3b-acf1f577eb2f', 'HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.PENDING', NULL, '[Pending — state whether a Horse Sale and Purchase Agreement accompanies this Bill of Sale. This placeholder is replaced by the applicable condition language and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-08-02 07:03:16.825255-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e38a9bf1-ca16-4805-a93d-d08acf004d1f', 'HORSE_SALE_V2', 'DELIVERY', 'DELIVERY.NO_SLAUGHTER', 'No-Slaughter Covenant', 'Buyer covenants that Buyer will not sell, transfer, consign, or deliver the Horse, directly or through intermediaries, for slaughter or for human consumption, whether within or outside California, and will not sell or transfer the Horse at auction without commercially reasonable steps to ensure the Horse is not being acquired for slaughter. The parties acknowledge that California Penal Code Section 598c makes it unlawful to possess, import, export, sell, or transfer a horse with the intent that it be killed for human consumption. This covenant survives Closing and binds Buyer''s successors in interest to the extent permitted by law.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 07:03:14.725264-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a7562d89-bf21-4d32-a6ee-a074653aaff6', 'HORSE_SALE_V2', 'RISK', 'RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement. This waiver does not apply to claims arising from fraud or from breach of the express representations and warranties stated in this Agreement.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 07:03:14.906136-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('91067cc5-e3c5-476a-a922-2fcff004b867', 'HORSE_SALE_V2', 'RISK', 'RISK.POST_CLOSING', 'Post-Closing Responsibility', 'From and after Closing, the Horse and its actions, behavior, care, and condition are the sole responsibility of Buyer, and Buyer shall indemnify, defend, and hold harmless the Seller Parties from and against any claim, damage, loss, liability, cost, or expense arising out of the Horse or its use, handling, care, or possession after Closing, except to the extent caused by the gross negligence, reckless conduct, intentional misconduct, or fraud of a Seller Party or by breach of the express representations and warranties stated in this Agreement.', 'prose', 50, false, NULL, NULL, NULL, '2026-08-02 07:03:14.953764-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10a12475-1071-4f7d-985e-c68f45b16019', 'HORSE_SALE_V2', 'RISK', 'RISK.PRE_CLOSING', 'Pre-Closing Responsibility', 'Before Closing, and except as allocated to Buyer during any trial period, Seller shall indemnify, defend, and hold harmless the Buyer Parties from and against any third-party claim arising out of the Horse''s ownership, care, or condition, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of a Buyer Party.', 'prose', 60, false, NULL, NULL, NULL, '2026-08-02 07:03:14.996756-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7f00aaa9-5c53-4019-bf05-866991d50c58', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.CURE', 'Default and Cure', 'A party in material breach of this Agreement has 10 days after written notice of the breach to cure it, except that no cure period applies to Buyer''s failure to complete the purchase after all conditions precedent are satisfied or waived, which is governed by the Deposit clause where a Deposit applies.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.044293-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('69c23dce-9b53-4705-b95b-e275cf078abf', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.SELLER', 'Seller Default', 'If Seller fails to complete the sale after all conditions precedent are satisfied or waived, Buyer is entitled to a full refund of the Deposit and all other amounts paid, and, because the Horse is unique, Buyer may alternatively seek specific performance of this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 07:03:15.087499-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bc73fc75-2e4a-4529-932f-8e7c300b8d31', 'HORSE_SALE_V2', 'DEFAULT', 'DEFAULT.INSTALLMENTS', 'Buyer Default Under Installments', 'If Seller retakes possession of the Horse following Buyer''s uncured installment default, Seller shall, within 60 days, elect either to retain the Horse and refund amounts paid in excess of the greater of the Deposit and 20 percent of the Purchase Price, or to resell the Horse in a commercially reasonable manner and account to Buyer for any amount received in excess of the unpaid balance plus Seller''s reasonable costs of retaking, keeping, and reselling the Horse.', 'prose', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-08-02 07:03:15.135051-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('27e259b4-0a05-404d-8423-28c924757e82', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.178193-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2bf8bae8-686d-45ee-8a80-b824db05c1bf', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.SELLER_ADDRESS', 'Seller', 'Name: {{SELLER.FULL_NAME}}
Address: {{SELLER.ADDRESS}}
Phone: {{SELLER.PHONE}}
Email: {{SELLER.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-08-02 07:03:15.225683-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8041210a-fe06-4cf3-94eb-b502827163c5', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.BUYER_ADDRESS', 'Buyer', 'Name: {{BUYER.FULL_NAME}}
Address: {{BUYER.ADDRESS}}
Phone: {{BUYER.PHONE}}
Email: {{BUYER.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-08-02 07:03:15.269649-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7585f0ec-8987-44a0-9990-e42ed52d4b2e', 'HORSE_SALE_V2', 'NOTICE', 'NOTICE.CHANGES', 'Changes in Contact Information', 'Each party shall promptly notify the other party in writing of any change in the party''s address or contact information.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-02 07:03:15.313193-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('059e6cdb-2126-4833-a6a6-211825a63341', 'HORSE_SALE_V2', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment', 'Neither party shall assign this Agreement or any of its rights or obligations under it without the other party''s prior written consent.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.355991-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e8e5682e-9c7e-4302-bb8b-3feade660fac', 'HORSE_SALE_V2', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions, advertisements, and understandings, and Buyer acknowledges that Buyer is not relying on any statement or representation regarding the Horse that is not stated in this Agreement. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.403618-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b1286f8a-ee4f-40a6-993a-889c05751a83', 'HORSE_SALE_V2', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Dispute Resolution', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.446805-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1e7282d1-e4e4-4ac3-82d3-813776f7651e', 'HORSE_SALE_V2', 'ATTORNEYS_FEES', 'ATTORNEYS_FEES.PREVAILING', 'Attorneys'' Fees', 'Each party shall cover their own attorney''s fees and costs.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.494336-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('49d792a9-ce23-44a4-8d0e-67e3b616b660', 'HORSE_SALE_V2', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.539609-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8a13190a-2b91-4eb3-8aed-328884b53111', 'HORSE_SALE_V2', 'REPS', 'REPS.SELLER', 'Seller''s Representations', 'Seller represents and warrants that Seller has full authority to enter into this Agreement, that the warranties of title and the disclosures stated in this Agreement are true and complete to Seller''s knowledge, and that Seller will promptly disclose any material change in the Horse''s health, soundness, or behavior arising before Closing.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.582913-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('41357dbf-f6a8-439a-9b3a-2dd3067a8e2a', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_ENT', 'Buyer''s Representations', 'Buyer represents and warrants that it is duly organized and in good standing, that the person signing on its behalf is authorized to bind it, that it has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of its choosing, and to ask questions about the Horse, and that it has the knowledge and experience, directly or through its personnel, to evaluate the Horse''s suitability for its intended use. By signing this Agreement, Buyer acknowledges that it has read this Agreement, fully understands its terms, and understands that it is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 30, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:15.674697-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0caea3e1-40a8-47c7-b757-173d85ac3131', 'HORSE_SALE_V2', 'REPS', 'REPS.BUYER_PENDING', 'Buyer''s Representations', '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:15.721806-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4a007f33-6528-4e76-a260-cab319e4ab29', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

BUYER
Signature: {{SIG.BUYER.NAME}}
Printed Name: {{BUYER.PRINTED_NAME}}
Date: {{SIG.BUYER.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:15.765016-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('aa20e851-43bc-41cd-8449-9e21e9f3afec', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.BUYER_CAPACITY', NULL, 'By: {{BUYER.ENTITY_SIGNER_NAME}}
Title: {{BUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{BUYER.FULL_NAME}}', 'input', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:15.808204-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('814f61b0-9517-49d1-bba1-7439079caa88', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.COBUYER_BLOCK', NULL, 'CO-BUYER
Signature: {{SIG.COBUYER.NAME}}
Printed Name: {{COBUYER.PRINTED_NAME}}
Date: {{SIG.COBUYER.DATE}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 07:03:15.851672-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('db725ec3-f106-4d7c-bb6d-9c6cf7fda2e0', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.COBUYER_CAPACITY', NULL, 'By: {{COBUYER.ENTITY_SIGNER_NAME}}
Title: {{COBUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{COBUYER.FULL_NAME}}', 'input', 40, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}, {"equals": ["ENTITY"], "field_key": "COBUYER.PARTY_TYPE"}]}', NULL, '2026-08-02 07:03:15.895305-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5b9b7352-7874-4ce5-aef7-5c51bd803110', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.SELLER_BLOCK', NULL, 'SELLER (OWNER)
Signature: {{SIG.SELLER.NAME}}
Printed Name: {{SELLER.PRINTED_NAME}}
Date: {{SIG.SELLER.DATE}}', 'prose', 50, false, NULL, NULL, NULL, '2026-08-02 07:03:15.942492-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a9d5246a-24bc-4616-a663-16eca12e8dd0', 'HORSE_SALE_V2', 'SIGNATURES', 'SIGNATURES.SELLER_CAPACITY', NULL, 'By: {{SELLER.ENTITY_SIGNER_NAME}}
Title: {{SELLER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{SELLER.FULL_NAME}}', 'input', 60, false, NULL, '{"equals": ["ENTITY"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-08-02 07:03:15.981415-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10b4a1e7-2541-4a3d-92f1-893840545ddc', 'HORSE_BILL_OF_SALE', 'BOS_TITLE', 'BOS_TITLE.INTRO', NULL, 'EQUINE BILL OF SALE. This Bill of Sale is made effective as of {{DOC.EFFECTIVE_DATE}} by {{SELLER.FULL_NAME}} of {{SELLER.ADDRESS}} ("Seller") in favor of {{BUYER.FULL_NAME}} of {{BUYER.ADDRESS}} ("Buyer").', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:16.383828-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('31aa9bbe-2ba5-41c8-9cc1-7d13a1edc5ab', 'HORSE_BILL_OF_SALE', 'BOS_TITLE', 'BOS_TITLE.CO_BUYER', NULL, '{{COBUYER.FULL_NAME}} of {{COBUYER.ADDRESS}} ("Co-Buyer") takes title jointly with Buyer as follows: {{TXN.CO_BUYER_TITLE_FORM}}. Every reference to Buyer in this Bill of Sale includes Co-Buyer.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-08-02 07:03:16.427058-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3050d2ab-e46d-4b2b-93d1-ce906aec9fc6', 'HORSE_BILL_OF_SALE', 'BOS_HORSE', 'BOS_HORSE.IDENTITY', NULL, 'This Bill of Sale conveys the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn Name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Height: {{HORSE.HEIGHT}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:16.470163-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('880a97d1-1351-4297-b4fb-b6ab846bf231', 'HORSE_BILL_OF_SALE', 'BOS_CONSIDERATION', 'BOS_CONSIDERATION.PRICE', NULL, 'The purchase price for the Horse is {{TXN.PURCHASE_PRICE}} (the "Purchase Price"), the receipt and sufficiency of which are acknowledged to the extent stated below. The parties state this Purchase Price for all purposes, including California Business and Professions Code Section 19525 where applicable.', 'input', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:16.517767-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('08463724-5b71-4c10-8c66-14d91f5b2ee5', 'HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.PAID', NULL, 'Seller acknowledges receipt of the Purchase Price in full and hereby sells, transfers, conveys, and delivers to Buyer all of Seller''s right, title, and interest in and to the Horse, together with the Horse''s registration papers and passport where applicable, TO HAVE AND TO HOLD the same unto Buyer and Buyer''s successors and assigns forever.', 'prose', 10, false, NULL, '{"equals": ["PAID_IN_FULL"], "field_key": "TXN.BOS_PAYMENT_STATUS"}', NULL, '2026-08-02 07:03:16.560907-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('60593f27-30c5-40ee-8980-03fc53dd9cb1', 'HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.INSTALLMENT', NULL, 'The Purchase Price is payable in installments under the parties'' Horse Sale and Purchase Agreement. Seller hereby transfers possession of the Horse to Buyer, and title to the Horse passes to Buyer only upon Seller''s receipt of the Purchase Price in full as provided in that Agreement, until which time Seller retains title and a purchase-money security interest in the Horse as stated in that Agreement. Upon payment in full, this Bill of Sale operates without further action to convey all of Seller''s right, title, and interest in and to the Horse to Buyer.', 'prose', 20, false, NULL, '{"equals": ["INSTALLMENTS"], "field_key": "TXN.BOS_PAYMENT_STATUS"}', NULL, '2026-08-02 07:03:16.604515-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10c6214c-1a16-4c33-aaf1-d7a936678be3', 'HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.PENDING', NULL, '[Pending — select whether the Purchase Price is paid in full or payable in installments. This placeholder is replaced by the applicable conveyance language and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "TXN.BOS_PAYMENT_STATUS"}', NULL, '2026-08-02 07:03:16.647247-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8cf5a25a-f930-4b76-979a-b748d7d5bc19', 'HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.TITLE', NULL, 'Seller warrants that Seller is the lawful owner of the Horse, has full right and authority to sell and convey the Horse, and that the Horse is free and clear of all liens, security interests, and encumbrances except as disclosed in writing to Buyer, and Seller will defend title to the Horse against the lawful claims of all persons.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-02 07:03:16.686991-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f0b310f4-6972-4ff3-afab-23e855c31566', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_INJURIES_TO_HORSE_GATE', NULL, '', 'input', 140, false, NULL, '{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}', NULL, '2026-10-20 04:30:32.506834-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c59f3280-4fad-4702-9c33-9ef100e8bede', 'HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.DISCLOSURE', NULL, 'The following person or entity acted as agent or intermediary in this transaction and receives compensation in connection with it: {{TXN.AGENT_NAME}}, acting on behalf of {{TXN.AGENT_ACTING_FOR}}, receiving compensation of {{TXN.AGENT_COMPENSATION}} paid by {{TXN.AGENT_PAID_BY}}. Where the agent acted on behalf of both Seller and Buyer, each party acknowledges that it received prior written disclosure of, and consented in writing to, the dual agency. The parties acknowledge that under California Business and Professions Code Section 19525, where it applies, an agent receiving compensation in excess of five hundred dollars in connection with the sale of a racing or showing equine must be authorized by a written agreement signed by the party the agent represents, and this Bill of Sale is delivered in satisfaction of the written bill of sale required by that statute.', 'input', 10, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.AGENT_ELECTION"}', NULL, '2026-08-02 07:03:16.868458-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d98c27de-1b20-479c-a6c7-5c146445ba1e', 'HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.NONE', NULL, 'No agent or intermediary receives compensation in connection with this transaction.', 'prose', 20, false, NULL, '{"equals": ["NOT_INCLUDED"], "field_key": "TXN.AGENT_ELECTION"}', NULL, '2026-08-02 07:03:16.924509-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6db3953f-71f9-4b4f-8c17-5b19d3937934', 'HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.PENDING', NULL, '[Pending — state whether a compensated agent or intermediary participated in this transaction. This placeholder is replaced by the applicable statement and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "TXN.AGENT_ELECTION"}', NULL, '2026-08-02 07:03:16.967755-07', false, NULL);
