INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f4d06927-ce2b-4b52-8457-c57aac39a024', 'HORSE_LEASE_V3', 'PURPOSE', 'PURPOSE.SUBLEASE_PERMITTED', NULL, 'Lessee may sublease the Horse without Lessor''s further consent.', 'input', 23, false, NULL, '{"all": [{"equals": ["FULL"], "field_key": "TXN.LEASE_TYPE"}, {"equals": ["PERMITTED"], "field_key": "TXN.SUBLEASE"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
