INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('054c2894-605e-481d-9d52-19a42470f96f', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PERMITTED_ACTIVITIES_PENDING', NULL, '[Pending — select the permitted activities. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 99, false, NULL, '{"equals": [""], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('30bb32ca-25f0-4b36-ac99-b164d93db28f', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_REQ', NULL, 'Lessor requires Lessee to maintain care, custody and control insurance for the duration of this Agreement. Care, custody and control insurance applies only where injury to, or death of the Horse is caused by Lessee''s negligence. It shall not be claimed against merely because other coverage is unavailable, is not in force, or has denied a claim. Where a loss is caused by Lessee''s negligence, care, custody and control insurance is the policy to be claimed against for that loss.', 'input', 173, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["YES"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('92d15887-d87e-44d5-864c-c935dc80f024', 'HORSE_LEASE_V3', 'CARE', 'RIDER_AIDS_PROHIBITED_PENDING', NULL, '[Pending — select which rider aids are prohibited. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 89, false, NULL, '{"equals": [""], "field_key": "TXN.RIDER_AIDS_PROHIBITED"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
