INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2b6716a0-0791-485b-a9de-d87e10e67227', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.TERMS_CURRENT', 'Trial Period', 'Buyer may keep and ride the Horse on trial from {{TXN.TRIAL_START}} to {{TXN.TRIAL_END}} at the Horse''s current location.
Current Location: {{TXN.TRIAL_LOCATION}}
Board and care costs borne by: {{TXN.TRIAL_BOARD_COST}}
Buyer shall use the Horse only for ordinary riding and evaluation consistent with the Horse''s training and shall not compete, breed, transport offsite (other than for veterinary care, which is always permitted), or permit third parties to ride the Horse without Seller''s written consent, and Buyer assumes all risk of injury to persons arising from the Horse during the trial period as provided in the Risk, Release, and Indemnification section of this Agreement. Seller bears the risk of loss of the Horse while Seller holds title. If the Horse dies or is injured before Closing, Buyer is entitled to the return of all amounts paid to Seller and may decline to complete the purchase by not executing the Bill of Sale, in which case Seller returns to Buyer all amounts paid and Buyer returns possession of the Horse to Seller. Nothing in this section limits Seller''s remedies for damage to the Horse caused by Buyer''s gross negligence, reckless conduct, or intentional misconduct. Unless written notice is given and approved by Seller, Buyer must return the Horse in substantially the condition received on or before {{TXN.TRIAL_END}} or execute this Agreement.', 'input', 10, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"equals": ["YES"], "field_key": "TXN.TRIAL_AT_CURRENT"}]}', NULL, '2026-10-12 10:34:06.972797-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8ee7ca79-4e9f-4903-8129-89743b5bff38', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.TERMS', 'Trial Period', 'Buyer may keep and ride the Horse on trial from {{TXN.TRIAL_START}} to {{TXN.TRIAL_END}} at {{TXN.TRIAL_LOCATION}}.
Board and care costs borne by: {{TXN.TRIAL_BOARD_COST}}
The Horse shall be transported to the trial location from the Horse''s current location. Transport is arranged by {{TXN.TRIAL_TRANSPORT_RESPONSIBLE}} and paid for by {{TXN.TRIAL_TRANSPORT_COST_RESPONSIBLE}}.
Buyer shall use the Horse only for ordinary riding and evaluation consistent with the Horse''s training and shall not compete, breed, transport offsite (other than for veterinary care, which is always permitted), or permit third parties to ride the Horse without Seller''s written consent, and Buyer assumes all risk of injury to persons arising from the Horse during the trial period as provided in the Risk, Release, and Indemnification section of this Agreement. Seller bears the risk of loss of the Horse while Seller holds title. If the Horse dies or is injured before Closing, Buyer is entitled to the return of all amounts paid to Seller and may decline to complete the purchase by not executing the Bill of Sale, in which case Seller returns to Buyer all amounts paid and Buyer returns possession of the Horse to Seller. Nothing in this section limits Seller''s remedies for damage to the Horse caused by Buyer''s gross negligence, reckless conduct, or intentional misconduct. Unless written notice is given and approved by Seller, Buyer must return the Horse in substantially the condition received on or before {{TXN.TRIAL_END}} or execute this Agreement.', 'input', 10, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"any": [{"equals": ["NO"], "field_key": "TXN.TRIAL_AT_CURRENT"}, {"equals": [""], "field_key": "TXN.TRIAL_AT_CURRENT"}]}]}', NULL, '2026-08-02 07:03:14.451713-07', false, NULL);
