INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10693c02-1e5a-4d65-80ed-eda2eac9169e', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_ALLOC_LESSOR', NULL, 'Lessor accepts full risk and responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement, except as otherwise expressly allocated in this Agreement.', 'prose', 157, false, NULL, '{"all": [{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}, {"equals": ["LESSOR_ALL"], "field_key": "TXN.GL_NO_REQ_ALLOCATION"}]}', NULL, '2026-08-09 16:42:33.954619-07', false, NULL);
