INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2826445e-b45e-4bc7-9cf9-2667704d2939', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_NOT_REQUIRED', NULL, 'Lessor does not require Lessee to carry general liability insurance under this Agreement.', 'prose', 155, false, NULL, '{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}', NULL, '2026-08-09 16:42:33.954619-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b9e23004-95be-4b1c-9edc-b84d25975541', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.OWNERSHIP_LIMITS', NULL, 'Lessor discloses the following ownership related leasing restrictions: {{TXN.OWNERSHIP_LIMITATIONS}}.', 'input', 115, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_OWNERSHIP_LIMITS"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9077e0d6-ec66-460f-82ec-0af9d886d39f', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_NONE', NULL, 'Lessor represents that, to Lessor''s knowledge, no person has been seriously injured by the direct actions of the Horse. This representation does not extend to any incident caused primarily by a third party or an external stimulus, such as another horse or rider being at fault, a loose dog, wildlife, or a vehicle, where the Horse''s reaction was within the range of normal equine behavior.', 'input', 121, false, NULL, '{"equals": ["NO"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-20 04:29:19.970099-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7d6b26c5-2ae4-490d-8182-c40c5c35437d', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_UNKNOWN', NULL, 'Lessor has no knowledge of whether any person has been seriously injured by the direct actions of the Horse.', 'input', 123, false, NULL, '{"equals": ["UNKNOWN"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fe470077-30a9-45cc-bafb-baff121c13ca', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_DISCLOSED_ACK', NULL, 'Lessee acknowledges the injuries to a person disclosed above and proceeds with knowledge of it. Initialed: {{ACK.INJURIES_TO_HUMANS}}', 'input', 124, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
