INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2446aa69-344a-4f44-b0fd-b898fb4e916c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSOR_COVERAGE_HAS', NULL, 'Lessor has and will maintain general liability insurance covering the Horse and the activities contemplated by this Agreement for the duration of this Agreement, and shall provide proof of coverage to Lessee upon request.', 'prose', 151, false, NULL, '{"equals": ["HAS"], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-08-09 16:53:40.234635-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d853b4b4-0613-4ffe-8509-1ed3f85cec50', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations expressly stated in this Agreement, LESSOR MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.', 'prose', 200, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('934e0198-0ac5-454d-b436-058c30c9d06b', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.VET_CHECK', 'Pre-Lease Veterinary Examination', '[Pending — select the pre-lease veterinary examination arrangement. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 210, false, NULL, '{"equals": [""], "field_key": "TXN.VET_CHECK_CHOICE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a4131ae2-9571-45f4-890e-89832e023635', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.VET_CHECK_LESSEE_OWN', NULL, 'Lessee has requested a pre-lease veterinary examination of the Horse, to be conducted at Lessee''s sole cost by a licensed veterinarian of Lessee''s choosing{{TXN.VET_TIMING}}. Lessor shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request. If the findings of the examination are not acceptable to Lessee in Lessee''s reasonable discretion, Lessee may terminate this Agreement by written notice to Lessor, and neither party has any further obligation to the other{{TXN.VET_FEE_PHRASE}}.', 'input', 211, false, NULL, '{"equals": ["LESSEE_OWN"], "field_key": "TXN.VET_CHECK_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('970124a2-edb7-448c-9883-9050d4948608', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.VET_CHECK_LESSEE_AT_LESSOR', NULL, 'Lessee has requested a pre-lease veterinary examination of the Horse, to be conducted at Lessor''s cost by a licensed veterinarian of Lessee''s choosing{{TXN.VET_TIMING}}. Lessor shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request. If the findings of the examination are not acceptable to Lessee in Lessee''s reasonable discretion, Lessee may terminate this Agreement by written notice to Lessor, and neither party has any further obligation to the other{{TXN.VET_FEE_PHRASE}}.', 'input', 212, false, NULL, '{"equals": ["LESSEE_AT_LESSOR"], "field_key": "TXN.VET_CHECK_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a495e50c-7d79-4634-8f95-e616bf8a7dc7', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSOR_COVERAGE_WILL', NULL, 'Lessor will obtain and will maintain general liability insurance covering the Horse and the activities contemplated by this Agreement, effective no later than the commencement of this Agreement and for its duration, and shall provide proof of coverage to Lessee upon request.', 'prose', 152, false, NULL, '{"equals": ["WILL_OBTAIN"], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-08-09 16:53:40.234635-07', false, NULL);
