INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('751130ff-00bc-40ef-8b21-469bfc46d30f', 'HORSE_LEASE_V3', 'CARE', 'SCHEDULE.CARE_DUTY', 'Lessee''s Responsibility for Care and Exercise', 'Lessee''s use of the Horse is a responsibility as well as a right: regular, consistent exercise and attention are important to the Horse''s health and wellbeing. Lessee is required to maintain regular use and exercise for the Horse on their allowed days, unless Lessee has discussed with and received mutual agreement from the Lessor in writing that one of those days will be used as a rest day for the Horse. If Lessee regularly fails to use and care for the Horse, Lessor may terminate this Agreement.', 'prose', 1, false, NULL, '{"equals": ["YES"], "field_key": "TXN.EXERCISE_INCLUDE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0af8e0f9-4cb6-41dd-b9b2-f35a4e538af8', 'HORSE_LEASE_V3', 'CARE', 'SCHEDULE.TRAINER_CARE', '3rd Party Exercise', 'Lessee is permitted to engage an approved 3rd party to exercise the Horse. All 3rd party exercise shall be conducted only by a French Heritage Equestrian Approved Trainer. Other 3rd parties must be approved in writing by the Lessor.
Party responsible for arranging: {{TXN.TRAINER_EXERCISE_ARRANGE}}
Party responsible for costs: {{TXN.TRAINER_EXERCISE_COST}}
Lessee''s share of the cost: {{TXN.TRAINER_EXERCISE_SPLIT_PCT}}', 'input', 2, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRAINER_CARE_INCLUDE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('58e11ddc-f93e-4829-a354-277995226071', 'HORSE_LEASE_V3', 'CARE', 'CARE.INTRO', NULL, 'Horse care and expenses shall be managed and paid for by the responsible party as listed below.', 'prose', 5, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
