INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('087245e9-0f78-4770-8b32-5676149b7056', 'HORSE_SALE_V2', 'TRIAL', 'TRIAL.INSURANCE', NULL, 'Title to the Horse remains with Seller during the trial period, and Seller bears the risk of loss of the Horse''s value. Seller may, in Seller''s sole discretion, maintain a mortality or other insurance policy on the Horse in an amount not less than the Purchase Price. Neither party is obligated under this Agreement to obtain or maintain such insurance. Any obligation of Seller to insure the Horse must be set out in a separate written agreement between the parties, and this Agreement does not create one.', 'input', 15, false, NULL, NULL, NULL, '2026-09-17 22:33:12.060687-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('27ee4366-7e90-4d25-b730-312cd792fe3b', 'HORSE_LEASE_V3', 'CARE', 'CARE.RIDER_AIDS_NONE', NULL, 'Lessor does not prohibit the use of rider aids.', 'prose', 91, false, NULL, '{"equals": ["NO"], "field_key": "TXN.RIDER_AIDS_PROHIBITED"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b7ef1876-400d-4918-ae9a-cc8e3fd8ac68', 'HORSE_LEASE_V3', 'CARE', 'CARE.RIDER_AIDS_LIST', NULL, 'Lessor prohibits the use of the following rider aids: {{TXN.RIDER_AIDS}}', 'input', 92, false, NULL, '{"equals": ["YES"], "field_key": "TXN.RIDER_AIDS_PROHIBITED"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d97b2f1a-9c13-4182-bbff-4c5e4efcf4ce', 'HORSE_LEASE_V3', 'CARE', 'CARE.RIDER_AIDS_OTHER', NULL, 'Other prohibited rider aid:
{{TXN.RIDER_AIDS_OTHER}}', 'input', 93, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.RIDER_AIDS_PROHIBITED"}, {"contains": ["OTHER"], "field_key": "TXN.RIDER_AIDS"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6cf7d1d4-20e5-4dca-a16b-21810ec52d26', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSOR_PENDING', NULL, '[Pending — select whether Lessor is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 10, false, NULL, '{"equals": [""], "field_key": "LESSOR.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('58a84e15-f75b-4482-8e21-5642297e2a7e', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSOR_IND', NULL, '"Lessor Parties" means Lessor; Lessor''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessor''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 20, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9efd3177-b99c-4f2b-91ee-f35e7350cf21', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSOR_ENT', NULL, '"Lessor Parties" means Lessor; Lessor''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessor and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 30, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8ca8080d-b807-4f07-b2c3-a13c3d6ab215', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSEE_PENDING', NULL, '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 40, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f7657f00-4d02-4bd0-aadc-8faec0194525', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSEE_IND', NULL, '"Lessee Parties" means Lessee; Lessee''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessee''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 50, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('885a8c6a-64b5-441c-b39b-661a4f5b77d1', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.LESSEE_ENT', NULL, '"Lessee Parties" means Lessee; Lessee''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessee and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 60, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('68ac964b-7f52-45e9-8ada-14054033f24c', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release satisfying the Releases Required for Authorized Riders provision of this Agreement to ride, handle, or care for the Horse, and each party shall indemnify, defend, and hold harmless the other party''s Lessor Parties or Lessee Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 70, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('58bf54aa-1bec-43b2-a2d8-ce8aa65699e9', 'HORSE_LEASE_V3', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Lessor Party and each Lessee Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'input', 80, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('50ca5a81-77b7-4d6a-8629-c9a66f8b2cc4', 'HORSE_LEASE_V3', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions and understandings. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('13f2c2a6-ecfe-4e0e-8450-fd15697817d7', 'HORSE_LEASE_V3', 'EVALUATION', 'EVALUATION.CHOICE', NULL, '', 'choice', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2db58ec1-2d04-4b1c-81a0-cc8d962f8756', 'HORSE_LEASE_V3', 'EVALUATION', 'EVALUATION.DATES_INCLUDED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_INCLUDED_LENGTH}} {{TXN.EVAL_INCLUDED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is included at no separate charge, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 20, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["INCLUDED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_INCLUDED_LENGTH"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7c55ee6d-3847-4217-a049-ba99afb46f64', 'HORSE_LEASE_V3', 'EVALUATION', 'EVALUATION.DATES_FIXED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_FIXED_LENGTH}} {{TXN.EVAL_FIXED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is {{TXN.EVAL_FIXED_FEE}}, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 21, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["FIXED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_FIXED_LENGTH"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('02fbffaa-1bed-447a-9124-a4a68e60ffb3', 'HORSE_LEASE_V3', 'EVALUATION', 'EVALUATION.REFUSED', NULL, 'No evaluation period applies to this Agreement. The Lessor has declined to provide an evaluation period, and the Lease begins on the Effective Date without one.', 'input', 40, false, NULL, '{"any": [{"equals": ["REFUSED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('89d0bde8-4f70-4ce2-b954-f5bfa69762d5', 'HORSE_LEASE_V3', 'EVALUATION', 'EVALUATION.WAIVED', NULL, 'No evaluation period applies to this Agreement. The Lessee has waived any evaluation period, and the Lease begins on the Effective Date without one.', 'input', 41, false, NULL, '{"any": [{"equals": ["WAIVED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('875e478f-a74b-468e-b242-98af4126266b', 'HORSE_LEASE_V3', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Venue', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a922daa9-44b8-499a-928d-251ad197441f', 'HORSE_LEASE_STANDARD', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN', 'Payments by the Lessee', 'The Lessee may pay amounts owed under this Agreement by the following method(s): {{TXN.PAYMENT_METHODS}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('561d521a-24ab-4b3d-9e05-6f5036982ca5', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.OWNERSHIP', 'Ownership of the Horse', 'Lessor warrants that Lessor lawfully owns the Horse — whether owned outright, financed without any restriction that prohibits or limits leasing the Horse, or owned jointly with one or more other owners — and that Lessor has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and lease the Horse.', 'input', 110, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6222411a-1892-4c08-97f7-cc12bea2ffd3', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.INSURANCE', 'Insurance Requirements', 'The parties agree to the insurance elections set forth below. Each policy elected or required below shall be maintained in effect for the duration of this Agreement.', 'prose', 100, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('555ce6b1-f909-4c45-9387-adb6548b17ab', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GENERAL_LIABILITY', 'General Liability Insurance', '', 'input', 150, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c8d0926c-b3b9-46f1-a0db-27a0c9142f4b', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSOR_COVERAGE_HAS', NULL, 'Lessor has and will maintain general liability insurance covering the Horse and the activities contemplated by this Agreement for the duration of this Agreement, and shall provide proof of coverage to Lessee upon request.', 'prose', 151, false, NULL, '{"equals": ["HAS"], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fa31c3dd-f9c4-4fc7-9bd9-6a6cba597f77', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSOR_COVERAGE_WILL', NULL, 'Lessor will obtain and will maintain general liability insurance covering the Horse and the activities contemplated by this Agreement, effective no later than the commencement of this Agreement and for its duration, and shall provide proof of coverage to Lessee upon request.', 'prose', 152, false, NULL, '{"equals": ["WILL_OBTAIN"], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c3708b2c-4368-41f8-8534-c39611d7349f', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSOR_COVERAGE_NONE', NULL, 'Lessor does not have general liability insurance for the Horse or the activities contemplated by this Agreement.', 'prose', 153, false, NULL, '{"equals": ["NONE"], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('644fa4dc-2bb4-477a-afa0-7b551ecf9877', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_REQUIRED', NULL, 'Lessor requires Lessee to maintain, at Lessee''s sole cost, general liability insurance covering the Horse and the activities contemplated by this Agreement for the duration of this Agreement, and to provide proof of coverage to Lessor upon request. Failure to maintain coverage constitutes a material breach subject to the Termination for Cause provisions of this Agreement.', 'prose', 154, false, NULL, '{"equals": ["GL_ONLY"], "field_key": "TXN.GL_LESSOR_REQUIRES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2523a65b-2c95-45c7-b95c-c7a2840d33bc', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_NOT_REQUIRED', NULL, 'Lessor does not require Lessee to carry general liability insurance under this Agreement.', 'prose', 155, false, NULL, '{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a399d12a-1f45-4dbf-aa7f-3cdaefe81a0c', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_ALLOC_PICK', NULL, '', 'input', 156, false, NULL, '{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8dc2096b-3e00-4e64-8e8c-43ba6a6eec1f', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_ALLOC_LESSOR', NULL, 'Lessor accepts full risk and responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement, except as otherwise expressly allocated in this Agreement.', 'prose', 157, false, NULL, '{"all": [{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}, {"equals": ["LESSOR_ALL"], "field_key": "TXN.GL_NO_REQ_ALLOCATION"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bc33b926-8221-4c74-a5a1-74e5c5d79379', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_ALLOC_FAULT', NULL, 'Lessor accepts risk and responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement, except for any such claim arising from an event for which Lessee is at fault, and except as otherwise expressly allocated in this Agreement. Each party is responsible for the costs of any claim arising from an event for which that party is at fault.', 'prose', 158, false, NULL, '{"all": [{"equals": ["NEITHER"], "field_key": "TXN.GL_LESSOR_REQUIRES"}, {"equals": ["LESSEE_AT_FAULT"], "field_key": "TXN.GL_NO_REQ_ALLOCATION"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4acb4ddb-7227-4168-a2f8-f95d37ff6b22', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSEE_PICK', NULL, '', 'input', 159, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('564c4a6c-fb19-4687-bce9-466da5f9d471', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSEE_AGREES', NULL, 'Lessee agrees to maintain general liability insurance covering the Horse and the activities contemplated by this Agreement for the duration of this Agreement, and shall provide to Lessor proof of coverage upon request. As between the parties, and except as otherwise expressly allocated in this Agreement, Lessee bears responsibility for liability claims for bodily injury or property damage to third parties arising from the Horse or the activities contemplated by this Agreement to the extent not covered by an in-force policy.', 'prose', 160, false, NULL, '{"equals": ["AGREES"], "field_key": "TXN.GL_LESSEE_STATUS"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('902ac72d-7353-4e34-ad53-8b6780981350', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_LESSEE_PERSONAL', NULL, 'Lessee does not carry general liability insurance under this Agreement. Lessee accepts personal financial responsibility for the costs of any liability claim for bodily injury or property damage to third parties arising from an event for which Lessee is at fault, and acknowledges that no policy stands behind that responsibility.', 'prose', 162, false, NULL, '{"equals": ["ACCEPTS_PERSONALLY"], "field_key": "TXN.GL_LESSEE_STATUS"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4e1e8a9c-1035-4173-bd3a-c54e29aab03b', 'HORSE_LEASE_V3', 'HORSE', 'LOCATION.MAIN', 'Location', 'Location of the Horse:
{{HORSE.CURRENT_LOCATION}}', 'input', 201, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2be5564c-5849-4561-95ed-0eab5cc5b632', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_INJURIES_TO_HORSE_DISCLOSED_ACK', NULL, 'Buyer acknowledges the injuries to the horse disclosed above and proceeds with knowledge of it. Initialed: {{ACK.INJURIES_TO_HORSE}}', 'input', 143, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HORSE_GATE"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1527e31a-9e43-4ea4-9144-9036b2d549ab', 'HORSE_SALE_V2', 'PPE', 'PPE.NA', NULL, 'No pre-purchase veterinary examination applies to this sale.', 'prose', 25, false, NULL, '{"equals": ["SELLER_DECLINES"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-09-17 22:34:55.553108-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d9fa082c-02d9-47a5-87c4-4502f9c2f39b', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.GL_DED_SIMPLE', NULL, 'For any and all such claims made against any such insurance policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by Lessee', 'input', 164, false, NULL, '{"equals": ["GL_ONLY"], "field_key": "TXN.GL_LESSOR_REQUIRES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f888795b-bd90-4b45-8cf7-a4525f2bac1b', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_PICK', 'Care, Custody and Control Insurance', '', 'input', 170, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9989ea5d-1e6b-4ae3-a133-f68ca884b197', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_NA', NULL, 'Not applicable. Care, custody and control coverage is available only as a component of a general liability policy carried by Lessee. Lessee carries no general liability insurance under this Agreement, so no care, custody and control coverage is available.', 'prose', 171, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["", "ACCEPTS_PERSONALLY"], "field_key": "TXN.GL_LESSEE_STATUS"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bf4b367d-9e14-4c4b-a9a3-aca7b2e38729', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_NOT_REQUIRED', NULL, 'Lessor does not require Lessee to maintain care, custody and control coverage under this Agreement.', 'prose', 172, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["NO"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5ae81499-a747-4383-96ea-8537c86220bb', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_REQ', NULL, 'Lessor requires Lessee to maintain care, custody and control insurance for the duration of this Agreement. Care, custody and control insurance applies only where injury to, or death of the Horse is caused by Lessee''s negligence. It shall not be claimed against merely because other coverage is unavailable, is not in force, or has denied a claim. Where a loss is caused by Lessee''s negligence, care, custody and control insurance is the policy to be claimed against for that loss.', 'input', 173, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}, {"equals": ["YES"], "field_key": "TXN.CCC_REQUIRED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bd4182f0-b27e-41e0-a44a-58581340a55b', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_STATUS', NULL, 'Lessee {{TXN.CCC_LESSEE_STATUS}} care, custody and control insurance covering the Horse while in Lessee''s care, custody, or control.', 'input', 174, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cfe24aed-cab3-4450-b5e8-c9a8bac3c251', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORTALITY', 'Mortality Insurance', '', 'input', 200, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('14f96847-afe4-461b-bd77-6f9c89c9bb26', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_NOT_REQ', NULL, 'Lessor does not carry mortality insurance on the Horse under this Agreement. Lessor accepts full risk and responsibility for the loss of the Horse''s value in the event of the Horse''s death, theft, or humane destruction, except as otherwise expressly allocated in this Agreement.', 'input', 201, false, NULL, '{"equals": ["NOT_CARRIED"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e85c1112-80f8-483c-8fbe-85f5c539e880', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_CARRIES', NULL, 'Lessor carries a mortality insurance policy for the Horse. Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality policy shall be the first policy noticed and claimed against for any such covered event.', 'prose', 202, false, NULL, '{"equals": ["CARRIES"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2f3a512d-8411-4353-8f4a-3db416f4abee', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_WILL_OBTAIN', NULL, 'Lessor will obtain a mortality insurance policy for the Horse. Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality policy shall be the first policy noticed and claimed against for any such covered event.', 'prose', 203, false, NULL, '{"equals": ["WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('278a4434-3b71-4319-a986-f785c153fbcc', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_COST', NULL, 'The cost of the policy is {{TXN.MORT_COST_RESP}}.', 'input', 206, false, NULL, '{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b457f6e4-6449-4d58-bb22-577357cd79cb', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_SHARE', NULL, 'Lessee''s share of the cost: {{TXN.MORT_COST_LESSEE_SHARE}}', 'input', 207, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b0dc6c4e-5a65-445d-9339-f68d2b7ee37a', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of this policy exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 210, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cd7d9079-ed83-4f98-9439-89062a09eeaf', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DEDR_SIMPLE', NULL, 'If a claim is made under any such policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by: {{TXN.MORT_DED_RESP}}', 'input', 214, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["SPLIT", "OTHER"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dc7dd845-3116-4cbb-b10b-861dde4227ba', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DEDR_SPLITC', NULL, 'Lessee''s share of the deductible: {{TXN.MORT_DED_LESSEE_SHARE}}', 'input', 215, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["SPLIT", "OTHER"], "field_key": "TXN.MORT_COST_RESP"}, {"equals": ["SPLIT"], "field_key": "TXN.MORT_DED_RESP"}]}', NULL, '2026-10-20 04:25:50.041445-07', true, NULL);
