INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fc614d1e-f641-4f4f-85bd-7de81061f85a', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NA', NULL, 'Not applicable. Medical coverage is available only as a component of a mortality policy on the Horse. No mortality insurance is required or in force under this Agreement, so no medical coverage is available.', 'input', 301, false, NULL, '{"equals": ["NOT_CARRIED"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3cdff8ea-3112-449b-a32c-3bbfe27e8f87', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NOT_INCLUDED', NULL, 'Medical coverage is not included on the mortality policy for the Horse under this Agreement.', 'input', 302, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["NO"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ad741c45-3eee-481d-aeeb-fac263be276f', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_INC', NULL, 'Medical coverage is included as a component of the mortality policy on the Horse for the duration of this Agreement.', 'input', 303, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
