INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8236f6aa-46c7-4c7e-beab-cd962dd27c73', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DEDR_SIMPLE', NULL, 'If a claim is made under any such policy arising from events for which Lessee bears responsibility, whether directly or indirectly, responsibility for any deductible shall be borne by: {{TXN.MED_DED_RESP}}', 'input', 314, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}, {"equals": ["SPLIT", "OTHER"], "field_key": "TXN.MED_COST_RESP"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
