INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3f363b32-72e3-4bb6-846e-3e9f9d36f3a4', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_TAIL', NULL, 'Any out-of-pocket costs for deductibles or other expenses related to the needs of the Horse are to be paid by Lessor, and where Lessee is deemed to be responsible for part or all of a cost paid by Lessor, Lessee shall reimburse Lessor in accordance with the acceptable payment methods stated in this Agreement, or, if Lessee so requests prior to payment by Lessor, Lessee may make such request to pay the billing party directly using a method allowed by that party. Lessee may, with Lessor''s written permission, pay for any or all of Lessor''s portion when paying the billing party directly, and Lessor may reimburse Lessee in accordance with the terms of this Agreement. Lessor assumes and is responsible for all risks and costs not paid or covered by any policy held by either party, including in the event a policy is not in effect at the time of the incident, an incident for which a claim is made is deemed not to be covered by a policy, a payment for a claim made for an incident that is covered by a policy is less than the actual cost incurred, or a claim made to a policy is denied for any reason, except as otherwise expressly allocated in this section or elsewhere in this Agreement.', 'input', 320, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-10-20 04:25:50.041445-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b5db0f07-aa73-453f-bd94-f709f33ee8cc', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.RISK_OF_LOSS', 'Risk of Loss of or Injury to the Horse', 'Lessor assumes all risk of loss of or injury to the Horse during the term of this Agreement, except to the extent caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct.', 'input', 500, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('907d8e5e-16ba-41d5-b18d-293f73e441eb', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.CCC_STATUS', NULL, 'Lessee {{TXN.CCC_LESSEE_STATUS}} care, custody and control insurance covering the Horse while in Lessee''s care, custody, or control.', 'input', 174, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"equals": ["AGREES", "OTHER"], "field_key": "TXN.GL_LESSEE_STATUS"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
