INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('91d2e193-7900-453f-98d4-8ebc86738c65', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.LOSS_OF_USE_ACK', 'Loss of Use', 'Lessor acknowledges and accepts that loss of use of the Horse may result from injury to, illness of, or the death of the Horse. No loss-of-use insurance is required or provided under this Agreement.', 'prose', 550, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('18c86f82-cc99-4359-a94a-8178073d7aa1', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_INJURIES_TO_HORSE_DISCLOSED_ACK_CB', NULL, 'Co-Buyer acknowledges the injuries to the horse disclosed above and proceeds with knowledge of it. Initialed: {{ACK.INJURIES_TO_HORSE_COBUYER}}', 'input', 144, false, NULL, '{"all": [{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HORSE_GATE"}]}, {"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
