INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('00b85e7f-d727-4f12-9607-9f67afaee58e', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_CARRIES', NULL, 'Lessor carries a mortality insurance policy for the Horse. Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality policy shall be the first policy noticed and claimed against for any such covered event.', 'prose', 202, false, NULL, '{"equals": ["CARRIES"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-11 08:10:08.765516-07', false, NULL);
