INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a6963a94-14c6-445e-b9dd-b2fdf7f8145e', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_CARRIES', NULL, 'Lessor carries a mortality insurance policy for the Horse. Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality policy shall be the first policy noticed and claimed against for any such covered event.', 'prose', 202, false, NULL, '{"equals": ["CARRIES"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-11 08:10:08.765516-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9c7a13d7-67f3-4da6-8d1b-c19347f00d83', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_WILL_OBTAIN', NULL, 'Lessor will obtain a mortality insurance policy for the Horse. Lessor bears responsibility for loss of, injury to, or death of the Horse, and Lessor''s mortality policy shall be the first policy noticed and claimed against for any such covered event.', 'prose', 203, false, NULL, '{"equals": ["WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-11 08:10:08.765516-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e2d25996-dbfe-42a8-9fd5-3d76bc42c18a', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of the medical component exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 310, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MED_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('85215769-d6aa-4252-a45d-8d6751b6002d', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of this policy exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 210, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('59a81e5e-4ebc-4a95-a5af-944f6f9cd995', 'HORSE_LEASE_FULL', 'EVALUATION', 'EVALUATION.DATES_FIXED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_FIXED_LENGTH}} {{TXN.EVAL_FIXED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is {{TXN.EVAL_FIXED_FEE}}, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 21, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["FIXED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_FIXED_LENGTH"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('97bcc220-1429-44d4-afa8-8ef686d0fa13', 'HORSE_LEASE_FULL', 'EVALUATION', 'EVALUATION.DATES_INCLUDED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_INCLUDED_LENGTH}} {{TXN.EVAL_INCLUDED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is included at no separate charge, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 20, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["INCLUDED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_INCLUDED_LENGTH"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('348c3b19-cbae-4043-b14a-2328b2f7d32e', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_KNOWN_CONDITIONS_NONE', NULL, 'Seller represents that, to Seller''s knowledge, the Horse has no known conditions, meaning medical conditions, lameness history, allergies, vices, or prior veterinary concerns, to disclose as of the date of this Bill of Sale.', 'input', 151, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["NO"], "field_key": "HORSE.KNOWN_CONDITIONS_GATE"}]}', NULL, '2026-10-20 04:30:32.506834-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b6f92141-50de-41d8-bc86-437b443162ef', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_TAIL', NULL, 'Any out-of-pocket costs for deductibles or other expenses related to the needs of the Horse are to be paid by Lessor, and where Lessee is deemed to be responsible for part or all of a cost paid by Lessor, Lessee shall reimburse Lessor in accordance with the acceptable payment methods stated in this Agreement, or, if Lessee so requests prior to payment by Lessor, Lessee may make such request to pay the billing party directly using a method allowed by that party. Lessee may, with Lessor''s written permission, pay for any or all of Lessor''s portion when paying the billing party directly, and Lessor may reimburse Lessee in accordance with the terms of this Agreement. Lessor assumes and is responsible for all risks and costs not paid or covered by any policy held by either party, including in the event a policy is not in effect at the time of the incident, an incident for which a claim is made is deemed not to be covered by a policy, a payment for a claim made for an incident that is covered by a policy is less than the actual cost incurred, or a claim made to a policy is denied for any reason, except as otherwise expressly allocated in this section or elsewhere in this Agreement.', 'input', 320, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-07 13:33:56.990982-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d6861cda-584e-4289-b9bc-405e955bbc7e', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Lessee understands that horseback riding and handling horses are inherently dangerous activities. Lessee acknowledges that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. Lessee acknowledges the California common law doctrine of "Primary Assumption of Risk," as established by the California Supreme Court in Knight v. Jewett (1992) 3 Cal.4th 296 and subsequent equine-specific case law (e.g., Levinson v. Owens (2009) 176 Cal.App.4th 1534). Consistent with this precedent, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, expressly and voluntarily assumes all inherent risks associated with riding or handling the Horse, and acknowledges that no Lessor Party owes a duty to protect Lessee from these inherent risks.', 'prose', 950, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ca126053-12be-4673-bea8-fc13b3c22834', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of the medical component exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 310, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MED_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a0cfd052-986d-49ae-824b-9954627d884c', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_COST', NULL, 'The cost of the medical component is {{TXN.MED_COST_RESP}}.', 'input', 306, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7f1feb1a-006d-40a3-ab62-c5463a629e7c', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_INC', NULL, 'Medical coverage is included as a component of the mortality policy on the Horse for the duration of this Agreement.', 'input', 303, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('66cded41-95f3-4d9e-ae3b-fb880234c468', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NOT_INCLUDED', NULL, 'Medical coverage is not included on the mortality policy for the Horse under this Agreement.', 'input', 302, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["NO"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cb61bcec-6d55-46b7-aabd-848b521c51f2', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE', 'Release of Liability', 'In consideration for being permitted to handle or ride the Horse, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, completely releases, forever discharges, and agrees to hold harmless the Lessor Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessee''s use, handling, or riding of the Horse, whether caused by the ordinary negligence of any Lessor Party or otherwise. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 960, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('85619e8c-54f2-4e98-b551-b98c0dd591f1', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_SUPPLEMENTS_DISCLOSED_ACK_CB', NULL, 'Co-Buyer acknowledges the supplements disclosed above and proceeds with knowledge of it. Initialed: {{ACK.SUPPLEMENTS_COBUYER}}', 'input', 184, false, NULL, '{"all": [{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.SUPPLEMENTS_GATE"}]}, {"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('83a0372f-c484-4f17-ad97-f7177d2bcd5c', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of this policy exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 210, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5ade1e31-15b8-4d69-9b40-aa708f214b95', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_COST', NULL, 'The cost of the policy is {{TXN.MORT_COST_RESP}}.', 'input', 206, false, NULL, '{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('50a5e6ba-555a-499c-ab4b-2eec96c7a1de', 'HORSE_LEASE_SIMPLE', 'EVALUATION', 'EVALUATION.DATES_INCLUDED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_INCLUDED_LENGTH}} {{TXN.EVAL_INCLUDED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is included at no separate charge, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 20, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["INCLUDED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_INCLUDED_LENGTH"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1e70708c-3a05-4868-826d-b0f94331300f', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_TAIL', NULL, 'Any out-of-pocket costs for deductibles or other expenses related to the needs of the Horse are to be paid by Lessor, and where Lessee is deemed to be responsible for part or all of a cost paid by Lessor, Lessee shall reimburse Lessor in accordance with the acceptable payment methods stated in this Agreement, or, if Lessee so requests prior to payment by Lessor, Lessee may make such request to pay the billing party directly using a method allowed by that party. Lessee may, with Lessor''s written permission, pay for any or all of Lessor''s portion when paying the billing party directly, and Lessor may reimburse Lessee in accordance with the terms of this Agreement. Lessor assumes and is responsible for all risks and costs not paid or covered by any policy held by either party, including in the event a policy is not in effect at the time of the incident, an incident for which a claim is made is deemed not to be covered by a policy, a payment for a claim made for an incident that is covered by a policy is less than the actual cost incurred, or a claim made to a policy is denied for any reason, except as otherwise expressly allocated in this section or elsewhere in this Agreement.', 'input', 320, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-07 13:33:56.990982-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d89fe084-44f3-47f1-88ed-59ad706fa4f1', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.VET_CHECK_LESSOR_FREE', NULL, 'Lessor will provide to Lessee, at no cost to Lessee, the results of a pre-lease veterinary examination of the Horse conducted by Lessor''s veterinarian, performed no more than {{TXN.VET_DAYS}} days before the date of this Agreement and delivered to Lessee no later than {{TXN.VET_END_DATE}}. If Lessor fails to provide an examination performed within that timeframe by that date, Lessee may terminate this Agreement at Lessee''s sole discretion by written notice to Lessor. If the findings of the examination are not acceptable to Lessee in Lessee''s reasonable discretion, Lessee may terminate this Agreement by written notice to Lessor, and neither party has any further obligation to the other{{TXN.VET_FEE_PHRASE}}.', 'input', 213, false, NULL, '{"equals": ["LESSOR_FREE"], "field_key": "TXN.VET_CHECK_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4f0c6639-862f-4877-9a69-8b437cee6e1a', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_INC', NULL, 'Medical coverage is included as a component of the mortality policy on the Horse for the duration of this Agreement.', 'input', 303, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f2137cca-a1bf-4355-89e5-994dbccbbab7', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NOT_INCLUDED', NULL, 'Medical coverage is not included on the mortality policy for the Horse under this Agreement.', 'input', 302, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["NO"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4f5b3519-cd30-45ac-91b3-6b9a101e9980', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.VET_CHECK_WAIVED', NULL, 'Lessee has been provided the option to obtain a pre-lease veterinary examination of the Horse at Lessee''s own expense and declines it. Lessee accepts the Horse without such examination and assumes the risk of conditions an examination might have revealed. This waiver does not limit Lessee''s rights arising from the disclosures and representations stated in this Agreement, or Lessee''s rights to terminate this Agreement as stated in the Termination section.', 'input', 214, false, NULL, '{"equals": ["WAIVED"], "field_key": "TXN.VET_CHECK_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dcfdeae4-a7a8-43a7-adc1-547b60111157', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_COST', NULL, 'The cost of the policy is {{TXN.MORT_COST_RESP}}.', 'input', 206, false, NULL, '{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
