INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('97a00636-8c21-4b17-85fa-bf90ef5ec6f1', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of the medical component exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 310, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MED_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('05d35a55-6a80-47b5-9223-ceb3fcb77ceb', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_COST', NULL, 'The cost of the medical component is {{TXN.MED_COST_RESP}}.', 'input', 306, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d46b9141-c89a-471d-ae39-157816a8b416', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_INC', NULL, 'Medical coverage is included as a component of the mortality policy on the Horse for the duration of this Agreement.', 'input', 303, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('58308622-8345-43dd-b302-e253287da8f7', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_NA', NULL, 'Not applicable. Medical coverage is available only as a component of a mortality policy on the Horse. No mortality insurance is required or in force under this Agreement, so no medical coverage is available.', 'input', 301, false, NULL, '{"equals": ["NOT_CARRIED"], "field_key": "TXN.MORT_ELECTION"}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d4d17116-3a42-4198-8246-a4784961a3f2', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE_LESSOR', 'Release of Liability by Lessor', 'In consideration of the mutual promises in this Agreement, Lessor, on behalf of Lessor and anyone claiming by, through, or under Lessor, completely releases, forever discharges, and agrees to hold harmless the Lessee Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessor''s riding or handling of the Horse or Lessor''s presence at any facility where the Horse is kept during the term of this Agreement, whether caused by the ordinary negligence of any Lessee Party or otherwise. Lessor expressly and voluntarily assumes all inherent risks of equine activities in connection with such riding, handling, or presence. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 961, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ea616e24-dc92-45c3-a574-b477f4b8639c', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_DISCLAIMER', NULL, 'Lessee''s obligation to contribute to the cost of this policy exists only while this Agreement is in effect and ends upon the termination or expiration of this Agreement, however arising. The cost of the policy is subject to change. Where the parties'' shares are stated as percentages, those percentages shall govern the allocation of any change in the cost of the policy.', 'input', 210, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["LESSEE", "SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-08-09 11:03:58.3238-07', false, NULL);
