INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0479ea5a-dd68-409d-9599-46c141bf962f', 'HORSE_LEASE_STANDARD', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment or Transfer', 'Lessee shall not assign, sublease, or otherwise transfer this Agreement or any of Lessee''s rights or obligations under it without Lessor''s prior written consent, unless permitted in the sections above.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
