INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('23a4a40a-8c51-48ff-b122-b83ea4e7c231', 'HORSE_LEASE_V2', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_SHARE', NULL, 'Lessee''s share of the cost: {{TXN.MED_COST_LESSEE_SHARE}}', 'input', 307, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}, {"equals": ["SPLIT"], "field_key": "TXN.MED_COST_RESP"}]}', NULL, '2026-08-11 08:10:08.765516-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cb32b403-755c-4a24-98ba-11596758dd56', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSOR_PENDING', NULL, '[Pending — select whether Lessor is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 10, false, NULL, '{"equals": [""], "field_key": "LESSOR.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('37baba20-f347-46c2-a0ea-6f44d2b1b15c', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSOR_IND', NULL, '"Lessor Parties" means Lessor; Lessor''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessor''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 20, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('57a3113f-5b90-4141-a9ce-ce5255239ccd', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSOR_ENT', NULL, '"Lessor Parties" means Lessor; Lessor''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessor and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 30, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('984edf1c-2489-4219-859b-7ef63641ccbe', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSEE_PENDING', NULL, '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 40, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('09decdef-d483-47ee-b6e4-5148eb01ae7f', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSEE_IND', NULL, '"Lessee Parties" means Lessee; Lessee''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessee''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 50, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('679c7ab7-f902-41fe-a6b7-6b312398bd04', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.LESSEE_ENT', NULL, '"Lessee Parties" means Lessee; Lessee''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessee and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 60, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5022b2b0-894d-4b84-9734-29cefa71e106', 'HORSE_LEASE_STANDARD', 'PAYMENT_METHOD', 'PAYMENT_METHOD.CARD', NULL, 'Credit card payments are processed as follows: {{TXN.CARD_PROCESSOR}}', 'input', 20, true, NULL, '{"contains": ["CREDIT_CARD"], "field_key": "TXN.PAYMENT_METHODS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('381141c5-7e1a-43be-a22e-70efbe3cbc46', 'HORSE_LEASE_STANDARD', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN_LESSOR', 'Payments by the Lessor', 'The Lessor may pay amounts owed under this Agreement by the following method(s): {{TXN.LESSOR_PAYMENT_METHODS}}', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c06cbce7-445e-4e20-a1c0-2829fb2c8184', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release satisfying the Releases Required for Authorized Riders provision of this Agreement to ride, handle, or care for the Horse, and each party shall indemnify, defend, and hold harmless the other party''s Lessor Parties or Lessee Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 70, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c0300b05-f736-43ac-b2d9-9ecd702bc260', 'HORSE_LEASE_STANDARD', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Lessor Party and each Lessee Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'input', 80, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('33b8cad1-fdbf-4750-9b05-45006989f003', 'HORSE_LEASE_STANDARD', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions and understandings. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('eb3a55a1-953a-47f4-9f45-231abbca0d3c', 'HORSE_LEASE_STANDARD', 'EVALUATION', 'EVALUATION.CHOICE', NULL, '', 'choice', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cd968c03-19cb-4acf-bbb2-7f5585d19c59', 'HORSE_SALE_V2', 'HORSE', 'HORSE.DISCLOSURES_NONE', 'Health and Condition Disclosures', 'To Seller''s knowledge, there is no material information regarding the Horse''s medical conditions, injuries, lameness history, surgeries, allergies, medications, behavioral issues, vices, or prior veterinary concerns to disclose as of the Effective Date. Seller shall promptly disclose any material change arising before Closing.', 'prose', 51, false, NULL, '{"equals": ["NO"], "field_key": "TXN.HAS_DISCLOSURES"}', NULL, '2026-09-17 22:37:35.976797-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2a710255-ceac-4033-bd34-2a8b95e3db49', 'HORSE_SALE_V2', 'BUYER_ACCEPTANCE', 'ACCEPT.DISCLOSURES', NULL, '{{TXN.BUYER_ACCEPTS_DISCLOSURES}}', 'input', 10, false, NULL, '{"any": [{"equals": ["YES"], "field_key": "TXN.HAS_DISCLOSURES"}, {"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}]}', NULL, '2026-09-17 22:37:36.11189-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e14d5c8e-e2a5-44b1-9948-4b8956b10fd4', 'HORSE_LEASE_STANDARD', 'EVALUATION', 'EVALUATION.REFUSED', NULL, 'No evaluation period applies to this Agreement. The Lessor has declined to provide an evaluation period, and the Lease begins on the Effective Date without one.', 'input', 40, false, NULL, '{"any": [{"equals": ["REFUSED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b1b10d8c-5067-479b-b898-442fec45afeb', 'HORSE_LEASE_STANDARD', 'EVALUATION', 'EVALUATION.WAIVED', NULL, 'No evaluation period applies to this Agreement. The Lessee has waived any evaluation period, and the Lease begins on the Effective Date without one.', 'input', 41, false, NULL, '{"any": [{"equals": ["WAIVED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d8a475d1-b371-4c0e-8207-58b0fb2463d0', 'HORSE_LEASE_STANDARD', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Venue', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('841ff515-3caa-4166-87a4-0d826bddbfd7', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.IDENTITY', 'Horse Details', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Current fair market value: {{HORSE.FAIR_MARKET_VALUE}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1a9e9e51-2ce2-4f47-bc2d-0b1475c6681d', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.OWNERSHIP', 'Ownership of the Horse', 'Lessor warrants that Lessor lawfully owns the Horse — whether owned outright, financed without any restriction that prohibits or limits leasing the Horse, or owned jointly with one or more other owners — and that Lessor has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and lease the Horse.', 'input', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c8d3653f-fea7-4490-9903-37734db015b6', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.COOWNERS', NULL, 'Co-owners: {{TXN.CO_OWNERS}}', 'input', 22, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('51ef3026-55a3-439f-9407-97e6a1195d36', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.OWNERSHIP_LIMITS_Q', NULL, 'Are there any ownership related leasing restrictions? {{TXN.HAS_OWNERSHIP_LIMITS}}', 'input', 25, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d1fef682-416d-47a3-8e2c-f07f03ff8ed4', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.OWNERSHIP_LIMITS', NULL, 'Ownership related leasing restrictions: {{TXN.OWNERSHIP_LIMITATIONS}}', 'input', 26, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_OWNERSHIP_LIMITS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1779200a-d99f-4161-97bf-f62524a8b06c', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.BEHAVIOR', 'Behavior', 'The Lessor warrants that the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement.', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f6465cbc-9e35-4d3d-a1d7-3949ee597376', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.BEHAVIOR_EXC', NULL, 'The Lessor notes the following known exceptions to the behavior of the Horse: {{TXN.BEHAVIOR_EXCEPTIONS}}', 'input', 32, true, NULL, '{"equals": ["YES"], "field_key": "TXN.BEHAVIOR_HAS_EXCEPTIONS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('63284ceb-1274-4c25-a84a-4f97574b7674', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'INSURANCE_RISK.SAFETY_ATTIRE', 'Required Protective Attire', 'Lessee shall wear, and shall ensure that any other person riding the Horse under Lessee''s authorization wears, an appropriately fitted and securely fastened ASTM/SEI-certified equestrian helmet at all times while mounted on the Horse, together with heeled boots and long pants; gloves and long sleeves are highly recommended. Riders shall provide their own helmet, boots, and pants meeting these requirements unless otherwise agreed in writing. Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, assumes all increased risk of injury or death resulting from any failure to wear the required attire. Any refusal or failure to wear an approved helmet or the other required attire immediately revokes permission to ride or handle the Horse and constitutes a material breach of this Agreement.', 'prose', 1100, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d5bc26b4-a0e5-4009-97a5-0ed723b1b1c3', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.VET_CHECK', 'Pre-Lease Veterinary Examination', 'Pre-lease veterinary examination of the Horse: {{TXN.VET_CHECK_CHOICE}}', 'input', 50, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2d771bbf-c935-4d12-be7c-10b5497ef69d', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.TRAINER_EVAL', 'Pre-Lease Trainer Evaluation', 'Pre-lease trainer evaluation of the Horse: {{TXN.TRAINER_EVAL_CHOICE}}', 'input', 55, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('350d832c-c56f-4dcd-af3b-b8fb46a8ff8c', 'HORSE_LEASE_STANDARD', 'HORSE', 'LOCATION.MAIN', 'Location', 'Location of the Horse:
{{HORSE.CURRENT_LOCATION}}', 'input', 56, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9cefce2a-b4dd-430d-bce9-39d9b11590b1', 'HORSE_LEASE_STANDARD', 'HORSE', 'LOCATION.MOVE_CHOICE', NULL, '', 'input', 57, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8770db84-4fb7-4a01-8762-c7abaa5bdf0a', 'HORSE_LEASE_STANDARD', 'HORSE', 'LOCATION.NEW', NULL, 'Location during lease term: {{TXN.NEW_LOCATION}}', 'input', 58, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HORSE_MOVES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9a8b5987-a25d-4240-aa93-27e2efe5d5e5', 'HORSE_LEASE_STANDARD', 'HORSE', 'LOCATION.INSPECTION', NULL, 'Lessor may inspect the Horse at any time, subject to the reasonable access rules of the facility where the Horse is kept. If Lessor reasonably determines that the Horse is not being properly cared for, Lessor may take possession of the Horse upon written notice to Lessee.', 'prose', 59, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d858093d-1ab7-4bb7-9017-71448445a7c5', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations expressly stated in this Agreement, LESSOR MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.', 'prose', 60, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6464da57-e90b-4fe5-b1e7-1efd715ef6a3', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.INSURANCE', 'Insurance Requirements', 'The parties agree to the insurance elections set forth below. Each policy elected or required below shall be maintained in effect for the duration of this Agreement.', 'prose', 100, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fa97b6dd-6653-491c-b279-3d8b419ade8a', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.GENERAL_LIABILITY', 'General Liability Insurance', '', 'input', 150, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6f5077c7-d0ec-4bcd-8841-3993b2ca7589', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Rider and Other Serious Injuries', 'Lessor discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Lessee acknowledges this disclosure and proceeds with knowledge of it.', 'input', 45, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('50ddab7f-cef1-4f43-b7dd-7a7ce5fe9244', 'HORSE_LEASE_STANDARD', 'HORSE', 'HORSE.INJURY_HISTORY_NONE', 'Rider and Other Serious Injuries', 'Lessor represents that, to Lessor''s knowledge, no person has suffered serious injury proximately caused by the direct actions of the Horse, including biting, kicking, striking, bucking, rearing, bolting, crushing, or throwing a rider. This representation does not extend to any incident caused primarily by a third party or an external stimulus — such as another horse or rider being at fault, a loose dog, wildlife, a vehicle, or a similar external provocation — where the Horse''s reaction was within the range of normal equine behavior.', 'input', 44, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cfb07dc8-ae96-4562-a287-de7f7f213c15', 'HORSE_LEASE_STANDARD', 'INSURANCE_RISK', 'INSURANCE_RISK.MORT_SHARE', NULL, 'Lessee''s share of the cost: {{TXN.MORT_COST_LESSEE_SHARE}}', 'input', 207, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["SPLIT"], "field_key": "TXN.MORT_COST_RESP"}]}', NULL, '2026-08-11 08:10:08.765516-07', false, NULL);
