INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c8749390-d8bb-4b13-8f86-4e9856755172', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'TRAINING_LESSONS.TRAINING', 'Training', 'Any professional training of the Horse under this Agreement, including groundwork, schooling, and under-saddle training, shall be conducted only by a French Heritage Equestrian Approved Trainer.', 'input', 270, false, NULL, '{"contains": ["TRAINING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
