INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('59fccb0e-deec-41a5-8513-14f951c98432', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PROHIBITED.OTHER', 'Other Allowed Activities', 'Lessee is permitted to engage in the following additional activities with the Horse: {{TXN.ADDITIONAL_ACTIVITIES}}', 'input', 450, true, NULL, '{"contains": ["BREEDING", "EMOTIONAL_SUPPORT", "FILM_TV_AD", "OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('599366c8-88f9-4b45-8cd9-9c34dab70faf', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PROHIBITED.OTHER_NONE', 'Other Allowed Activities', 'Lessee is not permitted to engage in any activities with the Horse beyond the permitted uses stated above.', 'input', 455, false, NULL, '{"equals": ["", "NONE"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('95ce6bb3-5dbc-4cf4-9546-5e1e6df1e30a', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PROHIBITED.OTHER_NOTE', NULL, 'Other additional permitted activity: {{TXN.ADDITIONAL_ACTIVITIES_OTHER}}', 'input', 460, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7b097c59-14d6-4c6d-a2a4-160818710011', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PROHIBITED.OTHERS', 'Allowing Others to Ride', 'The following additional persons may ride or handle the Horse without Lessor''s prior permission: {{TXN.OTHERS_ALLOWED}}.
Only the persons identified above shall be permitted to ride or handle the Horse without Lessor''s written permission.', 'input', 480, true, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('19528689-a0f1-49cb-a993-975cd226e4e1', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PERMITTED_USE.RELEASES_REQUIRED', 'Releases Required for Authorized Riders', 'All persons other than Lessee must, prior to handling or riding the Horse, have executed a liability release that names the Lessor Parties and the Lessee Parties as released parties, contains an express assumption of the inherent risks of equine activities, has been reviewed and approved by Lessor, and, for any rider under 18 years of age, is signed by the rider''s parent or legal guardian. Lessee is responsible for ensuring this requirement is satisfied before permitting any authorized person to ride or handle the Horse.', 'prose', 495, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cd32a554-d04f-48a6-8e1a-f0ffb0d9f7d4', 'HORSE_LEASE_STANDARD', 'PERMITTED_USE', 'PERMITTED_USE.TRANSPORT', 'Transport of the Horse', 'Transport of the Horse to offsite locations (other than for medical care, which is always permitted): {{TXN.OFFSITE_TRANSPORT}}
For clarity, riding trails attached to the location at which the Horse is kept under this Agreement are not offsite locations. Where Competitions are a permitted activity under this Agreement, transport of the Horse to and from the competition venue for that competition is deemed consented, subject to any competition restrictions stated in this Agreement.', 'input', 500, true, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('07ca466c-5595-498a-b756-e6e1c671cb5f', 'HORSE_LEASE_STANDARD', 'PURPOSE', 'PURPOSE.RECREATION_DEFAULT', 'Purpose of Agreement', '[Pending — select the purpose of this lease. This placeholder is replaced by the applicable purpose language and blocks signing.]', 'input', 5, false, NULL, '{"equals": [""], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0adcdc86-d71b-439c-9109-266bc4a87d0b', 'HORSE_LEASE_STANDARD', 'PURPOSE', 'PURPOSE.RECREATION', 'Purpose of Agreement', 'For {{TXN.LEASE_PURPOSE}} purposes, Lessee wishes to ride and/or handle Lessor''s horse, and Lessor agrees to allow Lessee to ride and/or handle Lessor''s horse in exchange for the consideration described herein.', 'prose', 10, false, NULL, '{"equals": ["RECREATIONAL", "INSTRUCTIONAL", "COMPETITION", "COMMERCIAL"], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a6e740b7-dc69-46e5-9350-351c0edc7ae2', 'HORSE_LEASE_STANDARD', 'PURPOSE', 'PURPOSE.GRANT', 'Lease Grant', 'Subject to the terms and conditions of this Agreement, Lessor agrees to lease to Lessee and Lessee agrees to lease from Lessor the horse described below.', 'prose', 15, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('20ada388-7b4d-4990-beff-e98fc16da17d', 'HORSE_LEASE_STANDARD', 'PURPOSE', 'PURPOSE.LEASE_TYPE', 'Lease Type', 'Lease type: {{TXN.LEASE_TYPE}}', 'input', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('61bc5b49-515b-4239-849c-26b9867f4165', 'HORSE_LEASE_STANDARD', 'SCHEDULE', 'SCHEDULE.MAIN', 'Schedule for Lessee''s Usage', 'Reserved days of use: {{TXN.DAYS_USED}}', 'input', 10, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f1a52735-b094-480c-b5bf-769dbc520b2e', 'HORSE_LEASE_STANDARD', 'SCHEDULE', 'SCHEDULE.OTHER', NULL, 'Additional or custom schedule terms: {{TXN.SCHEDULE_TERMS}}', 'input', 12, true, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ca82dd61-abc9-4bdb-9eda-228e8494f25e', 'HORSE_LEASE_STANDARD', 'SCHEDULE', 'SCHEDULE.CHANGES', 'Schedule Changes', 'Any changes to the agreed upon schedule must be made and accepted in writing.', 'prose', 15, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8b29cb67-0a8b-4d6c-aa52-f088de98b94d', 'HORSE_LEASE_STANDARD', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('20f0d6c5-6df0-4455-b780-c34d2ab00f7c', 'HORSE_LEASE_STANDARD', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

LESSEE
Signature: {{SIG.LESSEE.NAME}}
Printed Name: {{LESSEE.PRINTED_NAME}}
Date: {{SIG.LESSEE.DATE}}

LESSOR (OWNER)
Signature: {{SIG.LESSOR.NAME}}
Printed Name: {{LESSOR.PRINTED_NAME}}
Date: {{SIG.LESSOR.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9467bab9-a016-4848-b4de-103db54ad388', 'HORSE_LEASE_STANDARD', 'SIGNATURES', 'SIGNATURES.LESSEE_CAPACITY', NULL, 'By: {{LESSEE.ENTITY_SIGNER_NAME}}
