INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('943f2ac3-9c20-419e-a7fb-8a90bea69785', 'HORSE_LEASE_V3', 'LEASE_FEE', 'LEASE_FEE.NO_FEE_CONSIDERATION', NULL, 'If no monetary lease fee is payable under this Agreement, the parties agree that Lessee''s undertakings of care, exercise, and use of the Horse and Lessee''s other obligations under this Agreement constitute good and adequate consideration for this Agreement.', 'input', 6, true, NULL, '{"equals": ["NO"], "field_key": "TXN.LEASE_FEE_PAYABLE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10451619-482d-4257-bfb2-8df9f5769fc0', 'HORSE_LEASE_V3', 'LESSEE_REPS', 'LESSEE_REPS.PENDING', 'Lessee''s Representations', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 5, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('86422e8f-8084-4943-846d-58d070c7d593', 'HORSE_LEASE_V3', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_INDIVIDUAL', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is at least 18 years of age and has full authority to enter into this Agreement; that Lessee has no physical or mental condition that would prevent Lessee from safely participating in the activities contemplated by this Agreement; and that Lessee has the requisite knowledge and experience to handle and ride the Horse, and will use reasonable care in doing so and follow Lessor''s instructions. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3ad2b098-db53-44cb-8b03-1fd73e583152', 'HORSE_LEASE_V3', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_ENTITY', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is duly organized and in good standing, and has full authority to enter into this Agreement, and that the individual signing this Agreement does so as Lessee''s authorized representative; that each person who rides or handles the Horse under Lessee''s authorization will, before doing so, have executed the releases required under this Agreement and possess the knowledge and experience to handle and ride the Horse safely; and that Lessee will use reasonable care and follow Lessor''s instructions in all handling of the Horse. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('65f39549-056c-4132-b14d-d6236ed624e8', 'HORSE_LEASE_V3', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a29e553f-7fb0-464c-82d2-2c45dbee0d84', 'HORSE_LEASE_V3', 'NOTICE', 'NOTICE.LESSEE_ADDRESS', 'Lessee', 'Name: {{LESSEE.FULL_NAME}}
Address: {{LESSEE.ADDRESS}}
