INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('68ede4a7-7332-40c1-b431-bf7ce07433ae', 'HORSE_LEASE_V3', 'PAYMENT_TERMS', 'PAYMENT_TERMS.OFFSET', 'Right of Offset', 'A party to whom money is owed under this Agreement may offset the amount owed against any amount that party owes to the other party.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ba0a6e40-a473-48c4-84b5-5f507ce8e5ba', 'HORSE_LEASE_V3', 'PAYMENT_TERMS', 'PAYMENT_TERMS.RECEIPTS', 'Receipts', 'A party seeking reimbursement for an expense paid on behalf of the other party shall provide a receipt or other reasonable documentation of the expense as a condition of reimbursement.', 'prose', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6bbe6873-ada3-4e73-9445-78cec5396162', 'HORSE_LEASE_V3', 'PAYMENT_TERMS', 'PAYMENT_TERMS.LATE', 'Late Payments', 'All payments are due on their due date or within 5 business days of notification of the amount owed. Payments will be deemed late if they remain unpaid on the 6th business day. Late payments are considered a breach of the contract terms and may be grounds for termination of the Agreement unless the party from whom the payment is owed has communicated in writing the date by which payment will be made. Payments exceeding 1 calendar month in past-due status constitute grounds for termination for cause under the Termination for Cause provisions of this Agreement unless prior written acceptance of the delay is provided by the party to whom the payment is owed.', 'input', 40, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d96e7ec4-be1c-4490-9cff-63e58ce29658', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PERMITTED_USE.MAIN', 'Permitted Use(s)', 'Lessor grants Lessee the right to use the Horse for the following purpose(s): {{TXN.PERMITTED_ACTIVITIES}}
Lessee shall not use the Horse for any other purpose without Lessor''s prior written consent.', 'input', 100, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('54b0dbdf-a8cb-411f-acea-a1f5c267a2a3', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PERMITTED_USE.TRAINER', NULL, 'Riding Lessons, Jumping, and Competitions may take place only while a French Heritage Equestrian Approved Trainer or Instructor is present.', 'input', 200, false, NULL, '{"contains": ["LESSONS", "JUMPING", "COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e6fd607f-8a7e-4321-ac57-90430f02738a', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'TRAINING_LESSONS.PENDING', 'Lessons', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable lessons terms and blocks signing.]', 'input', 245, false, NULL, '{"all": [{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('46eed529-6e95-4b31-a3b4-4c54060c02c9', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'TRAINING_LESSONS.LESSONS', 'Lessons — Continuous Enrollment', 'Lessee is required to maintain continuous enrollment in weekly riding lessons: {{TXN.LESSONS_REQUIRED}}.
Lessons shall be conducted only by a French Heritage Equestrian Approved Instructor.', 'input', 250, false, NULL, '{"all": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('86edc56d-73b1-469b-9e31-c38c89e5c56f', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.RISK_OF_LOSS', 'Risk of Loss of or Injury to the Horse', 'Lessor assumes all risk of loss of or injury to the Horse during the term of this Agreement, except to the extent caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct.', 'input', 500, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c1e6f76d-e64b-4b2f-960a-3d97da030556', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.LOSS_OF_USE_ACK', 'Loss of Use', 'Lessor acknowledges and accepts that loss of use of the Horse may result from injury to, illness of, or the death of the Horse. No loss-of-use insurance is required or provided under this Agreement.', 'prose', 550, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e83b69b3-119a-405d-963c-335871415ebd', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Lessee understands that horseback riding and handling horses are inherently dangerous activities. Lessee acknowledges that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. Lessee acknowledges the California common law doctrine of "Primary Assumption of Risk," as established by the California Supreme Court in Knight v. Jewett (1992) 3 Cal.4th 296 and subsequent equine-specific case law (e.g., Levinson v. Owens (2009) 176 Cal.App.4th 1534). Consistent with this precedent, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, expressly and voluntarily assumes all inherent risks associated with riding or handling the Horse, and acknowledges that no Lessor Party owes a duty to protect Lessee from these inherent risks.', 'prose', 950, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3ec2d8b5-86f3-4141-bca4-098a619b8aa1', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE', 'Release of Liability', 'In consideration for being permitted to handle or ride the Horse, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, completely releases, forever discharges, and agrees to hold harmless the Lessor Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessee''s use, handling, or riding of the Horse, whether caused by the ordinary negligence of any Lessor Party or otherwise. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 960, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('85d66641-414c-434d-b7e7-90d771da4e8d', 'HORSE_LEASE_FULL', 'LESSEE_REPS', 'LESSEE_REPS.PENDING', 'Lessee''s Representations', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 5, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3e7c73c9-592e-4ca4-ae8b-3a550e9e2fbf', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'TRAINING_LESSONS.LESSONS_ENTITY', 'Lessons — Lessee''s Instruction Program', 'Lessee is permitted by Lessor to provide riding lessons with the Horse: {{TXN.LESSONS_ENTITY_PERMITTED}}', 'input', 255, false, NULL, '{"all": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}, {"contains": ["LESSONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4d639afd-c7a4-4522-ba9e-41e1a0298d7b', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'TRAINING_LESSONS.TRAINING', 'Training', 'Any professional training of the Horse under this Agreement, including groundwork, schooling, and under-saddle training, shall be conducted only by a French Heritage Equestrian Approved Trainer.', 'input', 270, false, NULL, '{"contains": ["TRAINING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e8568858-81b5-4067-999d-80696c823319', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'COMPETITIONS.INTRO', 'Competition Costs and Winnings', 'Expenses of competition (entry fees, transportation, and the like) are: {{TXN.COMPETITION_EXPENSES}}.
Any prize money or winnings earned in competition shall belong to: {{TXN.COMPETITION_WINNINGS}}', 'prose', 310, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d3b05608-a271-4635-9d65-afa02575fd50', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.COMP_TITLE', 'Competition Restrictions', '{{TXN.COMP_OMIT}}', 'input', 312, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a6ce82c2-579e-4f70-a185-c9f9be979dc4', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.COMP_ON', NULL, 'Competitions are restricted as follows: {{TXN.COMP_RESTRICTION}}', 'input', 313, true, NULL, '{"all": [{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.COMP_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d9deba79-a967-494f-8ed4-31efd186f1bf', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.COMP_OFF', NULL, 'Lessor does not restrict competition activity in any way.', 'input', 314, false, NULL, '{"all": [{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.COMP_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('66c01fc4-0c33-45f3-a603-3dfccd467508', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE_LESSOR', 'Release of Liability by Lessor', 'In consideration of the mutual promises in this Agreement, Lessor, on behalf of Lessor and anyone claiming by, through, or under Lessor, completely releases, forever discharges, and agrees to hold harmless the Lessee Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessor''s riding or handling of the Horse or Lessor''s presence at any facility where the Horse is kept during the term of this Agreement, whether caused by the ordinary negligence of any Lessee Party or otherwise. Lessor expressly and voluntarily assumes all inherent risks of equine activities in connection with such riding, handling, or presence. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 961, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('700961af-be94-452d-aa79-a4280b11f281', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.SAFETY_ATTIRE', 'Required Protective Attire', 'Lessee shall wear, and shall ensure that any other person riding the Horse under Lessee''s authorization wears, an appropriately fitted and securely fastened ASTM/SEI-certified equestrian helmet at all times while mounted on the Horse, together with heeled boots and long pants; gloves and long sleeves are highly recommended. Riders shall provide their own helmet, boots, and pants meeting these requirements unless otherwise agreed in writing. Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, assumes all increased risk of injury or death resulting from any failure to wear the required attire. Any refusal or failure to wear an approved helmet or the other required attire immediately revokes permission to ride or handle the Horse and constitutes a material breach of this Agreement.', 'prose', 1100, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e414702d-d297-49cf-aff1-7804643f76af', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.TRAIL_RIDING', 'Trail Riding Risks', 'Lessee acknowledges that riding outside an enclosed arena, including trail riding, exposes Lessee and the Horse to additional risks, including uneven terrain, traffic, wildlife, water crossings, and other conditions that may cause the Horse to spook or behave unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'prose', 1200, false, NULL, '{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2c7cf549-f93a-4617-bba2-ab516c287b24', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.JUMPING_RISKS', 'Jumping Risks', 'Lessee acknowledges that jumping the Horse exposes Lessee and the Horse to additional risks beyond flat riding, including refusals, run-outs, awkward or missed distances, falls, unseating, and the Horse landing, stopping, or twisting unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1210, false, NULL, '{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('62ca22da-5c48-4ba4-85e2-47ee09a060f9', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.COMPETITION_RISKS', 'Competition Risks', 'Lessee acknowledges that competing with the Horse exposes Lessee and the Horse to additional risks, including unfamiliar and crowded show grounds, proximity to other horses and riders, loudspeakers, banners, and other stimuli that may cause the Horse to spook or behave unpredictably, as well as the physical demands and pressures of competition. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1220, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1299e0e2-e533-4a0a-b7b1-f73f0b4bbf28', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.SHARED_ARENA_RISKS', 'Shared Arena Riding Risks', 'Lessee acknowledges that riding in an arena at the same time as other riders exposes Lessee and the Horse to additional risks, including collisions, crowding, sudden movements or loss of control by other horses or riders, and the Horse reacting to other horses. Lessee agrees to ride with awareness of others, to follow standard arena etiquette and right-of-way rules and any directions of Lessor or an instructor, and voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1230, false, NULL, '{"contains": ["ARENA_GROUP"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('db8c323f-1eb6-4c87-b2d3-97f8a8003920', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement.', 'prose', 1300, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b3a78e69-3255-4584-a3ea-959475c1d5e7', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.INDEMNIFICATION', 'Mutual Indemnification', 'Each party shall indemnify, defend, and hold harmless the other party and, respectively, the Lessor Parties or the Lessee Parties, from and against any and all claims, damages, losses, liabilities, costs, and expenses arising out of the indemnifying party''s use, handling, care, or possession of the Horse, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 1400, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e9f7a4ed-d91d-4954-98a4-f501caf05a0d', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.LIMITATION', 'Limitation of Liability', 'Under no circumstances shall either party be liable to the other for any special, consequential, incidental, or punitive damages arising out of or relating to this Agreement. The total aggregate liability of either party (including, respectively, the Lessor Parties and the Lessee Parties) to the other under this Agreement shall not exceed the Horse''s current fair market value of {{HORSE.FAIR_MARKET_VALUE}}. Any amount owed by one party to the other under this Agreement shall be reduced by the amount of any insurance proceeds actually received by the party owed with respect to the same loss. This limitation does not apply to gross negligence, reckless conduct, or intentional misconduct, to either party''s indemnification obligations for third-party claims for bodily injury or death, or to amounts actually covered by insurance available for the loss.', 'prose', 1520, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1f1fba6d-9e42-47f2-b555-77f89736018f', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.JUMP_TITLE', 'Jumping Restrictions', '{{TXN.JUMP_OMIT}}', 'input', 320, false, NULL, '{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f3e9b65f-3d7d-4d2e-9ee6-978cf5cc1607', 'HORSE_LEASE_SIMPLE', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN_LESSOR', 'Payments by the Lessor', 'The Lessor may pay amounts owed under this Agreement by the following method(s): {{TXN.LESSOR_PAYMENT_METHODS}}', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6cfcf347-cb60-4630-b751-10ec2f2b9d0d', 'HORSE_LEASE_FULL', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_INDIVIDUAL', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is at least 18 years of age and has full authority to enter into this Agreement; that Lessee has no physical or mental condition that would prevent Lessee from safely participating in the activities contemplated by this Agreement; and that Lessee has the requisite knowledge and experience to handle and ride the Horse, and will use reasonable care in doing so and follow Lessor''s instructions. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d4a6cf3d-cc4f-4687-9bd4-179deba84d3e', 'HORSE_LEASE_FULL', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_ENTITY', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is duly organized and in good standing, and has full authority to enter into this Agreement, and that the individual signing this Agreement does so as Lessee''s authorized representative; that each person who rides or handles the Horse under Lessee''s authorization will, before doing so, have executed the releases required under this Agreement and possess the knowledge and experience to handle and ride the Horse safely; and that Lessee will use reasonable care and follow Lessor''s instructions in all handling of the Horse. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2d03813e-452e-42ce-9c72-dd8fb6f173f8', 'HORSE_LEASE_FULL', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('202b682d-b2de-433e-8463-65576b0442b5', 'HORSE_LEASE_FULL', 'NOTICE', 'NOTICE.LESSEE_ADDRESS', 'Lessee', 'Name: {{LESSEE.FULL_NAME}}
Address: {{LESSEE.ADDRESS}}
Phone: {{LESSEE.PHONE}}
Email: {{LESSEE.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c58856a9-19ce-4fd9-a5c4-b7e9f036a5fd', 'HORSE_LEASE_FULL', 'NOTICE', 'NOTICE.LESSOR_ADDRESS', 'Lessor', 'Name: {{LESSOR.FULL_NAME}}
Address: {{LESSOR.ADDRESS}}
Phone: {{LESSOR.PHONE}}
Email: {{LESSOR.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
