INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('87011ab1-cf21-4b72-8805-151af49d3b67', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'RESTRICT.JUMP_ON', NULL, 'Jumping is restricted as follows: maximum height {{TXN.JUMP_MAX_HEIGHT}}; no more than {{TXN.JUMP_DAYS_PER_WEEK}} days per week; under trainer supervision only: {{TXN.JUMP_SUPERVISION}}', 'input', 321, true, NULL, '{"all": [{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.JUMP_OMIT"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
