INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5806e1c2-cf46-4a8c-871a-1965ca2ec62e', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'RESTRICT.TRAIL_ON', NULL, 'Trail riding is restricted as follows: {{TXN.TRAIL_RESTRICTION}}', 'input', 331, true, NULL, '{"all": [{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.TRAIL_OMIT"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
