INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('405dd80d-e524-41b3-a515-e9da55cb64fc', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PROHIBITED.OTHER', 'Other Allowed Activities', 'Lessee is permitted to engage in the following additional activities with the Horse: {{TXN.ADDITIONAL_ACTIVITIES}}', 'input', 450, true, NULL, '{"contains": ["BREEDING", "EMOTIONAL_SUPPORT", "FILM_TV_AD", "OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('de10b14b-8e2b-4f4e-b8b5-7c4b48119411', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PROHIBITED.OTHER_NONE', 'Other Allowed Activities', 'Lessee is not permitted to engage in any activities with the Horse beyond the permitted uses stated above.', 'input', 455, false, NULL, '{"equals": ["", "NONE"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('783d2d34-2252-4b83-9cab-72725d9ba2c3', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PROHIBITED.OTHER_NOTE', NULL, 'Other additional permitted activity: {{TXN.ADDITIONAL_ACTIVITIES_OTHER}}', 'input', 460, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('74f4e906-fc24-4d5c-ada2-765bbb052832', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PROHIBITED.OTHERS', 'Allowing Others to Ride', 'The following additional persons may ride or handle the Horse without Lessor''s prior permission: {{TXN.OTHERS_ALLOWED}}.
Only the persons identified above shall be permitted to ride or handle the Horse without Lessor''s written permission.', 'input', 480, true, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7e245772-9ae9-433f-b305-170faf79e953', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PERMITTED_USE.RELEASES_REQUIRED', 'Releases Required for Authorized Riders', 'All persons other than Lessee must, prior to handling or riding the Horse, have executed a liability release that names the Lessor Parties and the Lessee Parties as released parties, contains an express assumption of the inherent risks of equine activities, has been reviewed and approved by Lessor, and, for any rider under 18 years of age, is signed by the rider''s parent or legal guardian. Lessee is responsible for ensuring this requirement is satisfied before permitting any authorized person to ride or handle the Horse.', 'prose', 495, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c18dbaff-1f8f-4939-abf0-52e8bf0c0954', 'HORSE_LEASE_FULL', 'PERMITTED_USE', 'PERMITTED_USE.TRANSPORT', 'Transport of the Horse', 'Transport of the Horse to offsite locations (other than for medical care, which is always permitted): {{TXN.OFFSITE_TRANSPORT}}
For clarity, riding trails attached to the location at which the Horse is kept under this Agreement are not offsite locations. Where Competitions are a permitted activity under this Agreement, transport of the Horse to and from the competition venue for that competition is deemed consented, subject to any competition restrictions stated in this Agreement.', 'input', 500, true, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0eed43fe-381b-4849-8b72-c9b936e4ce7e', 'HORSE_LEASE_FULL', 'PURPOSE', 'PURPOSE.RECREATION_DEFAULT', 'Purpose of Agreement', '[Pending — select the purpose of this lease. This placeholder is replaced by the applicable purpose language and blocks signing.]', 'input', 5, false, NULL, '{"equals": [""], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d33534c0-3c8b-46fd-8274-77eb97ba5826', 'HORSE_LEASE_FULL', 'PURPOSE', 'PURPOSE.RECREATION', 'Purpose of Agreement', 'For {{TXN.LEASE_PURPOSE}} purposes, Lessee wishes to ride and/or handle Lessor''s horse, and Lessor agrees to allow Lessee to ride and/or handle Lessor''s horse in exchange for the consideration described herein.', 'prose', 10, false, NULL, '{"equals": ["RECREATIONAL", "INSTRUCTIONAL", "COMPETITION", "COMMERCIAL"], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0ae748aa-eae7-4129-a641-2fcca2e0bff7', 'HORSE_LEASE_FULL', 'PURPOSE', 'PURPOSE.GRANT', 'Lease Grant', 'Subject to the terms and conditions of this Agreement, Lessor agrees to lease to Lessee and Lessee agrees to lease from Lessor the horse described below.', 'prose', 15, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
