INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5f5402d6-5f9c-43c4-8cd3-613746db3026', 'HORSE_LEASE_FULL', 'SCHEDULE', 'SCHEDULE.CHANGES', 'Schedule Changes', 'Any changes to the agreed upon schedule must be made and accepted in writing.', 'prose', 15, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dcdf7daf-b22f-4072-a9f7-d964c738518e', 'HORSE_LEASE_FULL', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cc9c37b9-4f16-4a50-9390-e1eeb9dca1ba', 'HORSE_LEASE_FULL', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

