INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0c448548-e51a-4880-88e8-ad6ef1185047', 'HORSE_LEASE_FULL', 'TERM', 'TERM.TERMINATION_XREF', NULL, 'Notwithstanding the term stated above, this Agreement may be terminated earlier as provided in the Termination section of this Agreement.', 'prose', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5898fae8-3abf-4ba9-83e0-d9b63e6ede1a', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.LESSEE', 'Lessee''s Right to Terminate', 'Lessee may terminate this Agreement by giving Lessor at least {{TXN.LESSEE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8489d797-0a7a-46b3-ace2-e0092cbf3ddb', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.OWNER', 'Owner''s Right to Terminate', 'Lessor may terminate this Agreement by giving Lessee at least {{TXN.OWNER_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('398bdcff-1ddf-4ba8-ae33-bfc0e19bf917', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.CAUSE', 'Termination for Cause', 'Either party may terminate this Agreement for cause (including a material breach that remains uncured) by giving the other party at least {{TXN.CAUSE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('493271b1-e206-4b08-ac48-4b57f4fda250', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.LOSS', 'Self-Termination upon Loss or Injury', 'This Agreement shall self-terminate if the Horse is significantly injured or seriously ill as determined by a licensed veterinarian, or dies. Lessee is entitled to a prorated refund of Lease Fee paid for the remaining time unused at the time of self-termination. In the event Lessee is found to have caused, through gross negligence, reckless conduct, or intentional misconduct, the injury, illness, or death, Lessor may retain the unused portion of the paid Lease Fee.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b08e504f-5154-42b7-9381-bc6170e60134', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.LOSS_OF_USE', 'Termination upon Loss of Use', 'If the Horse becomes unusable for the purposes of this Agreement for any reason, Lessee may terminate this Agreement immediately upon written notice to Lessor. Upon such termination, Lessee is entitled to a prorated refund of any Lease Fee paid for the remaining unused time as of the date of termination.', 'prose', 45, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8a42a6a9-4f1a-4013-8e56-10ebec0d2eb6', 'HORSE_LEASE_FULL', 'TERMINATION', 'TERMINATION.SURVIVAL', 'Survival', 'The releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement, and any payment obligations accrued before termination, survive the expiration or termination of this Agreement for any reason.', 'prose', 50, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8b57891f-f388-4590-9d6c-1725701fe636', 'HORSE_LEASE_SIMPLE', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment or Transfer', 'Lessee shall not assign, sublease, or otherwise transfer this Agreement or any of Lessee''s rights or obligations under it without Lessor''s prior written consent, unless permitted in the sections above.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0ea9518e-77dc-4bd6-959e-3d1a4eb782e0', 'HORSE_LEASE_SIMPLE', 'ATTORNEYS_FEES', 'ATTORNEYS_FEES.PREVAILING', 'Attorneys'' Fees', 'Each party shall cover their own attorney''s fees and costs.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8bc0114d-d6f6-4dc3-b755-a9e89db45ff2', 'HORSE_LEASE_SIMPLE', 'CARE', 'SCHEDULE.CARE_DUTY', 'Lessee''s Responsibility for Care and Exercise', 'Lessee''s use of the Horse is a responsibility as well as a right: regular, consistent exercise and attention are important to the Horse''s health and wellbeing. Lessee is required to maintain regular use and exercise for the Horse on their allowed days, unless Lessee has discussed with and received mutual agreement from the Lessor in writing that one of those days will be used as a rest day for the Horse. If Lessee regularly fails to use and care for the Horse, Lessor may terminate this Agreement.', 'prose', 1, false, NULL, '{"equals": ["YES"], "field_key": "TXN.EXERCISE_INCLUDE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f77ec38d-aad0-4f6f-9c40-39f998f7f0d6', 'HORSE_LEASE_SIMPLE', 'CARE', 'SCHEDULE.TRAINER_CARE', '3rd Party Exercise', 'Lessee is permitted to engage an approved 3rd party to exercise the Horse. All 3rd party exercise shall be conducted only by a French Heritage Equestrian Approved Trainer. Other 3rd parties must be approved in writing by the Lessor.
Party responsible for arranging: {{TXN.TRAINER_EXERCISE_ARRANGE}}
Party responsible for costs: {{TXN.TRAINER_EXERCISE_COST}}
Lessee''s share of the cost: {{TXN.TRAINER_EXERCISE_SPLIT_PCT}}', 'input', 2, false, NULL, '{"equals": ["YES"], "field_key": "TXN.TRAINER_CARE_INCLUDE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5dfb62d2-8dfa-476b-a985-eb87df2b9ff9', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.INTRO', NULL, 'Horse care and expenses shall be managed and paid for by the responsible party as listed below.', 'prose', 5, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7a4b4087-9cd5-4395-89e8-25e6e0d8eb3f', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.SUPPLEMENTS', NULL, '{{TXN.MEDICATIONS}}', 'input', 10, true, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
