INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('daebc917-ff67-4ea0-9a1a-8cf9e0fcc9ed', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.PROTECTIVE', 'Protective Equipment', 'Horse must wear protective equipment: {{TXN.PROTECTIVE_REQUIRED}}', 'input', 60, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('72b37987-bab9-411b-810b-c5cfe595bbf6', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.PROTECTIVE_EQUIP', NULL, 'Lessor will provide the following equipment for the Horse: {{TXN.PROTECTIVE_EQUIPMENT}}
Lessee must ensure equipment is used and properly secured to the Horse prior to all activities.', 'input', 62, true, NULL, '{"equals": ["YES"], "field_key": "TXN.PROTECTIVE_REQUIRED"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('68a91078-bfbc-4c44-a3e6-306e8e3b0832', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.TACK', 'Tack', 'When riding and handling the Horse, Lessee shall use only tack in good condition that is properly fitted to the Horse.
{{TXN.TACK_PROHIBITED}}', 'input', 70, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('91d9b8bc-edf2-41fd-9ce3-8e9bd85ef533', 'HORSE_SALE_V3', 'TRIAL', 'TRIAL_ENABLED_PENDING', NULL, '[Pending — select whether a trial period applies. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 3, false, NULL, '{"equals": [""], "field_key": "TXN.TRIAL_ENABLED"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b810ba2f-d06c-467c-b3c0-a9836813f2cb', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSOR_PENDING', NULL, '[Pending — select whether Lessor is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 10, false, NULL, '{"equals": [""], "field_key": "LESSOR.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1c4ac092-aaff-4048-81c8-35d9c37e4634', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSOR_IND', NULL, '"Lessor Parties" means Lessor; Lessor''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessor''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 20, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3306d7c5-719c-4d33-bda6-a29130a250f0', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSOR_ENT', NULL, '"Lessor Parties" means Lessor; Lessor''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessor and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 30, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSOR.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fefb3fc4-10ae-4005-90ff-7b7574f96402', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSEE_PENDING', NULL, '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'input', 40, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4337b13e-5add-4c74-b256-7adc02e67451', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSEE_IND', NULL, '"Lessee Parties" means Lessee; Lessee''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Lessee''s estate, executors, administrators, legal representatives, successors, and assigns.', 'input', 50, false, NULL, '{"any": [{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9e2a34a0-52f0-49b7-a464-c2c82353500c', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.LESSEE_ENT', NULL, '"Lessee Parties" means Lessee; Lessee''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Lessee and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'input', 60, false, NULL, '{"any": [{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6048ba62-6afb-42d6-95d2-b1c8f3bc699f', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release satisfying the Releases Required for Authorized Riders provision of this Agreement to ride, handle, or care for the Horse, and each party shall indemnify, defend, and hold harmless the other party''s Lessor Parties or Lessee Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 70, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5cd098e1-ce20-478d-907c-bfbafc8fcf1e', 'HORSE_LEASE_SIMPLE', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Lessor Party and each Lessee Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'input', 80, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f256310e-6789-4c9f-a3f7-d7175177b66e', 'HORSE_LEASE_SIMPLE', 'CARE', 'CARE.RIDER_AIDS', 'Rider Aids', '', 'input', 90, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('99165ed7-a2a4-4f52-9be8-cc08a1202246', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.JUMP_ON', NULL, 'Jumping is restricted as follows: maximum height {{TXN.JUMP_MAX_HEIGHT}}; no more than {{TXN.JUMP_DAYS_PER_WEEK}} days per week; under trainer supervision only: {{TXN.JUMP_SUPERVISION}}', 'input', 321, true, NULL, '{"all": [{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.JUMP_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b9e7b0cb-940e-4b5c-ac62-a1e3fd4ec21b', 'HORSE_LEASE_SIMPLE', 'EVALUATION', 'EVALUATION.REFUSED', NULL, 'No evaluation period applies to this Agreement. The Lessor has declined to provide an evaluation period, and the Lease begins on the Effective Date without one.', 'input', 40, false, NULL, '{"any": [{"equals": ["REFUSED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('441ed77e-1709-4ea6-b3fd-c7c69a9a65d7', 'HORSE_LEASE_SIMPLE', 'EVALUATION', 'EVALUATION.WAIVED', NULL, 'No evaluation period applies to this Agreement. The Lessee has waived any evaluation period, and the Lease begins on the Effective Date without one.', 'input', 41, false, NULL, '{"any": [{"equals": ["WAIVED"], "field_key": "TXN.EVALUATION_ENABLED"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c403251b-e9b3-4ba9-b450-29b6dace4bcf', 'HORSE_LEASE_SIMPLE', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Venue', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('256cf108-b075-4b06-9605-a0c17b588ddb', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.IDENTITY', 'Horse Details', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Current fair market value: {{HORSE.FAIR_MARKET_VALUE}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3e469ecb-01b5-4d33-8ff2-d9d9fc04e97c', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.OWNERSHIP', 'Ownership of the Horse', 'Lessor warrants that Lessor lawfully owns the Horse — whether owned outright, financed without any restriction that prohibits or limits leasing the Horse, or owned jointly with one or more other owners — and that Lessor has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and lease the Horse.', 'input', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('88554764-d3e4-43f5-80e6-53f9c0e56fbb', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.COOWNERS', NULL, 'Co-owners: {{TXN.CO_OWNERS}}', 'input', 22, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1f36f80f-e4cb-4e3f-9bae-a33f7193acc7', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.OWNERSHIP_LIMITS_Q', NULL, 'Are there any ownership related leasing restrictions? {{TXN.HAS_OWNERSHIP_LIMITS}}', 'input', 25, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('78f6b7e0-2445-47f9-b181-215bd9a32fb1', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.OWNERSHIP_LIMITS', NULL, 'Ownership related leasing restrictions: {{TXN.OWNERSHIP_LIMITATIONS}}', 'input', 26, true, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_OWNERSHIP_LIMITS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e243d96b-e62c-4d0c-bd2c-3ae84ac55025', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.BEHAVIOR', 'Behavior', 'The Lessor warrants that the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement.', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('98d7c62e-4a73-48e8-a3ed-d5f0d47dd316', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.BEHAVIOR_EXC', NULL, 'The Lessor notes the following known exceptions to the behavior of the Horse: {{TXN.BEHAVIOR_EXCEPTIONS}}', 'input', 32, true, NULL, '{"equals": ["YES"], "field_key": "TXN.BEHAVIOR_HAS_EXCEPTIONS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ae8af3a9-5849-4d67-af3a-c37f23ea3747', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.CONDITION', 'Physical Condition', 'The Lessor warrants that the Horse is sound and in good physical condition as of the Effective Date of this Agreement.', 'input', 40, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('15b0c107-3c99-4683-ad72-ffc9b515ecab', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.CONDITION_EXC', NULL, 'The Lessor notes the following known exceptions to the physical condition of the Horse: {{TXN.CONDITION_EXCEPTIONS}}', 'input', 42, true, NULL, '{"equals": ["YES"], "field_key": "TXN.CONDITION_HAS_EXCEPTIONS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('299e8599-0e70-4ed1-b74f-a421e74b34d8', 'HORSE_LEASE_SIMPLE', 'EVALUATION', 'EVALUATION.DATES_FIXED', 'Evaluation Period Details', 'Lessee shall have an evaluation period of {{TXN.EVAL_FIXED_LENGTH}} {{TXN.EVAL_FIXED_UNIT}} beginning on the date this Agreement is fully signed by both parties. The evaluation period fee is {{TXN.EVAL_FIXED_FEE}}, is earned upon commencement of the evaluation period, and is nonrefundable. Either party may terminate this Agreement during the evaluation period by written notice to the other party. Upon such termination, any per-use or lease fees for usage that occurred remain due, and neither party owes the other any further amount under this Agreement except amounts already accrued.', 'input', 21, true, NULL, '{"all": [{"equals": ["REQUESTED", "REQUIRED"], "field_key": "TXN.EVALUATION_ENABLED"}, {"equals": ["FIXED"], "field_key": "TXN.EVAL_PERIOD_TYPE"}, {"gte": 1, "field_key": "TXN.EVAL_FIXED_LENGTH"}]}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2e1d3de3-3493-4213-a4f8-e8d2e9f2bf2c', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.JUMP_OFF', NULL, 'Lessor does not restrict jumping activity in any way.', 'input', 322, false, NULL, '{"all": [{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.JUMP_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a2c77d79-588a-4fdc-b776-7a90474afadd', 'HORSE_LEASE_SIMPLE', 'PAYMENT_METHOD', 'PAYMENT_METHOD.CARD_LESSOR', NULL, 'Credit card payments are processed as follows: {{TXN.LESSOR_CARD_PROCESSOR}}', 'input', 40, false, NULL, '{"contains": ["CREDIT_CARD"], "field_key": "TXN.LESSOR_PAYMENT_METHODS"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7b968a33-872d-4e7d-a418-0bd2913c7393', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.TRAIL_TITLE', 'Trail-Riding Restrictions', '{{TXN.TRAIL_OMIT}}', 'input', 330, false, NULL, '{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4bc86225-94f2-4f7c-88e1-56ff0021bb48', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.TRAIL_ON', NULL, 'Trail riding is restricted as follows: {{TXN.TRAIL_RESTRICTION}}', 'input', 331, true, NULL, '{"all": [{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["YES"], "field_key": "TXN.TRAIL_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fe5549c2-f0d4-4a99-ab5f-c16b38ada196', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'RESTRICT.TRAIL_OFF', NULL, 'Lessor does not restrict trail-riding activity in any way.', 'input', 332, false, NULL, '{"all": [{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}, {"equals": ["NO", ""], "field_key": "TXN.TRAIL_OMIT"}]}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
