INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9f83e809-1582-4db0-a1ea-a966fbd3ec24', 'HORSE_LEASE_SIMPLE', 'HORSE', 'LOCATION.INSPECTION', NULL, 'Lessor may inspect the Horse at any time, subject to the reasonable access rules of the facility where the Horse is kept. If Lessor reasonably determines that the Horse is not being properly cared for, Lessor may take possession of the Horse upon written notice to Lessee.', 'prose', 59, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9da7bc33-8fd7-4178-8bea-f335d1fe1b5d', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations expressly stated in this Agreement, LESSOR MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.', 'prose', 60, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c13f79c8-5e04-407e-ab97-81c2266019f1', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.INSURANCE', 'Insurance Requirements', 'The parties agree to the insurance elections set forth below. Each policy elected or required below shall be maintained in effect for the duration of this Agreement.', 'prose', 100, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6237caf9-d465-439c-9d68-e53a078235a2', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.GENERAL_LIABILITY', 'General Liability Insurance', '', 'input', 150, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4a39b854-f415-4140-bae7-7c97d8e3977c', 'HORSE_LEASE_SIMPLE', 'HORSE', 'HORSE.INJURY_HISTORY_DISCLOSED', 'Rider and Other Serious Injuries', 'Lessor discloses that one or more persons have suffered serious injury involving the direct actions of the Horse, as follows, including for each incident the approximate date, the circumstances, the Horse''s actions, and the nature of the injury: {{TXN.INJURY_HISTORY_DETAILS}}. Lessee acknowledges this disclosure and proceeds with knowledge of it.', 'input', 45, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INJURY_HISTORY"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3936e8f7-fa89-4734-8e61-b7ef01bff69b', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PROHIBITED.OTHER', 'Other Allowed Activities', 'Lessee is permitted to engage in the following additional activities with the Horse: {{TXN.ADDITIONAL_ACTIVITIES}}', 'input', 450, true, NULL, '{"contains": ["BREEDING", "EMOTIONAL_SUPPORT", "FILM_TV_AD", "OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('db24d482-6ae6-4501-b610-b88225611dc2', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PROHIBITED.OTHER_NONE', 'Other Allowed Activities', 'Lessee is not permitted to engage in any activities with the Horse beyond the permitted uses stated above.', 'input', 455, false, NULL, '{"equals": ["", "NONE"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('aa5a15f4-8dd6-4c7b-9a93-e5c0918bf0be', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PROHIBITED.OTHER_NOTE', NULL, 'Other additional permitted activity: {{TXN.ADDITIONAL_ACTIVITIES_OTHER}}', 'input', 460, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('64e5ab8a-59d7-4db6-af71-52304fc29ce8', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PROHIBITED.OTHERS', 'Allowing Others to Ride', 'The following additional persons may ride or handle the Horse without Lessor''s prior permission: {{TXN.OTHERS_ALLOWED}}.
Only the persons identified above shall be permitted to ride or handle the Horse without Lessor''s written permission.', 'input', 480, true, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('53c8fd27-5365-4da4-bc17-6978a3adb7d6', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MORTALITY', 'Mortality Insurance', '', 'input', 200, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ce956688-87f1-4872-b650-c56b76599214', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PROHIBITED.OTHERS_OTHER', NULL, 'Other persons allowed to ride or handle the Horse:
{{TXN.OTHERS_ALLOWED_OTHER}}', 'input', 490, false, NULL, '{"contains": ["OTHER"], "field_key": "TXN.OTHERS_ALLOWED"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('deceac17-2068-4aa3-ba20-52ab11a7957f', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PERMITTED_USE.RELEASES_REQUIRED', 'Releases Required for Authorized Riders', 'All persons other than Lessee must, prior to handling or riding the Horse, have executed a liability release that names the Lessor Parties and the Lessee Parties as released parties, contains an express assumption of the inherent risks of equine activities, has been reviewed and approved by Lessor, and, for any rider under 18 years of age, is signed by the rider''s parent or legal guardian. Lessee is responsible for ensuring this requirement is satisfied before permitting any authorized person to ride or handle the Horse.', 'prose', 495, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ce77b0ee-5853-4ed9-a6bd-5665f6ff1588', 'HORSE_LEASE_SIMPLE', 'PAYMENT_TERMS', 'PAYMENT_TERMS.OFFSET', 'Right of Offset', 'A party to whom money is owed under this Agreement may offset the amount owed against any amount that party owes to the other party.', 'prose', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b96d62dc-4529-4c3e-acb4-b237c7837d04', 'HORSE_LEASE_SIMPLE', 'PAYMENT_TERMS', 'PAYMENT_TERMS.RECEIPTS', 'Receipts', 'A party seeking reimbursement for an expense paid on behalf of the other party shall provide a receipt or other reasonable documentation of the expense as a condition of reimbursement.', 'prose', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('946c17ac-5e50-428f-bb23-b022fc365418', 'HORSE_LEASE_V3', 'PERMITTED_USE', 'PERMITTED_USE.TRANSPORT', 'Transport of the Horse', 'Transport of the Horse to offsite locations (other than for medical care, which is always permitted): {{TXN.OFFSITE_TRANSPORT}}
For clarity, riding trails attached to the location at which the Horse is kept under this Agreement are not offsite locations. Where Competitions are a permitted activity under this Agreement, transport of the Horse to and from the competition venue for that competition is deemed consented, subject to any competition restrictions stated in this Agreement.', 'input', 500, true, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5cfde90b-0788-43a4-9487-a35e9cca79d8', 'HORSE_LEASE_V3', 'PURPOSE', 'PURPOSE.RECREATION_DEFAULT', 'Purpose of Agreement', '[Pending — select the purpose of this lease. This placeholder is replaced by the applicable purpose language and blocks signing.]', 'input', 5, false, NULL, '{"equals": [""], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1601e442-c24f-4122-8274-7aa64adaa9d7', 'HORSE_LEASE_V3', 'PURPOSE', 'PURPOSE.RECREATION', 'Purpose of Agreement', 'For {{TXN.LEASE_PURPOSE}} purposes, Lessee wishes to ride and/or handle Lessor''s horse, and Lessor agrees to allow Lessee to ride and/or handle Lessor''s horse in exchange for the consideration described herein.', 'prose', 10, false, NULL, '{"equals": ["RECREATIONAL", "INSTRUCTIONAL", "COMPETITION", "COMMERCIAL"], "field_key": "TXN.LEASE_PURPOSE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('03509f31-9fff-4cd6-9002-a71df9e1ac46', 'HORSE_LEASE_V3', 'PURPOSE', 'PURPOSE.GRANT', 'Lease Grant', 'Subject to the terms and conditions of this Agreement, Lessor agrees to lease to Lessee and Lessee agrees to lease from Lessor the horse described below.', 'prose', 15, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c561b80b-27a8-45db-b8dc-11b51edaa995', 'HORSE_LEASE_V3', 'PURPOSE', 'PURPOSE.LEASE_TYPE', 'Lease Type', 'Lease type: {{TXN.LEASE_TYPE}}', 'input', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
