INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9be5e4de-f0d1-47c8-babd-5615c4240c98', 'HORSE_LEASE_V3', 'SCHEDULE', 'SCHEDULE.CHANGES', 'Schedule Changes', 'Any changes to the agreed upon schedule must be made and accepted in writing.', 'prose', 15, false, NULL, '{"equals": ["PARTIAL"], "field_key": "TXN.LEASE_TYPE"}', NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('61dba999-98da-4ced-9bcf-2eebb4d2d4af', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.MEDICAL', 'Medical Insurance', '', 'input', 300, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e8f5227d-0a0f-4ba2-bce2-9790bf7ae6d9', 'HORSE_LEASE_V3', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('739aa5c7-eca9-4858-ae0d-becad416f694', 'HORSE_LEASE_V3', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

LESSEE
Signature: {{SIG.LESSEE.NAME}}
Printed Name: {{LESSEE.PRINTED_NAME}}
Date: {{SIG.LESSEE.DATE}}

LESSOR (OWNER)
Signature: {{SIG.LESSOR.NAME}}
Printed Name: {{LESSOR.PRINTED_NAME}}
Date: {{SIG.LESSOR.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
