INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('96f15d5a-da41-4c72-8137-bf3864bc0eba', 'HORSE_LEASE_V3', 'TERM', 'TERM.MAIN', 'Agreement Term', 'Term of this Agreement: {{TXN.LEASE_TERM_TYPE}}. This Agreement begins on {{TXN.LEASE_START}}', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
