INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fc4fdf12-cfd0-4df4-8f74-93d09231c656', 'HORSE_LEASE_SIMPLE', 'PERMITTED_USE', 'PROHIBITED.OTHER_NOTE', NULL, 'Other additional permitted activity: {{TXN.ADDITIONAL_ACTIVITIES_OTHER}}', 'input', 460, true, NULL, '{"contains": ["OTHER"], "field_key": "TXN.ADDITIONAL_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2f2d63ba-81b3-4241-9e9e-adfe8cf55fa4', 'HORSE_LEASE_V3', 'TERM', 'TERM.ADDITIONAL', NULL, 'Additional terms: {{TXN.ADDITIONAL_TERMS}}', 'input', 22, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cc8b5466-5ab8-4348-b9ad-1656967a570f', 'HORSE_LEASE_V3', 'TERM', 'TERM.TERMINATION_XREF', NULL, 'Notwithstanding the term stated above, this Agreement may be terminated earlier as provided in the Termination section of this Agreement.', 'prose', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e214a810-5bc3-44c6-ab82-8a3e2ede7e4d', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.LESSEE', 'Lessee''s Right to Terminate', 'Lessee may terminate this Agreement by giving Lessor at least {{TXN.LESSEE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5d51e46b-7b02-4b2b-b5b5-13e73be8f363', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.OWNER', 'Owner''s Right to Terminate', 'Lessor may terminate this Agreement by giving Lessee at least {{TXN.OWNER_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cb86fe60-e403-48f2-8a5b-d42a8d72bee9', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.CAUSE', 'Termination for Cause', 'Either party may terminate this Agreement for cause (including a material breach that remains uncured) by giving the other party at least {{TXN.CAUSE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f921c904-85d5-4b55-b6ed-110521cd4cf6', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.LOSS', 'Self-Termination upon Loss or Injury', 'This Agreement shall self-terminate if the Horse is significantly injured or seriously ill as determined by a licensed veterinarian, or dies. Lessee is entitled to a prorated refund of Lease Fee paid for the remaining time unused at the time of self-termination. In the event Lessee is found to have caused, through gross negligence, reckless conduct, or intentional misconduct, the injury, illness, or death, Lessor may retain the unused portion of the paid Lease Fee.', 'prose', 40, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a40b44c3-ce5f-4a3b-941a-2a444ee6c5ee', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.LOSS_OF_USE', 'Termination upon Loss of Use', 'If the Horse becomes unusable for the purposes of this Agreement for any reason, Lessee may terminate this Agreement immediately upon written notice to Lessor. Upon such termination, Lessee is entitled to a prorated refund of any Lease Fee paid for the remaining unused time as of the date of termination.', 'prose', 45, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2e063fe9-21da-4143-b71f-50c56e2098f6', 'HORSE_LEASE_V3', 'TERMINATION', 'TERMINATION.SURVIVAL', 'Survival', 'The releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement, and any payment obligations accrued before termination, survive the expiration or termination of this Agreement for any reason.', 'prose', 50, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fc834639-8228-44e9-a814-a42b06083fb8', 'HORSE_SALE_V3', 'ASSIGNMENT', 'ASSIGNMENT.NO_ASSIGN', 'Assignment', 'Neither party shall assign this Agreement or any of its rights or obligations under it without the other party''s prior written consent.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('90e84896-0def-48ac-8d56-87ba3f3914ff', 'HORSE_SALE_V3', 'ATTORNEYS_FEES', 'ATTORNEYS_FEES.PREVAILING', 'Attorneys'' Fees', 'Each party shall cover their own attorney''s fees and costs.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9b48101d-497b-4674-9d3d-6334c233da2b', 'HORSE_SALE_V3', 'DEFAULT', 'DEFAULT.CURE', 'Default and Cure', 'A party in material breach of this Agreement has 10 days after written notice of the breach to cure it, except that no cure period applies to Buyer''s failure to complete the purchase after all conditions precedent are satisfied or waived, which is governed by the Deposit clause where a Deposit applies.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('054de3de-8a12-4740-87eb-ed4af62cb906', 'HORSE_SALE_V3', 'DEFAULT', 'DEFAULT.SELLER', 'Seller Default', 'If Seller fails to complete the sale after all conditions precedent are satisfied or waived, Buyer is entitled to a full refund of the Deposit and all other amounts paid, and, because the Horse is unique, Buyer may alternatively seek specific performance of this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fd8e126d-41b3-4bc6-a80d-dcc048aae450', 'HORSE_SALE_V3', 'DEFAULT', 'DEFAULT.INSTALLMENTS', 'Buyer Default Under Installments', 'If Seller retakes possession of the Horse following Buyer''s uncured installment default, Seller shall, within 60 days, elect either to retain the Horse and refund amounts paid in excess of the greater of the Deposit and 20 percent of the Purchase Price, or to resell the Horse in a commercially reasonable manner and account to Buyer for any amount received in excess of the unpaid balance plus Seller''s reasonable costs of retaking, keeping, and reselling the Horse.', 'prose', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('eca656f1-0474-4934-a9f2-50e7536aab08', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.RISK_OF_LOSS', 'Risk of Loss of or Injury to the Horse', 'Lessor assumes all risk of loss of or injury to the Horse during the term of this Agreement, except to the extent caused by Lessee''s gross negligence, reckless conduct, or intentional misconduct.', 'input', 500, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f928508a-8f9e-4c9c-a4c5-77b4ba04e7fa', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.LOSS_OF_USE_ACK', 'Loss of Use', 'Lessor acknowledges and accepts that loss of use of the Horse may result from injury to, illness of, or the death of the Horse. No loss-of-use insurance is required or provided under this Agreement.', 'prose', 550, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dbee43c4-f4e7-4473-96c9-ffc3d1918cf5', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Lessee understands that horseback riding and handling horses are inherently dangerous activities. Lessee acknowledges that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. Lessee acknowledges the California common law doctrine of "Primary Assumption of Risk," as established by the California Supreme Court in Knight v. Jewett (1992) 3 Cal.4th 296 and subsequent equine-specific case law (e.g., Levinson v. Owens (2009) 176 Cal.App.4th 1534). Consistent with this precedent, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, expressly and voluntarily assumes all inherent risks associated with riding or handling the Horse, and acknowledges that no Lessor Party owes a duty to protect Lessee from these inherent risks.', 'prose', 950, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bf4a987a-6276-4e9d-8d02-b5a65ce0de1d', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE', 'Release of Liability', 'In consideration for being permitted to handle or ride the Horse, Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, completely releases, forever discharges, and agrees to hold harmless the Lessor Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessee''s use, handling, or riding of the Horse, whether caused by the ordinary negligence of any Lessor Party or otherwise. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 960, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d022ea68-1a93-4a6c-b283-5196d66d99aa', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.RELEASE_LESSOR', 'Release of Liability by Lessor', 'In consideration of the mutual promises in this Agreement, Lessor, on behalf of Lessor and anyone claiming by, through, or under Lessor, completely releases, forever discharges, and agrees to hold harmless the Lessee Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Lessor''s riding or handling of the Horse or Lessor''s presence at any facility where the Horse is kept during the term of this Agreement, whether caused by the ordinary negligence of any Lessee Party or otherwise. Lessor expressly and voluntarily assumes all inherent risks of equine activities in connection with such riding, handling, or presence. This release does not apply to gross negligence, reckless conduct, or intentional misconduct.', 'prose', 961, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('78f898b8-5f2d-4d63-b92f-0bd51c649b7a', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.SAFETY_ATTIRE', 'Required Protective Attire', 'Lessee shall wear, and shall ensure that any other person riding the Horse under Lessee''s authorization wears, an appropriately fitted and securely fastened ASTM/SEI-certified equestrian helmet at all times while mounted on the Horse, together with heeled boots and long pants; gloves and long sleeves are highly recommended. Riders shall provide their own helmet, boots, and pants meeting these requirements unless otherwise agreed in writing. Lessee, on behalf of Lessee and anyone claiming by, through, or under Lessee, assumes all increased risk of injury or death resulting from any failure to wear the required attire. Any refusal or failure to wear an approved helmet or the other required attire immediately revokes permission to ride or handle the Horse and constitutes a material breach of this Agreement.', 'prose', 1100, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('560b7f38-94bc-48f3-8bd6-6952af5c4117', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.TRAIL_RIDING', 'Trail Riding Risks', 'Lessee acknowledges that riding outside an enclosed arena, including trail riding, exposes Lessee and the Horse to additional risks, including uneven terrain, traffic, wildlife, water crossings, and other conditions that may cause the Horse to spook or behave unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'prose', 1200, false, NULL, '{"contains": ["TRAIL"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0598d566-eb20-43b5-a04f-a4345239e343', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.JUMPING_RISKS', 'Jumping Risks', 'Lessee acknowledges that jumping the Horse exposes Lessee and the Horse to additional risks beyond flat riding, including refusals, run-outs, awkward or missed distances, falls, unseating, and the Horse landing, stopping, or twisting unpredictably. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1210, false, NULL, '{"contains": ["JUMPING"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9c1efbe6-494d-4ba9-8a3b-07fc439aebbb', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.COMPETITION_RISKS', 'Competition Risks', 'Lessee acknowledges that competing with the Horse exposes Lessee and the Horse to additional risks, including unfamiliar and crowded show grounds, proximity to other horses and riders, loudspeakers, banners, and other stimuli that may cause the Horse to spook or behave unpredictably, as well as the physical demands and pressures of competition. Lessee voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1220, false, NULL, '{"contains": ["COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('df2519d6-a187-4749-9463-26809752c496', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.SELLER_IND', NULL, '"Seller Parties" means Seller; Seller''s spouse and family and household members, in each case when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Seller''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3cc7ae6f-5a59-4a34-99cc-bbeb3be183f6', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.SHARED_ARENA_RISKS', 'Shared Arena Riding Risks', 'Lessee acknowledges that riding in an arena at the same time as other riders exposes Lessee and the Horse to additional risks, including collisions, crowding, sudden movements or loss of control by other horses or riders, and the Horse reacting to other horses. Lessee agrees to ride with awareness of others, to follow standard arena etiquette and right-of-way rules and any directions of Lessor or an instructor, and voluntarily assumes these and any other unforeseen or unspecified additional risks related to this activity.', 'input', 1230, false, NULL, '{"contains": ["ARENA_GROUP"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f6be9131-7d62-4231-ac8c-ba8b74944d4e', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement.', 'prose', 1300, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5bbd64d9-a6eb-4ad9-9c34-c3eacebcdb4b', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.INDEMNIFICATION', 'Mutual Indemnification', 'Each party shall indemnify, defend, and hold harmless the other party and, respectively, the Lessor Parties or the Lessee Parties, from and against any and all claims, damages, losses, liabilities, costs, and expenses arising out of the indemnifying party''s use, handling, care, or possession of the Horse, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'input', 1400, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fd0b0699-4df9-40b1-9b1c-db945a72f382', 'HORSE_LEASE_SIMPLE', 'INSURANCE_RISK', 'INSURANCE_RISK.LIMITATION', 'Limitation of Liability', 'Under no circumstances shall either party be liable to the other for any special, consequential, incidental, or punitive damages arising out of or relating to this Agreement. The total aggregate liability of either party (including, respectively, the Lessor Parties and the Lessee Parties) to the other under this Agreement shall not exceed the Horse''s current fair market value of {{HORSE.FAIR_MARKET_VALUE}}. Any amount owed by one party to the other under this Agreement shall be reduced by the amount of any insurance proceeds actually received by the party owed with respect to the same loss. This limitation does not apply to gross negligence, reckless conduct, or intentional misconduct, to either party''s indemnification obligations for third-party claims for bodily injury or death, or to amounts actually covered by insurance available for the loss.', 'prose', 1520, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('843dee4d-6db9-4f7a-aefb-d52ade7a333d', 'HORSE_LEASE_SIMPLE', 'LESSEE_REPS', 'LESSEE_REPS.PENDING', 'Lessee''s Representations', '[Pending — select whether Lessee is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 5, false, NULL, '{"equals": [""], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ca418afb-c9ae-4011-8a5f-1d0d3f64e698', 'HORSE_LEASE_SIMPLE', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_INDIVIDUAL', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is at least 18 years of age and has full authority to enter into this Agreement; that Lessee has no physical or mental condition that would prevent Lessee from safely participating in the activities contemplated by this Agreement; and that Lessee has the requisite knowledge and experience to handle and ride the Horse, and will use reasonable care in doing so and follow Lessor''s instructions. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 10, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2c5c8f58-03ab-4470-8cc9-41bd4c013c2b', 'HORSE_LEASE_SIMPLE', 'LESSEE_REPS', 'LESSEE_REPS.MAIN_ENTITY', 'Lessee''s Representations', 'Lessee represents and warrants that Lessee is duly organized and in good standing, and has full authority to enter into this Agreement, and that the individual signing this Agreement does so as Lessee''s authorized representative; that each person who rides or handles the Horse under Lessee''s authorization will, before doing so, have executed the releases required under this Agreement and possess the knowledge and experience to handle and ride the Horse safely; and that Lessee will use reasonable care and follow Lessor''s instructions in all handling of the Horse. By signing this Agreement, Lessee acknowledges that Lessee has read this Agreement, fully understands its terms, and understands that Lessee is giving up substantial legal rights on behalf of Lessee and anyone claiming by, through, or under Lessee, including the right to sue the Lessor Parties.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "LESSEE.PARTY_TYPE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0bb04092-7b01-44d6-9f77-39414965fffc', 'HORSE_LEASE_SIMPLE', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b913b417-6ee8-4c4c-8584-082e500ecf43', 'HORSE_LEASE_SIMPLE', 'NOTICE', 'NOTICE.LESSEE_ADDRESS', 'Lessee', 'Name: {{LESSEE.FULL_NAME}}
Address: {{LESSEE.ADDRESS}}
Phone: {{LESSEE.PHONE}}
Email: {{LESSEE.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('15d3b436-5ddc-4fd7-9838-5bdd7e5c9519', 'HORSE_LEASE_SIMPLE', 'NOTICE', 'NOTICE.LESSOR_ADDRESS', 'Lessor', 'Name: {{LESSOR.FULL_NAME}}
Address: {{LESSOR.ADDRESS}}
Phone: {{LESSOR.PHONE}}
Email: {{LESSOR.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ead8a487-af81-48c8-8b17-339a0432d23b', 'HORSE_LEASE_SIMPLE', 'NOTICE', 'NOTICE.CHANGES', 'Changes in Contact Information', 'Each party shall promptly notify the other party in writing of any change in the party''s address or contact information.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('60fe40fe-d6d1-4c79-af80-79486c0da34f', 'HORSE_LEASE_SIMPLE', 'PARTIES', 'PARTIES.INTRO', NULL, 'This Horse Lease Agreement (the "Agreement") is made effective as of {{DOC.EFFECTIVE_DATE}} by and between {{LESSOR.FULL_NAME}} of {{LESSOR.ADDRESS}} ("Lessor") and {{LESSEE.FULL_NAME}} of {{LESSEE.ADDRESS}} ("Lessee").', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('00d0a113-0ea1-4b1d-8639-92a8de969d87', 'HORSE_LEASE_SIMPLE', 'PAYMENT_METHOD', 'PAYMENT_METHOD.MAIN', 'Payments by the Lessee', 'The Lessee may pay amounts owed under this Agreement by the following method(s): {{TXN.PAYMENT_METHODS}}', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b6783c34-80c7-4e7e-bba5-0387edb9f8ab', 'HORSE_LEASE_SIMPLE', 'PAYMENT_TERMS', 'PAYMENT_TERMS.LATE', 'Late Payments', 'All payments are due on their due date or within 5 business days of notification of the amount owed. Payments will be deemed late if they remain unpaid on the 6th business day. Late payments are considered a breach of the contract terms and may be grounds for termination of the Agreement unless the party from whom the payment is owed has communicated in writing the date by which payment will be made. Payments exceeding 1 calendar month in past-due status constitute grounds for termination for cause under the Termination for Cause provisions of this Agreement unless prior written acceptance of the delay is provided by the party to whom the payment is owed.', 'input', 40, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c7f30f96-162c-46a4-9e04-f15110ead968', 'HORSE_LEASE_SIMPLE', 'PERMITTED_USE', 'PERMITTED_USE.MAIN', 'Permitted Use(s)', 'Lessor grants Lessee the right to use the Horse for the following purpose(s): {{TXN.PERMITTED_ACTIVITIES}}
Lessee shall not use the Horse for any other purpose without Lessor''s prior written consent.', 'input', 100, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('636d45fd-5fac-4225-a3c8-7dbeb0305e7d', 'HORSE_LEASE_SIMPLE', 'PERMITTED_USE', 'PERMITTED_USE.TRAINER', NULL, 'Riding Lessons, Jumping, and Competitions may take place only while a French Heritage Equestrian Approved Trainer or Instructor is present.', 'input', 200, false, NULL, '{"contains": ["LESSONS", "JUMPING", "COMPETITIONS"], "field_key": "TXN.PERMITTED_ACTIVITIES"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
