INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1d66792e-d41b-412a-b592-0433645ce3da', 'HORSE_LEASE_SIMPLE', 'TERM', 'TERM.RENEWAL', 'Renewal Terms', 'Renewal terms: {{TXN.RENEWAL_TERMS}}', 'input', 19, false, NULL, '{"equals": ["YES"], "field_key": "TXN.RENEWAL_INCLUDE"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5104b035-fba5-49f1-81c8-2e5bda7931ef', 'HORSE_LEASE_SIMPLE', 'TERM', 'TERM.ADDITIONAL', NULL, 'Additional terms: {{TXN.ADDITIONAL_TERMS}}', 'input', 22, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5806902f-2594-41bb-b176-af914016a972', 'HORSE_LEASE_SIMPLE', 'TERM', 'TERM.TERMINATION_XREF', NULL, 'Notwithstanding the term stated above, this Agreement may be terminated earlier as provided in the Termination section of this Agreement.', 'prose', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b33309b8-a1fd-423c-8bb1-0e0a0c5eb129', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.LESSEE', 'Lessee''s Right to Terminate', 'Lessee may terminate this Agreement by giving Lessor at least {{TXN.LESSEE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 10, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d213fe86-8628-4786-96a1-99e0190bd741', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.OWNER', 'Owner''s Right to Terminate', 'Lessor may terminate this Agreement by giving Lessee at least {{TXN.OWNER_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 20, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6409968e-9df8-44c3-a2c4-a6ea8290bd40', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.CAUSE', 'Termination for Cause', 'Either party may terminate this Agreement for cause (including a material breach that remains uncured) by giving the other party at least {{TXN.CAUSE_TERM_NOTICE_DAYS}} days'' prior written notice.', 'input', 30, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('6fc757b3-8ac5-4ef8-a786-a6149531ac1b', 'HORSE_LEASE_SIMPLE', 'PERMITTED_USE', 'PROHIBITED.OTHERS_OTHER', NULL, 'Other persons allowed to ride or handle the Horse:
{{TXN.OTHERS_ALLOWED_OTHER}}', 'input', 490, false, NULL, '{"contains": ["OTHER"], "field_key": "TXN.OTHERS_ALLOWED"}', NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b251240e-49c6-4507-9b84-66590f18b95b', 'HORSE_LEASE_V3', 'INSURANCE_RISK', 'GL_LESSOR_COVERAGE_PENDING', NULL, '[Pending — select the Lessor''s general liability coverage. This placeholder is replaced by the applicable term and blocks signing.]', 'input', 147, false, NULL, '{"equals": [""], "field_key": "TXN.GL_LESSOR_COVERAGE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('24f170ef-5653-493d-801b-d4f6f4e2afe4', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.LOSS', 'Self-Termination upon Loss or Injury', 'This Agreement shall self-terminate if the Horse is significantly injured or seriously ill as determined by a licensed veterinarian, or dies. Lessee is entitled to a prorated refund of Lease Fee paid for the remaining time unused at the time of self-termination. In the event Lessee is found to have caused, through gross negligence, reckless conduct, or intentional misconduct, the injury, illness, or death, Lessor may retain the unused portion of the paid Lease Fee.', 'prose', 40, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10d6b542-3d09-4c47-801a-924de711156b', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.LOSS_OF_USE', 'Termination upon Loss of Use', 'If the Horse becomes unusable for the purposes of this Agreement for any reason, Lessee may terminate this Agreement immediately upon written notice to Lessor. Upon such termination, Lessee is entitled to a prorated refund of any Lease Fee paid for the remaining unused time as of the date of termination.', 'prose', 45, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d3602747-7bb5-489a-a75d-598267839ee2', 'HORSE_LEASE_SIMPLE', 'TERMINATION', 'TERMINATION.SURVIVAL', 'Survival', 'The releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement, and any payment obligations accrued before termination, survive the expiration or termination of this Agreement for any reason.', 'prose', 50, false, NULL, NULL, NULL, '2026-08-07 13:33:56.990982-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('56ad9947-5209-4637-8b42-0ede587035df', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.SELLER_ENT', NULL, '"Seller Parties" means Seller; Seller''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Seller and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('83ddab86-0ee9-432f-83fc-63734c68d0b0', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.SELLER_PENDING', NULL, '[Pending — select whether Seller is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 30, false, NULL, '{"equals": [""], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b5091b26-8d5a-4803-aca1-ff6de71bf5cf', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.BUYER_IND', NULL, '"Buyer Parties" means Buyer; Buyer''s spouse and family and household members, in each case when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and Buyer''s estate, executors, administrators, legal representatives, successors, and assigns.', 'prose', 40, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f05f1821-14a9-4b41-9742-2ee363670379', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.BUYER_ENT', NULL, '"Buyer Parties" means Buyer; Buyer''s parent, subsidiary, and affiliated entities; the owners, principals, proprietors, partners, members, managers, officers, directors, employees, trainers, instructors, agents, contractors, and volunteers of Buyer and of each such entity, together with the family members of any such natural person when handling, caring for, transporting, riding, or otherwise involved with the Horse or the activities contemplated by this Agreement; and the successors and assigns of each of the foregoing.', 'prose', 50, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8c243512-0637-463f-8f5e-323660991ed5', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.BUYER_PENDING', NULL, '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable definition and blocks signing.]', 'prose', 60, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('982ed10a-37a1-4872-bb3e-0899d5a83ac7', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.CLOSING', NULL, '"Closing" means the moment at which both of the following have occurred: Seller''s receipt of the Purchase Price in full (or, where installment payment applies, receipt of all amounts due at transfer under the installment terms), and delivery of the Horse to Buyer as provided in this Agreement.', 'prose', 70, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e82f24a2-4e17-4417-943e-d3dfd3f43107', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.BINDING', NULL, 'Each release, waiver, assumption of risk, and covenant made by a party under this Agreement is made by that party on its own behalf and, to the fullest extent permitted by law, binds anyone claiming by, through, or under that party, including that party''s estate, executors, administrators, heirs, legal representatives, successors, assigns, insurers, and subrogees. Each party covenants that it will not permit any person who has not executed this Agreement or a release approved by the other party to ride, handle, or care for the Horse prior to Closing, and each party shall indemnify, defend, and hold harmless the other party''s Seller Parties or Buyer Parties, as applicable, from and against any claim brought by that party''s family members, invitees, or authorized riders arising out of the Horse or the activities contemplated by this Agreement, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of an indemnified party.', 'prose', 80, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4179781a-8899-40f7-8906-c3d3781eee4a', 'HORSE_SALE_V3', 'DEFINITIONS', 'DEFINITIONS.BENEFICIARIES', NULL, 'Each Seller Party and each Buyer Party who is not a signatory to this Agreement is an intended third-party beneficiary of the releases, waivers, assumptions of risk, indemnities, and limitations of liability in this Agreement and may enforce them directly.', 'prose', 90, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4e5ea8e3-ac11-4c56-996c-2f53ea4f0e14', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.TERMS', 'Delivery', 'The Horse shall be delivered to Buyer at {{TXN.DELIVERY_LOCATION}} on or about {{TXN.DELIVERY_DATE}}.', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f8d96ad0-34cb-43aa-9d8a-511c97130b7c', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.DELAYS', NULL, 'If Buyer fails to take delivery within 7 days of the agreed date other than due to Seller''s delay, Buyer shall pay board and care for the Horse at {{TXN.BOARD_RATE_AFTER}} per day until delivery occurs. If Seller delays delivery by more than 7 days, Seller shall pay {{TXN.SELLER_DELAY_PENALTY}} penalty to Buyer per day until delivery occurs.', 'prose', 12, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', true, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3d73ddb0-aa8e-4e87-a9b6-62177e7e9bfa', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.TITLE_RISK', 'Transfer of Title and Risk', 'Title to the Horse passes to Buyer at Closing (or, where installment payment applies, as provided in the Installment Terms), and risk of loss of or injury to the Horse passes to Buyer upon the passing of title. Upon Closing, this executed Agreement, together with the executed Bill of Sale, constitutes the instruments of transfer for the Horse, and Seller shall execute any additional transfer document reasonably required by a breed registry, microchip registry, or passport authority.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('73448e85-74a8-4a2a-b273-e9ba8872f2a8', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.PAPERS', 'Registration and Transfer Documents', 'At Closing (or, where installment payment applies, upon payment in full), Seller shall deliver to Buyer the Horse''s registration papers, passport, and any transfer forms required to record the change of ownership, executed by Seller where signature is required. Each party shall cooperate to complete breed registry, microchip registry, and passport transfers promptly, with recording fees paid by {{TXN.TRANSFER_FEES_RESPONSIBLE}}.', 'input', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('31805e50-43b7-41a8-8864-ebe85b7b559a', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.NO_SLAUGHTER', 'No-Slaughter Covenant', 'Buyer covenants that Buyer will not sell, transfer, consign, or deliver the Horse, directly or through intermediaries, for slaughter or for human consumption, whether within or outside California, and will not sell or transfer the Horse at auction without commercially reasonable steps to ensure the Horse is not being acquired for slaughter. The parties acknowledge that California Penal Code Section 598c makes it unlawful to possess, import, export, sell, or transfer a horse with the intent that it be killed for human consumption. This covenant survives Closing and binds Buyer''s successors in interest to the extent permitted by law.', 'prose', 40, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('774a2443-4b72-4655-a9e5-a9b84ed2c5b0', 'HORSE_SALE_V3', 'DELIVERY', 'DELIVERY.NO_SLAUGHTER_ACK', NULL, '{{TXN.NO_SLAUGHTER_ACK}}', 'input', 45, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('549e9ade-46cb-461a-a5ae-1baf4ac90b31', 'HORSE_SALE_V3', 'ENTIRE_AGREEMENT', 'ENTIRE_AGREEMENT.INTEGRATION', 'Entire Agreement', 'This Agreement contains the entire agreement between the parties with respect to its subject matter and supersedes all prior discussions, advertisements, and understandings, and Buyer acknowledges that Buyer is not relying on any statement or representation regarding the Horse that is not stated in this Agreement. Any modification of this Agreement must be in writing and signed by all parties.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1e4db0d1-3c05-4dd8-a408-1ddc1961f1d8', 'HORSE_SALE_V3', 'GOVERNING_LAW', 'GOVERNING_LAW.CHOICE', 'Governing Law and Dispute Resolution', 'This Agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Any dispute arising out of or relating to this Agreement or the Horse shall be resolved by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, or another administrator the parties agree to in writing, with arbitrator fees and administrative costs allocated as those rules provide. Either party may bring a qualifying claim in small claims court, and either party may seek provisional or injunctive relief, including recovery of possession of the Horse, in a court of competent jurisdiction without waiving arbitration. Judgment on the award may be entered in any court having jurisdiction.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('de25928f-41d2-45b2-b799-31a808e73318', 'HORSE_SALE_V3', 'HORSE', 'HORSE.IDENTITY', 'Horse', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn Name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Height: {{HORSE.HEIGHT}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}
Current Location: {{HORSE.CURRENT_LOCATION}}', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('10d7b622-d78d-4bf8-a14f-543d893290fc', 'HORSE_SALE_V3', 'HORSE', 'HORSE.OWNERSHIP', 'Title and Ownership', 'Seller warrants that Seller lawfully owns the Horse, holds good and marketable title to the Horse, free and clear of all liens, security interests, leases, breeding contracts, co-ownership interests, and encumbrances except as expressly disclosed in this Agreement, and has all requisite rights, authority, and (where there are co-owners) permission to enter into this Agreement and sell the Horse.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3bfe4d5b-5b43-45ed-b63c-29e4db3c562f', 'HORSE_SALE_V3', 'HORSE', 'HORSE.ENCUMBRANCES_GATE', NULL, '', 'prose', 25, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a735ba17-7606-441f-9098-85ba1b42aa01', 'HORSE_SALE_V3', 'HORSE', 'HORSE.ENCUMBRANCES', 'Disclosed Encumbrances and Interests', 'Seller discloses the following liens, leases, co-ownership interests, or other encumbrances affecting the Horse, each of which will be released or satisfied at or before Closing unless expressly stated otherwise: {{TXN.DISCLOSED_ENCUMBRANCES}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.HAS_ENCUMBRANCES"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bcf39991-94e7-4abb-9809-a2a26261c587', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.TRAINER_EVAL_LESSEE_AT_LESSOR', NULL, 'Lessee has requested a suitability evaluation of the Horse by a professional trainer of Lessee''s choosing, at Lessor''s cost,{{TXN.TRAINER_TIMING}}. Lessor shall make the Horse reasonably available for the evaluation. If the evaluation finds the Horse unsuitable for Lessee''s intended use in Lessee''s reasonable discretion, Lessee may terminate this Agreement by written notice to Lessor, and neither party has any further obligation to the other{{TXN.TRAINER_FEE_PHRASE}}.', 'input', 222, false, NULL, '{"equals": ["LESSEE_AT_LESSOR"], "field_key": "TXN.TRAINER_EVAL_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a48e41fd-0a3a-4a5e-979e-3082b6edff59', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.TRAINER_EVAL_LESSOR_FREE', NULL, 'Lessor will provide, at no cost to Lessee, a suitability evaluation of the Horse for Lessee''s intended use by a French Heritage Equestrian Approved Trainer{{TXN.TRAINER_TIMING}}. If the evaluation finds the Horse unsuitable for Lessee''s intended use in Lessee''s reasonable discretion, Lessee may terminate this Agreement by written notice to Lessor, and neither party has any further obligation to the other{{TXN.TRAINER_FEE_PHRASE}}.', 'input', 223, false, NULL, '{"equals": ["LESSOR_FREE"], "field_key": "TXN.TRAINER_EVAL_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('20200444-f3ee-4097-872a-4fca13ff19f4', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.TRAINER_EVAL_WAIVED', NULL, 'Lessee has been offered the opportunity to have the Horse evaluated by a professional trainer and knowingly and voluntarily waives it. Lessee accepts the Horse''s training and temperament as observed and assumes the risk of unsuitability an evaluation might have revealed. This waiver does not limit Lessee''s rights arising from the disclosures and representations stated in this Agreement, or Lessee''s rights to terminate this Agreement as stated in the Termination section.', 'input', 224, false, NULL, '{"equals": ["WAIVED"], "field_key": "TXN.TRAINER_EVAL_CHOICE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('05a0e185-aa03-4fbc-a9ca-48814c2b8c9f', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_GATE', NULL, '', 'input', 120, false, NULL, NULL, NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7884c8b1-34d4-4ed8-bcbd-a29a7494e0a2', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_NONE', NULL, 'Seller represents that, to Seller''s knowledge, no person has been seriously injured by the direct actions of the Horse. This representation does not extend to any incident caused primarily by a third party or an external stimulus, such as another horse or rider being at fault, a loose dog, wildlife, or a vehicle, where the Horse''s reaction was within the range of normal equine behavior.', 'input', 121, false, NULL, '{"equals": ["NO"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f37d7be3-fd8e-40ee-a8b2-7baa6670dad5', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BREEDING_GATE', NULL, '', 'prose', 191, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('aa622cd1-f5ce-4ef4-aaa5-02f896b013f0', 'HORSE_SALE_V3', 'NOTICE', 'NOTICE.FORM', 'Form of Notice', 'Any notice required or permitted under this Agreement shall be in writing and delivered by a method that provides evidence of receipt to the party at the contact information below. Notice by email is not effective unless the receiving party acknowledges receipt.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e72d00d6-6c21-4291-b96b-e9e4604fabbc', 'HORSE_SALE_V3', 'NOTICE', 'NOTICE.SELLER_ADDRESS', 'Seller', 'Name: {{SELLER.FULL_NAME}}
Address: {{SELLER.ADDRESS}}
Phone: {{SELLER.PHONE}}
Email: {{SELLER.EMAIL}}', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8148bee9-627b-46e2-a0a4-0751a69e6f5c', 'HORSE_SALE_V3', 'NOTICE', 'NOTICE.BUYER_ADDRESS', 'Buyer', 'Name: {{BUYER.FULL_NAME}}
Address: {{BUYER.ADDRESS}}
Phone: {{BUYER.PHONE}}
Email: {{BUYER.EMAIL}}', 'prose', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ae67079b-0c13-4dce-bf8a-062c0fd679a4', 'HORSE_SALE_V3', 'NOTICE', 'NOTICE.CHANGES', 'Changes in Contact Information', 'Each party shall promptly notify the other party in writing of any change in the party''s address or contact information.', 'prose', 40, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('154d58f6-f818-4403-b06d-774cb2a8d8b3', 'HORSE_SALE_V3', 'PARTIES', 'PARTIES.INTRO', NULL, 'This Horse Sale and Purchase Agreement (the "Agreement") is made effective as of {{DOC.EFFECTIVE_DATE}} by and between {{SELLER.FULL_NAME}} of {{SELLER.ADDRESS}} ("Seller") and {{BUYER.FULL_NAME}} of {{BUYER.ADDRESS}} ("Buyer").', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4d047c63-033f-4e87-b167-aedf2bd0b5a5', 'HORSE_SALE_V3', 'PARTIES', 'PARTIES.CO_BUYER_GATE', NULL, '', 'prose', 15, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9d7808e8-5e5b-407c-8cae-eb706b6ae8ce', 'HORSE_SALE_V3', 'PARTIES', 'PARTIES.CO_BUYER', 'Co-Buyer', '{{COBUYER.FULL_NAME}} of {{COBUYER.ADDRESS}} ("Co-Buyer") purchases the Horse jointly with Buyer. Co-Buyer is a Buyer for all purposes of this Agreement, every reference to Buyer includes Co-Buyer, and the representations, covenants, releases, waivers, and payment obligations of Buyer under this Agreement are made by Buyer and Co-Buyer jointly and severally. Buyer and Co-Buyer shall hold title to the Horse as follows: {{TXN.CO_BUYER_TITLE_FORM}}. This Agreement is effective as to Co-Buyer upon Co-Buyer''s execution of it.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3aba375d-74f4-4543-b442-9d3c8a2df9c2', 'HORSE_SALE_V3', 'PARTIES', 'PARTIES.CO_BUYER_TITLE_DETAIL', NULL, 'Title detail: {{TXN.CO_BUYER_TITLE_DETAIL}}', 'input', 40, false, NULL, '{"any": [{"equals": ["TIC_STATED"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}, {"equals": ["OTHER"], "field_key": "TXN.CO_BUYER_TITLE_FORM"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('56c007fb-0c9f-4bfd-ac21-71046be275e5', 'HORSE_SALE_V3', 'PPE', 'PPE.CHOICE_GATE', NULL, '', 'prose', 5, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2bbbc626-6b15-46ad-9d65-c475d20fc916', 'HORSE_SALE_V3', 'PPE', 'PPE.CONDUCTED', 'Pre-Purchase Examination', 'Buyer may, at Buyer''s sole cost, have the Horse examined by a licensed veterinarian of Buyer''s choosing{{TXN.PPE_TIMING}} {{TXN.PPE_DEADLINE}}. Seller shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request.', 'input', 10, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["DATE"], "field_key": "TXN.PPE_TIMING"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('20532df6-d027-42e7-8ccf-291bf09d33a6', 'HORSE_SALE_V3', 'PPE', 'PPE.CONDUCTED_EVAL', 'Pre-Purchase Examination', 'Buyer may, at Buyer''s sole cost, have the Horse examined by a licensed veterinarian of Buyer''s choosing{{TXN.PPE_TIMING}}. Seller shall disclose the Horse''s known medical history to the examining veterinarian on request.', 'input', 10, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["EVAL_PERIOD"], "field_key": "TXN.PPE_TIMING"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('cd544be5-51ce-468a-9afd-805b04278d7f', 'HORSE_SALE_V3', 'PPE', 'PPE.CONDUCTED_PRIOR', 'Pre-Purchase Examination', 'Buyer may, at Buyer''s sole cost, have the Horse examined by a licensed veterinarian of Buyer''s choosing{{TXN.PPE_TIMING}}. Seller shall make the Horse reasonably available for the examination and shall disclose the Horse''s known medical history to the examining veterinarian on request.', 'input', 10, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["PRIOR_DELIVERY"], "field_key": "TXN.PPE_TIMING"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('dbd7c88d-6b75-441f-8604-eb89ea400d44', 'HORSE_SALE_V3', 'PPE', 'PPE.CONTINGENCY', 'Sale Contingent on Examination', 'This sale is contingent on a pre-purchase examination whose results are satisfactory to Buyer in Buyer''s reasonable discretion. If the Buyer gives Seller written notice that the examination results are not satisfactory, this Agreement terminates, the Deposit is refunded in full, and neither party has further obligation to the other except obligations that expressly survive.', 'input', 20, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["YES"], "field_key": "TXN.PPE_CONTINGENT"}, {"equals": ["YES"], "field_key": "TXN.DEPOSIT_ENABLED"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('f97fff67-e58f-40b3-ad36-d71f775b21eb', 'HORSE_SALE_V3', 'PPE', 'PPE.CONTINGENCY_NODEP', 'Sale Contingent on Examination', 'This sale is contingent on a pre-purchase examination whose results are satisfactory to Buyer in Buyer''s reasonable discretion. If the Buyer gives Seller written notice that the examination results are not satisfactory, this Agreement terminates, and neither party has further obligation to the other except obligations that expressly survive.', 'input', 20, false, NULL, '{"all": [{"equals": ["BUYER_REQUESTED"], "field_key": "TXN.PPE_CHOICE"}, {"equals": ["YES"], "field_key": "TXN.PPE_CONTINGENT"}, {"equals": ["NO"], "field_key": "TXN.DEPOSIT_ENABLED"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a214bbf1-bb8e-4a19-a404-edc855d6450f', 'HORSE_SALE_V3', 'PPE', 'PPE.NA', NULL, 'No pre-purchase veterinary examination applies to this sale.', 'prose', 25, false, NULL, '{"equals": ["SELLER_DECLINES"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ecf93611-d9bc-44a0-ad3a-f1acc314eb17', 'HORSE_SALE_V3', 'PPE', 'PPE.WAIVED', 'Examination Waived', 'Buyer has been advised to obtain an independent pre-purchase veterinary examination of the Horse and knowingly and voluntarily waives it. Buyer accepts the Horse without such examination and assumes all risk associated with conditions an examination might have revealed. This waiver does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 30, false, NULL, '{"equals": ["BUYER_WAIVED"], "field_key": "TXN.PPE_CHOICE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('db1f526e-eecb-434a-9006-3d57ad933fe6', 'HORSE_SALE_V3', 'PRICE', 'PRICE.AMOUNT', 'Purchase Price', 'The purchase price for the Horse is {{TXN.PURCHASE_PRICE}} (the "Purchase Price").', 'input', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4d073d7f-19c8-47de-b8b0-a9069fe6f657', 'HORSE_SALE_V3', 'PRICE', 'PRICE.DEPOSIT_GATE', NULL, '', 'prose', 15, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5eadc2b2-cdfa-465b-a0e7-4afe8ac1e514', 'HORSE_SALE_V3', 'PRICE', 'PRICE.DEPOSIT', 'Deposit', 'Buyer shall pay a deposit of {{TXN.DEPOSIT_AMOUNT}} (the "Deposit") upon execution of this Agreement. The Deposit is applied against the Purchase Price at Closing. If this Agreement terminates because a condition precedent stated in this Agreement fails (including an unsatisfactory pre-purchase examination where the sale is contingent on one, a financing contingency that fails where one is included, or a trial period return in accordance with this Agreement), the Deposit is refunded to Buyer in full within 5 business days. If Buyer fails to complete the purchase for any other reason, the parties agree that Seller''s actual damages would be impracticable or extremely difficult to determine, that the Deposit is a reasonable estimate of those damages, and that Seller may retain the Deposit as liquidated damages as Seller''s sole monetary remedy for that failure.', 'input', 20, false, NULL, '{"equals": ["YES"], "field_key": "TXN.DEPOSIT_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('16ab8bfb-a54d-4c7c-8e76-8b94b0238313', 'HORSE_SALE_V3', 'PRICE', 'PRICE.PAYMENT_METHOD', 'Payment Method', 'The Purchase Price shall be paid by the following method(s): {{TXN.PAYMENT_METHODS}}. Payment is not received until funds are actually and irrevocably credited to Seller.', 'input', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('023c941c-2135-40d0-8b7a-69b68731bf3a', 'HORSE_SALE_V3', 'PRICE', 'PRICE.INSTALLMENTS_GATE', NULL, '', 'prose', 35, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3e8bdde8-ff57-4fec-8784-de1393fa5528', 'HORSE_SALE_V3', 'PRICE', 'PRICE.FULL_PAYMENT', 'Payment in Full at Transfer', 'The Purchase Price, less any Deposit already paid, is due in full at or before delivery of the Horse. Seller is not obligated to deliver the Horse or any registration or transfer documents until the Purchase Price is received in full.', 'prose', 40, false, NULL, '{"equals": ["NO"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b539da95-3c15-4447-b7aa-e60a96e08471', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_DISCLOSED', NULL, 'Seller discloses that one or more persons have been seriously injured by the direct actions of the Horse.', 'input', 122, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('aa17ae37-cd6c-49d3-9f70-0dcabb00b742', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_UNKNOWN', NULL, 'Seller has no knowledge of whether any person has been seriously injured by the direct actions of the Horse.', 'input', 123, false, NULL, '{"equals": ["UNKNOWN"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('da8c3ccf-5c39-4fa2-ae27-589f0d77f616', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_DISCLOSED_ACK', NULL, 'Buyer acknowledges the injuries to a person disclosed above and proceeds with knowledge of it. Initialed: {{ACK.INJURIES_TO_HUMANS}}', 'input', 124, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5708e718-d2b2-458f-b72a-460c261b8860', 'HORSE_SALE_V3', 'HORSE', 'HORSE.INJURIES_TO_HUMANS_DISCLOSED_ACK_CB', NULL, 'Co-Buyer acknowledges the injuries to a person disclosed above and proceeds with knowledge of it. Initialed: {{ACK.INJURIES_TO_HUMANS_COBUYER}}', 'input', 125, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HUMANS_GATE"}, {"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bceb88c8-cdb5-47fa-9701-60ac6fb1aacb', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BEHAVIORAL_HISTORY_GATE', NULL, '', 'input', 130, false, NULL, NULL, NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('bd6e524c-31ce-4a20-b551-34aac5267d06', 'HORSE_SALE_V3', 'PRICE', 'PRICE.INSTALLMENTS', 'Installment Terms', 'The Purchase Price is payable in installments as follows: {{TXN.INSTALLMENT_SCHEDULE}}. Until the Purchase Price is paid in full: title to the Horse remains with Seller and Buyer holds possession under this Agreement only; Buyer grants Seller a purchase-money security interest in the Horse and its registration papers to secure the unpaid balance, and authorizes Seller to file a financing statement; Buyer shall not sell, lease, encumber, breed, or relocate the Horse from {{TXN.INSTALLMENT_LOCATION}} without Seller''s prior written consent; and Buyer bears all costs of the Horse''s care. Seller bears the risk of loss of the Horse''s value while Seller holds title and may, in Seller''s sole discretion, maintain insurance on the Horse in an amount not less than the unpaid balance. Neither party is obligated under this Agreement to maintain such insurance, and any obligation of Seller to insure the Horse must be set out in a separate written agreement. If the Horse dies or is injured before title passes to Buyer, Buyer is entitled to the return of all amounts paid to Seller and may decline to complete the purchase, in which case Seller returns to Buyer all amounts paid and Buyer returns possession of the Horse to Seller. If Buyer fails to make a payment when due and does not cure within 10 days of written notice, Seller may retake possession of the Horse, and amounts already paid are subject to the default and remedies provisions of this Agreement. Registration and transfer documents are delivered upon payment in full.', 'input', 50, false, NULL, '{"equals": ["YES"], "field_key": "TXN.INSTALLMENTS_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('39f426db-05be-475a-9ca9-cfb553b2508f', 'HORSE_SALE_V3', 'PRICE', 'PRICE.FINANCING', 'Financing Contingency', 'This sale is contingent on Buyer obtaining financing for not less than {{TXN.FINANCING_AMOUNT}} on terms reasonably acceptable to Buyer on or before {{TXN.FINANCING_DEADLINE}}. Buyer shall pursue financing diligently and in good faith. If Buyer gives Seller written notice on or before that date that financing could not be obtained, this Agreement terminates, the Deposit (if any) is refunded in full, and neither party has further obligation to the other except obligations that expressly survive. If no such notice is given by that date, this contingency is deemed waived.', 'input', 70, false, NULL, '{"equals": ["INCLUDED"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('07376429-77c3-4137-a42c-d7a8221416a4', 'HORSE_SALE_V3', 'PRICE', 'PRICE.TAXES', 'Taxes', 'Any sales, use, or similar transfer tax arising from this sale is the responsibility of {{TXN.SALES_TAX_RESPONSIBLE}}. Each party is otherwise responsible for its own tax obligations arising from this transaction.', 'input', 90, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('16ddc1a1-fa5d-4edd-b96c-e93ca3c586fa', 'HORSE_SALE_V3', 'PURPOSE_SALE', 'PURPOSE_SALE.MAIN', 'Purpose of Agreement', 'Seller owns the horse described in this Agreement and desires to sell it, and Buyer desires to purchase it, on the terms and conditions of this Agreement.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('4775656e-1f56-4295-95c6-1f2b3a5de7c8', 'HORSE_SALE_V3', 'PURPOSE_SALE', 'PURPOSE_SALE.SALE', 'Agreement to Sell and Purchase', 'Subject to the terms and conditions of this Agreement, Seller agrees to sell, transfer, and convey the Horse to Buyer, and Buyer agrees to purchase the Horse from Seller, for the Purchase Price and on the terms stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d0127cd6-148a-4ede-b388-23c10f61fbba', 'HORSE_SALE_V3', 'REPS', 'REPS.SELLER', 'Seller''s Representations', 'Seller represents and warrants that Seller has full authority to enter into this Agreement, that the warranties of title and the disclosures stated in this Agreement are true and complete to Seller''s knowledge, and that Seller will promptly disclose any material change in the Horse''s health, soundness, or behavior arising before Closing.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e3abba82-36bf-4be6-a572-b91799ada56a', 'HORSE_SALE_V3', 'REPS', 'REPS.BUYER_IND', 'Buyer''s Representations', 'Buyer represents and warrants that Buyer is at least 18 years of age and has full authority to enter into this Agreement; that Buyer has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of Buyer''s choosing, and to ask questions about the Horse; and that Buyer has the knowledge and experience to evaluate the Horse''s suitability for Buyer''s intended use. By signing this Agreement, Buyer acknowledges that Buyer has read this Agreement, fully understands its terms, and understands that Buyer is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 20, false, NULL, '{"equals": ["INDIVIDUAL"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('a9d228f9-35f2-43ea-9e23-4a3f9603a0b2', 'HORSE_SALE_V3', 'REPS', 'REPS.BUYER_ENT', 'Buyer''s Representations', 'Buyer represents and warrants that it is duly organized and in good standing, that the person signing on its behalf is authorized to bind it, that it has had the opportunity to inspect the Horse, to have the Horse examined by a veterinarian of its choosing, and to ask questions about the Horse, and that it has the knowledge and experience, directly or through its personnel, to evaluate the Horse''s suitability for its intended use. By signing this Agreement, Buyer acknowledges that it has read this Agreement, fully understands its terms, and understands that it is giving up substantial legal rights on behalf of Buyer and anyone claiming by, through, or under Buyer, including the right to sue the Seller Parties.', 'prose', 30, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2c1c4dc0-2efc-4f0e-a3af-7d78f0283dcf', 'HORSE_SALE_V3', 'REPS', 'REPS.BUYER_PENDING', 'Buyer''s Representations', '[Pending — select whether Buyer is an individual or an entity. This placeholder is replaced by the applicable representations and blocks signing.]', 'prose', 40, false, NULL, '{"equals": [""], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fca761a5-47ad-4bf5-b72a-a0f3b2d2240f', 'HORSE_SALE_V3', 'RISK', 'RISK.ASSUMPTION_INHERENT', 'Assumption of Inherent Risks', 'Each party understands that horseback riding and handling horses are inherently dangerous activities, and that horses are unpredictable by nature and may buck, rear, bite, kick, spook, stumble, or otherwise react unpredictably to their environment, which can result in severe injury, paralysis, or death. In connection with any examination, trial, handling, riding, transport, or delivery of the Horse under this Agreement, each party, on behalf of itself and anyone claiming by, through, or under it, expressly and voluntarily assumes all inherent risks of equine activities, and acknowledges that the other party''s Seller Parties or Buyer Parties, as applicable, owe no duty to protect it from those inherent risks.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('daeaea11-e63a-415a-82fc-5eb0fd844d98', 'HORSE_SALE_V3', 'PRICE', 'PRICE.FINANCING_DECLINED', 'Financing Contingency Not Elected', 'This sale is not contingent on Buyer obtaining financing. The parties considered including a financing contingency and both elected not to include one.', 'prose', 80, false, NULL, '{"equals": ["NOT_CONDITIONAL"], "field_key": "TXN.FINANCING_ELECTION"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('b153dd0f-9b58-4999-8950-1c6043930abb', 'HORSE_SALE_V3', 'RISK', 'RISK.RELEASE_BUYER', 'Release by Buyer', 'Buyer, on behalf of Buyer and anyone claiming by, through, or under Buyer, completely releases, forever discharges, and agrees to hold harmless the Seller Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Buyer''s examination, trial, handling, riding, or transport of the Horse before Closing, whether caused by the ordinary negligence of any Seller Party or otherwise, and from any and all claims arising after Closing relating to the Horse''s condition, soundness, behavior, suitability, or value. This release does not apply to gross negligence, reckless conduct, intentional misconduct, fraud, or breach of the express representations and warranties stated in this Agreement.', 'prose', 20, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0dd44eb6-8d83-4aab-b4a6-0262561caa32', 'HORSE_SALE_V3', 'RISK', 'RISK.RELEASE_SELLER', 'Release by Seller', 'Seller, on behalf of Seller and anyone claiming by, through, or under Seller, completely releases, forever discharges, and agrees to hold harmless the Buyer Parties, to the fullest extent permitted by law, from any and all claims, demands, causes of action, liabilities, or damages for personal injury, property damage, or wrongful death arising out of Seller''s riding or handling of the Horse or Seller''s presence at any facility where the Horse is kept in connection with this Agreement, whether caused by the ordinary negligence of any Buyer Party or otherwise. This release does not apply to gross negligence, reckless conduct, intentional misconduct, or fraud.', 'prose', 30, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('21dccc41-af96-4849-aba8-392e237fa9f5', 'HORSE_SALE_V3', 'RISK', 'RISK.WAIVER_UNKNOWN', 'Waiver of Unknown Claims', 'Each party, on behalf of itself and anyone claiming by, through, or under it, expressly waives any and all claims released under this Agreement that the waiving party does not know or suspect to exist in its favor at the time of this Agreement. Each party acknowledges that it is familiar with, and expressly waives the protections of, California Civil Code Section 1542, which provides: "A general release does not extend to claims that the creditor or releasing party does not know or suspect to exist in his or her favor at the time of executing the release and that, if known by him or her, would have materially affected his or her settlement with the debtor or released party." Each party assumes the risk that claims presently unknown to it may later be discovered, and acknowledges that this waiver is a material term of this Agreement. This waiver does not apply to claims arising from fraud or from breach of the express representations and warranties stated in this Agreement.', 'prose', 40, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1783c444-547b-43bd-82e9-87821ae25fd5', 'HORSE_SALE_V3', 'RISK', 'RISK.POST_CLOSING', 'Post-Closing Responsibility', 'From and after Closing, the Horse and its actions, behavior, care, and condition are the sole responsibility of Buyer, and Buyer shall indemnify, defend, and hold harmless the Seller Parties from and against any claim, damage, loss, liability, cost, or expense arising out of the Horse or its use, handling, care, or possession after Closing, except to the extent caused by the gross negligence, reckless conduct, intentional misconduct, or fraud of a Seller Party or by breach of the express representations and warranties stated in this Agreement.', 'prose', 50, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('92901221-8d5a-47e1-a256-278f8300b34f', 'HORSE_SALE_V3', 'RISK', 'RISK.PRE_CLOSING', 'Pre-Closing Responsibility', 'Before Closing, and except as allocated to Buyer during any trial period, Seller shall indemnify, defend, and hold harmless the Buyer Parties from and against any third-party claim arising out of the Horse''s ownership, care, or condition, except to the extent caused by the gross negligence, reckless conduct, or intentional misconduct of a Buyer Party.', 'prose', 60, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d66b8b99-f0a6-45d0-b554-3c2dcc5dcbed', 'HORSE_SALE_V3', 'SEVERABILITY', 'SEVERABILITY.SAVING', 'Severability', 'If any provision of this Agreement is held to be invalid or unenforceable, the remaining provisions shall continue in full force and effect, and the invalid or unenforceable provision shall be deemed modified to the minimum extent necessary to make it valid and enforceable.', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('3b80f53a-828d-4ead-b733-907cc44951bb', 'HORSE_SALE_V3', 'SIGNATURES', 'SIGNATURES.BLOCK', 'Signatures', 'IN WITNESS WHEREOF, the parties have executed this Agreement as of the date first written above.

BUYER
Signature: {{SIG.BUYER.NAME}}
Printed Name: {{BUYER.PRINTED_NAME}}
Date: {{SIG.BUYER.DATE}}', 'prose', 10, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5c831e75-48f8-44f9-9e7c-d9203cefda3f', 'HORSE_SALE_V3', 'SIGNATURES', 'SIGNATURES.BUYER_CAPACITY', NULL, 'By: {{BUYER.ENTITY_SIGNER_NAME}}
Title: {{BUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{BUYER.FULL_NAME}}', 'input', 20, false, NULL, '{"equals": ["ENTITY"], "field_key": "BUYER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('300df3fc-cfeb-40b6-8550-45caed4d821c', 'HORSE_SALE_V3', 'SIGNATURES', 'SIGNATURES.COBUYER_BLOCK', NULL, 'CO-BUYER
Signature: {{SIG.COBUYER.NAME}}
Printed Name: {{COBUYER.PRINTED_NAME}}
Date: {{SIG.COBUYER.DATE}}', 'input', 30, false, NULL, '{"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('31490eb1-37c0-40ef-b122-fd1e9e773c25', 'HORSE_SALE_V3', 'SIGNATURES', 'SIGNATURES.COBUYER_CAPACITY', NULL, 'By: {{COBUYER.ENTITY_SIGNER_NAME}}
Title: {{COBUYER.ENTITY_SIGNER_TITLE}}
