INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('d9fff825-dfd1-415a-97ef-e4314fc2ad23', 'HORSE_SALE_V3', 'SIGNATURES', 'SIGNATURES.SELLER_CAPACITY', NULL, 'By: {{SELLER.ENTITY_SIGNER_NAME}}
Title: {{SELLER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{SELLER.FULL_NAME}}', 'input', 60, false, NULL, '{"equals": ["ENTITY"], "field_key": "SELLER.PARTY_TYPE"}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('0012c57b-7abb-43bf-8757-f2ffa443a9f3', 'HORSE_SALE_V3', 'TRIAL', 'TRIAL.GATE', NULL, '', 'prose', 5, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('588eb13f-a35b-4c5c-a474-c175a8ebdd71', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BEHAVIORAL_HISTORY_NONE', NULL, 'Seller represents that, to Seller''s knowledge, the Horse has no adverse behaviors to disclose as of the Effective Date.', 'input', 131, false, NULL, '{"equals": ["NO"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}', NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2b7cd253-3f4b-4045-bbc5-cd7407171dbe', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BEHAVIORAL_HISTORY_DISCLOSED', NULL, 'Seller discloses the following adverse behaviors, with all known information relating to description, trigger, and current status or date of last occurrence, as follows:
{{HORSE.BEHAVIORAL_HISTORY}}', 'input', 132, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}', NULL, '2026-10-20 04:28:15.492028-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('01d48126-4d91-4110-82cb-3e51aae4b62d', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BEHAVIORAL_HISTORY_DISCLOSED_ACK', NULL, 'Buyer acknowledges the behavior disclosed above and proceeds with knowledge of it. Initialed: {{ACK.BEHAVIORAL_HISTORY}}', 'input', 133, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('764d8bee-b1ba-4060-b681-5a02cc790e42', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BEHAVIORAL_HISTORY_DISCLOSED_ACK_CB', NULL, 'Co-Buyer acknowledges the behavior disclosed above and proceeds with knowledge of it. Initialed: {{ACK.BEHAVIORAL_HISTORY_COBUYER}}', 'input', 134, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}, {"equals": ["YES"], "field_key": "TXN.CO_BUYER_ENABLED"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('fc50f7dc-581b-4298-9218-afae371ec45b', 'HORSE_SALE_V3', 'TRIAL', 'TRIAL.TERMS_CURRENT', 'Trial Period', 'Buyer may keep and ride the Horse on trial from {{TXN.TRIAL_START}} to {{TXN.TRIAL_END}} at the Horse''s current location.
Current Location: {{TXN.TRIAL_LOCATION}}
Board and care costs borne by: {{TXN.TRIAL_BOARD_COST}}
Buyer shall use the Horse only for ordinary riding and evaluation consistent with the Horse''s training and shall not compete, breed, transport offsite (other than for veterinary care, which is always permitted), or permit third parties to ride the Horse without Seller''s written consent, and Buyer assumes all risk of injury to persons arising from the Horse during the trial period as provided in the Risk, Release, and Indemnification section of this Agreement. Seller bears the risk of loss of the Horse while Seller holds title. If the Horse dies or is injured before Closing, Buyer is entitled to the return of all amounts paid to Seller and may decline to complete the purchase by not executing the Bill of Sale, in which case Seller returns to Buyer all amounts paid and Buyer returns possession of the Horse to Seller. Nothing in this section limits Seller''s remedies for damage to the Horse caused by Buyer''s gross negligence, reckless conduct, or intentional misconduct. Unless written notice is given and approved by Seller, Buyer must return the Horse in substantially the condition received on or before {{TXN.TRIAL_END}} or execute this Agreement.', 'input', 10, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"equals": ["YES"], "field_key": "TXN.TRIAL_AT_CURRENT"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
