INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1352cfc1-2314-4974-aff9-bd88fb949dca', 'HORSE_LEASE_FULL', 'INSURANCE_RISK', 'INSURANCE_RISK.MED_TAIL', NULL, 'Any out-of-pocket costs for deductibles or other expenses related to the needs of the Horse are to be paid by Lessor, and where Lessee is deemed to be responsible for part or all of a cost paid by Lessor, Lessee shall reimburse Lessor in accordance with the acceptable payment methods stated in this Agreement, or, if Lessee so requests prior to payment by Lessor, Lessee may make such request to pay the billing party directly using a method allowed by that party. Lessee may, with Lessor''s written permission, pay for any or all of Lessor''s portion when paying the billing party directly, and Lessor may reimburse Lessee in accordance with the terms of this Agreement. Lessor assumes and is responsible for all risks and costs not paid or covered by any policy held by either party, including in the event a policy is not in effect at the time of the incident, an incident for which a claim is made is deemed not to be covered by a policy, a payment for a claim made for an incident that is covered by a policy is less than the actual cost incurred, or a claim made to a policy is denied for any reason, except as otherwise expressly allocated in this section or elsewhere in this Agreement.', 'input', 320, false, NULL, '{"all": [{"equals": ["CARRIES", "WILL_OBTAIN"], "field_key": "TXN.MORT_ELECTION"}, {"equals": ["YES"], "field_key": "TXN.MED_INCLUDED"}]}', NULL, '2026-08-07 13:33:56.990982-07', true, NULL);
