INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('1b9f05bc-2969-4234-acc1-e0fea56a6c62', 'HORSE_BILL_OF_SALE', 'BOS_DISCLOSURES', 'BOS_KNOWN_CONDITIONS_DISCLOSED', NULL, 'Seller has disclosed to Buyer all known material information regarding the Horse''s medical conditions (ongoing or episodic), lameness, allergies, vices, and prior veterinary concerns. Seller represents that these disclosures are true and complete to Seller''s knowledge as of the date of this Bill of Sale. The disclosed conditions are as follows:
{{HORSE.KNOWN_CONDITIONS}}', 'input', 152, false, NULL, '{"all": [{"equals": ["NO"], "field_key": "TXN.BOS_HAS_SALE_AGREEMENT"}, {"equals": ["YES"], "field_key": "HORSE.KNOWN_CONDITIONS_GATE"}]}', NULL, '2026-10-20 04:30:32.506834-07', false, NULL);
