INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('c6b409b2-90a2-4da1-ba13-80c71e3f5093', 'HORSE_LEASE_V3', 'HORSE', 'LOCATION.INSPECTION', NULL, 'Lessor may inspect the Horse at any time, subject to the reasonable access rules of the facility where the Horse is kept. If Lessor reasonably determines that the Horse is not being properly cared for, Lessor may take possession of the Horse upon written notice to Lessee.', 'prose', 204, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('e6ba6746-6733-4134-aef4-05aff34d4869', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.IDENTITY', 'Horse Details', 'This Agreement applies to the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Height: {{HORSE.HEIGHT}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Current fair market value: {{HORSE.FAIR_MARKET_VALUE}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}', 'input', 100, false, NULL, NULL, NULL, '2026-10-20 04:25:50.041445-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('9f7800e6-3729-43c6-8361-59418d7bb62b', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BREEDING', 'Breeding Warranty', 'Seller expressly warrants that, to Seller''s knowledge, the Horse is capable of breeding and free of any reproductive condition that would prevent it, as supported by the reproductive examination or records described here: {{TXN.BREEDING_BASIS}}. If a licensed veterinarian determines within {{TXN.BREEDING_CLAIM_WINDOW}} days after Closing that the Horse was incapable of breeding as of Closing due to a condition existing at Closing, Buyer''s exclusive remedy is, at Buyer''s election, return of the Horse in substantially the condition delivered for a refund of the Purchase Price, or a reduction of the Purchase Price agreed by the parties. This is the sole warranty regarding breeding and does not otherwise limit the Disclaimer of Warranties.', 'input', 192, false, NULL, '{"all": [{"any": [{"equals": ["Mare"], "field_key": "HORSE.SEX"}, {"equals": ["Stallion"], "field_key": "HORSE.SEX"}, {"equals": ["Colt"], "field_key": "HORSE.SEX"}, {"equals": ["Filly"], "field_key": "HORSE.SEX"}]}, {"equals": ["INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('11e86fea-8fa7-4ba2-a537-15ed6bbf6e23', 'HORSE_SALE_V3', 'HORSE', 'HORSE.BREEDING_DECLINED', 'Breeding Warranty Not Elected', 'No warranty of breeding soundness, fertility, or reproductive capacity is given or implied. The parties considered including a breeding warranty and both elected not to include one.', 'prose', 193, false, NULL, '{"all": [{"any": [{"equals": ["Mare"], "field_key": "HORSE.SEX"}, {"equals": ["Stallion"], "field_key": "HORSE.SEX"}, {"equals": ["Colt"], "field_key": "HORSE.SEX"}, {"equals": ["Filly"], "field_key": "HORSE.SEX"}]}, {"equals": ["NOT_INCLUDED"], "field_key": "TXN.BREEDING_ELECTION"}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('2c414340-3b0d-40d5-914a-3cce6a620749', 'HORSE_SALE_V3', 'HORSE', 'HORSE.WARRANTY', 'Disclaimer of Warranties', 'Except for the representations and warranties expressly stated in this Agreement, the Horse is sold AS IS, and SELLER MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE, and no warranty is made regarding the Horse''s future soundness, health, temperament, performance, suitability for any discipline or rider, or value. This disclaimer does not limit Buyer''s rights arising from the express representations in this Agreement or from fraud.', 'prose', 200, false, NULL, NULL, NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('763266fe-a4f9-4bf3-9855-7eff8bc2a5df', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.BEHAVIOR_EXC', 'Condition and Behavior', 'The Lessor warrants that the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement, except as disclosed in the Horse section of this Agreement.', 'input', 191, false, NULL, '{"equals": ["YES"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('5add0d1e-3239-4674-a292-3c5e7c3d413a', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.BEHAVIOR_PLAIN', 'Condition and Behavior', 'The Lessor warrants that the Horse has no history of dangerous or vicious behavior as of the Effective Date of this Agreement.', 'input', 190, false, NULL, '{"equals": ["NO"], "field_key": "HORSE.BEHAVIORAL_HISTORY_GATE"}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('ffb97525-e112-43e7-8521-437fdc4aa587', 'HORSE_LEASE_V3', 'HORSE', 'HORSE.CONDITION_EXC', NULL, 'The Lessor warrants that the Horse is sound and in good physical condition as of the Effective Date of this Agreement, except as disclosed in the Horse section of this Agreement.', 'input', 193, false, NULL, '{"any": [{"equals": ["YES"], "field_key": "HORSE.KNOWN_CONDITIONS_GATE"}, {"equals": ["YES"], "field_key": "HORSE.MEDICAL_HISTORY_GATE"}, {"equals": ["YES"], "field_key": "HORSE.INJURIES_TO_HORSE_GATE"}, {"equals": ["YES"], "field_key": "HORSE.MEDICATIONS_GATE"}]}', NULL, '2026-10-24 11:21:23.217861-07', true, NULL);
