INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('7d5d1cac-d398-46fa-9382-537d3ee51dbc', 'HORSE_SALE_V3', 'TRIAL', 'TRIAL.TERMS', 'Trial Period', 'Buyer may keep and ride the Horse on trial from {{TXN.TRIAL_START}} to {{TXN.TRIAL_END}} at {{TXN.TRIAL_LOCATION}}.
Board and care costs borne by: {{TXN.TRIAL_BOARD_COST}}
Buyer shall use the Horse only for ordinary riding and evaluation consistent with the Horse''s training and shall not compete, breed, transport offsite (other than for veterinary care, which is always permitted), or permit third parties to ride the Horse without Seller''s written consent, and Buyer assumes all risk of injury to persons arising from the Horse during the trial period as provided in the Risk, Release, and Indemnification section of this Agreement. Seller bears the risk of loss of the Horse while Seller holds title. If the Horse dies or is injured before Closing, Buyer is entitled to the return of all amounts paid to Seller and may decline to complete the purchase by not executing the Bill of Sale, in which case Seller returns to Buyer all amounts paid and Buyer returns possession of the Horse to Seller. Nothing in this section limits Seller''s remedies for damage to the Horse caused by Buyer''s gross negligence, reckless conduct, or intentional misconduct. Unless written notice is given and approved by Seller, Buyer must return the Horse in substantially the condition received on or before {{TXN.TRIAL_END}} or execute this Agreement.', 'input', 10, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"any": [{"equals": ["NO"], "field_key": "TXN.TRIAL_AT_CURRENT"}, {"equals": [""], "field_key": "TXN.TRIAL_AT_CURRENT"}]}]}', NULL, '2026-10-20 04:25:50.484194-07', false, NULL);
INSERT INTO public.contract_clause_defs (id, template_key, section_key, clause_key, heading, body, clause_type, sort_order, is_optional, cut_name, conditional_on, guidance, created_at, render_as_subitem, draft_body) VALUES ('8e2445d2-a901-40e6-b852-bd1a16ce7aec', 'HORSE_SALE_V3', 'TRIAL', 'TRIAL.TRANSPORT_GATE', NULL, '', 'input', 14, false, NULL, '{"all": [{"equals": ["YES"], "field_key": "TXN.TRIAL_ENABLED"}, {"equals": ["NO"], "field_key": "TXN.TRIAL_AT_CURRENT"}]}', NULL, '2026-10-24 11:21:23.217861-07', false, NULL);
