INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('966f8adb-af1a-4620-9ccd-f18fdc1490e9', NULL, 'PARTY', 'PHONE', '{{PARTY.PHONE}}', 'field', 'contacts', 'phone', false, false, true, 'Generic any-party phone. Unused by any live template — prefer the role-named token.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('d8ed2232-e452-4192-93bb-b43737000a00', NULL, 'PARTY', 'EMAIL', '{{PARTY.EMAIL}}', 'field', 'contacts', 'email', false, false, true, 'Generic any-party email. Unused by any live template — prefer the role-named token.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('cfad8a00-0198-48f2-974b-c3e5bc9bfe4a', NULL, 'PARTY', 'DOB', '{{PARTY.DOB}}', 'field', 'contacts', 'date_of_birth', false, false, true, 'Generic any-party date of birth (was meant for the minor sections). Unused by any live template — prefer PARTICIPANT.DOB.', '2026-07-02 20:01:19.284198-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4faa356c-d50f-46fa-99cb-23f0d847d848', NULL, 'CLIENT', 'RIDING_EXPERIENCE_YEARS', '{{CLIENT.RIDING_EXPERIENCE_YEARS}}', 'field', 'contacts', 'riding_experience_years', false, false, true, 'Years of riding experience the client attested, e.g. 12. Blank if never provided.', '2026-07-03 14:56:58.331851-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('915f30f8-40c2-4388-aedc-df0a25edd5d9', NULL, 'CLIENT', 'JUMP_EXPERIENCE', '{{CLIENT.JUMP_EXPERIENCE}}', 'field', 'contacts', 'jump_experience', false, false, true, 'The jumping experience and maximum height the client attested on their profile. Blank if never provided. Only meaningful on riding/jumper documents.', '2026-07-03 14:56:58.331851-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3d19ed69-d740-4e5c-8504-cea69a520b49', '66a4d669-efb4-47e0-8ce0-ffdb4c9bd0a7', 'ORG', 'PRINCIPALS', '{{ORG.PRINCIPALS}}', 'field', NULL, NULL, false, false, false, 'The named principals/owners line used in the releases. Fills from org settings key ORG / PRINCIPALS (seeded).', '2026-08-02 09:59:37.570742-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('78530769-8dfe-4ef4-ac41-c03cc84d3c88', '66a4d669-efb4-47e0-8ce0-ffdb4c9bd0a7', 'SIG', 'CLIENT.DATE', '{{SIG.CLIENT.DATE}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: replaced with the date the client signs. Stays as a visible placeholder until then — that is correct behavior on drafts.', '2026-08-02 09:59:37.570742-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('f7245b68-2e41-4631-9a2e-3332d1920dbf', '66a4d669-efb4-47e0-8ce0-ffdb4c9bd0a7', 'CLIENT', 'PRINTED_NAME', '{{CLIENT.PRINTED_NAME}}', 'field', NULL, NULL, false, false, false, 'The client''s name printed under a signature line. Identical output to CLIENT.FULL_NAME — the two names exist so signature blocks read as intended. Use this one in signature blocks.', '2026-08-02 09:59:37.570742-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('90881627-c5d3-48ce-be23-cc16b45c5b07', '66a4d669-efb4-47e0-8ce0-ffdb4c9bd0a7', 'SIG', 'CLIENT.NAME', '{{SIG.CLIENT.NAME}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: stays visible as a placeholder until the client signs, then is replaced with the signer''s name. Never filled at generation — a draft still showing {{SIG.CLIENT.NAME}} is correct behavior, not a defect.', '2026-08-02 09:59:37.570742-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('9a8dff1f-d024-4275-89ec-d00ca512b402', 'e49b1a01-e653-4250-9cdc-b0120593bf69', 'HORSE', 'MICROCHIP', '{{HORSE.MICROCHIP}}', 'field', NULL, NULL, false, false, false, 'The microchip id. Blank if not recorded.', '2026-08-02 09:59:37.873516-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('5a44988e-1eec-41f4-b95a-345248501ee3', NULL, 'DOC', 'DISPLAY_CODE', '{{DOC.DISPLAY_CODE}}', 'system', NULL, NULL, true, false, false, 'The document''s short human reference — e.g. "CTR-000101". On the company copy of an execution it falls back to the first eight characters of the document id, so it is never blank there. Blank elsewhere when the document has no code.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('e52f79ea-3a5c-4314-86f8-6c2cf7718a99', NULL, 'MSG', 'SENDER_NAME', '{{MSG.SENDER_NAME}}', 'system', NULL, NULL, true, false, false, 'Who submitted a website inquiry, raw, for the subject line — falls back to "A visitor" when they left the name blank. Use MSG.SENDER_NAME_HTML in the body.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('a9bf3985-621e-418e-b3ed-9310ba7ca15b', NULL, 'REQ', 'INTENT_HTML', '{{REQ.INTENT_HTML}}', 'system', NULL, NULL, true, false, false, 'The stated intent recorded with the inquiry — e.g. "book". Blank when not recorded.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3219417c-d3ea-40a9-83ed-07f4f54c7c12', NULL, 'DOC', 'REFERENCE_CODE', '{{DOC.REFERENCE_CODE}}', 'system', NULL, NULL, true, false, false, 'The first twelve characters of the execution hash, shown to a SIGNER as a tamper-evidence reference — e.g. "a1b2c3d4e5f6". Deliberately not the full hash: that is company-copy-only. Blank on a document with no execution hash.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('7f132de7-6c40-4f81-a4fd-a413f9d023c7', NULL, 'DOC', 'TITLE', '{{DOC.TITLE}}', 'system', NULL, NULL, true, false, false, 'The document''s title as stored — e.g. "Horse Lease Agreement". Insert raw; use DOC.TITLE_HTML where the surrounding email escapes it. Blank when the document has no title, which is why the templates that need a fallback word test DOC.HAS_TITLE first.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('39861999-6351-4192-85cc-fcdd78578044', NULL, 'DOC', 'PARTY_CAN_SUGGEST', '{{DOC.PARTY_CAN_SUGGEST}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: may this party suggest changes (but not make them)? Non-empty when they may. Only consult it when DOC.PARTY_CAN_EDIT_DEAL is blank; with both blank the party is read-only and reviews the terms as written.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('546ecb1a-1e13-4457-83e7-f1332e063e42', NULL, 'MSG', 'EXPIRES_ON', '{{MSG.EXPIRES_ON}}', 'system', NULL, NULL, true, false, false, 'The date an invitation link stops working, already written out — e.g. "Wednesday, August 20, 2026". Blank when the invitation carries no expiry, in which case the email says the link "expires soon" instead of naming a date.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('97a858f7-5df8-44f0-a533-011520585e27', NULL, 'DOC', 'INTEGRITY_HASH', '{{DOC.INTEGRITY_HASH}}', 'system', NULL, NULL, true, false, false, 'The FULL SHA-256 execution hash. COMPANY COPY ONLY — never put this in an email to a signer; they get DOC.REFERENCE_CODE instead. Blank on a document with no execution hash.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('477fd31e-905b-4cb0-a5fe-d85527fbd658', NULL, 'REQ', 'AVAILABILITY_HTML', '{{REQ.AVAILABILITY_HTML}}', 'system', NULL, NULL, true, false, false, 'The visitor''s proposed times as one line, entries separated by "; " — e.g. "2026-08-20 – 2026-08-22; Weekends". Blank when they proposed none.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('0e349913-f2d4-4e17-acf4-17e932f2f18a', NULL, 'REQ', 'EMAIL_HTML', '{{REQ.EMAIL_HTML}}', 'system', NULL, NULL, true, false, false, 'The visitor''s email address from the inquiry, HTML-escaped. Always present — an inquiry cannot be submitted without one.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3ec5c990-2be7-488c-b35a-e901af683071', NULL, 'REQ', 'ENTRY_LOCATION_HTML', '{{REQ.ENTRY_LOCATION_HTML}}', 'system', NULL, NULL, true, false, false, 'The page the visitor was on when they submitted — e.g. "/lessons". Useful for knowing what they had just read. Blank when not recorded.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3231a5ff-22cb-41e0-b1a8-0e1dc5e52935', 'e49b1a01-e653-4250-9cdc-b0120593bf69', 'SIG', 'CLIENT.NAME', '{{SIG.CLIENT.NAME}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: stays visible as a placeholder until the client signs, then is replaced with the signer''s name. Never filled at generation — a draft still showing {{SIG.CLIENT.NAME}} is correct behavior, not a defect.', '2026-08-02 09:59:37.873516-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('ad8e48b9-966a-4130-847b-4e299e6b7675', 'e49b1a01-e653-4250-9cdc-b0120593bf69', 'CLIENT', 'PRINTED_NAME', '{{CLIENT.PRINTED_NAME}}', 'field', NULL, NULL, false, false, false, 'The client''s name printed under a signature line. Identical output to CLIENT.FULL_NAME — the two names exist so signature blocks read as intended. Use this one in signature blocks.', '2026-08-02 09:59:37.873516-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('a94d7388-b4c8-410b-a006-65853c2de1a2', 'e49b1a01-e653-4250-9cdc-b0120593bf69', 'SIG', 'CLIENT.DATE', '{{SIG.CLIENT.DATE}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: replaced with the date the client signs. Stays as a visible placeholder until then — that is correct behavior on drafts.', '2026-08-02 09:59:37.873516-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('acc2ceb6-8e7e-45ce-8914-f2319c8906e4', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'DOC', 'EFFECTIVE_DATE', '{{DOC.EFFECTIVE_DATE}}', 'system', NULL, NULL, false, false, false, 'The date the document takes effect, written out — e.g. August 12, 2026. Uses the document''s effective date once set at execution; before that, the date it was created. Always prints a date.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('2abda179-d3e6-460b-9616-8ff25d62776d', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ORG', 'LEGAL_NAME', '{{ORG.LEGAL_NAME}}', 'field', NULL, NULL, false, false, false, 'The business''s legal/trade name: French Heritage Equestrian. Always fills, from Business Settings.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('e676ec54-790e-434a-8b8a-d82d1e8d55e1', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'CLIENT', 'FULL_NAME', '{{CLIENT.FULL_NAME}}', 'field', NULL, NULL, false, false, false, 'The client''s full name — first plus last, e.g. Mary Richardson. Renders the SAME value as CLIENT.PRINTED_NAME; use FULL_NAME in body text and PRINTED_NAME under signature lines.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('9bfb588c-a853-425f-b318-9efcfb773631', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'CLIENT', 'ADDRESS', '{{CLIENT.ADDRESS}}', 'field', NULL, NULL, false, false, false, 'The client''s mailing address on one line, e.g. 12 Main St, Carmel, CA 93923. Comes from the client''s contact record; blank if no address is on file or the document has no CLIENT party.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('7894829e-8aa6-489e-8697-cda32a987170', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'CLIENT', 'PHONE', '{{CLIENT.PHONE}}', 'field', NULL, NULL, false, false, false, 'The client''s phone number as recorded on their contact record. Blank if none is on file.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('9a87c1ff-8795-4e0e-ac5e-00e976b0b504', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'CLIENT', 'EMAIL', '{{CLIENT.EMAIL}}', 'field', NULL, NULL, false, false, false, 'The client''s email address. Blank if none is on file.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('475def17-25ac-41b0-9b95-0a928a0845e1', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'DIR', 'ROLE_TERM', '{{DIR.ROLE_TERM}}', 'field', NULL, NULL, false, false, false, 'The client''s role word — buyer, seller, owner, lessee or lessor — picked from the contract''s direction (who retained us + deal side). Blank without a contract.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('5fa90d68-f4e1-4023-8510-10f0ce781024', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'DIR', 'TARGET_TERM', '{{DIR.TARGET_TERM}}', 'field', NULL, NULL, false, false, false, 'What the search is looking for — a horse, a buyer, a lessee — picked from the contract''s direction. Used by the search retainer. Blank without a contract.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3a54d37a-808a-49ec-a0a3-a911295ec659', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'DIR', 'DIRECTION_TERM', '{{DIR.DIRECTION_TERM}}', 'field', NULL, NULL, false, false, false, 'The transaction word — purchase, sale or lease — picked from the template''s direction variants by who retained us and which side of the deal the contract records. Blank when the document has no contract behind it.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('cc473388-da15-443a-ba0f-b585af53f728', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'SEARCH_OBJECTIVE', '{{ENG.SEARCH_OBJECTIVE}}', 'field', NULL, NULL, false, false, false, 'Meant to carry the search objective statement on the search retainer — never wired, ALWAYS RENDERS BLANK today.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('62dfbeb8-b841-4a77-8b78-e1ffb5e1f752', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'DISCIPLINE', '{{ENG.DISCIPLINE}}', 'field', NULL, NULL, false, false, false, 'Meant to carry the riding discipline from a client intake that was never built — ALWAYS RENDERS BLANK today. Do not place until intake capture exists.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('ecd2250d-501b-4eb4-81b0-e4748fa90cf0', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'BREED_PREFERENCE', '{{ENG.BREED_PREFERENCE}}', 'field', NULL, NULL, false, false, false, 'Search parameter (breed preference) from intake that was never built — ALWAYS RENDERS BLANK today.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('0dd5812d-d248-4722-96de-c9339d861007', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'AGE_RANGE', '{{ENG.AGE_RANGE}}', 'field', NULL, NULL, false, false, false, 'Search parameter (age range) from intake that was never built — ALWAYS RENDERS BLANK today.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('91f2f121-232d-4387-8563-e626ae9668dc', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'HEIGHT_RANGE', '{{ENG.HEIGHT_RANGE}}', 'field', NULL, NULL, false, false, false, 'Search parameter (height range) from intake that was never built — ALWAYS RENDERS BLANK today.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('80c1eabc-dfba-4892-aebd-10f5f82a21c2', NULL, 'ORG', 'BRAND_NAME', '{{ORG.BRAND_NAME}}', 'system', NULL, NULL, true, false, false, 'The tenant''s display name, as it appears in the From line and in email prose — e.g. "French Heritage Equestrian". Comes from BRAND/NAME in the value registry. Blank only if no brand name is configured, which would also break the From header.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('975e5cf7-29c0-4cfa-b083-d26f788b8bf9', NULL, 'HORSE', 'LABEL', '{{HORSE.LABEL}}', 'system', NULL, NULL, true, false, false, 'The horse an evaluation report is about, as it should read to a person — e.g. "Beaumont de Cactai". Blank on a report with no horse attached, and every use is wrapped in {{#if HORSE.LABEL}} so the sentence still reads correctly without it.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('8e997cc7-1917-438f-9406-fee042be37d2', NULL, 'REQ', 'SUBJECT_HTML', '{{REQ.SUBJECT_HTML}}', 'system', NULL, NULL, true, false, false, 'The subject line the visitor typed, HTML-escaped. Blank when the form did not ask for one.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('69cc8a5b-4e59-465f-b1a6-1400dba421e6', NULL, 'DOC', 'TITLES', '{{DOC.TITLES}}', 'system', NULL, NULL, true, false, false, 'The list of document titles in a multi-document delivery, for {{#each DOC.TITLES}}<li>{{.}}</li>{{/each}}. Each item is a plain title string. Empty for a single-document email.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('402213cc-ac60-4807-993b-8c58ab4941d0', NULL, 'PARTY', 'GREETING_NAME', '{{PARTY.GREETING_NAME}}', 'system', NULL, NULL, true, false, false, 'The single name to greet the reader by — first name, or display name where that is what the account carries. Use as {{#if PARTY.GREETING_NAME}}Hi {{PARTY.GREETING_NAME}},{{else}}Hello,{{/if}}. Blank for a nameless contact, or when the email deliberately does not personalise (the executed-document copy is plain on purpose).', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('11842b3b-f068-45f7-9f34-ab8c924d3a43', NULL, 'MSG', 'NOTE_HTML', '{{MSG.NOTE_HTML}}', 'system', NULL, NULL, true, false, false, 'The reason a party gave when voiding a contract, HTML-escaped. Blank when they gave none, in which case the email says so plainly rather than leaving a silence.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4675b498-b044-4bd8-9a36-1e1d6a0f5a95', NULL, 'MSG', 'IS_GUARDIAN_COPY', '{{MSG.IS_GUARDIAN_COPY}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: is this copy addressed to a guardian because the party is a minor? Non-empty when it is. The greeting then names the guardian and the body names the minor as the SUBJECT of the document, not as the addressee.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('9fbe8d4d-923a-47c9-b982-8bd64cbf85bb', NULL, 'REQ', 'DETAILS', '{{REQ.DETAILS}}', 'system', NULL, NULL, true, false, false, 'The category-specific answers, for {{#each REQ.DETAILS}}. Each item has .LABEL (the humanised question, e.g. "Rider age") and .VALUE (the answer). Empty when the form asked no follow-up questions or all were left blank.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('15302dd3-845d-4fe7-a11c-b642882e3324', NULL, 'REQ', 'PHONE_HTML', '{{REQ.PHONE_HTML}}', 'system', NULL, NULL, true, false, false, 'The visitor''s phone number, HTML-escaped. Blank when they did not give one.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('585018c7-ae35-43c5-8bfe-3011c95f889c', NULL, 'REQ', 'CHANNEL_HTML', '{{REQ.CHANNEL_HTML}}', 'system', NULL, NULL, true, false, false, 'Which surface the inquiry came through — "Contact form", "Inquiry form", "Booking request" or "Kiosk". Blank when not recorded.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('2ad518ea-c3a5-4aa8-8ac8-e802fcde09a9', NULL, 'DOC', 'PARTY_CAN_EDIT_DEAL', '{{DOC.PARTY_CAN_EDIT_DEAL}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: may this party edit the terms directly? Non-empty when they may. Takes precedence over DOC.PARTY_CAN_SUGGEST — a party who can edit is never told they may only suggest.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('a77135dc-390b-4775-ad3d-2c4526543536', NULL, 'PARTY', 'EMAIL_HTML', '{{PARTY.EMAIL_HTML}}', 'system', NULL, NULL, true, false, false, 'The reader''s or submitter''s email address, HTML-escaped, for a contact line inside markup. Blank when no address is on file.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('41dcb813-974b-4ebd-90ae-94a37f7b0f37', NULL, 'DOC', 'TITLE_HTML', '{{DOC.TITLE_HTML}}', 'system', NULL, NULL, true, false, false, 'The same title, HTML-escaped. Present because the void and change-request emails escape the title in the body but not in the subject line; both are preserved. Blank when the document has no title.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('391d17e4-7b0b-4da5-9788-dadc84b32031', NULL, 'REQ', 'NOTES_HTML', '{{REQ.NOTES_HTML}}', 'system', NULL, NULL, true, false, false, 'The free-text note the visitor wrote, HTML-escaped, newlines preserved by the surrounding white-space:pre-line style. Blank when they wrote nothing.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('49e4948e-2465-4920-9d4e-bf1c329cb6ca', NULL, 'MSG', 'OFFERING_LABEL', '{{MSG.OFFERING_LABEL}}', 'system', NULL, NULL, true, false, false, 'What the invited person bought, when the invitation carries a purchase — e.g. "Private Lesson Package". Blank on an invitation with no purchase, and the whole "your purchase is ready" line disappears with it.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('e028867f-77ba-47fd-a6c3-8b582fb6fdf9', NULL, 'MSG', 'COUNT', '{{MSG.COUNT}}', 'system', NULL, NULL, true, false, false, 'How many things this email is about — updates in a digest, change requests listed, sessions upcoming. Already a string. Pair with MSG.IS_SINGLE to get the grammar right.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4732ac02-33c9-42cf-aaf5-d28ac3caeb06', NULL, 'PARTY', 'SIGNERS', '{{PARTY.SIGNERS}}', 'system', NULL, NULL, true, false, false, 'Every signer on an execution, joined for one line of prose — e.g. "Mary Richardson, CJ Zigmund". Blank when no signer has a name on file; the company-copy templates fall back to "A signer".', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('979d9743-0dc1-4534-951b-b5f3c0a89003', NULL, 'DOC', 'HAS_TITLE', '{{DOC.HAS_TITLE}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: does this document have a title at all? Non-empty when it does. Use it as {{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}your contract{{/if}} so the fallback wording lives in the template and can be edited. It tests for NULL, not for emptiness — an empty-string title keeps behaving exactly as it did before extraction.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('0038037f-b575-44ea-a6a3-bad5b0629ffc', NULL, 'MSG', 'SUBJECT_HTML', '{{MSG.SUBJECT_HTML}}', 'system', NULL, NULL, true, false, false, 'The subject line a member typed on a support request, HTML-escaped.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('6dda01fd-794d-4161-866c-6025b33fa270', NULL, 'ORG', 'FOOTER', '{{ORG.FOOTER}}', 'system', NULL, NULL, true, false, false, 'The legal/contact footer block: legal entity name on one line, then email · phone · website. Built from ORG.* and CONTACT.* registry values. Insert it RAW — most emails wrap it in <pre> or a pre-line paragraph. Blank when neither a legal name nor any contact detail is configured; wrap it in {{#if ORG.FOOTER}} so an unconfigured tenant does not get a stray horizontal rule.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('7bec42fc-2e02-4d5e-81ba-2b8bf91f8a06', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'ENG', 'DISCLOSURES', '{{ENG.DISCLOSURES}}', 'field', NULL, NULL, false, false, false, 'Meant to carry company conflict/relationship disclosures — never wired, ALWAYS RENDERS BLANK today.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4a59a6bd-58c8-461f-a983-c84cd164c88c', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'SIG', 'CLIENT.NAME', '{{SIG.CLIENT.NAME}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: stays visible as a placeholder until the client signs, then is replaced with the signer''s name. Never filled at generation — a draft still showing {{SIG.CLIENT.NAME}} is correct behavior, not a defect.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('c12c025d-9a6f-45ca-8a72-343e13fcbfc2', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'CLIENT', 'PRINTED_NAME', '{{CLIENT.PRINTED_NAME}}', 'field', NULL, NULL, false, false, false, 'The client''s name printed under a signature line. Identical output to CLIENT.FULL_NAME — the two names exist so signature blocks read as intended. Use this one in signature blocks.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('609cd2b1-731f-40ae-9b99-de89d2857751', 'dc42ca22-c6fb-4662-92f6-2187d2a8a2ec', 'SIG', 'CLIENT.DATE', '{{SIG.CLIENT.DATE}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: replaced with the date the client signs. Stays as a visible placeholder until then — that is correct behavior on drafts.', '2026-08-02 09:59:38.212144-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('e6c1d130-f1a2-4024-a9c4-3b8d9b328021', '1ebe7445-af88-4a5a-a0bb-adc69b6b6a86', 'DOC', 'EFFECTIVE_DATE', '{{DOC.EFFECTIVE_DATE}}', 'system', NULL, NULL, false, false, false, 'The date the document takes effect, written out — e.g. August 12, 2026. Uses the document''s effective date once set at execution; before that, the date it was created. Always prints a date.', '2026-08-02 09:59:38.452423-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('71a9f607-5502-456c-b1dd-d5a1941d573f', '1ebe7445-af88-4a5a-a0bb-adc69b6b6a86', 'ORG', 'LEGAL_NAME', '{{ORG.LEGAL_NAME}}', 'field', NULL, NULL, false, false, false, 'The business''s legal/trade name: French Heritage Equestrian. Always fills, from Business Settings.', '2026-08-02 09:59:38.452423-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('880f7e74-5389-43bf-8fdd-73b11a91f763', NULL, 'MSG', 'GENERATED_AT', '{{MSG.GENERATED_AT}}', 'system', NULL, NULL, true, false, false, 'When a working copy was produced, already formatted — e.g. "August 12, 2026 at 4:15 PM". It matters because a working copy is a snapshot of an unfinished contract and the reader needs to know how fresh it is.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('cb358449-bc8f-4021-b973-0c4de1f8ee83', NULL, 'MSG', 'RECIPIENT_EMAIL', '{{MSG.RECIPIENT_EMAIL}}', 'system', NULL, NULL, true, false, false, 'The address this personal link was issued to, shown so the reader can tell which of their addresses to sign in with. Never blank — a contract invitation cannot be sent without one.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('aff5eebe-e1ee-4dff-9446-90f9e8d57443', NULL, 'MSG', 'IS_SHARE', '{{MSG.IS_SHARE}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag on an evaluation report: was it shared with someone other than the buyer? Non-empty when shared. Changes "Your report" to "A report has been shared with you".', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('1bf86df4-e096-45ad-8cde-d5f6af287ef3', NULL, 'MSG', 'ITEMS', '{{MSG.ITEMS}}', 'system', NULL, NULL, true, false, false, 'The list this email is built around — notification titles, calendar reminders, lapsed holds. Scalar items: {{#each MSG.ITEMS}}<li>{{.}}</li>{{/each}}. Already escaped where the original sender escaped. Empty when there is nothing to list, and every use is guarded so no empty <ul> is emitted.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('98f743db-0f27-40ce-9375-b6539959108d', NULL, 'TXN', 'AMOUNT', '{{TXN.AMOUNT}}', 'system', NULL, NULL, true, false, false, 'A payment amount already formatted for display, currency symbol included — e.g. "$450.00". Blank when the amount is unknown, in which case the receipt simply says "We received your payment."', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('d4610c8f-e87d-4064-b9c8-092a37f101af', NULL, 'ORG', 'FOOTER_HTML', '{{ORG.FOOTER_HTML}}', 'system', NULL, NULL, true, false, false, 'The same footer as ORG.FOOTER, HTML-escaped. Use this one in the two barn-facing emails (new inquiry, new support request) that escape it today; use ORG.FOOTER everywhere else. The split preserves existing behaviour exactly — unifying it is a named follow-up, not a silent change.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('02e61f94-0002-481e-b9c6-d49abd35010d', NULL, 'MSG', 'BODY_HTML', '{{MSG.BODY_HTML}}', 'system', NULL, NULL, true, false, false, 'The message body a member typed on a support request, HTML-escaped, newlines preserved by the surrounding white-space:pre-line style.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('b78e743a-7a18-4bee-bee3-a193c6b130f6', NULL, 'ORG', 'SITE_HOST', '{{ORG.SITE_HOST}}', 'system', NULL, NULL, true, false, false, 'The same website with any http:// or https:// stripped, for building an href — e.g. "fhequestrian.com" for "https://fhequestrian.com". Pair it with ORG.SITE_LINK as the visible text. Blank when no site is configured.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('a20bf218-624d-4891-a27b-4e7103e836f3', NULL, 'ORG', 'SITE_LINK', '{{ORG.SITE_LINK}}', 'system', NULL, NULL, true, false, false, 'The tenant''s website as it should READ to a person — e.g. "fhequestrian.com". Prefers CONTACT/URL, falling back to BRAND/SITE_URL. Blank when neither is set.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('5e9b65c6-527e-43a6-8ddc-912b99515657', NULL, 'ORG', 'PHONE_TEL', '{{ORG.PHONE_TEL}}', 'system', NULL, NULL, true, false, false, 'The tenant''s public phone reduced to a dialable string (digits and a leading + only) — e.g. "8584393614" for "858-439-3614". For the href of a tel: link; show ORG.PHONE as the visible text. Blank when no phone is configured.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('cf7e124b-0b87-4955-bd17-d358bb621278', NULL, 'REQ', 'SUBMITTED_AT_HTML', '{{REQ.SUBMITTED_AT_HTML}}', 'system', NULL, NULL, true, false, false, 'When the inquiry was submitted, in Pacific time and already formatted — e.g. "Aug 12, 2026, 4:15 PM". Always present.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('50511603-ddb9-449c-a82c-289c04898f0a', NULL, 'MSG', 'IS_RESEND', '{{MSG.IS_RESEND}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag on the invitation: is this the SAME link sent again, rather than a new one? Non-empty on a resend. It changes the subject as well as the opening, because the subject is the only part of a resend most people read and it has to say "you already have this" without looking like a second invitation.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('202ccc72-ea88-49d6-85f1-fd55ff8efc32', NULL, 'DOC', 'PARTY_NEEDS_INFO', '{{DOC.PARTY_NEEDS_INFO}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: does this party still have fields to fill on this contract? Non-empty when their controls allow filling AND at least one of their fields is empty. Drives the "add your information" phrase in the contract invitation — never promise an action the party''s controls do not allow.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('0c5a69d5-8292-4e77-9329-759ad7bd9891', NULL, 'MSG', 'IS_SINGLE', '{{MSG.IS_SINGLE}}', 'system', NULL, NULL, true, false, false, 'A yes/no flag: is MSG.COUNT exactly one? Non-empty when it is. Use as {{#if MSG.IS_SINGLE}}update{{else}}updates{{/if}} so singular and plural wording is editable instead of compiled in.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('63faac4c-ba70-4a1c-a655-c601c4daf365', NULL, 'PARTY', 'GUARDIAN_FIRST_NAME', '{{PARTY.GUARDIAN_FIRST_NAME}}', 'system', NULL, NULL, true, false, false, 'The GUARDIAN''s first name on a copy redirected because the party is a minor. Blank when the guardian record has no first name — greet them as "there" in that case. A minor''s own address is never used: with no guardian email the send is skipped entirely and staff are alerted.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4626300b-89fd-4b82-bf26-288e4866a6c2', NULL, 'MSG', 'CHECKLIST', '{{MSG.CHECKLIST}}', 'system', NULL, NULL, true, false, false, 'What the invited person will be asked to do after clicking, for {{#each MSG.CHECKLIST}}. Each item has .TITLE (the thing) and .ACTION (what to do with it, already lower-cased so it reads mid-sentence). Only unfinished items appear. Empty when nothing is assigned yet.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('ab91ccca-f1c0-4c17-ad02-a30e4ee5cfa2', NULL, 'MSG', 'LINK', '{{MSG.LINK}}', 'system', NULL, NULL, true, false, false, 'The one action link this email exists to offer — open the contract, activate the account, open the Request Inbox. Already absolute and correct for the deployment that sent it (preview links point at preview). Never blank on an email that has a call to action.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('62fec499-b681-4e7d-b053-74b193236cd0', NULL, 'MSG', 'NEW_EMAIL', '{{MSG.NEW_EMAIL}}', 'system', NULL, NULL, true, false, false, 'The address a member is changing their sign-in email TO. This email is sent to that address and nowhere else; the current address keeps working until it is verified.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('2b44453e-8190-43ac-be32-3a1b1938f7f6', NULL, 'MSG', 'SENDER_NAME_HTML', '{{MSG.SENDER_NAME_HTML}}', 'system', NULL, NULL, true, false, false, 'The same as MSG.SENDER_NAME, HTML-escaped, for use inside markup.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3ba8430d-c78f-46b6-ae6d-5221e78977c5', NULL, 'PARTY', 'FULL_NAME_HTML', '{{PARTY.FULL_NAME_HTML}}', 'system', NULL, NULL, true, false, false, 'The same value as PARTY.FULL_NAME, HTML-escaped, for use inside markup where the original sender escaped it. Blank when no name is on file — the templates fall back to "The other party" or "A member" themselves.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('1eb91231-9dc3-4ac4-94c8-12df7a67ee3c', NULL, 'REQ', 'CONTACT_METHOD_HTML', '{{REQ.CONTACT_METHOD_HTML}}', 'system', NULL, NULL, true, false, false, 'How the visitor prefers to be reached, as a label — "Text", "Call" or "Email". An unrecognised value passes through as stored rather than disappearing. Blank when they expressed no preference.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('bab0da0e-49be-4188-b746-ac4495482135', NULL, 'REQ', 'CATEGORY_HTML', '{{REQ.CATEGORY_HTML}}', 'system', NULL, NULL, true, false, false, 'What the inquiry is about, as a label — e.g. "Riding lessons", "Horse care", "Buying or selling a horse". An unrecognised value passes through as stored. Blank when uncategorised.', '2026-08-12 11:15:13.715359-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3d8bf838-79bb-474c-95de-bff9a5b150c8', '637af213-4f00-4e36-8fd7-419390001e71', 'ORG', 'PRINCIPALS', '{{ORG.PRINCIPALS}}', 'field', NULL, NULL, false, false, false, 'The named principals/owners line used in the releases. Fills from org settings key ORG / PRINCIPALS (seeded).', '2026-08-02 09:59:38.704054-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('6f765c56-9a4c-479e-a7d7-a256fdd703a8', '637af213-4f00-4e36-8fd7-419390001e71', 'ORG', 'EMAIL', '{{ORG.EMAIL}}', 'field', NULL, NULL, false, false, false, 'The public contact email: Hello@FHEquestrian.com. From org settings (CONTACT / EMAIL).', '2026-08-02 09:59:38.704054-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('ee32a0c0-2f17-414a-8c90-5908ca1c03c0', '637af213-4f00-4e36-8fd7-419390001e71', 'SIG', 'CLIENT.DATE', '{{SIG.CLIENT.DATE}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: replaced with the date the client signs. Stays as a visible placeholder until then — that is correct behavior on drafts.', '2026-08-02 09:59:38.704054-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('8b02117b-f76e-4994-b13c-6b3aa2678607', NULL, 'ORD', 'DISPLAY_CODE', '{{ORD.DISPLAY_CODE}}', 'system', NULL, NULL, true, false, false, 'The order number a person can quote back — "PUR-000123", from purchases.display_code. Blank on an order that somehow has none. Added by TASK-CREDITGRANT; it is the readable reference ORD.UUID was wrongly reached for.', '2026-08-23 10:58:02.230711-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('fbac0a8e-7777-4409-9d1a-812efaccd5eb', NULL, 'ORD', 'LABEL', '{{ORD.LABEL}}', 'system', NULL, NULL, true, false, false, 'What is ON the order — the live line labels joined with commas, e.g. "4-Lesson Punch Card". Voided lines are excluded. Falls back to "Your order" so a sentence built on it is never headless.', '2026-08-23 10:58:02.230711-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('4f375cc0-e318-42fd-b615-0bc7060364f3', NULL, 'MSG', 'STAFF_NOTE', '{{MSG.STAFF_NOTE}}', 'system', NULL, NULL, true, false, false, 'The note a staff member typed when they asked for payment, HTML-escaped. Blank when they typed none, and the paragraph carrying it disappears with it.', '2026-08-23 10:58:02.230711-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('aff46d7c-ed98-4e15-afe1-de1fa34915d0', NULL, 'TXN', 'LEASE_FEE', '{{TXN.LEASE_FEE}}', 'field', 'transactions', 'lease_fee', false, false, false, 'The lease fee as entered on the deal''s working copy, printed as money, e.g. $1,200.00. Fills on clause-built lease contracts; blank anywhere there is no working-copy value.', '2026-07-02 15:24:17.023868-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('2726a750-8c99-41c9-b733-431fb6be37be', NULL, 'ORG', 'PHONE', '{{ORG.PHONE}}', 'field', 'config_values', 'value_text', true, false, false, 'The public contact phone: 858-439-3614. From org settings (CONTACT / PHONE).', '2026-07-02 15:24:24.66417-07');
