INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('97664a01-0c08-4b0e-84c1-c0747e510547', NULL, 'ORG', 'ENTITY_FORMATION', '{{ORG.ENTITY_FORMATION}}', 'field', 'business_config', 'entity_formation', true, false, false, 'How the entity is formed, e.g. Sole proprietorship (California). From Business Settings.', '2026-07-02 15:24:46.141043-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('740c4472-b5a0-416d-a4e7-652fb17037cd', NULL, 'MSG', 'CONTRACT_TITLE', '{{MSG.CONTRACT_TITLE}}', 'system', NULL, NULL, true, false, false, 'The name of the contract an account invitation ALSO carries — set only when staff sent a contract to a counterparty who has no account yet, so ONE email claims the account and names the document waiting behind it. Passed raw, like DOC.TITLE on CONTRACT_INVITE, because it renders into the subject line as well as the body. Empty on an ordinary account invitation.', '2026-08-25 16:28:52.945992-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('af8eee4f-c586-49e4-9468-a299c9add5bf', NULL, 'ENG', 'INTENDED_USE', '{{ENG.INTENDED_USE}}', 'field', 'intake', 'intended_use', false, false, false, 'Meant to carry the horse''s intended use from client intake — never wired, ALWAYS RENDERS BLANK today.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('8476b376-215e-4e95-aca5-13eb54d0c6ed', NULL, 'TXN', 'COLLECTED', '{{TXN.COLLECTED}}', 'system', NULL, NULL, true, false, false, 'What was actually collected on the order, formatted as dollars. Empty when nothing was ($0 on a comp), so {{#if}} can hide the payment sentence. Resolved by the receipt sender from purchases.amount_paid.', '2026-09-01 01:33:36.576482-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('f2620f71-9bdf-43e6-814a-0912272f97a2', NULL, 'TXN', 'WRITE_DOWN', '{{TXN.WRITE_DOWN}}', 'system', NULL, NULL, true, false, false, 'The written-down dollars on a discounted or comped order (purchases.write_down_amount). Empty on an ordinary paid order, so {{#if TXN.WRITE_DOWN}} selects the reduced-price receipt wording.', '2026-09-01 01:33:36.576482-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('60e873c7-4d0e-4bb5-abbb-51a7cfb857a6', NULL, 'TXN', 'REDUCTION_LABEL', '{{TXN.REDUCTION_LABEL}}', 'system', NULL, NULL, true, false, false, 'The customer-facing word for the write-down: "Discount" on a discounted order, "Complimentary" on a comped one. Empty on an ordinary paid order.', '2026-09-01 01:33:36.576482-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('d9306a89-cb08-413c-9960-e4f4b5b98f96', NULL, 'ENG', 'DISCIPLINE', '{{ENG.DISCIPLINE}}', 'field', 'intake', 'discipline', false, false, false, 'Meant to carry the riding discipline from a client intake that was never built — ALWAYS RENDERS BLANK today. Do not place until intake capture exists.', '2026-07-02 15:24:03.189985-07');
