INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('c571bb72-1e7b-4592-8347-7212d9296cf7', NULL, 'ENG', 'PROTECTION_PERIOD', '{{ENG.PROTECTION_PERIOD}}', 'field', 'config', 'protection_period', true, false, false, 'Meant to be the non-circumvention window in months on the retainer/representation agreements — never wired, ALWAYS RENDERS BLANK today.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('c969a068-59ea-4698-9fe3-fd4e14f64fbb', NULL, 'DOC', 'UUID', '{{DOC.UUID}}', 'system', 'documents', 'id', false, true, false, 'The document''s internal system id — a long UUID for tracing, not for reading. Always fills. Prefer DOC.ID in anything human-facing.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('3f010065-558b-408f-9d45-735304749f8f', NULL, 'DOC', 'ID', '{{DOC.ID}}', 'system', 'documents', 'display_code', false, false, false, 'The document''s human reference number, e.g. DOC-000123. Always fills. This is the one to use anywhere a person will read or quote the reference.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('69a3217e-cc80-43c5-86aa-b888eb9745fd', NULL, 'DOC', 'GENERATED_DATE', '{{DOC.GENERATED_DATE}}', 'system', NULL, NULL, true, true, false, 'The date the document was generated, e.g. August 12, 2026. Always fills.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('f3d8ff17-4729-4ce3-91ea-eb81c0d24799', NULL, 'DOC', 'EFFECTIVE_DATE', '{{DOC.EFFECTIVE_DATE}}', 'system', 'documents', 'effective_date', false, false, false, 'The date the document takes effect, written out — e.g. August 12, 2026. Uses the document''s effective date once set at execution; before that, the date it was created. Always prints a date.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('f306a13a-c593-4f1d-b8dd-8f23cf0365f3', '5b889f73-b3cc-43f4-9730-8c266570139f', 'ORG', 'LEGAL_NAME', '{{ORG.LEGAL_NAME}}', 'field', NULL, NULL, false, false, false, 'The business''s legal/trade name: French Heritage Equestrian. Always fills, from Business Settings.', '2026-08-02 09:59:37.459087-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('2241868c-ea96-4be1-8bf4-be49c03b7f9b', '5b889f73-b3cc-43f4-9730-8c266570139f', 'SIG', 'CLIENT.DATE', '{{SIG.CLIENT.DATE}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: replaced with the date the client signs. Stays as a visible placeholder until then — that is correct behavior on drafts.', '2026-08-02 09:59:37.459087-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('ebdcbd3e-8694-4885-8de3-114aa0a27109', '5b889f73-b3cc-43f4-9730-8c266570139f', 'CLIENT', 'PRINTED_NAME', '{{CLIENT.PRINTED_NAME}}', 'field', NULL, NULL, false, false, false, 'The client''s name printed under a signature line. Identical output to CLIENT.FULL_NAME — the two names exist so signature blocks read as intended. Use this one in signature blocks.', '2026-08-02 09:59:37.459087-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('fce9632e-daf9-407a-aa98-47a7a9067ca5', NULL, 'TXN', 'RETAINER_FEE', '{{TXN.RETAINER_FEE}}', 'field', 'transactions', 'retainer_fee', false, false, false, 'The flat search-retainer fee. RENDERS BLANK TODAY — no working-copy field feeds the HORSE_SEARCH_RETAINER template; wire the fee before using that template for a real retainer.', '2026-07-02 15:24:10.145523-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('eadfeba6-1521-4d7c-a73c-835d08174faf', NULL, 'TXN', 'SERVICE_FEE', '{{TXN.SERVICE_FEE}}', 'field', 'transactions', 'service_fee', false, false, false, 'Old order-form fee token (flat lesson/placement fee). Nothing feeds it — renders blank; only the retired MINOR_RIDER body still references it. Historically shared one source with TXN.PACKAGE_FEE — owner to rule which name survives.', '2026-07-02 15:24:10.145523-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('1bf27da2-36f5-44a9-b753-a54e3f0aa2b0', NULL, 'PARTY', 'FULL_NAME', '{{PARTY.FULL_NAME}}', 'field', 'contacts', 'first_name/last_name', false, true, true, 'Generic any-party name — NO live template uses PARTY.*; bodies use the role-named namespaces (CLIENT, PARTICIPANT, LESSOR, LESSEE, BUYER, SELLER). Renders the same value as PARTY.PRINTED_NAME. Prefer the role-named token for the person you mean.', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('80e5702f-b46f-4f9f-b0bf-0c98d257769b', NULL, 'PARTY', 'PRINTED_NAME', '{{PARTY.PRINTED_NAME}}', 'field', 'contacts', 'first_name/last_name', false, false, true, 'Generic any-party signature-line name — identical output to PARTY.FULL_NAME, and like it unused by any live template. Prefer the role-named token (e.g. CLIENT.PRINTED_NAME).', '2026-07-02 15:24:03.189985-07');
INSERT INTO public.template_tokens (id, template_id, namespace, field, token, kind, source_table, source_column, computed, required, party_scoped, notes, created_at) VALUES ('e06f290a-ac1f-4011-8709-058becea0009', '5b889f73-b3cc-43f4-9730-8c266570139f', 'SIG', 'CLIENT.NAME', '{{SIG.CLIENT.NAME}}', 'signature', NULL, NULL, false, false, false, 'Signature stamp: stays visible as a placeholder until the client signs, then is replaced with the signer''s name. Never filled at generation — a draft still showing {{SIG.CLIENT.NAME}} is correct behavior, not a defect.', '2026-08-02 09:59:37.459087-07');
